INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-20393','寄紫阁隐者','張籍','quantangshi','','卷21','紫阁气沉沉，先生住处深。
有人时得见，无路可相寻。
夜鹿伴茅屋，秋猿守栗林。
唯应采灵药，更不别营心。','',''),('quantangshi-20394','夜宿黑竈溪','張籍','quantangshi','','卷21','夜到碧溪里，无人秋月明。
逢幽更移宿，取伴亦探行。
花下红泉色，云西乳鹤声。
明朝记归处，石上自书名。','',''),('quantangshi-20395','古树','張籍','quantangshi','','卷21','古树枝柯少，枯来复几春。
露根堪系马，空腹定藏人。
蠹节莓苔老，烧痕霹雳新。
若当江浦上，行客祭为神。','',''),('quantangshi-20396','送徐先生归蜀','張籍','quantangshi','','卷21','日暮远归处，云间仙观钟。
唯持青玉牒，独立碧鸡峰。
阴涧长收乳，寒泉旧养龙。
几时因卖药，得向海边逢。','',''),('quantangshi-20397','隐者','張籍','quantangshi','','卷21','先生已得道，市井亦容身。
救病自行药，得钱多与人。
问年长不定，传法又非真。
每见邻家说，时闻使鬼神。','',''),('quantangshi-20398','送友人归山','張籍','quantangshi','','卷21','出山成北首，重去结茅庐。
移石修废井，埽龛盛旧书。
开田留杏树，分洞与僧居。
长在幽峰里，樵人见亦疎。','',''),('quantangshi-20399','霅溪西亭晚望','張籍','quantangshi','','卷21','霅水碧悠悠，西亭柳岸头。
夕阴生远岫，斜照逐回流。
此地动归思，逢人方倦游。
吴兴耆旧尽，空见白苹州。','',''),('quantangshi-20400','哭山中友人','張籍','quantangshi','','卷21','入云遥便哭，山友隔今生。
遶墓招魂魄，镌岩记姓名。
犬因无主善，鹤为见人鸣。
长说能尸解，多应别路行。','',''),('quantangshi-20401','答僧拄杖','張籍','quantangshi','','卷21','灵藤为拄杖，白净色如银。
得自高僧手，将扶病客身。
春游不骑马，夜会亦呈人。
持此归山去，深宜戴角巾。','',''),('quantangshi-20402','灵都观李道士','張籍','quantangshi','','卷21','仙观雨来静，遶房琼草春。
素书天上字，花洞古时人。
泥竈煮灵液，埽坛朝玉真。
几回游阆苑，青节亦随身。','',''),('quantangshi-20403','送韦评事归华阴','張籍','quantangshi','','卷21','三峰西面住，出见世人稀。
老大谁相识，恓惶又独归。
埽窗秋菌落，开箧夜蛾飞。
若向云中伴，还应着褐衣。','',''),('quantangshi-20404','送闽僧','張籍','quantangshi','','卷21','几夏京城住，今朝独远归。
修行四分律，护净七条衣。
溪寺黄橙熟，沙田紫芋肥。
九龙潭上路，同去客应稀。','',''),('quantangshi-20405','送海南客归旧岛','張籍','quantangshi','','卷21','海上去应远，蛮家云岛孤。
竹船来桂浦，山市卖鱼须。
入国自献宝，逢人多赠珠。
却归春洞口，斩象祭天吴。','',''),('quantangshi-20406','登咸阳北寺楼','張籍','quantangshi','','卷21','高秋原上寺，下马一登临。
渭水西来直，秦山南向深。
旧宫人不住，荒碣路难寻。
日暮凉风起，萧条多远心。','',''),('quantangshi-20407','送新罗使','張籍','quantangshi','','卷21','万里为朝使，离家今几年。
应知旧行路，却上远归船。
夜泊避蛟窟，朝炊求岛泉。
悠悠到乡国，还望海西天。','',''),('quantangshi-20408','宿广德寺寄从舅','張籍','quantangshi','','卷21','古寺客堂空，开帘四面风。
移牀动栖鹤，停烛聚飞虫。
闲卧逐凉处，远愁生静中。
林西微月色，思与甯家同。','',''),('quantangshi-20409','宿邯郸馆寄马磁州','張籍','quantangshi','','卷21','孤客到空馆，夜寒愁卧迟。
虽沽主人酒，不似在家时。
几宿得欢笑，如今成别离。
明朝行更远，回望隔山陂。','',''),('quantangshi-20410','舟行寄李湖州','張籍','quantangshi','','卷21','客愁无次第，川路重辛勤。
藻密行舟涩，湾多转檝频。
薄游空感惠，失计自怜贫。
赖有汀洲句，时时慰远人。','',''),('quantangshi-20411','送闲师归江南','張籍','quantangshi','','卷21','徧住江南寺，随缘到上京。
多生修律业，外学得诗名。
讲殿偏追入，斋家别请行。
青枫乡路远，几日尽归程。','',''),('quantangshi-20412','游襄阳山寺','張籍','quantangshi','','卷21','秋色江边路，烟霞若有期。
寺贫无利施，僧老足慈悲。
薜荔侵禅窟，虾蟆占浴池。
闲游殊未徧，即是下山时。','',''),('quantangshi-20413','登城寄王秘书建','張籍','quantangshi','','卷21','闻君鹤岭住，西望日依依。
远客偏相忆，登城独不归。
十年为道侣，几处共柴扉。
今日烟霞外，人间得见稀。','',''),('quantangshi-20414','送从弟戴玄往苏州','張籍','quantangshi','','卷21','杨柳阊门路，悠悠水岸斜。
乘舟向山寺，着屐到渔家。
夜月红柑树，秋风白藕花。
江天诗景好，回日莫令赊。','',''),('quantangshi-20415','送朱庆余及第归越','張籍','quantangshi','','卷21','东南归路远，几日到乡中。
有寺山皆遍，无家水不通。
湖声莲叶雨，野气稻花风。
州县知名久，争邀与客同。','',''),('quantangshi-20416','过贾岛野居','張籍','quantangshi','','卷21','青门坊外住，行坐见南山。
此地去人远，知君终日闲。
蛙声篱落下，草色户庭间。
好是经过处，唯愁暮独还。','',''),('quantangshi-20417','酬韩庶子','張籍','quantangshi','','卷21','西街幽僻处，正与嬾相宜。
寻寺独行远，借书常送迟。
家贫无易事，身病足闲时。
寂寞谁相问，祗应君自知。','',''),('quantangshi-20418','赠姚合少府','張籍','quantangshi','','卷21','病来辞赤县，案上有丹经。
为客烧茶竈，教儿埽竹亭。
诗成添旧卷，酒尽卧空瓶。
阙下今遗逸，谁瞻隐士星。','',''),('quantangshi-20419','送僧游五台兼谒李司空','張籍','quantangshi','','卷21','远去见双节，因行上五台。
化楼侵晓出，雪路向春开。
边寺连峰去，胡儿听法来。
定知巡礼后，解夏始应回。','',''),('quantangshi-20420','送郑秀才归宁','張籍','quantangshi','','卷21','桂檝彩为衣，行当令节归。
夕潮迷浦远，昼雨见人稀。
野芰到时熟，江鸥泊处飞。
离琴一奏罢，山雨霭余晖。','',''),('quantangshi-20421','送李评事游越','張籍','quantangshi','','卷21','未习风尘事，初为吴越游。
露沾湖草晚，日照海山秋。
梅市门何在，兰亭水尚流。
西陵待潮处，知汝不胜愁。','',''),('quantangshi-20422','夏日闲居','張籍','quantangshi','','卷21','无事门多闭，偏知夏日长。
早蝉声寂寞，新竹气清凉。
闲对临书案，看移晒药牀。
自怜归未得，犹寄在班行。','',''),('quantangshi-20423','闲居','張籍','quantangshi','','卷21','东城南陌尘，紫幰与朱轮。
尽说无多事，能闲有几人。
唯教推甲子，不信守庚申。
谁见衡门里，终朝自在贫。','',''),('quantangshi-20424','寄昭应王中丞','張籍','quantangshi','','卷21','借得街西宅，开门渭水头。
长贫唯要健，渐老不禁愁。
独凭藤书案，空悬竹酒钩。
春风石瓮寺，作意共君游。','',''),('quantangshi-20425','酬孙洛阳','張籍','quantangshi','','卷21','家贫相远住，斋馆入时稀。
独坐看书卷，闲行着褐衣。
早蝉庭笋老，新雨径莎肥。
各离争名地，无人见是非。','',''),('quantangshi-20426','送人任济阴','張籍','quantangshi','','卷21','黄绶在腰下，知君非旅行。
将书报旧里，留褐与诸生。
赠别尽沽酒，惜欢多出城。
春风济水上，候吏听车声。','',''),('quantangshi-20427','晚春过崔驸马东园','張籍','quantangshi','','卷21','闲园多好风，不意在街东。
早早诗名远，长长酒性同。
竹香新雨后，莺语落花中。
莫遣经过少，年光渐觉空。','',''),('quantangshi-20428','夏日闲居','張籍','quantangshi','','卷21','多病逢迎少，闲居又一年。
药看辰日合，茶过卯时煎。
草长晴来地，虫飞晚后天。
此时幽梦远，不觉到山边。','',''),('quantangshi-20429','晚秋闲居','張籍','quantangshi','','卷21','独坐高秋晚，萧条足远思。
家贫常畏客，身老转怜儿。
万种尽闲事，一生能几时。
从来疎嬾性，应祗有僧知。','',''),('quantangshi-20430','和陆司业习静寄所知','張籍','quantangshi','','卷21','幽室独焚香，清晨下未央。
山开登竹阁，僧到出茶牀。
收拾新琴谱，封题旧药方。
逍遥无别事，不似在班行。','',''),('quantangshi-20431','酬韩祭酒雨中见寄','張籍','quantangshi','','卷21','雨中愁不出，阴黑尽连宵。
屋湿唯添漏，泥深未放朝。
无刍怜马瘦，少食信儿娇。
闻道韩夫子，还同此寂寥。','',''),('quantangshi-20432','和裴仆射移官言志','張籍','quantangshi','','卷21','身在勤劳地，常思放旷时。
功成归圣主，位重委羣司。
看垒台边石，闲吟箧里诗。
苍生正瞻望，难与故山期。','',''),('quantangshi-20433','酬白二十二舍人早春曲江见招','張籍','quantangshi','','卷21','曲江冰欲尽，风日已恬和。
柳色看犹浅，泉声觉渐多。
紫蒲生湿岸，青鸭戏新波。
仙掖高情客，相招共一过。','',''),('quantangshi-20434','和裴仆射朝回寄韩吏部','張籍','quantangshi','','卷21','独爱南关里，山晴竹杪风。
从容朝早退，萧洒客常通。
案曲新亭上，移花远寺中。
唯应有吏部，诗酒每相同。','',''),('quantangshi-20435','春日李舍人宅见两省诸公唱和因书情即事','張籍','quantangshi','','卷21','又见帝城里，东风天气和。
官闲人事少，年长道情多。
紫掖发章句，青闱更咏歌。
谁知余寂寞，终日断经过。','',''),('quantangshi-20436','和李仆射秋日病中作','張籍','quantangshi','','卷21','由来病根浅，易见药功成。
晓日杵臼静，凉风衣服轻。
犹疑少气力，渐觉有心情。
独倚红藤杖，时时堦上行。','',''),('quantangshi-20437','早春病中','張籍','quantangshi','','卷21','羸病及年初，心情不自如。
多申请假牒，祗送贺官书。
幽径独行步，白头长嬾梳。
更怜晴日色，渐渐暖贫居。','',''),('quantangshi-20438','送严大夫之桂州','張籍','quantangshi','','卷21','旌斾过湘潭，幽奇得徧探。
莎城百越北，行路九疑南。
有地多生桂，无时不养蚕。
听歌疑似曲，风俗自相谙。','',''),('quantangshi-20439','咏怀','張籍','quantangshi','','卷21','老去多悲事，非唯见二毛。
眼昏书字大，耳重觉声高。
望月偏增思，寻山易发劳。
都无作官意，赖得在闲曹。','',''),('quantangshi-20440','使至蓝溪驿寄太常王丞','張籍','quantangshi','','卷21','独上七盘去，峰峦转转稠。
云中迷象鼻，雨里下筝头。
水没荒桥路，鸦啼古驿楼。
君今在城阙，肯见此中愁。','',''),('quantangshi-20441','留别江陵王少府','張籍','quantangshi','','卷21','迢迢山上路，病客独行迟。
况此分手处，当君失意时。
寒林远路驿，晚烧过荒陂。
别后空回首，相逢未有期。','',''),('quantangshi-20442','赠海东僧','張籍','quantangshi','','卷21','别家行万里，自说过扶余。
学得中州语，能为外国书。
与医收海藻，持咒取龙鱼。
更问同来伴，天台几处居。','',''),('quantangshi-20443','寄汉阳故人','張籍','quantangshi','','卷21','知君汉阳住，烟树远重重。
归使雨中发，寄书灯下封。
同时买江坞，今日别云松。
欲问新移处，青萝最北峰。','',''),('quantangshi-20444','送安西将','張籍','quantangshi','','卷21','万里海西路，茫茫边草秋。
计程沙塞口，望伴驿峰头。
雪暗非时宿，沙深独去愁。
塞乡人易老，莫住近蕃州。','',''),('quantangshi-20445','题李山人幽居','張籍','quantangshi','','卷21','襄阳南郭外，茅屋一书生。
无事焚香坐，有时寻竹行。
画苔藤杖细，踏石笋鞋轻。
应笑风尘客，区区逐世名。','',''),('quantangshi-20446','早春闲游','張籍','quantangshi','','卷21','年长身多病，独宜作冷官。
从来闲坐惯，渐觉出门难。
树影新犹薄，池光晚尚寒。
遥闻有花发，骑马暂行看。','',''),('quantangshi-20447','赠太常王建藤杖笋鞋','張籍','quantangshi','','卷21','蛮藤剪为杖，楚笋结成鞋。
称与诗人用，堪随礼寺斋。
寻花入幽径，步日下寒堦。
以此持相赠，君应惬素怀。','',''),('quantangshi-20448','和周赞善闻子规','張籍','quantangshi','','卷21','秦城啼楚鸟，远思更纷纷。
况是街西夜，偏当雨里闻。
应投最高树，似隔数重云。
此处谁能听，遥知独有君。','',''),('quantangshi-20449','送李骑曹灵州归觐','張籍','quantangshi','','卷21','翩翩出上京，几日到边城。
渐觉风沙起，还将弓箭行。
席箕侵路暗，野马见人惊。
军府知归庆，应教数骑迎。','',''),('quantangshi-20450','寒食夜寄姚侍郎','張籍','quantangshi','','卷21','贫官多寂寞，不异野人居。
作酒和山药，教儿写道书。
五湖归去远，百事病来疎。
况忆同怀者，寒庭月上初。','',''),('quantangshi-20451','题清彻上人院','張籍','quantangshi','','卷21','古寺临坛久，松间别起堂。
看添浴佛水，自合读经香。
爱养无家客，多传得效方。
过斋长不出，坐卧一绳牀。','',''),('quantangshi-20452','寄灵一上人初归云门寺','張籍','quantangshi','','卷21','寒山白云里，法侣自招携。
竹径通城下，松门隔水西。
方同沃洲去，不作武陵迷。
仿髴遥看处，秋风是会稽。','',''),('quantangshi-20453','和裴司空即事通简旧僚','張籍','quantangshi','','卷21','肃肃上台坐，四方皆仰风。
当朝奉明政，早日立元功。
独对赤墀下，密宣黄阁中。
犹闻动高韵，思与旧僚同。','',''),('quantangshi-20454','使回留别襄阳李司空','張籍','quantangshi','','卷21','江亭寒日晚，弦管有离声。
从此一筵别，独为千里行。
迟迟恋恩德，役役限公程。
回首吟新句，霜云满楚城。','',''),('quantangshi-20455','和户部令狐尚书喜裴司空见招看雪','張籍','quantangshi','','卷21','南园新覆雪，上宰晓来看。
谁共登春榭，唯闻有地官。
色连山远静，气与竹偏寒。
高韵更相应，宁同謌吹欢。','',''),('quantangshi-20456','和裴司空以诗请刑部白侍郎双鹤','張籍','quantangshi','','卷21','皎皎仙家鹤，远留闲宅中。
徘徊幽树月，嘹唳小亭风。
丞相西园好，池塘野水通。
欲将来放此，赏望与宾同。','',''),('quantangshi-20457','同锦州胡郎中清明日对雨西亭宴','張籍','quantangshi','','卷21','郡内开新火，高斋雨气清。
惜花邀客赏，劝酒促歌声。
共醉移芳席，留欢闭暮城。
政闲方宴语，琴筑任遥情。','',''),('quantangshi-20458','庄陵挽歌词三首 一','張籍','quantangshi','','卷21','白日已昭昭，干戈亦渐消。
迎师亲出道，从谏早临朝。
佞幸威权薄，忠良宠锡饶。
丘陵今一变，无复白云谣。','',''),('quantangshi-20459','庄陵挽歌词三首 二','張籍','quantangshi','','卷21','观风欲巡洛，习战亦开池。
始改三年政，旋闻七月期。
陵分内外使，官具吉凶仪。
渭北新园路，箫笳远更悲。','',''),('quantangshi-20460','庄陵挽歌词三首 三','張籍','quantangshi','','卷21','晓日龙车动，秋风阊阖开。
行帷六宫出，执绋万方来。
惨惨郊原暮，迟迟挽唱哀。
空山烟雨夕，新陌遶陵台。','',''),('quantangshi-20461','和左司元郎中秋居十首 一','張籍','quantangshi','','卷21','选得闲坊住，秋来草树肥。
风前卷筒簟，雨里脱荷衣。
野客留方去，山童取药归。
非因入朝省，过此出门稀。','',''),('quantangshi-20462','和左司元郎中秋居十首 二','張籍','quantangshi','','卷21','有地唯栽竹，无池亦养鹅。
学书求墨迹，酿酒爱朝和。
古镜铭文浅，神方谜语多。
居贫闲自乐，豪客莫相过。','',''),('quantangshi-20463','和左司元郎中秋居十首 三','張籍','quantangshi','','卷21','闲来松菊地，未省有埃尘。
直去多将药，朝回不访人。
见僧收酒器，迎客换纱巾。
更恐登清要，难成自在身。','',''),('quantangshi-20464','和左司元郎中秋居十首 四','張籍','quantangshi','','卷21','自知清静好，不要问时豪。
就石安琴枕，穿松压酒槽。
山晴因月甚，诗语入秋高。
身外无余事，唯应笔砚劳。','',''),('quantangshi-20465','和左司元郎中秋居十首 五','張籍','quantangshi','','卷21','闲堂新埽洒，称是早秋天。
书客多呈帖，琴僧与合弦。
莎台乘晚上，竹院就凉眠。
终日无忙事，还应似得仙。','',''),('quantangshi-20466','和左司元郎中秋居十首 六','張籍','quantangshi','','卷21','醉倚斑藤杖，闲眠瘿木牀。
案头行气诀，炉里降真香。
尚俭经营少，居闲意思长。
秋茶莫夜饮，新自作松浆。','',''),('quantangshi-20467','和左司元郎中秋居十首 七','張籍','quantangshi','','卷21','每忆旧山居，新教上墨图。
晚花回地种，好酒问人沽。
夜后开朝簿，申前发省符。
为郎凡几岁，已见白髭须。','',''),('quantangshi-20468','和左司元郎中秋居十首 八','張籍','quantangshi','','卷21','菊地才通履，茶房不垒阶。
凭医看蜀药，寄信觅吴鞋。
尽得仙家法，多随道客斋。
本无荣辱意，不是学安排。','',''),('quantangshi-20469','和左司元郎中秋居十首 九','張籍','quantangshi','','卷21','林下无拘束，闲行放性灵。
好时开药竈，高处置琴亭。
更撰居山记，唯寻相鹤经。
初当授衣假，无吏挽门铃。','',''),('quantangshi-20470','和左司元郎中秋居十首 十','張籍','quantangshi','','卷21','客散高斋晚，东园景象偏。
晴明犹有蝶，凉冷渐无蝉。
藤折霜来子，蜗行雨后涎。
新诗才上卷，已得满城传。','',''),('quantangshi-20471','经王处士原居','張籍','quantangshi','','卷21','旧宅谁相近，唯僧近竹关。
庭闲云满井，窗晓雪通山。
来客半留宿，借书多寄还。
明时未中岁，莫便一生闲。','',''),('quantangshi-20472','不食仙姑山房','張籍','quantangshi','','卷21','寂寂花枝里，草堂唯素琴。
因山曾改眼，见客不言心。
月出溪路静，鹤鸣云树深。
丹砂如可学，便欲住幽林。','',''),('quantangshi-20473','江头','張籍','quantangshi','','卷21','晚步随江远，来帆过眼频。
试寻新住客，少见故乡人。
回首怜归翼，长吟任此身。
应同南浦雁，更见岭头春。','',''),('quantangshi-20474','寄孙冲主簿','張籍','quantangshi','','卷21','低折沧州簿，无书整两春。
马从同事借，妻怕罢官贫。
道僻收闲药，诗高笑故人。
仍闻长吏奏，表乞锁厅频。','',''),('quantangshi-20475','赠任懒','張籍','quantangshi','','卷21','未肯求科第，深坊且隐居。
胜游寻野客，高卧看兵书。
点药医闲马，分泉灌远蔬。
汉庭无得意，谁拟荐相如。','',''),('quantangshi-20476','旧宫人','張籍','quantangshi','','卷21','謌舞梁州女，归时白发生。
全家没蕃地，无处问乡程。
宫锦不传样，御香空记名。
一身难自说，愁逐路人行。','',''),('quantangshi-20477','春日留别','張籍','quantangshi','','卷21','游人欲别离，半醉对花枝。
看着春又晚，莫轻少年时。
临行记分处，廻首是相思。
各向天涯去，重来未可期。','',''),('quantangshi-20478','没蕃故人','張籍','quantangshi','','卷21','前年伐月支，城上没全师。
蕃汉断消息，死生长别离。
无人收废帐，归马识残旗。
欲祭疑君在，天涯哭此时。','',''),('quantangshi-20479','赠箕山僧','張籍','quantangshi','','卷21','久住空林下，长斋耳目清。
蒲团借客坐，石磹甃人行。
似鹤难知性，因山强号名。
时闻衣袖里，暗掐念珠声。','',''),('quantangshi-20480','冬夕','張籍','quantangshi','','卷21','寒蛩独罢织，湘雁犹能鸣。
月色当窗入，乡心半夜生。
不成高枕梦，复作遶堦行。
回首嗟淹泊，城头北斗横。','',''),('quantangshi-20481','奉和陕州十四翁中丞寄雷州二十二翁司户之作','張籍','quantangshi','','卷21','联飞独不前，迥落海南天。
贾傅竟行矣，邵公惟泫然。
瘴开山更远，路极水无边。
沈劣本多感，况闻原上篇。','',''),('quantangshi-20482','老将','張籍','quantangshi','','卷21','鬓衰头似雪，行步急如风。
不怕骑生马，犹能挽硬弓。
兵书封锦字，手诏满香筒。
今日身憔悴，犹夸定远功。','',''),('quantangshi-20483','送友生游峡中','張籍','quantangshi','','卷21','风静杨柳垂，看花又别离。
几年同在此，今日各驱驰。
峡里闻猿呌，山头见月时。
殷勤一杯酒，珍重岁寒姿。','',''),('quantangshi-20484','送安法师','張籍','quantangshi','','卷21','出郭见落日，别君临古津。
远程无野寺，宿处问何人。
原色不分路，锡声遥隔尘。
山阴到家节，犹及蕙兰春。','',''),('quantangshi-20485','水','張籍','quantangshi','','卷21','荡漾空沙际，虚明入远天。
秋光照不极，鸟色去无边。
势引长云阔，波轻片雪连。
汀洲杳难测，万古覆苍烟。','',''),('quantangshi-20486','岳州晚景','張籍','quantangshi','','卷21','晚景寒鸦集，秋声旅雁归。
水光浮日去，霞彩暎江飞。
洲白芦花吐，园红柿叶稀。
长沙卑湿地，九月未成衣。','',''),('quantangshi-20487','寒食后','張籍','quantangshi','','卷21','田舍清明日，家家出火迟。
白衫眠古巷，红索搭高枝。
纱带生难结，铜钗重易垂。
斩新衣着尽，还似去年时。','',''),('quantangshi-20488','寒食书事二首 一','張籍','quantangshi','','卷21','今朝一百五，出户雨初晴。
舞爱双飞蝶，歌闻数里莺。
江深青草岸，花满白云城。
为政多孱懦，应无酷吏名。','',''),('quantangshi-20489','寒食书事二首 二','張籍','quantangshi','','卷21','出城烟火少，况复是今朝。
闲坐将谁语，临觞只自谣。
堦前春藓徧，衣上落花飘。
妓乐州人戏，使君心寂寥。','',''),('quantangshi-20490','和李仆射雨中寄卢严二给事','張籍','quantangshi','','卷21','郊原飞雨至，城阙湿云埋。
迸点时穿牖，浮沤欲上堦。
偏滋解箨竹，并洒落花槐。
晚润生琴匣，新凉满药斋。
从容朝务退，放旷掖曹乖。
尽日无来客，闲吟感此怀。','',''),('quantangshi-20491','酬李仆射晚春见寄','張籍','quantangshi','','卷21','戟户洞初晨，莺声雨后频。
虚庭清气在，众药湿光新。
鱼动芳池面，苔侵老竹身。
教铺尝酒处，自问探花人。
独此长多病，幽居欲过春。
今朝听高韵，忽觉离埃尘。','',''),('quantangshi-20492','和卢常侍寄华山郑隐者','張籍','quantangshi','','卷21','独住三峰下，年深学炼丹。
一间松叶屋，数片石花冠。
酒待山中饮，琴将洞口弹。
开门移远竹，剪草出幽兰。
荒壁通泉架，晴崖晒药坛。
寄知骑省客，长向白云闲。','',''),('quantangshi-20493','和令狐尚书平泉东庄近居李仆射有寄十韵','張籍','quantangshi','','卷21','平地有清泉，伊南古寺边。
涨池闲遶屋，出野徧浇田。
旧隐离多日，新邻得几年。
探幽皆一绝，选胜又双全。
门静山光别，园深竹影连。
斜分采药径，直过钓鱼船。
鸡犬还应识，云霞顿觉鲜。
追思应不远，赏爱谅难偏。
此处堪长往，游人早共传。
各当恩寄重，归卧恐无缘。','',''),('quantangshi-20494','送郑尚书出镇南海','張籍','quantangshi','','卷21','远镇承新命，王程不假催。
班行争路送，恩赐并时来。
牙斾从城展，兵符到府开。
蛮声喧夜市，海色浸潮台。
画角天边月，寒关岭上梅。
共知公望重，多是隔年回。','',''),('quantangshi-20495','徐州试反舌无声','張籍','quantangshi','','卷21','夏木多好鸟，偏知反舌名。
林幽仍共宿，时过即无声。
竹外天空晓，溪头雨自晴。
居人宜寂寞，深院益凄清。
入雾暗相失，当风闲易惊。
来年上林苑，知尔最先鸣。','',''),('quantangshi-20496','省试行不由径','張籍','quantangshi','','卷21','田里有微径，贤人不复行。
孰知求捷步，又恐异端成。
从易众所欲，安邪患亦生。
谁能达天道，共此竞前程。
子羽有遗迹，孔门传旧声。
今逢大君子，士节自光明。','',''),('quantangshi-20497','新城甲仗楼','張籍','quantangshi','','卷21','谢氏起新楼，西临城角头。
图功百尺丽，藏器五兵修。
结缔榱甍固，虚明户槛幽。
鱼龙卷旗帜，霜雪积戈矛。
暑雨熇烝隔，凉风宴位留。
地高形出没，山静气清优。
睥睨斜光彻，阑干宿霭浮。
芊芊秔稻色，脉脉苑溪流。
郡化黄丞相，诗成沈隐侯。
居兹良得景，殊胜岘山游。','',''),('quantangshi-20498','赠殷山人','張籍','quantangshi','','卷21','郁郁山中客，知名四十年。
恓惶身独隐，寂寞性应便。
世业公侯籍，生涯黍稷田。
藤悬读书帐，竹系网鱼船。
已种千头橘，新开数脉泉。
闲游携酒远，幽语向僧偏。
入洞题松过，看花选石眠。
避喧长汩没，逢胜即留连。
自古多高迹，如君少比肩。
耕耘此辛苦，章句已流传。
昔日交游盛，当时省阁贤。
同袍还共弊，连辔每推先。
讲序居重席，羣儒愿执鞭。
满堂虚左待，众目望乔迁。
才异时难用，情高道自全。
畏人颜惨澹，疎物势迍邅。
贤者闻知命，吾生复礼玄。
深藏报恩劒，久缉养生篇。
憔悴众夫笑，经过郡守怜。
夕阳悲病鹤，霜气动饥鹯。
处士谁能荐，穷途世所捐。
伯鸾甘寄食，元淑苦无钱。
策蹇秋尘里，吟诗黄叶前。
故裘余白领，废瑟断朱弦。
志气终犹在，逍遥任自然。
家贫念婚嫁，身老恋云烟。
放逸栖岩鹿，清虚饮露蝉。
郑逃秦谷口，严爱越溪边。
霄汉予犹阻，荣枯子不牵。
山城一相遇，感激意难宣。','',''),('quantangshi-20499','夏日可畏','張籍','quantangshi','','卷21','赫赫温风扇，炎炎夏日徂。
火威驰逈野，畏景铄遥途。
势矫翔阳翰，功分造化罏。
禁城千品烛，黄道一轮孤。
落照频空簟，余晖卷夕梧。
如何倦游子，中路独踟蹰。','',''),('quantangshi-20500','罔象得玄珠','張籍','quantangshi','','卷21','赤水今何处，遗珠已渺然。
离娄徒肆目，罔象乃通玄。
皎洁因成性，圆明不在泉。
暗中看夜色，尘外照晴田。
无胫真难掬，怀疑实易迁。
今朝搜择得，应免媚晴川。','',''),('quantangshi-20501','和李仆射西园','張籍','quantangshi','','卷21','遇午归闲处，西庭敞四檐。
高眠着琴枕，散帖检书签。
印在休通客，山晴好卷帘。
竹凉蝇少到，藤暗蝶争潜。
晓鹊频惊喜，疎蝉不许拈。
石苔生紫点，栏药吐红尖。
虚坐诗情远，幽探道侣兼。
所营尚胜地，虽俭复谁嫌。','',''),('quantangshi-20502','送裴相公赴镇太原','張籍','quantangshi','','卷21','盛德雄名远近知，功高先乞守藩维。
衔恩暂遣分龙节，署勅还同在凤池。
天子亲临楼上送，朝官齐出道傍辞。
明年塞北清蕃落，应建生祠请立碑。','',''),('quantangshi-20503','寄元员外','張籍','quantangshi','','卷21','外郎直罢无余事，埽洒书堂试药炉。
门巷不教当要闹，诗篇转觉足工夫。
月明台上唯僧到，夜静坊中有酒沽。
朝省入频闲日少，可能同作旧游无。','',''),('quantangshi-20504','赠梅处士','張籍','quantangshi','','卷21','早闻声价满京城，头白江湖放旷情。
讲易自传新注义，题诗不着旧官名。
近移马迹山前住，多向牛头寺里行。
天子如今议封禅，应将束帛请先生。','',''),('quantangshi-20505','赠王秘书','張籍','quantangshi','','卷21','不曾浪出谒公侯，唯向花间水畔游。
每着新衣看药竈，多收古器在书楼。
有官祗作山人老，平地能开洞穴幽。
自领闲司了无事，得来君处喜相留。','',''),('quantangshi-20506','谢裴司空寄马','張籍','quantangshi','','卷21','騄耳新驹骏得名，司空远自寄书生。
乍离华廐移蹄涩，初到贫家举眼惊。
每被闲人来借问，多寻古寺独骑行。
长思岁旦沙堤上，得从鸣珂傍火城。','',''),('quantangshi-20507','酬祕书王丞见寄','張籍','quantangshi','','卷21','相看头白来城阙，却忆漳溪旧往还。
今体诗中偏出格，常参官里每同班。
街西借宅多临水，马上逢人亦说山。
芸阁水曹虽最冷，与君长喜得身闲。','',''),('quantangshi-20508','送李余及第后归蜀','張籍','quantangshi','','卷21','十年人咏好诗章，今日成名出举场。
归去唯将新诰牒，后来争取旧衣裳。
山桥晓上芭蕉暗，水店晴看芋草黄。
乡里亲情相见日，一时携酒贺高堂。','',''),('quantangshi-20509','早朝寄白舍人严郎中','張籍','quantangshi','','卷21','鼓声初动未闻鸡，羸马街中踏冻泥。
烛暗有时冲石柱，雪深无处认沙堤。
常参班里人犹少，待漏房前月欲西。
凤阙星郎离去远，合门开日入还齐。','',''),('quantangshi-20510','书怀寄元郎中','張籍','quantangshi','','卷21','转觉人间无气味，常因身外省因缘。
经过独爱游山客，计校唯求买药钱。
重作学官闲尽日，一离江坞病多年。
吟君钓客词中说，便欲南归榜小船。','',''),('quantangshi-20511','赠道士宜师','張籍','quantangshi','','卷21','自到王城得几年，巴童蜀马共随缘。
两朝侍从当时贵，五字声名远处传。
旧住红楼通内院，新承墨诏赐斋钱。
闲房暂喜居相近，还得陪师坐竹边。','',''),('quantangshi-20512','书怀寄王祕书','張籍','quantangshi','','卷21','白发如今欲满头，从来百事尽应休。
祗于触目须防病，不拟将心更养愁。
下药远求新熟酒，看山多上最高楼。
赖君同在京城住，每到花前免独游。','',''),('quantangshi-20513','题韦郎中新亭','張籍','quantangshi','','卷21','起得幽亭景复新，碧莎地上更无尘。
琴书着尽犹嫌少，松竹栽多亦称贫。
药酒欲开期好客，朝衣暂脱见闲身。
成名同日官连署，此处经过有几人。','',''),('quantangshi-20514','送杨州判官','張籍','quantangshi','','卷21','应得烟霞出俗心，茅山道士共追寻。
闲怜鹤貌偏能画，暗辨桐声自作琴。
长啸每来松下坐，新诗堪向雪中吟。
征南幕里多宾客，君独相知最校深。','',''),('quantangshi-20515','喜王起侍郎放牒','張籍','quantangshi','','卷21','东风节气近清明，车马争来满禁城。
二十八人初上牒，百千万里尽传名。
谁家不借花园看，在处多将酒器行。
共贺春司能鉴识，今年定合有公卿。','',''),('quantangshi-20516','赠王司马','張籍','quantangshi','','卷21','白笏朱衫年少时，久登班列会朝仪。
贮财不省关身用，行义唯愁被众知。
藏得宝刀求主带，调成骏马乞人骑。
未曾相识多闻说，遥望长如白玉枝。','',''),('quantangshi-20517','书怀','張籍','quantangshi','','卷21','自小信成疎嬾性，人间事事总无功。
别从仙客求方法，时到僧家问苦空。
老大登朝如梦里，贫穷作活似村中。
未能即便休官去，惭愧南山采药翁。','',''),('quantangshi-20518','赠令狐博士','張籍','quantangshi','','卷21','头白新年六十余，近闻生计转空虚。
久为博士谁能识，自到长安赁舍居。
骑马出随寻寺客，呼儿散写乞钱书。
古来贤哲皆如此，应是才高与众疎。','',''),('quantangshi-20519','送从弟删东归','張籍','quantangshi','','卷21','云水东南两月程，贪归庆节马蹄轻。
春桥欲醉攀花别，野路闲吟触雨行。
诗价已高犹失意，礼司曾赏会成名。
旧山风月知应好，莫向秋时不到京。','',''),('quantangshi-20520','赠王祕书','張籍','quantangshi','','卷21','早在山东声价远，曾将顺策佐嫖姚。
赋来诗句无闲语，老去官班未在朝。
身屈祗闻词客说，家贫多见野僧招。
独从书阁归时晚，春水渠边看柳条。','',''),('quantangshi-20521','哭丘长史','張籍','quantangshi','','卷21','曾是先皇殿上臣，丹砂久服不成真。
常骑马在嘶空枥，自作书留别故人。
诗句徧传天下口，朝衣偏送地中身。
最悲昨日同游处，看却春风树树新。','',''),('quantangshi-20522','送枝江刘明府','張籍','quantangshi','','卷21','老着青衫为楚宰，平生志业有谁知。
家僮从去愁行远，县吏迎来怪到迟。
定访玉泉幽院宿，应过碧涧早茶时。
向南渐渐云山好，一路唯闻唱竹枝。','',''),('quantangshi-20523','送从弟彻东归','張籍','quantangshi','','卷21','缑山领印知公奏，才称同时尽不如。
奉使贺成登册礼，陪班看出降恩书。
去回在路秋尘里，受诏辞归晓漏初。
早晚得为朝署拜，闲坊买宅作邻居。','',''),('quantangshi-20524','哭胡十八遇','張籍','quantangshi','','卷21','早得声名年尚少，寻常志气出风尘。
文场继续成三代，家族辉华在一身。
幼子见生才满月，选书知写未呈人。
送君帐下衣裳白，数尺坟头栢树新。','',''),('quantangshi-20525','赠贾岛','張籍','quantangshi','','卷21','篱落荒凉僮仆饥，乐游原上住多时。
蹇驴放饱骑将出，秋卷装成寄与谁。
拄杖傍田寻野菜，封书乞米趂时炊。
姓名未上登科记，身屈惟应内史知。','',''),('quantangshi-20526','逢王建有赠','張籍','quantangshi','','卷21','年状皆齐初有髭，鹊山漳水每追随。
使君座下朝听易，处士庭中夜会诗。
新作句成相借问，闲求义尽共寻思。
经今三十余年事，却说还同昨日时。','',''),('quantangshi-20527','移居静安坊答元八郎中','張籍','quantangshi','','卷21','长安寺里多时住，虽守卑官不苦贫。
作活每常嫌费力，移居祗是贵容身。
初开井浅偏宜树，渐觉街闲省踏尘。
更喜往还相去近，门前减却送书人。','',''),('quantangshi-20528','送杨少尹赴凤翔','張籍','quantangshi','','卷21','诗名往日动长安，首首人家卷里看。
西学已行秦博士，南宫新拜汉郎官。
得钱祗了还书铺，借宅常时事药栏。
今去岐州生计薄，移居偏近陇头寒。','',''),('quantangshi-20529','送韩侍御归山','張籍','quantangshi','','卷21','闻君久卧在云间，为佐嫖姚未得还。
新阶茆庐招隐逸，独骑骢马入深山。
九灵洞口行应到，五粒松枝醉亦攀。
明日珂声出城去，家僮不复埽柴关。','',''),('quantangshi-20530','新除水曹郎答白舍人见贺','張籍','quantangshi','','卷21','年过五十到南宫，章句无名荷至公。
黄纸开呈相府后，朱衣引入谢班中。
诸曹纵许为仙侣，羣吏多嫌是老翁。
最幸紫薇郎见爱，独称官与古人同。','',''),('quantangshi-20531','送杨少尹赴满城','張籍','quantangshi','','卷21','官为本府当身荣，因得还乡任野情。
自废田园今作主，每逢耆老不呼名。
旧游寺里僧应识，新别桥边树已成。
公事况闲诗更好，将随相逐上山行。','',''),('quantangshi-20532','哭元九少府','張籍','quantangshi','','卷21','平生志业独相知，早结云山老去期。
初作学官常共宿，晚登朝列暂同时。
闲来各数经过地，醉后齐吟唱和诗。
今日春风花满宅，入门行哭见灵帷。','',''),('quantangshi-20533','送侯判官赴广州从军','張籍','quantangshi','','卷21','年少才高求自展，将身万里赴军门。
辟书远到开呈客，公服新成着谢恩。
驿舫过江分白堠，戍亭当岭见红幡。
海花蛮草连冬有，行处无家不满园。','',''),('quantangshi-20534','答白杭州郡楼登望画图见寄','張籍','quantangshi','','卷21','画得江城登望处，寄来今日到长安。
乍惊物色从诗出，更想工人下手难。
将展书堂偏觉好，每来朝客尽求看。
见君向此闲吟意，肯恨当时作外官。','',''),('quantangshi-20535','赠赵将军','張籍','quantangshi','','卷21','当年胆略已纵横，每见妖星气不平。
身贵早登龙尾道，功高自破鹿头城。
寻常得对论边事，委曲承恩掌内兵。
会取安西将报国，凌烟阁上大书名。','',''),('quantangshi-20536','送和蕃公主','張籍','quantangshi','','卷21','塞上如今无战尘，汉家公主出和亲。
邑司犹属宗卿寺，册号还同虏帐人。
九姓旗幡先引路，一生衣服尽随身。
毡城南望无回日，空见沙蓬水柳春。','',''),('quantangshi-20537','寒食内宴二首 一','張籍','quantangshi','','卷21','朝光瑞气满宫楼，彩纛鱼龙四面稠。
廊下御厨分冷食，殿前香骑逐飞球。
千官尽醉犹教坐，百戏皆呈未放休。
共喜拜恩侵夜出，金吾不敢问行由。','',''),('quantangshi-20538','寒食内宴二首 二','張籍','quantangshi','','卷21','城阙沈沈向晓寒，恩当令节赐余欢。
瑞烟深处开三殿，春雨微时引百官。
宝树楼前分绣幕，彩花廊下暎华栏。
宫筵戏乐年年别，已得三廻对御看。','',''),('quantangshi-20539','朝日勅赐百官樱桃','張籍','quantangshi','','卷21','仙果人间都未有，今朝忽见下天门。
捧盘小吏初宣勅，当殿羣臣共拜恩。
日色遥分门下坐，露香才出禁中园。
每年重此先偏待，愿得千春奉至尊。','',''),('quantangshi-20540','太白老人','張籍','quantangshi','','卷21','日观东峰幽客住，竹巾藤带亦逢迎。
暗修黄箓无人见，深种胡麻共犬行。
洞里仙家常独往，壶中灵药自为名。
春泉四面遶茅屋，日日唯闻杵臼声。','',''),('quantangshi-20541','和裴司空酬满城杨少尹','張籍','quantangshi','','卷21','圣朝偏重大司空，人咏元和第一功。
拥节高临汉水上，题诗远入舜城中。
共惊向老多年别，更忆登科旧日同。
谁不望归丞相府，江边杨柳又秋风。','',''),('quantangshi-20542','寄和州刘使君','張籍','quantangshi','','卷21','别离已久犹为郡，闲向春风倒酒瓶。
送客特过沙口堰，看花多上水心亭。
晓来江气连城白，雨后山光满郭青。
到此诗情应更远，醉中高咏有谁听。','',''),('quantangshi-20543','赠商州王使君','張籍','quantangshi','','卷21','衔命南来会郡堂，却思朝里接班行。
才雄犹是山城守，道薄初为水部郎。
选胜相留开客馆，寻幽更引到僧房。
明朝从此辞君去，独出商关路渐长。','',''),('quantangshi-20544','寄令狐宾客','張籍','quantangshi','','卷21','勋名尽得国家传，退狎琴僧与酒仙。
还带郡符经几处，暂辞台座已三年。
留司未到龙楼下，拜表长怀玉案前。
秋日出城伊水好，领谁相逐上闲船。','',''),('quantangshi-20545','寄梅处士','張籍','quantangshi','','卷21','扰扰人间是与非，官闲自觉省心机。
六行班里身常下，九列符中事亦稀。
市客惯曾赊贱药，家僮惊见着新衣。
君今独得居山乐，应喜多时未办归。','',''),('quantangshi-20546','送施肩吾东归','張籍','quantangshi','','卷21','知君本是烟霞客，被荐因来城阙间。
世业偏临七里濑，仙游多在四明山。
早闻诗句传人徧，新得科名到处闲。
惆怅灞亭相送去，云中琪树不同攀。','',''),('quantangshi-20547','昆仑儿','張籍','quantangshi','','卷21','昆仑家住海中州，蛮客将来汉地游。
言语解教秦吉了，波涛初过郁林洲。
金环欲落曾穿耳，螺髻长卷不裹头。
自爱肌肤黑如漆，行时半脱木绵裘。','',''),('quantangshi-20548','赠李杭州','張籍','quantangshi','','卷21','仙郎白首未归朝，应为苍生领六条。
惠化州人尽清净，高情野鹤与逍遥。
竹间虚馆无朝讼，山畔青田长夏苗。
终日政声长独坐，开门长望浙江潮。','',''),('quantangshi-20549','送郑尚书赴广州','張籍','quantangshi','','卷21','圣朝选将持符节，内使宣时百辟听。
海北蛮夷来舞蹈，岭南封管送图经。
白鹇飞遶迎官舫，红槿开当宴客亭。
此处莫言多瘴疠，天边看取老人星。','',''),('quantangshi-20550','贺秘书王丞南郊摄将军','張籍','quantangshi','','卷21','正初天子亲郊礼，诏摄将军领卫兵。
斜带银刀入黄道，先随玉辂到青城。
坛边不在千官位，仗外唯闻再拜声。
共喜与君逢此日，病中无计得随行。','',''),('quantangshi-20551','送令狐尚书赴东都留守','張籍','quantangshi','','卷21','朝廷重寄在关东，共说从前选上公。
勋业新城大梁镇，恩荣更守洛阳宫。
行香暂出天桥上，巡礼常过禁殿中。
每领羣臣拜章庆，半开门仗日曈曈。','',''),('quantangshi-20552','拜丰陵','張籍','quantangshi','','卷21','岁朝园寝遣公卿，学省班中亦摄行。
身逐陵官齐再拜，手持木铎叩三声。
寒更报点来山殿，晓炬分行照栢城。
却下龙门看渐远，金峰高处日微明。','',''),('quantangshi-20553','赠孔尚书','張籍','quantangshi','','卷21','能将直道历荣班，事着元和实录间。
三表自陈辞北阙，一家相送入南山。
买来侍女教人嫁，赐得朝衣在箧闲。
宅近青山高静处，时归林下暂开关。','',''),('quantangshi-20554','酬杭州白使君兼寄浙东元大夫','張籍','quantangshi','','卷21','相印暂离临远镇，掖垣出守复同时。
一行已作三年别，两处空传七字诗。
越地江山应共见，秦天风月不相知。
人间聚散真难料，莫叹平生信所之。','',''),('quantangshi-20555','寄苏州白二十二使君','張籍','quantangshi','','卷21','三朝出入紫微臣，头白金章未在身。
登第早年同座主，题诗今日是州人。
阊门柳色烟中远，茂苑莺声雨后新。
此处吟诗向山寺，知君忘却曲江春。','',''),('quantangshi-20556','送白宾客分司东都','張籍','quantangshi','','卷21','赫赫声名三十春，高情人独出埃尘。
病辞省闼归闲地，恩许宫曹作上宾。
诗里难同相得伴，酒边多见自由身。
老人也拟休官去，便是君家池上人。','',''),('quantangshi-20557','赠阎少保','張籍','quantangshi','','卷21','辞荣恋阙未还乡，修养年多气力强。
半俸归烧伏火药，全家解说养生方。
特承恩诏新开戟，每见公卿不下牀。
竹树晴深寒院静，长悬石磬在虚廊。','',''),('quantangshi-20558','赠别王侍御赴任陕州司马','張籍','quantangshi','','卷21','京城在处闲人少，唯共君行并马蹄。
更和诗篇名最出，时倾杯酒户常齐。
同趋阙下听钟漏，独向军前闻鼓鼙。
今日春明门外别，更无因得到街西。','',''),('quantangshi-20559','田司空入朝','張籍','quantangshi','','卷21','西来将相位兼雄，不与诸君觐礼同。
早变山东知顺命，新收济上立殊功。
朝官叙谒趋门外，恩使喧迎满路中。
阊阖晓开铜漏静，身当受册大明宫。','',''),('quantangshi-20560','送浙西周判官','張籍','quantangshi','','卷21','由来自是烟霞客，早已闻名诗酒间。
天阙因将贺表到，家乡新着赐衣远。
常吟卷里新酬句，自话湖中旧住山。
吴越主人偏爱重，多应不肯放君闲。','',''),('quantangshi-20561','送吴炼师归王屋','張籍','quantangshi','','卷21','玉阳峰下学长生，玉洞仙中已有名。
独戴熊须冠暂出，唯将鹤尾扇同行。
炼成云母休炊爨，已得雷公当吏兵。
却到瑶坛上头宿，应闻空里步虚声。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-20562','送邵州林使君','張籍','quantangshi','','卷21','词客南行宠命新，潇湘郡入曲江津。
山幽自足探微处，俗朴应无争竞人。
郭外相连排殿阁，市中多半用金银。
知君不作家私计，迁日还同到日贫。','',''),('quantangshi-20563','寄王六侍御','張籍','quantangshi','','卷21','渐觉近来筋力少，难堪今日在风尘。
谁能借问功名事，祗自扶持老病身。
贵得药资将助道，肯嫌家计不如人。
洞庭已置新居处，归去安期与作邻。','',''),('quantangshi-20564','送稽亭山寺僧','張籍','quantangshi','','卷21','师住稽亭高处寺，斜廊曲阁倚云开。
山门十里松间入，泉涧三重洞里来。
名岳寻游今已徧，家城礼谒便应回。
旧房到日闲吟后，林下还登说法台。','',''),('quantangshi-20565','送汀州源使君','張籍','quantangshi','','卷21','曾成赵北归朝计，因拜王门最好官。
为郡暂辞双凤阙，全家远过九龙滩。
山乡祗有输蕉户，水镇应多养鸭栏。
地僻寻常来客少，刺桐花发共谁看。','',''),('quantangshi-20566','寄孙洛阳格','張籍','quantangshi','','卷21','久持刑宪声名远，好是中朝正直臣。
赤县上来应足事，青山老去未离身。
常思从省连归马，乍觉同班少旧人。
