夜来霜压栈，骏骨折西风。','',''),('quantangshi-20888','马诗二十三首 十','李賀','quantangshi','','卷21','摧榜渡乌江，神骓泣向风。','',''),('quantangshi-20889','马诗二十三首 十一','李賀','quantangshi','','卷21','内马赐宫人，银鞯刺骐驎。
