廐中皆肉马，不解上青天。','',''),('quantangshi-20902','申胡子觱篥歌','李賀','quantangshi','','卷21','颜热感君酒，含嚼芦中声。
花娘篸绥妥，休睡芙蓉屏。
谁截太平管，列点排空星。
直贯开花风，天上驱云行。
今夕岁华落，令人惜平生。
心事如波涛，中坐时时惊。
朔客骑白马，剑弝悬兰缨。
俊健如生猱，肯拾蓬中萤。','',''),('quantangshi-20903','老夫采玉歌','李賀','quantangshi','','卷21','采玉采玉须水碧，琢作步摇徒好色。
老夫饥寒龙为愁，蓝溪水气无清白。
夜雨冈头食蓁子，杜鹃口血老夫泪。
蓝溪之水厌生人，身死千年恨溪水。
斜山柏风雨如啸，泉脚挂绳青褭褭。
村寒白屋念娇婴，古台石磴悬肠草。','',''),('quantangshi-20904','伤心行','李賀','quantangshi','','卷21','咽咽学楚吟，病骨伤幽素。
秋姿白发生，木叶啼风雨。
灯青兰膏歇，落照飞蛾舞。
古壁生凝尘，羇魂梦中语。','',''),('quantangshi-20905','湖中曲','李賀','quantangshi','','卷21','长眉越沙采兰若，桂叶水葓春漠漠。
横船醉眠白昼闲，渡口梅风歌扇薄。
燕钗玉股照青渠，越王娇郎小字书。
蜀纸封巾报云鬓，晚漏壶中水淋尽。','',''),('quantangshi-20906','黄家洞','李賀','quantangshi','','卷21','雀步蹙沙声促促，四尺角弓青石镞。
黑幡三点铜鼓鸣，高作猨啼摇箭箙。
彩巾缠踍幅半斜，溪头簇队暎葛花。
山潭晚雾吟白鼍，竹蛇飞蠹射金沙。
闲驱竹马缓归家，官军自杀容州槎。','',''),('quantangshi-20907','屏风曲','李賀','quantangshi','','卷21','蝶栖石竹银交关，水凝绿鸭瑠璃钱。
团回六曲抱膏兰，将鬟镜上掷金蝉。
沈香火暖茱萸烟，酒觥绾带新承懽。
月风吹露屏外寒，城上乌啼楚女眠。','',''),('quantangshi-20908','南山田中行','李賀','quantangshi','','卷21','秋野明，秋风白，塘水漻漻虫啧啧。
云根苔藓山上石，冷红泣露娇啼色。
荒畦九月稻叉牙，蛰萤低飞陇迳斜。
石脉水流泉滴沙，鬼灯如漆点松花。','',''),('quantangshi-20909','贵主征行乐','李賀','quantangshi','','卷21','奚骑黄铜连锁甲，罗旗香干金画叶。
中军留醉河阳城，娇嘶紫燕踏花行。
春营骑将如红玉，走马捎鞭上空绿。
女垣素月角吚吚，牙帐未开分锦衣。','',''),('quantangshi-20910','酒罢张大彻索赠诗','李賀','quantangshi','','卷21','长鬣张郎三十八，天遣裁诗花作骨。
往还谁是龙头人，公主遣秉鱼须笏。
太行青草上白衫，匣中章奏密如蚕。
金门石阁知卿有，豸角鸡香早晚含。
陇西长吉摧颓客，酒阑感觉中区窄。
葛衣断碎赵城秋，吟诗一夜东方白。','',''),('quantangshi-20911','罗浮山父与葛篇','李賀','quantangshi','','卷21','依依宜织江雨空，雨中六月兰台风。
博罗老仙时出洞，千岁石牀啼鬼工。
蛇毒浓凝洞堂湿，江鱼不食衔沙立。
欲剪箱中一尺天，吴娥莫道吴刀涩。','',''),('quantangshi-20912','仁和里杂叙皇甫湜','李賀','quantangshi','','卷21','大人乞马癯乃寒，宗人贷宅荒厥垣。
横庭鼠径空土涩，出篱大枣垂朱残。
安定美人截黄绶，脱落缨裾瞑朝酒。
还家白笔未上头，使我清声落人后。
枉辱称知犯君眼，排引才升强絙断。
洛风送马入长关，阖扇未开逢猰犬。
那知坚都相草草，客枕幽单看春老。
归来骨薄面无膏，疫气冲头鬓茎少。
欲雕小说干天官，宗孙不调为谁怜。
明朝下元复西道，崆峒叙别长如天。','',''),('quantangshi-20913','宫娃歌','李賀','quantangshi','','卷21','蜡光高悬照纱空，花房夜捣红守宫。
象口吹香毾㲪暖，七星挂城闻漏板。
寒入罘罳殿影昏，彩鸾帘额着霜痕。
啼蛄吊月钩栏下，屈膝铜铺锁阿甄。
梦入家门上沙渚，天河落处长洲路。
愿君光明如太阳，放妾骑鱼撇波去。','',''),('quantangshi-20914','堂堂','李賀','quantangshi','','卷21','堂堂复堂堂，红脱梅灰香。
十年粉蠹生画梁，饥虫不食推碎黄。
蕙花已老桃叶长，禁院悬帘隔御光。
华清源中礜石汤，裴回白凤随君王。','',''),('quantangshi-20915','勉爱行二首送小季之庐山 一','李賀','quantangshi','','卷21','洛郊无俎豆，弊廐慙老马。
小雁过炉峰，影落楚水下。
长船倚云泊，石镜秋凉夜。
岂解有乡情，弄月聊呜哑。','',''),('quantangshi-20916','勉爱行二首送小季之庐山 二','李賀','quantangshi','','卷21','别柳当马头，官槐如兔目。
欲将千里别，持我易斗粟。
南云北云空脉断，灵台经络悬春线。
青轩树转月满牀，下国饥儿梦中见。
维尔之昆二十余，年来持镜颇有须。
辞家三载今如此，索米王门一事无。
荒沟古水光如刀，庭南拱柳生蛴螬。
江干幼客真可念，郊原晚吹悲号号。','',''),('quantangshi-20917','致酒行','李賀','quantangshi','','卷21','零落栖迟一杯酒，主人奉觞客长寿。
主父西游困不归，家人折断门前柳。
吾闻马周昔作新丰客，天荒地老无人识。
空将牋上两行书，直犯龙颜请恩泽。
我有迷魂招不得，雄鸡一声天下白。
少年心事当拏云，谁念幽寒坐呜呃。','',''),('quantangshi-20918','长歌续短歌','李賀','quantangshi','','卷21','长歌破衣襟，短歌断白发。
秦王不可见，旦夕成内热。
渴饮壶中酒，饥拔陇头粟。
凄凄四月阑，千里一时绿。
夜峰何离离，明月落石底。
裴回沿石寻，照出高峰外。
不得与之游，歌成鬓先改。','',''),('quantangshi-20919','公莫舞歌','李賀','quantangshi','','卷21','方花古础排九楹，刺豹淋血盛银甖。
华筵鼓吹无桐竹，长刀直立割鸣筝。
横楣麤锦生红纬，日炙锦嫣王未醉。
腰下三看宝玦光，项庄掉箾栏前起。
材官小臣公莫舞，座上真人赤龙子。
芒砀云端抱天回，咸阳王气清如水。
