今年水曲春沙上，笛管新篁拔玉青。','',''),('quantangshi-20923','昌谷北园新笋四首 四','李賀','quantangshi','','卷21','古竹老梢惹碧云，茂陵归卧叹清贫。
风吹千亩迎雨啸，鸟重一枝入酒尊。','',''),('quantangshi-20924','恼公','李賀','quantangshi','','卷21','宋玉愁空断，娇饶粉自红。
歌声春草露，门掩杏花丛。
注口樱桃小，添眉桂叶浓。
晓奁妆秀靥，夜帐减香筒。
钿镜飞孤鹊，江图画水葓。
陂陀梳碧凤，腰褭带金虫。
杜若含清露，河蒲聚紫茸。
月分蛾黛破，花合靥朱融。
发重疑盘雾，腰轻乍倚风。
密书题豆蔲，隐语笑芙蓉。
莫锁茱萸匣，休开翡翠笼。
弄珠惊汉燕，烧蜜引胡蜂。
醉缬抛红网，单罗挂绿蒙。
数钱教姹女，买药问巴賨。
匀脸安斜雁，移灯想梦熊。
肠攒非束竹，胘急是张弓。
晚树迷新蝶，残霓忆断虹。
古时填渤澥，今日凿崆峒。
绣沓褰长幔，罗裙结短封。
心摇如舞鹤，骨出似飞龙。
井槛淋清漆，门铺缀白铜。
隈花开兔径，向壁印狐踪。
玳瑁钉帘薄，琉璃叠扇烘。
象牀缘素柏，瑶席卷香葱。
细管吟朝幌，芳醪落夜枫。
宜男生楚巷，栀子发金墉。
龟甲开屏涩，鹅毛渗墨浓。
黄庭留卫瓘，绿树养韩冯。
鸡唱星悬柳，鵶啼露滴桐。
黄娥初出座，宠妹始相从。
蜡泪垂兰烬，秋芜扫绮栊。
吹笙翻旧引，沽酒待新丰。
短佩愁填粟，长弦怨削菘。
曲池眠乳鸭，小阁睡娃僮。
褥缝篸双线，钩绦辫五总。
蜀烟飞重锦，峡雨溅轻容。
拂镜羞温峤，薰衣避贾充。
鱼生玉藕下，人在石莲中。
含水弯蛾翠，登楼选马鬉。
使君居曲陌，园令住临邛。
桂火流苏暖，金炉细炷通。
春迟王子态，莺啭谢娘慵。
玉漏三星曙，铜街五马逢。
犀株防胆怯，银液镇心忪。
跳脱看年命，琵琶道吉凶。
王时应七夕，夫位在三宫。
无力涂云母，多方带药翁。
符因青鸟送，囊用绛纱缝。
汉苑寻官柳，河桥阂禁钟。
月明中妇觉，应笑画堂空。','',''),('quantangshi-20925','感讽五首 一','李賀','quantangshi','','卷21','合浦无明珠，龙洲无木奴。
足知造化力，不给使君须。
越妇未织作，吴蚕始蠕蠕。
县官骑马来，狞色虬紫须。
怀中一方板，板上数行书。
不因使君怒，焉得诣尔庐。
越妇拜县官，桑牙今尚小。
会待春日晏，丝车方掷掉。
越妇通言语，小姑具黄粱。
县官踏飡去，簿吏复登堂。','',''),('quantangshi-20926','感讽五首 二','李賀','quantangshi','','卷21','奇俊无少年，日车何躃躃。
我待纡双绶，遗我星星发。
都门贾生墓，青蝇久断绝。
寒食摇扬天，愤景长肃杀。
皇汉十二帝，唯帝称睿哲。
一夕信竖儿，文明永沦歇。','',''),('quantangshi-20927','感讽五首 三','李賀','quantangshi','','卷21','南山何其悲，鬼雨洒空草。
长安夜半秋，风前几人老。
低迷黄昏径，褭褭青栎道。
月午树无影，一山唯白晓。
漆炬迎新人，幽圹萤扰扰。','',''),('quantangshi-20928','感讽五首 四','李賀','quantangshi','','卷21','星尽四方高，万物知天曙。
己生须己养，荷担出门去。
君平久不反，康伯循国路。
晓思何譊譊，闤闠千人语。','',''),('quantangshi-20929','感讽五首 五','李賀','quantangshi','','卷21','石根秋水明，石畔秋草瘦。
侵衣野竹香，蛰蛰垂叶厚。
岑中月归来，蟾光挂空秀。
桂露对仙娥，星星下云逗。
凄凉栀子落，山璺泣清漏。
下有张仲蔚，披书案将朽。','',''),('quantangshi-20930','三月过行宫','李賀','quantangshi','','卷21','渠水红繁拥御墙，风娇小叶学娥妆。
垂帘几度青春老，堪锁千年白日长。','',''),('quantangshi-20931','追和何谢铜雀妓','李賀','quantangshi','','卷21','佳人一壶酒，秋容满千里。
石马卧新烟，忧来何所似。
歌声且潜弄，陵树风自起。
长裾压高台，泪眼看花机。','',''),('quantangshi-20932','送秦光禄北征','李賀','quantangshi','','卷21','北虏胶堪折，秋沙乱晓鼙。
髯胡频犯塞，骄气似横霓。
灞水楼船渡，营门细柳开。
将军驰白马，豪彦骋雄材。
箭射欃枪落，旗悬日月低。
榆稀山易见，甲重马频嘶。
天远星光没，沙平草叶齐。
风吹云路火，雪污玉关泥。
屡断呼韩颈，曾然董卓脐。
太常犹旧宠，光禄是新隮。
宝玦麒麟起，银壶狒狖啼。
桃花连马发，彩絮扑鞍来。
呵臂悬金斗，当唇注玉罍。
清苏和碎蚁，紫腻卷浮杯。
虎鞹先蒙马，鱼肠且断犀。
䟃𧽼西旅狗，蹙额北方奚。
守帐然香暮，看鹰永夜栖。
黄龙就别镜，青冢念阳台。
周处长桥役，侯调短弄哀。
钱塘阶凤羽，正室擘鸾钗。
内子攀琪树，羌儿奏落梅。
今朝擎劒去，何日刺蛟回。','',''),('quantangshi-20933','酬答二首 一','李賀','quantangshi','','卷21','金鱼公子夹衫长，密装腰鞓割玉方。
行处春风随马尾，柳花偏打内家香。','',''),('quantangshi-20934','酬答二首 二','李賀','quantangshi','','卷21','雍州二月梅池春，御水䴔䴖暖白苹。
试问酒旗歌板地，今朝谁是抝花人。','',''),('quantangshi-20935','画角东城','李賀','quantangshi','','卷21','河转曙萧萧，鸦飞睥睨高。
帆长摽越甸，壁冷挂吴刀。
淡菜生寒日，鲕鱼潠白涛。
水花霑抹额，旗鼓夜迎潮。','',''),('quantangshi-20936','谢秀才有妾缟练改从于人秀才留之不得[后]生感忆座人制诗嘲谢贺复继四首 一','李賀','quantangshi','','卷21','谁知泥忆云，望断梨花春。
荷丝制机练，竹叶剪花裙。
月明啼阿姊，灯暗会良人。
也识君夫壻，金鱼挂在身。','',''),('quantangshi-20937','谢秀才有妾缟练改从于人秀才留之不得[后]生感忆座人制诗嘲谢贺复继四首 二','李賀','quantangshi','','卷21','铜镜立青鸾，燕脂拂紫绵。
腮花弄暗粉，眼尾泪侵寒。
碧玉破不复，瑶琴重拨弦。
今日非昔日，何人敢正看。','',''),('quantangshi-20938','谢秀才有妾缟练改从于人秀才留之不得[后]生感忆座人制诗嘲谢贺复继四首 三','李賀','quantangshi','','卷21','洞房思不禁，蜂子作花心。
灰暖残香炷，发冷青虫簪。
夜遥灯焰短，睡熟小屏深。
好作鸳鸯梦，南城罢捣砧。','',''),('quantangshi-20939','谢秀才有妾缟练改从于人秀才留之不得[后]生感忆座人制诗嘲谢贺复继四首 四','李賀','quantangshi','','卷21','寻常轻宋玉，今日嫁文鸯。
戟干横龙簴，刀环倚桂窗。
邀人裁半袖，端坐据胡牀。
泪湿红轮重，栖乌上井梁。','',''),('quantangshi-20940','昌谷读书示巴童','李賀','quantangshi','','卷21','虫响灯光薄，宵寒药气浓。
君怜垂翅客，辛苦尚相从。','',''),('quantangshi-20941','巴童答','李賀','quantangshi','','卷21','巨鼻宜山褐，庞眉入苦吟。
非君唱乐府，谁识怨秋深。','',''),('quantangshi-20942','代崔家送客','李賀','quantangshi','','卷21','行盖柳烟下，马蹄白翩翩。
恐随行处尽，何忍重扬鞭。','',''),('quantangshi-20943','出城','李賀','quantangshi','','卷21','雪下桂花稀，啼乌被弹归。
关水乘驴影，秦风帽带垂。
入乡试万里，无印自堪悲。
卿卿忍相问，镜中双泪姿。','',''),('quantangshi-20944','莫种树','李賀','quantangshi','','卷21','园中莫种树，种树四时愁。
独睡南牀月，今秋似去秋。','',''),('quantangshi-20945','将发','李賀','quantangshi','','卷21','东牀卷席罢，[濩]落将行去。
秋白遥遥空，日满门前路。','',''),('quantangshi-20946','追赋画江潭苑四首 一','李賀','quantangshi','','卷21','吴苑晓苍苍，宫衣水溅黄。
小鬟红粉薄，骑马佩珠长。
路指台城迥，罗薰袴褶香。
行云霑翠辇，今日似襄王。','',''),('quantangshi-20947','追赋画江潭苑四首 二','李賀','quantangshi','','卷21','宝袜菊衣单，蕉花密露寒。
水光兰泽叶，带重剪刀钱。
角暖盘弓易，靴长上马难。
泪痕霑寝帐，匀粉照金鞍。','',''),('quantangshi-20948','追赋画江潭苑四首 三','李賀','quantangshi','','卷21','剪翅小鹰斜，[绦]根玉镟花。
秋垂妆钿粟，箭箙钉文牙。
●●啼深竹，䴔䴖老湿沙。
宫官烧蜡火，飞烬汚铅华。','',''),('quantangshi-20949','追赋画江潭苑四首 四','李賀','quantangshi','','卷21','十骑簇芙蓉，宫衣小队红。
练香熏宋鹊，寻箭踏卢龙。
旗湿金铃重，霜干玉镫空。
今朝画眉早，不待景阳钟。','',''),('quantangshi-20950','潞州张大宅病酒遇江使寄上十四兄','李賀','quantangshi','','卷21','秋至昭关后，当知赵国寒。
系书随短羽，写恨破长笺。
病客眠清晓，疎桐坠绿鲜。
城鸦啼粉堞，军吹压芦烟。
岸帻褰沙幌，枯塘卧折莲。
木窗银迹画，石磴水痕钱。
旅酒侵愁肺，离歌绕懦弦。
诗封两条泪，露折一枝兰。
莎老沙鸡泣，松干瓦兽残。
觉骑燕地马，梦载楚溪船。
椒桂倾长席，鲈鲂斫玳筵。
岂能忘旧路，江岛滞佳年。','',''),('quantangshi-20951','难忘曲','李賀','quantangshi','','卷21','夹道开洞门，弱杨低画戟。
帘影竹华起，箫声吹日色。
蜂语绕妆镜，拂蛾学春碧。
乱系丁香梢，满栏花向夕。','',''),('quantangshi-20952','贾公闾贵壻曲','李賀','quantangshi','','卷21','朝衣不须长，分花对袍缝。
嘤嘤白马来，满脑黄金重。
今朝香气苦，珊瑚涩难枕。
且要弄风人，暖蒲沙上饮。
燕语踏帘钩，日虹屏中碧。
潘令在河阳，无人死芳色。','',''),('quantangshi-20953','夜饮朝眠曲','李賀','quantangshi','','卷21','觞酣出座东方高，腰横半解星劳劳。
柳苑鸦啼公主醉，薄露压花蕙园气。
玉转湿丝牵晓水，熟粉生香琅玕紫。
夜饮朝眠断无事，楚罗之帏卧皇子。','',''),('quantangshi-20954','王浚墓下作','李賀','quantangshi','','卷21','人间无阿童，犹唱水中龙。
白草侵烟死，秋梨遶地红。
古书平黑石，袖劒断青铜。
耕势鱼鳞起，坟科马鬣封。
菊花垂湿露，棘径卧干蓬。
松柏愁香涩，南原几夜风。','',''),('quantangshi-20955','客游','李賀','quantangshi','','卷21','悲满千里心，日暖南山石。
不谒承明庐，老作平原客。
四时别家庙，三年去乡国。
旅歌屡弹铗，归问时裂帛。','',''),('quantangshi-20956','崇义里滞雨','李賀','quantangshi','','卷21','落莫谁家子，来感长安秋。
壮年抱羁恨，梦泣生白头。
瘦马秣败草，雨沫飘寒沟。
南宫古帘暗，湿景传签筹。
家山远千里，云脚天东头。
忧眠枕劒匣，客帐梦封侯。','',''),('quantangshi-20957','冯小怜','李賀','quantangshi','','卷21','湾头见小怜，请上琵琶弦。
破得春风恨，今朝直几钱。
裙垂竹叶带，鬓湿杏花烟。
玉冷红丝重，齐宫妾驾鞭。','',''),('quantangshi-20958','赠陈商','李賀','quantangshi','','卷21','长安有男儿，二十心已朽。
楞伽堆案前，楚辞系肘后。
人生有穷拙，日暮聊饮酒。
秪今道已塞，何必须白首。
凄凄陈述圣，披褐鉏俎豆。
学为尧舜文，时人责衰偶。
柴门车辙冻，日下榆影瘦。
黄昏访我来，苦节青阳皱。
太华五千仞，劈地抽森秀。
旁古无寸寻，一上戛牛斗。
公卿纵不怜，宁能锁吾口。
李生师太华，大坐看白昼。
逢霜作朴𣙙，得气为春柳。
礼节乃相去，顦顇如刍狗。
风雪直斋坛，墨组贯铜绶。
臣妾气态间，唯欲承箕帚。
天眼何时开，古劒庸一吼。','',''),('quantangshi-20959','钓鱼诗','李賀','quantangshi','','卷21','秋水钓红渠，仙人待素书。
菱丝萦独茧，蒲米蛰双鱼。
斜竹垂清沼，长纶贯碧虚。
饵悬春[蜥蜴]，钩坠小蟾蜍。
詹子情无限，龙阳恨有余。
为看烟浦上，楚女泪霑裾。','',''),('quantangshi-20960','奉和二兄罢使遣马归延州','李賀','quantangshi','','卷21','空留三尺劒，不用一丸泥。
马向沙场去，人归故国来。
笛愁翻陇水，酒喜沥春灰。
锦带休惊雁，罗衣尚鬬鸡。
还吴已渺渺，入郢莫凄凄。
自是桃李树，何畏不成蹊。','',''),('quantangshi-20961','答赠','李賀','quantangshi','','卷21','本是张公子，曾名萼绿华。
沈香熏小像，杨柳伴啼鸦。
露重金泥冷，杯阑玉树斜。
琴堂沽酒客，新买后园花。','',''),('quantangshi-20962','题赵生壁','李賀','quantangshi','','卷21','大妇然竹根，中妇舂玉屑。
冬暖拾松枝，日烟坐蒙灭。
木藓青桐老，石井水声发。
曝背卧东亭，桃花满肌骨。','',''),('quantangshi-20963','感春','李賀','quantangshi','','卷21','日暖自萧条，花悲北郭骚。
榆穿莱子眼，柳断舞儿腰。
上幕迎神燕，飞丝送百劳。
胡琴今日恨，急语向檀槽。','',''),('quantangshi-20964','仙人','李賀','quantangshi','','卷21','弹琴石壁上，翻翻一仙人。
手持白鸾尾，夜扫南山云。
鹿饮寒涧下，鱼归清海滨。
当时汉武帝，书报桃花春。','',''),('quantangshi-20965','河阳歌','李賀','quantangshi','','卷21','染罗衣，秋蓝难着色。
不是无心人，为作台邛客。
花烧中潬城，颜郎身已老。
惜许两少年，抽心似春草。
今日见银牌，今夜鸣玉宴。
牛头高一尺，隔坐应相见。
月从东方来，酒从东方转。
觥船饫口红，[蜜]炬千枝烂。','',''),('quantangshi-20966','花游曲','李賀','quantangshi','','卷21','春柳南陌态，冷花寒露姿。
今朝醉城外，拂镜浓扫眉。
烟湿愁车重，红油覆画衣。
舞裙香不暖，酒色上来迟。','',''),('quantangshi-20967','春昼','李賀','quantangshi','','卷21','朱城报春更漏转，光风催兰吹小殿。
草细堪梳，柳长如线。
卷衣秦帝，扫粉赵燕。
日含画幕，蜂上罗荐。
平阳花坞，河阳花县。
越妇搘机，吴蚕作茧。
菱汀系带，荷塘倚扇。
江南有情，塞北无恨。','',''),('quantangshi-20968','安乐宫','李賀','quantangshi','','卷21','深井桐乌起，尚复牵情水。
未盥邵陵瓜，瓶中弄长翠。
新成安乐宫，宫如凤皇翅。
歌回蜡板鸣，左悺提壶使。
绿蘩悲水曲，茱萸别秋子。','',''),('quantangshi-20969','胡蝶飞','李賀','quantangshi','','卷21','杨花扑帐春云热，龟甲屏风醉眼缬。
东家胡蝶西家飞，白骑少年今日归。','',''),('quantangshi-20970','梁公子','李賀','quantangshi','','卷21','风彩出萧家，本是菖蒲花。
南塘连子熟，洗马走江沙。
御牋银沫冷，长簟凤窠斜。
种柳营中暗，题书赐馆娃。','',''),('quantangshi-20971','牡丹种曲','李賀','quantangshi','','卷21','莲枝未长秦蘅老，走马驮金斸春草。
水灌香泥却月盆，一夜绿房迎白晓。
美人醉语园中烟，晚华已散蝶又阑。
梁王老去罗衣在，拂袖风吹蜀国弦。
归霞帔拖蜀帐昏，嫣红落粉罢承恩。
檀郎谢女眠何处，楼台月明燕夜语。','',''),('quantangshi-20972','后园凿井歌','李賀','quantangshi','','卷21','井上辘轳牀上转，水声繁，弦声浅。
情若何，荀奉倩。
城头日，长向城头住。
一日作千年，不须流下去。','',''),('quantangshi-20973','开愁歌','李賀','quantangshi','','卷21','秋风吹地百草干，华容碧影生晚寒。
我当二十不得意，一心愁谢如枯兰。
衣如飞鹑马如狗，临岐击剑生铜吼。
旗亭下马解秋衣，请贳宜阳一壶酒。
壶中唤天云不开，白昼万里闲凄迷。
主人劝我养心骨，莫受俗物相填𧱉。','',''),('quantangshi-20974','秦宫诗','李賀','quantangshi','','卷21','越罗衫袂迎春风，玉刻麒麟腰带红。
楼头曲宴仙人语，帐底吹笙香雾浓。
人间酒暖春茫茫，花枝入帘白日长。
飞窗复道传筹饮，十夜铜盘腻烛黄。
秃衿小袖调鹦鹉，紫绣麻䪗踏哮虎。
斫桂烧金待晓筵，白鹿青苏夜半煮。
桐英永巷骑新马，内屋深屏生色画。
开门烂用水衡钱，卷起黄河向身泻。
皇天厄运犹曾裂，秦宫一生花底活。
鸾篦夺得不还人，醉睡氍毺满堂月。','',''),('quantangshi-20975','古邺城童子谣效王粲刺曹操','李賀','quantangshi','','卷21','邺城中，暮尘起。
将黑丸，斫文吏。
棘为鞭，虎为马。
团团走，邺城下。
切玉剑，射日弓。
献何人，奉相公。
扶毂来，关右儿。
香扫涂，相公归。','',''),('quantangshi-20976','杨生青花紫石砚歌','李賀','quantangshi','','卷21','端州石工巧如神，踏天磨刀割紫云。
佣刓抱水含满唇，暗洒苌弘冷血痕。
纱帷昼暖墨花春，轻沤漂沫松麝薰。
干腻薄重立脚匀，数寸光秋无日昏。
圆毫促点声静新，孔砚宽顽何足云。','',''),('quantangshi-20977','房中思','李賀','quantangshi','','卷21','新桂如蛾眉，秋风吹小绿。
行轮出门去，玉銮声断续。
月轩下风露，晓庭自幽涩。
谁能事贞素，卧听莎鸡泣。','',''),('quantangshi-20978','石城晓','李賀','quantangshi','','卷21','月落大堤上，女垣栖乌起。
细露湿团红，寒香解夜醉。
女牛渡天河，柳烟满城曲。
上客留断缨，残蛾鬬双绿。
春帐依微蝉翼罗，横茵突金隐体花。
帐前轻絮鹤毛起，欲说春心无所似。','',''),('quantangshi-20979','苦昼短','李賀','quantangshi','','卷21','飞光飞光，劝尔一杯酒。
吾不识青天高，黄地厚。
唯见月寒日暖，来煎人寿。
食熊则肥，食蛙则瘦。
神君何在，太一安有。
天东有若木，下置衔烛龙。
吾将斩龙足，嚼龙肉。
使之朝不得回，夜不得伏。
自然老者不死，少者不哭。
何为服黄金，吞白玉。
谁似任公子，云中骑碧驴。
刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。','',''),('quantangshi-20980','章和二年中','李賀','quantangshi','','卷21','云萧索，田风拂拂，麦芒如彗黍如粟。
关中父老百领襦，关东吏人乏诟租。
健犊春耕土膏黑，菖蒲丛丛沿水脉。
殷勤为我下田租，百钱携偿丝桐客。
游春漫光坞花白，野林散香神降席。
拜神得寿献天子，七星贯断姮娥死。','',''),('quantangshi-20981','春归昌谷','李賀','quantangshi','','卷21','束发方读书，谋身苦不早。
终军未乘传，颜子鬓先老。
天网信崇大，矫士常慅慅。
逸目骈甘华，羁心如荼蓼。
旱云二三月，岑岫相颠倒。
谁揭頳玉盘，东方发红照。
春热张鹤盖，兔目官槐小。
思焦面如病，尝胆肠似绞。
京国心烂漫，夜梦归家少。
发轫东门外，天地皆浩浩。
青树骊山头，花风满秦道。
宫台光错落，装尽偏峰峤。
细绿及团红，当路杂啼笑。
香风下高广，鞍马正华耀。
独乘鸡栖车，自觉少风调。
心曲语形影，祗身焉足乐。
岂能脱负檐，刻鹤曾无兆。
幽幽太华侧，老柏如建纛。
龙皮相排戛，翠羽更荡掉。
驱趋委憔悴，眺览强容貌。
花蔓阂行輈，縠烟暝深徼。
少健无所就，入门愧家老。
听讲依大树，观书临曲沼。
知非出柙虎，甘作藏雾豹。
韩鸟处[矰]缴，湘鯈在笼罩。
狭行无廓落，壮士徒轻躁。','',''),('quantangshi-20982','昌谷诗','李賀','quantangshi','','卷21','昌谷五月稻，细青满平水。
遥峦相压叠，颓绿愁堕地。
光洁无秋思，凉旷吹浮媚。
竹香满凄寂，粉节涂生翠。
草发垂恨鬓，光露泣幽泪。
层围烂洞曲，芳径老红醉。
攒虫锼古柳，蝉子鸣高邃。
大带委黄葛，紫蒲交狭涘。
石钱差复藉，厚叶皆蟠腻。
汰沙好平白，立马印青字。
晚鳞自遨游，瘦鹄暝单跱。
嘹嘹湿蛄声，咽源惊溅起。
纡缓玉真路，神娥蕙花里。
苔絮萦涧砾，山实垂頳紫。
小柏俨重扇，肥松突丹髓。
鸣流走响韵，壠秋拖光穟。
莺唱闵女歌，瀑悬楚练帔。
风露满笑眼，骈岩杂舒坠。
乱条迸石岭，细颈喧岛毖。
日脚埽昏翳，新云启华閟。
谧谧厌夏光，商风道清气。
高眠服玉容，烧桂祀天几。
雾衣夜披拂，眠坛梦真粹。
待驾栖鸾老，故宫椒壁圮。
鸿珑数铃响，羁臣发凉思。
阴藤束朱键，龙帐着魈魅。
碧锦帖花柽，香衾事残贵。
歌尘蠹木在，舞彩长云似。
珍壤割绣段，里俗祖风义。
邻凶不相杵，疫病无邪祀。
鲐皮识仁惠，丱角知腼耻。
县省司刑官，户乏诟租吏。
竹薮添堕简，石矶引钩饵。
溪湾转水带，芭蕉倾蜀纸。
岑光晃縠襟，孤景拂繁事。
泉尊陶宰酒，月眉谢郎妓。
丁丁幽钟远，矫矫单飞至。
霞巘殷嵯峨，危溜听争次。
淡蛾流平碧，薄月眇阴悴。
凉光入涧岸，廓尽山中意。
渔童下宵网，霜禽竦烟翅。
潭镜滑蛟涎，浮珠噞鱼戏。
风桐瑶匣瑟，萤星锦城使。
柳缀长缥带，篁掉短笛吹。
石根缘绿藓，芦笋抽丹渍。
漂旋弄天影，古桧拏云臂。
愁月薇帐红，罥云香蔓刺。
芒麦平百井，闲乘列千肆。
刺促成纪人，好学鸱夷子。','',''),('quantangshi-20983','铜驼悲','李賀','quantangshi','','卷21','落魄三月罢，寻花去东家。
谁作送春曲，洛岸悲铜驼。
桥南多马客，北山饶古人。
客饮杯中酒，驼悲千万春。
生世莫徒劳，风吹盘上烛。
厌见桃株笑，铜驼夜来哭。','',''),('quantangshi-20984','自昌谷到洛后门','李賀','quantangshi','','卷21','九月大野白，苍芩竦秋门。
寒凉十月末，露霰蒙晓昏。
澹色结昼天，心事填空云。
道上千里风，野竹蛇涎痕。
石涧涷波声，鸡叫清寒晨。
强行到东舍，解马投旧邻。
东家名廖者，乡曲传姓辛。
杖头非饮酒，吾请造其人。
始欲南去楚，又将西适秦。
襄王与武帝，各自留青春。
闻道兰台上，宋玉无归魂。
缃缥两行字，蛰虫蠹秋芸。
为探秦台意，岂命余负薪。','',''),('quantangshi-20985','七月一日晓入太行山','李賀','quantangshi','','卷21','一夕遶山秋，香露溘蒙菉。
新桥倚云阪，候虫嘶露朴。
洛南今已远，越衾谁为熟。
石气何凄凄，老莎如短镞。','',''),('quantangshi-20986','秋凉诗寄正字十二兄','李賀','quantangshi','','卷21','闭门感秋风，幽姿任契阔。
大野生素空，天地旷肃杀。
露光泣残蕙，虫响连夜发。
房寒寸辉薄，迎风绛纱折。
披书古芸馥，恨唱华容歇。
百日不相知，花光变凉节。
弟兄谁念虑，牋翰既通达。
青袍度白马，草简奏东阙。
梦中相聚笑，觉见半牀月。
长思剧寻环，乱忧抵覃葛。','',''),('quantangshi-20987','艾如张','李賀','quantangshi','','卷21','锦襜褕，绣裆襦。
强饮啄，哺尔雏。
陇东卧穟满风雨，莫信笼媒陇西去。
齐人织网如素空，张在野田平碧中。
网丝漠漠无形影，误尔触之伤首红。
艾叶绿花谁剪刻，中藏祸机不可测。','',''),('quantangshi-20988','上云乐','李賀','quantangshi','','卷21','飞香走红满天春，花龙盘盘上紫云。
三千宫女列金屋，五十弦瑟海上闻。
天江碎碎银沙路，嬴女机中断烟素。
断烟素，缝衣缕，八月一日君前舞。','',''),('quantangshi-20989','摩多楼子','李賀','quantangshi','','卷21','玉塞去金人，二万四千里。
风吹沙作云，一时渡辽水。
天白水如练，甲丝双串断。
行行莫苦辛，城月犹残半。
晓气朔烟上，趢趗胡马蹄。
行人临水别，隔陇长东西。','',''),('quantangshi-20990','猛虎行','李賀','quantangshi','','卷21','长戈莫舂，长弩莫抨。
乳孙哺子，教得生狞。
举头为城，掉尾为旌。
东海黄公，愁见夜行。
道逢驺虞，牛哀不平。
何用尺刀，壁上雷鸣。
泰山之下，妇人哭声。
官家有程，吏不敢听。','',''),('quantangshi-20991','日出行','李賀','quantangshi','','卷21','白日下昆仑，发光如舒丝。
徒照葵藿心，不照游子悲。
折折黄河曲，日从中央转。
阳谷耳曾闻，若木眼不见。
奈尔铄石，胡为销人，羿弯弓属矢那不中。
足令久不得奔，讵教晨光夕昏。','',''),('quantangshi-20992','苦篁调啸引','李賀','quantangshi','','卷21','请说轩辕在时事，伶伦采竹二十四。
伶伦采之自昆丘，轩辕诏遣中分作十二。
伶伦以之正音律，轩辕以之调元气。
当时黄帝上天时，二十三管咸相随。
唯留一管人间吹，无德不能得此管，此管沈埋虞舜祠。','',''),('quantangshi-20993','拂舞歌辞','李賀','quantangshi','','卷21','吴娥声绝天，空云闲裴回。
门外满车马，亦须生绿苔。
尊有乌程酒，劝君千万寿。
全胜汉武锦楼上，晓望晴寒饮花露。
东方日不破，天光无老时。
丹成作蛇乘白雾，千年重化玉井土。
从蛇作土一千载，吴堤绿草年年在。
背有八卦称神仙，邪鳞顽甲滑腥涎。','',''),('quantangshi-20994','夜坐吟','李賀','quantangshi','','卷21','踏踏马蹄谁见过，眼看北斗直天河。
西风罗幕生翠波，铅华笑妾颦青蛾。
为君起唱长相思，帘外严霜皆倒飞。
明星烂烂东方陲，红霞梢出东南涯，陆郎去矣乘班骓。','',''),('quantangshi-20995','箜篌引','李賀','quantangshi','','卷21','公乎公乎，提壶将焉如。
屈平沈湘不足慕，徐衍入海诚为愚。
公乎公乎，牀有菅席盘有鱼。
北里有贤兄，东隣有小姑。
陇亩油油黍与葫，瓦甒浊醪蚁浮浮。
黍可食，醪可饮，公乎公乎其奈居。
被发奔流竟何如，贤兄小姑哭呜呜。','',''),('quantangshi-20996','巫山高','李賀','quantangshi','','卷21','碧丛丛，高插天，大江翻澜神曳烟。
楚魂寻梦风飔然，晓风飞雨生苔钱。
瑶姬一去一千年，丁香筇竹啼老猨。
古祠近月蟾桂寒，椒花坠红湿云间。','',''),('quantangshi-20997','平城下','李賀','quantangshi','','卷21','饥寒平城下，夜夜守明月。
别劒无玉花，海风断鬓发。
塞长连白空，遥见汉旗红。
青帐吹短笛，烟雾湿昼龙。
日晚在城上，依稀望城下。
风吹枯蓬起，城中嘶瘦马。
借问筑城吏，去关几千里。
惟愁裹尸归，不惜倒戈死。','',''),('quantangshi-20998','江南弄','李賀','quantangshi','','卷21','江中绿雾起凉波，天上叠巘红嵯峨。
水风浦云生老竹，渚暝蒲帆如一幅。
鲈鱼千头酒百斛，酒中倒卧南山绿。
吴歈越吟未终曲，江上团团帖寒玉。','',''),('quantangshi-20999','荣华乐','李賀','quantangshi','','卷21','鸢肩公子二十余，齿编贝，唇激朱。
气如虹霓，饮如建瓴。
走马夜归呌严更，径穿复道游椒房。
龙裘金玦杂花光，玉堂调笑金楼子。
台下戏学邯郸倡，口吟舌话称女郎。
锦祛绣面汉帝旁，得明珠十斛。
白璧一双，新诏垂金曳紫光煌煌。
马如飞，人如水。
九卿六官皆望履，将回日月先反掌。
欲作江河唯画地，峨峨虎冠上切云。
竦劒晨趋凌紫氛，绣段千寻贻皂隶。
黄金百镒贶家臣，十二门前张大宅。
晴春烟起连天碧，金铺缀日杂红光。
铜龙啮环似争力，瑶姬凝醉卧芳席。
海素笼窗空下隔，丹穴取凤充行庖。
貜貜如拳那足食，金蟾呀呀兰烛香。
军装武妓声琅璫，谁知花雨夜来过。
但见池台春草长，嘈嘈弦吹匝天开。
洪厓箫声遶天来，天长一矢贯双虎。
云弝绝骋聒旱雷，乱袖交竿管儿舞。
吴音绿鸟学言语，能教刻石平紫金。
解送刻毛寄新兔，三皇皇后七贵人。
五十校尉二将军，当时飞去逐彩云，化作今日京华春。','',''),('quantangshi-21000','相劝酒','李賀','quantangshi','','卷21','羲和骋六辔，昼夕不曾闲。
弹乌崦嵫竹，抶马蟠桃鞭。
蓐收既断翠柳，青帝又造红兰。
尧舜至今万万岁，数子将为倾盖间。
青钱白璧买无端，丈夫快意方为欢。
臛蠵臛熊何足云，会须钟饮北海，箕踞南山。
歌淫淫，管愔愔，横波好送雕题金。
人生得意且如此，何用强知元化心。
相劝酒，终无辍，伏愿陛下鸿名终不歇。
子孙绵如石上葛，来长安，车骈骈。
中有梁冀旧宅，石崇故园。','',''),('quantangshi-21001','瑶华乐','李賀','quantangshi','','卷21','穆天子，走龙媒，八辔冬珑逐天回。
五精扫地凝云开，高门左右日月环。
四方错镂棱层殷，舞霞垂尾长盘珊。
江澄海净神母颜，施红点翠照虞泉。
曳云拖玉下昆山，列斾如松，张盖如轮。
金风殿秋，清明发春。
八銮十乘，矗如云屯。
琼钟瑶席甘露文，玄霜绛雪何足云，薰梅染柳将赠君。
铅华之水洗君骨，与君相对作真质。','',''),('quantangshi-21002','北中寒','李賀','quantangshi','','卷21','一方黑照三方紫，黄河冰合鱼龙死。
三尺木皮断文理，百石强车上河水。
霜花草上大如钱，挥刀不入迷蒙天。
争瀯海水飞凌喧，山瀑无声玉虹悬。','',''),('quantangshi-21003','梁台古愁','李賀','quantangshi','','卷21','梁王台沼空中立，天河之水夜飞入。
台前鬬玉作蛟龙，绿粉扫天愁露湿。
撞钟饮酒行射天，金虎蹙裘喷血斑。
朝朝暮暮愁海翻，长绳系日乐当年。
芙蓉凝红得秋色，兰脸别春啼脉脉。
芦洲客雁报春来，寥落野篁秋漫白。','',''),('quantangshi-21004','公无出门','李賀','quantangshi','','卷21','天迷迷，地密密。
熊虺食人魂，雪霜断人骨。
嗾犬狺狺相索索，舐掌偏宜佩兰客。
帝遣乘轩灾自息，玉星点劒黄金轭。
我虽跨马不得还，历阳湖波大如山。
毒虬相视振金环，狻猊猰貐吐嚵涎。
鲍焦一世披草眠，颜回廿九鬓毛斑。
颜回非血衰，鲍焦不违天。
天畏遭衔啮，所以致之然。
分明犹惧公不信，公看呵壁书问天。','',''),('quantangshi-21005','神弦别曲','李賀','quantangshi','','卷21','巫山小女隔云别，春风松花山上发。
绿盖独穿香径归，白马花竿前孑孑。
蜀江风澹水如罗，堕兰谁泛相经过。
南山桂树为君死，云衫浅汚红脂花。','',''),('quantangshi-21006','绿水词','李賀','quantangshi','','卷21','今宵好风月，阿侯在何处。
为有倾人色，翻成足愁苦。
东湖采莲叶，南湖拔蒲根。
未持寄小姑，且持感愁魂。','',''),('quantangshi-21007','沙路曲','李賀','quantangshi','','卷21','柳脸半眠丞相树，佩马钉铃踏沙路。
断烬遗香褭翠烟，烛骑啼乌上天去。
帝家玉龙开九关，帝前动笏移南山。
独垂重印押千官，金窠篆字红屈盘。
沙路归来闻好语，旱火不光天下雨。','',''),('quantangshi-21008','上之回','李賀','quantangshi','','卷21','上之回，大旗喜。
悬红云，挞凤尾。
劒匣破，舞蛟龙。
蚩尤死，鼓逢逢。
天高庆雷齐坠地，地无惊烟海千里。','',''),('quantangshi-21009','高轩过','李賀','quantangshi','','卷21','华裾织翠青如葱，金环压辔摇玲珑。
马蹄隐耳声隆隆，入门下马气如虹。
云是东京才子，文章钜公。
二十八宿罗心胸，九精照耀贯当中。
殿前作赋声摩空，笔补造化天无功。
庞眉书客感秋蓬，谁知死草生华风。
我今垂翅附冥鸿，他日不羞蛇作龙。','',''),('quantangshi-21010','贝宫夫人','李賀','quantangshi','','卷21','丁丁海女弄金环，雀钗翘揭双翅关。
六宫不语一生闲，高悬银牓照青山。
长眉凝绿几千年，清凉堪老镜中鸾。
秋肌稍觉玉衣寒，空光帖妥水如天。','',''),('quantangshi-21011','兰香神女庙','李賀','quantangshi','','卷21','古春年年在，闲绿摇暖云。
松香飞晚华，柳渚含日昏。
沙砌落红满，石泉生水芹。
幽篁画新粉，蛾绿横晓门。
弱蕙不胜露，山秀愁空春。
舞佩剪鸾翼，帐带涂轻银。
兰桂吹浓香，菱藕长莘莘。
看雨逢瑶姬，乘船值江君。
吹箫饮酒醉，结绶金丝裙。
走天呵白鹿，游水鞭锦鳞。
密发虚鬟飞，腻颊凝花匀。
团鬓分蛛巢，穠眉笼小唇。
弄蝶和轻妍，风光怯腰身。
深帏金鸭冷，奁镜幽凤尘。
踏雾乘风归，撼玉山上闻。','',''),('quantangshi-21012','送韦仁实兄弟入关','李賀','quantangshi','','卷21','送客饮别酒，千觞无赭颜。
何物最伤心，马首鸣金镮。
野色浩无主，秋明空旷间。
坐来壮胆破，断目不能看。
行槐引西道，青梢长攒攒。
韦郎好兄弟，叠玉生文翰。
我在山上舍，一亩蒿硗田。
夜雨呌租吏，春声暗交关。
谁解念劳劳，苍突唯南山。','',''),('quantangshi-21013','洛阳城外别皇甫湜','李賀','quantangshi','','卷21','洛阳吹别风，龙门起断烟。
冬树束生涩，晚紫凝华天。
单身野霜上，疲马飞蓬间。
凭轩一双泪，奉坠绿衣前。','',''),('quantangshi-21014','溪晚凉','李賀','quantangshi','','卷22','白狐向月号山风，秋寒扫云留碧空。
玉烟青湿白如幢，银湾晓转流天东。
溪汀眠鹭梦征鸿，轻涟不语细游溶。
层岫回岑复叠龙，苦篁对客吟歌筒。','',''),('quantangshi-21015','官不来题皇甫湜先辈厅','李賀','quantangshi','','卷22','官不来，官庭秋，老桐错干青龙愁。
书司曹佐走如牛，叠声问佐官来不。
官不来，门幽幽。','',''),('quantangshi-21016','长平箭头歌','李賀','quantangshi','','卷22','漆灰骨末丹水沙，凄凄古血生铜花。
白翎金簳雨中尽，直余三脊残狼牙。
我寻平原乘两马，驿东石田蒿坞下。
风长日短星萧萧，黑旗云湿悬空夜。
左魂右魄啼肌瘦，酪瓶倒尽将羊炙。
虫栖雁病芦笋红，回风送客吹阴火。
访古丸澜收断镞，折锋赤璺曾刲肉。
南陌东城马上儿，劝我将金换簝竹。','',''),('quantangshi-21017','江楼曲','李賀','quantangshi','','卷22','楼前流水江陵道，鲤鱼风起芙蓉老。
晓钗催鬓语南风，抽帆归来一日功。
鼍吟浦口飞梅雨，竿头酒旗换青苎。
萧骚浪白云差池，黄粉油衫寄郎主。
新槽酒声苦无力，南湖一顷菱花白。
眼前便有千里愁，小玉开屏见山色。','',''),('quantangshi-21018','塞下曲','李賀','quantangshi','','卷22','胡角引北风，蓟门白于水。
天含青海道，城头月千里。
露下旗蒙蒙，寒金鸣夜刻。
蕃甲鏁蛇鳞，马嘶青冢白。
秋静见旄头，沙远席羁愁。
帐北天应尽，河声出塞流。','',''),('quantangshi-21019','染丝上春机','李賀','quantangshi','','卷22','玉罂泣水桐花井，蒨丝沈水如云影。
美人嬾态燕脂愁，春梭抛掷鸣高楼。
彩线结茸背复叠，白袷玉郎寄桃叶。
为君挑鸾作腰绶，愿君处处宜春酒。','',''),('quantangshi-21020','五粒小松歌','李賀','quantangshi','','卷22','蛇子蛇孙鳞蜿蜿，新香几粒洪厓饭。
绿波浸叶满浓光，细束龙髯铰刀剪。
主人壁上铺州图，主人堂前多俗儒。
月明白露秋泪滴，石笋溪云肯寄书。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21021','塘上行','李賀','quantangshi','','卷22','藕花凉露湿，花缺藕根涩。
飞下雌鸳鸯，塘水声溘溘。','',''),('quantangshi-21022','吕将军歌','李賀','quantangshi','','卷22','吕将军，骑赤兔。
独携大胆出秦门，金粟堆边哭陵树。
北方逆气污青天，劒龙夜呌将军闲。
将军振袖挥劒锷，玉阙朱城有门阁。
榼榼银龟摇白马，傅粉女郎火旗下。
恒山铁骑请金枪，遥闻箙中花箭香。
西郊寒蓬叶如刺，皇天新栽养神骥。
廐中高桁排蹇蹄，饱食青刍饮白水。
圆苍低迷盖张地，九州人事皆如此。
赤山秀铤御时英，绿眼将军会天意。','',''),('quantangshi-21023','休洗红','李賀','quantangshi','','卷22','休洗红，洗多红色浅。
卿卿骋少年，昨日殷桥见。
封侯早归来，莫作弦上箭。','',''),('quantangshi-21024','神弦曲','李賀','quantangshi','','卷22','西山日没东山昏，旋风吹马马踏云。
画弦素管声浅繁，花裙綷䌨步秋尘。
桂叶刷风桂坠子，青狸哭血寒狐死。
古壁彩虬金帖尾，雨工骑入秋潭水。
百年老鸮成木魅，笑声碧火巢中起。','',''),('quantangshi-21025','野歌','李賀','quantangshi','','卷22','鵶翎羽箭山桑弓，仰天射落衔芦鸿。
麻衣黑肥冲北风，带酒日晚歌田中。
男儿屈穷心不穷，枯荣不等嗔天公。
寒风又变为春柳，条条看即烟蒙蒙。','',''),('quantangshi-21026','神弦','李賀','quantangshi','','卷22','女巫浇酒云满空，玉炉炭火香冬冬。
海神山鬼来座中，纸钱窸窣鸣𩘶风。
相思木帖金舞鸾，攒蛾一啑重一弹。
呼星召鬼歆杯盘，山魅食时人森寒。
终南日色低平湾，神兮长在有无间。
神嗔神喜师更颜，送神万骑还青山。','',''),('quantangshi-21027','将进酒','李賀','quantangshi','','卷22','琉璃钟，琥珀浓，小槽酒滴真珠红。
烹龙炮凤玉脂泣，罗屏绣幕围香风。
吹龙笛，击鼍鼓，皓齿歌，细腰舞。
况是青春日将暮，桃花乱落如红雨。
劝君终日酩酊醉，酒不到刘伶坟上土。','',''),('quantangshi-21028','美人梳头歌','李賀','quantangshi','','卷22','西施晓梦绡帐寒，香鬟堕髻半沈檀。
辘轳咿哑转鸣玉，惊起芙蓉睡新足。
双鸾开镜秋水光，解鬟临镜立象牀。
一编香丝云撒地，玉钗落处无声腻。
纤手却盘老鵶色，翠滑宝钗簪不得。
春风烂熳恼娇慵，十八鬟多无气力。
妆成𩭏鬌敧不斜，云裾数步踏雁沙。
背人不语向何处，下堦自折樱桃花。','',''),('quantangshi-21029','月漉漉篇','李賀','quantangshi','','卷22','月漉漉，波烟玉。
莎青桂花繁，芙蓉别江木。
粉态裌罗寒，雁羽铺烟湿。
谁能看石帆，乘船镜中入。
秋白鲜红死，水香莲子齐。
挽菱隔歌袖，绿刺罥银泥。','',''),('quantangshi-21030','京城','李賀','quantangshi','','卷22','驱马出门意，牢落长安心。
两事谁向道，自作秋风吟。','',''),('quantangshi-21031','官街鼓','李賀','quantangshi','','卷22','晓声隆隆催转日，暮声隆隆呼月出。
汉城黄柳暎新帘，柏陵飞燕埋香骨。
磓发千年日长白，孝武秦王听不得。
从君翠发芦花色，独共南山守中国。
几回天上葬神仙，漏声相将无断缘。','',''),('quantangshi-21032','许公子郑姬歌','李賀','quantangshi','','卷22','许史世家外亲贵，宫锦千端买沈醉。
铜驼酒熟烘明胶，古堤大柳烟中翠。
桂开客花名郑袖，入洛闻香鼎门口。
先将芍药献妆台，后解黄金大如斗。
莫愁帘中许合欢，清弦五十为君弹。
弹声咽春弄君骨，骨兴牵人马上鞍。
两马八蹄踏兰苑，情如合竹谁能见。
夜光玉枕栖凤皇，袷罗当门刺纯线。
长翻蜀纸卷明君，转角含商破碧云。
自从小靥来东道，曲里长眉少见人。
相如冢上生秋柏，三秦谁是言情客。
蛾鬟醉眼拜诸宗，为谒皇孙请曹植。','',''),('quantangshi-21033','新夏歌','李賀','quantangshi','','卷22','晓木千笼真蜡彩，落蕊枯香数分在。
阴枝秀牙卷缥茸，长风回气扶葱茏。
野家麦畦上新壠，长畛裴回桑柘重。
刺香满地菖蒲草，雨梁燕语悲身老。
三月摇扬入河道，天浓地浓柳梳扫。','',''),('quantangshi-21034','题归梦','李賀','quantangshi','','卷22','长安风雨夜，书客梦昌谷。
怡怡中堂笑，小弟栽涧菉。
家门厚重意，望我饱饥腹。
劳劳一寸心，灯花照鱼目。','',''),('quantangshi-21035','经沙苑','李賀','quantangshi','','卷22','野水泛长澜，宫牙开小蒨。
无人柳自春，草渚鸳鸯暖。
晴嘶卧沙马，老去悲啼展。
今春还不归，塞嘤折翅雁。','',''),('quantangshi-21036','出城别张又新酬李汉','李賀','quantangshi','','卷22','李子别上国，南山崆峒春。
不闻今夕鼓，差慰煎情人。
赵壹赋命薄，马卿家业贫。
乡书何所报，紫蕨生石云。
长安玉桂国，戟带披侯门。
惨阴地自光，宝马踏晓昏。
腊春戏草苑，玉挽鸣𨏈辚。
绿网缒金铃，霞卷清池漘。
开贯泻蚨母，买冰防夏蝇。
时宜裂大袂，劒客车盘茵。
小人如死灰，心切生秋榛。
皇图跨四海，百姓拖长绅。
光明霭不发，腰龟徒甃银。
吾将噪礼乐，声调摩清新。
欲使十千岁，帝道如飞神。
华实自苍老，流采长倾湓。
没没暗齰舌，涕血不敢论。
今将下东道，祭酒而别秦。
六郡无剿儿，长刀谁拭尘。
地理阳无正，快马逐服辕。
二子美年少，调道讲清浑。
讥笑断冬夜，家庭疎筱穿。
曙风起四方，秋月当东悬。
赋诗面投掷，悲哉不遇人。
此别定霑臆，越布先裁巾。','',''),('quantangshi-21037','南园','李賀','quantangshi','','卷22','方领蕙带折角巾，杜若已老兰苕春。
南山削秀蓝玉合，小雨归去飞凉云。
熟杏暖香梨叶老，草梢竹栅锁池痕。
郑公乡老开酒尊，坐泛楚奏吟招魂。','',''),('quantangshi-21038','假龙吟歌','李賀','quantangshi','','卷22','石轧铜杯，吟咏枯瘁。
苍鹰摆血，白凤下肺。
桂子自落，云弄车盖。
木死沙崩恶溪岛，阿母得仙今不老。
窞中跳汰截清涎，隈壖卧水埋金爪。
崖蹬苍苔吊石发，江君掩帐篔簹折。
莲花去国一千年，雨后闻腥犹带铁。','',''),('quantangshi-21039','感讽六首 一','李賀','quantangshi','','卷22','人间春荡荡，帐暖香扬扬。
飞光染幽红，夸娇来洞房。
舞席泥金蛇，桐竹罗花牀。
眼逐春瞑醉，粉随泪色黄。
王子下马来，曲沼鸣鸳鸯。
焉知肠车转，一夕巡九方。','',''),('quantangshi-21040','感讽六首 二','李賀','quantangshi','','卷22','苦风吹朔寒，沙惊秦木折。
舞影逐空天，画鼓余清节。
蜀书秋信断，黑水朝波咽。
娇魂从回风，死处悬乡月。','',''),('quantangshi-21041','感讽六首 三','李賀','quantangshi','','卷22','杂杂胡马尘，森森边士戟。
天教胡马战，晓云皆血色。
妇人携汉卒，箭箙囊巾帼。
不慙金印重，踉蹡腰鞬力。
恂恂乡门老，昨夜试锋镝。
走马遣书勋，谁能分粉墨。','',''),('quantangshi-21042','感讽六首 四','李賀','quantangshi','','卷22','青门放弹去，马色连空郊。
何年帝家物，玉装鞍上摇。
去去走犬归，来来坐烹羔。
千金不了馔，狢肉称盘臊。
试问谁家子，乃老能佩刀。
西山白盖下，贤儁寒萧萧。','',''),('quantangshi-21043','感讽六首 五','李賀','quantangshi','','卷22','晓菊泫寒露，似悲团扇风。
秋凉经汉殿，班子泣衰红。
本无辞辇意，岂见入空宫。
腰衱佩珠断，灰蝶生阴松。','',''),('quantangshi-21044','感讽六首 六','李賀','quantangshi','','卷22','蝶飞红粉台，柳扫吹笙道。
十日悬户庭，九秋无衰草。
调歌送风转，杯池白鱼小。
水宴截香腴，菱科映青罩。
䒠蒙梨花满，春昏弄长啸。
唯愁苦花落，不悟世衰到。
抚旧唯销魂，南山坐悲峭。','',''),('quantangshi-21045','莫愁曲','李賀','quantangshi','','卷22','草生龙坡下，鵶噪城堞头。
何人此城里，城角栽石榴。
青丝系五马，黄金络双牛。
白鱼驾莲船，夜作十里游。
归来无人识，暗上沈香楼。
罗牀倚瑶瑟，残月倾帘钩。
今日槿花落，明朝桐树秋。
莫负平生意，何名何莫愁。','',''),('quantangshi-21046','夜来乐','李賀','quantangshi','','卷22','红罗复帐金流苏，华灯九枝悬鲤鱼。
丽人暎月开铜铺，春水滴酒猩猩沽。
重一箧，香十株，赤金瓜子兼杂麸。
五丝封青凫，阿侯此笑千万余。
南轩汉转帘影疎，桐林哑哑挟子乌。
劒崖鞭节青石珠，白騧吹湍凝霜须。
漏长送佩承明庐，倡楼嵯峨明月孤。
新客下马故客去，绿蝉秀黛重拂梳。','',''),('quantangshi-21047','嘲雪','李賀','quantangshi','','卷22','昨日发葱岭，今朝下兰渚。
喜从千里来，乱笑含春语。
龙沙湿汉旗，凤扇迎秦素。
久别辽城鹤，毛衣已应故。','',''),('quantangshi-21048','春怀引','李賀','quantangshi','','卷22','芳蹊密影成花洞，柳结浓烟花带重。
蟾蜍碾玉挂明弓，捍拨装金打仙凤。
宝枕垂云选春梦，钿合碧寒龙脑冻。
阿侯系锦觅周郎，凭仗东风好相送。','',''),('quantangshi-21049','白虎行','李賀','quantangshi','','卷22','火乌日暗崩腾云，秦皇虎视苍生羣。
烧书灭国无暇日，铸劒佩玦惟将军。
玉坛设醮思冲天，一世二世当万年。
烧丹未得不死药，拏舟海上寻神仙。
鲸鱼张鬣海波沸，耕人半作征人鬼。
雄豪气猛如焰烟，无人为决天河水。
谁最苦兮谁最苦，报人义士深相许。
渐离击筑荆卿歌，荆卿把酒燕丹语。
劒如霜兮胆如铁，出燕城兮望秦月。
天授秦封祚未移，衮龙衣点荆卿血。
朱旗卓地白虎死，汉皇知是真天子。','',''),('quantangshi-21050','有所思','李賀','quantangshi','','卷22','去年陌上歌离曲，今日君书远游蜀。
帘外花开二月风，台前泪滴千行竹。
琴心与妾肠，此夜断还续。
想君白马悬雕弓，世间何处无春风。
君心未肯镇如石，妾颜不久如花红。
夜残高碧横长河，河上无梁空白波。
西风未起悲龙梭，年年织素攒双蛾。
江山迢遰无休绝，泪眼看灯乍明灭。
自从孤馆深锁窗，桂花几度圆还缺。
鵶鵶向晓鸣森木，风过池塘响丛玉。
白日萧条梦不成，桥南更问仙人卜。','',''),('quantangshi-21051','啁少年','李賀','quantangshi','','卷22','青騘马肥金鞍光，龙脑入缕罗衫香。
美人狭坐飞琼觞，贫人唤云天上郎。
别起高楼临碧筱，丝曳红鳞出深沼。
有时半醉百花前，背把金丸落飞鸟。
自说生来未为客，一身美妾过三百。
岂知斸地种苗家，官税频催勿人织。
长得积玉夸豪毅，每揖闲人多意气。
生来不读半行书，只把黄金买身贵。
少年安得长少年，海波尚变为桑田。
荣枯递传急如箭，天公不肯于公偏。
莫道韶华镇长在，发白面皱专相待。','',''),('quantangshi-21052','高平县东私路','李賀','quantangshi','','卷22','侵侵槲叶香，木花滞寒雨。
今夕山上秋，永谢无人处。
石磎远荒涩，棠实悬辛苦。
古者定幽寻，呼君作私路。','',''),('quantangshi-21053','神仙曲','李賀','quantangshi','','卷22','碧峰海面藏灵书，上帝拣作神仙居。
清明笑语闻空虚，鬬乘巨浪骑鲸鱼。
春罗书字邀王母，共宴红楼最深处。
鹤羽冲风过海迟，不如却使青龙去。
犹疑王母不相许，垂露娃鬟更传语。','',''),('quantangshi-21054','龙夜吟','李賀','quantangshi','','卷22','鬈发胡儿眼睛绿，高楼夜静吹横竹。
一声似向天上来，月下美人望乡哭。
直排七点星藏指，暗合清风调宫征。
蜀道秋深云满林，湘江半夜龙惊起。
玉堂美人边塞情，碧窗皓月愁中听。
寒砧能捣百尺练，粉泪凝珠滴红线。
胡儿莫作陇头吟，隔窗暗结愁人心。','',''),('quantangshi-21055','昆仑使者','李賀','quantangshi','','卷22','昆仑使者无消息，茂陵烟树生愁色。
金盘玉露自淋漓，元气茫茫收不得。
麒麟背上石文裂，虬龙鳞下红枝折。
何处偏伤万国心，中天夜久高明月。','',''),('quantangshi-21056','汉唐姬饮酒歌','李賀','quantangshi','','卷22','御服沾霜露，天衢长蓁棘。
金隐秋尘姿，无人为带饰。
玉堂歌声寝，芳林烟树隔。
云阳台上歌，鬼哭复何益。
铁劒常光光，至凶威屡逼。
彊枭噬母心，犇厉索人魄。
相看两相泣，泪下如波激。
宁用清酒为，欲作黄泉客。
不说玉山颓，且无饮中色。
勉从天帝诉，天上寡沈厄。
无处张穗帷，如何望松柏。
妾身昼团团，君魂夜寂寂。
蛾眉自觉长，颈粉谁怜白。
矜持昭阳意，不肯看南陌。','',''),('quantangshi-21057','听颖师琴歌','李賀','quantangshi','','卷22','别浦云归桂花渚，蜀国弦中双凤语。
芙蓉叶落秋鸾离，越王夜起游天姥。
暗佩清臣敲水玉，渡海蛾眉牵白鹿。
谁看挟劒赴长桥，谁看浸发题春竹。
竺僧前立当吾门，梵宫真相眉棱尊。
古琴大轸长八尺，峄阳老树非桐孙。
凉馆闻弦惊病客，药囊暂别龙须席。
请歌直请卿相歌，奉礼官卑复何益。','',''),('quantangshi-21058','谣俗','李賀','quantangshi','','卷22','上林胡蝶小，试伴汉家君。
飞向南城去，误落石榴裙。
脉脉花满树，翾翾燕遶云。
出门不识路，羞问陌头人。','',''),('quantangshi-21059','静女春曙曲','李賀','quantangshi','','卷22','嫩叶怜芳抱新蕊，泣露枝枝滴夭泪。
粉窗香咽颓晓云，锦堆花密藏春睡。
恋屏孔雀摇金尾，莺舌分明呼婢子。
冰洞寒龙半匣水，一只商鸾逐烟起。','',''),('quantangshi-21060','少年乐','李賀','quantangshi','','卷22','芳草落花如锦地，二十长游醉乡里。
红缨不动白马骄，垂柳金丝香拂水。
吴娥未笑花不开，绿鬓耸堕兰云起。
陆郎倚醉牵罗袂，夺得宝钗金翡翠。','',''),('quantangshi-21061','句','李賀','quantangshi','','卷22','不见山巅树，摧杌下为薪。
日覩井中泥，上出作埃尘。
情知一丘趣，不谢千里印。
倚剑登高台，悠悠送春目。','',''),('quantangshi-21062','冰柱','劉叉','quantangshi','','卷22','师干久不息，农为兵兮民重嗟。
骚然县宇，土崩水溃。
畹中无熟谷，壠上无桑麻。
王春判序，百卉茁甲含葩。
有客避兵奔游僻，跋履险厄至三巴。
貂裘蒙茸已敝缕，鬓发蓬舥。
雀惊鼠伏，宁遑安处。
独卧旅舍无好梦，更堪走风沙。
天人一夜剪瑛琭，诘旦都成六出花。
南亩未盈尺，纤片乱舞空纷拏。
旋落旋逐朝暾化，檐间冰柱若削出交加。
或低或昂，小大莹洁。
随势无等差，始疑玉龙下界来人世。
齐向茅檐布爪牙，又疑汉高帝。
西方未斩虵，人不识，谁为当风杖莫邪。
铿镗冰有韵，的皪玉无瑕。
不为四时雨，徒于道路成泥柤。
不为九江浪，徒为汩没天之涯。
不为双井水，满瓯泛泛烹春茶。
不为中山浆，清新馥鼻盈百车。
不为池与沼，养鱼种芰成霪䨟。
不为醴泉与甘露，使名异瑞世俗夸。
特禀朝澈气，洁然自许靡间其迩遐。
森然气结一千里，滴沥声沈十万家。
明也虽小，暗之大不可遮。
勿被曲瓦，直下不能抑羣邪。
奈何时逼，不得时在我目中。
倏然漂去无余㱔，自是成毁任天理。
天于此物岂宜有忒赊，反令井蛙壁虫变容易。
背人缩首竞呀呀，我愿天子回造化。
藏之韫椟翫之生光华。','',''),('quantangshi-21063','雪车','劉叉','quantangshi','','卷22','腊令凝绨三十日，缤纷密雪一复一。
孰云润泽在枯荄，闤闠饿民涷欲死。
死中犹被豺狼食，官车初还城垒未完备。
人家千里无烟火，鸡犬何太怨。
天不恤吾甿，如何连夜瑶花乱。
皎洁既同君子节，沾濡多着小人面。
寒鏁侯门见客稀，色迷塞路行商断。
小小细细如尘间，轻轻缓缓成朴簌。
官家不知民馁寒，尽驱牛车盈道载屑玉。
载载欲何之，祕藏深宫以御炎酷。
徒能自卫九重间，岂信车辙血，点点尽是农夫哭。
刀兵残丧后，满野谁为载白骨。
远戍久乏粮，太仓谁为运红粟。
戎夫尚逆命，扁箱鹿角谁为敌。
士夫困征讨，买花载酒谁为适。
天子端然少旁求，股肱耳目皆奸慝。
依违用事佞上方，犹驱饿民运造化防暑厄。
吾闻躬耕南亩舜之圣，为民吞蝗唐之德。
未闻𭐁孽苦苍生，相羣相党上下为蟊贼。
庙堂食禄不自慙，我为斯民叹息还叹息。','',''),('quantangshi-21064','修养','劉叉','quantangshi','','卷22','损神终日谈虚空，不必归命于胎中。
我神不西亦不东，烟收云散何蒙蒙。
尝令体如微微风，绵绵不断道自冲。
世人逢一不逢一，一回存想一回出。
只知一切望一切，不觉一日损一日。
劝君修真复识真，世上道人多忤人。
披图醮录益乱神，此法那能坚此身。
心田自有灵地珍，惜哉自有不自亲，明真汩没随埃尘。','',''),('quantangshi-21065','勿执古寄韩潮州','劉叉','quantangshi','','卷22','古人皆执古，不辞[冻]饿悲。
今人亦执古，自取行坐危。
老菊凌霜葩，狞松抱雪姿。
武王亦至明，宁哀首阳饥。
仲尼岂非圣，但为互乡嗤。
寸心生万路，今古棼若丝。
逐逐行不尽，茫茫休者谁。
来恨不可遏，去悔何足追。
玉石共笑唾，驽骥相奔驰。
请君勿执古，执古徒自隳。','',''),('quantangshi-21066','答孟东野','劉叉','quantangshi','','卷22','酸寒孟夫子，苦爱老叉诗。
生涩有百篇，谓是琼瑶辞。
百篇非所长，忧来豁穷悲。
唯有刚肠铁，百炼不柔亏。
退之何可駡，东野何可欺。
文王已云没，谁顾好爵縻。
生死守一丘，宁计饱与饥。
万事付杯酒，从人笑狂痴。','',''),('quantangshi-21067','自古无长生劝姚合酒','劉叉','quantangshi','','卷22','奉子一杯酒，为子照颜色。
但愿腮上红，莫管颏下白。
自古无长生，生者何戚戚。
登山勿厌高，四望都无极。
丘陇逐日多，天地为我窄。
祗见李耳书，对之空脉脉。
何曾见天上，着得刘安宅。
若问长生人，昭昭孔丘籍。','',''),('quantangshi-21068','独饮','劉叉','quantangshi','','卷22','尽欲调太羹，自古无好手。
所以山中人，兀兀但饮酒。','',''),('quantangshi-21069','作诗','劉叉','quantangshi','','卷22','作诗无知音，作不如不作。
未逢赓载人，此道终寂寞。
有虞今已殁，来者谁为托。
朗咏豁心胸，笔与泪俱落。','',''),('quantangshi-21070','天津桥','劉叉','quantangshi','','卷22','洛阳宫阙照天地，四面山川无毒气。
谁令汉祖都秦关，从此奸雄转相炽。','',''),('quantangshi-21071','嘲荆卿','劉叉','quantangshi','','卷22','白虹千里气，血颈一劒义。
报恩不到头，徒作轻生士。','',''),('quantangshi-21072','代牛言','劉叉','quantangshi','','卷22','渴饮颍水流，饿喘吴门月。
黄金如可种，我力终不竭。','',''),('quantangshi-21073','莫问卜','劉叉','quantangshi','','卷22','莫问卜，人生吉凶皆自速。
伏羲文王若无死，今人不为古人哭。','',''),('quantangshi-21074','观八骏图','劉叉','quantangshi','','卷22','穆王八骏走不歇，海外去寻长日月。
五云望断阿母宫，归来落得新白发。','',''),('quantangshi-21075','经战地','劉叉','quantangshi','','卷22','杀气不上天，阴风吹雨血。
冤魂不入地，髑髅哭沙月。
人命固有常，此地何夭折。','',''),('quantangshi-21076','野哭','劉叉','quantangshi','','卷22','棘针生狞义路闲，野泉相吊声潺潺。
哀哉异教溺颓俗，淳源一去何时还。','',''),('quantangshi-21077','古怨','劉叉','quantangshi','','卷22','君莫嫌丑妇，丑妇死守贞。
山头一怪石，长作望夫名。
鸟有并翼飞，兽有比肩行。
丈夫不立义，岂如鸟兽情。','',''),('quantangshi-21078','烈士咏','劉叉','quantangshi','','卷22','烈士或爱金，爱金不为贫。
义死天亦许，利生鬼亦嗔。
胡为轻薄儿，使酒杀平人。','',''),('quantangshi-21079','狂夫','劉叉','quantangshi','','卷22','大妻唱舜歌，小妻鼓湘瑟。
狂夫游冶归，端坐仍作色。
不读关雎篇，安知后妃德。','',''),('quantangshi-21080','饿咏','劉叉','quantangshi','','卷22','文王久不出，贤士如土贱。
妻孥从饿死，敢爱黄金篆。','',''),('quantangshi-21081','自问','劉叉','quantangshi','','卷22','自问彭城子，何人授汝颠。
酒肠宽似海，诗胆大于天。
断劒徒劳匣，枯琴无复弦。
相逢不多合，赖是向林泉。','',''),('quantangshi-21082','入蜀','劉叉','quantangshi','','卷22','望空问真宰，此路为谁开。
峡色侵天去，江声滚地来。
孔明深有意，钟会亦何才。
信此非人事，悲歌付一杯。','',''),('quantangshi-21083','塞上逢卢仝','劉叉','quantangshi','','卷22','直到桑干北，逢君夜不眠。
上楼腰脚健，怀土眼睛穿。
斗柄寒垂地，河流[冻]彻天。
羁魂泣相向，何事有诗篇。','',''),('quantangshi-21084','偶书','劉叉','quantangshi','','卷22','日出扶桑一丈高，人间万事细如毛。
野夫怒见不平处，磨损胸中万古刀。','',''),('quantangshi-21085','爱碣山石','劉叉','quantangshi','','卷22','碣石何青青，挽我双眼睛。
爱尔多古峭，不到人间行。','',''),('quantangshi-21086','与孟东野','劉叉','quantangshi','','卷22','寒衣草木皮，饥饭葵藿根。
不为孟夫子，岂识市井门。','',''),('quantangshi-21087','姚秀才爱予小劒因赠','劉叉','quantangshi','','卷22','一条古时水，向我手心流。
临行泻赠君，勿薄细碎讐。','',''),('quantangshi-21088','老恨','劉叉','quantangshi','','卷22','雪打杉松残，补书书不完。
嬾学渭上翁，辛苦把钓竿。','',''),('quantangshi-21089','思归乐','稹','quantangshi','','卷22','山中思归乐，尽作思归鸣。
尔是此山鸟，安得失乡名。
应缘此山路，自古离人征。
阴愁感和气，俾尔从此生。
我虽失乡去，我无失乡情。
惨舒在方寸，宠辱将何惊。
浮生居大块，寻丈可寄形。
身安即形乐，岂独乐咸京。
命者道之本，死者天之平。
安问远与近，何言殇与彭。
君看赵工部，八十支体轻。
交州二十载，一到长安城。
长安不须臾，复作交州行。
交州又累岁，移镇广与荆。
归朝新天子，济济为上卿。
肌肤无瘴色，饮食康且宁。
长安一昼夜，死者如霣星。
丧车四门出，何关炎瘴萦。
况我三十二，百年未半程。
江陵道涂近，楚俗云水清。
遐想玉泉寺，久闻岘山亭。
此去尽绵历，岂无心赏并。
红餐日充腹，碧涧朝析酲。
开门待宾客，寄书安弟兄。
闲穷四声韵，闷阅九部经。
身外皆委顺，眼前随所营。
此意久已定，谁能求苟荣。
所以官甚小，不畏权势倾。
倾心岂不易，巧诈神之刑。
万物有本性，况复人性灵。
金埋无土色，玉坠无瓦声。
劒折有寸利，镜破有片明。
我可俘为囚，我可刃为兵。
我心终不死，金石贯以诚。
此诚患不至，诚至道亦亨。
微哉满山鸟，呌噪何足听。','',''),('quantangshi-21090','春鸠','稹','quantangshi','','卷22','春鸠与百舌，音响讵同年。
如何一时语，俱得春风怜。
犹知化工意，当春不生蝉。
免教争呌噪，沸渭桃花前。','',''),('quantangshi-21091','春蝉','稹','quantangshi','','卷22','我自东归日，厌苦春鸠声。
作诗怜化工，不遣春蝉生。
及来商山道，山深气不平。
春秋两相似，虫豸百种鸣。
风松不成韵，蜩螗沸如羹。
岂无朝阳凤，羞与微物争。
安得天上雨，奔浑河海倾。
荡涤反时气，然后好晴明。','',''),('quantangshi-21092','兔丝','稹','quantangshi','','卷22','人生莫依倚，依倚事不成。
君看兔丝蔓，依倚榛与荆。
荆榛易蒙密，百鸟撩乱鸣。
下有狐兔穴，奔走亦纵横。
樵童斫将去，柔蔓与之并。
翳荟生可耻，束缚死无名。
桂树月中出，珊瑚石上生。
俊鹘度海食，应龙升天行。
灵物本特达，不复相缠萦。
缠萦竟何者，荆棘与飞茎。','',''),('quantangshi-21093','古社','稹','quantangshi','','卷22','古社基址在，人散社不神。
惟有空心树，妖狐藏魅人。
狐惑意颠倒，臊腥不复闻。
丘坟变城郭，花草仍荆榛。
良田千万顷，占作天荒田。
主人议芟斫，怪见不敢前。
那言空山烧，夜随风马奔。
飞声鼓鼙震，高焰旗帜飜。
逡巡荆棘尽，狐兔无子孙。
狐死魅人灭，烟消坛墠存。
绕坛旧田地，给授有等伦。
农收邨落盛，社树新团圆。
社公千万岁，永保邨中民。','',''),('quantangshi-21094','松树','稹','quantangshi','','卷22','华山高幢幢，上有高高松。
株株遥各各，叶叶相重重。
槐树夹道植，枝叶俱冥蒙。
既无贞直干，复有罥挂虫。
何不种松树，使之摇清风。
秦时已曾种，顦顇种不供。
可怜孤松意，不与槐树同。
闲在高山顶，樛盘虬与龙。
屈为大厦栋，庇荫侯与公。
不肯作行伍，俱在尘土中。','',''),('quantangshi-21095','芳树','稹','quantangshi','','卷22','芳树已寥落，孤英尤可嘉。
可怜团团叶，盖覆深深花。
游蜂竞钻刺，鬬雀亦纷拏。
天生细碎物，不爱好华光。
非无歼殄法，念尔有生涯。
春雷一声发，惊燕亦惊蛇。
清池养神蔡，已复长虾蟇。
雨露贵平施，吾其春草芽。','',''),('quantangshi-21096','桐花','稹','quantangshi','','卷22','胧月上山馆，紫桐垂好阴。
可惜暗澹色，无人知此心。
舜没苍梧野，凤归丹穴岑。
遗落在人世，光华那复深。
年年怨春意，不竞桃杏林。
唯占清明后，牡丹还复侵。
况此空馆闭，云谁恣幽寻。
徒烦鸟噪集，不语山嵚岑。
满院青苔地，一树莲花簪。
自开还自落，暗芳终暗沈。
尔生不得所，我愿裁为琴。
安置君王侧，调和元首音。
安问宫征角，先辨雅郑淫。
宫弦春以君，君若春日临。
商弦廉以臣，臣作旱天霖。
人安角声畅，人困鬬不任。
羽以类万物，祆物神不歆。
征以节百事，奉事罔不钦。
五者苟不乱，天命乃可忱。
君若问孝理，弹作梁山吟。
君若事宗庙，拊以和球琳。
君若不好谏，愿献触疏箴。
君若不罢猎，请听荒于禽。
君若侈台殿，雍门可霑襟。
君若傲贤隽，鹿鸣有食芩。
君闻祈招什，车马勿骎骎。
君若欲败度，中有式如金。
君闻薰风操，志气在愔愔。
中有阜财语，勿受来献賝。
北里当绝听，祸莫大于淫。
南风苟不竞，无往遗之擒。
奸声不入耳，巧言宁孔壬。
枭音亦云革，安得沴与祲。
天子既穆穆，羣材亦森森。
劒士还农野，丝人归织纴。
丹凤巢阿阁，文鱼游碧浔。
和气浃寰海，易若溉蹄[涔]。
改张乃可鼓，此语无古今。
非琴独能尔，事有谕因针。
感尔桐花意，闲怨杳难禁。
待我持斤斧，置君为大琛。','',''),('quantangshi-21097','雉媒','稹','quantangshi','','卷22','双雉在野时，可怜同嗜欲。
毛衣前后成，一种文章足。
一雉独先飞，冲开芳草绿。
网罗幽草中，暗被潜羁束。
剪刀摧六翮，丝线缝双目。
啖养能几时，依然已驯熟。
都无旧性灵，返与他心腹。
置在芳草中，翻令诱同族。
前时相失者，思君意弥笃。
朝朝旧处飞，往往巢边哭。
今朝树上啼，哀音断还续。
远见尔文章，知君草中伏。
和鸣忽相召，鼓翅遥相瞩。
畏我未肯来，又啄翳前粟。
歛翮远投君，飞驰势奔蹙。
罥挂在君前，向君声促促。
信君决无疑，不道君相覆。
自恨飞太高，疎罗偶然触。
看看架上鹰，拟食无罪肉。
君意定何如，依旧雕笼宿。','',''),('quantangshi-21098','箭镞','稹','quantangshi','','卷22','箭镞本求利，淬砺良甚难。
砺将何所用，砺以射凶残。
不砺射不入，不射人不安。
为盗即当射，宁问私与官。
夜射官中盗，中之血阑干。
带箭君前诉，君王悄不欢。
顷曾为盗者，百箭中心攒。
竞将儿女泪，滴沥助辛酸。
君王责良帅，此祸谁为端。
帅言发硎罪，不使刃稍刓。
君王不忍杀，逐之如迸丸。
仍令后来箭，尽可头团团。
发硎去虽远，砺镞心不阑。
会射蛟螭尽，舟行无恶澜。','',''),('quantangshi-21099','赛神','稹','quantangshi','','卷22','邨落事妖神，林木大如邨。
事来三十载，巫觋传子孙。
邨中四时祭，杀尽鸡与豚。
主人不堪命，积燎曾欲燔。
旋风天地转，急雨江河翻。
采薪持斧者，弃斧纵横奔。
山深多掩暎，仅免鲸鲵吞。
主人集邻里，各各持酒罇。
庙中再三拜，愿得禾稼存。
去年大巫死，小觋又妖言。
邑中神明宰，有意效西门。
焚除计未决，伺者迭乘轩。
庙深荆棘厚，但见狐兔蹲。
巫言小神变，可验牛马蕃。
邑吏齐进说，幸勿祸乡原。
逾年计不定，县听良亦烦。
涉夏祭时至，因令修四垣。
忧虞神愤恨，玉帛意弥敦。
我来神庙下，箫鼓正喧喧。
因言遣妖术，灭绝由本根。
主人中罢舞，许我重叠论。
蜉蝣生湿处，鸱鸮集黄昏。
主人邪心起，气焰日夜繁。
狐狸得蹊径，潜穴主人园。
腥臊袭左右，然后托丘樊。
岁深树成就，曲直可轮辕。
幽妖尽依倚，万怪之所屯。
主人一心好，四面无篱藩。
命樵执斤斧，怪木宁遽髠。
主人且倾听，再为谕清浑。
阿胶在末派，罔象游上源。
灵药逡巡尽，黑波朝夕喷。
神龙厌流浊，先伐鼍与鼋。
鼋鼍在龙穴，妖气常郁温。
主人恶淫祀，先去邪与惛。
惛邪中人意，蛊祸蚀精魂。
德胜妖不作，势强威亦尊。
计穷然后赛，后赛复何恩。','',''),('quantangshi-21100','大觜乌','稹','quantangshi','','卷22','阳乌有二类，觜白者名慈。
求食哺慈母，因以此名之。
饮啄颇廉俭，音响亦柔雌。
百巢同一树，栖宿不复疑。
得食先反哺，一身常苦羸。
缘知五常性，飜被众禽欺。
其一觜大者，攫搏性贪痴。
有力强如鹘，有爪利如锥。
音响甚㕭嗗，潜通妖怪词。
受日余光庇，终天无死期。
翺翔富人屋，栖息屋前枝。
巫言此乌至，财产日丰宜。
主人一心惑，诱引不知疲。
转见乌来集，自言家转孳。
白鹤门外养，花鹰架上维。
专听乌喜怒，信受若神龟。
举家同此意，弹射不复施。
往往清池侧，却令鵷鹭随。
羣乌饱粱肉，毛羽色泽滋。
远近恣所往，贪残无不为。
巢禽攫雏卵，廐马啄疮痍。
渗沥脂膏尽，凤皇那得知。
主人一朝病，争向屋檐窥。
呦鷕呼羣鵩，翩翻集怪鸱。
主人偏养者，啸聚最奔驰。
夜半仍惊噪，鸺鶹逐老狸。
主人病心怯，灯火夜深移。
左右虽无语，奄然皆泪垂。
平明天出日，阴魅走参差。
乌来屋檐上，又惑主人儿。
儿即当家业，玩好方爱奇。
占募能言鸟，置者许高赀。
陇树巢鹦鹉，言语好光仪。
美人倾心献，雕笼身自持。
求者临轩坐，置在白玉墀。
先问鸟中苦，便言乌若斯。
众乌齐搏铄，翠羽几离披。
远掷千余里，美人情亦衰。
举家惩此患，事乌逾昔时。
向言池上鹭，啄肉寝其皮。
夜漏天终晓，阴云风定吹。
况尔乌何者，数极不知危。
会结弥天网，尽取一无遗。
常令阿阁上，宛宛宿长离。','',''),('quantangshi-21101','分水岭','稹','quantangshi','','卷22','崔嵬分水岭，高下与云平。
上有分流水，东西随势倾。
朝同一源出，暮隔千里情。
风雨各自异，波澜相背惊。
势高竞奔注，势曲已回萦。
偶值当途石，蹙缩又纵横。
有时遭孔穴，变作呜咽声。
褊浅无所用，奔波奚所营。
团团井中水，不复东西征。
上应美人意，中涵孤月明。
旋风西面起，井深波不生。
坚冰一时合，井深冻不成。
终年汲引绝，不耗复不盈。
五月金石铄，既寒亦既清。
易时不易性，改邑不改名。
定如拱北极，莹若烧玉英。
君门客如水，日夜随势行。
君看守心者，井水为君盟。','',''),('quantangshi-21102','四皓庙','稹','quantangshi','','卷22','巢由昔避世，尧舜不得臣。
伊吕虽急病，汤武乃可君。
四贤胡为者，千载名氛氲。
显晦有遗迹，前后疑不伦。
秦政虐天下，黩武穷生民。
诸侯战必死，壮士眉亦嚬。
张良韩孺子，椎碎属车轮。
遂令英雄意，日夜思报秦。
先生相将去，不复婴世尘。
云卷在孤岫，龙潜为小鳞。
秦王转无道，谏者鼎镬亲。
茅焦脱衣谏，先生无一言。
赵高杀二世，先生如不闻。
刘项取天下，先生游白云。
海内八年战，先生全一身。
汉业日已定，先生名亦振。
不得为济世，宜哉为隐沦。
如何一朝起，屈作储贰宾。
安存孝惠帝，摧顇戚夫人。
舍大以谋细，虬盘而蠖伸。
惠帝竟不嗣，吕氏祸有因。
虽怀安刘志，未若周与陈。
皆落子房术，先生道何屯。
出处贵明白，故吾今有云。','',''),('quantangshi-21103','青云驿','稹','quantangshi','','卷22','岧峣青云岭，下有千仞溪。
裴回不可上，人倦马亦嘶。
愿登青云路，若望丹霞梯。
谓言青云驿，绣户芙蓉闺。
谓言青云骑，玉勒黄金蹄。
谓言青云具，瑚琏杂象犀。
谓言青云吏，的的颜如圭。
怀此青云望，安能复久稽。
攀援信不易，风雨正凄凄。
已怪杜鹃鸟，先来山下啼。
才及青云驿，忽遇蓬蒿妻。
延我开荜户，凿窦宛如圭。
逡巡吏来谒，头白颜色黧。
馈食频叫噪，假器仍乞醯。
向时延我者，共舍藿与藜。
乘我牂牁马，蒙茸大如羝。
悔为青云意，此意良噬脐。
昔游蜀门下，有驿名青泥。
闻名意惨怆，若坠牢与狴。
云泥异所称，人物一以齐。
复闻阊阖上，下视日月低。
银城蘂珠殿，玉版金字题。
大帝直南北，羣仙侍东西。
龙虎俨队仗，雷霆轰鼓鼙。
元君理庭内，左右桃花蹊。
丹霞烂成绮，景云轻若绨。
天池光滟滟，瑶草绿萋萋。
众真千万辈，柔颜尽如荑。
手持凤尾扇，头戴翠羽笄。
云韶互铿戛，霞服相提携。
双双发皓齿，各各扬轻袿。
天祚乐未极，溟波浩无堤。
秽贱灵所恶，安肯问黔黎。
桑田变成海，宇悬烹为韲。
虚皇不愿见，云雾重重翳。
大帝安可梦，阊阖何由跻。
灵物可见者，愿以谕端倪。
虫蛇吐云气，妖氛变虹霓。
获麟书诸册，豢龙醢为臡。
凤皇占梧桐，丛杂百鸟栖。
野鹤啄腥虫，贪饕不如鸡。
山鹿藏窟穴，虎豹吞其麛。
灵物比灵境，冠履宁甚睽。
道胜即为乐，何慙居稗稊。
金张好车马，于陵亲灌畦。
在梁或在火，不变玉与鹈。
上天勿行行，潜穴勿凄凄。
吟此青云谕，达观终不迷。','',''),('quantangshi-21104','阳城驿','稹','quantangshi','','卷22','商有阳城驿，名同阳道州。
阳公没已久，感我泪交流。
昔公孝父母，行与曾闵俦。
既孤善兄弟，兄弟和且柔。
一夕不相见，若怀三岁忧。
遂誓不婚娶，没齿同衾裯。
妹夫死他县，遗骨无人收。
公令季弟往，公与仲弟留。
相别竟不得，三人同远游。
共负他乡骨，归来藏故丘。
栖迟居夏邑，邑人无苟偷。
里中竞长短，来问劣与优。
官刑一朝耻，公短终身羞。
公亦不遗布，人自不盗牛。
问公何能尔，忠信先自修。
发言当道理，不顾党与讐。
声香渐翕习，冠盖若云浮。
少者从公学，老者从公游。
往来相告报，县尹与公侯。
名落公卿口，涌如波荐舟。
天子得闻之，书下再三求。
书中愿一见，不异旱地虬。
何以持为聘，束帛藉琳球。
何以持为御，驷马驾安輈。
公方伯夷操，事殷不事周。
我实唐士庶，食唐之田畴。
我闻天子忆，安敢专自由。
来为谏大夫，朝夕侍冕旒。
希夷敦薄俗，密勿献良筹。
神医不言术，人瘼曾暗瘳。
月请谏官俸，诸弟相对谋。
皆曰亲戚外，酒散目前愁。
公云不有尔，安得此嘉猷。
施余尽酤酒，客来相献酬。
日旰不谋食，春深仍弊裘。
人心良戚戚，我乐独由由。
贞元岁云暮，朝有曲如钩。
风波势奔蹙，日月光绸缪。
齿牙属为猾，禾黍暗生蟊。
岂无司言者，肉食吞其喉。
岂无司搏者，利柄扼其鞲。
鼻复势气塞，不得辩薰莸。
公虽未显谏，惴惴如患瘤。
飞章八九上，皆若珠暗投。
炎炎日将炽，积燎无人抽。
公乃帅其属，决谏同报仇。
延英殿门外，叩合仍叩头。
且曰事不止，臣谏誓不休。
上知不可遏，命以美语酬。
降官司成署，俾之为赘疣。
奸心不快活，击刺砺戈矛。
终为道州去，天道竟悠悠。
遂令不言者，反以言为訧。
喉舌坐成木，鹰鹯化为鸠。
避权如避虎，冠豸如冠猴。
平生附我者，诗人称好逑。
私来一执手，恐若坠诸沟。
送我不出户，决我不回眸。
唯有太学生，各具粮与糇。
咸言公去矣，我亦去荒陬。
公与诸生别，步步驻行驺。
有生不可诀，行行过闽瓯。
为师得如此，得为贤者不。
道州闻公来，鼓舞歌且讴。
昔公居夏邑，狎人如狎鸥。
况自为刺史，岂复援鼓桴。
滋章一时罢，教化天下遒。
炎瘴不得老，英华忽已秋。
有鸟哭杨震，无儿悲邓攸。
唯余门弟子，列树松与楸。
今来过此驿，若吊汨罗洲。
祠曹讳羊祜，此驿何不侔。
我愿避公讳，名为避贤邮。
此名有深意，蔽贤天所尤。
吾闻玄元教，日月冥九幽。
幽阴蔽翳者，永为幽翳囚。','',''),('quantangshi-21105','苦雨','稹','quantangshi','','卷22','江瘴气候恶，庭空田地芜。
烦昏一日内，阴暗三四殊。
巢燕汚牀席，苍蝇点肌肤。
不足生诟怒，但苦寡欢娱。
夜来稍清晏，放体阶前呼。
未饱风月思，已为蚊蚋图。
我受簪组身，我生天地炉。
炎蒸安敢勌，虫豸何时无。
凌晨坐堂庑，努力泥中趋。
官家事不了，尤悔亦可虞。
门外竹桥折，马惊不敢逾。
回头命僮御，向我色踟蹰。
自顾方濩落，安能相诘诛。
隐忍心愤恨，翻为声喣愉。
逡巡崔嵬日，杲曜东南隅。
已复云蔽翳，不使及泥涂。
良农尽蒲苇，厚地积潢汚。
三光不得照，万物何由苏。
安得飞廉车，磔裂云将躯。
又提精阳劒，蛟螭支节屠。
阴沴皆电埽，幽妖亦雷驱。
煌煌启阊阖，轧轧掉干枢。
东西生日月，昼夜如转珠。
百川朝巨海，六龙蹋亨衢。
此意倍寥廓，时来本须臾。
今也泥鸿洞，鼋鼍真得途。','',''),('quantangshi-21106','种竹','稹','quantangshi','','卷22','昔公怜我直，比之秋竹竿。
秋来苦相忆，种竹厅前看。
失地颜色改，伤根枝叶残。
清风犹淅淅，高节空团团。
鸣蝉聒暮景，跳蛙集幽阑。
尘土复昼夜，梢云良独难。
丹丘信云远，安得临仙坛。
瘴江冬草绿，何人惊岁寒。
可怜亭亭干，一一青琅玕。
孤凤竟不至，坐伤时节阑。','',''),('quantangshi-21107','和乐天赠樊着作','稹','quantangshi','','卷22','君为着作诗，志激词且温。
璨然光扬者，皆以义烈闻。
千虑竟一失，冰玉不断痕。
谬予顽不肖，列在数子间。
因君讥史氏，我亦能具陈。
羲黄眇云远，载籍无遗文。
煌煌二帝道，铺设在典坟。
尧心惟舜会，因着为话言。
臯夔益稷禹，粗得无间然。
缅然千载后，后圣曰孔宣。
迥知皇王意，缀书为百篇。
是时游夏辈，不敢措舌端。
信哉作遗训，职在圣与贤。
如何至近古，史氏为闲官。
但令识字者，窃弄刀笔权。
由心书曲直，不使当世观。
贻之千万代，疑言相竝传。
人人异所见，各各私所偏。
以是曰褒贬，不如都无焉。
况乃丈夫志，用舍贵当年。
顾予有微尚，愿以出处论。
出非利吾已，其出贵道全。
全道岂虚设，道全当及人。
全则富与寿，亏则饥与寒。
遂我一身逸，不如万物安。
解悬不泽手，拯溺无折旋。
神哉伊尹心，可以冠古先。
其次有独善，善己不善民。
天地为一物，死生为一源。
合杂分万变，忽若风中尘。
抗哉巢由志，尧舜不可迁。
舍此二者外，安用名为宾。
持谢着书郎，愚不愿有云。','',''),('quantangshi-21108','和乐天感鹤','稹','quantangshi','','卷22','我有所爱鹤，毛羽霜雪妍。
秋霄一滴露，声闻林外天。
自随卫侯去，遂入大夫轩。
云貌久已隔，玉音无复传。
吟君感鹤操，不觉心惕然。
无乃予所爱，误为微物迁。
因兹谕直质，未免柔细牵。
君看孤松树，左右萝茑缠。
既可习为饱，亦可薰为荃。
期君常善救，勿令终弃捐。','',''),('quantangshi-21109','谕宝二首 一','稹','quantangshi','','卷22','沈玉在弱泥，泥弱玉易沈。
扶桑寒日薄，不照万丈心。
安得潜渊虬，拔壑超邓林。
泥封泰山址，水散旱天霖。
洗此泥下玉，照耀台殿深。
刻为传国宝，神器人不侵。','',''),('quantangshi-21110','谕宝二首 二','稹','quantangshi','','卷22','冰置白玉壶，始见清皎洁。
珠穿殷红缕，始见明洞彻。
镆铘无人淬，两刃幽壤铁。
秦镜无人拭，一片埋雾月。
骥局环堵中，骨附筋入节。
虬蟠尺泽内，鱼贯蛙同穴。
艅艎无巨海，浮浮矜瀎潏。
栋梁无广厦，颠倒卧霜雪。
大鹏无长空，举翮受羁絏。
豫樟无厚地，危柢真卼臲。
圭璧无卞和，甘与顽石列。
舜禹无陶尧，名随腐草灭。
神功伏神物，神物神乃别。
神人不世出，所以神功绝。
神物岂徒然，用之乃施设。
禹功九州理，舜德天下悦。
璧充传国玺，圭用祈太折。
千寻豫樟干，九万大鹏歇。
栋梁庇生民，艅艎济来哲。
虬腾旱天雨，骥骋流电掣。
镜悬奸胆露，劒拂妖蛇裂。
珠玉照乘光，冰莹环坐热。
此物比在泥，斯言为谁发。
于今尽凡耳，不为君不说。','',''),('quantangshi-21111','说劒','稹','quantangshi','','卷22','吾友有宝劒，密之如密友。
我实胶漆交，中堂共杯酒。
酒酣肝胆露，恨不眼前剖。
高唱荆卿歌，乱击相如缶。
更击复更唱，更酌亦更寿。
白虹坐上飞，青蛇匣中吼。
我闻音响异，疑是干将偶。
为君再拜言，神物可见不。
君言我所重，我自为君取。
迎箧已焚香，近鞘先泽手。
徐抽寸寸刃，渐屈弯弯肘。
杀杀霜在锋，团团月临纽。
逡巡潜虬跃，郁律惊左右。
霆电满室光，蛟龙绕身走。
我为捧之泣，此劒别来久。
铸时近山破，藏在松桂朽。
幽匣狱底埋，神人水心守。
本是稽泥淬，果非雷焕有。
我欲评劒功，愿君良听受。
劒可剸犀兕，劒可切琼玖。
劒决天外云，劒冲日中斗。
劒隳妖蛇腹，劒拂佞臣首。
太古初断鳌，武王亲击纣。
燕丹卷地图，陈平绾花绶。
曾被桂树枝，寒光射林薮。
曾经铸农器，利用翦稂莠。
神物终变化，复为龙牝牡。
晋末武库烧，脱然排户牖。
为欲埽羣胡，散作弥天帚。
自兹失所往，豪英共为诟。
今复谁人铸，挺然千载后。
既非古风胡，无乃近鵶九。
自我与君游，平生益自负。
况擎宝劒出，重以雄心扣。
此劒何太奇，此心何太厚。
劝君慎所用，所用无或苟。
潜将辟魑魅，勿但防妾妇。
留斩泓下蛟，莫试街中狗。
君今困泥滓，我亦坌尘垢。
俗耳惊大言，逢人少开口。','',''),('quantangshi-21112','书异','稹','quantangshi','','卷22','孟冬初寒月，渚泽蒲尚青。
飘萧北风起，皓雪纷满庭。
行过冬至后，冻闭万物零。
奔浑驰暴雨，骤鼓轰雷霆。
传云不终日，通宵曾莫停。
瘴云愁拂地，急溜疑注瓶。
汹涌潢潦浊，喷薄鲸鲵腥。
跳趫井蛙喜，突兀水怪形。
飞蚋奔不死，修蛇蛰再醒。
应龙非时出，无乃岁不宁。
吾闻阴阳户，启闭各有扃。
后时无肃杀，废职乃玄冥。
座配五天帝，荐用百品珍。
权为祝融夺，神其焉得灵。
春秋雷电异，则必书诸经。
仲冬雷雨苦，愿省蒙蔽刑。','',''),('quantangshi-21113','和乐天折劒头','稹','quantangshi','','卷22','闻君得折劒，一片雄心起。
讵意铁蛟龙，潜在延津水。
风云会一合，呼吸期万里。
雷震山岳碎，电斩鲸鲵死。
莫但宝劒头，劒头非此比。','',''),('quantangshi-21114','松鹤','稹','quantangshi','','卷22','渚宫本坳下，佛庙有台阁。
台下三四松，低昂势前却。
是时晴景丽，松梢残雪薄。
日色相玲珑，纤云暎罗幕。
逡巡九霄外，似振风中铎。
渐见尺帛光，孤飞唳空鹤。
裴回耀霜雪，顾慕下寥廓。
蹋动樛盘枝，龙蛇互跳跃。
俯瞰九江水，旁瞻万里壑。
无心眄乌鸢，有字悲城郭。
清角已沈绝，虞韶亦冥寞。
骞翻勿重留，幸及钧天作。','',''),('quantangshi-21115','竞渡','稹','quantangshi','','卷22','吾观竞舟子，因测大竞源。
天地昔将竞，蓬勃昼夜昏。
龙蛇相嗔薄，海岱俱崩奔。
羣动皆搅挠，化作流浑浑。
数极鬬心息，太和蒸混元。
一气忽为二，矗然画干坤。
日月复照耀，春秋递寒温。
八荒坦以旷，万物罗以繁。
圣人中间立，理世了不烦。
延绵复几岁，逮及羲与轩。
炎皇炽如炭，蚩尤扇其燔。
有熊竞心起，驱兽出林樊。
一战波委焰，再战火燎原。
战讫天下定，号之为轩辕。
自是岂无竞，琐细不复言。
其次有龙竞，竞渡龙之门。
龙门浚如泻，淙射不可援。
赤鳞化时至，唐突鳍鬣掀。
乘风瞥然去，万里黄河飜。
接瞬电烻出，微吟霹雳喧。
傍瞻旷宇宙，俯瞰卑昆仑。
庶类咸在下，九霄行易扪。
倏辞蛙黾穴，遽排天帝阍。
回悲曝鳃者，未免鲸鲵吞。
帝命泽诸夏，不弃虫与昆。
随时布膏露，称物施厚恩。
草木霑我润，豚鱼望我蕃。
向来同竞辈，岂料由我存。
壮哉龙竞渡，一竞身独尊。
舍此皆蚁鬬，竞舟何足论。','',''),('quantangshi-21116','寺院新竹','稹','quantangshi','','卷22','宝地琉璃坼，紫苞琅玕踊。
亭亭巧于削，一一大如拱。
冰碧林外寒，峯峦眼前耸。
槎枒矛戟合，屹仡龙蛇动。
烟泛翠光流，岁余霜彩重。
风朝竽籁过，雨夜鬼神恐。
佳色有鲜妍，修茎无拥肿。
节高迷玉镞，箨缀疑花捧。
讵必太山根，本自仙坛种。
谁令植幽壤，复此依闲冗。
居然霄汉姿，坐受藩篱壅。
噪集勌鸱乌，炎昏繁蠛蠓。
未遭伶伦听，非安子犹宠。
威凤来有时，虚心岂无奉。','',''),('quantangshi-21117','酬别致用','稹','quantangshi','','卷22','风行自委顺，云合非有期。
神哉心相见，无眹安得离。
我有恳愤志，三十无人知。
修身不言命，谋道不择时。
达则济亿兆，穷亦济毫氂。
济人无大小，誓不空济私。
研几未淳熟，与世忽参差。
意气一为累，猜仍良已随。
昨来窜荆蛮，分与平生隳。
那言返为遇，获见心所奇。
一见肺肝尽，坦然无滞疑。
感念交契定，泪流如断縻。
此交定生死，非为论盛衰。
此契宗会极，非为同路岐。
君今虎在柙，我亦鹰就羁。
驯养保性命，安能奋殊姿。
玉色深不变，井水挠不移。
相看各年少，未敢深自悲。','',''),('quantangshi-21118','竹部','稹','quantangshi','','卷22','竹部竹山近，岁伐竹山竹。
伐竹岁亦深，深林隔深谷。
朝朝冰雪行，夜夜豺狼宿。
科首霜断蓬，枯形烧余木。
一束十余茎，千钱百余束。
得钱盈千百，得粟盈斗斛。
归来不买食，父子分半菽。
持此欲何为，官家岁输促。
我来荆门掾，寓食公堂肉。
岂惟遍妻孥，亦以及僮仆。
分尔有限资，饱我无端腹。
愧尔不复言，尔生何太蹙。','',''),('quantangshi-21119','赛神','稹','quantangshi','','卷22','楚俗不事事，巫风事妖神。
事妖结妖社，不问疎与亲。
年年十月暮，珠稻欲垂新。
家家不歛获，赛妖无富贫。
杀牛贳官酒，椎鼓集顽民。
喧阗里闾隘，凶酗日夜频。
岁暮雪霜至，稻珠随陇湮。
吏来官税迫，求质倍称缗。
贫者日消铄，富亦无仓囷。
不谓事神苦，自言诚不真。
岳阳贤刺史，念此为俗屯。
未可一朝去，俾之为等伦。
粗许存习俗，不得呼党人。
但许一日泽，不得月与旬。
吾闻国侨理，三年名乃振。
巫风燎原久，未必怜徙薪。
我来歌此事，非独歌政仁。
此事四邻有，亦欲闻四邻。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21120','竞舟','稹','quantangshi','','卷22','楚俗不爱力，费力为竞舟。
买舟俟一竞，竞歛贫者赇。
年年四五月，蠒实麦小秋。
积水堰堤坏，拔秧蒲稗稠。
此时集丁壮，习竞南亩头。
朝饮邨社酒，暮椎邻舍牛。
祭船如祭祖，习竞如习讐。
连延数十日，作业不复忧。
君侯馔良吉，会客陈膳羞。
画鷁四来合，大竞长江流。
建标明取舍，胜负死生求。
一时讙呼罢，三月农事休。
岳阳贤刺史，念此为俗疣。
习俗难尽去，聊用去其尤。
百船不留一，一竞不滞留。
自为里中戏，我亦不寓游。
吾闻管仲教，沐树惩堕游。
节此淫竞俗，得为良政不。
我来歌此事，非独歌此州。
此事数州有，亦欲闻数州。','',''),('quantangshi-21121','茅舍','稹','quantangshi','','卷22','楚俗不理居，居人尽茅舍。
茅苫竹梁栋，茅疎竹仍罅。
边缘堤岸斜，诘屈檐楹亚。
篱落不蔽肩，街衢不容驾。
南风五月盛，时雨不来下。
竹蠹茅亦干，迎风自焚灺。
防虞集邻里，巡警劳昼夜。
遗烬一星然，连延祸相嫁。
号呼邻谷帛，奔走伐桑柘。
旧架已新焚，新茅又初架。
前日洪州牧，念此常嗟讶。
牧民未及久，郡邑纷如化。
峻邸俨相望，飞甍远相跨。
旗亭红粉泥，佛庙青鸳瓦。
斯事才未终，斯人久云谢。
有客自洪来，洪民至今藉。
惜其心太亟，作役无容暇。
台观亦已多，工徒稍冤咤。
我欲他郡长，三时务耕稼。
农收次邑居，先室后台榭。
启闭既及期，公私亦相借。
度材无强略，庀役有定价。
不使及僭差，粗得御寒夏。
火至殊陈郑，人安极嵩华。
谁能继此名，名流袭兰麝。
五袴有前闻，斯言我非诈。','',''),('quantangshi-21122','后湖','稹','quantangshi','','卷22','荆有泥泞水，在荆之邑郛。
郛前水在后，谓之为后湖。
环湖十余里，岁积潢与汚。
臭腐鱼鳌死，不植菰与蒲。
郑公理三载，其理用喣愉。
岁稔民四至，隘廛亦隘衢。
公乃署其地，为民先矢谟。
人人傥自为，我亦不庀徒。
下里得闻之，各各相俞俞。
提携翁及孙，捧戴妇与姑。
壮者负砾石，老亦捽茅蒭。
斤磨片片雪，椎隐连连珠。
朝餐布庭落，夜宿完户枢。
邻里近相告，亲戚远相呼。
鬻者自为鬻，酤者自为酤。
鸡犬丰中市，人民岐下都。
百年废滞所，一旦奥浩区。
我实司水土，得为官事无。
人言贱事贵，贵直不贵谀。
此实公所小，安用歌袴襦。
答云潭及广，以至鄂与吴。
万里尽泽国，居人皆垫濡。
富者不容盖，贫者不庇躯。
得不歌此事，以我为楷模。','',''),('quantangshi-21123','八骏图诗','稹','quantangshi','','卷22','穆满志空阔，将行九州野。
神驭四来归，天与八骏马。
龙种无凡性，龙行无暂舍。
朝辞扶桑底，暮宿昆仑下。
鼻息吼春雷，蹄声裂寒瓦。
尾掉沧波黑，汗染白云赭。
华輈本修密，翠盖尚妍冶。
御者腕不移，乘者寐不假。
车无轮扁斵，辔无王良把。
虽有万骏来，谁是敢骑者。','',''),('quantangshi-21124','画松','稹','quantangshi','','卷22','张璪画古松，往往得神骨。
翠帚扫春风，枯龙戛寒月。
流传画师辈，奇态尽埋没。
纤枝无萧洒，顽干空突兀。
乃悟埃尘心，难状烟霄质。
我去淅阳山，深山看真物。','',''),('quantangshi-21125','遣兴十首 一','稹','quantangshi','','卷22','始见棃花房，坐对棃花白。
行看棃叶青，已复棃叶赤。
严霜九月半，危蔕几时客。
况有高高原，秋风四来迫。','',''),('quantangshi-21126','遣兴十首 二','稹','quantangshi','','卷22','莫厌夏日长，莫愁冬日短。
欲识短复长，君看寒又暖。
城中百万家，冤哀杂丝管。
草没奉诚园，轩车昔曾满。','',''),('quantangshi-21127','遣兴十首 三','稹','quantangshi','','卷22','孤竹迸荒园，误与蓬麻列。
久拥萧萧风，空长高高节。
严霜荡羣秽，蓬断麻亦折。
独立转亭亭，心期凤皇别。','',''),('quantangshi-21128','遣兴十首 四','稹','quantangshi','','卷22','艳艳翦红英，团团削翠茎。
托根在褊浅，因依泥滓生。
中有合欢蘂，池枯难遽呈。
凉宵露华重，低徊当月明。','',''),('quantangshi-21129','遣兴十首 五','稹','quantangshi','','卷22','晚荷犹展卷，早蝉遽萧嘹。
露叶行已重，况乃江风摇。
炎夏火再伏，清商暗回飙。
寄言抱志士，日月东西跳。','',''),('quantangshi-21130','遣兴十首 六','稹','quantangshi','','卷22','买马买锯牙，买犊买破车。
养禽当养鹘，种树先种花。
人生负俊健，天意与光华。
莫学蚯蚓辈，食泥近土涯。','',''),('quantangshi-21131','遣兴十首 七','稹','quantangshi','','卷22','爱直莫爱夸，爱疾莫爱斜。
爱谟莫爱诈，爱施莫爱奢。
择才不求备，任物不过涯。
用人如用己，理国如理家。','',''),('quantangshi-21132','遣兴十首 八','稹','quantangshi','','卷22','㸌㸌刀刃光，弯弯弓面张。
入水斩犀兕，上山椎虎狼。
里中无老少，唤作癫儿郎。
一日风云会，横行归故乡。','',''),('quantangshi-21133','遣兴十首 九','稹','quantangshi','','卷22','团团规内星，未必明如月。
托迹近北辰，周天无沦没。
老人在南极，地远光不发。
见则寿圣明，愿照高高阙。','',''),('quantangshi-21134','遣兴十首 十','稹','quantangshi','','卷22','河清谅嘉瑞，吾帝真圣人。
时哉不我梦，此时为废民。
光阴本跳踯，功业劳苦辛。
一到江陵郡，三年成去尘。','',''),('quantangshi-21135','野节鞭','稹','quantangshi','','卷22','神鞭鞭宇宙，玉鞭鞭骐骥。
紧綛野节鞭，本用鞭贔屭。
使君鞭甚长，使君马亦利。
司马竝马行，司马马顦顇。
短鞭不可施，疾步无由致。
使君驻马言，愿以长鞭遗。
此遗不寻常，此鞭不容易。
金坚无缴绕，玉滑无尘腻。
青蛇坼生石，不刺山阿地。
乌龟旋眼斑，不染江头泪。
长看雷雨痕，未忍驽骀试。
持用换所持，无令等闲弃。
答云君何奇，赠我君所贵。
我用亦不凡，终身保明义。
誓以鞭奸顽，不以鞭蹇踬。
指撝狡兔踪，决挞怪龙睡。
惜令寸寸折，节节不虚坠。
因作换鞭诗，诗成谓同志。
而我得闻之，笑君年少意。
安用换长鞭，鞭长亦奚为。
我有鞭尺余，泥抛风雨渍。
不拟闲赠行，唯将烂夸醉。
春来信马头，款缓花前辔。
愿我迟似挛，饶君疾如翅。','',''),('quantangshi-21136','旱灾自咎贻七县宰','稹','quantangshi','','卷22','吾闻上帝心，降命明且仁。
臣稹苟有罪，胡不灾我身。
胡为旱一州，祸此千万人。
一旱犹可忍，其旱亦已频。
腊雪不满地，膏雨不降春。
恻恻诏书下，半减麦与缗。
半租岂不薄，尚竭力与筋。
竭力不敢惮，惭戴天子恩。
累累妇拜姑，呐呐翁语孙。
禾黍日夜长，足得盈我囷。
还填折粟税，酬偿贳麦邻。
苟无公私责，饮水不为贫。
欢言未盈口，旱气已再振。
六月天不雨，秋孟亦既旬。
区区昧陋积，祷祝非不勤。
日驰衰白颜，再拜泥甲鳞。
归来重思忖，愿告诸邑君。
以彼天道远，岂如人事亲。
团团囹圄中，无乃冤不申。
扰扰食廪内，无乃奸有因。
轧轧输送车，无乃使不伦。
遥遥负担卒，无乃役不均。
今年无大麦，计与珠玉滨。
邨胥与里吏，无乃求取繁。
符不歛钱急，值官因酒嗔。
诛求与挞罚，无乃不逡巡。
生小下里住，不曾州县门。
诉词千万恨，无乃不得闻。
强豪富酒肉，穷独无蒭薪。
俱由案牍吏，无乃移祸屯。
官分市井户，迭配水陆珍。
未蒙所偿直，无乃不敢言。
有一于此事，安可尤苍旻。
借使漏刑宪，得不虞鬼神。
自顾顽滞牧，坐贻灾沴臻。
上羞朝廷寄，不愧闾里民。
岂无神明宰，为我同苦辛。
共布慈惠语，慰此衢客尘。','',''),('quantangshi-21137','虫豸诗 一','稹','quantangshi','','卷22','巴蛇千种毒，其最鼻褰蛇。
掉舌翻红焰，盘身蹙白花。
喷人竖毛发，饮浪沸泥沙。
欲学叔敖瘗，其如多似麻。','',''),('quantangshi-21138','虫豸诗 二','稹','quantangshi','','卷22','越岭南滨海，武都西隐戎。
雄黄假名石，鷣鸟远难笼。
讵有隳肠计，应无破脑功。
巴山昼昏黑，妖雾毒蒙蒙。','',''),('quantangshi-21139','虫豸诗 三','稹','quantangshi','','卷22','汉帝斩蛇劒，晋时烧上天。
自兹繁巨蟒，往往寿千年。
白昼遮长道，青溪蒸毒烟。
战龙苍海外，平地血浮船。','',''),('quantangshi-21140','虫豸诗 一','稹','quantangshi','','卷22','巴蛇蟠窟穴，穴下有巢蜂。
近树禽垂翅，依原兽绝踪。
微遭断手足，厚毒破心胸。
昔甚招魂句，那知眼自逢。','',''),('quantangshi-21141','虫豸诗 二','稹','quantangshi','','卷22','梨笑清都月，蜂游紫殿春。
构脾分部伍，嚼蕊奉君亲。
翅羽颇同类，心神固异伦。
安知人世里，下有噬人人。','',''),('quantangshi-21142','虫豸诗 三','稹','quantangshi','','卷22','兰蕙本同畹，蜂蛇亦杂居。
害心俱毒螫，妖焰两吹嘘。
雷蛰吞噬止，枯焚巢穴除。
可怜相济恶，勿谓祸无余。','',''),('quantangshi-21143','虫豸诗 一','稹','quantangshi','','卷22','蜘蛛天下足，巴蜀就中多。
缝隙容长踦，虚空织横罗。
萦缠伤竹柏，吞噬及虫蛾。
为送佳人喜，珠栊无奈何。','',''),('quantangshi-21144','虫豸诗 二','稹','quantangshi','','卷22','网密将求食，丝斜误着人。
因依方纪绪，挂罥遂容身。
截道蝉冠碍，漫天玉露频。
儿童怜小巧，渐欲及车轮。','',''),('quantangshi-21145','虫豸诗 三','稹','quantangshi','','卷22','稚子怜圆网，佳人祝喜丝。
那知缘暗隙，忽被啮柔肌。
毒腠攻犹易，焚心疗恐迟。
看看长祆绪，和扁欲涟洏。','',''),('quantangshi-21146','虫豸诗 一','稹','quantangshi','','卷22','蚁子生无处，偏因湿处生。
阴霪烦扰攘，拾粒苦譻𧭈。
牀上主人病，耳中虚藏鸣。
雷霆翻不省，闻汝作牛声。','',''),('quantangshi-21147','虫豸诗 二','稹','quantangshi','','卷22','时术功虽细，年深祸亦成。
攻穿漏江海，噆食困蛟鲸。
敢惮榱𣡵蠹，深藏柱石倾。
寄言持重者，微物莫全轻。','',''),('quantangshi-21148','虫豸诗 三','稹','quantangshi','','卷22','攘攘终朝见，悠悠卒岁疑。
讵能分牝牡，焉得有蝝蚳。
徙市竟何意，生涯都几时。
巢由或逢我，应似我相期。','',''),('quantangshi-21149','虫豸诗 一','稹','quantangshi','','卷22','蟆子微于蚋，朝繁夜则无。
毫端生羽翼，针喙噆肌肤。
暗毒应难免，羸形日渐枯。
将身远相就，不敢恨非辜。','',''),('quantangshi-21150','虫豸诗 二','稹','quantangshi','','卷22','晦景权藏毒，明时敢噬人。
不劳生诟怒，祗足助酸辛。
隼眦看无物，蛇躯庇有鳞。
天方刍狗我，甘与尔相亲。','',''),('quantangshi-21151','虫豸诗 三','稹','quantangshi','','卷22','有口深堪异，趋时讵可量。
谁令通鼻息，何故辨馨香。
沈水来沧海，崇兰泛露光。
那能枉焚爇，尔众我微茫。','',''),('quantangshi-21152','虫豸诗 一','稹','quantangshi','','卷22','可叹浮尘子，纤埃喻此微。
宁谕隔纱幌，并解透绵衣。
有毒能成痏，无声不见飞。
病来双眼暗，何计辨雰霏。','',''),('quantangshi-21153','虫豸诗 二','稹','quantangshi','','卷22','乍可巢蚊睫，胡为附蟒鳞。
已微于蠢蠢，仍害及仁人。
动植皆分命，毫芒亦是身。
哀哉此幽物，生死敌浮尘。','',''),('quantangshi-21154','虫豸诗 三','稹','quantangshi','','卷22','但觉皮肤憯，安知琐细来。
因风吹薄雾，向日误轻埃。
暗啮堪销骨，潜飞有祸胎。
然无防备处，留待雪霜摧。','',''),('quantangshi-21155','虫豸诗 一','稹','quantangshi','','卷22','阴深山有瘴，湿垫草多蝱。
众噬锥刀毒，羣飞风雨声。
汗粘疮痏痛，日曝苦辛行。
饱尔蛆残腹，安知天地情。','',''),('quantangshi-21156','虫豸诗 二','稹','quantangshi','','卷22','千山溪沸石，六月火烧云。
自顾生无类，那堪毒有羣。
搏牛皮若截，噬马血成文。
蹄角尚如此，肌肤安可云。','',''),('quantangshi-21157','虫豸诗 三','稹','quantangshi','','卷22','辛螫终非久，炎凉本递兴。
秋风自天落，夏蘖与霜澄。
一镜开潭面，千锋露石棱。
气平虫豸死，云路好攀登。','',''),('quantangshi-21158','楚歌十首 一','稹','quantangshi','','卷22','楚人千万户，生死系时君。
当璧便为嗣，贤愚安可分。
干戈长浩浩，篡乱亦纷纷。
纵有明在下，区区何足云。','',''),('quantangshi-21159','楚歌十首 二','稹','quantangshi','','卷22','陶虞事已远，尼父独将明。
潜穴龙无位，幽林兰自生。
楚王谋授邑，此意复中倾。
未别子西语，纵来何所成。','',''),('quantangshi-21160','楚歌十首 三','稹','quantangshi','','卷22','平王渐昏惑，无极转承恩。
子建犹相贰，伍奢安得存。
生居宫雉閟，死葬寝园尊。
岂料奔吴士，鞭尸郢市门。','',''),('quantangshi-21161','楚歌十首 四','稹','quantangshi','','卷22','惧盈因邓曼，罢猎为樊姬。
盛德留金石，清风鉴薄帷。
襄王忽妖梦，宋玉复淫辞。
万事捐宫馆，空山云雨期。','',''),('quantangshi-21162','楚歌十首 五','稹','quantangshi','','卷22','宜僚南市住，未省食人恩。
临难忽相感，解纷宁用言。
何如晋夷甫，坐占紫微垣。
看着五胡乱，清谈空自尊。','',''),('quantangshi-21163','楚歌十首 六','稹','quantangshi','','卷22','谁恃王深宠，谁为楚上卿。
包胥心独许，连夜哭秦兵。
千乘徒虚尔，一夫安可轻。
殷勤聘名士，莫但倚方城。','',''),('quantangshi-21164','楚歌十首 七','稹','quantangshi','','卷22','梁业雄图尽，遗孙世运消。
宣明徒有号，江汉不相朝。
碑碣高临路，松枝半作樵。
唯余开圣寺，犹学武皇妖。','',''),('quantangshi-21165','楚歌十首 八','稹','quantangshi','','卷22','江陵南北道，长有远人来。
死别登舟去，生心上马回。
荣枯诚异日，今古尽同灰。','',''),('quantangshi-21166','楚歌十首 九','稹','quantangshi','','卷22','三峡连天水，奔波万里来。
风涛各自急，前后苦相推。
倒入黄牛漩，惊冲滟滪堆。
古今流不尽，流去不曾回。','',''),('quantangshi-21167','楚歌十首 十','稹','quantangshi','','卷22','八荒同日月，万古共山川。
生死既由命，兴衰还付天。
栖栖王粲赋，愤愤屈平篇。
各自埋幽恨，江流终宛然。','',''),('quantangshi-21168','襄阳道','稹','quantangshi','','卷22','羊公名渐远，唯有岘山碑。
近日称难继，曹王任马彝。
椒兰俱下世，城郭到今时。
汉水清如玉，流来本为谁。','',''),('quantangshi-21169','赋得鱼登龙门','稹','quantangshi','','卷22','鱼贯终何益，龙门在苦登。
有成当作雨，无用耻为鹏。
激浪诚难溯，雄心亦自凭。
风云潜会合，鬐鬣忽腾凌。
泥滓辞河浊，烟霄见海澄。
回瞻顺流辈，谁敢望同升。','',''),('quantangshi-21170','贞元历','稹','quantangshi','','卷22','象魏才颁历，龙镳已御天。
犹看后元历，新署永贞年。
半岁光阴在，三朝礼数迁。
无因书简册，空得咏诗篇。','',''),('quantangshi-21171','塞马','稹','quantangshi','','卷22','塞马倦江渚，今朝神彩生。
晓风寒猎猎，乍得草头行。
夷狄寝烽候，关河无战声。
何由当阵面，从尔四蹄轻。','',''),('quantangshi-21172','鹿角镇','稹','quantangshi','','卷22','去年湖水满，此地覆行舟。
万怪吹高浪，千人死乱流。
谁能问帝子，何事宠阳侯。
渐恐鲸鲵大，波涛及九州。','',''),('quantangshi-21173','感事三首 一','稹','quantangshi','','卷22','为国谋羊舌，从来不为身。
此心长自保，终不学张陈。','',''),('quantangshi-21174','感事三首 二','稹','quantangshi','','卷22','自笑心何劣，区区辨所冤。
伯仁虽到死，终不向人言。','',''),('quantangshi-21175','感事三首 三','稹','quantangshi','','卷22','富贵年皆长，风尘旧转稀。
白头方见绝，遥为一霑衣。','',''),('quantangshi-21176','题翰林东合前小松','稹','quantangshi','','卷22','檐碍修鳞亚，霜侵簇翠黄。
唯余入琴韵，终待舜弦张。','',''),('quantangshi-21177','清都夜境','稹','quantangshi','','卷22','夜久连观静，斜月何晶荧。
寥天如碧玉，历历缀华星。
楼榭自阴暎，云牖深冥冥。
纤埃悄不起，玉砌寒光清。
栖鹤露微影，枯松多怪形。
南厢俨容卫，音响如可聆。
启圣发空洞，朝真趋广庭。
闲开蘂珠殿，暗阅金字经。
屏气动方息，凝神心自灵。
悠悠车马上，浩思安得宁。','',''),('quantangshi-21178','春晚寄杨十二兼呈赵八','稹','quantangshi','','卷22','蒙蒙竹树深，帘牖多清阴。
避日坐林影，余花委芳襟。
倾尊就残酌，舒卷续微吟。
空际扬高蝶，风中聆素琴。
广庭备幽趣，复对商山岑。
独此爱时景，旷怀云外心。
迁鸎恋嘉木，求友多好音。
自无琅玕实，安得莲花簪。
寄之二君子，希见双南金。','',''),('quantangshi-21179','与杨十二李三早入永寿寺看牡丹','稹','quantangshi','','卷22','晓入白莲宫，琉璃花界净。
开敷多喻草，凌乱被幽径。
压砌锦地铺，当霞日轮暎。
蝶舞香暂飘，蠭牵蕊难正。
笼处彩云合，露湛红珠莹。
结叶影自交，摇风光不定。
繁华有时节，安得保全盛。
色见尽浮荣，希君了真性。','',''),('quantangshi-21180','春余遣兴','稹','quantangshi','','卷22','春去日渐迟，庭空草偏长。
余英间初实，雪絮萦蛛网。
好鸟多息阴，新篁已成响。
帘开斜照入，树褭游丝上。
绝迹念物闲，良时契心赏。
单衣颇新绰，虚室复清敞。
置酒奉亲宾，树萱自怡养。
笑倚连枝花，恭扶瑞藤杖。
步屧恣优游，望山多气象。
云叶遥卷舒，风裾动萧爽。
簪缨固烦杂，江海徒浩荡。
野马笼赤霄，无由负羁鞅。','',''),('quantangshi-21181','忆云之','稹','quantangshi','','卷22','为鱼实爱泉，食辛宁避蓼。
人生既相合，不复论窕窕。
沧海良有穷，白日非长皎。
何事一人心，各在四方表。
泛若逐水萍，居为附松茑。
流浪随所之，萦纡牵所绕。
百龄颇局促，况复迷寿夭。
芟发君已衰，冠岁予非小。
娱乐不及时，暮年壮心少。
感此幽念绵，遂为长悄悄。
中庭草木春，历乱递相扰。
奇树花冥冥，竹竿凤褭褭。
幽芳被兰径，安得寄天杪。
万里潇湘魂，夜夜南枝鸟。','',''),('quantangshi-21182','别李三','稹','quantangshi','','卷22','阶蓂附瑶砌，藂兰偶芳藿。
高位良有依，幽姿亦相托。
鲍叔知我贫，烹葵不为薄。
半面契始终，千金比然诺。
人生系时命，安得无苦乐。
但感游子颜，又值余英落。
苍苍秦树云，去去缑山鹤。
日暮分手归，杨花满城郭。','',''),('quantangshi-21183','秋夕远怀','稹','quantangshi','','卷22','旦夕天气爽，风飘叶渐轻。
星繁河汉白，露逼衾枕清。
丹鸟月中灭，莎鸡牀下鸣。
悠悠此怀抱，况复多远情。','',''),('quantangshi-21184','东西道','稹','quantangshi','','卷22','天皇开四极，便有东西道。
万古阅行人，行人几人老。
顾我倦行者，息阴何不早？
少壮尘事多，那言壮年好。','',''),('quantangshi-21185','分流水','稹','quantangshi','','卷22','古时愁别泪，滴作分流水。
日夜东西流，分流几千里。
通塞两不见，波澜各自起。
与君相背飞，去去心如此。','',''),('quantangshi-21186','西还','稹','quantangshi','','卷22','悠悠洛阳梦，郁郁灞陵树。
落日正西归，逢君又东去。','',''),('quantangshi-21187','含风夕','稹','quantangshi','','卷22','炎昏勌烦久，逮此含风夕。
夏服稍轻清，秋堂已岑寂。
载欣凉宇旷，复念佳辰掷。
络纬惊岁功，顾我何成绩。
青荧微月钩，幽晖洞阴魄。
水镜涵玉轮，若见渊泉璧。
参差帘牖重，次第笼虚白。
树影满空牀，萤光缀深壁。
怅望牵牛星，复为经年隔。
露网褭风珠，轻河泛遥碧。
讵无深秋夜，感此乍流易。
亦有迟暮年，壮年良自惜。
循环切中肠，感念追往昔。
接瞬无停阴，何言问陈积。
馨香推蕙兰，坚贞谕松柏。
生物固有涯，安能比金石。
况兹百龄内，扰扰纷众役。
日月东西驰，飞车无留迹。
来者良未穷，去矣定奚适。
委顺在物为，营营复何益。','',''),('quantangshi-21188','秋堂夕','稹','quantangshi','','卷22','炎凉正回互，金火郁相乘。
云雷时交构，川泽方蒸腾。
清风一朝胜，白露忽已凝。
草木凡气尽，始见天地澄。
况此秋堂夕，幽怀旷无朋。
萧条帘外雨，倏闪案前灯。
书卷满牀席，蟏蛸悬复升。
啼儿屡哑咽，勌僮时寝兴。
泛觉昏夜目，咏谣畅烦膺。
况吟获麟章，欲罢久不能。
尧舜事已远，丘道安可胜。
蜉蝣不信鹤，蜩鷃肯窥鹏。
当年且不偶，没世何必称。
胡为揭闻见，褒贬贻爱憎。
焉用汩其泥，岂在清如冰。
非白又非黑，谁能点青蝇。
处世苟无闷，佯狂道非弘。
无言被人觉，予亦笑孙登。','',''),('quantangshi-21189','酬乐天','稹','quantangshi','','卷22','放鹤在深水，置鱼在高枝。
升沈或异势，同谓非所宜。
君为邑中吏，皎皎鸾凤姿。
顾我何为者，翻侍白玉墀。
昔作芸香侣，三载不暂离。
逮兹忽相失，旦夕梦魂思。
崔嵬骊山顶，宫树遥参差。
祗得两相望，不得长相随。
多君岁寒意，裁作秋兴诗。
上言风尘苦，下言时节移。
官家事拘束，安得携手期。
愿为云与雨，会合天之垂。','',''),('quantangshi-21190','杨子华画三首 一','稹','quantangshi','','卷22','杨画远于展，何言今在兹。
依然古妆服，但感时节移。
念君一朝意，遗我千载思。
子亦几时客，安能长苦悲。','',''),('quantangshi-21191','杨子华画三首 二','稹','quantangshi','','卷22','皓腕卷红袖，锦韝臂苍鹗。
故人断弦心，稚齿从禽乐。
当年惜贵游，遗形寄丹雘。
骨象或依稀，铅华已寥落。
似对古人民，无复昔城郭。
子亦观病身，色空俱寂寞。','',''),('quantangshi-21192','杨子华画三首 三','稹','quantangshi','','卷22','颠倒世人心，纷纷乏公是。
真赏画不成，画赏真相似。
丹青各所尚，工拙何足恃。
求此妄中精，嗟哉子华子。','',''),('quantangshi-21193','西州院','稹','quantangshi','','卷22','自入西州院，唯见东川城。
今夜城头月，非暗又非明。
文案牀席满，卷舒赃罪名。
惨凄且烦勌，弃之阶下行。
怅望天廻转，动摇万里情。
参辰次第出，牛女颠倒倾。
况此风中柳，枝条千万茎。
到来篱下笋，亦已长短生。
感怆正多绪，鵶鵶相唤惊。
墙上杜鹃鸟，又作思归鸣。
以彼撩乱思，吟为幽怨声。
吟罢终不寝，冬冬复铛铛。','',''),('quantangshi-21194','台中鞫狱忆开元观旧事呈损之兼赠周兄四十韵','稹','quantangshi','','卷22','忆在开元馆，食柏练玉颜。
疎慵日高卧，自谓轻人寰。
李生隔墙住，隔墙如隔山。
怪我久不识，先来问骄顽。
十过乃一往，遂成相往还。
以我文章卷，文章甚斒斓。
因言辛庾辈，亦愿放羸孱。
既廻数子顾，展转相连攀。
驱令选科目，若在闠与闤。
学随尘土坠，漫数公卿关。
唯恐坏情性，安能惧谤讪。
还招辛庾李，静处杯巡环。
进取果由命，不由趋险艰。
穿杨二三子，弓矢次第弯。
推我亦上道，再联朝士班。
二月除御史，三月使巴蛮。
蛮民詀諵诉，啮指明痛癏。
怜蛮不解语，为发昏帅奸。
归来五六月，旱色天地殷。
分司别兄弟，各各泪潸潸。
哀哉剧部职，唯数赃罪锾。
死款依稀取，鬬辞方便删。
道心常自愧，柔发难久黫。
折支望车乘，支痛谁置患。
奇哉乳臭儿，绯紫䙀被间。
渐大官渐贵，渐富心渐悭。
闹装辔头𧤾，静拭腰带斑。
鹞子绣线𩏪，狗儿金油镮。
香汤洗騘马，翠篾笼白鹇。
月请公王封，冰受天子颁。
开筵试歌舞，别宅宠妖娴。
坐卧摩绵褥，捧拥綟丝鬟。
旦夕不相离，比翼若飞鸾。
而我亦何苦，三十身已鳏。
愁吟心骨颤，寒卧支体𤸷。
居处虽幽静，尤悔少愉㦨。
不如周道士，鹤岭临钟湾。
绕院松瑟瑟，通畦水潺潺。
阳坡自寻蕨，邨沼看沤菅。
穷通两未遂，营营真老闲。','',''),('quantangshi-21195','韦氏馆与周隐客杜归和泛舟','稹','quantangshi','','卷22','天色低澹澹，池光漫油油。
轻舟闲缴绕，不远池上楼。
时物欣外奖，真元随内修。
神恬津藏满，气委支节柔。
众处岂自异，旷怀谁我俦。
风车笼野马，八荒安足游。
开颜陆浑杜，握手灵都周。
持君宝珠赠，顶戴头上头。','',''),('quantangshi-21196','刘氏馆集隐客归和子元及之子蒙晦之','稹','quantangshi','','卷22','湿垫缘竹径，寥落护岸冰。
偶然沽市酒，不越四五升。
诗客爱时景，道人话升腾。
笑言各有趣，悠哉古孙登。','',''),('quantangshi-21197','寄隐客','稹','quantangshi','','卷22','我年三十二，鬓有八九丝。
非无官次第，其如身早衰。
今人夸贵富，肉食与妖姬。
而我俱不乐，贵富亦何为。
况逢多士朝，贤俊若布棊。
班行次第立，朱紫相参差。
谟猷密勿进，羽檄纵横驰。
监察官甚小，发言无所裨。
小官仍不了，谴夺亦已随。
时或不之弃，得不自弃之。
陶君喜不遇，顾我复何疑。
潜书周隐士，白云今有期。','',''),('quantangshi-21198','元和五年予官不了罚俸西归三月六日至陕府与吴十一兄端公崔二十二院长思怆曩游因投五十韵','稹','quantangshi','','卷22','小年闲爱春，认得春风意。
未有花草时，先醲晓窗睡。
霞朝澹云色，霁景牵诗思。
渐到柳枝头，川光始明媚。
长安车马客，倾心奉权贵。
昼夜尘土中，那言早春至。
此时我独游，我游有伦次。
闲行曲江岸，便宿慈恩寺。
扣林引寒龟，疏丛出幽翠。
凌晨过杏园，晓露凝芳气。
初阳好明净，嫩树怜低庳。
排房似缀珠，欲啼红脸泪。
新莺语娇小，浅水光流利。
冷饮空腹杯，因成日高醉。
酒醒闻饭钟，随僧受遗施。
餐罢还复游，过从上文记。
行逢二月半，始足游春骑。
是时春已老，我游亦云既。
藤开九华观，草结三条隧。
新笋踊犀株，落梅飜蝶翅。
名倡绣毂车，公子青丝辔。
朝士还旬休，豪家得春赐。
提携好音乐，翦铲空田地。
同占杏花园，喧阗各丛萃。
顾予烦寝兴，复往散顦顇。
倦仆色肌羸，蹇驴行跛痹。
春衫未成就，冬服渐尘腻。
倾盖吟短章，书空忆难字。
遥闻公主笑，近被王孙戏。
邀我上华筵，横头坐宾位。
那知我年少，深解酒中事。
能唱犯声歌，偏精变筹义。
含词待残拍，促舞递繁吹。
叫噪掷投盘，生狞摄觥使。
逡巡光景晏，散乱东西异。
古观闭闲门，依然复幽閟。
无端矫情性，漫学求科试。
薄艺何足云，虚名偶频遂。
拾遗天子前，密奏升平议。
召见不须臾，憸庸已猜忌。
朝陪香案班，暮作风尘尉。
去岁又登朝，登为柏台吏。
台官相束缚，不许放情志。
寓直劳送迎，上堂烦避讳。
分司在东洛，所职尤不易。
罚俸得西归，心知受朝庇。
常山攻小寇，淮右择良帅。
国难身不行，劳生欲何为。
吾兄谙性灵，崔子同臭味。
投此挂冠词，一生还自恣。','',''),('quantangshi-21199','寄吴士矩端公五十韵','稹','quantangshi','','卷22','昔在凤翔日，十岁即相识。
未有好文章，逢人赏颜色。
可怜何郎面，二十才冠饰。
短发予近梳，罗衫紫蝉翼。
伯舅各骄纵，仁兄未摧抑。
事业若杯盘，诗书甚徽纆。
西州戎马地，贤豪事雄特。
百万时可赢，十千良易借。
寒食桐阴下，春风柳林侧。
藉草送远游，列筵酬博塞。
萎蕤云幕翠，灿烂红茵赩。
脍缕轻似丝，香醅腻如职。
将军频下城，佳人尽倾国。
媚语娇不闻，纤腰輭无力。
歌辞妙宛转，舞态能剜刻。
筝弦玉指调，粉汗红绡拭。
予时最年少，专务酒中职。
未能解生狞，偏矜任狂直。
曲庇桃根盏，横讲捎云式。
乱布鬬分朋，惟新间谗慝。
耻作最先吐，羞言未朝食。
醉眼渐纷纷，酒声频䬵䬵。
扣节参差乱，飞觥往来织。
强起相维持，飜成两匍匐。
边霜飒然降，战马鸣不息。
但喜秋光丽，谁忧塞云黑。
常随猎骑走，多在豪家匿。
夜饮天既明，朝歌日还昃。
荒狂岁云久，名利心潜逼。
时辈多得途，亲朋屡相敕。
闲因适农野，忽复爱稼穑。
平生中圣人，飜然腐肠贼。
亦从酒仙去，便被书魔惑。
脱迹壮士场，甘心竖儒域。
矜持翠筠管，敲断黄金勒。
屡益兰膏灯，犹研兔枝墨。
崎岖来掉荡，矫枉事沈默。
隐笑甚艰难，敛容还屴崱。
与君始分散，勉我劳修饰。
岐路各营营，别离长恻恻。
行看二十载，万事纷何极。
相值或须臾，安能洞胸臆。
昨来陕郊会，悲欢两难克。
问我新相知，但报长相忆。
岂无新知者，不及小相得。
亦有生岁游，同年不同德。
为别讵几时，伊予坠沟洫。
大江鼓风浪，远道参荆棘。
往事返无期，前途浩难测。
一旦得自由，相求北山北。','',''),('quantangshi-21200','三月二十四日宿曾峰馆夜对桐花寄乐天','稹','quantangshi','','卷22','微月照桐花，月微花漠漠。
怨澹不胜情，低回拂帘幕。
叶新阴影细，露重枝条弱。
夜久春恨多，风清暗香薄。
是夕远思君，思君瘦如削。
但感事睽违，非言官好恶。
奏书金銮殿，步屣青龙阁。
我在山馆中，满地桐花落。','',''),('quantangshi-21201','酬乐天书怀见寄','稹','quantangshi','','卷22','新昌北门外，与君从此分。
街衢走车马，尘土不见君。
君为分手归，我行行不息。
我上秦岭南，君直枢星北。
秦岭高崔嵬，商山好颜色。
月照山馆花，裁诗寄相忆。
天明作诗罢，草草随所如。
凭人寄将去，三月无报书。
荆州白日晚，城上鼓冬冬。
行逢贺州牧，致书三四封。
封题乐天字，未坼已霑裳。
坼书八九读，泪落千万行。
中有酬我诗，句句截我肠。
仍云得诗夜，梦我魂凄凉。
终言作书处，上直金銮东。
诗书费一夕，万恨缄其中。
中宵宫中出，复见宫月斜。
书罢月亦落，晓灯随暗花。
想君书罢时，南望劳所思。
况我江上立，吟君怀我诗。
怀我浩无极，江水秋正深。
清见万丈底，照我平生心。
感君求友什，因报壮士吟。
持谢众人口，销尽犹是金。','',''),('quantangshi-21202','酬乐天登乐游园见忆','稹','quantangshi','','卷22','昔君乐游园，怅望天欲曛。
今我大江上，快意波飜云。
秋空压澶漫，澒洞无垢氛。
四顾皆豁达，我眉今日伸。
长安隘朝市，百道走埃尘。
轩车随对列，骨肉非本亲。
夸游丞相第，偷入常侍门。
爱君直如发，勿念江湖人。','',''),('quantangshi-21203','酬乐天早夏见怀','稹','quantangshi','','卷22','庭柚有垂实，燕巢无宿雏。
我亦辞社燕，茫茫焉所如。
君诗夏方早，我叹秋已徂。
食物风土异，衾裯时节殊。
荒草满田地，近移江上居。
八日复切九，月明侵半除。','',''),('quantangshi-21204','酬乐天劝醉','稹','quantangshi','','卷22','神麯清浊酒，牡丹深浅花。
少年欲相饮，此乐何可涯。
沈机造神境，不必悟楞伽。
酡颜返童貌，安用成丹砂。
刘伶称酒德，所称良未多。
愿君听此曲，我为尽称嗟。
一杯颜色好，十盏胆气加。
半酣得自恣，酩酊归太和。
共醉真可乐，飞觥撩乱歌。
独醉亦有趣，兀然无与他。
美人醉灯下，左右流横波。
王孙醉牀上，颠倒眠绮罗。
君今劝我醉，劝醉意如何。','',''),('quantangshi-21205','和乐天初授户曹喜而言志','稹','quantangshi','','卷22','王爵无细大，得请即为恩。
君求户曹掾，贵以禄奉亲。
闻君得所请，感我欲霑巾。
今人重轩冕，所重华与纷。
矜夸仕台阁，奔走无朝昏。
君衣不盈箧，君食不满囷。
君言养既薄，何以荣我门。
披诚再三请，天子怜俭贫。
词曹直文苑，捧诏荣且忻。
归来高堂上，兄弟罗酒尊。
各称千万寿，共饮三四巡。
我实知君者，千里能具陈。
感君求禄意，求禄殊众人。
上以奉颜色，余以及亲宾。
弃名不弃实，谋养不谋身。
可怜白华士，永愿凌青云。','',''),('quantangshi-21206','和乐天赠吴丹','稹','quantangshi','','卷22','不识吴生面，久知吴生道。
迹虽染世名，心本奉天老。
雌一守命门，廻九填血脑。
委气荣卫和，咽津颜色好。
传闻共甲子，衰颓尽枯[槁]。
独有冰雪容，纤华夺鲜缟。
问人何能尔，吴实旷怀抱。
弁冕徒挂身，身外非所宝。
伊予固童昧，希真亦云早。
石坛玉晨尊，昼夜长自埽。
密印视丹田，游神梦三岛。
万过黄庭经，一食青精稻。
冥搜方朔桃，结念安期枣。
绿发幸未改，丹诚自能保。
行当摆尘缨，吴门事探讨。
君为先此词，终期搴瑶草。','',''),('quantangshi-21207','和乐天秋题曲江','稹','quantangshi','','卷22','十载定交契，七年镇相随。
长安最多处，多是曲江池。
梅杏春尚小，芰荷秋已衰。
共爱寥落境，相将偏此时。
緜緜红蓼水，扬扬白鹭鹚。
诗句偶未得，酒杯聊久持。
今来云雨旷，旧赏魂梦知。
况乃江枫夕，和君秋兴诗。','',''),('quantangshi-21208','和乐天别弟后月夜作','稹','quantangshi','','卷22','闻君别爱弟，明天照夜寒。
秋雁拂檐影，晓琴当砌弹。
怅望天澹澹，因思路漫漫。
吟为别弟操，闻者为辛酸。
况我兄弟远，一身形影单。
江波浩无极，但见时岁阑。','',''),('quantangshi-21209','和乐天秋题牡丹丛','稹','quantangshi','','卷22','敝宅艳山卉，别来长叹息。
吟君晚丛咏，似见摧颓色。
欲识别后容，勤过晚丛侧。','',''),('quantangshi-21210','春月','稹','quantangshi','','卷22','春月虽至明，终有霭霭光。
不似秋冬色，逼人寒带霜。
纤粉澹虚壁，轻烟笼半牀。
分晖间林影，余照上虹梁。
病久尘事隔，夜闲清兴长。
拥抱颠倒领，步屣东西厢。
风柳结柔援，露梅飘暗香。
雪含樱绽蘂，珠蹙桃缀房。
杳杳有余思，行行安可忘。
四邻非旧识，无以话中肠。
南有居士俨，默坐调心王。
款关一问讯，为我披衣裳。
延我入深竹，暖我于小堂。
视身琉璃莹，谕指芭蕉黄。
复有比丘溢，早传龙树方。
口中祕丹诀，肘后悬青囊。
锡杖虽独振，刀圭期共尝。
未知仙近远，已觉神轻翔。
夜久魂耿耿，月明露苍苍。
悲哉沈眠士，宁见兹夕良。','',''),('quantangshi-21211','月临花','稹','quantangshi','','卷22','临风扬扬花，透影胧胧月。
巫峡隔波云，姑峰漏霞雪。
镜匀娇面粉，灯泛高笼缬。
夜久清露多，啼珠坠还结。','',''),('quantangshi-21212','红芍药','稹','quantangshi','','卷22','芍药绽红绡，巴篱织青琐。
繁丝蹙金蘂，高焰当炉火。
翦刻彤云片，开张赤霞裹。
烟轻琉璃叶，风亚珊瑚朵。
受露色低迷，向人娇婀娜。
酡颜醉后泣，小女妆成坐。
艳艳锦不如，夭夭桃未可。
晴霞畏欲散，晚日愁将堕。
结植本为谁，赏心期在我。
采之谅多思，幽赠何由果。','',''),('quantangshi-21213','送王十一南行','稹','quantangshi','','卷22','夏水漾天末，晚阳依岸邨。
风调乌尾劲，眷恋余芳尊。
解袂方瞬息，征帆已翩翻。
江豚涌高浪，枫树摇去魂。
远戍宗侣泊，暮烟洲渚昏。
离心讵几许，骤若移寒温。
此别信非久，胡为坐忧烦。
我留石难转，君泛云无根。
万里湖南月，三声山上猿。
从兹耿幽梦，夜夜湘与沅。','',''),('quantangshi-21214','三叹 一','稹','quantangshi','','卷22','孤劒锋刀涩，犹能神彩生。
有时雷雨过，暗吼阗阗声。
主人閟灵宝，畏作升天行。
淬砺当阳铁，刻为干镆名。
远求䴙鹈莹，同用玉匣盛。
颜色纵相类，利钝颇相倾。
雄为光电烻，雌但深泓澄。
龙怒有奇变，青蛇终不惊。','',''),('quantangshi-21215','三叹 二','稹','quantangshi','','卷22','仙凤翠皇死，葳蕤光彩低。
非无鸳鸾侣，誓不同树栖。
飞驰岁云暮，感念雏在泥。
顾影不自暖，寄尔蟠桃鸡。
驯养岂无愧，类族安得齐。
愿言成羽翼，奋翅凌丹梯。','',''),('quantangshi-21216','三叹 三','稹','quantangshi','','卷22','天骥失龙偶，三年常夜嘶。
哀缘喷风断，渴且含霜啼。
长恐绝遗类，不复蹑云霓。
非无駉駉者，鹤意不在鸡。
春来筋骨瘦，吊影心亦迷。
自此渥洼种，应生浊水泥。','',''),('quantangshi-21217','遣昼','稹','quantangshi','','卷22','密竹有清阴，旷怀无尘滓。
况乃秋日光，玲珑晓窗里。
旬休聊自适，今辰日高起。
栉沐坐前轩，风轻镜如水。
开卷恣咏谣，望云闲徙倚。
新菊媚鲜妍，短萍怜靃靡。
埽除田地静，摘掇园蔬美。
幽翫惬诗流，空堂称居士。
客来伤寂寞，我念遗烦鄙。
心迹两相忘，谁能验行止。','',''),('quantangshi-21218','冬夜怀李侍御王太祝段丞','稹','quantangshi','','卷22','浩露烟壒尽，月光闲有余。
松篁细阴影，重以帘牖疎。
泛览星粲粲，轻河悠碧虚。
纤云不成叶，脉脉风丝舒。
丹竈炽东序，烧香罗玉书。
飘飘魂神举，若骖鸾鹤舆。
感念夙昔意，华尚簪与裾。
簪裾讵几许，累创吞钩鱼。
今闻馨香道，一以悟臭帤。
悟觉誓不惑，永抱胎仙居。
昼夜欣所适，安知岁云除。
行行二三友，君怀复何如。','',''),('quantangshi-21219','西斋小松二首 一','稹','quantangshi','','卷22','松树短于我，清风亦已多。
况乃枝上雪，动摇微月波。
幽姿得闲地，讵感岁蹉跎。
但恐厦终构，藉君当奈何。','',''),('quantangshi-21220','西斋小松二首 二','稹','quantangshi','','卷22','簇簇枝新黄，纤纤攒素指。
柔苙渐依条，短莎还半委。
清风日夜高，凌云意何已。
千岁盘老龙，修鳞自兹始。','',''),('quantangshi-21221','周先生','稹','quantangshi','','卷22','寥寥空山岑，冷冷风松林。
流月垂鳞光，悬泉扬高音。
希夷周先生，烧香调琴心。
神力盈三千，谁能还黄金。','',''),('quantangshi-21222','遣春十首 一','稹','quantangshi','','卷22','晓月笼云影，鸎声余雾中。
暗芳飘露气，轻寒生柳风。
冉冉一趋府，未为劳我躬。
因兹得晨起，但觉情兴隆。','',''),('quantangshi-21223','遣春十首 二','稹','quantangshi','','卷22','久雨怜霁景，偶来堤上行。
空蒙天色嫩，杳淼江面平。
百草短长出，众禽高下鸣。
春阳各有分，予亦澹无情。','',''),('quantangshi-21224','遣春十首 三','稹','quantangshi','','卷22','镜皎碧潭水，微波粗成文。
烟光垂碧草，琼脉散纤云。
岸柳好阴影，风裾遗垢氛。
悠然送春目，八荒谁与羣。','',''),('quantangshi-21225','遣春十首 四','稹','quantangshi','','卷22','低迷笼树烟，明净当霞日。
阳焰波春空，平湖漫凝溢。
雪鹭远近飞，渚牙浅深出。
江流复浩荡，相为坐纡郁。','',''),('quantangshi-21226','遣春十首 五','稹','quantangshi','','卷22','暄寒深浅春，红白前后花。
颜色讵相让，生成良有涯。
梅芳勿自早，菊秀勿自赊。
各将一时意，终年无再华。','',''),('quantangshi-21227','遣春十首 六','稹','quantangshi','','卷22','高屋童稚少，春来归燕多。
葺旧良易就，新院亦已罗。
俯怜雏化卵，仰愧鹏无窠。
巢栋与巢幕，秋风俱奈何。','',''),('quantangshi-21228','遣春十首 七','稹','quantangshi','','卷22','撩乱扑树蜂，摧残恋房蕊。
风吹雨又频，安得繁于绮。
酒杯沈易过，世事纷何已。
莫倚颜似花，君看岁如水。','',''),('quantangshi-21229','遣春十首 八','稹','quantangshi','','卷22','绕郭高高冢，半是荆王墓。
后嗣炽阳台，前贤甘荜路。
善恶徒自分，波流尽东注。
胡然不饮酒，坐落桐花树。','',''),('quantangshi-21230','遣春十首 九','稹','quantangshi','','卷22','花阴莎草长，藉莎闲自酌。
坐看鸎鬬枝，轻花满尊杓。
葛巾竹稍挂，书卷琴上阁。
沽酒过此生，狂歌眼前乐。','',''),('quantangshi-21231','遣春十首 十','稹','quantangshi','','卷22','梨叶已成阴，柳条纷起絮。
波绿紫屏风，螺红碧筹筯。
三杯面上热，万事心中去。
我意风散云，何劳问行处。','',''),('quantangshi-21232','表夏十首 一','稹','quantangshi','','卷22','夏风多暖暖，树木有繁阴。
新笋紫长短，早樱红浅深。
烟花云幕重，榴艳朝景侵。
华实各自好，讵云芳意沈。','',''),('quantangshi-21233','表夏十首 二','稹','quantangshi','','卷22','初日满阶前，轻风动帘影。
旬时得休浣，高卧阅清景。
僮儿拂巾箱，鵶轧深林井。
心到物自闲，何劳远箕頴。','',''),('quantangshi-21234','表夏十首 三','稹','quantangshi','','卷22','江瘴炎夏早，蒸腾信难度。
今宵好风月，独此荒庭趣。
露叶倾暗光，流星委余素。
但恐清夜徂，讵悲朝景暮。','',''),('quantangshi-21235','表夏十首 四','稹','quantangshi','','卷22','孟月夏犹浅，奇云未成峰。
度霞红漠漠，压浪白溶溶。
玉委有余润，飙驰无去踪。
何如捧云雨，喷毒随蛟龙。','',''),('quantangshi-21236','表夏十首 五','稹','quantangshi','','卷22','流芳递炎景，繁英尽寥落。
公署香满庭，晴霞覆阑药。
裁红起高焰，缀绿排新萼。
凭此遣幽怀，非言念将谑。','',''),('quantangshi-21237','表夏十首 六','稹','quantangshi','','卷22','红丝散芳树，旋转光风急。
烟泛被笼香，露浓妆面湿。
佳人不在此，恨望堦前立。
忽厌夏景长，今春行已及。','',''),('quantangshi-21238','表夏十首 七','稹','quantangshi','','卷22','百舌渐吞声，黄鸎正娇小。
云鸿方警夜，笼鸡已鸣晓。
当时客自适，运去谁能矫。
莫厌夏虫多，蜩螗定相扰。','',''),('quantangshi-21239','表夏十首 八','稹','quantangshi','','卷22','翩翩帘外燕，戢戢巢内雏。
啖食筋力尽，毛衣成紫襦。
朝来各飞去，雄雌梁上呼。
养子将备老，恶儿那胜无。','',''),('quantangshi-21240','表夏十首 九','稹','quantangshi','','卷22','西山夏雪消，江势东南泻。
风波高若天，滟滪低于马。
正被黄牛旋，难期白帝下。
我在平地行，翻忧济川者。','',''),('quantangshi-21241','表夏十首 十','稹','quantangshi','','卷22','灵均死波后，是节常浴兰。
彩缕碧筠糉，香秔白玉团。
逝者良自苦，今人反为欢。
哀哉徇名士，没命求所难。','',''),('quantangshi-21242','解秋十首 一','稹','quantangshi','','卷22','清晨頮寒水，动摇襟袖轻。
翳翳林上叶，不知秋暗生。
回悲镜中发，华白三四茎。
岂无满头黑，念此衰已萌。','',''),('quantangshi-21243','解秋十首 二','稹','quantangshi','','卷22','微霜才结露，翔鸠初变鹰。
无乃天地意，使之行小惩。
鸱鸮诚可恶，蔽日有高鹏。
舍大以擒细，我心终不能。','',''),('quantangshi-21244','解秋十首 三','稹','quantangshi','','卷22','往岁学仙侣，各在无何乡。
同时骛名者，次第鵷鹭行。
而我两不遂，三十鬓添霜。
日暮江上立，蝉鸣枫树黄。','',''),('quantangshi-21245','解秋十首 四','稹','quantangshi','','卷22','后伏火犹在，先秋蝉已多。
云色日夜白，骄阳能几何。
壤隙漏江海，忽微成网罗。
勿言时不至，但恐岁蹉跎。','',''),('quantangshi-21246','解秋十首 五','稹','quantangshi','','卷22','新月才到地，轻河如泛云。
萤飞高下火，树影参差文。
露簟有微润，清香时暗焚。
夜闲心寂默，洞庭无垢氛。','',''),('quantangshi-21247','解秋十首 六','稹','quantangshi','','卷22','霁丽牀前影，飘萧帘外竹。
簟凉朝睡重，梦觉茶香熟。
亲烹园内葵，凭买家家麯。
酿酒并毓蔬，人来有棊局。','',''),('quantangshi-21248','解秋十首 七','稹','quantangshi','','卷22','寒竹秋雨重，凌霄晚花落。
低回翠玉梢，散乱栀黄萼。
颜色有殊异，风霜无好恶。
年年百草芳，毕意同萧索。','',''),('quantangshi-21249','解秋十首 八','稹','quantangshi','','卷22','春非我独春，秋非我独秋。
岂念百草死，但念霜满头。
头白古所同，胡为坐烦忧。
茫茫百年内，处身良未休。','',''),('quantangshi-21250','解秋十首 九','稹','quantangshi','','卷22','西风冷衾簟，展转布华茵。
来者承玉体，去者流芳尘。
适意丑为好，及时疎亦亲。
衰周仲尼出，无乃为妖人。','',''),('quantangshi-21251','解秋十首 十','稹','quantangshi','','卷22','漠漠江面烧，微微枫树烟。
今日复今夕，秋怀方浩然。
况我头上发，衰白不待年。
我怀有时极，此意何由诠。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21252','遣病十首 一','稹','quantangshi','','卷22','服药备江瘴，四年方一疠。
岂是药无功，伊予久留滞。
滞留人固薄，瘴久药难制。
去日良已甘，归途奈无际。','',''),('quantangshi-21253','遣病十首 二','稹','quantangshi','','卷22','弃置何所任，郑公怜我病。
三十九万钱，资予养顽瞑。
身贱杀何益，恩深报难罄。
公其万千年，世有天之郑。','',''),('quantangshi-21254','遣病十首 三','稹','quantangshi','','卷22','忆作孩稚初，健羡成人列。
倦学厌日长，嬉游念佳节。
今来渐讳年，顿与前心别。
白日速如飞，佳晨亦骚屑。','',''),('quantangshi-21255','遣病十首 四','稹','quantangshi','','卷22','昔在痛饮场，憎人病辞醉。
病来身怕酒，始悟他人意。
怕酒岂不闲，悲无少年气。
传语少年儿，杯盘莫廻避。','',''),('quantangshi-21256','遣病十首 五','稹','quantangshi','','卷22','忆初头始白，昼夜惊一缕。
渐及鬓与须，多来不能数。
壮年等闲过，过壮年已五。
华发不再青，劳生竟何补。','',''),('quantangshi-21257','遣病十首 六','稹','quantangshi','','卷22','在家非不病，有病心亦安。
起居甥侄扶，药饵兄嫂看。
今病兄远路，道遥书信难。
寄言娇小弟，莫作官家官。','',''),('quantangshi-21258','遣病十首 七','稹','quantangshi','','卷22','燕巢官舍内，我尔俱为客。
岁晚我独留，秋深尔安适。
风高翅羽垂，路远烟波隔。
去去玉山岑，人间网罗窄。','',''),('quantangshi-21259','遣病十首 八','稹','quantangshi','','卷22','檐宇夜来旷，暗知秋已生。
卧悲衾簟冷，病觉支体轻。
炎昏岂不勌，时去聊自惊。
浩叹终一夕，空堂天欲明。','',''),('quantangshi-21260','遣病十首 九','稹','quantangshi','','卷22','秋依静处多，况乃凌晨趣。
深竹蝉昼风，翠茸衫晓露。
庭莎病看长，林果闲知数。
何以强健时，公门日劳骛。','',''),('quantangshi-21261','遣病十首 十','稹','quantangshi','','卷22','朝结故乡念，暮作空堂寝。
梦别泪亦流，啼痕暗横枕。
昔愁凭酒遣，今病安能饮。
落尽秋槿花，离人病犹甚。','',''),('quantangshi-21262','寒','稹','quantangshi','','卷22','江瘴节候暖，腊初梅已残。
夜来北风至，喜见今日寒。
扣冰浅塘水，拥雪深竹阑。
复此满尊醁，但嗟谁与欢。','',''),('quantangshi-21263','玉泉道中作','稹','quantangshi','','卷22','楚俗物候晚，孟冬才有霜。
早农半华实，夕水含风凉。
遐想云外寺，峰峦渺相望。
松门接官路，泉脉连僧房。
微露上弦月，暗焚初夜香。
谷深烟壒净，山虚钟磬长。
念此清境远，复忧尘事妨。
行行即前路，勿滞分寸光。','',''),('quantangshi-21264','遣病','稹','quantangshi','','卷22','自古谁不死，不复记其名。
今年京城内，死者老少并。
独孤才四十，仕宦方荣荣。
李三三十九，登朝有清声。
赵昌八十余，三拥大将旌。
为生信异异，之死同冥冥。
其家哭泣爱，一一无异情。
其类嗟叹惜，各各无重轻。
万龄龟菌等，一死天地平。
以此方我病，我病何足惊。
借如今日死，亦足了一生。
借使到百年，不知何所成。
况我早师佛，屋宅此身形。
舍彼复就此，去留何所萦。
前身为过迹，来世即前程。
但念行不息，岂忧无路行。
蜕骨龙不死，蜕皮蝉自鸣。
胡为神蜕体，此道人不明。
持谢爱朋友，寄之仁弟兄。
吟此可达观，世言何足听。','',''),('quantangshi-21265','感梦','稹','quantangshi','','卷22','十月初二日，我行蓬州西。
三十里有馆，有馆名芳溪。
荒邮屋舍坏，新雨田地泥。
我病百日余，肌体顾若刲。
气填暮不食，早早掩窦圭。
阴寒筋骨病，夜久灯火低。
忽然寝成梦，宛见颜如圭。
似叹久离别，嗟嗟复凄凄。
问我何病痛，又叹何栖栖。
答云痰滞久，与世复相暌。
重云痰小疾，良药固易挤。
前时奉橘丸，攻疾有神功。
何不善和疗，岂独头有风。
殷勤平生事，款曲无不终。
悲欢两相极，以是半日中。
言罢相与行，行行古成里。
同行复一人，不识谁氏子。
逡巡急吏来，呼唤愿且止。
驰至相君前，再拜复再起。
启云吏有奉，奉命传所旨。
事有大惊忙，非君不能理。
答云久就闲，不愿见劳使。
多谢致勤勤，未敢相唯唯。
我因前献言，此事愚可料。
乱热由静消，理繁在知要。
君如冬月阳，奔走不必召。
君如铜镜明，万物自可照。
愿君许苍生，勿复高体调。
相君不我言，顾我再三笑。
行行及城户，黯黯余日晖。
相君不我言，命我从此归。
不省别时语，但省涕淋漓。
觉来身体汗，坐卧心骨悲。
闪闪灯背壁，胶胶鸡去埘。
倦童颠倒寝，我泪纵横垂。
泪垂啼不止，不止啼且声。
啼声觉僮仆，僮仆撩乱惊。
问我何所苦，问我何所思。
我亦不能语，惨惨即路岐。
前经新政县，今夕复明辰。
置置满心气，不得说向人。
奇哉赵明府，怪我眉不伸。
云有北来僧，住此月与旬。
自言辨贵骨，谓若识天真。
谈游费閟景，何不与逡巡？
僧来为予语，语及昔所知。
自言有奇中，裴相未相时。
读书灵山寺，住处接园篱。
指言他日贵，晷刻似不移。
我闻僧此语，不觉泪歔欷。
因言前夕梦，无人一相谓。
无乃裴相君，念我胸中气。
遣师及此言，使我尽前事。
僧云彼何亲，言下涕不已。
我云知我深，不幸先我死。
僧云裴相君，如君恩有几。
我云滔滔众，好直者皆是。
唯我与白生，感遇同所以。
官学不同时，生小异乡里。
拔我尘土中，使我名字美。
美名何足多，深分从此始。
吹嘘莫我先，顽陋不我鄙。
往往裴相门，终年不曾履。
相门多众流，多誉亦多毁。
如闻风过尘，不动井中水。
前时予掾荆，公在期复起。
自从裴公无，吾道甘已矣。
白生道亦孤，谗谤销骨髓。
司马九江城，无人一言理。
为师陈苦言，挥涕满十指。
未死终报恩，师听此男子。','',''),('quantangshi-21266','和东川李相公慈竹十二韵','稹','quantangshi','','卷22','慈竹不外长，密比青瑶华。
矛攒有森束，玉粒无蹉跎。
纤粉妍腻质，细琼交翠柯。
亭亭霄汉近，霭霭雨露多。
冰碧寒夜耸，箫韶风昼罗。
烟含胧胧影，月泛鳞鳞波。
鸾凤一已顾，燕雀永不过。
幽姿媚庭实，颢气爽天涯。
峻节高转露，贞筠寒更佳。
托身仙坛上，灵物神所呵。
时与天籁合，日闻阳春歌。
应怜孤生者，摧折成病疴。','',''),('quantangshi-21267','酬东川李相公十六韵','稹','quantangshi','','卷22','昔附赤霄羽，葳蕤游紫垣。
鬬班香案上，奏语玉晨尊。
戆直撩忌讳，科仪惩傲顽。
自从真籍除，弃置勿复论。
前时共游者，日夕黄金轩。
请帝下巫觋，八荒求我魂。
鸾凤屡鸣顾，燕雀尚篱藩。
徒令霄汉外，往往尘念存。
存念岂虚设，并投琼与璠。
弹珠古所讶，此用何太敦。
邹律寒气变，郑琴祥景奔。
灵芝绕身出，左右光彩繁。
碾玉无俗色，蘂珠非世言。
重慙前日句，陋若莸并荪。
腊月巴地雨，瘴江愁浪翻。
因持骇鸡宝，一照浊水昏。','',''),('quantangshi-21268','酬独孤二十六送归通州','稹','quantangshi','','卷22','再拜捧兄赠，拜兄珍重言。
我有平生志，临别将具论。
十岁慕倜傥，爱白不爱昏。
宁爱寒切烈，不爱阳温暾。
二十走猎骑，三十游海门。
憎兔跳趯趯，恶鹏黑翻翻。
鳌钓气方壮，鹘拳心颇尊。
下观鬇鬡辈，一扫冀不存。
名冠壮士籍，功酬明主恩。
不然合身弃，何况身上痕。
金石有销烁，胏腑无寒温。
分画久已定，波涛何足烦。
尝希苏门啸，讵厌巴树猿。
瘴水徒浩浩，浮云亦轩轩。
长歌莫长欢，饮斛莫饮樽。
生为醉乡客，死作达士魂。','',''),('quantangshi-21269','酬刘猛见送','稹','quantangshi','','卷22','种花有颜色，异色即为妖。
养鸟恶羽翮，剪翮不待高。
非无剪伤者，物性难自逃。
百足虽捷捷，商羊亦翘翘。
伊余狷然质，谬入多士朝。
任气有愎戆，容身寡朋曹。
愚狂偶似直，静僻非敢骄。
一为毫发忤，十载山川遥。
烁铁不在火，割肌不在刀。
险心露山岳，流语翻波涛。
六尺安敢主，方寸自由调。
神劒土不蚀，异布火不燋。
虽无二物姿，庶欲効一毫。
未能深蹙蹙，多谢相劳劳。
去去我移马，迟迟君过桥。
云势正横壑，江流初满槽。
持此慰远道，此之为旧交。','',''),('quantangshi-21270','酬乐天赴江州路上见寄三首 一','稹','quantangshi','','卷22','昔在京城心，今在吴楚末。
千山道路险，万里音尘阔。
天上参与商，地上胡与越。
终天升沈异，满地网罗设。
心有无眹环，肠有无绳结。
有结解不开，有环寻不歇。
山岳移可尽，江海塞可绝。
离恨若空虚，穷年思不彻。
生莫强相同，相同会相别。','',''),('quantangshi-21271','酬乐天赴江州路上见寄三首 二','稹','quantangshi','','卷22','襄阳大堤绕，我向堤前住。
烛随花艳来，骑送朝云去。
万竿高庙竹，三月徐亭树。
我昔忆君时，君今怀我处。
有身有离别，无地无岐路。
风尘同古今，人世劳新故。','',''),('quantangshi-21272','酬乐天赴江州路上见寄三首 三','稹','quantangshi','','卷22','人亦有相爱，我尔殊众人。
朝朝宁不食，日日愿见君。
一日不得见，愁肠坐氛氲。
如何远相失，各作万里云。
云高风苦多，会合难遽因。
天上犹有碍，何况地上身。','',''),('quantangshi-21273','邮竹','稹','quantangshi','','卷22','庭有萧萧竹，门有阗阗骑。
嚣静本殊途，因依偶同寄。
亭亭乍干云，袅袅亦垂地。
人有异我心，我无异人意。','',''),('quantangshi-21274','落月','稹','quantangshi','','卷22','落月沈余影，阴渠流暗光。
蚊声霭窗户，萤火绕屋梁。
飞幌翠云薄，新荷清露香。
不吟复不寐，竟夕池水傍。','',''),('quantangshi-21275','高荷','稹','quantangshi','','卷22','种藕百余根，高荷才四叶。
颭闪碧云扇，团圆青玉叠。
亭亭自抬举，鼎鼎难藏擪。
不学着水荃，一生长怗怗。','',''),('quantangshi-21276','和裴校书鹭鸶飞','稹','quantangshi','','卷22','鹭鸶鹭鸶何遽飞，鵶惊雀噪难久依。
清江见底草堂在，一点白光终不归。','',''),('quantangshi-21277','夜池','稹','quantangshi','','卷22','荷叶团圆茎削削，绿萍面上红衣落。
满池明月思啼螿，高屋无人风张幕。','',''),('quantangshi-21278','酬杨司业十二兄早秋述情见寄','稹','quantangshi','','卷22','白发故人少，相逢意弥远。
往事共销沈，前期各衰晚。
昨来遇弥苦，已复云离巘。
秋草古胶庠，寒沙废宫苑。
知心岂忘鲍，咏怀难和阮。
壮志日萧条，那能竞朝幰。','',''),('quantangshi-21279','代杭人作使君一朝去二首 一','稹','quantangshi','','卷22','使君一朝去，遗爱在人口。
惠化境内春，才名天下首。
为问龚黄辈，兼能作诗否。','',''),('quantangshi-21280','代杭人作使君一朝去二首 二','稹','quantangshi','','卷22','使君一朝去，断肠如锉檗。
无复见冰壶，唯应镂金石。
自此一州人，生男尽名白。','',''),('quantangshi-21281','长庆历','稹','quantangshi','','卷22','年历复年历，卷尽悲且惜。
历日何足悲，但悲年运易。
年年岂无叹，此叹何唧唧。
所叹别此年，永无长庆历。','',''),('quantangshi-21282','顺宗至德大圣大安孝皇帝挽歌词三首 一','稹','quantangshi','','卷22','不改延洪祚，因成揖让朝。
讴歌同戴启，遏密共思尧。
雨露施恩广，梯航会葬遥。
号弓那独切，曾感昔年招。','',''),('quantangshi-21283','顺宗至德大圣大安孝皇帝挽歌词三首 二','稹','quantangshi','','卷22','前春文祖庙，大舜嗣尧登。
及此逾年感，还因是月崩。
寿缘追孝促，业在继明兴。
俭诏同今古，山川绕灞陵。','',''),('quantangshi-21284','顺宗至德大圣大安孝皇帝挽歌词三首 三','稹','quantangshi','','卷22','七月悲风起，凄凉万国人。
羽仪经巷内，輼𨍇转城闉。
暝色依陵早，秋声入辂新。
自嗟同草木，不识永贞春。','',''),('quantangshi-21285','宪宗章武孝皇帝挽歌词三首 一','稹','quantangshi','','卷22','国付重离后，身随十圣仙。
北辰移帝座，西日到虞泉。
方丈言虚设，华胥事眇然。
触鳞曾在宥，偏哭堕髯前。','',''),('quantangshi-21286','宪宗章武孝皇帝挽歌词三首 二','稹','quantangshi','','卷22','天宝遗余事，元和盛圣功。
二凶枭帐下，三叛斩都中。
始服沙陁虏，方吞逻逤戎。
狼星如要射，犹有鼎湖弓。','',''),('quantangshi-21287','宪宗章武孝皇帝挽歌词三首 三','稹','quantangshi','','卷22','月落禁垣西，星攒晓仗齐。
风传宫漏苦，云拂羽仪低。
路隘车千两，桥危马万蹄。
共嗟封石捡，不为报功泥。','',''),('quantangshi-21288','恭王故太妃挽歌词二首 一','稹','quantangshi','','卷22','燕姞贻天梦，梁王尽孝思。
虽从魏诏葬，得用汉藩仪。
曙月残光敛，寒箫度曲迟。
平生奉恩地，哀挽欲何之。','',''),('quantangshi-21289','恭王故太妃挽歌词二首 二','稹','quantangshi','','卷22','文卫罗新圹，仙娥掩暝山。
雪云埋陇合，箫鼓望城还。
寒树风难静，霜郊夜更闲。
哀荣深孝嗣，仪表在河间。','',''),('quantangshi-21290','哭吕衡州六首 一','稹','quantangshi','','卷22','气敌三人杰，交深一纸书。
我投冰莹眼，君报水怜鱼。
髀股惟夸瘦，膏肓岂暇除。
伤心死诸葛，忧道不忧余。','',''),('quantangshi-21291','哭吕衡州六首 二','稹','quantangshi','','卷22','望有经纶钓，虔收宰相刀。
江文驾风远，云貌接天高。
国待球琳器，家藏虎豹韬。
尽将千载宝，埋入五原蒿。','',''),('quantangshi-21292','哭吕衡州六首 三','稹','quantangshi','','卷22','白马双旌队，青山八阵图。
请缨期系虏，枕草誓捐躯。
势激三千壮，年应四十无。
遥闻不瞑目，非是不怜吴。','',''),('quantangshi-21293','哭吕衡州六首 四','稹','quantangshi','','卷22','雕鹗生难敌，沉檀死更香。
儿童喧巷市，羸老哭碑堂。
雁起沙汀暗，云连海气黄。
祝融峰上月，几照北人丧。','',''),('quantangshi-21294','哭吕衡州六首 五','稹','quantangshi','','卷22','廻雁峰前雁，春廻尽却廻。
联行四人去，同葬一人来。
铙吹临江返，城池隔雾开。
满船深夜哭，风棹楚猿哀。','',''),('quantangshi-21295','哭吕衡州六首 六','稹','quantangshi','','卷22','杜预春秋癖，扬雄着述精。
在时兼不语，终古定归名。
耒水波文细，湘江竹叶轻。
平生思风月，潜寐若为情。','',''),('quantangshi-21296','僧如展及韦载同游碧涧寺各赋诗予落句云他生莫忘灵山座满壁人名后会稀展共吟他生之句因话释氏缘会所以莫不凄然久之不十日而展公长逝惊悼返覆则他生岂有兆耶其间展公仍赋黄字五十韵飞札相示予方属和未毕自此不复撰成徒以四韵为识','稹','quantangshi','','卷22','重吟前日他生句，岂料逾旬便隔生。
会拟一来身塔下，无因共绕寺廊竹。
紫毫飞札看犹湿，黄字新诗和未成。
纵使得如羊叔子，不闻兼记旧交情。','',''),('quantangshi-21297','公安县远安寺水亭见展公题壁漂然泪流因书四韵','稹','quantangshi','','卷22','碧涧去年会，与师三两人。
今来见题壁，师已是前身。
芰叶迎僧夏，杨花度俗春。
空将数行泪，洒徧塔中尘。','',''),('quantangshi-21298','寒食日毛空路示侄晦及从简','稹','quantangshi','','卷22','我昔孩提从我兄，我今衰白尔初成。
分明寄取原头路，百世长须此路行。','',''),('quantangshi-21299','别孙村老人','稹','quantangshi','','卷22','年年渐觉老人稀，欲别孙翁泪满衣。
未死不知何处去，此身终向此原归。','',''),('quantangshi-21300','和乐天刘家花','稹','quantangshi','','卷22','闲坊静曲同消日，泪草伤花不为春。
徧问旧交零落尽，十人才有两三人。','',''),('quantangshi-21301','褒城驿二首 一','稹','quantangshi','','卷22','容州诗句在褒城，几度经过眼暂明。
今日重看满衫泪，可怜名字已前生。','',''),('quantangshi-21302','褒城驿二首 二','稹','quantangshi','','卷22','忆昔万株梨映竹，遇逢黄令醉残春。
梨枯竹尽黄令死，今日再来衰病身。','',''),('quantangshi-21303','和乐天梦亡友刘太白同游二首 一','稹','quantangshi','','卷22','君诗昨日到通州。
万里知君一梦刘，闲坐思量小来事。
秪应元是梦中游。','',''),('quantangshi-21304','和乐天梦亡友刘太白同游二首 二','稹','quantangshi','','卷22','老来东郡复西州，行处生尘为丧刘。
纵使刘君魂魄在，也应至死不同游。','',''),('quantangshi-21305','酬乐天见忆兼伤仲远','稹','quantangshi','','卷22','死别重泉閟，生离万里赊。
瘴侵新病骨，梦到故人家。
遥泪陈根草，闲收落地花。
庾公楼怅望，巴子国生涯。
河任天然曲，江随峡势斜。
与君皆直戆，须分老泥沙。','',''),('quantangshi-21306','与乐天同葬杓直','稹','quantangshi','','卷22','元伯来相葬，山涛誓抚孤。
不知他日事，兼得似君无。','',''),('quantangshi-21307','夜闲','稹','quantangshi','','卷22','感极都无梦，魂销转易惊。
风帘半钩落，秋月满牀明。
怅望临阶坐，沈吟遶树行。
孤琴在幽匣，时迸断弦声。','',''),('quantangshi-21308','感小株夜合','稹','quantangshi','','卷22','纤干未盈把，高条才过眉。
不禁风苦动，偏受露先萎。
不分秋同尽，深嗟小便衰。
伤心落残叶，犹识合昏期。','',''),('quantangshi-21309','醉醒','稹','quantangshi','','卷22','积善坊中前度饮，谢家诸婢笑扶行。
今宵还似当时醉，半夜觉来闻哭声。','',''),('quantangshi-21310','追昔游','稹','quantangshi','','卷22','谢傅堂前音乐和，狗儿吹笛胆娘歌。
花园欲盛千场饮，水阁初成百度过。
醉摘樱桃投小玉，嬾梳丛鬓舞曹婆。
再来门馆唯相吊，风落秋池红叶多。','',''),('quantangshi-21311','空屋题','稹','quantangshi','','卷22','朝从空屋里，骑马入空台。
尽日推闲事，还归空屋来。
月明穿暗隙，灯烬落残灰。
更想咸阳道，魂车昨夜回。','',''),('quantangshi-21312','初寒夜寄卢子蒙','稹','quantangshi','','卷22','月是阴秋镜，寒为寂寞资。
轻寒酒醒后，斜月枕前时。
倚壁思闲事，回灯检旧诗。
闻君亦同病，终夜远相悲。','',''),('quantangshi-21313','城外回谢子蒙见谕','稹','quantangshi','','卷22','十里抚柩别，一身骑马回。
寒烟半堂影，烬火满庭灰。
稚女凭人问，病夫空自哀。
潘安寄新咏，仍是夜深来。','',''),('quantangshi-21314','谕子蒙','稹','quantangshi','','卷22','抚稚君休感，无儿我不伤。
片云离岫远，双燕念巢忙。
大壑谁非水，华星各自光。
但令长有酒，何必谢家庄。','',''),('quantangshi-21315','遣悲怀三首 一','稹','quantangshi','','卷22','谢公最小偏怜女，嫁与黔娄百事乖。
顾我无衣搜画箧，泥他沽酒拔金钗。
野蔬充膳甘长藿，落叶添薪仰古槐。
今日俸钱过十万，与君营奠复营斋。','',''),('quantangshi-21316','遣悲怀三首 二','稹','quantangshi','','卷22','昔日戏言身后意，今朝皆到眼前来。
衣裳已施行看尽，针线犹存未忍开。
尚想旧情怜婢仆，也曾因梦送钱财。
诚知此恨人人有，贫贱夫妻百事哀。','',''),('quantangshi-21317','遣悲怀三首 三','稹','quantangshi','','卷22','闲坐悲君亦自悲，百年都是几多时。
邓攸无子寻知命，潘岳悼亡犹费词。
同穴窅冥何所望，他生缘会更难期。
唯将终夜长开眼，报答平生未展眉。','',''),('quantangshi-21318','旅眠','稹','quantangshi','','卷22','内外都无隔，帷屏不复张。
夜眠兼客坐，同在火炉牀。','',''),('quantangshi-21319','除夜','稹','quantangshi','','卷22','忆昔岁除夜，见君花烛前。
今宵祝文上，重叠叙新年。
闲处低声哭，空堂背月眠。
伤心小儿女，撩乱火堆边。','',''),('quantangshi-21320','感梦','稹','quantangshi','','卷22','行吟坐叹知何极，影绝魂销动隔年。
今夜商山馆中梦，分明同在后堂前。','',''),('quantangshi-21321','合衣寝','稹','quantangshi','','卷22','良夕背灯坐，方成合衣寝。
酒醉夜未阑，几回颠倒枕。','',''),('quantangshi-21322','竹簟','稹','quantangshi','','卷22','竹簟衬重茵，未忍都令卷。
忆昨初来日，看君自施展。','',''),('quantangshi-21323','听庾及之弹乌夜啼引','稹','quantangshi','','卷22','君弹乌夜啼，我传乐府解古题。
良人在狱妻在闺，官家欲赦乌报妻。
乌前再拜泪如雨，乌作哀声妻暗语。
后人写出乌啼引，吴调哀弦声楚楚。
四五年前作拾遗，谏书不密丞相知。
谪官诏下吏驱遣，身作囚拘妻在远。
归来相见泪如珠，唯说闲宵长拜乌。
君来到舍是乌力，妆点乌盘邀女巫。
今君为我千万弹，乌啼啄啄泪澜澜。
感君此曲有深意，昨日乌啼桐叶坠。
当时为我赛乌人，死葬咸阳原上地。','',''),('quantangshi-21324','梦井','稹','quantangshi','','卷22','梦上高高原，原上有深井。
登高意枯渴，愿见深泉冷。
裴回遶井顾，自照泉中影。
沈浮落井瓶，井上无悬绠。
念此瓶欲沈，荒忙为求请。
遍入原上村，村空犬仍猛。
还来遶井哭，哭声通复哽。
哽噎梦忽惊，觉来房舍静。
灯焰碧胧胧，泪光疑冏冏。
钟声夜方半，坐卧心难整。
忽忆咸阳原，荒田万余顷。
土厚圹亦深，埋魂在深埂。
埂深安可越，魂通有时逞。
今宵泉下人，化作瓶相憬。
感此涕丸澜，丸澜涕霑领。
所伤觉梦间，便觉死生境。
岂无同穴期，生期谅绵永。
又恐前后魂，安能两知省。
寻环意无极，坐见天将昞。
吟此梦井诗，春朝好光景。','',''),('quantangshi-21325','江陵三梦 一','稹','quantangshi','','卷22','平生每相梦，不省两相知。
况乃幽明隔，梦魂徒尔为。
情知梦无益，非梦见何期。
今夕亦何夕，梦君相见时。
依稀旧妆服，暗淡昔容仪。
不道间生死，但言将别离。
分张碎针线，襵叠故幈帏。
抚稚再三嘱，泪珠千万垂。
嘱云唯此女，自叹总无儿。
尚念娇且呆，未禁寒与饥。
君复不憘事，奉身犹脱遗。
况有官缚束，安能长顾私。
他人生间别，婢仆多谩欺。
君在或有托，出门当付谁。
言罢泣幽噎，我亦涕淋漓。
惊悲忽然寤，坐卧若狂痴。
月影半床黑，虫声幽草移。
心魂生次第，觉梦久自疑。
寂默深想像，泪下如流澌。
百年永已诀，一梦何太悲。
悲君所娇女，弃置不我随。
长安远于日，山川云间之。
纵我生羽翼，网罗生絷维。
今宵泪零落，半为生别滋。
感君下泉魄，动我临川思。
一水不可越，黄泉况无涯。
此怀何由极，此梦何由追。
坐见天欲曙，江风吟树枝。','',''),('quantangshi-21326','江陵三梦 二','稹','quantangshi','','卷22','古原三丈穴，深葬一枝琼。
崩剥山门坏，烟绵坟草生。
久依荒陇坐，却望远村行。
惊觉满床月，风波江上声。','',''),('quantangshi-21327','江陵三梦 三','稹','quantangshi','','卷22','君骨久为土，我心长似灰。
百年何处尽，三夜梦中来。
逝水良已矣，行云安在哉？
坐看朝日出，众鸟双裴回。','',''),('quantangshi-21328','张旧蚊帱','稹','quantangshi','','卷22','逾年间生死，千里旷南北。
家居无见期，况乃异乡国。
破尽裁缝衣，忘收遗翰墨。
独有缬纱帱，凭人远携得。
施张合欢榻，展卷双鸳翼。
已矣长空虚，依然旧颜色。
裴回将就寝，徙倚情何极。
昔透香田田，今无魂恻恻。
隙穿斜月照，灯背空床黑。
达理强开怀，梦啼还过臆。
平生贫寡欢，夭枉劳苦忆。
我亦距几时，胡为自摧逼。
烛蛾焰中舞，蠒蚕丛上织。
燋烂各自求，他人顾何力。
多离因苟合，恶影当务息。
往事勿复言，将来幸前识。','',''),('quantangshi-21329','独夜伤怀赠呈张侍御','稹','quantangshi','','卷22','烬火孤星灭，残灯寸焰明。
竹风吹面冷，檐雪坠阶声。
寡鹤连天呌，寒雏彻夜惊。
秪应张侍御，潜会我心情。','',''),('quantangshi-21330','六年春遣怀八首 一','稹','quantangshi','','卷22','伤禽我是笼中鹤，沈劒君为泉下龙。
重纩犹存孤枕在，春衫无复旧裁缝。','',''),('quantangshi-21331','六年春遣怀八首 二','稹','quantangshi','','卷22','检得旧书三四纸，高低阔狭粗成行。
自言并食寻高事，唯念山深驿路长。','',''),('quantangshi-21332','六年春遣怀八首 三','稹','quantangshi','','卷22','公无渡河音响绝，已隔前春复去秋。
今日闲窗拂尘土，残弦犹迸钿箜篌。','',''),('quantangshi-21333','六年春遣怀八首 四','稹','quantangshi','','卷22','婢仆晒君余服用，娇痴稚女遶床行。
玉梳钿朵香胶解，尽日风吹玳瑁筝。','',''),('quantangshi-21334','六年春遣怀八首 五','稹','quantangshi','','卷22','伴客销愁长日饮，偶然乘兴便醺醺。
怪来醒后傍人泣，醉里时时错问君。','',''),('quantangshi-21335','六年春遣怀八首 六','稹','quantangshi','','卷22','我随楚泽波中梗，君作咸阳泉下泥。
百事无心值寒食，身将稚女帐前啼。','',''),('quantangshi-21336','六年春遣怀八首 七','稹','quantangshi','','卷22','童稚痴狂撩乱走，绣球花仗满堂前。
病身一到繐帷下，还向临阶背日眠。','',''),('quantangshi-21337','六年春遣怀八首 八','稹','quantangshi','','卷22','小于潘岳头先白，学取庄周泪莫多。
止竟悲君须自省，川流前后各风波。','',''),('quantangshi-21338','答友封见赠','稹','quantangshi','','卷22','荀令香销潘簟空，悼亡诗满旧屏风。
扶床小女君先识，应为些些似外翁。','',''),('quantangshi-21339','梦成之','稹','quantangshi','','卷22','烛暗船风独梦惊，梦君频问向南行。
觉来不语到明坐，一夜洞庭湖水声。','',''),('quantangshi-21340','哭小女降真','稹','quantangshi','','卷22','雨点轻沤风复惊，偶来何事去何情。
浮生未到无生地，暂到人间又一生。','',''),('quantangshi-21341','哭女樊','稹','quantangshi','','卷22','秋天净绿月分明，何事巴猿不剩鸣。
应是一声肠断去，不容啼到第三声。','',''),('quantangshi-21342','哭女樊四十韵','稹','quantangshi','','卷22','逝者何由见，中人未达情。
马无生角望，猿有断肠鸣。
去伴投遐徼，来随梦险程。
四年巴养育，万里硖回萦。
病是他乡染，魂应远处惊。
山魈邪乱逼，沙虱毒潜婴。
母约看宁辨，余慵疗不精。
欲寻方次第，俄值疾充盈。
灯火徒相守，香花秪浪擎。
莲初开月梵，蕣已落朝荣。
魄散云将尽，形全玉尚莹。
空垂两行血，深送一枝琼。
祕祝休巫觋，安眠放使令。
旧衣和箧施，残药满瓯倾。
乳媪闲于社，医僧婗似酲。
悯渠身觉剩，讶佛力难争。
骑竹痴犹子，牵车小外甥。
等长迷过影，遥戏误啼声。
涴纸伤余画，扶床念试行。
独留呵面镜，谁弄倚墙筝。
忆昨工言语，怜初妙长成。
撩风妬鹦舌，凌露触兰英。
翠凤舆真女，红蕖捧化生。
秪忧嫌五浊，终恐向三清。
宿恶诸荤味，悬知众物名。
环从枯树得，经认宝函盛。
愠怒偏憎数，分张雅爱平。
最怜贪栗妹，频救嬾书兄。
为占娇饶分，良多眷恋诚。
别常回面泣，归定出门迎。
解怪还家晚，长将远信呈。
说人偷罪过，要我抱纵横。
腾蹋游江舫，攀缘看乐棚。
和蛮歌字拗，学妓舞腰轻。
迢遰离荒服，提携到近京。
未容夸伎俩，唯恨枉聪明。
往绪心千结，新丝鬓百茎。
暗窗风报晓，秋幌雨闻更。
败槿萧疎馆，衰杨破坏城。
此中临老泪，仍自哭孩婴。','',''),('quantangshi-21343','哭子十首 一','稹','quantangshi','','卷22','维鹈受刺因吾过，得马生灾念尔冤。
独在中庭倚闲树，乱蝉嘶噪欲黄昏。','',''),('quantangshi-21344','哭子十首 二','稹','quantangshi','','卷22','才能辨别东西位，未解分明管带身。
自食自眠犹未得，九重泉路托何人。','',''),('quantangshi-21345','哭子十首 三','稹','quantangshi','','卷22','尔母溺情连夜哭，我身因事有时悲。
钟声欲绝东方动，便是寻常上学时。','',''),('quantangshi-21346','哭子十首 四','稹','quantangshi','','卷22','莲花上品生真界，兜率天中离世途。
彼此业缘多障碍，不知还得见儿无。','',''),('quantangshi-21347','哭子十首 五','稹','quantangshi','','卷22','节量棃栗愁生疾，教示诗书望早成。
鞭扑校多怜校少，又缘遗恨哭三声。','',''),('quantangshi-21348','哭子十首 六','稹','quantangshi','','卷22','深嗟尔更无兄弟，自叹予应绝子孙。
寂寞讲堂基址在，何人车马入高门。','',''),('quantangshi-21349','哭子十首 七','稹','quantangshi','','卷22','往年鬓已同潘岳，垂老年教作邓攸。
烦恼数中除一事，自兹无复子孙忧。','',''),('quantangshi-21350','哭子十首 八','稹','quantangshi','','卷22','长年苦境知何限，岂得因儿独丧明。
消遣又来缘尔母，夜深和泪有经声。','',''),('quantangshi-21351','哭子十首 九','稹','quantangshi','','卷22','乌生八子今无七，猿呌三声月正孤。
寂寞空堂天欲曙，拂帘双燕引新雏。','',''),('quantangshi-21352','哭子十首 十','稹','quantangshi','','卷22','频频子落长江水，夜夜巢边旧处栖。
若是愁肠终不断，一年添得一声啼。','',''),('quantangshi-21353','感逝','稹','quantangshi','','卷22','头白夫妻分无子，谁令兰梦感衰翁。
三声啼妇卧床上，一寸断肠埋土中。
蜩甲暗枯秋叶坠，燕雏新去夜巢空。
情知此恨人皆有，应与暮年心不同。','',''),('quantangshi-21354','妻满月日相唁','稹','quantangshi','','卷22','十月辛勤一月悲，今朝相见泪淋漓。
狂风落尽莫惆怅，犹胜因花压折枝。','',''),('quantangshi-21355','代曲江老人百韵','稹','quantangshi','','卷22','何事花前泣，曾逢旧日春。
先皇初在镐，贱子正游秦。
拨乱干戈后，经文礼乐辰。
徽章悬象魏，貔虎画骐驎。
光武休言战，唐尧念睦姻。
琳琅铺柱础，葛藟茂河漘。
尚齿敦耆艾，搜材拔积薪。
裴王持藻镜，姚宋斡陶钧。
内史称张敞，苍生借寇恂。
名卿唯讲德，命士耻忧贫。
