悬金收逸骥，鼓瑟荐嘉宾。
羽翼皆随凤，圭璋肯杂珉。
班行容济济，文质道彬彬。
百度依皇极，千门辟紫宸。
措刑非苟简，稽古蹈因循。
书谬偏求伏，诗亡远听申。
雄推三虎贾，羣擢八龙荀。
