儒林精阃奥，流品重清淳。
天净三光丽，时和四序均。
卑官休力役，蠲赋免艰辛。
蛮貊同车轨，乡原尽里仁。
帝途高荡荡，风俗厚誾誾。
暇日耕耘足，丰年雨露频。
戍烟生不见，村竖老犹纯。
耒耜勤千亩，牲牢奉六禋。
