沃土心逾炽，豪家礼渐湮。
老农羞荷锸，贪贾学垂绅。
曲艺争工巧，雕机变组紃。
青凫连不解，红粟朽相因。
山泽长孳货，梯航竞献珍。
翠毛开越巂，龙眼弊瓯闽。
玉馔薪然蜡，椒房烛用银。
铜山供横赐，金屋贮宜嚬。
班女恩移赵，思王赋感甄。
辉光随顾步，生死属摇唇。
世族功勋久，王姬宠爱亲。
街衢连甲第，冠盖拥朱轮。
大道垂珠箔，当垆踏锦茵。
轩车隘南陌，钟磬满西邻。
出入张公子，骄奢石季伦。
鸡场潜介羽，马埒并扬尘。
韬袖夸狐腋，弓弦尚鹿𦟘。
紫绦牵白犬，绣䪜被花駰。
箭倒南山虎，鹰擒东郭㕙。
翻身迎过雁，劈肘取廻鹑。
竟蓄朱公产，争藏邴氏缗。
桥桃矜马鹜，倚顿数牛犉。
齑鬬冬中韭，羹怜远处莼。
万钱才下筯，五酘未称醇。
曲水闲销日，倡楼醉度旬。
探丸依郭解，投辖伴陈遵。
共谓长之泰，那知遽构屯。
奸心兴桀黠，凶丑比顽嚚。
斗柄侵妖彗，天泉化逆鳞。
背恩欺乃祖，连祸及吾民。
䝟貐当前路，鲸鲵得要津。
王师才业业，暴卒已䖜䖜。
杂虏同谋夏，宗周蹔去豳。
陵园深暮景，霜露下秋旻。
凤阙悲巢鵩，鵷行乱野麏。
华林荒茂草，寒竹碎贞筠。
村落空垣坏，城隍旧井堙。
破船沉古渡，战鬼聚阴磷。
振臂谁相应，攒眉独不伸。
毁容怀赤绂，混迹戴黄巾。
木梗随波荡，桃源斅隐沦。
