忽遇山光澈，遥瞻海气真。
祕图推废[主]，后圣合经纶。
野杏浑休植，幽兰不复纫。
但惊心愤愤，谁恋水粼粼。
尽室离深洞，轻桡荡小䑳。
殷勤题白石，怅望出青苹。
梦寐平生在，经过处所新。
阮郎迷里巷，辽鹤记城闉。
虚过休明代，旋为朽病身。
劳生常矻矻，语旧苦谆谆。
晚岁多衰柳，先秋愧大椿。
眼前年少客，无复昔时人。','',''),('quantangshi-21356','开元观闲居酬吴士矩侍御三十韵','稹','quantangshi','','卷22','静习狂心尽，幽居道气添。
神编启黄简，祕箓捧朱签。
烂熳烟霞驻，优游岁序淹。
