禹步星纲动，焚符竈鬼詹。
冥搜呼直使，章奏役飞廉。
仙籍聊凭检，浮名复为占。
赤诚祈皓鹤，绿发代青缣。
虚室常怀素，玄关屡引枮。
貂蝉徒自宠，鸥鹭不相嫌。
始悟身为患，唯欣禄未恬。
龟龙恋淮海，鸡犬傍闾阎。
松笠新偏翠，山峰远更尖。
箫声吟茂竹，虹影逗虚檐。
初日先通牖，轻飔每透帘。
露盘朝滴滴，钩月夜纤纤。
已得餐霞味，应嗤食蓼甜。
工琴闲度昼，耽酒醉销炎。
几案随宜设，诗书逐便拈。
灌园多抱瓮，刈藿乍腰镰。
野鸟终难絷，鹪鹩本易厌。
风高云远逝，波骇鲤深潜。
邸第过从隔，蓬壶梦寐瞻。
所希颜颇练，谁恨突无黔。
思拙慙圭璧，词烦杂米盐。
谕锥言太小，求药意何谦。
语默君休问，行藏我讵兼。
狂歌终此曲，情尽口长箝。','',''),('quantangshi-21357','病减逢春期白二十二辛大不至十韵','稹','quantangshi','','卷22','病与穷阴退，春从血气生。
寒肤渐舒展，阳脉乍虚盈。
就日临堦坐，扶牀履地行。
问人知面瘦，祝鸟愿身轻。
风暖牵诗兴，时新变卖声。
饥馋看药忌，闲闷点书名。
旧雪依深竹，微和动早萌。
推迁悲往事，疎数辨交情。
琴待嵇中散，杯思阮步兵。
世间除却病，何者不营营。','',''),('quantangshi-21358','黄明府诗','稹','quantangshi','','卷22','少年曾痛饮，黄令苦飞觥。
席上当时走，马前今日迎。
依稀迷姓氏，积渐识平生。
故友身皆远，他乡眼暂明。
便邀连榻坐，兼共榜船行。
酒思临风乱，霜棱埽地平。
不堪深浅酌，贪怆古今情。
逦迤七盘路，坡陁数丈城。
花疑褒女笑，栈想武侯征。
一种埋幽石，老闲千载名。','',''),('quantangshi-21359','酬翰林白学士代书一百韵','稹','quantangshi','','卷22','昔岁俱充赋，同年遇有司。
八人称迥拔，两郡滥相知。
逸骥初翻步，鞲鹰暂脱羁。
远途忧地窄，高视觉天卑。
并入红兰署，偏亲白玉规。
近朱怜冉冉，伐木愿偲偲。
鱼鲁非难识，铅黄自嬾持。
心轻马融帐，谋夺子房帷。
秀发幽岩电，清澄隘岸陂。
九霄排直上，万里整前期。
勇赠栖鸾句，慙当古井诗。
多闻全受益，择善颇相师。
脱俗殊常调，潜工大有为。
还醇凭酎酒，运智托围棊。
情会招车胤，闲行觅戴逵。
僧餐月灯阁，醵宴劫灰池。
胜概争先到，篇章竞出奇。
输赢论破的，点窜肯容丝。
山岫当街翠，墙花拂面枝。
莺声爱娇小，燕翼翫逶迤。
辔为逢车缓，鞭缘趂伴施。
密携长上乐，偷宿静坊姬。
僻性慵朝起，新晴助晚嬉。
相欢常满目，别处鲜开眉。
翰墨题名尽，光阴听话移。
绿袍因醉典，乌帽逆风遗。
暗插轻筹箸，仍提小屈巵。
本弦才一举，下口已三迟。
逃席冲门出，归倡借马骑。
狂歌繁节乱，醉舞半衫垂。
散漫纷长薄，邀遮守隘岐。
几遭朝士笑，兼任巷童随。
苟务形骸达，浑将性命[推]。
何曾爱官序，不省计家资。
忽悟成虚掷，翻然叹未宜。
使回躭乐事，坚赴策贤时。
寝食都忘倦，园庐遂绝闚。
劳神甘戚戚，攻短过孜孜。
叶怯穿杨箭，囊藏透頴锥。
超遥望云雨，摆落占泉坻。
略削荒凉苑，搜求激直词。
那能作牛后，更拟助洪基。
唱第听鸡集，趋朝忘马疲。
内人舆御案，朝景丽神旗。
首被呼名姓，多慙冠等衰。
千官容眷盼，五色照离披。
鵷侣从兹洽，鸥情转自縻。
分张殊品命，中外却驱驰。
出入称金籍，东西侍碧墀。
鬬班云汹涌，开扇雉参差。
切愧寻常质，亲瞻咫尺姿。
日轮光照耀，龙服瑞葳蕤。
誓欲通愚謇，生憎效喔咿。
佞存真妾妇，谏死是男儿。
便殿承偏召，权臣惧挠私。
庙堂虽稷契，城社有狐狸。
似锦言应巧，如弦数易欺。
敢嗟身暂黜，所恨政无毗。
谬辱良由此，升腾亦在斯。
再令陪宪禁，依旧履阽危。
使蜀常緜远，分台更嶮巇。
匿奸劳发掘，破党恶持疑。
斧刃迎皆碎，盘牙老未萎。
乍能还帝笏，讵忍折吾支。
虎尾元来险，圭文却类疵。
浮荣齐壤芥，闲气咏江蓠。
阙下殷勤拜，樽前啸傲辞。
飘沈委蓬梗，忠信敌蛮夷。
戏诮青云驿，讥题皓发祠。
贪过谷隐寺，留读岘山碑。
草没章台址，堤横楚泽湄。
野莲侵稻陇，亚柳压城陴。
遇物伤凋换，登楼思漫弥。
金攒嫩橙子，瑿泛远鸬鹚。
仰竹藤缠屋，苫茆荻补篱。
麪梨通蔕朽，火米带芒炊。
苇笋针筒束，鯾鱼箭羽鬐。
芋羹真底可，鲈鲙漫劳思。
北渚销魂望，南风着骨吹。
度梅衣色渍，食稗马蹄羸。
院榷和泥硷，官酤小麴醨。
讹音烦缴绕，轻俗丑威仪。
树罕贞心柏，畦丰卫足葵。
坳洼饶尰矮，游惰压庸缁。
病赛乌称鬼，巫占瓦代龟。
连阴蛙张王，瘴疟雪治医。
我正穷于是，君宁念及兹。
一篇从日下，双鲤送天涯。
坐捧迷前席，行吟忘结綦。
匡床铺错绣，几案踊灵芝。
形影同初合，参商喻此离。
扇因秋弃置，镜异月盈亏。
壮志诚难夺，良辰岂复追。
甯牛终夜永，潘鬓去年衰。
溟渤深那测，穹苍意在谁。
驭方轻騕褭，车肯重辛夷。
卧辙希濡沫，低颜受颔颐。
世情焉足怪，自省固堪悲。
溷鼠虚求洁，笼禽方讶饥。
犹胜忆黄犬，幸得早图之。','',''),('quantangshi-21360','纪怀赠李六户曹崔二十功曹五十韵','稹','quantangshi','','卷22','昔冠诸生首，初因三道征。
公卿碧墀会，名姓白麻称。
日月光遥射，烟霄志渐弘。
荣班联锦绣，谏纸赐牋藤。
便欲呈肝胆，何言犯股肱。
椎埋冲斗劒，消碎莹壶冰。
赤县才分务，青骢已迥乘。
因骑度海鹘，拟杀蔽天鹏。
缚虎声空壮，连鳌力未胜。
风翻波竟蹙，山压势逾崩。
僇辱徒相困，苍黄性不能。
酣歌离岘顶，负气入江陵。
华表当蟾魄，高楼挂玉绳。
角声悲掉荡，城影暗棱层。
军幕威容盛，官曹礼数兢。
心虽出云鹤，身尚触笼鹰。
竦足良甘分，排衙苦未曾。
通名参将校，抵掌见亲朋。
喣沫求涓滴，沧波怯斗升。
荒居邻鬼魅，羸马步殑㱥。
白草堂檐短，黄梅雨气蒸。
霑黏经汗席，颭闪尽油灯。
夜怯餐肤蚋，朝烦拂面蝇。
过从愁厌贱，专静畏猜仍。
旅寓谁堪托，官联自可凭。
甲科崔并骛，柱史李齐升。
共展排空翼，俱遭激远矰。
他乡元易感，同病转相矜。
投分多然诺，忘言少爱憎。
誓将探胏腑，耻更辨淄渑。
会宿形骸远，论交意气增。
一心吞渤澥，戮力拔嵩恒。
语到磨圭角，疑消破弩症。
吹嘘期指掌，患难许檐簦。
铩翮鸾栖棘，藏锋箭在弸。
雪中方覩桂，木上莫施罾。
且泛夤沿水，兼过被病僧。
有时鞭欵段，尽日醉儚僜。
蹑屐看秧稻，敲船和采菱。
叉鱼江火合，唤客谷神应。
啸傲虽开口，幽忧复满膺。
望云鳍拨剌，透匣色腾凌。
每想潢池寇，犹稽赤族惩。
夔龙劳算画，貔虎带威棱。
逐鸟忠潜奋，悬旌意远凝。
弢弓思彻札，绊骥闷牵緪。
运甓调辛苦，闻鸡屡寝兴。
闲随人兀兀，梦听鼓鼟鼟。
班笔行看掷，黄陂莫漫澄。
骐驎高阁上，须及壮时登。','',''),('quantangshi-21361','答姨兄胡灵之见寄五十韵','稹','quantangshi','','卷22','忆昔凤翔城，龆年是事荣。
理家烦伯舅，相宅尽吾兄。
诗律蒙亲授，朋游忝自迎。
题头筠管缦，教射角弓騂。
矮马駞鬉䪜，牦牛兽面缨。
对谈依赳赳，送客步盈盈。
米椀诸贤让，蠡杯大户倾。
一船席外语，三榼拍心精。
传盏加分数，横波掷目成。
华奴歌淅淅，媚子舞卿卿。
鬬设狂为好，谁忧饮败名。
屠过隐朱亥，楼梦古秦嬴。
环坐唯便草，投盘暂废觥。
春郊才烂熳，夕鼓已砰轰。
荏苒移灰琯，喧阗勌塞兵。
糟浆闻渐足，书劒讶无成。
抵璧慙虚弃，弹珠觉用轻。
遂笼云际鹤，来狎谷中莺。
学问攻方苦，篇章兴太清。
囊疎萤易透，锥钝股多坑。
笔阵戈矛合，文房栋桷撑。
豆萁才敏儁，羽猎正峥嵘。
岐下寻时别，京师触处行。
醉眠街北庙，闲绕宅南营。
柳爱凌寒软，梅怜上番惊。
观松青黛笠，栏药紫霞英。
尽日听僧讲，通宵咏月明。
正耽幽趣乐，旋被宦途萦。
吏晋资材枉，留秦岁序更。
我髯黳数寸，君发白千茎。
芸阁怀铅暇，姑峰带雪晴。
何由身倚玉，空覩翰飞琼。
世道难于劒，谗言巧似笙。
但憎心可转，不解跽如擎。
始效神羊触，俄随旅雁征。
孤芳安可驻，五鼎几时烹。
潦倒沉泥滓，欹危践矫衡。
登楼王粲望，落帽孟嘉情。
巫峡连天水，章台塞路荆。
雨摧渔火焰，风引竹枝声。
分作屯之蹇，那知困亦亨。
官曹三语掾，国器万寻桢。
逸杰雄姿迥，皇王雅论评。
蕙依潜可习，云合定谁令。
原燎逢冰井，鸿流值木罂。
智囊推有在，勇爵敢徒争。
迅拔看鹏举，高音侍鹤鸣。
所期人拭目，焉肯自佯盲。
铅钝丁宁淬，芜荒展转耕。
穷通须豹变，撄搏笑狼狞。
愧捧芝兰赠，还披胏腑呈。
此生如未死，未拟变平生。','',''),('quantangshi-21362','酬许五康佐','稹','quantangshi','','卷22','奋迅君何晚，羁离我讵俦。
鹤笼闲警露，鹰缚闷牵韝。
蓬阁深沈省，荆门远慢州。
课书同吏职，旅宦各乡愁。
白日伤心过，沧江满眼流。
嘶风悲代马，喘月伴吴牛。
枯涸方穷辙，生涯不系舟。
猿啼三峡雨，蝉报两京秋。
珠玉慙新赠，芝兰忝旧游。
他年问狂客，须向老农求。','',''),('quantangshi-21363','送崔侍御之岭南二十韵','稹','quantangshi','','卷22','汉法戎施幕，秦官郡置监。
萧何归旧印，鲍永授新衔。
币聘虽盈箧，泥章未破缄。
蛛悬丝缭绕，鹊报语詀諵。
再砺神羊角，重开宪简函。
鞶缨骢赳赳，緌佩绣縿縿。
逸翮怜鸿翥，离心觉刃劖。
联游亏片玉，洞照失明鉴。
遥想车登岭，那无泪满衫。
茅蒸连蟒气，衣渍度梅黬。
象鬬缘溪竹，猿鸣带雨杉。
飓风狂浩浩，韶石峻崭崭。
宿浦宜深泊，祈泷在至諴。
瘴江乘早度，毒草莫亲芟。
试蛊看银黑，排腥贵食咸。
菌须虫已蠹，菓重鸟先鹐。
冰莹怀贪水，霜清顾痛岩。
珠玑当尽掷，薏苡讵能谗。
荆俗欺王粲，吾生问季咸。
远书多不达，勤为枉攕攕。','',''),('quantangshi-21364','酬段丞与诸棊流会宿弊居见赠二十四韵','稹','quantangshi','','卷22','鸣局宁虚日，闲窗任废时。
琴书甘尽弃，园井讵能窥。
运石疑填海，争筹忆坐帷。
赤心方苦鬬，红烛已先施。
蛇势萦山合，鸿联度岭迟。
堂堂排直阵，衮衮逼羸师。
悬劫偏深猛，回征特险巇。
旁攻百道进，死战万般为。
异日玄黄队，今宵黑白棊。
斫营看迥点，对垒重相持。
善败虽称怯，骄盈最易欺。
狼牙当必碎，虎口祸难移。
乘胜同三捷，扶颠望一词。
希因送目便，敢恃指纵奇。
退引防边策，雄吟斩将诗。
眠牀都浪置，通夕共忘疲。
晓雉风传角，寒藂雪压枝。
繁星收玉版，残月耀冰池。
僧请闻钟粥，宾催下药巵。
兽炎余炭在，蜡泪短光衰。
俛仰嗟陈迹，殷勤卜后期。
公私牵去住，车马各支离。
分作终身癖，兼从是事隳。
此中无限兴，唯怕俗人知。','',''),('quantangshi-21365','酬窦校书二十韵','稹','quantangshi','','卷22','鸥鹭元相得，杯觞每共传。
芳游春烂熳，晴望月团圆。
调笑风流剧，论文属对全。
赏花珠并缀，看雪璧常连。
竹寺荒唯好，松斋小更怜。
潜投孟公辖，狂乞莫愁钱。
尘土抛书卷，枪筹弄酒权。
令夸齐箭道，力鬬抹弓弦。
但喜添樽满，谁忧乏桂然。
渐轻身外役，浑证饮中禅。
及我辞云陛，逢君仕圃田。
音徽千里断，魂梦两情偏。
足听猿啼雨，深藏马腹鞭。
官醪半清浊，夷馔杂腥膻。
顾影无依倚，甘心守静专。
那知暮江上，俱会落英前。
欵曲生平在，悲凉岁序迁。
鹤方同北渚，鸿又过南天。
丽句慙虚掷，沈机嬾强牵。
粗酬珍重意，工拙定相悬。','',''),('quantangshi-21366','泛江翫月十二韵','稹','quantangshi','','卷22','楚塞分形势，羊公压大邦。
因依多士子，参画尽敦厖。
岳璧闲相对，荀龙自有双。
共将船载酒，同泛月临江。
远树悬金镜，深潭倒玉幢。
委波添净练，洞照灭凝釭。
阗咽沙头市，𤫩珑竹岸窗。
巴童唱巫峡，海客话神泷。
已困连飞盏，犹催未倒缸。
饮荒情烂熳，风棹乐峥摐。
胜事他年忆，愁心此夜降。
知君皆逸韵，须为应莛撞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21367','痁卧闻幕中诸公征乐会饮因有戏呈三十韵','稹','quantangshi','','卷22','濩落因寒甚，沈阴与病偕。
药囊堆小案，书卷塞空斋。
胀腹看成鼓，羸形渐比柴。
道情忧易适，温瘴气难排。
治尰扶轻杖，开门立静街。
耳鸣疑暮角，眼暗助昏霾。
野竹连荒草，平陂接断崖。
坐隅甘对鵩，当路恐遭豺。
蛇蛊迷弓影，雕翎落箭靫。
晚篱喧鬬雀，残菊半枯荄。
怅望悲回雁，依迟傍古槐。
一生长苦节，三省讵行怪。
奔北翻成勇，司南却是呙。
穹苍真漠漠，风雨漫喈喈。
彼美犹溪女，其谁占馆娃。
诚知通有日，太极浩无涯。
布卦求无妄，祈天愿孔皆。
藏衰谋计拙，地僻往还乖。
况羡莲花侣，方欣绮席谐。
钿车迎妓乐，银翰屈朋侪。
白紵颦歌黛，同蹄坠舞钗。
纤身霞出海，艳脸月临淮。
筹箸随宜放，投盘止罚啀。
红娘留醉打，觥使及醒差。
顾我潜孤愤，何人想独怀。
夜灯然檞叶，冻雪堕塼堦。
坏壁虚缸倚，深炉小火埋。
鼠骄衔笔砚，被冷束筋骸。
毕竟图斟酌，先须遣疠痎。
枪旗如在手，那复敢崴㠢。','',''),('quantangshi-21368','酬友封话旧叙怀十二韵','稹','quantangshi','','卷22','风波千里别，书信二年稀。
乍见悲兼喜，犹惊是与非。
身名判作梦，杯盏莫相违。
草馆同牀宿，沙头待月归。
春深乡路远，老去宦情微。
魏阙何由到，荆州且共依。
人欺翻省事，官冷易藏威。
但拟驯鸥鸟，无因用弩机。
开张图卷轴，颠倒醉衫衣。
莼菜银丝嫩，鲈鱼雪片肥。
怜君诗似涌，赠我笔如飞。
会遣诸伶唱，篇篇入禁闱。','',''),('quantangshi-21369','送王协律游杭越十韵','稹','quantangshi','','卷22','去去莫凄凄，余杭接会稽。
松门天竺寺，花洞若耶溪。
浣渚逢新艳，兰亭识旧题。
山经秦帝望，垒辨越王栖。
江树春常早，城楼月易低。
镜呈湖面出，云叠海潮齐。
章甫官人戴，莼丝姹女提。
长干迎客闹，小市隔烟迷。
纸乱红蓝压，瓯凝碧玉泥。
荆南无抵物，来日为侬携。','',''),('quantangshi-21370','送东川马逢侍御使回十韵','稹','quantangshi','','卷22','风水荆门阔，文章蜀地豪。
眼青宾礼重，眉白众情高。
思勇曾吞笔，投虚惯用刀。
词锋倚天劒，学海驾云涛。
南郡传纱帐，东方让锦袍。
旋吟新乐府，便续古离骚。
雪岸犹封草，春江欲满槽。
饯筵君置醴，随俗我哺糟。
莫叹巴三峡，休惊鬓二毛。
流年等头过，人世各劳劳。','',''),('quantangshi-21371','酬卢祕书','稹','quantangshi','','卷22','偶有冲天气，都无处世才。
未容荣路稳，先蹋祸机开。
分久沉荆掾，慙经厕柏台。
理推愁易惑，乡思病难裁。
夜伴吴牛喘，春惊朔雁回。
北人肠断送，西日眼穿颓。
唯望魂归去，那知诏下来。
涸鱼千丈水，僵燕一声雷。
幽匣提清镜，衰颜拂故埃。
梦云期紫阁，厌雨别黄梅。
亲戚迎时到，班行见处陪。
文工犹畏忌，朝士绝嫌猜。
新识蓬山杰，深交翰苑材。
连投珠作贯，独和玉成堆。
剧敌徒相轧，羸师亦自媒。
磨砻刮骨刃，翻掷委心灰。
恐被神明哭，忧为造化灾。
私调破叶箭，定饮搴旗杯。
金宝潜砂砾，芝兰似草莱。
凭君毫发鉴，莫遣翳莓苔。','',''),('quantangshi-21372','见人咏韩舍人新律诗因有戏赠','稹','quantangshi','','卷22','喜闻韩古调，兼爱近诗篇。
玉磬声声彻，金铃个个圆。
高疎明月下，细腻早春前。
花态繁于绮，闺情软似绵。
轻新便妓唱，凝妙入僧禅。
欲得人人伏，能教面面全。
延之苦拘检，摩诘好因缘。
七字排居敬，千词敌乐天。
殷勤闲太祝，好去老通川。
莫漫裁章句，须饶紫禁仙。','',''),('quantangshi-21373','奉和权相公行次临阙驿逢仆射相公归朝俄顷分途因以奉赠诗十四韵','稹','quantangshi','','卷22','帝下赤霄符，搜求造化炉。
中台归内座，太一直南都。
黄霸乘轺入，王尊叱驭趋。
万人东道送，六纛北风驱。
栈阁才倾盖，关门已合繻。
贯鱼行逦迤，交马语踟蹰。
去速熊罴兆，来驰虎豹夫。
昔怜三易地，今讶两分途。
别路环山雪，离章运寸珠。
锋铓断犀兕，波浪没蓬壶。
区宇声虽动，淮河孽末诛。
将军遥策画，师氏密訏谟。
汉上坛仍筑，褒西阵再图。
公方先二虏，何暇进愚儒。','',''),('quantangshi-21374','酬乐天东南行诗一百韵','稹','quantangshi','','卷22','我病方吟越，君行已过湖。
去应缘直道，哭不为穷途。
亚竹寒惊牖，空堂夜向隅。
暗魂思背烛，危梦怯乘桴。
坐痛筋骸憯，旁嗟物候殊。
雨蒸虫沸渭，浪涌怪睢盱。
索绠飘蚊蚋，蓬麻甃舳舻。
短檐苫稻草，微俸封渔租。
泥浦喧捞蛤，荒郊险鬬貙。
鲸吞近溟涨，猿闹接黔巫。
芒屩泅牛妇，丫头荡桨夫。
酢醅荷裹卖，醨酒水淋沽。
舞态翻鸜鹆，歌词咽鹧鸪。
夷音啼似笑，蛮语谜相呼。
江郭船添店，山城木竖郛。
吠声沙市犬，争食墓林乌。
犷俗诚堪惮，妖神甚可虞。
欲令仁渐及，已被疟潜图。
膳减思调鼎，行稀恐蠹枢。
杂莼多剖鳝，和黍半蒸菰。
绿糉新菱实，金丸小木奴。
芋羹真蹔淡，䶉炙漫涂苏。
炮鼈那胜羜，烹鯄只似鲈。
楚风轻似蜀，巴地湿如吴。
气浊星难见，州斜日易晡。
通宵但云雾，未酉即桑榆。
瘴窟蛇休蛰，炎溪暑不徂。
伥魂阴叫啸，鵩貌昼踟蹰。
乡里家藏蛊，官曹世乏儒。
敛缗偷印信，传箭作符繻。
椎髻抛巾帼，镩刀代辘轳。
当心鞙铜鼓，背弝射桑弧。
岂复民甿料，须将鸟兽驱。
是非浑并漆，词讼敢研朱。
陋室鸮窥伺，衰形蟒觊觎。
鬓毛霜点合，襟泪血痕濡。
倍忆京华伴，偏忘我尔躯。
谪居今共远，荣路昔同趋。
科试铨衡局，衙参典校厨。
月中分桂树，天上识昌蒲。
应召逢鸿泽，陪游值赐酺。
心唯撞卫磬，耳不乱齐竽。
海岱词锋截，皇王笔阵敺。
疾奔凌騕褭，高唱轧吴歈。
点检张仪舌，提携傅说图。
摆囊看利頴，开颔出明珠。
并取千人特，皆非十上徒。
白麻云色腻，墨诏电光麤。
众口贪归美，何颜敢妬姝。
秦台纳红旭，酆匣洗黄垆。
谏猎宁规避，弹豪讵嗫嚅。
胏肝憎巧曲，蹊径绝萦迂。
誓遣朝纲振，忠饶翰苑输。
骥调方汗血，蝇点忽成卢。
遂谪栖遑掾，还飞送别盂。
痛嗟亲爱隔，颠望友朋扶。
狸病翻随鼠，骢羸返作驹。
物情良狥俗，时论太诬吾。
瓶罄罍偏耻，松摧柏自枯。
虎虽遭陷穽，龙不怕泥涂。
重喜登贤苑，方欣佐伍符。
判身入矛戟，轻敌比锱铢。
驿骑来千里，天书下九衢。
因教罢飞檄，便许到皇都。
舟败罂浮汉，骖疲杖过邘。
邮亭一萧索，烽候各崎岖。
馈饷人推辂，谁何吏执殳。
拔家逃力役，连鏁责逋诛。
防戍兄兼弟，收田妇与姑。
缣缃工女竭，青紫使臣纡。
望国参云树，归家满地芜。
破窗尘𡋯𡋯，幽院鸟呜呜。
祖竹藂新笋，孙枝压旧梧。
晚花狂蛱蝶，残蒂宿茱萸。
始悟摧林秀，因衔避缴芦。
文房长遣闭，经肆未曾铺。
鵷鹭方求侣，鸱鸢已吓雏。
征还何郑重，斥去亦须臾。
迢递投遐徼，苍黄出奥区。
通川诚有咎，湓口定无辜。
利器从头匣，刚肠到底刳。
薰莸任盛贮，稊稗莫超逾。
公干经时卧，钟仪几岁拘。
光阴流似水，蒸瘴热于炉。
薄命知然也，深交有矣夫。
救焚期骨肉，投分刻肌肤。
二妙驰轩陛，三英咏袴襦。
李多嘲蝘蜓，窦数集蜘蛛。
数子皆奇货，唯予独朽株。
邯郸笑匍匐，燕蒯受揶揄。
嬾学三闾愤，甘齐百里愚。
耽眠稀醒素，凭醉少嗟吁。
学问徒为尔，书题尽已于。
别犹多梦寐，情尚感凋枯。
近喜司戎健，寻伤掌诰徂。
士元名位屈，伯道子孙无。
旧好飞琼翰，新诗灌玉壶。
几催闲处泣，终作苦中娱。
廉蔺声相让，燕秦势岂俱。
此篇应绝倒，休漫捋髭须。','',''),('quantangshi-21375','和乐天送客游岭南二十韵','稹','quantangshi','','卷22','我自离乡久，君那度岭频。
一杯魂惨澹，万里路艰辛。
江馆连沙市，泷船泊水滨。
骑田廻北顾，铜柱指南邻。
大壑浮三岛，周天过五均。
波心涌楼阁，规外布星辰。
狒狒穿筒格，猩猩置屐驯。
贡兼蛟女绢，俗重语儿巾。
舶主腰藏宝，黄家砦起尘。
歌钟排象背，炊爨上鱼身。
电白雷山接，旗红贼舰新。
岛夷徐市种，庙觋赵佗神。
鸢跕方知瘴，蛇苏不待春。
曙潮云斩斩，夜海火磷磷。
冠冕中华客，梯航异域臣。
果然皮胜锦，吉了舌如人。
风黖秋茅叶，烟埋晓月轮。
定应玄发变，焉用翠毛珍。
句漏沙须买，贪泉货莫亲。
能传稚川术，何患隐之贫。','',''),('quantangshi-21376','献荥阳公诗五十韵','稹','quantangshi','','卷22','郑驿骑翩翩，丘门子弟贤。
文翁开学日，正礼骋途年。
骏骨黄金买，英髦绛帐延。
趋风皆蹀足，侍坐各差肩。
解榻招徐穉，登楼引仲宣。
凤攒题字扇，鱼落讲经筵。
盛气河包济，贞姿岳柱天。
臯夔当五百，邹鲁重三千。
科斗翻腾取，关雎教授先。
篆垂朝露滴，诗缀夜珠联。
逸礼多心匠，焚书旧口传。
陈遵修尺牍，阮瑀让飞牋。
中的颜初启，抽毫踵未旋。
森罗万木合，属对百花全。
词海跳波涌，文星拂坐悬。
戴冯遥避席，祖逖后施鞭。
西蜀凌云赋，东阳咏月篇。
劲芟鳌足断，精贯虱心穿。
浩汗神弥王，鹞扬兴欲仙。
冰壶通皓雪，绮树眇晴烟。
驱驾雷霆走，铺陈锦绣鲜。
情机登穾奥，流韵溢山川。
墨客膺潜服，谈宾膝误前。
张鳞定摧败，折角反矜怜。
句句推琼玉，声声播管弦。
纤新撩造化，澒洞斡陶甄。
卫磬琤鍧极，齐竽僭滥偏。
空虚慙炙輠，点窜许怀铅。
惫色秋来草，哀吟雨后蝉。
自伤魂惨沮，何暇思幽玄。
喜到樽罍侧，愁亲几案边。
菁华知竭矣，胏腑尚求旃。
抵滞浑成醉，徘徊转慕膻。
老叹才渐少，闲苦病相煎。
瓦砾难追琢，刍荛分弃捐。
漫劳成恳恳，那得美娟娟。
拙劣仍非速，迂愚且异专。
移时停笔砚，挥景乏戈鋋。
仪舌忻犹在，舒帷誓不褰。
会将连献楚，深耻谬游燕。
蒲有临书叶，韦充读易编。
沙须披见宝，经拟带耕田。
入雾长期闰，持朱本望研。
轮辕呈曲直，凿枘取方圆。
呼吸宁徒尔，霑濡岂浪然。
过箫资响亮，随水涨沦涟。
惜日看圭短，偷光恨壁坚。
勤勤雕朽木，细细导蒙泉。
传癖今应甚，头风昨已痊。
丹青公旧物，一为变蚩妍。','',''),('quantangshi-21377','酬乐天江楼夜吟稹诗因成三十韵','稹','quantangshi','','卷22','忽见君新句，君吟我旧篇。
见当巴徼外，吟在楚江前。
思鄙宁通律，声清遂扣玄。
三都时觉重，一顾世称妍。
排韵曾遥答，分题几共联。
昔凭银翰写，今赖玉音宣。
布鼓随椎响，坯泥仰匠圆。
铃因风断续，珠与调牵緜。
阮籍惊长啸，商陵怨别弦。
猿羞啼月峡，鹤让警秋天。
志士潜兴感，高僧暂废禅。
兴飘沧海动，气合碧云连。
点缀工微者，吹嘘势特然。
休文徒倚槛，彦伯浪回船。
伎乐当筵唱，儿童满巷传。
改张思妇锦，腾跃贾人牋。
魏拙虚教出，曹风敢望痊。
定遭才子笑，恐赚学生癫。
裁什情何厚，飞书信不专。
隼猜鸿蓄缩，虎横犬迍邅。
水墨看虽久，琼瑶喜尚全。
才从鱼里得，便向市头悬。
夜置堂东序，朝铺座右边。
手寻韦欲绝，泪滴纸浑穿。
甘蔗销残醉，醍醐醒早眠。
深藏那遽灭，同咏苦无缘。
雅羡诗能圣，终嗟药未仙。
五千诚远道，四十已中年。
暗魄多相梦，衰容每自怜。
卒章还恸哭，蚊蚋溢山川。','',''),('quantangshi-21378','酬乐天待漏入合见赠','稹','quantangshi','','卷22','未勘银台契，先排浴殿关。
沃心因特召，[承]旨绝常班。
颭闪才人袖，呕鵶软举镮。
宫花低作帐，云从积成山。
密视枢机草，偷瞻咫尺颜。
恩垂天语近，对久漏声闲。
丹陛曾同立，金銮恨独攀。
笔无鸿业润，袍愧紫文殷。
河水通天上，瀛州接世间。','',''),('quantangshi-21379','酬乐天早春闲游西湖颇多野趣恨不得与微之同赏因思在越官重事殷镜湖之游或恐未暇因成十八韵见寄乐天前篇到时适会予亦宴镜湖南亭因述目前所睹以成酬答末章亦示暇诚则势使之然亦欲粗为恬养之赠耳','稹','quantangshi','','卷22','雁思欲回宾，风声乍变新。
各携红粉伎，俱伴紫垣人。
水面波疑縠，山腰虹似巾。
柳条黄大带，茭葑绿文茵。
雪尽才通屐，汀寒未有苹。
向阳偏晒羽，依岸小游鳞。
浦屿崎岖到，林园次第巡。
墨池怜嗜学，丹井羡登真。
雅叹游方盛，聊非意所亲。
白头辞北阙，沧海是东邻。
问俗烦江界，搜畋想渭津。
故交音讯少，归梦往来频。
独喜同门旧，皆为列郡臣。
三刀连地轴，一苇碍车轮。
尚阻青天雾，空瞻白玉尘。
龙因雕字识，犬为送书驯。
胜事无穷境，流年有限身。
嬾将闲气力，争鬬野塘春。','',''),('quantangshi-21380','江边四十韵','稹','quantangshi','','卷22','官借江边宅，天生地势坳。
敧危饶坏构，迢递接长郊。
怪鵩频栖息，跳蛙颇混肴。
总无篱缴绕，尤怕虎咆哮。
停潦鱼招獭，空仓鼠敌猫。
土虚烦穴蚁，柱朽畏藏蛟。
蛇虺吞檐雀，豺狼逐野麃。
犬惊狂浩浩，鸡乱响嘐嘐。
濩落贫甘守，荒凉秽尽包。
断帘飞熠耀，当户网蟏蛸。
曲突翻成沼，行廊却代庖。
桥横老颠枿，马病裛刍茭。
一一牀头点，连连砌下泡。
辱泥疑在绛，避雨想经崤。
相顾忧为鼈，谁能复系匏。
誓心来利往，卜食过安爻。
何计逃昏垫，移文报旧交。
栋梁存伐木，苫盖愧分茅。
金琯排黄荻，琅玕褭翠梢。
花塼水面鬬，鸳瓦玉声敲。
方础荆山采，修掾郢匠刨。
隐锥雷震蛰，破竹箭鸣骹。
正寝初停午，频眠欲转胞。
囷圆收薄禄，厨敝备嘉肴。
各各人宁宇，双双燕贺巢。
高门受车辙，华廐称蒲捎。
尺寸皆随用，毫厘敢浪抛。
篾余笼白鹤，枝剩架青䴔。
制榻容筐篚，施关拒斗筲。
栏干防汲井，密室待持胶。
庭草佣工剃，园蔬稚子掊。
本图闲种植，那要择肥硗。
绿柚勤勤数，红榴个个抄。
池清漉螃蟹，瓜蠹拾𧏘蟊。
晒篆看沙鸟，磨刀绽海鲛。
罗灰修药竈，筑垛阅弓弰。
散诞都由习，童蒙剩嬾教。
最便陶静饮，还作解愁嘲。
近浦闻归楫，遥城罢晓铙。
王孙如有问，须为并挥鞘。','',''),('quantangshi-21381','春六十韵','稹','quantangshi','','卷22','节应寒灰下，春生返照中。
未能消积雪，已渐少回风。
迎气邦经重，斋诚帝念隆。
龙骧紫宸北，天压翠坛东。
仙仗摇佳彩，荣光答圣衷。
便从威仰座，随入大罗宫。
先到璇渊底，偷穿玳瑁栊。
馆娃朝镜晚，太液晓冰融。
撩摘芳情徧，搜求好处终。
九霄浑可可，万姓尚忡忡。
昼漏频加箭，宵晖欲半弓。
驱令三殿出，乞与百蛮同。
直自方壶岛，斜临绝漠戎。
南巡暧珠树，西转丽崆峒。
度岭梅甘坻，潜泉脉暗洪。
悠悠铺塞草，冉冉着江枫。
蚕役投筐妾，耘催荷蓧翁。
既蒸难发地，仍送嬾归鸿。
约略环区宇，殷勤绮镐酆。
华山青黛扑，渭水碧沙蒙。
宿露清余霭，晴烟塞迥空。
燕巢才点缀，莺舌最惺愡。
腻粉梨园白，胭脂桃径红。
郁金垂嫩柳，罯画委高笼。
地甲门阑大，天开禁掖崇。
层台张舞凤，阁道架飞虹。
麴糵调神化，鵷鸾竭至忠。
歌钟齐锡宴，车服奖庸功。
俊造欣时用，闾阎贺岁丰。
倡楼妆㸌㸌，农野绿芃芃。
贵主骄矜盛，豪家恃赖雄。
偏霑打球彩，频得铸钱铜。
专杀擒杨若，殊恩赦邓通。
女孙新在内，婴稚近封公。
游衍关心乐，诗书对面聋。
盘筵饶异味，音乐斥庸工。
酒爱油衣浅，杯夸玛瑙烘。
挑鬟玉钗髻，刺绣宝装拢。
启齿呈编贝，弹丝动削葱。
醉圆双媚靥，波溢两明瞳。
但赏欢无极，那知恨亦充。
洞房闲窈窕，庭院独葱茏。
谢砌萦残絮，班窗网曙虫。
望夫身化石，为伯首如蓬。
顾我沉忧士，骑他老病骢。
静街乘旷荡，初日接曈昽。
饮败胏常渴，魂惊耳更聪。
虚逢好阳艳，其那苦昏懜。
僶俛还移步，持疑又省躬。
慵将疲顇质，漫走倦羸僮。
季月行当暮，良辰坐叹穷。
晋悲焚介子，鲁愿浴沂童。
燧改鲜妍火，阴繁暗澹桐。
瑞云低𢈁𢈁，香雨润蒙蒙。
药溉分窠数，篱栽备幼冲。
种莎怜见叶，护笋冀成筒。
有梦多为蝶，因搜定坐熊。
漂沈随坏芥，荣茂委苍穹。
震动风千变，晴和鹤一冲。
丁宁搴芳侣，须识未开丛。','',''),('quantangshi-21382','月三十韵','稹','quantangshi','','卷22','蓂叶标新朔，霜豪引细辉。
白眉惊半隐，虹势讶全微。
凉魄潭空洞，虚弓雁畏威。
上弦何汲汲，佳色转依依。
绮幕残灯敛，妆楼破镜飞。
玲珑穿竹树，岑寂思幈帏。
坐爱规将合，行看望已几。
绛河冰鉴朗，黄道玉轮巍。
迥照偏琼砌，余光借粉闱。
泛池相皎洁，压桂共芳菲。
的的当歌扇，娟娟透舞衣。
殷勤入怀什，恳款堕云圻。
素液传烘盏，鸣琴荐碧徽。
椒房深肃肃，兰路霭霏霏。
翡翠通帘影，琉璃莹殿扉。
西园筵玳瑁，东壁射蛜蝛。
老将占天阵，幽人钓石矶。
荷锄元亮息，回棹子猷归。
迢递同千里，孤高净九围。
从星作风雨，配日丽旌旗。
麟鬬宁徒设，蝇声岂浪讥。
司存委卿士，新拜出郊畿。
今古虽云极，亏盈不易违。
珠胎方夜满，清露忍朝曦。
渐减姮娥面，徐收楚练机。
卞疑雕璧碎，潘感竟牀稀。
捐箧辞班女，潜波蔽虙妃。
氛埃谁定灭，蟾兔杳难希。
须遣圆明尽，良嗟造化非。
如能付刀尺，别为创璇玑。','',''),('quantangshi-21383','饮致用神麴酒三十韵','稹','quantangshi','','卷22','七月调神麴，三春酿绿醽。
雕镌荆玉盏，烘透内丘瓶。
试滴盘心露，疑添案上萤。
满尊凝止水，祝地落繁星。
翻陋琼浆浊，唯闻石髓馨。
冰壶通角簟，金镜彻云屏。
雪暎烟光薄，霜涵霁色泠。
蚌珠悬皎皛，桂魄倒瀴溟。
昼洒蝉将饮，宵挥鹤误聆。
琉璃惊太白，钟乳讶微青。
讵敢辞濡首，并怜可鉴形。
行当遣俗累，便得造禅扃。
何惮说千日，甘从过百龄。
但令长泛蚁，无复恨漂萍。
胆壮还增气，机忘反自冥。
瓮眠思毕卓，糟籍忆刘伶。
仿髴中圣日，希夷夹大庭。
眼前须底物，座右任他铭。
刮骨都无痛，如泥未拟停。
残觞犹漠漠，华烛已荧荧。
真性临时见，狂歌半睡听。
喧阗争意气，调笑学娉婷。
酩酊焉知极，羇离忽暂宁。
鸡声催欲曙，蟾影照初醒。
咽绝鹃啼竹，萧撩雁去汀。
遥城传漏箭，乡寺响风铃。
楚泽一为梗，尧阶屡变蓂。
醉荒非独此，愁梦几曾经。
每耻穷途哭，今那客泪零。
感君澄醴酒，不遣渭和泾。','',''),('quantangshi-21384','感石榴二十韵','稹','quantangshi','','卷22','何年安石国，万里贡榴花。
迢递河源道，因依汉使槎。
酸辛犯葱岭，顦顇涉龙沙。
初到摽珍木，多来比乱麻。
深抛故园里，少种贵人家。
唯我荆州见，怜君胡地赊。
从教当路长，兼恣入檐斜。
绿叶裁烟翠，红英动日华。
新帘帬透影，疎牖烛笼纱。
委作金炉焰，飘成玉砌瑕。
乍惊珠缀密，终误绣帏奢。
琥珀烘梳碎，燕支嬾颊涂。
风翻一树火，电转五云车。
绛帐迎宵日，芙蕖绽早牙。
浅深俱隐映，前后各分葩。
宿露低莲脸，朝光借绮霞。
暗虹徒缴绕，濯锦莫周遮。
俗态能嫌旧，芳姿尚可嘉。
非专爱颜色，同恨阻幽遐。
满眼思乡泪，相嗟亦自嗟。','',''),('quantangshi-21385','度门寺','稹','quantangshi','','卷22','北祖三禅地，西山万树松。
门临溪一带，桥映竹千重。
翦凿基阶正，包藏景气浓。
诸岩分院宇，双岭抱垣墉。
舍利开层墖，香炉占小峰。
道场居士置，经藏大师封。
太子知栽植，神王守要冲。
由旬排讲座，丈六写真容。
佛语迦陵说，僧行猛虎从。
修罗抬日拒，楼至拔霜锋。
画井垂枯朽，穿池救噞喁。
蕉非难败坏，槿喻暂丰茸。
宝界留遗事，金棺灭去踪。
钵传烘玛瑙，石长翠芙蓉。
影帐纱全落，绳牀土半壅。
荒林迷醉象，危壁亚盘龙。
行色怜初月，归程待晓钟。
心源虽了了，尘世苦憧憧。
宿荫高声忏，斋粮并力舂。
他生再来此，还愿总相逢。','',''),('quantangshi-21386','大云寺二十韵','稹','quantangshi','','卷22','地胜宜台殿，山晴离垢氛。
现身千佛国，护世四王军。
碧耀高楼瓦，赬飞半壁文。
鹤林萦古道，雁墖没归云。
幡影中天扬，钟声下界闻。
攀萝极峰顶，游目到江濆。
驯鸽闲依缀，调猿静守羣。
虎行风捷猎，龙睡气氛氲。
获稻禅衣卷，烧畲劫火焚。
新英蜂采掇，荒草象耕耘。
钵付灵童洗，香教善女熏。
果枝低罯罯，花雨泽雰雰。
示化维摩疾，降魔力士勋。
听经神变见，说偈鸟纷纭。
上境光犹在，深溪暗不分。
竹笼烟欲暝，松带日余曛。
真谛成知别，迷心尚有云。
多生沈五蕴，宿习乐三坟。
谕鹿车虽设，如蚕绪正棼。
且将平等义，还奉圣明君。','',''),('quantangshi-21387','和友封题开善寺十韵','稹','quantangshi','','卷22','梁王开佛庙，云构岁时遥。
珠缀飞闲鸽，红泥落碎椒。
灯笼青焰短，香印白灰销。
古匣收遗施，行廊画本朝。
藏经霑雨烂，魔女捧花娇。
亚树牵藤阁，横查压石桥。
竹荒新笋细，池浅小鱼跳。
匠正琉璃瓦，僧锄芍药苗。
旋蒸茶嫩叶，偏把柳长条。
便欲忘归路，方知隐易招。','',''),('quantangshi-21388','牡丹二首 一','稹','quantangshi','','卷22','簇蘂风频坏，裁红雨更新。
眼看吹落地，便别一年春。','',''),('quantangshi-21389','牡丹二首 二','稹','quantangshi','','卷22','繁绿阴全合，衰红展渐难。
风光一抬举，犹得暂时看。','',''),('quantangshi-21390','象人','稹','quantangshi','','卷22','被色空成象，观空色异真。
自悲人是假，那复假为人。','',''),('quantangshi-21391','与杨十二巨源卢十九经济同游大安亭各赋二物各为五韵探得松石','稹','quantangshi','','卷22','片石与孤松，曾经物外逢。
月临栖鹤影，云抱老人峰。
蜀客君当问，秦官我旧封。
积膏当琥珀，新劫长芙蓉。
待补苍苍去，樛柯早变龙。','',''),('quantangshi-21392','赋得春雪映早梅','稹','quantangshi','','卷22','飞舞先春雪，因依上番梅。
一枝方渐秀，六出已同开。
积素光逾密，真花节暗催。
抟风飘不散，见晛忽偏摧。
郢曲琴空奏，羌音笛自哀。
今朝两成咏，翻挟昔人才。','',''),('quantangshi-21393','赋得玉巵无当','稹','quantangshi','','卷22','共惜连城宝，翻成无当巵。
讵慙君子贵，深讶巧工隳。
泛蚁功全小，如虹色不移。
可怜殊砾石，何计辨糟醨。
江海诚难满，盘筵莫忘施。
纵乖斟酌意，犹得对光仪。','',''),('quantangshi-21394','赋得数蓂','稹','quantangshi','','卷22','将课司天历，先观近砌蓂。
一旬开应月，五日数从星。
桂满丛初合，蟾亏影渐零。
辨时长有素，数闰或余青。
坠叶推前事，新芽察未形。
尧年始今岁，方欲瑞千龄。','',''),('quantangshi-21395','赋得九月尽','稹','quantangshi','','卷22','霜降三旬后，蓂余一叶秋。
玄阴迎落日，凉魄尽残钓。
半夜灰移琯，明朝帝御裘。
潘安过今夕，休咏赋中愁。','',''),('quantangshi-21396','赋得雨后花','稹','quantangshi','','卷22','红芳怜静色，深与雨相宜。
余滴下纤蘂，残珠堕细枝。
浣花江上思，啼粉镜中窥。
念此低回久，风光幸一吹。','',''),('quantangshi-21397','早归','稹','quantangshi','','卷22','春静晓风微，凌晨带酒归。
远山笼宿雾，高树影朝晖。
饮马鱼惊水，穿花露滴衣。
娇莺似相恼，含啭傍人飞。','',''),('quantangshi-21398','晚秋','稹','quantangshi','','卷22','竹露滴寒声，离人晓思惊。
酒醒秋簟冷，风急夏衣轻。
寝倦解幽梦，虑闲添远情。
谁怜独欹枕，斜月透窗明。','',''),('quantangshi-21399','送林复梦赴韦令辟','稹','quantangshi','','卷22','蜀路危于劒，怜君自坦途。
几回曾啖炙，千里远衔珠。
野性便荒饮，时风忌酒徒。
相门多礼让，前后莫相逾。','',''),('quantangshi-21400','忆杨十二','稹','quantangshi','','卷22','杨子爱言诗，春天好咏时。
恋花从马滞，联句放杯迟。
日映含烟竹，风牵卧柳丝。
南山更多兴，须作白云期。','',''),('quantangshi-21401','夜合','稹','quantangshi','','卷22','绮树满朝阳，融融有露光。
雨多疑濯锦，风散似分妆。
叶密烟蒙火，枝低绣拂墙。
更怜当暑见，留咏日偏长。','',''),('quantangshi-21402','新竹','稹','quantangshi','','卷22','新篁才解箨，寒色已青葱。
冉冉偏凝粉，萧萧渐引风。
扶疎多透日，寥落未成丛。
惟有团团节，坚贞大小同。','',''),('quantangshi-21403','秋相望','稹','quantangshi','','卷22','檐月惊残梦，浮凉满夏衾。
蟏蛸低户网，萤火度墙阴。
炉暗灯光短，牀空帐影深。
此时相望久，高树忆横岑。','',''),('quantangshi-21404','春病','稹','quantangshi','','卷22','病来闲卧久，因见静时心。
残月晓窗迥，落花幽院深。
望山移坐榻，行药步墙阴。
车马门前度，遥闻哀苦吟。','',''),('quantangshi-21405','山竹枝','稹','quantangshi','','卷22','深院虎溪竹，远公身自栽。
多慙折君节，扶我出山来。
贵宅安危步，难将混俗材。
还投辋川水，从作老龙回。','',''),('quantangshi-21406','悟禅三首寄胡果 一','稹','quantangshi','','卷22','近闻胡隐士，潜认得心王。
不恨百年促，翻悲万劫长。
有修终有限，无事亦无殃。
慎莫通方便，应机不顿忘。','',''),('quantangshi-21407','悟禅三首寄胡果 二','稹','quantangshi','','卷22','百年都几日，何事苦嚣然。
晚岁倦为学，闲心易到禅。
病宜多宴坐，贫似少攀缘。
自笑无名字，因名自在天。','',''),('quantangshi-21408','悟禅三首寄胡果 三','稹','quantangshi','','卷22','近见新章句，因知见在心。
春游晋祠水，晴上霍山岑。
问法僧当偈，还丹客赠金。
莫惊头欲白，禅观老弥深。','',''),('quantangshi-21409','东台去','稹','quantangshi','','卷22','陶君喜不遇，予每为君言。
今日东台去，澄心在陆浑。
旋抽随日俸，并买近山园。
千万崔兼白，殷勤承主恩。','',''),('quantangshi-21410','戴光弓','稹','quantangshi','','卷22','潞府筋角劲，戴光因合成。
因君怀胆气，赠我定交情。
不拟闲穿叶，那能枉始生。
唯调一只箭，飞入破聊城。','',''),('quantangshi-21411','刘颇诗','稹','quantangshi','','卷22','一言感激士，三世义忠臣。
破瓮嫌妨路，烧庄耻属人。
迥分辽海气，闲蹋洛阳尘。
傥使权由我，还君白马津。','',''),('quantangshi-21412','夜饮','稹','quantangshi','','卷22','灯火隔帘明，竹梢风雨声。
诗篇随意赠，杯酒越巡行。
漫唱江朝曲，闲征药草名。
莫辞终夜饮，朝起又营营。','',''),('quantangshi-21413','襃城驿','稹','quantangshi','','卷22','严秦修此驿，兼涨驿前池。
已种千竿竹，又栽千树棃。
四年三月半，新笋晚花时。
怅望东川去，等闲题作诗。','',''),('quantangshi-21414','闲二首 一','稹','quantangshi','','卷22','暗澹洲烟白，篱筛日脚红。
江喧过云雨，船泊打头风。
艇子收鱼市，鸦儿噪荻丛。
不堪堤上立，满眼是蚊虫。','',''),('quantangshi-21415','闲二首 二','稹','quantangshi','','卷22','青衫经夏黕，白发望乡稠。
雨冷新秋簟，星稀欲曙楼。
连鸿尽南去，双鲤本东流。
北信无人寄，蝉声满树头。','',''),('quantangshi-21416','欲曙','稹','quantangshi','','卷22','江堤阅暗流，漏鼓急残筹。
片月低城堞，稀星转角楼。
鹤媒华表上，{篦𥫗+鸟}鵊柳枝头。
不为来趋府，何因欲曙游。','',''),('quantangshi-21417','寄胡灵之','稹','quantangshi','','卷22','早岁颠狂伴，城中共几年。
有时潜步出，连夜小亭眠。
月影侵牀上，花丛在眼前。
今宵正风雨，空宅楚江边。','',''),('quantangshi-21418','夜雨','稹','quantangshi','','卷22','水怪潜幽草，江云拥废居。
雷惊空屋柱，电照满牀书。
竹瓦风频裂，茅檐雨渐疎。
平生沧海意，此去怯为鱼。','',''),('quantangshi-21419','酬李六醉后见寄口号','稹','quantangshi','','卷22','顿愈头风疾，因吟口号诗。
文章纷似绣，珠玉布如棊。
健羡觥飞酒，苍黄日映篱。
命童寒色倦，抚穉晚啼饥。
潦倒慙相识，平生颇自奇。
明公将有问，林下是灵龟。','',''),('quantangshi-21420','归田','稹','quantangshi','','卷22','陶君三十七，挂绶出都门。
我亦今年去，商山淅岸邨。
冬修方丈室，春种桔橰园。
千万人间事，从兹不复言。','',''),('quantangshi-21421','缘路','稹','quantangshi','','卷22','总是玲珑竹，兼藏浅漫溪。
沙平深见底，石乱不成泥。
烟火遥邨落，桑麻隔稻畦。
此中如有问，甘被到头迷。','',''),('quantangshi-21422','诮卢戡与予数约游三寺戡独沈醉而不行','稹','quantangshi','','卷22','乘兴无羁束，闲行信马蹄。
路幽穿竹远，野迥望云低。
素帚茅花乱，圆珠稻实齐。
如何卢进士，空恋醉如泥。','',''),('quantangshi-21423','遣春三首 一','稹','quantangshi','','卷22','杨公三不惑，我惑两般全。
逢酒判身病，拈花尽意怜。
水生低岸没，梅蹙小珠连。
千万红颜辈，须惊又一年。','',''),('quantangshi-21424','遣春三首 二','稹','quantangshi','','卷22','柳眼开浑尽，梅心动已阑。
风光好时少，杯酒病中难。
学问慵都废，声名老更判。
唯余看花伴，未免忆长安。','',''),('quantangshi-21425','遣春三首 三','稹','quantangshi','','卷22','失却游花伴，因风浪引将。
柳堤遥认马，梅径误寻香。
晚景行看谢，春心渐欲狂。
园林都不到，何处枉风光。','',''),('quantangshi-21426','岁日','稹','quantangshi','','卷22','一日今年始，一年前事空。
凄凉百年事，应与一年同。','',''),('quantangshi-21427','湘南登临湘楼','稹','quantangshi','','卷22','高处望潇湘，花时万井香。
雨余怜日嫩，岁闰觉春长。
霞刹分危牓，烟波透远光。
情知楼上好，不是仲宣乡。','',''),('quantangshi-21428','晚宴湘亭','稹','quantangshi','','卷22','晚日宴清湘，晴空走艳阳。
花低愁露醉，絮起觉春狂。
舞旋红裙急，歌垂碧袖长。
甘心出童羖，须一尽时荒。','',''),('quantangshi-21429','酒醒','稹','quantangshi','','卷22','饮醉日将尽，醒时夜已阑。
暗灯风焰晓，春席水窗寒。
未解萦身带，犹倾坠枕冠。
呼儿问狼藉，疑是梦中欢。','',''),('quantangshi-21430','独游','稹','quantangshi','','卷22','远地难逢侣，闲人且独行。
上山随老鹤，接酒待残鸎。
花当西施面，泉胜卫玠清。
鹈鹕满春野，无限好同声。','',''),('quantangshi-21431','洞庭湖','稹','quantangshi','','卷22','人生除泛海，便到洞庭波。
驾浪沉西日，吞空接曙河。
虞巡竟安在，轩乐讵曾过。
唯有君山下，狂风万古多。','',''),('quantangshi-21432','雪天','稹','quantangshi','','卷22','故乡千里梦，往事万重悲。
小雪沈阴夜，闲窗老病时。
独闻归去雁，偏咏别来诗。
惭愧红妆女，频惊两鬓丝。','',''),('quantangshi-21433','赠熊士登','稹','quantangshi','','卷22','平生本多思，况复老逢春。
今日梅花下，他乡值故人。','',''),('quantangshi-21434','别岭南熊判官','稹','quantangshi','','卷22','十年常远道，不忍别离声。
况复三巴外，仍逢万里行。
桐花新雨气，梨叶晚春晴。
到海知何日，风波从此生。','',''),('quantangshi-21435','水上寄乐天','稹','quantangshi','','卷22','眼前明月水，先入汉江流。
汉水流江海，西江过庾楼。
庾楼今夜月，君岂在楼头。
万一楼头望，还应望我愁。','',''),('quantangshi-21436','夏阳亭临望寄河阳侍御尧','稹','quantangshi','','卷22','望远音书绝，临川意绪长。
殷勤眼前水，千里到河阳。','',''),('quantangshi-21437','日高睡','稹','quantangshi','','卷22','隔是身如梦，频来不为名。
怜君近南住，时得到山行。','',''),('quantangshi-21438','辋川','稹','quantangshi','','卷22','世累为身累，闲忙不自由。
殷勤辋川水，何事出山流。','',''),('quantangshi-21439','天坛归','稹','quantangshi','','卷22','为结区中累，因辞洞里花。
还来旧城郭，烟火万人家。','',''),('quantangshi-21440','雨后','稹','quantangshi','','卷22','倦寝数残更，孤灯暗又明。
竹梢余雨重，时复拂帘惊。','',''),('quantangshi-21441','晴日','稹','quantangshi','','卷22','多病苦虚羸，晴明强展眉。
读书心绪少，闲卧日长时。','',''),('quantangshi-21442','直台','稹','quantangshi','','卷22','麋入神羊队，乌惊海鹭眠。
仍教百余日，迎送直厅前。','',''),('quantangshi-21443','行宫','稹','quantangshi','','卷22','寥落古行宫，宫花寂寞红。
白头宫女在，闲坐说玄宗。','',''),('quantangshi-21444','醉行','稹','quantangshi','','卷22','秋风方索漠，霜貌足暌携。
今日骑骢马，街中醉蹋泥。','',''),('quantangshi-21445','指巡胡','稹','quantangshi','','卷22','遣闷多凭酒，公心只仰胡。
挺身唯直指，无意独欺愚。','',''),('quantangshi-21446','饮新酒','稹','quantangshi','','卷22','闻君新酒熟，况值菊花秋。
莫怪平生志，图销尽日愁。','',''),('quantangshi-21447','香球','稹','quantangshi','','卷22','顺俗唯团转，居中莫动摇。
爱君心不恻，犹讶火长烧。','',''),('quantangshi-21448','景申秋八首 一','稹','quantangshi','','卷22','年年秋意绪，多向雨中生。
渐欲烟火近，稍怜衣服轻。
咏诗闲处立，忆事夜深行。
濩落寻常惯，凄凉别为情。','',''),('quantangshi-21449','景申秋八首 二','稹','quantangshi','','卷22','蚊幌雨来卷，烛蛾灯上稀。
啼儿冷秋簟，思妇问寒衣。
帘断萤火入，窗明蝙蝠飞。
良辰日夜去，渐与壮心违。','',''),('quantangshi-21450','景申秋八首 三','稹','quantangshi','','卷22','嗢嗢檐溜凝，丁丁窗雨繁。
枕倾筒簟滑，幔颭案灯翻。
唤魇儿难觉，吟诗婢苦烦。
强眠终不着，闲卧暗消魂。','',''),('quantangshi-21451','景申秋八首 四','稹','quantangshi','','卷22','瓶泻高檐雨，窗来激箭风。
病憎灯火暗，寒觉薄帏空。
婢报樵苏竭，妻愁院落通。
老夫慵计数，教想蔡城东。','',''),('quantangshi-21452','景申秋八首 五','稹','quantangshi','','卷22','风头难着枕，病眼厌看书。
无酒销长夜，回灯照小余。
三元推废王，九曜入乘除。
廊庙应多算，参差斡太虚。','',''),('quantangshi-21453','景申秋八首 六','稹','quantangshi','','卷22','经雨篱落坏，入秋田地荒。
竹垂哀折节，莲败惜空房。
小片慈菇白，低丛柚子黄。
眼前撩乱辈，无不是同乡。','',''),('quantangshi-21454','景申秋八首 七','稹','quantangshi','','卷22','雨柳枝枝弱，风光片片斜。
蜻蜓怜晓露，蛱蝶恋秋花。
饥啅空篱雀，寒栖满树鸦。
荒凉池馆内，不似有人家。','',''),('quantangshi-21455','景申秋八首 八','稹','quantangshi','','卷22','病苦十年后，连阴十日余。
人方教作鼠，天岂遣为鱼。
鲛绽酆城劒，虫凋鬼火书。
出闻泥泞尽，何地不摧车。','',''),('quantangshi-21456','遣行十首 一','稹','quantangshi','','卷22','惨切风雨夕，沉吟离别情。
燕辞前日社，蝉是每年声。
暗泪深相感，危心亦自惊。
不如元不识，俱作路人行。','',''),('quantangshi-21457','遣行十首 二','稹','quantangshi','','卷22','十五年前事，恓惶无限情。
病僮更借出，羸马共驰声。
射叶杨才破，闻弓雁已惊。
小年辛苦学，求得苦辛行。','',''),('quantangshi-21458','遣行十首 三','稹','quantangshi','','卷22','徙倚檐宇下，思量去住情。
暗萤穿竹见，斜雨隔窗声。
就枕回转数，闻鸡撩乱惊。
一家同草草，排比送君行。','',''),('quantangshi-21459','遣行十首 四','稹','quantangshi','','卷22','已怆朋交别，复怀儿女情。
相兄亦相旧，同病又同声。
白发年年剩，秋蓬处处惊。
不堪身渐老，频送异乡行。','',''),('quantangshi-21460','遣行十首 五','稹','quantangshi','','卷22','塞上风雨思，城中兄弟情。
北随鵷立位，南送雁来声。
遇适尤兼恨，闻书喜复惊。
唯应遥料得，知我伴君行。','',''),('quantangshi-21461','遣行十首 六','稹','quantangshi','','卷22','暮欲歌吹乐，暗冲泥水情。
稻花秋雨气，江石夜滩声。
犬吠穿篱出，鸥眠起水惊。
愁君明月夜，独自入山行。','',''),('quantangshi-21462','遣行十首 七','稹','quantangshi','','卷22','七过襃城驿，回回各为情。
八年身世梦，一种水风声。
寻觅诗章在，思量岁月惊。
更悲西塞别，终夜绕池行。','',''),('quantangshi-21463','遣行十首 八','稹','quantangshi','','卷22','襃县驿前境，曲江池上情。
南堤衰柳意，西寺晚钟声。
云水兴方远，风波心已惊。
可怜皆老大，不得自由行。','',''),('quantangshi-21464','遣行十首 九','稹','quantangshi','','卷22','见说巴风俗，都无汉性情。
猿声芦管调，羌笛竹鸡声。
迎候人应少，平安火莫惊。
每逢危栈处，须作贯鱼行。','',''),('quantangshi-21465','遣行十首 十','稹','quantangshi','','卷22','闻道阴平郡，翛然古戍情。
桥兼麋鹿蹋，山应鼓鼙声。
羌妇梳头紧，蕃牛护尾惊。
怜君闲闷极，只傍白江行。','',''),('quantangshi-21466','生春二十首 一','稹','quantangshi','','卷22','何处生春早，春生云色中。
笼葱闲着水，暗淡欲随风。
度晓分霞态，余光庇雪融。
晚来低漠漠，浑欲泥幽丛。','',''),('quantangshi-21467','生春二十首 二','稹','quantangshi','','卷22','何处生春早，春生漫雪中。
浑无到地片，唯逐入楼风。
屋上些些薄，池心旋旋融。
自悲销散尽，谁假入兰丛。','',''),('quantangshi-21468','生春二十首 三','稹','quantangshi','','卷22','何处生春早，春生霁色中。
远林横返照，高树亚东风。
水冻霜威庇，泥新地气融。
渐知残雪薄，杪近最怜丛。','',''),('quantangshi-21469','生春二十首 四','稹','quantangshi','','卷22','何处生春早，春生曙火中。
星围分暗陌，烟气满晴风。
宫树栖鵶乱，城楼带雪融。
竞排阊阖侧，珂伞自相丛。','',''),('quantangshi-21470','生春二十首 五','稹','quantangshi','','卷22','何处生春早，春生晓禁中。
殿阶龙斾日，漏阁宝筝风。
药树香烟重，天颜瑞气融。
柳梅浑未觉，青紫已丛丛。','',''),('quantangshi-21471','生春二十首 六','稹','quantangshi','','卷22','何处生春早，春生江路中。
雨移临浦市，晴候过湖风。
芦笋锥犹短，凌澌玉渐融。
数宗船载足，商妇两眉丛。','',''),('quantangshi-21472','生春二十首 七','稹','quantangshi','','卷22','何处生春早，春生野墅中。
病翁闲向日，征妇嬾成风。
斫筤天虽暖，穿区冻未融。
鞭牛县门外，争土盖蚕丛。','',''),('quantangshi-21473','生春二十首 八','稹','quantangshi','','卷22','何处生春早，春生冰岸中。
尚怜扶腊雪，渐觉受东风。
织女云桥断，波神玉貌融。
便成呜咽去，流恨与莲丛。','',''),('quantangshi-21474','生春二十首 九','稹','quantangshi','','卷22','何处生春早，春生柳眼中。
芽新才绽日，茸短未含风。
绿误眉心重，黄惊蜡泪融。
碧条殊未合，愁绪已先丛。','',''),('quantangshi-21475','生春二十首 十','稹','quantangshi','','卷22','何处生春早，春生梅援中。
蘂排难犯雪，香乞拟来风。
陇迥羌声怨，江遥客思融。
年年最相恼，缘未有诸丛。','',''),('quantangshi-21476','生春二十首 十一','稹','quantangshi','','卷22','何处生春早，春生鸟思中。
鹊巢移旧岁，䳒羽旋高风。
鸿雁惊沙暖，鸳鸯爱水融。
最怜双翡翠，飞入小梅丛。','',''),('quantangshi-21477','生春二十首 十二','稹','quantangshi','','卷22','何处生春早，春生池榭中。
镂琼冰陷日，文縠水廻风。
柳爱和身动，梅愁合树融。
草芽犹未出，挑得小萱丛。','',''),('quantangshi-21478','生春二十首 十三','稹','quantangshi','','卷22','何处生春早，春生稚戏中。
乱骑残爆竹，争唾小旋风。
駡雨愁妨走，呵冰喜旋融。
女儿针线尽，偷学五辛丛。','',''),('quantangshi-21479','生春二十首 十四','稹','quantangshi','','卷22','何处生春早，春生人意中。
晓妆虽近火，晴戏渐怜风。
暗入心情嬾，先添酒思融。
预知花好恶，偏在最深丛。','',''),('quantangshi-21480','生春二十首 十五','稹','quantangshi','','卷22','何处生春早，春生半睡中。
见灯如见雾，闻雨似闻风。
开眼犹残梦，抬身便恐融。
却成双翅蝶，还绕庳花丛。','',''),('quantangshi-21481','生春二十首 十六','稹','quantangshi','','卷22','何处生春早，春生晓镜中。
手寒匀面粉，鬟动倚帘风。
宿雾梅心滴，朝光幕上融。
思牵梳洗嬾，空拔绿丝丛。','',''),('quantangshi-21482','生春二十首 十七','稹','quantangshi','','卷22','何处生春早，春生绮户中。
玉栊穿细日，罗幔张轻风。
柳软腰支嫩，梅香密气融。
独眠傍妬物，偷铲合欢丛。','',''),('quantangshi-21483','生春二十首 十八','稹','quantangshi','','卷22','何处生春早，春生老病中。
土膏蒸足肿，天暖痒头风。
似觉肌肤展，潜知血气融。
又添新一岁，衰白转成丛。','',''),('quantangshi-21484','生春二十首 十九','稹','quantangshi','','卷22','何处生春早，春生客思中。
旅魂惊北雁，乡信是东风。
纵有心灰动，无由鬓雪融。
未知开眼日，空绕未开丛。','',''),('quantangshi-21485','生春二十首 二十','稹','quantangshi','','卷22','何处生春早，春生蒙雨中。
裛尘微有气，拂面细如风。
柳误啼珠密，梅惊粉汗融。
满空愁淡淡，应豫忆芳丛。','',''),('quantangshi-21486','嘉陵水','稹','quantangshi','','卷22','尔是无心水，东流有恨无。
我心无说处，也共尔何殊。','',''),('quantangshi-21487','漫天岭赠僧','稹','quantangshi','','卷22','五上两漫天，因师忏业缘。
漫天无尽日，浮世有穷年。','',''),('quantangshi-21488','百牢关','稹','quantangshi','','卷22','天上无穷路，生期七十间。
那堪九年内，五度百牢关。','',''),('quantangshi-21489','二月十九日酬王十八全素','稹','quantangshi','','卷22','君念世上川，嗟予老瘴天。
那堪十日内，又长白头年。','',''),('quantangshi-21490','荥阳郑公以稹寓居严茅有池塘之胜寄诗四首因有意献','稹','quantangshi','','卷22','激射分流阔，湾环此地多。
暂停随梗浪，犹阅败霜荷。
恨阻还江势，思深到海波。
自伤才畎浍，其奈赠珠何。','',''),('quantangshi-21491','酬乐天寄蕲州簟','稹','quantangshi','','卷22','蕲簟未经春，君先拭翠筠。
知为热时物，预与瘴中人。
碾玉连心润，编牙小片珍。
霜凝青汗简，冰透碧游鳞。
水魄轻涵黛，琉璃薄带尘。
梦成伤冷滑，惊卧老龙身。','',''),('quantangshi-21492','酬李浙西先因从事见寄之作','稹','quantangshi','','卷22','近日金銮直，亲于汉珥貂。
内人传帝命，丞相让吾僚。
浙郡悬旌远，长安谕日遥。
因君蘂珠赠，还一梦烟霄。','',''),('quantangshi-21493','酬周从事望海亭见寄','稹','quantangshi','','卷22','年老无流辈，行稀足薜萝。
热时怜水近，高处见山多。
衣袖长堪舞，喉咙转解歌。
不辞狂复醉，人世有风波。','',''),('quantangshi-21494','代杭民答乐天','稹','quantangshi','','卷22','翠幕笼斜日，朱衣俨别筵。
管弦凄欲罢，城郭望依然。
路溢新城市，农开旧废田。
春坊幸无事，何惜借三年。','',''),('quantangshi-21495','杏园','稹','quantangshi','','卷22','浩浩长安车马尘，狂风吹送每年春。
门前本是虚空界，何事栽花误世人。','',''),('quantangshi-21496','菊花','稹','quantangshi','','卷22','秋丛绕舍似陶家，遍绕篱边日渐斜。
不是花中偏爱菊，此花开尽更无花。','',''),('quantangshi-21497','酬哥舒大少府寄同年科第','稹','quantangshi','','卷22','前年科第偏年少，未解知羞最爱狂。
九陌争驰好鞍马，八人同着彩衣裳。
自言行乐朝朝是，岂料浮生渐渐忙。
赖得官闲且疎散，到君花下忆诸郎。','',''),('quantangshi-21498','幽栖','稹','quantangshi','','卷22','野人自爱幽栖所，近对长松远是山。
尽日望云心不系，有时看月夜方闲。
壶中天地干坤外，梦里身名旦暮间。
辽海若思千岁鹤，且留城市会飞还。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21499','清都春霁寄胡三吴十一','稹','quantangshi','','卷22','蘂珠宫殿经微雨，草树无尘耀眼光。
白日当空天气暖，好风飘树柳阴凉。
蜂怜宿露攒芳久，燕得新泥拂户忙。
时节催年春不住，武陵花谢忆诸郎。','',''),('quantangshi-21500','华岳寺','稹','quantangshi','','卷22','山前古寺临长道，来往淹留为爱山。
双燕营巢始西别，百花成子又东还。
暝驱羸马频看堠，晓听鸣鸡欲度关。
羞见窦师无外役，竹窗依旧老身闲。','',''),('quantangshi-21501','天坛上境','稹','quantangshi','','卷22','野人性僻穷深僻，芸署官闲不似官。
万里洞中朝玉帝，九光霞外宿天坛。
洪涟浩渺东溟曙，白日低回上境寒。
因为南昌检仙籍，马君家世奉还丹。','',''),('quantangshi-21502','寻西明寺僧不在','稹','quantangshi','','卷22','春来日日到西林，飞锡经行不可寻。
莲池旧是无波水，莫逐狂风起浪心。','',''),('quantangshi-21503','与吴侍御春游','稹','quantangshi','','卷22','苍龙阙下陪骢马，紫阁峰头见白云。
满眼流光随日度，今朝花落更纷纷。','',''),('quantangshi-21504','晚春','稹','quantangshi','','卷22','昼静帘疎燕语频，双双鬬雀动阶尘。
柴扉日暮随风掩，落尽闲花不见人。','',''),('quantangshi-21505','先醉','稹','quantangshi','','卷22','今日樽前败饮名，三杯未尽不能倾。
怪来花下长先醉，半是春风荡酒情。','',''),('quantangshi-21506','独醉','稹','quantangshi','','卷22','一树芳菲也当春，漫随车马拥行尘。
桃花解笑莺能语，自醉自眠那藉人。','',''),('quantangshi-21507','宿醉','稹','quantangshi','','卷22','风引春心不自由，等闲冲席饮多筹。
朝来始向花前觉，度却醒时一夜愁。','',''),('quantangshi-21508','惧醉','稹','quantangshi','','卷22','闻道秋来怯夜寒，不辞泥水为杯盘。
殷勤惧醉有深意，愁到醒时灯火阑。','',''),('quantangshi-21509','羡醉','稹','quantangshi','','卷22','绮陌高楼竞醉眠，共期顦顇不相怜。
也应自有寻春日，虚度而今正少年。','',''),('quantangshi-21510','忆醉','稹','quantangshi','','卷22','自叹旅人行意速，每嫌杯酒缓归期。
今朝偏遇醒时别，泪落风前忆醉时。','',''),('quantangshi-21511','病醉','稹','quantangshi','','卷22','醉伴见侬因病酒，道侬无酒不相窥。
那知下药还沽底，人去人来剩一巵。','',''),('quantangshi-21512','拟醉','稹','quantangshi','','卷22','九月闲宵初向火，一尊清酒始行杯。
怜君城外遥相忆，冒雨冲泥黑地来。','',''),('quantangshi-21513','劝醉','稹','quantangshi','','卷22','窦家能酿销愁酒，但是愁人便与销。
愿我共君俱寂寞，只应连夜复连朝。','',''),('quantangshi-21514','任醉','稹','quantangshi','','卷22','本怕酒醒浑不饮，因君相劝觉情来。
殷勤满酌从听醉，乍可欲醒还一杯。','',''),('quantangshi-21515','同醉','稹','quantangshi','','卷22','柏树台中推事人，杏花坛上炼形真。
心源一种闲如水，同醉樱桃林下春。','',''),('quantangshi-21516','狂醉','稹','quantangshi','','卷22','一自柏台为御史，二年辜负两京春。
岘亭今日颠狂醉，舞引红娘乱打人。','',''),('quantangshi-21517','伴僧行','稹','quantangshi','','卷22','春来求事百无成，因向愁中识道情。
花满杏园千万树，几人能伴老僧行。','',''),('quantangshi-21518','古寺','稹','quantangshi','','卷22','古寺春余日半斜，竹风萧爽胜人家。
花时不到有花院，意在寻僧不在花。','',''),('quantangshi-21519','定僧','稹','quantangshi','','卷22','落魄闲行不着家，徧寻春寺赏年华。
野僧偶向花前定，满树狂风满树花。','',''),('quantangshi-21520','观心处','稹','quantangshi','','卷22','满坐喧喧笑语频，独怜方丈了无尘。
灯前便是观心处，要似观心有几人。','',''),('quantangshi-21521','智度师二首 一','稹','quantangshi','','卷22','四十年前马上飞，功名藏尽拥禅衣。
石榴园下擒生处，独自闲行独自归。','',''),('quantangshi-21522','智度师二首 二','稹','quantangshi','','卷22','三陷思明三突围，铁衣抛尽衲禅衣。
天津桥上无人识，闲凭栏干望落晖。','',''),('quantangshi-21523','西明寺牡丹','稹','quantangshi','','卷22','花向琉璃地上生，光风炫转紫云英。
自从天女盘中见，直至今朝眼更明。','',''),('quantangshi-21524','忆杨十二','稹','quantangshi','','卷22','去时芍药才堪赠，看却残花已度春。
只为情深偏怆别，等闲相见莫相亲。','',''),('quantangshi-21525','送复梦赴韦令幕','稹','quantangshi','','卷22','世上于今重检身，吾徒耽酒作狂人。
西曹旧事多持法，慎莫吐他丞相茵。','',''),('quantangshi-21526','送刘太白','稹','quantangshi','','卷22','洛阳大底居人少，从善坊西最寂寥。
想得刘君独骑马，古堤愁树隔中桥。','',''),('quantangshi-21527','奉诚园','稹','quantangshi','','卷22','萧相深诚奉至尊，旧居求作奉诚园。
秋来古巷无人扫，树满空墙闭戟门。','',''),('quantangshi-21528','与太白同之东洛至栎阳太白染疾驻行予九月二十五日至华岳寺雪后望山','稹','quantangshi','','卷22','共作洛阳千里伴，老刘因疾驻行轩。
今朝独自山前立，雪满三峰倚寺门。','',''),('quantangshi-21529','野狐泉柳林','稹','quantangshi','','卷22','去日野狐泉上柳，紫牙初绽拂眉低。
秋来寥落惊风雨，叶满空林踏作泥。','',''),('quantangshi-21530','酬胡三凭人问牡丹','稹','quantangshi','','卷22','窃见胡三问牡丹，为言依旧满西栏。
花时何处偏相忆，寥落衰红雨后看。','',''),('quantangshi-21531','酬乐天秋兴见赠本句云莫怪独吟秋兴苦比君校近二毛年','稹','quantangshi','','卷22','劝君休作悲秋赋，白发如星也任垂。
