俄惊四面云屏合，坐见千峰雪浪堆。
罔象睢盱频逞怪，石尤翻动忽成灾。
胜凌岂但河宫溢，坱轧浑忧地轴摧。
疑是阴兵致昏黑，果闻灵鼓借喧豗。
龙归窟穴深潭漩，蜃作波涛古岸颓。
水客暗游烧野火，枫人夜长吼春雷。
浸淫沙市儿童乱，汩没汀洲雁鹜哀。
自叹生涯看转烛，更悲商旅哭沈财。
樯乌斗折头仓掉，水狗斜倾尾缆开。
在昔讵慙横海志，此时甘乏济川才。
历阳旧事曾为鼈，鮌穴相传有化能。
闭目唯愁满空电，冥心真类不然灰。
那知否极休征至，渐觉宵分曙气催。
怪族潜收湖黯湛，幽妖尽走日崔嵬。
