顾我亲情皆远道，念君兄弟欲他乡。
红旗满眼襄州路，此别泪流千万行。','',''),('quantangshi-21660','雨声','稹','quantangshi','','卷22','风吹竹叶休还动，雨点荷心暗复明。
曾向西江船上宿，惯闻寒夜滴篷声。','',''),('quantangshi-21661','奉和荥阳公离筵作','稹','quantangshi','','卷22','南郡生徒辞绛帐，东山妓乐拥油旌。
钧天排比箫韶待，犹顾人间有别情。','',''),('quantangshi-21662','嘉陵水','稹','quantangshi','','卷22','古时应是山头水，自古流来江路深。
若使江流会人意，也应知我远来心。','',''),('quantangshi-21663','阆州开元寺壁题乐天诗','稹','quantangshi','','卷22','忆君无计写君诗，写尽千行说向谁。
题在阆州东寺壁，几时知是见君时。','',''),('quantangshi-21664','凭李忠州寄书乐天','稹','quantangshi','','卷22','万里寄书将出峡，却凭巫峡寄江州。
伤心最是江头月，莫把书将上庾楼。','',''),('quantangshi-21665','得乐天书','稹','quantangshi','','卷22','远信入门先有泪，妻惊女哭问何如。
寻常不省曾如此，应是江州司马书。','',''),('quantangshi-21666','寄乐天','稹','quantangshi','','卷22','无身尚拟魂相就，身在那无梦往还。
直到他生亦相觅，不能空记树中环。','',''),('quantangshi-21667','酬知退','稹','quantangshi','','卷22','终须修到无修处，闻尽声闻始不闻。
莫着妄心销彼我，我心无我亦无君。','',''),('quantangshi-21668','通州','稹','quantangshi','','卷22','平生欲得山中住，天与通州遶郡山。
睡到日西无一事，月储三万买教闲。','',''),('quantangshi-21669','酬乐天书后三韵','稹','quantangshi','','卷22','今日庐峰霞遶寺，昔时鸾殿凤廻书。
两封相去八年后，一种俱云五夜初。
渐觉此生都是梦，不能将泪滴双鱼。','',''),('quantangshi-21670','相忆泪','稹','quantangshi','','卷22','西江流水到江州，闻道分成九道流。
我滴两行相忆泪，遣君何处遣人求。
除非入海无由住，纵使逢滩未拟休。
会向伍员潮上见，气充顽石报心雠。','',''),('quantangshi-21671','喜李十一景信到','稹','quantangshi','','卷22','何事相逢翻有泪，念君缘我到通州。
留君剩住君须住，我不自由君自由。','',''),('quantangshi-21672','与李十一夜饮','稹','quantangshi','','卷22','寒夜灯前赖酒壶，与君相对兴犹孤。
忠州刺史应闲卧，江水猿声睡得无。','',''),('quantangshi-21673','赠李十一','稹','quantangshi','','卷22','淮水连年起战尘，油旌三换一何频。
共君前后俱从事，羞见功名与别人。','',''),('quantangshi-21674','寒食日','稹','quantangshi','','卷22','今年寒食好风流，此日一家同出游。
碧水青山无限思，莫将心道是涪州。','',''),('quantangshi-21675','三兄以白角巾寄遗发不胜冠因有感叹','稹','quantangshi','','卷22','病瘴年深浑秃尽，那能胜置角头巾。
暗梳蓬发羞临镜，私戴莲花耻见人。
白发过于冠色白，银钉少校颔中银。
我身四十犹如此，何况吾兄六十身。','',''),('quantangshi-21676','别李十一五绝 一','稹','quantangshi','','卷22','巴南分与亲情别，不料与君牀竝头。
为我远来休怅望，折君灾难是通州。','',''),('quantangshi-21677','别李十一五绝 二','稹','quantangshi','','卷22','京城每与闲人别，犹自伤心与白头。
今日别君心更苦，别君缘是在通州。','',''),('quantangshi-21678','别李十一五绝 三','稹','quantangshi','','卷22','万里尚能来远道，一程那忍便分头。
鸟笼猿槛君应会，十步向前非我州。','',''),('quantangshi-21679','别李十一五绝 四','稹','quantangshi','','卷22','来时见我江南岸，今日送君江上头。
别后料添新梦寐，虎惊蛇伏是通州。','',''),('quantangshi-21680','别李十一五绝 五','稹','quantangshi','','卷22','闻君欲去潜销骨，一夜暗添新白头。
明朝别后应肠断，独棹破船归到州。','',''),('quantangshi-21681','酬乐天醉别','稹','quantangshi','','卷22','前回一去五年别，此别又知何日回。
好住乐天休怅望，匹如元不到京来。','',''),('quantangshi-21682','酬乐天雨后见忆','稹','quantangshi','','卷22','雨滑危梁性命愁，差池一步一生休。
黄泉便是通州郡，渐入深泥渐到州。','',''),('quantangshi-21683','和乐天过祕阁书省旧厅','稹','quantangshi','','卷22','闻君西省重徘徊，祕阁书房次第开。
壁记欲题三漏合，吏人惊问十年来。
经排蠹简怜初校，芸长陈根识旧栽。
司马见诗心最苦，满身蚊蚋哭烟埃。','',''),('quantangshi-21684','和乐天赠杨祕书','稹','quantangshi','','卷22','旧与杨郎在帝城，搜天斡地觅诗情。
曾因竝句甘称小，不为论年便唤兄。
刮骨直穿由苦鬬，梦肠翻出暂闲行。
因君投赠还相和，老去那能竞底名。','',''),('quantangshi-21685','和乐天题王家亭子','稹','quantangshi','','卷22','风吹笋箨飘红砌，雨打桐花盖绿莎。
都大资人无暇日，泛池全少买池多。','',''),('quantangshi-21686','酬乐天频梦微之','稹','quantangshi','','卷22','山水万重书断绝，念君怜我梦相闻。
我今因病魂颠倒，唯梦闲人不梦君。','',''),('quantangshi-21687','琵琶','稹','quantangshi','','卷22','学语胡儿撼玉玲，甘州破里最星星。
使君自恨常多事，不得工夫夜夜听。','',''),('quantangshi-21688','春词','稹','quantangshi','','卷22','山翠湖光似欲流，蜂声鸟思却堪愁。
西施颜色今何在，但看春风百草头。','',''),('quantangshi-21689','酬乐天春寄微之','稹','quantangshi','','卷22','鹦心明黠雀幽蒙，何事相将尽入笼。
君避海鲸惊浪里，我随巴蟒瘴烟中。
千山塞路音书绝，两地知春历日同。
一树梅花数升酒，醉寻江岸哭东风。','',''),('quantangshi-21690','酬乐天舟泊夜读微之诗','稹','quantangshi','','卷22','知君暗泊西江岸，读我闲诗欲到明。
今夜通州还不睡，满山风雨杜鹃声。','',''),('quantangshi-21691','酬乐天武关南见微之题山石榴花诗','稹','quantangshi','','卷22','比因酬赠为花时，不为君行不复知。
又更几年还共到，满墙尘土两篇诗。','',''),('quantangshi-21692','酬乐天见寄','稹','quantangshi','','卷22','三千里外巴虵穴，四十年来司马官。
瘴色满身治不尽，疮痕刮骨洗应难。
常甘人向衰容薄，独讶君将旧眼看。
前日诗中高盖字，至今唇舌遍长安。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21693','酬乐天得稹所寄紵丝布白轻庸制成衣服以诗报之','稹','quantangshi','','卷22','湓城万里隔巴庸，紵薄绨轻共一封。
腰带定知今瘦小，衣衫难作远裁缝。
唯愁书到炎凉变，忽见诗来意绪浓。
春草绿茸云色白，想君骑马好仪容。','',''),('quantangshi-21694','和乐天寻郭道士不遇','稹','quantangshi','','卷22','昔年我见杯中渡，今日人言鹤上逢。
两虎定随千岁鹿，双林添作几株松。
方瞳应是新烧药，短脚知缘旧施舂。
欲请僧繇远相画，苦愁频变本形容。','',''),('quantangshi-21695','酬乐天寄生衣','稹','quantangshi','','卷22','秋茅处处流痎疟，夜鸟声声哭瘴云。
羸骨不胜纤细物，欲将文服却还君。','',''),('quantangshi-21696','酬乐天得微之诗知通州事因成四首 一','稹','quantangshi','','卷22','茅檐屋舍竹篱州，虎怕偏蹄虵两头。
暗蛊有时迷酒影，浮尘向日似波流。
沙含水弩多伤骨，田仰畲刀少用牛。
知得共君相见否，近来魂梦转悠悠。','',''),('quantangshi-21697','酬乐天得微之诗知通州事因成四首 二','稹','quantangshi','','卷22','平地才应一顷余，阁栏都大似巢居。
入衙官吏声疑鸟，下峡舟船腹似鱼。
市井无钱论尺丈，田畴付火罢耘锄。
此中愁杀须甘分，惟惜平生旧着书。','',''),('quantangshi-21698','酬乐天得微之诗知通州事因成四首 三','稹','quantangshi','','卷22','哭鸟昼飞人少见，伥魂夜啸虎行多。
满身沙虱无防处，独脚山魈不奈何。
甘受鬼神侵骨髓，常忧岐路处风波。
南歌未有东西分，敢唱沧浪一字歌。','',''),('quantangshi-21699','酬乐天得微之诗知通州事因成四首 四','稹','quantangshi','','卷22','荒芜满院不能锄，甑有尘埃圃乏蔬。
定觉身将囚一种，未知生共死何如。
饥摇困尾丧家狗，热暴枯鳞失水鱼。
苦境万般君莫问，自怜方寸本来虚。','',''),('quantangshi-21700','酬乐天闻李尚书拜相以诗见贺','稹','quantangshi','','卷22','初因弹劾死东川，又为亲情弄化权百口共经三峡水，一时重上两漫天。
尚书入用虽旬月，司马衔冤已十年。
若待更遭秋瘴后，便愁平地有重泉。','',''),('quantangshi-21701','酬乐天叹穷愁见寄','稹','quantangshi','','卷22','病煎愁绪转纷纷，百里何由说向君。
老去心情随日减，远来书信隔年闻。
三冬有电连春雨，九月无霜尽火云。
并与巴南终岁热，四时谁道各平分。','',''),('quantangshi-21702','酬乐天三月三日见寄','稹','quantangshi','','卷22','当年此日花前醉，今日花前病里销。
独倚破帘闲怅望，可怜虚度好春朝。','',''),('quantangshi-21703','酬乐天叹损伤见寄','稹','quantangshi','','卷22','前途何在转茫茫，渐老那能不自伤。
病为怕风多睡月，起因花药暂扶牀。
函关气索迷真侣，峡水波翻碍故乡。
唯有秋来两行泪，对君新赠远诗章。','',''),('quantangshi-21704','瘴塞','稹','quantangshi','','卷22','瘴塞巴山哭鸟悲，红妆少妇敛啼眉。
殷勤奉药来相劝，云是前年欲病时。','',''),('quantangshi-21705','红荆','稹','quantangshi','','卷22','庭中栽得红荆树，十月花开不待春。
直到孩提尽惊怪，一家同是北来人。','',''),('quantangshi-21706','黄草峡听柔之琴二首 一','稹','quantangshi','','卷22','胡笳夜奏塞声寒，是我乡音听渐难。
料得小来辛苦学，又因知向峡中弹。','',''),('quantangshi-21707','黄草峡听柔之琴二首 二','稹','quantangshi','','卷22','别鹤凄清觉露寒，离声渐咽命雏难。
怜君伴我涪州宿，犹有心情彻夜弹。','',''),('quantangshi-21708','书劒','稹','quantangshi','','卷22','渝工劒刃皆欧冶，巴吏书踪尽子云。
唯我心知有来处，泊船黄草夜思君。','',''),('quantangshi-21709','内状诗寄杨白二员外','稹','quantangshi','','卷22','天门暗辟玉琤鍧，昼送中枢晓禁清。
彤管内人书细腻，金匳御印篆分明。
冲街不避将军令，跋勅兼题宰相名。
南省郎官谁待诏，与君将向世间行。','',''),('quantangshi-21710','别毅郎 一','稹','quantangshi','','卷22','尔爷只为一杯酒，此别那知死与生。
儿有何辜才七岁，亦教儿作瘴江行。','',''),('quantangshi-21711','别毅郎 二','稹','quantangshi','','卷22','爱惜尔爷唯有我，我今顦顇望何人。
伤心自比笼中鹤，翦尽翅翎愁到身。','',''),('quantangshi-21712','自责','稹','quantangshi','','卷22','犀带金鱼束紫袍，不能将命报分毫。
他时得见牛常侍，为尔君前捧佩刀。','',''),('quantangshi-21713','送公度之福建','稹','quantangshi','','卷22','棠阴犹在建溪矶，此去那论是与非。
若见白头须尽敬，恐曾江岸识胡威。','',''),('quantangshi-21714','喜五兄自泗州至','稹','quantangshi','','卷22','眼中三十年来泪，一望南云一度垂。
惭愧临淮李常侍，远教形影暂相随。','',''),('quantangshi-21715','杏花','稹','quantangshi','','卷22','常年出入右银台，每怪春光例早回。
惭愧杏园行在景，同州园里也先开。','',''),('quantangshi-21716','第三岁日咏春风凭杨员外寄长安柳','稹','quantangshi','','卷22','三日春风已有情，拂人头面稍怜轻。
殷勤为报长安柳，莫惜枝条动软声。','',''),('quantangshi-21717','赠别杨员外巨源','稹','quantangshi','','卷22','忆昔西河县下时，青山顦顇宦名卑。
揄扬陶令缘求酒，结托萧娘只在诗。
朱紫衣裳浮世重，苍黄岁序长年悲。
白头后会知何日，一盏烦君不用辞。','',''),('quantangshi-21718','寄乐天二首 一','稹','quantangshi','','卷22','荣辱升沈影与身，世情谁是旧雷陈。
唯应鲍叔犹怜我，自保曾参不杀人。
山入白楼沙苑暮，潮生沧海野塘春。
老逢佳景唯惆怅，两地各伤何限神。','',''),('quantangshi-21719','寄乐天二首 二','稹','quantangshi','','卷22','论才赋命不相干，凤有文章雉有冠。
羸骨欲销犹被刻，疮痕未没又遭弹。
劒头已折藏须盖，丁字虽刚屈莫难。
休学州前罗刹石，一生身敌海波澜。','',''),('quantangshi-21720','听妻弹别鹤操','稹','quantangshi','','卷22','别鹤声声怨夜弦，闻君此奏欲潸然。
商瞿五十知无子，更付琴书与仲宣。','',''),('quantangshi-21721','和王侍郎酬广宣上人观放牓后相贺','稹','quantangshi','','卷22','渥洼徒自有权奇，伯乐书名世始知。
竞走墙前希得儁，高县日下表无私。
都中纸贵流传后，海外金填姓字时。
珍重刘繇因首荐，为君送和碧云诗。','',''),('quantangshi-21722','酬乐天喜邻郡','稹','quantangshi','','卷22','蹇驴瘦马尘中伴，紫绶朱衣梦里身。
符竹偶因成对岸，文章虚被配为邻。
湖翻白浪常看雪，火照红妆不待春。
老大那能更争竞，任君投募醉乡人。','',''),('quantangshi-21723','再酬复言和前篇','稹','quantangshi','','卷22','经过二郡逢贤牧，聚集诸郎宴老身。
清夜漫劳红烛会，白头非是翠娥邻。
曾携酒伴无端宿，自入朝行便别春。
潦倒微之从不占，未知公议道何人。','',''),('quantangshi-21724','赠乐天','稹','quantangshi','','卷22','莫言邻境易经过，彼此分符欲奈何。
垂老相逢渐难别，白头期限各无多。','',''),('quantangshi-21725','重赠','稹','quantangshi','','卷22','休遣玲珑唱我诗，我诗多是别君词。
明朝又向江头别，月落潮平是去时。','',''),('quantangshi-21726','别后西陵晚眺','稹','quantangshi','','卷22','晚日未抛诗笔砚，夕阳空望郡楼台。
与君后会知何日，不似潮头暮却廻。','',''),('quantangshi-21727','以州宅夸于乐天','稹','quantangshi','','卷22','州城迥遶拂云堆，镜水稽山满眼来。
四面常时对屏障，一家终日在楼台。
星河似向檐前落，鼓角惊从地底廻。
我是玉皇香案吏，谪居犹得住蓬莱。','',''),('quantangshi-21728','重夸州宅旦暮景色兼酬前篇末句','稹','quantangshi','','卷22','仙都难画亦难书，暂合登临不合居。
绕郭烟岚新雨后，满山楼阁上灯初。
人声晓动千门辟，湖色宵涵万象虚。
为问西州罗刹岸，涛头冲突近何如。','',''),('quantangshi-21729','酬乐天吟张员外诗见寄因思上京每与乐天于居敬兄升平里咏张新诗','稹','quantangshi','','卷22','乐天书内重封到，居敬堂前共读时。
四友一为泉路客，三人两咏浙江诗。
别无远近皆难见，老减心情自各知。
杯酒与他年少隔，不相酬赠欲何之。','',''),('quantangshi-21730','寄乐天','稹','quantangshi','','卷22','闲夜思君坐到明，追寻往事倍伤情。
同登科后心相合，初得官时髭未生。
二十年来谙世路，三千里外老江城。
犹应更有前途在，知向人间何处行。','',''),('quantangshi-21731','戏赠乐天复言','稹','quantangshi','','卷22','乐事难逢岁易徂，白头光景莫令孤。
弄涛船更曾观否，望市楼还有会无。
眼力少将寻案牍，心情且强掷枭卢。
孙园虎寺随宜看，不必遥遥羡镜湖。','',''),('quantangshi-21732','重酬乐天','稹','quantangshi','','卷22','红尘扰扰日西徂，我兴云心两共孤。
暂出已遭千骑拥，故交求见一人无。
百篇书判从饶白，八米诗章未伏卢。
最笑近来黄叔度，自投名刺占陂湖。','',''),('quantangshi-21733','再酬复言','稹','quantangshi','','卷22','绕郭笙歌夜景徂，稽山迥带月轮孤。
休文欲咏心应破，道子虽来画得无。
顾我小才同培塿，知君险鬬敌都卢。
不然岂有姑苏郡，拟着陂塘比镜湖。','',''),('quantangshi-21734','郡务稍简因得整比旧诗并连缀焚削封章委箧仅逾百轴偶成自叹因寄乐天','稹','quantangshi','','卷22','近来章奏小年诗，一种成空尽可悲。
书得眼昏朱似碧，用来心破发如丝。
催身易老缘多事，报主深恩在几时。
天遣两家无嗣子，欲将文集与它谁。','',''),('quantangshi-21735','酬乐天余思不尽加为六韵之作','稹','quantangshi','','卷22','律吕同声我尔身，文章君是一伶伦。
众推贾谊为才子，帝喜相如作侍臣。
次韵千言曾报答，直词三道共经纶。
元诗驳杂真难辨，白朴流传用转新。
蔡女图书虽在口，于公门户岂生尘。
商瞿未老犹希冀，莫把籝金便付人。','',''),('quantangshi-21736','寄乐天','稹','quantangshi','','卷22','莫嗟虚老海壖西，天下风光数会稽。
灵泛桥前百里镜，石帆山崦五云溪。
冰销田地芦锥短，春入枝条柳眼低。
安得故人生羽翼，飞来相伴醉如泥。','',''),('quantangshi-21737','酬乐天雪中见寄','稹','quantangshi','','卷22','知君夜听风萧索，晓望林亭雪半糊。
撼落不教封柳眼，埽来偏尽附梅株。
敲扶密竹枝犹亚，煦暖寒禽气渐苏。
坐觉湖声迷远浪，回惊云路在长途。
钱塘湖上苹先合，梳洗楼前粉暗铺。
石立玉童披鹤氅，台施瑶席换龙须。
满空飞舞应为瑞，寡和高歌只自娱。
莫遣拥帘伤思妇，且将盈尺慰农夫。
称觞彼此情何异，对景东西事有殊。
镜水遶山山尽白，琉璃云母世间无。','',''),('quantangshi-21738','和乐天早春见寄','稹','quantangshi','','卷22','雨香云澹觉微和，谁送春声入棹歌。
萱近北堂穿土早，柳偏东面受风多。
湖添水色消残雪，江送潮头涌漫波。
同受新年不同赏，无由缩地欲如何。','',''),('quantangshi-21739','酬复言长庆四年元日郡斋感怀见寄','稹','quantangshi','','卷22','腊尽残销春又归，逢新别故欲沾衣。
自惊身上添年纪，休系心中小是非。
富贵祝来何所遂，聪明鞭得转无机。
羞看稚子先拈酒，怅望平生旧采薇。
去日渐加余日少，贺人虽闹故人稀。
椒花丽句闲重检，艾发衰容惜寸辉。
苦思正旦酬白雪，闲观风色动青旗。
千官仗下炉烟里，东海西头意独违。','',''),('quantangshi-21740','代郡斋神答乐天','稹','quantangshi','','卷22','虚白堂神传好语，二年长伴独吟时。
夜怜星月多离烛，日滉波涛一下帷。
为报何人偿酒债，引看墙上使君诗。','',''),('quantangshi-21741','酬乐天重寄别','稹','quantangshi','','卷22','却报君侯听苦辞，老头抛我欲何之。
武牢关外虽分手，不似如今衰白时。','',''),('quantangshi-21742','和乐天重题别东楼','稹','quantangshi','','卷22','山容水态使君知，楼上从容万状移。
日映文章霞细丽，风驱鳞甲浪参差。
鼓催潮户凌晨击，笛赛婆官彻夜吹。
唤客潜挥远红袖，卖垆高挂小青旗。
剩铺牀席春眠处，乍卷帘帷月上时。
光景无因将得去，为郎抄在和郎诗。','',''),('quantangshi-21743','余杭周从事以十章见寄词调清婉难于遍酬聊和诗首篇以答来贶','稹','quantangshi','','卷22','扰扰纷纷旦暮间，经营闲事不曾闲。
多缘老病推辞酒，少有功夫久羡山。
清夜笙歌喧四郭，黄昏钟漏下重关。
何由得似周从事，醉入人家醒始还。','',''),('quantangshi-21744','寄浙西李大夫四首 一','稹','quantangshi','','卷22','柳眼梅心渐欲春，白头西望忆何人。
金陵太守曾相伴，共蹋银台一路尘。','',''),('quantangshi-21745','寄浙西李大夫四首 二','稹','quantangshi','','卷22','蘂珠深处少人知，网索西临太液池。
浴殿晓闻天语后，步廊骑马笑相随。','',''),('quantangshi-21746','寄浙西李大夫四首 三','稹','quantangshi','','卷22','禁林同直话交情，无夜无曾不到明。
最忆西楼人静夜，玉晨钟磬两三声。','',''),('quantangshi-21747','寄浙西李大夫四首 四','稹','quantangshi','','卷22','由来鹏化便图南，浙右虽雄我未甘。
早渡西江好归去，莫抛舟楫滞春潭。','',''),('quantangshi-21748','初除浙东妻有阻色因以四韵晓之','稹','quantangshi','','卷22','嫁时五月归巴地，今日双旌上越州。
兴庆首行千命妇，会稽旁带六诸侯。
海楼翡翠闲相逐，镜水鸳鸯暖共游。
我有主恩羞未报，君于此外更何求。','',''),('quantangshi-21749','为乐天自勘诗集因思顷年城南醉归马上递唱艳曲十余里不绝长庆初俱以制诰侍宿南郊斋宫夜后偶吟数十篇两掖诸公洎翰林学士三十余人惊起就听逮至卒吏莫不众观羣公直至侍从行礼之时不复聚寐予与乐天吟哦竟亦不绝因书于乐天卷后越中冬夜风雨不觉将晓诸门互启关锁即事成篇','稹','quantangshi','','卷22','春野醉吟十里程，斋宫潜咏万人惊。
今宵不寐到明读，风雨晓闻开锁声。','',''),('quantangshi-21750','题长庆四年历日尾','稹','quantangshi','','卷22','残历半张余十四，灰心雪鬓两凄然。
定知新岁御楼后，从此不名长庆年。','',''),('quantangshi-21751','乐府古题序 梦上天','稹','quantangshi','','卷22','梦上高高天，高高苍苍高不极。
下视五岳块累累，仰天依旧苍苍色。
蹋云耸身身更上，攀天上天攀未得。
西瞻若水兔轮低，东望蟠桃海波黑。
日月之光不到此，非暗非明烟塞塞。
天悠地远身跨风，下无阶梯上无力。
来时畏有他人上，截断龙胡斩鹏翼。
茫茫漫漫方自悲，哭向青云椎素臆。
哭声厌咽旁人恶，唤起惊悲泪飘露。
千慙万谢唤厌人，向使无君终不寤。','',''),('quantangshi-21752','乐府古题序 冬白紵','稹','quantangshi','','卷22','吴宫夜长宫漏款，帘幕四垂灯焰暖。
西施自舞王自管，雪紵翻翻鹤翎散。
促节牵繁舞腰嬾，舞腰嬾，王罢饮。
盖覆西施凤花锦，身作匡牀臂为枕。
朝佩枞玉王晏寝，寝醒阍报门无事。
子胥死后言为讳，近王之臣谕王意。
共笑越王穷惴惴，夜夜抱冰寒不睡。','',''),('quantangshi-21753','乐府古题序 将进酒','稹','quantangshi','','卷22','将进酒，将进酒。
酒中有毒鸩主父，言之主父伤主母。
母为妾地父妾天，仰天俯地不忍言。
阳为僵踣主父前，主父不知加妾鞭。
旁人知妾为主说，主将泪洗鞭头血。
推椎主母牵下堂，扶妾遣升堂上牀。
将进酒，酒中无毒令主寿。
愿主廻恩归主母，遣妾如此由主父。
妾为此事人偶知，自慙不密方自悲。
主今颠倒安置妾，贪天僭地谁不为。','',''),('quantangshi-21754','乐府古题序 采珠行','稹','quantangshi','','卷22','海波无底珠沈海，采珠之人判死采。
万人判死一得珠，斛量买婢人何在。
年年采珠珠避人，今年采珠由海神。
海神采珠珠尽死，死尽明珠空海水。
珠为海物海属神，神今自采何况人。','',''),('quantangshi-21755','乐府古题序 董逃行','稹','quantangshi','','卷22','董逃董逃董卓逃，揩铿戈甲声劳嘈。
剜剜深脐脂焰焰，人皆数叹曰。
尔独不忆年年取我身上膏，膏销骨尽烟火死。
长安城中贼毛起，城门四走公卿士。
走劝刘虞作天子，刘虞不敢作天子。
曹瞒篡乱从此始，董逃董逃人莫喜。
胜负相环相枕倚，缝缀难成裁破易。
何况曲针不能伸巧指，欲学裁缝须准拟。','',''),('quantangshi-21756','乐府古题序 忆远曲','稹','quantangshi','','卷22','忆远曲，郎身不远郎心远。
沙随郎饭俱在匙，郎意看沙那比饭。
水中书字无字痕，君心暗画谁会君。
况妾事姑姑进止，身去门前同万里。
一家尽是郎腹心，妾似生来无两耳。
妾身何足言，听妾私劝君。
君今夜夜醉何处？姑来伴妾自闭门。
嫁夫恨不早，养儿将备老。
妾自嫁郎身骨立，老姑为郎求娶妾。
妾不忍见姑郎忍见，为郎忍耐看姑面。','',''),('quantangshi-21757','乐府古题序 夫远征','稹','quantangshi','','卷22','赵卒四十万，尽为坑中鬼。
赵王未信赵母言，犹点新兵更填死。
填死之兵兵气索，秦强赵破括敌起。
括虽专命起尚轻，何况牵肘之人牵不已。
坑中之鬼妻在营，髽麻戴绖鹅雁鸣。
送夫之妇又行哭，哭声送死非送行。
夫远征，远征不必戍长城，出门便不知死生。','',''),('quantangshi-21758','乐府古题序 织妇词','稹','quantangshi','','卷22','织夫何太忙，蚕经三卧行欲老。
蚕神女圣早成丝，今年丝税抽征早。
早征非是官人恶，去岁官家事戎索。
征人战苦束刀疮，主将勋高换罗幕。
缫丝织帛犹努力，变缉撩机苦难织。
东家头白双女儿，为解挑纹嫁不得。
檐前袅袅游丝上，上有蜘蛛巧来往。
羡他虫豸解缘天，能向虚空织罗网。','',''),('quantangshi-21759','乐府古题序 田家词','稹','quantangshi','','卷22','牛吒吒，田确确。
旱块敲牛蹄趵趵，种得官仓珠颗谷。
六十年来兵蔟蔟，月月食粮车辘辘。
一日官军收海服，驱牛驾车食牛肉。
归来攸得牛两角，重铸锄犂作斤劚。
姑舂妇担去输官，输官不足归卖屋。
愿官早胜雠早覆，农死有儿牛有犊，誓不遣官军粮不足。','',''),('quantangshi-21760','乐府古题序 侠客行','稹','quantangshi','','卷22','侠客不怕死，怕在事不成。
事成不肯藏姓名，我非窃贼谁夜行。
白日堂堂杀袁盎，九衢草草人面青。
此客此心师海鲸，海鲸露背横沧溟。
海波分作两处生，分海减海刀，侠客有谋。
人不识测，三尺铁蛇延二国。','',''),('quantangshi-21761','乐府古题序 君莫非','稹','quantangshi','','卷22','鸟不解走，兽不解飞。
两不相解，那得相讥。
犬不饮露，蝉不噉肥。
以蝉易犬，蝉死犬饥。
燕在梁栋，鼠在阶基。
各自窠窟，人不能移。
妇好针缕，夫读书诗。
男翁女嫁，卒不相知。
惧聋摘耳，效痛嚬眉。
我不非尔，尔无我非。','',''),('quantangshi-21762','乐府古题序 田野狐兔行','稹','quantangshi','','卷22','种豆耘锄，种禾沟甽。
禾苗豆甲，狐榾兔翦。
割鹄餧鹰，烹麟噉犬。
鹰怕兔毫，犬被狐引。
狐兔相须，鹰犬相尽。
日暗天寒，禾稀豆损。
鹰犬就烹，狐兔俱哂。','',''),('quantangshi-21763','乐府古题序 当来日大难行','稹','quantangshi','','卷22','当来日大难行，前有阪，后有坑。
大梁侧，小梁倾。
两轴相绞，两轮相撑。
大牛竖，小牛横。
乌啄牛背，足趺力儜，当来日大难行。
太行虽险，险可使平。
轮轴自挠，牵制不停。
泥潦渐久，荆棘旋生。
行必不得，不如不行。','',''),('quantangshi-21764','乐府古题序 人道短','稹','quantangshi','','卷22','古道天道长人道短，我道天道短人道长。
天道昼夜廻转不曾住，春秋冬夏忙，颠风暴雨电雷狂。
晴被阴暗，月夺日光。
往往星宿，日亦堂堂。
天既职性命，道德人自强。
尧舜有圣德，天不能遣。
寿命永昌，泥金刻玉。
与秦始皇，周公傅说。
何不长宰相，老耼仲尼。
何事栖遑，莽卓恭显。
皆数十年富贵，梁冀夫妇。
车马煌煌，若此颠倒事。
岂非天道短，岂非人道长。
尧舜留得神圣事，百代天子有典章。
仲尼留得孝顺语，千年万岁父子不敢相灭亡。
殁后千余载，唐家天子封作文宣王。
老君留得五千字，子孙万万称圣唐。
諡作玄元帝，魂魄坐天堂。
周公周礼二十卷，有能行者知纪纲。
傅说说命三四纸，有能师者称祖宗。
天能夭人命，人使道无穷。
若此神圣事，谁道人道短。
岂非人道长，天能种百草。
莸得十年有气息，蕣才一日芳。
人能拣得丁沈兰蕙，料理百和香。
天解养禽兽，餧虎豹豺狼。
人解和麯糵，充礿祀烝尝。
杜鹃无百作，天遣百鸟哺雏。
不遣哺凤皇，巨蟒寿千岁。
天遣食牛吞象充腹肠，蛟螭与变化。
鬼怪与隐藏，蚊蚋与利觜。
枳棘与锋铓，赖得人道有拣别。
信任天道真茫茫，若此撩乱事。
岂非天道短，赖得人道长。','',''),('quantangshi-21765','乐府古题序 苦乐相倚曲','稹','quantangshi','','卷22','古来苦乐之相倚，近于掌上之十指。
君心半夜猜恨生，荆棘满怀天未明。
汉成眼瞥飞燕时，可怜班女恩已衰。
未有因由相决绝，犹得半年佯暖热。
转将深意谕旁人，缉缀瑕疵遣潜说。
一朝诏下辞金屋，班姬自痛何仓卒。
呼天抚地将自明，不悟寻时暗销骨。
白首宫人前再拜，愿将日月相辉解。
苦乐相寻昼夜间，灯光那有天明在。
主今被夺心应苦，妾夺深恩初为主。
欲知妾意恨主时，主今为妾思量取。
班姬收泪抱妾身，我曾排摈无限人。','',''),('quantangshi-21766','乐府古题序 出门行','稹','quantangshi','','卷22','兄弟同出门，同行不同志。
凄凄分岐路，各各营所为。
兄上荆山巅，翻石辨虹气。
弟沈沧海底，偷珠待龙睡。
出门不数年，同归亦同遂。
俱用私所珍，升沈自兹异。
献珠龙王宫，值龙觅珠次。
但喜复得珠，不求珠所自。
酬客双龙女，授客六龙辔。
遣充行雨神，雨泽随客意。
雩夏钟鼓繁，禜秋玉帛积。
彩色画廊庙，奴僮被珠翠。
骥騄千万双，鸳鸯七十二。
言者未摇舌，无人敢轻议。
其兄因献璞，再刖不履地。
门户亲戚疎，匡牀妻妾弃。
铭心有所待，视足无所愧。
持璞自枕头，泪痕双血渍。
一朝龙醒寤，本问偷珠事。
因知行雨偏，妻子五刑备。
仁兄捧尸哭，势友掉头讳。
丧车黔首葬，吊客青蝇至。
楚有望气人，王前忽长跪。
贺王得贵宝，不远王所莅。
求之果如言，剖出浮筠腻。
白珩无颜色，垂棘有瑕累。
在楚裂地封，入赵连城贵。
秦遣李斯书，书为传国瑞。
秦亡汉魏传，传者得神器。
卞和名永永，与宝不相坠。
劝尔出门行，行难莫行易。
易得还易失，难同亦难离。
善贾识贪廉，良田无稙穉。
磨劒莫磨锥，磨锥成小利。','',''),('quantangshi-21767','乐府古题序 捉捕歌','稹','quantangshi','','卷22','捉捕复捉捕，莫捉狐与兔。
狐兔藏窟穴，豺狼妨道路。
道路非不妨，最忧蝼蚁聚。
豺狼不陷穽，蝼蚁潜幽蠹。
切切主人窗，主人轻细故。
延缘蚀𣡵栌，渐入栋梁柱。
梁栋尽空虚，攻穿痕不露。
主人坦然意，昼夜安寝寤。
网罗布参差，鹰犬走回互。
尽力穷窟穴，无心自还顾。
客来歌捉捕，歌竟泪如雨。
岂是惜狐兔，畏君先后误。
愿君埽梁栋，莫遣蝼蚁附。
次及清道涂，尽灭豺狼步。
主人堂上坐，行客门前度。
然后巡野田，徧张畋猎具。
外无枭獍援，内有熊罴驱。
狡兔掘荒榛，妖狐熏古墓。
用力不足多，得禽自无数。
畏君听未详，听客有明喻。
虮虱谁不轻，鲸鲵谁不恶。
在海尚幽遐，在怀交秽汚。
歌此劝主人，主人那不悟。
不悟还更歌，谁能恐违忤。','',''),('quantangshi-21768','乐府古题序 古筑城曲五解 一','稹','quantangshi','','卷22','年年塞下丁，长作出塞兵。
自从冒顿强，官筑遮虏城。','',''),('quantangshi-21769','乐府古题序 古筑城曲五解 二','稹','quantangshi','','卷22','筑城须努力，城高遮得贼。
但恐贼路多，有城遮不得。','',''),('quantangshi-21770','乐府古题序 古筑城曲五解 三','稹','quantangshi','','卷22','丁口传父言，莫问城坚不。
平城被虏围，汉劚城墙走。','',''),('quantangshi-21771','乐府古题序 古筑城曲五解 四','稹','quantangshi','','卷22','因兹请休和，虏往骑来过。
半疑兼半信，筑城犹嵯峨。','',''),('quantangshi-21772','乐府古题序 古筑城曲五解 五','稹','quantangshi','','卷22','筑城安敢烦，愿听丁一言。
请筑鸿胪寺，兼愁虏出关。','',''),('quantangshi-21773','乐府古题序 估客乐','稹','quantangshi','','卷22','估客无住着，有利身则行。
出门求火伴，入户辞父兄。
父兄相教示，求利莫求名。
求名有所避，求利无不营。
火伴相勒缚，卖假莫卖诚。
交关但交假，本生得失轻。
自兹相将去，誓死意不更。
亦解市头语，便无邻里情。
鍮石打臂钏，糯米吹项璎。
归来邨中卖，敲作金石声。
邨中田舍娘，贵贱不敢争。
所费百钱本，已得十倍赢。
颜色转光净，饮食亦甘馨。
子本频蕃息，货贩日兼并。
求珠驾沧海，采玉上荆衡。
北买党项马，西擒吐蕃鹦。
炎洲布火浣，蜀地锦织成。
越婢脂肉滑，奚僮眉眼明。
通算衣食费，不计远近程。
经游天下徧，却到长安城。
城中东西市，闻客次第迎。
迎客兼说客，多财为势倾。
客心本明黠，闻语心已惊。
先问十常侍，次求百公卿。
侯家与主第，点缀无不精。
归来始安坐，富与王者勍。
市卒酒肉臭，县胥家舍成。
岂唯绝言语，奔走极使令。
大儿贩材木，巧识梁栋形。
小儿贩盐卤，不入州县征。
一身偃市利，突若截海鲸。
钩距不敢下，下则牙齿横。
生为估客乐，判尔乐一生。
尔又生两子，钱刀何岁平。','',''),('quantangshi-21774','连昌宫词','稹','quantangshi','','卷22','连昌宫中满宫竹，岁久无人森似束。
又有墙头千叶桃，风动落花红蔌蔌。
宫边老翁为余泣，小年进食曾因入。
上皇正在望仙楼，太真同凭阑干立。
楼上楼前尽珠翠，炫转荧煌照天地。
归来如梦复如痴，何暇备言宫里事。
初过寒食一百六，店舍无烟宫树绿。
夜半月高弦索鸣，贺老琵琶定场屋。
力士传呼觅念奴，念奴潜伴诸郎宿。
须臾觅得又连催，特敕街中许然烛。
春娇满眼睡红绡，掠削云鬟旋装束。
飞上九天歌一声，二十五郎吹管逐。
逡巡大徧凉州彻，色色龟兹轰录续。
李謩擪笛傍宫墙，偷得新翻数般曲。
平明大驾发行宫，万人歌舞涂路中。
百官队仗避岐薛，杨氏诸姨车鬬风。
明年十月东都破，御路犹存禄山过。
驱令供顿不敢藏，万姓无声泪潜堕。
两京定后六七年，却寻家舍行宫前。
庄园烧尽有枯井，行宫门闭树宛然。
尔后相传六皇帝，不到离宫门久闭。
往来年少说长安，玄武楼成花萼废。
去年敕使因斫竹，偶值门开暂相逐。
荆榛栉比塞池塘，狐兔骄痴缘树木。
舞榭敧倾基尚在，文窗窈窕纱犹绿。
尘埋粉壁旧花钿，乌啄风筝碎珠玉。
上皇偏爱临砌花，依然御榻临阶斜。
蛇出燕巢盘鬬栱，菌生香案正当衙。
寝殿相连端正楼，太真梳洗楼上头。
晨光未出帘影黑，至今反挂珊瑚钩。
指似傍人因恸哭，却出宫门泪相续。
自从此后还闭门，夜夜狐狸上门屋。
我闻此语心骨悲，太平谁致乱者谁。
翁言野父何分别，耳闻眼见为君说。
姚崇宋璟作相公，劝谏上皇言语切。
燮理阴阳禾黍丰，调和中外无兵戎。
长官清平太守好，拣选皆言由相公。
开元之末姚宋死，朝廷渐渐由妃子。
禄山宫里养作儿，虢国门前闹如市。
弄权宰相不记名，依稀忆得杨与李。
庙谟颠倒四海摇，五十年来作疮痏。
今皇神圣丞相明，诏书才下吴蜀平。
官军又取淮西贼，此贼亦除天下宁。
年年耕种宫前道，今年不遣子孙耕。
老翁此意深望幸，努力庙谋休用兵。','',''),('quantangshi-21775','望云骓马歌','稹','quantangshi','','卷22','忆昔先皇幸蜀时，八马入谷七马疲。
肉绽筋挛四蹄脱，七马死尽无马骑。
天子蒙尘天雨泣，巉岩道路淋漓湿。
峥嵘白草眇难期，謥洞黄泉安可入。
朱泚围兵抽未尽，怀光寇骑追行及。
嫔娥相顾倚树啼，鵷鹭无声仰天立。
圉人初进望云骓，彩色顦顇众马欺。
上前喷吼如有意，耳尖卓立节踠奇。
君王试遣廻胸臆，撮骨锯牙骈两肋。
蹄悬四局脑颗方，胯耸三山尾株直。
圉人畏诮仍相惑，此马无良空有力。
频频啮掣辔难施，往往跳趫鞍不得。
色沮声悲仰天诉，天不遣言君未识。
亚身受取白玉羁，开口衔将紫金勒。
君王自此方敢骑，似遇良臣久凄恻。
龙腾鱼鼈啅然惊，骥朌驴骡少颜色。
七圣心迷运方厄，五丁力尽路犹窄。
橐它山上斧刃堆，望秦岭下锥头石。
五六百里真符县，八十四盘青山驿。
掣开流电有辉光，突过浮云无朕迹。
地平险尽施黄屋，九九属车十二纛。
齐暎前导引骓头，严震迎号抱骓足。
路傍垂白天宝民，望骓礼拜见骓哭。
皆言玄宗当时无此马，不免骑骡来幸蜀。
雄雄猛将李令公，收城杀贼豺狼空。
天旋地转日再中，天子却坐明光宫。
朝廷无事忘征战，校猎朝廻暮球宴。
御马齐登拟用槽，君王自试宣徽殿。
圉人还进望云骓，性强步阔无方便。
分鬃摆杖头太高，擘肘廻头项难转。
人人共恶难廻跋，潜遣飞龙减刍秣。
银鞍绣韂不复施，空尽天年御槽活。
当时邹谚已有言，莫倚功高浪开阔。
登山纵似望云骓，平地须饶红叱拨。
长安三月花垂草，果下翩翩紫骝好。
千官暖热李令闲，百马生狞望云老。
望云骓，尔之种类世世奇。
当时项王乘尔祖，分配英豪称霸王。
尔身今日逢圣人，从幸巴渝归入秦。
功成事遂身退天之道，何必随羣逐队到死蹋红尘。
望云骓，用与不用各有时，尔勿悲。','',''),('quantangshi-21776','和李校书新题乐府十二首 上阳白发人','稹','quantangshi','','卷22','天宝年中花鸟使，撩花狎鸟含春思。
满怀墨诏求嫔御，走上高楼半酣醉。
醉酣直入卿士家，闺闱不得偷廻避。
良人顾妾心死别，小女呼爷血垂泪。
十中有一得更衣，永配深宫作宫婢。
御马南奔胡马蹙，宫女三千合宫弃。
宫门一闭不复开，上阳花草青苔地。
月夜闲闻洛水声，秋池暗度风荷气。
日日长看提众门，终身不见门前事。
近年又送数人来，自言兴庆南宫至。
我悲此曲将彻骨，更想深冤复酸鼻。
此辈贱嫔何足言，帝子天孙古称贵。
诸王在合四十年，七宅六宫门户閟。
隋炀枝条袭封邑，肃宗血胤无官位。
王无妃媵主无壻，阳亢阴淫结灾累。
何如决壅顺众流，女遣从夫男作吏。','',''),('quantangshi-21777','和李校书新题乐府十二首 华原磬','稹','quantangshi','','卷22','泗滨浮石裁为磬，古乐疎音少人听。
工师小贱牙旷稀，不辨邪声嫌雅正。
正声不屈古调高，钟律参差管弦病。
铿金戛瑟徒相杂，投玉敲冰杳然零。
华原輭石易追琢，高下随人无雅郑。
弃旧美新由乐胥，自此黄钟不能竞。
玄宗爱乐爱新乐，梨园弟子承恩横。
霓裳才彻胡骑来，云门未得蒙亲定。
我藏古磬藏在心，有时激作南风咏。
伯夔曾抚野兽驯，仲尼暂叩春雷盛。
何时得向笋簴悬，为君一吼君心醒。
愿君每听念封疆，不遣豺狼剿人命。','',''),('quantangshi-21778','和李校书新题乐府十二首 五弦弹','稹','quantangshi','','卷22','赵璧五弦弹征调，征声巉绝何清峭。
辞雄皓鹤警露啼，失子哀猿绕林啸。
风入春松正凌乱，莺含晓舌怜娇妙。
呜呜暗溜咽冰泉，杀杀霜刀涩寒鞘。
促节频催渐繁拨，珠幢斗绝金铃掉。
千靫鸣镝发胡弓，万片清球击虞庙。
众乐虽同第一部，德宗皇帝常偏召。
旬休节假暂归来，一声狂杀长安少。
主第侯家最难见，挼歌按曲皆承诏。
水精帘外教贵嫔，瑇瑁筵心伴中要。
臣有五贤非此弦，或在拘囚或屠钓。
一贤得进胜累百，两贤得进同周召。
三贤事汉灭暴彊，四贤镇岳宁边徼。
五贤竝用调五常，五常既叙三光耀。
赵璧五弦非此贤，九九何劳设庭燎。','',''),('quantangshi-21779','和李校书新题乐府十二首 西凉伎','稹','quantangshi','','卷22','吾闻昔日西凉州，人烟扑地桑柘稠。
蒲萄酒熟恣行乐，红艳青旗朱粉楼。
楼下当垆称卓女，楼头伴客名莫愁。
乡人不识离别苦，更卒多为沈滞游。
哥舒开府设高宴，八珍九酝当前头。
前头百戏竞撩乱，丸劒跳踯霜雪浮。
狮子摇光毛彩竖，胡腾醉舞筋骨柔。
大宛来献赤汗马，赞普亦奉翠茸裘。
一朝燕贼乱中国，河湟没尽空遗丘。
开远门前万里堠，今来蹙到行原州。
去京五百而近何其逼，天子县内半没为荒陬。
西凉之道尔阻修，连城边将但高会，每听此曲能不羞。','',''),('quantangshi-21780','和李校书新题乐府十二首 法曲','稹','quantangshi','','卷22','吾闻黄帝鼓清角，弭伏熊罴舞玄鹤。
舜持干羽苗革心，尧用咸池凤巢阁。
大夏濩武皆象功，功多已讶玄功薄。
汉祖过沛亦有歌，秦王破阵非无作。
作之宗庙见艰难，作之军旅传糟粕。
明皇度曲多新态，宛转侵淫易沈着。
赤白桃李取花名，霓裳羽衣号天落。
雅弄虽云已变乱，夷音未得相参错。
自从胡骑起烟尘，毛毳腥膻满咸洛。
女为胡妇学胡妆，伎进胡音务胡乐。
火凤声沈多咽绝，春莺啭罢长萧索。
胡音胡骑与胡妆，五十年来竞纷泊。','',''),('quantangshi-21781','和李校书新题乐府十二首 驯犀','稹','quantangshi','','卷22','建中之初放驯象，远归林邑近交广。
兽返深山鸟构巢，鹰雕鹞鹘无羁鞅。
贞元之岁贡驯犀，上林置圈官司养。
玉盆金栈非不珍，虎噉狴牢鱼食网。
渡江之橘逾汶貉，反时易性安能长。
腊月北风霜雪深，蜷局鳞身遂长往。
行地无疆费传驿，通天异物罹幽枉。
乃知养兽如养人，不必人人自敦奖。
不扰则得之于理，不夺有以多于赏。
脱衣推食衣食之，不若男耕女令纺。
尧民不自知有尧，但见安闲聊击壤。
前观驯象后驯犀，理国其如指诸掌。','',''),('quantangshi-21782','和李校书新题乐府十二首 立部伎','稹','quantangshi','','卷22','胡部新声锦筵坐，中庭汉振高音播。
太宗庙乐传子孙，取类羣凶阵初破。
戢戢攒枪霜雪耀，腾腾击鼓云雷磨。
初疑遇敌身启行，终象由文士宪左。
昔日高宗常立听，曲终然后临玉座。
如今节将一掉头，电卷风收尽摧挫。
宋晋郑女歌声发，满堂会客齐喧㰤。
珊珊佩玉动腰身，一一贯珠随咳唾。
顷向圜丘见郊祀，亦曾正旦亲朝贺。
太常雅乐备宫悬，九奏未终百寮惰。
惉滞难令季札辨，迟廻但恐文侯卧。
工师尽取聋昧人，岂是先王作之过。
宋沇尝传天宝季，法曲胡音忽相和。
明年十月燕寇来，九庙千门虏尘涴我闻此语叹复泣，古来邪正将谁奈。
奸声入耳佞入心，侏儒饱饭夷齐饿。','',''),('quantangshi-21783','和李校书新题乐府十二首 骠国乐','稹','quantangshi','','卷22','骠之乐器头象驼，音声不合十二和。
促舞跳趫筋节硬，繁辞变乱名字讹。
千弹万唱皆咽咽，左旋右转空傞傞。
俯地呼天终不会，曲成调变当如何。
德宗深意在柔远，笙镛不御停娇娥。
史馆书为朝贡传，太常编入鞮靺科。
古时陶尧作天子，逊遁亲听康衢歌。
又遣遒人持木铎，徧采讴谣天下过。
万人有意皆洞达，四岳不敢施烦苛。
尽令区中击壤块，燕及海外覃恩波。
秦霸周衰古官废，下堙上塞王道颇。
共矜异俗同声教，不念齐民方荐瘥。
传称鱼鼈亦咸若，苟能效此诚足多。
借如牛马未蒙泽，岂在抱瓮滋鼋鼍。
教化从来有源委，必将泳海先泳河。
是非倒置自古有，骠兮骠兮谁尔诃。','',''),('quantangshi-21784','和李校书新题乐府十二首 胡旋女','稹','quantangshi','','卷22','天宝欲末胡欲乱，胡人献女能胡旋。
旋得明王不觉迷，妖胡奄到长生殿。
胡旋之义世莫知，胡旋之容我能传。
蓬断霜根羊角疾，竿戴朱盘火轮炫。
骊珠迸珥逐飞星，虹晕轻巾掣流电。
潜鲸暗噏笡波海，回风乱舞当空霰。
万过其谁辨终始，四座安能分背面。
才人观者相为言，承奉君恩在圜变。
是非好恶随君口，南北东西逐君眄。
柔輭依身着佩带，裴回绕指同环钏。
佞臣闻此心计回，荧惑君心君眼眩。
君言似曲屈为钩，君言好直舒为箭。
巧随清影触处行，妙学春莺百般啭。
倾天侧地用君力，抑塞周遮恐君见。
翠华南幸万里桥，玄宗始悟坤维转寄言旋目与旋心，有国有家当共谴。','',''),('quantangshi-21785','和李校书新题乐府十二首 蛮子朝','稹','quantangshi','','卷22','西南六诏有遗种，僻在荒陬路寻壅。
部落支离君长贱，比诸夷狄为幽冗。
犬戎彊盛频侵削，降有愤心战无勇。
夜防抄盗保深山，朝望烟尘上高冢。
鸟道绳桥来款附，非因慕化因危悚。
清平官系金呿嵯，求天叩地持双珙。
益州大将韦令公，顷实遭时定汧陇。
自居剧镇无他绩，幸得蛮来固恩宠。
为蛮开道引蛮朝，迎蛮送蛮常继踵。
天子临轩四方贺，朝廷无事唯端拱。
漏天走马春雨寒，泸水飞蛇瘴烟重。
椎头丑类除忧患，瘇足役夫劳汹涌。
匈奴互市岁不供，云蛮通好辔长駷。
戎王养马渐多年，南人耗顇西人恐。','',''),('quantangshi-21786','和李校书新题乐府十二首 缚戎人','稹','quantangshi','','卷22','边头大将差健卒，入抄禽生快于鹘。
但逢赬面即捉来，半是边人半戎羯。
大将论功重多级，捷书飞奏何超忽。
圣朝不杀谐至仁，远送炎方示微罚。
万里虚劳肉食费，连头尽被毡裘暍。
华裀重席卧腥臊，病犬愁鸪声咽嗢。
中有一人能汉语，自言家本长城窟。
少年随父戍安西，河渭瓜沙眼看没。
天宝未乱犹数载，狼星四角光蓬勃。
中原祸作边防危，果有豺狼四来伐。
蕃马膘成正翘健，蕃兵肉饱争唐突。
烟尘乱起无亭燧，主帅惊跳弃旄钺。
半夜城摧鹅雁鸣，妻啼子叫曾不歇。
阴森神庙未敢依，脆薄河冰安可越。
荆棘深处共潜身，前困蒺藜后臲卼。
平明蕃骑四面走，古墓深林尽株榾。
少壮为俘头被髠，老翁留居足多刖。
乌鸢满野尸狼藉，楼榭成灰墙突兀。
暗水溅溅入旧池，平沙漫漫铺明月。
戎王遣将来安慰，口不敢言心咄咄。
供进腋腋御叱般，岂料穹庐拣肥腯。
五六十年消息绝，中间盟会又猖獗。
眼穿东日望尧云，肠断正朝梳汉发。
近年如此思汉者，半为老病半埋骨。
常教孙子学乡音，犹话平时好城阙。
老者傥尽少者壮，生长蕃中似蕃悖。
不知祖父皆汉民，便恐为蕃心矻矻。
缘边饱餧十万众，何不齐驱一时发。
年年但捉两三人，精卫衔芦塞溟渤。','',''),('quantangshi-21787','和李校书新题乐府十二首 阴山道','稹','quantangshi','','卷22','年年买马阴山道，马死阴山帛空耗。
元和天子念女工，内出金银代酬犒。
臣有一言昧死进，死生甘分答恩焘。
费财为马不独生，耗帛伤工有他盗。
臣闻平时七十万匹马，关中不省闻嘶噪。
四十八监选龙媒，时贡天庭付良造。
如今坰野十无一，尽在飞龙相践暴。
万束刍茭供旦暮，千钟菽粟长牵漕。
屯军郡国百余镇，缣缃岁奉春冬劳。
税户逋逃例摊配，官司折纳仍贪冒。
挑纹变䌰力倍费，弃旧从新人所好。
越縠缭绫织一端，十匹素缣功未到。
豪家富贾逾常制，令族清班无雅操。
从骑爱奴丝布衫，臂鹰小儿云锦韬。
羣臣利己要差僭，天子深衷空悯悼。
绰立花塼鵷凤行，雨露恩波几时报。','',''),('quantangshi-21788','有鸟二十章 一','稹','quantangshi','','卷22','有鸟有鸟名老鸱，鸱张贪很老不衰。
似鹰指爪唯攫肉，戾天羽翮徒翰飞。
朝偷暮窃恣昏饱，后顾前瞻高树枝。
珠丸弹射死不去，意在护巢兼护儿。','',''),('quantangshi-21789','有鸟二十章 二','稹','quantangshi','','卷22','有鸟有鸟毛似鹤，行步虽迟性灵恶。
主人但见闲慢容，许占蓬莱最高阁。
弱羽长忧俊鹘拳，疽肠暗着鵷雏啄。
千年不死伴灵龟，枭心鹤貌何人觉。','',''),('quantangshi-21790','有鸟二十章 三','稹','quantangshi','','卷22','有鸟有鸟如鹳雀，食蛇抱礐天姿恶。
行经水浒为毒流，羽拂酒杯为死药。
汉后忍渴天岂知，骊姬坟地君宁觉。
呜呼为有白色毛，亦得乘轩谬称鹤。','',''),('quantangshi-21791','有鸟二十章 四','稹','quantangshi','','卷22','有鸟有鸟名为鸠，毛衣輭毳心性柔。
鹘缘暖足怜不吃，鹞为同科曾共游。
飞飞渐上高高阁，百鸟不猜称好逑。
佳人许伴鵷雏食，望尔化为张氏钩。','',''),('quantangshi-21792','有鸟二十章 五','稹','quantangshi','','卷22','有鸟有鸟名野鸡，天姿耿介行步齐。
主人偏养怜整顿，玉粟充肠瑶树栖。
池塘潜狎不鸣雁，津梁暗引无用鹈。
秋鹰迸逐霜鹘远，鵩鸟护巢当昼啼。
主人频问遣妖术，力尽计穷音响凄。
当时何不早量分，莫遣辉光深照泥。','',''),('quantangshi-21793','有鸟二十章 六','稹','quantangshi','','卷22','有鸟有鸟羣翠碧，毛羽短长心竝窄。
皆曾偷食渌池鱼，前去后来更逼迫。
食鱼满腹各自飞，池上见人长似客。
飞飞竞占嘉树林，百鸟不争缘凤惜。','',''),('quantangshi-21794','有鸟二十章 七','稹','quantangshi','','卷22','有鸟有鸟羣纸鸢，因风假势童子牵。
去地渐高人眼乱，世人为尔羽毛全。
风吹绳断童子走，余势尚存犹在天。
愁尔一朝还到地，落在深泥谁复怜。','',''),('quantangshi-21795','有鸟二十章 八','稹','quantangshi','','卷22','有鸟有鸟名啄木，木中求食常不足。
偏啄邓林求一虫，虫孔未穿长觜秃。
木皮已穴虫在信，虫蚀木心根柢覆。
可怜树上百鸟儿，有时飞向新林宿。','',''),('quantangshi-21796','有鸟二十章 九','稹','quantangshi','','卷22','有鸟有鸟众蝙蝠，长伴佳人占华屋。
妖鼠多年羽翮生，不辨雌雄无本族。
穿墉伺隙善潜身，昼伏宵飞恶明烛。
大厦虽存柱石倾，暗啮栋梁成蠹木。','',''),('quantangshi-21797','有鸟二十章 十','稹','quantangshi','','卷22','有鸟有鸟名为鸮，深藏孔穴难动摇。
鹰鹯绕树探不得，随珠弹尽声转娇。
主人烦惑罢擒取，许占神林为物妖。','',''),('quantangshi-21798','有鸟二十章 十一','稹','quantangshi','','卷22','有鸟有鸟名燕子，口中未省无泥滓。
春风吹送廊庑间，秋社驱将嵌孔里。
雷惊雨洒一时苏，云压霜摧半年死。
驱去驱来长信风，暂托栋梁何用喜。','',''),('quantangshi-21799','有鸟二十章 十二','稹','quantangshi','','卷22','有鸟有鸟名老乌，贪痴突誖天下无。
田中攫肉吞不足，偏入诸巢探众雏。
归来仍占主人树，腹饱巢高声响麤。
山鵶野鹊闲受肉，凤皇不得闻罪辜。
秋鹰掣断架上索，利爪一挥毛血落。
可怜鵶鹊慕腥膻，犹向巢边竞纷泊。','',''),('quantangshi-21800','有鸟二十章 十三','稹','quantangshi','','卷22','有鸟有鸟谓白鹇，雪毛皓白红觜殷。
贵人妾妇爱光彩，行提坐臂怡朱颜。
妖姬谢宠辞金屋，雕笼又伴新人宿。
无心为主拟衔花，空长白毛映红肉。','',''),('quantangshi-21801','有鸟二十章 十四','稹','quantangshi','','卷22','有鸟有鸟羣雀儿，中庭啄粟篱上飞。
秋鹰欺小嫌不食，凤皇容众从尔随。
大鹏忽起遮白日，余风簸荡山岳移。
翩翾百万徒惊噪，扶摇势远何由知。
古来妄说衔花报，纵解衔花何所为。
可惜官仓无限粟，伯夷饿死黄口肥。','',''),('quantangshi-21802','有鸟二十章 十五','稹','quantangshi','','卷22','有鸟有鸟皆百舌，舌端百啭声咄㗌。
先春尽学百鸟啼，真伪不分听者悦。
伶伦凤律乱宫商，盘木天鸡误时节。
朝朝暮暮主人耳，桃李无言管弦咽。
五月炎光朱火盛，阳焰烧阴幽响绝。
安知不是卷舌星，化作刚刀一时截。','',''),('quantangshi-21803','有鸟二十章 十六','稹','quantangshi','','卷22','有鸟有鸟毛羽黄，雄者为鸳雌者鸯。
主人并养七十二，罗列雕笼开洞房。
雄鸣一声雌鼓翼，夜不得栖朝不食。
气息榻然双翅垂，犹入笼中就颜色。','',''),('quantangshi-21804','有鸟二十章 十七','稹','quantangshi','','卷22','有鸟有鸟名鹞雏，铃子眼睛苍锦襦。
贵人腕輭怜易臂，奋肘一挥前后呼。
俊鹘无由拳狡兔，金雕不得擒魅狐。
文王长在苑中猎，何日非熊休卖屠。','',''),('quantangshi-21805','有鸟二十章 十八','稹','quantangshi','','卷22','有鸟有鸟名鹦鹉，养在雕笼解人语。
主人曾问私所闻，因说妖姬暗欺主。
主人方惑翻见疑，趁归陇底双翅垂。
山鵶野雀怪鹦语，竞噪争窥无已时。
君不见隋朝陇头姥，娇养双鹦嘱新妇。
一鹦曾说妇无仪，悍妇杀鹦欺主母。
一鹦闭口不复言，母问不言何太久。
鹦言悍妇杀鹦由，母为逐之乡里丑。
当时主母信尔言，顾尔微禽命何有。
今之主人翻尔疑，何事笼中漫开口。','',''),('quantangshi-21806','有鸟二十章 十九','稹','quantangshi','','卷22','有鸟有鸟名俊鹘，鹞小雕痴俊无匹。
雏鸭拂爪血迸天，狡兔中拳头粉骨。
平明度海朝未食，拔上秋空云影没。
瞥然飞下人不知，搅碎荒城魅狐窟。','',''),('quantangshi-21807','有鸟二十章 二十','稹','quantangshi','','卷22','有鸟有鸟真白鹤，飞上九霄云漠漠。
司晨守夜悲鸡犬，啄腐吞腥笑雕鹗。
尧年值雪度关山，晋室闻琴下寥廓。
辽东尽尔千岁人，怅望桥边旧城郭。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21808','有酒十章 一','稹','quantangshi','','卷22','有酒有酒鸡初鸣，夜长睡足神虑清。
悄然危坐心不平，浩思一气初彭亨。
澒洞浩汗真无名，胡不终浑成。
胡为沈浊以升清，矗然分画高下程。
天蒸地郁羣动萌，毛鳞裸介如鬇鬡。
呜呼万物纷已生，我可奈何兮杯一倾。','',''),('quantangshi-21809','有酒十章 二','稹','quantangshi','','卷22','有酒有酒东方明，一杯既进吞元精。
尚思天地之始名，一元既二分浊清。
地居方直天体明，胡不八荒圢圢如砥平。
胡山高屹崪海泓澄，胡不日车杲杲昼夜行。
胡为月轮灭缺星𥋝盯，呜呼不得真宰情，我可奈何兮杯再倾。','',''),('quantangshi-21810','有酒十章 三','稹','quantangshi','','卷22','有酒有酒兮湛渌波，饮将愉兮气弥和。
念万古之纷罗，我独慨然而浩歌。
歌曰：天耶，地耶。
肇万物耶，储胥大庭之君耶。
恍耶，忽耶。
有耶，传而信耶。
久而谬耶，文字生而羲农作耶。
仁义别而圣贤出耶，炎始暴耶。
蚩尤炽耶，轩辕战耶。
不得已耶，仁耶。
圣耶，愍人之毒耶。
天荡荡耶，尧穆穆耶。
岂其让耶，归有德耶。
舜其贪耶，德能嗣耶。
岂其让耶，授有功耶。
禹功大耶，人戴之耶。
益不逮耶，启能德耶。
家天下耶，荣后嗣耶。
于后嗣之荣则可耶，于天下之荣其可耶。
呜呼远尧舜之日耶，何弃舜之速耶。
辛癸虐耶，汤武革耶。
顺天意耶，公天下耶。
踵夏荣嗣，私其公耶。
竝建万国，均其私耶。
专征递伐，鬬海内耶。
秦埽其类，威定之耶。
二代而陨，守不仁耶。
汉魏而降，乘其机耶。
短长理乱，系其术耶。
尧耶，舜耶。
终不可逮耶，将德之者不位。
位者不逮其德耶，时耶。
时耶，时其可耶，我可奈何兮一杯又进歌且歌。','',''),('quantangshi-21811','有酒十章 四','稹','quantangshi','','卷22','有酒有酒兮黯兮溟，仰天大呼兮。
天漫漫兮高兮青，高兮漫兮吾孰知天否与灵。
取人之仰者，无乃在乎昭昭乎曰与夫日星。
何三光之竝照兮，奄云雨之冥冥。
幽妖倏忽兮水怪族形，鼋鼍岸走兮海若鬬鲸。
河溃溃兮愈浊，济翻翻兮不宁。
蛇喷云而出穴，虎啸风兮屡鸣。
污高巢而凤去兮，溺厚地而芝兰以之不生。
葵心倾兮何向，松影直而孰明。
人惧愁兮戴荣，天寂默兮无声。
呜呼！天在云之上兮，人在云之下兮。
又安能决云而上征，呜呼。
既上征之不可兮，我奈何兮杯复倾。','',''),('quantangshi-21812','有酒十章 五','稹','quantangshi','','卷22','有酒有酒香满尊，君宁不饮开君颜。
岂不知君饮此心恨，君今独醒谁与言。
君宁不见飓风翻海火燎原，巨鳌唐突高焰延。
精卫衔芦塞海溢，枯鱼喷沫救池燔。
筋疲力竭波更大，鳍燋甲裂身已干。
有翼劝尔升九天，有鳞劝尔登龙门。
九天下视日月转，龙门上激雷雨奔。
螗蜋虽怒谁尔惧，鹖旦虽啼谁尔怜。
抟空意远风来壮，我可奈何兮一杯又进消我烦。','',''),('quantangshi-21813','有酒十章 六','稹','quantangshi','','卷22','有酒有酒歌且哀，江春例早多早梅。
樱桃桃李相续开，间以木兰之秀香裴回。
东风吹尽南风来，莺声渐涩花摧颓。
四月清和艳残卉，芍药翻红蒲映水。
夏龙痡毒雷雨多，蒲叶离披艳红死。
红艳犹存榴树花，紫苞欲绽高笋牙。
笋牙成竹冒霜雪，榴花落地还销歇。
万古盈亏相逐行，君看夜夜当窗月。
荣落亏盈可奈何，生成未徧霜霰过。
霜霰过兮复奈何，灵芝敻绝荆棘多。
荆棘多兮可奈何，可奈何兮终奈何。
秦皇尧舜俱腐骨，我可奈何兮又进一杯歌复歌。','',''),('quantangshi-21814','有酒十章 七','稹','quantangshi','','卷22','有酒有酒方烂漫，饮酣拔劒心眼乱。
声若雷砰目流电，醉舞翻环身眩转。
干纲倒轧坤维旋，白日横空星宿见，一夫心醉万物变。
何况蚩尤之蹴蹋，安得不以熊罴战。
呜呼！风后力牧得亲见，我可奈何兮又进一杯除健羡。','',''),('quantangshi-21815','有酒十章 八','稹','quantangshi','','卷22','有酒有酒兮告临江，风漫漫兮波长。
渺渺兮注海，海苍苍兮路茫茫。
彼万流之混入兮，又安能分若畎浍淮河与夫岷吴之巨江。
味作咸而若一，虽甘淡兮谁谓尔为良。
济涓涓而缕贯，将奈何兮万里之浑黄。
鲸归穴兮渤溢，鳌载山兮低昂。
阴火然兮众族沸渭，飓风作兮昼夜猖狂。
顾千珍与万怪兮，皆委润而深藏。
信天地之潴蓄兮，我可奈何兮一杯又进兮包大荒。','',''),('quantangshi-21816','有酒十章 九','稹','quantangshi','','卷22','有酒有酒兮日将落，余光委照在林薄。
阳乌撩乱兮屋上栖，阴怪跳趫兮水中跃。
月争光兮星又繁，烧横空兮焰仍烁。
我可奈何兮时既昏，一杯又进兮聊处廓。','',''),('quantangshi-21817','有酒十章 十','稹','quantangshi','','卷22','有酒有酒兮再祝，祝予心兮何欲。
欲天泰而地宁，欲人康而岁熟。
欲凤翥而鵷随兮，欲龙亨而骥逐。
欲日盛而星微兮，欲滋兰而歼毒。
欲人欲而天从，苟天未从兮，我可奈何兮一杯又进聊自足。','',''),('quantangshi-21818','华之巫','稹','quantangshi','','卷22','有一人兮神之侧，庙森森兮神默默。
神默默兮可奈何，愿一见神兮何可得。
女巫索我何所有，神之开闭予之手。
我能进若神之前，神不自言寄予口。
尔欲见神安尔身，买我神钱沽我酒。
我家又有神之盘，尔进此盘神尔安。
此盘不进行路难，陆有摧车舟有澜。
我闻此语长太息，岂有神明欺正直。
尔居大道谁南北，恣矫神言假神力。
假神力兮神未悟，行道之人不得度。
我欲见神诛尔巫，岂是因巫假神祜。
尔巫，尔巫。
尔独不闻乎？
与其媚于奥，不若媚于竈。
使我倾心事尔巫，吾宁驱车守吾道。
尔巫尔巫且相保，吾心自有丘之祷。','',''),('quantangshi-21819','庙之神','稹','quantangshi','','卷22','我马烦兮释我车，神之庙兮山之阿。
予一拜而一祝，祝予心之无涯。
涕丸澜而零落，神寂默而无哗。
神兮，神兮。
奈神之寂默而不言何，复再拜而再祝。
鼓吾腹兮歌吾歌，歌曰。
今耶，古耶。
有耶，无耶。
福不自神耶，神不福人耶。
巫尔惑耶，稔而诛耶。
谒不得耶，终不可谒耶。
返吾驾而遵吾道，庙之木兮山之花。','',''),('quantangshi-21820','村花晚','稹','quantangshi','','卷22','三春已暮桃李伤，棠梨花白蔓菁黄。
村中女儿争摘将，插刺头鬓相夸张。
田翁蚕老迷臭香，晒暴𢽱𣀳熏衣裳。
非无后秀与孤芳，奈尔千株万顷之茫茫。
天公此意何可量，长教尔辈时节长。','',''),('quantangshi-21821','紫踯躅','稹','quantangshi','','卷22','紫踯躅，灭紫拢帬倚山腹。
文君新寡乍归来，羞怨春风不能哭。
我从相识便相怜，但是花丛不回目。
去年春别湘水头，今年夏见青山曲。
迢迢远在青山上，山高水阔难容足。
愿为朝日早相暾，愿作轻风暗相触。
尔踯躅，我向通州尔幽独。
可怜今夜宿青山，何年却向青山宿。
山花渐暗月渐明，月照空山满山绿。','',''),('quantangshi-21822','山枇杷','稹','quantangshi','','卷22','山枇杷，花似牡丹殷泼血。
往年乘传过青山，正值山花好时节。
压枝凝艳已全开，映叶香苞才半裂。
紧搏红袖欲支颐，慢解绛囊初破结。
金线丛飘繁蘂乱，珊瑚朵重纤茎折。
因风旋落帬片飞，带日斜看目精热。
亚水依岩半倾侧，笼云隐雾多愁绝。
绿珠语尽身欲投，汉武眼穿神渐灭。
穠姿秀色人皆爱，怨媚羞容我偏别。
说向闲人人不听，曾向乐天时一说。
昨来谷口先相问，及到山前已消歇。
左降通州十日迟，又与幽花一年别。
山枇杷，尔托深山何太拙。
天高万里看不精，帝在九重声不彻。
园中杏树良人醉，陌上柳枝年少折。
因尔幽芳喻昔贤，磻溪冷坐权门咽。','',''),('quantangshi-21823','树上乌','稹','quantangshi','','卷22','树上乌，洲中有树巢若铺。
百巢一树知几乌，一乌不下三四雏。
雏又生雏知几雏，老乌未死雏已乌。
散向人间何处无，攫麑啄卵方可食。
男女羣强最多力，灵蛇万古唯一珠。
岂可抨弹千万亿，吾不会天教尔辈多子孙，告诉天公天不言。','',''),('quantangshi-21824','琵琶歌','稹','quantangshi','','卷22','琵琶宫调八十一，旋宫三调弹不出。
玄宗偏许贺怀智，段师此艺还相匹。
自后流传指拨衰，昆仑善才徒尔为。
澒声少得似雷吼，缠弦不敢弹羊皮。
人间奇事会相续，但有卞和无有玉。
段师弟子数十人，李家管儿称上足。
管儿不作供奉儿，抛在东都双鬓丝。
逢人便请送杯盏，着尽工夫人不知。
李家兄弟皆爱酒，我是酒徒为密友。
着作曾邀连夜宿，中碾春溪华新绿。
平明船载管儿行，尽日听弹无限曲。
曲名无限知者鲜，霓裳羽衣偏宛转。
凉州大徧最豪嘈，六么散序多笼拈。
我闻此曲深赏奇，赏着奇处惊管儿。
管儿为我双泪垂，自弹此曲长自悲。
泪垂捍拨朱弦湿，冰泉呜咽流莺涩。
因兹弹作雨霖铃，风雨萧条鬼神泣。
一弹既罢又一弹，珠幢夜静风珊珊。
低回慢弄关山思，坐对燕然秋月寒。
月寒一声深殿磬，骤弹曲破音繁并。
百万金铃旋玉盘，醉客满船皆暂醒。
自兹听后六七年，管儿在洛我朝天。
游想慈恩杏园里，梦寐仁风花树前。
去年御史留东台，公私蹙促颜不开。
今春制狱正撩乱，昼夜推囚心似灰。
暂辍归时寻着作，着作南园花坼萼。
胭脂耀眼桃正红，雪片满溪梅已落。
是夕青春值三五，花枝向月云含吐。
着作施罇命管儿，管儿久别今方覩。
管儿还为弹六么，六么依旧声迢迢。
猿鸣雪岫来三峡，鹤唳晴空闻九霄。
逡巡弹得六么彻，霜刀破竹无残节。
幽关鵶轧胡雁悲，断弦砉騞层冰裂。
我为含凄叹奇绝，许作长歌始终说。
艺奇思寡尘事多，许来寒暑又经过。
如今左降在闲处，始为管儿歌此歌。
歌此歌，寄管儿，管儿管儿忧尔衰。
尔衰之后继者谁，继之无乃在铁山。
铁山已近曹穆间，性灵甚好功犹浅。
急处未得臻幽闲，努力铁山勤学取，莫遣后来无所祖。','',''),('quantangshi-21825','小胡笳引','稹','quantangshi','','卷22','雷氏金徽琴，王君宝重轻千金。
三峡流中将得来，明窗拂席幽匣开。
朱弦宛转盘凤足，骤击数声风雨回。
哀笳慢指董家本，姜生得之妙思忖。
泛徽胡雁咽萧萧，绕指辘轳圆衮衮。
吞恨缄情乍轻激，故国关山心历历。
潺湲疑是雁䴙鹈，砉騞如闻发鸣镝。
流宫变征渐幽咽，别鹤欲飞猿欲绝。
秋霜满树叶辞风，寒雏坠地乌啼血。
哀弦已罢春恨长，恨长何恨怀我乡。
我乡安在长城窟，闻君虏奏心飘忽。
何时窄袖短貂裘，胭脂山下弯明月。','',''),('quantangshi-21826','去杭州','稹','quantangshi','','卷22','房杜王魏之子孙，虽及百代为清门。
骏骨凤毛真可贵，冈头泽底何足论。
去年江上识君面，爱君风貌情已敦。
与君言语见君性，灵府坦荡消尘烦。
自兹心洽迹亦洽，居常并榻游竝轩。
柳阴覆岸郑监水，李花压树韦公园。
每出新诗共联缀，闲因醉舞相牵援。
时寻沙尾枫林夕，夜摘兰丛衣露繁。
今君别我欲何去，自言远结迢迢婚。
简书五府已再至，波涛万里酬一言。
为君再拜赠君语，愿君静听君勿喧。
君名师范欲何范，君之烈祖遗范存。
永宁昔在抡鉴表，沙汰沈浊澄浚源。
君今取友由取士，得不别白清与浑。
昔公事主尽忠谠，虽及死谏誓不谖。
今君佐藩如佐主，得不陈露酬所恩。
昔公为善日不足，假寐待旦朝至尊。
今君三十朝未与，得不寸晷倍璵璠。
昔公令子尚贵主，公执舅礼妇执笲。
返拜之仪自此绝，关雎之化皎不昏。
君今远娉奉明祀，得不齐励亲苹蘩。
斯言皆为书佩带，然后别袂乃可扪。
别袂可扪不可解，解袂开帆凄别魂。
魂摇江树鸟飞没，帆挂樯竿鸟尾翻。
翻风驾浪拍何处，直指杭州由上元。
上元萧寺基址在，杭州潮水霜雪屯。
潮户迎潮击潮鼓，潮平潮退有潮痕。
得得为题罗刹石，古来非独伍员冤。','',''),('quantangshi-21827','南家桃','稹','quantangshi','','卷22','南家桃树深红色，日照露光看不得。
树小花狂风易吹，一夜风吹满墙北。
离人自有经时别，眼前落花心叹息。
更待明年花满枝，一年迢递空相忆。','',''),('quantangshi-21828','志坚师','稹','quantangshi','','卷22','嵩山老僧披破衲，七十八年三十腊。
灵武朝天辽海征，宇宙曾行三四匝。
初因怏怏剃却头，便绕嵩山寂师墖。
淮西未返半年前，已见淮西阵云合。','',''),('quantangshi-21829','答子蒙','稹','quantangshi','','卷22','报卢君，门外雪纷纷。
纷纷门外雪，城中鼓声绝。
强梁御史人覰步，安得夜开沽酒户。','',''),('quantangshi-21830','辛夷花','稹','quantangshi','','卷22','问君辛夷花，君言已斑驳。
不畏辛夷不烂开，顾我筋骸官束缚。
缚遣推囚名御史，狼藉囚徒满田地。
明日不推缘国忌，依前不得花前醉。
韩员外家好辛夷，开时乞取三两枝。
折枝为赠君莫惜，纵君不折风亦吹。','',''),('quantangshi-21831','厅前柏','稹','quantangshi','','卷22','厅前柏，知君曾对罗希奭。
我本癫狂耽酒人，何事与君为对敌。
为对敌，洛阳城中花赤白。
花赤白，囚渐多，花之赤白奈尔何。','',''),('quantangshi-21832','夜别筵','稹','quantangshi','','卷22','夜长酒阑灯花长，灯花落地复落牀。
似我别泪三四行，滴君满坐之衣裳。
与君别后泪痕在，年年着衣心莫改。','',''),('quantangshi-21833','三泉驿','稹','quantangshi','','卷22','三泉驿内逢上巳，新叶趋尘花落地。
劝君满盏君莫辞，别后无人共君醉。
洛阳城中无限人，贵人自贵贫自贫。','',''),('quantangshi-21834','何满子歌','稹','quantangshi','','卷22','何满能歌能宛转，天宝年中世称罕。
婴刑击在囹圄间，水调哀音歌愤懑。
梨园弟子奏玄宗，一唱承恩羁网缓。
便将何满为曲名，御谱亲题乐府纂。
鱼家入内本领绝，叶氏有年声气短。
自外徒烦记得词，点拍才成已夸诞。
我来湖外拜君侯，正值灰飞仲春琯。
广宴江亭为我开，红妆逼坐花枝暖。
此时有态蹋华筵，未吐芳词貌夷坦。
翠蛾转盼摇雀钗，碧袖歌垂翻鹤卵。
定面凝眸一声发，云停尘下何劳算。
迢迢击磬远玲玲，一一贯珠匀款款。
犯羽含商移调态，留情度意抛弦管。
湘妃宝瑟水上来，秦女玉箫空外满。
缠緜叠破最殷勤，整顿衣裳颇闲散。
冰含远溜咽还通，莺泥晚花啼渐嬾。
敛黛吞声若自冤，郑袖见捐西子浣。
阴山鸣雁晓断行，巫峡哀猿夜呼伴。
古者诸侯飨外宾，鹿鸣三奏陈圭瓒。
何如有态一曲终，牙筹记令红螺盌。','',''),('quantangshi-21835','通州丁溪馆夜别李景信三首 一','稹','quantangshi','','卷22','月蒙蒙兮山掩掩，束束别魂眉歛歛。
蠡琖覆时天欲明，碧幌青灯风滟滟。
泪消语尽还暂眠，唯梦千山万山险。','',''),('quantangshi-21836','通州丁溪馆夜别李景信三首 二','稹','quantangshi','','卷22','水环环兮山簇簇，啼鸟声声妇人哭。
离牀别脸睡还开，灯灺暗飘珠蔌蔌。
山深虎横馆无门，夜集巴儿扣空木。','',''),('quantangshi-21837','通州丁溪馆夜别李景信三首 三','稹','quantangshi','','卷22','雨潇潇兮鹃咽咽，倾冠倒枕灯临灭。
倦僮呼唤譍复眠，啼鸡拍翅三声绝。
握手相看其奈何，奈何其奈天明别。','',''),('quantangshi-21838','酬郑从事四年九月宴望海亭次用旧韵','稹','quantangshi','','卷22','海亭树木何茏葱，寒光透坼秋玲珑。
湖山四面争气色，旷望不与人间同。
一拳墺伏东武小，两山鬬构秦望雄。
嵌空古墓失文种，突兀怪石疑防风。
舟船骈比有宗侣，水云滃泱无始终。
雪花布徧稻陇白，日脚插入秋波红。
兴余望剧酒四坐，歌声舞艳烟霞中。
酒酣从事歌送我，歌云此乐难再逢。
良时年少犹健羡，使君况是头白翁。
我闻此曲深叹息，唧唧不异秋草虫。
忆年十五学构厦，有意盖覆天下穷。
安知四十虚富贵，朱紫束缚心志空。
妆梳伎女上楼榭，止欲欢乐微茫躬。
虽无趣尚慕贤圣，幸有心目知西东。
欲将滑甘柔藏府，已被郁噎冲喉咙。
君今劝我酒太醉，醉语不复能冲融。
劝君莫学虚富贵，不是贤人难变通。','',''),('quantangshi-21839','梦游春七十韵','稹','quantangshi','','卷22','昔岁梦游春，梦游何所遇。
梦入深洞中，果遂平生趣。
清泠浅漫流，画舫兰篙渡。
过尽万株桃，盘旋竹林路。
长廊抱小楼，门牖相回互。
楼下杂花丛，丛边绕鸳鹭。
池光漾霞影，晓日初明煦。
未敢上阶行，频移曲池步。
乌龙不作声，碧玉曾相慕。
渐到帘幕间，裴回意犹惧。
闲窥东西合，奇玩参差布。
隔子碧油糊，驼钩紫金镀。
逡巡日渐高，影响人将寤。
鹦鹉饥乱鸣，娇娃睡犹怒。
帘开侍儿起，见我遥相谕。
铺设绣红茵，施张钿妆具。
潜褰翡翠帷，瞥见珊瑚树。
不辨花貌人，空惊香若雾。
身回夜合偏，态敛晨霞聚。
睡脸桃破风，汗妆莲委露。
丛梳百叶髻，金蹙重台屦。
纰輭钿头帬，玲珑合欢袴。
鲜妍脂粉薄，暗澹衣裳故。
最似红牡丹，雨来春欲暮。
梦魂良易惊，灵境难久寓。
夜夜望天河，无由重沿溯。
结念心所期，返如禅顿悟。
觉来八九年，不向花回顾。
杂合两京春，喧阗众禽护。
我到看花时，但作怀仙句。
浮生转经历，道性尤坚固。
近作梦仙诗，亦知劳肺腑。
一梦何足云，良时事婚娶。
当年二纪初，嘉节三星度。
朝蕣玉佩迎，高松女萝附。
韦门正全盛，出入多欢裕。
甲第涨清池，鸣驺引朱辂。
广榭舞萎蕤，长筵宾杂厝。
青春讵几日，华实潜幽蠹。
秋月照潘郎，空山怀谢傅。
红楼嗟坏壁，金谷迷荒戍。
石压破阑干，门摧旧梐枑。
虽云觉梦殊，同是终难驻。
悰绪竟何如，棼丝不成絇。
卓女白头吟，阿娇金屋赋。
重璧盛姬台，青冢明妃墓。
尽委穷尘骨，皆随流波注。
幸有古如今，何劳缣比素。
况余当盛时，早岁谐如务。
诏册冠贤良，谏垣陈好恶。
三十再登朝，一登还一仆。
宠荣非不早，邅回亦云屡。
直气在膏肓，氛氲日沈痼。
不言意不快，快意言多忤。
忤诚人所贼，性亦天之付。
乍可沈为香，不能浮作瓠。
诚为坚所守，未为明所措。
事事身已经，营营计何误。
美玉琢文圭，良金填武库。
徒谓自坚贞，安知受砻铸。
长丝羁野马，密网罗阴兔。
物外各迢迢，谁能远相锢。
时来既若飞，祸速当如骛。
曩意自未精，此行何所诉。
努力去江陵，笑言谁与晤。
江花纵可怜，奈非心所慕。
石竹逞奸黠，蔓青夸亩数。
一种薄地生，浅深何足妒。
荷叶水上生，团团水中住。
泻水置叶中，君看不相汚。','',''),('quantangshi-21840','桐花落','稹','quantangshi','','卷22','莎草徧桐阴，桐花满莎落。
盖覆相团圆，可怜无厚薄。
昔岁幽院中，深堂下帘幕。
同在后门前，因论花好恶。
君夸沈檀样，云是指撝作。
暗澹灭紫花，句连蹙金萼。
都绣六七枝，鬬成双孔雀。
尾上稠叠花，又将金解络。
我爱看不已，君烦睡先着。
我作绣桐诗，系君帬带着。
别来苦修道，此意都萧索。
今日竟相牵，思量偶然错。','',''),('quantangshi-21841','梦昔时','稹','quantangshi','','卷22','闲窗结幽梦，此梦谁人知。
夜半初得处，天明临去时。
山川已久隔，云雨两无期。
何事来相感，又成新别离。','',''),('quantangshi-21842','恨妆成','稹','quantangshi','','卷22','晓日穿隙明，开帷理妆点。
傅粉贵重重，施朱怜冉冉。
柔鬟背额垂，丛鬓随钗敛。
凝翠晕蛾眉，轻红拂花脸。
满头行小梳，当面施圆靥。
最恨落花时，妆成独披掩。','',''),('quantangshi-21843','古决絶词 一','稹','quantangshi','','卷22','乍可为天上牵牛织女星，不愿为庭前红槿枝。
七月七日一相见，相见故心终不移。
那能朝开暮飞去，一任东西南北吹。
分不两相守，恨不两相思。
对面且如此，背面当可知。
春风撩乱伯劳语，况是此时抛去时。
握手苦相问，竟不言后期。
君情既决绝，妾意已参差。
借如死生别，安得长苦悲。','',''),('quantangshi-21844','古决絶词 二','稹','quantangshi','','卷22','噫春冰之将泮，何予怀之独结。
有美一人，于焉旷绝。
一日不见，比一日于三年。
况三年之旷别，水得风兮小而已波。
笋在苞兮高不见节，矧桃李之当春。
竞众人而攀折，我自顾悠悠而若云。
又安能保君皑皑之如雪，感破镜之分明，覩泪痕之余血。
幸他人之既不我先，又安能使他人之终不我夺？
已焉哉！织女别黄姑，一年一度暂相见，彼此隔河何事无。','',''),('quantangshi-21845','古决絶词 三','稹','quantangshi','','卷22','夜夜相抱眠，幽怀尚沈结。
那堪一年事，长遣一宵说。
但感久相思，何暇暂相悦。
虹桥薄夜成，龙驾侵晨列。
生憎野鹤性迟回，死恨天鸡识时节。
曙色渐曈曈，华星欲明灭。
一去又一年，一年何可彻。
有此迢递期，不如死生别。','',''),('quantangshi-21846','樱桃花','稹','quantangshi','','卷22','樱桃花，一枝两枝千万朵。
花塼曾立摘花人，窣破罗帬红似火。','',''),('quantangshi-21847','曹十九舞绿钿','稹','quantangshi','','卷22','急管清弄频，舞衣才揽结。
含情独摇手，双袖参差列。
騕褭柳牵丝，炫转风回雪。
凝眄娇不移，往往度繁节。','',''),('quantangshi-21848','闺晚','稹','quantangshi','','卷22','红帬委塼堦，玉爪剺朱橘。
素臆光如砑，明瞳艳凝溢。
调弦不成曲，学书徒弄笔。
夜色侵洞房，春烟透帘出。','',''),('quantangshi-21849','晓将别','稹','quantangshi','','卷22','风露晓凄凄，月下西墙西。
行人帐中起，思妇枕前啼。
屑屑命僮御，晨装俨已齐。
将去复携手，日高方解携。','',''),('quantangshi-21850','蔷薇架','稹','quantangshi','','卷22','五色阶前架，一张笼上被。
殷红稠叠花，半绿鲜明地。
风蔓罗帬带，露英莲脸泪。
多逢走马郎，可惜帘边思。','',''),('quantangshi-21851','月暗','稹','quantangshi','','卷22','月暗灯残面墙泣，罗缨斗重知啼湿。
真珠帘断蝙蝠飞，燕子巢空萤火入。
深殿门重夜漏严，柔□□□□年急。
君王掌上容一人，更有轻身何处立。','',''),('quantangshi-21852','新秋','稹','quantangshi','','卷22','旦暮已凄凉，离人远思忙。
夏衣临晓薄，秋影入檐长。
前事风随扇，归心燕在梁。
殷勤寄牛女，河汉正相望。','',''),('quantangshi-21853','赠双文','稹','quantangshi','','卷22','艳极翻含怨，怜多转自娇。
有时还暂笑，闲坐爱无憀。
晓月行看堕，春酥见欲消。
何因肯垂手，不敢望回腰。','',''),('quantangshi-21854','春别','稹','quantangshi','','卷22','幽芳本未阑，君去蕙花残。
河汉秋期远，关山世路难。
云屏留粉絮，风幌引香兰。
肠断回文锦，春深独自看。','',''),('quantangshi-21855','和乐天示杨琼','稹','quantangshi','','卷22','我在江陵少年日，知有杨琼初唤出。
腰身瘦小歌圆紧，依约年应十六七。
去年十月过苏州，琼来拜问郎不识。
青衫玉貌何处去，安得红旗遮头白。
我语杨琼琼莫语，汝虽笑我我笑汝。
汝今无复小腰身，不似江陵时好女。
杨琼为我歌送酒，尔忆江陵县中否。
江陵王令骨为灰，车来嫁作尚书妇。
卢戡及第严涧在，其余死者十八九。
我今贺尔亦自多，尔得老成余白首。','',''),('quantangshi-21856','鱼中素','稹','quantangshi','','卷22','重叠鱼中素，幽缄手自开。
斜红余泪迹，知着脸边来。','',''),('quantangshi-21857','代九九','稹','quantangshi','','卷22','昔年桃李月，颜色共花宜。
廻脸莲初破，低蛾柳竝垂。
望山多倚树，弄水爱临池。
远被登楼识，潜因倒影窥。
隔林徒想像，上砌转逶迤。
谩掷庭中果，虚攀墙外枝。
强持文玉佩，求结麝香缡。
阿母怜金重，亲兄要马骑。
把将娇小女，嫁与冶游儿。
自隐勤勤索，相要事事随。
每常同坐卧，不省暂参差。
才学羞兼妒，何言宠便移。
青春来易皎，白日誓先亏。
僻性嗔来见，邪行醉后知。
别牀铺枕席，当面指瑕疵。
妾貌应犹在，君情遽若斯。
的成终世恨，焉用此宵为。
鸾镜灯前扑，鸳衾手下隳。
参商半夜起，琴瑟一声离。
努力新丛艳，狂风次第吹。','',''),('quantangshi-21858','卢十九子蒙吟卢七员外洛川怀古六韵命余和','稹','quantangshi','','卷22','闻道卢明府，闲行咏洛神。
浪圆疑靥笑，波鬬忆眉嚬。
蹀躞桥头马，空蒙水上尘。
草芽犹犯雪，冰岸欲消春。
寓目终无限，通辞未有因。
子蒙将此曲，吟似独眠人。','',''),('quantangshi-21859','刘阮妻二首 一','稹','quantangshi','','卷22','仙洞千年一度开，等闲偷入又偷廻。
桃花飞尽东风起，何处消沈去不来。','',''),('quantangshi-21860','刘阮妻二首 二','稹','quantangshi','','卷22','芙蓉脂肉绿云鬟，罨画楼台青黛山。
千树桃花万年药，不知何事忆人间。','',''),('quantangshi-21861','桃花','稹','quantangshi','','卷22','桃花浅深处，似匀深浅妆。
春风助肠断，吹落白衣裳。','',''),('quantangshi-21862','暮秋','稹','quantangshi','','卷22','看着墙西日又沈，步廊廻合戟门深。
栖乌满树声声绝，小玉上牀铺夜衾。','',''),('quantangshi-21863','压墙花','稹','quantangshi','','卷22','野性大都迷里巷，爱将高树记人家。
春来偏认平阳宅，为见墙头拂面花。','',''),('quantangshi-21864','舞腰','稹','quantangshi','','卷22','帬裾旋旋手迢迢，不趁音声自趁娇。
未必诸郎知曲误，一时偷眼为廻腰。','',''),('quantangshi-21865','白衣裳二首 一','稹','quantangshi','','卷22','雨湿轻尘隔院香，玉人初着白衣裳。
半含惆怅闲看绣，一朵棃花压象牀。','',''),('quantangshi-21866','白衣裳二首 二','稹','quantangshi','','卷22','藕丝衫子柳花帬，空着沈香慢火熏。
闲倚屏风笑周昉，枉抛心力画朝云。','',''),('quantangshi-21867','忆事','稹','quantangshi','','卷22','夜深闲到戟门边，却绕行廊又独眠。
明月满庭池水渌，桐花垂在翠帘前。','',''),('quantangshi-21868','寄旧诗与薛涛因成长句','稹','quantangshi','','卷22','诗篇调态人皆有，细腻风光我独知。
月夜咏花怜暗澹，雨朝题柳为敧垂。
长教碧玉藏深处，总向红牋写自随。
老大不能收拾得，与君闲似好男儿。','',''),('quantangshi-21869','友封体','稹','quantangshi','','卷22','雨送浮凉夏簟清，小楼腰褥怕单轻。
微风暗度香囊转，胧月斜穿隔子明。
桦烛焰高黄耳吠，柳堤风静紫骝声。
频频闻动中门锁，桃叶知嗔未敢迎。','',''),('quantangshi-21870','看花','稹','quantangshi','','卷22','努力少年求好官，好花须是少年看。
君看老大逢花树，未折一枝心已阑。','',''),('quantangshi-21871','斑竹','稹','quantangshi','','卷22','一枝斑竹渡湘沅，万里行人感别魂。
知是娥皇庙前物，远随风雨送啼痕。','',''),('quantangshi-21872','筝','稹','quantangshi','','卷22','莫愁私地爱王昌，夜夜筝声怨隔墙。
火凤有凰求不得，春莺无伴啭空长。
急挥舞破催飞燕，慢逐歌词弄小娘。
死恨相如新索妇，枉将心力为他狂。','',''),('quantangshi-21873','春晓','稹','quantangshi','','卷22','半欲天明半未明，醉闻花气睡闻莺。
𤞇儿撼起钟声动，二十年前晓寺情。','',''),('quantangshi-21874','所思二首 一','稹','quantangshi','','卷22','庾亮楼中初见时，武昌春柳似腰肢。
相逢相失还如梦，为雨为云今不知。','',''),('quantangshi-21875','所思二首 二','稹','quantangshi','','卷22','鄂渚蒙蒙烟雨微，女郎魂逐暮云归。
只应长在汉阳渡，化作鸳鸯一只飞。','',''),('quantangshi-21876','莺莺诗','稹','quantangshi','','卷22','殷红浅碧旧衣裳，取次梳头暗澹妆。
夜合带烟笼晓日，牡丹经雨泣残阳。
低迷隐笑原非笑，散漫清香不似香。
频动横波嗔阿母，等闲教见小儿郎。','',''),('quantangshi-21877','离思五首 一','稹','quantangshi','','卷22','自爱残妆晓镜中，环钗谩篸绿丝丛。
须臾日射燕脂颊，一朵红苏旋欲融。','',''),('quantangshi-21878','离思五首 二','稹','quantangshi','','卷22','山泉散漫绕阶流，万树桃花暎小楼。
闲读道书慵未起，水晶帘下看梳头。','',''),('quantangshi-21879','离思五首 三','稹','quantangshi','','卷22','红罗着压逐时新，吉了花纱嫩麴尘。
第一莫嫌材地弱，些些纰缦最宜人。','',''),('quantangshi-21880','离思五首 四','稹','quantangshi','','卷22','曾经沧海难为水，除却巫山不是云。
取次花丛嬾回顾，半缘修道半缘君。','',''),('quantangshi-21881','离思五首 五','稹','quantangshi','','卷22','寻常百种花齐发，偏摘棃花与白人。
今日江头两三树，可怜和叶度残春。','',''),('quantangshi-21882','杂忆五首 一','稹','quantangshi','','卷22','今年寒食月无光，夜色才侵已上牀。
忆得双文通内里，玉栊深处暗闻香。','',''),('quantangshi-21883','杂忆五首 二','稹','quantangshi','','卷22','花笼微月竹笼烟，百尺丝绳拂地悬。
忆得双文人静后，潜教桃叶送秋千。','',''),('quantangshi-21884','杂忆五首 三','稹','quantangshi','','卷22','寒轻夜浅绕回廊，不辨花丛暗辨香。
