人人总解争时势，都大须看各自宜。','',''),('quantangshi-21888','襄阳为卢窦纪事 一','稹','quantangshi','','卷22','帝下真符召玉真，偶逢游女暂相亲。
素书三卷留为赠，从向人间说向人。','',''),('quantangshi-21889','襄阳为卢窦纪事 二','稹','quantangshi','','卷22','风弄花枝月照阶，醉和春睡倚香怀。
依稀似觉双环动，潜被萧郎卸玉钗。','',''),('quantangshi-21890','襄阳为卢窦纪事 三','稹','quantangshi','','卷22','莺声撩乱曙灯残，暗觅金钗动晓寒。
犹带春酲嬾相送，樱桃花下隔帘看。','',''),('quantangshi-21891','襄阳为卢窦纪事 四','稹','quantangshi','','卷22','琉璃波面月笼烟，暂逐萧郎走上天。
今日归时最肠断，回江还是夜来船。','',''),('quantangshi-21892','襄阳为卢窦纪事 五','稹','quantangshi','','卷22','花枝临水复临堤，闲照江流亦照泥。
千万春风好抬举，夜来曾有凤皇栖。','',''),('quantangshi-21893','会真诗三十韵','稹','quantangshi','','卷22','微月透帘栊，萤光度碧空。
遥天初缥缈，低树渐葱茏。
龙吹过庭竹，鸾歌拂井桐。
罗绡垂薄雾，环佩响轻风。
绛节随金母，云心捧玉童。
更深人悄悄，晨会雨蒙蒙。
珠莹光文履，花明隐绣栊。
宝钗行彩凤，罗帔掩丹虹。
言自瑶华浦，将朝碧帝宫。
因游李城北，偶向宋家东。
戏调初微拒，柔情已暗通。
低鬟蝉影动，廻步玉尘蒙。
转面流花雪，登牀抱绮丛。
鸳鸯交颈舞，翡翠合欢笼。
眉黛羞频聚，朱唇暖更融。
气清兰蘂馥，肤润玉肌丰。
无力慵移腕，多娇爱敛躬。
汗光珠点点，发乱绿松松。
方喜千年会，俄闻五夜穷。
留连时有限，缱绻意难终。
慢脸含愁态，芳词誓素衷。
赠环明运合，留结表心同。
啼粉流清镜，残灯绕暗虫。
华光独冉冉，旭日渐曈曈。
警乘还归洛，吹箫亦上嵩。
衣香犹染麝，枕腻尚残红。
羃羃临塘草，飘飘思渚蓬。
素琴鸣怨鹤，清汉望归鸿。
海阔诚难度，天高不易冲。
行云无处所，萧史在楼中。','',''),('quantangshi-21894','古艳诗二首 一','稹','quantangshi','','卷22','春来频到宋家东，垂袖开怀待好风。
莺藏柳暗无人语，惟有墙花满树红。','',''),('quantangshi-21895','古艳诗二首 二','稹','quantangshi','','卷22','深院无人草树光，娇莺不语趁阴藏。
等闲弄水浮花片，流出门前赚阮郎。','',''),('quantangshi-21896','奉和浙西大夫李德裕述梦四十韵大夫本题言赠于梦中诗赋以寄一二僚友故今所和者亦止述翰苑旧游而已次本韵','稹','quantangshi','','卷22','闻有池塘什，还因梦寐遭。
攀禾工类蔡，咏豆敏过曹。
庄蝶玄言祕，罗禽藻思高。
戈矛排笔阵，貔虎让文韬。
彩缋鸾凰颈，权奇骥騄髦。
神枢千里应，华衮一言褒。
李广留飞箭，王祥得佩刀。
传乘司隶马，继染翰林毫。
辨颖□超脱，词锋岂足櫜。
金刚锥透玉，镔铁劒吹毛。
顾我曾陪附，思君正郁陶。
近酬新乐录，仍寄续离骚。
阿阁偏随凤，方壶共跨鳌。
借骑银杏叶，横赐锦垂萄。
冰井分珍果，金瓶贮御醪。
独辞珠有戒，廉取玉非叨。
麦纸侵红点，兰灯焰碧高。
代予言不易，承圣旨偏劳。
绕月同栖鹊，惊风比夜獒。
吏传开锁契，神撼引铃绦。
渥泽深难报，危心过自操。
犯颜诚恳恳，腾口惧忉忉。
佩宠虽緺绶，安贫尚葛袍。
宾亲多谢绝，延荐必英豪。
分阻杯盘会，闲随寺观遨。
祗园一林杏，仙洞万株桃。
澥海沧波减，昆明劫火熬。
未陪登鹤驾，已讣堕乌号。
痛泪过江浪，冤声出海涛。
尚看恩诏湿，已梦寿宫牢。
再造承天宝，新持济巨篙。
犹怜弊簪履，重委旧旌旄。
北望心弥苦，西回首屡搔。
九霄难就日，两浙仅容舠。
暮竹寒窗影，衰杨古郡濠。
鱼鰕集橘市，鹤鹳起亭臯。
朽刃休冲斗，良弓枉在弢。
早弯摧虎兕，便铸垦蓬蒿。
渔艇宜孤棹，楼船称万艘。
量材分用处，终不学滔滔。','',''),('quantangshi-21897','自述','稹','quantangshi','','卷22','延英引对碧衣郎，江砚宣毫各别牀。
天子下帘亲考试，宫人手里过茶汤。','',''),('quantangshi-21898','春分投简阳明洞天作','稹','quantangshi','','卷22','中分春一半，今日半春徂。
老惜光阴甚，慵牵兴绪孤。
偶成投祕简，聊得泛平湖。
郡邑移仙界，山川展画图。
旌旗遮屿浦，士女满闉闍。
似木吴儿劲，如花越女姝。
牛侬惊力直，蚕妾笑睢盱。
怪我携章甫，嘲人托鹧鸪。
闾阎随地胜，风俗举华殊。
跣足沿流妇，丫头避役奴。
雕题虽少有，鸡卜尚多巫。
乡味尤珍蛤，家神爱事乌。
舟船通海峤，田种绕城隅。
栉比千艘合，袈裟万顷铺。
亥茶阗小市，渔父隔深芦。
日脚斜穿浪，云根远曳蒲。
凝风花气度，新雨草芽苏。
粉坏梅辞萼，红含杏缀珠。
薅余秧渐长，烧后葑犹枯。
绿綟高悬柳，青钱密辫榆。
驯鸥眠浅濑，惊雉迸平芜。
水静王余见，山空谢豹呼。
燕狂捎蛱蝶，螟挂集蒲卢。
浅碧鹤新卵，深黄鹅嫩雏。
邨扉以白板，寺壁耀赬糊。
禹庙才离郭，陈庄恰半途。
石帆何峭峣，龙瑞本萦纡。
穴为探符坼，潭因失箭刳。
堤形弯熨斗，峰势踊香炉。
幢盖迎三洞，烟霞贮一壶。
桃枝蟠复直，桑树亚还扶。
鼈解称从事，松堪作大夫。
荣光飘殿阁，虚籁合笙竽。
庭狎仙翁鹿，池游县令凫。
君心除健羡，扣寂入虚无。
冈蹋翻星纪，章飞动帝枢。
东皇提白日，北斗下玄都。
骑吏帬皆紫，科车幰尽朱。
地侯鞭社伯，海若跨天吴。
雾喷雷公怒，烟扬竈鬼趋。
投壶怜玉女，噀饭笑麻姑。
果实经千岁，衣裳重六铢。
琼杯传素液，金匕进雕胡。
掌里承来露，盘中钓得鲈。
菌生悲局促，柯烂觉须臾。
稊米休言圣，醯鸡益伏愚。
鼓鼙催瞑色，簪组缚微躯。
遂别真徒侣，还来世路衢。
题诗叹城郭，挥手谢妻孥。
幸有桃源近，全家肯去无。','',''),('quantangshi-21899','春游','稹','quantangshi','','卷22','酒户年年减，山行渐渐难。
欲终心懒慢，转恐兴阑散。
镜水波犹冷，稽峰雪尚残。
不能辜物色，乍可怯春寒。
远目伤千里，新年思万端。
无人知此意，闲凭小栏干。','',''),('quantangshi-21900','除夜酬乐天','稹','quantangshi','','卷22','引傩绥斾乱毵毵，戏罢人归思不堪。
虚涨火尘龟浦北，无由阿伞凤城南。
休官期限元同约，除夜情怀老共谙。
莫道明朝始添岁，今年春在岁前三。','',''),('quantangshi-21901','酬乐天初冬早寒见寄','稹','quantangshi','','卷22','乍起衣犹冷，微吟帽半敧。
霜凝南屋瓦，鸡唱后园枝。
洛水碧云晓，吴宫黄叶时。
两传千里意，书札不如诗。','',''),('quantangshi-21902','酬白乐天杏花园','稹','quantangshi','','卷22','刘郎不用闲惆怅，且作花间共醉人。
算得贞元旧朝士，几人同见太和春。','',''),('quantangshi-21903','过东都别乐天二首 一','稹','quantangshi','','卷22','君应怪我留连久，我欲与君辞别难。
白头徒侣渐稀少，明日恐君无此欢。','',''),('quantangshi-21904','过东都别乐天二首 二','稹','quantangshi','','卷22','自识君来三度别，这回白尽老髭须。
恋君不去君须会，知得后廻相见无。','',''),('quantangshi-21905','逢白公','稹','quantangshi','','卷22','远路事无限，相逢唯一言。
月色照荣辱，长安千万门。','',''),('quantangshi-21906','酬白太傅','稹','quantangshi','','卷22','太空秋色凉，独鸟下微阳。
三径池塘静，六街车马忙。
渐能高酒户，始是入诗狂。
官冷且无事，追陪慎莫忘。','',''),('quantangshi-21907','和严给事闻唐昌观玉蘂花下有游仙','稹','quantangshi','','卷22','弄玉潜过玉树时，不教青鸟出花枝。
的应未有诸人觉，只是严朗不得知。','',''),('quantangshi-21908','赠毛仙翁','稹','quantangshi','','卷22','仙驾初从蓬海来，相逢又说向天台。
一言亲授希微诀，三夕同倾沆瀣杯。
此日临风飘羽卫，他年嘉约指盐梅。
花前挥手迢遥去，目断霓旌不可陪。','',''),('quantangshi-21909','八月十四日夜玩月','稹','quantangshi','','卷22','犹欠一宵轮未满，紫霞红衬碧云端。
谁能唤得姮娥下，引向堂前子细看。','',''),('quantangshi-21910','寒食夜','稹','quantangshi','','卷22','红染桃花雪压棃，玲珑鸡子鬬赢时。
今年不是明寒食，暗地秋千别有期。','',''),('quantangshi-21911','三月三十日程氏馆饯杜十四归京','稹','quantangshi','','卷22','江春今日尽，程馆祖筵开。
我正南冠絷，君寻北路回。
谋身诚太拙，从宦苦无媒。
处困方明命，遭时不在才。
逾年长倚玉，连夜共衔杯。
涸溜霑濡沫，余光照死灰。
行看鸿欲翥，敢惮酒相催。
拍逐飞觥绝，香随舞袖来。
消棃抛五徧，娑葛𣩄三台。
已许尊前倒，临风泪莫颓。','',''),('quantangshi-21912','酬张祕书因寄马赠诗','稹','quantangshi','','卷22','丞相功高厌武名，牵将战马寄儒生。
四蹄荀距藏虽尽，六尺须头见尚惊。
减粟偷儿憎未饱，骑驴诗客駡先行。
劝君还却司空着，莫遣衙参傍子城。','',''),('quantangshi-21913','戏酬副使中丞见示四韵','稹','quantangshi','','卷22','莫恨暂櫜鞬，交游几个全。
眼明相见日，肺病欲秋天。
五马虚盈枥，双蛾浪满船。
可怜俱老大，无处用闲钱。','',''),('quantangshi-21914','赠柔之','稹','quantangshi','','卷22','穷冬到乡国，正岁别京华。
自恨风尘眼，常看远地花。
碧幢还照曜，红粉莫咨嗟。
嫁得浮云壻，相随即是家。','',''),('quantangshi-21915','修龟山鱼池示众僧','稹','quantangshi','','卷22','劝尔诸僧好护持，不须垂钓引青丝。
云山莫厌看经坐，便是浮生得道时。','',''),('quantangshi-21916','寄赠薛涛','稹','quantangshi','','卷22','锦江滑腻蛾眉秀，幻出文君与薛涛。
言语巧偷鹦鹉舌，文章分得凤皇毛。
纷纷辞客多停笔，个个公卿欲梦刀。
别后相思隔烟水，菖蒲花发五云高。','',''),('quantangshi-21917','赠刘采春','稹','quantangshi','','卷22','新妆巧样画双蛾，谩裹常州透额罗。
正面偷匀光滑笏，缓行轻踏破纹波。
言辞雅措风流足，举止低回秀媚多。
更有恼人肠断处，选词能唱望夫歌。','',''),('quantangshi-21918','醉题东武','稹','quantangshi','','卷22','役役行人事，纷纷碎簿书。
功夫两衙尽，留滞七年余。
病痛梅天发，亲情海岸疎。
因循未归得，不是忆鲈鱼。','',''),('quantangshi-21919','崔徽歌','稹','quantangshi','','卷22','崔徽本不是娼家，教歌按舞娼家长。
使君知有不自由，坐在头时立在掌。
有客有客名丘夏，善写仪容得恣把。
为徽持此谢敬中，以死报郎为□□。','',''),('quantangshi-21920','一字至七字诗 茶','稹','quantangshi','','卷22','茶，香叶，嫩芽。
慕诗客，爱僧家。
碾雕白玉，罗织红纱。
铫煎黄蘂色，椀转麴尘花。
夜后邀陪明月，晨前命对朝霞。
洗尽古今人不倦，将知醉后岂堪夸。','',''),('quantangshi-21921','句','稹','quantangshi','','卷22','儿歌杨柳叶，妾拂石榴花。
松门待制应全远，药树监搜可得知。
髻鬟峨峨高一尺，门前立地看春风。','',''),('quantangshi-21922','贺雨','白居易','quantangshi','','卷22','皇帝嗣宝历，元和三年冬。
自冬及春暮，不雨旱爞爞。
上心念下民，惧岁成灾凶。
遂下罪己诏，殷勤告万邦。
帝曰予一人，继天承祖宗。
忧勤不遑宁，夙夜心忡忡。
元年诛刘辟，一举靖巴邛。
二年戮李錡，不战安江东。
顾惟眇眇德，遽有巍巍功。
或者天降沴，无乃儆予躬。
上思天戒，下思致时邕。
莫如率其身，慈和与俭恭。
乃命罢进献，乃命赈饥穷。
宥死降五刑，责己宽三农。
宫女出宣徽，廐马减飞龙。
庶政靡不举，皆出自宸衷。
奔腾道路人，伛偻田野翁。
欢呼相告报，感泣涕霑胸。
顺人人心悦，先天天意从。
诏下才七日，和气生冲融。
凝为油油云，散作习习风。
昼夜三日雨，凄凄复蒙蒙。
万心春熙熙，百谷青芃芃。
人变愁为喜，岁易俭为丰。
乃知王者心，忧乐与众同。
皇天与后土，所感无不通。
冠佩何锵锵，将相及王公。
蹈舞呼万岁，列贺明庭中。
小臣诚愚陋，职忝金銮宫。
稽首再三拜，一言献天聪。
君以明为圣，臣以直为忠。
敢贺有其始，亦愿有其终。','',''),('quantangshi-21923','读张籍古乐府','白居易','quantangshi','','卷22','张君何为者，业文三十春。
尤工乐府诗，举代少其伦。
为诗意如何，六义互铺陈。
风雅比兴外，未尝着空文。
读君学仙诗，可讽放佚君。
读君董公诗，可诲贪暴臣。
读君商女诗，可感悍妇仁。
读君勤齐诗，可劝薄夫敦。
上可裨教化，舒之济万民。
下可理情性，卷之善一身。
始从青衿岁，迨此白发新。
日夜秉笔吟，心苦力亦勤。
时无采诗官，委弃如泥尘。
恐君百岁后，灭没人不闻。
愿藏中祕书，百代不湮沦。
愿播内乐府，时得闻至尊。
言者志之苗，行者文之根。
所以读君诗，亦知君为人。
如何欲五十，官小身贱贫。
病眼街西住，无人行到门。','',''),('quantangshi-21924','哭孔戡','白居易','quantangshi','','卷22','洛阳谁不死，戡死闻长安。
我是知戡者，闻之涕泫然。
戡佐山东军，非义不可干。
拂衣向西来，其道直如弦。
从事得如此，人人以为难。
人言明明代，合置在朝端。
或望居谏司，有事戡必言。
或望居宪府，有邪戡必弹。
惜哉两不谐，没齿为闲官。
竟不得一日，謇謇立君前。
形骸随众人，敛葬北邙山。
平生刚肠内，直气归其间。
贤者为生民，生死悬在天。
谓天不爱人，胡为生其贤。
谓天果爱民，胡为夺其年。
茫茫元化中，谁执如此权。','',''),('quantangshi-21925','凶宅','白居易','quantangshi','','卷22','长安多大宅，列在街西东。
往往朱门内，房廊相对空。
枭鸣松桂树，狐藏兰菊丛。
苍苔黄叶地，日暮多旋风。
前主为将相，得罪窜巴庸。
后主为公卿，寝疾殁其中。
连延四五主，殃祸继相钟。
自从十年来，不利主人翁。
风雨坏檐隙，蛇鼠穿墙墉。
人凝不敢买，日毁土木功。
嗟嗟俗人心，甚矣其愚蒙。
旦恐灾将至，不思祸所从。
我今题此诗，欲悟迷者胸。
凡为大官人，年禄多高崇。
权重持难久，位高势易穷。
骄者物之盈，老者数之终。
四者如寇盗，日夜来相攻。
假使居吉土，孰能保其躬。
因小以明大，借家可喻邦。
周秦宅肴函，其宅非不同。
一兴八百年，一死望夷宫。
寄语家与国，人凶非宅凶。','',''),('quantangshi-21926','梦仙','白居易','quantangshi','','卷22','人有梦仙者，梦身升上清。
坐乘一白鹤，前引双红旌。
羽衣忽飘飘，玉鸾俄铮铮。
半空直下视，人世尘冥冥。
渐失乡国处，才分山水形。
东海一片白，列岳五点青。
须臾羣仙来，相引朝玉京。
安期羡门辈，列侍如公卿。
仰谒玉皇帝，稽首前致诚。
帝言汝仙才，努力勿自轻。
却后十五年，期汝不死庭。
再拜受斯言，既寤喜且惊。
祕之不敢泄，誓志居岩扃。
恩爱舍骨肉，饮食断膻腥。
朝餐云母散，夜吸沆瀣精。
空山三十载，日望辎軿迎。
前期过已久，鸾鹤无来声。
齿发日衰白，耳目减聪明。
一朝同物化，身与粪壤并。
神仙信有之，俗力非可营。
苟无金骨相，不列丹台名。
徒传辟谷法，虚受烧丹经。
只自取勤苦，百年终不成。
悲哉梦仙人，一梦误一生。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-21927','观刈麦','白居易','quantangshi','','卷22','田家少闲月，五月人倍忙。
夜来南风起，小麦覆陇黄。
妇姑荷箪食，童穉携壶浆。
相随饷田去，丁壮在南冈。
足蒸暑土气，背灼炎天光。
力尽不知热，但惜夏日长。
复有贫妇人，抱子在其傍。
右手秉遗穗，左臂悬敝筐。
听其相顾言，闻者为悲伤。
家田输税尽，拾此充饥肠。
今我何功德，曾不事农桑。
吏禄三百石，岁晏有余粮。
念此私自愧尽日不能忘。','',''),('quantangshi-21928','题海图屏风','白居易','quantangshi','','卷22','海水无风时，波涛安悠悠。
鳞介无小大，遂性各沈浮。
突兀海底鳌，首冠三神丘。
钓网不能制，其来非一秋。
或者不量力，谓兹鳌可求。
贔屭牵不动，纶绝沈其钩。
一鳌既顿颔，诸鳌齐掉头。
白涛与黑浪，呼吸绕咽喉。
喷风激飞廉，鼓波怒阳侯。
鲸鲵得其便，张口欲吞舟。
万里无活鳞，百川多倒流。
遂使江汉水，朝宗意亦休。
苍然屏风上，此画良有由。','',''),('quantangshi-21929','羸骏','白居易','quantangshi','','卷22','骅骝失其主，羸饿无人牧。
向风嘶一声，莽苍黄河曲。
蹋冰水畔立，卧雪冢间宿。
岁暮田野空，寒草不满腹。
岂无市骏者，尽是凡人目。
相马失于瘦，遂遗千里足。
村中何扰扰，有吏征刍粟。
输彼军廐中，化作驽骀肉。','',''),('quantangshi-21930','废琴','白居易','quantangshi','','卷22','丝桐合为琴，中有太古声。
古声澹无味，不称今人情。
玉徽光彩灭，朱弦尘土生。
废弃来已久，遗音尚泠泠。
不辞为君弹，纵弹人不听。
何物使之然，羌笛与秦筝。','',''),('quantangshi-21931','李都尉古劒','白居易','quantangshi','','卷22','古劒寒黯黯，铸来几千秋。
白光纳日月，紫气排斗牛。
有客借一观，爱之不敢求。
湛然玉匣中，秋水澄不流。
至宝有本性，精刚无与俦。
可使寸寸折，不能绕指柔。
愿快直士心，将断佞臣头。
不愿报小怨，夜半刺私雠。
劝君慎所用，无作神兵羞。','',''),('quantangshi-21932','云居寺孤桐','白居易','quantangshi','','卷22','一株青玉立，千叶绿云委。
亭亭五丈余，高意犹未已。
山僧年九十，清净老不死。
自云手种时，一棵青桐子。
直从萌芽拔，高自毫末始。
四面无附枝，中心有通理。
寄言立身者，孤直当如此。','',''),('quantangshi-21933','京兆府新栽莲','白居易','quantangshi','','卷22','汚沟贮浊水，水上叶田田。
我来一长叹，知是东溪莲。
下有青泥汚，馨香无复全。
上有红尘扑，颜色不得鲜。
物性犹如此，人事亦宜然。
托根非其所，不如遭弃捐。
昔在溪中日，花叶媚清涟。
今来不得地，顦顇府门前。','',''),('quantangshi-21934','月夜登阁避暑','白居易','quantangshi','','卷22','旱久炎气盛，中人若燔烧。
青风隐何处，草树不动摇。
何以避暑气，无如出尘嚣。
行行都门外，佛阁正岧嶤。
清凉近高生，烦热委静销。
开襟当轩坐，意泰神飘飘。
回看归路傍，禾黍尽枯焦。
独善诚有计，将何救旱苗。','',''),('quantangshi-21935','初授拾遗','白居易','quantangshi','','卷22','奉诏登左掖，束带参朝议。
何言初命卑，且脱风尘吏。
杜甫陈子昂，才名括天地。
当时非不遇，尚无过斯位。
况余蹇薄者，宠至不自意。
惊近白日光，慙非青云器。
天子方从谏，朝廷无忌讳。
岂不思匪躬，适遇时无事。
受命已旬月，饱食随班次。
谏纸忽盈箱，对之终自愧。','',''),('quantangshi-21936','赠元稹','白居易','quantangshi','','卷22','自我从宦游，七年在长安。
所得惟元君，乃知定交难。
岂无山上苗，径寸无岁寒。
岂无要津水，咫尺有波澜。
之子异于是，久处誓不谖。
无波古井水，有节秋竹竿。
一为同心友，三及芳岁阑。
花下鞍马游，雪中杯酒欢。
衡门相逢迎，不具带与冠。
春风日高睡，秋月夜深看。
不为同登科，不为同署官。
所合在方寸，心源无异端。','',''),('quantangshi-21937','哭刘敦质','白居易','quantangshi','','卷22','小树两株柏，新土三尺坟。
苍苍白露草，此地哭刘君。
哭君岂无辞，辞云君子人。
如何天不吊，穷悴至终身。
愚者多贵寿，贤者独贱迍。
龙亢彼无悔，蠖屈此不伸。
哭罢持此辞，吾将诘羲文。','',''),('quantangshi-21938','答友问','白居易','quantangshi','','卷22','大圭廉不割，利劒用不缺。
当其斩马时，良玉不如铁。
置铁在洪炉，铁消易如雪。
良玉同其中，三日烧不热。
君疑才与德，咏此知优劣。','',''),('quantangshi-21939','杂兴三首 一','白居易','quantangshi','','卷22','楚王多内宠，倾国选嫔妃。
又爱从禽乐，驰骋每相随。
锦韝臂花隼，罗袂控金羁。
遂习宫中女，皆如马上儿。
色禽合为荒，刑政两已衰。
云梦春仍猎，章华夜不归。
东风二月天，春雁正离离。
美人挟银镝，一发叠双飞。
飞鸿惊断行，敛翅避蛾眉。
君王顾之笑，弓箭生光辉。
回眸语君曰，昔闻庄王时。
有一愚夫人，其名曰樊姬。
不有此游乐，三载断鲜肥。','',''),('quantangshi-21940','杂兴三首 二','白居易','quantangshi','','卷22','越国政初荒，越天旱不已。
风日燥水田，水涸尘飞起。
国中新下令，官渠禁流水。
流水不入田，壅入王宫里。
余波养鱼鸟，倒影浮楼雉。
澹滟九折池，萦回十余里。
四月芰荷发，越王日游嬉。
左右好风来，香动芙蓉蘂。
但爱芙蓉香，又种芙蓉子。
不念阊门外，千里稻苗死。','',''),('quantangshi-21941','杂兴三首 三','白居易','quantangshi','','卷22','吴王心日侈，服玩尽奇瓌。
身卧翠羽帐，手持红玉杯。
冠垂明月珠，带束通天犀。
行动自矜顾，数步一裴回。
小人知所好，怀宝四方来。
奸邪得藉手，从此幸门开。
古称国之宝，谷米与贤才。
今看君王眼，视之如尘灰。
伍员谏已死，浮尸去不回。
姑苏台下草，麋鹿暗生麑。','',''),('quantangshi-21942','宿紫阁山北村','白居易','quantangshi','','卷22','晨游柴阁峰，暮宿山下村。
村老见余喜，为余开一尊。
举杯未及饮，暴卒来入门。
柴衣挟刀斧，草草十余人。
夺我席上酒，掣我盘中飧。
主人退后立，敛手反如宾。
中庭有奇树，种来三十春。
主人惜不得，持斧断其根。
口称采造家，身属神策军。
主人慎勿语，中尉正承恩。','',''),('quantangshi-21943','读汉书','白居易','quantangshi','','卷22','禾黍与稂莠，雨来同日滋。
桃李与荆棘，霜降同夜萎。
草木既区别，荣枯那等夷。
茫茫天地意，无乃太无私。
小人与君子，用置各有宜。
奈何西汉末，忠邪竝信之。
不然尽信忠，早绝邪臣窥。
不然尽信邪，早使忠臣知。
优游两不断，盛业日已衰。
痛矣萧京辈，终令陷祸机。
每读元成纪，愤愤令人悲。
寄言为国者，不得学天时。
寄言为臣者，可以鉴于斯。','',''),('quantangshi-21944','赠樊着作','白居易','quantangshi','','卷22','阳城为谏议，以正事其君。
其手如屈轶，举必指佞臣。
卒使不仁者，不得秉国钧。
元稹为御史，以直立其身。
其心如肺石，动必达穷民。
东川八十家，冤愤一言伸。
刘辟肆乱心，杀人正纷纷。
其嫂曰庾氏，弃绝不为亲。
从史萌逆节，隐心潜负恩。
其佐曰孔戡，舍去不为宾。
凡此士与女，其道天下闻。
常恐国史上，但记凤与麟。
贤者不为名，名彰教乃敦。
每惜若人辈，身死名亦沦。
君为着作郎，职废志空存。
虽有良史才，直笔无所申。
何不自着书？实录彼善人。
编为一家言，以备史阙文。','',''),('quantangshi-21945','蜀路石妇','白居易','quantangshi','','卷22','道旁一石妇，无记复无铭。
传是此乡女，为妇孝且贞。
十五嫁邑人，十六夫征行。
夫行二十载，妇独守孤焭。
其夫有父母，老病不安宁。
其妇执妇道，一一如礼经。
晨昏问起居，恭顺发心诚。
药饵自调节，膳羞必甘馨。
夫行竟不归，妇德转光明。
后人高其节，刻石像妇形。
俨然整衣巾，若立在闺庭。
似见舅姑礼，如闻环佩声。
至今为妇者，见此孝心生。
不比山头石，空有望夫名。','',''),('quantangshi-21946','折劒头','白居易','quantangshi','','卷22','拾得折劒头，不知折之由。
一握青蛇尾，数寸碧峰头。
疑是斩鲸鲵，不然刺蛟虬。
缺落泥土中，委弃无人收。
我有鄙介性，好刚不好柔。
勿轻直折劒，犹胜曲全钩。','',''),('quantangshi-21947','登乐游园望','白居易','quantangshi','','卷22','独上乐游园，四望天日曛。
东北何霭霭，宫阙入烟云。
爱此高处立，忽如遗垢氛。
耳目暂清旷，怀抱郁不伸。
下视十二街，绿树间红尘。
车马徒满眼，不见心所亲。
孔生死洛阳，元九谪荆门。
可怜南北路，高盖者何人。','',''),('quantangshi-21948','酬元九对新栽竹有怀见寄','白居易','quantangshi','','卷22','昔我十年前，与君始相识。
曾将秋竹竿，比君孤且直。
中心一以合，外事纷无极。
共保秋竹心，风霜侵不得。
始嫌梧桐树，秋至先改色。
不爱杨柳枝，春来輭无力。
怜君别我后，见竹长相忆。
长欲在眼前，故栽庭户侧。
分首今何处，君南我在北。
吟我赠君诗，对之心恻恻。','',''),('quantangshi-21949','感鹤','白居易','quantangshi','','卷22','鹤有不羣者，飞飞在野田。
饥不啄腐鼠，渴不饮盗泉。
贞姿自耿介，杂鸟何翩翾。
同游不同志，如此十余年。
一兴嗜欲念，遂为矰缴牵。
委质小池内，争食羣鸡前。
不惟怀稻粱，兼亦竞腥膻。
不惟恋主人，兼亦狎鸟鸢。
物心不可知，天性有时迁。
一饱尚如此，况乘大夫轩。','',''),('quantangshi-21950','春雪','白居易','quantangshi','','卷22','元和岁在卯，六年春二月。
月晦寒食天，天阴夜飞雪。
连宵复竟日，浩浩殊未歇。
大似落鹅毛，密如飘玉屑。
寒销春茫苍，气变风凛冽。
上林草尽没，曲江水复结。
红干杏花死，绿冻杨枝折。
所怜物性伤，非惜年芳绝。
上天有时令，四序平分别。
寒燠苟反常，物生皆夭阏。
我观圣人意，鲁史有其说。
或记水不冰，或书霜不杀。
上将儆政教，下以防灾孽。
兹雪今如何，信美非时节。','',''),('quantangshi-21951','高仆射','白居易','quantangshi','','卷22','富贵人所爱，圣人去其泰。
所以致仕年，着在礼经内。
玄元亦有训，知止则不殆。
二疏独能行，遗迹东门外。
清风久销歇，迨此向千载。
斯人古亦稀，何况今之代。
遑遑名利客，白首千百辈。
惟有高仆射，七十悬车盖。
我年虽未老，岁月亦云迈。
预恐耄及时，贪荣不能退。
中心私自儆，何以为我戒。
故作仆射诗，书之于大带。','',''),('quantangshi-21952','白牡丹','白居易','quantangshi','','卷22','城中看花客，旦暮走营营。
素华人不顾，亦占牡丹名。
闭在深寺中，车马无来声。
唯有钱学士，尽日绕丛行。
怜此皓然质，无人自芳馨。
众嫌我独赏，移植在中庭。
留景夜不暝，迎光曙先明。
对之心亦静，虚白相向生。
唐昌玉蘂花，攀玩众所争。
折来比颜色，一种如瑶琼。
彼因稀见贵，此以多为轻。
始知无正色，爱恶随人情。
岂惟花独尔，理与人事并。
君看入时者，紫艳与红英。','',''),('quantangshi-21953','赠内','白居易','quantangshi','','卷22','生为同室亲，死为同穴尘。
他人尚相勉，而况我与君。
黔娄固穷士，妻贤忘其贫。
冀缺一农夫，妻敬俨如宾。
陶潜不营生，翟氏自爨薪。
梁鸿不肯仕，孟光甘布帬。
君虽不读书，此事耳亦闻。
至此千载后，传是何如人。
人生未死间，不能忘其身。
所须者衣食，不过饱与温。
蔬食足充饥，何必膏粱珍。
缯絮足御寒，何必锦绣文。
君家有贻训，清白遗子孙。
我亦贞苦士，与君新结婚。
庶保贫与素，偕老同欣欣。','',''),('quantangshi-21954','寄唐生','白居易','quantangshi','','卷22','贾谊哭时事，阮籍哭路岐。
唐生今亦哭，异代同其悲。
唐生者何人，五十寒且饥。
不悲口无食，不悲身无衣。
所悲忠与义，悲甚则哭之。
太尉击贼日，尚书叱盗时。
大夫死凶寇，谏议谪蛮夷。
每见如此事，声发涕辄随。
往往闻其风，俗士犹或非。
怜君头半白，其志竟不衰。
我亦君之徒，郁郁何所为。
不能发声哭，转作乐府诗。
篇篇无空文，句句必尽规。
功高虞人箴，痛甚骚人辞。
非求宫律高，不务文字奇。
惟歌生民病，愿得天子知。
未得天子知，甘受时人嗤。
药良气味苦，琴澹音声稀。
不惧权豪怒，亦任亲朋议。
人竟无奈何，呼作狂男儿。
每逢羣盗息，或遇云雾披。
但自高声歌，庶几天听卑。
歌哭虽异名，所感则同归。
寄君三十章，与君为哭词。','',''),('quantangshi-21955','伤唐衢二首 一','白居易','quantangshi','','卷22','自我心存道，外物少能逼。
常排伤心事，不为长叹息。
忽闻唐衢死，不觉动颜色。
悲端从东来，触我心恻恻。
伊昔未相知，偶游滑台侧。
同宿李翺家，一言如旧识。
酒酣出送我，风雪黄河北。
日西竝马头，语别至昏黑。
君归向东郑，我来游上国。
交心不交面，从此重相忆。
怜君儒家子，不得诗书力。
五十着青衫，试官无禄食。
遗文仅千首，六义无差忒。
散在京洛间，何人为收拾。','',''),('quantangshi-21956','伤唐衢二首 二','白居易','quantangshi','','卷22','忆昨元和初，忝备谏官位。
是时兵革后，生民正顦顇。
但伤民病痛，不识时忌讳。
遂作秦中吟，一吟悲一事。
贵人皆怪怒，闲人亦非訾。
天高未及闻，荆棘生满地。
惟有唐衢见，知我平生志。
一读兴叹嗟，再吟垂涕泗。
因和三十韵，手题远缄寄。
致吾陈杜间，赏爱非常意。
此人无复见，此诗犹可贵。
今日开箧看，蠹鱼损文字。
不知何处葬，欲问先歔欷。
终去哭坟前，还君一掬泪。','',''),('quantangshi-21957','问友','白居易','quantangshi','','卷22','种兰不种艾，兰生艾亦生。
根荄相交长，茎叶相附荣。
香茎与臭叶，日夜俱长大。
锄艾恐伤兰，溉兰恐滋艾。
兰亦未能溉，艾亦未能除。
沈吟意不决，问君合何如。','',''),('quantangshi-21958','悲哉行','白居易','quantangshi','','卷22','悲哉为儒者，力学不知疲。
读书眼欲暗，秉笔手生胝。
十上方一第，成名常苦迟。
纵有宦达者，两鬓已成丝。
可怜少壮日，适在穷贱时。
丈夫老且病，焉用富贵为。
沈沈朱门宅，中有乳臭儿。
状貌如妇人，光明膏粱肌。
手不把书卷，身不擐戎衣。
二十袭封爵，门承勋戚资。
春来日日出，服御何轻肥。
朝从博徒饮，暮有倡楼期。
平封还酒债，堆金选蛾眉。
声色狗马外，其余一无知。
山苗与涧松，地势随高卑。
古来无奈何，非君独伤悲。','',''),('quantangshi-21959','紫藤','白居易','quantangshi','','卷22','藤花紫蒙茸，藤叶青扶疎。
谁谓好颜色，而为害有余。
下如蛇屈盘，上若绳萦纡。
可怜中间树，束缚成枯株。
柔蔓不自胜，袅袅挂空虚。
岂知缠树木，千夫力不如。
先柔后为害，有似谀佞徒。
附着君权势，君迷不肯诛。
又如妖妇人，绸缪蛊其夫。
奇邪坏人室，夫惑不能除。
寄言邦与家，所慎在其初。
毫末不早辨，滋蔓信难图。
愿以藤为戒，铭之于座隅。','',''),('quantangshi-21960','放鹰','白居易','quantangshi','','卷22','十月鹰出笼，草枯雉兔肥。
下韝随指顾，百掷无一遗。
鹰翅疾如风，鹰爪利如锥。
本为鸟所设，今为人所资。
孰能使之然，有术甚易知。
取其向背性，制在饥饱时。
不可使长饱，不可使长饥。
饥则力不足，饱则背人飞。
乘饥纵搏击，未饱须絷维。
所以爪翅功，而人坐收之。
圣明驭英雄，其术亦如斯。
鄙语不可弃，吾闻诸猎师。','',''),('quantangshi-21961','慈乌夜啼','白居易','quantangshi','','卷22','慈乌失其母，哑哑吐哀音。
昼夜不飞去，经年守故林。
夜夜夜半啼，闻者为霑襟。
声中如告诉，未尽反哺心。
百鸟岂无母，尔独哀怨深。
应是母慈重，使尔悲不任。
昔有吴起者，母殁丧不临。
嗟哉斯徒辈，其心不如禽。
慈乌复慈乌，鸟中之曾参。','',''),('quantangshi-21962','燕诗示刘叟','白居易','quantangshi','','卷22','梁上有双燕，翩翩雄与雌。
衔泥两椽间，一巢生四儿。
四儿日夜长，索食声孜孜。
青虫不易捕，黄口无饱期。
觜爪虽欲敝，心力不知疲。
须臾十来往，犹恐巢中饥。
辛勤三十日，母瘦雏渐肥。
喃喃教言语，一一刷毛衣。
一旦羽翼成，引上庭树枝。
举翅不回顾，随风四散飞。
雌雄空中鸣，声尽呼不归。
却入空巢里，啁啾终夜悲。
燕燕尔勿悲，尔当返自思。
思尔为雏日，高飞背母时。
当时父母念，今日尔应知。','',''),('quantangshi-21963','采地黄者','白居易','quantangshi','','卷22','麦死春不雨，禾损秋早霜。
岁晏无口食，田中采地黄。
采时将何用，持以易糇粮。
凌晨荷锄去，薄暮不盈筐。
携来朱门家，卖与白面郎。
与君噉肥马，可使照地光。
愿易马残粟，救此苦饥肠。','',''),('quantangshi-21964','初入太行路','白居易','quantangshi','','卷22','天冷日不光，太行峰苍莽。
尝闻此中险，今我方独往。
马蹄冻且滑，羊肠不可上。
若比世路难，犹自平于掌。','',''),('quantangshi-21965','邓鲂张彻落第','白居易','quantangshi','','卷22','古琴无俗韵，奏罢无人听。
寒松无妖花，枝下无人行。
春风十二街，轩骑不暂停。
奔车看牡丹，走马听秦筝。
众目悦芳艳，松独守其贞。
众耳喜郑卫，琴亦不改声。
怀哉二夫子，念此无自轻。','',''),('quantangshi-21966','送王处士','白居易','quantangshi','','卷22','王门岂无酒，侯门岂无肉。
主人贵且骄，待客礼不足。
望尘而拜者，朝夕走碌碌。
王生独拂衣，遐举如云鹄。
宁归白云外，饮水卧空谷。
不能随众人，敛手低眉目。
扣门与我别，酤酒留君宿。
好去采薇人，终南山正绿。','',''),('quantangshi-21967','村居苦寒','白居易','quantangshi','','卷22','八年十二月，五日雪纷纷。
竹柏皆冻死，况彼无衣民。
回观村闾间，十室八九贫。
北风利如劒，布絮不蔽身。
唯烧蒿棘火，愁坐夜待晨。
乃知大寒岁，农者尤苦辛。
顾我当此日，草堂深掩门。
褐裘覆絁被，坐卧有余温。
幸免饥冻苦，又无壠亩勤。
念彼深可愧，自问是何人。','',''),('quantangshi-21968','纳粟','白居易','quantangshi','','卷22','有吏夜叩门，高声催纳粟。
家人不待晓，场上张灯烛。
扬簸净如珠，一车三十斛。
犹忧纳不中，鞭责及僮仆。
昔余谬从事，内愧才不足。
连授四命官，坐尸十年禄。
常闻古人语，损益周必复。
今日谅甘心，还他太仓谷。','',''),('quantangshi-21969','薛中丞','白居易','quantangshi','','卷22','百人无一直，百直无一遇。
借问遇者谁，正人行得路。
中丞薜存诚，守直心甚固。
皇明烛如日，再使秉王度。
奸豪与佞巧，非不憎且惧。
直道渐光明，邪谋难盖覆。
每因匪躬节，知有匡时具。
张为坠网纲，倚作颓檐柱。
悠哉上天意，报施纷回互。
自古已冥茫，从今尤不谕。
岂与小人意，昏然同好恶。
不然君子人，何反如朝露。
裴相昨已夭，薛君今又去。
以我惜贤心，五年如旦暮。
况闻善人命，长短系运数。
今我一涕零，岂为中丞故。','',''),('quantangshi-21970','秋池二首 一','白居易','quantangshi','','卷22','前池秋始半，卉物多摧坏。
欲暮槿先萎，未霜荷已败。
默然有所感，可以从兹诫。
本不种松筠，早雕何足怪。','',''),('quantangshi-21971','秋池二首 二','白居易','quantangshi','','卷22','凿池贮秋水，中有苹与芰。
天旱水暗消，塌然委空地。
有似泛泛者，附离权与贵。
一旦恩势移，相随共顦顇。','',''),('quantangshi-21972','夏旱','白居易','quantangshi','','卷22','太阴不离毕，太岁仍在午。
旱日与炎风，枯燋我田亩。
金石欲销铄，况兹禾与黍。
嗸嗸万族中，唯农最辛苦。
悯然望岁者，出门何所覩。
但见棘与茨，罗生徧场圃。
恶苗承沴气，欣然得其所。
感此因问天，可能长不雨。','',''),('quantangshi-21973','谕友','白居易','quantangshi','','卷22','昨夜霜一降，杀君庭中槐。
干叶不待黄，索索飞下来。
怜君感节物，晨起步前阶。
临风蹋叶立，半日颜色哀。
西望长安城，歌钟十二街。
何人不欢乐，君独心悠哉。
白日头上走，朱颜镜中颓。
平生青云心，销化成死灰。
我今赠一言，胜饮酒千杯。
其言虽甚鄙，可破悒悒怀。
朱门有勋贵，陋巷有颜回。
穷通各问命，不系才不才。
推此自豁豁，不必待安排。','',''),('quantangshi-21974','丘中有一士二首 一','白居易','quantangshi','','卷22','丘中有一士，不知其姓名。
面色不忧苦，血气常和平。
每选隙地居，不蹋要路行。
举动无尤悔，物莫与之争。
藜藿不充肠，布褐不蔽形。
终岁守穷饿，而无嗟叹声。
岂是爱贫贱，深知时俗情。
勿矜罗弋巧，鸾鹤在冥冥。','',''),('quantangshi-21975','丘中有一士二首 二','白居易','quantangshi','','卷22','丘中有一士，守道岁月深。
行披带索衣，坐拍无弦琴。
不饮浊泉水，不息曲木阴。
所逢苟非义，粪土千黄金。
乡人化其风，熏如兰在林。
智愚与强弱，不忍相欺侵。
我欲访其人，将行复沈吟。
何必见其面，但在学其心。','',''),('quantangshi-21976','新制布裘','白居易','quantangshi','','卷22','桂布白似雪，吴緜輭于云。
布重緜且厚，为裘有余温。
朝拥坐至暮，夜覆眠达晨。
谁知严冬月，支体暖如春。
中夕忽有念，抚裘起逡巡。
丈夫贵兼济，岂独善一身。
安得万里裘，盖裹周四垠。
稳暖皆如我，天下无寒人。','',''),('quantangshi-21977','杏园中枣树','白居易','quantangshi','','卷22','人言百果中，唯枣凡且鄙。
皮皴似龟手，叶小如鼠耳。
胡为不自知，生花此园里。
岂宜遇攀玩，幸免遭伤毁。
二月曲江头，杂英红旖旎。
枣亦在其间，如嫫对西子。
东风不择木，吹喣长未已。
眼看欲合抱，得尽生生理。
寄言游春客，乞君一回视。
君爱绕指柔，从君怜柳杞。
君求悦目艳，不敢争桃李。
君若作大车，轮轴材须此。','',''),('quantangshi-21978','虾蟇','白居易','quantangshi','','卷22','嘉鱼荐宗朝，灵龟贡邦家。
应龙能致雨，润我百谷芽。
蠢蠢水族中，无用者虾蟇。
形秽肌肉腥，出没于泥沙。
六月七月交，时雨正滂沱。
虾蟇得其志，快乐无以加。
地既蕃其生，使之族类多。
天又与其声，得以相喧哗。
岂惟玉池上，汚君清冷波。
可独瑶瑟前，乱君鹿鸣歌。
常恐飞上天，跳跃随姮娥。
往往蚀明月，遣君无奈何。','',''),('quantangshi-21979','寄隐者','白居易','quantangshi','','卷22','卖药向都城，行憩青门树。
道逢驰驿者，色有非常惧。
亲族走相送，欲别不敢住。
私怪问道旁，何人复何故。
云是右丞相，当国握枢务。
禄厚食万钱，恩深日三顾。
昨日延英对，今日崖州去。
由来君臣间，宠辱在朝暮。
青青东郊草，中有归山路。
归去卧云人，谋身计非误。','',''),('quantangshi-21980','放鱼','白居易','quantangshi','','卷22','晓日提竹篮，家僮买春蔬。
青青芹蕨下，叠卧双白鱼。
无声但呀呀，以气相喣濡。
倾篮写地上，拨刺长尺余。
岂唯刀机忧，坐见蝼蚁图。
脱泉虽已久，得水犹可苏。
放之小池中，且用救干枯。
水小池窄狭，动尾触四隅。
一时幸苟活，久远将何如。
怜其不得所，移放于南湖。
南湖连西江，好去勿踟蹰。
施恩即望报，吾非斯人徒。
不须泥沙底，辛苦觅明珠。','',''),('quantangshi-21981','文柏牀','白居易','quantangshi','','卷22','陵上有老柏，柯叶寒苍苍。
朝为风烟树，暮为宴寝牀。
以其多奇文，宜升君子堂。
刮削露节目，拂拭生辉光。
玄斑状狸首，素质如截肪。
虽充悦目玩，终乏周身防。
华彩诚可爱，生理苦已伤。
方知自残者，为有好文章。','',''),('quantangshi-21982','浔阳三题 庐山桂','白居易','quantangshi','','卷22','偃蹇月中桂，结根依青天。
天风绕月起，吹子下人间。
飘零委何处，乃落匡庐山。
生为石上桂，叶如翦碧鲜。
枝干日长大，根荄日牢坚。
不归天上月，空老山中年。
庐山去咸阳，道里三四千。
无人为移植，得入上林园。
不及红花树，长栽温室前。','',''),('quantangshi-21983','浔阳三题 湓浦竹','白居易','quantangshi','','卷22','浔阳十月天，天气仍温燠。
有霜不杀草，有风不落木。
玄冥气力薄，草木冬犹绿。
谁肯湓浦头，回眼看修竹。
其有顾盼者，持刀斩且束。
剖劈青琅玕，家家盖墙屋。
吾闻汾晋间，竹少重如玉。
胡为取轻贱，生此西江曲。','',''),('quantangshi-21984','浔阳三题 东林寺白莲','白居易','quantangshi','','卷22','东林北塘水，湛湛见底清。
中生白芙蓉，菡萏三百茎。
白日发光彩，清飙散芳馨。
泄香银囊破，泻露玉盘倾。
我慙尘垢眼，见此琼瑶英。
乃知红莲花，虚得清净名。
夏萼敷未歇，秋房结才成。
夜深众僧寝，独起绕池行。
欲收一颗子，寄向长安城。
但恐出山去，人间种不生。','',''),('quantangshi-21985','大水','白居易','quantangshi','','卷22','浔阳郊郭间，大水岁一至。
闾阎半飘荡，城堞多倾坠。
苍茫生海色，渺漫连空翠。
风卷白波飜，日煎红浪沸。
工商彻屋去，牛马登山避。
况当率税时，颇害农桑事。
独有佣舟子，鼓枻生意气。
不知万人灾，自觅锥刀利。
吾无奈尔何，尔非久得志。
九月霜降后，水涸为平地。','',''),('quantangshi-21986','续古诗十首 一','白居易','quantangshi','','卷22','戚戚复戚戚，送君远行役。
行役非中原，海外黄沙碛。
伶俜独居妾，迢遰长征客。
君望功名归，妾忧生死隔。
谁家无夫妇，何人不离坼。
所恨薄命身，嫁迟别日迫。
妾身有存殁，妾心无改易。
生作闺中妇，死作山头石。','',''),('quantangshi-21987','续古诗十首 二','白居易','quantangshi','','卷22','掩泪别乡里，飘颻将远行。
茫茫绿野中，春尽孤客情。
驱马上丘陇，高低路不平。
风吹棠棃花，啼鸟时一声。
古墓何代人，不知姓与名。
化作路傍土，年年春草生。
感彼忽自悟，今我何营营。','',''),('quantangshi-21988','续古诗十首 三','白居易','quantangshi','','卷22','朝采山上薇，暮采山上薇。
岁晏薇亦尽，饥来何所为。
坐饮白石水，手把青松枝。
击节独长謌，其声清且悲。
枥马非不肥，所苦常絷维。
豢豕非不饱，所忧竟为牺。
行行歌此曲，以慰常苦饥。','',''),('quantangshi-21989','续古诗十首 四','白居易','quantangshi','','卷22','雨露长纤草，山苗高入云。
风雪折劲木，涧松摧为薪。
风摧此何意，雨长彼何因。
百丈涧底死，寸茎山上春。
可怜苦节士，感此涕盈巾。','',''),('quantangshi-21990','续古诗十首 五','白居易','quantangshi','','卷22','窈窕双鬟女，容德俱如玉。
昼居不逾阈，夜行常秉烛。
气如含露兰，心如贯霜竹。
宜当备嫔御，胡为守幽独。
无媒不得选，年忽过三六。
岁暮望汉宫，谁在黄金屋。
邯郸进倡女，能唱黄花曲。
一曲称君心，恩荣连九族。','',''),('quantangshi-21991','续古诗十首 六','白居易','quantangshi','','卷22','栖栖远方士，读书三十年。
业成无知己，徒步来入关。
长安多王候，英俊竞攀援。
幸随众宾末，得厠门馆间。
东合有旨酒，中堂有管弦。
何为向隅客，对此不开颜。
富贵无是非，主人终日欢。
贫贱多悔尤，客子中夜叹。
归去复归去，故乡贫亦安。','',''),('quantangshi-21992','续古诗十首 七','白居易','quantangshi','','卷22','凉风飘嘉树，日夜减芳华。
下有感秋妇，攀条苦悲嗟。
我本幽闲女，结发事豪家。
豪家多婢仆，门内颇骄奢。
良人近封候，出入鸣玉珂。
自从富贵来，恩薄谗言多。
冢妇独守礼，羣妾互奇衺。
但信言有玷，不察心无瑕。
容光未销歇，欢爱忽蹉跎。
何意掌上玉，化为眼中砂。
盈盈一尺水，浩浩千丈河。
勿言小大异，随分有风波。
闺房犹复尔，邦国当如何。','',''),('quantangshi-21993','续古诗十首 八','白居易','quantangshi','','卷22','心亦无所迫，身亦无所拘。
何为肠中气，郁郁不得舒。
不舒良有以，同心久离居。
五年不见面，三年不得书。
念此令人老，抱膝坐长吁。
岂无盈尊酒，非君谁与娱。','',''),('quantangshi-21994','续古诗十首 九','白居易','quantangshi','','卷22','揽衣出门行，游观绕林渠。
澹澹春水暖，东风生绿蒲。
上有和鸣雁，下有掉尾鱼。
飞沈一何乐，鳞羽各有徒。
而我方独处，不与之子俱。
顾彼自伤己，禽鱼之不如。
出游欲遣忧，孰知忧有余。','',''),('quantangshi-21995','续古诗十首 十','白居易','quantangshi','','卷22','春旦日初出，曈曈耀晨辉。
草木照未远，浮云已蔽之。
天地黯以晦，当午如昏时。
虽有东南风，力微不能吹。
中园何所有，满地青青葵。
阳光委云上，倾心欲何依。','',''),('quantangshi-21996','秦中吟十首 议婚','白居易','quantangshi','','卷22','天下无正声，悦耳即为娱。
人间无正色，悦目即为姝。
颜色非相远，贫富则有殊。
贫为时所弃，富为时所趋。
红楼富家女，金缕绣罗襦。
见人不敛手，娇痴二八初。
母兄未开口，已嫁不须臾。
绿窗贫家女，寂莫二十余。
荆钗不直钱，衣上无真珠。
几回人欲聘，临日又踟蹰。
主人会良媒，置酒满玉壶。
四座且勿饮，听我歌两途。
富家女易嫁，嫁早轻其夫。
贫家女难嫁，嫁晚孝于姑。
闻君欲娶妇，娶妇意何如。','',''),('quantangshi-21997','秦中吟十首 重赋','白居易','quantangshi','','卷22','厚地植桑麻，所要济生民。
生民理布帛，所求活一身。
身外充征赋，上以奉君亲。
国家定两税，本意在爱人。
厥初防其淫，明敕内外臣。
税外加一物，皆以枉法论。
奈何岁月久，贪吏得因循。
浚我以求宠，敛索无冬春。
织绢未成匹，缲丝未盈斤。
里胥迫我纳，不许暂逡巡。
岁暮天地闭，阴风生破村。
夜深烟火尽，霰雪白纷纷。
幼者形不蔽，老者体无温。
悲喘与寒气，并入鼻中辛。
昨日输残税，因窥官库门。
缯帛如山积，丝絮如云屯。
号为羡余物，随月献至尊。
夺我身上暖，买尔眼前恩。
进入琼林库，岁久化为尘。','',''),('quantangshi-21998','秦中吟十首 伤宅','白居易','quantangshi','','卷22','谁家起甲第，朱门大道边。
丰屋中栉比，高墙外回环。
累累六七堂，栋宇相连延。
一堂费百万，郁郁起青烟。
洞房温且清，寒暑不能干。
高堂虚且迥，坐卧见南山。
绕廊柴藤架，夹砌红药栏。
攀枝摘樱桃，带花移牡丹。
主人此中坐，十载为大官。
厨有臭败肉，库有贯朽钱。
谁能将我语，问尔骨肉间。
岂无穷贱者，忍不救饥寒。
如何奉一身，直欲保千年。
不见马家宅，今作奉诚园。','',''),('quantangshi-21999','秦中吟十首 伤友','白居易','quantangshi','','卷22','陋巷孤寒士，出门苦恓恓。
虽云志气高，岂免颜色低。
平生同门友，通籍在金闺。
曩者胶漆契，迩来云雨睽。
正逢下朝归，轩骑五门西。
是时天久阴，三日雨凄凄。
蹇驴避路立，肥马当风嘶。
回头忘相识，占道上沙堤。
昔年洛阳社，贫贱相提携。
今日长安道，对面隔云泥。
近日多如此，非君独惨凄。
死生不变者，唯闻任与黎。','',''),('quantangshi-22000','秦中吟十首 不致仕','白居易','quantangshi','','卷22','七十而致仕，礼法有明文。
何乃贪荣者，斯言如不闻。
可怜八九十，齿堕双眸昏。
朝露贪名利，夕阳忧子孙。
挂冠顾翠緌，悬车惜朱轮。
金章腰不胜，伛偻入君门。
谁不爱富贵，谁不恋君恩。
年高须告老，名遂合退身。
少时共嗤诮，晚岁多因循。
贤哉汉二疏，彼独是何人。
寂莫东门路，无人继去尘。','',''),('quantangshi-22001','秦中吟十首 立碑','白居易','quantangshi','','卷22','勋德既下衰，文章亦陵夷。
但见山中石，立作路旁碑。
铭勋悉太公，叙德皆仲尼。
复以多为贵，千言直万赀。
为文彼何人，想见下笔时。
但欲愚者悦，不思贤者嗤。
岂独贤者嗤，仍传后代疑。
古石苍苔字，安知是愧词。
我闻望江县，麴令抚惸嫠。
在官有仁政，名不闻京师。
身殁欲归葬，百姓遮路岐。
攀辕不得归，留葬此江湄。
至今道其名，男女涕皆垂。
无人立碑碣，唯有邑人知。','',''),('quantangshi-22002','秦中吟十首 轻肥','白居易','quantangshi','','卷22','意气骄满路，鞍马光照尘。
借问何为者，人称是内臣。
朱绂皆大夫，紫绶或将军。
夸赴军中宴，走马去如云。
尊罍溢九酝，水陆罗八珍。
果擘洞庭橘，脍切天池鳞。
食饱心自若，酒酣气益振。
是岁江南旱，衢州人食人。','',''),('quantangshi-22003','秦中吟十首 五弦','白居易','quantangshi','','卷22','清歌且罢唱，红袂亦停舞。
赵叟抱五弦，宛转当胸抚。
大声麄若散，飒飒风和雨。
小声细欲绝，切切鬼神语。
又如鹊报喜，转作猨啼苦。
十指无定音，颠倒宫征羽。
坐客闻此声，形神若无主。
行客闻此声，驻足不能举。
嗟嗟俗人耳，好今不好古。
所以绿窗琴，日日生尘土。','',''),('quantangshi-22004','秦中吟十首 歌舞','白居易','quantangshi','','卷22','秦中岁云暮，大雪满皇州。
雪中退朝者，朱紫尽公候。
贵有风雪兴，富无饥寒忧。
所营唯第宅，所务在追游。
朱门车马客，红烛歌舞楼。
欢酣促密坐，醉暖脱重裘。
秋官为主人，廷尉居上头。
日中为一乐，夜半不能休。
岂知阌乡狱，中有冻死囚。','',''),('quantangshi-22005','秦中吟十首 买花','白居易','quantangshi','','卷22','帝城春欲暮，喧喧车马度。
共道牡丹时，相随买花去。
贵贱无常价，酬直看花数。
灼灼百朵红，戋戋五束素。
上张幄幕庇，旁织巴篱护。
水洒复泥封，移来色如故。
家家习为俗，人人迷不悟。
有一田舍翁，偶来买花处。
低头独长叹，此叹无人喻。
一丛深色花，十户中人赋。','',''),('quantangshi-22006','赠友五首 一','白居易','quantangshi','','卷22','一年十二月，每月有常令。
君出臣奉行，谓之握金镜。
由兹六气顺，以遂万物性。
时令一反常，生灵受其病。
周汉德下衰，王风始不竞。
又从斩鼂错，诸侯益强盛。
百里不同禁，四时自为政。
盛夏兴土功，方春剿人命。
谁能救其失，待君佐邦柄。
峨峨象魏门，悬法彝伦正。','',''),('quantangshi-22007','赠友五首 二','白居易','quantangshi','','卷22','银生楚山曲，金生鄱溪滨。
南人弃农业，求之多苦辛。
披砂复凿石，矻矻无冬春。
手足尽皴胝，爱利不爱身。
畲田既慵斫，稻田亦嬾耘。
相携作游手，皆道求金银。
毕竟金与银，何殊泥与尘。
且非衣食物，不济饥寒人。
弃本以趋末，日富而岁贫。
所以先圣王，弃藏不为珍。
谁能反古风，待君秉国钧。
捐金复抵璧，勿使劳生民。','',''),('quantangshi-22008','赠友五首 三','白居易','quantangshi','','卷22','私家无钱炉，平地无铜山。
胡为秋夏税，岁岁输铜钱。
钱力日已重，农力日已殚。
贱粜粟与麦，贱贸丝与緜。
岁暮衣食尽，焉得无饥寒。
吾闻国之初，有制垂不刊。
庸必算丁口，租必计桑田。
不求土所无，不强人所难。
量入以为出，上足下亦安。
兵兴一变法，兵息遂不还。
使我农桑人，顦顇畎亩间。
谁能革此弊，待君秉利权。
复彼租庸法，令如贞观年。','',''),('quantangshi-22009','赠友五首 四','白居易','quantangshi','','卷22','京师四方则，王化之本根。
长吏久于政，然后风教敦。
如何尹京者，迁次不逡巡。
请君屈指数，十年十五人。
科条日相矫，吏力亦已勤。
宽猛政不一，民心安得淳。
九州雍为首，羣牧之所遵。
天下率如此，何以安吾民。
谁能变此法，待君赞弥纶。
慎择循良吏，令其长子孙。','',''),('quantangshi-22010','赠友五首 五','白居易','quantangshi','','卷22','三十男有室，二十女有归。
近代多离乱，婚姻多过期。
嫁娶既不早，生育常苦迟。
儿女未成人，父母已衰羸。
凡人贵达日，多在长大时。
欲报亲不待，孝心无所施。
哀哉三牲养，少得及庭闱。
惜哉万钟粟，多用饱妻儿。
谁能正婚礼，待君张国维。
庶使孝子心，皆无风树悲。','',''),('quantangshi-22011','寓意诗五首 一','白居易','quantangshi','','卷22','豫樟生深山，七年而后知。
挺高二百尺，本末皆十围。
天子建明堂，此材独中规。
匠人执斤墨，采度将有期。
孟冬草木枯，烈火燎山陂。
疾风吹猛焰，从根烧到枝。
养材三十年，方成栋梁姿。
一朝为灰烬，柯叶无孑遗。
地虽生尔材，天不与尔时。
不如粪土英，犹有人掇之。
已矣勿重陈，重陈令人悲。
不悲焚烧苦，但悲采用迟。','',''),('quantangshi-22012','寓意诗五首 二','白居易','quantangshi','','卷22','赫赫京内史，炎炎中书郎。
昨传征拜日，恩赐颇殊常。
貂冠水苍玉，紫绶黄金章。
佩服身未暖，已闻窜遐荒。
亲戚不得别，吞声泣路旁。
宾客亦已散，门前雀罗张。
富贵来不久，倏如瓦沟霜。
权势去尤速，瞥若石火光。
不如守贫贱，贫贱可久长。
传语宦游子，且来归故乡。','',''),('quantangshi-22013','寓意诗五首 三','白居易','quantangshi','','卷22','促织不成章，提壶但闻声。
嗟哉虫与鸟，无实有虚名。
与君定交日，久要如弟兄。
何以示诚信，白水指为盟。
云雨一为别，飞沈两难并。
君为得风鹏，我为失水鲸。
音信日已疎，恩分日已轻。
穷通尚如此，何况死与生。
乃知择交难，须有知人明。
莫将山上松，结托水上萍。','',''),('quantangshi-22014','寓意诗五首 四','白居易','quantangshi','','卷23','翩翩两玄鸟，本是同巢燕。
分飞来几时，秋夏炎凉变。
一宿蓬筚庐，一栖明光殿。
偶因衔泥处，复得重相见。
彼矜杏梁贵，此嗟茅栋贱。
眼看秋社至，两处俱难恋。
所托各暂时，胡为相叹羡。','',''),('quantangshi-22015','寓意诗五首 五','白居易','quantangshi','','卷23','婆娑园中树，根株大合围。
蠢尔树间虫，形质一何微。
孰谓虫之微，虫蠹已无期。
孰谓树之大，花叶有衰时。
花衰夏未实，叶病秋先萎。
树心半为土，观者安得知。
借问虫何在，在身不在枝。
借问虫何食，食心不食皮。
岂无啄木鸟，觜长将何为。','',''),('quantangshi-22016','读史五首 一','白居易','quantangshi','','卷23','楚怀放灵均，国政亦荒淫。
彷徨未忍决，绕泽行悲吟。
汉文疑贾生，谪置湘之阴。
是时刑方措，此去难为心。
士生一代间，谁不有浮沈。
良时真可惜，乱世何足钦。
乃知汨罗恨，未抵长沙深。','',''),('quantangshi-22017','读史五首 二','白居易','quantangshi','','卷23','祸患如棼丝，其来无端绪。
马迁下蚕室，嵇康就囹圄。
抱冤志气屈，忍耻形神沮。
当彼戮辱时，奋飞无翅羽。
商山有黄绮，颍川有巢许。
何不从之游？超然离网罟。
山林少羁鞅，世路多艰阻。
寄谢伐檀人，慎勿嗟穷处。','',''),('quantangshi-22018','读史五首 三','白居易','quantangshi','','卷23','汉日大江军，少为乞食子。
秦时故列侯，老作锄瓜士。
春华何暐晔，园中发桃李。
秋风忽萧条，堂上生荆杞。
深谷变为岸，桑田成海水。
势去未须悲，时来何足喜。
寄言荣枯者，反复殊未已。','',''),('quantangshi-22019','读史五首 四','白居易','quantangshi','','卷23','含沙射人影，虽病人不知。
巧言构人罪，至死人不疑。
掇蠭杀爱子，掩鼻戮宠姬。
弘恭陷萧望，赵高谋李斯。
阴德既必报，阴祸岂虚施。
人事虽可罔，天道终难欺。
明则有刑辟，幽则有神祗。
苟免勿私喜，鬼得而诛之。','',''),('quantangshi-22020','读史五首 五','白居易','quantangshi','','卷23','季子顦顇时，妇见不下机。
买臣负薪日，妻亦弃如遗。
一朝黄金多，佩印衣锦归。
去妻不敢视，妇嫂强依依。
富贵家人重，贫贱妻子欺。
奈何贫富间，可移亲爱志。
遂使中人心，汲汲求富贵。
又令下人力，各竞锥刀利。
随分归舍来，一取妻孥意。','',''),('quantangshi-22021','和答诗十首 和思归乐','白居易','quantangshi','','卷23','山中不栖鸟，夜半声嘤嘤。
似道思归乐，行人掩泣听。
皆疑此山路，迁客多南征。
忧愤气不散，结化为精灵。
我谓此山鸟，本不因人生。
人心自怀土，想作思归鸣。
孟尝平居时，娱耳琴泠泠。
雍门一言感，未奏泪霑缨。
魏武铜雀妓，日与欢乐并。
一旦西陵望，欲歌先涕零。
峡猨亦何意，陇水复何情。
为入愁人耳，皆为肠断声。
请看元侍御，亦宿此邮亭。
因听思归鸟，神气独安宁。
问君何以然，道胜心自平。
虽为南迁客，如在长安城。
云得此道来，何虑复何营。
穷达有前定，忧喜无交争。
所以事君日，持宪立大庭。
虽有回天力，挠之终不倾。
况始三十余，年少有直名。
心中志气大，眼前爵禄轻。
君恩若雨露，君威若雷霆。
退不苟免难，进不曲求荣。
在火辨玉性，经霜识松贞。
展禽任三黜，灵均长独醒。
获戾自东洛，贬官向南荆。
再拜辞阙下，长揖别公卿。
荆州又非远，驿路半月程。
汉水照天碧，楚山插云青。
江陵橘似珠，宜城酒如饧。
谁谓谴谪去，未妨游赏行。
人生百岁内，天地暂寓形。
太仓一稊米，大海一浮萍。
身委逍遥篇，心付头陀经。
尚达死生观，宁为宠辱惊。
中怀苟有主，外物安能萦。
任意思归乐，声声啼到明。','',''),('quantangshi-22022','和答诗十首 和阳城驿','白居易','quantangshi','','卷23','商山阳城驿，中有叹者谁。
云是元监察，江陵谪去时。
忽见此驿名，良久涕欲垂。
何故阳道州，名姓同于斯。
怜君一寸心，宠辱誓不移。
疾恶若巷伯，好贤如缁衣。
沈吟不能去，意者欲改为。
改为避贤驿，大署于门楣。
荆人爱羊祜，户曹改为辞。
一字不忍道，况兼姓呼之。
因题八百言，言直文甚奇。
诗成寄与我，锵若金和丝。
上言阳公行，友悌无等夷。
骨肉同衾裯，至死不相离。
次言阳公迹，夏邑始栖迟。
乡人化其风，少长皆孝慈。
次言阳公道，终日对酒巵。
兄弟笑相顾，醉貌红怡怡。
次言阳公节，謇謇居谏司。
誓心除国蠹，决死犯天威。
终言阳公命，左迁天一涯。
道州炎瘴地，身不得生归。
一一皆实录，事事无孑遗。
凡是为善者，闻之恻然悲。
道州既已矣，往者不可追。
何世无其人，来者亦可思。
愿以君子文，告彼大乐师。
附于雅歌末，奏之白玉墀。
天子闻此章，教化如法施。
直谏从如流，佞臣恶如疵。
宰相闻此章，政柄端正持。
进贤不知倦，去邪勿复疑。
宪臣闻此章，不敢怀依违。
谏官闻此章，不忍纵诡随。
然后告史氏，旧史有前规。
若作阳公传，欲令后世知。
不劳叙世家，不用费文辞。
但于国史上，全录元稹诗。','',''),('quantangshi-22023','和答诗十首 答桐花','白居易','quantangshi','','卷23','山木多蓊郁，兹桐独亭亭。
叶重碧云片，花簇紫霞英。
是时三月天，春暖山雨晴。
夜色向月浅，暗香随风轻。
行者多商贾，居者悉黎氓。
无人解赏爱，有客独屏营。
手攀花枝立，足蹋花影行。
生怜不得所，死欲扬其声。
截为天子琴，刻作古人形。
云待我成器，荐之于穆清。
诚是君子心，恐非草木情。
胡为爱其华，而反伤其生。
老龟被刳肠，不如无神灵。
雄鸡自断尾，不愿为牺牲。
况此好颜色，花紫叶青青。
宜遂天地性，忍加刀斧刑。
我思五丁力，拔入九重城。
当君正殿栽，花叶生光晶。
上对月中桂，下覆阶前蓂。
泛拂香炉烟，隐映斧藻屏。
为君布绿阴，当暑荫轩楹。
沈沈绿满地，桃李不敢争。
为君发清韵，风来如叩琼。
泠泠声满耳，郑卫不足听。
受君封植力，不独吐芬馨。
助君行春令，开花应晴明。
受君雨露恩，不独含芳荣。
戒君无戏言，翦叶封弟兄。
受君岁月功，不独资生成。
为君长高枝，凤皇上头鸣。
一鸣君万岁，寿如山不倾。
再鸣万人泰，泰阶为之平。
如何有此用，幽滞在岩坰。
岁月不尔驻，孤芳坐凋零。
请向桐枝上，为余题姓名。
待余有势力，移尔献丹庭。','',''),('quantangshi-22024','和答诗十首 和大觜乌','白居易','quantangshi','','卷23','乌者种有二，名同性不同。
觜小者慈孝，觜大者贪庸。
觜大命又长，生来十余冬。
物老颜色变，头毛白茸茸。
飞来庭树上，初但惊儿童。
老巫生奸计，与乌意潜通。
云此非凡鸟，遥见起敬恭。
千岁乃一出，喜贺主人翁。
祥瑞来白日，神圣占知风。
阴作北斗使，能为人吉凶。
此乌所止家，家产日夜丰。
上以致寿考，下可宜田农。
主人富家子，身老心童蒙。
随巫拜复祝，妇姑亦相从。
杀鸡荐其肉，敬若禋六宗。
乌喜张大觜，飞接在虚空。
乌既饱膻腥，巫亦飨甘浓。
乌巫互相利，不复两西东。
日日营巢窟，稍稍近房栊。
虽生八九子，谁辨其雌雄。
羣雏又成长，众觜逞残凶。
探巢吞燕卵，入蔟啄蚕虫。
岂无乘秋隼，羁绊委高墉。
但食乌残肉，无施搏击功。
亦有能言鹦，翅碧觜距红。
暂曾说乌罪，囚闭在深笼。
青青窗前柳，郁郁井上桐。
贪乌占栖息，慈乌独不容。
慈鸟尔奚为，来往何憧憧。
晓去先晨鼓，暮归后昏钟。
辛苦尘土间，飞啄禾黍丛。
得食将哺母，饥肠不自充。
主人憎慈乌，命子削弹弓。
弦续会稽竹，丸铸荆山铜。
慈乌求母食，飞下尔庭中。
数粒未入口，一丸已中胸。
仰天号一声，似欲诉苍穹。
反哺日未足，非是惜微躬。
谁能持此冤，一为问化工。
胡然大觜乌，竟得天年终。','',''),('quantangshi-22025','和答诗十首 答四皓庙','白居易','quantangshi','','卷23','天下有道见，无道卷怀之。
此乃圣人语，吾闻诸仲尼。
矫矫四先生，同禀希世资。
随时有显晦，秉道无磷缁。
秦皇肆暴虐，二世遘乱离。
先生相随去，商岭采紫芝。
君看秦狱中，戮辱者李斯。
刘项争天下，谋臣竟悦随。
先生如鸾鹤，去入冥冥飞。
君看齐鼎中，焦烂者郦其。
子房得沛公，自谓相遇迟。
八难掉舌枢，三略役心机。
辛苦十数年，昼夜形神疲。
竟杂霸者道，徒称帝者师。
子房尔则能，此非吾所宜。
汉高之季年，嬖宠钟所私。
冢嫡欲废夺，骨肉相忧疑。
岂无子房口，口舌无所施。
亦有陈平心，心计将何为。
皤皤四先生，高冠危映眉。
从容下南山，顾盼入东闱。
前瞻惠太子，左右生羽仪。
却顾戚夫人，楚舞无光辉。
心不画一计，口不吐一词。
暗定天下本，遂安刘氏危。
子房吾则能，此非尔所知。
先生道既光，太子礼甚卑。
安车留不住，功成弃如遗。
如彼旱天云，一雨百谷滋。
泽则在天下，云复归稀夷。
勿高巢与由，勿尚吕与伊。
巢由往不返，伊吕去不归。
岂如四先生，出处两逶迤。
何必长隐逸，何必长济时。
由来圣人道，无朕不可窥。
卷之不盈握，舒之亘八陲。
先生道甚明，夫子犹或非。
愿子辨其惑，为予吟此诗。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22026','和答诗十首 和雉媒','白居易','quantangshi','','卷23','吟君雉媒什，一哂一复叹。
和之一何晚，今日乃成篇。
岂唯鸟有之，抑亦人复然。
张陈刎颈交，竟以势不完。
至今不平气，塞绝泜水源。
赵襄骨肉亲，亦以利相残。
至今不善名，高于磨笄山。
况此笼中雉，志在饮啄间。
稻粱暂入口，性已随人迁。
身苦亦自忘，同族何足言。
但恨为媒拙，不足以自全。
劝君今日后，养鸟养青鸾。
青鸾一失侣，至死守孤单。
劝君今日后，结客结任安。
主人宾客去，独住在门阑。','',''),('quantangshi-22027','和答诗十首 和松树','白居易','quantangshi','','卷23','亭亭山上松，一一生朝阳。
森耸上参天，柯条百尺长。
漠漠尘中槐，两两夹康庄。
婆娑低覆地，枝干亦寻常。
八月白露降，槐叶次第黄。
岁暮满山雪，松色郁青苍。
彼如君子心，秉操贯冰霜。
此如小人面，变态随炎凉。
共知松胜槐，诚欲栽道傍。
粪土种瑶草，瑶草终不芳。
尚可以斧斤，伐之为栋梁。
杀身获其所，为君构明堂。
不然终天年，老死在南冈。
不愿亚枝叶，低随槐树行。','',''),('quantangshi-22028','和答诗十首 答箭镞','白居易','quantangshi','','卷23','矢人职司忧，为箭恐不精。
精在利其镞，错磨锋镝成。
插以青竹簳，羽之赤雁翎。
勿言分寸铁，为用乃长兵。
闻有狗盗者，昼伏夜潜行。
摩弓拭箭镞，夜射不待明。
一盗既流血，百犬同吠声。
狺狺嘷不已，主人为之惊。
盗心憎主人，主人不知情。
反责镞太利，矢人获罪名。
寄言控弦者，愿君少留听。
何不向西射？西天有狼星。
何不向东射？东海有长鲸。
不然学仁贵，三矢平虏庭。
不然学仲连，一发下燕城。
胡为射小盗，此用无乃轻。
徒霑一点血，虚汚箭头腥。','',''),('quantangshi-22029','和答诗十首 和古社','白居易','quantangshi','','卷23','废村多年树，生在古社隈。
为作妖狐窟，心空身未摧。
妖狐变美女，社树成楼台。
黄昏行人过，见者心裴回。
饥雕竟不捉，老犬反为媒。
岁媚少年客，十去九不回。
昨夜云雨合，烈风驱迅雷。
风拔树根出，雷劈社坛开。
飞电化为火，妖狐烧作灰。
天明至其所，清旷无氛埃。
旧地葺村落，新田辟荒莱。
始知天降火，不必常为灾。
勿谓神默默，勿谓天恢恢。
勿喜犬不捕，勿夸雕不猜。
寄言狐媚者，天火有时来。','',''),('quantangshi-22030','和答诗十首 和分水岭','白居易','quantangshi','','卷23','高岭峻棱棱，细泉流亹亹。
势分合不得，东西随所委。
悠悠草蔓底，溅溅石罅里。
分流来几年，昼夜两如此。
朝宗远不及，去海三千里。
浸润小无功，山苗长旱死。
萦纡用无所，奔迫流不已。
唯作呜咽声，夜入行人耳。
有源殊不竭，无坎终难止。
同出而异流，君看何所似。
有似骨肉亲，派别从兹始。
又似势利交，波澜相背起。
所以赠君诗，将君何所比。
不比山上泉，比君井中水。','',''),('quantangshi-22031','有木诗八首 一','白居易','quantangshi','','卷23','有木名弱柳，结根近清池。
风烟借颜色，雨露助华滋。
峨峨白雪花，袅袅青丝枝。
渐密阴自庇，转高梢四垂。
截枝扶为杖，輭弱不自持。
折条用樊圃，柔脆非其宜。
为树信可玩，论材何所施。
可惜金堤地，栽之徒尔为。','',''),('quantangshi-22032','有木诗八首 二','白居易','quantangshi','','卷23','有木名樱桃，得地早滋茂。
叶密独承日，花繁偏受露。
迎风暗摇动，引鸟潜来去。
鸟啄子难成，风来枝莫住。
低輭易攀玩，佳人屡回顾。
色求桃李饶，心向松筠妬。
好是映墙花，本非当轩树。
所以姓萧人，曾为伐樱赋。','',''),('quantangshi-22033','有木诗八首 三','白居易','quantangshi','','卷23','有木秋不凋，青青在江北。
谓为洞庭橘，美人自移植。
上受顾盼恩，下勤浇溉力。
实成乃是枳，臭苦不堪食。
物有似是者，真伪何由识。
美人默无言，对之长叹息。
中含害物意，外矫凌霜色。
仍向枝叶间，潜生刺如棘。','',''),('quantangshi-22034','有木诗八首 四','白居易','quantangshi','','卷23','有木名杜棃，阴森覆丘壑。
心蠹已空朽，根深尚盘薄。
狐媚言语巧，鸟妖声音恶。
凭此为巢穴，往来互栖托。
四傍五六本，叶枝相交错。
借问因何生，秋风吹子落。
为长社坛下，无人敢芟斫。
几度野火来，风回烧不着。','',''),('quantangshi-22035','有木诗八首 五','白居易','quantangshi','','卷23','有木香苒苒，山头生一蕟。
主人不知名，移种近轩闼。
爱其有芳味，因以调麴糵。
前后曾饮者，十人无一活。
岂徒悔封植，兼亦误采掇。
试问识药人，始知名野葛。
年深已滋蔓，刀斧不可伐。
何时猛风来，为我连根拔。','',''),('quantangshi-22036','有木诗八首 六','白居易','quantangshi','','卷23','有木名水柽，远望青童童。
根株非劲挺，柯叶多蒙笼。
彩翠色如柏，鳞皴皮似松。
为同松柏类，得列嘉树中。
枝弱不胜雪，势高常惧风。
雪压低还举，风吹西复东。
柔芳甚杨柳，早落先梧桐。
惟有一堪赏，中心无蠹虫。','',''),('quantangshi-22037','有木诗八首 七','白居易','quantangshi','','卷23','有木名凌霄，擢秀非孤标。
偶依一株树，遂抽百尺条。
托根附树身，开花寄树梢。
自谓得其势，无因有动摇。
一旦树摧倒，独立暂飘颻。
疾风从东起，吹折不终朝。
朝为拂云花，暮为委地樵。
寄言立身者，勿学柔弱苗。','',''),('quantangshi-22038','有木诗八首 八','白居易','quantangshi','','卷23','有木名丹桂，四时香馥馥。
花团夜雪明，叶翦春云绿。
风影清似水，霜枝冷如玉。
独占小山幽，不容凡鸟宿。
匠人爱芳直，裁截为厦屋。
干细力未成，用之君自速。
重任虽大过，直心终不曲。
纵非梁栋材，犹胜寻常木。','',''),('quantangshi-22039','叹鲁二首 一','白居易','quantangshi','','卷23','季桓心岂忠，其富过周公。
阳货道岂正，其权执国命。
由来富与权，不系才与贤。
所托得其地，虽愚亦获安。
彘肥因粪壤，鼠稳依社坛。
虫兽尚如是，岂谓无因缘。','',''),('quantangshi-22040','叹鲁二首 二','白居易','quantangshi','','卷23','展禽胡为者，直道竟三黜。
颜子何如人，屡空聊过日。
皆怀王佐道，不践陪臣秩。
自古无奈何，命为时所屈。
有如草木分，天各与其一。
荔枝非名花，牡丹无甘实。','',''),('quantangshi-22041','反鲍明远白头吟','白居易','quantangshi','','卷23','炎炎者烈火，营营者小蝇。
火不热贞玉，蝇不点清冰。
此苟无所受，彼莫能相仍。
乃知物性中，各有能不能。
古称怨恨死，则人有所惩。
惩淫或应可，在道未为弘。
譬如蜩鷃徒，啾啾啅龙鹏。
宜当委之去，寥廓高飞腾。
岂能泥尘下，区区酬怨憎。
胡为坐自苦，吞悲仍抚膺。','',''),('quantangshi-22042','青冢','白居易','quantangshi','','卷23','上有饥鹰号，下有枯蓬走。
茫茫边雪里，一掬沙培塿。
传是昭君墓，埋闭蛾眉久。
凝脂化为泥，铅黛复何有。
唯有阴怨气，时生坟左右。
郁郁如苦雾，不随骨销朽。
妇人无他才，荣枯系妍否。
何乃明妃命，独悬画工手。
丹青一诖误，白黑相纷纠。
遂使君眼中，西施作嫫母。
同侪倾宠幸，异类为配偶。
祸福安可知，美颜不如丑。
何言一时事，可戒千年后。
特报后来姝，不须倚眉首。
无辞插荆钗，嫁作贫家妇。
不见青冢上，行人为浇酒。','',''),('quantangshi-22043','杂感','白居易','quantangshi','','卷23','君子防悔尤，贤人戒行藏。
嫌疑远瓜李，言动慎毫芒。
立教固如此，抚事有非常。
为君持所感，仰面问苍苍。
犬啮桃树根，李树反见伤。
老龟烹不烂，延祸及枯桑。
城门自焚爇，池鱼罹其殃。
阳货肆凶暴，仲尼畏于匡。
鲁酒薄如水，邯郸开战场。
伯禽鞭见血，过失由成王。
都尉身降虏，宫刑加子长。
吕安兄不道，都市杀嵇康。
斯人死已久，其事甚昭彰。
是非不由己，祸患安可防。
使我千载后，涕泗满衣裳。','',''),('quantangshi-22044','新乐府 七德舞 美拨乱，陈王业也','白居易','quantangshi','','卷23','七德舞，七德歌，传自武德至元和。
元和小臣白居易，观舞听歌知乐意。
乐终稽首陈其事，太宗十八举义兵。
白旄黄钺定两京，擒充戮窦四海清。
二十有四功业成，二十有九即帝位。
三十有五致太平，功成理定何神速。
速在推心置人腹，亡卒遗骸散帛收。
饥人卖子分金赎，魏征梦见子夜泣。
张谨哀闻辰日哭，怨女三千放出宫。
死囚四百来归狱，翦须烧药赐功臣。
李绩呜咽思杀身含血吮创抚战士，思摩奋呼乞効死。
则知不独善战善乘时，以心感人人心归。
尔来一百九十载，天下至今歌舞之。
歌七德，舞七德，圣人有作垂无极。
岂徒耀神武，岂徒夸圣文。
太宗意在陈王业，王业艰难示子孙。','',''),('quantangshi-22045','新乐府 法曲 美列圣，正华声也','白居易','quantangshi','','卷23','法曲法曲歌大定，积德重熙有余庆。
永徽之人舞而咏，法曲法曲舞霓裳。
政和世理音洋洋，开元之人乐且康。
法曲法曲歌堂堂，堂堂之庆垂无疆。
中宗肃宗复鸿业，唐祚中兴万万叶。
法曲法曲合夷歌，夷声邪乱华声和。
以乱干和天宝末，明年胡尘犯宫阙。
乃知法曲本华风，苟能审音与政通。
一从胡曲相参错，不辨兴衰与哀乐。
愿求牙旷正华音，不令夷夏相交侵。','',''),('quantangshi-22046','新乐府 二王后 明祖宗之意也','白居易','quantangshi','','卷23','二王后，彼何人，介公酅公为国宾。
周武隋文之子孙，古人有言天下者，非是一人之天下。
周亡天下传于隋，隋人失之唐得之。
唐兴十叶岁二百，介公酅公世为客。
明堂太庙朝享时，引居宾位备威仪。
备威仪，助郊祭，高祖太宗之遗制。
不独兴灭国，不独继绝世。
欲令嗣位守文君，亡国之孙取为戒。','',''),('quantangshi-22047','新乐府 海漫漫 戒求仙也','白居易','quantangshi','','卷23','海漫漫，直下无底傍无边。
云涛烟浪最深处，人传中有三神山。
山上多生不死药，服之羽化为天仙。
秦皇汉武信此语，方士年年采药去。
蓬莱今古但闻名，烟水茫茫无觅处。
海漫漫，风浩浩，眼穿不见蓬莱岛。
不见蓬莱不敢归，童男丱女舟中老。
徐福文成多诳诞，上元太一虚祈祷。
君看骊山顶上茂陵头，毕竟悲风吹蔓草。
何况玄元圣祖五千言，不言药，不言仙，不言白日升青天。','',''),('quantangshi-22048','新乐府 立部伎 刺雅乐之替也','白居易','quantangshi','','卷23','立部伎，鼓笛喧，舞双劒，跳七丸，袅巨索，掉长竿。
太常部伎有等级，堂上者坐堂下立。
堂上坐部笙歌清，堂下立部鼓笛鸣。
笙歌一声众侧耳，鼓笛万曲无人听。
立部贱，坐部贵，坐部退为立部伎。
击鼓吹笙和杂戏，立部又退何所任。
始就乐悬操雅音，雅音替坏一至此。
长令尔辈调宫征，圆丘后土郊祀时。
言将此乐感神只，欲望凤来百兽舞。
何异北辕将适楚，工师愚贱安足云。','',''),('quantangshi-22049','新乐府 华原磬 刺乐工非其人也','白居易','quantangshi','','卷23','华原磬，华原磬，古人不听今人听。
泗滨石，泗滨石，今人不击古人击。
今人古人何不同？用之舍之由乐工。
乐工虽在耳如壁，不分清浊即为聋。
棃园弟子调律吕，知有新声不如古。
古称浮磬出泗滨，立辨致死声感人。
宫悬一听华原石，君心遂忘封疆臣。
果然胡寇从燕起，武臣少肯封疆死。
始知乐与时政通，岂听铿锵而已矣。
磬襄入海去不归，长安市儿为乐师。
华原磬与泗滨石，清浊两声谁得知。','',''),('quantangshi-22050','新乐府 上阳白发人 愍怨旷也','白居易','quantangshi','','卷23','上阳人，红颜暗老白发新。
绿衣监使守宫门，一闭上阳多少春。
玄宗末岁初选入，入时十六今六十。
同时采择百余人，零落年深残此身。
忆昔吞悲别亲族，扶入车中不教哭。
皆云入内便承恩，脸似芙蓉胸似玉。
未容君王得见面，已被杨妃遥侧目。
妬令潜配上阳宫，一生遂向空房宿。
宿空房，秋夜长，夜长无寐天不明。
耿耿残灯背壁影，萧萧暗雨打窗声。
春日迟，日迟独坐天难暮。
宫莺百啭愁厌闻，梁燕双栖老休妬。
莺归燕去长悄然，春往秋来不记年。
唯向深宫望明月，东西四五百回圆。
今日宫中年最老，大家遥赐尚书号。
小头鞋履窄衣裳，青黛点眉眉细长。
外人不见见应笑，天宝末年时世妆。
上阳人，苦最多，少亦苦，老亦苦，少苦老苦两如何？
君不见昔时吕向美人赋，又不见今日上阳白发歌。','',''),('quantangshi-22051','新乐府 胡旋女 戒近习也','白居易','quantangshi','','卷23','胡旋女，胡旋女，心应弦，手应鼓。
弦鼓一声双袖举，回雪飘颻转蓬舞。
左旋右转不知疲，千匝万周无已时。
人间物类无可比，奔车轮缓旋风迟。
曲终再拜谢天子，天子为之微启齿。
胡旋女，出康居，徒劳东来万里余。
中原自有胡旋者，鬬妙争能尔不如。
天宝季年时欲变，臣妾人人学圜转。
中有太真外禄山，二人最道能胡旋。
棃花园中册作妃，金鸡障下养为儿。
禄山胡旋迷君眼，兵过黄河疑未反。
贵妃胡旋惑君心，死弃马嵬念更深。
从兹地轴天维转，五十年来制不禁。
胡旋女，莫空舞，数唱此歌悟明主。','',''),('quantangshi-22052','新乐府 新丰折臂翁 戒边功也','白居易','quantangshi','','卷23','新丰老翁八十八，头鬓眉须皆似雪。
玄孙扶向店前行，左臂凭肩右臂折。
问翁臂折来几年，兼问致折何因缘。
翁云贯属新丰县，生逢圣代无征战。
惯听棃园歌管声，不识旗枪与弓箭。
无何天宝大征兵，户有三丁点一丁。
点得驱将何处去，五月万里云南行。
闻道云南有泸水，椒花落时瘴烟起。
大军徒涉水如汤，未过十人二三死。
村南村北哭声哀，儿别爷娘夫别妻。
皆云前后征蛮者，千万人行无一回。
是时翁年二十四，兵部牒中有名字。
夜深不敢使人知，偷将大石捶折臂。
张弓簸旗俱不堪，从兹始免征云南。
骨碎筋伤非不苦，且图拣退归乡土。
此臂折来六十年，一肢虽废一身全。
至今风雨阴寒夜，直到天明痛不眠。
痛不眠，终不悔，且喜老身今独在。
不然当时泸水头，身死魂孤骨不收。
应作云南望乡鬼，万人冢上哭呦呦。
老人言，君听取。
君不闻开元宰相宋开府，不赏边功防黩武。
又不闻天宝宰相杨国忠，欲求恩幸立边功。
边功未立生人怨，请问新丰折臂翁。','',''),('quantangshi-22053','新乐府 太行路 借夫妇以讽君臣之不终也','白居易','quantangshi','','卷23','太行之路能摧车，若比人心是坦途。
巫峡之水能覆舟，若比人心是安流。
人心好恶苦不常，好生毛羽恶生疮。
与君结发未五载，岂期牛女为参商。
古称色衰相弃背，当时美人犹怨悔。
何况如今鸾镜中，妾颜未改君心改。
为君熏衣裳，君闻兰麝不馨香。
为君盛容饰，君看金翠无颜色。
行路难，难重陈。
人生莫作妇人身，百年苦乐由他人。
行路难，难于山，险于水。
不独人间夫与妻，近代君臣亦如此。
君不见左纳言，右纳史，朝承恩，暮赐死。
行路难，不在水，不在山，只在人情反覆间。','',''),('quantangshi-22054','新乐府 司天台 引古以儆今也','白居易','quantangshi','','卷23','司天台，仰观俯察天人际。
羲和死来职事废，官不求贤空取艺。
昔闻西汉元成间，上陵下替谪见天。
北辰微暗少光色，四星煌煌如火赤。
耀芒动角射三台，上台半灭中台坼。
是时非无太史官，眼见心知不敢言。
明朝趋入明光殿，唯奏庆云寿星见。
天文时变两如斯，九重天子不得知。
不得知，安用台高百尺为。','',''),('quantangshi-22055','新乐府 捕蝗 刺长吏也','白居易','quantangshi','','卷23','捕蝗捕蝗谁家子，天热日长饥欲死。
兴元兵后伤阴阳，和气蛊蠹化为蝗。
始自两河及三辅，荐食如蚕飞似雨。
雨飞蚕食千里间，不见青苗空赤土。
河南长吏言忧农，课人昼夜捕蝗虫。
是时粟斗钱三百，蝗虫之价与粟同。
捕蝗捕蝗竟何利，徒使饥人重劳费。
一虫虽死百虫来，岂将人力定天灾。
我闻古之良吏有善政，以政驱蝗蝗出境。
又闻贞观之初道欲昌，文皇仰天吞一蝗。
一人有庆兆民赖，是岁虽蝗不为害。','',''),('quantangshi-22056','新乐府 昆明春 思王泽之广被也','白居易','quantangshi','','卷23','昆明春，昆明春，春池岸古春流新。
影浸南山青滉漾，波沈西日红奫沦。
往年因旱池枯竭，龟尾曳涂鱼喣沫。
诏开八水注恩波，千介万鳞同日活。
今来净绿水照天，游鱼鱍鱍莲田田。
洲香杜若抽心短，沙暖鸳鸯铺翅眠。
动植飞沈皆遂性，皇泽如春无不被。
渔者仍丰网罟资，贫人久获菰蒲利。
诏以昆明近帝城，官家不得收其征。
菰蒲无租鱼无税，近水之人感君惠。
感君惠，独何人。
吾闻率土皆王民，远民何疎近何亲。
愿推此惠及天下，无远无近同欣欣。
吴兴山中罢榷茗，鄱阳坑里休封银。
天涯地角无禁利，熙熙同似昆明春。','',''),('quantangshi-22057','新乐府 城盐州 美圣谟而诮边将也','白居易','quantangshi','','卷23','城盐州，城盐州，城在五原原上头。
蕃东节度钵阐布，忽见新城当要路。
金鸟飞传赞普闻，建牙传箭集羣臣。
君臣赬面有忧色，皆言勿谓唐无人。
自筑盐州十余载，左衽毡裘不犯塞。
昼牧牛羊夜捉生，长去新城百里外。
诸边急警劳戍人，唯此一道无烟尘。
灵夏潜安谁复辨，秦原暗通何处见。
鄜州驿路好马来，长安药肆黄蓍贱。
城盐州，盐州未城天子忧。
德宗按图自定计，非关将略与庙谋。
吾闻高宗中宗世，北虏猖狂最难制。
韩公创筑受降城，三城鼎峙屯汉兵。
东西亘绝数千里，耳冷不闻胡马声。
如今边将非无策，心笑韩公筑城壁。
相看养寇为身谋，各握强兵固恩泽。
愿分今日边将恩，褒赠韩公封子孙。
谁能将此盐州曲，飜作歌词闻至尊。','',''),('quantangshi-22058','新乐府 道州民 美臣遇明主也','白居易','quantangshi','','卷23','道州民，多侏儒，长者不过三尺余。
市作矮奴年进送，号为道州任土贡。
任土贡，宁若斯。
不闻使人生别离，老翁哭孙母哭儿。
一自阳城来守郡，不进矮奴频诏问。
城云臣按六典书，任土贡有不贡无。
道州水土所生者，只有矮民无矮奴。
吾君感悟玺书下，岁贡矮奴宜悉罢。
道州民，老者幼者何欣欣。
父兄子弟始相保，从此得作良人身。
道州民，民到于今受其赐，欲说使君先下泪。
仍恐儿孙忘使君，生男多以阳为字。','',''),('quantangshi-22059','新乐府 驯犀 感为政之难终也','白居易','quantangshi','','卷23','驯犀驯犀通天犀，躯貌骇人角骇鸡。
海蛮闻有明天子，驱犀乘传来万里。
一朝得谒大明宫，欢呼拜舞自论功。
五年驯养始堪献，六译语言方得通。
上嘉人兽俱来远，蛮馆四方犀入苑。
秣以瑶刍鏁以金，故乡迢遰君门深。
海鸟不知钟鼓乐，池鱼空结江湖心。
驯犀生处南方热，秋无白露冬无雪。
一入上林三四年，又逢今岁苦寒月。
饮冰卧霰苦蜷局，角骨冻伤鳞甲蹜。
驯犀死，蛮儿啼，向阙再拜颜色低。
奏乞生归本国去，恐身冻死似驯犀。
君不见建中初，驯象生还放林邑。
君不见贞元年末，驯犀冻死蛮儿泣。
所嗟建中异贞元，象生犀死何足言。','',''),('quantangshi-22060','新乐府 五弦弹 恶郑之夺雅也','白居易','quantangshi','','卷23','五弦弹，五弦弹，听者倾耳心寥寥。
赵璧知君入骨爱，五弦一一为君调。
第一第二弦索索，秋风拂松疎韵落。
第三第四弦泠泠，夜鹤忆子笼中鸣。
第五弦声最掩抑，陇水冻咽流不得。
五弦竝奏君试听，凄凄切切复铮铮。
铁击珊瑚一两曲，冰泻玉盘千万声。
铁声杀，冰声寒。
杀声入耳肤血憯，寒气中人肌骨酸。
曲终声尽欲半日，四坐相对愁无言。
座中有一远方士，唧唧咨咨声不已。
自叹今朝初得闻，始知孤负平生耳。
唯忧赵璧白发生，老死人间无此声。
远方士，尔听五弦信为美，吾闻正始之音不如是。
正始之音其若何，朱弦疏越清庙歌。
一弹一唱再三叹，曲澹节稀声不多。
融融曳曳召元气，听之不觉心平和。
人情重今多贱古，古琴有弦人不抚。
更从赵璧艺成来，二十五弦不如五。','',''),('quantangshi-22061','新乐府 蛮子朝 刺将骄而相备位也','白居易','quantangshi','','卷23','蛮子朝，泛皮船兮渡绳桥，来自巂州道路遥。
入界先经蜀川过，蜀将收功先表贺。
臣闻云南六诏蛮，东连牂牁西连蕃。
六诏星居初琐碎，合为一诏渐强大。
开元皇帝虽圣神，唯蛮倔强不来宾。
鲜于仲通六万卒，征蛮一阵全军没。
至今西洱河岸边，箭孔刀痕满枯骨。
谁知今日慕华风，不劳一人蛮自通。
诚由陛下休明德，亦赖微臣诱谕功。
德宗省表知如此，笑令中使迎蛮子。
蛮子导从者谁何，摩挲俗羽双隈伽。
清平官持赤藤杖，大将军系金呿喈。
异牟寻男寻合劝，特敕召对延英殿。
上心贵在怀远蛮，引临玉座近天颜。
冕旒不垂亲劳倈，赐衣赐食移时对。
移时对，不可得，大臣相看有羡色。
可怜宰相拖紫佩金章，朝日唯闻对一刻。','',''),('quantangshi-22062','新乐府 骠国乐 欲王化之先迩后远也','白居易','quantangshi','','卷23','骠国乐，骠国乐，出自大海西南角。
雍羌之子舒难陀，来献南音奉正朔。
德宗立仗御紫庭，黈纩不塞为尔听。
玉螺一吹椎髻耸，铜鼓一击文身踊。
珠缨炫转星宿摇，花鬘斗薮龙蛇动。
曲终王子启圣人，臣父愿为唐外臣。
左右欢呼何翕习，至尊德广之所及。
须臾百辟诣合门，俯伏拜表贺至尊。
伏见骠人献新乐，请书国史传子孙。
时有击壤老农父，暗测君心闲独语。
闻君政化甚圣明，欲感人心致太平。
感人在近不在远，太平由实非由声。
观身理国国可济，君如心兮民如体。
体生疾苦心憯凄，民得和平君恺悌。
贞元之民若未安，骠乐虽闻君不欢。
贞元之民苟无病，骠乐不来君亦圣。
骠乐骠乐徒喧喧，不如闻此刍荛言。','',''),('quantangshi-22063','新乐府 缚戎人 达穷民之情也','白居易','quantangshi','','卷23','缚戎人，缚戎人，耳穿面破驱入秦。
天子矜怜不忍杀，诏徙东南吴与越。
黄衣小使录姓名，领出长安乘递行。
身被金创面多瘠，扶病徒行日一驿。
朝餐饥渴费杯盘，夜卧腥臊汚牀席。
忽逢江水忆交河，垂手齐声呜咽歌。
其中一虏语诸虏，尔苦非多我苦多。
同伴行人因借问，欲说喉中气愤愤。
自云乡管本凉原，大历年中没落蕃。
一落蕃中四十载，遣着皮裘系毛带。
唯许正朝服汉仪，敛衣整巾潜泪垂。
誓心密定归乡计，不使蕃中妻子知。
暗思幸有残筋力，更恐年衰归不得。
蕃候严兵鸟不飞，脱身冒死奔逃归。
昼伏宵行经大漠，云阴月黑风沙恶。
惊藏青冢寒草疎，偷渡黄河夜冰薄。
忽闻汉军鼙鼓声，路傍走出再拜迎。
游骑不听能汉语，将军遂缚作蕃生。
配向东南卑湿地，定无存恤空防备。
念此吞声仰诉天，若为辛苦度残年。
凉原乡井不得见，胡地妻儿虚弃捐。
没蕃被囚思汉土，归汉被劫为蕃虏。
早知如此悔归来，两地宁如一处苦。
缚戎人，戎人之中我苦辛。
自古此冤应未有，汉心汉语吐蕃身。','',''),('quantangshi-22064','新乐府 骊宫高 美天子重惜人之财力也','白居易','quantangshi','','卷23','高高骊山上有宫，朱楼紫殿三四重。
迟迟兮春日，玉甃暖兮温泉溢。
袅袅兮秋风，山蝉鸣兮宫树红。
翠华不来岁月久，墙有衣兮瓦有松。
吾君在位已五载，何不一幸乎其中？
西去都门几多地，吾君不游有深意。
一人出兮不容易，六宫从兮百司备。
八十一车千万骑，朝有宴饫暮有赐。
中人之产数百家，未足充君一日费。
吾君修己人不知，不自逸兮不自嬉。
吾君爱人人不识，不伤财兮不伤力。
骊宫高兮高入云，君之来兮为一身，君之不来兮为万人。','',''),('quantangshi-22065','新乐府 百炼镜 辨皇王鉴也','白居易','quantangshi','','卷23','百炼镜，镕范非常规，日辰处所灵且只。
江心波上舟中铸，五月五日日午时。
琼粉金膏磨莹已，化为一片秋潭水。
镜成将献蓬莱宫，扬州长吏手自封。
人间臣妾不合照，背有九五飞天龙。
人人呼为天子镜，我有一言闻太宗。
太宗常以人为镜，鉴古鉴今不鉴容。
四海安危居掌内，百王治乱悬心中。
乃知天子别有镜，不是扬州百炼铜。','',''),('quantangshi-22066','新乐府 青石 激忠烈也','白居易','quantangshi','','卷23','青石出自蓝田山，兼车运载来长安。
工人磨琢欲何用，石不能言我代言。
不愿作人家墓前神道碣，坟土未干名已灭。
不愿作官家道旁德政碑，不镌实录镌虚辞。
愿为颜氏段氏碑，雕镂太尉与太师。
刻此两片坚贞质，状彼二人忠烈姿。
义心如石屹不转，死节如石确不移。
如观奋击朱泚日，似见叱诃希烈时。
各于其上题名諡，一置高山一沈水。
陵谷虽迁碑独存，骨化为尘名不死。
长使不忠不烈臣，观碑改节慕为人。
慕为人，劝事君。','',''),('quantangshi-22067','新乐府 两朱阁 刺佛寺寖多也','白居易','quantangshi','','卷23','两朱阁，南北相对起。
借问何人家，贞元双帝子。
帝子吹箫双得仙，五云飘颻飞上天。
第宅亭台不将去，化为佛寺在人间。
妆合伎楼何寂静，柳似舞腰池似镜。
花落黄昏悄悄时，不闻歌吹闻钟磬。
寺门敕牓金字书，尼院佛庭宽有余。
青苔明月多闲地，比屋疲人无处居。
忆昨平阳宅初置，吞并平人几家地。
仙去双双作梵宫，渐恐人间尽为寺。','',''),('quantangshi-22068','新乐府 西凉伎 刺封疆之臣也','白居易','quantangshi','','卷23','西凉伎，假面胡人假狮子。
刻木为头丝作尾，金镀眼睛银帖齿。
奋迅毛衣摆双耳，如从流沙来万里。
紫髯深目两胡儿，鼓舞跳梁前致辞。
应似凉州未陷日，安西都护进来时。
须臾云得新消息，安西路绝归不得。
泣向狮子涕双垂，凉州陷没知不知。
狮子回头向西望，哀吼一声观者悲。
贞元边将爱此曲，醉坐笑看看不足。
娱宾犒士宴监军，狮子胡儿长在目。
有一征夫年七十，见弄凉州低面泣。
泣罢敛手白将军，主忧臣辱昔所闻。
自从天宝兵戈起，犬戎日夜吞西鄙。
凉州陷来四十年，河陇侵将七千里。
平时安西万里疆，今日边防在凤翔。
缘边空屯十万卒，饱食温衣闲过日。
遗民肠断在凉州，将卒相看无意收。
天子每思长痛惜，将军欲说合慙羞。
奈何仍看西凉伎，取笑资欢无所愧。
纵无智力未能收，忍取西凉弄为戏。','',''),('quantangshi-22069','新乐府 八骏图 戒奇物惩佚游也','白居易','quantangshi','','卷23','穆王八骏天马驹，后人爱之写为图。
背如龙兮颈如象，骨耸筋高脂肉壮。
日行万里疾如飞，穆王独乘何所之。
四荒八极蹋欲徧，三十二蹄无歇时。
属车轴折趁不及，黄屋草生弃若遗。
瑶池西赴王母宴，七庙经年不亲荐。
璧台南与盛姬游，明堂不复朝诸侯。
白云黄竹歌声动，一人荒乐万人愁。
周从后稷至文武，积德累功世勤苦。
岂知才及四代孙，心轻王业如灰土。
由来尤物不在大，能荡君心则为害。
文帝却之不肯乘，千里马去汉道兴。
穆王得之不为戒，八骏驹来周室坏。
至今此物尚称珍，不知房星之精下为怪。
八骏图，君莫爱。','',''),('quantangshi-22070','新乐府 涧底松 念寒儁也','白居易','quantangshi','','卷23','有松百尺大十围，生在涧底寒且卑。
涧深山险人路绝，老死不逢工度之。
天子明堂欠梁木，此求彼有两不知。
谁喻苍苍造物意，但与之材不与地。
金张世禄原宪贫，牛衣寒贱貂蝉贵。
貂蝉与牛衣，高下虽有殊。
高者未必贤，下者未必愚。
君不见沈沈海底生珊瑚，历历天上种白榆。','',''),('quantangshi-22071','新乐府 牡丹芳 美天子忧农也','白居易','quantangshi','','卷23','牡丹芳，牡丹芳，黄金蘂绽红玉房。
千片赤英霞烂烂，百枝绛点灯煌煌。
照地初开锦绣段，当风不结兰麝囊。
仙人琪树白无色，王母桃花小不香。
宿露轻盈泛紫艳，朝阳照耀生红光。
红紫二色间深浅，向背万态随低昂。
映叶多情隐羞面，卧丛无力含醉妆。
低娇笑容疑掩口，凝思怨人如断肠。
穠姿贵彩信奇绝，杂卉乱花无比方。
石竹金钱何细碎，芙蓉芍药苦寻常。
遂使王公与乡士，游花冠盖日相望。
庳车輭轝贵公主，香衫细马豪家郎。
卫公宅静闭东院，西明寺深开北廊。
戏蝶双舞看人久，残莺一声春日长。
共愁日照芳难驻，仍张帷幕垂阴凉。
花开花落二十日，一城之人皆若狂。
三代以还文胜质，人心重华不重实。
重华直至牡丹芳，其来有渐非今日。
元和天子忧农桑，恤下动天天降祥。
去岁嘉禾生九穗，田中寂莫无人至。
今年瑞麦分两岐，君心独喜无人知。
无人知，可叹息，我愿暂求造化力。
减却牡丹妖艳色，少回乡士爱花心，同似吾君忧稼穑。','',''),('quantangshi-22072','新乐府 红线毯 忧蚕桑之费也','白居易','quantangshi','','卷23','红线毯，择蠒缲丝清水煮。
拣丝练线红蓝染，染为红线红于蓝。
织作披香殿上毯，披香殿广十丈余。
红线织成可殿铺，彩丝茸茸香拂拂。
线輭花虚不胜物，美人蹋上歌舞来。
罗韤绣鞋随步没，太原毯涩毳缕硬。
蜀都褥薄锦花冷，不如此毯温且柔。
年年十月来宣州，宣城太守加样织。
自谓为臣能竭力，百夫同担进宫中。
线厚丝多卷不得，宣城太守知不知。
一丈毯，千两丝，地不知寒人要暖，少夺人衣作地衣。','',''),('quantangshi-22073','新乐府 杜陵叟 伤农夫之困也','白居易','quantangshi','','卷23','杜陵叟，杜陵居，岁种薄田一顷余。
三月无雨旱风起，麦苗不秀多黄死。
九月降霜秋早寒，禾穗未熟皆青干。
长吏明知不申破，急敛暴征求考课。
典桑卖地纳官租，明年衣食将何如。
剥我身上帛，夺我口中粟。
虐人害物即豺狼，何必钩爪锯牙食人肉。
不知何人奏皇帝，帝心恻隐知人弊。
白麻纸上书德音，京畿尽放今年税。
昨日里胥方到门，手持尺牒牓乡村。
十家租税九家毕，虚受吾君蠲免恩。','',''),('quantangshi-22074','新乐府 缭绫 念女工之劳也','白居易','quantangshi','','卷23','缭绫缭绫何所似，不似罗绡与纨绮。
应似天台山上月明前，四十五尺瀑布泉。
中有文章又奇绝，地铺白烟花簇雪。
织者何人衣者谁，越溪寒女汉宫姬。
去年中使宣口敕，天上取样人间织。
织为云外秋雁行，染作江南春水色。
广裁衫袖长制帬，金斗熨波刀翦纹。
异彩奇文相隐映，转侧看花花不定。
昭阳舞人恩正深，春衣一对直千金。
汗霑粉污不再着，曳土蹋泥无惜心。
缭绫织成费功绩，莫比寻常缯与帛。
丝细缲多女手疼，扎扎千声不盈尺。
昭阳殿里歌舞人，若见织时应也惜。','',''),('quantangshi-22075','新乐府 卖炭翁 苦官市也','白居易','quantangshi','','卷23','卖炭翁，伐薪烧炭南山中。
满面尘灰烟火色，两鬓苍苍十指黑。
卖炭得钱何所营，身上衣裳口中食。
可怜身上衣正单，心忧炭贱愿天寒。
夜来城上一尺雪，晓驾炭车辗冰辙。
牛困人饥日已高，市南门外泥中歇。
翩翩两骑来是谁，黄衣使者白衫儿。
手把文书口称敕，回车叱牛牵向北。
一车炭，千余斤，官使驱将惜不得。
半匹红纱一丈绫，系向牛头充炭直。','',''),('quantangshi-22076','新乐府 母别子 刺新间旧也','白居易','quantangshi','','卷23','母别子，子别母，白日无光哭声苦。
关西骠骑大将军，去年破虏新策勋。
敕赐金钱二百万，洛阳迎得如花人。
新人迎来旧人弃，掌上莲花眼中刺。
迎新弃旧未足悲，悲在君家留两儿。
一始扶行一初坐，坐啼行哭牵人衣。
以汝夫妇新燕婉，使我母子生别离。
不如林中乌与鹊，母不失雏雄伴雌。
应似园中桃李树，花落随风子在枝。
新人新人听我语，洛阳无限红楼女。
但愿将军重立功，更有新人胜于汝。','',''),('quantangshi-22077','新乐府 阴山道 疾贪虏也','白居易','quantangshi','','卷23','阴山道，阴山道，纥逻敦肥水泉好。
每至戎人送马时，道旁千里无纤草。
草尽泉枯马病羸，飞龙但印骨与皮。
五十匹缣易一匹，缣去马来无了日。
养无所用去非宜，每岁死伤十六七。
缣丝不足女工苦，疎织短截充匹数。
藕丝蛛网三丈余，回纥诉称无用处。
咸安公主号可敦，远为可汗频奏论。
元和二年下新敕，内出金帛酬马直。
仍诏江淮马价缣，从此不令疎短织。
合罗将军呼万岁，捧授金银与缣彩。
谁知黠虏启贪心，明年马多来一倍。
缣渐好，马渐多，阴山虏，奈尔何。','',''),('quantangshi-22078','新乐府 时世妆 儆戎也','白居易','quantangshi','','卷23','时世妆，时世妆，出自城中传四方。
时世流行无远近，顋不施朱面无粉。
乌膏注唇唇似泥，双眉画作八字低。
妍媸黑白失本态，妆成尽似含悲啼。
圆鬟无鬓堆髻样，斜红不晕赭面状。
昔闻被发伊川中，辛有见之知有戎。
元和妆梳君记取，髻堆面赭非华风。','',''),('quantangshi-22079','新乐府 李夫人 鉴嬖惑也','白居易','quantangshi','','卷23','汉武帝，初丧李夫人。
夫人病时不肯别，死后留得生前恩。
君恩不尽念未已，甘泉殿里令写真。
丹青画出竟何益，不言不笑愁杀人。
又令方士合灵药，玉釜煎炼金炉焚。
九华帐深夜悄悄，反魂香降夫人魂。
夫人之魂在何许，香烟引到焚香处。
既来何苦不须臾，缥缈悠扬还灭去。
去何速兮来何迟，是耶非耶两不知。
翠蛾仿髴平生貌，不似昭阳寝疾时。
魂之不来君心苦，魂之来兮君亦悲。
背灯隔帐不得语，安用暂来还见违。
伤心不独汉武帝，自古及今皆若斯。
君不见穆王三日哭，重璧台前伤盛姬。
又不见泰陵一掬泪，马嵬坡下念杨妃。
纵令妍姿艳质化为土，此恨长在无销期。
生亦惑，死亦惑，尤物惑人忘不得。
人非木石皆有情，不如不遇倾城色。','',''),('quantangshi-22080','新乐府 陵园妾 怜幽闭也','白居易','quantangshi','','卷23','陵园妾，颜色如花命如叶。
命如叶薄将奈何，一奉寝宫年月多。
年月多，时光换，春愁秋思知何限。
青丝发落丛鬓疎，红玉肤销系帬慢。
忆昔宫中被妬猜，因谗得罪配陵来。
老母啼呼趁车别，中官监送鏁门回。
山宫一闭无开日，未死此身不令出。
松门到晓月裴回，柏城尽日风萧瑟。
松门柏城幽闭深，闻蝉听燕感光阴。
眼看菊蘂重阳泪，手把棃花寒食心。
把花掩泪无人见，绿芜墙绕青苔院。
四季徒支妆粉钱，三朝不识君王面。
遥想六宫奉至尊，宣徽雪夜浴堂春。
雨露之恩不及者，犹闻不啻三千人。
三千人，我尔君恩何厚薄。
愿令轮转直陵园，三岁一来均苦乐。','',''),('quantangshi-22081','新乐府 盐商妇 恶幸人也','白居易','quantangshi','','卷23','盐商妇，多金帛，不事田农与蚕绩。
南北东西不失家，风水为乡船作宅。
本是扬州小家女，嫁得西江大商客。
绿鬟富去金钗多，皓腕肥来银钏窄。
前呼苍头后叱婢，问尔因何得如此。
壻作盐商十五年，不属州县属天子。
每年盐利入官时，少入官家多入私。
官家利薄私家厚，盐铁尚书远不知。
何况江头鱼米贱，红脍黄橙香稻饭。
饱食浓妆倚柁楼，两朵红顋花欲绽。
盐商妇，有幸嫁盐商。
终朝美饭食，终岁好衣裳。
好衣美食来何处，亦须慙愧桑弘羊。
桑弘羊，死已久，不独汉时今亦有。','',''),('quantangshi-22082','新乐府 杏为梁 刺居处僭也','白居易','quantangshi','','卷23','杏为梁，桂为柱，何人堂室李开府。
碧砌红轩色未干，去年身殁今移主。
高其墙，大其门，谁家第宅卢将军。
素泥朱版光未灭，今日官收别赐人。
开府之堂将军宅，造未成时头已白。
逆旅重居逆旅中，心是主人身是客。
更有愚夫念身后，心虽甚长计非久。
穷奢极丽越规模，付子传孙令保守。
莫教门外过客闻，抚掌回头笑杀君。
君不见马家宅，尚犹存，宅门题作奉诚园。
君不见魏家宅，属他人，诏赎赐还五代孙。
俭存奢失今在目，安用高墙围大屋。','',''),('quantangshi-22083','新乐府 井底引银瓶 止淫奔也','白居易','quantangshi','','卷23','井底引银瓶，银瓶欲上丝绳绝。
石上磨玉簪，玉簪欲成中央折。
瓶沈簪折知奈何，似妾今朝与君别。
忆昔在家为女时，人言举动有殊姿。
婵娟两鬓秋蝉翼，宛转双蛾远山色。
笑随戏伴后园中，此时与君未相识。
妾弄青梅凭短墙，君骑白马傍垂杨。
墙头马上遥相顾，一见知君即断肠。
知君断肠共君语，君指南山松柏树。
感君松柏化为心，暗合双鬟逐君去。
到君家舍五六年，君家大人频有言。
聘则为妻奔是妾，不堪主祀奉苹蘩。
终知君家不可住，其奈出门无去处。
岂无父母在高堂，亦有亲情满故乡。
潜来更不通消息，今日悲羞归不得。
为君一日恩，误妾百年身。
寄言痴小人家女，慎勿将身轻许人。','',''),('quantangshi-22084','新乐府 官牛 讽执政也','白居易','quantangshi','','卷23','官牛官牛驾官车，浐水岸边般载沙。
一石沙，几斤重，朝载暮载将何用。
载向五门官道西，绿槐阴下铺沙堤。
昨来新拜右丞相，恐怕泥涂汚马蹄。
右丞相，马蹄蹋沙虽净洁，牛领牵车欲流血。
右丞相，但能济人治国调阴阳，官牛领穿亦无妨。','',''),('quantangshi-22085','新乐府 紫毫笔 讥失职也','白居易','quantangshi','','卷23','紫毫笔，尖如锥兮利如刀。
江南石上有老兔，吃竹饮泉生紫毫。
宣城之人采为笔，千万毛中拣一毫。
毫虽轻，功甚重，管勒工名充岁贡。
君兮臣兮勿轻用，勿轻用，将何如。
愿赐东西府御史，愿颁左右台起居。
搦管趋入黄金阙，抽毫立在白玉除。
臣有奸邪正衙奏，君有动言直笔书。
起居郎，侍御史，尔知紫毫不易致。
每岁宣城进笔时，紫毫之价如金贵。
慎勿空将弹失仪，慎勿空将录制词。','',''),('quantangshi-22086','新乐府 隋堤柳 悯亡国也','白居易','quantangshi','','卷23','隋堤柳，岁久年深尽衰朽。
风飘飘兮雨萧萧，三株两株汴河口。
老枝病叶愁杀人，曾经大业年中春。
大业年中炀天子，种柳成行夹流水。
西自黄河东至淮，绿阴一千三百里。
大业末年春暮月，柳色如烟絮如雪。
南幸江都恣佚游，应将此柳系龙舟。
紫髯郎将护锦缆，青娥御史直迷楼。
海内财力此时竭，舟中歌笑何日休。
上荒下困势不久，宗社之危如缀旒。
炀天子，自言福祚长无穷，岂知皇子封酅公。
龙舟未过彭城合，义旗已入长安宫。
萧墙祸生人事变，晏驾不得归秦中。
土坟数尺何处葬，吴公台下多悲风。
二百年来汴河路，沙草和烟朝复暮。
后王何以鉴前王，请看隋堤亡国树。','',''),('quantangshi-22087','新乐府 草茫茫 惩厚葬也','白居易','quantangshi','','卷23','草茫茫，土苍苍，苍苍茫茫在何处，骊山脚下秦皇墓。
墓中下涸二重泉，当时自以为深固。
下流水银象江海，上缀珠光作乌兔。
别为天地于其间，拟将富贵随身去。
一朝盗掘坟陵破，龙椁神堂三月火。
可怜宝玉归人间，暂借泉中买身祸。
奢者狼藉俭者安，一凶一吉在眼前。
凭君回首向南望，汉文葬在霸陵原。','',''),('quantangshi-22088','新乐府 古冢狐 戒艳色也','白居易','quantangshi','','卷23','古冢狐，妖且老，化为妇人颜色好。
头变云鬟面变妆，大尾曳作长红裳。
徐徐行傍荒村路，日欲暮时人静处。
或歌或舞或悲啼，翠眉不举花颜低。
忽然一笑千万态，见者十人八九迷。
假色迷人犹若是，真色迷人应过此。
彼真此假俱迷人，人心恶假贵重真。
狐假女妖害犹浅，一朝一夕迷人眼。
女为狐媚害即深，日长月增溺人心。
何况褒妲之色善蛊惑，能丧人家覆人国。
君看为害浅深间，岂将假色同真色。','',''),('quantangshi-22089','新乐府 黑潭龙 疾贪吏也','白居易','quantangshi','','卷23','黑潭水深黑如墨，传有神龙人不识。
潭上架屋官立祠，龙不能神人神之。
丰凶水旱与疾疫，乡里皆言龙所为。
家家养豚漉清酒，朝祈暮赛依巫口。
神之来兮风飘飘，纸钱动兮锦伞摇。
神之去兮风亦静，香火灭兮杯盘冷。
肉堆潭岸石，酒泼庙前草。
不知龙神享几多，林鼠山狐长醉饱。
狐何幸，豚何辜，年年杀豚将餧狐。
狐假龙神食豚尽，九重泉底龙知无。','',''),('quantangshi-22090','新乐府 天可度 恶诈人也','白居易','quantangshi','','卷23','天可度，地可量，唯有人心不可防。
但见丹诚赤如血，谁知伪言巧似簧。
劝君掩鼻君莫掩，使君夫妇为参商。
劝君掇蠭君莫掇，使君父子成豺狼。
海底鱼兮天上鸟，高可射兮深可钓。
唯有人心相对时，咫尺之间不能料。
君不见李义府之辈笑欣欣，笑中有刀潜杀人。
阴阳神变皆可测，不测人间笑是瞋。','',''),('quantangshi-22091','新乐府 秦吉了 哀冤民也','白居易','quantangshi','','卷23','秦吉了，出南中，彩毛青黑花颈红。
耳聪心慧舌端巧，鸟语人言无不通。
昨日长爪鸢，今朝大觜乌。
鸢捎乳燕一窠覆，乌琢母鸡双眼枯。
鸡号堕地燕惊去，然后拾卵攫其雏。
岂无雕与鹗，嗉中肉饱不肯搏。
亦有鸾鹤羣，闲立高扬如不闻。
秦吉了，人云尔是能言鸟。
岂不见鸡燕之冤苦，吾闻凤皇百鸟主。
尔竟不为凤皇之前致一言，安用噪噪闲言语。','',''),('quantangshi-22092','新乐府 鵶九劒 思决壅也','白居易','quantangshi','','卷23','欧冶子死千年后，精灵暗授张鵶九。
鵶九铸劒吴山中，天与日时神借功。
金铁腾精火飜焰，踊跃求为镆鎁劒。
劒成未试十余年，有客持金买一观。
谁知闭匣长思用，三尺青蛇不肯蟠。
客有心，劒无口，客代劒言告鵶九。
君勿矜我玉可切，君勿夸我钟可刜。
不如持我决浮云，无令漫漫蔽白日。
为君使无私之光及万物，蛰虫昭苏萌草出。','',''),('quantangshi-22093','新乐府 采诗官 监前王乱亡之由也','白居易','quantangshi','','卷23','采诗官，采诗听歌导人言。
言者无罪闻者诫，下流上通上下泰。
周灭秦兴至隋氏，十代采诗官不置。
郊庙登歌赞君美，乐府艳词悦君意。
若求兴谕规刺言，万句千章无一字。
不是章句无规刺，渐及朝廷绝讽议。
诤臣杜口为冗员，谏鼓高悬作虚器。
一人负扆常端默，百辟入门两自媚。
夕郎所贺皆德音，春官每奏唯祥瑞。
君之堂兮千里远，君之门兮九重閟。
君耳唯闻堂上言，君眼不见门前事。
贪吏害民无所忌，奸臣蔽君无所畏。
君不见厉王胡亥之末年，羣臣有利君无利。
君兮君兮愿听此，欲开壅蔽达人情。
先向歌诗求讽刺。','',''),('quantangshi-22094','常乐里闲居偶题十六韵兼寄刘十五公舆王十一起吕二炅吕四熲崔十八玄亮元九稹刘三十二敦质张十五仲元时为校书郎','白居易','quantangshi','','卷23','帝都名利场，鸡鸣无安居。
独有嬾慢者，日高头未梳。
工拙性不同，进退迹遂殊。
幸逢太平代，天子好文儒。
小才难大用，典校在祕书。
三旬两入省，因得养顽疎。
茅屋四五间，一马二仆夫。
俸钱万六千，月给亦有余。
既无衣食牵，亦少人事拘。
遂使少年心，日日常晏如。
勿言无知己，躁静各有徒。
兰台七八人，出处与之俱。
旬时阻谈笑，旦夕望轩车。
谁能雠校闲，解带卧吾庐。
窗前有竹玩，门外有酒酤。
何以待君子，数竿对一壶。','',''),('quantangshi-22095','答元八宗简同游曲江后明日见赠','白居易','quantangshi','','卷23','长安千万人，出门各有营。
唯我与夫子，信马悠悠行。
行到曲江头，反照草树明。
南山好颜色，病客有心情。
水禽飜白羽，风荷袅翠茎。
何必沧浪去，即此可濯缨。
时景不重来，赏心难再并。
坐愁红尘里，夕鼓冬冬声。
归来经一宿，世虑稍复生。
赖闻瑶华唱，再得尘襟清。','',''),('quantangshi-22096','感时','白居易','quantangshi','','卷23','朝见日上天，暮见日入地。
不觉明镜中，忽年三十四。
勿言身未老，冉冉行将至。
白发虽未生，朱颜已先悴。
人生讵几何，在世犹如寄。
虽有七十期，十人无一二。
今我犹未悟，往往不适意。
胡为方寸间，不贮浩然气。
贫贱非不恶，道在何足避。
富贵非不爱，时来当自致。
所以达人心，外物不能累。
唯当饮美酒，终日陶陶醉。
斯言胜金玉，佩服无失坠。','',''),('quantangshi-22097','首夏同诸校正游开元观因宿玩月','白居易','quantangshi','','卷23','我与二三子，策名在京师。
官小无职事，闲于为客时。
沈沈道观中，心赏期在兹。
到门车马回，入院巾杖随。
清和四月初，树木正华滋。
风清新叶影，鸟恋残花枝。
向夕天又晴，东南余霞披。
置酒西廊下，待月杯行迟。
须臾金魄生，若与吾徒期。
光华一照耀，殿角相参差。
终夜清景前，笑歌不知疲。
长安名利地，此兴几人知。','',''),('quantangshi-22098','永崇里观居','白居易','quantangshi','','卷23','季夏中气侯，烦暑自此收。
萧飒风雨天，蝉声暮啾啾。
永崇里巷静，华阳观院幽。
轩车不到处，满地槐花秋。
年光忽冉冉，世事本悠悠。
何必待衰老，然后悟浮休。
真隐岂长远，至道在冥搜。
身虽世界住，心与虚无游。
朝饥有蔬食，夜寒有布裘。
幸免冻与馁，此外复何求。
寡欲虽少病，乐天心不忧。
何以明吾志，周易在牀头。','',''),('quantangshi-22099','早送举人入试','白居易','quantangshi','','卷23','夙驾送举人，东方犹未明。
自谓出太早，已有车马行。
骑火高低影，街鼓参差声。
可怜早朝者，相看意气生。
日出尘埃飞，羣动互营营。
营营各何求，无非利与名。
而我常晏起，虚住长安城。
春深官又满，日有归山情。','',''),('quantangshi-22100','招王质夫','白居易','quantangshi','','卷23','濯足云水客，折腰簪笏身。
喧闲迹相背，十里别经旬。
忽因乘逸兴，莫惜访嚣尘。
窗前故栽竹，与君为主人。','',''),('quantangshi-22101','祗役骆口因与王质夫同游秋山偶题三韵','白居易','quantangshi','','卷23','石拥百泉合，云破千峰开。
平生烟霞侣，此地重裴回。
今日勤王意，一半为山来。','',''),('quantangshi-22102','见萧侍御忆旧山草堂诗因以继和','白居易','quantangshi','','卷23','琢玉以为架，缀珠以为笼。
玉架绊野鹤，珠笼鏁冥鸿。
鸿思云外天，鹤忆松上风。
珠玉信为美，鸟不恋其中。
台中萧侍御，心与鸿鹤同。
晚起慵冠豸，闲行厌避骢。
昨见忆山诗，诗思浩无穷。
归梦杳何处，旧居茫水东。
秋闲杉桂林，春老芝术丛。
自云别山后，离抱常忡忡。
衣绣非不荣，持宪非不雄。
所乐不在此，怅望草堂空。','',''),('quantangshi-22103','病假中南亭闲望','白居易','quantangshi','','卷23','欹沈不视事，两日门掩关。
始知吏役身，不病不得闲。
闲意不在远，小亭方丈间。
西檐竹梢上，坐见太白山。
遥愧峰上云，对此尘中颜。','',''),('quantangshi-22104','仙游寺独宿','白居易','quantangshi','','卷23','沙鹤上阶立，潭月当户开。
此中留我宿，两夜不能回。
幸与静境遇，喜无归侣催。
从今独游后，不拟共人来。','',''),('quantangshi-22105','前庭凉夜','白居易','quantangshi','','卷23','露簟色似玉，风幌影如波。
坐愁树叶落，中庭明月多。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22106','官舍小亭闲望','白居易','quantangshi','','卷23','风竹散清韵，烟槐凝绿姿。
日高人吏去，闲坐在茅茨。
葛衣御时暑，蔬饭疗朝饥。
持此聊自足，心力少营为。
亭上独吟罢，眼前无事时。
数峰太白雪，一卷陶潜诗。
人心各自是，我是良在兹。
回谢争名客，甘从君所嗤。','',''),('quantangshi-22107','早秋独夜','白居易','quantangshi','','卷23','井梧凉叶动，邻杵秋声发。
独向檐下眠，觉来半牀月。','',''),('quantangshi-22108','听弹古渌水','白居易','quantangshi','','卷23','闻君古渌水，使我心和平。
欲识慢流意，为听疎泛声。
西窗竹阴下，竟日有余清。','',''),('quantangshi-22109','松斋自题','白居易','quantangshi','','卷23','非老亦非少，年过三纪余。
非贱亦非贵，朝登一命初。
才小分易足，心宽体长舒。
充肠皆美食，容膝即安居。
况此松斋下，一琴数帙书。
书不求甚解，琴聊以自娱。
夜直入君门，晚归卧吾庐。
形骸委顺动，方寸付空虚。
持此将过日，自然多晏如。
昏昏复默默，非智亦非愚。','',''),('quantangshi-22110','冬夜与钱员外同直禁中','白居易','quantangshi','','卷23','夜深草诏罢，霜月凄凛凛。
欲卧暖残杯，灯前相对饮。
连铺青缣被，对置通中枕。
仿髴百余宵，与君同此寝。','',''),('quantangshi-22111','和钱员外禁中夙兴见示','白居易','quantangshi','','卷23','窗白星汉曙，窗暖灯火余。
坐卷朱里幕，看封紫泥书。
窅窅钟漏尽，曈曈霞景初。
楼台红照曜，松竹青扶疎。
君爱此时好，回头特谓余。
不知上清界，晓景复何如。','',''),('quantangshi-22112','夏日独直寄萧侍御','白居易','quantangshi','','卷23','宪台文法地，翰林清切司。
鹰猜课野鹤，骥德责山麋。
课责虽不同，同归非所宜。
是以方寸内，忽忽暗相思。
夏日独上直，日长何所为。
澹然无他念，虚静是吾师。
形委有事牵，心与无事期。
中臆一以旷，外累都若遗。
地贵身不觉，意闲境来随。
但对松与竹，如在山中时。
情性聊自适，吟咏偶成诗。
此意非夫子，余人多不知。','',''),('quantangshi-22113','松声','白居易','quantangshi','','卷23','月好好独坐，双松在前轩。
西南微风来，潜入枝叶间。
萧寥发为声，半夜明月前。
寒山飒飒雨，秋琴泠泠弦。
一闻涤炎暑，再听破昏烦。
竟夕遂不寐，心体俱翛然。
南陌车马动，西邻歌吹繁。
谁知兹檐下，满耳不为喧。','',''),('quantangshi-22114','禁中','白居易','quantangshi','','卷23','门严九重静，窗幽一室闲。
好是修心处，何必在深山。','',''),('quantangshi-22115','赠吴丹','白居易','quantangshi','','卷23','巧者力苦劳，智者心苦忧。
爱君无巧智，终岁闲悠悠。
尝登御史府，亦佐东诸候。
手操纠谬简，心运决胜筹。
宦途似风水，君心如虚舟。
泛然而不有，进退得自由。
今来脱豸冠，时往侍龙楼。
官曹称心静，居处随迹幽。
冬负南荣日，支体甚温柔。
夏卧北窗风，枕席如凉秋。
南山入舍下，酒瓮在牀头。
人间有闲地，何必隐林丘。
顾我愚且昧，劳生殊未休。
一入金门直，星霜三四周。
主恩信难报，近地徒久留。
终当乞闲官，退与夫子游。','',''),('quantangshi-22116','初除户曹喜而言志','白居易','quantangshi','','卷23','诏授户曹掾，捧诏感君恩。
感恩非为己，禄养及吾亲。
弟兄俱簪笏，新妇俨衣巾。
罗列高堂下，拜庆正纷纷。
俸钱四五万，月可奉晨昏。
廪禄二百石，岁可盈仓囷。
喧喧车马来，贺客满我门。
不以我为贪，知我家内贫。
置酒延贺客，客容亦欢欣。
笑云今日后，不复忧空尊。
答云如君言，愿君少逡巡。
我有平生志，醉后为君陈。
人生百岁期，七十有几人。
浮荣及虚位，皆是身之宾。
唯有衣与食，此事粗关身。
苟免饥寒外，余物尽浮云。','',''),('quantangshi-22117','秋居书怀','白居易','quantangshi','','卷23','门前少宾客，阶下多松竹。
秋景下西墙，凉风入东屋。
有琴慵不弄，有书闲不读。
尽日方寸中，澹然无所欲。
何须广居处，不用多积蓄。
丈室可容身，斗储可充腹。
况无治道术，坐受官家禄。
不种一株桑，不锄一壠谷。
终朝饱饭餐，卒岁丰衣服。
持此知愧心，自然易为足。','',''),('quantangshi-22118','禁中晓卧因怀王起居','白居易','quantangshi','','卷23','迟迟禁漏尽，悄悄暝鵶喧。
夜雨槐花落，微凉卧北轩。
曙灯残未灭，风帘闲自飜。
每一得静境，思与故人言。','',''),('quantangshi-22119','养拙','白居易','quantangshi','','卷23','铁柔不为劒，木曲不为辕。
今我亦如此，愚蒙不及门。
甘心谢名利，灭迹归丘园。
坐卧茅茨中，但对琴与尊。
身去缰锁累，耳辞朝市喧。
逍遥无所为，时窥五千言。
无忧乐性场，寡欲清心源。
始知不才者，可以探道根。','',''),('quantangshi-22120','寄李十一建','白居易','quantangshi','','卷23','外事牵我形，外物诱我情。
李君别来久，褊恡从中生。
忆昨访君时，立马扣柴荆。
有时君未起，穉子喜先迎。
连步笑出门，衣飜冠或倾。
埽阶苔纹绿，拂榻藤阴清。
家酝及春熟，园葵乘露烹。
看山东亭坐，待月南原行。
门静唯鸟语，坊远少鼓声。
相对尽日言，不及利与名。
分手来几时，明月三四盈。
别时残花落，及此新蝉鸣。
芳岁忽已晚，离抱怅未平。
岂不思命驾，吏职坐相萦。
前时君有期，访我来山城。
心赏久云阻，言约无自轻。
相去幸非远，走马一日程。','',''),('quantangshi-22121','旅次华州赠袁右丞','白居易','quantangshi','','卷23','渭水绿溶溶，华山青崇崇。
山水一何丽，君子在其中。
才与世会合，物随诚感通。
德星降人福，时雨助岁功。
化行人无讼，囹圄千日空。
政顺气亦和，黍稷三年丰。
客自帝城来，驱马出关东。
爱此一郡人，如见太古风。
方今天子心，忧人正忡忡。
安得天下守，尽得如袁公。','',''),('quantangshi-22122','酬杨九弘贞长安病中见寄','白居易','quantangshi','','卷23','伏枕君寂寂，折腰我营营。
所嗟经时别，相去一宿程。
携手昨何时，昆明春水平。
离郡来几日，太白夏云生。
之子未得意，贫病客帝城。
贫坚志士节，病长高人情。
隐几自恬澹，闭门无送迎。
龙卧心有待，鹤瘦貌弥清。
清机发为文，投我如振琼。
何以慰饥渴，捧之吟一声。','',''),('quantangshi-22123','禁中寓直梦游仙游寺','白居易','quantangshi','','卷23','西轩草诏暇，松竹深寂寂。
月出清风来，忽似山中夕。
因成西南梦，梦作游仙客。
觉闻宫漏声，犹谓山泉滴。','',''),('quantangshi-22124','赠王山人','白居易','quantangshi','','卷23','闻君减寝食，日听神仙说。
暗待非常人，潜求长生诀。
言长本对短，未离生死辙。
假使得长生，才能胜夭折。
松树千年朽，槿花一日歇。
毕竟共虚空，何须夸岁月。
彭殇徒自异，生死终无别。
不如学无生，无生即无灭。','',''),('quantangshi-22125','秋山','白居易','quantangshi','','卷23','久病旷心赏，今朝一登山。
山秋云物冷，称我清羸颜。
白石卧可枕，青萝行可攀。
意中如有得，尽日不欲还。
人生无几何，如寄天地间。
心有千载忧，身无一日闲。
何时解尘网，此地来掩关。','',''),('quantangshi-22126','赠能七伦','白居易','quantangshi','','卷23','涧松高百寻，四时寒森森。
临风有清韵，向日无曲阴。
如何时俗人，但赏桃李林。
岂不知坚贞，芳馨诱其心。
能生学为文，气高功亦深。
手中一百篇，句句披沙金。
苦节二十年，无人振陆沈。
今我尚贫贱，徒为尔知音。','',''),('quantangshi-22127','题杨颖士西亭','白居易','quantangshi','','卷23','静得亭上境，远谐尘外踪。
凭轩东南望，鸟灭山重重。
竹露冷烦襟，杉风清病容。
旷然宜真趣，道与心相逢。
即此可遗世，何必蓬壶峰。','',''),('quantangshi-22128','题赠郑祕书征君石沟溪隐居','白居易','quantangshi','','卷23','郑君得自然，虚白生心胸。
吸彼沆瀣精，凝为冰雪容。
大君贞元初，求贤致时雍。
蒲轮入翠微，迎下天台峰。
赤城别松乔，黄合交夔龙。
俛仰受三命，从容辞九重。
出笼鹤翩翩，归林凤雝雝。
在火辨良玉，经霜识贞松。
新居寄楚山，山碧溪溶溶。
丹竈烧烟煴，黄精花丰茸。
蕙帐夜琴澹，桂尊春酒浓。
时人不到处，苔石无尘踪。
我今何为者，趋世身龙钟。
不向林壑访，无由朝市逢。
终当解尘缨，卜筑来相从。','',''),('quantangshi-22129','及第后归觐留别诸同年','白居易','quantangshi','','卷23','十年常苦学，一上谬成名。
擢第未为贵，贺亲方始荣。
时辈六七人，送我出帝城。
轩车动行色，丝管举离声。
得意减别恨，半酣轻远程。
翩翩马蹄疾，春日归乡情。','',''),('quantangshi-22130','清夜琴兴','白居易','quantangshi','','卷23','月出鸟栖尽，寂然坐空林。
是时心境闲，可以弹素琴。
清泠由木性，恬澹随人心。
心积和平气，木应正始音。
响余羣动息，曲罢秋夜深。
正声感元化，天地清沈沈。','',''),('quantangshi-22131','效陶潜体诗十六首 一','白居易','quantangshi','','卷23','不动者厚地，不息者高天。
无穷者日月，长在者山川。
松柏与龟鹤，其寿皆千年。
嗟嗟羣物中，而人独不然。
早出向朝市，暮已归下泉。
形质及寿命，危脆若浮烟。
尧舜与周孔，古来称圣贤。
借问今何在，一去亦不还。
我无不死药，万万随化迁。
所未定知者，修短迟速间。
幸及身健日，当歌一尊前。
何必待人劝，持此自为欢。','',''),('quantangshi-22132','效陶潜体诗十六首 二','白居易','quantangshi','','卷23','翳翳逾月阴，沈沈连日雨。
开帘望天色，黄云暗如土。
行潦毁我墉，疾风坏我宇。
蓬莠生庭院，泥涂失场圃。
村深绝宾客，窗晦无俦侣。
尽日不下牀，跳蛙时入户。
出门无所往，入室还独处。
不以酒自娱，块然与谁语。','',''),('quantangshi-22133','效陶潜体诗十六首 三','白居易','quantangshi','','卷23','朝饮一杯酒，冥心合元化。
兀然无所思，日高尚闲卧。
暮读一卷书，会意如嘉话。
欣然有所遇，夜深犹独坐。
又得琴上趣，安弦有余暇。
复多诗中狂，下笔不能罢。
唯兹三四事，持用度昼夜。
所以阴雨中，经旬不出舍。
始悟独往人，心安时亦过。','',''),('quantangshi-22134','效陶潜体诗十六首 四','白居易','quantangshi','','卷23','车家采桑妇，雨来苦愁悲。
蔟蚕北堂前，雨冷不成丝。
西家荷锄叟，雨来亦怨咨。
种豆南山下，雨多落为萁。
而我独何幸，酝酒本无期。
及此多雨日，正遇新熟时。
开瓶泻尊中，玉液黄金脂。
持玩已可悦，欢尝有余滋。
一酌发好容，再酌开愁眉。
连延四五酌，酣畅入四肢。
忽然遗我物，谁复分是非。
是时连夕雨，酩酊无所知。
人心苦颠倒，反为忧者嗤。','',''),('quantangshi-22135','效陶潜体诗十六首 五','白居易','quantangshi','','卷23','朝亦独醉歌，暮亦独醉睡。
未尽一壶酒，已成三独醉。
勿嫌饮太少，且喜欢易致。
一杯复两杯，多不过三四。
便得心中适，尽忘身外事。
更复强一杯，陶然遗万累。
一饮一石者，徒以多为贵。
及其酩酊时，与我亦无异。
笑谢多饮者，酒钱徒自费。','',''),('quantangshi-22136','效陶潜体诗十六首 六','白居易','quantangshi','','卷23','天秋无片云，地静无纤尘。
团团新晴月，林外生白轮。
忆昨阴霖天，连连三四旬。
赖逢家酝熟，不觉过朝昏。
私言雨霁后，可以罢余尊。
及对新月色，不醉亦愁人。
牀头残酒榼，欲尽味弥淳。
携置南檐下，举酌自殷勤。
清光入杯杓，白露生衣巾。
乃知阴与晴，安可无此君。
我有乐府诗，成来人未闻。
今宵醉有兴，狂咏惊四邻。
独赏犹复尔，何况有交亲。','',''),('quantangshi-22137','效陶潜体诗十六首 七','白居易','quantangshi','','卷23','中秋三五夜，明月在前轩。
临觞忽不饮，忆我平生欢。
我有同心人，邈邈崔与钱。
我有忘形友，迢迢李与元。
或飞青云上，或落江湖间。
与我不相见，于今四五年。
我无缩地术，君非驭风仙。
安得明月下，四人来晤言。
良夜信难得，佳期杳无缘。
明月又不驻，渐下西南天。
岂无他时会，惜此清景前。','',''),('quantangshi-22138','效陶潜体诗十六首 八','白居易','quantangshi','','卷23','家酝饮已尽，村中无酒酤。
坐愁今夜醒，其奈秋怀何。
有客忽叩门，言语一何佳。
云是南村叟，挈榼来相过。
且喜尊不燥，安问少与多。
重阳虽已过，篱菊有残花。
欢来苦昼短，不觉夕阳斜。
老人[勿]遽起，且待新月华。
客去有余趣，竟夕独酣歌。','',''),('quantangshi-22139','效陶潜体诗十六首 九','白居易','quantangshi','','卷23','原生衣百结，颜子食一箪。
欢然乐其志，有以忘饥寒。
今我何人哉，德不及先贤。
衣食幸相属，胡为不自安。
况兹清渭曲，居处安且闲。
榆柳百余树，茅茨十数间。
寒负檐下日，热濯涧底泉。
日出犹未起，日入已复眠。
西风满村巷，清凉八月天。
但有鸡犬声，不闻车马喧。
时倾一尊酒，坐望东南山。
穉侄初学步，牵衣戏我前。
即此自可乐，庶几颜与原。','',''),('quantangshi-22140','效陶潜体诗十六首 十','白居易','quantangshi','','卷23','湛湛尊中酒，有功不自伐。
不伐人不知，我今代其说。
良将临大敌，前驱千万卒。
一箪投河饮，赴死心如一。
壮士磨匕首，勇愤气咆𠷺。
一酣忘报雠，四体如无骨。
东海杀孝妇，天旱逾年月。
一酌酹其魂，通宵雨不歇。
咸阳秦狱气，冤痛结为物。
千岁不肯散，一沃亦销失。
况兹儿女恨，及彼幽忧疾。
快饮无不消，如霜得春日。
方知麴糵灵，万物无与匹。','',''),('quantangshi-22141','效陶潜体诗十六首 十一','白居易','quantangshi','','卷23','烟霞隔悬圃，风波限瀛州。
我岂不欲往，大海路阻修。
神仙但闻说，灵药不可求。
长生无得者，举世如蜉蝣。
逝者不重回，存者难久留。
踟蹰未死间，何苦怀百忧。
念此忽内热，坐看成白头。
举杯还独饮，顾影自献酬。
心与口相约，未醉勿言休。
今朝不尽醉，知有明朝不。
不见郭门外，累累坟与丘。
月明愁杀人，黄蒿风飕飕。
死者若有知，悔不秉烛游。','',''),('quantangshi-22142','效陶潜体诗十六首 十二','白居易','quantangshi','','卷23','吾闻浔阳郡，昔有陶征君。
爱酒不爱名，忧醒不忧贫。
尝为彭泽令，在官才八旬。
愀然忽不乐，挂印着公门。
口吟归去来，头戴漉酒巾。
人吏留不得，直入故山云。
归来五柳下，还以酒养真。
人间荣与利，摆落如泥尘。
先生去已久，纸墨有遗文。
篇篇劝我饮，此外无所云。
我从老大来，窃慕其为人。
其他不可及，且效醉昏昏。','',''),('quantangshi-22143','效陶潜体诗十六首 十三','白居易','quantangshi','','卷23','楚王疑忠臣，江南放屈平。
晋朝轻高士，林下弃刘伶。
一人常独醉，一人常独醒。
醒者多苦志，醉者多欢情。
欢情信独善，苦志竟何成。
兀傲瓮间卧，顦顇泽畔行。
彼忧而此乐，道理甚分明。
愿君且饮酒，勿思身后名。','',''),('quantangshi-22144','效陶潜体诗十六首 十四','白居易','quantangshi','','卷23','有一燕赵士，言貌甚奇瓌。
日日酒家去，脱衣典数杯。
问君何落拓，云仆生草莱。
地寒命且薄，徒抱王佐才。
岂无济时策，君门乏良媒。
三献寝不报，迟迟空手回。
亦有同门生，先升青云梯。
贵贱交道绝，朱门叩不开。
及归种禾黍，三岁旱为灾。
入山烧黄白，一旦化为灰。
蹉跎五十余，生世苦不谐。
处处去不得，却归酒中来。','',''),('quantangshi-22145','效陶潜体诗十六首 十五','白居易','quantangshi','','卷23','南巷有贵人，高盖驷马车。
我问何所苦，四十垂白须。
答云君不知，位重多忧虞。
北里有寒士，瓮牖绳为枢。
出扶桑枣杖，入卧蜗牛庐。
散贱无忧患，心安体亦舒。
东邻有富翁，藏货徧五都。
东京收粟帛，西市鬻金珠。
朝营暮计算，昼夜不安居。
西舍有贫者，匹妇配匹夫。
布帬行赁舂，裋褐坐佣书。
以此求口食，一饱欣有余。
贵贱与贫富，高下虽有殊。
忧乐与利害，彼此不相逾。
是以达人观，万化同一途。
但未知生死，胜负两何如。
迟疑未知间，且以酒为娱。','',''),('quantangshi-22146','效陶潜体诗十六首 十六','白居易','quantangshi','','卷23','济水澄而洁，河水浑而黄。
交流列四渎，清浊不相伤。
太公战牧野，伯夷饿首阳。
同时号贤圣，进退不相妨。
谓天不爱民，胡为生稻粱。
谓天果爱民，胡为生豺狼。
谓神福善人，孔圣竟栖遑。
谓神祸淫人，暴秦终霸王。
颜回与黄宪，何辜早夭亡。
蝮蛇与鸩鸟，何得寿延长。
物理不可测，神道亦难量。
举头仰问天，天色但苍苍。
唯当多种黍，日醉手中觞。','',''),('quantangshi-22147','自题写真','白居易','quantangshi','','卷23','我貌不自识，李放写我真。
静观神与骨，合是山中人。
蒲柳质易朽，麋鹿心难驯。
何事赤墀上，五年为侍臣。
况多刚狷性，难与世同尘。
不惟非贵相，但恐生祸因。
宜当早罢去，收取云泉身。','',''),('quantangshi-22148','遣怀','白居易','quantangshi','','卷23','寓心身体中，寓性方寸内。
此身是外物，何足苦忧爱。
况有假饰者，华簪及高盖。
此又疎于身，复在外物外。
操之多惴栗，失之又悲悔。
乃知名与器，得丧俱为害。
颓然环堵客，萝蕙为巾带。
自得此道来，身穷心甚泰。','',''),('quantangshi-22149','渭上偶钓','白居易','quantangshi','','卷23','渭水如镜色，中有鲤与鲂。
偶持一竿竹，悬钓在其傍。
微风吹钓丝，袅袅十尺长。
谁知对鱼坐，心在无何乡。
昔有白头人，亦钓此渭阳。
钓人不钓鱼，七十得文王。
况我垂钓意，人鱼又兼忘。
无机两不得，但弄秋水光。
兴尽钓亦罢，归来饮我觞。','',''),('quantangshi-22150','隐几','白居易','quantangshi','','卷23','身适忘四支，心适忘是非。
既适又忘适，不知吾是谁。
百体如槁木，兀然无所知。
方寸如死灰，寂然无所思。
今日复明日，身心忽两遗。
行年三十九，岁暮日斜时。
四十心不动，吾今其庶几。','',''),('quantangshi-22151','春眠','白居易','quantangshi','','卷23','新浴肢体畅，独寝神魂安。
况因夜深坐，遂成日高眠。
春被薄亦暖，朝窗深更闲。
却忘人间事，似得枕上仙。
至适无梦想，大和难名言。
全胜彭泽醉，欲敌曹溪禅。
何物呼我觉，伯劳声关关。
起来妻子笑，生计春茫然。','',''),('quantangshi-22152','闲居','白居易','quantangshi','','卷23','空腹一盏粥，饥食有余味。
南檐半牀日，暖卧因成睡。
緜袍拥两膝，竹几支双臂。
从旦直至昏，身心一无事。
心足即为富，身闲乃当贵。
富贵在此中，何必居高位。
君看裴相国，金紫光照地。
心苦头尽白，才年四十四。
乃知高盖车，乘者多忧畏。','',''),('quantangshi-22153','夏日','白居易','quantangshi','','卷23','东窗晚无热，北户凉有风。
尽日坐复卧，不离一室中。
中心本无系，亦与出门同。','',''),('quantangshi-22154','适意二首 一','白居易','quantangshi','','卷23','十年为旅客，常有饥寒愁。
三年作谏官，复多尸素羞。
有酒不暇饮，有山不得游。
岂无平生志，拘牵不自由。
一朝归渭上，泛如不系舟。
置心世事外，无喜亦无忧。
终日一蔬食，终年一布裘。
寒来弥嬾放，数日一梳头。
朝睡足始起，夜酌醉即休。
人心不过适，适外复何求。','',''),('quantangshi-22155','适意二首 二','白居易','quantangshi','','卷23','早岁从旅游，颇谙时俗意。
中年忝班列，备见朝廷事。
作客诚已难，为臣尤不易。
况余方且介，举动多忤累。
直道速我尤，诡遇非吾志。
胸中十年内，消尽浩然气。
自从返田亩，顿觉无忧愧。
蟠木用难施，浮云心易遂。
悠悠身与世，从此两相弃。','',''),('quantangshi-22156','首夏病间','白居易','quantangshi','','卷23','我生来几时，万有四千日。
自省于其间，非忧即有疾。
老去虑渐息，年来病初愈。
忽喜身与心，泰然两无苦。
况兹孟夏月，清和好时节。
微风吹裌衣，不寒复不热。
移榻树阴下，竟日何所为。
或饮一瓯茗，或吟两句诗。
内无忧患迫，外无职役羁。','',''),('quantangshi-22157','晚春酤酒','白居易','quantangshi','','卷23','百花落如雪，两鬓垂作丝。
春去有来日，我老无少时。
人生待富贵，为乐常苦迟。
不如贫贱日，随分开愁眉。
卖我所乘马，典我旧朝衣。
尽将酤酒饮，酩酊步行归。
名姓日隐晦，形骸日变衰。
醉卧黄公肆，人知我是谁。','',''),('quantangshi-22158','兰若寓居','白居易','quantangshi','','卷23','名宦老慵求，退身安草野。
家园病嬾归，寄居在兰若。
薜衣换簪组，藜杖代车马。
行止辄自由，甚觉身潇洒。
晨游南坞上，夜息东庵下。
人间千万事，无有关心者。','',''),('quantangshi-22159','麴生访宿','白居易','quantangshi','','卷23','西斋寂已暮，叩门声樀樀。
知是君宿来，自拂尘埃席。
村家何所有，茶果迎来客。
贫静似僧居，竹林依四壁。
厨灯斜影出，檐雨余声滴。','',''),('quantangshi-22160','闻庾七左降因咏所怀','白居易','quantangshi','','卷23','我病卧渭北，君老谪巴东。
相悲一长叹，薄命与君同。
既叹还自哂，哂叹两未终。
后心诮前意，所见何迷蒙。
人生大块间，如鸿毛在风。
或飘青云上，或落泥涂中。
衮服相天下，傥来非我通。
布衣委草莽，偶去非吾穷。
外物不可必，中怀须自空。
无令怏怏气，留滞在心胸。','',''),('quantangshi-22161','答卜者','白居易','quantangshi','','卷23','病眼昏似夜，衰鬓飒如秋。
除却须衣食，平生百事休。
知君善易者，问我决疑不。
不卜非他故，人间无所求。','',''),('quantangshi-22162','归田三首 一','白居易','quantangshi','','卷23','人生何所欲，所欲唯两端。
中人爱富贵，高士慕神仙。
神仙须有籍，富贵亦在天。
莫恋长安道，莫寻方丈山。
西京尘浩浩，东海浪漫漫。
金门不可入，琪树何由攀。
不如归山下，如法种春田。','',''),('quantangshi-22163','归田三首 二','白居易','quantangshi','','卷23','种田意已决，决意复何如。
卖马买犊使，徒步归田庐。
迎春治耒耜，候雨辟菑畲。
策杖田头立，躬亲课仆夫。
吾闻老农言，为稼慎在初。
所施不卤莽，其报必有余。
上求奉王税，下望备家储。
安得放慵惰，拱手而曳裾。
学农未为鄙，亲友勿笑余。
更待明年后，自拟执犂锄。','',''),('quantangshi-22164','归田三首 三','白居易','quantangshi','','卷23','三十为近臣，腰间鸣佩玉。
四十为野夫，田中学锄谷。
何言十年内，变化如此速。
此理固是常，穷通相倚伏。
为鱼有深水，为鸟有高木。
何必守一方，窘然自牵束。
化吾足为马，吾因以行陆。
化吾手为弹，吾因以求肉。
形骸为异物，委顺心犹足。
幸得且归农，安知不为福。
况吾行欲老，瞥若风前烛。
孰能俄顷间，将心系荣辱。','',''),('quantangshi-22165','秋游原上','白居易','quantangshi','','卷23','七月行已半，早凉天气清。
清晨起巾栉，徐步出柴荆。
露杖筇竹冷，风襟越蕉轻。
闲携弟侄辈，同上秋原行。
新枣未全赤，晚瓜有余馨。
依依田家叟，设此相逢迎。
自我到此村，往来白发生。
村中相识久，老幼皆有情。
留连向暮归，树树风蝉声。
是时新雨足，禾黍夹道青。
见此令人饱，何必待西成。','',''),('quantangshi-22166','九日登西原宴望','白居易','quantangshi','','卷23','病爱枕席凉，日高眠未辍。
弟兄呼我起，今日重阳节。
起登西原望，怀抱同一豁。
移座就菊丛，餻酒前罗列。
虽无丝与管，歌笑随情发。
白日未及倾，颜酡耳已热。
酒酣四向望，六合何空阔。
天地自久长，斯人几时活。
请看原下村，村人死不歇。
一村四十家，哭葬无虚月。
指此各相勉，良辰且欢悦。','',''),('quantangshi-22167','寄同病者','白居易','quantangshi','','卷23','三十生二毛，早衰为沈疴。
四十官七品，拙宦非由他。
年颜日枯槁，时命日蹉跎。
岂独我如此，圣贤无奈何。
回观亲旧中，举目尤可嗟。
或有终老者，沈贱如泥沙。
或有始壮者，飘忽如风花。
穷饿与夭促，不如我者多。
以此反自慰，常得心平和。
寄言同病者，回叹且为歌。','',''),('quantangshi-22168','游蓝田山卜居','白居易','quantangshi','','卷23','脱置腰下组，摆落心中尘。
行歌望山去，意似归乡人。
朝蹋玉峰下，暮寻蓝水滨。
拟求幽僻地，安置疎慵身。
本性便山寺，应须旁悟真。','',''),('quantangshi-22169','村雪夜坐','白居易','quantangshi','','卷23','南窗背灯坐，风霰暗纷纷。
寂莫深村夜，残雁雪中闻。','',''),('quantangshi-22170','东园玩菊','白居易','quantangshi','','卷23','少年昨已去，芳岁今又阑。
如何寂莫意，复此荒凉园。
园中独立久，日澹风露寒。
秋蔬尽芜没，好树亦凋残。
唯有数丛菊，新开篱落间。
携觞聊就酌，为尔一留连。
忆我少小日，易为兴所牵。
见酒无时节，未饮已欣然。
近从年长来，渐觉取乐难。
常恐更衰老，强饮亦无欢。
顾谓尔菊花，后时何独鲜。
诚知不为我，借尔暂开颜。','',''),('quantangshi-22171','观稼','白居易','quantangshi','','卷23','世役不我牵，身心常自若。
晚出看田亩，闲行旁村落。
累累绕场稼，啧啧羣飞雀。
年丰岂独人，禽鸟声亦乐。
田翁逢我喜，默起具尊杓。
敛手笑相延，社酒有残酌。
愧兹勤且敬，藜杖为淹泊。
言动任天真，未觉农人恶。
停杯问生事，夫种妻儿获。
筋力苦疲劳，衣食常单薄。
自慙禄仕者，曾不营农作。
饱食无所劳，何殊卫人鹤。','',''),('quantangshi-22172','闻哭者','白居易','quantangshi','','卷23','昨日南邻哭，哭声一何苦。
云是妻哭夫，夫年二十五。
今朝北里哭，哭声又何切。
云是母哭儿，儿年十七八。
四邻尚如此，天下多夭折。
乃知浮世人，少得垂白发。
余今过四十，念彼聊自悦。
从此明镜中，不嫌头似雪。','',''),('quantangshi-22173','新构亭台示诸弟侄','白居易','quantangshi','','卷23','平台高数尺，台上结茅茨。
东西疏二牖，南北开两扉。
芦帘前后卷，竹簟当中施。
清泠白石枕，疏凉黄葛衣。
开襟向风坐，夏日如秋时。
啸傲颇有趣，窥临不知疲。
东窗对华山，三峰碧参差。
南檐当渭水，卧见云帆飞。
仰摘枝上果，俯折畦中葵。
足以充饥渴，何必慕甘肥。
况有好羣从，旦夕相追随。','',''),('quantangshi-22174','自吟拙什因有所怀','白居易','quantangshi','','卷23','嬾病每多暇，暇来何所为。
未能抛笔研，时作一篇诗。
诗成澹无味，多被众人嗤。
上怪落声韵，下嫌拙言词。
时时自吟咏，吟罢有所思。
苏州及彭泽，与我不同时。
此外复谁爱，唯有元微之。
谪向江陵府，三年作判司。
向去二千里，诗成远不知。','',''),('quantangshi-22175','东坡秋意寄元八','白居易','quantangshi','','卷23','寥落野陂畔，独行思有余。
秋荷病叶上，白露大如珠。
忽忆同赏地，曲江东北隅。
秋池少游客，唯我与君俱。
啼蛩隐红蓼，瘦马蹋青芜。
当时与今日，俱是暮秋初。
节物苦相似，时景亦无余。
唯有人分散，经年不得书。','',''),('quantangshi-22176','闲居','白居易','quantangshi','','卷23','深闭竹间扉，静埽松下地。
独啸晚风前，何人知此意。
看山尽日坐，枕帙移时睡。
谁能从我游，使君心无事。','',''),('quantangshi-22177','咏拙','白居易','quantangshi','','卷23','所禀有巧拙，不可改者性。
所赋有厚薄，不可移者命。
我性愚且蠢，我命薄且屯。
问我何以知，所知良有因。
亦曾举两足，学人蹋红尘。
从兹知性拙，不解转如轮。
亦曾奋六翮，高飞到青云。
从兹知命薄，摧落不逡巡。
慕贵而厌贱，乐富而恶贫。
同此天地间，我岂异于人。
性命苟如此，反则成苦辛。
以此自安分，虽穷每欣欣。
葺茅为我庐，编蓬为我门。
缝布作袍被，种谷充盘飧。
静读古人书，闲钓清渭滨。
优哉复游哉，聊以终吾身。','',''),('quantangshi-22178','咏慵','白居易','quantangshi','','卷23','有官慵不选，有田慵不农。
屋穿慵不葺，衣裂慵不缝。
有酒慵不酌，无异尊常空。
有琴慵不弹，亦与无弦同。
家人告饭尽，欲炊慵不舂。
亲朋寄书至，欲读慵开封。
尝闻嵇叔夜，一生在慵中。
弹琴复锻铁，比我未为慵。','',''),('quantangshi-22179','冬夜','白居易','quantangshi','','卷23','家贫亲爱散，身病交游罢。
眼前无一人，独掩村斋卧。
冷落灯火暗，离披帘幕破。
策策窗户前，又闻新雪下。
长年渐省睡，夜半起端坐。
不学坐忘心，寂莫安可过。
兀然身寄世，浩然心委化。
如此来四年，一千三百夜。','',''),('quantangshi-22180','村中留李三固言宿','白居易','quantangshi','','卷23','平生早游宦，不道无亲故。
如我与君心，相知应有数。
春明门前别，金氏陂中遇。
村酒两三杯，相留寒日暮。
勿嫌村酒薄，聊酌论心素。
请君少踟蹰，系马门前树。
明年身若健，便拟江湖去。
他日纵相思，知君无觅处。
后会既茫茫，今宵君且住。','',''),('quantangshi-22181','友人夜访','白居易','quantangshi','','卷23','檐间清风簟，松下明月杯。
幽意正如此，况乃故人来。','',''),('quantangshi-22182','游悟真寺诗','白居易','quantangshi','','卷23','元和九年秋，八月月上弦。
我游悟真寺，寺在王顺山。
去山四五里，先闻水潺湲。
自兹舍车马，始涉蓝溪湾。
手拄青竹杖，足蹋白石滩。
渐怪耳目旷，不闻人世喧。
山下望山上，初疑不可攀。
谁知中有路，盘折通岩巅。
一息幡竿下，再休石龛边。
龛间长丈余，门户无扃关。
仰窥不见人，石发垂若鬟。
惊出白蝙蝠，双飞如雪飜。
回首寺门望，青崖夹朱轩。
如擘山腹开，置寺于其间。
入门无平地，地窄虚空宽。
房廊与台殿，高下随峰峦。
岩崿无撮土，树木多瘦坚。
根株抱石长，屈曲虫蛇蟠。
松桂乱无行，四时郁芊芊。
枝梢袅青翠，韵若风中弦。
日月光不透，绿阴相交延。
幽鸟时一声，闻之似寒蝉。
首憩宾位亭，就坐未及安。
须臾开北户，万里明豁然。
拂檐虹霏微，绕栋云回旋。
赤日间白雨，阴晴同一川。
野绿簇草树，眼界吞秦原。
渭水细不见，汉陵小于拳。
却顾来时路，萦纡映朱阑。
历历上山人，一一遥可观。
前对多宝墖，风铎鸣四端。
栾栌与户牖，恰恰金碧繁。
云昔迦叶佛，此地坐涅盘。
至今铁钵在，当底手迹穿。
西开玉像殿，白佛森比肩。
斗薮尘埃衣，礼拜冰雪颜。
叠霜为袈裟，贯雹为华鬘。
逼观疑鬼功，其迹非雕镌。
次登观音堂，未到闻栴檀。
上阶脱双履，敛足升净筵。
六楹排玉镜，四座敷金钿。
黑夜自光明，不待灯烛然。
众宝互低昂，碧佩珊瑚幡。
风来似天乐，相触声珊珊。
白珠垂露凝，赤珠滴血殷。
点缀佛髻上，合为七宝冠。
双瓶白琉璃，色若秋水寒。
隔瓶见舍利，圆转如金丹。
玉笛何代物，天人施只园。
吹如秋鹤声，可以降灵仙。
是时秋方中，三五月正圆。
宝堂豁三门，金魄当其前。
月与宝相射，晶光争鲜妍。
照人心骨冷，竟夕不欲眠。
晓寻南墖路，乱竹低婵娟。
林幽不逢人，寒蝶飞翾翾。
山果不识名，离离夹道蕃。
足以疗饥乏，摘尝味甘酸。
道南蓝谷神，紫伞白纸钱。
若岁有水旱，诏使修苹蘩。
以地清净故，献奠无荤膻。
危石叠四五，𡾋嵬欹且刓。
造物者何意，堆在岩东偏。
冷滑无人迹，苔点如花牋。
我来登上头，下临不测渊。
目眩手足掉，不敢低头看。
风从石下生，薄人而上抟。
衣服似羽翮，开张欲飞骞。
𡾼𡾼三面峰，峰尖刀劒攒。
往往白云过，决开露青天。
西北日落时，夕晖红团团。
千里翠屏外，走下丹砂丸。
东南月上时，夜气青漫漫。
百丈碧潭底，写出黄金盘。
蓝水色似蓝，日夜长潺潺。
周回绕山转，下视如青环。
或铺为慢流，或激为奔湍。
泓澄最深处，浮出蛟龙涎。
侧身入其中，悬磴尤险艰。
扪萝蹋樛木，下逐饮涧猨。
雪迸起白鹭，锦跳惊红鳣。
歇定方盥漱，濯去支体烦。
浅深皆洞彻，可照脑与肝。
但爱清见底，欲寻不知源。
东崖饶怪石，积甃苍琅玕。
温润发于外，其间韫璵璠。
卞和死已久，良玉多弃捐。
或时泄光彩，夜与星月连。
中顶最高峰，拄天青玉竿。
𪕍𪕌上不得，岂我能攀援。
上有白莲池，素葩覆清澜。
闻名不可到，处所非人寰。
又有一片石，大如方尺甎。
插在半壁上，其下万仞悬。
云有过去师，坐得无生禅。
号为定心石，长老世相传。
却上谒仙祠，蔓草生緜緜。
昔闻王氏子，羽化升上玄。
其西晒药台，犹对芝术田。
时复明月夜，上闻黄鹤言。
回寻画龙堂，二叟鬓发斑。
想见听法时，欢喜礼印坛。
复归泉窟下，化作龙蜿蜒。
阶前石孔在，欲雨生白烟。
往有写经僧，身静心精专。
感彼云外鸽，羣飞千翩翩。
来添研中水，去吸岩底泉。
一日三往复，时节长不愆。
经成号圣僧，弟子名杨难。
诵此莲花偈，数满百亿千。
身坏口不坏，舌根如红莲。
颅骨今不见，石函尚存焉。
粉壁有吴画，笔彩依旧鲜。
素屏有褚书，墨色如新干。
灵境与异迹，周览无不殚。
一游五昼夜，欲返仍盘桓。
我本山中人，误为时网牵。
牵率使读书，推挽令効官。
既登文字科，又忝谏诤员。
拙直不合时，无益同素餐。
以此自慙惕，戚戚常寡欢。
无成心力尽，未老形骸残。
今来脱簪组，始觉离忧患。
及为山水游，弥得纵疎顽。
野麋断羁绊，行走无拘挛。
池鱼放入海，一往何时还。
身着居士衣，手把南华篇。
终来此山住，永谢区中缘。
我今四十余，从此终身闲。
若以七十期，犹得三十年。','',''),('quantangshi-22183','酬张十八访宿见赠','白居易','quantangshi','','卷23','昔我为近臣，君常稀到门。
今我官职冷，君君来往频。
我受狷介性，立为顽拙身。
平生虽寡合，合即无缁磷。
况君秉高义，富贵视如云。
五侯三相家，眼冷不见君。
问其所与游，独言韩舍人。
其次即及我，我愧非其伦。
胡为谬相爱，岁晚逾勤勤。
落然颓檐下，一话夜达晨。
牀单食味薄，亦不嫌我贫。
日高上马去，相顾犹逡巡。
长安久无雨，日赤风昏昏。
怜君将病眼，为我犯埃尘。
远从延康里，来访曲江滨。
所重君子道，不独愧相亲。','',''),('quantangshi-22184','朝归书寄元八','白居易','quantangshi','','卷23','进入合前拜，退就廊下餐。
归来昭国里，人卧马歇鞍。
却睡至日午，起坐心浩然。
况当好时节，雨后清和天。
柿树绿阴合，王家庭院宽。
瓶中鄠县酒，墙上终南山。
独眠仍独坐，开襟当风前。
禅师与诗客，次第来相看。
要语连夜语，须眠终日眠。
除非奉朝谒，此外无别牵。
年长身且健，官贫心甚安。
幸无急病痛，不至苦饥寒。
自此聊以适，外缘不能干。
唯应静者信，难为动者言。
台中元侍御，早晚作郎官。
未作郎官际，无人相伴闲。','',''),('quantangshi-22185','酬吴七见寄','白居易','quantangshi','','卷23','曲江有病客，寻常多掩关。
又闻马死来，不出身更闲。
闻有送书者，自起出门看。
素缄署丹字，中有琼瑶篇。
口吟耳自听，当暑忽翛然。
似漱寒玉冰，如闻商风弦。
首章叹时节，末句思笑言。
嬾慢不相访，隔街如隔山。
尝闻陶潜语，心远地自偏。
君住安邑里，左右车徒喧。
竹药闭深院，琴尊开小轩。
谁知市南地，转作壶中天。
君本上清人，名在石堂间。
不知有何过，谪作人间仙。
常恐岁月满，飘然归紫烟。
莫忘蜉蝣内，进士有同年。','',''),('quantangshi-22186','昭国闲居','白居易','quantangshi','','卷23','贫闲日高起，门巷昼寂寂。
时暑放朝参，天阴少人客。
槐花满田地，仅绝人行迹。
独在一牀眠，清凉风雨夕。
勿嫌坊曲远，近即多牵役。
勿嫌禄俸薄，厚即多忧责。
平生尚恬旷，老大宜安适。
何以养吾真，官闲居处僻。','',''),('quantangshi-22187','喜陈兄至','白居易','quantangshi','','卷23','黄鸟啼欲歇，青梅结半成。
坐怜春物尽，起入东园行。
携觞嬾独酌，忽闻叩门声。
闲人犹喜至，何况是陈兄。
从容尽日语，稠叠长年情。
勿轻一盏酒，可以话平生。','',''),('quantangshi-22188','赠杓直','白居易','quantangshi','','卷23','世路重禄位，栖栖者孔宣。
人情爱年寿，夭死者颜渊。
二人如何人，不奈命与天。
我今信多幸，抚己愧前贤。
已年四十四，又为五品官。
况兹知足外，别有所安焉。
早年以身代，直赴逍遥篇。
近岁将心地，回向南宗禅。
外顺世间法，内脱区中缘。
进不厌朝市，退不恋人寰。
自吾得此心，投足无不安。
体非导引适，意无江湖闲。
有兴或饮酒，无事多掩关。
寂静夜深坐，安稳日高眠。
秋不苦长夜，春不惜流年。
委形老小外，忘怀生死间。
昨日共君语，与余心膂然。
此道不可道，因君聊强言。','',''),('quantangshi-22189','寄张十八','白居易','quantangshi','','卷23','饥止一箪食，渴止一壶浆。
出入止一马，寝兴止一牀。
此外无长物，于我有若亡。
胡然不知足，名利心遑遑。
念兹弥嬾放，积习遂为常。
经旬不出门，竟日不下堂。
同病者张生，贫僻住延康。
慵中每相忆，此意未能忘。
迢迢青槐街，相去八九坊。
秋来未相见，应有新诗章。
早晚来同宿，天气转清凉。','',''),('quantangshi-22190','题玉泉寺','白居易','quantangshi','','卷23','湛湛玉泉色，悠悠浮云身。
闲心对定水，清静两无尘。
手把青筇杖，头戴白纶巾。
兴尽下山去，知我是谁人。','',''),('quantangshi-22191','朝回游城南','白居易','quantangshi','','卷23','朝退马未困，秋初日犹长。
回辔城南去，郊野正清凉。
水竹夹小径，萦回绕川冈。
仰看晚山色，俯弄秋泉光。
青松系我马，白石为我牀。
常时簪组累，此日和身忘。
旦随鵷鹭末，暮游鸥鹤旁。
机心一以尽，两处不乱行。
谁辨心与迹，非行亦非藏。','',''),('quantangshi-22192','舟行','白居易','quantangshi','','卷23','帆影日渐高，闲眠犹未起。
起问鼓枻人，已行三十里。
船头有行竈，炊稻烹红鲤。
饱食起婆娑，盥漱秋江水。
平生沧浪意，一旦来游此。
何况不失家，舟中载妻子。','',''),('quantangshi-22193','湓浦早冬','白居易','quantangshi','','卷23','浔阳孟冬月，草木未全衰。
祗抵长安陌，凉风八月时。
日西湓水曲，独行吟旧诗。
蓼花始零落，蒲叶稍离披。
但作城中想，何异曲江池。','',''),('quantangshi-22194','江州雪','白居易','quantangshi','','卷23','新雪满前山，初晴好天气。
日西骑马出，忽有京都意。
城柳方缀花，檐冰才结穗。
须臾风日暖，处处皆飘坠。
行吟赏未足，坐叹销何易。
犹胜岭南看，雰雰不到地。','',''),('quantangshi-22195','题浔阳楼','白居易','quantangshi','','卷23','常爱陶彭泽，文思何高玄。
又怪韦江州，诗情亦清闲。
今朝登此楼，有以知其然。
大江寒见底，匡山青倚天。
深夜湓浦月，平旦炉峰烟。
清辉与灵气，日夕供文篇。
我无二人才，孰为来其间。
因高偶成句，俯仰愧江山。','',''),('quantangshi-22196','访陶公旧宅','白居易','quantangshi','','卷23','垢尘不汚玉，灵凤不啄膻。
呜呼陶靖节，生彼晋宋间。
心实有所守，口终不能言。
永惟孤竹子，拂衣首阳山。
夷齐各一身，穷饿未为难。
先生有五男，与之同饥寒。
肠中食不充，身上衣不完。
连征竟不起，斯可谓真贤。
我生君之后，相去五百年。
每读五柳传，目想心拳拳。
昔常咏遗风，着为十六篇。
今来访故宅，森若君在前。
不慕尊有酒，不慕琴无弦。
慕君遗荣利，老死此丘园。
柴桑古村落，栗里旧山川。
不见篱下菊，但余墟中烟。
子孙虽无闻，族氏犹未迁。
每逢姓陶人，使我心依然。','',''),('quantangshi-22197','北亭','白居易','quantangshi','','卷23','庐宫山下州，湓浦沙边宅。
宅北倚高冈，迢迢数千尺。
上有青青竹，竹间多白石。
茅亭居上头，豁达门四辟。
前楹卷帘箔，北牖施牀席。
江风万里来，吹我凉淅淅。
日高公府归，巾笏随手掷。
脱衣恣搔首，坐卧任所适。
时倾一杯酒，旷望湖天夕。
口咏独酌谣，目送归飞翮。
慙无出尘操，未免折腰役。
偶获此闲居，谬似高人迹。','',''),('quantangshi-22198','泛湓水','白居易','quantangshi','','卷23','四月未全热，麦凉江气秋。
湖山处处好，最爱湓水头。
湓水从东来，一派入江流。
可怜似萦带，中有随风舟。
命酒一临泛，舍鞍扬棹讴。
放回岸傍马，去逐波间鸥。
烟浪始渺渺，风襟亦悠悠。
初疑上河汉，中若寻瀛洲。
汀树绿拂地，沙草芳未休。
青萝与紫葛，枝蔓垂相樛。
系缆步平岸，回头望江州。
城雉映水见，隐隐如蜃楼。
日入意未尽，将归复少留。
到官行半岁，今日方一游。
此地来何暮，可以写吾忧。','',''),('quantangshi-22199','答故人','白居易','quantangshi','','卷23','故人对酒叹，叹我在天涯。
见我昔荣遇，念我今蹉跎。
问我为司马，官意复如何。
答云且勿叹，听我为君歌。
我本蓬荜人，鄙贱剧泥沙。
读书未百卷，信口嘲风花。
自从筮仕来，六命三登科。
顾慙虚劣姿，所得亦已多。
散员足庇身，薄俸可资家。
省分辄自愧，岂为不遇耶。
烦君对杯酒，为我一咨蹉。','',''),('quantangshi-22200','官舍内新凿小池','白居易','quantangshi','','卷23','帘下开小池，盈盈水方积。
中底铺白沙，四隅甃青石。
勿言不深广，但取幽人适。
泛滟微雨朝，泓澄明月夕。
岂无大江水，波浪连天白。
未如牀席间，方丈深盈尺。
清浅可狎弄，昏烦聊漱涤。
最爱晓暝时，一片秋天碧。','',''),('quantangshi-22201','宿简寂观','白居易','quantangshi','','卷23','岩白云尚屯，林红叶初陨。
秋光引闲步，不知身远近。
夕投灵洞宿，卧觉尘机泯。
名利心既忘，市朝梦亦尽。
暂来尚如此，况乃终身隐。
何以疗夜饥，一匙云母粉。','',''),('quantangshi-22202','读谢灵运诗','白居易','quantangshi','','卷23','吾闻达士道，穷通顺冥数。
通乃朝廷来，穷即江湖去。
谢公才廓落，与世不相遇。
壮志郁不用，须有所泄处。
泄为山水诗，逸韵谐奇趣。
大必笼天海，细不遗草树。
岂惟玩景物，亦欲摅心素。
往往即事中，未能忘兴谕。
因知康乐作，不独在章句。','',''),('quantangshi-22203','北亭独宿','白居易','quantangshi','','卷23','悄悄壁下牀，纱笼耿残烛。
夜半独眠觉，疑在僧房宿。','',''),('quantangshi-22204','约心','白居易','quantangshi','','卷23','黑鬓丝雪侵，青袍尘土涴。
兀兀复腾腾，江城一上佐。
朝就高斋上，熏然负暄卧。
晚下小池前，澹然临水坐。
已约终身心，长如今日过。','',''),('quantangshi-22205','晚望','白居易','quantangshi','','卷23','江城寒角动，沙洲夕鸟还。
独在高亭上，西南望远山。','',''),('quantangshi-22206','早春','白居易','quantangshi','','卷23','雪消冰又释，景和风复暄。
满庭田地湿，荠叶生墙根。
官舍悄无事，日西斜掩门。
不开庄老卷，欲与何人言。','',''),('quantangshi-22207','春寝','白居易','quantangshi','','卷23','何处春暄来？微和生血气。
气熏肌骨畅，东窗一昏睡。
是时正月晦，假日无公事。
烂熳不能休，自午将及未。
缅思少健日，甘寝常自恣。
一从衰疾来，枕上无此味。','',''),('quantangshi-22208','睡起晏坐','白居易','quantangshi','','卷23','后亭昼眠足，起坐春景暮。
新觉眼犹昏，无思心正住。
澹寂归一性，虚闲遗万虑。
了然此时心，无物可譬喻。
本是无有乡，亦名不用处。
行禅与坐忘，同归无异路。','',''),('quantangshi-22209','咏怀','白居易','quantangshi','','卷23','尽日松下坐，有时池畔行。
行立与坐卧，中怀澹无营。
不觉流年过，亦任白发生。
不为世所薄，安得遂闲情。','',''),('quantangshi-22210','春游二林寺','白居易','quantangshi','','卷23','下马二林寺，翛然进轻策。
朝为公府吏，暮作灵山客。
二月匡庐北，冰雪始消释。
阳丛抽茗芽，阴窦泄泉脉。
熙熙风土暖，蔼蔼云岚积。
散作万壑春，凝为一气碧。
身闲易飘泊，官散无牵迫。
缅彼十八人，古今同此适。
是年淮寇起，处处兴兵革。
智士劳思谋，戎臣苦征役。
独有不才者，山中弄泉石。','',''),('quantangshi-22211','出山吟','白居易','quantangshi','','卷23','朝咏游仙诗，暮歌采薇曲。
卧云坐白石，山中十五宿。
行随出洞水，回别缘岩竹。
早晚重来游，心期瑶草绿。','',''),('quantangshi-22212','岁暮','白居易','quantangshi','','卷23','已任时命去，亦从岁月除。
中心一调伏，外累尽空虚。
名宦意已矣，林泉计何如。
拟近东林寺，溪边结一庐。','',''),('quantangshi-22213','闻早莺','白居易','quantangshi','','卷23','日出眠未起，屋头闻早莺。
忽如上林晓，万年枝上鸣。
忆为近臣时，秉笔直承明。
春深视草暇，旦暮闻此声。
今闻在何处，寂莫浔阳城。
鸟声信如一，分别在人情。
不作天涯意，岂殊禁中听。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22214','栽杉','白居易','quantangshi','','卷23','劲叶森利劒，孤茎挺端标。
才高四五尺，势若干青霄。
移栽东窗前，爱尔寒不凋。
病夫卧相对，日夕闲萧萧。
昨为山中树，今为檐下条。
虽然遇赏玩，无乃近尘嚣。
犹胜涧谷底，埋没随众樵。
不见郁郁松，委质山上苗。','',''),('quantangshi-22215','过李生','白居易','quantangshi','','卷23','苹小蒲叶短，南湖春水生。
子近湖边住，静境称高情。
我为郡司马，散拙无所营。
使君知性野，衙退任闲行。
行携小榼出，逢花辄独倾。
半酣到子舍，下马扣柴荆。
何以引我步，绕篱竹万茎。
何以醒我酒，吴音吟一声。
须臾进野饭，饭稻茹芹英。
白瓯青竹箸，俭洁无膻腥。
欲去复裴回，夕鸦已飞鸣。
何当重游此，待君湖水平。','',''),('quantangshi-22216','咏意','白居易','quantangshi','','卷23','常闻南华经，巧劳智忧愁。
不如无能者，饱食但遨游。
平生爱慕道，今日近此流。
自来浔阳郡，四序忽已周。
不分物黑白，但与时沈浮。
朝餐夕安寝，用是为身谋。
此外即闲放，时寻山水幽。
春游慧远寺，秋上庾公楼。
或吟诗一章，或饮茶一瓯。
身心一无系，浩浩如虚舟。
富贵亦有苦，苦在心危忧。
贫贱亦有乐，乐在身自由。','',''),('quantangshi-22217','食笋','白居易','quantangshi','','卷23','此州乃竹乡，春笋满山谷。
山夫折盈抱，抱来早市鬻。
物以多为贱，双钱易一束。
置之炊甑中，与饭同时熟。
紫箨坼故锦，素肌擘新玉。
每日遂加餐，经时不思肉。
久为京洛客，此味常不足。
且食勿踟蹰，南风吹作竹。','',''),('quantangshi-22218','游石门涧','白居易','quantangshi','','卷23','石门无旧径，披榛访遗迹。
时逢山水秋，清辉如古昔。
常闻慧远辈，题诗此岩壁。
云覆莓苔封，苍然无处觅。
萧疎野生竹，崩剥多年石。
自从东晋后，无复人游历。
独有秋涧声，潺湲空旦夕。','',''),('quantangshi-22219','招东邻','白居易','quantangshi','','卷23','小榼二升酒，新簟六尺牀。
能来夜话否，池畔欲秋凉。','',''),('quantangshi-22220','题元十八溪亭','白居易','quantangshi','','卷23','怪君不喜仕，又不游州里。
今日到幽居，了然知所以。
宿君石溪亭，潺湲声满耳。
饮君螺杯酒，醉卧不能起。
见君五老峰，益悔居城市。
爱君三男儿，始叹身无子。
余方炉峰下，结室为居士。
山北与山东，往来从此始。','',''),('quantangshi-22221','香炉峰下新置草堂即事咏怀题于石上','白居易','quantangshi','','卷23','香炉峰北面，遗爱寺西偏。
白石何凿凿，清流亦潺潺。
有松数十株，有竹千余竿。
松张翠繖盖，竹倚青琅玕。
其下无人居，悠哉多岁年。
有时聚猨鸟，终日空风烟。
时有沈冥子，姓白字乐天。
平生无所好，见此心依然。
如获终老地，忽乎不知还。
架岩结茅宇，斵壑开茶园。
何以洗我耳，屋头飞落泉。
何以净我眼，砌下生白莲。
左手携一壶，右手挈五弦。
傲然意自足，箕踞于其间。
兴酣仰天歌，歌中聊寄言。
言我本野夫，误为世网牵。
时来昔捧日，老去今归山。
倦鸟得茂树，涸鱼返清源。
舍此欲焉往，人间多险艰。','',''),('quantangshi-22222','草堂前新开一池养鱼种荷日有幽趣','白居易','quantangshi','','卷23','淙淙三峡水，浩浩万顷陂。
未如新塘上，微风动涟漪。
小萍加泛泛，初蒲正离离。
红鲤二三寸，白莲八九枝。
绕水欲成径，护堤方插篱。
已被山中客，呼作白家池。','',''),('quantangshi-22223','白云期','白居易','quantangshi','','卷23','三十气太状，胷中多是非。
六十身太老，四体不支持。
四十至五十，正是退闲时。
年长识命分，心慵少营为。
见酒兴犹在，登山力未衰。
吾年幸当此，且与白云期。','',''),('quantangshi-22224','登香炉峰顶','白居易','quantangshi','','卷23','迢迢香炉峰，心存耳目想。
终年牵物役，今日方一往。
攀萝蹋危石，手足劳俛仰。
同游三四人，两人不敢上。
上到峰之顶，目眩神怳怳。
高低有万寻，阔狭无数丈。
不穷视听界，焉识宇宙广。
江水细如绳，湓城小于掌。
纷吾何屑屑，未能脱尘鞅。
归去思自嗟，低头入蚁壤。','',''),('quantangshi-22225','答崔侍郎钱舍人书问因继以诗','白居易','quantangshi','','卷23','旦暮两蔬食，日中一闲眠。
便是了一日，如此已三年。
心不择时适，足不拣地安。
穷通与远近，一贯无两端。
常见今之人，其心或不然。
在劳则念息，处静已思喧。
如是用身心，无乃自伤残。
坐输忧恼便，安得形神全。
吾有二道友，蔼蔼崔与钱。
同飞青云路，独堕黄泥泉。
岁暮物万变，故情何不迁？
应为平生心，与我同一源。
帝乡远于日，美人高在天。
谁谓万里别，常若在目前。
泥泉乐者鱼，云路游者鸾。
勿言云泥异，同在逍遥间。
因君问心地，书后偶成篇。
慎勿说向人，人多笑此言。','',''),('quantangshi-22226','烹葵','白居易','quantangshi','','卷23','昨卧不夕食，今起乃朝饥。
贫厨何所有，炊稻烹秋葵。
红粒香复輭，绿英滑且肥。
饥来止于饱，饱后复何思。
忆昔荣遇日，迨今穷退时。
今亦不冻馁，昔亦无余资。
口既不减食，身又不减衣。
抚心私自问，何者是荣衰。
勿学常人意，其间分是非。','',''),('quantangshi-22227','小池二首 一','白居易','quantangshi','','卷23','昼倦前斋热，晚爱小池清。
映林余景没，近水微凉生。
坐把蒲葵扇，闲吟三两声。','',''),('quantangshi-22228','小池二首 二','白居易','quantangshi','','卷23','有意不在大，湛湛方丈余。
荷侧泻清露，萍开见游鱼。
每一临此坐，忆归青溪居。','',''),('quantangshi-22229','闭关','白居易','quantangshi','','卷23','我心忘世久，世亦不我干。
遂成一无事，因得长掩关。
掩关来几时，仿髴二三年。
着书已盈帙，生子欲能言。
始悟身向老，复悲世多艰。
回顾趋时者，役役尘壤间。
岁暮竟何得，不如且安闲。','',''),('quantangshi-22230','弄龟罗','白居易','quantangshi','','卷23','有侄始六岁，字之为阿龟。
有女生三年，其名曰罗儿。
一始学笑语，一能诵歌诗。
朝戏抱我足，夜眠枕我衣。
汝生何其晚，我年行已衰。
物情小可念，人意老多慈。
酒美竟须坏，月圆终有亏。
亦如恩爱缘，乃是忧恼资。
举世同此累，吾安能去之。','',''),('quantangshi-22231','截树','白居易','quantangshi','','卷23','种树当前轩，树高柯叶繁。
惜哉远山色，隐此蒙笼间。
一朝持斧斤，手自截其端。
万叶落头上，千峰来面前。
忽似决云雾，豁达覩青天。
又如所念人，久别一款颜。
始有清风至，稍见飞鸟还。
开怀东南望，目远心辽然。
人各有偏好，物莫能两全。
岂不爱柔条，不如见青山。','',''),('quantangshi-22232','望江楼上作','白居易','quantangshi','','卷23','江畔百尺楼，楼前千里道。
凭高望平远，亦足舒怀抱。
驿路使憧憧，关防兵草草。
及兹多事日，尤觉闲人好。
我年过不惑，休退诚非早。
从此拂尘衣，归山未为老。','',''),('quantangshi-22233','题座隅','白居易','quantangshi','','卷23','手不任执殳，肩不能荷锄。
量力揆所用，曾不敌一夫。
幸因笔研功，得升仕进途。
历官凡五六，禄俸及妻孥。
左右有兼仆，出入有单车。
自奉虽不厚，亦不至饥劬。
若有人及此，傍观为何如。
虽贤亦为幸，况我鄙且愚。
伯夷古贤人，鲁山亦其徒。
时哉无奈何，俱化为饿殍。
念彼益自愧，不敢忘斯须。
平生荣利心，破灭无遗余。
犹恐尘妄起，题此于座隅。','',''),('quantangshi-22234','昔与微之在朝日同蓄休退之心迨今十年沦落老人追寻前约且结后期','白居易','quantangshi','','卷23','往子为御史，伊余忝拾遗。
皆逢盛明代，俱登清近司。
予系玉为佩，子曳绣为衣。
从容香烟下，同侍白玉墀。
朝见宠者辱，暮见安者危。
纷纷无退者，相顾令人悲。
宦情君早厌，世事我深知。
常于荣显日，已约林泉期。
况今各流落，身病齿发衰。
不作卧云计，携手欲何之。
待君女嫁后，及我官满时。
稍无骨肉累，粗有渔樵资。
岁晚青山路，白首期同归。','',''),('quantangshi-22235','垂钓','白居易','quantangshi','','卷23','临水一长啸，忽思十年初。
三登甲乙第，一入承明庐。
浮生多变化，外事有盈虚。
今来伴江叟，沙头坐钓鱼。','',''),('quantangshi-22236','晚燕','白居易','quantangshi','','卷23','百鸟乳雏毕，秋燕独蹉跎。
去社日已近，衔泥意如何。
不悟时节晚，徒施工用多。
人间事亦尔，不独燕营窠。','',''),('quantangshi-22237','赎鸡','白居易','quantangshi','','卷23','清晨临江望，水禽正喧繁。
凫雁与鸥鹭，游扬戏朝暾。
适有鬻鸡者，挈之来远村。
飞鸣彼何乐，窘束此何冤。
喔喔十四雏，罩缚同一樊。
足伤金距蹜，头抢花冠飜。
经宿废饮啄，日高诣屠门。
迟回未死间，饥渴欲相吞。
常慕古人道，仁信及鱼豚。
见兹生恻隐，赎放双林园。
开笼解索时，鸡鸡听我言。
与尔镪三百，小惠何足论。
莫学衔环雀，崎岖谩报恩。','',''),('quantangshi-22238','秋日怀杓直','白居易','quantangshi','','卷23','晚来天色好，独出江边步。
忆与李舍人，曲江相近住。
常云遇清景，必约同幽趣。
若不访我来，还须觅君去。
开眉笑相见，把手期何处。
西寺老胡僧，南园乱松树。
携持小酒榼，吟咏新诗句。
同出复同归，从朝直至暮。
风雨忽消散，江山眇回互。
浔阳与涔阳，相望空云雾。
心期自乖旷，时景还如故。
今日郡斋中，秋光谁共度。','',''),('quantangshi-22239','食后','白居易','quantangshi','','卷23','食罢一觉睡，起来两瓯茶。
举头看日影，已复西南斜。
乐人惜日促，忧人厌年赊。
无忧无乐者，长短任生涯。','',''),('quantangshi-22240','齐物二首 一','白居易','quantangshi','','卷23','青松高百尺，绿蕙低数寸。
同生大块间，长短各有分。
长者不可退，短者不可进。
若用此理推，穷通两无闷。','',''),('quantangshi-22241','齐物二首 二','白居易','quantangshi','','卷23','椿寿八千春，槿花不经宿。
中间复何有，冉冉孤竹生。
竹身三年老，竹色四时绿。
虽谢椿有余，犹胜槿不足。','',''),('quantangshi-22242','山下宿','白居易','quantangshi','','卷23','独到山下宿，静向月中行。
何处水边碓，夜舂云母声。','',''),('quantangshi-22243','题旧写真图','白居易','quantangshi','','卷23','我昔三十六，写貌在丹青。
我今四十六，衰顇卧江城。
岂比十年老，曾与众苦并。
一照旧图画，无复昔仪形。
形影默相顾，如弟对老兄。
况使他人见，能不昧平生。
羲和鞭日走，不为我少停。
形骸属日月，老去何足惊。
所恨凌烟阁，不得画功名。','',''),('quantangshi-22244','闲居','白居易','quantangshi','','卷23','肺病不饮酒，眼昏不读书。
端然无所作，身意闲有余。
鸡栖篱落晚，雪映林木疎。
幽独已云极，何必山中居。','',''),('quantangshi-22245','对酒示行简','白居易','quantangshi','','卷23','今旦一尊酒，欢畅何怡怡。
此乐从中来，他人安得知。
兄弟唯二人，远别恒苦悲。
今春自巴峡，万里平安归。
复有双幼妹，笄年未结褵。
昨日嫁娶毕，良人皆可依。
忧念两消释，如刀断羁縻。
身轻心无系，忽欲凌空飞。
人生苟有累，食肉常如饥。
我心既无苦，饮水亦可肥。
行简劝尔酒，停杯听我辞。
不叹乡国远，不嫌官禄微。
但愿我与尔，终老不相离。','',''),('quantangshi-22246','咏怀','白居易','quantangshi','','卷23','冉牛与颜渊，卞和与马迁。
或罹天六极，或被人刑残。
顾我信为幸，百骸且完全。
五十不为夭，吾今欠数年。
知分心自足，委顺身常安。
故虽穷退日，而无戚戚颜。
昔有荣先生，从事于其间。
今我不量力，举心欲攀援。
穷通不由己，欢戚不由天。
命即无奈何，心可使泰然。
且务由己者，省躬谅非难。
勿问由天者，天高难与言。','',''),('quantangshi-22247','夜琴','白居易','quantangshi','','卷23','蜀[桐]木性实，楚丝音韵清。
调慢弹且缓，夜深十数声。
入耳澹无味，惬心潜有情。
自弄还自罢，亦不要人听。','',''),('quantangshi-22248','山中独吟','白居易','quantangshi','','卷23','人各有一癖，我癖在章句。
万缘皆已消，此病独未去。
每逢美风景，或对好亲故。
高声咏一篇，恍若与神遇。
自为江上客，半在山中住。
有时新诗成，独上东岩路。
身倚白石崖，手攀青桂树。
狂吟惊林壑，猿鸟皆窥覰。
恐为世所嗤，故就无人处。','',''),('quantangshi-22249','达理二首 一','白居易','quantangshi','','卷23','何物壮不老，何时穷不通。
如彼音与律，宛转旋为宫。
我命独何薄，多悴而少丰。
当壮已先衰，暂泰还长穷。
我无奈命何，委顺以待终。
命无奈我何，方寸如虚空。
瞢然与化俱，混然与俗同。
谁能坐自苦，龃龉于其中。','',''),('quantangshi-22250','达理二首 二','白居易','quantangshi','','卷23','舒姑化为泉，牛哀病作虎。
或柳生肘间，或男变为女。
鸟兽及水木，本不与民伍。
胡然生变迁，不待死归土。
百骸是己物，尚不能为主。
况彼时命间，倚伏何足数。
时来不可遏，命去焉能取。
唯当养浩然，吾闻达人语。','',''),('quantangshi-22251','湖亭晚望残水','白居易','quantangshi','','卷23','湖上秋泬寥，湖边晚萧瑟。
登亭望湖水，水缩湖底出。
清渟得早霜，明灭浮残日。
流注随地势，洼坳无定质。
泓澄白龙卧，宛转青蛇屈。
破镜折劒头，光芒又非一。
久为山水客，见尽幽奇物。
及来湖亭望，此状难谈悉。
乃知天地间，胜事殊未毕。','',''),('quantangshi-22252','郭虚舟相访','白居易','quantangshi','','卷23','朝暖就南轩，暮寒归后屋。
晚酒一两杯，夜棊三数局。
寒灰埋暗火，晓焰凝残烛。
不嫌贫冷人，时来同一宿。','',''),('quantangshi-22253','长庆二年七月自中书舍人出守杭州路次蓝溪作','白居易','quantangshi','','卷23','太原一男子，自顾庸且鄙。
老逢不次恩，洗拔出泥滓。
既居可言地，愿助朝廷理。
伏合三上章，戆愚不称旨。
圣人存大体，优贷容不死。
凤诏停舍人，鱼书除刺史。
冥怀齐宠辱，委顺随行止。
我自得此心，于兹十年矣。
余杭乃名郡，郡郭临江汜。
已想海门山，潮声来入耳。
昔予贞元末，羇旅曾游此。
甚觉太守尊，亦谙鱼酒美。
因生江海兴，每羡沧浪水。
尚拟拂衣行，况今兼禄仕。
青山峰峦接，白日烟尘起。
东道既不通，改辕遂南指。
自秦穷楚越，浩荡五千里。
闻有贤主人，而多好山水。
是行颇为惬，所历良可纪。
策马度蓝溪，胜游从此始。','',''),('quantangshi-22254','初出城留别','白居易','quantangshi','','卷23','朝从紫禁归，暮出青门去。
勿言城东陌，便是江南路。
扬鞭簇车马，挥手辞亲故。
我生本无乡，心安是归处。','',''),('quantangshi-22255','过骆山人野居小池','白居易','quantangshi','','卷23','茅覆环堵亭，泉添方丈沼。
红芳照水荷，白颈观鱼鸟。
拳石苔苍翠，尺波烟杳渺。
但问有意无，勿论池大小。
门前车马路，奔走无昏晓。
名利驱人心，贤愚同扰扰。
善哉骆处士，安置身心了。
何乃独多君，丘园居者少。','',''),('quantangshi-22256','宿清源寺','白居易','quantangshi','','卷23','往谪浔阳去，夜憩辋溪曲。
今为钱塘行，重经兹寺宿。
尔来几何岁，溪草二八绿。
不见旧房僧，苍然新树木。
虚空走日月，世界迁陵谷。
我生寄其间，孰能逃倚伏。
随缘又南去，好住东廊竹。','',''),('quantangshi-22257','宿蓝溪对月','白居易','quantangshi','','卷23','昨夜凤池头，今夜蓝溪口。
明月本无心，行人自回首。
新秋松影下，半夜钟声后。
清影不宜昏，聊将茶代酒。','',''),('quantangshi-22258','自秦望赴五松驿马上偶睡睡觉成吟','白居易','quantangshi','','卷23','长途发已久，前馆行未至。
体倦目已昏，瞌然遂成睡。
右袂尚垂鞭，左手暂委辔。
忽觉问仆夫，才行百步地。
形神分处所，迟速相乖异。
马上几多时，梦中无限事。
诚哉达人语，百龄同一寐。','',''),('quantangshi-22259','邓州路中作','白居易','quantangshi','','卷23','萧萧谁家村，秋棃叶半坼。
漠漠谁家园，秋韭花初白。
路逢故里物，使我嗟行役。
不归渭北村，又作江南客。
去乡徒自苦，济世终无益。
自问波上萍，何如涧中石。','',''),('quantangshi-22260','朱藤杖紫骢吟','白居易','quantangshi','','卷23','拄上山之下，骑下山之下。
江州去日朱藤杖，忠州归日紫骢马。
天生二物济我穷，我生合是栖栖者。','',''),('quantangshi-22261','桐树馆重题','白居易','quantangshi','','卷23','阶前下马时，梁上题诗处。
惨澹病使君，萧疎老松树。
自嗟还自哂，又向杭州去。','',''),('quantangshi-22262','过紫霞兰若','白居易','quantangshi','','卷23','我爱此山头，及此三登历。
紫霞旧精舍，寥落空泉石。
朝市日喧隘，云林长悄寂。
犹存住寺僧，肯有归山客。','',''),('quantangshi-22263','感旧纱帽','白居易','quantangshi','','卷23','昔君乌纱帽，赠我白头翁。
帽今在顶上，君已归泉中。
物故犹堪用，人亡不可逢。
岐山今夜月，坟树正秋风。','',''),('quantangshi-22264','思竹窗','白居易','quantangshi','','卷23','不忆西省松，不忆南宫菊。
惟忆新昌堂，萧萧北窗竹。
窗间枕簟在，来后何人宿。','',''),('quantangshi-22265','马上作','白居易','quantangshi','','卷23','处世非不遇，荣身颇有余。
勋为上柱国，爵乃朝大夫。
自问有何才，两入承明庐。
又问有何政，再驾朱轮车。
矧予东山人，自惟朴且疎。
弹琴复有酒，且慕嵇阮徒。
暗被乡里荐，误上贤能书。
一列朝士籍，遂为世网拘。
高有罾缴忧，下有陷穽虞。
每觉宇宙窄，未尝心体舒。
蹉跎二十年，颔下生白须。
何言左迁去，尚获专城居。
杭州五千里，往若投渊鱼。
虽未脱簪组，且来泛江湖。
吴中多诗人，亦不少酒酤。
高声咏篇什，大笑飞杯盂。
五十未全老，尚可且欢娱。
用兹送日月，君以为何如。
秋风起江上，白日落路隅。
回首语五马，去矣勿踟蹰。','',''),('quantangshi-22266','秋蝶','白居易','quantangshi','','卷23','秋花紫蒙蒙，秋蝶黄茸茸。
花低蝶新小，飞戏丛西东。
日暮凉风来，纷纷花落丛。
夜深白露冷，蝶已死丛中。
朝生夕俱死，气类各相从。
不见千年鹤，多栖百丈松。','',''),('quantangshi-22267','登商山最高顶','白居易','quantangshi','','卷23','高高此山顶，四望唯烟云。
下有一条路，通达楚与秦。
或名诱其心，或利牵其身。
乘者及负者，来去何云云。
我亦斯人徒，未能出嚣尘。
七年三往复，何得笑他人。','',''),('quantangshi-22268','枯桑','白居易','quantangshi','','卷23','道傍老枯树，枯来非一朝。
皮黄外尚活，心黑中先焦。
有似多忧者，非因外火烧。','',''),('quantangshi-22269','山路偶兴','白居易','quantangshi','','卷23','筋力未全衰，仆马不至弱。
又多山水趣，心赏非寂莫。
扪萝上烟岭，蹋石穿云壑。
谷鸟晚仍啼，洞花秋不落。
提笼复携榼，遇胜时停泊。
泉憩茶数瓯，岚行酒一酌。
独吟还独啸，此兴殊未恶。
假使在城时，终年有何乐。','',''),('quantangshi-22270','山雉','白居易','quantangshi','','卷23','五步一啄草，十步一饮水。
适性遂其生，时哉山梁雉。
梁上无罾缴，梁下无鹰鹯。
雌雄与羣雏，皆得终天年。
嗟嗟笼下鸡，及彼池中雁。
既有稻粱恩，必有牺牲患。','',''),('quantangshi-22271','初下汉江舟中作寄两省给舍','白居易','quantangshi','','卷23','秋水淅红粒，朝烟烹白鳞。
一食饱至夜，一卧安达晨。
晨无朝谒劳，夜无直宿勤。
不知两掖客，何似扁舟人。
尚想到郡日，且称守土臣。
犹须副忧寄，恤隐安疲民。
朞年庶报政，三年当退身。
终使沧浪水，濯吾缨上尘。','',''),('quantangshi-22272','自蜀江至洞庭湖口有感而作','白居易','quantangshi','','卷23','江从西南来，浩浩无旦夕。
长波逐若泻，连山凿如劈。
千年不壅溃，万姓无垫溺。
不尔民为鱼，大哉禹之绩。
导岷既艰远，距海无咫尺。
胡为不讫功，余水斯委积。
洞庭与青草，大小两相敌。
混合万丈深，淼茫千里白。
每岁秋夏时，浩大吞七泽。
水族窟穴多，农人土地窄。
我今尚嗟叹，禹岂不爱惜。
邈未究其由，想古观遗迹。
疑此苗人顽，恃险不终役。
帝亦无奈何，留患与今昔。
水流天地内，如身有血脉。
滞则为疽疣，治之在针石。
安得禹复生，为唐水官伯。
手提倚天劒，重来亲指画。
疏河似翦纸，决壅同裂帛。
渗作膏腴田，蹋平鱼鼈宅。
龙宫变闾里，水府生禾麦。
坐添百万户，书我司徒籍。','',''),('quantangshi-22273','初领郡政衙退登东楼作','白居易','quantangshi','','卷23','鳏惸心所念，简牍手自操。
何言符竹贵，未免州县劳。
赖是余杭郡，台榭绕官曹。
凌晨亲政事，向晚恣游遨。
山冷微有雪，波平未生涛。
水心如镜面，千里无纤毫。
直下江最阔，近东楼更高。
烦襟与滞念，一望皆遁逃。','',''),('quantangshi-22274','清调吟','白居易','quantangshi','','卷23','索索风戒寒，沈沈日藏耀。
劝君饮浊醪，听我吟清调。
芳节变穷阴，朝光成夕照。
与君生此世，不合长年少。
今晨从此过，明日安能料。
若不结跏禅，即须开口笑。','',''),('quantangshi-22275','狂歌词','白居易','quantangshi','','卷23','明月照君席，白露霑我衣。
劝君酒杯满，听我狂歌词。
五十已后衰，二十已前痴。
昼夜又分半，其间几何时。
生前不欢乐，死后有余赀。
焉用黄墟下，珠衾玉匣为。','',''),('quantangshi-22276','郡亭','白居易','quantangshi','','卷23','平旦起视事，亭午卧掩关。
除亲簿领外，多在琴书前。
况有虚白亭，坐见海门山。
潮来一凭槛，宾至一开筵。
终朝对云水，有时听管弦。
持此聊过日，非忙亦非闲。
山林太寂莫，朝阙空喧烦。
唯兹郡合内，嚣静得中间。','',''),('quantangshi-22277','咏怀','白居易','quantangshi','','卷23','昔为凤合郎，今为二千石。
自觉不如今，人言不如昔。
昔虽居近密，终日多忧惕。
有诗不敢吟，有酒不敢吃。
今虽在疎远，竟岁无牵役。
饱食坐终朝，长歌醉通夕。
人生百年内，疾速如过隙。
先务身安闲，次要心欢适。
事有得而失，物有损而益。
所以见道人，观心不观迹。','',''),('quantangshi-22278','立春后五日','白居易','quantangshi','','卷23','立春后五日，春态纷婀娜。
白日斜渐长，碧云低欲堕。
残冰坼玉片，新萼排红颗。
遇物尽欣欣，爱春非独我。
迎芳后园立，就暖前檐作。
还有惆怅心，欲别红炉火。','',''),('quantangshi-22279','郡中即事','白居易','quantangshi','','卷23','漫漫潮初平，熙熙春日至。
空阔远江山，晴明好天气。
外有适意物，中无系心事。
数篇对竹吟，一杯望云醉。
行携杖扶力，卧读书取睡。
久养病形骸，深谙闲气味。
遥思九城陌，扰扰趋名利。
今朝是双日，朝谒多轩骑。
宠者防悔尤，权者怀忧畏。
为报高车盖，恐非真富贵。','',''),('quantangshi-22280','郡斋暇日辱常州陈郎中使君早春晚坐水西馆书事诗十六韵见寄亦以十六韵酬之','白居易','quantangshi','','卷23','新年多暇日，晏起褰帘坐。
睡足心更慵，日高头未裹。
徐倾下药酒，稍爇煎茶火。
谁伴寂寥身，无弦琴在左。
遥思毗陵馆，春深物袅娜。
波拂黄柳梢，风摇白梅朵。
衙门排晓戟，铃阁开朝锁。
太守水西来，朱衣垂素舸。
良辰不易得，佳会无由果。
五马正相望，双鱼忽前堕。
鱼中获瑰宝，持玩何磊砢。
一百六十言，字字灵珠颗。
上申心款曲，下叙时轗轲。
才富不如君，道孤还似我。
敢辞官远慢，且贵身安妥。
勿复问荣枯，冥心无不可。','',''),('quantangshi-22281','官舍','白居易','quantangshi','','卷23','高树换新叶，阴阴覆地隅。
何言太守宅，有似幽人居。
太守卧其下，闲慵两有余。
起尝一瓯茗，行读一卷书。
早梅结青实，残樱落红珠。
穉女弄庭果，嬉戏牵人裾。
是日晚弥静，巢禽下相呼。
啧啧护儿鹊，哑哑母子乌。
岂唯云鸟尔，吾亦引吾雏。','',''),('quantangshi-22282','吾雏','白居易','quantangshi','','卷23','吾雏字阿罗，阿罗才七龄。
嗟吾不才子，怜尔无弟兄。
抚养虽骄呆，性识颇聪明。
学母画眉样，效吾咏诗声。
我齿今欲堕，汝齿昨始生。
我头发尽落，汝顶髻初成。
老幼不相待，父衰汝孩婴。
缅想古人心，慈爱亦不轻。
蔡邕念文姬，于公叹缇萦。
敢求得汝力，但未忘父情。','',''),('quantangshi-22283','题小桥前新竹招客','白居易','quantangshi','','卷23','雁齿小红桥，垂檐低白屋。
桥前何所有，苒苒新生竹。
皮开坼褐锦，节露抽青玉。
筠翠如可餐，粉霜不忍触。
闲吟声未已，幽玩心难足。
管领好风烟，轻欺凡草木。
谁能有月夜，伴我林中宿。
为君倾一杯，狂歌竹枝曲。','',''),('quantangshi-22284','病中逢秋招客夜酌','白居易','quantangshi','','卷23','不见诗酒客，卧来半月余。
合和新药草，寻检旧方书。
晚霁烟景度，早凉窗户虚。
雪生衰鬓久，秋入病心初。
卧簟蕲竹冷，风襟邛葛疎。
夜来身校健，小饮复何如。','',''),('quantangshi-22285','食饱','白居易','quantangshi','','卷23','食饱拂枕卧，睡足起闲吟。
浅酌一杯酒，缓弹数弄琴。
既可畅情性，亦足傲光阴。
谁知利名尽，无复长安心。','',''),('quantangshi-22286','严十八郎中在郡日改制东南楼因名清辉未立标牓征归郎署予既到郡性爱楼居宴游其间颇有幽致聊成十韵兼戏寄严','白居易','quantangshi','','卷23','严郎置兹楼，立名曰清辉。
未及署花牓，遽征还粉闱。
去来三四年，尘土登者稀。
今春新太守，洒埽施帘帏。
院柳烟婀娜，檐花雪霏微。
看山倚前户，待月阐东扉。
碧窗戛瑶瑟，朱阑飘舞衣。
烧香卷幕坐，风燕双双飞。
君作不得住，我来幸因依。
始知天地间，灵境有所归。','',''),('quantangshi-22287','南亭对酒送春','白居易','quantangshi','','卷23','含桃实已落，红薇花尚熏。
冉冉三月尽，晚莺城上闻。
独持一杯酒，南亭送残春。
半酣忽长歌，歌中何所云。
云我五十余，未是苦老人。
刺史二千石，亦不为贱贫。
天下三品官，多老于我身。
同年登第者，零落无一分。
亲故半为鬼，僮仆多见孙。
念此聊自解，逢酒且欢欣。','',''),('quantangshi-22288','玩新庭树因咏所怀','白居易','quantangshi','','卷23','霭霭四月初，新树叶成阴。
动摇风景丽，盖覆庭院深。
下有无事人，竟日此幽寻。
岂惟玩时物，亦可开烦襟。
时与道人语，或听诗客吟。
度春足芳色，入夜多鸣禽。
偶得幽闲境，遂忘尘俗心。
始知真隐者，不必在山林。','',''),('quantangshi-22289','仲夏斋戒月','白居易','quantangshi','','卷23','仲夏斋戒月，三旬断腥膻。
自觉心骨爽，行起身翩翩。
始知绝粒人，四体更轻便。
初能脱病患，久必成神仙。
御寇驭[泠]风，赤松游紫烟。
常疑此说谬，今乃知其然。
我今过半百，气衰神不全。
已垂两鬓丝，难补三丹田。
但减荤血味，稍结清净缘。
脱巾且修养，聊以终天年。','',''),('quantangshi-22290','除官去未间','白居易','quantangshi','','卷23','除官去未间，半月恣游讨。
朝寻霞外寺，暮宿波上岛。
新树少于松，平湖半连草。
跻攀有次第，赏玩无昏早。
有时骑马醉，兀兀冥天造。
穷通与生死，其奈吾怀抱。
江山信为美，齿发行将老。
在郡诚未厌，归乡去亦好。','',''),('quantangshi-22291','三年为刺史二首 一','白居易','quantangshi','','卷23','三年为刺史，无政在人口。
唯向城郡中，题诗十余首。
慙非甘棠咏，岂有思人不。','',''),('quantangshi-22292','三年为刺史二首 二','白居易','quantangshi','','卷23','三年为刺史，饮冰复食檗。
唯向天竺山，取得两片石。
此抵有千金，无乃伤清白。','',''),('quantangshi-22293','别萱桂','白居易','quantangshi','','卷23','使君竟不住，萱桂徒栽种。
桂有留人名，萱无忘忧用。
不如江畔月，步步来相送。','',''),('quantangshi-22294','自余杭归宿淮口作','白居易','quantangshi','','卷23','为郡已多暇，犹少勤吏职。
罢郡更安闲，无所劳心力。
舟行明月下，夜泊清淮北。
岂止吾一身，举家同燕息。
三年请禄俸，颇有余衣食。
乃至僮仆间，皆无冻馁色。
行行弄云水，步步近乡国。
妻子在我前，琴书在我侧。
此外吾不知，于焉心自得。','',''),('quantangshi-22295','舟中李山人访宿','白居易','quantangshi','','卷23','日暮舟悄悄，烟生水沈沈。
何以延宿客，夜酒与秋琴。
来客道门子，来自嵩高岑。
轩轩举云貌，豁豁开清襟。
得意言语断，入玄滋味深。
默然相顾哂，心适而忘心。','',''),('quantangshi-22296','洛下卜居','白居易','quantangshi','','卷23','三年典郡归，所得非金帛。
天竺石两片，华亭鹤一只。
饮啄供稻粱，包裹用茵席。
诚知是劳费，其奈心爱惜。
远从余杭郭，同到洛阳陌。
下担拂云根，开笼展霜翮。
贞姿不可杂，高性宜其适。
遂就无尘坊，仍求有水宅。
东南得幽境，树老寒泉碧。
池畔多竹阴，门前少人迹。
未请中庶禄，且脱双骖易。
岂独为身谋，安吾鹤与石。','',''),('quantangshi-22297','洛中偶作','白居易','quantangshi','','卷23','五年职翰林，四年涖浔阳。
一年巴郡守，半年南宫郎。
二年直纶合，三年刺史堂。
凡此十五载，有诗千余章。
境兴周万象，土风备四方。
独无洛中作，能不心悢悢。
今为青宫长，始来游此乡。
裴回伊涧上，睥睨嵩少傍。
遇物辄一咏，一咏倾一觞。
笔下成释憾，卷中同补亡。
往往顾自哂，眼昏须鬓苍。
不知老将至，犹自放诗狂。','',''),('quantangshi-22298','赠苏少府','白居易','quantangshi','','卷23','籍甚二十年，今日方款颜。
相送嵩洛下，论心杯酒间。
河亚嬾出入，府寮多闭关。
苍发彼此老，白日寻常闲。
朝从携手出，暮思联骑还。
何当挈一榼，同宿龙门山。','',''),('quantangshi-22299','移家入新宅','白居易','quantangshi','','卷23','移家入新宅，罢郡有余赀。
既可避燥湿，复免忧寒饥。
疾平未还假，官闲得分司。
幸有俸禄在，而无职役羁。
清旦盥漱毕，开轩卷帘帏。
家人及鸡犬，随我亦熙熙。
取兴或寄酒，放情不过诗。
何必苦修道，此即是无为。
外累信已遣，中怀时有思。
有思一何远，默坐低双眉。
十载囚窜客，万里征戍儿。
春朝鏁笼鸟，冬夜支牀龟。
驿马走四蹄，痛酸无歇期。
硙牛封两目，昏闭何人知。
谁能脱放去，四散任所之。
各得适其性，如吾今日时。','',''),('quantangshi-22300','琴','白居易','quantangshi','','卷23','置琴曲几上，慵坐但含情。
何烦故挥弄，风弦自有声。','',''),('quantangshi-22301','鹤','白居易','quantangshi','','卷23','人各有所好，物固无常宜。
谁谓尔能舞，不如闲立时。','',''),('quantangshi-22302','自咏','白居易','quantangshi','','卷23','夜镜隐白发，朝酒发红颜。
可怜假年少，自笑须臾间。
朱砂贱如土，不解烧为丹。
玄鬓化为雪，未闻休得官。
咄哉个丈夫，心性何堕顽。
但遇诗与酒，便忘寝与餐。
高声发一吟，似得诗中仙。
引满饮一盏，尽忘身外缘。
昔有醉先生，席地而幕天。
于今居处在，许我当中眠。
眠罢又一酌，酌罢又一篇。
回面顾妻子，生计方落然。
诚知此事非，又过知非年。
岂不欲自改，改即心不安。
且向安处去，其余皆老闲。','',''),('quantangshi-22303','林下闲步寄皇甫庶子','白居易','quantangshi','','卷23','扶杖起病初，策马力未任。
既嬾出门去，亦无客来寻。
以此遂成闲，闲步绕园林。
天晓烟景澹，树寒鸟雀深。
一酌池上酒，数声竹间吟。
寄言东曹长，当知幽独心。','',''),('quantangshi-22304','晏起','白居易','quantangshi','','卷23','鸟鸣庭树上，日照屋檐时。
老去慵转极，寒来起尤迟。
厚薄被适性，高低枕得宜。
神安体稳暖，此味何人知。
睡足仰头坐，兀然无所思。
如未凿七窍，若都遗四肢。
缅想长安客，早朝霜满衣。
彼此各自适，不知谁是非。','',''),('quantangshi-22305','池畔二首 一','白居易','quantangshi','','卷23','结构池西廊，疏理池东树。
此意人不知，欲为待月处。','',''),('quantangshi-22306','池畔二首 二','白居易','quantangshi','','卷23','持刀𠜴密竹，竹少风来多。
此意人不会，欲令池有波。','',''),('quantangshi-22307','春葺新居','白居易','quantangshi','','卷23','江州司马日，忠州刺史时。
栽松满后院，种柳荫前墀。
彼皆非吾土，栽种尚忘疲。
况兹是我宅，葺艺固其宜。
平旦领仆使，乘春亲指挥。
移花夹暖室，徙竹覆寒池。
池水变绿色，池芳动清辉。
寻芳弄水坐，尽日心熙熙。
一物苟可适，万缘都若遗。
设如宅门外，有事吾不知。','',''),('quantangshi-22308','赠言','白居易','quantangshi','','卷23','捧籯献千金，彼金何足道。
临觞赠一言，此言真可宝。
流光我已晚，适意君不早。
况君春风面，柔促如芳草。
二十方长成，三十向衰老。
镜中桃李色，不得十年好。
胡为坐脉脉，不肯倾怀抱。','',''),('quantangshi-22309','泛春池','白居易','quantangshi','','卷23','白苹湘渚曲，绿筱剡溪口。
各在天一涯，信美非吾有。
何如此庭内，水竹交左右。
霜竹百千竿，烟波六七亩。
泓澄动阶砌，澹泞映户牖。
蛇皮细有纹，镜面清无垢。
主人过桥来，双童扶一叟。
恐汚清泠波，尘缨先抖擞。
波上一叶舟，舟中一尊酒。
酒开舟不系，去去随所偶。
或绕蒲浦前，或泊桃岛后。
未拨落杯花，低冲拂面柳。
半酣迷所在，倚榜兀回首。
不知此何处，复是人寰否。
谁知始疏凿，几主相传受。
杨家去云远，田氏将非久。
天与爱水人，终焉落吾手。','',''),('quantangshi-22310','西明寺牡丹花时忆元九','白居易','quantangshi','','卷23','前年题名处，今日看花来。
一作芸香吏，三见牡丹开。
岂独花堪惜，方知老暗催。
何况寻花伴，东都去未回。
讵知红芳侧，春尽思悠哉。','',''),('quantangshi-22311','伤杨弘贞','白居易','quantangshi','','卷23','颜子昔短命，仲尼惜其贤。
杨生亦好学，不幸复徒然。
谁识天地意，独与龟鹤年。','',''),('quantangshi-22312','权摄昭应早秋书事寄元拾遗兼呈李司录','白居易','quantangshi','','卷23','夏闰秋候早，七月风骚骚。
渭川烟景晚，骊山宫殿高。
丹殿子司谏，赤县我徒劳。
相去半日程，不得同游遨。
到官来十日，览镜生二毛。
可怜趋走吏，尘土满青袍。
邮传拥两驿，簿书堆六曹。
为问纲纪掾，何必使铅刀。','',''),('quantangshi-22313','新栽竹','白居易','quantangshi','','卷23','佐邑意不适，闭门秋草生。
何以娱野性，种竹百余茎。
见此溪上色，忆得山中情。
有时公事暇，尽日绕阑行。
勿言根未固，勿言阴未成。
已觉庭宇内，稍稍有余清。
最爱近窗卧，秋风枝有声。','',''),('quantangshi-22314','秋霖中过尹纵之仙游山居','白居易','quantangshi','','卷23','惨惨八月暮，连连三日霖。
邑居尚愁寂，况乃在山林。
林下有志士，苦学惜光阴。
岁晚千万虑，并入方寸心。
岩鸟共旅宿，草虫伴愁吟。
秋天牀席冷，夜雨灯火深。
怜君寂莫意，携酒一相寻。','',''),('quantangshi-22315','寄江南兄弟','白居易','quantangshi','','卷23','分散骨肉恋，趋驰名利牵。
一奔尘埃马，一泛风波船。
忽忆分手时，悯默秋风前。
别来朝复夕，积日成七年。
花落城中池，春深江上天。
登楼东南望，鸟灭烟苍然。
相去复几许，道里近三千。
平地犹难见，况乃隔山川。','',''),('quantangshi-22316','曲江早秋','白居易','quantangshi','','卷23','秋波红蓼水，夕照青芜岸。
独信马蹄行，曲江池四畔。
早凉晴后至，残暑暝来散。
方喜炎燠销，复嗟时节换。
我年三十六，冉冉昏复旦。
人寿七十稀，七十新过半。
且当对酒笑，勿起临风叹。','',''),('quantangshi-22317','寄题盩厔厅前双松','白居易','quantangshi','','卷23','忆昨为吏日，折腰多苦辛。
归来不自适，无计慰心神。
手栽两树松，聊以当嘉宾。
乘春日一溉，生意渐欣欣。
清韵度秋在，绿茸随日新。
始怜涧底色，不忆城中春。
有时昼掩关，双影对一身。
尽日不寂莫，意中如三人。
忽奉宣室诏，征为文苑臣。
闲来一惆怅，恰似别交亲。
早知烟翠前，攀玩不逡巡。
悔从白云里，移尔落嚣尘。','',''),('quantangshi-22318','翰林院中感秋怀王质夫','白居易','quantangshi','','卷23','何处感时节，新蝉禁中闻。
宫槐有秋意，风夕花纷纷。
寄迹鸳鹭行，归心鸥鹤羣。
唯有王居士，知予忆白云。
何日仙游寺，潭前秋见君。','',''),('quantangshi-22319','禁中月','白居易','quantangshi','','卷23','海水明月出，禁中清夜长。
东南楼殿白，稍稍上宫墙。
净落金塘水，明浮玉砌霜。
不比人间见，尘土汚清光。','',''),('quantangshi-22320','赠卖松者','白居易','quantangshi','','卷23','一束苍苍色，知从涧底来。
斸掘经几日，枝叶满尘埃。
不买非他意，城中无地栽。','',''),('quantangshi-22321','初见白发','白居易','quantangshi','','卷23','白发生一茎，朝来明镜里。
勿言一茎少，满头从此始。
青山方远别，黄绶初从仕。
未料容鬓间，蹉跎忽如此。','',''),('quantangshi-22322','别元九后咏所怀','白居易','quantangshi','','卷23','零落桐叶雨，萧条槿花风。
悠悠早秋意，生此幽闲中。
况与故人别，中怀正无悰。
勿云不相送，心到青门东。
相知岂在多，但问同不同。
同心一人去，坐觉长安空。','',''),('quantangshi-22323','禁中秋宿','白居易','quantangshi','','卷23','风飜朱里幕，雨冷通中枕。
耿耿背斜灯，秋牀一人寝。','',''),('quantangshi-22324','早秋曲江感怀','白居易','quantangshi','','卷23','离离暑云散，袅袅凉风起。
池上秋又来，荷花半成子。
朱颜易销歇，白日无穷已。
人寿不如山，年光忽于水。
青芜与红蓼，岁岁秋相似。
去岁此悲秋，今秋复来此。','',''),('quantangshi-22325','寄元九','白居易','quantangshi','','卷23','身为近密拘，心为名检缚。
月夜与花时，少逢杯酒乐。
唯有元夫子，闲来同一酌。
把手或酣歌，展眉时笑谑。
今春除御史，前月之东洛。
别来未开颜，尘埃满尊杓。
蕙风晚香尽，槐雨余花落。
秋意一萧条，离容两寂莫。
况随白日老，共负青山约。
谁识相念心，韝鹰与笼鹤。','',''),('quantangshi-22326','暮春寄元九','白居易','quantangshi','','卷23','棃花结成实，燕卵化为雏。
时物又若此，道情复何如。
但觉日月促，不嗟年岁徂。
浮生都是梦，老小亦何殊。
唯与故人别，江陵初谪居。
时时一相见，此意未全除。','',''),('quantangshi-22327','早梳头','白居易','quantangshi','','卷23','夜沐早梳头，窗明秋镜晓。
飒然握中发，一沐知一少。
年事渐蹉跎，世缘方缴绕。
不学空门法，老病何由了。
未得无生心，白头亦为夭。','',''),('quantangshi-22328','出关路','白居易','quantangshi','','卷23','山川函谷路，尘土游子颜。
萧条去国意，秋风生故关。','',''),('quantangshi-22329','别舍弟后月夜','白居易','quantangshi','','卷23','悄悄初别夜，去住两盘桓。
行子孤灯店，居人明月轩。
平生共贫苦，未必日成欢。
及此暂为别，怀抱已忧烦。
况是庭叶尽，复思山路寒。
如何为不念，马瘦衣裳单。','',''),('quantangshi-22330','新丰路逢故人','白居易','quantangshi','','卷23','尘土长路晚，风烟废宫秋。
相逢立马语，尽日此桥头。
知君不得意，郁郁来西游。
惆怅新丰店，何人识马周。','',''),('quantangshi-22331','金銮子晬日','白居易','quantangshi','','卷23','行年欲四十，有女曰金銮。
生来始周岁，学坐未能言。
慙非达者怀，未免俗情怜。
从此累身外，徒云慰目前。
若无夭折患，则有婚嫁牵。
使我归山计，应迟十五年。','',''),('quantangshi-22332','青龙寺早夏','白居易','quantangshi','','卷23','尘埃经小雨，地高倚长坡。
日西寺门外，景气含清和。
闲有老僧立，静无凡客过。
残莺意思尽，新叶阴凉多。
春去来几日，夏云忽嵯峨。
朝朝感时节，年鬓暗蹉跎。
胡为恋朝市，不去归烟萝。
青山寸步地，自问心如何。','',''),('quantangshi-22333','秋题牡丹丛','白居易','quantangshi','','卷23','晚丛白露夕，衰叶凉风朝。
红艳久已歇，碧芳今亦销。
幽人坐相对，心事共萧条。','',''),('quantangshi-22334','劝酒寄元九','白居易','quantangshi','','卷23','薤叶有朝露，槿枝无宿花。
君今亦如此，促促生有涯。
既不逐禅僧，林下学楞伽。
又不随道士，山中炼丹砂。
百年夜分半，一岁春无多。
何不饮美酒？胡然自悲嗟。
俗号销愁药，神速无以加。
一杯驱世虑，两杯反天和。
三杯即酩酊，或笑任狂歌。
陶陶复兀兀，吾孰知其他。
况在名利途，平生有风波。
深心藏陷穽，巧言织网罗。
举目非不见，不醉欲如何。','',''),('quantangshi-22335','曲江感秋','白居易','quantangshi','','卷23','沙草新雨地，岸柳凉风枝。
三年感秋意，并在曲江池。
早蝉已嘹唳，晚荷复离披。
前秋去秋思，一一生此时。
昔人三十二，秋兴已云悲。
我今欲四十，秋怀亦可知。
岁月不虚设，此身随日衰。
暗老不自觉，直到鬓成丝。','',''),('quantangshi-22336','酬张太祝晚秋卧病见寄','白居易','quantangshi','','卷23','高才淹礼寺，短羽翔禁林。
西街居处远，北阙官曹深。
君病不来访，我忙难往寻。
差池终日别，寥落经年心。
露湿绿芜地，月寒红树阴。
况兹独愁夕，闻彼相思吟。
上叹言笑阻，下嗟时岁侵。
容衰晓窗镜，思苦秋弦琴。
一章锦绣段，八韵琼瑶音。
何以报珍重，慙无双南金。','',''),('quantangshi-22337','立秋日曲江忆元九','白居易','quantangshi','','卷23','下马柳阴下，独上堤上行。
故人千万里，新蝉三两声。
城中曲江水，江上江陵城。
两地新秋思，应同此日情。','',''),('quantangshi-22338','早朝贺雪寄陈山人','白居易','quantangshi','','卷23','长安盈尺雪，早朝贺君喜。
将赴银台门，始出新昌里。
上堤马蹄滑，中路蜡烛死。
十里向北行，寒风吹破耳。
待漏午门外，候对三殿里。
须鬓冻生冰，衣裳冷如水。
忽思仙游谷，暗谢陈居士。
暖覆褐裘眠，日高应未起。','',''),('quantangshi-22339','初与元九别后忽梦见之及寤而书适至兼寄桐花诗怅然感怀因以此寄','白居易','quantangshi','','卷23','永寿寺中语，新昌坊北分。
归来数行泪，悲事不悲君。
悠悠蓝田路，自去无消息。
计君食宿程，已过商山北。
昨夜云四散，千里同月色。
晓来梦见君，应是君相忆。
梦中握君手，问君意何如。
君言苦相忆，无人可寄书。
觉来未及说，叩门声冬冬。
言是商州使，送君书一封。
枕上忽惊起，颠倒着衣裳。
开缄见手札，一纸十三行。
上论迁谪心，下说离别肠。
心肠都未尽，不暇叙炎凉。
云作此书夜，夜宿商州东。
独对孤灯坐，阳城山馆中。
夜深作书毕，山月向西斜。
月下何所有，一树紫桐花。
桐花半落时，复道正相思。
殷勤书背后，兼寄桐花诗。
桐花诗八韵，思绪一何深。
以我今朝意，忆君此夜心。
一章三徧读，一句十回吟。
珍重八十字，字字化为金。','',''),('quantangshi-22340','和元九悼往','白居易','quantangshi','','卷23','美人别君去，自去无处寻。
旧物零落尽，此情安可任。
唯有襭纱幌，尘埃日夜侵。
馨香与颜色，不似旧时深。
透影灯耿耿，笼光月沈沈。
中有孤眠客，秋凉生夜衾。
旧宅牡丹院，新坟松柏林。
梦中咸阳泪，觉后江陵心。
含此隔年恨，发为中夜吟。
无论君自感，闻者欲霑襟。','',''),('quantangshi-22341','重到渭上旧居','白居易','quantangshi','','卷23','旧居清渭曲，开门当蔡渡。
十年方一还，几欲迷归路。
追思昔日行，感伤故游处。
插柳作高林，种桃成老树。
因惊成人者，尽是旧童孺。
试问旧老人，半为绕村墓。
浮生同过客，前后递来去。
白日如弄珠，出没光不住。
人物日改变，举目悲所遇。
回念念我身，安得不衰暮。
朱颜销不歇，白发生无数。
唯有山门外，三峰色如故。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22342','白发','白居易','quantangshi','','卷23','白发知时节，暗与我有期。
今朝日阳裹，梳落数茎丝。
家人不惯见，悯默为我悲。
我云何足怪，此意尔不知。
凡人年三十，外壮中已衰。
但思寝食味，已减二十时。
况我今四十，本来形貌羸。
书魔昏两眼，酒病沈四肢。
亲爱日零落，在者仍别离。
身心久如此，白发生已迟。
由来生老死，三病长相随。
除却念无生，人间无药治。','',''),('quantangshi-22343','秋日','白居易','quantangshi','','卷23','池残寥落水，窗下悠杨日。
袅袅秋风多，槐花半成实。
下有独立人，年来四十一。','',''),('quantangshi-22344','将之饶州江浦夜泊','白居易','quantangshi','','卷23','明月满深浦，愁人卧孤舟。
烦冤寝不得，夏夜长于秋。
苦乏衣食资，远为江海游。
光阴坐迟暮，乡国行阻修。
身病向鄱阳，家贫寄徐州。
前事与后事，岂堪心并忧。
忧来起长望，但见江水流。
云树霭苍苍，烟波澹悠悠。
故园迷处所，一念堪白头。','',''),('quantangshi-22345','思归','白居易','quantangshi','','卷23','养无晨昏膳，隐无伏腊资。
遂求及亲禄，僶俛来京师。
薄俸未及亲，别家已经时。
冬积温席恋，春违采兰期。
夏至一阴生，稍稍夕漏迟。
块然抱愁者，长夜独先知。
悠悠乡关路，梦去身不随。
坐惜时节变，蝉鸣槐花枝。','',''),('quantangshi-22346','冀城北原作','白居易','quantangshi','','卷23','野色何莽苍，秋声亦萧疎。
风吹黄埃起，落日驱征车。
何代此开国，封疆百里余。
古今不相待，朝市无常居。
昔人城邑中，今变为丘墟。
昔人墓田中，今化为里闾。
废兴相催迫，日月互居诸。
世变无遗风，焉能知其初。
行人千载后，怀古空踌躇。','',''),('quantangshi-22347','客路感秋寄明准上人','白居易','quantangshi','','卷23','日暮天地冷，雨霁山河清。
长风从西来，草木凝秋声。
已感岁倏忽，复伤物凋零。
孰能不憯凄，天时牵人情。
借问空门子，何法易修行。
使我忘得心，不教烦恼生。','',''),('quantangshi-22348','游襄阳怀孟浩然','白居易','quantangshi','','卷23','楚山碧岩岩，汉水碧汤汤。
秀气结成象，孟氏之文章。
今我讽遗文，思人至其乡。
清风无人继，日暮空襄阳。
南望鹿门山，蔼若有余芳。
旧隐不知处，云深树苍苍。','',''),('quantangshi-22349','秋暮西归途中书情','白居易','quantangshi','','卷23','耿耿旅灯下，愁多常少眠。
思乡贵早发，发在鸡鸣前。
九月草木落，平芜连远山。
秋阴和曙色，万木苍苍然。
去秋偶东游，今秋始西旋。
马瘦衣裳破，别家来二年。
忆归复愁归，归无一囊钱。
心虽非兰膏，安得不自然。','',''),('quantangshi-22350','秋怀','白居易','quantangshi','','卷23','月出照北堂，光华满阶墀。
凉风从西至，草木日夜衰。
桐柳减绿阴，蕙兰消碧滋。
感物私自念，我心亦如之。
安得长少壮，盛衰迫天时。
人生如石火，为乐长苦迟。','',''),('quantangshi-22351','别杨颖士卢克柔殷尧藩','白居易','quantangshi','','卷23','倦鸟暮归林，浮云晴归山。
独有行路子，悠悠不知还。
人生苦营营，终日羣动间。
所务虽不同，同归于不闲。
扁舟来楚乡，匹马往秦关。
离忧绕心曲，宛转如循环。
且持一杯酒，聊以开愁颜。','',''),('quantangshi-22352','题赠定光上人','白居易','quantangshi','','卷23','二十身出家，四十心离尘。
得径入大道，乘此不退轮。
一坐十五年，林下秋复春。
春花与秋气，不感无情人。
我来如有悟，潜以心照身。
误落闻见中，忧喜伤形神。
安得遗耳目，冥然反天真。','',''),('quantangshi-22353','只役骆口驿喜萧侍御书至兼覩新诗吟讽通宵因寄八韵','白居易','quantangshi','','卷23','日暮心无憀，吏役正营营。
忽惊芳信至，复与新诗并。
是时天无云，山馆有月明。
月下读数徧，风前吟一声。
一吟三四叹，声尽有余清。
雅哉君子文，咏性不咏情。
使我灵府中，鄙恡不得生。
始知听韶濩，可使心和平。','',''),('quantangshi-22354','酬李少府曹长官舍见赠','白居易','quantangshi','','卷23','低腰复敛手，心体不遑安。
一落风尘下，方知为吏难。
公事与日长，宦情随岁阑。
惆怅青袍袖，芸香无半残。
赖有李夫子，此怀聊自宽。
两心如止水，彼此无波澜。
往往簿书暇，相劝强为欢。
白马晚蹋雪，渌觞春暖寒。
恋月夜同宿，爱山晴共看。
野性自相近，不是为同官。','',''),('quantangshi-22355','留别','白居易','quantangshi','','卷23','秋凉卷朝簟，春暖撤夜衾。
虽是无情物，欲别尚沈吟。
况与有情别，别随情浅深。
二年欢笑意，一旦东西心。
独留诚可念，同行力不任。
前事讵能料，后期谅难寻。
唯有潺湲泪，不惜共霑襟。','',''),('quantangshi-22356','晓别','白居易','quantangshi','','卷23','晓鼓声已半，离筵坐难久。
请君断肠歌，送我和泪酒。
月落欲明前，马嘶初别后。
浩浩暗尘中，何由见回首。','',''),('quantangshi-22357','北园','白居易','quantangshi','','卷23','北园东风起，杂花次第开。
心知须臾落，一日三四来。
花下岂无酒，欲酌复迟回。
所思眇千里，谁劝我一杯。','',''),('quantangshi-22358','惜栯李花','白居易','quantangshi','','卷23','树小花鲜妍，香繁条輭弱。
高低二三尺，重叠千万萼。
朝艳蔼霏霏，夕凋纷漠漠。
辞枝朱粉细，覆地红绡薄。
由来好颜色，常苦易销铄。
不见莨荡花，狂风吹不落。','',''),('quantangshi-22359','照镜','白居易','quantangshi','','卷23','皎皎青铜镜，斑斑白丝鬓。
岂复更藏年，实年君不信。','',''),('quantangshi-22360','新秋','白居易','quantangshi','','卷23','西风飘一叶，庭前飒已凉。
风池明月水，衰莲白露房。
其奈江南夜，緜緜自此长。','',''),('quantangshi-22361','夜雨','白居易','quantangshi','','卷23','早蛩啼复歇，残灯灭又明。
隔窗知夜雨，芭蕉先有声。','',''),('quantangshi-22362','秋江送客','白居易','quantangshi','','卷23','秋鸿次第过，哀猨朝夕闻。
是日孤舟客，此地亦离羣。
蒙蒙润衣雨，漠漠冒帆云。
不醉浔阳酒，烟波愁杀人。','',''),('quantangshi-22363','感逝寄远','白居易','quantangshi','','卷23','昨日闻甲死，今朝闻乙死。
知识三分中，二分化为鬼。
逝者不复见，悲哉长已矣。
存者今如何，去我皆万里。
平生知心者，屈指能有几。
通果澧凤州，眇然四君子。
相思俱老大，浮世如流水。
应叹旧交游，凋零日如此。
何当一杯酒，开眼笑相视。','',''),('quantangshi-22364','秋月','白居易','quantangshi','','卷23','夜初色苍然，夜深光浩然。
稍转西廊下，渐满南窗前。
况是绿芜地，复兹清露天。
落叶声策策，惊鸟影翩翩。
栖禽尚不稳，愁人安可眠。','',''),('quantangshi-22365','朱陈村','白居易','quantangshi','','卷23','徐州古丰县，有村曰朱陈。
去县百余里，桑麻青氛氲。
机梭声札札，牛驴走纭纭。
女汲涧中水，男采山上薪。
县远官事少，山深人俗淳。
有财不行商，有丁不入军。
家家守村业，头白不出门。
生为村之民，死为村之尘。
田中老与幼，相见何欣欣。
一村唯两姓，世世为婚姻。
亲疎居有族，少长游有羣。
黄鸡与白酒，欢会不隔旬。
生者不远别，嫁娶先近邻。
死者不远葬，坟墓多绕村。
既安生与死，不苦形与神。
所以多寿考，往往见玄孙。
我生礼义乡，少小孤且贫。
徒学辨是非，祗自取辛勤。
世法贵名教，士人重冠婚。
以此自桎梏，信为大谬人。
十岁解读书，十五能属文。
二十举秀才，三十为谏臣。
下有妻子累，上有君亲恩。
承家与事国，望此不肖身。
忆昨旅游初，迨今十五春。
孤舟三适楚，羸马四经秦。
昼行有饥色，夜寝无安魂。
东西不暂住，来往若浮云。
离乱失故乡，骨肉多散分。
江南与江北，各有平生亲。
平生终日别，逝者隔年闻。
朝忧卧至暮，夕哭坐达晨。
悲火烧心曲，愁霜侵鬓根。
一生苦如此，长羡村中民。','',''),('quantangshi-22366','读邓鲂诗','白居易','quantangshi','','卷23','尘架多文集，偶取一卷披。
未及看姓名，疑是陶潜诗。
看名知是君，恻恻令我悲。
诗人多蹇厄，近日诚有之。
京兆杜子美，犹得一拾遗。
襄阳孟浩然，亦闻鬓成丝。
嗟君两不如，三十在布衣。
擢第禄不及，新婚妻未归。
少年无疾患，溘死于路岐。
天不与爵寿，唯与好文词。
此理勿复道，巧历不能推。','',''),('quantangshi-22367','寄元九','白居易','quantangshi','','卷23','晨鸡才发声，夕雀俄敛翼。
昼夜往复来，疾如出入息。
非徒改年貌，渐觉无心力。
自念因念君，俱为老所逼。
君年虽校少，顦顇谪南国。
三年不放归，炎瘴消颜色。
山无杀草霜，水有含沙蜮。
健否远不知，书多隔年得。
愿君少愁苦，我亦加餐食。
各保金石躯，以慰长相忆。','',''),('quantangshi-22368','秋夕','白居易','quantangshi','','卷23','叶声落如雨，月色白似霜。
夜深方独卧，谁为拂尘牀。','',''),('quantangshi-22369','夜雨','白居易','quantangshi','','卷23','我有所念人，隔在远远乡。
我有所感事，结在深深肠。
乡远去不得，无日不瞻望。
肠深解不得，无夕不思量。
况此残灯夜，独宿在空堂。
秋天殊未晓，风雨正苍苍。
不学头陀法，前心安可忘。','',''),('quantangshi-22370','秋霁','白居易','quantangshi','','卷23','金火不相待，炎凉雨中变。
林晴有残蝉，巢冷无留燕。
沈吟卷长簟，怆恻收团扇。
向夕稍无泥，闲步青苔院。
月出砧杵动，家家捣秋练。
独对多病妻，不能理针线。
冬衣殊未制，夏服行将绽。
何以迎早秋，一杯聊自劝。','',''),('quantangshi-22371','叹老三首 一','白居易','quantangshi','','卷23','晨兴照青镜，形影两寂莫。
少年辞我去，白发随梳落。
万化成于渐，渐衰看不觉。
但恐镜中颜，今朝老于昨。
人年少满百，不得长欢乐。
谁会天地心，千龄与龟鹤。
吾闻善医者，今古称扁鹊。
万病皆可治，唯无治老药。','',''),('quantangshi-22372','叹老三首 二','白居易','quantangshi','','卷23','我有一握发，梳理何稠直。
昔似玄云光，今如素丝色。
匣中有旧镜，欲照先叹息。
自从头白来，不欲明磨拭。
鵶头与鹤颈，至老常如墨。
独有人鬓毛，不得终身黑。','',''),('quantangshi-22373','叹老三首 三','白居易','quantangshi','','卷23','前年种桃核，今岁成花树。
去岁新婴儿，今年已学步。
但惊物长成，不觉身衰暮。
去矣欲何如，少年留不住。
因书今日意，徧寄诸亲故。
壮岁不欢娱，长年当悔悟。','',''),('quantangshi-22374','送兄弟回雪夜','白居易','quantangshi','','卷23','日晦云气黄，东北风切切。
时从村南还，新与兄弟别。
离襟泪犹湿，回马嘶未歇。
欲归一室坐，天阴多无月。
夜长火消尽，岁暮雨凝结。
寂莫满炉灰，飘零上阶雪。
对雪画寒灰，残灯明复灭。
灰死如我心，雪白如我发。
所隅皆如此，顷刻堪愁绝。
回念入坐忘，转忧作禅悦。
平生洗心法，正为今宵设。','',''),('quantangshi-22375','溪中早春','白居易','quantangshi','','卷23','南山雪未尽，阴岭留残白。
西涧冰已消，春溜含新碧。
东风来几日，蛰动萌草坼。
潜知阳和功，一日不虚掷。
爱此天气暖，来拂溪边石。
一坐欲忘归，暮禽声啧啧。
蓬蒿隔桑枣，隐映烟火夕。
归来问夜餐，家人烹荠麦。','',''),('quantangshi-22376','同友人寻涧花','白居易','quantangshi','','卷23','闻有涧底花，贳得村中酒。
与君来校迟，已逢摇落后。
临觞有遗恨，怅望空溪口。
记取花发时，期君重携手。
我生日日老，春色年年有。
且作来岁期，不知身健否。','',''),('quantangshi-22377','登村东古冢','白居易','quantangshi','','卷23','高低古时冢，上有牛羊道。
独立最高头，悠哉此怀抱。
回头向村望，但见荒田草。
村人不爱花，多种栗与枣。
自来此村住，不觉风光好。
花少莺亦稀，年年春暗老。','',''),('quantangshi-22378','梦裴相公','白居易','quantangshi','','卷23','五年生死隔，一夕魂梦通。
梦中如往日，同直金銮宫。
仿髴金紫色，分明冰玉容。
勤勤相眷意，亦与平生同。
既寤知是梦，悯然情未终。
追想当时事，何殊昨夜中。
自我学心法，万缘成一空。
今朝为君子，流涕一霑胷。','',''),('quantangshi-22379','昼寝','白居易','quantangshi','','卷23','坐整白单衣，起穿黄草屦。
朝餐盥漱毕，徐下阶前步。
暑风微变候，昼刻渐加数。
院静地阴阴，鸟鸣新叶树。
独行还独卧，夏景殊未暮。
不作午时眠，日长安可度。','',''),('quantangshi-22380','别行简','白居易','quantangshi','','卷23','漠漠病眼花，星星愁鬓雪。
筋骸已衰惫，形影仍分诀。
梓州二千里，劒门五六月。
岂是远行时，火云烧栈热。
何言巾上泪，乃是肠中血。
念此早归来，莫作经年别。','',''),('quantangshi-22381','观儿戏','白居易','quantangshi','','卷23','髫龀七八岁，绮纨三四儿。
弄尘复鬭草，尽日乐嬉嬉。
堂上长年客，鬓间新有丝。
一看竹马戏，每忆童呆时。
童呆饶戏乐，老大多忧悲。
静念彼与此，不知谁是痴。','',''),('quantangshi-22382','叹常生','白居易','quantangshi','','卷23','西村常氏子，卧疾不须臾。
前旬犹访我，今日忽云殂。
时我病多暇，与之同野居。
园林青蔼蔼，相去数里余。
村邻无好客，所遇唯农夫。
之子何如者，往还犹胜无。
于今亦已矣，可为一长吁。','',''),('quantangshi-22383','寄元九','白居易','quantangshi','','卷23','一病经四年，亲朋书信断。
穷通合易交，自笑知何晚。
元君在荆楚，去日唯云远。
彼独是何人，心如石不转。
忧我贫病身，书来唯劝勉。
上言少愁苦，下道加餐饭。
怜君为谪吏，穷薄家贫褊。
三寄衣食资，数盈二十万。
岂是贪衣食，感君心缱绻。
念我口中食，分君身上暖。
不因身病久，不因命多蹇。
平生亲友心，岂得知深浅。','',''),('quantangshi-22384','以镜赠别','白居易','quantangshi','','卷23','人言似明月，我道胜明月。
明月非不明，一年十二缺。
岂如玉匣里，如水常澄澈。
月破天暗时，圆明独不歇。
我慙貌丑老，绕鬓斑斑雪。
不如赠少年，回照青丝发。
因君千里去，持此将为别。','',''),('quantangshi-22385','城上对月期友人不至','白居易','quantangshi','','卷23','古人惜昼短，劝令秉烛游。
况此迢迢夜，明月满西楼。
复有盈尊酒，置在城上头。
期君君不至，人月两悠悠。
照水烟波白，照人肌发秋。
清光正如此，不醉即须愁。','',''),('quantangshi-22386','念金銮子二首 一','白居易','quantangshi','','卷23','衰病四十身，娇痴三岁女。
非男犹胜无，慰情时一抚。
一朝舍我去，魂影无处所。
况念夭札时，呕哑初学语。
始知骨肉爱，乃是忧悲聚。
唯思未有前，以理遣伤苦。
忘怀日已久，三度移寒暑。
今日一伤心，因逢旧乳母。','',''),('quantangshi-22387','念金銮子二首 二','白居易','quantangshi','','卷23','与尔为父子，八十有六旬。
忽然又不见，迩来三四春。
形质本非实，气聚偶成身。
恩爱元是妄，缘合暂为亲。
念兹庶有悟，聊用遣悲辛。
暂将理自夺，不是忘情人。','',''),('quantangshi-22388','对酒','白居易','quantangshi','','卷23','人生一百岁，通计三万日。
何况百岁人，人间百无一。
贤愚共零落，贵贱同埋没。
东岱前后魂，北邙新旧骨。
复闻药误者，为爱延年术。
又有忧死者，为贪政事笔。
药误不得老，忧死非因疾。
谁言人最灵，知得不知失。
何如会亲友，饮此杯中物。
能沃烦虑消，能陶真性出。
所以刘阮辈，终年醉兀兀。','',''),('quantangshi-22389','渭村雨归','白居易','quantangshi','','卷23','渭水寒渐落，离离蒲稗苗。
闲傍沙边立，看人刈苇苕。
近水风景冷，晴明犹寂寥。
复兹夕阴起，野色重萧条。
萧条独归路，暮雨湿村桥。','',''),('quantangshi-22390','谕怀','白居易','quantangshi','','卷23','黑头日已白，白面日已黑。
人生未死间，变化何终极。
常言在己者，莫若形与色。
一朝改变来，止遏不能得。
况彼身外事，悠悠通与塞。','',''),('quantangshi-22391','喜友至留宿','白居易','quantangshi','','卷23','村中少宾客，柴门多不开。
忽闻车马至，云是故人来。
况值风雨夕，愁心正悠哉。
愿君且同宿，尽此手中杯。
人生开口笑，百年都几回。','',''),('quantangshi-22392','西原晚望','白居易','quantangshi','','卷23','花菊引闲行，行上西原路。
原上晚无人，因高聊四顾。
南阡有烟火，北陌连墟墓。
村邻何萧疎，近者犹百步。
吾庐在其下，寂莫风日暮。
门外转枯蓬，篱根伏寒兔。
故园汴水上，离乱不堪去。
近岁始移家，飘然此村住。
新屋五六间，古槐八九树。
便是衰病身，此生终老处。','',''),('quantangshi-22393','感镜','白居易','quantangshi','','卷23','美人与我别，留镜在匣中。
自从花颜去，秋水无芙蓉。
经年不开匣，红埃覆青铜。
今朝一拂拭，自照顦顇容。
照罢重惆怅，背有双盘龙。','',''),('quantangshi-22394','村居卧病三首 一','白居易','quantangshi','','卷23','戚戚抱羸病，悠悠度朝暮。
夏木才结阴，秋兰已含露。
前日巢中卵，化作雏飞去。
昨日穴中虫，蜕为蝉上树。
四时未尝歇，一物不暂住。
唯有病客心，沈然独如故。','',''),('quantangshi-22395','村居卧病三首 二','白居易','quantangshi','','卷23','新秋久病客，起步村南道。
尽日不逢人，虫声徧荒草。
西风吹白露，野绿秋仍早。
草木犹为伤，先伤我怀抱。
朱颜与玄鬓，强健几时好。
况为忧病侵，不得依年老。','',''),('quantangshi-22396','村居卧病三首 三','白居易','quantangshi','','卷23','种黍三十亩，雨来苗渐大。
种薤二十畦，秋来欲堪刈。
望黍作冬酒，留薤为春菜。
荒村百物无，待此养衰瘵。
葺庐备阴雨，补褐防寒岁。
病身知几时，且作明年计。','',''),('quantangshi-22397','沐浴','白居易','quantangshi','','卷23','经年不沐浴，尘垢满肌肤。
今朝一澡濯，衰瘦颇有余。
老色头鬓白，病形支体虚。
衣宽有剩带，发少不胜梳。
自问今年岁，春秋四十初。
四十已如此，七十复何如。','',''),('quantangshi-22398','栽松二首 一','白居易','quantangshi','','卷23','小松未盈尺，心爱手自移。
苍然涧底色，云湿烟霏霏。
栽植我年晚，长成君性迟。
如何过四十，种此数寸枝。
得见成阴否，人生七十稀。','',''),('quantangshi-22399','栽松二首 二','白居易','quantangshi','','卷23','爱君抱晚节，怜君含直文。
欲得朝朝见，阶前故种君。
知君死则已，不死会凌云。','',''),('quantangshi-22400','病中友人相访','白居易','quantangshi','','卷23','卧久不记日，南窗昏复昏。
萧条草檐下，寒雀朝夕闻。
强扶牀前杖，起向庭中行。
偶逢故人至，便当一逢迎。
移榻就斜日，披裘倚前楹。
闲谈胜服药，稍觉有心情。','',''),('quantangshi-22401','自觉二首 一','白居易','quantangshi','','卷23','四十未为老，忧伤早衰恶。
前岁二毛生，今年一齿落。
形骸日损耗，心事同萧索。
夜寝与朝餐，其间味亦薄。
同岁崔舍人，容光方灼灼。
始知年与貌，衰盛随忧乐。
畏老老转迫，忧病病弥缚。
不畏复不忧，是除老病药。','',''),('quantangshi-22402','自觉二首 二','白居易','quantangshi','','卷23','朝哭心所爱，暮哭心所亲。
亲爱零落尽，安用身独存。
几许平生欢，无限骨肉恩。
结为肠间痛，聚作鼻头辛。
悲来四支缓，泣尽双眸昏。
所以年四十，心如七十人。
我闻浮屠教，中有解脱门。
置心为止水，视身如浮云。
斗擞垢秽衣，度脱生死轮。
胡为恋此苦，不去犹逡巡。
回念发弘愿，愿此见在身。
但受过去报，不结将来因。
誓以智慧水，永洗烦恼尘。
不将恩爱子，更种悲忧根。','',''),('quantangshi-22403','夜雨有念','白居易','quantangshi','','卷23','以道治心气，终岁得晏然。
何乃戚戚意，忽来风雨天。
既非慕荣显，又不恤饥寒。
胡为悄不乐，抱膝残灯前。
形影暗相问，心默对以言。
骨肉能几人，各在天一端。
吾兄寄宿州，吾弟客东川。
南北五千里，吾身在中间。
欲去病未能，欲住心不安。
有如波上舟，此缚而彼牵。
自我向道来，于今六七年。
炼成不二性，消尽千万缘。
唯有恩爱火，往往犹熬煎。
岂是药无効，病多难尽蠲。','',''),('quantangshi-22404','寄杨六','白居易','quantangshi','','卷23','青宫官冷静，赤县事繁剧。
一闲复一忙，动作经时隔。
清觞久废酌，白日顿虚掷。
念此忽踟蹰，悄然心不适。
岂无旧交结，久别或迁易。
亦有新往还，相见多形迹。
唯君于我分，坚久如金石。
何况老大来，人情重姻戚。
会稀岁月急，此事真可惜。
几回开口笑，便到髭须白。
公门苦鞅掌，尽日无闲隙。
犹冀乘暝来，静言同一夕。','',''),('quantangshi-22405','送春','白居易','quantangshi','','卷23','三月三十日，春归日复暮。
惆怅问春风，明朝应不住。
送春曲江上，眷眷东西顾。
但见扑水花，纷纷不知数。
人生似行客，两足无停步。
日日进前程，前程几多路。
兵刀与水火，尽可违之去。
唯有老到来，人间无避处。
感时良为已，独倚池南树。
今日送春心，心如别亲故。','',''),('quantangshi-22406','哭李三','白居易','quantangshi','','卷23','去年渭水曲，秋时访我来。
今年常乐里，春日哭君回。
哭君仰问天，天意安在哉。
若必夺其寿，何如不与才。
落然身后事，妻病女婴孩。','',''),('quantangshi-22407','别李十一后重寄','白居易','quantangshi','','卷23','秋日正萧条，驱车出蓬荜。
回望青门道，目极心郁郁。
岂独恋乡土，非关慕簪绂。
所怆别李君，平生同道术。
俱承金马诏，联秉谏臣笔。
共上青云梯，中途一相失。
江湖我方往，朝廷君不出。
蕙带与华簪，相逢是何日。','',''),('quantangshi-22408','初出蓝田路作','白居易','quantangshi','','卷23','停骖问前路，路在秋云里。
苍苍县南道，去途从此始。
绝顶忽上盘，众山皆下视。
下视千万峰，峰头如浪起。
朝经韩公坡，夕次蓝桥水。
浔阳近四千，始行七十里。
人烦马蹄跙，劳苦已如此。','',''),('quantangshi-22409','仙娥峰下作','白居易','quantangshi','','卷23','我为东南行，始登商山道。
商山无数峰，最爱仙娥好。
参差树若插，匼匝云如抱。
渴望寒玉泉，香闻紫芝草。
青崖屏削碧，白石牀铺缟。
向无如此物，安足留四皓。
感彼私自问，归山何不早？
可能尘土中，还随众人老。','',''),('quantangshi-22410','微雨夜行','白居易','quantangshi','','卷23','漠漠秋云起，稍稍夜寒生。
但觉衣裳湿，无点亦无声。','',''),('quantangshi-22411','再到襄阳访问旧居','白居易','quantangshi','','卷23','昔到襄阳日，髯髯初有髭。
今过襄阳日，髭鬓半成丝。
旧游都是梦，乍到忽如归。
东郭蓬蒿宅，荒凉今属谁。
故知多零落，闾井亦迁移。
独有秋江水，烟波似旧时。','',''),('quantangshi-22412','寄微之三首 一','白居易','quantangshi','','卷23','江州望通州，天涯与地末。
有山万丈高，有江千里阔。
间之以云雾，飞鸟不可越。
谁知千古险，为我二人设。
通州君初到，郁郁愁如结。
江州我方去，迢迢行未歇。
道路日乖隔，音信日断绝。
因风欲寄语，地远声不彻。
生当复相逢，死当从此别。','',''),('quantangshi-22413','寄微之三首 二','白居易','quantangshi','','卷23','君游襄阳日，我在长安住。
今君在通州，我过襄阳去。
襄阳九里郭，楼堞连云树。
顾此稍依依，是君旧游处。
苍茫蒹葭水，中有浔阳路。
此去更相思，江西少亲故。','',''),('quantangshi-22414','寄微之三首 三','白居易','quantangshi','','卷23','去国日已远，喜逢物似人。
如何含此意，江上坐思君。
有如河岳气，相合方氛氲。
狂风吹中绝，两处成孤云。
风回终有时，云合岂无因。
努力各自爱，穷通我尔身。','',''),('quantangshi-22415','舟中雨夜','白居易','quantangshi','','卷23','江云暗悠悠，江风冷修修。
夜雨滴船背，风浪打船头。
船中有病客，左降向江州。','',''),('quantangshi-22416','夜闻歌者','白居易','quantangshi','','卷23','夜泊鹦鹉洲，江月秋澄澈。
邻船有歌者，发词堪愁绝。
歌罢继以泣，泣声通复咽。
寻声见其人，有妇颜如雪。
独倚帆樯立，娉婷十七八。
夜泪如真珠，双双堕明月。
借问谁家妇，歌泣何凄切。
一问一霑襟，低眉终不说。','',''),('quantangshi-22417','江楼闻砧','白居易','quantangshi','','卷23','江人授衣晚，十月始闻砧。
一夕高楼月，万里故园心。','',''),('quantangshi-22418','宿东林寺','白居易','quantangshi','','卷23','经窗灯焰短，僧炉火气深。
索落庐山夜，风雪宿东林。','',''),('quantangshi-22419','忆洛下故园','白居易','quantangshi','','卷23','浔阳迁谪地，洛阳离乱年。
烟尘三川上，炎瘴九江边。
乡心坐如此，秋风仍飒然。','',''),('quantangshi-22420','赠别崔五','白居易','quantangshi','','卷23','朝送南去客，暮迎北来宾。
孰云当大路，少遇心所亲。
劳者念息肩，热者思濯身。
何如愁独日，忽见平生人。
平生已不浅，是日重殷勤。
问从何处来，及此江亭春。
江天春多阴，夜月隔重云。
移尊树间饮，灯照花纷纷。
一会不易得，余事何足云。
明旦又分手，今夕且欢忻。','',''),('quantangshi-22421','春晚寄微之','白居易','quantangshi','','卷23','三月江水阔，悠悠桃花波。
年芳与心事，此地共蹉跎。
南国方谴谪，中原正兵戈。
眼前故人少，头上白发多。
通州更迢遰，春尽复如何。','',''),('quantangshi-22422','渐老','白居易','quantangshi','','卷23','今朝复明日，不觉年齿暮。
白发逐梳落，朱颜辞镜去。
当春颇愁寂，对酒寡欢趣。
遇境多怆辛，逢人益敦故。
形质属天地，推迁从不住。','',''),('quantangshi-22423','送幼史','白居易','quantangshi','','卷23','淮右寇未散，江西岁再徂。
故里干戈地，行人风雪途。
此时与尔别，江畔立踟蹰。','',''),('quantangshi-22424','夜雪','白居易','quantangshi','','卷23','已讶衾枕冷，复见窗户明。
夜深知雪重，时闻折竹声。','',''),('quantangshi-22425','寄行简','白居易','quantangshi','','卷23','郁郁眉多敛，默默口寡言。
岂是愿如此，举目谁与欢。
去春尔西征，从事巴蜀间。
今春我南谪，抱疾江海壖。
相去六千里，地绝天邈然。
十书九不达，何以开忧颜。
渴人多梦饮，饥人多梦餐。
春来梦何处，合眼到东川。','',''),('quantangshi-22426','首夏','白居易','quantangshi','','卷23','孟夏百物滋，动植一时好。
麋鹿乐深林，虫蛇喜丰草。
翔禽爱密叶，游鳞悦新藻。
天和遗漏处，而我独枯槁。
一身在天末，骨肉皆远道。
旧国无来人，寇戎尘浩浩。
沈忧竟何益，祗自劳怀抱。
不如放身心，冥然任天造。
浔阳多美酒，可使杯不燥。
湓鱼贱如泥，烹炙无昏早。
朝饭山下寺，暮醉湖中岛。
何必归故乡，兹焉可终老。','',''),('quantangshi-22427','孟夏思渭村旧居寄舍弟','白居易','quantangshi','','卷23','啧啧雀引雏，稍稍笋成竹。
时物感人情，忆我故乡曲。
故园渭水上，十载事樵牧。
手种榆柳成，阴阴覆墙屋。
兔隐豆苗肥，鸟鸣桑椹熟。
前年当此时，与尔同游瞩。
诗书课弟侄，农圃资童仆。
日暮麦登场，天晴蚕坼簇。
弄泉南涧坐，待月东亭宿。
兴发饮数杯，闷来棊一局。
一朝忽分散，万里仍羁束。
井鲋思反泉，笼莺悔出谷。
九江地卑湿，四月天炎燠。
苦雨初入梅，瘴云稍含毒。
泥秧水畦稻，灰种畲田粟。
已讶殊岁时，仍嗟异风俗。
闲登郡楼望，日落江山绿。
归雁拂乡心，平湖断人目。
殊方我漂泊，旧里君幽独。
何时同一瓢，饮水心亦足。','',''),('quantangshi-22428','早蝉','白居易','quantangshi','','卷23','六月初七日，江头蝉始鸣。
石楠深叶里，薄暮两三声。
一催衰鬓色，再动故园情。
西风殊未起，秋思先秋生。
忆昔在东掖，宫槐花下听。
今朝无限思，云树绕湓城。','',''),('quantangshi-22429','感情','白居易','quantangshi','','卷23','中庭晒服玩，忽见故乡履。
昔赠我者谁，东邻婵娟子。
因思赠时语，特用结终始。
永愿如履綦，双行复双止。
自吾谪江郡，漂荡三千里。
为感长情人，提携同到此。
今朝一惆怅，反覆看未已。
人只履犹双，何曾得相似。
可嗟复可惜，锦表绣为里。
况经梅雨来，色黯花草死。','',''),('quantangshi-22430','南湖晚秋','白居易','quantangshi','','卷23','八月白露降，湖中水方老。
旦夕秋风多，衰荷半倾倒。
手攀青枫树，足蹋黄芦草。
惨澹老容颜，冷落秋怀抱。
有兄在淮楚，有弟在蜀道。
万里何时来，烟波白浩浩。','',''),('quantangshi-22431','郡厅有树晚荣早凋人不识名因题其上','白居易','quantangshi','','卷23','浔阳郡厅后，有树不知名。
秋先梧桐落，春后桃李荣。
五月始萌动，八月已凋零。
左右皆松桂，四时郁青青。
岂量雨露恩，霑濡不均平。
荣枯各有分，天地本无情。
顾我亦相类，早衰向晚成。
形骸少多病，三十不丰盈。
毛鬓早改变，四十白髭生。
谁教两萧索，相对此江城。','',''),('quantangshi-22432','感秋怀微之','白居易','quantangshi','','卷23','叶下湖又波，秋风此时至。
谁知濩落心，先纳萧条气。
推移感流岁，漂泊思同志。
昔为烟霄侣，今作泥涂吏。
白鸥毛羽弱，青凤文章异。
各闭一笼中，岁晚同顦顇。','',''),('quantangshi-22433','因沐感发寄朗上人二首 一','白居易','quantangshi','','卷23','年长身转慵，百事无所欲。
乃至头上发，经年方一沐。
沐稀发苦落，一沐仍半秃。
短鬓经霜蓬，老面辞春木。
强年过犹近，衰相来何速。
应是烦恼多，心焦血不足。','',''),('quantangshi-22434','因沐感发寄朗上人二首 二','白居易','quantangshi','','卷23','渐少不满把，渐短不盈尺。
况兹短少中，日夜落复白。
既无神仙术，何除老死籍。
祗有解脱门，能度衰苦厄。
掩镜望东寺，降心谢禅客。
衰白何足言，剃落犹不惜。','',''),('quantangshi-22435','早蝉','白居易','quantangshi','','卷23','月出先照山，风生先动水。
亦如早蝉声，先入闲人耳。
一闻愁意结，再听乡心起。
渭上新蝉声，先听浑相似。
衡门有谁听，日暮槐花里。','',''),('quantangshi-22436','苦热喜凉','白居易','quantangshi','','卷23','经时苦炎暑，心体但烦倦。
白日一何长，清秋不可见。
岁功成者去，天数极则变。
潜知寒燠间，迁次如乘传。
火云忽朝敛，金风俄夕扇。
枕簟遂清凉，筋骸稍轻健。
因思望月侣，好卜迎秋宴。
竟夜无客来，引杯还自劝。','',''),('quantangshi-22437','早秋晚望兼呈韦侍郎','白居易','quantangshi','','卷23','九派绕孤城，城高生远思。
人烟半在船，野水多于地。
穿霞日脚直，驱雁风头利。
去国来几时，江上秋三至。
夫君亦沦落，此地同飘寄。
悯默向隅心，摧颓触笼翅。
且谋眼前计，莫问胸中事。
浔阳酒甚浓，相劝时时醉。','',''),('quantangshi-22438','司马宅','白居易','quantangshi','','卷23','雨径绿芜合，霜园红叶多。
萧条司马宅，门巷无人过。
唯对大江水，秋风朝夕波。','',''),('quantangshi-22439','司马厅独宿','白居易','quantangshi','','卷23','荒凉满庭草，偃亚侵檐竹。
府吏下厅帘，家僮开被襆。
数声城上漏，一点窗间烛。
官曹冷似冰，谁肯来同宿。','',''),('quantangshi-22440','梦与李七庾三十三同访元九','白居易','quantangshi','','卷23','夜梦归长安，见我故亲友。
损之在我左，顺之在我右。
云是二月天，春风出携手。
同过靖安里，下马寻元九。
元九正独坐，见我笑开口。
还指西院花，仍开北亭酒。
如言各有故，似惜欢难久。
神合俄顷间，神离欠伸后。
觉来疑在侧，求索无所有。
残灯影闪墙，斜月光穿牖。
天明西北望，万里君知否。
老去无见期，踟蹰搔白首。','',''),('quantangshi-22441','秋槿','白居易','quantangshi','','卷23','风露飒已冷，天色亦黄昏。
中庭有槿花，荣落同一晨。
秋开已寂莫，夕陨何纷纷。
正怜少颜色，复叹不逡巡。
感此因念彼，怀哉聊一陈。
男儿老富贵，女子晚婚姻。
头白始得志，色衰方事人。
后时不获已，安得如青春。','',''),('quantangshi-22442','答元郎中杨员外喜乌见寄','白居易','quantangshi','','卷23','南宫鸳鸯地，何忽乌来止。
故人锦帐郎，闻乌笑相视。
疑乌报消息，望我归乡里。
我归应待乌头白，慙愧元郎误欢喜。','',''),('quantangshi-22443','初入峡有感','白居易','quantangshi','','卷23','上有万仞山，下有千丈水。
苍苍两崖间，阔狭容一苇。
瞿唐呀直泻，滟滪屹中峙。
未夜黑岩昏，无风白浪起。
大石如刀劒，小石如牙齿。
一步不可行，况千三百里。
苒蒻竹篾𥮘，欹危檝师趾。
一跌无完舟，吾生系于此。
常闻仗忠信，蛮貊可行矣。
自古漂沈人，岂尽非君子。
况吾时与命，蹇舛不足恃。
常恐不才身，复作无名死。','',''),('quantangshi-22444','过昭君村','白居易','quantangshi','','卷23','灵珠产无种，彩云出无根。
亦如彼姝子，生此遐陋村。
至丽物难掩，遽选入君门。
独美众所嫉，终弃出塞垣。
唯此希代色，岂无一顾恩。
事排势须去，不得由至尊。
白黑既可变，丹青何足论。
竟埋代北骨，不返巴东魂。
惨澹晚云水，依稀旧乡园。
妍姿化已久，但有村名存。
村中有遗老，指点为我言。
不敢往者戒，恐贻来者冤。
至今村女面，烧灼成瘢痕。','',''),('quantangshi-22445','自江州至忠州','白居易','quantangshi','','卷23','前在浔阳日，已叹宾朋寡。
忽忽抱忧怀，出门无处写。
今来转深僻，穷峡巅山下。
五月断行舟，滟堆正如马。
巴人类猨狖，矍铄满山野。
敢望见交亲，喜逢似人者。','',''),('quantangshi-22446','初到忠州登东楼寄万州杨八使君','白居易','quantangshi','','卷23','山束邑居窄，峡牵气候偏。
林峦少平地，雾雨多阴天。
隐隐煮盐火，漠漠烧畲烟。
赖此东楼夕，风月时翛然。
凭轩望所思，目断心涓涓。
背春有去雁，上水无来船。
我怀巴东守，本是关西贤。
平生已不浅，流落重相怜。
水梗漂万里，笼禽囚五年。
新恩同雨露，远郡邻山川。
书信虽往复，封疆徒接连。
其如美人面，欲见杳无缘。','',''),('quantangshi-22447','郡中','白居易','quantangshi','','卷23','乡路音信断，山城日月迟。
欲知州近远，阶前摘荔枝。','',''),('quantangshi-22448','西楼夜','白居易','quantangshi','','卷23','悄悄复悄悄，城隅隐林杪。
山郭灯火稀，峡天星汉少。
年光东流水，生计南枝鸟。
月没江沈沈，西楼殊未晓。','',''),('quantangshi-22449','东楼晓','白居易','quantangshi','','卷23','脉脉复脉脉，东楼无宿客。
城暗云雾多，峡深田地窄。
宵灯尚留焰，晨禽初展翮。
欲知山高低，不见东方白。','',''),('quantangshi-22450','寄王质夫','白居易','quantangshi','','卷23','忆始识君时，爱君世缘薄。
我亦吏王畿，不为名利着。
春寻仙游洞，秋上云居阁。
楼观水潺潺，龙潭花漠漠。
吟诗石上坐，引酒泉边酌。
因话出处心，心期老岩壑。
忽从风雨别，遂被簪缨缚。
君作出山云，我为入笼鹤。
笼深鹤残顇，山远云飘泊。
去处虽不同，同负平生约。
今来各何在，老去随所托。
我守巴南城，君佐征西幕。
年颜渐衰飒，生计仍萧索。
方含去国愁，且羡从军乐。
旧游疑是梦，往事思如昨。
相忆春又深，故山花正落。','',''),('quantangshi-22451','南宾郡斋即事寄杨万州','白居易','quantangshi','','卷23','山上巴子城，山下巴江水。
中有穷独人，强名为刺史。
时时窃自哂，刺史岂如是。
仓粟餧家人，黄缣裹妻子。
莓苔翳冠带，雾雨霾楼雉。
衙鼓暮复朝，郡斋卧还起。
回头望南浦，亦在烟波里。
而我复何嗟，夫君犹滞此。','',''),('quantangshi-22452','招萧处士','白居易','quantangshi','','卷23','峡内岂无人，所逢非所思。
门前亦有客，相对不相知。
仰望但云树，俯顾惟妻儿。
寝食起居外，端然无所为。
东郊萧处士，聊可与开眉。
能饮满杯酒，善吟长句诗。
庭前吏散后，江畔路干时。
请君携竹杖，一赴郡斋期。','',''),('quantangshi-22453','庭槐','白居易','quantangshi','','卷23','南方饶竹树，唯有青槐稀。
十种七八死，纵活亦支离。
何此郡庭下，一株独华滋。
蒙蒙碧烟叶，袅袅黄花枝。
我家渭水上，此树荫前墀。
忽向天涯见，忆在故园时。
人生有情感，遇物牵所思。
树木犹复尔，况见旧亲知。','',''),('quantangshi-22454','送客回晚兴','白居易','quantangshi','','卷23','城上云雾开，沙头风浪定。
参差乱山出，澹泞平江净。
行客舟已远，居人酒初醒。
袅袅秋竹梢，巴蝉声似磬。','',''),('quantangshi-22455','东楼竹','白居易','quantangshi','','卷23','潇洒城东楼，绕楼多修竹。
森然一万竿，白粉封青玉。
卷帘睡初觉，欹枕看未足。
影转色入楼，牀席生浮绿。
空城绝宾客，向夕弥幽独。
楼上夜不归，此君留我宿。','',''),('quantangshi-22456','九日登巴台','白居易','quantangshi','','卷23','黍香酒初熟，菊暖花未开。
闲听竹枝曲，浅酌茱萸杯。
去年重阳日，漂泊湓城隈。
今岁重阳日，萧条巴子台。
旅鬓寻已白，乡书久不来。
临觞一搔首，座客亦裴回。','',''),('quantangshi-22457','东城寻春','白居易','quantangshi','','卷23','老色日上面，欢情日去心。
今既不如昔，后当不如今。
今犹未甚衰，每事力可任。
花时仍爱出，酒后尚能吟。
但恐如此兴，亦随日销沈。
东城春欲老，勉强一来寻。','',''),('quantangshi-22458','江上送客','白居易','quantangshi','','卷23','江花已萎绝，江草已消歇。
远客何处归，孤舟今日发。
杜鹃声似哭，湘竹斑如血。
共是多感人，仍为此中别。','',''),('quantangshi-22459','桐花','白居易','quantangshi','','卷23','春令有常候，清明桐始发。
何此巴峡中，桐花开十月。
岂伊物理变，信是土宜别。
地气反寒暄，天时倒生杀。
草木坚强物，所禀固难夺。
风候一参差，荣枯遂乖剌。
况吾北人性，不耐南方热。
强羸寿夭间，安得依时节。','',''),('quantangshi-22460','早祭风伯因怀李十一舍人','白居易','quantangshi','','卷23','远郡虽褊陋，时祀奉朝经。
夙兴祭风伯，天气晓冥冥。
导骑与从吏，引我出东坰。
水雾重如雨，山火高于星。
忽忆早朝日，与君趋紫庭。
步登龙尾道，却望终南青。
一别身向老，所思心未宁。
至今想在耳，玉音尚玲玲。','',''),('quantangshi-22461','花下对酒二首 一','白居易','quantangshi','','卷23','蔼蔼江气春，南宾闰正月。
梅樱与桃杏，次第城上发。
红房烂簇火，素艳纷团雪。
香惜委风飘，愁牵压枝折。
楼中老太守，头上新白发。
冷澹病心情，暄和好时节。
故园音信断，远郡亲宾绝。
欲问花前尊，依然为谁设。','',''),('quantangshi-22462','花下对酒二首 二','白居易','quantangshi','','卷23','引手攀红樱，红樱落似霰。
仰首看白日，白日走如箭。
年芳与时景，顷刻犹衰变。
况是血肉身，安能长强健。
人心苦迷执，慕贵忧贫贱。
愁色常在眉，欢容不上面。
况吾头半白，把镜非不见。
何必花下杯，更待他人劝。','',''),('quantangshi-22463','不二门','白居易','quantangshi','','卷23','两眼日将暗，四肢渐衰瘦。
束带剩昔围，穿衣妨宽袖。
流年似江水，奔注无昏昼。
志气与形骸，安得长依旧。
亦曾登玉陛，举措多纰缪。
至今金阙籍，名姓独遗漏。
亦曾烧大药，消息乖火候。
至今残丹砂，烧干不成就。
行藏事两失，忧恼心交鬬。
化作顦顇翁，抛身在荒陋。
坐看老病逼，须得医王救。
唯有不二门，其间无夭寿。','',''),('quantangshi-22464','我身','白居易','quantangshi','','卷23','我身何所似，似彼孤生蓬。
秋霜翦根断，浩浩随长风。
昔游秦雍间，今落巴蛮中。
昔为意气郎，今作寂寥翁。
外貌虽寂莫，中怀颇冲融。
赋命有厚薄，委心任穷通。
通当为大鹏，举翅摩苍穹。
穷则为鹪鹩，一枝足自容。
苟知此道者，身穷心不穷。','',''),('quantangshi-22465','哭王质夫','白居易','quantangshi','','卷23','仙游寺前别，别来十年余。
生别犹怏怏，死别复何如。
客从梓潼来，道君死不虚。
惊疑心未信，欲哭复踟蹰。
踟蹰寝门侧，声发涕亦俱。
衣上今日泪，箧中前月书。
怜君古人风，重有君子儒。
篇咏陶谢辈，风流嵇阮徒。
出身既蹇屯，生世仍须臾。
诚知天至高，安得不一呼。
江南有毒蟒，江北有妖狐。
皆享千年寿，多于王质夫。
不知彼何德，不识此何辜。','',''),('quantangshi-22466','东坡种花二首 一','白居易','quantangshi','','卷23','持钱买花树，城东坡上栽。
但购有花者，不限桃杏梅。
百果参杂种，千枝次第开。
天时有早晚，地力无高低。
红者霞艳艳，白者雪皑皑。
游蠭逐不去，好鸟亦来栖。
前有长流水，下有小平台。
时拂台上石，一举风前杯。
花枝荫我头，花蘂落我怀。
独酌复独咏，不觉月平西。
巴俗不爱花，竟春无人来。
唯此醉太守，尽日不能回。','',''),('quantangshi-22467','东坡种花二首 二','白居易','quantangshi','','卷23','东坡春向暮，树木今何如。
漠漠花落尽，翳翳叶生初。
每日领童仆，荷鉏仍决渠。
刬土壅其本，引泉溉其枯。
小树低数尺，大树长丈余。
封植来几时，高下随扶疎。
养树既如此，养民亦何殊。
将欲茂枝叶，必先救根株。
云何救根株，劝农均赋租。
云何茂枝叶，省事宽刑书。
移此为郡政，庶几甿俗苏。','',''),('quantangshi-22468','登城东古台','白居易','quantangshi','','卷23','迢迢东郊上，有土青崔嵬。
不知何代物，疑是巴王台。
巴歌久无声，巴宫没黄埃。
靡靡春草合，牛羊缘四隈。
我来一登眺，目极心悠哉。
始见江山势，峰叠水环回。
凭高视听旷，向远胷襟开。
唯有故园念，时时东北来。','',''),('quantangshi-22469','哭诸故人因寄元八','白居易','quantangshi','','卷23','昨日哭寝门，今日哭寝门。
借问所哭谁，无非故交亲。
伟卿既长往，质夫亦幽沦。
屈指数年世，收涕自思身。
彼皆少于我，先为泉下人。
我今头半白，焉得身久存。
好狂元郎中，相识二十春。
昔见君生子，今闻君抱孙。
存者尽老大，逝者已成尘。
早晚升平宅，开眉一见君。','',''),('quantangshi-22470','郡中春宴因赠诸客','白居易','quantangshi','','卷23','仆本儒家子，待诏金马门。
尘忝亲近地，孤负圣明恩。
一旦奉优诏，万里牧远人。
可怜岛夷帅，自称为使君。
身骑牂牁马，口食涂江鳞。
暗澹绯衫故，斓斑白发新。
是时岁二月，玉历布春分。
颁条示皇泽，命宴及良辰。
冉冉趋府吏，蚩蚩聚州民。
有如蛰虫鸟，亦应天地春。
薰草席铺坐，藤枝酒注樽。
中庭无平地，高下随所陈。
蛮鼓声坎坎，巴女舞蹲蹲。
使君居上头，掩口语众宾。
勿笑风俗陋，勿欺官府贫。
蠭巢与蚁穴，随分有君臣。','',''),('quantangshi-22471','开元寺东池早春','白居易','quantangshi','','卷23','池水暖温暾，水清波潋滟。
簇簇青泥中，新蒲叶如劒。
梅房小白裹，柳彩轻黄染。
顺气草熏熏，适情鸥泛泛。
旧游成梦寐，往事随阳焱。
芳物感幽怀，一动平生念。','',''),('quantangshi-22472','东溪种柳','白居易','quantangshi','','卷23','野性爱栽植，植柳水中坻。
乘春持斧斫，裁截而树之。
长短既不一，高下随所宜。
倚岸埋大干，临流插小枝。
松柏不可待，楩柟固难移。
不如种此树，此树易荣滋。
无根亦可活，成阴况非迟。
三年未离郡，可以见依依。
种罢水边憩，仰头闲自思。
富贵本非望，功名须待时。
不种东溪柳，端坐欲何为。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22473','卧小斋','白居易','quantangshi','','卷23','朝起视事毕，晏坐饱食终。
散步长廊下，卧退小斋中。
拙政自多暇，幽情谁与同。
孰云二千石，心如田野翁。','',''),('quantangshi-22474','步东坡','白居易','quantangshi','','卷23','朝上东坡步，夕上东坡步。
东坡何所爱，爱此新成树。
种植当岁初，滋荣及春暮。
信意取次栽，无行亦无数。
绿阴斜景转，芳气微风度。
新叶鸟下来，萎花蝶飞去。
闲携斑竹杖，徐曳黄麻屦。
欲识往来频，青芜成白路。','',''),('quantangshi-22475','征秋税毕题郡南亭','白居易','quantangshi','','卷23','高城直下视，蠢蠢见巴蛮。
安可施政教，尚不通语言。
且喜赋敛毕，幸闻闾井安。
岂伊循良化，赖此丰登年。
案牍既简少，池馆亦清闲。
秋雨檐果落，夕钟林鸟还。
南亭日潇洒，偃卧恣疎顽。','',''),('quantangshi-22476','蚊蟆','白居易','quantangshi','','卷23','巴徼炎毒早，二月蚊蟆生。
咂肤拂不去，绕耳薨薨声。
斯物颇微细，中人初甚轻。
如有肤受谮，久则疮痏成。
痏成无奈何，所要防其萌。
么虫何足道，潜喻儆人情。','',''),('quantangshi-22477','登龙昌上寺望江南山怀钱舍人','白居易','quantangshi','','卷23','骑马出西郭，悠悠欲何之。
独上高寺去，一与白云期。
虚槛晚潇洒，前山碧参差。
忽似青龙合，同望玉峰时。
因咏松雪句，永怀鸾鹤姿。
六年不相见，况乃隔荣衰。','',''),('quantangshi-22478','郊下','白居易','quantangshi','','卷23','西日照高树，树头子规鸣。
东风吹野水，水畔江蓠生。
尽日看山立，有时寻涧行。
兀兀长如此，何许似专城。','',''),('quantangshi-22479','遣怀','白居易','quantangshi','','卷23','乐往必悲生，泰来由否极。
谁言此数然，吾道何终塞。
尝求詹尹卜，拂龟竟默默。
亦曾仰问天，天但苍苍色。
自兹唯委命，名利心双息。
近日转安闲，乡园亦休忆。
回看世间苦，苦在求不得。
我今无所求，庶离忧悲域。','',''),('quantangshi-22480','岁晚','白居易','quantangshi','','卷23','霜降水返壑，风落木归山。
冉冉岁将宴，物皆复本源。
何此南迁客，五年独未还。
命屯分已定，日久心弥安。
亦尝心与口，静念私自言。
去国固非乐，归乡未必欢。
何须自生苦，舍易求其难。','',''),('quantangshi-22481','负冬日','白居易','quantangshi','','卷23','杲杲冬日出，照我屋南隅。
负暄闭目坐，和气生肌肤。
初似饮醇醪，又如蛰者苏。
外融百骸畅，中适一念无。
旷然忘所在，心与虚空俱。','',''),('quantangshi-22482','委顺','白居易','quantangshi','','卷23','山城虽荒芜，竹树有嘉色。
郡俸诚不多，亦足充衣食。
外累由心起，心宁累自息。
尚欲忘家乡，谁能算官职。
宜怀齐远近，委顺随南北。
归去诚可怜，天涯住亦得。','',''),('quantangshi-22483','宿溪翁','白居易','quantangshi','','卷23','众心爱金玉，众口贪酒肉。
何如此溪翁，饮瓢亦自足。
溪南刈薪草，溪北修墙屋。
岁种一顷田，春驱两黄犊。
于中甚安适，此外无营欲。
溪畔偶相逢，庵中遂同宿。
醉翁向朝市，问我何官禄。
虚言笑杀翁，郎官应列宿。','',''),('quantangshi-22484','重过寿泉忆与杨九别时因题店壁','白居易','quantangshi','','卷23','商州南十里，有水名寿泉。
涌出石崖下，流经山店前。
忆昔相送日，我去君言还。
寒波与老泪，此地共潺湲。
一去历万里，再来经六年。
形容已变改，处所犹依然。
他日君过此，殷勤吟此篇。','',''),('quantangshi-22485','西掖早秋直夜书意','白居易','quantangshi','','卷23','凉风起禁掖，新月生宫沼。
夜半秋暗来，万年枝袅袅。
炎凉递时节，钟鼓交昏晓。
遇圣惜年衰，报恩愁力小。
素餐无补益，朱绶虚缠绕。
冠盖栖野云，稻粱养山鸟。
量能私自省，所得已非少。
五品不为贱，五十不为夭。
若无知足心，贪求何日了。','',''),('quantangshi-22486','庭松','白居易','quantangshi','','卷23','堂下何所有，十松当我阶。
乱立无行次，高下亦不齐。
高者三丈长，下者十尺低。
有如野生物，不知何人栽。
接以青瓦屋，承之白沙台。
朝昏有风月，燥湿无尘泥。
疎韵秋槭槭，凉阴夏凄凄。
春深微雨夕，满叶珠蓑蓑。
岁暮大雪天，压枝玉皑皑。
四时各有趣，万木非其侪。
去年买此宅，多为人所咍。
一家二十口，移转就松来。
移来有何得，但得烦襟开。
即此是益友，岂必交贤才。
顾我犹俗士，冠带走尘埃。
未称为松主，时时一愧怀。','',''),('quantangshi-22487','竹窗','白居易','quantangshi','','卷23','常爱辋川寺，竹窗东北廊。
一别十余载，见竹未曾忘。
今春二月初，卜居在新昌。
未暇作廐库，且先营一堂。
开窗不糊纸，种竹不依行。
意取北檐下，窗与竹相当。
绕屋声淅淅，逼人色苍苍。
烟通杳蔼气，月透玲珑光。
是时三伏天，天气热如汤。
独此竹窗下，朝回解衣裳。
轻纱一幅巾，小簟六尺牀。
无客尽日静，有风终夜凉。
乃知前古人，言事颇谙详。
清风北窗卧，可以傲羲皇。','',''),('quantangshi-22488','同韩侍郎游郑家池吟诗小饮','白居易','quantangshi','','卷23','野艇容三人，晚池流浼浼。
悠然依棹坐，水思如江海。
宿雨洗沙尘，晴风荡烟霭。
残阳上竹树，枝叶生光彩。
我本偶然来，景物如相待。
白鸥惊不起，绿芡行堪采。
齿发虽已衰，性灵未云改。
逢诗遇杯酒，尚有心情在。','',''),('quantangshi-22489','晚归有感','白居易','quantangshi','','卷23','朝吊李家孤，暮问崔家疾。
回马独归来，低眉心郁郁。
平生所善者，多不过六七。
如何十年间，零落三无一。
刘曾梦中见，元向花前失。
渐老与谁游，春城好风日。','',''),('quantangshi-22490','曲江感秋二首 一','白居易','quantangshi','','卷23','元和二年秋，我年三十七。
长庆二年秋，我年五十一。
中间十四年，六年居谴黜。
穷通与荣悴，委运随外物。
遂师庐山远，重吊湘江屈。
夜听竹枝愁，秋看滟堆没。
近辞巴郡印，又秉纶闱笔。
晚遇何足言，白发映朱绂。
销沈昔意气，改换旧容质。
独有曲江秋，风烟如往日。','',''),('quantangshi-22491','曲江感秋二首 二','白居易','quantangshi','','卷23','疎芜南岸草，萧飒西风树。
秋到未几时，蝉声又无数。
莎平绿茸合，莲落青房露。
今日临望时，往年感秋处。
池中水依旧，城上山如故。
独我鬓间毛，昔黑今垂素。
荣名与壮齿，相避如朝暮。
时命始欲来，年颜已先去。
当春不欢乐，临老徒惊误。
故作咏怀诗，题于曲江路。','',''),('quantangshi-22492','玩松竹二首 一','白居易','quantangshi','','卷23','龙蛇隐大泽，麋鹿游丰草。
栖凤安于梧，潜鱼乐于藻。
吾亦爱吾庐，庐中乐吾道。
前松后修竹，偃卧可终老。
各附其所安，不知他物好。','',''),('quantangshi-22493','玩松竹二首 二','白居易','quantangshi','','卷23','坐爱前檐前，卧爱北窗北。
窗竹多好风，檐松有嘉色。
幽怀一以合，俗念随缘息。
在尔虽无情，于予即有得。
乃知性相近，不必动与植。','',''),('quantangshi-22494','衰病无趣因吟所怀','白居易','quantangshi','','卷23','朝餐多不饱，夜卧常少睡。
自觉寝食间，多无少年味。
平生好诗酒，今亦将舍弃。
酒唯下药饮，无复曾欢醉。
诗多听人吟，自不题一字。
病姿与衰相，日夜相继至。
况当尚少朝，弥慙居近侍。
终当求一郡，聚少渔樵费。
合口便归山，不问人间事。','',''),('quantangshi-22495','逍遥咏','白居易','quantangshi','','卷23','亦莫恋此身，亦莫厌此身。
此身何足恋，万劫烦恼根。
此身何足厌，一聚虚空尘。
无恋亦无厌，始是逍遥人。','',''),('quantangshi-22496','短歌行','白居易','quantangshi','','卷23','曈曈太阳如火色，上行千里下一刻。
出为白昼入为夜，圆转如珠住不得。
住不得，可奈何，为君举酒歌短歌。
歌声苦，词亦苦，四座少年君听取。
今夕未竟明夕催，秋风才往春风回。
人无根蔕时不驻，朱颜白日相隳颓。
劝君且强笑一面，劝君且强饮一杯。
人生不得长欢乐，年少须臾老到来。','',''),('quantangshi-22497','生离别','白居易','quantangshi','','卷23','食檗不易食梅难，檗能苦兮梅能酸。
未如生别之为难，苦在心兮酸在肝。
晨鸡再鸣残月没，征马连嘶行人出。
回看骨肉哭一声，梅酸檗苦甘如蜜。
黄河水白黄云秋，行人河边相对愁。
天寒野旷何处宿？棠棃叶战风飕飕。
生离别，生离别，忧从中来无断绝。
忧极心劳血气衰，未年三十生白发。','',''),('quantangshi-22498','浩歌行','白居易','quantangshi','','卷23','天长地久无终毕，昨夜今朝又明日。
鬓发苍浪牙齿疎，不觉身年四十七。
前去五十有几年，把镜照面心茫然。
既无长绳系白日，又无大药驻朱颜。
朱颜日渐不如故，青史功名在何处？
欲留年少待富贵，富贵不来年少去。
去复去兮如长河，东流赴海无回波。
贤愚贵贱同归尽，北邙冢墓高嵯峨。
古来如此非独我，未死有酒且高歌。
颜回短命伯夷饿，我今所得亦已多。
功名富贵须待命，命若不来知奈何。','',''),('quantangshi-22499','王夫子','白居易','quantangshi','','卷23','王夫子，送君为一尉，东南三千五百里。
道途虽远位虽卑，月俸犹堪活妻子。
男儿口读古人书，束带敛手来从事。
近将徇禄给一家，远则行道佐时理。
行道佐时须待命，委身下位无为耻。
命苟未来且求食，官无卑高及远迩。
男儿上既未能济天下，下又不至饥寒死。
吾观九品至一品，其间气味都相似。
紫绶朱绂青布衫，颜色不同而已矣。
王夫子，别有一事欲劝君，遇酒逢春且欢喜。','',''),('quantangshi-22500','江南遇天宝乐叟','白居易','quantangshi','','卷23','白头病叟泣且言，禄山未乱入棃园。
能弹琵琶和法曲，多在华清随至尊。
是时天下太平久，年年十月坐朝元。
千官起居环佩合，万国会同车马奔。
金钿照耀石瓮寺，兰麝熏煮温汤源。
贵妃宛转侍君侧，体弱不胜珠翠繁。
冬雪飘颻锦袍暖，春风荡漾霓裳飜。
欢娱未足燕寇至，弓劲马肥胡语喧。
豳土人迁避夷狄，鼎湖龙去哭轩辕。
从此漂沦落南土，万人死尽一身存。
秋风江上浪无限，暮雨舟中酒一尊。
涸鱼久失风波势，枯草曾霑雨露恩。
我自秦来君莫问，骊山渭水如荒村。
新丰树老笼明月，长生殿暗锁春云。
红叶纷纷盖欹瓦，绿苔重重封坏垣。
唯有中官作宫使，每年寒食一开门。','',''),('quantangshi-22501','送张山人归嵩阳','白居易','quantangshi','','卷23','黄昏惨惨天微雪，修行坊西鼓声绝。
张生马瘦衣且单，夜扣柴门与我别。
愧君冒寒来别我，为君酤酒张灯火。
酒酣火暖与君言，何事入关又出关。
答云前年偶下山，四十余月客长安。
长安古来名利地，空手无金行路难。
朝游九城陌，肥马轻车欺杀客。
暮宿五侯门，残茶冷酒愁杀人。
春明门，门前便是嵩山路。
幸有云泉容此身，明日辞君且归去。','',''),('quantangshi-22502','醉后走笔酬刘五主簿长句之赠兼简张大贾二十四先辈昆季','白居易','quantangshi','','卷23','刘兄文高行孤立，十五年前名翕习。
是时相遇在符离，我年二十君三十。
得意忘年心迹亲，寓居同县日知闻。
衡门寂莫朝寻我，古寺萧条暮访君。
朝来暮去多携手，穷巷贫居何所有。
秋灯夜写联句诗，春雪朝倾暖寒酒。
陴湖绿爱白鸥飞，濉水清怜红鲤肥。
偶语闲攀芳树立，相扶醉蹋落花归。
张贾弟兄同里巷，乘闲数数来相访。
雨天连宿草堂中，月夜徐行石桥上。
我年渐长忽自惊，镜中冉冉髭须生。
心畏后时同励志，身牵前事各求名。
问我栖栖何所适，乡人荐为鹿鸣客。
二千里别谢交游，三十韵诗慰行役。
出门可怜唯一身，敝裘瘦马入咸秦。
冬冬街鼓红尘暗，晚到长安无主人。
二贾二张与余弟，躯车逦迤来相继。
操词握赋为干戈，锋锐森然胜气多。
齐入文场同苦战，五人十载九登科。
二张得隽名居甲，美退争雄重告捷。
棠棣辉荣竝桂枝，芝兰芳馥和荆叶。
唯有沅犀屈未伸，握中自谓骇鸡珍。
三年不鸣鸣必大，岂独骇鸡当骇人。
元和运启千年圣，同遇明时余最幸。
始辞祕阁吏王畿，遽列谏垣升禁闱。
蹇步何堪鸣佩玉，衰容不称着朝衣。
阊阖晨开朝百辟，冕旒不动香烟碧。
步登龙尾上虚空，立去天颜无咫尺。
宫花似雪从乘舆，禁月如霜坐直庐。
身贱每惊随内宴，才微常愧草天书。
晚松寒竹新昌第，职居密近门多闭。
日暮银台下直回，故人到门门暂开。
回头下马一相顾，尘土满衣何处来？
敛手炎凉叙未毕，先说旧山今悔出。
岐阳旅宦少欢娱，江左羇游费时日。
赠我一篇行路吟，吟之句句披沙金。
岁月徒催白发貌，泥涂不屈青云心。
谁会茫茫天地意，短才获用长才弃。
我随鵷鹭入烟云，谬上丹墀为近臣。
君同鸾凤栖荆棘，犹着青袍作选人。
惆怅知贤不能荐，徒为出入蓬莱殿。
月慙谏纸二百张，岁愧俸钱三十万。
大底浮荣何足道，几度相逢即身老。
且倾斗酒慰羇愁，重话符离问旧游。
北巷邻居几家去，东林旧院何人住。
武里村花落复开，流沟山色应如故。
感此酬君千字诗，醉中分手又何之。
须知通塞寻常事，莫叹浮沈先后时。
慷慨临歧重相勉，殷勤别后加餐饭。
君不见买臣衣锦还故乡，五十身荣未为晚。','',''),('quantangshi-22503','和钱员外答卢员外早春独游曲江见寄长句','白居易','quantangshi','','卷23','春来有色暗融融，先到诗情酒思中。
柳岸霏微裛尘雨，杏园澹荡开花风。
闻君独游心郁郁，薄晚新晴骑马出。
醉思诗侣有同年，春叹翰林无暇日。
云夫首倡寒玉音，蔚章继和春搜吟。
此时我亦闭门坐，一日风光三处心。','',''),('quantangshi-22504','东墟晚歇','白居易','quantangshi','','卷23','凉风冷露萧索天，黄蒿紫菊荒凉田。
绕冢秋花少颜色，细虫小蝶飞飜飜。
中有腾腾独行者，手拄渔竿不骑马。
晚从南涧钓鱼回，歇此墟中白杨下。
褐衣半故白发新，人逢知我是何人。
谁言渭浦栖迟客，曾作甘泉侍从臣。','',''),('quantangshi-22505','客中月','白居易','quantangshi','','卷23','客从江南来，来时月上弦。
悠悠行旅中，三见清光圆。
晓随残月行，夕与新月宿。
谁谓月无情，千里远相逐。
朝发渭水桥，暮入长安陌。
不知今夜月，又作谁家客。','',''),('quantangshi-22506','挽歌词','白居易','quantangshi','','卷23','丹旐何飞扬，素骖亦悲鸣。
晨光照闾巷，輀车俨欲行。
萧条九月天，哀挽出重城。
借问送者谁，妻子与弟兄。
苍苍上古原，峨峨开新茔。
含酸一恸哭，异口同哀声。
旧陇转芜绝，新坟日罗列。
春风草绿北邙山，此地年年生死别。','',''),('quantangshi-22507','长相思','白居易','quantangshi','','卷23','九月西风兴，月冷露华凝。
思君秋夜长，一夜魂九升。
二月东风来，草拆花心开。
思君春日迟，一日肠九回。
妾住洛桥北，君住洛桥南。
十五即相识，今年二十三。
有如女萝草，生在松之侧。
蔓短枝苦高，萦回上不得。
人言人有愿，愿至天必成。
愿作远方兽，步步比肩行。
愿作深山木，枝枝连理生。','',''),('quantangshi-22508','山鹧鸪','白居易','quantangshi','','卷23','山鹧鸪，朝朝暮暮啼复啼，啼时露白风凄凄。
黄茅冈头秋日晚，苦竹岭下寒月低。
畲田有粟何不啄，石楠有枝何不栖？
迢迢不缓复不急，楼上舟中声暗入。
梦乡迁客展转卧，抱儿寡妇彷徨立。
山鹧鸪，尔本此乡鸟。
生不辞巢不别羣，何苦声声啼到晓。
啼到晓，唯能愁北人，南人惯闻如不闻。','',''),('quantangshi-22509','放旅雁','白居易','quantangshi','','卷23','九江十年冬大雪，江水生冰树枝折。
百鸟无食东西飞，中有旅雁声最饥。
雪中啄草冰上宿，翅冷腾空飞动迟。
江童持网捕将去，手携入市生卖之。
我本北人今谴谪，人鸟虽殊同是客。
见此客鸟伤客人，赎汝放汝飞入云。
雁雁汝飞向何处？第一莫飞西北去。
淮西有贼讨未平，百万甲兵久屯聚。
官军贼军相守老，食尽兵穷将及汝。
健儿饥饿射汝吃，拔汝翅翎为箭羽。','',''),('quantangshi-22510','送春归','白居易','quantangshi','','卷23','送春归，三月尽日日暮时。
去年杏园花飞御沟绿，何处送春曲江曲。
今年杜鹃花落子规啼，送春何处西江西。
帝城送春犹怏怏，天涯送春能不加惆怅。
莫惆怅，送春人。
冗员无替五年罢，应须准拟再送浔阳春。
五年炎凉凡十变，又知此身健不健。
好去今年江上春，明年未死还相见。','',''),('quantangshi-22511','山石榴寄元九','白居易','quantangshi','','卷23','山石榴，一名山踯躅，一名杜鹃花。
杜鹃啼时花扑扑，九江三月杜鹃来，一声催得一枝开。
江城上佐闲无事，山下斸得厅前栽。
烂熳一阑十八树，根株有数花无数。
千房万叶一时新，嫩紫殷红鲜麴尘。
泪痕裛损燕支脸，剪刀裁破红绡巾。
谪仙初堕愁在世，姹女新嫁娇泥春。
日射血珠将滴地，风飜火焰欲烧人。
闲折两枝持在手，细看不似人间有。
花中此物似西施，芙蓉芍药皆嫫母。
奇芳绝艳别者谁，通州迁客元拾遗。
拾遗初贬江陵去，去时正值青春暮。
商山秦岭愁杀君，山石榴花红夹路。
题诗报我何所云，苦云色似石榴帬。
当时丛畔唯思我，今日阑前只忆君。
忆君不见坐销落，日西风起红纷纷。','',''),('quantangshi-22512','画竹歌','白居易','quantangshi','','卷23','植物之中竹难写，故今虽画无似者。
萧郎下笔独逼真，丹青以来唯一人。
人画竹身肥拥肿，萧画茎瘦节节竦。
人画竹梢死羸垂，萧画枝活叶叶动。
不根而生从意生，不笋而成由笔成。
野塘水边崎岸侧，森森两丛十五茎。
婵娟不失筠粉态，萧飒尽得风烟情。
举头忽看不似画，低耳静听疑有声。
西丛七茎劲而健，省向天竺寺前石上见。
东丛八茎疎且寒，忆曾湘妃庙里雨中看。
幽姿远思少人别，与君相顾空长叹。
萧郎萧郎老可惜，手颤眼昏头雪色。
自言便是绝笔时，从今此竹尤难得。','',''),('quantangshi-22513','真娘墓','白居易','quantangshi','','卷23','真娘墓，虎丘道。
不识真娘镜中面，唯见真娘墓头草。
霜摧桃李风折莲，真娘死时犹少年。
脂肤荑手不牢固，世间尤物难留连。
难留连，易销歇，塞北花，江南雪。','',''),('quantangshi-22514','长恨歌','白居易','quantangshi','','卷23','汉皇重色思倾国，御宇多年求不得。
杨家有女初长成，养在深闺人未识。
天生丽质难自弃，一朝选在君王侧。
回眸一笑百媚生，六宫粉黛无颜色。
春寒赐浴华清池，温泉水滑洗凝脂。
侍儿扶起娇无力，始是新承恩泽时。
云鬓花颜金步摇，芙蓉帐暖度春宵。
春宵苦短日高起，从此君王不早朝。
承欢侍宴无闲暇，春从春游夜专夜。
后宫佳丽三千人，三千宠爱在一身。
金屋妆成娇侍夜，玉楼宴罢醉和春。
姊妹弟兄皆列土，可怜光彩生门户。
遂令天下父母心，不重生男重生女。
骊宫高处入青云，仙乐风飘处处闻。
缓歌慢舞凝丝竹，尽日君王看不足。
渔阳鞞鼓动地来，惊破霓裳羽衣曲。
九重城阙烟尘生，千乘万骑西南行。
翠华摇摇行复止，西出都门百余里。
六军不发无奈何，宛转蛾眉马前死。
花钿委地无人收，翠翘金雀玉搔头。
君王掩面救不得，回看血泪相和流。
黄埃散漫风萧索，云栈萦纡登劒阁。
峨嵋山下少人行，旌旗无光日色薄。
蜀江水碧蜀山青，圣主朝朝暮暮情。
行宫见月伤心色，夜雨闻铃肠断声。
天旋日转回龙驭，到此踌躇不能去。
马嵬坡下泥土中，不见玉颜空死处。
君臣相顾尽霑衣，东望都门信马归。
归来池苑皆依旧，太液芙蓉未央柳。
芙蓉如面柳如眉，对此如何不泪垂？
春风桃李花开夜，秋雨梧桐叶落时。
西宫南苑多秋草，宫叶满阶红不埽。
棃园弟子白发新，椒房阿监青娥老。
夕殿萤飞思悄然，孤灯挑尽未成眠。
迟迟钟鼓初长夜，耿耿星河欲曙天。
鸳鸯瓦冷霜华重，翡翠衾寒谁与共。
悠悠生死别经年，魂魄不曾来入梦。
临邛道士鸿都客，能以精诚致魂魄。
为感君王展转思，遂教方士殷勤觅。
排空驭气奔如电，升天入地求之徧。
上穷碧落下黄泉，两处茫茫皆不见。
忽闻海上有仙山，山在虚无缥缈间。
楼阁玲珑五云起，其中绰约多仙子。
中有一人字太真，雪肤花貌参差是。
金阙西厢叩玉扃，转教小玉报双成。
闻道汉家天子使，九华帐里梦魂惊。
揽衣推枕起裴回，珠箔银屏逦迤开。
云鬓半偏新睡觉，花冠不整下堂来。
风吹仙袂飘颻举，犹似霓裳羽衣舞。
玉容寂莫泪阑干，棃花一枝春带雨。
含情凝睇谢君王，一别音容两渺茫。
昭阳殿里恩爱绝，蓬莱宫中日月长。
回头下望人寰处，不见长安见尘雾。
唯将旧物表深情，钿合金钗寄将去。
钗留一股合一扇，钗擘黄金合分钿。
但教心似金钿坚，天上人间会相见。
临别殷勤重寄词，词中有誓两心知。
七月七日长生殿，夜半无人私语时。
在天愿作比翼鸟，在地愿为连理枝。
天长地久有时尽，此恨緜緜无绝期。','',''),('quantangshi-22515','妇人苦','白居易','quantangshi','','卷23','蝉鬓加意梳，蛾眉用心埽。
几度晓妆成，君看不言好。
妾身重同穴，君意轻偕老。
惆怅去年来，心知未能道。
今朝一开口，语少意何深。
愿引他时事，移君此日心。
人言夫妇亲，义合如一身。
及至死生际，何曾苦乐均。
妇人一丧夫，终身守孤孑。
有如林中竹，忽被风吹折。
一折不重生，枯死犹抱节。
男儿若丧妇，能不暂伤情。
应似门前柳，逢春易发荣。
风吹一枝折，还有一枝生。
为君委曲言，愿君再三听。
须知妇人苦，从此莫相轻。','',''),('quantangshi-22516','长安道','白居易','quantangshi','','卷23','花枝缺处青楼开，艳歌一曲酒一杯。
美人劝我急行乐，自古朱颜不再来。
君不见外州客，长安道，一回来，一回老。','',''),('quantangshi-22517','潜别离','白居易','quantangshi','','卷23','不得哭，潜别离，不得语，暗相思。
两心之外无人知，深笼夜鏁独栖鸟。
利劒春断连理枝，河水虽浊有清日。
乌头虽黑有白时，唯有潜离与暗别。','',''),('quantangshi-22518','隔浦莲','白居易','quantangshi','','卷23','隔浦爱红莲，昨日看犹在。
夜来风吹落，只得一回采。
花开虽有明年期，复愁明年还暂时。','',''),('quantangshi-22519','寒食野望吟','白居易','quantangshi','','卷23','丘墟郭门外，寒食谁家哭。
风吹旷野纸钱飞，古墓累累春草绿。
棠棃花映白杨树，尽是死生离别处。
冥寞重泉哭不闻，萧萧暮雨人归去。','',''),('quantangshi-22520','琵琶引','白居易','quantangshi','','卷23','浔阳江头夜送客，枫叶荻花秋索索。
主人下马客在船，举酒欲饮无管弦。
醉不成欢惨将别，别时茫茫江浸月。
忽闻水上琵琶声，主人忘归客不发。
寻声暗问弹者谁，琵琶声停欲语迟。
移船相近邀相见，添酒回灯重开宴。
千呼万唤始出来，犹抱琵琶半遮面。
转轴拨弦三两声，未成曲调先有情。
弦弦掩抑声声思，似诉平生不得意。
低眉信手续续弹，说尽心中无限事。
轻拢慢拈抹复挑，初为霓裳后六幺。
大弦嘈嘈如急雨，小弦切切如私语。
嘈嘈切切错杂弹，大珠小珠落玉盘。
间关莺语花底滑，幽咽泉流水下滩。
水泉冷涩弦疑绝，疑绝不通声暂歇。
别有幽愁暗恨生，此时无声胜有声。
银瓶乍破水浆迸，铁骑突出刀枪鸣。
曲终收拨当心画，四弦一声如裂帛。
东舟西舫悄无言，唯见江心秋月白。
沈吟放拨插弦中，整顿衣裳起敛容。
自言本是京城女，家在虾蟇陵下住。
十三学得琵琶成，名蜀教坊第一部。
曲罢曾教善才伏，妆成每被秋娘妬。
五陵年少争缠头，一曲红绡不知数。
钿头云箆击节碎，血色罗帬飜酒污。
今年欢笑复明年，秋月春风等闲度。
弟走从军阿姨死，暮去朝来颜色故。
门前冷落鞍马稀，老大嫁作商人妇。
商人重利轻别离，前月浮梁买茶去。
去来江口守空船，绕船月明江水寒。
夜深忽梦少年事，梦啼妆泪红阑干。
我闻琵琶已叹息，又闻此语重唧唧。
同是天涯沦落人，相逢何必曾相识。
我从去年辞帝京，谪居卧病浔阳城。
浔阳小处无音乐，终岁不闻丝竹声。
住近湓江地低湿，黄芦苦竹绕宅生。
其间旦暮闻何物，杜鹃啼血猨哀鸣。
春江花朝秋月夜，往往取酒还独倾。
岂无山歌与村笛，呕哑嘲哳难为听。
今夜闻君琵琶语，如听仙乐耳暂明。
莫辞更坐弹一曲，为君飜作琵琶行。
感我此言良久立，却坐促弦弦转急。
凄凄不似向前声，满座重闻皆掩泣。
座中泣下谁最多，江州司马青衫湿。','',''),('quantangshi-22521','简简吟','白居易','quantangshi','','卷23','苏家小女名简简，芙蓉花顋柳叶眼。
十一把镜学点妆，十二抽针能绣裳。
十三行坐事调品，不肯迷头白地藏。
玲珑云髻生花样，飘颻风袖蔷薇香。
殊姿异态不可状，忽忽转动如有光。
二月繁霜杀桃李，明年欲嫁今年死。
丈人阿母勿悲啼，此女不是凡夫妻。
恐是天仙谪人世，只合人间十三岁。
大都好物不坚牢，彩云易散琉璃脆。','',''),('quantangshi-22522','花非花','白居易','quantangshi','','卷23','花非花，雾非雾，夜半来，天明去。
来如春梦几多时，去似朝云无觅处。','',''),('quantangshi-22523','醉后狂言酬赠萧殷二协律','白居易','quantangshi','','卷23','余杭邑客多羇贫，其间甚者萧与殷。
天寒身上犹衣葛，日高甑中未拂尘。
江城山寺十一月，北风吹沙雪纷纷。
宾客不见绨袍惠，黎庶未霑襦袴恩。
此时太守自慙愧，重衣复衾有余温。
因命染人与针女，先制两裘赠二君。
吴緜细輭桂布密，柔如狐腋白似云。
劳将诗书投赠我，如此小惠何足论。
我有大裘君未见，宽广和暖如阳春。
此裘非缯亦非纩，裁以法度絮以仁。
刀尺钝拙制未毕，出亦不独裹一身。
若令在郡得五考，与君展覆杭州人。','',''),('quantangshi-22524','醉歌','白居易','quantangshi','','卷23','罢胡琴，掩秦瑟，玲珑再拜歌初毕。
谁道使君不解歌，听唱黄鸡与白日。
黄鸡催晓丑时鸣，白日催年酉前没。
腰间红绶系未稳，镜里朱颜看已失。
玲珑玲珑奈老何，使君歌了汝更歌。','',''),('quantangshi-22525','代书诗一百韵寄微之','白居易','quantangshi','','卷23','忆在贞元岁，初登典校司。
身名同日授，心事一言知。
肺腑都无隔，形骸两不羁。
疎狂属年少，闲散为官卑。
分定金兰契，言通药石规。
交贤方汲汲，友直每偲偲。
有月多同赏，无杯不共持。
秋风拂琴匣，夜雪卷书帷。
高上慈恩塔，幽寻皇子陂。
唐昌玉蘂会，崇敬牡丹期。
笑劝迂辛酒，闲吟短李诗。
儒风爱敦质，佛理赏玄师。
度日曾无闷，通宵靡不为。
双声联律句，八面对宫棊。
往往游三省，腾腾出九逵。
寒销直城路，春到曲江池。
树暖枝条弱，山晴彩翠奇。
峰攒石绿点，柳宛麴尘丝。
岸草烟铺地，园花雪压枝。
早光红照耀，新溜碧逶迤。
幄幕侵堤布，盘筵占地施。
征伶皆绝艺，选伎悉名姬。
粉黛凝春态，金钿耀水嬉。
风流夸堕髻，时世鬬啼眉。
密坐随欢促，华尊逐胜移。
香飘歌袂动，翠落舞钗遗。
筹插红螺椀，觥飞白玉巵。
打嫌调笑易，饮讶卷波迟。
残席喧哗散，归鞍酩酊骑。
酡颜乌帽侧，醉袖玉鞭垂。
紫陌传钟鼓，红尘塞路岐。
几时曾蹔别，何处不相随？
茌苒星霜换，回环节候催。
两衙多请告，三考欲成资。
运启千年圣，天成万物宜。
皆当少壮日，同惜盛明时。
光景嗟虚掷，云霄窃暗窥。
攻文朝矻矻，讲学夜孜孜。
策目穿如札，锋毫锐若锥。
繁张获鸟网，坚守钓鱼坻。
竝受夔龙荐，齐陈鼂董词。
万言经济略，三策太平基。
中第争无敌，专场战不疲。
辅车排胜阵，掎角搴降旗。
双阙纷容卫，千僚俨等衰。
恩随紫泥降，名向白麻披。
既在高科选，还从好爵縻。
东垣君谏诤，西邑我驱驰。
再喜登乌府，多慙侍赤墀。
官班分内外，游处遂参差。
每列鵷鸾序，偏瞻獬豸姿。
简威霜凛冽，衣彩绣葳蕤。
正色摧强御，刚肠嫉喔咿。
常憎持禄位，不拟保妻儿。
养勇期除恶，输忠在灭私。
下韝惊燕雀，当道慑狐狸。
南国人无怨，东台吏不欺。
理冤多定国，切谏甚辛毗。
造次行于是，平生志在兹。
道将心共直，言与行兼危。
水暗波飜覆，山藏路险巇。
未为明主识，已被幸臣疑。
木秀遭风折，兰芳遇霰萎。
千钧势易压，一柱力难搘。
腾口因成痏，吹毛遂得疵。
忧来吟贝锦，谪去咏江蓠。
邂逅尘中遇，殷勤马上辞。
贾生离魏阙，王粲向荆夷。
水过清源寺，山经绮季祠。
心摇汉臯佩，泪堕岘亭碑。
驿路缘云际，城楼枕水湄。
思乡多绕泽，望阙独登陴。
林晚青萧索，江平绿渺弥。
野秋鸣蟋蟀，沙冷聚鸬鷀。
官舍黄茅屋，人家苦竹篱。
白醪充夜酌，红粟备晨炊。
寡鹤摧风翮，鳏鱼失水鬐。
暗雏啼渴旦，凉叶坠相思。
一点寒灯灭，三声晓角吹。
蓝衫经雨故，骢马卧霜羸。
念涸谁濡沫，嫌醒自歠醨。
耳垂无伯乐，舌在有张仪。
负气冲星劒，倾心向日葵。
金言自销铄，玉性肯磷缁。
伸屈须看蠖，穷通莫问龟。
定知身是患，应用道为医。
想子今如彼，嗟予独在斯。
无憀当岁杪，有梦到天涯。
坐阻连襟带，行乖接履綦。
润销衣上雾，香散室中芝。
念远缘迁贬，惊时为别离。
素书三往复，明月七盈亏。
旧里非难到，余欢不可追。
树依兴善老，草傍静安衰。
前事思如昨，中怀写向谁。
北村寻古柏，南宅访辛夷。
此日空搔首，何人共解颐。
病多知夜永，年长觉秋悲。
不饮长如醉，加餐亦似饥。
狂吟一千字，因使寄微之。','',''),('quantangshi-22526','和郑元及第后秋归洛下闲居','白居易','quantangshi','','卷23','勤苦成名后，优游得意间。
玉怜同匠琢，桂恨隔年攀。
山静豹难隐，谷幽莺暂还。
微吟诗引步，浅酌酒开颜。
门迥暮临水，窗深朝对山。
云衢日相待，莫误许身闲。','',''),('quantangshi-22527','与诸同年贺座主侍郎新拜太常同宴萧尚书亭子','白居易','quantangshi','','卷23','宠新卿典礼，会盛客征文。
不失迁莺侣，因成贺燕羣。
池台晴间雪，冠盖暮和云。
共仰曾攀处，年深桂尚熏。','',''),('quantangshi-22528','东都冬日会诸同年宴郑家林亭','白居易','quantangshi','','卷23','盛时陪上第，暇日会羣贤。
桂折因同树，莺迁各异年。
宾阶纷组佩，妓席俨花钿。
促膝齐荣贱，差肩次后先。
助歌林下水，销酒雪中天。
他日升沈者，无忘共此筵。','',''),('quantangshi-22529','叙德书情四十韵上宣歙翟中丞','白居易','quantangshi','','卷23','元圣生乘运，忠贤出应期。
还将稽古力，助立太平基。
土控吴兼越，州连歙与池。
山河地襟带，军镇国藩维。
廉察安江甸，澄清肃海夷。
股肱分外守，耳目付中司。
楚老歌来暮，秦人咏去思。
望如时雨至，福是岁星移。
政静民无讼，刑行吏不欺。
撝谦惊主宠，阴德畏人知。
白玉慙温色，朱绳让直辞。
行为时领袖，言作世蓍龟。
盛幕招贤士，连营训锐师。
光华下鵷鹭，气色动熊罴。
出入麾幢引，登临劒戟随。
好风迎解榻，美景待搴帷。
晴野霞飞绮，春郊柳宛丝。
城乌惊画角，江雁避红旗。
藉草朱轮驻，攀花紫绶垂。
山宜谢公屐，洲称柳家诗。
酒气和芳杜，弦声乱子规。
分球齐马首，列舞匝蛾眉。
醉惜年光晚，欢怜日影迟。
回塘排玉棹，归路拥金羁。
自顾龙钟者，尝蒙噢咻之。
仰山尘不让，涉海水难为。
身忝乡人荐，名因国士推。
提携增善价，拂拭长妍姿。
射策端心术，迁乔整羽仪。
幸穿杨远叶，谬折桂高枝。
佩德潜书带，铭仁暗勒肌。
饬躬趋馆舍，拜手挹阶墀。
霄汉程虽在，风尘迹尚卑。
敝衣羞布素，败屋厌茅茨。
养乏晨昏膳，居无伏腊资。
盛时贫可耻，壮岁病堪嗤。
擢第名方立，耽书力未疲。
磨铅重剸割，策蹇再奔驰。
相马须怜瘦，呼鹰正及饥。
扶摇重即事，会有答恩时。','',''),('quantangshi-22530','和渭北刘大夫借便秋遮虏寄朝中亲友','白居易','quantangshi','','卷23','巨镇为邦屏，全材作国桢。
韬钤汉上将，文墨鲁诸生。
豹虎关西卒，金汤渭北城。
宠深初受棨，威重正扬兵。
阵占山河布，军谙水草行。
夏苗侵虎落，宵遁失蕃营。
云队攒戈戟，风行卷斾旌。
堠空烽火灭，气胜鼓鼙鸣。
胡马辞南牧，周师罢北征。
回头问天下，何处有欃枪。','',''),('quantangshi-22531','题故曹王宅','白居易','quantangshi','','卷23','甲第何年置，朱门此地开。
山当宾阁出，溪绕妓堂回。
覆井桐新长，阴窗竹旧栽。
池荒红菡萏，砌老绿莓苔。
捐馆梁王去，思人楚客来。
西园飞盖处，依旧月裴回。','',''),('quantangshi-22532','自江陵之徐州路上寄兄弟','白居易','quantangshi','','卷23','岐路南将北，离忧弟与兄。
关河千里别，风雪一身行。
夕宿劳乡梦，晨装惨旅情。
家贫忧后事，日短念前程。
烟雁飜寒渚，霜乌聚古城。
谁怜陟冈者，西楚望南荆。','',''),('quantangshi-22533','酬哥舒大见赠','白居易','quantangshi','','卷23','去岁欢游何处去？曲江西岸杏园东。
花下忘归因美景，尊前劝酒是春风。
各从微宦风尘里，共度流年离别中。
今日相逢愁又喜，八人分散两人同。','',''),('quantangshi-22534','和谈校书秋夜感怀呈朝中亲友','白居易','quantangshi','','卷23','遥夜凉风楚客悲，清砧繁漏月高时。
秋霜似鬓年空长，春草如袍位尚卑。
词赋擅名来已久，烟霄得路去何迟。
汉庭卿相皆知己，不荐扬雄欲荐谁。','',''),('quantangshi-22535','感秋寄远','白居易','quantangshi','','卷23','惆怅时节晚，两情千里同。
离忧不散处，庭树正秋风。
燕影动归翼，蕙香销故丛。
佳期与芳岁，牢落两成空。','',''),('quantangshi-22536','春题华阳观','白居易','quantangshi','','卷23','帝子吹箫逐凤皇，空留仙洞号华阳。
落花何处堪惆怅，头白宫人埽影堂。','',''),('quantangshi-22537','秋雨中赠元九','白居易','quantangshi','','卷23','不堪红叶青苔地，又是凉风暮雨天。
莫怪独吟秋思苦，比君校近二毛年。','',''),('quantangshi-22538','城东闲游','白居易','quantangshi','','卷23','宠辱忧欢不到情，任他朝市自营营。
独寻秋景城东去，白鹿原头信马行。','',''),('quantangshi-22539','答韦八','白居易','quantangshi','','卷23','丽句劳相赠，佳期恨有违。
早知留酒待，悔不趁花归。
春尽绿醅老，雨多红萼稀。
今朝如一醉，犹得及芳菲。','',''),('quantangshi-22540','华阳观桃花时招李六拾遗饮','白居易','quantangshi','','卷23','华阳观里仙桃发，把酒看花心自知。
争忍开时不同醉，明朝后日即空枝。','',''),('quantangshi-22541','和友人洛中春感','白居易','quantangshi','','卷23','莫悲金谷园中月，莫叹天津桥上春。
若学多情寻往事，人间何处不伤神。','',''),('quantangshi-22542','送张南简入蜀','白居易','quantangshi','','卷23','昨日诏书下，求贤访陆沈。
无论能与否，皆起徇名心。
君独南游去，云山蜀路深。','',''),('quantangshi-22543','寄陆补阙','白居易','quantangshi','','卷23','忽忆前年科第后，此时鸡鹤暂同羣。
秋风惆怅须吹散，鸡在中庭鹤在云。','',''),('quantangshi-22544','华阳观中八月十五日夜招友玩月','白居易','quantangshi','','卷23','人道秋中明月好，欲邀同赏意如何。
华阳洞里秋坛上，今夜清光此处多。','',''),('quantangshi-22545','曲江忆元九','白居易','quantangshi','','卷23','春来无伴闲游少，行乐三分减二分。
何况今朝杏园里，闲人逢尽不逢君。','',''),('quantangshi-22546','过刘三十二故宅','白居易','quantangshi','','卷23','不见刘君来近远，门前两度满枝花。
朝来惆怅宣平过，柳巷当头第一家。','',''),('quantangshi-22547','下邽庄南桃花','白居易','quantangshi','','卷23','村南无限桃花发，唯我多情独自来。
日暮风吹红满地，无人解惜为谁开。','',''),('quantangshi-22548','三月三十日题慈恩寺','白居易','quantangshi','','卷23','慈恩春色今朝尽，尽日裴回倚寺门。
惆怅春归留不得，紫藤花下渐黄昏。','',''),('quantangshi-22549','看恽家牡丹花戏赠李二十','白居易','quantangshi','','卷23','香胜烧兰红胜霞，城中最数令公家。
人人散后君须看，归到江南无此花。','',''),('quantangshi-22550','春中与卢四周谅华阳观同居','白居易','quantangshi','','卷23','性情嬾慢好相亲，门巷萧条称作邻。
背烛共怜深夜月，蹋花同惜少年春。
杏坛住僻虽宜病，芸阁官微不救贫。
文行如君尚顦顇，不知霄汉待何人。','',''),('quantangshi-22551','自城东至以诗代书戏招李六拾遗崔二十六先辈','白居易','quantangshi','','卷23','青门走马趁心期，惆怅归来已校迟。
应过唐昌玉蘂后，犹当崇敬牡丹时。
暂游还忆崔先辈，欲醉先邀李拾遗。
尚残半月芸香俸，不作归粮作酒赀。','',''),('quantangshi-22552','盩厔县北楼望山','白居易','quantangshi','','卷23','一为趋走吏，尘土不开颜。
孤负平生眼，今朝始见山。','',''),('quantangshi-22553','县西郊秋寄赠马造','白居易','quantangshi','','卷23','紫阁峰西清渭东，野烟深处夕阳中。
风荷老叶萧条绿，水蓼残花寂寞红。
我厌宦游君失意，可怜秋思两心同。','',''),('quantangshi-22554','别韦苏州','白居易','quantangshi','','卷23','百年愁里过，万感醉中来。
惆怅城西别，愁眉两不开。','',''),('quantangshi-22555','戏题新栽蔷薇','白居易','quantangshi','','卷23','移根易地莫顦顇，野外庭前一种春。
少府无妻春寂寞，花开将尔当夫人。','',''),('quantangshi-22556','酬王十八李大见招游山','白居易','quantangshi','','卷23','自怜幽会心期阻，复愧嘉招书信频。
王事牵身去不得，满山松雪属他人。','',''),('quantangshi-22557','县南花下醉中留刘五','白居易','quantangshi','','卷23','百岁几回同酩酊，一年今日最芳菲。
愿将花赠天台女，留取刘郎到夜归。','',''),('quantangshi-22558','宿杨家','白居易','quantangshi','','卷23','杨氏弟兄俱醉卧，披衣独起下高斋。
夜深不语中庭立，月照藤花影上阶。','',''),('quantangshi-22559','醉中留别杨六兄弟','白居易','quantangshi','','卷23','春初携手春深散，无日花间不醉狂。
别后何人堪共醉，犹残十日好风光。','',''),('quantangshi-22560','醉中归盩厔','白居易','quantangshi','','卷23','金光门外昆明路，半醉腾腾信马回。
数日非关王事系，牡丹花尽始归来。','',''),('quantangshi-22561','游云居寺赠穆三十六地主','白居易','quantangshi','','卷23','乱峰深处云居路，共蹋花行独惜春。
胜地本来无定主，大都山属爱山人。','',''),('quantangshi-22562','和王十八蔷薇涧花时有怀萧侍御兼见赠','白居易','quantangshi','','卷23','霄汉风尘俱是系，蔷薇花委故山深。
怜君独向涧中立，一把红芳三处心。','',''),('quantangshi-22563','再因公事到骆口驿','白居易','quantangshi','','卷23','今年到时夏云白，去年来时秋树红。
两度见山心有愧，皆因王事到山中。','',''),('quantangshi-22564','期李二十文略王十八质夫不至独宿仙游寺','白居易','quantangshi','','卷23','文略也从牵吏役，质夫何故恋嚣尘。
始知解爱山中宿，千万人中无一人。','',''),('quantangshi-22565','酬赵秀才赠新登科诸先辈','白居易','quantangshi','','卷23','莫羡蓬莱鸾鹤侣，道成羽翼自生身。
君看名在丹台者，尽是人间修道人。','',''),('quantangshi-22566','过天门街','白居易','quantangshi','','卷23','雪尽终南又欲春，遥怜翠色对红尘。
千车万马九衢上，回首看山无一人。','',''),('quantangshi-22567','惜玉蘂花有怀集贤王校书起','白居易','quantangshi','','卷23','芳意将阑风又吹，白云离叶雪辞枝。
集贤雠校无闲日，落尽瑶花君不知。','',''),('quantangshi-22568','春送卢秀才下第游太原谒严尚书','白居易','quantangshi','','卷23','未将时会合，且与俗浮沈。
鸿养青冥翮，蛟潜云雨心。
烟郊春别远，风碛暮程深。
墨客投何处，并州旧翰林。','',''),('quantangshi-22569','长安送柳大东归','白居易','quantangshi','','卷23','白社羁游伴，青门远别离。
浮名相引住，归路不同归。','',''),('quantangshi-22570','送文畅上人东游','白居易','quantangshi','','卷23','得道即无着，随缘西复东。
貌依年腊老，心到夜禅空。
山宿驯溪虎，江行滤水虫。
悠悠尘客思，春满碧云中。','',''),('quantangshi-22571','社日关路作','白居易','quantangshi','','卷23','晚景函关路，凉风社日天。
青岩新有燕，红树欲无蝉。
愁立驿楼上，厌行官堠前。
萧条秋兴苦，渐近二毛年。','',''),('quantangshi-22572','重到毓村宅有感','白居易','quantangshi','','卷23','欲入中门泪满巾，庭花无主两回春。
轩窗帘幕皆依旧，只是堂前欠一人。','',''),('quantangshi-22573','乱后过流沟寺','白居易','quantangshi','','卷23','九月徐州新战后，悲风杀气满山河。
唯有流沟山下寺，门前依旧白云多。','',''),('quantangshi-22574','叹发落','白居易','quantangshi','','卷23','多病多愁心自知，行年未老发先衰。
随梳落去何须惜，不落终须变作丝。','',''),('quantangshi-22575','留别吴七正字','白居易','quantangshi','','卷23','成名共记甲科上，署吏同登芸阁间。
唯是尘心殊道性，秋蓬常转水长闲。','',''),('quantangshi-22576','除夜宿洺州','白居易','quantangshi','','卷23','家寄关西住，身为河北游。
萧条岁除夜，旅泊在洺州。','',''),('quantangshi-22577','邯郸冬至夜思家','白居易','quantangshi','','卷23','邯郸驿里逢冬至，抱膝灯前影伴身。
想得家中夜深坐，还应说着远行人。','',''),('quantangshi-22578','冬至夜怀湘灵','白居易','quantangshi','','卷23','艳质无由见，寒衾不可亲。
何堪最长夜，俱作独眠人。','',''),('quantangshi-22579','感故张仆射诸妓','白居易','quantangshi','','卷23','黄金不惜买蛾眉，拣得如花三四枝。
歌舞教成心力尽，一朝身去不相随。','',''),('quantangshi-22580','游仙游山','白居易','quantangshi','','卷23','暗将心地出人间，五六年来人怪闲。
自嫌恋着未全尽，犹爱云泉多在山。','',''),('quantangshi-22581','见尹公亮新诗偶赠绝句','白居易','quantangshi','','卷23','袖里新诗十首余，吟看句句是琼琚。
如何持此将干谒，不及公卿一字书。','',''),('quantangshi-22582','长安闲居','白居易','quantangshi','','卷23','风竹松烟昼掩关，意中长似在深山。
无人不怪长安住，何独朝朝暮暮间。','',''),('quantangshi-22583','早春独游曲江','白居易','quantangshi','','卷23','散职无羁束，羸骖少送迎。
朝从直城出，春傍曲江行。
风起池东暖，云开山北晴。
冰销泉脉动，雪尽草芽生。
露杏红初坼，烟杨绿未成。
影迟新度雁，声涩欲啼莺。
闲地心俱静，韶光眼共明。
酒狂怜性逸，药效喜身轻。
慵慢疎人事，幽栖逐野情。
回看芸阁笑，不似有浮名。','',''),('quantangshi-22584','祕书省中忆旧山','白居易','quantangshi','','卷23','厌从薄宦校青简，悔别故山思白云。
犹喜兰台非傲吏，归时应免动移文。','',''),('quantangshi-22585','凉夜有怀','白居易','quantangshi','','卷23','清风吹枕席，白露湿衣裳。
好是相亲夜，漏迟天气凉。','',''),('quantangshi-22586','送武士曹归蜀','白居易','quantangshi','','卷23','花落鸟嘤嘤，南归称野情。
月宜秦岭宿，春好蜀江行。
乡路通云栈，郊扉近锦城。
乌台陟冈送，人羡别时荣。','',''),('quantangshi-22587','江南送北客因凭寄徐州兄弟书','白居易','quantangshi','','卷23','故园望断欲何如，楚水吴山万里余。
今日因君访兄弟，数行乡泪一封书。','',''),('quantangshi-22588','赋得古原草送别','白居易','quantangshi','','卷23','离离原上草，一岁一枯荣。
野火烧不尽，春风吹又生。
远芳侵古道，晴翠接荒城。
又送王孙去，萋萋满别情。','',''),('quantangshi-22589','夜哭李夷道','白居易','quantangshi','','卷23','逝者绝影响，空庭朝复昏。
家人哀临毕，夜鏁寿堂门。
无妻无子何人葬，空见铭旌向月飜。','',''),('quantangshi-22590','病中作','白居易','quantangshi','','卷23','久为劳生事，不学摄生道。
年少已多病，此身岂堪老。','',''),('quantangshi-22591','秋江晚泊','白居易','quantangshi','','卷23','扁舟泊云岛，倚棹念乡国。
四望不见人，烟江澹秋色。
客心贫易动，日入愁未息。','',''),('quantangshi-22592','旅次景空寺宿幽上人院','白居易','quantangshi','','卷23','不与人境接，寺门开向山。
暮钟寒鸟聚，秋雨病僧闲。
月隐云树外，萤飞廊宇间。
幸投花界宿，暂得静心颜。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22593','长安正月十五日','白居易','quantangshi','','卷23','喧喧车骑帝王州，羇病无心逐胜游。
明月春风三五夜，万人行乐一人愁。','',''),('quantangshi-22594','过高将军墓','白居易','quantangshi','','卷23','原上新坟委一身，城中旧宅有何人。
妓堂宾阁无归日，野草山花又欲春。
门客空将感恩泪，白杨风里一霑巾。','',''),('quantangshi-22595','寒食卧病','白居易','quantangshi','','卷23','病逢佳节长叹息，春雨蒙蒙榆柳色。
羸坐全非旧日容，扶行半是他人力。
喧喧里巷蹋青归，笑闭柴门度寒食。','',''),('quantangshi-22596','宿桐庐馆同崔存度醉后作','白居易','quantangshi','','卷23','江海漂漂共旅游，一尊相劝散穷愁。
夜深醒后愁还在，雨滴梧桐山馆秋。','',''),('quantangshi-22597','江楼望归','白居易','quantangshi','','卷23','满眼云水色，月明楼上人。
旅愁春入越，乡梦夜归秦。
道路通荒服，田园隔虏尘。
悠悠沧海畔，十载避黄巾。','',''),('quantangshi-22598','除夜寄弟妹','白居易','quantangshi','','卷23','感时思弟妹，不寐百忧生。
万里经年别，孤灯此夜情。
病容非旧日，归思逼新正。
早晚重欢会，羇离各长成。','',''),('quantangshi-22599','寒食月夜','白居易','quantangshi','','卷23','风香露重棃花湿，草舍无灯愁未入。
南邻北里歌吹时，独倚柴门月中立。','',''),('quantangshi-22600','感芍药花寄正一上人','白居易','quantangshi','','卷23','今日阶前红芍药，几花欲老几花新。
开时不解比色相，落后始知如幻身。
空门此去几多地，欲把残花问上人。','',''),('quantangshi-22601','晚秋闲居','白居易','quantangshi','','卷23','地僻门深少送迎，披衣闲坐养幽情。
秋庭不埽携藤杖，闲蹋梧桐黄叶行。','',''),('quantangshi-22602','秋暮郊居书怀','白居易','quantangshi','','卷23','郊居人事少，昼卧对林峦。
穷巷厌多雨，贫家愁早寒。
葛衣秋未换，书卷病仍看。
若问生涯计，前溪一钓竿。','',''),('quantangshi-22603','为薛台悼亡','白居易','quantangshi','','卷23','半死梧桐老病身，重泉一念一伤神。
手携穉子夜归院，月冷空房不见人。','',''),('quantangshi-22604','途中寒食','白居易','quantangshi','','卷23','路傍寒食行人尽，独占春愁在路旁。
马上垂鞭愁不语，风吹百草野田香。','',''),('quantangshi-22605','题流沟寺古松','白居易','quantangshi','','卷23','烟叶葱茏苍麈尾，霜皮剥落紫龙鳞。
欲知松老看尘壁，死却题诗几许人。','',''),('quantangshi-22606','感月悲逝者','白居易','quantangshi','','卷23','存亡感月一潸然，月色今宵似往年。
何处曾经同望月？樱桃树下后堂前。','',''),('quantangshi-22607','代邻叟言怀','白居易','quantangshi','','卷23','人生何事心无定，宿昔如今意不同。
宿昔愁身不得老，如今恨作白头翁。','',''),('quantangshi-22608','自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄于潜七兄乌江十五兄兼示符离及下邽弟妹','白居易','quantangshi','','卷23','时难年饥世业空，弟兄羇旅各西东。
田园寥落干戈后，骨肉流离道路中。
吊影分为千里雁，辞根散作九秋蓬。
共看明月应垂泪，一夜乡心五处同。','',''),('quantangshi-22609','长安早春旅怀','白居易','quantangshi','','卷23','轩车歌吹喧都邑，中有一人向隅立。
夜深明月卷帘愁，日暮青山望乡泣。
风吹新绿草芽坼，雨洒轻黄柳条湿。
此生知负少年春，不展愁眉欲三十。','',''),('quantangshi-22610','寒闺夜','白居易','quantangshi','','卷23','夜半衾裯冷，孤眠嬾未能。
笼香销尽火，巾泪滴成冰。
为惜影相伴，通宵不灭灯。','',''),('quantangshi-22611','寄湘灵','白居易','quantangshi','','卷23','泪眼凌寒冻不流，每经高处即回头。
遥知别后西楼上，应凭阑干独自愁。','',''),('quantangshi-22612','冬至宿杨梅馆','白居易','quantangshi','','卷23','十一月中长至夜，三千里外远行人。
若为独宿杨梅馆，冷枕单牀一病身。','',''),('quantangshi-22613','临江送夏瞻','白居易','quantangshi','','卷23','悲君老别我霑巾，七十无家万里身。
愁见舟行风又起，白头浪里白头人。','',''),('quantangshi-22614','冬夜示敏巢','白居易','quantangshi','','卷23','炉火欲销灯欲尽，夜长相对百忧生。
他时诸处重相见，莫忘今宵灯下情。','',''),('quantangshi-22615','客中守岁','白居易','quantangshi','','卷23','守岁尊无酒，思乡泪满巾。
始知为客苦，不及在家贫。
畏老偏惊节，防愁预恶春。
故园今夜里，应念未归人。','',''),('quantangshi-22616','问淮水','白居易','quantangshi','','卷23','自嗟名利客，扰扰在人间。
何事长淮水，东流亦不闲。','',''),('quantangshi-22617','宿樟亭驿','白居易','quantangshi','','卷23','夜半樟亭驿，愁人起望乡。
月明何所见，潮水白茫茫。','',''),('quantangshi-22618','及第后忆旧山','白居易','quantangshi','','卷23','偶献子虚登上第，却吟招隐忆中林。
春萝秋桂莫惆怅，纵有浮名不系心。','',''),('quantangshi-22619','题李次云窗竹','白居易','quantangshi','','卷23','不用裁为鸣凤管，不须截作钓鱼竿。
千花百草凋零后，留向纷纷雪里看。','',''),('quantangshi-22620','花下自劝酒','白居易','quantangshi','','卷23','酒盏酌来须满满，花枝看即落纷纷。
莫言三十是年少，百岁三分已一分。','',''),('quantangshi-22621','题李十一东亭','白居易','quantangshi','','卷23','相思夕上松台立，蛩思蝉声满耳秋。
惆怅东亭风月好，主人今夜在鄜州。','',''),('quantangshi-22622','春村','白居易','quantangshi','','卷23','二月村园暖，桑间戴胜飞。
农夫舂旧谷，蚕妾捣新衣。
牛马因风远，鸡豚过社稀。
黄昏林下路，鼓笛赛神归。','',''),('quantangshi-22623','题施山人野居','白居易','quantangshi','','卷23','得道应无着，谋生亦不妨。
春泥秧稻暖，夜火焙茶香。
水巷风尘少，松斋日月长。','',''),('quantangshi-22624','翰林中送独孤二十七起居罢职出院','白居易','quantangshi','','卷23','碧落留云住，青冥放鹤还。
银台向南路，从此到人间。','',''),('quantangshi-22625','重寻杏园','白居易','quantangshi','','卷23','忽忆芳时频酩酊，却寻醉处重裴回。
杏花结子春深后，谁解多情又独来。','',''),('quantangshi-22626','曲江独行','白居易','quantangshi','','卷23','独来独去何人识，廐马朝衣野客心。
闲爱无风水边坐，杨花不动树阴阴。','',''),('quantangshi-22627','同李十一醉忆元九','白居易','quantangshi','','卷23','花时同醉破春愁，醉折花枝当酒筹。
忽忆故人天际去，计程今日到凉州。','',''),('quantangshi-22628','同钱员外题绝粮僧巨川','白居易','quantangshi','','卷23','三十年来坐对山，唯将无事化人间。
斋时往往闻钟笑，一食何如不食闲。','',''),('quantangshi-22629','绝句代书赠钱员外','白居易','quantangshi','','卷23','欲寻秋景闲行去，君病多慵我兴孤。
可惜今朝山最好，强能骑马出来无。','',''),('quantangshi-22630','晚秋有怀郑中旧隐','白居易','quantangshi','','卷23','天高风袅袅，乡思绕关河。
寥落归山梦，殷勤采蕨歌。
病添心寂寞，愁人鬓蹉跎。
晚树蝉鸣少，秋阶日上多。
长闲羡云鹤，久别愧烟萝。
其奈丹墀上，君恩未报何。','',''),('quantangshi-22631','禁中九日对菊花酒忆元九','白居易','quantangshi','','卷23','赐酒盈杯谁共持，宫花满把独相思。
相思只傍花边立，尽日吟君咏菊诗。','',''),('quantangshi-22632','送王十八归山寄题仙游寺','白居易','quantangshi','','卷23','曾于太白峰前住，数到仙游寺里来。
黑水澄时潭底出，白云破处洞门开。
林间暖酒烧红叶，石上题诗埽绿苔。
惆怅旧游那复到，菊花时节羡君回。','',''),('quantangshi-22633','答张籍因以代书','白居易','quantangshi','','卷23','怜君马瘦衣裘薄，许到江东访鄙夫。
今日正闲天又暖，可能扶病暂来无。','',''),('quantangshi-22634','曲江早春','白居易','quantangshi','','卷23','曲江柳条渐无力，杏园伯劳初有声。
可怜春浅游人少，好傍池边下马行。','',''),('quantangshi-22635','见元九悼亡诗因以此寄','白居易','quantangshi','','卷23','夜泪暗销明月幌，春肠遥断牡丹庭。
人间此病治无药，唯有楞伽四卷经。','',''),('quantangshi-22636','寒食夜','白居易','quantangshi','','卷23','无月无灯寒食夜，夜深犹立暗花前。
忽因时节惊年几，四十如今欠一年。','',''),('quantangshi-22637','杏园花落时招钱员外同醉','白居易','quantangshi','','卷23','花园欲去去应迟，正是风吹狼藉时。
近西数树犹堪醉，半落春风半在枝。','',''),('quantangshi-22638','重题西明寺牡丹','白居易','quantangshi','','卷23','往年君向东都去，曾叹花时君未回。
今年况作江陵别，惆怅花前又独来。
只愁离别长如此，不道明年花不开。','',''),('quantangshi-22639','同钱员外禁中夜直','白居易','quantangshi','','卷23','宫漏三声知半夜，好风凉月满松筠。
此时闲坐寂无语，药树影中唯两人。','',''),('quantangshi-22640','禁中夜作书与元九','白居易','quantangshi','','卷23','心绪万端书两纸，欲封重读意迟迟。
五声宫漏初鸣夜，一点窗灯欲灭时。','',''),('quantangshi-22641','八月十五日夜禁中独直对月忆元九','白居易','quantangshi','','卷23','银台金阙夕沈沈，独宿相思在翰林。
三五夜中新月色，二千里外故人心。
渚宫东面烟波冷，浴殿西头钟漏深。
犹恐清光不同见，江陵卑湿足秋阴。','',''),('quantangshi-22642','寄陈式五兄','白居易','quantangshi','','卷23','年来白发两三茎，忆别君时髭未生。
惆怅料君应满鬓，当初是我十年兄。','',''),('quantangshi-22643','庾顺之以紫霞绮远赠以诗答之','白居易','quantangshi','','卷23','千里故人心郑重，一端香绮紫氛氲。
开缄日映晚霞色，满幅风生秋水纹。
为褥欲裁怜叶破，制裘将翦惜花分。
不如缝作合欢被，寤寐相思如对君。','',''),('quantangshi-22644','送元八归凤翔','白居易','quantangshi','','卷23','莫道岐州三日程，其如风雪一身行。
与君况是经年别，暂到城来又出城。','',''),('quantangshi-22645','雨雪放朝因怀微之','白居易','quantangshi','','卷23','归骑纷纷满九衢，放朝三日为泥涂。
不知雨雪江陵府，今日排衙得免无。','',''),('quantangshi-22646','咏怀','白居易','quantangshi','','卷23','岁去年来尘土中，眼看变作白头翁。
如何办得归山计，两顷村田一亩宫。','',''),('quantangshi-22647','闻微之江陵卧病以大通中散碧腴垂云膏寄之因题四韵','白居易','quantangshi','','卷23','已题一帖红消散，又封一合碧云英。
凭人寄向江陵去，道路迢迢一月程。
未必能治江上瘴，且图遥慰病中情。
到时想得君拈得，枕上开看眼暂明。','',''),('quantangshi-22648','酬钱员外雪中见寄','白居易','quantangshi','','卷23','松雪无尘小院寒，闭门不似住长安。
烦君想我看心坐，报道心空无可看。','',''),('quantangshi-22649','重酬钱员外','白居易','quantangshi','','卷23','雪中重寄雪山偈，问答殷勤四句中。
本立空名缘破妄，若能无妄亦无空。','',''),('quantangshi-22650','独酌忆微之','白居易','quantangshi','','卷23','独酌花前醉忆君，与君春别又逢春。
惆怅银杯来处重，不曾盛酒劝闲人。','',''),('quantangshi-22651','微之宅残牡丹','白居易','quantangshi','','卷23','残红零落无人赏，雨打风摧花不全。
诸处见时犹怅望，况当元九小亭前。','',''),('quantangshi-22652','新磨镜','白居易','quantangshi','','卷23','衰容常晚栉，秋镜偶新磨。
一与清光对，方知白发多。
鬓毛从幻化，心地付头陀。
任意浑成雪，其如似梦何。','',''),('quantangshi-22653','感发落','白居易','quantangshi','','卷23','昔日愁头白，谁知未白衰。
眼看应落尽，无可变成丝。','',''),('quantangshi-22654','八月十五日夜闻崔大员外翰林独直对酒玩月因怀禁中清景偶题是诗','白居易','quantangshi','','卷23','秋月高悬空碧外，仙郎静玩禁闱间。
岁中唯有今宵好，海内无如此地闲。
皓色分明双阙牓，清光深到九门关。
遥闻独醉还惆怅，不见金波照玉山。','',''),('quantangshi-22655','酬王十八见寄','白居易','quantangshi','','卷23','秋思太白峰头雪，晴忆仙游洞口云。
未报皇恩归未得，慙君为寄北山文。','',''),('quantangshi-22656','立春日酬钱员外曲江同行见赠','白居易','quantangshi','','卷23','下直遇春日，垂鞭出禁闱。
两人携手语，十里看山归。
柳色早黄浅，水文新绿微。
风光向晚好，车马近南稀。
机尽笑相顾，不惊鸥鹭飞。','',''),('quantangshi-22657','和钱员外青龙寺上方望旧山','白居易','quantangshi','','卷23','旧峰松雪旧溪云，怅望今朝遥属君。
共道使臣非俗吏，南山莫动北山文。','',''),('quantangshi-22658','宴周皓大夫光福宅','白居易','quantangshi','','卷23','何处风光最可怜？妓堂阶下砌台前。
轩车拥路光照地，丝管入门声沸天。
绿蕙不香饶桂酒，红樱无色让花钿。
野人不敢求他事，唯借泉声伴醉眠。','',''),('quantangshi-22659','晚秋夜','白居易','quantangshi','','卷23','碧空溶溶月华静，月里愁人吊孤影。
花开残菊傍疎篱，叶下衰桐落寒井。
塞鸿飞急觉秋尽，邻鸡鸣迟知夜永。
凝情不语空所思，风吹白露衣裳冷。','',''),('quantangshi-22660','惜牡丹花二首 一','白居易','quantangshi','','卷23','惆怅阶前红牡丹，晚来唯有两枝残。
明朝风起应吹尽，夜惜衰红把火看。','',''),('quantangshi-22661','惜牡丹花二首 二','白居易','quantangshi','','卷23','寂寞萎红低向雨，离披破艳散随风。
晴明落地犹惆怅，何况飘零泥土中。','',''),('quantangshi-22662','答元奉礼同宿见赠','白居易','quantangshi','','卷23','相逢俱叹不闲身，直日常多斋日频。
晓鼓一声分散去，明朝风景属何人。','',''),('quantangshi-22663','答马侍御见赠','白居易','quantangshi','','卷23','谬入金门侍玉除，烦君问我意何如。
蟠木讵堪明主用，笼禽徒与故人疎。
苑花似雪同随辇，宫月如眉伴直庐。
浅薄求贤思自代，嵇康莫寄绝交书。','',''),('quantangshi-22664','上巳日恩赐曲江宴会即事','白居易','quantangshi','','卷23','赐欢仍许醉，此会兴如何。
翰苑主恩重，曲江春意多。
花低羞艳妓，莺散让清歌。
共道升平乐，元和胜永和。','',''),('quantangshi-22665','夜惜禁中桃花因怀钱员外','白居易','quantangshi','','卷23','前日归时花正红，今夜宿时枝半空。
坐惜残芳君不见，风吹狼藉月明中。','',''),('quantangshi-22666','和钱员外早冬玩禁中新菊','白居易','quantangshi','','卷23','禁署寒气迟，孟冬菊初坼。
新黄间繁绿，烂若金照碧。
仙郎小隐日，心似陶彭泽。
秋怜潭上看，日惯篱边摘。
今来此地赏，野意潜自适。
金马门内花，玉山峰下客。
寒芳引清句，吟玩烟景夕。
赐酒色偏宜，握兰香不敌。
凄凄百卉死，岁晚冰霜积。
唯有此花开，殷勤助君惜。','',''),('quantangshi-22667','答刘戒之早秋别墅见寄','白居易','quantangshi','','卷23','凉风木槿篱，暮雨槐花枝。
并起新秋思，为得故人诗。
避地鸟择木，升朝鱼在池。
城中与山下，喧静暗相思。','',''),('quantangshi-22668','凉夜有怀','白居易','quantangshi','','卷23','念别感时节，早蛩闻一声。
风帘夜凉入，露簟秋意生。
灯尽梦初罢，月斜天未明。
暗凝无限思，起傍药阑行。','',''),('quantangshi-22669','秋思','白居易','quantangshi','','卷23','病眠夜少梦，闲立秋多思。
寂寞余雨晴，萧条早寒至。
鸟栖红叶树，月照青苔地。
何况镜中年，又过三十二。','',''),('quantangshi-22670','禁中闻蛩','白居易','quantangshi','','卷23','悄悄禁门闭，夜深无月明。
西窗独暗坐，满耳新蛩声。','',''),('quantangshi-22671','秋虫','白居易','quantangshi','','卷23','切切暗窗下，喓喓深草里。
秋天思妇心，雨夜愁人耳。','',''),('quantangshi-22672','赠别宣上人','白居易','quantangshi','','卷23','上人处世界，清净何所似。
似彼白莲花，在水不着水。
性真悟泡幻，行洁离尘滓。
修道来几时，身心俱到此。
嗟余牵世网，不得长依止。
离念与碧云，秋来朝夕起。','',''),('quantangshi-22673','春夜喜雪有怀王二十二','白居易','quantangshi','','卷23','夜雪有佳趣，幽人出书帷。
微寒生枕席，轻素对阶墀。
坐罢楚弦曲，起吟班扇诗。
明宜灭烛后，净爱褰帘时。
窗引曙色早，庭销春气迟。
山阴应有兴，不卧待徽之。','',''),('quantangshi-22674','酬和元九东川路诗十二首 骆口驿旧题诗','白居易','quantangshi','','卷23','拙诗在壁无人爱，鸟污苔侵文字残。
唯有多情元侍御，绣衣不惜拂尘看。','',''),('quantangshi-22675','酬和元九东川路诗十二首 南秦雪','白居易','quantangshi','','卷23','往岁曾为西邑吏，惯从骆口到南秦。
三时云冷多飞雪，二月山寒少有春。
我思旧事犹惆怅，君作初行定苦辛。
任赖愁猨寒不叫，若闻猨叫更愁人。','',''),('quantangshi-22676','酬和元九东川路诗十二首 山枇杷花二首 一','白居易','quantangshi','','卷23','万重青嶂蜀门口，一树红花山顶头。
春尽忆家归未得，低红如解替君愁。','',''),('quantangshi-22677','酬和元九东川路诗十二首 山枇杷花二首 二','白居易','quantangshi','','卷23','叶如帬色碧绡浅，花似芙蓉红粉轻。
若使此花兼解语，推囚御史定违程。','',''),('quantangshi-22678','酬和元九东川路诗十二首 江楼月','白居易','quantangshi','','卷23','嘉陵江曲曲江池，明月虽同人别离。
一宵光景潜相忆，两地阴晴远不知。
谁料江边怀我夜，正当池畔望君时。
今朝共语方同悔，不解多情先寄诗。','',''),('quantangshi-22679','酬和元九东川路诗十二首 亚枝花','白居易','quantangshi','','卷23','山邮花木似平阳，愁杀多情骢马郎。
还似升平池畔坐，低头向水自看妆。','',''),('quantangshi-22680','酬和元九东川路诗十二首 江上笛','白居易','quantangshi','','卷23','江上何人夜吹笛，声声似忆故园春。
此时闻者堪头白，况是多愁少睡人。','',''),('quantangshi-22681','酬和元九东川路诗十二首 嘉陵夜有怀二首 一','白居易','quantangshi','','卷23','露湿墙花春意深，西廊月上半牀阴。
怜君独卧无言语，唯我知君此夜心。','',''),('quantangshi-22682','酬和元九东川路诗十二首 嘉陵夜有怀二首 二','白居易','quantangshi','','卷23','不明不暗胧胧月，不暖不寒慢慢风。
独卧空牀好天气，平明闲事到心中。','',''),('quantangshi-22683','酬和元九东川路诗十二首 夜深行','白居易','quantangshi','','卷23','百牢关外夜行客，三殿角头宵直人。
莫道近臣胜远使，其如同是不闲身。','',''),('quantangshi-22684','酬和元九东川路诗十二首 望驿台','白居易','quantangshi','','卷23','靖安宅里当窗柳，望驿台前扑地花。
两处春光同日尽，居人思客客思家。','',''),('quantangshi-22685','酬和元九东川路诗十二首 江岸棃花','白居易','quantangshi','','卷23','棃花有思缘和叶，一树江头恼杀君。
最似孀闺少年妇，白妆素袖碧纱帬。','',''),('quantangshi-22686','答谢家最小偏怜女','白居易','quantangshi','','卷23','嫁得梁鸿六七年，耽书爱酒日高眠。
雨荒春圃唯生草，雪压朝厨未有烟。
身病忧来缘女少，家贫忘却为夫贤。
谁知厚俸今无分，枉向秋风吹纸钱。','',''),('quantangshi-22687','答骑马入空台','白居易','quantangshi','','卷23','君入空台去，朝往暮还来。
我入泉台去，泉门无复开。
鳏夫任系职，穉女未胜哀。
寂寞咸阳道，家人覆墓回。','',''),('quantangshi-22688','答山驿梦','白居易','quantangshi','','卷23','入君旅梦来千里，闭我幽魂欲二年。
莫忘平生行坐处，后堂阶下竹丛前。','',''),('quantangshi-22689','和元九与吕二同宿话旧感赠','白居易','quantangshi','','卷23','见君新赠吕君诗，忆得同年行乐时。
争入杏园齐马首，潜过柳曲鬬蛾眉。
八人云散俱游宦，七度花开尽别离。
闻道秋娘犹且在，至今时复问微之。','',''),('quantangshi-22690','忆元九','白居易','quantangshi','','卷23','渺渺江陵道，相思远不知。
近来文卷里，半是忆君诗。','',''),('quantangshi-22691','萧员外寄新蜀茶','白居易','quantangshi','','卷23','蜀茶寄到但惊新，渭水煎来始觉珍。
满瓯似乳堪持玩，况是春深酒渴人。','',''),('quantangshi-22692','寄上大兄','白居易','quantangshi','','卷23','秋鸿过尽无书信，病戴纱巾强出门。
独上荒台东北望，日西愁立到黄昏。','',''),('quantangshi-22693','病中哭金銮子','白居易','quantangshi','','卷23','岂料吾方病，飜悲汝不全。
卧惊从枕上，扶哭就灯前。
有女诚为累，无儿岂免怜。
病来才十日，养得已三年。
慈泪随声迸，悲肠遇物牵。
故衣犹架上，残药尚头边。
送出深村巷，看封小墓田。
莫言三里地，此别是终天。','',''),('quantangshi-22694','寄内','白居易','quantangshi','','卷23','条桑初绿即为别，柿叶半红犹未归。
不如村妇知时节，解为田夫秋捣衣。','',''),('quantangshi-22695','病气','白居易','quantangshi','','卷23','自知气发每因情，情在何由气得平。
若问病根深与浅，此身应与病齐生。','',''),('quantangshi-22696','叹元九','白居易','quantangshi','','卷23','不入城门来五载，同时班列尽官高。
何人牢落犹依旧，唯有江陵元士曹。','',''),('quantangshi-22697','眼暗','白居易','quantangshi','','卷23','早年勤倦看书苦，晚岁悲伤出泪多。
眼损不知都自取，病成方悟欲如何。
夜昏乍似灯将灭，朝暗长疑镜未磨。
千药万方治不得，唯应闭目学头陀。','',''),('quantangshi-22698','得袁相书','白居易','quantangshi','','卷23','谷苗深处一农夫，面黑头斑手把锄。
何意使人犹识我，就田来送相公书。','',''),('quantangshi-22699','病中作','白居易','quantangshi','','卷23','病来城里诸亲故，厚薄亲疎心总知。
唯有蔚章于我分，深于同在翰林时。','',''),('quantangshi-22700','感化寺见元九刘三十二题名处','白居易','quantangshi','','卷23','微之谪去千余里，太白无来十一年。
今日见名如见面，尘埃壁上破窗前。','',''),('quantangshi-22701','游悟贞寺回山下别张殷衡','白居易','quantangshi','','卷23','世缘未了治不得，孤负青山心共知。
愁君又入都门去，即是红尘满眼时。','',''),('quantangshi-22702','村居寄张殷衡','白居易','quantangshi','','卷23','金氏村中一病夫，生涯濩落性灵迂。
唯看老子五千字，不蹋长安十二衢。
药铫夜倾残酒暖，竹牀寒取旧毡铺。
闻君欲发江东去，能到茅庵访别无。','',''),('quantangshi-22703','病中得樊大书','白居易','quantangshi','','卷23','荒村破屋经年卧，寂绝无人问病身。
唯有东都樊着作，至今书信尚殷勤。','',''),('quantangshi-22704','开元九诗书卷','白居易','quantangshi','','卷23','红牋白纸两三束，半是君诗半是书。
经年不展缘身病，今日开看生蠹鱼。','',''),('quantangshi-22705','昼卧','白居易','quantangshi','','卷23','抱枕无言语，空房独悄然。
谁知尽日卧，非病亦非眠。','',''),('quantangshi-22706','夜坐','白居易','quantangshi','','卷23','庭前尽日立到夜，灯下有时坐彻明。
此情不语何人会，时复长吁一两声。','',''),('quantangshi-22707','暮立','白居易','quantangshi','','卷23','黄昏独立佛堂前，满地槐花满树蝉。
大抵四时心总苦，就中肠断是秋天。','',''),('quantangshi-22708','有感','白居易','quantangshi','','卷23','绝弦与断丝，犹有却续时。
唯有衷肠断，应无续得期。','',''),('quantangshi-22709','答友问','白居易','quantangshi','','卷23','似玉童颜尽，如霜病鬓新。
莫惊身顿老，心更老于身。','',''),('quantangshi-22710','村夜','白居易','quantangshi','','卷23','霜草苍苍虫切切，村南村北行人绝。
独出前门望野田，月明荞麦花如雪。','',''),('quantangshi-22711','闻虫','白居易','quantangshi','','卷23','暗虫唧唧夜緜緜，况是秋阴欲雨天。
犹恐愁人暂得睡，声声移近卧牀前。','',''),('quantangshi-22712','寒食夜有怀','白居易','quantangshi','','卷23','寒食非长非短夜，春风不热不寒天。
可怜时节堪相忆，何况无灯各早眠。','',''),('quantangshi-22713','赠内','白居易','quantangshi','','卷23','漠漠暗苔新雨地，微微凉露欲秋天。
莫对月明思往事，损君颜色减君年。','',''),('quantangshi-22714','得钱舍人书问眼疾','白居易','quantangshi','','卷23','春来眼暗少心情，点尽黄连尚未平。
唯得君书胜得药，开缄未读眼先明。','',''),('quantangshi-22715','还李十一马','白居易','quantangshi','','卷23','传语李君劳寄马，病来唯着杖扶身。
纵拟强骑无出处，却将牵与趁朝人。','',''),('quantangshi-22716','九日寄行简','白居易','quantangshi','','卷23','摘得菊花携得酒，绕村骑马思悠悠。
下邽田地平如掌，何处登髙望梓州。','',''),('quantangshi-22717','夜坐','白居易','quantangshi','','卷23','斜月入前楹，迢迢夜坐情。
梧桐上阶影，蟋蟀近牀声。
曙傍窗间至，秋从簟上生。
感时因忆事，不寝到鸡鸣。','',''),('quantangshi-22718','村居二首 一','白居易','quantangshi','','卷23','田园莽苍经春早，篱落萧条尽日风。
若问经过谈笑者，不过田舍白头翁。','',''),('quantangshi-22719','村居二首 二','白居易','quantangshi','','卷23','门闭仍逢雪，厨寒未起烟。
贫家重寥落，半为日高眠。','',''),('quantangshi-22720','早春','白居易','quantangshi','','卷23','雪散因和气，冰开得暖光。
春销不得处，唯有鬓边霜。','',''),('quantangshi-22721','和梦游春诗一百韵','白居易','quantangshi','','卷23','昔君梦游春，梦游仙山曲。
怳若有所遇，似惬平生欲。
因寻菖蒲水，渐入桃花谷。
到一红楼家，爱之看不足。
池流渡清泚，草嫩蹋绿蓐。
门柳暗全低，檐樱红半熟。
转行深深院，过尽重重屋。
乌龙卧不惊，青鸟飞相逐。
渐闻玉佩响，始辨珠履躅。
遥见窗下人，娉婷十五六。
霞光抱明月，莲艳开初旭。
缥缈云雨仙，氛氲兰麝馥。
风流薄梳洗，时世宽妆束。
袖輭异文绫，裾轻单丝縠。
裙腰银线压，梳掌金筐蹙。
带襭紫蒲萄，袴花红石竹。
凝情都未语，付意微相瞩。
眉敛远山青，鬟低片云绿。
帐牵翡翠带，被解鸳鸯襆。
秀色似堪餐，穠华如可掬。
半卷锦头席，斜铺绣腰褥。
朱唇素指匀，粉汗红緜扑。
心惊睡易觉，梦断魂难续。
笼委独栖禽，劒分连理木。
存诚期有感，誓志贞无黩。
京洛八九春，未曾花里宿。
壮年徒自弃，佳会应无复。
鸾歌不重闻，凤兆从兹卜。
韦门女清贵，裴氏甥贤淑。
罗扇夹花灯，金鞍攒绣毂。
既倾南国貌，遂坦东牀腹。
刘阮心渐忘，潘杨意方睦。
新修履信第，初食尚书禄。
九酝备圣贤，八珍穷水陆。
秦家重萧史，彦辅怜卫叔。
朝馔馈独盘，夜醪倾百斛。
亲宾盛辉赫，妓乐纷晔煜。
宿醉才解酲，朝欢俄枕麴。
饮过君子争，令甚将军酷。
酩酊歌鹧鸪，颠狂舞鸲鹆。
月流春夜短，日下秋天速。
谢傅隙过驹，萧娘风过烛。
全凋蕣花折，半死梧桐秃。
暗镜对孤鸾，哀弦留寡鹄。
凄凄隔幽显，冉冉移寒燠。
万事此时休，百身何处赎。
提携小儿女，将领旧姻族。
再入朱门行，一傍青楼哭。
枥空无廐马，水涸失池[鹜]。
摇落废井梧，荒凉故篱菊。
莓苔上几阁，尘土生琴筑。
舞榭缀蟏蛸，歌梁聚蝙蝠。
嫁分红粉妾，卖散苍头仆。
门客思旁徨，家人泣吚噢。
心期正萧索，宦序仍拘局。
怀策入崤函，驱车辞郏鄏。
逢时念既济，聚学思大畜。
端详筮仕蓍，磨拭穿杨镞。
始从讐校职，首中贤良目。
一拔侍瑶墀，再升纡绣服。
誓酬君王宠，愿使朝廷肃。
密勿奏封章，清明操宪牍。
鹰韝中病下，豸角当邪触。
纠谬静东周，申冤动南蜀。
危言诋阍寺，直气忤钧轴。
不忍曲作钩，乍能折为玉。
扪心无愧畏，腾口有谤讟。
只要明是非，何曾虞祸福。
车摧太行路，劒落酆城狱。
襄汉问修途，荆蛮指殊俗。
谪为江府掾，遣事荆州牧。
趋走谒麾幢，喧烦视鞭朴。
簿书常自领，缧囚每亲鞫。
竟日坐官曹，经旬旷休沐。
宅荒渚宫草，马瘦畲田粟。
薄俸等涓毫，微官同桎梏。
月中照形影，天际辞骨肉。
鹤病翅羽垂，兽穷爪牙缩。
行看须间白，谁劝杯中绿。
时伤大野麟，命问长沙鵩。
夏梅山雨渍，秋瘴江云毒。
巴水白茫茫，楚山青簇簇。
吟君七十韵，是我心所蓄。
既去诚莫追，将来幸前勖。
欲除忧恼病，当取禅经读。
须悟事皆空，无令念将属。
请思游春梦，此梦何闪倏。
艳色即空花，浮生乃焦谷。
良姻在嘉偶，顷克为单独。
入仕欲荣身，须臾成黜辱。
合者离之始，乐兮忧所伏。
愁恨僧只长，欢荣刹那促。
觉悟因傍喻，迷执由当局。
膏明诱暗蛾，阳焱奔痴鹿。
贪为苦聚落，爱是悲林麓。
水荡无明波，轮回死生辐。
尘应甘露洒，垢待醍醐浴。
障要智灯烧，魔须慧刀戮。
外熏性易染，内战心难衂。
法句与心王，期君日三复。','',''),('quantangshi-22722','王昭君二首 一','白居易','quantangshi','','卷23','满面胡沙满鬓风，眉销残黛脸销红。
愁苦辛勤顦顇尽，如今却似画图中。','',''),('quantangshi-22723','王昭君二首 二','白居易','quantangshi','','卷23','汉使却回凭寄语，黄金何日赎蛾眉。
君王若问妾颜色，莫道不知宫里时。','',''),('quantangshi-22724','渭村退居寄礼部崔侍郎翰林钱舍人诗一百韵','白居易','quantangshi','','卷23','圣代元和岁，闲居渭水阳。
不才甘命舛，多幸遇时康。
朝野分伦序，贤愚定否臧。
重文疎卜式，尚少弃冯唐。
由是推天运，从兹乐性场。
笼禽放高翥，雾豹得深藏。
世虑休相扰，身谋且自强。
犹须务衣食，未免事农桑。
剃草通三径，开田占一坊。
昼扉扃白版，夜碓埽黄粱。
隙地治场圃，闲时粪土疆。
枳篱编刺夹，薤垄擘科秧。
穑力嫌身病，农心愿岁穰。
朝衣典杯酒，佩劒博牛羊。
困倚栽松锸，饥提采蕨筐。
引泉来后涧，移竹下前冈。
生计虽勤苦，家资甚渺茫。
尘埃常满甑，钱帛少盈囊。
弟病仍扶杖，妻愁不出房。
传衣念繿缕，举案笑糟糠。
犬吠村胥闹，蝉鸣织妇忙。
纳租看县贴，输粟问军仓。
夕歇攀村树，秋行绕野塘。
云容阴惨澹，月色冷悠扬。
荞麦铺花白，棠棃间叶黄。
早寒风摵摵，新霁月苍苍。
园菜迎霜死，庭芜过雨荒。
檐空愁宿燕，壁暗思啼螿。
眼为看书损，肱因运甓伤。
病骸浑似木，老鬓欲成霜。
少睡知年长，端忧觉夜长。
旧游多废忘，往事偶思量。
忽忆烟霄路，常陪劒履行。
登朝思检束，入阁学趋跄。
命偶风云会，恩覃雨露霶。
霑枯发枝叶，磨钝起锋铓。
崔合连镳骛，钱兄接翼翔。
齐竽混韶夏，燕石厕琳琅。
同日升金马，分宵直未央。
共词加宠命，合表谢恩光。
廐马骄初跨，天厨味始尝。
朝晡颁饼饵，寒暑赐衣裳。
对秉鹅毛笔，俱含鸡舌香。
青缣衾薄絮，朱里幕高张。
昼食恒连案，宵眠每竝牀。
差肩承诏旨，连署进封章。
起草偏同视，疑文最共详。
灭私容点窜，穷理析毫芒。
便共输肝胆，何曾异肺肠。
慎微参石奋，决密与张汤。
禁闼青交琐，宫垣紫界墙。
井阑排菡萏，檐瓦鬬鸳鸯。
楼额题鳷鹊，池心浴凤凰。
风枝万年动，温树四时芳。
宿露凝金掌，晨晖上璧璫。
砌筠涂绿粉，庭果滴红浆。
晓从朝兴庆，春陪宴柏梁。
传呼鞭索索，拜舞佩锵锵。
仙仗环双阙，神兵辟两厢。
火飜红尾斾，冰卓白竿枪。
滉漾经鱼藻，深沈近浴堂。
分庭皆命妇，对院即储皇。
贵主冠浮动，亲王辔闹装。
金钿相照耀，朱紫间荧煌。
球簇桃花绮，歌巡竹叶觞。
洼银中贵带，昂黛内人妆。
赐禊东城下，颁酺曲水傍。
尊罍分圣酒，妓乐借仙倡。
浅酌看红药，徐吟把绿杨。
宴回过御陌，行歇入僧房。
白鹿原东脚，青龙寺北廊。
望春花景暖，避暑竹风凉。
下直闲如社，寻芳醉似狂。
有时还后到，无处不相将。
鸡鹤初虽杂，萧兰久乃彰。
来燕隗贵重，去鲁孔恓惶。
聚散期难定，飞沈势不常。
五年同昼夜，一别似参商。
屈折孤生竹，销摧百炼钢。
途穷任顦顇，道在肯旁徨。
尚念遗簪折，仍怜病雀疮。
恤寒分赐帛，救馁减余粮。
药物来盈裹，书题寄满箱。
殷勤翰林主，珍重礼闱郎。
喣沫诚多谢，抟扶岂所望。
提携劳气力，吹簸不飞扬。
拙劣才何用，龙钟分自当。
妆嫫徒费黛，磨甋讵成璋。
习隐将时背，干名与道妨。
外身宗老氏，齐物学蒙庄。
疎放遗千虑，愚蒙守一方。
乐天无怨叹，倚命不匡勷。
愤懑胷须豁，交加臂莫攘。
珠沈犹是宝，金跃未为祥。
泥尾休摇掉，灰心罢激昂。
渐闲亲道友，因病事医王。
息乱归禅定，存神入坐亡。
断痴求慧劒，济苦得慈航。
不动为吾志，无何是我乡。
可怜身与世，从此两相忘。','',''),('quantangshi-22725','酬卢祕书二十韵','白居易','quantangshi','','卷23','谬历文场选，慙非翰苑才。
云霄高暂致，毛羽弱先摧。
识分忘轩冕，知归返草莱。
杜陵书积蠹，丰狱劒生苔。
晦厌鸣鸡雨，春惊震蛰雷。
旧恩收坠履，新律动寒灰。
凤诏容徐起，鵷行许重陪。
衰颜虽拂拭，蹇步尚低徊。
睡少钟偏警，行迟漏苦摧。
风霜趁朝去，泥雪拜陵回。
上感君犹念，傍慙友或推。
石顽镌费匠，女丑嫁劳媒。
倏忽青春度，奔波白日颓。
性将时共背，病与老俱来。
闻有蓬壶客，知怀杞梓材。
世家标甲第，官职滞麟台。
笔尽铅黄点，诗成锦绣堆。
尝思豁云雾，忽喜访尘埃。
心为论文合，眉因劝善开。
不胜珍重意，满袖写琼瓌。','',''),('quantangshi-22726','题卢祕书夏日新栽竹二十韵','白居易','quantangshi','','卷23','湘竹初封植，卢生此考盘。
久持霜节苦，新托露根难。
等度须当砌，疎稠要满阑。
买怜分薄俸，栽称作闲官。
叶翦蓝罗碎，茎抽玉琯端。
几声清淅沥，一簇绿檀栾。
未夜青岚入，先秋白露团。
拂肩摇翡翠，熨手弄琅玕。
韵透窗风起，阴铺砌月残。
炎天闻觉冷，窄地见疑宽。
梢动胜摇扇，枝低好挂冠。
碧笼烟幕幕，珠洒雨珊珊。
晚箨晴云展，阴芽蛰虺蟠。
爱从抽马策，惜未截鱼竿。
松韵徒烦听，桃夭不足观。
梁慙当家杏，台陋本司兰。
撑拨诗人兴，勾牵酒客欢。
静连芦簟滑，凉拂葛衣单。
岂止消时暑，应能保岁寒。
莫同凡草木，一种夏中看。','',''),('quantangshi-22727','渭村酬李二十见寄','白居易','quantangshi','','卷23','百里音书何太迟，暮秋把得暮春诗。
柳条绿日君相忆，棃叶红时我始知。
莫叹学官贫冷落，犹胜村客病支离。
形容意绪遥看取，不似华阳观里时。','',''),('quantangshi-22728','初授赞善大夫早朝寄李二十助教','白居易','quantangshi','','卷23','病身初谒青宫日，衰貌新垂白发年。
寂莫曹司非热地，萧条风雪是寒天。
远坊早起常侵鼓，瘦马行迟苦费鞭。
一种共君官职冷，不如犹得日高眠。','',''),('quantangshi-22729','欲与元八卜邻先有是赠','白居易','quantangshi','','卷23','平生心迹最相亲，欲隐墙东不为身。
明月好同三径夜，绿杨宜作两家春。
每因暂出犹思伴，岂得安居不择邻。
何独终身数相见，子孙长作隔墙人。','',''),('quantangshi-22730','游城南留元九李二十晚归','白居易','quantangshi','','卷23','老游春饮莫相违，不独花稀人亦稀。
更劝残杯看日影，犹应趁得鼓声归。','',''),('quantangshi-22731','广宣上人以应制诗见示因以赠之诏许上人居安国寺红楼院以诗供奉','白居易','quantangshi','','卷23','道林谈论惠休诗，一到人天便作师。
香积筵承紫泥诏，昭阳歌唱碧云词。
红楼许住请银钥，翠辇陪行蹋玉墀。
惆怅甘泉曾侍从，与君前后不同时。','',''),('quantangshi-22732','重过祕书旧房因题长句','白居易','quantangshi','','卷23','阁前下马思裴回，第二房门手自开。
昔为白面书郎去，今作苍须赞善来。
吏人不识多新补，松竹相亲是旧栽。
应有题墙名姓在，试将衫袖拂尘埃。','',''),('quantangshi-22733','重到城七绝句 见元九','白居易','quantangshi','','卷23','容貌一日减一日，心情十分无九分。
每逢陌路犹嗟叹，何况今朝是见君。','',''),('quantangshi-22734','重到城七绝句 高相宅','白居易','quantangshi','','卷23','青苔故里怀恩地，白发新生抱病身。
涕泪虽多无哭处，永宁门馆属他人。','',''),('quantangshi-22735','重到城七绝句 张十八','白居易','quantangshi','','卷23','谏垣几见迁遗补，宪府频闻转殿监。
独有咏诗张太祝，十年不改旧官衔。','',''),('quantangshi-22736','重到城七绝句 刘家花','白居易','quantangshi','','卷23','刘家墙上花还发，李十门前草又春。
处处伤心心始悟，多情不及少情人。','',''),('quantangshi-22737','重到城七绝句 裴五','白居易','quantangshi','','卷23','莫怪相逢无笑语，感今思旧戟门前。
张家伯仲偏相似，每见清扬一惘然。','',''),('quantangshi-22738','重到城七绝句 仇家酒','白居易','quantangshi','','卷23','年年老去欢情少，处处春来感事深。
时到仇家非爱酒，醉时心胜醒时心。','',''),('quantangshi-22739','重到城七绝句 恒寂师','白居易','quantangshi','','卷23','旧游分散人零落，如此伤心事几条。
会逐禅师坐禅去，一时灭尽定中消。','',''),('quantangshi-22740','靖安北街赠李二十','白居易','quantangshi','','卷23','榆荚抛钱柳展眉，两人竝马语行迟。
还似往年安福寺，共君私试却回时。','',''),('quantangshi-22741','重伤小女子','白居易','quantangshi','','卷23','学人言语凭牀行，嫩似花房脆似琼。
才知恩爱迎三岁，未辨东西过一生。
汝异下殇应杀礼，吾非上圣讵忘情。
伤心自叹鸠巢拙，长堕春雏养不成。','',''),('quantangshi-22742','过颜处士墓','白居易','quantangshi','','卷23','向坟道径没荒榛，满室诗书积暗尘。
长夜肯教黄壤晓，悲风不许白杨春。
箪瓢颜子生仍促，布被黔娄死更贫。
未会悠悠上天意，惜将富寿与何人。','',''),('quantangshi-22743','题周皓大夫新亭子二十二韵','白居易','quantangshi','','卷23','东道常为主，南亭别待宾。
规模何日创，景致一时新。
广砌罗红药，疎窗荫绿筠。
锁开宾阁晓，梯上妓楼春。
置醴宁三爵，加笾过八珍。
茶香飘紫笋，脍缕落红鳞。
辉赫车舆闹，珍奇鸟兽驯。
猕猴看枥马，鹦鹉唤家人。
锦额帘高卷，银花盏慢巡。
劝尝光禄酒，许看洛川神。
敛翠凝歌黛，流香动舞巾。
帬飜绣鸂鶒，梳陷钿麒麟。
笛怨音含楚，筝娇语带秦。
侍儿催画烛，醉客吐文茵。
投辖多连夜，鸣珂便达晨。
入朝纡紫绶，待漏拥朱轮。
贵介交三事，光荣照四邻。
甘浓将奉客，稳暖不缘身。
十载歌钟地，三朝节钺臣。
爱才心倜傥，敦旧礼殷勤。
门以招贤盛，家因好事贫。
始知豪杰意，富贵为交亲。','',''),('quantangshi-22744','赋得听边鸿','白居易','quantangshi','','卷23','惊风吹起塞鸿羣，半拂平沙半入云。
为问昭君月下听，何如苏武雪中闻。','',''),('quantangshi-22745','见杨弘贞诗赋因题绝句以自谕','白居易','quantangshi','','卷23','赋句诗章妙入神，未年三十即无身。
常嗟薄命形顦顇，若比弘贞是幸人。','',''),('quantangshi-22746','病中早春','白居易','quantangshi','','卷23','今朝枕上觉头轻，强起阶前试脚行。
膻腻断来无气力，风痰恼得少心情。
暖消霜瓦津初合，寒减冰渠冻不成。
唯有愁人鬓间雪，不随春尽逐春生。','',''),('quantangshi-22747','送人贬信州判官','白居易','quantangshi','','卷23','地僻山深古上饶，土风贫薄道程遥。
不唯迁客须恓屑，见说居人也寂寥。
溪畔毒沙藏水弩，城头枯树下山魈。
若于此郡为卑吏，刺史厅前又折腰。','',''),('quantangshi-22748','曲江醉后赠诸亲故','白居易','quantangshi','','卷23','郭东丘墓何年客，江畔风光几日春。
只合殷勤逐杯酒，不须疎索向交亲。
中天或有长生药，下界应无不死人。
除却醉来开口笑，世间何事更关身。','',''),('quantangshi-22749','和元八侍御升平新居四绝句 看花屋','白居易','quantangshi','','卷23','忽惊映树新开屋，却似当檐故种花。
可惜年年红似火，今春始得属元家。','',''),('quantangshi-22750','和元八侍御升平新居四绝句 累土山','白居易','quantangshi','','卷23','堆土渐高山意出，终南移入户庭间。
玉峰蓝水应惆怅，恐见新山望旧山。','',''),('quantangshi-22751','和元八侍御升平新居四绝句 高亭','白居易','quantangshi','','卷23','亭脊太高君莫拆，东家留取当西山。
好看落日斜衔处，一片春岚映半环。','',''),('quantangshi-22752','和元八侍御升平新居四绝句 松树','白居易','quantangshi','','卷23','白金换得青松树，君既先栽我不栽。
幸有西风易凭仗，夜深偷送好声来。','',''),('quantangshi-22753','醉后却寄元九','白居易','quantangshi','','卷23','蒲池村里悤悤别，沣水桥边兀兀回。
行到城门残酒醒，万重离恨一时来。','',''),('quantangshi-22754','重寄','白居易','quantangshi','','卷23','萧散弓惊雁，分飞劒化龙。
悠悠天地内，不死会相逢。','',''),('quantangshi-22755','李十一舍人松园饮小酎酒得元八侍御诗叙云在台中推院有鞫狱之苦即事书怀因酬四韵','白居易','quantangshi','','卷23','爱酒舍人开小酌，能文御史寄新诗。
乱松园里醉相忆，古柏厅前忙不知。
早夏我当逃暑日，晚衙君是虑囚时。
唯应清夜无公事，新草亭中好一期。','',''),('quantangshi-22756','重到华阳观旧居','白居易','quantangshi','','卷23','忆昔初年三十二，当时秋思已难堪。
若为重入华阳院，病鬓愁心四十三。','',''),('quantangshi-22757','答劝酒','白居易','quantangshi','','卷23','莫怪近来都不饮，几回因醉却霑巾。
谁料平生狂酒客，如今变作酒悲人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22758','题王侍御池亭','白居易','quantangshi','','卷23','朱门深锁春池满，岸落蔷薇水浸莎。
毕竟林塘谁是主，主人来少客来多。','',''),('quantangshi-22759','听水部吴员外新诗因赠绝句','白居易','quantangshi','','卷23','朱绂仙郎白雪歌，和人虽少爱人多。
明朝说与诗人道，水部如今不姓何。','',''),('quantangshi-22760','雨夜忆元九','白居易','quantangshi','','卷23','天阴一日便堪愁，何况连宵雨不休。
一种雨中君最苦，偏梁阁道向通州。','',''),('quantangshi-22761','雨中携元九诗访元八侍御','白居易','quantangshi','','卷23','微之诗卷忆同开，假日多应不入台。
好句无人堪共咏，冲泥蹋水就君来。','',''),('quantangshi-22762','赠杨祕书巨源','白居易','quantangshi','','卷23','早闻一箭取辽城，相识虽新有故情。
清句三朝谁是敌，白须四海半为兄。
贫家剃草时时入，瘦马寻花处处行。
不用更教诗过好，折君官职是声名。','',''),('quantangshi-22763','和武相公感韦令公旧池孔雀','白居易','quantangshi','','卷23','索莫少颜色，池边无主禽。
难收带泥翅，易结着人心。
顶毳落残碧，尾花销暗金。
放归飞不得，云海故巢深。','',''),('quantangshi-22764','寄生衣与微之因题封上','白居易','quantangshi','','卷23','浅色縠衫轻似雾，纺花纱袴薄于云。
莫嫌轻薄但知着，犹恐通州热杀君。','',''),('quantangshi-22765','白牡丹','白居易','quantangshi','','卷23','白花冷澹无人爱，亦占芳名道牡丹。
应似东宫白赞善，被人还唤作朝官。','',''),('quantangshi-22766','梦旧','白居易','quantangshi','','卷23','别来老大苦修道，炼得离心成死灰。
平生忆念消磨尽，昨夜因何入梦来。','',''),('quantangshi-22767','戏题卢祕书新移蔷薇','白居易','quantangshi','','卷23','风动翠条腰袅娜，露垂红萼泪阑干。
移他到此须为主，不别花人莫使看。','',''),('quantangshi-22768','曲江夜归闻元八见访','白居易','quantangshi','','卷23','自入台来见面稀，班中遥得揖容辉。
早知相忆来相访，悔待江头明月归。','',''),('quantangshi-22769','苦热题恒寂师禅室','白居易','quantangshi','','卷23','人人避暑走如狂，独有禅师不出房。
可是禅房无热到，但能心静即身凉。','',''),('quantangshi-22770','微之到通州日授馆未安见尘壁间有数行字读之即仆旧诗其落句云渌水红莲一朵开千花百草无颜色然不知题者何人也微之吟叹不足因缀一章兼录仆诗本同寄省其诗乃十五年前初及第时赠长安妓人阿輭绝句缅思往事杳若梦中怀旧感今因酬长句','白居易','quantangshi','','卷23','十五年前似梦游，曾将诗句结风流。
偶助笑歌嘲阿輭，可知传诵到通州。
昔教红袖佳人唱，今遣青衫司马愁。
惆怅又闻题处所，雨淋江馆破墙头。','',''),('quantangshi-22771','得微之到官后书备知通州之事怅然有感因成四章 一','白居易','quantangshi','','卷23','来书子细说通州，州在山根峡岸头。
四面千重火云合，中心一道瘴江流。
虫蛇白昼拦官道，蚊蚋黄昏扑郡楼。
何罪遣君居此地，天高无处问来由。','',''),('quantangshi-22772','得微之到官后书备知通州之事怅然有感因成四章 二','白居易','quantangshi','','卷23','匼匝巅山万仞余，人家应似甑中居。
寅年篱下多逢虎，亥日沙头始卖鱼。
衣斑梅雨长须熨，米涩畲田不解鉏。
努力安心过三考，已曾愁杀李尚书。','',''),('quantangshi-22773','得微之到官后书备知通州之事怅然有感因成四章 三','白居易','quantangshi','','卷23','人稀地僻医巫少，夏旱秋霖瘴疟多。
老去一身须爱惜，别来四体得如何。
侏儒饱笑东方朔，薏苡谗忧马伏波。
莫遣沈愁结成病，时时一唱濯缨歌。','',''),('quantangshi-22774','得微之到官后书备知通州之事怅然有感因成四章 四','白居易','quantangshi','','卷23','通州海内恓惶地，司马人间冗长官。
伤鸟有弦惊不定，卧龙无水动应难。
劒埋狱底谁深掘，松偃霜中尽冷看。
举目争能不惆怅，高车大马满长安。','',''),('quantangshi-22775','病中答招饮者','白居易','quantangshi','','卷23','顾我镜中悲白发，尽君花下醉青春。
不缘眼痛兼身病，可是尊前第二人。','',''),('quantangshi-22776','燕子楼三首 一','白居易','quantangshi','','卷23','满窗明月满帘霜，被冷灯残拂卧牀。
燕子楼中霜月夜，秋来只为一人长。','',''),('quantangshi-22777','燕子楼三首 二','白居易','quantangshi','','卷23','钿晕罗衫色似烟，几回欲着即潸然。
自从不舞霓裳曲，叠在空箱十一年。','',''),('quantangshi-22778','燕子楼三首 三','白居易','quantangshi','','卷23','今春有客洛阳回，曾到尚书墓上来。
见说白杨堪作柱，争教红粉不成灰。','',''),('quantangshi-22779','初贬官过望秦岭','白居易','quantangshi','','卷23','草草辞家忧后事，迟迟去国问前途。
望秦岭上回头立，无限秋风吹白须。','',''),('quantangshi-22780','蓝桥驿见元九诗','白居易','quantangshi','','卷23','蓝桥春雪君归日，秦岭秋风我去时。
