文章辩慧皆如此，笼槛何年出得身。','',''),('quantangshi-22785','题四皓庙','白居易','quantangshi','','卷23','卧逃秦乱起安刘，舒卷如云得自由。
若有精灵应笑我，不成一事谪江州。','',''),('quantangshi-22786','罢药','白居易','quantangshi','','卷23','自学坐禅休服药，从他时复病沈沈。
此身不要全彊健，彊健多生人我心。','',''),('quantangshi-22787','白鹭','白居易','quantangshi','','卷23','人生四十未全衰，我为愁多白发垂。
何故水边双白鹭，无愁头上亦垂丝。','',''),('quantangshi-22788','襄阳舟夜','白居易','quantangshi','','卷23','下马襄阳郭，移舟汉阴驿。
秋风截江起，寒浪连天白。
本是多愁人，复此风波夕。','',''),('quantangshi-22789','江夜舟行','白居易','quantangshi','','卷23','烟澹月蒙蒙，舟行夜色中。
