唯有红藤杖，相随万里来。','',''),('quantangshi-22791','江上吟元八绝句','白居易','quantangshi','','卷23','大江深处月明时，一夜吟君小律诗。
应有水仙潜出听，飜将唱作步虚词。','',''),('quantangshi-22792','途中感秋','白居易','quantangshi','','卷23','节物行摇落，年颜坐变衰。
