回看深浦停舟处，芦荻花中一点灯。','',''),('quantangshi-22798','卢侍御与崔评事为予于黄鹤楼置宴宴罢同望','白居易','quantangshi','','卷23','江边黄鹤古时楼，劳置华筵待我游。
