为寻庄子知归处，认得无何是本乡。','',''),('quantangshi-22807','江楼偶宴赠同座','白居易','quantangshi','','卷23','南浦闲行罢，西楼小宴时。
望湖凭槛久，待月放杯迟。
江果尝卢橘，山歌听竹枝。
相逢且同乐，何必旧相知。','',''),('quantangshi-22808','放言五首 一','白居易','quantangshi','','卷23','朝真暮伪何人辨，古往今来底事无。
