为学空门平等法，先齐老少死生心。','',''),('quantangshi-22814','岁暮道情二首 二','白居易','quantangshi','','卷23','半故青衫半白头，雪风吹面上江楼。
禅功自见无人觉，合是愁时亦不愁。','',''),('quantangshi-22815','读李杜诗集因题卷后','白居易','quantangshi','','卷23','翰林江左日，员外劒南时。
