天意君须会，人间要好诗。','',''),('quantangshi-22816','强酒','白居易','quantangshi','','卷23','若不坐禅销妄想，即须行醉放狂歌。
不然秋月春风夜，争那闲思往事何。','',''),('quantangshi-22817','独树浦雨夜寄李六郎中','白居易','quantangshi','','卷23','忽忆两家同里巷，何曾一处不追随。
