凭君向道休弹去，白尽江州司马头。','',''),('quantangshi-22819','望江州','白居易','quantangshi','','卷23','江回望见双华表，知是浔阳西郭门。
犹去孤舟三四里，水烟沙雨欲黄昏。','',''),('quantangshi-22820','初到江州','白居易','quantangshi','','卷23','浔阳欲到思无穷，庾亮楼南湓口东。
树木凋疎山雨后，人家低湿水烟中。
菰蒋餧马行无力，芦荻编房卧有风。
遥见朱轮来出郭，相迎劳动使君公。','',''),('quantangshi-22821','醉后题李马二妓','白居易','quantangshi','','卷23','行摇云髻花钿节，应似霓裳趁管弦。
艳动舞帬浑是火，愁凝歌黛欲生烟。
有风纵道能回雪，无水何由忽吐莲。
疑是两般心未决，雨中神女月中仙。','',''),('quantangshi-22822','卢侍御小妓乞诗座上留赠','白居易','quantangshi','','卷23','郁金香汗裛歌巾，山石榴花染舞帬。
好似文君还对酒，胜于神女不归云。
梦中那及觉时见，宋玉荆王应羡君。','',''),('quantangshi-22823','东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书','白居易','quantangshi','','卷23','南去经三楚，东来过五湖。
山头看候馆，水面问征途。
地远穷江界，天低极海隅。
飘零同落叶，浩荡似乘桴。
渐觉乡原异，深知土产殊。
夷音语嘲异常，蛮态笑睢盱。
水市通闤闠，烟村混舳舻。
吏征渔户税，人纳火田租。
亥日饶鰕蟹，寅年足虎貙。
成人男作丱，事鬼女为巫。
楼暗攒倡妇，堤长簇贩夫。
夜船论铺赁，春酒断瓶酤。
见果皆卢橘，闻禽悉鹧鸪。
山歌猨独叫，野哭鸟相呼。
岭徼云成栈，江郊水当郛。
月移翘柱鹤，风泛颭樯乌。
鳌碍潮无信，蛟惊浪不虞。
鼍鸣江擂鼓，蜃气海浮图。
树裂山魈穴，沙含水弩枢。
喘牛犂紫芋，羸马放青菰。
绣面谁家婢，鵶头几岁奴。
泥中采菱芡，烧后拾樵苏。
鼎腻愁烹鼈，盘腥厌脍鲈。
钟仪徒恋楚，张翰浪思吴。
气序凉还热，光阴旦复晡。
身方逐萍梗，年欲近桑榆。
渭北田园废，江西岁月徂。
忆归恒惨澹，怀旧忽踟蹰。
自念咸秦客，尝为邹鲁儒。
蕴藏经国术，轻弃度关繻。
赋力凌鹦鹉，词锋敌辘轳。
战文重掉鞅，射策一弯弧。
崔杜鞭齐下，元韦辔并驱。
名声逼扬马，交分过萧朱。
世务轻摩揣，周行窃觊觎。
风云皆会合，雨露各霑濡。
共遇升平代，偏慙固陋躯。
承明连夜直，建礼拂晨趋。
美服颁王府，珍羞降御厨。
议高通白虎，谏切伏青蒲。
柏殿行陪宴，花楼走看酺。
神旗张鸟兽，天籁动笙芋。
戈劒星芒耀，鱼龙电策驱。
定场排越伎，促坐进吴歈。
缥缈疑仙乐，婵娟胜画图。
歌鬟低翠羽，舞汗堕红珠。
别选闲游伴，潜招小饮徒。
一杯愁已破，三盏气弥麤。
輭美仇家酒，幽闲葛氏姝。
十千方得斗，二八正当垆。
论笑杓胡律，谈怜巩嗫嚅。
李酣犹短窦，庾醉更蔫迂。
鞍马呼教住，骰盘喝遣输。
长驱波卷白，连掷采成卢。
筹并频逃席，觥严列置盂。
满巵那可灌，颓玉不胜扶。
入视中枢草，归乘内廐驹。
醉曾冲宰相，骄不揖金吾。
日近恩虽重，云高势却孤。
飜身落霄汉，失脚倒泥涂。
博望移门籍，浔阳佐郡符。
时情变寒暑，世利算锱铢。
即日辞双阙，明朝别九衢。
播迁分郡国，次第出京都。
秦岭驰三驿，商山上二邘。
岘阳亭寂莫，夏口路崎岖。
大道全生棘，中丁尽执殳。
江关未撤警，淮寇尚稽诛。
林对东西寺，山分大小姑。
庐峰莲刻削，湓浦带萦纡。
九派吞青草，孤城覆绿芜。
黄昏钟寂寂，清晓角呜呜。
春色辞门柳，秋声到井梧。
残芳悲鶗鴂，暮节感茱萸。
蘂坼金英菊，花飘雪片芦。
波红日斜没，沙白月平铺。
几见林抽笋，频惊燕引雏。
岁华何倏忽，年少不须臾。
眇默思千古，苍茫想八区。
孔穷缘底事，颜夭有何辜。
龙智犹经醢，龟灵未免刳。
穷通应已定，圣哲不能逾。
况我身谋拙，逢他厄运拘。
漂流随大海，锤锻任洪炉。
险阻尝之矣，栖迟命也夫。
沈冥消意气，穷饿耗肌肤。
防瘴和残药，迎寒补旧襦。
书牀鸣蟋蟀，琴匣网蜘蛛。
贫室如悬磐，端忧剧守株。
时遭人指点，数被鬼揶揄。
兀兀都疑梦，昏昏半是愚。
女惊朝不起，妻怪夜长吁。
万里抛朋侣，三年隔友于。
自然悲聚散，不是恨荣枯。
去夏微之疟，今春席八殂。
天涯书达否，泉下哭知无。
谩写诗盈卷，空盛酒满壶。
只添新怅望，岂复旧欢娱。
壮志因愁减，衰容与病俱。
相逢应不识，满颔白髭须。','',''),('quantangshi-22824','谪居','白居易','quantangshi','','卷23','面瘦头斑四十四，远谪江州为郡史。
逢时弃置从不才，未老衰羸为何事。
火烧寒涧松为烬，霜降春林花委地。
遭时荣悴一时间，岂是昭昭上天意。','',''),('quantangshi-22825','初到江州寄翰林张李杜三学士','白居易','quantangshi','','卷23','早攀霄汉上天衢，晚落风波委世途。
雨露施恩无厚薄，蓬蒿随分有荣枯。
伤禽侧翅惊弓箭，老妇低颜事舅姑。
碧落三仙曾识面，年深记得姓名无。','',''),('quantangshi-22826','庾楼晓望','白居易','quantangshi','','卷23','独凭朱槛立凌晨，山色初明水色新。
竹雾晓笼衔岭月，苹风暖送过江春。
子城阴处犹残雪，衙鼓声前未有尘。
三百年来庾楼上，曾经多少望乡人。','',''),('quantangshi-22827','宿西林寺','白居易','quantangshi','','卷23','木落天晴山翠开，爱山骑马入山来。
心知不及柴桑令，一宿西林便却回。','',''),('quantangshi-22828','江楼宴别','白居易','quantangshi','','卷23','楼中别曲催离酌，灯下红裙间绿袍。
缥缈楚风罗绮薄，铮鏦越调管弦高。
寒流带月澄如镜，夕吹和霜利似刀。
尊酒未空欢未尽，舞腰歌袖莫辞劳。','',''),('quantangshi-22829','题山石榴花','白居易','quantangshi','','卷23','一丛千朵压阑干，翦碎红绡却作团。
风袅舞腰香不尽，露销妆脸泪新干。
蔷薇带刺攀应嬾，菡萏生泥玩亦难。
争及此花檐户下，任人采弄尽人看。','',''),('quantangshi-22830','代春赠','白居易','quantangshi','','卷23','山吐晴岚水放光，辛夷花白柳梢黄。
但知莫作江西意，风景何曾异帝乡。','',''),('quantangshi-22831','答春','白居易','quantangshi','','卷23','草烟低重水花明，从道风光似帝京。
其奈山猨江上叫，故乡无此断肠声。','',''),('quantangshi-22832','樱桃花下叹白发','白居易','quantangshi','','卷23','逐处花皆好，随年貌自衰。
红樱满眼日，白发半头时。
倚树无言久，攀条欲放迟。
临风两堪叹，如雪复如丝。','',''),('quantangshi-22833','惜落花赠崔二十四','白居易','quantangshi','','卷23','漠漠纷纷不奈何，狂风急雨两相和。
晚来怅望君知否，枝上稀疎地上多。','',''),('quantangshi-22834','移山樱桃','白居易','quantangshi','','卷23','亦知官舍非吾宅，且斸山樱满院栽。
上佐近来多五考，少应四度见花开。','',''),('quantangshi-22835','官舍闲题','白居易','quantangshi','','卷23','职散优闲地，身慵老大时。
送春唯有酒，销日不过棊。
禄米麞牙稻，园蔬鸭脚葵。
饱餐仍晏起，余暇弄龟儿。','',''),('quantangshi-22836','晚春登大云寺南楼赠常禅师','白居易','quantangshi','','卷23','花尽头新白，登楼意若何。
岁时春日少，世界苦人多。
愁醉非因酒，悲吟不是歌。
求师治此病，唯劝读楞伽。','',''),('quantangshi-22837','北楼送客归上都','白居易','quantangshi','','卷23','凭高眺远一凄凄，却下朱阑即解携。
京路人归天直北，江楼客散日平西。
长津欲度回渡尾，残酒重倾簇马蹄。
不独别君须强饮，穷愁自要醉如泥。','',''),('quantangshi-22838','北亭招客','白居易','quantangshi','','卷23','疎散郡丞同野客，幽闲官舍抵山家。
春风北户千茎竹，晚日东园一树花。
小盏吹醅尝冷酒，深炉敲火炙新茶。
能来近日观棊否，太守知慵放晚衙。','',''),('quantangshi-22839','宿西林寺早赴东林满上人之会因寄崔二十二员外','白居易','quantangshi','','卷23','谪辞魏阙鵷鸾隔，老入庐山麋鹿随。
薄暮萧条投寺宿，凌晨清净与僧期。
双林我起闻钟后，只日君趋入阁时。
鹏鷃高低分皆定，莫劳心力远相思。','',''),('quantangshi-22840','游宝称寺','白居易','quantangshi','','卷23','竹寺初晴日，花塘欲晓春。
野猨疑弄客，山鸟似呼人。
酒嫩倾金液，茶新碾玉尘。
可怜幽静地，堪寄老慵身。','',''),('quantangshi-22841','早春闻提壶鸟因题邻家','白居易','quantangshi','','卷23','厌听秋猨催下泪，喜闻春鸟劝提壶。
谁家红树先花发，何处青楼有酒酤。
进士麄豪寻静尽，拾遗风采近都无。
欲期明日东邻醉，变作腾腾一俗夫。','',''),('quantangshi-22842','见紫薇花忆微之','白居易','quantangshi','','卷23','一丛暗澹将何比，浅碧笼帬衬紫巾。
除却微之见应爱，人间少有别花人。','',''),('quantangshi-22843','蔷薇花一丛独死不知其故因有是篇','白居易','quantangshi','','卷23','柯条未尝损，根蕟不曾移。
同类今齐茂，孤芳忽独萎。
仍怜委地日，正是带花时。
碎碧初凋叶，燋红尚恋枝。
干坤无厚薄，草木自荣衰。
欲问因何事，春风亦不知。','',''),('quantangshi-22844','湖亭望水','白居易','quantangshi','','卷23','久雨南湖涨，新晴北客过。
日沈红有影，风定绿无波。
岸没闾阎少，滩平船舫多。
可怜心赏处，其奈独游何。','',''),('quantangshi-22845','闲游','白居易','quantangshi','','卷23','外事因慵废，中怀与静期。
寻泉上山远，看笋出林迟。
白石磨樵斧，青竿理钓丝。
澄清深浅好，最爱夕阳时。','',''),('quantangshi-22846','忆微之伤仲远','白居易','quantangshi','','卷23','幽独辞羣久，漂流去国赊。
只将琴作伴，唯以酒为家。
感逝因看水，伤离为见花。
李三埋地底，元九谪天涯。
举眼青云远，回头白日斜。
可能胜贾谊，犹自滞长沙。','',''),('quantangshi-22847','过郑处士','白居易','quantangshi','','卷23','闻道移居村坞间，竹林多处独开关。
故来不是求他事，暂借南亭一望山。','',''),('quantangshi-22848','霖雨苦多江湖暴涨块然独望因题北亭','白居易','quantangshi','','卷23','自作浔阳客，无如苦雨何。
阴昏晴日少，闲闷睡时多。
湖阔将天合，云低与水和。
篱根舟子语，巷口钓人歌。
雾岛沈黄气，风帆蹙白波。
门前车马道，一宿变江河。','',''),('quantangshi-22849','春末夏初闲游江郭二首 一','白居易','quantangshi','','卷23','闲出乘轻屐，徐行蹋輭沙。
观鱼傍湓浦，看竹入杨家。
林迸穿篱笋，藤飘落水花。
雨埋钓舟小，风扬酒旗斜。
嫩剥青菱角，浓煎白茗芽。
淹留不知夕，城树欲栖鸦。','',''),('quantangshi-22850','春末夏初闲游江郭二首 二','白居易','quantangshi','','卷23','柳影繁初合，莺声涩渐稀。
早梅迎夏结，残絮送春飞。
西日韶光尽，南风暑气微。
展张新小簟，熨帖旧生衣。
绿蚁杯香嫩，红丝脍缕肥。
故园无此味，何必苦思归。','',''),('quantangshi-22851','红藤杖','白居易','quantangshi','','卷23','南诏红藤杖，西江白首人。
时时携步月，处处把寻春。
劲健孤茎直，疎圆六节匀。
火山生处远，泸水洗来新。
粗细才盈手，高低仅过身。
天边望乡客，何日拄归秦。','',''),('quantangshi-22852','风雨中寻李十一因题船上','白居易','quantangshi','','卷23','匹马来郊外，扁舟在水滨。
可怜冲雨客，来访阻风人。
小榼酤清醑，行厨煮白鳞。
停杯看柳色，各忆故园春。','',''),('quantangshi-22853','题庐山山下汤泉','白居易','quantangshi','','卷23','一眼汤泉流向东，浸泥浇草暖无功。
骊山温水因何事，流入金铺玉甃中。','',''),('quantangshi-22854','寄蕲州簟与元九因题六韵','白居易','quantangshi','','卷23','笛竹出蕲春，霜刀劈翠筠。
织成双锁簟，寄与独眠人。
卷作筒中信，舒为席上珍。
滑如铺薤叶，冷似卧龙鳞。
清润宜乘露，鲜华不受尘。
通州炎瘴地，此物最关身。','',''),('quantangshi-22855','秋热','白居易','quantangshi','','卷23','西江风候接南威，暑气常多秋气微。
犹道江州最凉冷，至今九月着生衣。','',''),('quantangshi-22856','题元八溪居','白居易','quantangshi','','卷23','溪岚漠漠树重重，水槛山窗次第逢。
晚叶尚开红踯躅，秋芳初结白芙蓉。
声来枕上千年鹤，影落杯中五老峰。
更愧殷勤留客意，鱼鲜饭细酒香浓。','',''),('quantangshi-22857','晚出西郊','白居易','quantangshi','','卷23','散吏闲如客，贫州冷似村。
早凉湖北岸，残照郭西门。
嬾镊从须白，休治任眼昏。
老来何所用，少兴不多言。','',''),('quantangshi-22858','阶下莲','白居易','quantangshi','','卷23','叶展影飜当砌月，花开香散入帘风。
不如种在天池上，犹胜生于野水中。','',''),('quantangshi-22859','端居咏怀','白居易','quantangshi','','卷23','贾生俟罪心相似，张翰思归事不如。
斜日早知惊鵩鸟，秋风悔不忆鲈鱼。
胷襟曾贮匡时策，怀袖犹残谏猎书。
从此万缘都摆落，欲携妻子买山居。','',''),('quantangshi-22860','夜宿江浦闻元八改官因寄此什','白居易','quantangshi','','卷23','君游丹陛已三迁，我泛沧浪欲二年。
劒佩晓趋双凤阙，烟波夜宿一渔船。
交亲尽在青云上，乡国遥抛白日边。
若报生涯应笑杀，结茅栽芋种畲田。','',''),('quantangshi-22861','百花亭','白居易','quantangshi','','卷23','朱槛在空虚，凉风八月初。
山形如岘首，江色似桐庐。
佛寺乘船入，人家枕水居。
高亭仍有月，今夜宿何如。','',''),('quantangshi-22862','江楼早秋','白居易','quantangshi','','卷23','南国虽多热，秋来亦不迟。
湖光朝霁后，竹气晚凉时。
楼阁宜佳客，江山入好诗。
清风水苹叶，白露木兰枝。
欲作云泉计，须营伏腊资。
匡庐一步地，官满更何之。','',''),('quantangshi-22863','送客之湖南','白居易','quantangshi','','卷23','年年渐见南方物，事事堪伤北客情。
山鬼趫跳唯一足，峡猿哀怨过三声。
帆开青草湖中去，衣湿黄梅雨里行。
别后双鱼难定寄，近来潮不到湓城。','',''),('quantangshi-22864','百花亭晚望夜归','白居易','quantangshi','','卷23','百花亭上晚裴回，云影阴晴掩复开。
日色悠扬暎山尽，雨声萧飒渡江来。
鬓毛遇病双如雪，心绪逢秋一似灰。
向夜欲归愁未了，满湖明月小船回。','',''),('quantangshi-22865','西楼','白居易','quantangshi','','卷23','小郡大江边，危楼夕照前。
青芜卑湿地，白露泬寥天。
乡国此时阻，家书何处传？
仍闻陈蔡戍，转战已三年。','',''),('quantangshi-22866','寻李道士山居兼呈元明府','白居易','quantangshi','','卷23','尽日行还歇，迟迟独上山。
攀藤老筋力，照水病容颜。
陶巷招居住，茅家许往还。
饱谙荣辱事，无意恋人间。','',''),('quantangshi-22867','四十五','白居易','quantangshi','','卷23','行年四十五，两鬓半苍苍。
清瘦诗成癖，粗豪酒放狂。
老来尤委命，安处即为乡。
或拟庐山下，来春结草堂。','',''),('quantangshi-22868','寄李相公崔侍郎钱舍人','白居易','quantangshi','','卷23','曾陪鹤驭两三仙，亲侍龙舆四五年。
天上欢华春有限，世间漂泊海无边。
荣枯事过都成梦，忧喜心忘便是禅。
官满更归何处去，香炉峰在宅门前。','',''),('quantangshi-22869','厅前桂','白居易','quantangshi','','卷23','天台岭上凌霜树，司马厅前委地丛。
一种不生明月里，山中犹校胜尘中。','',''),('quantangshi-22870','寻王道士药堂因有题赠','白居易','quantangshi','','卷23','行行觅路缘松峤，步步寻花到杏坛。
白石先生小有洞，黄芽姹女大还丹。
常悲东郭千家冢，欲乞西山五色丸。
但恐长生须有籍，仙台试为检名看。','',''),('quantangshi-22871','秋晚','白居易','quantangshi','','卷23','篱菊花稀砌桐落，树阴离离日色薄。
单幕疎帘贫寂莫，凉风冷露秋萧索。
光阴流转忽已晚，颜色凋残不如昨。
莱妻卧病月明时，不捣寒衣空捣药。','',''),('quantangshi-22872','南浦岁暮对酒送王十五归京','白居易','quantangshi','','卷23','腊后冰生覆湓水，夜来云暗失庐山。
风飘细雪落如米，索索萧萧芦苇间。
此地二年留我住，今朝一酌送君还。
相看渐老无过醉，聚散穷通总是闲。','',''),('quantangshi-22873','除夜','白居易','quantangshi','','卷23','薄晚支颐坐，中宵枕臂眠。
一从身去国，再见日周天。
老度江南岁，春抛渭北田。
浔阳来早晚，明日是三年。','',''),('quantangshi-22874','闻李十一出牧澧州崔二十二出牧果州因寄绝句','白居易','quantangshi','','卷23','平生相见即眉开，静念无如李与崔。
各是天涯为刺史，缘何不觅九江来。','',''),('quantangshi-22875','元和十三年淮寇未平诏停岁仗愤然有感率尔成章','白居易','quantangshi','','卷23','闻停岁仗轸皇情，应为淮西寇未平。
不分气从歌里发，无明心向酒中生。
愚计忽思飞短檄，狂心便欲请长缨。
从来妄动多如此，自笑何曾得事成。','',''),('quantangshi-22876','庾楼新岁','白居易','quantangshi','','卷23','岁时销旅貌，风景触乡愁。
牢落江湖意，新年上庾楼。','',''),('quantangshi-22877','上香炉峰','白居易','quantangshi','','卷23','倚石攀箩歇病身，青筇竹仗白纱巾。
他时画出庐山障，便是香炉峰上人。','',''),('quantangshi-22878','忆微之','白居易','quantangshi','','卷23','与君何日出屯蒙，鱼恋江湖鸟厌笼。
分手各抛沧海畔，折腰俱老绿衫中。
三年隔阔音尘断，两地飘零气味同。
又被新年劝相忆，柳条黄輭欲春风。','',''),('quantangshi-22879','雨夜赠元十八','白居易','quantangshi','','卷23','卑湿沙头宅，连阴雨夜天。
共听檐溜滴，心事两悠然。
把酒循环饮，移牀曲尺眠。
莫言非故旧，相识已三年。','',''),('quantangshi-22880','寒食江畔','白居易','quantangshi','','卷23','草香沙暖水云晴，风景令人忆帝京。
还似往年春气味，不宜今日病心情。
闻莺树下沈吟立，信马江头取次行。
忽见紫桐花怅望，下邽明日是清明。','',''),('quantangshi-22881','三月三日登庾楼寄庾三十二','白居易','quantangshi','','卷23','三日欢游辞曲水，二年愁卧在长沙。
每登高处长相忆，何况兹楼属庾家。','',''),('quantangshi-22882','闻李六景俭自河东令授唐邓行军司马以诗贺之','白居易','quantangshi','','卷23','谁能淮上静风波，闻道河东应此科。
不独文词供奏记，定将谈笑解兵戈。
泥埋劒戟终难久，水借蛟龙可在多。
四十着绯军司马，男儿官职未蹉跎。','',''),('quantangshi-22883','石榴树','白居易','quantangshi','','卷23','可怜颜色好阴凉，叶翦红牋花扑霜。
繖盖低垂金翡翠，熏笼乱搭绣衣裳。
春芽细炷千灯焰，夏蘂浓焚百[和]香。
见说上林无此树，只教桃柳占年芳。','',''),('quantangshi-22884','大林寺桃花','白居易','quantangshi','','卷23','人间四月芳菲尽，山寺桃花始盛开。
长恨春归无觅处，不知转入此中来。','',''),('quantangshi-22885','咏怀','白居易','quantangshi','','卷23','自从委顺任浮沈，渐觉年多功用深。
面上减除忧喜色，胷中消尽是非心。
妻儿不问唯耽酒，冠盖皆慵只抱琴。
长笑灵均不知命，江蓠丛畔苦悲吟。','',''),('quantangshi-22886','早发楚城驿','白居易','quantangshi','','卷23','雨过尘埃灭，沿江道径平。
月乘残夜出，人趁早凉行。
寂历闲吟动，冥蒙暗思生。
荷塘飜露气，稻垄泻泉声。
宿犬闻铃起，栖禽见火惊。
昽昽烟树色，十里始天明。','',''),('quantangshi-22887','箬岘东池','白居易','quantangshi','','卷23','箬岘亭东有小池，早荷新荇绿参差。
中宵把火行人发，惊起双栖白鹭鸶。','',''),('quantangshi-22888','建昌江','白居易','quantangshi','','卷23','建昌江水县门前，立马教人唤渡船。
忽似往年归蔡渡，草风沙雨渭河边。','',''),('quantangshi-22889','哭从弟','白居易','quantangshi','','卷23','伤心一尉便终身，叔母年高新妇贫。
一片绿衫消不得，腰金拖紫是何人。','',''),('quantangshi-22890','香炉峰下新卜山居草堂初成偶题东壁','白居易','quantangshi','','卷23','五架三间新草堂，石阶桂柱竹编墙。
南檐纳日冬天暖，北户迎风夏月凉。
洒砌飞泉才有点，拂窗斜竹不成行。
来春更葺东厢屋，纸阁芦帘着孟光。','',''),('quantangshi-22891','重题 一','白居易','quantangshi','','卷23','喜入山林初息影，厌趋朝市久劳生。
早年薄有烟霞志，岁晚深谙世俗情。
已许虎溪云里卧，不争龙尾道前行。
从兹耳界应清净，免见啾啾毁誉声。','',''),('quantangshi-22892','重题 二','白居易','quantangshi','','卷23','长松树下小溪头，班鹿胎巾白布裘。
药圃茶园为产业，野麋林鹤是交游。
云生涧户衣裳润，岚隐山厨火烛幽。
最爱一泉新引得，清泠屈曲绕阶流。','',''),('quantangshi-22893','重题 三','白居易','quantangshi','','卷23','日高睡足犹慵起，小阁重衾不怕寒。
遗爱寺钟欹枕听，香炉峰雪拨帘看。
匡庐便是逃名地，司马仍为送老官。
心泰身宁是归处，故乡何独在长安。','',''),('quantangshi-22894','重题 四','白居易','quantangshi','','卷23','宦途自此心长别，世事从今口不言。
岂止形骸同土木，兼将寿夭任干坤。
胷中壮气犹须遣，身外浮荣何足论。
还有一条遗恨事，高家门馆未酬恩。','',''),('quantangshi-22895','山中问月','白居易','quantangshi','','卷23','为问长安月，谁教不相离。
昔随飞盖处，今照入山时。
借助秋怀旷，留连夜卧迟。
如归旧乡国，似对好亲知。
松下行为伴，溪头坐有期。
千岩将万壑，无处不相随。','',''),('quantangshi-22896','正月十五日夜东林寺学禅偶怀蓝田杨主簿因呈智禅师','白居易','quantangshi','','卷23','新年三五东林夕，星汉迢迢钟梵迟。
花县当君行乐夜，松房是我坐禅时。
忽看月满还相忆，始叹春来自不知。
不觉定中微念起，明朝更问雁门师。','',''),('quantangshi-22897','临水坐','白居易','quantangshi','','卷23','昔为东掖垣中客，今作西方社内人。
手把杨枝临水坐，闲思往事似前身。','',''),('quantangshi-22898','山居','白居易','quantangshi','','卷23','山斋方独往，尘事莫相仍。
蓝轝辞鞍马，缁徒换友朋。
朝餐唯药菜，夜伴只纱灯。
除却青衫在，其余便是僧。','',''),('quantangshi-22899','遗爱寺','白居易','quantangshi','','卷23','弄日临溪坐，寻花绕寺行。
时时闻鸟语，处处是泉声。','',''),('quantangshi-22900','山中与元九书因题书后','白居易','quantangshi','','卷23','忆昔封书与君夜，金銮殿后欲明天。
今夜封书在何处，庐山庵里晚灯前。
笼鸟槛猿俱未死，人间相见是何年。','',''),('quantangshi-22901','黄石岩下作','白居易','quantangshi','','卷23','久别鵷鸾侣，深随鸟兽羣。
教他远亲故，何处觅知闻？
昔日青云意，今移向白云。','',''),('quantangshi-22902','戏赠李十三判官','白居易','quantangshi','','卷23','垂鞭相送醉醺醺，遥见庐山指似君。
想君初觉从军乐，未爱香炉峰上云。','',''),('quantangshi-22903','醉中戏赠郑使君','白居易','quantangshi','','卷23','密座移红毯，酡颜照渌杯。
双娥留且住，五马任先回。
醉耳歌催醒，愁眉笑引开。
平生少年兴，临老暂重来。','',''),('quantangshi-22904','江亭夕望','白居易','quantangshi','','卷23','凭高望远思悠哉，晚上江亭夜未回。
日欲没时红浪沸，月初生处白烟开。
辞枝雪蘂将春去，满镊霜毛送老来。
争敢三年作归计，心知不及贾生才。','',''),('quantangshi-22905','酬元员外三月三十日慈恩寺相忆见寄','白居易','quantangshi','','卷23','怅望慈恩三月尽，紫桐花落鸟关关。
诚知曲水春相忆，其奈长沙老未还。
赤岭猨声催白首，黄茅瘴色换朱颜。
谁言南国无霜雪，尽在愁人鬓发间。','',''),('quantangshi-22906','偶然二首 一','白居易','quantangshi','','卷23','楚怀邪乱灵均直，放弃合宜何恻恻。
汉文明圣贾生贤，谪向长沙堪叹息。
人事多端何足怪，天文至信犹差忒。
月离于毕合滂沱，有时不雨何能测。','',''),('quantangshi-22907','偶然二首 二','白居易','quantangshi','','卷23','火发城头鱼水里，救火竭池鱼失水。
乖龙藏在牛[领]中，雷击龙来牛枉死。
人道蓍神龟骨灵，试卜鱼牛那至此。
六十四卦七十钻，毕竟不能知所以。','',''),('quantangshi-22908','中秋月','白居易','quantangshi','','卷23','万里清光不可思，添愁益恨绕天涯。
谁人陇外久征戍，何处庭前新别离？
失宠故姬归院夜，没蕃老将上楼时。
照他几许人肠断，玉兔银蟾远不知。','',''),('quantangshi-22909','谢李六郎中寄新蜀茶','白居易','quantangshi','','卷23','故情周匝向交亲，新茗分张及病身。
红纸一封书后信，绿芽十片火前春。
汤添勺水煎鱼眼，末下刀圭搅麴尘。
不寄他人先寄我，应缘我是别茶人。','',''),('quantangshi-22910','携诸山客同上香炉峰遇雨而还霑濡狼籍互相笑谑题此解嘲','白居易','quantangshi','','卷23','萧洒登山去，龙钟遇雨回。
磴危攀薜荔，石滑践莓苔。
韤污君相谑，鞵穿我自咍。
莫欺泥土脚，曾蹋玉阶来。','',''),('quantangshi-22911','彭蠡湖晚归','白居易','quantangshi','','卷23','彭蠡湖天晚，桃花水气春。
鸟飞千白点，日没半红轮。
何必为迁客，无劳是病身。
但来临此望，少有不愁人。','',''),('quantangshi-22912','酬赠李炼师见招','白居易','quantangshi','','卷23','几年司谏直承明，今日求真礼上清。
曾犯龙鳞容不死，欲骑鹤背觅长生。
刘纲有妇仙同得，伯道无儿累更轻。
若许移家相近住，便驱鸡犬上层城。','',''),('quantangshi-22913','西河雨夜送客','白居易','quantangshi','','卷23','云黑雨翛翛，江昏水暗流。
有风催解缆，无月伴登楼。
酒罢无多兴，帆开不少留。
唯看一点火，遥认是行舟。','',''),('quantangshi-22914','登西楼忆行简','白居易','quantangshi','','卷23','每因楼上西南望，始觉人间道路长。
碍日暮山青蔟蔟，漫天秋水白茫茫。
风波不见三年面，书信难传万里肠。
早晚东归来下峡，稳乘船舫过瞿唐。','',''),('quantangshi-22915','罗子','白居易','quantangshi','','卷23','有女名罗子，生来才两春。
我今年已长，日夜二毛新。
顾念娇啼面，思量老病身。
直应头似雪，始得见成人。','',''),('quantangshi-22916','读僧灵彻诗','白居易','quantangshi','','卷23','东林寺里西廊下，石片镌题数首诗。
言句怪来还校别，看名知是老汤师。','',''),('quantangshi-22917','听李士良琵琶','白居易','quantangshi','','卷23','声似胡儿弹舌语，愁如塞月恨边云。
闲人暂听犹眉敛，可使和蕃公主闻。','',''),('quantangshi-22918','昭君怨','白居易','quantangshi','','卷23','明妃风貌最娉婷，合在椒房应四星。
只得当年备宫掖，何曾专夜奉帏屏。
见疎从道迷图画，知屈那教配虏庭。
自是君恩薄如纸，不须一向恨丹青。','',''),('quantangshi-22919','闲吟','白居易','quantangshi','','卷23','自从苦学空门法，销尽平生种种心。
唯有诗魔降未得，每逢风月一闲吟。','',''),('quantangshi-22920','戏问山石榴','白居易','quantangshi','','卷23','小树山榴近砌栽，半含红萼带花来。
争知司马夫人妬，移到庭前便不开。','',''),('quantangshi-22921','编集拙诗成一十五卷因题卷末戏赠元九李二十','白居易','quantangshi','','卷23','一篇长恨有风情，十首秦吟近正声。
每被老元偷格律，苦教短李伏歌行。
世间富贵应无分，身后文章合有名。
莫怪气粗言语大，新排十五卷诗成。','',''),('quantangshi-22922','湖上闲望','白居易','quantangshi','','卷23','藤花浪拂紫茸条，菰叶风飜绿剪刀。
闲弄水芳生楚思，时时合眼咏离骚。','',''),('quantangshi-22923','江南谪居十韵','白居易','quantangshi','','卷23','自哂沈冥客，曾为献纳臣。
壮心徒许国，薄命不如人。
才展凌云翅，俄成失水鳞。
葵枯犹向日，蓬断即辞春。
泽畔长愁地，天边欲老身。
萧条残活计，冷落旧交亲。
草合门无径，烟消甑有尘。
忧方知酒圣，贫始觉钱神。
虎尾难容足，羊肠易覆轮。
行藏与通塞，一切任陶钧。','',''),('quantangshi-22924','江楼夜吟元九律诗成三十韵','白居易','quantangshi','','卷23','昨夜江楼上，吟君数十篇。
词飘朱槛底，韵堕渌江前。
清楚音谐律，精微思入玄。
收将白雪丽，夺尽碧云妍。
寸截金为句，双雕玉作联。
八风凄间发，五彩烂相宣。
冰扣声声冷，珠排字字圆。
文头交比绣，筋骨软于绵。
澒涌同波浪，铮鏦过管弦。
醴泉流出地，钧乐下从天。
神鬼闻如泣，鱼龙听似禅。
星回疑聚集，月落为留连。
雁感无鸣者，猨愁亦悄然。
交流迁客泪，停住贾人船。
暗被歌姬乞，潜闻思妇传。
斜行题粉壁，短卷写红笺。
肉味经时忘，头风当日痊。
老张知定伏，短李爱应颠。
道屈才方振，身闲业始专。
天教声烜赫，理合命迍邅。
顾我文章劣，知他气力全。
工夫虽共到，巧拙尚相悬。
各有诗千首，俱抛海一边。
白头吟处变，青眼望中穿。
酬答朝妨食，披寻夜废眠。
老偿文债负，宿结字因缘。
每叹陈夫子，常嗟李谪仙。
名高折人爵，思苦减天年。
不得当时遇，空令后代怜。
相悲今若此，湓浦与通川。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-22925','浔阳岁晚寄元八郎中庾三十二员外','白居易','quantangshi','','卷23','阅水年将暮，烧金道未成。
丹砂不肯死，白发自须生。
病肺慙杯满，衰颜忌镜明。
春深旧乡梦，岁晚故交情。
一别浮云散，双瞻列宿荣。
螭头阶下立，龙尾道前行。
封事频闻奏，除书数见名。
虚怀事僚友，平步取公卿。
漏尽鸡人报，朝回幼女迎。
可怜白司马，老大在湓城。','',''),('quantangshi-22926','元九以绿丝布白轻褣见寄制成衣服以诗报知','白居易','quantangshi','','卷23','绿丝文布素轻褣，珍重京华手自封。
贫友远劳君寄附，病妻亲为我裁缝。
袴花白似秋云薄，衫色青于春草浓。
欲着却休知不称，折腰无复旧形容。','',''),('quantangshi-22927','清明日送韦侍御贬虔州','白居易','quantangshi','','卷23','寂寞清明日，萧条司马家。
留饧和冷粥，出火煮新茶。
欲别能无酒，相留亦有花。
南迁更何处，此地已天涯。','',''),('quantangshi-22928','九江春望','白居易','quantangshi','','卷23','淼茫积水非吾土，飘泊浮萍自我身。
身外信缘为活计，眼前随事觅交亲。
炉烟岂异终南色，湓草宁殊渭北春。
此地何妨便终老，譬如元是九江人。','',''),('quantangshi-22929','晚题东林寺双池','白居易','quantangshi','','卷23','向晚双池好，初晴百物新。
褭枝翻翠羽，溅水跃红鳞。
萍泛同游子，莲开当丽人。
临流一惆怅，还忆曲江春。','',''),('quantangshi-22930','赠内子','白居易','quantangshi','','卷23','白发长兴叹，青娥亦伴愁。
寒衣补灯下，小女戏牀头。
暗澹屏帏故，凄凉枕席秋。
贫中有等级，犹胜嫁黔娄。','',''),('quantangshi-22931','送客春游岭南二十韵','白居易','quantangshi','','卷23','已讶游何远，仍嗟别太频。
离容君蹙促，赠语我殷勤。
迢遰天南面，苍茫海北漘。
诃陵国分界，交趾郡为邻。
蓊郁三光晦，温暾四气匀。
阴晴变寒暑，昏晓错星辰。
瘴地难为老，蛮陬不易驯。
土民稀白首，洞主尽黄巾。
战舰犹惊浪，戎车未息尘。
红旗围卉服，紫绶裹文身。
麪苦桄榔裛，浆酸橄榄新。
牙樯迎海舶，铜鼓赛江神。
不冻贪泉暖，无霜毒草春。
云烟蟒蛇气，刀劒鰐鱼鳞。
路足羁栖客，官多谪逐臣。
天黄生飓母，雨黑长枫人。
回使先传语，征轩早返轮。
须防杯里蛊，莫爱橐中珍。
北与南殊俗，身将货孰亲。
尝闻君子诫，忧道不忧贫。','',''),('quantangshi-22932','自题','白居易','quantangshi','','卷23','功名宿昔人多许，宠辱斯须自不如。
一旦失恩先左降，三年随例未量移。
马头觅角生何日，石火敲光住几时。
前事是身俱若此，空门不去欲何之。','',''),('quantangshi-22933','自悲','白居易','quantangshi','','卷23','火宅煎熬地，霜松摧折身。
因知羣动内，易死不过人。','',''),('quantangshi-22934','寻郭道士不遇','白居易','quantangshi','','卷23','郡中乞假来相访，洞里朝元去不逢。
看院祗留双白鹤，入门惟见一青松。
药炉有火丹应伏，云碓无人水自舂。
欲问参同契中事，更期何日得从容。','',''),('quantangshi-22935','浔阳春三首 春生','白居易','quantangshi','','卷23','春生何处暗周游，海角天涯徧始休。
先遣和风报消息，续教啼鸟说来由。
展张草色长河畔，点缀花房小树头。
若到故园应觅我，为传沦落在江州。','',''),('quantangshi-22936','浔阳春三首 春来','白居易','quantangshi','','卷23','春来触地故乡情，忽见风光忆两京。
金谷蹋花香骑入，曲江碾草钿车行。
谁家绿酒欢连夜，何处红楼睡失明。
独有不眠不醉客，经春冷坐古湓城。','',''),('quantangshi-22937','浔阳春三首 春去','白居易','quantangshi','','卷23','一从泽畔为迁客，两度江头送暮春。
白发更添今日鬓，青衫不改去年身。
百川未有回流水，一老终无却少人。
四十六时三月尽，送春争得不殷勤。','',''),('quantangshi-22938','梦微之','白居易','quantangshi','','卷23','晨起临风一惆怅，通川湓水断相闻。
不知忆我因何事，昨夜三回梦见君。','',''),('quantangshi-22939','赠韦炼师','白居易','quantangshi','','卷23','浔阳迁客为居士，身似浮云心似灰。
上界女仙无嗜欲，何因相顾两裴回。
共疑过去人间世，曾作谁家夫妇来。','',''),('quantangshi-22940','问刘十九','白居易','quantangshi','','卷23','绿螘新醅酒，红泥小火垆。
晚来天欲雪，能饮一杯无。','',''),('quantangshi-22941','得行简书闻欲下峡先以诗寄','白居易','quantangshi','','卷23','朝来又得东川信，欲取春初发梓州。
书报九江闻暂喜，路经三峡想还愁。
潇湘瘴雾加餐饭，滟滪惊波稳泊舟。
欲寄两行迎尔泪，长江不肯向西流。','',''),('quantangshi-22942','南湖早春','白居易','quantangshi','','卷23','风回云断雨初晴，返照湖边暖复明。
乱点碎红山杏发，平铺新绿水苹生。
翅低白雁飞仍重，舌涩黄鹂语未成。
不道江南春不好，年年衰病减心情。','',''),('quantangshi-22943','元十八从事南海欲出庐山临别旧居有恋泉声之什因以投和兼伸别情','白居易','quantangshi','','卷23','贤侯辟士礼从容，莫恋泉声问所从。
雨露初承黄纸诏，烟霞欲别紫霄峰。
伤弓未息新惊鸟，得水难留久卧龙。
我正退藏君变化，一杯可易得相逢。','',''),('quantangshi-22944','题韦家泉池','白居易','quantangshi','','卷23','泉落青山出白云，萦村绕郭几家分。
自从引作池中水，深浅方圆一任君。','',''),('quantangshi-22945','醉中对红叶','白居易','quantangshi','','卷23','临风杪秋树，对酒长年人。
醉貌如霜叶，虽红不是春。','',''),('quantangshi-22946','遣怀','白居易','quantangshi','','卷23','羲和走驭趂年光，不许人间日月长。
遂使四时都似电，争教两鬓不成霜。
荣销枯去无非命，壮尽衰来亦是常。
已共身心要约定，穷通生死不惊忙。','',''),('quantangshi-22947','点额鱼','白居易','quantangshi','','卷23','龙门点额意何如，红尾青鬐却返初。
见说在天行雨苦，为龙未必胜为鱼。','',''),('quantangshi-22948','闻龟儿咏诗','白居易','quantangshi','','卷23','怜渠已解咏诗章，摇膝支颐学二郎。
莫学二郎吟太苦，才年四十鬓如霜。','',''),('quantangshi-22949','对酒','白居易','quantangshi','','卷23','未济卦中休卜命，参同契里莫劳心。
无如饮此销愁物，一饷愁消直万金。','',''),('quantangshi-22950','东墙夜合树去秋为风雨所摧今年花时怅然有感','白居易','quantangshi','','卷23','碧荑红缕今何在，风雨飘将去不回。
惆怅去年墙下地，今春唯有荠花开。','',''),('quantangshi-22951','病起','白居易','quantangshi','','卷23','病不出门无限时，今朝强出与谁期。
经年不上江楼醉，劳动春风扬酒旗。','',''),('quantangshi-22952','梦亡友刘太白同游彰敬寺','白居易','quantangshi','','卷23','三千里外卧江州，十五年前哭老刘。
昨夜梦中彰敬寺，死生魂魄暂同游。','',''),('quantangshi-22953','与果上人殁时题此诀别兼简二林僧社','白居易','quantangshi','','卷23','本结菩提香火社，为嫌烦恼电泡身。
不须惆怅从师去，先请西方作主人。','',''),('quantangshi-22954','赠写真者','白居易','quantangshi','','卷23','子骋丹青日，予当丑老时。
无劳役神思，更画病容仪。
迢递麒麟阁，图功未有期。
区区尺素上，焉用写真为。','',''),('quantangshi-22955','刘十九同宿','白居易','quantangshi','','卷23','红旗破贼非吾事，黄纸除书无我名。
唯共嵩阳刘处士，围棊赌酒到天明。','',''),('quantangshi-22956','十二年冬江西温暖喜元八寄金石棱到因题此诗','白居易','quantangshi','','卷23','今冬腊候不严凝，暖雾温风气上腾。
山脚崦中才有雪，江流慢处亦无冰。
欲将何药防春瘴，只有元家金石棱。','',''),('quantangshi-22957','闲意','白居易','quantangshi','','卷23','不争荣耀任沈沦，日与时疎共道亲。
北省朋僚音信断，东林长老往还频。
病停夜食闲如社，慵拥朝裘暖似春。
渐老溅谙闲气味，终身不拟作忙人。','',''),('quantangshi-22958','送友人上峡赴东川辟命','白居易','quantangshi','','卷23','见说瞿塘峡，斜衔滟滪根。
难于寻鸟路，险过上龙门。
羊角风头急，桃花水色浑。
山回若鳌转，舟入似鲸吞。
岸合愁天断，波跳恐地翻。
怜君经此去，为感主人恩。','',''),('quantangshi-22959','夜送孟司功','白居易','quantangshi','','卷23','浔阳白司马，夜送孟功曹。
江暗管弦急，楼明灯火高。
湖波翻似箭，霜草杀如刀。
且莫开征棹，阴风正怒号。','',''),('quantangshi-22960','衰病','白居易','quantangshi','','卷23','老辞游冶寻花伴，病别荒狂旧酒徒。
更恐五年三岁后，些些谭笑亦应无。','',''),('quantangshi-22961','题诗屏风绝句','白居易','quantangshi','','卷23','相忆采君诗作障，自书自勘不辞劳。
障成定被人争写，从此南中纸价高。','',''),('quantangshi-22962','答微之','白居易','quantangshi','','卷23','君写我诗盈寺壁，我题君句满屏风。
与君相遇知何处，两叶浮萍大海中。','',''),('quantangshi-22963','偶宴有怀','白居易','quantangshi','','卷23','遇兴寻文客，因欢命酒徒。
春游忆亲故，夜会似京都。
诗思闲仍在，乡愁醉暂无。
狂来欲起舞，慙见白髭须。','',''),('quantangshi-22964','山中酬江州崔使君见寄','白居易','quantangshi','','卷23','眷眄情无恨，优容礼有余。
三年为郡吏，一半许山居。
酒熟心相待，诗来手自书。
庾楼春好醉，明月且回车。','',''),('quantangshi-22965','山枇杷','白居易','quantangshi','','卷23','深山老去惜年华，况对东溪野枇杷。
火树风来翻绛焰，琼枝日出晒红纱。
回看桃李都无色，映得芙蓉不是花。
争奈结根深石底，无因移得到人家。','',''),('quantangshi-22966','闻李尚书拜相因以长句寄贺微之','白居易','quantangshi','','卷23','怜君不久在通川，知已新提造化权。
夔卨定求才济世，张雷应辨气冲天。
那知沦落天涯日，正是陶钧海内年。
肯向泥中抛折劒，不收重铸作龙泉。','',''),('quantangshi-22967','岁暮','白居易','quantangshi','','卷23','穷阴急景坐相催，壮齿韶颜去不回。
旧病重因年老发，新愁多是夜长来。
膏明自爇缘多事，雁默先烹为不才。
祸福细寻无会处，不如且进手中杯。','',''),('quantangshi-22968','雨中赴刘十九二林之期及到寺刘已先去因以四韵寄之','白居易','quantangshi','','卷23','云中台殿泥中路，既阻同游嬾却还。
将谓独愁犹对雨，不知多兴已寻山。
才应行到千峰里，只校来迟半日间。
最惜杜鹃花烂熳，春风吹尽不同攀。','',''),('quantangshi-22969','蔷薇正开春酒初熟因招刘十九张大夫崔二十四同饮','白居易','quantangshi','','卷23','瓮头竹叶经春熟，阶底蔷薇入夏开。
似火浅深红压架，如饧气味绿黏台。
试将诗句相招去，倘有风情或可来。
明日早花应更好，心期同醉卯时杯。','',''),('quantangshi-22970','李白墓','白居易','quantangshi','','卷23','采石江边李白坟，遶田无限草连云。
可怜荒壠穷泉骨，曾有惊天动地文。
但是诗人多薄命，就中沦落不过君。','',''),('quantangshi-22971','对酒','白居易','quantangshi','','卷23','漫把参同契，难烧伏火砂。
有时成白首，无处问黄芽。
幻世如泡影，浮生抵眼花。
唯将绿醅酒，且替紫河车。','',''),('quantangshi-22972','戏答诸少年','白居易','quantangshi','','卷23','顾我长年头似雪，饶君壮岁气如云。
朱颜今日虽欺我，白发他时不放君。','',''),('quantangshi-22973','风雨晚泊','白居易','quantangshi','','卷23','苦竹林边芦苇丛，停舟一望思无穷。
青苔扑地连春雨，白浪掀天尽日风。
忽忽百年行欲半，茫茫万事坐成空。
此生飘荡何时定，一缕鸿毛天地中。','',''),('quantangshi-22974','题崔使君新楼','白居易','quantangshi','','卷23','忧人何处可消忧，碧瓮红栏湓水头。
从此浔阳风月夜，崔公楼替庾公楼。','',''),('quantangshi-22975','山中戏问韦侍御','白居易','quantangshi','','卷23','我抱栖云志，君怀济世才。
常吟反招隐，那得入山来。','',''),('quantangshi-22976','赠昙禅师','白居易','quantangshi','','卷23','五年不入慈恩寺，今日寻师始一来。
欲知火宅焚烧苦，方寸如今化作灰。','',''),('quantangshi-22977','寄微之','白居易','quantangshi','','卷23','帝城行乐日纷纷，天畔穷愁我与君。
秦女笑歌春不见，巴猨啼哭夜常闻。
何处琵琶弦似语，谁家[呙]堕髻如云。
人生多少欢娱事，那独千分无一分。','',''),('quantangshi-22978','醉吟二首 一','白居易','quantangshi','','卷23','空王百法学未得，姹女丹砂烧即飞。
事事无成身老也，醉乡不去欲何归。','',''),('quantangshi-22979','醉吟二首 二','白居易','quantangshi','','卷23','两鬓千茎新似雪，十分一盏欲如泥。
酒狂又引诗魔发，日午悲吟到日西。','',''),('quantangshi-22980','晓寝','白居易','quantangshi','','卷23','转枕重安寝，回头一欠伸。
纸窗明觉晓，布被暖知春。
莫强疎慵性，须安老大身。
鸡鸣一觉睡，不博早朝人。','',''),('quantangshi-22981','答元八郎中杨十二博士','白居易','quantangshi','','卷23','身觉浮云无所着，心同止水有何情。
但知潇洒疎朝市，不要崎岖隐姓名。
尽日观鱼临涧坐，有时随鹿上山行。
谁能抛得人间事，来共腾腾过此生。','',''),('quantangshi-22982','湖亭与行简宿','白居易','quantangshi','','卷23','浔阳少有风情客，招宿湖亭尽却回。
水槛虚凉风月好，夜深谁共阿怜来。','',''),('quantangshi-22983','八月十五日夜湓亭望月','白居易','quantangshi','','卷23','昔年八月十五夜，曲江池畔杏园边。
今年八月十五夜，湓浦沙头水馆前。
西北望乡何处是，东南见月几回圆。
临风一叹无人会，今夜清光似往年。','',''),('quantangshi-22984','赠江客','白居易','quantangshi','','卷23','江柳影寒新雨地，塞鸿声急欲霜天。
愁君独向沙头宿，水遶芦花月满船。','',''),('quantangshi-22985','残暑招客','白居易','quantangshi','','卷23','云截山腰断，风驱雨脚回。
早阴江上散，残热日中来。
却取生衣着，重拈竹簟开。
谁能淘晚热，闲饮两三杯。','',''),('quantangshi-22986','浔阳秋怀赠许明府','白居易','quantangshi','','卷23','霜红二林叶，风白九江波。
暝色投烟鸟，秋声带雨荷。
马闲无处出，门冷少人过。
卤莽还乡梦，依稀望阙歌。
共思除醉外，无计奈愁何。
试问陶家酒，新篘得几多。','',''),('quantangshi-22987','九日醉吟','白居易','quantangshi','','卷23','有恨头还白，无情菊自黄。
一为州司马，三见岁重阳。
劒匣尘埃满，笼禽日月长。
身从渔父笑，门任雀罗张。
问疾因留客，听吟偶置觞。
叹时论倚伏，怀旧数存亡。
奈老应无计，治愁或有方。
无过学王绩，唯以醉为乡。','',''),('quantangshi-22988','问韦山人山甫','白居易','quantangshi','','卷23','身名身事两蹉跎，试就先生问若何。
从此神仙学得否，白须虽有未为多。','',''),('quantangshi-22989','送萧炼师步虚词十首卷后以二绝继之 一','白居易','quantangshi','','卷23','欲上瀛州临别时，赠君十首步虚词。
天仙若爱应相问，可道江州司马诗。','',''),('quantangshi-22990','送萧炼师步虚词十首卷后以二绝继之 二','白居易','quantangshi','','卷23','花纸瑶缄松墨字，把将天上共谁开。
试呈王母如堪唱，发遣双成更取来。','',''),('quantangshi-22991','赠李兵马使','白居易','quantangshi','','卷23','身得贰师余气概，家藏都尉旧诗章。
江南别有楼船将，燕颔虬须不姓杨。','',''),('quantangshi-22992','题遗爱寺前溪松','白居易','quantangshi','','卷23','偃亚长松树，侵临小石溪。
静将流水对，高共远峰齐。
翠盖烟笼密，花幢雪压低。
与僧清影坐，借鹤稳枝栖。
笔写形难似，琴偷韵易迷。
暑天风槭槭，晴夜露凄凄。
独契依为舍，闲行遶作蹊。
栋梁君莫采，留着伴幽栖。','',''),('quantangshi-22993','庐山草堂夜雨独宿寄牛二李七庾三十二员外','白居易','quantangshi','','卷23','丹霄携手三君子，白发垂头一病翁。
兰省花时锦帐下，庐山雨夜草庵中。
终身胶漆心应在，半路云泥迹不同。
唯有无生三昧观，荣枯一照两成空。','',''),('quantangshi-22994','闻杨十二新拜省郎遥以诗贺','白居易','quantangshi','','卷23','文昌新入有光辉，紫界宫墙白粉闱。
晓日鸡人传漏箭，春风侍女护朝衣。
雪飘歌句高难和，鹤拂烟霄老惯飞。
官职声名俱入手，近来诗客似君稀。','',''),('quantangshi-22995','三月三日怀微之','白居易','quantangshi','','卷23','良时光景长虚掷，壮岁风情已暗销。
忽忆同为校书日，每年同醉是今朝。','',''),('quantangshi-22996','赠韦八','白居易','quantangshi','','卷23','辞君岁久见君初，白发惊嗟两有余。
容鬓别来今至此，心情料取合何如。
曾同曲水花亭醉，亦共华阳竹院居。
岂料天南相见夜，哀猨瘴雾宿匡庐。','',''),('quantangshi-22997','春江闲步赠张山人','白居易','quantangshi','','卷23','江景又妍和，牵愁发浩歌。
晴沙金屑色，春水麴尘波。
红簇交枝杏，青含卷叶荷。
藉莎怜輭暖，憩树爱婆娑。
书信朝贤断，知音野老多。
相逢不闲语，争奈日长何。','',''),('quantangshi-22998','春听琵琶兼简长孙司户','白居易','quantangshi','','卷23','四弦不似琵琶声，乱写真珠细撼铃。
指底商风悲飒飒，舌头胡语苦醒醒。
如言都尉思京国，似诉明妃厌虏庭。
迁客共君想劝谏，春肠易断不须听。','',''),('quantangshi-22999','吴宫辞','白居易','quantangshi','','卷23','一入吴王殿，无人覩翠娥。
楼高时见舞，宫静夜闻歌。
半露胷如雪，斜回脸似波。
妍媸各有分，谁敢妬恩多。','',''),('quantangshi-23000','送韦侍御量移金州司马','白居易','quantangshi','','卷23','春欢雨露同霑泽，冬叹风霜独满衣。
留滞多时如我少，迁移好处似君稀。
卧龙云到须先起，蛰燕雷惊尚未飞。
莫恨东西沟水别，沧溟长短拟同归。','',''),('quantangshi-23001','自到浔阳生三女子因诠真理用遣妄怀','白居易','quantangshi','','卷23','宦途本自安身拙，世累由来向老多。
远谪四年徒已矣，晚生三女拟如何。
预愁嫁娶真成患，细念因缘尽是魔。
赖学空王治苦法，须抛烦恼入头陀。','',''),('quantangshi-23002','江西裴常侍以优礼见待又蒙赠诗輙叙鄙诚用伸感谢','白居易','quantangshi','','卷23','一从簪笏事金貂，每借温颜放折腰。
长觉身轻离泥滓，忽惊手重捧琼瑶。
马因回顾虽增价，桐遇知音已半焦。
他日秉钧如见念，壮心直气未全销。','',''),('quantangshi-23003','自江州司马授忠州刺史仰荷圣泽聊书鄙诚','白居易','quantangshi','','卷23','炎瘴抛身远，泥涂索脚难。
网初鳞拨剌，笼久翅摧残。
雷电颁时令，阳和变岁寒。
遗簪承旧念，剖竹授新官。
乡觉前程近，心随外事宽。
生还应有分，西笑问长安。','',''),('quantangshi-23004','除忠州寄谢崔相公','白居易','quantangshi','','卷23','提拔出泥知力竭，吹嘘生翅见情深。
劒锋缺折难冲斗，桐尾烧焦岂望琴。
感旧两行年老泪，酬恩一寸岁寒心。
忠州好恶何须问，鸟得辞笼不择林。','',''),('quantangshi-23005','初除官蒙裴常侍赠鹘衔瑞草绯袍鱼袋因谢惠贶兼抒离情','白居易','quantangshi','','卷23','新授铜符未着绯，因君装束始光辉。
惠深范叔绨袍赠，荣过苏秦佩印归。
鱼缀白金随步跃，鹘衔红绶遶身飞。
明朝恋别朱门泪，不敢多垂恐污衣。','',''),('quantangshi-23006','洪州逢熊孺登','白居易','quantangshi','','卷23','靖安院里辛夷下，醉笑狂吟气最麤。
莫问别来多少苦，低头看取白髭须。','',''),('quantangshi-23007','初着刺史绯答友人见赠','白居易','quantangshi','','卷23','故人安慰善为辞，五十专城道未迟。
徒使花袍红似火，其如蓬鬓白成丝。
且贪薄俸君应惜，不称衰容我自知。
银印可怜将底用，只堪归舍吓妻儿。','',''),('quantangshi-23008','又答贺客','白居易','quantangshi','','卷23','银章暂假为专城，贺客来多嬾起迎。
似挂绯衫衣架上，朽株枯竹有何荣。','',''),('quantangshi-23009','别草堂三绝句 一','白居易','quantangshi','','卷23','正听山鸟向阳眠，黄纸除书落枕前。
为感君恩须暂起，炉峰不拟住多年。','',''),('quantangshi-23010','别草堂三绝句 二','白居易','quantangshi','','卷23','久眠褐被为居士，忽挂绯袍作使君。
身出草堂心不出，庐山未要勒移文。','',''),('quantangshi-23011','别草堂三绝句 三','白居易','quantangshi','','卷23','三间茅舍向山开，一带山泉遶舍回。
山色泉声莫惆怅，三年官满却归来。','',''),('quantangshi-23012','钟陵饯送','白居易','quantangshi','','卷23','翠幕红筵高在云，歌钟一曲万家闻。
路人指点滕王阁，看送忠州白使君。','',''),('quantangshi-23013','浔阳宴别','白居易','quantangshi','','卷23','鞍马军城外，笙歌祖帐前。
乘潮发湓口，带雪别庐山。
暮景牵行色，春寒散醉颜。
共嗟炎瘴地，尽室得生还。','',''),('quantangshi-23014','戏赠户部李巡官','白居易','quantangshi','','卷24','好去民曹李判官，少贪公事且谋欢。
男儿未死争能料，莫作忠州刺史看。','',''),('quantangshi-23015','行次夏口先寄李大夫','白居易','quantangshi','','卷24','连山断处大江流，红斾逶迤镇上游。
幕下翱翔秦御史，军前奔走汉诸侯。
曾陪劒履升鸾殿，欲谒旌幢入鹤楼。
假着绯袍君莫笑，恩深始得向忠州。','',''),('quantangshi-23016','重赠李大夫','白居易','quantangshi','','卷24','早接清班登玉陛，同承别诏直金銮。
凤巢阁上容身稳，鹤鏁笼中展翅难。
流落多年应是命，量移远郡未成官。
慙君独不欺顦顇，犹作银台旧眼看。','',''),('quantangshi-23017','对镜吟','白居易','quantangshi','','卷24','闲看明镜坐清晨，多病姿容半老身。
谁论情性乖时事，自想形骸非贵人。
三殿失恩宜放弃，九宫推命合漂沦。
如今所得须甘分，腰佩银龟朱两轮。','',''),('quantangshi-23018','江州赴忠州至江陵已来舟中示舍弟五十韵','白居易','quantangshi','','卷24','昔作咸秦客，常思江海行。
今来仍尽室，此去又专城。
典午犹为幸，分忧固是荣。
箳篂州乘送，艛艓驿船迎。
共载皆妻子，同游即弟兄。
宁辞浪迹远，且贵赏心并。
云展帆高挂，飙驰棹迅征。
溯流从汉浦，循路转荆衡。
山逐时移色，江随地改名。
风光近东早，水木向南清。
夏口烟孤起，湘川雨半晴。
日煎红浪沸，月射白砂明。
北渚寒留雁，南枝暖待莺。
骈朱桃露萼，点翠柳含萌。
亥市鱼盐聚，神林鼓笛鸣。
壶浆椒叶气，歌曲竹枝声。
系缆怜沙静，垂纶爱岸平。
水飡红粒稻，野茹紫花菁。
瓯泛茶如乳，台黏酒似饧。
脍长抽锦缕，藕脆削琼英。
容易来千里，斯须进一程。
未曾劳气力，渐觉有心情。
卧稳添春睡，行迟带酒酲。
忽愁牵世网，便欲濯尘缨。
早接文场战，曾争翰苑盟。
掉头称俊造，翘足取公卿。
且昧随时义，徒输报国诚。
众排恩易失，偏压势先倾。
虎尾忧危切，鸿毛性命轻。
烛蛾谁救活，蚕茧自缠萦。
歛手辞双阙，回眸望两京。
长沙抛贾谊，漳浦卧刘桢。
鶗鴂鸣还歇，蟾蜍破又盈。
年光同激箭，乡思极摇旌。
潦倒亲知笑，衰羸旧识惊。
乌头因感白，鱼尾为劳頳。
劒学将何用，丹烧竟不成。
孤舟萍一叶，双鬓雪千茎。
老见人情尽，闲思物理精。
如汤探冷热，似博鬬输赢。
险路应须避，迷途莫共争。
此心知止足，何物要经营。
玉向泥中洁，松经雪后贞。
无妨隐朝市，不必谢寰瀛。
但在前非悟，期无后患婴。
多知非景福，少语是元亨。
晦即全身药，明为伐性兵。
昏昏随世俗，蠢蠢学黎甿。
鸟以能言{构木=糸}，龟缘入梦烹。
知之一何晚，犹足保余生。','',''),('quantangshi-23019','题岳阳楼','白居易','quantangshi','','卷24','岳阳城下水漫漫，独上危楼倚曲栏。
春岸绿时连梦泽，夕波红处近长安。
猨攀树立啼何苦，雁点湖飞渡亦难。
此地唯堪画图障，华堂张与贵人看。','',''),('quantangshi-23020','入峡次巴东','白居易','quantangshi','','卷24','不知远郡何时到，犹喜全家此去同。
万里王程三峡外，百年生计一舟中。
巫山暮足霑花雨，陇水春多逆浪风。
两片红旌数声鼓，使君艛艓上巴东。','',''),('quantangshi-23021','十年三月三十日别微之于[沣]上十四年三月十一日夜遇微之于峡中停舟夷陵三宿而别言不尽者以诗终之因赋七言十七韵以赠且欲记所遇之地与相见之时为他年会话张本也','白居易','quantangshi','','卷24','[沣]水店头春尽日，送君上马谪通川。
夷陵峡口明月夜，此处逢君是偶然。
一别五年方见面，相携三宿未回船。
坐从日暮唯长叹，语到天明竟未眠。
齿发蹉跎将五十，关河迢递过三千。
生涯共寄沧江上，乡国俱抛白日边。
往事渺茫都似梦，旧游流落半归泉。
醉悲洒泪春杯里，吟苦支颐晓烛前。
莫问龙钟恶官职，且听清脆好文篇。
别来只是成诗癖，老去何曾更酒颠。
各限王程须去住，重开离宴贵留连。
黄牛渡北移征棹，白狗崖东卷别筵。
神女台云闲缭绕，使君滩水急潺湲。
风凄暝色愁杨柳，月吊宵声哭杜鹃。
万丈赤幢潭底日，一条白练峡中天。
君还秦地辞炎徼，我向忠州入瘴烟。
未死会应相见在，又知何地复何年。','',''),('quantangshi-23022','题峡中石上','白居易','quantangshi','','卷24','巫女庙花红似粉，昭君村柳翠于眉。
诚知老去风情少，见此争无一句诗。','',''),('quantangshi-23023','夜入瞿唐峡','白居易','quantangshi','','卷24','瞿唐天下险，夜上信难哉。
岸似双屏合，天如匹帛开。
逆风惊浪起，拔𥮘暗船来。
欲识愁多少，高于滟滪堆。','',''),('quantangshi-23024','初到忠州赠李六','白居易','quantangshi','','卷24','好在天涯李使君，江头相见日黄昏。
吏人生梗都如鹿，市井疎芜只抵村。
一只兰船当驿路，百层石磴上州门。
更无平地堪行处，虚受朱轮五马恩。','',''),('quantangshi-23025','郡斋暇日忆庐山草堂兼寄二林僧社三十韵多叙贬官已来出处之意','白居易','quantangshi','','卷24','谏诤知无补，迁移分所当。
不堪匡圣主，只合事空王。
龙象投新社，鵷鸾失故行。
沈吟辞北阙，诱引向西方。
便住双林寺，仍开一草堂。
平治行道路，安置坐禅牀。
手版支为枕，头巾阁在墙。
先生乌几舃，居士白衣裳。
竟岁何曾闷，终身不拟忙。
灭除残梦想，换尽旧心肠。
世界多烦恼，形神久损伤。
正从风鼓浪，转作日销霜。
吾道寻知止，君恩偶未忘。
忽蒙颁凤诏，兼谢剖鱼章。
莲静方依水，葵枯重仰阳。
三车犹夕会，五马已晨装。
去似寻前世，来如别故乡。
眉低出鹫岭，脚重下虵冈。
渐望庐山远，弥愁峡路长。
香炉峰隐隐，巴字水茫茫。
瓢挂留庭树，经收在屋梁。
春抛红药圃，夏忆白莲塘。
唯拟捐尘事，将何答宠光。
有期追永远，无政继龚黄。
南国秋犹热，西斋夜暂凉。
闲吟四句偈，静对一炉香。
身老同丘井，心空是道场。
觅僧为去伴，留俸作归粮。
为报山中侣，凭看竹下房。
会应归去在，松菊莫教荒。','',''),('quantangshi-23026','赠康叟','白居易','quantangshi','','卷24','八十秦翁老不归，南宾太守乞寒衣。
再三怜汝非他意，天宝遗民见渐稀。','',''),('quantangshi-23027','鹦鹉','白居易','quantangshi','','卷24','竟日语还默，中宵栖复惊。
身囚缘彩翠，心苦为分明。
暮起归巢思，春多忆侣声。
谁能拆笼破，从放快飞鸣。','',''),('quantangshi-23028','京使回累得南省诸公书因以长句诗寄谢萧五刘二元八吴十一韦大陆郎中崔二十二牛二李七庾三十二李六李十杨三樊大杨十二员外','白居易','quantangshi','','卷24','雪压泥埋未死身，每劳存问愧交亲。
浮萍飘泊三千里，列宿参差十五人。
禁月落时君待漏，畲烟深处我行春。
瘴乡得老犹为幸，岂敢伤嗟白发新。','',''),('quantangshi-23029','东城春意','白居易','quantangshi','','卷24','风輭云不动，郡城东北隅。
晚来春澹澹，天气似京都。
弦管随宜有，杯觞不道无。
其如亲故远，无可共欢娱。','',''),('quantangshi-23030','木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉溪生者穠茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 一','白居易','quantangshi','','卷24','如折芙蓉栽旱地，似抛芍药挂高枝。
云埋水隔无人识，唯有南宾太守知。','',''),('quantangshi-23031','木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉溪生者穠茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 二','白居易','quantangshi','','卷24','红似燕支腻如粉，伤心好物不须臾。
山中风起无时节，明日重来得在无。','',''),('quantangshi-23032','木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉溪生者穠茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 三','白居易','quantangshi','','卷24','已愁花落荒岩底，复恨根生乱石间。
几度欲移移不得，天教抛掷在深山。','',''),('quantangshi-23033','种桃杏','白居易','quantangshi','','卷24','无论海角与天涯，大抵心安即是家。
路远谁能念乡曲，年深兼欲忘京华。
忠州且作三年计，种杏栽桃拟待花。','',''),('quantangshi-23034','新秋','白居易','quantangshi','','卷24','二毛生镜日，一叶落庭时。
老去争由我，愁来欲泥谁。
空销闲岁月，不见旧亲知。
唯弄扶牀女，时时强展眉。','',''),('quantangshi-23035','龙昌寺荷池','白居易','quantangshi','','卷24','冷碧新秋水，残红半破莲。
从来寥落意，不似此池边。','',''),('quantangshi-23036','听竹枝赠李侍御','白居易','quantangshi','','卷24','巴童巫女竹枝歌，懊恼何人怨咽多。
暂听遣君犹怅望，长闻教我复如何。','',''),('quantangshi-23037','寄胡饼与杨万州','白居易','quantangshi','','卷24','胡麻饼样学京都，麪脆油香新出炉。
寄与饥馋杨大使，尝看得似辅兴无。','',''),('quantangshi-23038','感樱桃花因招饮客','白居易','quantangshi','','卷24','樱桃昨夜开如雪，鬓发今年白如霜。
渐觉花前成老丑，何曾酒后更颠狂。
谁能闻此来相劝，共泥春风醉一场。','',''),('quantangshi-23039','东亭闲望','白居易','quantangshi','','卷24','东亭尽日坐，谁伴寂寥身。
绿桂为佳客，红蕉当美人。
笑言虽不接，情状似相亲。
不作悠悠想，如何度晚春。','',''),('quantangshi-23040','画木莲花图寄元郎中','白居易','quantangshi','','卷24','花房腻似红莲朵，艳色鲜如紫牡丹。
唯有诗人能解爱，丹青写出与君看。','',''),('quantangshi-23041','和李澧州题韦开州经藏诗','白居易','quantangshi','','卷24','既悟莲花藏，须遗贝叶书。
菩提无处所，文字本空虚。
观指非知月，忘筌是得鱼。
闻君登彼岸，舍筏复何如。','',''),('quantangshi-23042','九日题涂溪','白居易','quantangshi','','卷24','蕃草席铺枫叶岸，竹枝歌送菊花杯。
明年尚作南宾守，或可重阳更一来。','',''),('quantangshi-23043','即事寄微之','白居易','quantangshi','','卷24','畲田涩米不耕鉏，旱地荒园少菜蔬。
想念土风今若此，料看生计合何如。
衣缝纰纇黄丝绢，饭下腥咸白小鱼。
饱暖饥寒何足道，此身长短是空虚。','',''),('quantangshi-23044','题郡中荔枝诗十八韵兼寄万州杨八使君','白居易','quantangshi','','卷24','奇果标南土，芳林对北堂。
素华春漠漠，丹实夏煌煌。
叶捧低垂户，枝擎重压墙。
始因风弄色，渐与日争光。
夕讶条悬火，朝惊树点妆。
深于红踯躅，大校白槟榔。
星缀连心朵，珠排耀眼房。
紫罗裁衬壳，白玉裹填瓤。
早岁曾闻说，今朝始摘尝。
嚼疑天上味，嗅异世间香。
润胜莲生水，鲜逾橘得霜。
燕支掌中颗，甘露舌头浆。
物少尤珍重，天高苦渺茫。
已教生暑月，又使阻遐方。
粹液灵难驻，妍姿嫩易伤。
近南光景热，向北道途长。
不得充王赋，无由寄帝乡。
唯君堪掷赠，面白似潘郎。','',''),('quantangshi-23045','留北客','白居易','quantangshi','','卷24','峡外相逢远，樽前一会难。
即须分手别，且强展眉欢。
楚袖萧条舞，巴弦趣数弹。
笙歌随分有，莫作帝乡看。','',''),('quantangshi-23046','重寄荔枝与杨使君时闻杨使君欲种植故有落句之戏','白居易','quantangshi','','卷24','摘来正带凌晨露，寄去须凭下水船。
映我绯衫浑不见，对公银印最相鲜。
香连翠叶真堪画，红透青笼实可怜。
闻道万州方欲种，愁君得吃是何年。','',''),('quantangshi-23047','和万州杨使君四绝句 竞渡','白居易','quantangshi','','卷24','竞渡相传为汨罗，不能止遏意无他。
自经放逐来顦顇，能校灵均死几多。','',''),('quantangshi-23048','和万州杨使君四绝句 江边草','白居易','quantangshi','','卷24','闻君泽畔伤春草，忆在天门街里时。
漠漠凄凄愁满眼，就中惆怅是江蓠。','',''),('quantangshi-23049','和万州杨使君四绝句 嘉庆李','白居易','quantangshi','','卷24','东都绿李万州栽，君手封题我手开。
把得欲尝先怅望，与渠同别故乡来。','',''),('quantangshi-23050','和万州杨使君四绝句 白槿花','白居易','quantangshi','','卷24','秋蕣晚英无艳色，何因栽种在人家。
使君自别罗敷面，争解回头爱白花。','',''),('quantangshi-23051','和行简望郡南山','白居易','quantangshi','','卷24','反照前山云树明，从君苦道似华清。
试听肠断巴猨呌，早晚骊山有此声。','',''),('quantangshi-23052','种荔枝','白居易','quantangshi','','卷24','红颗珍珠诚可爱，白须太守亦何痴。
十年结子知谁在，自向庭中种荔枝。','',''),('quantangshi-23053','阴雨','白居易','quantangshi','','卷24','岚雾今朝重，江山此地深。
滩声秋更急，峡气晓多阴。
望阙云遮眼，思乡雨滴心。
将何慰幽独，赖此北窗琴。','',''),('quantangshi-23054','送客归京','白居易','quantangshi','','卷24','水陆四千里，何时归到秦？
舟辞三峡雨，马入九衢尘。
有酒留行客，无书寄贵人。
唯凭远传语，好在曲江春。','',''),('quantangshi-23055','送萧处士游黔南','白居易','quantangshi','','卷24','能文好饮老萧郎，身似浮云鬓似霜。
生计抛来诗是业，家园忘却酒为乡。
江从巴峡初成字，猨过巫阳始断肠。
不醉黔中争去得，磨围山月正苍苍。','',''),('quantangshi-23056','东楼醉','白居易','quantangshi','','卷24','天涯深峡无人地，岁暮穷阴欲夜天。
不向东楼时一醉，如何拟过二三年。','',''),('quantangshi-23057','寄微之','白居易','quantangshi','','卷24','高天默默物茫茫，各有来由致损伤。
鹦为能言长剪翅，龟缘难死久搘牀。
莫嫌冷落抛闲地，犹胜炎蒸卧瘴乡。
外物竟关身底事，谩排门戟系腰章。','',''),('quantangshi-23058','东楼招客夜饮','白居易','quantangshi','','卷24','莫辞数数醉东楼，除醉无因破得愁。
唯有绿樽红烛下，暂时不似在忠州。','',''),('quantangshi-23059','醉后戏题','白居易','quantangshi','','卷24','自知清冷似冬凌，每被人呼作律僧。
今夜酒醺罗绮暖，被君融尽玉壶冰。','',''),('quantangshi-23060','冬至夜','白居易','quantangshi','','卷24','老去襟怀常濩落，病来须鬓转苍浪。
心灰不及炉中火，鬓雪多于砌下霜。
三峡南宾城最远，一年冬至夜偏长。
今宵始觉房栊冷，坐索寒衣托孟光。','',''),('quantangshi-23061','竹枝词四首 一','白居易','quantangshi','','卷24','瞿唐峡口水烟低，白帝城头月向西。
唱到竹枝声咽处，寒猨暗鸟一时啼。','',''),('quantangshi-23062','竹枝词四首 二','白居易','quantangshi','','卷24','竹枝苦怨怨何人，夜静山空歇又闻。
蛮儿巴女齐声唱，愁杀江楼病使君。','',''),('quantangshi-23063','竹枝词四首 三','白居易','quantangshi','','卷24','巴东船舫上巴西，波面风生雨脚齐。
水蓼冷花红簇簇，江蓠湿叶碧凄凄。','',''),('quantangshi-23064','竹枝词四首 四','白居易','quantangshi','','卷24','江畔谁人唱竹枝，前声断咽后声迟。
怪来调苦缘词苦，多是通州司马诗。','',''),('quantangshi-23065','酬严中丞晚眺黔江见寄','白居易','quantangshi','','卷24','江水三回曲，愁人两地情。
磨围山下色，明月峡中声。
晚后连天碧，秋来彻底清。
临流有新恨，照见白须生。','',''),('quantangshi-23066','寄题杨万州四望楼','白居易','quantangshi','','卷24','江上新楼名四望，东西南北水茫茫。
无由得与君携手，同凭栏干一望乡。','',''),('quantangshi-23067','答杨使君登楼见忆','白居易','quantangshi','','卷24','忠万楼中南北望，南州烟水北州云。
两州何事偏相忆，各是笼禽作使君。','',''),('quantangshi-23068','除夜','白居易','quantangshi','','卷24','岁暮纷多思，天涯渺未归。
老添新甲子，病减旧容辉。
乡国仍留念，功名已息机。
明朝四十九，应转悟前非。','',''),('quantangshi-23069','闻雷','白居易','quantangshi','','卷24','瘴地风霜早，温天气候催。
穷冬不见雪，正月已闻雷。
震蛰虫蛇出，惊枯草木开。
空余客方寸，依旧似寒灰。','',''),('quantangshi-23070','春至','白居易','quantangshi','','卷24','若为南国春还至，争向东楼日又长。
白片落梅浮涧水，黄梢新柳出城墙。
闲拈蕉叶题诗咏，闷取藤枝引酒尝。
乐事渐无身渐老，从今始拟负风光。','',''),('quantangshi-23071','感春','白居易','quantangshi','','卷24','巫峡中心郡，巴城四面春。
草青临水地，头白见花人。
忧喜皆心火，荣枯是眼尘。
除非一杯酒，何物更关身。','',''),('quantangshi-23072','春江','白居易','quantangshi','','卷24','炎凉昏晓苦推迁，不觉忠州已二年。
闭阁只听朝暮鼓，上楼空望往来船。
莺声诱引来花下，草色句留坐水边。
唯有春江看未厌，萦砂遶石渌潺湲。','',''),('quantangshi-23073','题东楼前李使君所种樱桃花','白居易','quantangshi','','卷24','身入青云无见日，手栽红树又逢春。
唯留花向楼前着，故故抛愁与后人。','',''),('quantangshi-23074','巴水','白居易','quantangshi','','卷24','城下巴江水，春来似麴尘。
软沙如渭曲，斜岸忆天津。
影蘸新黄柳，香浮小白苹。
临流搔首坐，惆怅为何人。','',''),('quantangshi-23075','野行','白居易','quantangshi','','卷24','草润衫襟重，沙干屐齿轻。
仰头听鸟立，信脚望花行。
暇日无公事，衰年有道情。
浮生短于梦，梦里莫营营。','',''),('quantangshi-23076','送高侍御使回因寄杨八','白居易','quantangshi','','卷24','明月峡边逢制使，黄茅岸上是忠州。
到城莫说忠州恶，无益虚教杨八愁。','',''),('quantangshi-23077','奉酬李相公见示绝句','白居易','quantangshi','','卷24','碧油幢下捧新诗，荣贱虽殊共一悲。
涕泪满襟君莫怪，甘泉侍从最多时。','',''),('quantangshi-23078','喜山石榴花开','白居易','quantangshi','','卷24','忠州州里今日花，庐山山头去时树。
已怜根损斩新栽，还喜花开依旧数。
赤玉何人少琴轸，红缬谁家合罗袴。
但知烂熳恣情开，莫怕南宾桃李妬。','',''),('quantangshi-23079','戏赠萧处士清禅师','白居易','quantangshi','','卷24','三杯嵬峩忘机客，百衲头陀任运僧。
又有放慵巴郡守，不营一事共腾腾。','',''),('quantangshi-23080','钱虢州以三堂绝句见寄因以本韵和之','白居易','quantangshi','','卷24','同事空王岁月深，相思远寄定中吟。
遥知清净中和化，祗用金刚三昧心。','',''),('quantangshi-23081','三月三日','白居易','quantangshi','','卷24','暮春风景初三日，流世光阴半百年。
欲作闲游无好伴，半江惆怅却回船。','',''),('quantangshi-23082','寒食夜','白居易','quantangshi','','卷24','四十九年身老日，一百五夜月明天。
抱膝思量何事在，痴男呆女唤秋千。','',''),('quantangshi-23083','代州民问','白居易','quantangshi','','卷24','龙昌寺底开山路，巴子台前种柳林。
官职家乡都忘却，谁人会得使君心。','',''),('quantangshi-23084','答州民','白居易','quantangshi','','卷24','宦情斗擞随尘去，乡思销磨逐日无。
唯拟腾腾作闲事，遮渠不道使君愚。','',''),('quantangshi-23085','荔枝楼对酒','白居易','quantangshi','','卷24','荔枝新熟鸡冠色，烧酒初开琥珀香。
欲摘一枝倾一盏，西楼无客共谁尝。','',''),('quantangshi-23086','房家夜宴喜雪戏赠主人','白居易','quantangshi','','卷24','风头向夜利如刀，赖此温炉輭锦袍。
桑落气薰珠翠暖，柘枝声引管弦高。
酒钩送盏推莲子，烛泪黏盘垒蒲萄。
不醉遣侬争散得，门前雪片似鹅毛。','',''),('quantangshi-23087','醉后赠人','白居易','quantangshi','','卷24','香球趂拍回环匼，花盏抛巡取次飞。
自入春来未同醉，那能夜去独先归。','',''),('quantangshi-23088','初除尚书郎脱刺史绯','白居易','quantangshi','','卷24','亲宾相贺问何如，服色恩光尽反初。
头白喜抛黄草峡，眼明惊拆紫泥书。
便留朱绂还铃阁，却着青袍侍玉除。
无奈娇痴三岁女，绕腰啼哭觅金鱼。','',''),('quantangshi-23089','留题开元寺上方','白居易','quantangshi','','卷24','东寺台阁好，上方风景清。
数来犹未厌，长别岂无情。
恋水多临坐，辞花剩绕行。
最怜新岸柳，手种未全成。','',''),('quantangshi-23090','别种东坡花树两绝 一','白居易','quantangshi','','卷24','三年留滞在江城，草树禽鱼尽有情。
何处殷勤重回首，东坡桃李种新成。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-23091','别种东坡花树两绝 二','白居易','quantangshi','','卷24','花林好住莫顦顇，春至但知依旧春。
楼上明年新太守，不妨还是爱花人。','',''),('quantangshi-23092','别桥上竹','白居易','quantangshi','','卷24','穿桥迸竹不依行，恐碍行人被损伤。
我去自慙遗爱少，不教君得似甘棠。','',''),('quantangshi-23093','发白狗峡次黄牛峡登高寺却望忠州','白居易','quantangshi','','卷24','白狗次黄牛，滩如竹节稠。
路穿天地险，人续古今愁。
忽见千花塔，因停一叶舟。
畏途常迫促，静境暂淹留。
巴曲春全尽，巫阳雨半收。
北归虽引领，南望亦回头。
昔去悲殊俗，今来念旧游。
别僧山北寺，抛竹水西楼。
郡树花如雪，军厨酒似油。
时时大开口，自笑忆忠州。','',''),('quantangshi-23094','棣华驿见杨八题梦兄弟诗','白居易','quantangshi','','卷24','遥闻旅宿梦兄弟，应为邮亭名棣华。
名作棣华来早晚，自题诗后属杨家。','',''),('quantangshi-23095','商山路有感','白居易','quantangshi','','卷24','万里路长在，六年身始归。
所经多旧馆，大半主人非。','',''),('quantangshi-23096','商山路驿桐树昔与微之前后题名处','白居易','quantangshi','','卷24','与君前后多迁谪，五度经过此路隅。
笑问中庭老桐树，这回归去免来无。','',''),('quantangshi-23097','恻恻吟','白居易','quantangshi','','卷24','恻恻复恻恻，逐臣返乡国。
前事难重论，少年不再得。
泥涂绛老头班白，炎瘴灵均面黎黑。
六年不死却归来，道着姓名人不识。','',''),('quantangshi-23098','德宗皇帝挽歌词四首 一','白居易','quantangshi','','卷24','执象宗玄祖，贻谋启孝孙。
文高柏梁殿，礼薄霸陵原。
宫仗辞天阙，朝仪出国门。
生成不可报，二十七年恩。','',''),('quantangshi-23099','德宗皇帝挽歌词四首 二','白居易','quantangshi','','卷24','虞帝南巡后，殷宗谅暗中。
初辞铸鼎地，已闭望仙宫。
晓落当陵月，秋生满斾风。
前星承帝座，不使北辰空。','',''),('quantangshi-23100','德宗皇帝挽歌词四首 三','白居易','quantangshi','','卷24','业大承宗祖，功成付子孙。
睿文诗播乐，遗训史标言。
节表中和德，方垂广利恩。
悬知千载后，理代数贞元。','',''),('quantangshi-23101','德宗皇帝挽歌词四首 四','白居易','quantangshi','','卷24','梦减三龄寿，哀延七月期。
寝园愁望远，宫仗哭行迟。
云日添寒惨，笳箫向晚悲。
因山有遗诏，如葬汉文时。','',''),('quantangshi-23102','昭德皇后挽歌词','白居易','quantangshi','','卷24','仙去逍遥境，诗留窈窕章。
春归金屋少，夜入寿宫长。
凤引曾辞辇，蚕休昔采桑。
阴灵何处感，沙麓月无光。','',''),('quantangshi-23103','太平乐词二首 一','白居易','quantangshi','','卷24','岁丰仍节俭，时泰更销兵。
圣念长如此，何忧不太平。','',''),('quantangshi-23104','太平乐词二首 二','白居易','quantangshi','','卷24','湛露浮尧酒，薰风起舜歌。
愿同尧舜意，所乐在人和。','',''),('quantangshi-23105','小曲新词二首 一','白居易','quantangshi','','卷24','霁色鲜宫殿，秋声脆管弦。
圣明千岁乐，岁岁似今年。','',''),('quantangshi-23106','小曲新词二首 二','白居易','quantangshi','','卷24','红裾明月夜，碧簟早秋时。
好向昭阳宿，天凉玉漏迟。','',''),('quantangshi-23107','闺怨词三首 一','白居易','quantangshi','','卷24','朝憎莺百啭，夜妒燕双栖。
不惯经春别，谁知到晓啼。','',''),('quantangshi-23108','闺怨词三首 二','白居易','quantangshi','','卷24','珠箔笼寒月，纱窗背晓灯。
夜来巾上泪，一半是春冰。','',''),('quantangshi-23109','闺怨词三首 三','白居易','quantangshi','','卷24','关山征戍远，闺阁别离难。
苦战应顦顇，寒衣不要宽。','',''),('quantangshi-23110','残春曲','白居易','quantangshi','','卷24','禁苑残莺三四声，景迟风慢暮春情。
日西无事墙阴下，闲蹋宫花独自行。','',''),('quantangshi-23111','长安春','白居易','quantangshi','','卷24','青门柳枝软无力，东风吹作黄金色。
街东酒薄醉易醒，满眼春愁销不得。','',''),('quantangshi-23112','长乐坡送人赋得愁','白居易','quantangshi','','卷24','行人南北分征路，流水东西接御沟。
终日坡前恨离别，谩名长乐是长愁。','',''),('quantangshi-23113','独眠吟二首 一','白居易','quantangshi','','卷24','夜长无睡起阶前，寥落星河欲曙天。
十五年来明月夜，何曾一夜不孤眠。','',''),('quantangshi-23114','独眠吟二首 二','白居易','quantangshi','','卷24','独眠客，夜夜可怜长寂寂。
就中今夜最愁人，凉月清风满牀席。','',''),('quantangshi-23115','期不至','白居易','quantangshi','','卷24','红烛清樽久延伫，出门入门天欲曙。
星稀月落竟不来，烟柳胧胧鹊飞去。','',''),('quantangshi-23116','长洲苑','白居易','quantangshi','','卷24','春入长洲草又生，鹧鸪飞起少人行。
年深不辨娃宫处，夜夜苏台空月明。','',''),('quantangshi-23117','忆江柳','白居易','quantangshi','','卷24','曾栽杨柳江南岸，一别江南两度春。
遥忆青青江岸上，不知攀折是何人。','',''),('quantangshi-23118','南浦别','白居易','quantangshi','','卷24','南浦凄凄别，西风袅袅秋。
一看肠一断，好去莫回头。','',''),('quantangshi-23119','三年别','白居易','quantangshi','','卷24','悠悠一别已三年，相望相思明月天。
肠断青天望明月，别来三十六回圆。','',''),('quantangshi-23120','伤春词','白居易','quantangshi','','卷24','深浅檐花千万枝，碧纱窗外啭黄鹂。
残妆含泪下帘坐，尽日伤春春不知。','',''),('quantangshi-23121','后宫词','白居易','quantangshi','','卷24','泪湿罗巾梦不成，夜深前殿按歌声。
红颜未老恩先断，斜倚薰笼坐到明。','',''),('quantangshi-23122','吟元郎中白须诗兼饮雪水茶因题壁上','白居易','quantangshi','','卷24','吟咏霜毛句，闲尝雪水茶。
城中展眉处，只是有元家。','',''),('quantangshi-23123','吴七郎中山人待制班中偶赠绝句','白居易','quantangshi','','卷24','金马东门只日开，汉庭待诏重仙才。
第三松树非华表，那得辽东鹤下来。','',''),('quantangshi-23124','和张十八祕书谢裴相公寄马','白居易','quantangshi','','卷24','齿齐膘足毛头腻，祕阁张郎叱拨驹。
洗了颔花翻假锦，走时蹄汗蹋真珠。
青衫乍见曾惊否，红粟难赊得饱无。
丞相寄来应有意，遣君骑去上云衢。','',''),('quantangshi-23125','答山侣','白居易','quantangshi','','卷24','颔下髭须半是丝，光阴向后几多时。
非无解挂簪缨意，未有支持伏腊资。
冒热冲寒徒自取，随行逐队欲何为。
更慙山侣频传语，五十归来道未迟。','',''),('quantangshi-23126','早朝思退居','白居易','quantangshi','','卷24','霜严月苦欲明天，忽忆闲居思浩然。
自问寒灯夜半起，何如暖被日高眠。
唯慙老病披朝服，莫虑饥寒计俸钱。
随有随无且归去，拟求丰足是何年。','',''),('quantangshi-23127','曲江亭晚望','白居易','quantangshi','','卷24','曲江岸北凭栏干，水面阴生日脚残。
尘路行多绿袍故，风亭立久白须寒。
诗成暗着闲心记，山好遥偷病眼看。
不被马前提省印，何人信道是郎官。','',''),('quantangshi-23128','初除主客郎中知制诰与王十一李七元九三舍人中书同宿话旧感怀','白居易','quantangshi','','卷24','闲宵静话喜还悲，聚散穷通不自知。
已分云泥行异路，忽惊鸡鹤宿同枝。
紫垣曹署荣华地，白发郎官老丑时。
莫怪不如君气味，此中来校十年迟。','',''),('quantangshi-23129','西省对花忆忠州东坡新花树因寄题东楼','白居易','quantangshi','','卷24','每看阙下丹青树，不忘天边锦绣林。
西掖垣中今日眼，南宾楼上去年心。
花含春意无分别，物感人情有浅深。
最忆东坡红烂熳，野桃山杏水林檎。','',''),('quantangshi-23130','寄题忠州小楼桃花','白居易','quantangshi','','卷24','再游巫峡知何日，总是秦人说向谁。
长忆小楼风月夜，红栏干上两三枝。','',''),('quantangshi-23131','中书连直寒食不归因怀元九','白居易','quantangshi','','卷24','去岁清明日，南巴古郡楼。
今年寒食夜，西省凤池头。
并上新人直，难随旧伴游。
诚知视草贵，未免对花愁。
鬓发茎茎日，光阴寸寸流。
经春不同宿，何异在忠州。','',''),('quantangshi-23132','春忆二林寺旧游因寄朗满晦三上人','白居易','quantangshi','','卷24','一别东林三度春，每春常似忆情亲。
头陀会里为逋客，供俸班中作老臣。
清净久辞香火伴，尘劳难索幻泡身。
最惭僧社题桥处，十八人名空一人。','',''),('quantangshi-23133','和元少尹新授官','白居易','quantangshi','','卷24','官稳身应泰，春风信马行。
纵忙无苦事，虽病有心情。
厚禄儿孙饱，前驱道路荣。
花时八入直，无暇贺元兄。','',''),('quantangshi-23134','朝回和元少尹绝句','白居易','quantangshi','','卷24','朝客朝回回望好，尽纡朱紫佩金银。
此时独与君为伴，马上青袍唯两人。','',''),('quantangshi-23135','重和元少尹','白居易','quantangshi','','卷24','凤阁舍人京亚尹，白头俱未着绯衫。
南宫起请无消息，朝散何时得入衔。','',''),('quantangshi-23136','中书夜直梦忠州','白居易','quantangshi','','卷24','阁下灯前梦，巴南城里游。
觅花来渡口，寻寺到山头。
江色分明绿，猨声依旧愁。
禁钟惊睡觉，唯不上东楼。','',''),('quantangshi-23137','醉后','白居易','quantangshi','','卷24','酒后高歌且放狂，门前闲事莫思量。
犹嫌小户长先醒，不得多时住醉乡。','',''),('quantangshi-23138','待漏入阁书事奉赠元九学士阁老','白居易','quantangshi','','卷24','衙排宣政仗，门启紫宸关。
彩笔停书命，花甎趂立班。
稀星点银砾，残月堕金环。
暗漏犹传水，明河渐下山。
从东分地色，向北仰天颜。
碧缕炉烟直，红垂佩尾闲。
纶闱惭并入，翰苑忝先攀。
笑我青袍故，饶君茜绶殷。
诗仙归洞里，酒病滞人间。
好去鸳鸾侣，冲天便不还。','',''),('quantangshi-23139','晚春重到集贤院','白居易','quantangshi','','卷24','官曹清切非人境，风月鲜明是洞天。
满砌荆花铺紫毯，隔墙榆荚撒青钱。
前时谪去三千里，此地辞来十四年。
虚薄至今惭旧职，院名抬举号为贤。','',''),('quantangshi-23140','紫薇花','白居易','quantangshi','','卷24','丝纶阁下文书静，钟鼓楼中刻漏长。
独坐黄昏谁是伴，紫薇花对紫微郎。','',''),('quantangshi-23141','后宫词','白居易','quantangshi','','卷24','雨露由来一点恩，争能徧布及千门。
三千宫女胭脂面，几个春来无泪痕。','',''),('quantangshi-23142','卜居','白居易','quantangshi','','卷24','游宦京都二十春，贫中无处可安贫。
长羡蜗牛犹有舍，不如硕鼠解藏身。
且求容立锥头地，免似漂流木偶人。
但道吾庐心便足，敢辞湫隘与嚣尘。','',''),('quantangshi-23143','题新居寄元八','白居易','quantangshi','','卷24','青龙冈北近西边，移入新居便泰然。
冷巷闭门无客到，暖檐移榻向阳眠。
阶庭宽窄才容足，墙壁高低粗及肩。
莫羡升平元八宅，自思买用几多钱。','',''),('quantangshi-23144','登龙尾道南望忆庐山旧隐','白居易','quantangshi','','卷24','龙尾道边来一望，香炉峰下去无因。
青山举眼三千里，白发平头五十人。
自笑形骸纡组绶，将何言语掌丝纶。
君恩壮健犹难报，况被年年老逼身。','',''),('quantangshi-23145','冯阁老处见与严郎中酬和诗因戏赠绝句','白居易','quantangshi','','卷24','乍来天上宜清净，不用回头望故山。
纵有旧游君莫忆，尘心起即堕人间。','',''),('quantangshi-23146','见于给事暇日上直寄南省诸郎官诗因以戏赠','白居易','quantangshi','','卷24','倚作天仙弄地仙，夸张一日抵千年。
黄麻勅胜长生箓，白紵词嫌内景篇。
云彩误居青琐地，风流合在紫微天。
东曹渐去西垣近，鹤驾无妨更着鞭。','',''),('quantangshi-23147','题新昌所居','白居易','quantangshi','','卷24','宅小人烦闷，泥深马钝顽。
街东闲处住，日午热时还。
院窄难栽竹，墙高不见山。
唯应方寸内，此地觅宽闲。','',''),('quantangshi-23148','西省北院新构小亭种竹开窗东通骑省与李常侍隔窗小饮各题四韵','白居易','quantangshi','','卷24','结托白须伴，因依青竹丛。
题诗新壁上，过酒小窗中。
深院晚无白，虚檐凉有风。
金貂醉好看，回首紫垣东。','',''),('quantangshi-23149','酬元郎中同制加朝散大夫书怀见赠','白居易','quantangshi','','卷24','命服虽同黄纸上，官班不共紫垣前。
青衫脱早差三日，白发生迟校九年。
曩者定交非势利，老来同病是诗篇。
终身拟作卧云伴，逐月须收烧药钱。
五品足为婚嫁主，绯袍着了好归田。','',''),('quantangshi-23150','初着绯戏赠元九','白居易','quantangshi','','卷24','晚遇缘才拙，先衰被病牵。
那知垂白日，始是着绯年。
身外名徒尔，人间事偶然。
我朱君紫绶，犹未得差肩。','',''),('quantangshi-23151','和韩侍郎苦雨','白居易','quantangshi','','卷24','润气凝柱础，繁声注瓦沟。
暗留窗不晓，凉引簟先秋。
叶湿蚕应病，泥稀燕亦愁。
仍闻放朝夜，误出到街头。','',''),('quantangshi-23152','连雨','白居易','quantangshi','','卷24','风雨暗萧萧，鸡鸣暮复朝。
碎声笼苦竹，冷翠落芭蕉。
水鸟投檐宿，泥蛙入户跳。
仍闻蕃客见，明日欲追朝。','',''),('quantangshi-23153','初加朝散大夫又转上柱国','白居易','quantangshi','','卷24','紫微今日烟霄地，赤岭前年泥土身。
得水鱼还动鳞鬣，乘轩鹤亦长精神。
且慙身忝官阶贵，未敢家嫌活计贫。
柱国勋成私自问，有何功德及生人。','',''),('quantangshi-23154','行简初授拾遗同早朝入合因示十二韵','白居易','quantangshi','','卷24','夜色尚苍苍，槐阴夹路长。
听钟出长乐，传鼓到新昌。
宿雨沙堤润，秋风桦烛香。
马骄欺地软，人健得天凉。
待漏排阊阖，停珂拥建章。
尔随黄合老，吾次紫微郎。
并入连称籍，齐趋对折方。
鬬班花接萼，绰立雁分行。
近职诚为美，微才岂合当。
纶言难下笔，谏纸易盈箱。
老去何侥幸，时来不料量。
唯求杀身地，相誓答恩光。','',''),('quantangshi-23155','立秋日登乐游园','白居易','quantangshi','','卷24','独行独语曲江头，回马迟迟上乐游。
萧飒凉风与衰鬓，谁教计会一时秋。','',''),('quantangshi-23156','新秋早起有怀元少尹','白居易','quantangshi','','卷24','秋来转觉此身衰，晨起临阶盥漱时。
漆匣镜明头尽白，铜瓶水冷齿先知。
光阴纵惜[留难]住，官职虽荣得已迟。
老去相逢无别计，强开笑口展愁眉。','',''),('quantangshi-23157','夜筝','白居易','quantangshi','','卷24','紫袖红弦明月中，自弹自感暗低容。
弦凝指咽声停处，别有深情一万重。','',''),('quantangshi-23158','妻初授邑号告身','白居易','quantangshi','','卷24','弘农旧县授新封，钿轴金泥诰一通。
我转官阶常自愧，君加邑号有何功。
花笺印了排窠湿，锦褾装来耀手红。
倚得身名便慵堕，日高犹睡绿窗中。','',''),('quantangshi-23159','送客南迁','白居易','quantangshi','','卷24','我说南中事，君应不愿听。
曾经身困苦，不觉语叮咛。
烧处愁云梦，波时忆洞庭。
春畲烟勃勃，秋瘴露冥冥。
蚊蚋经冬活，鱼龙欲雨腥。
水虫能射影，山鬼解藏形。
穴掉巴蛇尾，林飘鸩鸟翎。
飓风千里黑，䕭草四时青。
客似惊弦雁，舟如委浪萍。
谁人劝言笑，何计慰漂零。
慎勿琴离膝，长须酒满瓶。
大都从此去，宜醉不宜醒。','',''),('quantangshi-23160','暮归','白居易','quantangshi','','卷24','不觉百年半，何曾一日闲。
朝随烛影出，暮趂鼓声还。
瓮里非无酒，墙头亦有山。
归来长困卧，早晚得开颜。','',''),('quantangshi-23161','寄远','白居易','quantangshi','','卷24','欲忘忘未得，欲去去无由。
两腋不生翅，二毛空满头。
坐看新落叶，行上最高楼。
暝色无边际，茫茫尽眼愁。','',''),('quantangshi-23162','旧房','白居易','quantangshi','','卷24','远壁秋声虫络丝，入檐新影月低眉。
牀帷半故帘旌断，仍是初寒欲夜时。','',''),('quantangshi-23163','钱侍郎使君以题庐山草堂诗见寄因酬之','白居易','quantangshi','','卷24','殷勤江郡守，怅望掖垣郎。
慙见新琼什，思归旧草堂。
事随心未得，名与道相妨。
若不休官去，人间到老忙。','',''),('quantangshi-23164','寄山僧','白居易','quantangshi','','卷24','眼看过半百，早晚扫岩扉。
白首谁能住，青山自不归。
百千万劫障，四十九年非。
会拟抽身去，当风斗擞衣。','',''),('quantangshi-23165','慈恩寺有感','白居易','quantangshi','','卷24','自问有何惆怅事，寺门临入却迟回。
李家哭泣元家病，柿叶红时独自来。','',''),('quantangshi-23166','酬严十八郎中见示','白居易','quantangshi','','卷24','口厌含香握厌兰，紫微青琐举头看。
忽惊鬓后苍浪发，未得心中本分官。
夜酌满容花色暖，秋吟切骨玉声寒。
承明长短君应入，莫忆家江七里滩。','',''),('quantangshi-23167','寄王祕书','白居易','quantangshi','','卷24','霜菊花萎日，风梧叶碎时。
怪来秋思苦，缘咏秘书诗。','',''),('quantangshi-23168','中书寓直','白居易','quantangshi','','卷24','缭绕宫墙围禁林，半开阊阖晓沈沈。
天晴更觉南山近，月出方知西掖深。
病对词头惭彩笔，老看镜面愧华簪。
自嫌野物将何用，土木形骸麋鹿心。','',''),('quantangshi-23169','自问','白居易','quantangshi','','卷24','黑花满眼丝满头，早衰因病病因愁。
宦途气味已谙尽，五十不休何日休。','',''),('quantangshi-23170','曲江独行招张十八','白居易','quantangshi','','卷24','曲江新岁后，冰与水相和。
南岸犹残雪，东风未有波。
偶游身独自，相忆意如何。
莫待春深去，花时鞍马多。','',''),('quantangshi-23171','新居早春二首 一','白居易','quantangshi','','卷24','静巷无来客，深居不出门。
铺沙盖苔面，扫雪拥松根。
渐暖宜闲步，初晴爱小园。
觅花都未有，唯觉树枝繁。','',''),('quantangshi-23172','新居早春二首 二','白居易','quantangshi','','卷24','地润东风暖，闲行蹋草芽。
呼童遣移竹，留客伴尝茶。
溜滴檐冰尽，尘浮隟日斜。
新居未曾到，邻里是谁家。','',''),('quantangshi-23173','新昌新居书事四十韵因寄元郎中张博士','白居易','quantangshi','','卷24','冒宠已三迁，归期始二年。
囊中贮余俸，园外买闲田。
狐兔同三迳，蒿莱共一壥。
新园聊刬秽，旧屋且扶颠。
檐漏移倾瓦，梁欹换蠹椽。
平治遶台路，整顿近阶甎。
巷狭开容驾，墙低垒过肩。
门闾堪驻盖，堂室可铺筵。
丹凤楼当后，青龙寺在前。
市街尘不到，宫树影相连。
省史嫌坊远，豪家笑地偏。
敢劳宾客访，或望子孙传。
不觅他人爱，唯将自性便。
等闲栽树木，随分占风烟。
逸致因心得，幽期遇境牵。
松声疑涧底，草色胜河边。
虚润冰销地，晴和日出天。
苔行滑如簟，莎坐软于绵。
帘每当山卷，帷多带月褰。
篱东花掩映，窗北竹婵娟。
迹慕青门隐，名慙紫禁仙。
假归思晚沐，朝去恋春眠。
拙薄才无取，疎慵职不专。
题墙书命笔，沽酒率分钱。
柏杵舂灵药，铜瓶漱暖泉。
炉香穿盖散，笼烛隔纱然。
陈室何曾扫，陶琴不要弦。
屏除俗事尽，养活道情全。
尚有妻孥累，犹为组绶缠。
终须抛爵禄，渐拟断腥膻。
大抵宗庄叟，私心事竺干。
浮荣水划字，真谛火生莲。
梵部经十二，玄书字五千。
是非都付梦，语默不妨禅。
博士官犹冷，郎中病已痊。
多同僻处住，久结静中缘。
缓步携筇杖，徐吟展蜀笺。
老宜闲语话，闷忆好诗篇。
蛮榼来方泻，蒙茶到始煎。
无辞数相见，鬓发各苍然。','',''),('quantangshi-23174','喜敏中及第偶示所怀','白居易','quantangshi','','卷24','自知羣从为儒少，岂料词场中第频。
桂折一枝先许我，杨穿三叶尽惊人。
转于文墨须留意，贵向烟霄早致身。
莫学尔兄年五十，蹉跎始得掌丝纶。','',''),('quantangshi-23175','久不见韩侍郎戏题四韵以寄之','白居易','quantangshi','','卷24','近来韩合老，疎我我心知。
户大嫌甜酒，才高笑小诗。
静吟乖月夜，闲醉旷花时。
还有愁同处，春风满鬓丝。','',''),('quantangshi-23176','寄白头陀','白居易','quantangshi','','卷24','近见头陀伴，云师老更慵。
性灵闲似鹤，颜状古于松。
山里犹难觅，人间岂易逢。
仍闻移住处，太白最高峰。','',''),('quantangshi-23177','和韩侍郎题杨舍人林池见寄','白居易','quantangshi','','卷24','渠水暗流春冻解，风吹日炙不成凝。
凤池冷暖君谙在，二月因何更有冰。','',''),('quantangshi-23178','勤政楼西老柳','白居易','quantangshi','','卷24','半朽临风树，多情立马人。
开元一株柳，长庆二年春。','',''),('quantangshi-23179','偶题合下厅','白居易','quantangshi','','卷24','静爱青苔院，深宜白鬓翁。
貌将松共瘦，心与竹俱空。
暖有低檐日，春多扬幕风。
平生闲境界，尽在五言中。','',''),('quantangshi-23180','予与故刑部李侍郎早结道友以药术为事与故京兆元尹晚为诗侣有林泉之期周岁之间二君长逝李住曲江北元居升平西追感旧游因贻同志','白居易','quantangshi','','卷24','从哭李来伤道气，自亡元后减诗情。
金丹同学都无益，水竹邻居竟不成。
月夜若为游曲水，花时那忍到升平。
如年七十身犹在，但恐伤心无处行。','',''),('quantangshi-23181','送冯舍人合老往襄阳','白居易','quantangshi','','卷24','紫微合底送君回，第二厅帘下不开。
莫恋汉南风景好，岘山花尽早归来。','',''),('quantangshi-23182','莫走柳条词送别','白居易','quantangshi','','卷24','南陌伤心别，东风满把春。
莫欺杨柳弱，劝酒胜于人。','',''),('quantangshi-23183','酬韩侍郎张博士雨后游曲江见寄','白居易','quantangshi','','卷24','小园新种红樱树，闲遶花行便当游。
何必更随鞍马队，冲泥蹋雨曲江头。','',''),('quantangshi-23184','元家花','白居易','quantangshi','','卷24','今日元家宅，樱桃发几枝。
稀稠与颜色，一似去年时。
失却东园主，春风可得知。','',''),('quantangshi-23185','代人赠王员外','白居易','quantangshi','','卷24','好在王员外，平生记得不。
共赊黄叟酒，同上莫愁楼。
静接殷勤语，狂随烂熳游。
那知今日眼，相见冷于秋。','',''),('quantangshi-23186','惜小园花','白居易','quantangshi','','卷24','晓来红萼凋零尽，但见空枝四五株。
前日狂风昨夜雨，残芳更合得存无。','',''),('quantangshi-23187','萧相公宅遇自远禅师有感而赠','白居易','quantangshi','','卷24','宦途堪笑不胜悲，昨日荣华今日衰。
转似秋蓬无定处，长于春梦几多时。
半头白发慙萧相，满面红尘问远师。
应是世间缘未尽，欲抛官去尚迟疑。','',''),('quantangshi-23188','草词毕遇芍药初开因咏小谢红药当阶翻诗以为一句未尽其状偶成十六韵','白居易','quantangshi','','卷24','罢草紫泥诏，起吟红药诗。
词头封送后，花口拆开时。
坐对钩帘久，行观步履迟。
两三丛烂熳，十二叶参差。
背日房微歛，当阶朵旋欹。
钗葶抽碧股，粉蘂扑黄丝。
动荡情无限，低斜力不支。
周回看未足，比谕语难为。
句漏丹砂里，僬侥火焰旗。
彤云剩根蒂，绛帻欠缨緌。
况有晴风度，仍兼宿露垂。
疑香薰罨画，似泪着胭脂。
有意留连我，无言怨思谁。
应愁明日落，如恨隔年期。
菡萏泥连萼，玫瑰刺绕枝。
等量无胜者，唯眼与心知。','',''),('quantangshi-23189','喜张十八博士除水部员外郎','白居易','quantangshi','','卷24','老何殁后吟声绝，虽有郎官不爱诗。
无复篇章传道路，空流风月在曹司。
长嗟博士官犹屈，亦恐骚人道渐衰。
今日闻君除水部，喜于身得省郎时。','',''),('quantangshi-23190','与沈杨二舍人合老同食勅赐樱桃翫物感恩因成十四韵','白居易','quantangshi','','卷24','清晓趋丹禁，红缨降紫宸。
驱禽养得熟，和叶摘来新。
圆转盘倾玉，鲜明笼透银。
内园题两字，西掖赐三臣。
荧惑晶华赤，醍醐气味真。
如珠未穿孔，似火不烧人。
杏俗难为对，桃顽讵可伦。
肉嫌卢橘厚，皮笑荔枝皴。
琼液酸甜足，金丸大小匀。
偷须防曼倩，惜莫掷安仁。
手擘才离核，匙抄半是津。
甘为舌上露，暖作腹中春。
已惧长尸禄，仍惊数食珍。
最慙恩未报，饱餧不才身。','',''),('quantangshi-23191','送严大夫赴桂州','白居易','quantangshi','','卷24','地压坤方重，官兼宪府雄。
桂林无瘴气，柏署有清风。
山水衙门外，旌旗艛艓中。
大夫应绝席，诗酒与谁同。','',''),('quantangshi-23192','春夜宿直','白居易','quantangshi','','卷24','三月十四夜，西垣东北廊。
碧梧叶重叠，红药树低昂。
月砌漏幽影，风帘飘暗香。
禁中无宿客，谁伴紫微郎。','',''),('quantangshi-23193','夏夜宿直','白居易','quantangshi','','卷24','人少庭宇旷，夜凉风露清。
槐花满院气，松子落堦声。
寂寞挑灯坐，沈吟蹋月行。
年衰自无趣，不是厌承明。','',''),('quantangshi-23194','七言十二句赠驾部吴郎中七兄','白居易','quantangshi','','卷24','四月天气和且清，绿槐阴合沙堤平。
独骑善马衔镫稳，初着单衣肢体轻。
退朝下直少徒侣，归舍闭门无送迎。
风生竹夜窗间卧，月照松时台上行。
春酒冷尝三数盏，晓琴闲弄十余声。
幽怀静境何人别，唯有南宫老驾兄。','',''),('quantangshi-23195','玉真张观主下小女冠阿容','白居易','quantangshi','','卷24','绰约小天仙，生来十六年。
姑山半峰雪，瑶水一枝莲。
晚院花留立，春窗月伴眠。
回眸虽欲语，阿母在傍边。','',''),('quantangshi-23196','龙花寺主家小尼','白居易','quantangshi','','卷24','头青眉眼细，十四女沙弥。
夜静双林怕，春深一食饥。
步慵行道困，起晚诵经迟。
应似仙人子，花宫未嫁时。','',''),('quantangshi-23197','访陈二','白居易','quantangshi','','卷24','晓垂朱绶带，晚着白纶巾。
出去为朝客，归来是野人。
两飱聊过日，一榻足容身。
此外皆闲事，时时访老陈。','',''),('quantangshi-23198','晚亭逐凉','白居易','quantangshi','','卷24','送客出门后，移牀下砌初。
趂凉行绕竹，引睡卧看书。
老更为官拙，慵多向事疎。
松窗倚藤杖，人道似僧居。','',''),('quantangshi-23199','曲江忆李十一','白居易','quantangshi','','卷24','李君殁后共谁游，柳岸荷亭两度秋。
独绕曲江行一匝，依前还立水边愁。','',''),('quantangshi-23200','江亭翫春','白居易','quantangshi','','卷24','江亭乘晓阅众芳，春妍景丽草树光。
日消石桂绿岚气，风坠木兰红露浆。
水蒲渐展书带叶，山榴半含琴轸房。
何物春风吹不变，愁人依旧鬓苍苍。','',''),('quantangshi-23201','闻夜砧','白居易','quantangshi','','卷24','谁家思妇秋捣帛，月苦风凄砧杵悲。
八月九日正长夜，千声万声无了时。
应到天明头尽白，一声添得一茎丝。','',''),('quantangshi-23202','板桥路','白居易','quantangshi','','卷24','梁苑城西二十里，一渠春水柳千条。
若为此路今重过，十五年前旧板桥。
曾共玉颜桥上别，不知消息到今朝。','',''),('quantangshi-23203','青门柳','白居易','quantangshi','','卷24','青青一树伤心色，曾入几人离恨中。
为近都门多送别，长条折尽减春风。','',''),('quantangshi-23204','梨园弟子','白居易','quantangshi','','卷24','白头垂泪话梨园，五十年前雨露恩。
莫问华清今日事，满山红叶鏁宫门。','',''),('quantangshi-23205','暮江吟','白居易','quantangshi','','卷24','一道残阳铺水中，半江瑟瑟半江红。
可怜九月初三夜，露似真珠月似弓。','',''),('quantangshi-23206','思妇眉','白居易','quantangshi','','卷24','春风摇荡自东来，折尽樱桃绽尽梅。
惟余思妇愁眉结，无限春风吹不开。','',''),('quantangshi-23207','怨词','白居易','quantangshi','','卷24','夺宠心那惯，寻思倚殿门。
不知移旧爱，何处作新恩。','',''),('quantangshi-23208','空闺怨','白居易','quantangshi','','卷24','寒月沈沈洞房静，真珠帘外梧桐影。
秋霜欲下手先知，灯底裁缝剪刀冷。','',''),('quantangshi-23209','秋房夜','白居易','quantangshi','','卷24','云露青天月漏光，中庭立久却归房。
水窗席冷未能卧，挑尽残灯秋夜长。','',''),('quantangshi-23210','采莲曲','白居易','quantangshi','','卷24','菱叶萦波荷颭风，荷花深处小船通。
逢郎欲语低头笑，碧玉搔头落水中。','',''),('quantangshi-23211','邻女','白居易','quantangshi','','卷24','娉婷十五胜天仙，白日姮娥旱地莲。
何处闲教鹦鹉语，碧纱窗下绣牀前。','',''),('quantangshi-23212','闺妇','白居易','quantangshi','','卷24','斜凭绣牀愁不动，红绡带缓绿鬟低。
辽阳春尽无消息，夜合花前日又西。','',''),('quantangshi-23213','移牡丹栽','白居易','quantangshi','','卷24','金钱买得牡丹栽，何处辞丛别主来？红芳堪惜还堪恨，百处移将百处开。','',''),('quantangshi-23214','听夜筝有感','白居易','quantangshi','','卷24','江州去日听筝夜，白发新生不愿闻。
如今格是头成雪，弹到天明亦任君。','',''),('quantangshi-23215','代谢好妓答崔员外','白居易','quantangshi','','卷24','青娥小谢娘，白发老崔郎。
谩爱胸前雪，其如头上霜。
别后曹家碑背上，思量好字断君肠。','',''),('quantangshi-23216','琵琶','白居易','quantangshi','','卷24','弦清拨剌语铮铮，背却残灯就月明。
赖是心无惆怅事，不然争奈子弦声。','',''),('quantangshi-23217','和殷协律琴思','白居易','quantangshi','','卷24','秋水莲冠春草帬，依稀风调似文君。
烦君玉指分明语，知是琴心佯不闻。','',''),('quantangshi-23218','寄李苏州兼示杨琼','白居易','quantangshi','','卷24','真娘墓头春草碧，心奴鬓上秋霜白。
为问苏台酒席中，使君歌笑与谁同。
就中犹有杨琼在，堪上东山伴谢公。','',''),('quantangshi-23219','听弹湘妃怨','白居易','quantangshi','','卷24','玉轸朱弦瑟瑟徽，吴娃征调奏湘妃。
分明曲里愁云雨，似道萧萧郎不归。','',''),('quantangshi-23220','闲坐','白居易','quantangshi','','卷24','暖拥红炉火，闲搔白发头。
百年慵里过，万事醉中休。
有室同摩诘，无儿比邓攸。
莫论身在日，身后亦无忧。','',''),('quantangshi-23221','不睡','白居易','quantangshi','','卷24','焰短寒缸尽，声长晓漏迟。
年衰自无睡，不是守三尸。','',''),('quantangshi-23222','初罢中书舍人','白居易','quantangshi','','卷24','自慙拙宦叨清贵，还有痴心怕素餐。
或望君臣相献替，可图妻子免饥寒。
性疎岂合承恩久，命薄元知济事难。
分寸宠光酬未得，不休更拟觅何官。','',''),('quantangshi-23223','宿阳城驿对月','白居易','quantangshi','','卷24','亲故寻回驾，妻孥未出关。
凤皇池上月，送我过商山。','',''),('quantangshi-23224','商山路有感','白居易','quantangshi','','卷24','忆昨征还日，三人归路同。
此生都是梦，前事旋成空。
杓直泉埋玉，虞平烛过风。
唯残乐天在，头白向江东。','',''),('quantangshi-23225','重感','白居易','quantangshi','','卷24','停骖歇路隅，重感一长吁。
扰扰生还死，纷纷荣又枯。
困支青竹杖，闲捋白髭须。
莫叹身衰老，交游半已无。','',''),('quantangshi-23226','逢张十八员外籍','白居易','quantangshi','','卷24','旅思正茫茫，相逢此道傍。
晓岚林叶暗，秋露草花香。
白发江城守，青衫水部郎。
客亭同宿处，忽似夜归乡。','',''),('quantangshi-23227','赴杭州重宿棣华驿见杨八旧诗感题一绝','白居易','quantangshi','','卷24','往恨今愁应不殊，题诗梁下又踟蹰。
羡君犹梦见兄弟，我到天明睡亦无。','',''),('quantangshi-23228','寓言题僧','白居易','quantangshi','','卷24','劫风火起烧荒宅，苦海波生荡破船。
力小无因救焚溺，清凉山下且安禅。','',''),('quantangshi-23229','内乡村路作','白居易','quantangshi','','卷24','日下风高野路凉，缓驱疲马暗思乡。
渭村秋物应如此，枣赤梨红稻穗黄。','',''),('quantangshi-23230','路上寄银匙与阿龟','白居易','quantangshi','','卷24','谪宦心都惯，辞乡去不难。
缘留龟子住，涕泪一阑干。
小子须娇养，邹婆为好看。
银匙封寄汝，忆我即加餐。','',''),('quantangshi-23231','山泉煎茶有怀','白居易','quantangshi','','卷24','坐酌泠泠水，看煎瑟瑟尘。
无由持一盌，寄与爱茶人。','',''),('quantangshi-23232','郢州赠别王八使君','白居易','quantangshi','','卷24','昔是诗狂客，今为酒病夫。
强饮翻怅望，纵醉不欢娱。
鬓发三分白，交亲一半无。
郢城君莫厌，犹校近京都。','',''),('quantangshi-23233','吉祥寺见钱侍郎题名','白居易','quantangshi','','卷24','云雨三年别，风波万里行。
愁来正萧索，况见古人名。','',''),('quantangshi-23234','重到江州感旧游题郡楼十一韵','白居易','quantangshi','','卷24','掌纶知是忝，剖竹信为荣。
才薄官仍重，恩深责尚轻。
昔征从典午，今出自承明。
凤诏休挥翰，渔歌欲濯缨。
还乘小艛艓，却到古湓城。
醉客临江待，禅僧出郭迎。
青山满眼在，白发半头生。
又校三年老，何曾一事成。
重过萧寺宿，再上庾楼行。
云水新秋思，闾阎旧日情。
郡民犹认得，司马咏诗声。','',''),('quantangshi-23235','赠江州李十使君员外十二韵','白居易','quantangshi','','卷24','我本江湖上，悠悠任运身。
朝随卖药客，暮伴钓鱼人。
迹为烧丹隐，家缘嗜酒贫。
经过剡溪雪，寻觅武陵春。
岂有疎狂性，堪为侍从臣。
仰头惊凤阙，下口触龙鳞。
劒佩辞天上，风波向海滨。
非贤虚偶圣，无屈感求伸。
昔去曾同日，今来即后尘。
中年俱白发，左宦各朱轮。
长短才虽异，荣枯事略均。
殷勤李员外，不合不相亲。','',''),('quantangshi-23236','题别遗爱草堂兼呈李十使君','白居易','quantangshi','','卷24','曾住炉峰下，书堂对药台。
斩新萝径合，依旧竹窗开。
砌水亲开决，池荷手自栽。
五年方暂至，一宿又须回。
纵未长归得，犹胜不到来。
君家白鹿洞，闻道亦生苔。','',''),('quantangshi-23237','重题','白居易','quantangshi','','卷24','泉石尚依依，林疎僧亦稀。
何年辞水阁，今夜宿云扉。
谩献长杨赋，虚抛薜荔衣。
不能成一事，赢得白头归。','',''),('quantangshi-23238','夜泊旅望','白居易','quantangshi','','卷24','少睡多愁客，中宵起望乡。
沙明连浦月，帆白满船霜。
近海江弥阔，迎秋夜更长。
烟波三十宿，犹未到钱唐。','',''),('quantangshi-23239','九江北岸遇风雨','白居易','quantangshi','','卷24','黄梅县边黄梅雨，白头浪里白头翁。
九江阔处不见岸，五月尽时多恶风。
人间稳路应无限，何事抛身在此中。','',''),('quantangshi-23240','舟中晚起','白居易','quantangshi','','卷24','日高犹掩水窗眠，枕簟清凉八月天。
泊处或依沽酒店，宿时多伴钓鱼船。
退身江海应无用，忧国朝廷自有贤。
且向钱唐湖上去，冷吟闲醉二三年。','',''),('quantangshi-23241','秋寒','白居易','quantangshi','','卷24','雪鬓年颜老，霜庭景气秋。
病看妻检药，寒遣婢梳头。
身外名何有，人间事且休。
澹然方寸内，唯拟学虚舟。','',''),('quantangshi-23242','初到郡斋寄钱湖州李苏州','白居易','quantangshi','','卷24','俱来沧海郡，半作白头翁。
谩道风烟接，何曾笑语同。
吏稀秋税毕，客散晚庭空。
霁后当楼月，潮来满座风。
霅溪殊冷僻，茂苑太繁雄。
唯此钱唐郡，闲忙恰得中。','',''),('quantangshi-23243','对酒自勉','白居易','quantangshi','','卷24','五十江城守，停杯一自思。
头仍未尽白，官亦不全卑。
荣宠寻过分，欢娱已校迟。
肺伤虽怕酒，心健尚夸诗。
夜舞吴娘袖，春歌蛮子词。
犹堪三五岁，相伴醉花时。','',''),('quantangshi-23244','郡楼夜宴留客','白居易','quantangshi','','卷24','北客劳相访，东楼为一开。
褰帘待月出，把火看潮来。
艳听竹枝曲，香传莲子杯。
寒天殊未晓，归骑却迟回。','',''),('quantangshi-23245','醉题候仙亭','白居易','quantangshi','','卷24','蹇步垂朱绶，华缨映白须。
何因驻衰老，只有且欢娱。
酒兴还应在，诗情可便无。
登山与临水，犹未要人扶。','',''),('quantangshi-23246','东院','白居易','quantangshi','','卷24','松下轩廊竹下房，暖檐晴日满绳牀。
净名居士经三卷，荣启先生琴一张。
老去齿衰嫌橘醋，病来肺渴觉茶香。
有时闲酌无人伴，独自腾腾入醉乡。','',''),('quantangshi-23247','虚白堂','白居易','quantangshi','','卷24','虚白堂前衙退后，更无一事到中心。
移牀就日檐间卧，卧咏闲诗侧枕琴。','',''),('quantangshi-23248','闲夜咏怀因招周协律刘薛二秀才','白居易','quantangshi','','卷24','世名检束为朝士，心性疎慵是野夫。
高置寒灯如客店，深藏夜火似僧炉。
香浓酒熟能尝否，冷澹诗成肯和无。
若厌雅吟须俗饮，妓筵勉力为君铺。','',''),('quantangshi-23249','晚兴','白居易','quantangshi','','卷24','极浦收残雨，高城驻落晖。
山明虹半出，松暗鹤双归。
将吏随衙散，文书入务稀。
闲吟倚新竹，筠粉污朱衣。','',''),('quantangshi-23250','衰病','白居易','quantangshi','','卷24','老与病相仍，华簪发不胜。
行多朝散药，睡少夜停灯。
禄食分供鹤，朝衣减施僧。
性多移不得，郡政谩如绳。','',''),('quantangshi-23251','病中对病鹤','白居易','quantangshi','','卷24','同病病夫怜病鹤，精神不损翅翎伤。
未堪再举摩霄汉，只合相随觅稻粱。
但作悲吟和嘹唳，难将俗貌对昂藏。
唯应一事宜为伴，我发君毛俱似霜。','',''),('quantangshi-23252','夜归','白居易','quantangshi','','卷24','半醉闲行湖岸东，马鞭敲镫辔珑璁。
万株松树青山上，十里沙堤明月中。
楼角渐移当路影，潮头欲过满江风。
归来未放笙歌散，画戟门开蜡烛红。','',''),('quantangshi-23253','腊后岁前遇景咏意','白居易','quantangshi','','卷24','海梅半日柳微黄，冻水初融日欲长。
度腊都无苦霜霰，迎春先有好风光。
郡中起晚听衙鼓，城上行慵倚女墙。
公事渐闲身且健，使君殊未厌余杭。','',''),('quantangshi-23254','白发','白居易','quantangshi','','卷24','雪发随梳落，霜毛绕鬓垂。
加添老气味，改变旧容仪。
不肯长如漆，无过总作丝。
最憎明镜里，黑白半头时。','',''),('quantangshi-23255','钱湖州以箬下酒李苏州以五酘酒相次寄到无因饮聊咏所怀','白居易','quantangshi','','卷24','劳将箬下忘忧物，寄与江城爱酒翁。
铛脚三州何处会，瓮头一盏几时同。
倾如竹叶盈樽绿，饮作桃花上面红。
莫怪殷勤醉相忆，曾陪西省与南宫。','',''),('quantangshi-23256','花楼望雪命宴赋诗','白居易','quantangshi','','卷24','连天际海白皑皑，好上高楼望一回。
何处更能分道路，此时兼不认池台。
万重云树山头翠，百尺花楼江畔开。
素壁联题分韵句，红炉巡饮暖寒杯。
冰铺湖水银为面，风卷汀沙玉作堆。
绊惹舞人春艳曳，句留醉客夜裴回。
输将虚白堂前鹤，失却樟亭驿后梅。
别有故情偏忆得，曾经穷苦照书来。','',''),('quantangshi-23257','晚岁','白居易','quantangshi','','卷24','壮岁忽已去，浮荣何足论。
身为百口长，官是一州尊。
不觉白双鬓，徒言朱两轓。
病难施郡政，老未答君恩。
岁暮别兄弟，年衰无子孙。
惹愁谙世网，治苦赖空门。
擥带知腰瘦，看灯觉眼昏。
不缘衣食系，寻合返丘园。','',''),('quantangshi-23258','宿竹阁','白居易','quantangshi','','卷24','晚坐松檐下，宵眠竹阁间。
清虚当服药，幽独抵归山。
巧未能胜拙，忙应不及闲。
无劳别修道，即此是玄关。','',''),('quantangshi-23259','岁暮枉衢州张使君书并诗因以长句报之','白居易','quantangshi','','卷24','西州彼此意何如，官职蹉跎岁欲除。
浮石潭边停五马，望涛楼上得双鱼。
万言旧手才难敌，五字新题思有余。
贫薄诗家无好物，反投桃李报琼琚。','',''),('quantangshi-23260','和薛秀才寻梅花同饮见赠','白居易','quantangshi','','卷24','忽惊林下发寒梅，便试花前饮冷杯。
白马走迎诗客去，红筵铺待舞人来。
歌声怨处微微落，酒气熏时旋旋开。
若到岁寒无雨雪，犹应醉得两三回。','',''),('quantangshi-23261','与诸客空腹饮','白居易','quantangshi','','卷24','隔宿书招客，平明饮暖寒。
麴神寅日合，酒圣卯时欢。
促膝才飞白，酡颜已渥丹。
碧筹攒米盌，红袖拂骰盘。
醉后歌尤异，狂来舞不难。
抛杯语同坐，莫作老人看。','',''),('quantangshi-23262','小岁日对酒吟钱湖州所寄诗','白居易','quantangshi','','卷24','独酌无多兴，闲吟有所思。
一杯新岁酒，两句故人诗。
杨柳初黄日，髭须半白时。
蹉跎春气味，彼此老心知。','',''),('quantangshi-23263','钱唐湖春行','白居易','quantangshi','','卷24','孤山寺北贾亭西，水面初平云脚低。
几处早莺争暖树，谁家新燕啄春泥。
乱花渐欲迷人眼，浅草才能没马蹄。
最爱湖东行不足，绿杨阴里白沙堤。','',''),('quantangshi-23264','题灵隐寺红辛夷花戏酬光上人','白居易','quantangshi','','卷24','紫粉笔含尖火焰，红胭脂染小莲花。
芳情乡思知多少，恼得山僧悔出家。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-23265','重向火','白居易','quantangshi','','卷24','火销灰复死，疎弃已经旬。
岂是人情薄，其如天气春。
风寒忽再起，手冷重相亲。
却就红炉坐，心如逢故人。','',''),('quantangshi-23266','候仙亭同诸客醉作','白居易','quantangshi','','卷24','谢安山下空携妓，柳恽洲边只赋诗。
争及湖亭今日会，嘲花咏水赠蛾眉。','',''),('quantangshi-23267','城上','白居易','quantangshi','','卷24','城上冬冬鼓，朝衙复晚衙。
为君慵不出，落尽遶城花。','',''),('quantangshi-23268','早行林下','白居易','quantangshi','','卷24','披衣未冠栉，晨起入前林。
宿露残花气，朝光新叶阴。
傍松人迹少，隔竹鸟声深。
闲倚小桥立，倾头时一吟。','',''),('quantangshi-23269','送李校书趂寒食归义兴山居','白居易','quantangshi','','卷24','大见腾腾诗酒客，不忧生计似君稀。
到舍将何作寒食，满船唯载树阴归。','',''),('quantangshi-23270','题孤山寺山石榴花示诸僧众','白居易','quantangshi','','卷24','山榴花似结红巾，容艳新妍占断春。
色相故关行道地，香尘拟触坐禅人。
瞿昙弟子君知否，恐是天魔女化身。','',''),('quantangshi-23271','独行','白居易','quantangshi','','卷24','暗诵黄庭经在口，闲携青竹杖随身。
晚花新笋堪为伴，独入林行不要人。','',''),('quantangshi-23272','二月五日花下作','白居易','quantangshi','','卷24','二月五日花如雪，五十二人头似霜。
闻有酒时须笑乐，不关身事莫思量。
羲和趂日沈西海，鬼伯驱人葬北邙。
只有且来花下醉，从人笑道老颠狂。','',''),('quantangshi-23273','戏题木兰花','白居易','quantangshi','','卷24','紫房日照胭脂拆，素艳风吹腻粉开。
怪得独饶脂粉态，木兰曾作女郎来。','',''),('quantangshi-23274','清明日观妓舞听客诗','白居易','quantangshi','','卷24','看舞颜如玉，听诗韵似金。
绮罗从许笑，弦管不妨吟。
可惜春风老，无嫌酒盏深。
辞花送寒食，并在此时心。','',''),('quantangshi-23275','西湖晚归回望孤山寺赠诸客','白居易','quantangshi','','卷24','柳湖松岛莲花寺，晚动归桡出道场。
卢橘子低山雨重，棕榈叶战水风凉。
烟波澹荡摇空碧，楼殿参差倚夕阳。
到岸请君回首望，蓬莱宫在海中央。','',''),('quantangshi-23276','湖中自照','白居易','quantangshi','','卷24','重重照影看容鬓，不见朱颜见白丝。
失却少年无处觅，泥他湖水欲何为。','',''),('quantangshi-23277','赠苏炼师','白居易','quantangshi','','卷24','两鬓苍然心浩然，松窗深处药炉前。
携将道士通宵语，忘却花时尽日眠。
明镜嬾开长在匣，素琴欲弄半无弦。
犹嫌庄子多词句，只读逍遥六七篇。','',''),('quantangshi-23278','杭州春望','白居易','quantangshi','','卷24','望海楼明照曙霞，护江堤白蹋晴沙。
涛声夜入伍员庙，柳色春藏苏小家。
红袖织绫夸柿蒂，青旗沽酒趂梨花。
谁开湖寺西南路，草绿帬腰一道斜。','',''),('quantangshi-23279','饮散夜归赠诸客','白居易','quantangshi','','卷24','鞍马夜纷纷，香街起暗尘。
回鞭招饮妓，分火送归人。
风月应堪惜，杯觞莫厌频。
明朝三月尽，忍不送残春。','',''),('quantangshi-23280','湖亭晚归','白居易','quantangshi','','卷24','尽日湖亭卧，心闲事亦稀。
起因残醉醒，坐待晚凉归。
松雨飘藤帽，江风透葛衣。
柳堤行不厌，沙软絮霏霏。','',''),('quantangshi-23281','东楼南望八韵','白居易','quantangshi','','卷24','不厌东南望，江楼对海门。
风涛生有信，天水合无痕。
鷁带云帆动，鸥和雪浪翻。
鱼盐聚为市，烟火起成村。
日脚金波碎，峰头钿点繁。
送秋千里雁，报暝一声猿。
已豁烦襟闷，仍开病眼昏。
郡中登眺处，无胜此东轩。','',''),('quantangshi-23282','醉中酬殷协律','白居易','quantangshi','','卷24','泗水亭边一分散，浙江楼上重游陪。
挥鞭二十年前别，命驾三千里外来。
醉袖放狂相向舞，愁眉和笑一时开。
留君夜住非无分，且尽青娥红烛台。','',''),('quantangshi-23283','孤山寺遇雨','白居易','quantangshi','','卷24','拂波云色重，洒叶雨声繁。
水鹭双飞起，风荷一向翻。
空蒙连北岸，萧飒入东轩。
或拟湖中宿，留船在寺门。','',''),('quantangshi-23284','樟亭双樱树','白居易','quantangshi','','卷24','南馆西轩两树樱，春条长足夏阴成。
素华朱实今虽尽，碧叶风来别有情。','',''),('quantangshi-23285','湖上夜饮','白居易','quantangshi','','卷24','郭外迎人月，湖边醒酒风。
谁留使君饮，红烛在舟中。','',''),('quantangshi-23286','赠沙鸥','白居易','quantangshi','','卷24','老逼教垂白，官科遣着绯。
形骸虽有累，方寸却无机。
遇酒多先醉，逢山爱晚归。
沙鸥不知我，犹被隼旟飞。','',''),('quantangshi-23287','余杭形胜','白居易','quantangshi','','卷24','余杭形胜四方无，州傍青山县枕湖。
遶郭荷花三十里，拂城松树一千株。
梦儿亭古传名谢，教妓楼新道姓苏。
独有使君年太老，风光不称白髭须。','',''),('quantangshi-23288','江楼夕望招客','白居易','quantangshi','','卷24','海天东望夕茫茫，山势川形阔复长。
灯火万家城四畔，星河一道水中央。
风吹古木晴天雨，月照平沙夏夜霜。
能就江楼销暑否，比君茅舍较清凉。','',''),('quantangshi-23289','新秋病起','白居易','quantangshi','','卷24','一叶落梧桐，年光半又空。
秋多上阶日，凉足入怀风。
病瘦形如鹤，愁焦鬓似蓬。
损心诗思里，伐性酒狂中。
华盖何曾惜，金丹不致功。
犹须自慙愧，得作白头翁。','',''),('quantangshi-23290','木芙蓉花下招客饮','白居易','quantangshi','','卷24','晚凉思饮两三杯，召得江头酒客来。
莫怕秋无伴醉物，水莲花尽木莲开。','',''),('quantangshi-23291','悲歌','白居易','quantangshi','','卷24','白头新洗镜新磨，老逼身来不奈何。
耳里频闻故人死，眼前唯觉少年多。
塞鸿遇暖犹回翅，江水因潮亦反波。
独有衰颜留不得，醉来无计但悲歌。','',''),('quantangshi-23292','江楼晚眺景物鲜奇吟翫成篇寄水部张员外','白居易','quantangshi','','卷24','澹烟疎雨间斜阳，江色鲜明海气凉。
蜃散云收破楼阁，虹残水照断桥梁。
风翻白浪花千片，雁点青天字一行。
好着丹青图画取，题诗寄与水曹郎。','',''),('quantangshi-23293','夜招周协律兼答所赠','白居易','quantangshi','','卷24','满眼虽多客，开眉复向谁。
少年非我伴，秋夜与君期。
落魄俱耽酒，殷勤共爱诗。
相怜别有意，彼此老无儿。','',''),('quantangshi-23294','重酬周判官','白居易','quantangshi','','卷24','秋爱冷吟春爱醉，诗家眷属酒家仙。
若教早被浮名系，可得闲游三十年。','',''),('quantangshi-23295','饮后夜醒','白居易','quantangshi','','卷24','黄昏饮散归来卧，夜半人扶强起行。
枕上酒容和睡醒，楼前海月伴潮生。
将归梁燕还重宿，欲灭窗灯却复明。
直至晓来犹妄想，耳中如有管弦声。','',''),('quantangshi-23296','代卖薪女赠诸妓','白居易','quantangshi','','卷24','乱蓬为鬓布为巾，晓蹋寒山自负薪。
一种钱唐江畔女，着红骑马是何人。','',''),('quantangshi-23297','奉和李大夫题新诗二首各六韵 因严亭','白居易','quantangshi','','卷24','箕颍人穷独，蓬壶路阻难。
何如兼吏隐，复得事跻攀。
岩树罗阶下，江云贮栋间。
似移天目石，疑入武丘山。
清景徒堪赏，皇恩肯放闲。
遥知兴未足，即被诏征还。','',''),('quantangshi-23298','奉和李大夫题新诗二首各六韵 忘筌亭','白居易','quantangshi','','卷24','翠巘公门对，朱轩野径连。
只开新户牖，不改旧风烟。
虚室闲生白，高情澹入玄。
酒容同座劝，诗借属城传。
自笑沧江畔，遥思绛帐前。
亭台随处有，争敢比忘筌。','',''),('quantangshi-23299','予以长庆二年冬十月到杭州明年秋九月始与范阳卢贾汝南周元范兰陵萧悦清河崔求东莱刘方舆同游恩德寺之泉洞竹石籍甚久矣及兹目击果惬心期因自嗟云到郡周岁方来入寺半日复去俯视朱绶仰睇白云有愧于心遂留绝句','白居易','quantangshi','','卷24','云水埋藏恩德洞，簪裾束缚使君身。
暂来不宿归州去，应被山呼作俗人。','',''),('quantangshi-23300','早冬','白居易','quantangshi','','卷24','十月江南天气好，可怜冬景似春华。
霜经未杀萋萋草，日暖初干漠漠沙。
老柘叶黄如嫩树，寒樱枝白是狂花。
此时却羡闲人醉，五马无由入酒家。','',''),('quantangshi-23301','岁假内命酒赠周判官萧协律','白居易','quantangshi','','卷24','共知欲老流年急，且喜新正假日频。
闻健此时相劝醉，偷闲何处共寻春？
脚随周叟行犹疾，头比萧翁白未匀。
岁酒先拈辞不得，被君推作少年人。','',''),('quantangshi-23302','与诸客携酒寻去年梅花有感','白居易','quantangshi','','卷24','马上同携今日杯，湖边共觅去春梅。
年年只是人空老，处处何曾花不开。
诗思又牵吟咏发，酒酣闲唤管弦来。
樽前百事皆依旧，点检惟无薛秀才。','',''),('quantangshi-23303','醉送李协律赴湖南辟命因寄沈八中丞','白居易','quantangshi','','卷24','富阳山底樟亭畔，立马停舟飞酒盂。
曾共中丞情缱绻，暂留协律语踟蹰。
紫微星北承恩去，青草湖南称意无。
不羡君官羡君幕，幕中收得阮元瑜。','',''),('quantangshi-23304','内道场永讙上人就郡见访善说维摩经临别请诗因以此赠','白居易','quantangshi','','卷24','五夏登坛内殿师，水为心地玉为仪。
正传金粟如来偈，何用钱唐太守诗。
苦海出来应有路，灵山别后可无期。
他生莫忘今朝会，虚白亭中法乐时。','',''),('quantangshi-23305','见李苏州示男阿武诗自感成咏','白居易','quantangshi','','卷24','遥羡青云里，祥鸾正引雏。
自怜沧海伴，老蚌不生珠。','',''),('quantangshi-23306','正月十五日夜月','白居易','quantangshi','','卷24','岁熟人心乐，朝游复夜游。
春风来海上，明月在江头。
灯火家家市，笙歌处处楼。
无妨思帝里，不合厌杭州。','',''),('quantangshi-23307','题州北路傍老柳树','白居易','quantangshi','','卷24','皮枯缘受风霜久，条短为应攀折频。
但见半衰当此路，不知初种是何人。
雪花零碎逐年减，烟叶稀疎随分新。
莫道老株芳意少，逢春犹胜不逢春。','',''),('quantangshi-23308','题清头陀','白居易','quantangshi','','卷24','头陀独宿寺西峰，百尺禅庵半夜钟。
烟月苍苍风瑟瑟，更无杂树对山松。','',''),('quantangshi-23309','自叹二首 一','白居易','quantangshi','','卷24','形羸自觉朝飡减，睡少偏知夜漏长。
实事渐消虚事在，银鱼金带遶腰光。','',''),('quantangshi-23310','自叹二首 二','白居易','quantangshi','','卷24','二毛晓落梳头嬾，两眼春昏点药频。
唯有闲行犹得在，心情未到不如人。','',''),('quantangshi-23311','湖上醉中代诸妓寄严郎中','白居易','quantangshi','','卷24','笙歌杯酒正欢娱，忽忆仙郎望帝都。
借问连宵直南省，何如尽日醉西湖。
蛾眉别久心知否，鸡舌含多口厌无。
还有些些惆怅事，春来山路见蘼芜。','',''),('quantangshi-23312','自咏','白居易','quantangshi','','卷24','闷发每吟诗引兴，兴来兼酌酒开颜。
欲逢假日先招客，正对衙时亦望山。
句检簿书多卤莽，堤防官吏少机关。
谁能头白劳心力，人道无才也是闲。','',''),('quantangshi-23313','晚兴','白居易','quantangshi','','卷24','草浅马翩翩，新晴薄暮天。
柳条春拂面，衫袖醉垂鞭。
立语花堤上，行吟水寺前。
等闲消一日，不觉过三年。','',''),('quantangshi-23314','早兴','白居易','quantangshi','','卷24','晨光出照屋梁明，初打开门鼓一声。
犬上阶眠知地湿，鸟临窗语报天晴。
半销宿酒头仍重，新脱冬衣体乍轻。
睡觉心空思想尽，近来乡梦不多成。','',''),('quantangshi-23315','竹楼宿','白居易','quantangshi','','卷24','小书楼下千竿竹，深火炉前一盏灯。
此处与谁相伴宿，烧丹道士坐禅僧。','',''),('quantangshi-23316','湖上招客送春泛舟','白居易','quantangshi','','卷24','欲送残春招酒伴，客中谁最有风情。
两瓶箬下新开得，一曲霓裳初教成。
排比管弦行翠袖，指麾船舫点红旌。
慢牵好向湖心去，恰似菱花镜上行。','',''),('quantangshi-23317','戏醉客','白居易','quantangshi','','卷24','莫言鲁国书生懦，莫把杭州刺史欺。
醉客请君开眼望，绿杨风下有红旗。','',''),('quantangshi-23318','紫阳花','白居易','quantangshi','','卷24','何年植向仙坛上，早晚移栽到梵家。
虽在人间人不识，与君名作紫阳花。','',''),('quantangshi-23319','郡斋旬假始命宴呈座客示郡寮','白居易','quantangshi','','卷24','公门日两衙，公假月三旬。
衙用决簿领，旬以会亲宾。
公多及私少，劳逸常不均。
况为剧郡长，安得闲宴频。
下车已二月，开筵始今晨。
初黔军厨突，一拂郡蹋尘。
既备献酬礼，亦具水陆珍。
萍醅箬溪醑，水鲙松江鳞。
侑食乐悬动，佐懽妓席陈。
风流吴中客，佳丽江南人。
歌节点随袂，舞香遗在茵。
清奏凝未阕，酡颜气已春。
众宾勿遽起，羣寮且逡巡。
无轻一日醉，用犒九日勤。
微彼九日勤，何以治吾民。
微此一日醉，何以乐吾身。','',''),('quantangshi-23320','题西亭','白居易','quantangshi','','卷24','朝亦视簿书，暮亦视簿书。
簿书视未竟，蟋蟀鸣座隅。
始觉芳岁晚，复嗟尘务拘。
西园景多暇，可以少踌躇。
池鸟澹容与，桥柳高扶疎。
烟蔓袅青薜，水花披白蕖。
何人造兹亭，华敞绰有余。
四檐轩鸟翅，复屋罗蜘蛛。
直廊抵曲房，𥦖窱深且虚。
修竹夹左右，清风来徐徐。
此宜宴佳宾，鼓瑟吹笙竽。
荒淫即不可，废旷将何如。
幸有酒与乐，及时欢且娱。
忽其解郡印，他人来此居。','',''),('quantangshi-23321','郡中西园','白居易','quantangshi','','卷24','闲园多芳草，春夏香靡靡。
深树足佳禽，旦暮鸣不已。
院门闭松竹，庭径穿兰芷。
爱彼池上桥，独来聊徙倚。
鱼依藻长乐，鸥见人暂起。
有时舟随风，尽日莲照水。
谁知郡府内，景物闲如此。
始悟喧静缘，何尝系远迩。','',''),('quantangshi-23322','北亭卧','白居易','quantangshi','','卷24','树绿晚阴合，池凉朝气清。
莲开有佳色，鹤唳无凡声。
唯此闲寂境，惬我幽独情。
病假十五日，十日卧兹亭。
明朝吏呼起，还复视黎甿。','',''),('quantangshi-23323','一叶落','白居易','quantangshi','','卷24','烦暑郁未退，凉飙潜已起。
寒温与盛衰，遰相为表里。
萧萧秋林下，一叶忽先委。
勿言微摇落，摇落从此始。','',''),('quantangshi-23324','崔湖州赠红石琴荐焕如锦文无以答之以诗酬谢','白居易','quantangshi','','卷24','頳锦支绿绮，韵同相感深。
千年古涧石，八月秋堂琴。
引出山水思，助成金玉音。
人间无可比，比我与君心。','',''),('quantangshi-23325','九日宴集醉题郡楼兼呈周殷二判官','白居易','quantangshi','','卷24','前年九日余杭郡，呼宾命宴虚白堂。
去年九日到东洛，今年九日来吴乡。
两边蓬鬓一时白，三处菊花同色黄。
一日日知添老病，一年年觉惜重阳。
江南九月未摇落，柳青蒲绿稻穟香。
姑苏台榭倚苍霭，太湖山水含清光。
可怜假日好天色，公门吏静风景凉。
榜舟鞭马取宾客，扫楼拂席排壶觞。
胡琴铮鏦指拨刺，吴娃美丽眉眼长。
笙歌一曲思凝绝，金钿再拜光低昂。
日脚欲落备灯烛，风头渐高加酒浆。
觥盏艳飜菡萏叶，舞鬟摆落茱萸房。
半酣凭槛起四顾，七堰八门六十坊。
远近高低寺间出，东西南北桥相望。
水道脉分棹鳞次，里闾碁布城册方。
人烟树色无隙罅，十里一片青茫茫。
自问有何才与政，高厅大馆居中央。
铜鱼今乃泽国节，刺史是古吴都王。
郊无戎马郡无事，门有棨戟腰有章。
盛时傥来合惭愧，壮岁忽去还感伤。
从事醒归应不可，使君醉倒亦何妨。
请君停杯听我语，此语真实非虚狂。
五旬已过不为夭，七十为期盖是常。
须知菊酒登高会，从此多无二十场。','',''),('quantangshi-23326','同微之赠别郭虚舟炼师五十韵','白居易','quantangshi','','卷24','我为江司马，君为荆判司。
俱当愁悴日，始识虚舟师。
师年三十余，白皙好容仪。
专心在铅汞，余力工琴碁。
静弹弦数声，闲饮酒一巵。
因指尘土下，蜉蝣良可悲。
不闻姑射上，千岁冰雪肌。
不见辽城外，古今冢累累。
嗟我天地间，有术人莫知。
得可逃死籍，不唯走三尸。
授我参同契，其辞妙且微。
六一閟扃鐍，子午守雄雌。
我读随日悟，心中了无疑。
黄芽与紫车，谓其坐致之。
自负因自叹，人生号男儿。
若不佩金印，即合翳玉芝。
高谢人间世，深结山中期。
泥坛方合矩，铸鼎圆中䂓。
炉橐一以动，瑞气红辉辉。
斋心独叹拜，中夜偷一窥。
二物正欣合，厥状何怪奇。
绸缪夫妇体，狎猎鱼龙姿。
简寂馆钟后，紫霄峰晓时。
心尘未净洁，火候遂参差。
万寿觊刀圭，千功失毫厘。
先生弹指起，姹女随烟飞。
始知缘会间，阴隲不可移。
药竈今夕罢，诏书明日追。
追我复追君，次第承恩私。
官虽小大殊，同立白玉墀。
我直紫微闼，手进赏罚词。
君侍玉皇座，口含生杀机。
直躬易媒孽，浮俗多瑕疵。
转徙今安在，越峤吴江湄。
一提支郡印，一建连帅旗。
何言四百里，不见如天涯。
秋风旦夕来，白日西南驰。
雪霜各满鬓，朱紫徒为衣。
师从庐山洞，访旧来于斯。
寻君又觅我，风驭纷逶迤。
帔裾曳黄绢，须发垂青丝。
逢人但歛手，问道亦颔颐。
孤云难久留，十日告将归。
欵曲话平昔，殷勤勉衰羸。
后会杳何许，前心日磷缁。
俗家无异物，何以充别资。
素牋一百句，题附元家诗。
朱顶鹤一只，与师云间骑。
云间鹤背上，故情若相思。
时时摘一句，唱作步虚辞。','',''),('quantangshi-23327','霓裳羽衣歌','白居易','quantangshi','','卷24','我昔元和侍宪皇，曾陪内宴宴昭阳。
千歌百舞不可数，就中最爱霓裳舞。
舞时寒食春风天，玉钩栏下香案前。
案前舞者颜如玉，不着人家俗衣服。
虹裳霞帔步摇冠，钿璎累累佩珊珊。
娉婷似不任罗绮，顾听乐悬行复止。
磬箫筝笛遰相搀，击擫弹吹声逦迤。
散序六奏未动衣，阳台宿云慵不飞。
中序擘騞初入拍，秋竹竿裂春冰拆。
飘然转旋回雪轻，嫣然纵送游龙惊。
小垂手后柳无力，斜曳裾时云欲生。
烟蛾歛略不胜态，风袖低昂如有情。
上元点鬟招萼绿，王母挥袂别飞琼。
繁音急节十二徧，跳珠撼玉何铿铮。
翔鸾舞了却收翅，唳鹤曲终长引声。
当时乍见惊心目，凝视谛听殊未足。
一落人间八九年，耳冷不曾闻此曲。
湓城但听山魈语，巴峡唯闻杜鹃哭。
移领钱唐第二年，始有心情问丝竹。
玲珑箜篌谢好筝，陈宠觱栗沈平笙。
清弦脆管纤纤手，教得霓裳一曲成。
虚白亭前湖水畔，前后祗应三度按。
便除庶子抛却来，闻道如今各星散。
今年五月至苏州，朝钟暮角催白头。
贪看案牍常侵夜，不听笙歌直到秋。
秋来无事多闲闷，忽忆霓裳无处问。
闻君部内多乐徒，问有霓裳舞者无。
答云七县十万户，无人知有霓裳舞。
唯寄长歌与我来，题作霓裳羽衣谱。
四幅花牋碧间红，霓裳实录在其中。
千姿万状分明见，恰与[昭]阳舞者同。
眼前仿髴覩形质，昔日今朝想如一。
疑从魂梦呼召来，似着丹青图写出。
我爱霓裳君合知，发于歌咏形于诗。
君不见我歌云，惊破霓裳羽衣曲。
又不见我诗云，曲爱霓裳未拍时。
由来能事皆有主，杨氏创声君造谱。
君言此舞难得人，须是倾城可怜女。
吴妖小玉飞作烟，越艳西施化为土。
娇花巧笑久寂寥，娃馆苎萝空处所。
如君所言诚有是，君试从容听我语。
若求国色始翻传，但恐人间废此舞。
妍媸优劣宁相远，大都只在人抬举。
李娟张态君莫嫌，亦拟随宜且教取。','',''),('quantangshi-23328','小童薛阳陶吹觱栗歌','白居易','quantangshi','','卷24','剪削干芦插寒竹，九孔漏声五音足。
近来吹者谁得名，关璀老死李衮生。
衮今又老谁其嗣，薛氏乐童年十二。
指点之下师授声，含嚼之间天与气。
润州城高霜月明，吟霜思月欲发声。
山头江底何悄悄，猨声不喘鱼龙听。
翕然声作疑管裂，诎然声尽疑刀截。
有时婉软无筋骨，有时顿挫生棱节。
急声圆转促不断，轹轹辚辚似珠贯。
缓声展引长有条，有条直直如笔描。
下声乍坠石沈重，高声忽举云飘萧。
明旦公堂陈宴席，主人命乐娱宾客。
碎丝细竹徒纷纷，宫调一声雄出羣。
众音覼缕不落道，有如部伍随将军。
嗟尔阳陶方稚齿，下手发声已如此。
若教头白吹不休，但恐声名压关李。','',''),('quantangshi-23329','啄木曲','白居易','quantangshi','','卷24','莫买宝剪刀，虚费千金直。
我有心中愁，知君剪不得。
莫磨解结锥，徒劳人气力。
我有肠中结，知君解不得。
莫染红丝线，徒夸好颜色。
我有双泪珠，知君穿不得。
莫近红炉火，炎气徒相逼。
我有两鬓霜，知君销不得。
刀不能剪心愁，锥不能解肠结。
线不能穿泪珠，火不能销鬓雪。
不如饮此神圣杯，万念千忧一时歇。','',''),('quantangshi-23330','题灵岩寺','白居易','quantangshi','','卷24','娃宫屧廊寻已倾，砚池香径又欲平。
二三月时何草绿，几百年来空月明。
使君虽老颇多思，携觞领妓处处行。
今愁古恨入丝竹，一曲凉州无限情。
直自当时到今日，中间歌吹更无声。','',''),('quantangshi-23331','双石','白居易','quantangshi','','卷24','苍然两片石，厥状怪且丑。
俗用无所堪，时人嫌不取。
结从胚浑始，得自洞庭口。
万古遗水滨，一朝入吾手。
担舁来郡内，洗刷去泥垢。
孔黑烟痕深，罅青苔色厚。
老蛟蟠作足，古剑插为首。
忽疑天上落，不似人间有。
一可支吾琴，一可贮吾酒。
峭绝高数尺，坳泓容一斗。
五弦倚其左，一杯置其右。
洼樽酌未空，玉山颓已久。
人皆有所好，物各求其偶。
渐恐少年场，不容垂白叟。
回头问双石，能伴老夫否。
石虽不能言，许我为三友。','',''),('quantangshi-23332','宿东亭晓兴','白居易','quantangshi','','卷24','温温土炉火，耿耿纱笼烛。
独抱一张琴，夜入东斋宿。
窗声度残漏，帘影浮初旭。
头痒晓梳多，眼昏春睡足。
负暄檐宇下，散步池塘曲。
南雁去未回，东风来何速。
雪依瓦沟白，草遶墙根绿。
何言万户州，太守常幽独。','',''),('quantangshi-23333','日渐长赠周殷二判官','白居易','quantangshi','','卷24','日渐长，春尚早。
墙头半露红萼枝，池岸新铺绿芽草。
蹋草攀枝仰头叹，何人知此春怀抱。
年颜盛壮名未成，官职欲高身已老。
万茎白发真堪恨，一片绯衫何足道。
赖得君来劝一杯，愁开闷破心头好。','',''),('quantangshi-23334','花前叹','白居易','quantangshi','','卷24','前岁花前五十二，今年花前五十五。
岁课年功头发知，从霜成雪君看取。
几人得老莫自嫌，樊李吴韦尽成土。
南州桃李北州梅，且喜年年作花主。
花前置酒谁相劝，容坐唱歌满起舞。
欲散重拈花细看，争知明日无风雨。','',''),('quantangshi-23335','自咏五首 一','白居易','quantangshi','','卷24','朝亦随羣动，暮亦随羣动。
荣华瞬息间，求得将何用。
形骸与冠盖，假合相戏弄。
但异睡着人，不知梦是梦。','',''),('quantangshi-23336','自咏五首 二','白居易','quantangshi','','卷24','一家五十口，一郡十万户。
出为差科头，入为衣食主。
水旱合心忧，饥寒须手抚。
何异食蓼虫，不知苦是苦。','',''),('quantangshi-23337','自咏五首 三','白居易','quantangshi','','卷24','公私颇多事，衰惫殊少欢。
迎送宾客嬾，鞭笞黎庶难。
老耳倦声乐，病口厌杯盘。
既无可恋者，何以不休官。','',''),('quantangshi-23338','自咏五首 四','白居易','quantangshi','','卷24','一日复一日，自问何留滞。
为贫逐日俸，拟作归田计。
亦须随丰约，可得无限剂。
若待足始休，休官在何岁。','',''),('quantangshi-23339','自咏五首 五','白居易','quantangshi','','卷24','官舍非我庐，官园非我树。
洛中有小宅，渭上有别墅。
既无婚嫁累，幸有归休处。
归去诚已迟，犹胜不归去。','',''),('quantangshi-23340','和微之听妻弹别鹤操因为解释其义依韵加四句','白居易','quantangshi','','卷24','义重莫若妻，生离不如死。
誓将死同穴，其奈生无子。
商陵追礼教，妇出不能止。
舅姑明旦辞，夫妻中夜起。
起闻双鹤别，若与人相似。
听其悲唳声，亦如不得已。
青田八九月，辽城一万里。
裴回去住云，呜咽东西水。
写之在琴曲，听者酸心髓。
况当秋月弹，先入忧人耳。
怨抑掩朱弦，沈吟停玉指。
一闻无儿叹，相念两如此。
无儿虽薄命，有妻偕老矣。
幸免生别离，犹胜商陵氏。','',''),('quantangshi-23341','题故元少尹集后二首 一','白居易','quantangshi','','卷24','黄壤讵知我，白头徒忆君。
唯将老年泪，一洒故人文。','',''),('quantangshi-23342','题故元少尹集后二首 二','白居易','quantangshi','','卷24','遗文三十轴，轴轴金玉声。
龙门原上土，埋骨不埋名。','',''),('quantangshi-23343','和微之四月一日作','白居易','quantangshi','','卷24','四月一日天，花稀叶阴薄。
泥新燕影忙，蜜熟蜂声乐。
麦风低冉冉，稻水平漠漠。
芳节或蹉跎，游心稍牢落。
春华信为美，夏景亦未恶。
颭浪嫩青荷，重栏晚红药。
吴宫好风月，越郡多楼阁。
两地诚可怜，其奈久离索。','',''),('quantangshi-23344','吴中好风景二首 一','白居易','quantangshi','','卷24','吴中好风景，八月如三月。
水荇叶仍香，木莲花未歇。
海天微雨散，江郭纤埃灭。
暑退衣服干，潮生船舫活。
两衙渐多暇，亭午初无热。
骑吏语使君，正是游时节。','',''),('quantangshi-23345','吴中好风景二首 二','白居易','quantangshi','','卷24','吴中好风景，风景无朝暮。
晓色万家烟，秋声八月树。
舟移管弦动，桥拥旌旗驻。
改号齐云楼，重开武丘路。
况当丰岁熟，好是欢游处。
州民劝使君，且莫抛官去。','',''),('quantangshi-23346','答刘禹锡白太守行','白居易','quantangshi','','卷24','吏满六百石，昔贤輙去之。
秩登二千石，今我方罢归。
我秩讶已多，我归慙已迟。
犹胜尘土下，终老无休期。
卧乞百日告，起吟五篇诗。
朝与府吏别，暮与州民辞。
去年到郡时，麦穗黄离离。
今年去郡日，稻花白霏霏。
为郡已周岁，半岁罹旱饥。
襦袴无一片，甘棠无一枝。
何乃老与幼，泣别尽沾衣。
下慙苏人泪，上愧刘君辞。','',''),('quantangshi-23347','别苏州','白居易','quantangshi','','卷24','浩浩姑苏民，郁郁长洲城。
来慙荷宠命，去愧无能名。
青紫行将吏，班白列黎甿。
一时临水拜，十里随舟行。
饯筵犹未收，征棹不可停。
稍隔烟树色，尚闻丝竹声。
怅望武丘路，沈吟浒水亭。
还乡信有兴，去郡能无情。','',''),('quantangshi-23348','卯时酒','白居易','quantangshi','','卷24','佛法赞醍醐，仙方夸沆瀣。
未如卯时酒，神速功力倍。
一杯置掌上，三咽入腹内。
煦若春贯肠，暄如日炙背。
岂独肢体畅，仍加志气大。
当时遗形骸，竟日忘冠带。
似游华胥国，疑反混元代。
一性既完全，万机皆破碎。
半醒思往来，往来吁可怪。
宠辱忧喜间，惶惶二十载。
前年辞紫闼，今岁抛皂盖。
去矣鱼返泉，超然蝉离蜕。
是非莫分别，行止无疑碍。
浩气贮胸中，青云委身外。
扪心私自语，自语谁能会。
五十年来心，未如今日泰。
况兹杯中物，行坐长相对。','',''),('quantangshi-23349','自问行何迟','白居易','quantangshi','','卷24','前月发京口，今辰次淮涯。
二旬四百里，自问行何迟。
还乡无他计，罢郡有余资。
进不慕富贵，退未忧寒饥。
以此易过日，腾腾何所为。
逢山輙倚棹，遇寺多题诗。
酒醒夜深后，睡足日高时。
眼底一无事，心中百不知。
想到京国日，嬾放亦如斯。
何必冒风水，促促赴程归。','',''),('quantangshi-23350','除日答梦得同发楚州','白居易','quantangshi','','卷24','共作千里伴，俱为一郡回。
岁阴中路尽，乡思先春来。
山雪晚犹在，淮冰晴欲开。
归欤吟可作，休恋主人杯。','',''),('quantangshi-23351','问杨琼','白居易','quantangshi','','卷24','古人唱歌兼唱情，今人唱歌唯唱声。
欲说向君君不会，试将此语问杨琼。','',''),('quantangshi-23352','有感三首 一','白居易','quantangshi','','卷24','鬓发已斑白，衣绶方朱紫。
穷贱当壮年，富荣临暮齿。
车舆红尘合，第宅青烟起。
彼来此须去，品物之常理。
第宅非吾庐，逆旅暂留止。
子孙非我有，委蜕而已矣。
有如蚕造茧，又似花生子。
子结花暗凋，茧成蚕老死。
悲哉可奈何，举世皆如此。','',''),('quantangshi-23353','有感三首 二','白居易','quantangshi','','卷24','莫养瘦马驹，莫教小妓女。
后事在目前，不信君看取。
马肥快行走，妓长能歌舞。
三年五岁间，已闻换一主。
借问新旧主，谁乐谁辛苦。
请君大带上，把笔书此语。','',''),('quantangshi-23354','有感三首 三','白居易','quantangshi','','卷24','往事勿追思，追思多悲怆。
来事勿相迎，相迎已惆怅。
不如兀然坐，不如塌然卧。
食来即开口，睡来即合眼。
二事最关身，安寝加餐饭。
忘怀任行止，委命随修短。
更若有兴来，狂歌酒一盏。','',''),('quantangshi-23355','宿荥阳','白居易','quantangshi','','卷24','生长在荥阳，少小辞乡曲。
迢迢四十载，复向荥阳宿。
去时十一二，今年五十六。
追思儿戏时，宛然犹在目。
旧居失处所，故里无宗族。
岂唯变市朝，兼亦迁陵谷。
独有溱洧水，无情依旧绿。','',''),('quantangshi-23356','经溱洧','白居易','quantangshi','','卷24','落日驻行骑，沈吟怀古情。
郑风变已尽，溱洧至今清。
不见士与女，亦无芍药名。','',''),('quantangshi-23357','就花枝','白居易','quantangshi','','卷24','就花枝，移酒海，今朝不醉明朝悔。
且算欢娱逐日来，任他容鬓随年改。
醉翻衫袖抛小令，笑掷骰盘呼大采。
自量气力与心情，三五年间犹得在。','',''),('quantangshi-23358','喜雨','白居易','quantangshi','','卷24','圃旱忧葵堇，农旱忧禾菽。
人各有所私，我旱忧松竹。
松干竹焦死，眷眷在心目。
洒叶溉其根，汲水劳僮仆。
油云忽东起，凉雨凄相续。
似面洗垢尘，如头得膏沐。
千柯习习润，万叶欣欣绿。
千日浇灌功，不如一霢霂。
方知宰生灵，何异活草木。
所以圣与贤，同心调玉烛。','',''),('quantangshi-23359','题道宗上人十韵','白居易','quantangshi','','卷24','如来说偈赞，菩萨着论议。
是故宗律师，以诗为佛事。
一音无差别，四句有诠次。
欲使第一流，皆知不二义。
精洁霑戒体，闲淡藏禅味。
从容恣语言，缥缈离文字。
旁延邦国彦，上达王公贵。
先以诗句牵，后令入佛智。
人多爱师句，我独知师意。
不似休上人，空多碧云思。','',''),('quantangshi-23360','寄皇甫宾客','白居易','quantangshi','','卷24','名利既两忘，形体方自遂。
卧掩罗雀门，无人惊我睡。
睡足斗擞衣，闲步中庭地。
食饱摩挲腹，心头无一事。
除却玄晏翁，何人知此味。','',''),('quantangshi-23361','寄庾侍郎','白居易','quantangshi','','卷24','一双华亭鹤，数片太湖石。
巉巉苍玉峰，矫矫青云翮。
是时岁云暮，淡薄烟景夕。
庭霜封石棱，池雪印鹤迹。
幽致竟谁别，闲静聊自适。
怀哉庾顺之，好是今宵客。','',''),('quantangshi-23362','寄崔少监','白居易','quantangshi','','卷24','微微西风生，稍稍东方明。
入秋神骨爽，琴晓丝桐清。
弹为古宫调，玉水寒泠泠。
自觉弦指下，不是寻常声。
须臾羣动息，掩琴坐空庭。
直至日出后，犹得心和平。
惜哉意未已，不使崔君听。','',''),('quantangshi-23363','醉题沈子明壁','白居易','quantangshi','','卷24','不爱君池东十丛菊，不爱君池南万竿竹。
爱君帘下唱歌人，色似芙蓉声似玉。
我有阳关君未闻，若闻亦应愁杀君。','',''),('quantangshi-23364','劝酒','白居易','quantangshi','','卷24','劝君一盏君莫辞，劝君两盏君莫疑，劝君三盏君始知。
面上今日老昨日，心中醉时胜醒时。
天地迢遥自长久，白兔赤乌相趂走。
身后堆金拄北斗，不如生前一樽酒。
君不见春明门外天欲明，喧喧歌哭半死生。
游人驻马出不得，白轝素车争路行。
归去来，头已白，典钱将用买酒吃。','',''),('quantangshi-23365','落花','白居易','quantangshi','','卷24','留春春不住，春归人寂寞。
厌风风不定，风起花萧索。
既兴风前叹，重命花下酌。
劝君尝绿醅，教人拾红萼。
桃飘火焰焰，梨堕雪漠漠。
独有病眼花，春风吹不落。','',''),('quantangshi-23366','对镜吟','白居易','quantangshi','','卷24','白头老人照镜时，掩镜沈吟吟旧诗。
二十年前一茎白，如今变作满头丝。
吟罢回头索杯酒，醉来屈指数亲知。
老于我者多穷贱，设使身存寒且饥。
少于我者半为土，墓树已抽三五枝。
我今幸得见头白，禄俸不薄官不卑。
眼前有酒心无苦，只合欢娱不合悲。','',''),('quantangshi-23367','耳顺吟寄敦诗梦得','白居易','quantangshi','','卷24','三十四十五欲牵，七十八十百病缠。
五十六十却不恶，恬淡清净心安然。
已过爱贪声利后，犹在病羸昏耄前。
未无筋力寻山水，尚有心情听管弦。
闲开新酒尝数盏，醉忆旧诗吟一篇。
敦诗梦得且相劝，不用嫌他耳顺年。','',''),('quantangshi-23368','别毡帐火炉','白居易','quantangshi','','卷24','忆昨腊月天，北风三尺雪。
年老不禁寒，夜长安可彻。
赖有青毡帐，风前自张设。
复此红火炉，雪中相暖热。
如鱼入渊水，似兔藏深穴。
婉软蛰鳞苏，温炖冻肌活。
方安阴惨夕，遽变阳和节。
无奈时候迁，岂是恩情绝。
毳䈴逐日卷，香燎随灰灭。
离恨属三春，佳期在十月。
但令此身健，不作多时别。','',''),('quantangshi-23369','六年春赠分司东都诸公','白居易','quantangshi','','卷24','我为同州牧，内愧无才术。
忝擢恩已多，遭逢幸非一。
偶当谷贱岁，适值民安日。
郡县狱空虚，乡闾盗奔逸。
其间最幸者，朝客多分秩。
行接鸳鹭羣，坐成芝兰室。
时联拜表骑，间动题诗笔。
夜雪秉烛游，春风携榼出。
花教莺点检，柳付风排比。
法酒淡清浆，含桃袅红实。
洛童调金管，卢女铿瑶瑟。
黛惨歌思深，腰凝舞拍密。
每因同醉乐，自觉忘衰疾。
始悟肘后方，不如杯中物。
生涯随日过，世事何时毕？
老子苦乖慵，希君数牵率。','',''),('quantangshi-23370','九日代罗樊二妓招舒着作','白居易','quantangshi','','卷24','罗敷歛双袂，樊姬献一杯。
不见舒员外，秋菊为谁开。','',''),('quantangshi-23371','忆旧游','白居易','quantangshi','','卷24','忆旧游，旧游安在哉。
旧游之人半白首，旧游之地多苍苔。
江南旧游凡几处，就中最忆吴江隈。
长洲苑绿柳万树，齐云楼春酒一杯。
阊门晓严旗鼓出，臯桥夕闹船舫回。
修蛾慢脸灯下醉，急管繁弦头上催。
六七年前狂烂熳，三千里外思裴回。
李娟张态一春梦，周五殷三归夜台。
虎丘月色为谁好，娃宫花枝应自开。
赖得刘郎解吟咏，江山气色合归来。','',''),('quantangshi-23372','答崔宾客晦叔十二月四日见寄','白居易','quantangshi','','卷24','今岁日余二十六，来岁年登六十二。
尚不能忧眼下身，因何更算人间事。
居士忘筌默默坐，先生枕麴昏昏睡。
早晚相从归醉乡，醉乡去此无多地。','',''),('quantangshi-23373','劝我酒','白居易','quantangshi','','卷24','劝我酒，我不辞，请君歌，歌莫迟。
歌声长，辞亦切，此辞听者堪愁绝。
洛阳女儿面似花，河南大尹头如雪。','',''),('quantangshi-23374','赠韦处士六年夏大热旱','白居易','quantangshi','','卷24','骄阳连毒暑，动植皆枯槁。
旱日干密云，炎烟焦茂草。
少壮犹困苦，况予病且老。
脱无白栴檀，何以除热恼。
汗巾束头鬓，膻食熏襟抱。
始觉韦山人，休粮散发好。','',''),('quantangshi-23375','和微之诗二十三首 和晨霞','白居易','quantangshi','','卷24','君歌仙氏真，我歌慈氏真。
慈氏发真念，念此阎浮人。
左命大迦叶，右召桓提因。
千万化菩萨，百亿诸鬼神。
上自非相顶，下及风水轮。
胎卵湿化类，蠢蠢难具陈。
弘愿在救㧞，大悲忘辛勤。
无论善不善，岂间冤与亲。
抉开生盲眼，摆去烦恼尘。
烛以智慧日，洒之甘露津。
千界一时度，万法无与邻。
借问晨霞子，何如朝玉宸。','',''),('quantangshi-23376','和微之诗二十三首 和送刘道士游天台','白居易','quantangshi','','卷24','闻君梦游仙，轻举超世雰。
握持尊皇节，统卫吏兵军。
灵旗星月象，天衣龙凤纹。
佩服交带箓，讽吟蘂珠文。
阆宫缥缈间，钧乐依稀闻。
斋心谒西母，暝拜朝东君。
烟霏子晋裾，霞烂麻姑帬。
倏忽别真侣，怅望随归云。
人生同大梦，梦与觉谁分。
况此梦中梦，悠哉何足云。
假如金阙顶，设使银河濆。
既未出三界，犹应在五蕴。
饮咽日月精，菇嚼沆瀣芬。
尚是色香味，六尘之所熏。
仙中有大仙，首出梦幻羣。
慈光一照烛，奥法相絪緼。
不知万龄暮，不见三光曛。
一性自了了，万缘徒纷纷。
苦海不能漂，劫火不能焚。
此是竺干教，先生垂典坟。','',''),('quantangshi-23377','和微之诗二十三首 和栉沐寄道友','白居易','quantangshi','','卷24','栉沐事朝谒，中门初动关。
盛服去尚早，假寐须臾间。
钟声发东寺，夜色藏南山。
停骖待五漏，人马同时闲。
高星粲金粟，落月沈玉环。
出门向关路，坦坦无阻艰。
始出里北閈，稍转市西闤。
晨烛照朝服，紫烂复朱殷。
由来朝廷士，一入多不还。
因循掷白日，积渐凋朱颜。
青云已难致，碧落安能攀。
但且知止足，尚可销忧患。','',''),('quantangshi-23378','和微之诗二十三首 和祝苍华','白居易','quantangshi','','卷24','日居复月诸，环回照下土。
使我玄云发，化为素丝缕。
禀质本羸劣，养生仍莽卤。
痛饮困连宵，悲吟饥过午。
遂令头上发，种种无尺五。
根稀比黍苗，梢细同钗股。
岂是乏膏沐，非关栉风雨。
最为悲伤多，心焦衰落苦。
余者能有几，落者不可数。
秃似鹊填河，堕如乌解羽。
苍华何用祝，苦辞亦休吐。
匹如剃头僧，岂要巾冠主。','',''),('quantangshi-23379','和微之诗二十三首 和我年三首 一','白居易','quantangshi','','卷24','我年五十七，荣名得几许。
甲乙三道科，苏杭两州主。
才能本浅薄，心力虚劳苦。
可能随众人，终老于尘土。','',''),('quantangshi-23380','和微之诗二十三首 和我年三首 二','白居易','quantangshi','','卷24','我年五十七，归去诚已迟。
历官十五政，数若珠累累。
野萍始宾荐，场苗初絷维。
因读管萧书，窃慕大有为。
及遭荣遇来，乃觉才力羸。
黄纸诏频草，朱轮车载脂。
妻孥及仆使，皆免寒与饥。
省躬私自愧，知我者微之。
永怀山阴守，未遂嵩阳期。
如何坐留滞，头白江之湄。','',''),('quantangshi-23381','和微之诗二十三首 和我年三首 三','白居易','quantangshi','','卷24','我年五十七，荣名得非少。
报国竟何如，谋身犹未了。
昔尝速官谤，恩大而惩小。
一黜鹤辞轩，七年鱼在沼。
将枯鳞再跃，经铩翮重矫。
白日上昭昭，青云高渺渺。
平生颇同病，老大宜相晓。
紫绶足可荣，白头不为夭。
夙怀慕箕颍，晚节期松筱。
何当阙下来，同拜陈情表。','',''),('quantangshi-23382','和微之诗二十三首 和三月三十日四十韵','白居易','quantangshi','','卷24','送春君何在，君在山阴署。
忆我苏杭时，春游亦多处。
为君歌往事，岂敢辞劳虑。
莫怪言语狂，须知酬答遽。
江南腊月半，水冻凝如瘀。
寒景尚苍茫，和风已吹嘘。
女墙城似竈，雁齿桥如锯。
鱼尾上奫沦，草芽生沮洳。
律迟太簇管，日缓羲和驭。
布泽木龙催，迎春土牛助。
雨师习习洒，云将飘飘翥。
四野万里晴，千山一时曙。
杭土丽且康，苏民富而庶。
善恶有惩劝，刚柔无吐茹。
两衙少辞牒，四境稀书疏。
俗以劳倈安，政因闲暇着。
仙亭日登眺，虎丘时游豫。
寻幽驻旌轩，选胜回宾御。
舟移溪鸟避，乐作林猨覰。
池古莫耶沈，石奇罗刹踞。
水苗泥易耨，畲粟灰难锄。
紫蕨抽出畦，白莲埋在淤。
萎花红带黯，湿叶黄含菸。
镜动波颭菱，雪回风旋絮。
手经攀桂馥，齿为尝梅楚。
坐并船脚欹，行多马蹄跙。
圣贤清浊醉，水陆鲜肥饫。
鱼鲙芥酱调，水葵盐豉絮。
虽微五袴咏，幸免兆人诅。
但令乐不荒，何必游无倨。
吴苑仆寻罢，越城公尚据。
旧游几客存，新宴谁人与。
莫空文举酒，强下何曾箸。
江上易优游，城中多毁誉。
分应当自尽，事勿求人恕。
我既无子孙，君仍毕婚娶。
久为云雨别，终拟江湖去。
范蠡有扁舟，陶潜有篮轝。
两心苦相忆，两口遥相语。
最恨七年春，春来各一处。','',''),('quantangshi-23383','和微之诗二十三首 和寄乐天','白居易','quantangshi','','卷24','贤愚类相交，人情之大率。
然自古今来，几人号胶漆。
近闻屈指数，元某与白乙。
旁爱及弟兄，中权避家室。
松筠与金石，未足喻坚密。
在车如轮辕，在身如肘腋。
又如风云会，天使相召匹。
不似势利交，有名而无实。
顷我在杭岁，值君之越日。
望愁来仪迟，宴惜流景疾。
坐耀黄金带，酌酡頳玉质。
酣歌口不停，狂舞衣相拂。
平生赏心事，施展十未一。
会笑始哑哑，离嗟乃唧唧。
饯筵才收拾，征棹遽排[比]。
后恨苦緜緜，前欢何卒卒。
居人色惨淡，行子心纡郁。
风袂去时挥，云帆望中失。
宿酲和别思，目眩心忽忽。
病魂黯然销，老泪凄其出。
别君只如昨，芳岁换六七。
俱是官家身，后期难自必。','',''),('quantangshi-23384','和微之诗二十三首 和寄问刘白','白居易','quantangshi','','卷24','正与刘梦得，醉笑大开口。
适值此诗来，欢喜君知否。
遂令高卷幕，兼遣重添酒。
起望会稽云，东南一回首。
爱君金玉句，举世谁人有。
功用随日新，资材本天授。
吟哦不能散，自午将及酉。
遂留梦得眠，匡牀宿东牖。','',''),('quantangshi-23385','和微之诗二十三首 和新楼北园偶集从孙公度周巡官韩秀才卢秀才范处士小饮郑侍御判官周刘二从事皆先归','白居易','quantangshi','','卷24','闻君新楼宴，下对北园花。
主人既贤豪，宾客皆才华。
初筵日未高，中饮景已斜。
天地为幕席，富贵如泥沙。
嵇刘陶阮徒，不足置齿牙。
卧瓮鄙毕卓，落帽嗤孟嘉。
芳草供枕藉，乱莺助喧哗。
醉乡得道路，狂海无津涯。
一岁春又尽，百年期不赊。
同醉君莫辞，独醒古所嗟。
销愁若沃雪，破闷如割瓜。
称觞起为寿，此乐无以加。
歌声凝贯珠，舞袖飘乱麻。
相公谓四座，今日非自夸。
有奴善吹笙，有婢弹琵琶。
十指纤若笋，双鬟黳如鵶。
履舃起交杂，杯盘散纷拏。
归去勿拥遏，倒载逃难遮。
明日宴东武，后日游若耶。
岂独相公乐，讴歌千万家。','',''),('quantangshi-23386','和微之诗二十三首 和除夜作','白居易','quantangshi','','卷24','君赋此诗夜，穷阴岁之余。
我和此诗日，微和春之初。
老知颜状改，病觉肢体虚。
头上毛发短，口中牙齿疎。
一落老病界，难逃生死墟。
况此促促世，与君多索居。
君在浙江东，荣驾方伯舆。
我在魏阙下，谬乘大夫车。
妻孥常各饱，奴婢亦盈庐。
唯是利人事，比君全不如。
我统十郎官，君领百吏胥。
我掌四曹局，君管十乡闾。
君为父母君，大惠在资储。
我为刀笔吏，小恶乃诛锄。
君提七郡籍，我按三尺书。
俱已佩金印，尝同趋玉除。
外宠信非薄，中怀何不摅？
恩光未报答，日月空居诸。
磊落尝许君，局促应笑予。
所以自知分，欲先歌归欤。','',''),('quantangshi-23387','和微之诗二十三首 和知非','白居易','quantangshi','','卷24','因君知非问，诠较天下事。
第一莫若禅，第二无如醉。
禅能泯人我，醉可忘荣悴。
与君次第言，为我少留意。
儒教重礼法，道家养神气。
重礼足滋彰，养神多避忌。
不如学禅定，中有甚深味。
旷廓了如空，澄凝胜于睡。
屏除默默念，销尽悠悠思。
春无伤春心，秋无感秋泪。
坐成真谛乐，如受空王赐。
既得脱尘劳，兼应离慙愧。
除禅其次醉，此说非无谓。
一酌机即忘，三杯性咸遂。
逐臣去室妇，降虏败军帅。
思苦膏火煎，忧深扃鏁祕。
须凭百杯沃，莫惜千金费。
便似罩中鱼，脱飞生两翅。
劝君虽老大，逢酒莫回避。
不然即学禅，两途同一致。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-23388','和微之诗二十三首 和望晓','白居易','quantangshi','','卷24','休吟稽山晓，听咏秦城旦。
鸣鸡初有声，宿鸟犹未敢。
丁丁漏向尽，冬冬鼓过半。
南山青沈沈，东方白漫漫。
街心若流水，城角如断岸。
星河稍隅落，宫阙方轮焕。
朝车雷四合，骑火星一贯。
赫奕冠盖盛，荧煌朱紫烂。
沙堤亘蟆池，市路遶龙断。
白日忽照耀，红尘纷散乱。
贵教过客避，荣任行人看。
祥烟满虚空，春色无边畔。
鵷行候晷刻，龙尾登霄汉。
台殿暖宜攀，风光晴可翫。
草铺地茵褥，云卷天帏幔。
莺杂佩锵锵，花饶衣粲粲。
何言终日乐，独起临风叹。
叹我同心人，一别春七换。
相望山隔碍，欲去官羇绊。
何日到江东，超然似张翰。','',''),('quantangshi-23389','和微之诗二十三首 和李势女','白居易','quantangshi','','卷24','减一分太短，增一分太长。
不朱面若花，不粉肌如霜。
色为天下艳，心乃女中郎。
自言重不幸，家破身未亡。
人各有一死，此死职所当。
忍将先人体，与主为疣疮。
妾死主意快，从此两无妨。
愿信赤心语，速即白刃光。
南郡忽感激，却立舍锋铓。
抚背称阿姉，归我如归乡。
竟以恩信待，岂止猜妬忘。
由来几上肉，不足挥干将。
南郡死已久，骨枯墓苍苍。
愿于墓上头，立石镌此章。
劝诫天下妇，不令阴胜阳。','',''),('quantangshi-23390','和微之诗二十三首 和酬郑侍御东阳春闷放怀追越游见寄','白居易','quantangshi','','卷24','君得嘉鱼置宾席，乐如南有嘉鱼时。
劲气森爽竹竿竦，妍文焕烂芙蓉披。
载笔在幕名已重，补衮于朝官尚卑。
一缄疏入掩谷永，三都赋成排左思。
自言拜辞主人后，离心荡扬风前旗。
东南门馆别经岁，春眼怅望秋心悲。
昨日嘉鱼来访我，方驾同出何所之。
乐游原头春尚早，百舌新语声椑椑。
日趂花忙向南拆，风催柳急从东吹。
流年惝怳不饶我，美景鲜妍来为谁。
红尘三条界阡陌，碧草千里铺郊畿。
余霞断时绮幅裂，斜云展处罗文纰。
暮钟远近声互动，暝鸟高下飞追随。
酒酣将归未能去，怅然回望天四垂。
生何足养嵇着论，途何足泣杨涟洏。
胡不花下伴春醉，满酌绿酒听黄鹂。
嘉鱼点头时一叹，听我此言不知疲。
语终兴尽各分散，东西轩骑分逶迤。
此诗勿遣闲人见，见恐与他为笑资。
白首旧寮知我者，凭君一咏向周师。','',''),('quantangshi-23391','和微之诗二十三首 和自劝二首 一','白居易','quantangshi','','卷24','稀稀疎疎遶篱竹，窄窄狭狭向阳屋。
屋中有一曝背翁，委置形骸如土木。
日暮半炉麸炭火，夜深一盏纱笼烛。
不知有益及民无，二十年来食官禄。
就暖移盘檐下食，防寒拥被帷中宿。
秋官月俸八九万，岂徒遣尔身温足。
勤操丹笔念黄沙，莫使饥寒囚滞狱。','',''),('quantangshi-23392','和微之诗二十三首 和自劝二首 二','白居易','quantangshi','','卷24','急景凋年急于水，念此揽衣中夜起。
门无宿客共谁言，暖酒挑灯对妻子。
身饮数杯妻一盏，余酌分张与儿女。
微酣静坐未能眠，风霰萧萧打窗纸。
自问有何才与术，入为丞郎出刺史。
争知寿命短复长，岂得营营心不止。
请看韦孔与钱崔，半月之间四人死。','',''),('quantangshi-23393','和微之诗二十三首 和雨中花','白居易','quantangshi','','卷24','真宰倒持生杀柄，闲物命长人短命。
松枝上鹤蓍下龟，千年不死仍无病。
人生不得似龟鹤，少去老来同旦暝。
何异花开旦暝间，未落仍遭风雨横。
草得经年菜连月，唯花不与多时节。
一年三百六十日，花能几日供攀折。
桃李无言难自诉，黄莺解语凭君说。
莺虽为说不分明，叶底枝头谩饶舌。','',''),('quantangshi-23394','和微之诗二十三首 和晨兴因报问龟儿','白居易','quantangshi','','卷24','冬旦寒惨澹，云日无晶辉。
当此岁暮感，见君晨兴诗。
君诗亦多苦，苦在兄远离。
我苦不在远，缠绵肝与脾。
西院病孀妇，后牀孤侄儿。
黄昏一恸后，夜半十起时。
病眼两行血，衰鬓万茎丝。
咽绝五脏脉，瘦消百骸脂。
双目失一目，四肢断两肢。
不如溘然逝，安用半活为。
谁谓荼蘖苦，荼蘖甘如饴。
谁谓汤火热，汤火冷如澌。
前时君寄诗，忧念问阿龟。
喉燥声气窒，经年无报辞。
及覩晨兴句，未吟先涕垂。
因兹涟洳际，一吐心中悲。
茫茫四海间，此苦唯君知。
去我四千里，使我告诉谁。
仰头向青天，但见雁南飞。
凭雁寄一语，为我达微之。
弦绝有续胶，树斩可接枝。
唯我中肠断，应无连得期。','',''),('quantangshi-23395','和微之诗二十三首 和朝回与王炼师游南山下','白居易','quantangshi','','卷24','蔼蔼春景余，峨峨夏云初。
躞蹀退朝骑，飘颻随风裾。
晨从四丞相，入拜白玉除。
暮与一道士，出寻青溪居。
吏隐本齐致，朝野孰云殊。
道在有中适，机忘无外虞。
但愧烟霄上，鸾凤为吾徒。
又慙云林间，鸥鹤不我疎。
坐倾数杯酒，卧枕一卷书。
兴酣头兀兀，睡觉心于于。
以此送日月，问师为何如。','',''),('quantangshi-23396','和微之诗二十三首 和尝新酒','白居易','quantangshi','','卷24','空腹尝新酒，偶成卯时醉。
醉来拥褐裘，直至斋时睡。
睡酣不语笑，真寝无梦寐。
殆欲妄形骸，讵知属天地。
醒余和未散，起坐澹无事。
举臂一欠伸，引琴弹秋思。','',''),('quantangshi-23397','和微之诗二十三首 和顺之琴者','白居易','quantangshi','','卷24','阴阴花院月，耿耿兰房烛。
中有弄琴人，声貌俱如玉。
清泠石泉引，雅澹风松曲。
遂使君子心，不爱凡丝竹。','',''),('quantangshi-23398','感旧写真','白居易','quantangshi','','卷24','李放写我真，写来二十载。
莫问真何如，画亦销光彩。
朱颜与玄鬓，日夜改复改。
无嗟貌遽非，且喜身犹在。','',''),('quantangshi-23399','授太子宾客归洛','白居易','quantangshi','','卷24','南省去拂衣，东都来掩扉。
病将老齐至，心与身同归。
白首外缘少，红尘前事非。
怀哉紫芝叟，千载心相依。','',''),('quantangshi-23400','秋池二首 一','白居易','quantangshi','','卷24','身闲无所为，心闲无所思。
况当故园夜，复此新秋池。
岸暗鸟栖后，桥明月出时。
菱风香散漫，桂露光参差。
静境多独得，幽怀竟谁知。
悠然心中语，自问来何迟。','',''),('quantangshi-23401','秋池二首 二','白居易','quantangshi','','卷24','朝衣薄且健，晚簟清仍滑。
社近燕影稀，雨余蝉声歇。
闲中得诗境，此境幽难说。
露荷珠自倾，风竹玉相戛。
谁能一同宿，共翫新秋月。
暑退早凉归，池边好时节。','',''),('quantangshi-23402','中隐','白居易','quantangshi','','卷24','大隐住朝市，小隐入丘樊。
丘樊太冷落，朝市太嚣喧。
不如作中隐，隐在留司官。
似出复似处，非忙亦非闲。
不劳心与力，又免饥与寒。
终岁无公事，随月有俸钱。
君若好登临，城南有秋山。
君若爱游荡，城东有春园。
君若欲一醉，时出赴宾筵。
洛中多君子，可以恣欢言。
君若欲高卧，但自深掩关。
亦无车马客，造次到门前。
人生处一世，其道难两全。
贱即苦冻馁，贵则多忧患。
唯此中隐士，致身吉且安。
穷通与丰约，正在四者间。','',''),('quantangshi-23403','问秋光','白居易','quantangshi','','卷24','殷卿领北镇，崔尹开南幕。
外事信为荣，中怀未必乐。
何如不才者，兀兀无所作。
不引窗下琴，即举池上酌。
淡交唯对水，老伴无如鹤。
自适颇从容，旁观诚濩落。
身心转恬泰，烟景弥淡泊。
回首语秋光，东来应不错。','',''),('quantangshi-23404','引泉','白居易','quantangshi','','卷24','一为止足限，二为衰疾牵。
邴罢不因事，陶归非待年。
归来嵩洛下，闭户何翛然。
静扫林下地，闲疏池畔泉。
伊流狭似带，洛石大如拳。
谁教明月下，为我声溅溅。
竟夕舟中坐，有时桥上眠。
何用施屏障，水竹绕牀前。','',''),('quantangshi-23405','知足吟','白居易','quantangshi','','卷24','不种一陇田，仓中有余粟。
不采一株桑，箱中有余服。
官闲离忧责，身泰无羁束。
中人百户税，宾客一年禄。
樽中不乏酒，篱下仍多菊。
是物皆有余，非心无所欲。
吟君未贫作，因歌知足曲。','',''),('quantangshi-23406','酬集贤刘郎中对月见寄兼怀元浙东','白居易','quantangshi','','卷24','月在洛阳天，天高净如水。
下有白头人，擥衣中夜起。
思远镜亭上，光深书殿里。
眇然三处心，相去各千里。','',''),('quantangshi-23407','太湖石','白居易','quantangshi','','卷24','远望老嵯峨，近观怪嵚崟。
才高八九尺，势若千万寻。
嵌空华阳洞，重叠匡山岑。
邈矣仙掌迥，呀然劒门深。
形质冠今古，气色通晴阴。
未秋已瑟瑟，欲雨先沈沈。
天姿信为异，时用非所任。
磨刀不如砺，捣帛不如砧。
何乃主人意，重之如万金。
岂伊造物者，独能知我心。','',''),('quantangshi-23408','偶作二首 一','白居易','quantangshi','','卷24','扰扰贪生人，几何不夭阏。
遑遑爱名人，几何能贵达。
伊余信多幸，拖紫垂白发。
身为三品官，年已五十八。
筋骸虽早衰，尚未苦羸惙。
资产虽不丰，亦不甚贫竭。
登山力犹在，遇酒兴时发。
无事日月长，不羁天地阔。
安身有处所，适意无时节。
解带松下风，抱琴池上月。
人间所重者，相印将军钺。
谋虑系安危，威权主生杀。
焦心一身苦，炙手旁人热。
未必方寸间，得如吾快活。','',''),('quantangshi-23409','偶作二首 二','白居易','quantangshi','','卷24','日出起盥栉，振衣入道场。
寂然无他念，但对一炉香。
日高始就食，食亦非膏粱。
精麤随所有，亦足饱充肠。
日午脱巾簪，燕息窗下牀。
清风飒然至，卧可致羲皇。
日西引杖屦，散步游林塘。
或饮茶一盏，或吟诗一章。
日入多不食，有时唯命觞。
何以送闲夜，一曲秋霓裳。
一日分五时，作息率有常。
自喜老后健，不嫌闲中忙。
是非一以贯，身世交相忘。
若问此何许，此是无何乡。','',''),('quantangshi-23410','葺池上旧亭','白居易','quantangshi','','卷24','池月夜凄凉，池风晓萧飒。
欲入池上冬，先葺池上合。
向暖窗户开，迎寒帘幕合。
苔封旧瓦木，水照新朱蜡。
软火深土炉，香醪小瓷榼。
中有独宿翁，一灯对一榻。','',''),('quantangshi-23411','崔十八新池','白居易','quantangshi','','卷24','爱君新小池，池色无人知。
见底月明夜，无波风定时。
忽看不似水，一泊稀琉璃。','',''),('quantangshi-23412','翫止水','白居易','quantangshi','','卷24','动者乐流水，静者乐止水。
利物不如流，鉴形不如止。
凄清早霜降，淅沥微风起。
中面红叶开，四隅绿萍委。
广狭八九丈，湾环有涯涘。
浅深三四尺，洞彻无表里。
净分鹤翘足，澄见鱼掉尾。
迎眸洗眼尘，隔胷荡心滓。
定将禅不别，明与诚相似。
清能律贪夫，淡可交君子。
岂唯空狎翫，亦取相伦拟。
欲识静者心，心源只如此。','',''),('quantangshi-23413','闻崔十八宿予新昌弊宅时予亦宿崔家依仁新亭一宵偶同两兴暗合因而成咏聊以写怀','白居易','quantangshi','','卷24','陋巷掩弊庐，高居敞华屋。
新昌七株松，依仁万茎竹。
松前月台白，竹下风池绿。
君向我斋眠，我在君亭宿。
平生有微尚，彼此多幽独。
何必本主人，两心聊自足。','',''),('quantangshi-23414','日长','白居易','quantangshi','','卷24','日长昼加餐，夜短朝余睡。
春来寝食间，虽老犹有味。
林塘得芳景，园曲生幽致。
爱水多棹舟，惜花不扫地。
幸无眼下病，且向樽前醉。
身外何足言，人间本无事。','',''),('quantangshi-23415','三月三十日作','白居易','quantangshi','','卷24','今朝三月尽，寂寞春事毕。
黄鸟渐无声，朱樱新结实。
临风独长叹，此叹意非一。
半百过九年，艳阳残一日。
随年减欢笑，逐日添衰疾。
且遣花下歌，送此杯中物。','',''),('quantangshi-23416','慵不能','白居易','quantangshi','','卷24','架上非无书，眼慵不能看。
匣中亦有琴，手慵不能弹。
腰慵不能带，头慵不能冠。
午后恣情寝，午时随事餐。
一餐终日饱，一寝至夜安。
饥寒亦闲事，况乃不饥寒。','',''),('quantangshi-23417','晨兴','白居易','quantangshi','','卷24','宿鸟动前林，晨光上东屋。
铜炉添早香，纱笼灭残烛。
头醒风稍愈，眼饱睡初足。
起坐兀无思，叩齿三十六。
何以解宿斋，一杯云母粥。','',''),('quantangshi-23418','朝课','白居易','quantangshi','','卷24','平甃白石渠，静扫青苔院。
池上好风来，新荷大如扇。
小亭中何有，素琴对黄卷。
蘂珠讽数篇，秋思弹一徧。
从容朝课毕，方与客相见。','',''),('quantangshi-23419','天竺寺七叶堂避暑','白居易','quantangshi','','卷24','郁郁复郁郁，伏热何时毕？
行入七叶堂，烦暑随步失。
檐雨稍霏微，窗风正萧瑟。
清宵一觉睡，可以销百疾。','',''),('quantangshi-23420','香山寺石楼潭夜浴','白居易','quantangshi','','卷24','炎光昼方炽，暑气宵弥毒。
摇扇风甚微，褰裳汗霢霂。
起向月下行，来就潭中浴。
平石为浴牀，洼石为浴斛。
绡巾薄露顶，草屦轻乘足。
清凉咏而归，归上石楼宿。','',''),('quantangshi-23421','嗟发落','白居易','quantangshi','','卷24','朝亦嗟发落，暮亦嗟发落。
落尽诚可嗟，尽来亦不恶。
既不劳洗沐，又不烦梳掠。
最宜湿暑天，头轻无髻缚。
脱置垢巾帻，解去尘缨络。
银瓶贮寒泉，当顶倾一勺。
有如醍醐灌，坐受清凉乐。
因悟自在僧，亦资于剃削。','',''),('quantangshi-23422','安稳眠','白居易','quantangshi','','卷24','家虽日渐贫，犹未苦饥冻。
身虽日渐老，幸无急病痛。
眼逢闹处合，心向闲时用。
既得安稳眠，亦无颠倒梦。','',''),('quantangshi-23423','池上夜境','白居易','quantangshi','','卷24','晴空星月落池塘，澄鲜净绿表里光。
露簟清莹迎夜滑，风襟潇洒先秋凉。
无人惊处野禽下，新睡觉时幽草香。
但问尘埃能去否，濯缨何必向沧浪。','',''),('quantangshi-23424','书绅','白居易','quantangshi','','卷24','仕有职役劳，农有畎畮勤。
优哉分司叟，心力无苦辛。
岁晚头又白，自问何欣欣。
新酒始开瓮，旧谷犹满囷。
吾尝静自思，往往夜达晨。
何以送吾老，何以安吾贫。
岁计莫如谷，饱则不干人。
日计莫如醉，醉则兼忘身。
诚知有道理，未敢劝交亲。
恐为人所哂，聊自书诸绅。','',''),('quantangshi-23425','秋游平泉赠韦处士闲禅师','白居易','quantangshi','','卷24','秋景引闲步，山游不知疲。
杖藜舍舆马，十里与僧期。
昔尝忧六十，四体不支持。
今来已及此，犹未苦衰羸。
心兴遇境发，身力因行知。
寻云到起处，爱泉听滴时。
南村韦处士，西寺闲禅师。
山头与涧底，闻健且相随。','',''),('quantangshi-23426','游坊口悬泉偶题石上','白居易','quantangshi','','卷24','济源山水好，老尹知之久。
常日听人言，今秋入吾手。
孔山刀劒立，沁水龙蛇走。
危磴上悬泉，澄湾转坊口。
虚明见深底，净绿无纤垢。
仙棹浪悠扬，尘缨风斗薮。
岩寒松柏短，石古莓苔厚。
锦坐缨高低，翠屏张左右。
虽无安石妓，不乏文举酒。
谈笑逐身来，管弦随事有。
时逢杖锡客，或值垂纶叟。
相与澹忘归，自辰将及酉。
公门欲返驾，溪路犹回首。
早晚重来游，心期罢官后。','',''),('quantangshi-23427','对火翫雪','白居易','quantangshi','','卷24','平生所心爱，爱火兼怜雪。
火是腊天春，雪为阴夜月。
鹅毛纷正堕，兽炭敲初折。
盈尺白盐寒，满炉红玉热。
稍宜杯酌动，渐引笙歌发。
但识欢来由，不知醉时节。
银盘堆柳絮，罗袖抟琼屑。
共愁明日销，便作经年别。','',''),('quantangshi-23428','六年寒食洛下宴游赠冯李二少尹','白居易','quantangshi','','卷24','丰年寒食节，美景洛阳城。
三尹皆强健，七日尽晴明。
东郊蹋青草，南园攀紫荆。
风拆海榴艳，露坠木兰英。
假开春未老，宴合日屡倾。
珠翠混花影，管弦藏水声。
佳会不易得，良辰亦难并。
听吟歌暂辍，看舞杯徐行。
米价贱如土，酒味浓于饧。
此时不尽醉，但恐负平生。
殷勤二曹长，各捧一银觥。','',''),('quantangshi-23429','苦热中寄舒员外','白居易','quantangshi','','卷24','何堪日衰病，复此时炎燠。
厌对俗杯盘，倦听凡丝竹。
藤牀铺晚雪，角枕截寒玉。
安得清瘦人，新秋夜同宿。
非君固不可，何夕枉高躅。','',''),('quantangshi-23430','闲夕','白居易','quantangshi','','卷24','一声早蝉发，数点新萤度。
兰釭耿无烟，筠簟清有露。
未归后房寝，且下前轩步。
斜月入低廊，凉风满高树。
放怀常自适，遇境多成趣。
何法使之然，心中无细故。','',''),('quantangshi-23431','寄情','白居易','quantangshi','','卷24','灼灼早春梅，东南枝最早。
持来翫未足，花向手中老。
芳香销掌握，怅望生怀抱。
岂无后开花，念此先开好。','',''),('quantangshi-23432','舒员外游香山寺数日不归兼辱尺书大夸胜事时正值坐衙虑囚之际走笔题长句以赠之','白居易','quantangshi','','卷24','香山石楼倚天开，翠屏壁立波环回。
黄菊繁时好客到，碧云合处佳人来。
酡颜一笑夭桃绽，清吟数声寒玉哀。
轩骑逶迟棹容与，留连三日不能回。
白头老尹府中坐，早衙才退暮衙催。
庭前堦上何所有，累囚成贯案成堆。
岂无池塘长秋草，亦有丝竹生尘埃。
今日清光昨夜月，竟无人来劝一杯。','',''),('quantangshi-23433','早冬游王屋自灵都抵阳台上方望天坛偶吟成章寄温谷周尊师中书李相公','白居易','quantangshi','','卷24','霜降山水清，王屋十月时。
石泉碧漾漾，岩树红离离。
朝为灵都游，暮有阳台期。
飘然世尘外，鸾鹤如可追。
忽念公程尽，复慙身力衰。
天坛在天半，欲上心迟迟。
尝闻此游者，隐客与损之。
各抱贵仙骨，俱非泥垢姿。
二人相顾言，彼此称男儿。
若不为松乔，即须作臯夔。
今果如其语，光彩双葳蕤。
一人佩金印，一人翳玉芝。
我来高其事，咏欢偶成诗。
为君题石上，欲使故山知。','',''),('quantangshi-23434','吴宫辞','白居易','quantangshi','','卷24','淡红花帔浅檀蛾，睡脸初开似剪波。
坐对珠笼闲理曲，琵琶鹦鹉语相和。','',''),('quantangshi-23435','元微之除浙东观察使喜得杭越邻州先赠长句','白居易','quantangshi','','卷24','稽山镜水欢游地，犀带金章荣贵身。
官职比君虽校小，封疆与我且为邻。
郡楼对翫千峰月，江界平分两岸春。
杭越风光诗酒主，相看更合与何人。','',''),('quantangshi-23436','席上答微之','白居易','quantangshi','','卷24','我住浙江西，君去浙江东。
勿言一水隔，便与千里同。
富贵无人劝君酒，今宵为我尽杯中。','',''),('quantangshi-23437','答微之上船后留别','白居易','quantangshi','','卷24','烛下尊前一分手，舟中岸上两回头。
归来虚白堂中梦，合眼先应到越州。','',''),('quantangshi-23438','答微之泊西陵驿见寄','白居易','quantangshi','','卷24','烟波尽处一点白，应是西陵古驿台。
知在台边望不见，暮潮空送渡船回。','',''),('quantangshi-23439','答微之夸越州州宅','白居易','quantangshi','','卷24','贺上人回得报书，大夸州宅似仙居。
厌看冯翊风沙久，喜见兰亭烟景初。
日出旌旗生气色，月明楼阁在空虚。
知君暗数江南郡，除却余杭尽不如。','',''),('quantangshi-23440','微之重夸州居其落句有西州罗刹之谑因嘲兹石聊以寄怀','白居易','quantangshi','','卷24','君问西州城下事，醉中叠纸为君书。
嵌空石面标罗刹，压捺潮头敌子胥。
神鬼曾鞭犹不动，波涛虽打欲何如。
谁知太守心相似，抵滞坚顽两有余。','',''),('quantangshi-23441','张十八员外以新诗二十五首见寄郡楼月下吟翫通夕因题卷后封寄微之','白居易','quantangshi','','卷24','秦城南省清秋夜，江郡东楼明月时。
去我三千六百里，得君二十五篇诗。
阳春曲调高难和，淡水交情老始知。
坐到天明吟未足，重封转寄与微之。','',''),('quantangshi-23442','酬微之','白居易','quantangshi','','卷24','满袠填箱唱和诗，少年为戏老成悲。
声声丽曲敲寒玉，句句妍辞缀色丝。
吟翫独当明月夜，伤嗟同是白头时。
由来才命相磨折，天遣无儿欲怨谁。','',''),('quantangshi-23443','余思未尽加为六韵重寄微之','白居易','quantangshi','','卷24','海内声华并在身，箧中文字绝无伦。
遥知独对封章草，忽忆同为献纳臣。
走笔往来盈卷轴，除官递互掌丝纶。
制从长庆辞高古，诗到元和体变新。
各有文姬才稚齿，俱无通子继余尘。
琴书何必求王粲，与女犹胜与外人。','',''),('quantangshi-23444','答微之咏怀见寄','白居易','quantangshi','','卷24','合中同直前春事，船里相逢昨日情。
分袂二年劳梦寐，并牀三宿话平生。
紫微半畔辞宫阙，沧海西头对郡城。
聚散穷通何足道，醉来一曲放歌行。','',''),('quantangshi-23445','酬微之夸镜湖','白居易','quantangshi','','卷24','我嗟身老岁方徂，君更官高兴转孤。
军门郡合曾闲否，禹穴耶溪得到无。
酒盏省陪波卷白，骰盘思共彩呼卢。
一泓镜水谁能羡，自有胷中万顷湖。','',''),('quantangshi-23446','雪中即事答微之','白居易','quantangshi','','卷24','连夜江云黄惨澹，平明山雪白糢糊。
银河沙涨三千里，梅岭花排一万株。
北市风生飘散麪，东楼日出照凝酥。
谁家高士关门户，何处行人失道途？
舞鹤庭前毛稍定，捣衣砧上练新铺。
戏团稚女呵红手，愁坐衰翁对白须。
压瘴一州除疾苦，呈丰万井尽欢娱。
润含玉德怀君子，寒助霜威忆大夫。
莫道烟波一水隔，何妨气候两乡殊。
越中地暖多成雨，还有瑶台琼树无。','',''),('quantangshi-23447','醉封诗筒寄微之','白居易','quantangshi','','卷24','一生休戚与穷通，处处相随事事同。
未死又怜沧海郡，无儿俱作白头翁。
展眉只仰三杯后，代面唯凭五字中。
为向两州邮吏道，莫辞来去递诗筒。','',''),('quantangshi-23448','除夜寄微之','白居易','quantangshi','','卷24','鬓毛不觉白毵毵，一事无成百不堪。
共惜盛时辞阙下，同嗟除夜在江南。
家山泉石寻常忆，世路风波子细谙。
老校于君合先退，明年半百又加三。','',''),('quantangshi-23449','苏州李中丞以元日郡斋感怀诗寄微之及予輙依来篇七言八韵走笔奉答兼呈微之','白居易','quantangshi','','卷24','白首余杭白太守，落魄抛名来已久。
一辞渭北故园春，再把江南新岁酒。
杯前笑歌徒勉强，镜里形容渐衰朽。
领郡慙当潦倒年，邻州喜得平生友。
长洲草接松江岸，曲水花连镜湖口。
老去还能痛饮无，春来曾作闲游否。
凭莺传语报李六，倩雁将书与元九。
莫嗟一日日催人，且贵一年年入手。','',''),('quantangshi-23450','早春西湖闲游怅然兴怀忆与微之同赏因思在越官重事殷镜湖之游或恐未暇偶成十八韵寄微之','白居易','quantangshi','','卷24','上马复呼宾，湖边景气新。
管弦三数事，骑从十余人。
立换登山屐，行携漉酒巾。
逢花看当妓，遇草坐为茵。
西日笼黄柳，东风荡白苹。
小桥装雁齿，轻浪甃鱼鳞。
画舫牵徐转，银船酌慢巡。
野情遗世累，醉态任天真。
彼此年将老，平生分最亲。
高天从所愿，远地得为邻。
云树分三驿，烟波限一津。
飜嗟寸步隔，却厌尺书频。
浙右称雄镇，山阴委重臣。
贵垂长紫绶，荣驾大朱轮。
出动刀枪队，归生道路尘。
雁惊弓易散，鸥怕鼓难驯。
百吏瞻相面，千夫捧拥身。
自然闲兴少，应负镜湖春。','',''),('quantangshi-23451','答微之见寄','白居易','quantangshi','','卷24','可怜风景浙东西，先数余杭次会稽。
禹庙未胜天竺寺，钱湖不羡若耶溪。
摆尘野鹤春毛暖，拍水沙鸥湿翅低。
更对雪楼君爱否，红栏碧甃点银泥。','',''),('quantangshi-23452','祭社宵兴灯前偶作','白居易','quantangshi','','卷24','城头传鼓角，灯下整衣冠。
夜镜藏须白，秋泉漱齿寒。
欲将闲送老，须着病辞官。
更待年终后，支持归计看。','',''),('quantangshi-23453','闲卧','白居易','quantangshi','','卷24','尽日前轩卧，神闲境亦空。
有山当枕上，无事到心中。
帘卷侵牀日，屏遮入座风。
望春春未到，应在海门东。','',''),('quantangshi-23454','新春江次','白居易','quantangshi','','卷24','浦干潮未应，堤湿冻初销。
粉片妆梅朵，金丝刷柳条。
鸭头新绿水，雁齿小红桥。
莫怪珂声碎，春来五马骄。','',''),('quantangshi-23455','春题湖上','白居易','quantangshi','','卷24','湖上春来似画图，乱峰围绕水平铺。
松排山面千重翠，月点波心一颗珠。
碧毯线头抽早稻，青罗帬带展新蒲。
未能抛得杭州去，一半句留是此湖。','',''),('quantangshi-23456','早春忆微之','白居易','quantangshi','','卷24','昏昏老与病相和，感物思君叹复歌。
声早鸡先知夜短，色浓柳最占春多。
沙头雨染斑斑草，水面风驱瑟瑟波。
可道眼前光景恶，其如难见故人何。','',''),('quantangshi-23457','失鹤','白居易','quantangshi','','卷24','失为庭前雪，飞因海上风。
九霄应得侣，三夜不归笼。
声断碧云外，影沈明月中。
郡斋从此后，谁伴白头翁。','',''),('quantangshi-23458','自感','白居易','quantangshi','','卷24','宴游寝食渐无味，杯酒管弦徒绕身。
宾客欢娱僮仆饱，始知官职为它人。','',''),('quantangshi-23459','得湖州崔十八使君书喜与杭越邻郡因成长句代贺兼寄微之','白居易','quantangshi','','卷24','三郡何因此结缘，贞元科第忝同年。
故情欢喜开书后，旧事思量在眼前。
越国封疆吞碧海，杭城楼合入青烟。
吴兴卑小君应屈，为是蓬莱最后仙。','',''),('quantangshi-23460','同诸客携酒早看樱桃花','白居易','quantangshi','','卷24','晓报樱桃发，春携酒客过。
绿饧黏盏杓，红雪压枝柯。
天色晴明少，人生事故多。
停杯替花语，不醉拟如何。','',''),('quantangshi-23461','柳絮','白居易','quantangshi','','卷24','三月尽是头白日，与春老别更依依。
凭莺为向杨花道，绊惹春风莫放归。','',''),('quantangshi-23462','早饮湖州酒寄崔使君','白居易','quantangshi','','卷24','一榼扶头酒，泓澄泻玉壶。
十分蘸甲酌，潋艳满银盂。
捧出光华动，尝看气味殊。
手中稀琥珀，舌上冷醍醐。
瓶里有时尽，江边无处沽。
不知崔太守，更有寄来无。','',''),('quantangshi-23463','病中书事','白居易','quantangshi','','卷24','三载卧山城，闲知节物情。
莺多过春语，蝉不待秋鸣。
气嗽因寒发，风痰欲雨生。
病身无所用，唯解卜阴晴。','',''),('quantangshi-23464','与微之唱和来去常以竹筒贮诗陈协律美而成篇因以此答','白居易','quantangshi','','卷24','拣得琅玕截作筒，缄题章句写心胷。
随风每喜飞如鸟，渡水常忧化作龙。
粉节坚如太守信，霜筠冷称大夫容。
烦君赞咏心知愧，鱼目骊珠同一封。','',''),('quantangshi-23465','醉戏诸妓','白居易','quantangshi','','卷24','席上争飞使君酒，歌中多唱舍人诗。
不知明日休官后，逐我东山去是谁。','',''),('quantangshi-23466','北院','白居易','quantangshi','','卷24','北院人稀到，东窗事最偏。
竹烟行竈上，石壁卧房前。
性拙身多暇，心慵事少缘。
还如病居士，唯置一牀眠。','',''),('quantangshi-23467','酬周协律','白居易','quantangshi','','卷24','五十钱唐守，应为送老官。
滥蒙辞客爱，犹作近臣看。
凿落愁须饮，琵琶闷遣弹。
白头虽强醉，不似少年欢。','',''),('quantangshi-23468','题石山人','白居易','quantangshi','','卷24','腾腾兀兀在人间，贵贱贤愚尽往还。
膻腻筵中唯饮酒，歌钟会处独思山。
存神不许三尸住，混俗无妨两鬓斑。
除却余杭白太守，何人更解爱君闲。','',''),('quantangshi-23469','诗解','白居易','quantangshi','','卷24','新篇日日成，不是爱声名。
旧句时时改，无妨悦性情。
但令长守郡，不觉却归城。
祗拟江湖上，吟哦过一生。','',''),('quantangshi-23470','潮','白居易','quantangshi','','卷24','早潮才落晚潮来，一月周流六十回。
不独光阴朝复暮，杭州老去被潮催。','',''),('quantangshi-23471','闻歌妓唱严郎中诗因以绝句寄之','白居易','quantangshi','','卷24','已留旧政布中和，又付新词与艳歌。
但是人家有遗爱，就中苏小感恩多。','',''),('quantangshi-23472','柘枝妓','白居易','quantangshi','','卷24','平铺一合锦筵开，连击三声画鼓催。
红蜡烛移桃叶起，紫罗衫动柘枝来。
带垂钿胯花腰重，帽转金铃雪面回。
看即曲终留不住，云飘雨送向阳台。','',''),('quantangshi-23473','急乐世辞','白居易','quantangshi','','卷24','正抽碧线绣红罗，忽听黄莺歛翠蛾。
秋思冬愁春怅望，大都不称意时多。','',''),('quantangshi-23474','天竺寺送坚上人归庐山','白居易','quantangshi','','卷24','锡杖登高寺，香炉忆旧峰。
偶来舟不系，忽去鸟无踪。
岂要留离偈，宁劳动别容。
与师俱是梦，梦里暂相逢。','',''),('quantangshi-23475','除官赴阙留赠微之','白居易','quantangshi','','卷24','去年十月半，君来过浙东。
今年五月尽，我发向关中。
两乡默默心相别，一水盈盈路不通。
从此津人应省事，寂寥无复递诗筒。','',''),('quantangshi-23476','留题郡斋','白居易','quantangshi','','卷24','吟山歌水嘲风月，便是三年官满时。
春为醉眠多闭合，秋因晴望暂褰帷。
更无一事移风俗，唯化州民解咏诗。','',''),('quantangshi-23477','别州民','白居易','quantangshi','','卷24','耆老遮归路，壶浆满别筵。
甘棠无一树，那得泪潸然。
税重多贫户，农饥足旱田。
唯留一湖水，与汝救凶年。','',''),('quantangshi-23478','留题天竺灵隐两寺','白居易','quantangshi','','卷24','在郡六百日，入山十二回。
宿因月桂落，醉为海榴开。
黄纸除书到，青宫诏命催。
僧徒多怅望，宾从亦裴回。
寺暗烟埋竹，林香雨落梅。
别桥怜白石，辞洞恋青苔。
渐出松间路，犹飞马上杯。
谁教冷泉水，送我下山来。','',''),('quantangshi-23479','西湖留别','白居易','quantangshi','','卷24','征途行色惨风烟，祖帐离声咽管弦。
翠黛不须留五马，皇恩只许住三年。
绿藤阴下铺歌席，红藕花中泊妓船。
处处回头尽堪恋，就中难别是湖边。','',''),('quantangshi-23480','重寄别微之','白居易','quantangshi','','卷24','凭仗江波寄一辞，不须惆怅报微之。
犹胜往岁峡中别，滟滪堆边招手时。','',''),('quantangshi-23481','重题别东楼','白居易','quantangshi','','卷24','东楼胜事我偏知，气象多随昏旦移。
湖卷衣裳白重叠，山张屏障绿参差。
海仙楼塔晴方出，江女笙箫夜始吹。
春雨星攒寻蟹火，秋风霞颭弄涛旗。
宴宜云髻新梳后，曲爱霓裳未拍时。
太守三年嘲不尽，郡斋空作百篇诗。','',''),('quantangshi-23482','别周军事','白居易','quantangshi','','卷24','主人头白官仍冷，去后怜君是底人。
试谒会稽元相去，不妨相见却殷勤。','',''),('quantangshi-23483','看常州柘枝赠贾使君','白居易','quantangshi','','卷24','莫惜新衣舞柘枝，也从尘汚汗霑垂。
料君即却归朝去，不见银泥衫故时。','',''),('quantangshi-23484','汴河路有感','白居易','quantangshi','','卷24','三十年前路，孤舟重往还。
绕身新眷属，举目旧乡关。
事去唯留水，人非但见山。
啼襟与愁鬓，此日两成斑。','',''),('quantangshi-23485','埇桥旧业','白居易','quantangshi','','卷24','别业埇城北，抛来二十春。
改移新径路，变换旧村邻。
有税田畴薄，无官弟侄贫。
田园何用问，强半属他人。','',''),('quantangshi-23486','茅城驿','白居易','quantangshi','','卷24','汴河无景思，秋日又凄凄。
地薄桑麻瘦，村贫屋舍低。
早苗多间草，浊水半和泥。
最是萧条处，茅城驿向西。','',''),('quantangshi-23487','河阴夜泊忆微之','白居易','quantangshi','','卷24','忆君我正泊行舟，望我君应上郡楼。
万里月明同此夜，黄河东面海西头。','',''),('quantangshi-23488','杭州回舫','白居易','quantangshi','','卷24','自别钱塘山水后，不多饮酒嬾吟诗。
欲将此意凭回棹，报与西湖风月知。','',''),('quantangshi-23489','途中题山泉','白居易','quantangshi','','卷24','决决涌岩穴，溅溅出洞门。
向东应入海，从此不归源。
似叶飘辞树，如云断别根。
吾身亦如此，何日返乡园。','',''),('quantangshi-23490','欲到东洛得杨使君书因以此报','白居易','quantangshi','','卷24','向公心切向财疎，淮上休官洛下居。
三郡政能从独步，十年生计复何如。
使君滩上久分手，别驾渡头先得书。
且喜平安又相见，其余外事尽空虚。','',''),('quantangshi-23491','洛下寓居','白居易','quantangshi','','卷24','秋馆清凉日，书因解闷看。
夜窗幽独处，琴不为人弹。
游宴慵多废，趋朝老渐难。
禅僧教断酒，道士劝休官。
渭曲庄犹在，钱唐俸尚残。
如能便归去，亦不至饥寒。','',''),('quantangshi-23492','味道','白居易','quantangshi','','卷24','叩齿晨兴秋院静，焚香冥坐晚窗深。
七篇真诰论仙事，一卷檀经说佛心。
此日尽知前境妄，多生曾被外尘侵。
自嫌习性犹残处，爱咏闲诗好听琴。','',''),('quantangshi-23493','好听琴','白居易','quantangshi','','卷24','本性好丝桐，尘机闻即空。
一声来耳里，万事离心中。
清畅堪销疾，恬和好养蒙。
尤宜听三乐，安慰白头翁。','',''),('quantangshi-23494','爱咏诗','白居易','quantangshi','','卷24','辞章讽咏成千首，心行归依向一乘。
坐倚绳牀闲自念，前生应是一诗僧。','',''),('quantangshi-23495','酬皇甫庶子见寄','白居易','quantangshi','','卷24','掌纶不称吾应笑，典郡无能我自知。
别诏忽惊新命出，同寮偶与夙心期。
春坊潇洒优闲地，秋鬓苍浪老大时。
独占二疏应未可，龙楼见拟觅分司。','',''),('quantangshi-23496','卧疾','白居易','quantangshi','','卷24','闲官卧疾绝经过，居处萧条近洛河。
水北水南秋月夜，管弦声少杵声多。','',''),('quantangshi-23497','远师','白居易','quantangshi','','卷24','东宫白庶子，南寺远禅师。
何处遥相见，心无一事时。','',''),('quantangshi-23498','问远师','白居易','quantangshi','','卷24','荤膻停夜食，吟咏散秋怀。
笑问东林老，诗应不破斋。','',''),('quantangshi-23499','小院酒醒','白居易','quantangshi','','卷24','酒醒闲独步，小院夜深凉。
一领新秋簟，三间明月廊。
未收残盏杓，初换热衣裳。
好是幽眠处，松阴六尺牀。','',''),('quantangshi-23500','赠侯三郎中','白居易','quantangshi','','卷24','老爱东都好寄身，足泉多竹少埃尘。
年丰最喜唯贫客，秋冷先知是瘦人。
幸有琴书堪作伴，苦无田宅可为邻。
洛中纵未长居得，且与苏田游过春。','',''),('quantangshi-23501','求分司东都寄牛相公十韵','白居易','quantangshi','','卷24','忽忽心如梦，星星鬓似丝。
纵贫长有酒，虽老未抛诗。
俭薄身都惯，疎顽性颇宜。
饭麤飱亦饱，被暖起常迟。
万里归何得，三年伴是谁。
华亭鹤不去，天竺石相随。
王尹贳将马，田家卖与池。
开门闲坐日，遶水独行时。
嬾慢交游许，衰羸相府知。
官寮幸无事，可惜不分司。','',''),('quantangshi-23502','酬杨八','白居易','quantangshi','','卷24','君以旷怀宜静境，我因蹇步称闲官。
闭门足病非高士，劳作云心鹤眼看。','',''),('quantangshi-23503','履道新居二十韵','白居易','quantangshi','','卷24','履道坊西角，官河曲北头。
林园四邻好，风景一家秋。
门闭深沈树，池通浅沮沟。
拔青松直上，铺碧水平流。
篱菊黄金合，窗筠绿玉稠。
疑连紫阳洞，似到白苹洲。
僧至多同宿，宾来輙少留。
岂无诗引兴，兼有酒销忧。
移榻临平岸，携茶上小舟。
果穿闻鸟啄，萍破见鱼游。
地与尘相远，人将境共幽。
泛潭菱点镜，沈浦月生钩。
厨晓烟孤起，庭寒雨半收。
老饥初爱粥，瘦冷早披裘。
洛下招新隐，秦中忘旧游。
辞章留凤合，班籍寄龙楼。
病惬官曹静，闲慙俸禄忧。
琴书中有得，衣食外何求。
济世才无取，谋身智不周。
应须共心语，万事一时休。','',''),('quantangshi-23504','九日思杭州旧游寄周判官及诸客','白居易','quantangshi','','卷24','忽忆郡南山顶上，昔时同醉是今辰。
笙歌委曲声延耳，金翠动摇光照身。
风景不随宫相去，欢娱应逐使君新。
江山宾客皆如旧，唯是当筵换主人。','',''),('quantangshi-23505','秋晚','白居易','quantangshi','','卷24','烟景澹蒙蒙，池边微有风。
觉寒蛬近壁，知瞑鹤归笼。
长貌随年改，衰情与物同。
夜来霜厚薄，梨叶半低红。','',''),('quantangshi-23506','分司','白居易','quantangshi','','卷24','散秩留司殊有味，最宜病拙不才身。
行香拜表为公事，碧洛青嵩当主人。
已出闲游多到夜，却归慵卧又经旬。
钱唐五马留三匹，还拟骑游搅扰春。','',''),('quantangshi-23507','河南王尹初到以诗代书先问之','白居易','quantangshi','','卷24','别来王阁老，三岁似须臾。
鬓上斑多少，杯前兴有无。
官从分紧慢，情莫问荣枯。
许入朱门否，篮舆一病夫。','',''),('quantangshi-23508','池西亭','白居易','quantangshi','','卷24','朱栏映晚树，金魄落秋池。
还似钱唐夜，西楼月出时。','',''),('quantangshi-23509','临池闲卧','白居易','quantangshi','','卷24','小竹围庭匝，平池与砌连。
闲多临水坐，老爱向阳眠。
营役抛身外，幽奇送枕前。
谁家卧牀脚，解系钓鱼船。','',''),('quantangshi-23510','吾庐','白居易','quantangshi','','卷24','吾庐不独贮妻儿，自觉年侵身力衰。
眼下营求容足地，心中准拟挂冠时。
新昌小院松当户，履道幽居竹遶池。
莫道两都空有宅，林泉风月是家资。','',''),('quantangshi-23511','题新居寄宣州崔相公','白居易','quantangshi','','卷24','门庭有水巷无尘，好称闲官作主人。
冷似雀罗虽少客，宽于蜗舍足容身。
疎通竹径将迎月，扫掠莎台欲待春。
济世料君归未得，南园北曲谩为邻。','',''),('quantangshi-23512','忆杭州梅花因叙旧游寄萧协律','白居易','quantangshi','','卷24','三年闲闷在余杭，曾为梅花醉几场。
伍相庙边繁似雪，孤山园里丽如妆。
蹋随游骑心长惜，折赠佳人手亦香。
赏自初开直至落，欢因小饮便成狂。
薛刘相次埋新壠，沈谢双飞出故乡。
歌伴酒徒零散尽，唯残头白老萧郎。','',''),('quantangshi-23513','病中辱张常侍题集贤院诗因以继和','白居易','quantangshi','','卷24','天禄阁门开，甘泉侍从回。
图书皆帝籍，寮友尽仙才。
骑省通中掖，龙楼隔上台。
犹怜病宫相，诗寄洛阳来。','',''),('quantangshi-23514','早春晚归','白居易','quantangshi','','卷24','晚归骑马过天津，沙白桥红返照新。
草色连延多隙地，鼓声闲缓少忙人。
还如南国饶沟水，不似西京足路尘。
金谷风光依旧在，无人管领石家春。','',''),('quantangshi-23515','赠杨使君','白居易','quantangshi','','卷24','曾嗟放逐同巴峡，且喜归还会洛阳。
时命到来须作用，功名未立莫思量。
银衔叱拨欺风雪，金屑琵琶费酒浆。
更待城东桃李发，共君沈醉两三场。','',''),('quantangshi-23516','赠皇甫庶子','白居易','quantangshi','','卷24','何因散地共徘徊，人道君才我不才。
骑少马蹄生易蹶，用稀印鏁涩难开。
妻知年老添衣絮，婢报天寒拨酒醅。
更愧小胥谘拜表，单衫冲雪夜深来。','',''),('quantangshi-23517','池上竹下作','白居易','quantangshi','','卷24','穿篱遶舍碧逶迤，十畮闲居半是池。
食饱窗间新睡后，脚轻林下独行时。
水能性淡为吾友，竹解心虚即我师。
何必悠悠人世上，劳心费目觅亲知。','',''),('quantangshi-23518','闲出觅春戏赠诸郎官','白居易','quantangshi','','卷24','年来数出觅风光，亦不全闲亦不忙。
放鞚体安骑稳马，隔袍身暖照晴阳。
迎春日日添诗思，送老时时放酒狂。
除却髭须白一色，其余未伏少年郎。','',''),('quantangshi-23519','别春炉','白居易','quantangshi','','卷24','暖阁春初入，温炉兴稍阑。
晚风犹冷在，夜火且留看。
独宿相依久，多情欲别难。
谁能共天语，长遣四时寒。','',''),('quantangshi-23520','泛小䑳二首 一','白居易','quantangshi','','卷24','水一塘，䑳一只。
䑳头漾漾知风起，䑳背萧萧闻雨滴。
醉卧船中欲醒时，忽疑身是江南客。','',''),('quantangshi-23521','泛小䑳二首 二','白居易','quantangshi','','卷24','船缓进，水平流。
一茎竹篙剔船尾，两幅青幕覆船头。
亚竹乱藤多照岸，如从凤口向湖州。','',''),('quantangshi-23522','梦行简','白居易','quantangshi','','卷24','天气妍和水色鲜，闲吟独步小桥边。
池塘草绿无佳句，虚卧春窗梦阿怜。','',''),('quantangshi-23523','题新居呈王尹兼简府中三掾','白居易','quantangshi','','卷24','弊宅须重葺，贫家乏羡财。
桥凭川守造，树倩府僚栽。
朱板新犹湿，红英暖渐开。
仍期更携酒，倚槛看花来。','',''),('quantangshi-23524','云和','白居易','quantangshi','','卷24','非琴非瑟亦非筝，拨柱推弦调未成。
欲散白头千万恨，只消红袖两三声。','',''),('quantangshi-23525','春老','白居易','quantangshi','','卷24','欲随年少强游春，自觉风光不属身。
歌舞屏风花障上，几时曾画白头人。','',''),('quantangshi-23526','春雪过皇甫家','白居易','quantangshi','','卷24','晚来篮轝雪中回，喜遇君家门正开。
唯要主人青眼待，琴诗谈笑自将来。','',''),('quantangshi-23527','崔侍御以孩子三日示其所生诗见示因以二绝句和之 一','白居易','quantangshi','','卷24','洞房门上挂桑弧，香水盆中浴凤雏。
还似初生三日魄，嫦娥满月即成珠。','',''),('quantangshi-23528','崔侍御以孩子三日示其所生诗见示因以二绝句和之 二','白居易','quantangshi','','卷24','爱惜肯将同宝玉，喜欢应胜得王侯。
弄璋诗句多才思，愁杀无儿老邓攸。','',''),('quantangshi-23529','与皇甫庶子同游城东','白居易','quantangshi','','卷24','闲游何必多徒侣，相劝时时举一杯。
博望苑中无职役，建春门外足池台。
绿油剪叶蒲新长，红蜡黏枝杏欲开。
白马朱衣两宫相，可怜天气出城来。','',''),('quantangshi-23530','洛城东花下作','白居易','quantangshi','','卷24','记得旧诗章，花多数洛阳及逢枝似雪，已是鬓成霜。
向后光阴促，从前事意忙。
无因重年少，何计驻时芳。
欲送愁离面，须倾酒入肠。
白头无藉在，醉倒亦何妨。','',''),('quantangshi-23531','晚春寄微之并崔湖州','白居易','quantangshi','','卷24','洛阳陌上少交亲，履道城边欲暮春。
崔在吴兴元在越，出门骑马觅何人。','',''),('quantangshi-23532','城东闲行因题尉迟司业水阁','白居易','quantangshi','','卷24','闲遶洛阳城，无人知姓名。
病乘篮轝出，老着茜衫行。
处处花相引，时时酒一倾。
借君溪阁上，醉咏两三声。','',''),('quantangshi-23533','寄皇甫七','白居易','quantangshi','','卷24','孟夏爱吾庐，陶潜语不虚。
花樽飘落酒，风案展开书。
邻女偷新果，家僮漉小鱼。
不知皇甫七，池上兴何如。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-23534','访皇甫七','白居易','quantangshi','','卷24','上马行数里，逢花倾一杯。
更无停泊处，还是觅君来。','',''),('quantangshi-23535','除苏州刺史别洛城东花','白居易','quantangshi','','卷24','乱雪千花落，新丝两鬓生。
老除吴郡守，春别洛阳城。
江上今重去，城东更一行。
别花何用伴，劝酒有残莺。','',''),('quantangshi-23536','奉和汴州令狐令公二十二韵','白居易','quantangshi','','卷24','客有东征者，夷门一落帆。
二年方得到，五日未为淹。
在浚旌重葺，游梁馆更添。
心因好善乐，貌为礼贤谦。
俗阜知敦劝，民安见察廉。
仁风扇道路，阴雨膏闾阎。
文律操将柄，兵机钓得钤。
碧幢油叶叶，红斾火襜襜。
景象春加丽，威容晓助严。
枪森赤豹尾，纛吒黑龙髯。
门静尘初歛，城昏日半衔。
选幽开后院，占胜坐前檐。
平展丝头毯，高褰锦额帘。
雷捶柘枝鼓，雪摆胡腾衫。
发滑歌钗坠，妆光舞汗霑。
回灯花簇簇，过酒玉纤纤。
馔盛盘心殢，醅浓盏底黏。
陆珍熊掌烂，海味蟹螯咸。
福履千夫祝，形仪四座瞻。
羊公长在岘，傅说莫归岩。
眷爱人人遍，风情事事兼。
犹嫌客不醉，同赋夜厌厌。','',''),('quantangshi-23537','船夜援琴','白居易','quantangshi','','卷24','鸟栖鱼不动，月照夜江深。
身外都无事，舟中只有琴。
七弦为益友，两耳是知音。
心静即声淡，其间无古今。','',''),('quantangshi-23538','答刘和州禹锡','白居易','quantangshi','','卷24','换印虽频命未通，历阳湖上又秋风。
不教才展休明代，为罚诗争造化功。
我亦思归田舍下，君应厌卧郡斋中。
好相收拾为闲伴，年齿官班约略同。','',''),('quantangshi-23539','渡淮','白居易','quantangshi','','卷24','淮水东南阔，无风渡亦难。
孤烟生乍直，远树望多圆。
春浪棹声急，夕阳帆影残。
清流宜映月，今夜重吟看。','',''),('quantangshi-23540','赴苏州至常州答贾舍人','白居易','quantangshi','','卷24','杭城隔岁转苏台，还拥前时五马回。
厌见簿书先眼合，喜逢杯酒暂眉开。
未酬恩宠年空去，欲立功名命不来。
一别承明三领郡，甘从人道是粗才。','',''),('quantangshi-23541','去岁罢杭州今春领吴郡慙无善政聊写鄙怀兼寄三相公','白居易','quantangshi','','卷24','为问三丞相，如何秉国钧。
那将最剧郡，付与苦慵人。
岂有吟诗客，堪为持节臣。
不才空饱暖，无惠及饥贫。
昨卧南城月，今行北境春。
铅刀磨欲尽，银印换何频。
杭老遮车辙，吴童扫路尘。
虚迎复虚送，慙见两州民。','',''),('quantangshi-23542','宣武令狐相公以诗寄赠传播吴中聊奉短草用申酬谢','白居易','quantangshi','','卷24','新诗传咏忽纷纷，楚老吴娃耳徧闻。
尽解呼为好才子，不知官是上将军。
辞人命薄多无位，战将功高少有文。
谢朓篇章韩信钺，一生双得不如君。','',''),('quantangshi-23543','自咏','白居易','quantangshi','','卷24','形容瘦薄诗情苦，岂是人间有相人。
只合一生眠白屋，何因三度拥朱轮。
金章未佩虽非贵，银榼常携亦不贫。
唯是无儿头早白，被天磨折恰平均。','',''),('quantangshi-23544','吟前篇因寄微之','白居易','quantangshi','','卷24','君颜贵茂不清羸，君句雄华不苦悲。
何事遣君还似我，髭须早白亦无儿。','',''),('quantangshi-23545','紫薇花','白居易','quantangshi','','卷24','紫薇花对紫微翁，名目虽同貌不同。
独占芳菲当夏景，不将颜色托春风。
浔阳官舍双高树，兴善僧庭一大丛。
何似苏州安置处，花堂栏下月明中。','',''),('quantangshi-23546','自到郡斋仅经旬日方专公务未及宴游偷闲走笔题二十四韵兼寄常州贾舍人湖州崔郎中仍呈吴中诸客','白居易','quantangshi','','卷24','渭北离乡客，江南守土臣。
涉途初改月，入境已经旬。
甲郡标天下，环封极海滨。
版图十万户，兵籍五千人。
自顾才能少，何堪宠命频。
冒荣慙印绶，虚奖负丝纶。
候病须通脉，防流要塞津。
救烦无若静，补拙莫如勤。
削使科条简，摊令赋役均。
以兹为报効，安敢不躬亲。
襦袴提于手，韦弦佩在绅。
敢辞称俗吏，且愿活疲民。
常未征黄霸，湖犹借寇恂。
愧无铛脚政，徒忝犬牙邻。
制诰夸黄绢，诗篇占白苹。
铜符抛不得，琼树见无因。
警寐钟传夜，催衙鼓报晨。
唯知对胥吏，未暇接亲宾。
色变云迎夏，声残鸟过春。
麦风非逐扇，梅[雨]异随轮。
武寺山如故，王楼月自新。
池塘闲长草，丝竹废生尘。
暑遣烧神酎，晴教晒舞茵。
待还公事了，亦拟乐吾身。','',''),('quantangshi-23547','题笼鹤','白居易','quantangshi','','卷24','经旬不饮酒，逾月未闻歌。
岂是风情少，其如尘事多。
虎丘慙客问，娃馆妬人过。
莫笑笼中鹤，相看去几何。','',''),('quantangshi-23548','答客问杭州','白居易','quantangshi','','卷24','为我踟蹰停酒盏，与君约略说杭州。
山名天竺堆青黛，湖号钱唐泻绿油。
大屋檐多装雁齿，小航船亦画龙头。
所嗟水路无三百，官系何因得再游。','',''),('quantangshi-23549','登阊门闲望','白居易','quantangshi','','卷24','阊门四望郁苍苍，始觉州雄土俗强。
十万夫家供课税，五千子弟守封疆。
阖闾城碧铺秋草，乌鹊桥红带夕阳。
处处楼前飘管吹，家家门外泊舟航。
云埋虎寺山藏色，月耀娃宫水放光。
曾赏钱唐嫌茂苑，今来未敢苦夸张。','',''),('quantangshi-23550','代诸妓赠送周判官','白居易','quantangshi','','卷24','妓筵今夜别姑苏，客棹明朝向镜湖。
莫泛扁舟寻范蠡，且随五马觅罗敷。
兰亭月破能回否，娃馆秋凉却到无。
好与使君为老伴，归来休染白髭须。','',''),('quantangshi-23551','秋寄微之十二韵','白居易','quantangshi','','卷24','娃馆松江北，稽城浙水东。
屈君为长吏，伴我作衰翁。
旌斾知非远，烟云望不通。
忙多对酒榼，兴少阅诗筒。
淡白秋来日，疎凉雨后风。
余霞数片绮，新月一张弓。
影满衰桐树，香凋晚蕙丛。
饥啼春谷鸟，寒怨络丝虫。
览镜头虽白，听歌耳未聋。
老愁从此遣，醉笑与谁同。
清旦方堆案，黄昏始退公。
可怜朝暮景，销在两衙中。','',''),('quantangshi-23552','池上早秋','白居易','quantangshi','','卷24','荷芰绿参差，新秋水满池。
早凉生北槛，残照下东篱。
露饱蝉声嬾，风干柳意衰。
过潘二十岁，何必更愁悲。','',''),('quantangshi-23553','郡西亭偶咏','白居易','quantangshi','','卷24','常爱西亭面北林，公私尘事不能侵。
共闲作伴无如鹤，与老相宜只有琴。
莫遣是非分作界，须教吏隐合为心。
可怜此道人皆见，但要修行功用深。','',''),('quantangshi-23554','故衫','白居易','quantangshi','','卷24','暗淡绯衫称老身，半披半曳出朱门。
袖中吴郡新诗本，襟上杭州旧酒痕。
残色过梅看向尽，故香因洗嗅犹存。
曾经烂熳三年着，欲弃空箱似少恩。','',''),('quantangshi-23555','郡中夜听李山人弹三乐','白居易','quantangshi','','卷24','风琴秋拂匣，月户夜开关。
荣启先生乐，姑苏太守闲。
传声千古后，得意一时间。
却怪钟期耳，唯听水与山。','',''),('quantangshi-23556','东城桂三首 一','白居易','quantangshi','','卷24','子堕本从天竺寺，根盘今在阖闾城。
当时应逐南风落，落向人间取次生。','',''),('quantangshi-23557','东城桂三首 二','白居易','quantangshi','','卷24','霜雪压多虽不死，荆榛长疾欲相埋。
长忧落在樵人手，卖作苏州一束柴。','',''),('quantangshi-23558','东城桂三首 三','白居易','quantangshi','','卷24','遥知天上桂花孤，试问嫦娥更要无。','',''),('quantangshi-23559','闻行简恩赐章服喜成长句寄之','白居易','quantangshi','','卷24','吾年五十加朝散，尔亦今年赐服章。
齿发恰同知命岁，官衔俱是客曹郎。
荣传锦帐花联萼，彩动绫袍雁趂行。
大抵着绯宜老大，莫嫌秋鬓数茎霜。','',''),('quantangshi-23560','唤笙歌','白居易','quantangshi','','卷24','露坠萎花槿，风吹败叶荷。
老心欢乐少，秋眼感伤多。
芳岁今如此，衰翁可奈何。
犹应不如醉，试遣唤笙歌。','',''),('quantangshi-23561','对酒吟','白居易','quantangshi','','卷24','一抛学士笔，三佩使君符。
未换银青绶，唯添雪白须。
公门衙退掩，妓席客来铺。
履舃从相近，讴吟任所须。
金衔嘶五马，钿带舞双姝。
不得当年有，犹胜到老无。
合声歌汉月，齐手拍吴歈。
今夜还先醉，应烦红袖扶。','',''),('quantangshi-23562','偶饮','白居易','quantangshi','','卷24','三盏醺醺四体融，妓亭檐下夕阳中。
千声方响敲相续，一曲[云]和戛未终。
今日心情如往日，秋风气味似春风。
唯憎小吏樽前报，道去衙时水五筒。','',''),('quantangshi-23563','早发赴洞庭舟中作','白居易','quantangshi','','卷24','阊门曙色欲苍苍，星月高低宿水光。
棹举影摇灯烛动，舟移声拽管弦长。
渐看海树红生日，遥见包山白带霜。
出郭已行十五里，唯消一曲慢霓裳。','',''),('quantangshi-23564','宿湖中','白居易','quantangshi','','卷24','水天向晚碧沉沉，树影霞光重叠深。
浸月冷波千顷练，苞霜新橘万株金。
幸无案牍何妨醉，纵有笙歌不废吟。
十只画船何处宿，洞庭山脚太湖心。','',''),('quantangshi-23565','拣贡橘书情','白居易','quantangshi','','卷24','洞庭贡橘拣宜精，太守勤王请自行。
珠颗形容随日长，琼浆气味得霜成。
登山敢惜驽骀力，望阙难伸蝼蚁情。
疎贱无由亲跪献，愿凭朱实表丹诚。','',''),('quantangshi-23566','夜泛阳坞入明月湾即事寄崔湖州','白居易','quantangshi','','卷24','湖山处处好淹留，最爱东湾北坞头。
掩映橘林千点火，泓澄潭水一盆油。
龙头画舸衔明月，鹊脚红旗蘸碧流。
为报茶山崔太守，与君各是一家游。','',''),('quantangshi-23567','泛太湖书事寄微之','白居易','quantangshi','','卷24','烟渚云帆处处通，飘然舟似入虚空。
玉杯浅酌巡初匝，金管徐吹曲未终。
黄夹缬林寒有叶，碧琉璃水净无风。
避旗飞鹭翩翻白，惊鼓跳鱼拨剌红。
涧雪压多松偃蹇，岩泉滴久石玲珑。
书为故事留湖上，吟作新诗寄浙东。
军府威容从道盛，江山气色定知同。
报君一事君应羡，五宿澄波皓月中。','',''),('quantangshi-23568','题新馆','白居易','quantangshi','','卷24','曾为白社羁游子，今作朱门醉饱身。
十万户州尤觉贵，二千石禄敢言贫。
重裘每念单衣士，兼味尝思旅食人。
新馆寒来多少客，欲回歌酒暖风尘。','',''),('quantangshi-23569','西楼喜雪命宴','白居易','quantangshi','','卷24','宿云黄惨澹，晓雪白飘颻。
散麪遮槐市，堆花压柳桥。
四郊铺缟素，万室甃琼瑶。
银榼携桑落，金炉上丽谯。
光迎舞妓动，寒近醉人销。
歌乐虽盈耳，慙无五袴谣。','',''),('quantangshi-23570','新栽梅','白居易','quantangshi','','卷24','池边新种七株梅，欲到花时点检来。
莫怕长洲桃李妬，今年好为使君开。','',''),('quantangshi-23571','酬刘和州戏赠','白居易','quantangshi','','卷24','钱唐山水接苏台，两地褰帷愧不才。
政事素无争学得，风情旧有且将来。
双蛾解佩啼相送，五马鸣珂笑却回。
不似刘郎无景行，长抛春恨在天台。','',''),('quantangshi-23572','戏和贾常州醉中二绝句 一','白居易','quantangshi','','卷24','闻道毗陵诗酒兴，近来积渐学姑苏。
罨头新令从偷去，刮骨清吟得似无。','',''),('quantangshi-23573','戏和贾常州醉中二绝句 二','白居易','quantangshi','','卷24','越调管吹留客曲，吴吟诗送暖寒杯。
娃宫无限风流事，好遣孙心暂学来。','',''),('quantangshi-23574','岁暮寄微之三首 一','白居易','quantangshi','','卷24','微之别久能无叹，知退书稀岂免愁。
甲子百年过半后，光阴一岁欲终头。
池水晓合胶船底，楼雪晴销露瓦沟。
自觉欢情随日减，苏州心不及杭州。','',''),('quantangshi-23575','岁暮寄微之三首 二','白居易','quantangshi','','卷24','荣进虽频退亦频，与君才命不调匀。
若不九重中掌事，即须千里外抛身。
紫垣南北厅曾对，沧海东西郡又邻。
唯欠结庐嵩洛下，一时归去作闲人。','',''),('quantangshi-23576','岁暮寄微之三首 三','白居易','quantangshi','','卷24','白头岁暮苦相思，除却悲吟无可为。
枕上从妨一夜睡，灯前读尽十年诗。
龙钟校正骑驴日，顦顇通江司马时。
若并如今是全活，纡朱拖紫且开眉。','',''),('quantangshi-23577','岁日家宴戏示弟侄等兼呈张侍御二十八丈殷判官二十三兄','白居易','quantangshi','','卷24','弟妹妻孥小侄甥，娇痴弄我助欢情。
岁盏后推蓝尾酒，春盘先劝胶牙饧。
形骸潦到虽堪叹，骨肉团圆亦可荣。
犹有夸张少年处，笑呼张丈唤殷兄。','',''),('quantangshi-23578','正月三日闲行','白居易','quantangshi','','卷24','黄鹂巷口莺欲语，乌鹊河头冰欲销。
绿浪东西南北水，红栏三百九十桥。
鸳鸯荡漾双双翅，杨柳交加万万条。
借问春风来早晚，只从前日到今朝。','',''),('quantangshi-23579','夜归','白居易','quantangshi','','卷24','逐胜移朝宴，留欢放晚衙。
宾寮多谢客，骑从半吴娃。
到处销春景，归时及月华。
城阴一道直，烛焰两行斜。
东吹先催柳，南霜不杀花。
臯桥夜沽酒，灯火是谁家。','',''),('quantangshi-23580','自叹','白居易','quantangshi','','卷24','岂独年相迫，兼为病所侵。
春来痰气动，老去嗽声深。
眼暗犹操笔，头斑未挂簪。
因循过日月，真是俗人心。','',''),('quantangshi-23581','郡中闲独寄微之及崔湖州','白居易','quantangshi','','卷24','少年宾旅非吾辈，晚岁簪缨束我身。
酒散更无同宿客，诗成长作独吟人。
苹洲会面知何日，镜水离心又一春。
两处也应相忆在，官高年长少情亲。','',''),('quantangshi-23582','小舫','白居易','quantangshi','','卷24','小舫一艘新造了，轻装梁柱庳安篷。
深坊静岸游应徧，浅水低桥去尽通。
黄柳影笼随棹月，白苹香起打头风。
慢牵欲傍樱桃泊，借问谁家花最红。','',''),('quantangshi-23583','马坠强出赠同座','白居易','quantangshi','','卷24','足伤遭马坠，腰重倩人抬。
秪合窗间卧，何由花下来。
坐依桃叶枝，行呷地黄杯。
强出非他意，东风落尽梅。','',''),('quantangshi-23584','夜闻贾常州崔湖州茶山境会想羡欢宴因寄此诗','白居易','quantangshi','','卷24','遥闻境会茶山夜，珠翠歌钟俱遶身。
盘下中分两州界，灯前合作一家春。
青娥遰舞应争妙，紫笋齐尝各鬬新。
自叹花时北窗下，蒲黄酒对病眠人。','',''),('quantangshi-23585','酬微之开拆新楼初毕相报末联见戏之作','白居易','quantangshi','','卷24','海山郁郁石棱棱，新豁高居正好登。
南临赡部三千界，东对蓬宫十二层。
报我楼成秋望月，把君诗读夜回灯。
无妨却有他心眼，妆点亭台即不能。','',''),('quantangshi-23586','病中多雨逢寒食','白居易','quantangshi','','卷24','水国多阴常嬾出，老夫饶病爱闲眠。
三旬卧度莺花月，一半春销风雨天。
薄暮何人吹觱篥，新晴几处缚秋千。
彩绳芳树长如旧，唯是年年换少年。','',''),('quantangshi-23587','清明夜','白居易','quantangshi','','卷24','好风胧月清明夜，碧砌红轩刺史家。
独绕回廊行复歇，遥听弦管暗看花。','',''),('quantangshi-23588','苏州柳','白居易','quantangshi','','卷24','金谷园中黄袅娜，曲江亭畔碧婆娑。
老来处处游行徧，不似苏州柳最多。
絮扑白头条拂面，使君无计奈春何。','',''),('quantangshi-23589','三月二十八日赠周判官','白居易','quantangshi','','卷24','一春惆怅残三日，醉问周郎忆得无。
柳絮送人莺劝酒，去年今日别东都。','',''),('quantangshi-23590','偶作','白居易','quantangshi','','卷24','红杏初生叶，青梅已缀枝。
阑珊花落后，寂寞酒醒时。
坐闷低眉久，行慵举足迟。
少年君莫怪，头白自应知。','',''),('quantangshi-23591','重答刘和州','白居易','quantangshi','','卷24','分无佳丽敌西施，敢有文章替左司。
随分笙歌聊自乐，等闲篇咏被人知。
花边妓引寻香径，月下僧留宿劒池。
可惜当时好风景，吴王应不解吟诗。','',''),('quantangshi-23592','奉送三兄','白居易','quantangshi','','卷24','少年曾管二千兵，昼听笙歌夜斫营。
自反丘园头尽白，每逢旗鼓眼犹明。
杭州暮醉连牀卧，吴郡春游并马行。
自愧阿连官职慢，只教兄作使君兄。','',''),('quantangshi-23593','城上夜宴','白居易','quantangshi','','卷24','留春不住登城望，惜夜相将秉烛游。
风月万家河两岸，笙歌一曲郡西楼。
诗听越客吟何苦，酒被吴娃劝不休。
从道人生都是梦，梦中欢笑亦胜愁。','',''),('quantangshi-23594','重题小舫赠周从事兼戏微之','白居易','quantangshi','','卷24','细[篷]青篾织鱼鳞，小眼红窗衬麴尘。
阔狭才容从事座，高低恰称使君身。
舞筵须拣腰轻女，仙棹难胜骨重人。
不似镜湖廉使出，高樯大艑闹惊春。','',''),('quantangshi-23595','吴樱桃','白居易','quantangshi','','卷24','含桃最说出东吴，香色鲜穠气味殊。
洽恰举头千万颗，婆娑拂面两三株。
鸟偷飞处衔将火，人摘争时蹋破珠。
可惜风吹兼雨打，明朝后日即应无。','',''),('quantangshi-23596','春尽劝客酒','白居易','quantangshi','','卷24','林下春将尽，池边日半斜。
樱桃落砌颗，夜合隔帘花。
尝酒留闲客，行茶使小娃。
残杯劝不饮，留醉向谁家。','',''),('quantangshi-23597','仲夏斋居偶题八韵寄微之及崔湖州','白居易','quantangshi','','卷24','腥血与荤蔬，停来一月余。
肌肤虽瘦损，方寸任清虚。
体适通宵坐，头慵隔日梳。
眼前无俗物，身外即僧居。
水榭风来远，松廊雨过初。
褰帘放巢燕，投食施池鱼。
久别闲游伴，频劳问疾书。
不知湖与越，吏隐兴何如。','',''),('quantangshi-23598','官宅','白居易','quantangshi','','卷24','红紫共纷纷，祗承老使君。
移舟木兰棹，行酒石榴帬。
水色窗窗见，花香院院闻。
恋他官舍住，双鬓白如云。','',''),('quantangshi-23599','六月三日夜闻蝉','白居易','quantangshi','','卷24','荷香清露坠，柳动好风生。
微月初三夜，新蝉第一声。
乍闻愁北客，静听忆东京。
我有竹林宅，别来蝉再鸣。
不知池上月，谁拨小船行。','',''),('quantangshi-23600','莲石','白居易','quantangshi','','卷24','青石一两片，白莲三四枝。
寄将东洛去，心与物相随。
石倚风前树，莲栽月下池。
遥知安置处，预想发荣时。
领郡来何远，还乡去已迟。
莫言千里别，岁晚有心期。','',''),('quantangshi-23601','眼病二首 一','白居易','quantangshi','','卷24','散乱空中千片雪，蒙笼物上一重纱。
纵逢晴景如看雾，不是春天亦看花。
僧说客尘来眼界，医言风眩在肝家。
两头治疗何曾瘥，药力微茫佛力赊。','',''),('quantangshi-23602','眼病二首 二','白居易','quantangshi','','卷24','眼藏损伤来已久，病根牢固去应难。
医师尽劝先停酒，道侣多教早罢官。
案上谩铺龙树论，盒中虚拈决明丸。
人间方药应无益，争得金箆试刮看。','',''),('quantangshi-23603','题东武丘寺六韵','白居易','quantangshi','','卷24','香刹看非远，只园入始深。
龙蟠松矫矫，玉立竹森森。
怪石千僧坐，灵池一劒沈。
海当亭两面，山在寺中心。
酒熟凭花劝，诗成倩鸟吟。
寄言轩冕客，此地好抽簪。','',''),('quantangshi-23604','夜游西武丘寺八韵','白居易','quantangshi','','卷24','不厌西丘寺，闲来即一过。
舟船转云岛，楼阁出烟萝。
路入青松影，门临白月波。
鱼跳惊秉烛，猨覰怪鸣珂。
摇曳双红斾，娉婷十翠娥。
香花助罗绮，钟梵避笙歌。
领郡时将久，游山数几何。
一年十二度，非少亦非多。','',''),('quantangshi-23605','咏怀','白居易','quantangshi','','卷24','苏杭自昔称名郡，牧守当今当好官。
两地江山蹋得徧，五年风月咏将残。
几时酒盏曾抛却，何处花枝不把看？
白发满头归得也，诗情酒兴渐阑珊。','',''),('quantangshi-23606','重咏','白居易','quantangshi','','卷24','日觉双眸暗，年惊两鬓苍。
病应无处避，老更不宜忙。
徇俗心情少，休官道理长。
今秋归去定，何必重思量。','',''),('quantangshi-23607','百日假满','白居易','quantangshi','','卷24','心中久有归田计，身上都无济世才。
长告初从百日满，故乡元约一年回。
马辞辕下头高举，鹤出笼中翅大开。
但拂衣行莫回顾，的无官职趁人来。','',''),('quantangshi-23608','九日寄微之','白居易','quantangshi','','卷24','眼暗头风事事妨，遶篱新菊为谁黄。
闲游日久心慵倦，痛饮年深肺损伤。
吴郡两回逢九月，越州四度见重阳。
怕飞杯酒多分数，厌听笙歌旧曲章。
蟋蟀声寒初过雨，茱萸色浅未经霜。
去秋共数登高会，又被今年减一场。','',''),('quantangshi-23609','题报恩寺','白居易','quantangshi','','卷24','好是清凉地，都无系绊身。
晚晴宜野寺，秋景属闲人。
净石堪敷坐，寒泉可濯巾。
自慙容鬓上，犹带郡庭尘。','',''),('quantangshi-23610','晚起','白居易','quantangshi','','卷24','卧听冬冬衙鼓声，起迟睡足长心情。
华簪脱后头虽白，堆案抛来眼校明。
闲上篮轝乘兴出，醉回花舫信风行。
明朝更濯尘缨去，闻道松江水最清。','',''),('quantangshi-23611','自思益寺次楞伽寺作','白居易','quantangshi','','卷24','朝从思益峰游后，晚到楞伽寺歇时。
照水姿容虽已老，上山筋力未全衰。
行逢禅客多相问，坐倚渔舟一自思。
犹去悬车十五载，休官非早亦非迟。','',''),('quantangshi-23612','松江亭携乐观渔宴宿','白居易','quantangshi','','卷24','震泽平芜岸，松江落叶波。
在官常梦想，为客始经过。
水面排罾网，船头簇绮罗。
朝盘鲙红鲤，夜烛舞青娥。
雁断知风急，潮平见月多。
繁丝与促管，不解和渔歌。','',''),('quantangshi-23613','宿灵岩寺上院','白居易','quantangshi','','卷24','高高白月上青林，客去僧归独夜深。
荤血屏除唯对酒，歌钟放散只留琴。
更无俗物当人眼，但有泉声洗我心。
最爱晓亭东望好，太湖烟水绿沈沈。','',''),('quantangshi-23614','酬别周从事二首 一','白居易','quantangshi','','卷24','腰痛拜迎人客倦，眼昏勾押簿书难。
辞官归去缘衰病，莫作陶潜范蠡看。','',''),('quantangshi-23615','酬别周从事二首 二','白居易','quantangshi','','卷24','洛下田园久抛掷，吴中歌酒莫留连。
嵩阳云树伊川月，已校归迟四五年。','',''),('quantangshi-23616','武丘寺路','白居易','quantangshi','','卷24','自开山寺路，水陆往来频。
银勒牵骄马，花船载丽人。
芰荷生欲徧，桃李种仍新。
好住湖堤上，长留一道春。','',''),('quantangshi-23617','齐云楼晚望偶题十韵兼呈冯侍御周殷二协律','白居易','quantangshi','','卷24','潦倒宦情尽，萧条芳岁阑。
欲辞南国去，重上北城看。
复叠江山壮，平铺井邑宽。
人稠过杨府，坊闹半长安。
插雾峰头没，穿霞日脚残。
水光红漾漾，树色绿漫漫。
约略留遗爱，殷勤念旧欢。
病抛官职易，老别友朋难。
九月全无热，西风亦未寒。
齐云楼北面，半日凭栏干。','',''),('quantangshi-23618','河亭晴望','白居易','quantangshi','','卷24','风转云头歛，烟销水面开。
晴虹桥影出，秋雁橹声来。
郡静官初罢，乡遥信未回。
明朝是重九，谁劝菊花杯。','',''),('quantangshi-23619','留别微之','白居易','quantangshi','','卷24','干时久与本心违，悟道深知前事非。
犹厌劳形辞郡印，那将趂伴着朝衣。
五千言里教知足，三百篇中劝式微。
少室云边伊水畔，比君校老合先归。','',''),('quantangshi-23620','自喜','白居易','quantangshi','','卷24','自喜天教我少缘，家徒行计两翩翩。
身兼妻子都三口，鹤与琴书共一船。
僮仆减来无冗食，资粮算外有余钱。
携将贮作丘中费，犹免饥寒得数年。','',''),('quantangshi-23621','武丘寺路宴留别诸妓','白居易','quantangshi','','卷24','银泥帬映锦障泥，画舸停桡马簇蹄。
清管曲终鹦鹉语，红旗影动䮂䮧嘶。
渐消醉色朱颜浅，欲语离情翠黛低。
莫忘使君吟咏处，女坟湖北武丘西。','',''),('quantangshi-23622','江上对酒二首 一','白居易','quantangshi','','卷24','酒助疎顽性，琴资缓慢情。
有慵将送老，无智可劳生。
忽忽忘机坐，伥伥任运行。
家乡安处是，那独在神京。','',''),('quantangshi-23623','江上对酒二首 二','白居易','quantangshi','','卷24','久贮沧浪意，初辞桎梏身。
昏昏常带酒，默默不应人。
坐稳便箕踞，眠多爱欠伸。
客来存礼数，始着白纶巾。','',''),('quantangshi-23624','望亭驿酬别周判官','白居易','quantangshi','','卷24','何事出长洲，连宵饮不休。
醒应难作别，欢渐少于愁。
灯火穿村市，笙歌上驿楼。
何言五十里，已不属苏州。','',''),('quantangshi-23625','见小侄龟儿咏灯诗并腊娘制衣因寄行简','白居易','quantangshi','','卷24','已知腊子能裁服，复报龟儿解咏灯。
巧妇才人常薄命，莫教男女苦多能。','',''),('quantangshi-23626','酒筵上答张居士','白居易','quantangshi','','卷24','但要前尘减，无妨外相同。
虽过酒肆上，不离道场中。
弦管声非实，花钿色是空。
何人知此义，唯有净名翁。','',''),('quantangshi-23627','鹦鹉','白居易','quantangshi','','卷24','陇西鹦鹉到江东，养得经年觜渐红。
常恐思归先剪翅，每因餧食暂开笼。
人怜巧语情虽重，鸟忆高飞意不同。
应似朱门歌舞妓，深藏牢闭后房中。','',''),('quantangshi-23628','听琵琶妓弹略略','白居易','quantangshi','','卷24','腕软拨头轻，新教略略成。
四弦千遍语，一曲万重情。
法向师边得，能从意上生。
莫欺江外手，别是一家声。','',''),('quantangshi-23629','写新诗寄微之偶题卷后','白居易','quantangshi','','卷24','写了吟看满卷愁，浅红牋纸小银钩。
未容寄与微之去，已被人传到越州。','',''),('quantangshi-23630','宝历二年八月三十日夜梦后作','白居易','quantangshi','','卷24','尘缨忽解诚堪喜，世网重来未可知。
莫忘全吴馆中梦，岭南泥雨步行时。','',''),('quantangshi-23631','与梦得同登栖灵塔','白居易','quantangshi','','卷24','半月悠悠在广陵，何楼何塔不同登。
共怜筋力犹堪在，上到栖灵第九层。','',''),('quantangshi-23632','梦苏州水阁寄冯侍御','白居易','quantangshi','','卷24','扬州驿里梦苏州，梦到花桥水阁头。
觉后不知冯侍御，此中昨夜共谁游。','',''),('quantangshi-23633','喜罢郡','白居易','quantangshi','','卷24','五年两郡亦堪嗟，偷出游山走看花。
自此光阴为己有，从前日月属官家。
樽前免被催迎使，枕上休闻报坐衙。
睡到午时欢到夜，回看官职是泥沙。','',''),('quantangshi-23634','答次休上人','白居易','quantangshi','','卷24','姓白使君无丽句，名休座主有新文。
禅心不合生分别，莫爱余霞嫌碧云。','',''),('quantangshi-23635','感悟妄缘题如上人壁','白居易','quantangshi','','卷24','自从为呆童，直至作衰翁。
所好随年异，为忙终日同。
弄沙成佛塔，锵玉谒王宫。
彼此皆儿戏，须臾即色空。
有营非了义，无着是真宗。
兼恐勤修道，犹应在妄中。','',''),('quantangshi-23636','思子台有感二首 一','白居易','quantangshi','','卷24','曾家机上闻投杼，尹氏园中见掇蜂。
但以恩情生隙罅，何人不解作江充。','',''),('quantangshi-23637','思子台有感二首 二','白居易','quantangshi','','卷24','暗生魑魅蠹生虫，何异谗生疑阻中。
但使武皇心似烛，江充不敢作江充。','',''),('quantangshi-23638','赋得边城角','白居易','quantangshi','','卷24','边角两三枝，霜天陇上儿。
望乡相并立，向月一时吹。
战马头皆举，征人手尽垂。
呜呜三奏罢，城上展旌旗。','',''),('quantangshi-23639','忆洛中所居','白居易','quantangshi','','卷24','忽忆东都宅，春来事宛然。
雪销行径里，水上卧房前。
厌绿栽黄竹，嫌红种白莲。
醉教鸎送酒，闲遣鹤看船。
幸是林园主，慙为食禄牵。
宦情薄似纸，乡思急于弦。
岂合姑苏守，归休更待年。','',''),('quantangshi-23640','想归田园','白居易','quantangshi','','卷24','恋他朝市求何事，想取丘园乐此身。
千首恶诗吟过日，一壶好酒醉消春。
归乡年亦非全老，罢郡家仍未苦贫。
快活不知如我者，人间能有几多人。','',''),('quantangshi-23641','琴茶','白居易','quantangshi','','卷24','兀兀寄形羣动内，陶陶任性一生间。
自抛官后春多醉，不读书来老更闲。
琴里知闻唯渌水，茶中故旧是蒙山。
穷通行止长相伴，谁道吾今无往还。','',''),('quantangshi-23642','赠楚州郭使君','白居易','quantangshi','','卷24','淮水东南第一州，山围雉堞月当楼。
黄金印绶悬腰底，白雪歌诗落笔头。
笑看儿童骑竹马，醉携宾客上仙舟。
当家美事堆身上，何啻林宗与细侯。','',''),('quantangshi-23643','和郭使君题枸杞','白居易','quantangshi','','卷24','山阳太守政严明，吏静人安无犬惊。
不知灵药根成狗，怪得时闻吠夜声。','',''),('quantangshi-23644','初到洛下闲游','白居易','quantangshi','','卷24','汉庭重少身宜退，洛下闲居迹可逃。
趂伴入朝应老丑，寻春放醉尚粗豪。
诗携彩纸新装卷，酒典绯花旧赐袍。
曾在东方千骑上，至今躞蹀马头高。','',''),('quantangshi-23645','醉赠刘二十八使君','白居易','quantangshi','','卷24','为我引杯添酒饮，与君把箸击盘歌。
诗称国手徒为尔，命压人头不奈何。
举眼风光长寂寞，满朝官职独蹉跎。
亦知合被才名折，二十三年折太多。','',''),('quantangshi-23646','太湖石','白居易','quantangshi','','卷24','烟翠三秋色，波涛万古痕。
削成青玉片，截断碧云根。
风气通岩穴，苔文护洞门。
三峰具体小，应是华山孙。','',''),('quantangshi-23647','过敷水','白居易','quantangshi','','卷24','垂鞭欲渡罗敷水，处分鸣驺且缓驱。
秦氏双蛾久冥漠，苏台五马尚踟蹰。
村童店女仰头笑，今日使君真是愚。','',''),('quantangshi-23648','南院','白居易','quantangshi','','卷24','林院无情绪，经春不一开。
杨花飞作穗，榆荚落成堆。
壮气从中减，流年逐后催。
只应如过客，病去老迎来。','',''),('quantangshi-23649','闲咏','白居易','quantangshi','','卷24','步月怜清景，眠松爱绿阴。
早年诗思苦，晚岁道情深。
夜学禅多坐，秋牵兴暂吟。
悠然两事外，无处更留心。','',''),('quantangshi-23650','初授祕监拜赐金紫闲吟小酌偶写所怀','白居易','quantangshi','','卷24','紫袍新祕监，白首旧书生。
鬓雪人间寿，腰金世上荣。
子孙无可念，产业不能营。
酒引眼前兴，诗留身后名。
闲倾三数酌，醉咏十余声。
便是羲皇代，先从心太平。','',''),('quantangshi-23651','新昌闲居招杨郎中兄弟','白居易','quantangshi','','卷24','纱巾角枕病眠翁，忙少闲多谁与同。
但有双松当砌下，更无一事到心中。
金章紫绶堪如梦，皂盖朱轮别似空。
暑月贫家何所有，客来唯赠北窗风。','',''),('quantangshi-23652','祕省后厅','白居易','quantangshi','','卷24','槐花雨润新秋地，桐叶风翻欲夜天。
尽日后厅无一事，白头老监枕书眠。','',''),('quantangshi-23653','松斋偶兴','白居易','quantangshi','','卷24','置心思虑外，灭迹是非间。
约俸为生计，随官换往还。
耳烦闻晓角，眼醒见秋山。
赖此松檐下，朝回半日闲。','',''),('quantangshi-23654','和杨郎中贺杨仆射致仕后杨侍郎门生合宴席上作','白居易','quantangshi','','卷24','业重关西继大名，恩深阙下遂高情。
祥鳣降伴趋庭鲤，贺燕飞和出谷莺。
范蠡舟中无子弟，疏家席上欠门生。
可怜玉树连桃李，从古无如此会荣。','',''),('quantangshi-23655','松下琴赠客','白居易','quantangshi','','卷24','松寂风初定，琴清夜欲阑。
偶因羣动息，试拨一声看。
寡鹤当徽怨，秋泉应指寒。
慙君此倾听，本不为君弹。','',''),('quantangshi-23656','秋斋','白居易','quantangshi','','卷24','晨起秋斋冷，萧条称病容。
清风两窗竹，白露一庭松。
阮籍谋身拙，嵇康向事慵。
生涯别有处，浩气在心胸。','',''),('quantangshi-23657','涂山寺独游','白居易','quantangshi','','卷24','野径行无伴，僧房宿有期。
涂山来去熟，唯是马蹄知。','',''),('quantangshi-23658','登观音台望城','白居易','quantangshi','','卷24','百千家似围棊局，十二街如种菜畦。
遥认微微入朝火，一条星宿五门西。','',''),('quantangshi-23659','登灵应台北望','白居易','quantangshi','','卷24','临高始见人寰小，对远方知色界空。
回首却归朝市去，一稊米落太仓中。','',''),('quantangshi-23660','酬裴相公题兴化小池见招长句','白居易','quantangshi','','卷24','为爱小塘招散客，不嫌老监与新诗。
山公倒载无妨学，范蠡扁舟未要追。
蓬断偶飘桃李径，鸥惊误拂凤皇池。
敢辞课拙酬高韵，一勺争禁万顷陂。','',''),('quantangshi-23661','闲行','白居易','quantangshi','','卷24','五十年来思虑熟，忙人应未胜闲人。
林园傲逸真成贵，衣食单疎不是贫。
专掌图书无过地，遍寻山水自由身。
傥年七十犹强健，尚得闲行十五春。','',''),('quantangshi-23662','闲出','白居易','quantangshi','','卷24','兀兀出门何处去，新昌街晚树阴斜。
马蹄知意缘行熟，不向杨家即庾家。','',''),('quantangshi-23663','与僧智如夜话','白居易','quantangshi','','卷24','嬾钝尤知命，幽栖渐得朋。
门闲无谒客，室静有禅僧。
炉向初冬火，笼停半夜灯。
忧劳缘智巧，自喜百无能。','',''),('quantangshi-23664','忆庐山旧隐及洛下新居','白居易','quantangshi','','卷24','形骸僶俛班行内，骨肉句留俸禄中。
无奈攀缘随手长，亦知恩爱到头空。
草堂久闭庐山下，竹院新抛洛水东。
自是未能归去得，世间谁要白须翁。','',''),('quantangshi-23665','晚寒','白居易','quantangshi','','卷24','急景流如箭，凄风利似刀。
暝催鸡翅歛，寒束树枝高。
缩水浓和酒，加緜厚絮袍。
可怜冬计毕，暖卧醉陶陶。','',''),('quantangshi-23666','偶眠','白居易','quantangshi','','卷24','放杯书案上，枕臂火炉前。
老爱寻思事，慵多取次眠。
妻教卸乌帽，婢与展青氊。
便是屏风样，何劳画古贤。','',''),('quantangshi-23667','华城西北雉堞最高崔相公首创楼台钱左丞继种花果合为胜境题在雅篇岁暮独游怅然成咏','白居易','quantangshi','','卷24','高居称君子，潇洒四无邻。
丞相栋梁久，使君桃李新。
凝情看丽句，驻步想清尘。
况是寒天客，楼空无主人。','',''),('quantangshi-23668','奉使途中戏赠张常侍','白居易','quantangshi','','卷24','早风吹土满长衢，驿骑星轺尽疾驱。
共笑篮舁亦称使，日驰一驿向东都。','',''),('quantangshi-23669','有小白马乘驭多时奉使东行至稠桑驿溘然而毙足可惊伤不能忘情题二十韵','白居易','quantangshi','','卷24','能骤复能驰，翩翩白马儿。
毛寒一团雪，鬃薄万条丝。
皂盖春行日，骊驹晓从时。
双旌前独步，五马内偏骑。
芳草承蹄叶，垂杨拂顶枝。
跨将迎好客，惜不换妖姬。
慢鞚游萧寺，闲驱醉习池。
睡来乘作梦，兴发倚成诗。
鞭为驯难下，鞍缘稳不离。
北归还共到，东使亦相随。
赭白何曾变，玄黄岂得知。
嘶风觉声急，蹋雪怪行迟。
昨夜犹刍秣，今朝尚絷维。
卧槽应不起，顾主遂长辞。
尘灭骎骎迹，霜留皎皎姿。
度关形未改，过隙影难追。
念倍燕求骏，情深项别骓。
银收钩臆带，金卸络头羁。
何处埋奇骨，谁家觅弊帷。
稠桑驿门外，吟罢涕双垂。','',''),('quantangshi-23670','题喷玉泉','白居易','quantangshi','','卷24','泉喷声如玉，潭澄色似空。
练垂青嶂上，珠泻绿盆中。
溜滴三秋雨，寒生六月风。
何时此岩下，来作濯缨翁。','',''),('quantangshi-23671','酬皇甫宾客','白居易','quantangshi','','卷24','闲官兼慢使，着处易停轮。
况欲逢新岁，仍初见故人。
冒寒寻到洛，待暖始归秦。
亦拟同携手，城东畧看春。','',''),('quantangshi-23672','种白莲','白居易','quantangshi','','卷24','吴中白藕洛中栽，莫恋江南花嬾开。
万里携归尔知否，红蕉朱槿不将来。','',''),('quantangshi-23673','答苏庶子','白居易','quantangshi','','卷24','偶作关东使，重陪洛下游。
病来从断酒，老去可禁愁。
款曲偏青眼，蹉跎各白头。
蓬山闲气味，依约似龙楼。','',''),('quantangshi-23674','答尉迟少监水阁重宴','白居易','quantangshi','','卷24','人情依旧岁华新，今日重招往日宾。
鸡黍重回千里驾，林园暗换四年春。
水轩平写琉璃镜，草岸斜铺翡翠茵。
闻道经营费心力，忍教成后属他人。','',''),('quantangshi-23675','和刘郎中伤鄂姬','白居易','quantangshi','','卷24','不独君嗟我亦嗟，西风北雪杀南花。
不知月夜魂归处，鹦鹉洲头第几家。','',''),('quantangshi-23676','赠东邻王十三','白居易','quantangshi','','卷24','携手池边月，开襟竹下风。
驱愁知酒力，破睡见茶功。
居处东西接，年颜老少同。
能来为伴否，伊上作渔翁。','',''),('quantangshi-23677','早春同刘郎中寄宣武令狐相公','白居易','quantangshi','','卷24','梁园不到一年强，遥想清吟对绿觞。
更有何人能饮酌，新添几卷好篇章。
马头拂柳时回辔，豹尾穿花暂亚枪。
谁引相公开口笑，不逢白监与刘郎。','',''),('quantangshi-23678','寄太原李相公','白居易','quantangshi','','卷24','闻道北都今一变，政和军乐万人安。
绮罗二八围宾榻，组练三千夹将坛。
蝉鬓应夸丞相少，貂裘不觉太原寒。
世间大有虚荣贵，百岁无君一日欢。','',''),('quantangshi-23679','雪中寄令狐相公兼呈梦得','白居易','quantangshi','','卷24','兔园春雪梁王会，想对金罍咏玉尘。
今日相如身在此，不知客右坐何人。','',''),('quantangshi-23680','出使在途所骑马死改乘肩轝将归长安偶咏旅怀寄太原李相公','白居易','quantangshi','','卷24','驿路崎岖泥雪寒，欲登篮轝一长叹。
风光不见桃花骑，尘土空留杏叶鞍。
丧乘独归殊不易，脱骖相赠岂为难。
并州好马应无数，不怕旌旄试觅看。','',''),('quantangshi-23681','有双鹤留在洛中忽见刘郎中依然鸣顾刘因为鹤叹二篇寄予予以二绝句答之 一','白居易','quantangshi','','卷24','辞乡远隔华亭水，逐我来栖缑岭云。
惭愧稻粱长不饱，未曾回眼向鸡羣。','',''),('quantangshi-23682','有双鹤留在洛中忽见刘郎中依然鸣顾刘因为鹤叹二篇寄予予以二绝句答之 二','白居易','quantangshi','','卷24','荒草院中池水畔，衔恩不去又经春。
见君惊喜双回顾，应为吟声似主人。','',''),('quantangshi-23683','宿窦使君庄水亭','白居易','quantangshi','','卷24','使君何在在江东，池柳初黄杏欲红。
有兴即来闲便宿，不知谁是主人翁。','',''),('quantangshi-23684','龙门下作','白居易','quantangshi','','卷24','龙门涧下濯尘缨，拟作闲人过此生。
筋力不将诸处用，登山临水咏诗行。','',''),('quantangshi-23685','姚侍御见过戏赠','白居易','quantangshi','','卷24','晚起春寒慵裹头，客来池上偶同游。
东台御史多提举，莫按金章系布裘。','',''),('quantangshi-23686','履道春居','白居易','quantangshi','','卷24','微雨洒园林，新晴好一寻。
低风洗池面，斜日拆花心。
暝助岚阴重，春添水色深。
不如陶省事，犹抱有弦琴。','',''),('quantangshi-23687','题洛中第宅','白居易','quantangshi','','卷24','水木谁家宅，门高占地宽。
悬鱼挂青甃，行马护朱栏。
春榭笼烟暖，秋庭锁月寒。
松胶黏琥珀，筠粉扑琅玕。
试问池台主，多为将相官。
终身不曾到，唯展宅图看。','',''),('quantangshi-23688','寄殷协律','白居易','quantangshi','','卷24','五岁优游同过日，一朝消散[似]浮云。
琴诗酒伴皆抛我，雪月花时最忆君。
几度听鸡歌白日，亦曾骑马咏红裙。
吴娘暮雨萧萧曲，自别江南更不闻。','',''),('quantangshi-23689','洛下诸客就宅相送偶题西亭','白居易','quantangshi','','卷24','几榻临池坐，轩车冒雪过。
交亲致杯酒，僮仆解笙歌。
流岁行将晚，浮荣得几多。
林泉应问我，不住意如何。','',''),('quantangshi-23690','答林泉','白居易','quantangshi','','卷24','好住旧林泉，回头一怅然。
渐知吾潦倒，深愧尔留连。
欲作栖云计，须营种黍钱。
更容求一郡，不得亦归田。','',''),('quantangshi-23691','将发洛中枉令狐相公手札兼辱二篇宠行以长句答之','白居易','quantangshi','','卷24','尺素忽惊来梓泽，双金不惜送蓬山。
八行落泊飞云雨，五字枪鏦动佩环。
玉韵乍听堪醒酒，银钩细读当披颜。
收藏便作终身宝，何啻三年怀袖间。','',''),('quantangshi-23692','临都驿答梦得六言二首 一','白居易','quantangshi','','卷24','扬子津头月下，临都驿里灯前。
昨日老于前日，去年春似今年。','',''),('quantangshi-23693','临都驿答梦得六言二首 二','白居易','quantangshi','','卷24','谢守归为秘监，冯公老作郎官。
前事不须问着，新诗且更吟看。','',''),('quantangshi-23694','喜钱左丞再除华州以诗伸贺','白居易','quantangshi','','卷24','左辖辍中台，门东委上才。
彤襜经宿到，绛帐及春开。
民望恳难夺，天心慈易回。
那知不隔岁，重借寇恂来。','',''),('quantangshi-23695','和钱华州题少华清光绝句','白居易','quantangshi','','卷24','高情雅韵三峯守，主领清光管白云。
自笑亦曾为刺史，苏州肥腻不如君。','',''),('quantangshi-23696','送陕府王大夫','白居易','quantangshi','','卷24','金马门前回劒佩，铁牛城下拥旌旗。
他时万一为交代，留取甘棠三两枝。','',''),('quantangshi-23697','代迎春花招刘郎中','白居易','quantangshi','','卷24','幸与松筠相近栽，不随桃李一时开。
杏园岂敢妨君去，未有花时且看来。','',''),('quantangshi-23698','翫迎春花赠杨郎中','白居易','quantangshi','','卷24','金英翠萼带春寒，黄色花中有几般。
凭君与向游人道，莫作蔓菁花眼看。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-23699','闲出','白居易','quantangshi','','卷24','身外无羁束，心中少是非。
被花留便住，逢酒醉方归。
人事行时少，官曹入日稀。
春寒游正好，稳马薄绵衣。','',''),('quantangshi-23700','座上赠卢判官','白居易','quantangshi','','卷24','把酒承花花落频，花香酒味相和春。
莫言不是江南会，虚白亭中旧主人。','',''),('quantangshi-23701','曲江有感','白居易','quantangshi','','卷24','曲江西岸又春风，万树花前一老翁。
遇酒逢花还且醉，若论惆怅事何穷。','',''),('quantangshi-23702','杏园花下赠刘郎中','白居易','quantangshi','','卷24','怪君把酒偏惆怅，曾是贞元花下人。
自别花来多少事，东风二十四回春。','',''),('quantangshi-23703','花前有感兼呈崔相公刘郎中','白居易','quantangshi','','卷24','落花如雪鬓如霜，醉把花看益自伤。
少日为名多检束，长年无兴可颠狂。
四时轮转春常少，百刻支分夜苦长。
何事同生壬子岁，老于崔相及刘郎。','',''),('quantangshi-23704','微之就拜尚书居易续除刑部因书贺意兼咏离怀','白居易','quantangshi','','卷24','我为宪部入南宫，君作尚书镇浙东。
老去一时成白首，别来七度换春风。
簪缨假合虚名在，筋力销磨实事空。
远地官高亲故少，些些谈笑与谁同。','',''),('quantangshi-23705','喜与韦左丞同入南省因叙旧以赠之','白居易','quantangshi','','卷24','早年同遇陶钧主，利钝精粗共在镕。
金劒淬来长透匣，铅刀磨尽不成锋。
差肩北省慙非据，接武南宫幸再容。
跛鼈虽迟骐骥疾，何妨中路亦相逢。','',''),('quantangshi-23706','伊州','白居易','quantangshi','','卷24','老去将何散老愁，新教小玉唱伊州。
亦应不得多年听，未教成时已白头。','',''),('quantangshi-23707','早朝','白居易','quantangshi','','卷24','鼓动出新昌，鸡鸣赴建章。
翩翩稳鞍马，楚楚健衣裳。
宫漏传残夜，城阴送早凉。
月堤槐露气，风烛桦烟香。
双阙龙相对，千官雁一行。
汉庭方尚少，慙叹鬓如霜。','',''),('quantangshi-23708','答裴相公乞鹤','白居易','quantangshi','','卷24','警露声音好，冲天相貌殊。
终宜向辽廓，不称在泥涂。
白首劳为伴，朱门幸见呼。
不知疎野性，解爱凤池无。','',''),('quantangshi-23709','晚从省归','白居易','quantangshi','','卷24','朝回北阙值清晨，晚出南宫送暮春。
入去丞郎非散秩，归来诗酒是闲人。
犹思泉石多成梦，尚叹簪裾未离身。
终是不如山下去，心头眼底两无尘。','',''),('quantangshi-23710','北窗闲坐','白居易','quantangshi','','卷24','虚窗两丛竹，静室一炉香。
门外红尘合，城中白日忙。
无烦寻道士，不要学仙方。
自有延年术，心闲岁月长。','',''),('quantangshi-23711','酬严给事','白居易','quantangshi','','卷24','嬴女偷乘凤去时，洞中潜歇弄琼枝。
不缘啼鸟春饶舌，青琐仙郎可得知。','',''),('quantangshi-23712','京路','白居易','quantangshi','','卷24','西来为看秦山雪，东去缘寻洛苑春。
来去腾腾两京路，闲行除我更无人。','',''),('quantangshi-23713','华州西','白居易','quantangshi','','卷24','每逢人静慵多歇，不计程行困即眠。
上得篮轝未能去，春风敷水店门前。','',''),('quantangshi-23714','从陕至东京','白居易','quantangshi','','卷24','从陕至东京，山低路渐平。
风光四百里，车马十三程。
花共垂鞭看，杯多并辔倾。
笙歌与谈笑，随分自将行。','',''),('quantangshi-23715','送春','白居易','quantangshi','','卷24','银花凿落从君劝，金屑琵琶为我弹。
不独送春兼送老，更尝一着更听看。','',''),('quantangshi-23716','宿杜曲花下','白居易','quantangshi','','卷24','觅得花千树，携来酒一壶。
嬾归兼拟宿，未醉岂劳扶。
但惜春将晚，宁愁日渐晡。
篮轝为卧舍，漆盝是行厨。
斑竹盛茶柜，红泥罨饭炉。
眼前无所阙，身外更何须。
小面琵琶婢，苍头觱篥奴。
从君饱富贵，曾作此游无。','',''),('quantangshi-23717','逢旧','白居易','quantangshi','','卷24','久别偶相逢，俱疑是梦中。
即今欢乐事，放盏又成空。','',''),('quantangshi-23718','绣妇叹','白居易','quantangshi','','卷24','连枝花样绣罗襦，本拟新年饷小姑。
自觉逢春饶怅望，谁能每日趂功夫。
针头不解愁眉结，线缕难穿泪脸珠。
虽凭绣牀都不绣，同牀绣伴得知无。','',''),('quantangshi-23719','春词','白居易','quantangshi','','卷24','低花树暎小妆楼，春入眉心两点愁。
斜倚栏干背鹦鹉，思量何事不回头。','',''),('quantangshi-23720','恨词','白居易','quantangshi','','卷24','翠黛眉低歛，红珠泪暗销。
从来恨人意，不省似今朝。','',''),('quantangshi-23721','山石榴花十二韵','白居易','quantangshi','','卷24','晔晔复煌煌，花中无比方。
艳夭宜小院，条短称低廊。
本是山头物，今为砌下芳。
千丛相向背，万朵互低昂。
照灼连朱槛，玲珑暎粉墙。
风来添意态，日出助晶光。
渐绽胭脂萼，犹含琴轸房。
离披乱剪彩，斑驳未匀妆。
绛焰灯千炷，红裙妓一行。
此时逢国色，何处觅天香？
恐合栽金阙，思将献玉皇。
好差青鸟使，封作百花王。','',''),('quantangshi-23722','送敏中归豳宁幕','白居易','quantangshi','','卷24','六十衰翁儿女悲，傍人应笑尔应知。
弟兄垂老相逢日，杯酒临欢欲散时。
前路加餐须努力，今宵尽醉莫推辞。
司徒知我难为别，直过秋归未讶迟。','',''),('quantangshi-23723','宴散','白居易','quantangshi','','卷24','小宴追凉散，平桥步月回。
笙歌归院落，灯火下楼台。
残暑蝉催尽，新秋雁带来。
将何迎睡兴，临卧举残杯。','',''),('quantangshi-23724','人定','白居易','quantangshi','','卷24','人定月胧明，香消枕簟清。
翠屏遮烛影，红袖下帘声。
坐久吟方罢，眠初梦未成。
谁家教鹦鹉，故故语相惊。','',''),('quantangshi-23725','池上','白居易','quantangshi','','卷24','褭褭凉风动，凄凄寒露零。
兰衰花始白，荷破叶犹青。
独立栖沙鹤，双飞照水萤。
若为寥落境，仍值酒初醒。','',''),('quantangshi-23726','池窗','白居易','quantangshi','','卷24','池晚莲芳谢，窗秋竹意深。
更无人作伴，唯对一张琴。','',''),('quantangshi-23727','花酒','白居易','quantangshi','','卷24','香醅浅酌浮如蚁，雪鬓新梳薄似蝉。
为报洛城花酒道，莫辞送老二三年。','',''),('quantangshi-23728','题崔常侍济源庄','白居易','quantangshi','','卷24','谷口谁家住，云扃锁竹泉。
主人何处去，萝薜换貂蝉。
籍在金闺内，班排玉扆前。
诚知忆山水，归得是何年。','',''),('quantangshi-23729','认春戏呈冯少尹李郎中陈主簿','白居易','quantangshi','','卷24','认得春风先到处，西园南面水东头。
柳初变后条犹重，花未开时枝已稠。
暗助醉欢寻绿酒，潜添睡兴着红楼。
知君未别阳和意，直待春深始拟游。','',''),('quantangshi-23730','魏堤有怀','白居易','quantangshi','','卷24','魏王堤下水，声似使君滩。
惆怅回头听，踌蹰立马看。
荡风波眼急，翻雪浪心寒。
忆得瞿唐事，重吟行路难。','',''),('quantangshi-23731','柘枝词','白居易','quantangshi','','卷24','柳暗长廊合，花深小院开。
苍头铺锦褥，皓腕捧银杯。
绣帽珠稠缀，香衫袖窄裁。
将军拄球杖，看按柘枝来。','',''),('quantangshi-23732','代梦得吟','白居易','quantangshi','','卷24','后来变化三分贵，同辈凋零太半无。
世上争先从尽汝，人间鬬在不如吾。
竿头已到应难久，局势虽迟未必输。
不见山苗与林叶，迎春先绿亦先枯。','',''),('quantangshi-23733','寄答周协律','白居易','quantangshi','','卷24','故人叙旧寄新篇，惆怅江南到眼前。
暗想楼台万余里，不闻歌吹一周年。
桥头谁更看新月，池畔犹应泊旧船。
最忆后庭杯酒散，红屏风掩绿窗眠。','',''),('quantangshi-23734','太和戊申岁大有年诏赐百寮出城观稼谨书盛事以俟采诗','白居易','quantangshi','','卷24','清晨承诏命，丰岁阅田闾。
膏雨抽苗足，凉风吐穗初。
早禾黄错落，晚稻绿扶疎。
好入诗家咏，宜令史馆书。
散为万姓食，堆作九年储。
莫道如云稼，今秋云不如。','',''),('quantangshi-23735','赠悼怀太子挽歌辞二首 一','白居易','quantangshi','','卷24','竹马书薨岁，铜龙表葬时。
永言窀穸事，全用少阳仪。
寿夭由天命，哀荣出圣慈。
恭闻褒赠诏，轸念在与夷。','',''),('quantangshi-23736','赠悼怀太子挽歌辞二首 二','白居易','quantangshi','','卷24','剪叶藩封早，承华册命尊。
笙歌辞洛苑，风雪蔽梁园。
卤簿凌霜宿，铭旌向月翻。
宫寮不逮事，哭送出都门。','',''),('quantangshi-23737','雨中招张司业宿','白居易','quantangshi','','卷24','过夏衣香润，迎秋簟色鲜。
斜支花石枕，卧咏蘂珠篇。
泥泞非游日，阴沈好睡天。
能来同宿否，听雨对牀眠。','',''),('quantangshi-23738','和集贤刘学士早朝作','白居易','quantangshi','','卷24','吟君昨日早朝诗，金御炉前唤仗时。
烟吐白龙头宛转，扇开青雉尾参差。
暂留春殿多称屈，合入纶闱即可知。
从此摩霄去非晚，鬓边未有一茎丝。','',''),('quantangshi-23739','送陕州王司马建赴任','白居易','quantangshi','','卷24','陕州司马去何如，养静资贫两有余。
公事闲忙同少尹，料钱多少敌尚书。
秪携美酒为行伴，唯作新诗趂下车。
自有铁牛无咏者，料君投刃必应虚。','',''),('quantangshi-23740','对琴待月','白居易','quantangshi','','卷24','竹院新晴夜，松窗未卧时。
共琴为老伴，与月有秋期。
玉轸临风久，金波出雾迟。
幽音待清景，唯是我心知。','',''),('quantangshi-23741','杨家南亭','白居易','quantangshi','','卷24','小亭门向月斜开，满地凉风满地苔。
此院好弹秋思处，终须一夜抱琴来。','',''),('quantangshi-23742','早寒','白居易','quantangshi','','卷24','黄叶聚墙角，青苔围柱根。
被经霜后薄，镜遇雨来昏。
半卷寒檐幕，斜开暖阁门。
迎冬兼送老，只仰酒盈尊。','',''),('quantangshi-23743','斋月静居','白居易','quantangshi','','卷24','病来心静一无思，老去身闲百不为。
忽忽眼尘犹爱睡，些些口业尚夸诗。
荤腥每断斋居月，香火常亲宴坐时。
万虑消停百神泰，唯应寂寞杀三尸。','',''),('quantangshi-23744','宿裴相公兴化池亭','白居易','quantangshi','','卷24','林亭一出宿风尘，忘却平津是要津。
松阁晴看山色近，石渠秋放水声新。
孙弘阁闹无闲客，傅说舟忙不借人。
何似抡才济川外，别开池馆待交亲。','',''),('quantangshi-23745','和刘郎中望终南山秋雪','白居易','quantangshi','','卷24','遍览古今集，都无秋雪诗。
阳春先唱后，阴岭未消时。
草讶霜凝重，松疑鹤散迟。
清光莫独占，亦对白云司。','',''),('quantangshi-23746','广府胡尚书频寄诗因答绝句','白居易','quantangshi','','卷24','尚书清白临南海，虽饮贪泉心不回。
唯向诗中得珠玉，时时寄到帝乡来。','',''),('quantangshi-23747','送鹤与裴相临别赠诗','白居易','quantangshi','','卷24','司空爱尔尔须知，不信听吟送鹤诗。
羽翮势高宁惜别，稻粱恩厚莫愁饥。
夜栖少共鸡争树，晓浴先饶凤占池。
稳上青云勿回顾，的应胜在白家时。','',''),('quantangshi-23748','令狐相公拜尚书后有喜从镇归朝之作刘郎中先和因以继之','白居易','quantangshi','','卷24','车骑新从梁苑回，履声佩响入中台。
凤池望在终重去，龙节功成且纳来。
金勒最宜乘雪出，玉觞何必待花开。
尚书首唱郎中和，不计官资只计才。','',''),('quantangshi-23749','送河南尹冯学士赴任','白居易','quantangshi','','卷24','石渠金谷中间路，轩骑翩翩十日程。
清洛饮冰添苦节，碧嵩看雪助高情。
谩夸河北操旄钺，莫羡江西拥斾旌。
何似府寮京令外，别教三十六峰迎。','',''),('quantangshi-23750','读鄂公传','白居易','quantangshi','','卷24','高卧深居不见人，功名斗薮似灰尘。
唯留一部清商乐，月下风前伴老身。','',''),('quantangshi-23751','乌夜啼','白居易','quantangshi','','卷24','城上归时晚，庭前宿处危。
月明无叶树，霜滑有风枝。
啼涩饥喉咽，飞低冻翅垂。
画堂鹦鹉鸟，冷暖不相知。','',''),('quantangshi-23752','镜换杯','白居易','quantangshi','','卷24','欲将珠匣青铜镜，换取金尊白玉巵。
镜里老来无避处，尊前愁至有消时。
茶能散闷为功浅，萱纵忘忧得力迟。
不似杜康神用速，十分一盏便开眉。','',''),('quantangshi-23753','冬夜闻虫','白居易','quantangshi','','卷24','虫声冬思苦于秋，不解愁人闻亦愁。
我是老翁听不畏，少年莫听白君头。','',''),('quantangshi-23754','双鹦鹉','白居易','quantangshi','','卷24','绿衣整顿双栖起，红觜分明对语时。
始觉琵琶弦莽卤，方知吉了舌参差。
郑牛识字吾常叹，丁鹤能歌尔亦知。
若称白家鹦鹉鸟，笼中兼合解吟诗。','',''),('quantangshi-23755','赠朱道士','白居易','quantangshi','','卷24','仪容白皙上仙郎，方寸清虚内道场。
两翼化生因服药，三尸卧死为休粮。
醮坛北向宵占斗，寝室东开早纳阳。
尽日窗间更无事，唯烧一炷降真香。','',''),('quantangshi-23756','昨以拙诗十首寄西川杜相公相公亦以新作十首惠然报示首数虽等工拙不伦重以一章用伸答谢','白居易','quantangshi','','卷24','诗家律手在成都，权与寻常将相殊。
剪截五言兼用钺，陶钧六义别开炉。
惊人卷轴须知有，随事文章不道无。
篇数虽同光价异，十鱼目换十骊珠。','',''),('quantangshi-23757','和汴州令狐相公新于郡内栽竹百竿拆壁开轩旦夕对翫偶题七言五韵','白居易','quantangshi','','卷24','梁园修竹旧传名，园废年深竹不生。
千亩荒凉寻未得，百竿青翠种新成。
墙开乍见重添兴，窗静时闻别有情。
烟叶蒙笼侵夜色，风枝萧飒欲秋声。
更登楼望尤堪重，千万人家无一茎。','',''),('quantangshi-23758','重答汝州李六使君见和忆吴中旧游五首','白居易','quantangshi','','卷24','为忆娃宫与虎丘，翫君新作不能休。
蜀牋写出篇篇好，吴调吟时句句愁。
洛下林园终共住，江南风月会重游。
由来事过多堪惜，何况苏州胜汝州。','',''),('quantangshi-23759','见殷尧藩侍御忆江南诗三十首诗中多叙苏杭胜事余尝典二郡因继和之','白居易','quantangshi','','卷24','江南名郡数苏杭，写在殷家三十章。
君是旅人犹苦忆，我为刺史更难忘。
境牵吟咏真诗国，兴入笙歌好醉乡。
为念旧游终一去，扁舟直拟到沧浪。','',''),('quantangshi-23760','闻新蝉赠刘二十八','白居易','quantangshi','','卷24','蝉发一声时，槐花带两枝。
只应催我老，兼遣报君知。
白发生头速，青云入手迟。
无过一杯酒，相劝数开眉。','',''),('quantangshi-23761','赠王山人','白居易','quantangshi','','卷24','玉芝观里王居士，服气餐霞善养身。
夜后不闻龟喘息，秋来唯长鹤精神。
容颜尽怪长如故，名姓多疑不是真。
贵重荣华轻寿命，知君闷见世间人。','',''),('quantangshi-23762','和刘郎中学士题集贤阁','白居易','quantangshi','','卷24','朱阁青山高庳齐，与君才子作诗题。
傍闻大内笙歌近，下视诸司屋舍低。
万卷图书天禄上，一条风景月华西。
欲知丞相优贤意，百步新廊不蹋泥。','',''),('quantangshi-23763','观幻','白居易','quantangshi','','卷24','有起皆因灭，无暌不暂同。
从欢终作戚，转苦又成空。
次第花生眼，须臾烛过风。
更无寻觅处，鸟迹印空中。','',''),('quantangshi-23764','病假中庞少尹携鱼酒相过','白居易','quantangshi','','卷24','宦情牢落年将暮，病假联緜日渐深。
被老相催虽白首，与春无分未甘心。
闲停茶椀从容语，醉把花枝取次吟。
劳动故人庞阁老，提鱼携酒远相寻。','',''),('quantangshi-23765','听田顺儿歌','白居易','quantangshi','','卷24','戛玉敲冰声未停，嫌云不遏入青冥。
争得黄金满衫袖，一时抛与断年听。','',''),('quantangshi-23766','听曹刚琵琶兼示重莲','白居易','quantangshi','','卷24','拨拨弦弦意不同，胡啼番语两玲珑。
谁能截得曹刚手，插向重莲衣袖中。','',''),('quantangshi-23767','酬令狐相公春日寻花见寄六韵','白居易','quantangshi','','卷24','病卧帝王州，花时不得游。
老应随日至，春肯为人留。
粉坏杏将谢，火繁桃尚稠。
白飘僧院地，红落酒家楼。
空里雪相似，晚来风不休。
吟君怅望句，如到曲江头。','',''),('quantangshi-23768','和刘郎中曲江春望见示','白居易','quantangshi','','卷24','芳景多游客，衰翁独在家。
肺伤妨饮酒，眼痛忌看花。
寺路随江曲，宫墙夹道斜。
羡君犹壮健，不枉度年华。','',''),('quantangshi-23769','送东都留守令狐尚书赴任','白居易','quantangshi','','卷24','翠华黄屋未东巡，碧洛青嵩付大臣。
地称高情多水竹，山宜闲望少风尘。
龙门即拟为游客，金谷先凭作主人。
歌酒家家花处处，莫空管领上阳春。','',''),('quantangshi-23770','自题新昌居止因招杨郎中小饮','白居易','quantangshi','','卷24','地偏坊远巷仍斜，最近东头是白家。
宿雨长齐邻舍柳，晴光照出夹城花。
春风小榼三升酒，寒食深炉一椀茶。
能到南园同醉否，笙歌随分有些些。','',''),('quantangshi-23771','南园试小乐','白居易','quantangshi','','卷24','小园斑驳花初发，新乐铮摐教欲成。
红萼紫房皆手植，苍头碧玉尽家生。
高调管色吹银字，慢拽歌词唱渭城。
不饮一杯听一曲，将何安慰老心情。','',''),('quantangshi-23772','和微之春日投简阳明洞天五十韵','白居易','quantangshi','','卷24','青阳行已半，白日坐将徂。
越国强仍大，稽城高且孤。
利饶盐煮海，名胜水澄湖。
牛斗天垂象，台明地展图。
瓌奇填市井，佳丽溢闉闍。
句践遗风霸，西施旧俗姝。
船头龙夭矫，桥脚兽睢盱。
乡味珍蟛蚏，时鲜贵鹧鸪。
语言诸夏异，衣服一方殊。
捣练蛾眉婢，鸣榔蛙角奴。
江清敌伊洛，山翠胜荆巫。
华表双栖鹤，联樯几点乌。
烟波分渡口，云树接城隅。
涧远松如画，洲平水似铺。
绿科秧早稻，紫笋折新芦。
暖蹋泥中藕，香寻石上蒲。
雨来萌尽达，雷后蛰全苏。
柳眼黄丝纇，花房绛蜡珠。
林风新竹折，野烧老桑枯。
带嚲长枝蕙，钱穿短贯榆。
暄和生野菜，卑湿长街芜。
女浣纱相伴，儿烹鲤一呼。
山魈啼稚子，林狖挂山都。
产业论蚕蚁，孳生计鸭雏。
泉岩雪飘洒，苔壁锦漫糊。
堰限舟航路，堤通车马途。
耶溪岸回合，禹庙径盘纡。
洞穴何因凿，星槎谁与刳。
石凹仙药臼，峰峭佛香炉。
去为投金简，来因挈玉壶。
贵仍招客宿，健未要人扶。
闻望贤丞相，仪形美丈夫。
前驱驻旌斾，偏坐列笙竽。
刺史旟翻隼，尚书履曳凫。
学禅超后有，观妙造虚无。
髻里传僧宝，环中得道枢。
登楼诗八咏，置砚赋三都。
捧拥罗将绮，趋跄紫与朱。
庙谟藏稷卨，兵略贮孙吴。
令下三军整，风高四海趋。
千家得慈母，六郡事严姑。
重士过三哺，轻财抵一铢。
送觥歌宛转，嘲妓笑卢胡。
佐饮时炮鼈，蠲酲数鲙鲈。
醉乡虽咫尺，乐事亦须臾。
若不中贤圣，何由外智愚。
伊予一生志，我尔百年躯。
江上三千里，城中十二衢。
出多无伴侣，归只对妻孥。
白首青山约，抽身去得无。','',''),('quantangshi-23773','酬郑侍御多雨春空过诗三十韵','白居易','quantangshi','','卷24','南雨来多滞，东风动即狂。
月行离毕急，龙走召云忙。
鬼转雷车响，蛇腾电策光。
浸淫天似漏，沮洳地成疮。
惨淡阴烟白，空蒙宿雾黄。
暗遮千里目，闷结九回肠。
寂寞羁臣馆，深沈思妇房。
镜昏鸾灭影，衣润麝消香。
兰湿难纫佩，花凋易落妆。
沾黄莺翅重，滋绿草心长。
紫陌皆泥泞，黄汚共淼茫。
恐霖成怪沴，望霁剧祯祥。
楚柳腰肢嚲，湘筠涕泪滂。
昼昏疑是夜，阴盛胜于阳。
居士巾皆垫，行人盖尽张。
跳蛙还屡出，移蚁欲深藏。
端坐交游废，闲行去步妨。
愁生垂白叟，恼杀蹋青娘。
变海常须虑，为鱼慎勿忘。
此时方共惧，何处可相将？
已望东溟祷，仍封北户禳。
却思逢旱魃，谁喜见商羊。
预怕为蚕病，先忧作麦伤。
惠应施浃洽，政岂假揄扬。
祀典修咸秩，农书振满牀。
丹诚期恳苦，白日会昭彰。
赈廪赒饥户，苫城备坏墙。
且当营岁事，宁暇惜年芳。
德胜令灾弭，人安在吏良。
尚书心若此，不枉系金章。','',''),('quantangshi-23774','和春深二十首 一','白居易','quantangshi','','卷24','何处春深好，春深富贵家。
马为中路鸟，妓作后庭花。
罗绮驱论队，金银用断车。
眼前何所苦，唯苦日西斜。','',''),('quantangshi-23775','和春深二十首 二','白居易','quantangshi','','卷24','何处春深好，春深贫贱家。
荒凉三径草，冷落四邻花。
奴困归佣力，妻愁出赁车。
途穷平路险，举足剧褒斜。','',''),('quantangshi-23776','和春深二十首 三','白居易','quantangshi','','卷24','何处春深好，春深执政家。
凤池添砚水，鸡树落衣花。
诏借当衢宅，恩容上殿车。
延英开对久，门与日西斜。','',''),('quantangshi-23777','和春深二十首 四','白居易','quantangshi','','卷24','何处春深好，春深方镇家。
通犀排带胯，瑞鹘勘袍花。
飞絮冲球马，垂杨拂妓车。
戎装拜春设，左握宝刀斜。','',''),('quantangshi-23778','和春深二十首 五','白居易','quantangshi','','卷24','何处春深好，春深刺史家。
阴繁棠布叶，岐秀麦分花。
五疋鸣珂马，双轮画轼车。
和风引行乐，叶叶隼旟斜。','',''),('quantangshi-23779','和春深二十首 六','白居易','quantangshi','','卷24','何处春深好，春深学士家。
凤书裁五色，马鬣剪三花。
蜡炬开明火，银台赐物车。
相逢不敢揖，彼此帽低斜。','',''),('quantangshi-23780','和春深二十首 七','白居易','quantangshi','','卷24','何处春深好，春深女学家。
惯看温室树，饱识浴堂花。
御印提随仗，香牋把下车。
宋家宫样髻，一片绿云斜。','',''),('quantangshi-23781','和春深二十首 八','白居易','quantangshi','','卷24','何处春深好，春深御史家。
絮萦骢马尾，蝶绕绣衣花。
破柱行持斧，埋轮立驻车。
入班遥认得，鱼贯一行斜。','',''),('quantangshi-23782','和春深二十首 九','白居易','quantangshi','','卷24','何处春深好，春深迁客家。
一杯寒食酒，万里故园花。
炎瘴蒸如火，光阴走似车。
为忧鵩鸟至，只恐日光斜。','',''),('quantangshi-23783','和春深二十首 十','白居易','quantangshi','','卷24','何处春深好，春深经业家。
唯求太常第，不管曲江花。
折桂名慙郄，收萤志慕车。
官场泥补处，最怕寸阴斜。','',''),('quantangshi-23784','和春深二十首 十一','白居易','quantangshi','','卷24','何处春深好，春深隐士家。
野衣裁薜叶，山饭晒松花。
兰索纫幽佩，蒲轮驻软车。
林间箕踞坐，白眼向人斜。','',''),('quantangshi-23785','和春深二十首 十二','白居易','quantangshi','','卷24','何处春深好，春深渔父家。
松湾随棹月，桃浦落船花。
投饵移轻楫，牵轮转小车。
萧萧芦叶里，风起钓丝斜。','',''),('quantangshi-23786','和春深二十首 十三','白居易','quantangshi','','卷24','何处春深好，春深潮户家。
涛翻三月雪，浪喷四时花。
曳练驰千马，惊雷走万车。
余波落何处，江转富阳斜。','',''),('quantangshi-23787','和春深二十首 十四','白居易','quantangshi','','卷24','何处春深好，春深痛饮家。
十分杯里物，五色眼前花。
哺歠眠糟瓮，流涎见麴车。
中山一沈醉，千度日西斜。','',''),('quantangshi-23788','和春深二十首 十五','白居易','quantangshi','','卷24','何处春深好，春深上巳家。
兰亭席上酒，曲洛岸边花。
弄水游童棹，湔裾小妇车。
齐桡争渡处，一匹锦标斜。','',''),('quantangshi-23789','和春深二十首 十六','白居易','quantangshi','','卷24','何处春深好，春深寒食家。
玲珑镂鸡子，宛转彩球花。
碧草追游骑，红尘拜扫车。
秋千细腰女，摇曳逐风斜。','',''),('quantangshi-23790','和春深二十首 十七','白居易','quantangshi','','卷24','何处春深好，春深博弈家。
一先争破眼，六聚鬬成花。
鼓应投壶马，兵冲象戏车。
弹碁局上事，最妙是长斜。','',''),('quantangshi-23791','和春深二十首 十八','白居易','quantangshi','','卷24','何处春深好，春深嫁女家。
紫排襦上雉，黄帖鬓边花。
转烛初移障，鸣环欲上车。
青衣传毡褥，锦绣一条斜。','',''),('quantangshi-23792','和春深二十首 十九','白居易','quantangshi','','卷24','何处春深好，春深娶妇家。
两行笼里烛，一树扇间花。
宾拜登华席，亲迎障幰车。
催妆诗未了，星斗渐倾斜。','',''),('quantangshi-23793','和春深二十首 二十','白居易','quantangshi','','卷24','何处春深好，春深妓女家。
眉欺杨柳叶，裙妬石榴花。
兰麝熏行被，金铜钉坐车。
杭州苏小小，人道最夭斜。','',''),('quantangshi-23794','咏家醖十韵','白居易','quantangshi','','卷24','独醒从古笑灵均，长醉如今斅伯伦。
旧法依稀传自杜，新方要妙得于陈。
井泉王相资重九，麴糵精灵用上寅。
酿糯岂劳炊范黍，撇篘何假漉陶巾。
常嫌竹叶犹凡浊，始觉榴花不正真。
瓮揭开时香酷烈，瓶封贮后味甘辛。
捧疑明水从空化，饮似阳和满腹春。
色洞玉壶无表里，光摇金盏有精神。
能销忙事成闲事，转得忧人作乐人。
应是世间贤圣物，与君还往拟终身。','',''),('quantangshi-23795','池鹤二首 一','白居易','quantangshi','','卷24','高竹笼前无伴侣，乱鸡羣里有风标。
低头乍恐丹砂落，晒翅常疑白雪消。
转觉鸬鷀毛色下，苦嫌鹦鹉语声娇。
临风一唳思何事，怅望青田云水遥。','',''),('quantangshi-23796','池鹤二首 二','白居易','quantangshi','','卷24','池中此鹤鹤中稀，恐是辽东老令威。
带雪松枝翘膝胫，放花菱片缀毛衣。
低回且向林间宿，奋迅终须天外飞。
若问故巢知处在，主人相恋未能归。','',''),('quantangshi-23797','对酒五首 一','白居易','quantangshi','','卷24','巧拙贤愚相是非，何如一醉尽忘机。
君知天地中宽窄，雕鹗鸾皇各自飞。','',''),('quantangshi-23798','对酒五首 二','白居易','quantangshi','','卷24','蜗牛角上争何事，石火光中寄此身。
随富随贫且欢乐，不开口笑是痴人。','',''),('quantangshi-23799','对酒五首 三','白居易','quantangshi','','卷24','丹砂见火去无迹，白发泥人来不休。
赖有酒仙相暖热，松乔醉即到前头。','',''),('quantangshi-23800','对酒五首 四','白居易','quantangshi','','卷24','百岁无多时壮健，一春能几日晴明。
相逢且莫推辞醉，听唱阳关第四声。','',''),('quantangshi-23801','对酒五首 五','白居易','quantangshi','','卷24','昨日低眉问疾来，今朝收泪吊人回。
眼前流例君看取，且遣琵琶送一杯。','',''),('quantangshi-23802','僧院花','白居易','quantangshi','','卷24','欲悟色空为佛事，故栽芳树在僧家。
细看便是华严偈，方便风开智慧花。','',''),('quantangshi-23803','老戒','白居易','quantangshi','','卷24','我有白头戒，闻于韩侍郎。
老多忧活计，病更恋班行。
矍铄夸身健，周遮说话长。
不知吾免否，两鬓已成霜。','',''),('quantangshi-23804','洛桥寒食日作十韵','白居易','quantangshi','','卷24','上苑风烟好，中桥道路平。
蹴球尘不起，泼火雨新晴。
宿醉头仍重，晨游眼乍明。
老慵虽省事，春诱尚多情。
遇客踟蹰立，寻花取次行。
连钱嚼金勒，凿落写银罂。
府酝伤教送，官娃岂要迎。
舞腰那及柳，歌舌不如莺。
乡国真堪恋，光阴可合轻。
三年遇寒食，尽在洛阳城。','',''),('quantangshi-23805','快活','白居易','quantangshi','','卷24','可惜莺啼花落处，一壶浊酒送残春。
可怜月好风凉夜，一部清商伴老身。
饱食安眠消日月，闲谈冷笑接交亲。
谁知将相王侯外，别有优游快活人。','',''),('quantangshi-23806','送令狐相公赴太原','白居易','quantangshi','','卷24','六纛双旌万铁衣，并汾旧路满光辉。
青衫书记何年去，红斾将军昨日归。
诗作马蹄随笔走，猎酣鹰翅伴觥飞。
此都莫作多时计，再为苍生入紫微。','',''),('quantangshi-23807','不出','白居易','quantangshi','','卷24','檐前新叶覆残花，席上余杯对早茶。
好是老身销日处，谁能骑马傍人家。','',''),('quantangshi-23808','惜落花','白居易','quantangshi','','卷24','夜来风雨急，无复旧花林。
枝上三分落，园中二寸深。
日斜啼鸟思，春尽老人心。
莫怪添杯饮，情多酒不禁。','',''),('quantangshi-23809','老病','白居易','quantangshi','','卷24','昼听笙歌夜醉眠，若非月下即花前。
如今老病须知分，不负春来二十年。','',''),('quantangshi-23810','忆晦叔','白居易','quantangshi','','卷24','游山弄水携诗卷，看月寻花把酒杯。
六事尽思君作伴，几时归到洛阳来。','',''),('quantangshi-23811','送徐州高仆射赴镇','白居易','quantangshi','','卷24','大红斾引碧幢旌，新拜将军指点行。
战将易求何足贵，书生难得始堪荣。
离筵歌舞花丛散，候骑刀枪雪队迎。
应笑蹉跎白头尹，风尘唯管洛阳城。','',''),('quantangshi-23812','琴酒','白居易','quantangshi','','卷24','耳根得听琴初畅，心地忘机酒半酣。
若使启期兼解醉，应言四乐不言三。','',''),('quantangshi-23813','听幽兰','白居易','quantangshi','','卷24','琴中古曲是幽兰，为我殷勤更弄看。
欲得身心俱静好，自弹不及听人弹。','',''),('quantangshi-23814','六年秋重题白莲','白居易','quantangshi','','卷24','素房含露玉冠鲜，绀叶摇风钿扇圆。
本是吴州供进藕，今为伊水寄生莲。
移根到此三千里，结子经今六七年。
不独池中花故旧，兼乘旧日采花船。','',''),('quantangshi-23815','元相公挽歌词三首 一','白居易','quantangshi','','卷24','铭旌官重威仪盛，骑吹声繁卤簿长。
后魏帝孙唐宰相，六年七月葬咸阳。','',''),('quantangshi-23816','元相公挽歌词三首 二','白居易','quantangshi','','卷24','墓门已闭笳箫去，唯有夫人哭不休。
苍苍露草咸阳壠，此是千秋第一秋。','',''),('quantangshi-23817','元相公挽歌词三首 三','白居易','quantangshi','','卷24','送葬万人皆惨澹，反虞驷马亦悲鸣。
琴书劒佩谁收拾，三岁遗孤新学行。','',''),('quantangshi-23818','卧听法曲霓裳','白居易','quantangshi','','卷24','金磬玉笙调已久，牙牀角枕睡常迟。
朦胧闲梦初成后，宛转柔声入破时。
乐可理心应不谬，酒能陶性信无疑。
起尝残酌听余曲，斜背银缸半下帷。','',''),('quantangshi-23819','结之','白居易','quantangshi','','卷24','欢爱今何在，悲啼亦是空。
同为一夜梦，共过十年中。','',''),('quantangshi-23820','五凤楼晚望','白居易','quantangshi','','卷24','晴阳晚照湿烟销，五凤楼高天泬寥。
野绿全经朝雨洗，林红半被暮云烧。
龙门翠黛眉相对，伊水黄金线一条。
自入秋来风景好，就中最好是今朝。','',''),('quantangshi-23821','寄刘苏州','白居易','quantangshi','','卷24','去年八月哭微之，今年八月哭敦诗。
何堪老泪交流日，多是秋风摇落时。
泣罢几回深自念，情来一倍苦相思。
同年同病同心事，除却苏州更是谁。','',''),('quantangshi-23822','送客','白居易','quantangshi','','卷24','病上篮舆相送来，衰容秋思两悠哉。
凉风褭褭吹槐子，却请行人劝一杯。','',''),('quantangshi-23823','秋思','白居易','quantangshi','','卷24','夕照红于烧，晴空碧胜蓝。
兽形云不一，弓势月初三。
雁思来天北，砧愁满水南。
萧条秋气味，未老已深谙。','',''),('quantangshi-23824','酬梦得秋夕不寐见寄','白居易','quantangshi','','卷24','碧簟绛纱帐，夜凉风景清。
病闻和药气，渴听碾茶声。
露竹偷灯影，烟松护月明。
何言千里隔，秋思一时生。','',''),('quantangshi-23825','题周家歌者','白居易','quantangshi','','卷24','清紧如敲玉，深圆似转簧。
一声肠一断，能有几多肠。','',''),('quantangshi-23826','忆梦得','白居易','quantangshi','','卷24','齿发各蹉跎，疎慵与病和。
爱花心在否，见酒兴如何。
年长风情少，官高俗虑多。
几时红烛下，闻唱竹枝歌。','',''),('quantangshi-23827','赠同座','白居易','quantangshi','','卷24','春黛双蛾嫩，秋蓬两鬓侵。
谋欢身太晚，恨老意弥深。
薄解灯前舞，尤能酒后吟。
花丛便不入，犹自未甘心。','',''),('quantangshi-23828','失婢','白居易','quantangshi','','卷24','宅院小墙庳，坊门帖牓迟。
旧恩惭自薄，前事悔难追。
笼鸟无常主，风花不恋枝。
今宵在何处，唯有月明知。','',''),('quantangshi-23829','夜招晦叔','白居易','quantangshi','','卷24','庭草留霜池结冰，黄昏钟绝冻云凝。
碧毡帐上正飘雪，红火炉前初炷灯。
高调秦筝一两弄，小花蛮榼二三升。
为君更奏湘神曲，夜就侬来能不能。','',''),('quantangshi-23830','戏答皇甫监','白居易','quantangshi','','卷24','寒宵劝酒君须饮，君是孤眠七十身。
莫道非人身不暖，十分一盏暖于人。','',''),('quantangshi-23831','和杨师臯伤小姬英英','白居易','quantangshi','','卷24','自从娇呆一相依，共见杨花七度飞。
玳瑁牀空收枕席，琵琶弦断倚屏帏。
人间有梦何曾入，泉下无家岂是归。
坟上少啼留取泪，明年寒食更沾衣。','',''),('quantangshi-23832','池边即事','白居易','quantangshi','','卷24','毡帐胡琴出塞曲，兰塘越棹弄潮声。
何言此处同风月，蓟北江南万里情。','',''),('quantangshi-23833','闻乐感邻','白居易','quantangshi','','卷24','老去亲朋零落尽，秋来弦管感伤多。
尚书宅畔悲邻笛，廷尉门前叹雀罗。
绿绮窗空分妓女，绛纱帐掩罢笙歌。
欢娱未足身先去，争奈书生薄命何。','',''),('quantangshi-23834','戊申岁暮咏怀三首 一','白居易','quantangshi','','卷24','穷冬月末两三日，半百年过六七时。
龙尾趂朝无气力，牛头参道有心期。
荣华外物终须悟，老病傍人岂得知。
犹被妻儿教渐退，莫求致仕且分司。','',''),('quantangshi-23835','戊申岁暮咏怀三首 二','白居易','quantangshi','','卷24','唯生一女才十二，秪欠三年未六旬。
婚嫁累轻何怕老，饥寒心惯不忧贫。
紫泥丹笔皆经手，赤绂金章尽到身。
更拟踟蹰觅何事，不归嵩洛作闲人。','',''),('quantangshi-23836','戊申岁暮咏怀三首 三','白居易','quantangshi','','卷24','七年囚闭作笼禽，但愿开笼便入林。
幸得展张今日翅，不能辜负昔时心。
人间祸福愚难料，世上风波老不禁。
万一差池似前事，又应追悔不抽簪。','',''),('quantangshi-23837','赠梦得','白居易','quantangshi','','卷24','心中万事不思量，坐倚屏风卧向阳。
渐觉咏诗犹老丑，岂宜凭酒更麄狂。
头垂白发我思退，脚蹋青云君欲忙。
只有今春相伴在，花前剩醉两三场。','',''),('quantangshi-23838','想东游五十韵','白居易','quantangshi','','卷24','海内时无事，江南岁有秋。
生民皆乐业，地主尽贤侯。
郊静销戎马，城高逼斗牛。
平河七百里，沃壤二三州。
坐有湖山趣，行无风浪忧。
食宁妨解缆，寝不废乘流。
泉石谙天竺，烟霞识虎丘。
余芳认兰泽，遗咏思苹洲。
菡萏红涂粉，菰蒲绿泼油。
鳞差渔户舍，绮错稻田沟。
紫洞藏仙窟，玄泉贮怪湫。
精神昂老鹤，姿彩媚潜蚪。
静阅天工妙，闲窥物状幽。
投竿出比目，掷果下猕猴。
味苦莲心小，浆甜蔗节稠。
橘苞从自结，藕孔是谁锼。
逐日移潮信，随风变棹讴。
递夫交烈火，候吏次鸣驺。
梵塔形疑踊，阊门势欲浮。
客迎携酒榼，僧待置茶瓯。
小宴闲谈笑，初筵雅献酬。
稍催朱蜡炬，徐动碧牙筹。
圆盏飞莲子，长裾曳石榴。
柘枝随画鼓，调笑从香球。
幕扬云飘槛，帘褰月露钩。
舞繁红袖凝，歌切翠眉愁。
弦管宁容歇，杯盘未许收。
良辰宜酩酊，卒岁好优游。
鲙缕鲜仍细，莼丝滑且柔。
饱餐为日计，稳睡是身谋。
名愧空虚得，官知止足休。
自嫌犹屑屑，众笑大悠悠。
物表疎形役，人寰足悔尤。
蛾须远灯烛，兔勿近罝罘。
幻世春来梦，浮生水上沤。
百忧中莫入，一醉外何求。
未死痴王湛，无儿老邓攸。
蜀琴安膝上，周易在牀头。
去去无程客，行行不系舟。
劳君频问讯，劝我少淹留。
云雨多分散，关山苦阻修。
一吟江月别，七见日星周。
珠玉传新什，鵷鸾念故俦。
悬旌心宛转，束楚意绸缪。
驿舫妆青雀，官槽䬴紫骝。
镜湖期远泛，禹穴约冥搜。
预扫题诗壁，先开望海楼。
饮思亲履舄，宿忆竝衾裯。
志气吾衰也，风情子在不。
应须相见后，别作一家游。','',''),('quantangshi-23839','病免后喜除宾客','白居易','quantangshi','','卷24','卧在漳滨满十旬，起为商皓伴三人。
从今且莫嫌身病，不病何由索得身。','',''),('quantangshi-23840','长乐亭留别','白居易','quantangshi','','卷24','灞浐风烟函谷路，曾经几度别长安。
昔时蹙促为迁客，今日从容自去官。
优诏幸分四皓秩，祖筵惭继二疎欢。
尘缨世网重重缚，回顾方知出得难。','',''),('quantangshi-23841','陕府王大夫相迎偶赠','白居易','quantangshi','','卷24','紫微阁老自多情，白首园公岂要迎。
伴我绿槐阴下歇，向君红斾影前行。
纶巾发少浑欹仄，篮轝肩齐甚稳平。
但问主人留几日，分司宾客去无程。','',''),('quantangshi-23842','别陕州王司马','白居易','quantangshi','','卷24','笙歌惆怅欲为别，风景阑珊初过春。
争得遣君诗不苦，黄河岸上白头人。','',''),('quantangshi-23843','将至东都先寄令狐留守','白居易','quantangshi','','卷24','黄鸟无声叶满枝，闲吟想到洛城时。
惜逢金谷三春尽，恨拜铜楼一月迟。
诗境忽来还自得，醉乡潜去与谁期。
东都添个狂宾客，先报壶觞风月知。','',''),('quantangshi-23844','答崔十八见寄','白居易','quantangshi','','卷24','明朝欲见琴尊伴，洗拭金杯拂玉徽。
君乞曹州刺史替，我抛刑部侍郎归。
倚疮老马收蹄立，避箭高鸿尽翅飞。
岂料洛阳风月夜，故人垂老得相依。','',''),('quantangshi-23845','赠皇甫宾客','白居易','quantangshi','','卷24','轻衣稳马槐阴路，渐近东来渐少尘。
耳闹久憎闻俗事，眼明初喜见闲人。
昔曾对作承华相，今复连为博望宾。
始信淡交宜久远，与君转老转相亲。','',''),('quantangshi-23846','归履道宅','白居易','quantangshi','','卷24','驿吏引藤轝，家童开竹扉。
往时多暂住，今日是长归。
眼下有衣食，耳边无是非。
不论贫与富，饮水亦应肥。','',''),('quantangshi-23847','问江南物','白居易','quantangshi','','卷24','归来未及问生涯，先问江南物在耶。
引手摩挲青石笋，回头点检白莲花。
苏州舫故龙头暗，王尹桥倾雁齿斜。
别有夜深惆怅事，月明双鹤在裴家。','',''),('quantangshi-23848','萧庶子相过','白居易','quantangshi','','卷24','半日停车马，何人在白家。
殷勤萧庶子，爱酒不嫌茶。','',''),('quantangshi-23849','答尉迟少尹问所须','白居易','quantangshi','','卷24','乍到频劳问所须，所须非玉亦非珠。
爱君水阁宜闲咏，每有诗成许去无。','',''),('quantangshi-23850','咏闲','白居易','quantangshi','','卷24','但有闲销日，都无事系怀。
朝眠因客起，午饭伴僧斋。
树合阴交户，池分水夹阶。
就中今夜好，风月似江淮。','',''),('quantangshi-23851','同崔十八寄元浙东王陕州','白居易','quantangshi','','卷24','未能同隐云林下，且复相招禄仕间。
随月有钱胜卖药，终年无事抵归山。
镜湖水远何由泛，棠树枝高不易攀。
惆怅八科残四在，两人荣闹两人闲。','',''),('quantangshi-23852','答苏庶子月夜闻家僮奏乐见赠','白居易','quantangshi','','卷24','墙西明月水东亭，一曲霓裳按小伶。
不敢邀君无别意，弦生管涩未堪听。','',''),('quantangshi-23853','偶吟','白居易','quantangshi','','卷24','里巷多通水，林园尽不扃。
松身为外户，池面是中庭。
元氏诗三帙，陈家酒一瓶。
醉来狂发咏，邻女暎篱听。','',''),('quantangshi-23854','白莲池泛舟','白居易','quantangshi','','卷24','白藕新花照水开，红窗小舫信风回。
谁教一片江南兴，逐我殷勤万里来。','',''),('quantangshi-23855','池上即事','白居易','quantangshi','','卷24','行寻甃石引新泉，坐看修桥补钓船。
绿竹挂衣凉处歇，清风展簟困时眠。
身闲当贵真天爵，官散无忧即地仙。
林下水边无厌日，便堪终老岂论年。','',''),('quantangshi-23856','酬裴相公见寄二绝 一','白居易','quantangshi','','卷24','习静心方泰，劳生事渐稀。
可怜安稳地，舍此欲何归。','',''),('quantangshi-23857','酬裴相公见寄二绝 二','白居易','quantangshi','','卷24','一双垂翅鹤，数首解嘲文。
总是迂闲物，争堪伴相君。','',''),('quantangshi-23858','答梦得闻蝉见寄','白居易','quantangshi','','卷24','开缄思浩然，独咏晚风前。
人貌非前日，蝉声似去年。
槐花新雨后，柳影欲秋天。
听罢无他计，相思又一篇。','',''),('quantangshi-23859','令狐尚书许过弊居先赠长句','白居易','quantangshi','','卷24','不矜轩冕爱林泉，许到池头一醉眠。
已遣平治行药迳，兼教扫拂钓鱼船。
应将笔砚随诗主，定有笙歌伴酒仙。
祗候高情无别物，苍苔石笋白花莲。','',''),('quantangshi-23860','自题','白居易','quantangshi','','卷24','老宜官冷静，贫赖俸优饶。
热月无堆案，寒天不趂朝。
傍看应寂寞，自觉甚逍遥。
徒对盈尊酒，兼无愁可销。','',''),('quantangshi-23861','答崔十八','白居易','quantangshi','','卷24','劳将白叟比黄公，今古由来事不同。
我有商山君未见，清泉白石在胸中。','',''),('quantangshi-23862','偶咏','白居易','quantangshi','','卷24','御热蕉衣健，扶羸竹杖轻。
诵经凭槛立，散药绕廊行。
暝槿无风落，秋虫欲雨鸣。
身闲当将息，病亦有心情。','',''),('quantangshi-23863','答苏六','白居易','quantangshi','','卷24','但喜暑随三伏去，不知秋送二毛来。
更无别计相宽慰，故遣阳关劝一杯。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-23864','秋游','白居易','quantangshi','','卷24','下马闲行伊水头，凉风清景胜春游。
何事古今诗句里，不多说着洛阳秋。','',''),('quantangshi-23865','偶作','白居易','quantangshi','','卷24','张翰一杯酒，荣期三乐歌。
聪明伤混沌，烦恼汚头陁。
簟冷秋生早，堦闲日上多。
近来门更静，无雀可张罗。','',''),('quantangshi-23866','游平原赠晦叔','白居易','quantangshi','','卷24','照水容虽老，登山力未衰。
欲眠先命酒，暂歇亦吟诗。
且喜身无缚，终慙鬓有丝。
回头语闲伴，闲校十年迟。','',''),('quantangshi-23867','不出门','白居易','quantangshi','','卷24','不出门来又数旬，将何销日与谁亲。
鹤笼开处见君子，书卷展时逢古人。
自静其心延寿命，无求于物长精神。
能行便是真修道，何必降魔调伏身。','',''),('quantangshi-23868','叹鹤病','白居易','quantangshi','','卷24','右翅低垂左胫伤，可怜风貌甚昂藏。
亦知白日青天好，未要高飞且养疮。','',''),('quantangshi-23869','临都驿送崔十八','白居易','quantangshi','','卷24','勿言临都五六里，扶病出城相送来。
莫道长安一步地，马头西去几时回。
与君后会知何处，为我今朝尽一杯。','',''),('quantangshi-23870','对镜','白居易','quantangshi','','卷24','三分鬓发二分丝，晓镜秋容相对时。
去作忙官应太老，退为闲叟未全迟。
静中得味何须道，稳处安身更莫疑。
若使至今黄绮在，闻吾此语亦分司。','',''),('quantangshi-23871','劝酒十四首 何处难忘酒七首 一','白居易','quantangshi','','卷24','何处难忘酒，长安喜气新。
初登高第后，乍作好官人。
省壁明张牓，朝衣稳称身。
此时无一盏，争奈帝城春。','',''),('quantangshi-23872','劝酒十四首 何处难忘酒七首 二','白居易','quantangshi','','卷24','何处难忘酒，天涯话旧情。
青云俱不达，白发递相惊。
二十年前别，三千里外行。
此时无一盏，何以叙平生。','',''),('quantangshi-23873','劝酒十四首 何处难忘酒七首 三','白居易','quantangshi','','卷24','何处难忘酒，朱门羡少年。
春分花发后，寒食月明前。
小院回罗绮，深房理管弦。
此时无一盏，争过艳阳天。','',''),('quantangshi-23874','劝酒十四首 何处难忘酒七首 四','白居易','quantangshi','','卷24','何处难忘酒，霜庭老病翁。
暗声啼蟋蟀，干叶落梧桐。
鬓为愁先白，颜因醉暂红。
此时无一盏，何计奈秋风。','',''),('quantangshi-23875','劝酒十四首 何处难忘酒七首 五','白居易','quantangshi','','卷24','何处难忘酒，军功第一高。
还乡随露布，半路授旌旄。
玉柱剥葱手，金章烂椹袍。
此时无一盏，何以骋雄豪。','',''),('quantangshi-23876','劝酒十四首 何处难忘酒七首 六','白居易','quantangshi','','卷24','何处难忘酒，青门送别多。
歛襟收涕泪，簇马听笙歌。
烟树灞陵岸，风尘长乐坡。
此时无一盏，争奈去留何。','',''),('quantangshi-23877','劝酒十四首 何处难忘酒七首 七','白居易','quantangshi','','卷24','何处难忘酒，逐臣归故园。
赦书逢驿骑，贺客出都门。
半面瘴烟色，满衫乡泪痕。
此时无一盏，何物可招魂。','',''),('quantangshi-23878','劝酒十四首 不如来饮酒七首 一','白居易','quantangshi','','卷24','莫隐深山去，君应到自嫌。
齿伤朝水冷，貌苦夜霜严。
渔去风生浦，樵归雪满岩。
不如来饮酒，相对醉厌厌。','',''),('quantangshi-23879','劝酒十四首 不如来饮酒七首 二','白居易','quantangshi','','卷24','莫作农夫去，君应见自愁。
迎春犂瘦地，趂晚餧羸牛。
数被官加税，稀逢岁有秋。
不如来饮酒，相伴醉悠悠。','',''),('quantangshi-23880','劝酒十四首 不如来饮酒七首 三','白居易','quantangshi','','卷24','莫作商人去，恓惶君未谙。
雪霜行塞北，风水宿江南。
藏镪百千万，沈舟十二三。
不如来饮酒，仰面醉酣酣。','',''),('quantangshi-23881','劝酒十四首 不如来饮酒七首 四','白居易','quantangshi','','卷24','莫事长征去，辛勤难具论。
何曾画麟阁，祗是老辕门。
虮虱衣中物，刀枪面上痕。
不如来饮酒，合眼醉昏昏。','',''),('quantangshi-23882','劝酒十四首 不如来饮酒七首 五','白居易','quantangshi','','卷24','莫学长生去，仙方悞杀君。
那将薤上露，拟待鹤边云。
矻矻皆烧药，累累尽作坟。
不如来饮酒，闲坐醉醺醺。','',''),('quantangshi-23883','劝酒十四首 不如来饮酒七首 六','白居易','quantangshi','','卷24','莫上青云去，青云足爱憎。
自贤夸智慧，相糺鬬功能。
鱼烂缘吞饵，蛾燋为扑灯。
不如来饮酒，任性醉腾腾。','',''),('quantangshi-23884','劝酒十四首 不如来饮酒七首 七','白居易','quantangshi','','卷24','莫入红尘去，令人心力劳。
相争两蜗角，所得一牛毛。
且灭嗔中火，休磨笑里刀。
不如来饮酒，稳卧醉陶陶。','',''),('quantangshi-23885','和令狐相公寄刘郎中兼见示长句','白居易','quantangshi','','卷24','日月天衢仰面看，尚淹池凤滞台鸾。
碧幢千里空移镇，赤笔三年未转官。
别后纵吟终少兴，病来虽饮不多欢。
酒军诗敌如相遇，临老犹能一据鞍。','',''),('quantangshi-23886','即事','白居易','quantangshi','','卷24','见月连宵坐，闻风尽日眠。
室香罗药气，笼暖焙茶烟。
鹤啄新晴地，鸡栖薄暮天。
自看淘酒米，倚杖小池前。','',''),('quantangshi-23887','期宿客不至','白居易','quantangshi','','卷24','风飘雨洒帘帷故，竹暎松遮灯火深。
宿客不来嫌冷落，一尊酒对一张琴。','',''),('quantangshi-23888','问移竹','白居易','quantangshi','','卷24','问君移竹意如何，慎勿排行但间窠。
多种少栽皆有意，大都少校不如多。','',''),('quantangshi-23889','重阳席上赋白菊','白居易','quantangshi','','卷24','满园花菊郁金黄，中有孤丛色似霜。
还似今朝歌酒席，白头翁入少年场。','',''),('quantangshi-23890','偶吟二首 一','白居易','quantangshi','','卷24','眼下有衣兼有食，心中无喜亦无忧。
正如身后有何事，应向人间无所求。
静念道经深闭目，闲迎禅客小低头。
犹残少许云泉兴，一岁龙门数度游。','',''),('quantangshi-23891','偶吟二首 二','白居易','quantangshi','','卷24','晴教晒药泥茶竈，闲看科松洗竹林。
活计纵贫长净洁，池亭虽小颇幽深。
厨香炊黍调和酒，窗暖安弦拂拭琴。
老去生涯祗如此，更无余事可劳心。','',''),('quantangshi-23892','何处春先到','白居易','quantangshi','','卷24','何处春先到，桥东水北亭。
冻花开未得，冷酒酌难醒。
就日移轻榻，遮风展小屏。
不劳人劝醉，莺语渐丁宁。','',''),('quantangshi-23893','勉闲游','白居易','quantangshi','','卷24','天时人事常多故，一岁春能几处游。
不是尘埃便风雨，若非疾病即悲忧。
贫穷心苦多无兴，富贵身忙不自由。
唯有分司官恰好，闲游虽老未能休。','',''),('quantangshi-23894','寄两银榼与裴侍郎因题两绝句 一','白居易','quantangshi','','卷24','贫无好物堪为信，双榼虽轻意不轻。
愿奉谢公池上酌，丹心绿酒一时倾。','',''),('quantangshi-23895','寄两银榼与裴侍郎因题两绝句 二','白居易','quantangshi','','卷24','惯和麴糵堪盛否，重用盐梅试洗看。
小器不知容几许，襄阳米贱酒升宽。','',''),('quantangshi-23896','小桥柳','白居易','quantangshi','','卷24','细水涓涓似泪流，日西惆怅小桥头。
衰杨叶尽空枝在，犹被霜风吹不休。','',''),('quantangshi-23897','哭微之二首 一','白居易','quantangshi','','卷24','八月凉风吹白幕，寝门廊下哭微之。
妻孥朋友来相吊，唯道皇天无所知。','',''),('quantangshi-23898','哭微之二首 二','白居易','quantangshi','','卷24','文章卓荦生无敌，风骨英灵殁有神。
哭送咸阳北原上，可能随例作灰尘。','',''),('quantangshi-23899','马上晚吟','白居易','quantangshi','','卷24','人少街荒已寂寥，风多尘起重萧条。
上阳落叶飘宫树，中渡流澌拥渭桥。
出早冒寒衣挍薄，归迟侵黑酒全消。
如今不是闲行日，日短天阴坊曲遥。','',''),('quantangshi-23900','醉中重留梦得','白居易','quantangshi','','卷24','刘郎刘郎莫先起，苏台苏台隔云水。
酒盏来从一百分，马头去便三千里。','',''),('quantangshi-23901','雪夜喜李郎中见访兼酬所赠','白居易','quantangshi','','卷24','可怜今夜鹅毛雪，引得高情鹤氅人。
红蜡烛前明似昼，青毡帐里暖如春。
十分满盏黄金液，一尺中庭白玉尘。
对此欲留君便宿，诗情酒分合相亲。','',''),('quantangshi-23902','任老','白居易','quantangshi','','卷24','不愁陌上春光尽，亦任庭前日影斜。
面黑眼昏头雪白，老应无可更增加。','',''),('quantangshi-23903','劝欢','白居易','quantangshi','','卷24','火急欢娱慎勿迟，眼看老病悔难追。
尊前花下歌筵里，会有求来不得时。','',''),('quantangshi-23904','答王尚书问履道池旧桥','白居易','quantangshi','','卷24','虹梁雁齿随年换，素板朱栏逐日修。
但恨尚书能久别，莫忘州守不频游。
重移旧柱开中眼，乱种新花拥两头。
李郭小船何足问，待君乘过济川舟。','',''),('quantangshi-23905','晚归府','白居易','quantangshi','','卷24','晚从履道来归府，街路虽长尹不嫌。
马上凉于牀上坐，绿槐风透紫蕉衫。','',''),('quantangshi-23906','从龙潭寺至少林寺题赠同游者','白居易','quantangshi','','卷24','山屐田衣六七贤，搴芳蹋翠弄潺湲。
九龙潭月落杯酒，三品松风飘管弦。
强健且宜游胜地，清凉不觉过炎天。
始知驾鹤乘云外，别有逍遥地上仙。','',''),('quantangshi-23907','夜从法王寺下归岳寺','白居易','quantangshi','','卷24','双刹夹虚空，缘云一径通。
似从忉利下，如过劒门中。
灯火光初合，笙歌曲未终。
可怜狮子座，舁出净名翁。','',''),('quantangshi-23908','宿龙潭寺','白居易','quantangshi','','卷24','夜上九潭谁是伴，云随飞盖月随杯。
明年尚作三川守，此地兼将歌舞来。','',''),('quantangshi-23909','嵩阳观夜奏霓裳','白居易','quantangshi','','卷24','开元遗曲自凄凉，况近秋天调是商。
爱者谁人唯白尹，奏时何处在嵩阳。
回临山月声弥怨，散入松风韵更长。
子晋少姨闻定怪，人间亦便有霓裳。','',''),('quantangshi-23910','过元家履信宅','白居易','quantangshi','','卷24','鸡犬丧家分散后，林园失主寂寥时。
落花不语空辞树，流水无情自入池。
风荡宴船初破漏，雨淋歌阁欲倾欹。
前庭后院伤心事，唯是春风秋月知。','',''),('quantangshi-23911','和杜录事题红叶','白居易','quantangshi','','卷24','寒山十月旦，霜叶一时新。
似烧非因火，如花不待春。
连行排绛帐，乱落剪红巾。
解驻篮轝看，风前唯两人。','',''),('quantangshi-23912','题崔常侍济上别墅','白居易','quantangshi','','卷24','求荣争宠任纷纷，脱弃金貂祗有君。
散员疏去未为贵，小邑陶休何足云。
山色好当晴后见，泉声宜向醉中闻。
主人忆尔尔知否，抛却青云归白云。','',''),('quantangshi-23913','过温尚书旧庄','白居易','quantangshi','','卷24','白石清泉抛济口，碧幢红斾照河阳。
邨人都不知时事，犹自呼为处士庄。','',''),('quantangshi-23914','天坛峰下赠杜录事','白居易','quantangshi','','卷24','年颜气力渐衰残，王屋中峰欲上难。
顶上将探小有洞，喉中须咽大还丹。
河车九转宜精炼，火候三年在好看。
他日药成分一粒，与君先去扫天坛。','',''),('quantangshi-23915','赠僧五首 钵塔院如大师','白居易','quantangshi','','卷24','百千万劫菩提种，八十三年功德林。
若不秉持僧行苦，将何报答佛恩深。
慈悲不瞬诸天眼，清净无尘几地心。
每岁八关蒙九授，殷勤一戒重千金。','',''),('quantangshi-23916','赠僧五首 神照上人','白居易','quantangshi','','卷24','心如定水随形应，口似悬河逐病治。
曾向众中先礼拜，西方去日莫相遗。','',''),('quantangshi-23917','赠僧五首 自远禅师','白居易','quantangshi','','卷24','自出家来长自在，缘身一衲一绳牀。
令人见即心无事，每一相逢是道场。','',''),('quantangshi-23918','赠僧五首 宗实上人','白居易','quantangshi','','卷24','荣华恩爱弃成唾，戒定真如和作香。
今古虽殊同一法，瞿昙抛却转轮王。','',''),('quantangshi-23919','赠僧五首 清闲上人','白居易','quantangshi','','卷24','梓潼眷属何年别，长寿坛场近日开。
应是蜀人皆度了，法轮移向洛中来。','',''),('quantangshi-23920','弹秋思','白居易','quantangshi','','卷24','信意闲弹秋思时，调清声直韵疎迟。
近来渐喜无人听，琴格高低心自知。','',''),('quantangshi-23921','自咏','白居易','quantangshi','','卷24','随宜饮食聊充腹，取次衣裘亦暖身。
未必得年非瘦薄，无妨长福是单贫。
老龟岂羡牺牲饱，蟠木宁争桃李春。
随分自安心自断，是非何用问闲人。','',''),('quantangshi-23922','分司初到洛中偶题六韵兼戏呈冯尹','白居易','quantangshi','','卷24','相府念多病，春宫容不才。
官衔依口得，俸料逐身来。
白首林园在，红尘车马回。
招呼新客侣，扫掠旧池台。
小舫宜携乐，新荷好盖杯。
不知金谷主，早晚贺筵开。','',''),('quantangshi-23923','春风','白居易','quantangshi','','卷24','春风先发苑中梅，樱杏桃梨次第开。
荠花榆荚深邨里，亦道春风为我来。','',''),('quantangshi-23924','洛阳春','白居易','quantangshi','','卷24','洛阳陌上春长在，惜别今来二十年。
唯觅少年心不得，其余万事尽依然。','',''),('quantangshi-23925','恨去年','白居易','quantangshi','','卷24','老去唯耽酒，春来不着家。
去年来校晚，不见洛阳花。','',''),('quantangshi-23926','早出晚归','白居易','quantangshi','','卷24','早起或因携酒出，晚归多是看花回。
若抛风景长闲坐，自问东京作底来。','',''),('quantangshi-23927','魏王堤','白居易','quantangshi','','卷24','花寒嬾发鸟慵啼，信马闲行到日西。
何处未春先有思，柳条无力魏王堤。','',''),('quantangshi-23928','尝黄醅新酎忆微之','白居易','quantangshi','','卷24','世间好物黄醅酒，天下闲人白侍郎。
爱向卯时谋洽乐，亦曾酉日放粗狂。
醉来枕麴贫如富，身后堆金有若亡。
元九计程殊未到，瓮头一盏共谁尝。','',''),('quantangshi-23929','劝行乐','白居易','quantangshi','','卷24','少年信美何曾久，春日虽迟不再中。
欢笑胜愁歌胜哭，请君莫道等头空。','',''),('quantangshi-23930','老慵','白居易','quantangshi','','卷24','岂是交亲向我疎，老慵自爱闭门居。
近来渐喜知闻断，免恼嵇康索报书。','',''),('quantangshi-23931','酬别微之','白居易','quantangshi','','卷24','[沣]头峡口钱唐岸，三别都经二十年。
且喜筋骸俱健在，勿嫌须鬓各皤然。
君归北阙朝天帝，我住东京作地仙。
博望自来非弃置，承明重入莫拘牵。
醉收杯杓停灯语，寒展衾裯对枕眠。
犹被分司官系绊，送君不得过甘泉。','',''),('quantangshi-23932','予与微之老而无子发于言叹着在诗篇今年冬各有一子戏作二什一以相贺一以自嘲 一','白居易','quantangshi','','卷24','常忧到老都无子，何况新生又是儿。
阴德自然宜有庆，皇天可得道无知。
一园水竹今为主，百卷文章更付谁。
莫虑鵷鶵无浴处，即应重入凤皇池。','',''),('quantangshi-23933','予与微之老而无子发于言叹着在诗篇今年冬各有一子戏作二什一以相贺一以自嘲 二','白居易','quantangshi','','卷24','五十八翁方有后，静思堪喜亦堪嗟。
一珠甚小还惭蚌，八子虽多不羡鸦。
秋月晚生丹桂实，春风新长紫兰芽。
持杯祝愿无他语，慎勿顽愚似汝爷。','',''),('quantangshi-23934','自问','白居易','quantangshi','','卷24','年来私自问，何故不归京。
佩玉腰无力，看花眼不明。
老慵难发遣，春病易滋生。
赖有弹琴女，时时听一声。','',''),('quantangshi-23935','晚桃花','白居易','quantangshi','','卷24','一树红桃亚拂池，竹遮松荫晚开时。
非因斜日无由见，不是闲人岂得知。
寒地生材遗挍易，贫家养女嫁常迟。
春深欲落谁怜惜，白侍郎来折一枝。','',''),('quantangshi-23936','夜调琴忆崔少卿','白居易','quantangshi','','卷24','今夜调琴忽有情，欲弹惆怅忆崔卿。
何人解爱中徽上，秋思头边八九声。','',''),('quantangshi-23937','阿崔','白居易','quantangshi','','卷24','谢病卧东都，羸然一老夫。
孤单同伯道，迟暮过商瞿。
岂料鬓成雪，方看掌弄珠。
已衰宁望有，虽晚亦胜无。
兰入前春梦，桑悬昨日弧。
里闾多庆贺，亲戚共欢娱。
腻剃新胎发，香綳小绣襦。
玉芽开手爪，酥颗点肌肤。
弓冶将传汝，琴书勿坠吾。
未能知寿夭，何暇虑贤愚。
乳气初离壳，啼声渐变雏。
何时能反哺，供养白头乌。','',''),('quantangshi-23938','赠邻里往还','白居易','quantangshi','','卷24','问予何故独安然，免被饥寒婚嫁牵。
骨肉都卢无十口，粮储依约有三年。
但能斗薮人间事，便是逍遥地上仙。
唯恐往还相厌贱，南家饮酒北家眠。','',''),('quantangshi-23939','王子晋庙','白居易','quantangshi','','卷24','子晋庙前山月明，人闻往往夜吹笙。
鸾吟凤唱听无拍，多似霓裳散序声。','',''),('quantangshi-23940','晚起','白居易','quantangshi','','卷24','起晚怜春暖，归迟爱月明。
放慵长饱睡，闻健且闲行。
北阙停朝簿，西方入社名。
唯吟一句偈，无念是无生。','',''),('quantangshi-23941','酬皇甫宾客','白居易','quantangshi','','卷24','玄晏家风黄绮身，深居高卧养精神。
性慵无病常称病，心足虽贫不道贫。
竹院君闲销永日，花亭我醉送残春。
自嫌诗酒犹多兴，若比先生是俗人。','',''),('quantangshi-23942','池上赠韦山人','白居易','quantangshi','','卷24','新竹夹平流，新荷拂小舟。
众皆嫌好拙，谁肯伴闲游。
客为忙多去，僧因饭暂留。
独怜韦处士，尽日共悠悠。','',''),('quantangshi-23943','无梦','白居易','quantangshi','','卷24','老眼花前暗，春衣雨后寒。
旧诗多忘却，新酒且尝看。
拙定于身稳，慵应趂伴难。
渐销名利想，无梦到长安。','',''),('quantangshi-23944','对小潭寄远上人','白居易','quantangshi','','卷24','小潭澄见底，闲客坐开襟。
借问不流水，何如无念心。
彼惟清且浅，此乃寂而深。
是义谁能答，明朝问道林。','',''),('quantangshi-23945','闲吟二首 一','白居易','quantangshi','','卷24','留司老宾客，春尽兴如何。
官寺行香少，僧房寄宿多。
闲倾一盏酒，醉听两声歌。
忆得陶潜语，羲皇无以过。','',''),('quantangshi-23946','闲吟二首 二','白居易','quantangshi','','卷24','闲游来早晚，已得一周年。
嵩洛供云水，朝廷乞俸钱。
长歌时独酌，饱食后安眠。
闻道山榴发，明朝向玉泉。','',''),('quantangshi-23947','独游玉泉寺','白居易','quantangshi','','卷24','云树玉泉寺，肩舁半日程。
更无人作伴，祗共酒同行。
新叶千万影，残莺三两声。
闲游竟未足，春尽有余情。','',''),('quantangshi-23948','晚出寻人不遇','白居易','quantangshi','','卷24','篮轝不乘乘晚凉，相寻不遇亦无妨。
轻衣稳马槐阴下，自要闲行一两坊。','',''),('quantangshi-23949','苦热','白居易','quantangshi','','卷24','头痛汗盈巾，连宵复达晨。
不堪逢苦热，犹赖是闲人。
朝客应烦倦，农夫更苦辛。
始慙当此日，得作自由身。','',''),('quantangshi-23950','销暑','白居易','quantangshi','','卷24','何以销烦暑，端居一院中。
眼前无长物，窗下有清风。
热散由心静，凉生为室空。
此时身自得，难更与人同。','',''),('quantangshi-23951','行香归','白居易','quantangshi','','卷24','出作行香客，归如坐夏僧。
牀前双草屦，檐下一纱灯。
佩委腰无力，冠欹发不胜。
鸾台龙尾道，合尽少年登。','',''),('quantangshi-23952','同王十七庶子李六员外郑二侍御同年四人游龙门有感而作','白居易','quantangshi','','卷24','一曲悲歌酒一尊，同年零落几人存。
世如阅水应堪叹，名是浮云岂足论。
各从仕禄休明代，共感平生知己恩。
今日与君重上处，龙门不是旧龙门。','',''),('quantangshi-23953','池上小宴问程秀才','白居易','quantangshi','','卷24','洛下林园好自知，江南景物暗相随。
净淘红粒罯香饭，薄切紫鳞烹水葵。
雨滴篷声青雀舫，浪摇花影白莲池。
停杯一问苏州客，何似吴松江上时。','',''),('quantangshi-23954','桥亭卯饮','白居易','quantangshi','','卷24','卯时偶饮斋时卧，林下高桥桥上亭。
松影过窗眠始觉，竹风吹面醉初醒。
就荷叶上包鱼鲊，当石渠中浸酒瓶。
生计悠悠身兀兀，甘从妻唤作刘伶。','',''),('quantangshi-23955','舟中夜坐','白居易','quantangshi','','卷24','潭边霁后多清景，桥下凉来足好风。
秋鹤一双船一只，夜深相伴月明中。','',''),('quantangshi-23956','戏和微之答窦七行军之作','白居易','quantangshi','','卷24','旌钺从櫜鞬，宾僚礼数全。
夔龙来要地，鵷鹭下辽天。
赭汗骑骄马，青娥舞醉仙。
合成江上作，散到洛中传。
陋巷能无酒，贫池亦有船。
春装秋未寄，谩道有闲钱。','',''),('quantangshi-23957','闲忙','白居易','quantangshi','','卷24','奔走朝行内，栖迟林墅间。
多因病后退，少及健时还。
斑白霜侵鬓，苍黄日下山。
闲忙俱过日，忙挍不如闲。','',''),('quantangshi-23958','西风','白居易','quantangshi','','卷24','西风来几日，一叶已先飞。
新霁乘轻屐，初凉换熟衣。
浅渠销慢水，疎竹漏斜晖。
薄暮青苔巷，家僮引鹤归。','',''),('quantangshi-23959','题西亭','白居易','quantangshi','','卷24','多见朱门富贵人，林园未毕即无身。
我今幸作西亭主，已见池塘五度春。','',''),('quantangshi-23960','观游鱼','白居易','quantangshi','','卷24','绕池闲步看鱼游，正值儿童弄钓舟。
一种爱鱼心各异，我来施食尔垂钩。','',''),('quantangshi-23961','看采莲','白居易','quantangshi','','卷24','小桃闲上小莲船，半采红莲半白莲。
不似江南恶风浪，芙蓉池在卧牀前。','',''),('quantangshi-23962','看采菱','白居易','quantangshi','','卷24','菱池如镜净无波，白点花稀青角多。
时唱一声新水调，谩人道是采菱歌。','',''),('quantangshi-23963','夭老','白居易','quantangshi','','卷24','早世身如风里烛，暮年发似镜中丝。
谁人断得人间事，少夭堪伤老又悲。','',''),('quantangshi-23964','秋池','白居易','quantangshi','','卷24','洗浪清风透水霜，水边闲坐一绳牀。
眼尘心垢见皆尽，不是秋池是道场。','',''),('quantangshi-23965','登天宫阁','白居易','quantangshi','','卷24','午时乘兴出，薄暮未能还。
高上烟中阁，平看雪后山。
委形羣动里，任性一生间。
洛下多闲客，其中我最闲。','',''),('quantangshi-23966','新雪二首 一','白居易','quantangshi','','卷24','不思北省烟霄地，不忆南宫风月天。
唯忆静恭杨阁老，小园新雪暖炉前。','',''),('quantangshi-23967','新雪二首 二','白居易','quantangshi','','卷24','不思朱雀街东鼓，不忆青龙寺后钟。
唯忆夜深新雪后，新昌台上七株松。','',''),('quantangshi-23968','日高卧','白居易','quantangshi','','卷24','怕寒放嬾日高卧，临老谁言牵率身。
夹幕绕房深似洞，重裀衬枕暖于春。
小青衣动桃根起，嫩绿醅浮竹叶新。
未裹头前倾一盏，何如冲雪趂朝人。','',''),('quantangshi-23969','和微之任校书郎日过三乡','白居易','quantangshi','','卷24','三乡过日君年几，今日君年五十余。
不独年催身亦变，校书郎变作尚书。','',''),('quantangshi-23970','和微之十七与君别及陇月花枝之咏','白居易','quantangshi','','卷24','别时十七今头白，恼乱君心三十年。
垂老休吟花月句，恐君更结后身缘。','',''),('quantangshi-23971','和微之叹槿花','白居易','quantangshi','','卷24','朝荣殊可惜，暮落实堪嗟。
若向花中比，犹应胜眼花。','',''),('quantangshi-23972','思往喜今','白居易','quantangshi','','卷24','忆除司马向江州，及此凡经十五秋。
虽在簪裾从俗累，半寻山水是闲游。
谪居终带乡关思，领郡犹分邦国忧。
争似如今作宾客，都无一念到心头。','',''),('quantangshi-23973','题平泉薛家雪堆庄','白居易','quantangshi','','卷24','怪石千年应自结，灵泉一带是谁开。
蹙为宛转青蛇项，喷作玲珑白雪堆。
赤日旱天长看雨，玄阴腊月亦闻雷。
所嗟地去都门远，不得肩舁每日来。','',''),('quantangshi-23974','和微之道保生三日','白居易','quantangshi','','卷24','相看鬓似丝，始作弄璋诗。
且有承家望，谁论得力时。
莫兴三日叹，犹胜七年迟。
我未能忘喜，君应不合悲。
嘉名称道保，乞姓号崔儿。
但恐持相竝，蒹葭琼树枝。','',''),('quantangshi-23975','哭皇甫七郎中','白居易','quantangshi','','卷24','志业过玄晏，词华似禰衡。
多才非福禄，薄命是聪明。
不得人间寿，还留身后名。
涉江文一首，便可敌公卿。','',''),('quantangshi-23976','晚起','白居易','quantangshi','','卷24','烂熳朝眠后，频伸晚起时。
暖炉生火早，寒镜裹头迟。
融雪煎香茗，调酥煮乳糜。
慵馋还自哂，快活亦谁知。
酒性温无毒，琴声淡不悲。
荣公三乐外，仍弄小男儿。','',''),('quantangshi-23977','疑梦二首 一','白居易','quantangshi','','卷24','莫惊宠辱虚忧喜，莫计恩讐浪苦辛。
黄帝孔丘无处问，安知不是梦中身。','',''),('quantangshi-23978','疑梦二首 二','白居易','quantangshi','','卷24','鹿疑郑相终难辨，蝶化庄生讵可知。
假使如今不是梦，能长于梦几多时。','',''),('quantangshi-23979','夜宴惜别','白居易','quantangshi','','卷24','笙歌旖旎曲终头，转作离声满坐愁。
筝怨朱弦从此断，烛啼红泪为谁流。
夜长似岁欢宜尽，醉未如泥饮莫休。
何况鸡鸣即须别，门前风雨冷修修。','',''),('quantangshi-23980','归来二周岁','白居易','quantangshi','','卷24','归来二周岁，二岁似须臾。
池藕重生叶，林鸦再引雏。
时丰实仓廪，春暖葺庖厨。
更作三年计，三年身健无。','',''),('quantangshi-23981','吾土','白居易','quantangshi','','卷24','身心安处为吾土，岂限长安与洛阳。
水竹花前谋活计，琴诗酒里到家乡。
荣先生老何妨乐，楚接舆歌未必狂。
不用将金买庄宅，城东无主是春光。','',''),('quantangshi-23982','题岐王旧山池石壁','白居易','quantangshi','','卷24','树深藤老竹回环，石壁重重锦翠斑。
俗客看来犹解爱，忙人到此亦须闲。
况当霁景凉风后，如在千岩万壑间。
黄绮更归何处去，洛阳城内有商山。','',''),('quantangshi-23983','病眼花','白居易','quantangshi','','卷24','头风目眩乘衰老，祗有增加岂有瘳。
花发眼中犹足怪，柳生肘上亦须休。
大窠罗绮看才辨，小字文书见便愁。
必若不能分黑白，却应无悔复无尤。','',''),('quantangshi-23984','早饮醉中除河南尹敕到','白居易','quantangshi','','卷24','雪拥衡门水满池，温炉卯后暖寒时。
绿醅新酎尝初醉，黄纸除书到不知。
厚俸自来诚忝滥，老身欲起尚迟疑。
应须了却丘中计，女嫁男婚三迳资。','',''),('quantangshi-23985','除夜','白居易','quantangshi','','卷24','病眼少眠非守岁，老心多感又临春。
火销灯尽天明后，便是平头六十人。','',''),('quantangshi-23986','府西池','白居易','quantangshi','','卷24','柳无气力枝先动，池有波纹冰尽开。
今日不知谁计会，春风春水一时来。','',''),('quantangshi-23987','天津桥','白居易','quantangshi','','卷24','津桥东北斗亭西，到此令人诗思迷。
眉月晚生神女浦，脸波春傍窈娘堤。
柳丝褭褭风缲出，草缕茸茸雨剪齐。
报道前驱少呼喝，恐惊黄鸟不成啼。','',''),('quantangshi-23988','不准拟二首 一','白居易','quantangshi','','卷24','篮轝腾腾一老夫，褐裘乌帽白髭须。
早衰饶病多蔬食，筋力消磨合有无。
不准拟身年六十，上山仍未要人扶。','',''),('quantangshi-23989','不准拟二首 二','白居易','quantangshi','','卷24','忆昔谪居炎瘴地，巴猿引哭虎随行。
多于贾谊长沙苦，小挍潘安白发生。
不准拟身年六十，游春犹自有心情。','',''),('quantangshi-23990','府中夜赏','白居易','quantangshi','','卷24','樱桃厅院春偏好，石井栏堂夜更幽。
白粉墙头花半出，绯纱烛下水平流。
闲留宾客尝新酒，醉领笙歌上小舟。
舞袖飘颻棹容与，忽疑身是梦中游。','',''),('quantangshi-23991','府西池北新葺水斋即事招宾偶题十六韵','白居易','quantangshi','','卷24','缭绕府西面，潺湲池北头。
凿开明月峡，决破白苹洲。
清浅漪澜急，夤缘浦屿幽。
直冲行径断，平入卧斋流。
石叠青棱玉，波翻白片鸥。
喷时千点雨，澄处一泓油。
绝境应难别，同心岂易求。
少逢人爱翫，多是我淹留。
夹岸铺长簟，当轩泊小舟。
枕前看鹤浴，牀下见鱼游。
洞户斜开扇，疎帘半上钩。
紫浮萍泛泛，碧亚竹修修。
读罢书仍展，碁终局未收。
午茶能散睡，卯酒善销愁。
檐雨晚初霁，窗风凉欲休。
谁能伴老尹，时复一闲游。','',''),('quantangshi-23992','哭崔儿','白居易','quantangshi','','卷24','掌珠一颗儿三岁，鬓雪千茎父六旬。
岂料汝先为异物，常忧吾不见成人。
悲肠自断非因劒，啼眼加昏不是尘。
怀抱又空天默默，依前重作邓攸身。','',''),('quantangshi-23993','初丧崔儿报微之晦叔','白居易','quantangshi','','卷24','书报微之晦叔知，欲题崔字泪先垂。
世间此恨偏敦我，天下何人不哭儿。
蝉老悲鸣抛蜕后，龙眠惊觉失珠时。
文章十帙官三品，身后传谁庇荫谁。','',''),('quantangshi-23994','府斋感怀酬梦得','白居易','quantangshi','','卷24','府伶呼唤争先到，家酝提携动輙随。
合是人生开眼日，自当年老歛眉时。
丹砂炼作三铢土，玄发看成一把丝。
劳寄新诗远安慰，不闻枯树再生枝。','',''),('quantangshi-23995','斋居','白居易','quantangshi','','卷24','香火多相对，荤腥久不尝。
黄耆数匙粥，赤箭一瓯汤。
厚俸将何用，闲居不可忘。
明年官满后，拟买雪堆庄。','',''),('quantangshi-23996','与诸道者同游二室至九龙潭作','白居易','quantangshi','','卷24','喜逢二室游仙子，厌作三川守土臣。
举手摩挲潭上石，开襟斗薮府中尘。
他日终为独往客，今朝未是自由身。
若言尹是嵩山主，三十六峰应笑人。','',''),('quantangshi-23997','履道池上作','白居易','quantangshi','','卷24','家池动作经旬别，松竹琴鱼好在无。
树暗小巢藏巧妇，渠荒新叶长慈姑。
不因车马时时到，岂觉林园日日芜。
犹喜春深公事少，每来花下得踟蹰。','',''),('quantangshi-23998','六十拜河南尹','白居易','quantangshi','','卷24','六十河南尹，前途足可知。
老应无处避，病不与人期。
幸遇芳菲日，犹富强健时。
万金何假藉，一盏莫推辞。
流水光阴急，浮云富贵迟。
人间若无酒，尽合鬓成丝。','',''),('quantangshi-23999','重修府西水亭院','白居易','quantangshi','','卷24','因下疏为沼，随高筑作台。
龙门分水入，金谷取花栽。
绕岸行初匝，凭轩立未回。
园西有池位，留与后人开。','',''),('quantangshi-24000','与诸公同出城观稼','白居易','quantangshi','','卷24','老尹醉醺醺，来随年少羣。
不忧头似雪，但喜稼如云。
岁望千箱积，秋怜五谷分。
何人知帝力，尧舜正为君。','',''),('quantangshi-24001','水堂醉卧问杜三十一','白居易','quantangshi','','卷24','闻君洛下住多年，何处春流最可怜？
为问魏王堤岸下，何如同德寺门前。
无妨水色堪闲翫，不得泉声伴醉眠。
那似此堂帘幕底，连明连夜碧潺湲。','',''),('quantangshi-24002','岁暮言怀','白居易','quantangshi','','卷24','职与才相背，心将口自言。
磨铅教切玉，驱鹤遣乘轩。
只合居岩窟，何因入府门。
年终若无替，转恐负君恩。','',''),('quantangshi-24003','座中戏呈诸少年','白居易','quantangshi','','卷24','衰容禁得无多酒，秋鬓新添几许霜。
纵有风情应淡薄，假如老健莫夸张。
兴来吟咏从成癖，饮后酣歌少放狂。
不为倚官兼挟势，因何入得少年场。','',''),('quantangshi-24004','雪后早过天津桥偶呈诸客','白居易','quantangshi','','卷24','官桥晴雪晓峩峩，老尹行吟独一过。
紫绶相辉应不恶，白须同色复如何。
悠扬短景凋年急，牢落衰情感事多。
犹赖洛中饶醉客，时时䛏我唤笙歌。','',''),('quantangshi-24005','新制绫袄成感而有咏','白居易','quantangshi','','卷24','水波文袄造新成，绫软绵匀温复轻。
晨兴好拥向阳坐，晚出宜披蹋雪行。
鹤氅毳疎无实事，木棉花冷得虚名。
宴安往往欢侵夜，卧稳昏昏睡到明。
百姓多寒无可救，一身独暖亦何情。
心中为念农桑苦，耳里如闻饥冻声。
争得大裘长万丈，与君都盖洛阳城。','',''),('quantangshi-24006','早春雪后赠洛阳李长官长水郑明府二同年','白居易','quantangshi','','卷24','献岁晴和风景新，铜駞街郭暖无尘。
府庭共贺三川雪，县道分行百里春。
朱绂洛阳官位屈，青袍长水俸钱贫。
有何功德纡金紫，若比同年是幸人。','',''),('quantangshi-24007','醉吟','白居易','quantangshi','','卷24','醉来忘渴复忘饥，冠带形骸杳若遗。
耳底斋钟初过后，心头卯酒未消时。
临风朗咏从人听，看雪闲行任马迟。
应被众疑公事慢，承前府尹不吟诗。','',''),('quantangshi-24008','府酒五绝 变法','白居易','quantangshi','','卷24','自惭到府来周岁，惠爱威棱一事无。
唯是改张官酒法，渐从浊水作醍醐。','',''),('quantangshi-24009','府酒五绝 招客','白居易','quantangshi','','卷24','日午微风且暮寒，春风冷峭雪干残。
碧毡帐下红炉畔，试为来尝一盏看。','',''),('quantangshi-24010','府酒五绝 辨味','白居易','quantangshi','','卷24','甘露太甜非正味，醴泉虽洁不芳馨。
杯中此物何人别，柔旨之中有典刑。','',''),('quantangshi-24011','府酒五绝 自劝','白居易','quantangshi','','卷24','忆昔羁贫应举年，脱衣典酒曲江边。
十千一斗犹赊饮，何况官供不着钱。','',''),('quantangshi-24012','府酒五绝 谕妓','白居易','quantangshi','','卷24','烛泪夜黏桃叶袖，酒痕春汚石榴裙。
莫辞辛苦供欢宴，老后思量悔煞君。','',''),('quantangshi-24013','晚归早出','白居易','quantangshi','','卷24','筋力年年减，风光日日新。
退衙归逼夜，拜表出侵晨。
何处台无月，谁家池不春。
莫言无胜地，自是少闲人。
坐厌推囚案，行嫌引马尘。
几时辞府印，却作自由身。','',''),('quantangshi-24014','南龙兴寺残雪','白居易','quantangshi','','卷25','南龙兴寺春晴后，缓步徐吟绕四廊。
老趂风花应不称，闲寻松雪正相当。
吏人引从多乘轝，宾客逢迎少下堂。
不拟人间更求事，些些疎嬾亦何妨。','',''),('quantangshi-24015','天宫阁早春','白居易','quantangshi','','卷25','天宫高阁上何频，每上令人耳目新。
前日晚登缘看雪，今朝晴望为迎春。
林莺何处吟筝柱，墙柳谁家晒麴尘。
可惜三川虚作主，风光不属白头人。','',''),('quantangshi-24016','履道居三首 一','白居易','quantangshi','','卷25','莫嫌地窄林亭小，莫厌贫家活计微。
大有高门鏁宽宅，主人到老不曾归。','',''),('quantangshi-24017','履道居三首 二','白居易','quantangshi','','卷25','东里素帷犹未彻，南邻丹旐又新悬。
衡门蜗舍自慙愧，收得身来已五年。','',''),('quantangshi-24018','履道居三首 三','白居易','quantangshi','','卷25','世事平分众所知，何尝苦乐不相随。
唯余耽酒狂歌客，只有乐时无苦时。','',''),('quantangshi-24019','和梦得冬日晨兴','白居易','quantangshi','','卷25','漏传初五点，鸡报第三声。
帐下从容起，窗间昽{日怱}明。
照书灯未灭，暖酒火重生。
理曲弦歌动，先闻唱渭城。','',''),('quantangshi-24020','雪夜对酒招客','白居易','quantangshi','','卷25','帐小青毡暖，杯香[绿]蚁新。
醉怜今夜月，欢忆去年人。
暗落灯花烬，闲生草座尘。
殷勤报弦管，明日有嘉宾。','',''),('quantangshi-24021','赠晦叔忆梦得','白居易','quantangshi','','卷25','自别崔公四五秋，因何临老转风流。
归来不说秦中事，歇定唯谋洛下游。
酒面浮花应是喜，歌眉歛黛不关愁。
得君更有无厌意，犹恨尊前欠老刘。','',''),('quantangshi-24022','醉后重赠晦叔','白居易','quantangshi','','卷25','老伴知君少，欢情向我偏。
无论疎与数，相见輙欣然。
各以诗成癖，俱因酒得仙。
笑回青眼语，醉竝白头眠。
岂是今投分，多疑宿结缘。
人间更何事，携手送衰年。','',''),('quantangshi-24023','睡觉','白居易','quantangshi','','卷25','星河耿耿漏绵绵，月暗灯微欲曙天。
转枕频伸书帐下，披裘箕踞火炉前。
老眠早觉常残夜，病力先衰不待年。
五欲已销诸念息，世间无境可勾牵。','',''),('quantangshi-24024','咏兴五首 解印出公府','白居易','quantangshi','','卷25','解印出公府，斗薮尘土衣。
百吏放尔散，双鹤随我归。
归来履道宅，下马入柴扉。
马嘶返旧枥，鹤舞还故池。
鸡犬何忻忻，隣里亦依依。
年颜老去日，生计胜前时。
有帛御冬寒，有谷防岁饥。
饱于东方朔，乐于荣启期。
人生且如此，此外吾不知。','',''),('quantangshi-24025','咏兴五首 出府归吾庐','白居易','quantangshi','','卷25','出府归吾庐，静然安且逸。
更无客干谒，时有僧问疾。
家僮十余人，枥马三四匹。
慵发经旬卧，兴来连日出。
出游爱何处，嵩碧伊瑟瑟。
况有清和天，正当疎散日。
身闲自为贵，何必居荣秩。
心足即非贫，岂唯金满室。
吾观权势者，苦以身徇物。
炙手外炎炎，履冰中栗栗。
朝饥口忘味，夕惕心忧失。
但有富贵名，而无富贵实。','',''),('quantangshi-24026','咏兴五首 池上有小舟','白居易','quantangshi','','卷25','池上有小舟，舟中有胡牀。
牀前有新酒，独酌还独尝。
熏若春日气，皎如秋水光。
可洗机巧心，可荡尘垢肠。
岸曲舟行迟，一曲进一觞。
未知几曲醉，醉入无何乡。
寅缘潭岛间，水竹深青苍。
身闲心无事，白日为我长。
我若未忘世，虽闲心亦忙。
世若未忘我，虽退身难藏。
我今异于是，身世交相忘。','',''),('quantangshi-24027','咏兴五首 四月池水满','白居易','quantangshi','','卷25','四月池水满，龟游鱼跃出。
吾亦爱吾池，池边开一室。
人鱼虽异族，其乐归于一。
且与尔为徒，逍遥同过日。
尔无羡沧海，蒲藻可委质。
吾亦忘青云，衡茅足容膝。
况吾与尔辈，本非蛟龙匹。
假如云雨来，祗是池中物。','',''),('quantangshi-24028','咏兴五首 小庭亦有月','白居易','quantangshi','','卷25','小庭亦有月，小院亦有花。
可怜好风景，不解嫌贫家。
菱角执笙簧，谷儿抹琵琶。
红绡信手舞，紫绡随意歌。
邨歌与社舞，客哂主人夸。
但问乐不乐，岂在钟鼓多。
客告暮将归，主称日未斜。
请客稍深酌，愿见朱颜酡。
客知主意厚，分数随口加。
堂上烛未秉，座中冠已峩。
左顾短红袖，右命小青娥。
长跪谢贵客，蓬门劳见过。
客散有余兴，醉卧独吟哦。
幕天而席地，谁奈刘伶何。','',''),('quantangshi-24029','秋凉闲卧','白居易','quantangshi','','卷25','残暑昼犹长，早凉秋尚嫩。
露荷散清香，风竹含疎韵。
幽闲竟日卧，衰病无人问。
薄暮宅门前，槐花深一寸。','',''),('quantangshi-24030','酬思黯相公见过弊居戏赠','白居易','quantangshi','','卷25','轩盖光照地，行人为裴回。
呼传君子出，乃是故人来。
访我入穷巷，引君登小台。
台前多竹树，池上无尘埃。
贫家何所有，新酒三两杯。
停杯欵曲语，上马复迟回。
留守不外宿，日斜宫漏催。
但留金刀赠，未接玉山颓。
家酝不敢惜，待君来即开。
邨妓不辞出，恐君冁然咍。','',''),('quantangshi-24031','再授宾客分司','白居易','quantangshi','','卷25','优稳四皓官，清崇三品列。
伊予再尘忝，内愧非才哲。
俸钱七八万，给受无虚月。
分命在东司，又不劳朝谒。
既资闲养疾，亦赖慵藏拙。
宾友得从容，琴觞恣怡悦。
乘篮城外去，系马花前歇。
六游金谷春，五看龙门雪。
吾若默无语，安知吾快活。
吾欲更尽言，复恐人豪夺。
应为时所笑，苦惜分司阙。
但问适意无，岂论官冷热。','',''),('quantangshi-24032','把酒','白居易','quantangshi','','卷25','把酒仰问天，古今谁不死。
所贵未死间，少忧多欢喜。
穷通谅在天，忧喜即由己。
是故达道人，去彼而取此。
勿言未富贵，久忝居禄仕。
借问宗族间，几人拖金紫。
勿忧渐衰老，且喜加年纪。
试数班行中，几人及暮齿。
朝飱不过饱，五鼎徒为尔。
夕寝止求安，一衾而已矣。
此外皆长物，于我云相似。
有子不留金，何况兼无子。','',''),('quantangshi-24033','首夏','白居易','quantangshi','','卷25','林静蚊未生，池静蛙未鸣。
景长天气好，竟日和且清。
春禽余哢在，夏木新阴成。
兀尔水边坐，翛然桥上行。
自问一何适，身闲官不轻。
料钱随月用，生计逐日营。
食饱慙伯夷，酒足愧渊明。
寿倍颜氏子，富百黔娄生。
有一即为乐，况吾四者并。
所以私自慰，虽老有心情。','',''),('quantangshi-24034','代鹤','白居易','quantangshi','','卷25','我本海上鹤，偶逢江南客。
感君一顾恩，同来洛阳陌。
洛阳寡族类，皎皎唯两翼。
貌是天与高，色非日浴白。
主人诚可恋，其奈轩庭窄。
饮啄杂鸡羣，年深损标格。
故乡渺何处，云水重重隔。
谁念深笼中，七换摩天翮。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24035','立秋夕有怀梦得','白居易','quantangshi','','卷25','露簟荻竹清，风扇蒲葵轻。
一与故人别，再见新蝉鸣。
是夕凉飙起，闲境入幽情。
回灯见栖鹤，隔竹闻吹笙。
夜茶一两杓，秋吟三数声。
所思渺千里，云外长洲城。','',''),('quantangshi-24036','哭崔常侍晦叔','白居易','quantangshi','','卷25','顽贱一拳石，精珍百炼金。
名价既相远，交分何其深。
中诚一以合，外物不能侵。
逶迤二十年，与世同浮沈。
晚有退闲约，白首归云林。
垂老忽相失，悲哉口语心。
春日嵩高阳，秋夜清洛阴。
丘园共谁卜，山水共谁寻。
风月共谁赏，诗篇共谁吟。
花开共谁看，酒熟共谁斟。
惠死庄杜口，钟殁师废琴。
道理使之然，从古非独今。
吾道自此孤，我情安可任。
唯将病眼泪，一洒秋风襟。','',''),('quantangshi-24037','新秋晓兴','白居易','quantangshi','','卷25','浊暑忽已退，清宵未全长。
晨釭耿残焰，宿合凝微香。
喔喔鸡下树，辉辉日上梁。
枕低茵席软，卧稳身入牀。
睡足景犹早，起初风乍凉。
展张小屏幛，收拾生衣裳。
还有惆怅事，迟迟未能忘。
拂镜梳白发，可怜冰照霜。','',''),('quantangshi-24038','秋日与张宾客舒着作同游龙门醉中狂歌凡二百三十八字','白居易','quantangshi','','卷25','秋天高高秋光清，秋风褭褭秋虫鸣。
嵩峰余霞锦绮卷，伊水细浪鳞甲生。
洛阳闲客知无数，少出游山多在城。
商岭老人自追逐，蓬丘逸士相逢迎。
南出鼎门十八里，庄店逦迤桥道平。
不寒不热好时节，鞍马稳快衣衫轻。
竝辔踟蹰下西岸，扣舷容与绕中汀。
开怀旷达无所系，触目胜绝不可名。
荷衰欲黄荇犹绿，鱼乐自跃鸥不惊。
翠藻蔓长孔雀尾，彩船橹急寒雁声。
家酝一壶白玉液，野花数把黄金英。
昼游四看西日暮，夜话三及东方明。
暂停杯觞辍吟咏，我有狂言君试听。
丈夫一生有二志，兼济独善难得并。
不能救疗生民病，即须先濯尘土缨。
况吾头白眼已暗，终日戚促何所成。
不如展眉开口笑，龙门醉卧香山行。','',''),('quantangshi-24039','履信池樱桃岛上醉后走笔送别舒员外兼寄宗正李卿考功崔郎中','白居易','quantangshi','','卷25','樱桃岛前春，去春花万枝。
忽忆与宗卿闲饮日，又忆与考功狂醉时。
岁晚无花空有叶，风吹满地干重叠。
蹋叶悲秋复忆春，池边树下重殷勤。
今朝一酌临寒水，此地三回别故人。
樱桃花，来春千万朵，来春共谁花下坐。
不论崔李上青云，明日舒三亦抛我。','',''),('quantangshi-24040','秋池独泛','白居易','quantangshi','','卷25','萧疎秋竹篱，清浅秋风池。
一只短舫艇，一张斑鹿皮。
皮上有野叟，手中持酒巵。
半酣箕踞坐，自问身为谁。
严子垂钓日，苏门长啸时。
悠然意自得，意外何人知。','',''),('quantangshi-24041','冬日早起闲咏','白居易','quantangshi','','卷25','水塘耀初旭，风竹飘余霰。
幽境虽目前，不因闲不见。
晨起对炉香，道经寻两卷。
晚坐拂琴尘，秋思弹一遍。
此外更无事，开尊时自劝。
何必东风来，一杯春上面。','',''),('quantangshi-24042','岁暮','白居易','quantangshi','','卷25','惨澹岁云暮，穷阴动经旬。
霜风裂人面，冰雪摧车轮。
而我当是时，独不知苦辛。
晨炊廪有米，夕爨厨有薪。
夹帽长覆耳，重裘宽裹身。
加之一杯酒，煦妪如阳春。
洛城士与庶，比屋多饥贫。
何处炉有火，谁家甑无尘。
如我饱暖者，百人无一人。
安得不慙愧，放歌聊自陈。','',''),('quantangshi-24043','南池早春有怀','白居易','quantangshi','','卷25','朝游北桥上，晚憩南塘畔。
西日雪全销，东风冰尽泮。
簁簁鱼尾掉，瞥瞥鹅毛换。
泥暖草芽生，沙虚泉脉散。
晴芳冒苔岛，宿润侵蒲岸。
洛下日初长，江南春欲半。
时光共抛掷，人事堪嗟叹。
倚棹忽寻思，去年池上伴。','',''),('quantangshi-24044','古意','白居易','quantangshi','','卷25','脉脉复脉脉，美人千里隔。
不见来几时，瑶草三四碧。
玉琴声悄悄，鸾镜尘幂幂。
昔为连理枝，今作分飞翮。
寄书多不达，加饭终无益。
心肠不自宽，衣带何由窄。','',''),('quantangshi-24045','山游示小妓','白居易','quantangshi','','卷25','双鬟垂未合，三十才过半。
本是绮罗人，今为山水伴。
春泉共挥弄，好树同攀翫。
笑容花底迷，酒思风前乱。
红凝舞袖急，黛惨歌声缓。
莫唱杨柳枝，无肠与君断。','',''),('quantangshi-24046','神照禅师同宿','白居易','quantangshi','','卷25','八年三月晦，山梨花满枝。
龙门水西寺，夜与远公期。
晏坐自相对，密语谁得知。
前后际断处，一念不生时。','',''),('quantangshi-24047','张常侍相访','白居易','quantangshi','','卷25','西亭晚寂寞，莺散柳阴繁。
水户帘不卷，风牀席自翻。
忽闻车马客，来访蓬蒿门。
况是张常侍，安得不开尊。','',''),('quantangshi-24048','早夏游宴','白居易','quantangshi','','卷25','虽慵兴犹在，虽老心犹健。
昨日山水游，今朝花酒宴。
山榴艳似火，玉蘂飘如霰。
荣落逐瞬迁，炎凉随刻变。
未收木绵褥，已动蒲葵扇。
且喜物与人，年年得相见。','',''),('quantangshi-24049','感白莲花','白居易','quantangshi','','卷25','白白芙蓉花，本生吴江濆。
不与红者杂，色类自区分。
谁移尔至此，姑苏白使君。
初来苦顦顇，久乃芳氛氲。
月月叶换叶，年年根生根。
陈根与故叶，销化成泥尘。
化者日已远，来者日复新。
一为池中物，永别江南春。
忽想西凉州，中有天宝民。
埋殁汉父祖，孳生胡子孙。
已忘乡土恋，岂念君亲恩。
生人尚复尔，草木何足云。','',''),('quantangshi-24050','咏所乐','白居易','quantangshi','','卷25','兽乐在山谷，鱼乐在陂池。
虫乐在深草，鸟乐在高枝。
所乐虽不同，同归适其宜。
不以彼易此，况论是与非。
而我何所乐，所乐在分司。
分司有何乐，乐哉人不知。
官优有禄料，职散无羁縻。
嬾与道相近，钝将闲自随。
昨朝拜表回，今晚行香归。
归来北窗下，解巾脱尘衣。
冷泉灌我顶，暖水濯四肢。
体中幸无疾，卧任清风吹。
心中又无事，坐任白日移。
或开书一篇，或引酒一巵。
但得如今日，终身无厌时。','',''),('quantangshi-24051','思旧','白居易','quantangshi','','卷25','闲日一思旧，旧游如目前。
再思今何在，零落归下泉。
退之服硫黄，一病讫不痊。
微之炼秋石，未老身溘然。
杜子得丹诀，终日断腥膻。
崔君夸药力，经冬不衣绵。
或疾或暴夭，悉不过中年。
唯予不服食，老命反迟延。
况在少壮时，亦为嗜欲牵。
但躭荤与血，不识汞与铅。
饥来吞热物，渴来饮寒泉。
诗役五藏神，酒汨三丹田。
随日合破坏，至今粗完全。
齿牙未缺落，肢体尚轻便。
已开第七秩，饱食仍安眠。
且进杯中物，其余皆付天。','',''),('quantangshi-24052','寄卢少尹','白居易','quantangshi','','卷25','老诲心不乱，庄戒形太劳。
生命既能保，死籍亦可逃。
嘉肴与旨酒，信是腐肠膏。
艳声与丽色，真为伐性刀。
补养在积功，如裘集众毛。
将欲致千里，可得差一毫。
颜回何为者，簟瓢才自给。
肥醲不到口，年不登三十。
张苍何为者，染爱浩无际。
妾媵填后房，竟寿百余岁。
苍寿有何德，回夭有何辜。
谁谓具圣体，不如肥瓠躯。
遂使世俗心，多疑仙道书。
寄问卢先生，此理当何如。','',''),('quantangshi-24053','池上清晨候皇甫郎中','白居易','quantangshi','','卷25','晓景丽未热，晨飙鲜且凉。
池幽绿苹合，霜洁白莲香。
深扫竹间迳，静拂松下牀。
玉柄鹤翎扇，银甖云母浆。
屏除无俗物，瞻望唯清光。
何人拟相访，嬴女从萧郎。','',''),('quantangshi-24054','咏怀','白居易','quantangshi','','卷25','我知世无幻，了无干世意。
世知我无堪，亦无责我事。
由兹两相忘，因得长自遂。
自遂意何如，闲官在闲地。
闲地唯东都，东都少名利。
闲官是宾客，宾客无牵累。
嵇康日日嬾，毕卓时时醉。
酒肆夜深归，僧房日高睡。
形安不劳苦，神泰无忧畏。
从官三十年，无如今气味。
鸿虽脱罗弋，鹤尚居禄位。
唯此未忘怀，有时犹内愧。','',''),('quantangshi-24055','北窗三友','白居易','quantangshi','','卷25','今日北窗下，自问何所为。
欣然得三友，三友者为谁。
琴罢輙举酒，酒罢輙吟诗。
三友递相引，循环无已时。
一弹惬中心，一咏畅四肢。
犹恐中有间，以酒弥缝之。
岂独吾拙好，古人多若斯。
嗜诗有渊明，嗜琴有启期。
嗜酒有伯伦，三人皆吾师。
或乏儋石储，或穿带索衣。
弦歌复觞咏，乐道知所归。
三师去已远，高风不可追。
三友游甚熟，无日不相随。
左掷白玉巵，右拂黄金徽。
兴酣不叠纸，走笔操狂词。
谁能持此词，为我谢亲知。
纵未以为是，岂以我为非。','',''),('quantangshi-24056','吟四虽','白居易','quantangshi','','卷25','酒酣后，歌歇时。
请君添一酌，听我吟四虽。
年虽老，犹少于韦长史。
命虽薄，犹胜于郑长水。
眼虽病，犹明于徐郎中。
家虽贫，犹富于郭庶子。
省躬审分何侥幸，值酒逢歌且欢喜。
忘荣知足委天和，亦应得尽生生理。','',''),('quantangshi-24057','裴侍中晋公以集贤林亭即事诗三十六韵见赠猥蒙征和才拙词繁輙广为五百言以伸酬献','白居易','quantangshi','','卷25','三江路千里，五湖天一涯。
何如集贤第，中有平津池。
池胜主见觉，景新人未知。
竹森翠琅玕，水深洞琉璃。
水竹以为质，质立而文随。
文之者何人，公来亲指麾。
疏凿出人意，结构得地宜。
灵襟一搜索，胜概无遁遗。
因下张沼沚，依高筑阶基。
嵩峰见数片，伊水分一支。
南溪修且直，长波碧逶迤。
北馆壮复丽，倒影红参差。
东岛号晨光，杲曜迎朝曦。
西岭名夕阳，杳暧留落晖。
前有水心亭，动荡架涟漪。
后有开阖堂，寒温变天时。
幽泉镜泓澄，怪石山欹危。
春葩雪漠漠，夏果珠离离。
主人命方舟，宛在水中坻。
亲宾次第至，酒乐前后施。
解缆始登泛，山游仍水嬉。
沿洄无滞碍，向背穷幽奇。
瞥过远桥下，飘旋深涧陲。
管弦去缥缈，罗绮来霏微。
棹风逐舞回，梁尘随歌飞。
宴余日云暮，醉客未放归。
高声索彩牋，大笑催金巵。
唱和笔走疾，问答杯行迟。
一咏清两耳，一酣畅四肢。
主客忘贵贱，不知俱是谁。
客有诗魔者，吟哦不知疲。
乞公残纸墨，一扫狂歌词。
维云社稷臣，赫赫文武姿。
十授丞相印，五建大将旗。
四朝致勋华，一身冠臯夔。
去年才七十，决赴悬车期。
公志不可夺，君恩亦难希。
从容就中道，俛僶来保厘。
貂蝉虽未脱，鸾皇已不羁。
历征今与古，独步无等夷。
陆贾功业少，二疏官秩卑。
乘舟范蠡惧，辟谷留侯饥。
岂若公今日，身安家国肥。
羊祜在汉南，空留岘首碑。
柳恽在江南，祗赋汀洲诗。
谢安入东山，但说携蛾眉。
山简醉高阳，唯闻倒接䍦。
岂如公今日，余力兼有之。
愿公寿如山，安乐长在兹。
愿我比蒲稗，永得相因依。','',''),('quantangshi-24058','晚归香山寺因咏所怀','白居易','quantangshi','','卷25','我年日已老，我身日已闲。
闲出都门望，但见水与山。
关塞碧岩岩，伊流清潺潺。
中有古精舍，轩户无扃关。
岸草歇可藉，迳萝行可攀。
朝随浮云出，夕与飞鸟还。
吾道本迂拙，世途多险艰。
尝闻嵇吕辈，尤悔生疎顽。
巢悟入箕颍，皓知返商巅。
岂唯乐肥遁，聊复祛忧患。
吾亦从此去，终老伊嵩间。','',''),('quantangshi-24059','张常侍池凉夜闲宴赠诸公','白居易','quantangshi','','卷25','竹桥新月上，水岸凉风至。
对月五六人，管弦三两事。
留连池上酌，款曲城外意。
或啸或讴吟，谁知此闲味。
回看市朝客，矻矻趋名利。
朝忙少游宴，夕困多眠睡。
清凉属吾徒，相逢勿辞醉。','',''),('quantangshi-24060','和皇甫郎中秋晓同登天宫阁言怀六韵','白居易','quantangshi','','卷25','碧天忽已高，白日犹未短。
玲珑晓楼阁，清脆秋丝管。
张翰一杯酣，嵇康终日嬾。
尘中足忧累，云外多疎散。
病木斧斤遗，冥鸿羁緤断。
逍遥二三子，永愿为闲伴。','',''),('quantangshi-24061','送吕漳州','白居易','quantangshi','','卷25','今朝一壶酒，言送漳州牧。
半自要闲游，爱花怜草绿。
花前下鞍马，草上携丝竹。
行客饮数杯，主人歌一曲。
端居惜风景，屡出劳僮仆。
独醉似无名，借君作题目。','',''),('quantangshi-24062','短歌曲','白居易','quantangshi','','卷25','世人求富贵，多为奉嗜欲。
盛衰不自由，得失常相逐。
问君少年日，苦学将干禄。
负笈尘中游，抱书雪前读。
布衾不周体，藜茹才充腹。
三十登宦途，五十被朝服。
奴温新挟纩，马肥初食粟。
未敢议欢游，尚为名检束。
耳目聋暗后，堂上调丝竹。
牙齿缺落时，盘中堆酒肉。
彼来此已去，外余中不足。
少壮与荣华，相避如寒燠。
青云去地远，白日经天速。
从古无奈何，短歌听一曲。','',''),('quantangshi-24063','咏怀','白居易','quantangshi','','卷25','高人乐丘园，中人慕官职。
一事尚难成，两途安可得。
遑遑干世者，多苦时命塞。
亦有爱闲人，又为穷饿逼。
我今幸双遂，禄仕兼游息。
未尝羡荣华，不省劳心力。
妻孥与婢仆，亦免愁衣食。
所以吾一家，面无忧喜色。','',''),('quantangshi-24064','府西亭纳凉归','白居易','quantangshi','','卷25','避暑府西亭，晚归有闲思。
夏浅蝉未多，绿槐阴满地。
带宽衫解领，马稳人拢辔。
面上有凉风，眼前无俗事。
路经府门过，落日照官次。
牵联缧绁囚，奔走尘埃吏。
低眉悄不语，谁复知兹意。
忆得五年前，晚衙时气味。','',''),('quantangshi-24065','老热','白居易','quantangshi','','卷25','一饱百情足，一酣万事休。
何人不衰老，我老心无忧。
仕者拘职役，农者劳田畴。
何人不苦热，我热身自由。
卧风北窗下，坐月南池头。
脑凉脱乌帽，足热濯清流。
慵发昼高枕，兴来夜泛舟。
何乃有余适，祗缘无过求。
或问诸亲友，乐天是与不。
亦无别言语，多道天悠悠。
悠悠君不知，此味深且幽。
但恐君知后，亦来从我游。','',''),('quantangshi-24066','新秋喜凉因寄兵部杨侍郎','白居易','quantangshi','','卷25','外强火未退，中锐金方战。
一夕风雨来，炎凉随数变。
徐徐炎景度，稍稍凉飙扇。
枕簟忽凄清，巾裳亦轻健。
老夫纳秋候，心体殊安便。
睡足一屈伸，搔首摩挲面。
褰帘对池竹，幽寂如僧院。
俯观游鱼羣，仰数浮云片。
闲忙各有趣，彼此宁相见。
昨日闻慕巢，召对延英殿。','',''),('quantangshi-24067','嬾放二首呈刘梦得吴方之 一','白居易','quantangshi','','卷25','青衣报平旦，呼我起盥栉。
今早天气寒，郎君应不出。
又无宾客至，何以销闲日。
已向微阳前，暖酒开诗帙。','',''),('quantangshi-24068','嬾放二首呈刘梦得吴方之 二','白居易','quantangshi','','卷25','朝怜一牀日，暮爱一炉火。
牀暖日高眠，炉温夜深坐。
雀罗门嬾出，鹤发头慵裹。
除却刘与吴，何人来问我。','',''),('quantangshi-24069','六十六','白居易','quantangshi','','卷25','病知心力减，老觉光阴速。
五十八归来，今年六十六。
鬓丝千万白，池草八九绿。
童稚尽成人，园林半乔木。
看山倚高石，引水穿深竹。
虽有潺湲声，至今听未足。','',''),('quantangshi-24070','三适赠道友','白居易','quantangshi','','卷25','褐绫袍厚暖，卧盖行坐披。
紫毡履宽稳，蹇步颇相宜。
足适已忘履，身适已忘衣。
况我心又适，兼忘是与非。
三适今为一，怡怡复熙熙。
禅那不动处，混沌未凿时。
此固不可说，为君强言之。','',''),('quantangshi-24071','洛阳春赠刘李二宾客','白居易','quantangshi','','卷25','水南冠盖地，城东桃李园。
雪消洛阳堰，春入永通门。
淑景方霭霭，游人稍喧喧。
年丰酒浆贱，日晏歌吹繁。
中有老朝客，华发暎朱轩。
从容三两人，藉草开一尊。
尊前春可惜，身外事勿论。
明日期何处，杏花游赵村。','',''),('quantangshi-24072','寒食','白居易','quantangshi','','卷25','人老何所乐，乐在归乡国。
我归故园来，九度逢寒食。
故园在何处，池馆东城侧。
四隣梨花时，二月伊水色。
岂独好风土，仍多旧亲戚。
出去恣欢游，归来聊燕息。
有官供禄俸，无事劳心力。
但恐优稳多，微躬销不得。','',''),('quantangshi-24073','和裴令公一日日一年年杂言见赠','白居易','quantangshi','','卷25','一日日，作老翁。
一年年，过春风。
公心不以贵隔我，我散唯将闲伴公。
我无才能忝高秩，合是人间闲散物。
公有功德在生民，何因得作自由身。
前日魏王潭上宴连夜，今日午桥池头游拂晨。
山客砚前吟待月，野人尊前醉送春。
不敢与公闲中争第一，亦应占得第二第三人。','',''),('quantangshi-24074','题裴晋公女几山刻石诗后','白居易','quantangshi','','卷25','何处画功业，何处题诗篇？
麒麟高阁上，女几小山前。
尔后多少时，四朝二十年。
贼骨化为土，贼垒犂为田。
一从贼垒平，陈蔡民晏然。
骡军成牛户，鬼火变人烟。
生子已嫁娶，种桑亦丝緜。
皆云公之德，欲报无由缘。
公今在何处，守都镇三川。
旧宅留永乐，新居开集贤。
公今在何官，被衮珥貂蝉。
战袍破犹在，髀肉生欲圆。
襟怀转萧洒，气力弥精坚。
登山不拄杖，上马能掉鞭。
利泽浸入池，福降升自天。
昔号天下将，今称地上仙。
勿追赤松游，勿拍洪崖肩。
商山有遗老，可以奉周旋。','',''),('quantangshi-24075','洛阳有愚叟','白居易','quantangshi','','卷25','洛阳有愚叟，白黑无分别。
浪迹虽似狂，谋身亦不拙。
点检盘中饭，非精亦非粝。
点检身上衣，无余亦无阙。
天时方得所，不寒复不热。
体气正调和，不饥仍不渴。
闲将酒壶出，醉向人家歇。
野食或烹鲜，寓眠多拥褐。
抱琴荣启乐，荷锸刘伶达。
放眼看青山，任头生白发。
不知天地内，更得几年活。
从此到终身，尽为闲日月。','',''),('quantangshi-24076','饱食闲坐','白居易','quantangshi','','卷25','红粒陆浑稻，白鳞伊水鲂。
庖童呼我食，饭热鱼鲜香。
筯筯适我口，匙匙充我肠。
八珍与五鼎，无复心思量。
扪腹起盥漱，下阶振衣裳。
绕庭行数匝，却上檐下牀。
箕踞拥裘坐，半身在日阳。
可怜饱暖味，谁肯来同尝。
是岁太和八，兵销时渐康。
朝廷重经术，草泽搜贤良。
尧舜求理切，夔龙启沃忙。
怀才抱智者，无不走遑遑。
唯此不才叟，顽慵恋洛阳。
饱食不出门，闲坐不下堂。
子弟多寂寞，僮仆少精光。
衣食虽充给，神意不扬扬。
为尔谋则短，为吾谋甚长。','',''),('quantangshi-24077','闲居自题','白居易','quantangshi','','卷25','门前有流水，墙上多高树。
竹迳绕荷池，萦回百余步。
波闲戏鱼鼈，风静下鸥鹭。
寂无城市喧，渺有江湖趣。
吾庐在其上，偃卧朝复暮。
洛下安一居，山中亦慵去。
时逢过客爱，问是谁家住。
此是白家翁，闭门终老处。','',''),('quantangshi-24078','览镜喜老','白居易','quantangshi','','卷25','今朝览明镜，须鬓尽成丝。
行年六十四，安得不衰羸。
亲属惜我老，相顾兴叹咨。
而我独微笑，此意何人知。
笑罢仍命酒，掩镜捋白髭。
尔辈且安坐，从容听我词。
生若不足恋，老亦何足悲。
生若苟可恋，老即生多时。
不老即须夭，不夭即须衰。
晚衰胜早夭，此理决不疑。
古人亦有言，浮生七十稀。
我今欠六岁，多幸或庶几。
傥得及此限，何羡荣启期。
当喜不当叹，更倾酒一巵。','',''),('quantangshi-24079','风雪中作','白居易','quantangshi','','卷25','岁暮风动地，夜寒雪连天。
老夫何处宿，暖帐温炉前。
两重褐绮衾，一领花茸毡。
粥熟呼不起，日高安稳眠。
是时心与身，了无闲事牵。
以此度风雪，闲居来六年。
忽思远游客，复想早朝士。
蹋冻侵夜行，凌寒未明起。
心为身君父，身为心臣子。
不得身自由，皆为心所使。
我心既知足，我身自安止。
方寸语形骸，吾应不负尔。','',''),('quantangshi-24080','对琴酒','白居易','quantangshi','','卷25','西窗明且暖，晚坐卷书帷。
琴匣拂开后，酒瓶添满时。
角尊白螺盏，玉轸黄金徽。
未及弹与酌，相对已依依。
泠泠秋泉韵，贮在龙凤池。
油油春云心，一杯可致之。
自古有琴酒，得此味者稀。
祗因康与籍，及我三心知。','',''),('quantangshi-24081','雪中晏起偶咏所怀兼呈张常侍韦庶子皇甫郎中','白居易','quantangshi','','卷25','穷阴苍苍雪雰雰，雪深没胫泥埋轮。
东家典钱归碍夜，南家贳米出凌晨。
我独何者无此弊，复帐重衾暖若春。
怕寒放嬾不肯动，日高眠足方频伸。
瓶中有酒炉有炭，瓮中有饭庖有薪。
奴温婢饱身晏起，致兹快活良有因。
上无臯陶伯益廊庙材，的不能匡君辅国活生民。
下无巢父许由箕颍操，又不能食薇饮水自苦辛。
君不见南山悠悠多白云，又不见西京浩浩唯红尘。
红尘闹热白云冷，好于冷热中间安置身。
三年徼幸忝洛尹，两任优稳为商宾。
非贤非愚非智慧，不贵不富不贱贫。
冉冉老去过六十，腾腾闲来经七春。
不知张韦与皇甫，私唤我作何如人。','',''),('quantangshi-24082','和裴侍中南园静兴见示','白居易','quantangshi','','卷25','池馆清且幽，高怀亦如此。
有时帘动风，尽日桥照水。
静将鹤为伴，闲与云相似。
何必学留侯，崎岖觅松子。','',''),('quantangshi-24083','春寒','白居易','quantangshi','','卷25','今朝春气寒，自问何所欲。
酥暖薤白酒，乳和地黄粥。
岂惟厌馋口，亦可调病腹。
助酌有枯鱼，佐餐兼旨蓄。
省躬念前哲，醉饱多惭忸。
君不闻靖节先生尊长空，广文先生饭不足。','',''),('quantangshi-24084','菩提寺上方晚望香山寺寄舒员外','白居易','quantangshi','','卷25','晚登西宝刹，晴望东精舍。
反照转楼台，辉辉似图画。
冰浮水明灭，雪压松偃亚。
石阁僧上来，云汀雁飞下。
西京闹于市，东洛闲如社。
曾忆旧游无，香山明月夜。','',''),('quantangshi-24085','二月一日作赠韦七庶子','白居易','quantangshi','','卷25','园杏红萼坼，庭兰紫芽出。
不觉春已深，今朝二月一。
去冬病疮痏，将养遵医术。
今春入道场，清净依僧律。
尝闻圣贤语，所慎斋与疾。
遂使爱酒人，停杯一百日。
明朝二月二，疾平斋复毕。
应须挈一壶，寻花觅韦七。','',''),('quantangshi-24086','犬鸢','白居易','quantangshi','','卷25','晚来天气好，散步中门前。
门前何所有，偶覩犬与鸢。
鸢饱凌风飞，犬暖向日眠。
腹舒稳贴地，翅凝高摩天。
上无罗弋忧，下无羁锁牵。
见彼物遂性，我亦心适然。
心适复何为，一咏逍遥篇。
此仍着于适，尚未能忘言。','',''),('quantangshi-24087','梦刘二十八因诗问之','白居易','quantangshi','','卷25','昨夜梦梦得，初觉思踟蹰。
忽忘来汝郡，犹疑在吴都。
吴都三千里，汝郡二百余。
非梦亦不见，近与远何殊。
尚能齐近远，焉用论荣枯。
但问寝与食，近日两何如。
病后能吟否，春来曾醉无。
楼台与风景，汝又何如苏。
相思一相报，勿复慵为书。','',''),('quantangshi-24088','闲吟','白居易','quantangshi','','卷25','贫穷汲汲求衣食，富贵营营役心力。
人生不富即贫穷，光阴易过闲难得。
我今幸在穷富间，虽在朝廷不入山。
看雪寻花翫风月，洛阳城里七年闲。','',''),('quantangshi-24089','西行','白居易','quantangshi','','卷25','衣裘不单薄，车马不羸弱。
蔼蔼三月天，闲行亦不恶。
寿安流水馆，硖石青山郭。
官道柳阴阴，行宫花漠漠。
常闻俗间语，有钱在处乐。
我虽非富人，亦不苦寂寞。
家僮解弦管，骑从携杯杓。
时向春风前，歇鞍开一酌。','',''),('quantangshi-24090','东归','白居易','quantangshi','','卷25','翩翩平肩舆，中有醉老夫。
膝上展诗卷，竿头悬酒壶。
食宿无定程，仆马多缓驱。
临水歇半日，望山倾一盂。
藉草坐嵬峩，攀花行踟蹰。
风将景共暖，体与心同舒。
始悟有营者，居家如在途。
方知无系者，在道如安居。
前夕宿三堂，今旦游申湖。
残春三百里，送我归东都。','',''),('quantangshi-24091','途中作','白居易','quantangshi','','卷25','早起上肩舁，一杯平旦醉。
晚憩下肩舁，一觉残春睡。
身不经营物，心不思量事。
但恐绮与里，只如吾气味。','',''),('quantangshi-24092','小台','白居易','quantangshi','','卷25','新树低如帐，小台平似掌。
六尺白藤牀，一茎青竹杖。
风飘竹皮落，苔印鹤迹上。
幽境与谁同，闲人自来往。','',''),('quantangshi-24093','睡后茶兴忆杨同州','白居易','quantangshi','','卷25','昨晚饮太多，嵬峩连宵醉。
今朝餐又饱，烂熳移时睡。
睡足摩挲眼，眼前无一事。
信脚绕池行，偶然得幽致。
婆娑绿阴树，斑驳青苔地。
此处置绳牀，傍边洗茶器。
白瓷瓯甚洁，红炉炭方炽。
沫下麴尘香，花浮鱼眼沸。
盛来有佳色，咽罢余芳气。
不见杨慕巢，谁人知此味。','',''),('quantangshi-24094','题文集柜','白居易','quantangshi','','卷25','破柏作书柜，柜牢柏复坚。
收贮谁家集，题云白乐天。
我生业文字，自幼及老年。
前后七十卷，小大三千篇。
诚知终散失，未忍遽弃捐。
自开自锁闭，置在书帷前。
身是邓伯道，世无王仲宣。
只应分付女，留与外孙传。','',''),('quantangshi-24095','旱热二首 一','白居易','quantangshi','','卷25','彤云散不雨，赫日吁可畏。
端坐犹挥汗，出门岂容易。
忽思公府内，青衫折腰吏。
复想驿路中，红尘走马使。
征夫更辛苦，逐客弥顦顇。
日入尚趋程，宵分不遑寐。
安知北窗叟，偃卧风飒至。
簟拂碧龙鳞，扇摇白鹤翅。
岂唯身所得，兼示心无事。
谁言苦热天，元有清凉地。','',''),('quantangshi-24096','旱热二首 二','白居易','quantangshi','','卷25','勃勃旱尘气，炎炎赤日光。
飞禽颭将坠，行人渴欲狂。
壮者不耐饥，饥火烧其肠。
肥者不禁热，喘急汗如浆。
此时方自悟，老瘦亦何妨。
肉轻足健逸，发少头清凉。
薄食不饥渴，端居省衣裳。
数匙粱饭冷，一领绡衫香。
持此聊过日，焉知畏景长。','',''),('quantangshi-24097','偶作二首 一','白居易','quantangshi','','卷25','战马春放归，农牛冬歇息。
何独徇名人，终身役心力。
来者殊未已，去者不知还。
我今悟已晚，六十方退闲。
犹胜不悟者，老死红尘间。','',''),('quantangshi-24098','偶作二首 二','白居易','quantangshi','','卷25','名无高与卑，未得多健羡。
事无小与大，已得多厌贱。
如此常自苦，反此或自安。
此理知甚易，此道行甚难。
勿信人虚语，君当事上看。','',''),('quantangshi-24099','池上作','白居易','quantangshi','','卷25','西溪风生竹森森，南潭萍开水沈沈。
丛翠万竿湘岸色，空碧一泊松江心。
浦派萦回误远近，桥岛向背迷窥临。
澄澜方丈若万顷，倒影咫尺如千寻。
泛然独游邈然坐，坐念行心思古今。
菟裘不闻有泉沼，西河亦恐无云林。
岂如白翁退老地，树高竹密池塘深。
华亭双鹤白矫矫，太湖四石青岑岑。
眼前尽日更无客，膝上此时唯有琴。
洛阳冠盖自相索，谁肯来此同抽簪。','',''),('quantangshi-24100','何处堪避暑','白居易','quantangshi','','卷25','何处堪避暑，林间背日楼。
何处好追凉，池上随风舟。
日高饥始食，食竟饱还游。
游罢睡一觉，觉来茶一瓯。
眼明见青山，耳醒闻碧流。
脱袜闲濯足，解巾快掻头。
如此来几时，已过六七秋。
从心至百骸，无一不自由。
拙退是其分，荣耀非所求。
虽被世间笑，终无身外忧。
此语君莫怪，静思吾亦愁。
如何三伏月，杨尹谪虔州。','',''),('quantangshi-24101','诏下','白居易','quantangshi','','卷25','昨日诏下去罪人，今日诏下得贤臣。
进退者谁非我事，世间宠辱常纷纷。
我心与世两相忘，时事虽闻如不闻。
但喜今年饱饭吃，洛阳禾稼如秋云。
更倾一尊歌一曲，不独忘世兼忘身。','',''),('quantangshi-24102','七月一日作','白居易','quantangshi','','卷25','七月一日天，秋生履道里。
闲居见清景，高兴从此始。
林间暑雨歇，池上凉风起。
桥竹碧鲜鲜，岸莎青靡靡。
苍然古磐石，清浅平流水。
何言中门前，便是深山里。
双僮侍坐卧，一杖扶行止。
饥闻麻粥香，渴觉云汤美。
平生所好物，今日多在此。
此外更何思，市朝心已矣。','',''),('quantangshi-24103','开襟','白居易','quantangshi','','卷25','开襟何处好，竹下池边地。
余热体犹烦，早凉风有味。
黄萎槐蘂结，红破莲芳坠。
无奈每年秋，先来入衰思。','',''),('quantangshi-24104','自宾客迁太子少傅分司','白居易','quantangshi','','卷25','头上渐无发，耳间新有毫。
形容逐日老，官秩随年高。
优饶又加俸，闲稳仍分曹。
饮食免藜藿，居处非蓬蒿。
何言家尚贫，银榼提绿醪。
勿谓身未贵，金章照紫袍。
诚合知止足，岂宜更贪饕。
默默心自问，于国有何劳。','',''),('quantangshi-24105','自在','白居易','quantangshi','','卷25','杲杲冬日光，明暖真可爱。
移榻向阳坐，拥裘仍解带。
小奴捶我足，小婢搔我背。
自问我为谁，胡然独安泰。
安泰良有以，与君论梗概。
心了事未了，饥寒迫于外。
事了心未了，念虑煎于内。
我今实多幸，事与心和会。
内外及中间，了然无一碍。
所以日阳中，向君言自在。','',''),('quantangshi-24106','咏史','白居易','quantangshi','','卷25','秦磨利刀斩李斯，齐烧沸鼎烹郦其。
可怜黄绮入商洛，闲卧白云歌紫芝。
彼为葅醢机上尽，此为鸾皇天外飞。
去者逍遥来者死，乃知祸福非天为。','',''),('quantangshi-24107','因梦有悟','白居易','quantangshi','','卷25','交友沦殁尽，悠悠劳梦思。
平生所厚者，昨夜梦见之。
梦中几许事，枕上无多时。
欵曲数杯酒，从容一局碁。
初见韦尚书，金紫何辉辉。
中遇李侍郎，笑言甚怡怡。
终为崔常侍，意色苦依依。
一夕三改变，梦心不惊疑。
此事人尽怪，此理谁得知。
我粗知此理，闻于竺干师。
识行妄分别，智隐迷是非。
若转识为智，菩提其庶几。','',''),('quantangshi-24108','春游','白居易','quantangshi','','卷25','上马临出门，出门复逡巡。
回头问妻子，应怪春游频。
诚知春游频，其奈老大身。
朱颜去复去，白发新更新。
请君屈十指，为我数交亲。
大限年百岁，几人及七旬。
我今六十五，走若下坂轮。
假使得七十，祗有五度春。
逢春不游乐，但恐是痴人。','',''),('quantangshi-24109','题天竺南院赠闲元旻清四上人','白居易','quantangshi','','卷25','杂芳涧草合，繁绿岩树新。
山深景候晚，四月有余春。
竹寺过微雨，石迳无纤尘。
白衣一居士，方袍四道人。
地是佛国土，人非俗交亲。
城中山下别，相送亦殷勤。','',''),('quantangshi-24110','哭师臯','白居易','quantangshi','','卷25','南康丹旐引魂回，洛阳篮舁送葬来。
北邙原边尹村畔，月苦烟愁夜过半。
妻孥兄弟号一声，十二人肠一时断。
往者何人送者谁，乐天哭别师臯时。
平生分义向人尽，今日哀冤唯我知。
我知何益徒垂泪，篮轝回竿马回辔。
何日重闻扫市歌，谁家收得琵琶伎。
萧萧风树白杨影，苍苍露草青蒿气。
更就坟前哭一声，与君此别终天地。','',''),('quantangshi-24111','隐几赠客','白居易','quantangshi','','卷25','宦情本淡薄，年貌又老丑。
紫绶与金章，于予亦何有。
有时独隐几，答然无所偶。
卧枕一卷书，起尝一杯酒。
书将引昏睡，酒用扶衰朽。
客到忽已酣，脱巾坐搔首。
疎顽倚老病，容恕惭交友。
忽思庄生言，亦拟鞭其后。','',''),('quantangshi-24112','夏日作','白居易','quantangshi','','卷25','葛衣疎且单，纱帽轻复宽。
一衣与一帽，可以过炎天。
止于便吾体，何必被罗纨。
宿雨林笋嫩，晨露园葵鲜。
烹葵炮嫩笋，可以备朝餐。
止于适吾口，何必饫腥膻。
饭讫盥漱已，扪腹方果然。
婆娑庭前步，安稳窗下眠。
外养物不费，内归心不烦。
不费用难尽，不烦神易安。
庶几无夭阏，得以终天年。','',''),('quantangshi-24113','晚凉偶咏','白居易','quantangshi','','卷25','日下西墙西，风来北窗北。
中有逐凉人，单牀独栖息。
飘萧过云雨，摇曳归飞翼。
新叶多好阴，初筠有佳色。
幽深小池馆，优稳闲官职。
不爱勿复论，爱亦不易得。','',''),('quantangshi-24114','酬牛相公宫城早秋寓言见示兼呈梦得','白居易','quantangshi','','卷25','七月中气后，金与火交争。
一闻白雪唱，暑退清风生。
碧树未摇落，寒蝉始悲鸣。
夜凉枕簟滑，秋燥衣巾轻。
疎受老慵出，刘桢疾未平。
何人伴公醉，新月上宫城。','',''),('quantangshi-24115','小台晚坐忆梦得','白居易','quantangshi','','卷25','汲泉洒小台，台上无纤埃。
解带面西坐，轻襟随风开。
晚凉闲兴动，忆同倾一杯。
月明候柴户，藜杖何时来。','',''),('quantangshi-24116','种桃歌','白居易','quantangshi','','卷25','食桃种其核，一年核生芽。
二年长枝叶，三年桃有花。
忆昨五六岁，灼灼盛芬华。
迨兹八九载，有减而无加。
去春已稀少，今春渐无多。
明年后年后，芳意当如何。
命酒树下饮，停杯拾余葩。
因桃忽自感，悲吒成狂歌。','',''),('quantangshi-24117','狂言示诸侄','白居易','quantangshi','','卷25','世欺不识字，我忝攻文笔。
世欺不得官，我忝居班秩。
人老多病苦，我今幸无疾。
人老多忧累，我今婚嫁毕。
心安不移转，身泰无牵率。
所以十年来，形神闲且逸。
况当垂老岁，所要无多物。
一裘暖过冬，一饭饱终日。
勿言舍宅小，不过寝一室。
何用鞍马多，不能骑两匹。
如我优幸身，人中十有七。
如我知足心，人中百无一。
傍观愚亦见，当己贤多失。
不敢论他人，狂言示诸侄。','',''),('quantangshi-24118','偶以拙诗数首寄呈裴少尹侍郎蒙以盛制四篇一时酬和重投长句美而谢之','白居易','quantangshi','','卷25','投君之文甚荒芜，数篇价直一束刍。
报我之章何璀璨，累累四贯骊龙珠。
毛诗三百篇后得，文选六十卷中无。
一麋丽龟绝报赛，五鹿连柱难支梧。
高兴独因秋日尽，清吟多与好风俱。
银钩金错两殊重，宜上屏风张座隅。','',''),('quantangshi-24119','六年冬暮赠崔常侍晦叔','白居易','quantangshi','','卷25','鬓毛霜一色，光景水争流。
易过唯冬日，难销是老愁。
香开绿蚁酒，暖拥褐绫裘。
已共崔君约，尊前倒即休。','',''),('quantangshi-24120','戏招诸客','白居易','quantangshi','','卷25','黄醅绿醑迎冬熟，绛帐红炉逐夜开。
谁道洛中多逸客，不将书唤不曾来。','',''),('quantangshi-24121','十二月二十三日作兼呈晦叔','白居易','quantangshi','','卷25','案头历日虽未尽，向后唯残六七行。
牀下酒瓶虽不满，犹应醉得两三场。
病身不许依年老，拙宦虚教逐日忙。
闻健偷闲且勤饮，一杯之外莫思量。','',''),('quantangshi-24122','七年元日对酒五首 一','白居易','quantangshi','','卷25','庆吊经过嬾，逢迎跪拜迟。
不因时节日，岂觉此身羸。','',''),('quantangshi-24123','七年元日对酒五首 二','白居易','quantangshi','','卷25','众老忧添岁，余衰喜入春。
年开第七秩，屈指几多人。','',''),('quantangshi-24124','七年元日对酒五首 三','白居易','quantangshi','','卷25','三杯蓝尾酒，一楪胶牙饧。
除却崔常侍，无人共我争。','',''),('quantangshi-24125','七年元日对酒五首 四','白居易','quantangshi','','卷25','今朝吴与洛，相忆一欣然。
梦得君知否，俱过本命年。','',''),('quantangshi-24126','七年元日对酒五首 五','白居易','quantangshi','','卷25','同岁崔何在，同年杜又无。
应无藏避处，只有且欢娱。','',''),('quantangshi-24127','七年春题府厅','白居易','quantangshi','','卷25','潦倒守三川，因循涉四年。
推诚废钩距，示耻用蒲鞭。
以此称公事，将何销俸钱。
虽非好官职，岁久亦妨贤。','',''),('quantangshi-24128','早春醉吟寄太原令狐相公苏州刘郎中','白居易','quantangshi','','卷25','雪夜闲游多秉烛，花时蹔出亦提壶。
别来少遇新诗敌，老去难逢旧饮徒。
大振威名降北虏，勤行惠化活东吴。
不知歌酒腾腾兴，得似河南醉尹无。','',''),('quantangshi-24129','洛下送牛相公出镇淮南','白居易','quantangshi','','卷25','北阙至东京，风光十六程。
坐移丞相阁，春入广陵城。
红斾拥双节，白须无一茎。
万人开路看，百吏立班迎。
阃外君弥重，尊前我亦荣。
何须身自得，将相是门生。','',''),('quantangshi-24130','筝','白居易','quantangshi','','卷25','云髻飘萧绿，花颜旖旎红。
双眸剪秋水，十指剥春葱。
楚艳为门阀，秦声是女工。
甲明银玓瓅，柱触玉玲珑。
猨苦啼嫌月，莺娇语䛏风。
移愁来手底，送恨入弦中。
赵瑟清相似，胡琴闹不同。
慢弹回断雁，急奏转飞蓬。
霜佩锵还委，冰泉咽复通。
珠联千拍碎，刀截一声终。
倚丽精神定，矜能意态融。
歇时情不断，休去思无穷。
灯下青春夜，尊前白首翁。
且听应得在，老耳未多聋。','',''),('quantangshi-24131','洛中春游呈诸亲友','白居易','quantangshi','','卷25','莫叹年将暮，须怜岁又新。
府中三遇腊，洛下五逢春。
春树花珠颗，春塘水麴尘。
春娃无气力，春马有精神。
并辔鞭徐动，连盘酒慢巡。
经过旧邻里，追逐好交亲。
笑语销闲日，酣歌送老身。
一生欢乐事，亦不少于人。','',''),('quantangshi-24132','酬舒三员外见赠长句','白居易','quantangshi','','卷25','自请假来多少日，五旬光景似须臾。
已判到老为狂客，不分当春作病夫。
杨柳花飘新白雪，樱桃子缀小红珠。
头风不敢多多饮，能酌三分相劝无。','',''),('quantangshi-24133','将归一绝','白居易','quantangshi','','卷25','欲去公门返野扉，预思泉竹已依依。
更怜家酝迎春熟，一瓮醍醐待我归。','',''),('quantangshi-24134','罢府归旧居','白居易','quantangshi','','卷25','陋巷乘篮入，朱门挂印回。
腰间抛组绶，缨上拂尘埃。
屈曲闲池沼，无非手自开。
青苍好竹树，亦是眼看栽。
石片抬琴匣，松枝阁酒杯。
此生终老处，昨日却归来。','',''),('quantangshi-24135','睡觉偶吟','白居易','quantangshi','','卷25','官初罢后归来夜，天欲明前睡觉时。
起坐思量更无事，身心安乐复谁知。','',''),('quantangshi-24136','问支琴石','白居易','quantangshi','','卷25','疑因星陨空中落，叹被泥埋涧底沈。
天上定应胜地上，支机未必及支琴。
提携拂拭知恩否，虽不能言合有心。','',''),('quantangshi-24137','自喜','白居易','quantangshi','','卷25','身慵难勉强，性拙易迟回。
布被辰时起，柴门午后开。
忙驱能者去，闲逐钝人来。
自喜谁能会，无才胜有才。','',''),('quantangshi-24138','裴常侍以题蔷薇架十八韵见示因广为三十韵以和之','白居易','quantangshi','','卷25','托质依高架，攒花对小堂。
晚开春去后，独秀院中央。
霁景朱明早，芳时白昼长。
穠因天与色，丽共日争光。
剪碧排千萼，研朱染万房。
烟条涂石绿，粉蘂扑雌黄。
根动彤云涌，枝摇赤羽翔。
九微灯炫转，七宝帐荧煌。
淑气熏行径，清阴接步廊。
照梁迷藻梲，耀壁变雕墙。
烂若藂然火，殷于叶得霜。
胭脂含脸笑，苏合裛衣香。
浃洽濡晨露，玲珑漏夕阳。
合罗排勘缬，醉晕浅深妆。
乍见疑回面，遥看误断肠。
风朝舞飞燕，雨夜泣萧娘。
桃李慙无语，芝兰让不芳。
山榴何细碎，石竹苦寻常。
蕙惨偎栏避，莲羞映浦藏。
怯教蕉叶战，妬得柳花狂。
岂可轻嘲咏，应须痛比方。
画幈风自展，绣繖盖谁张。
翠锦挑成字，丹砂印着行。
猩猩凝血点，瑟瑟蹙金匡。
散乱萎红片，尖纤嫩紫芒。
触僧飘毳褐，留妓冒罗裳。
寡和阳春曲，多情骑省郎。
缘夸美颜色，引出好文章。
东顾辞仁里，西归入帝乡。
假如君爱杀，留着莫移将。','',''),('quantangshi-24139','感旧诗卷','白居易','quantangshi','','卷25','夜深吟罢一长吁，老泪灯前湿白须。
二十年前旧诗卷，十人酬和九人无。','',''),('quantangshi-24140','酬李二十侍郎','白居易','quantangshi','','卷25','笋老兰长花渐稀，衰翁相对惜芳菲。
残莺着雨慵休啭，落絮无风凝不飞。
行掇木芽供野食，坐牵萝蔓挂朝衣。
十年分手今同醉，醉未如泥莫道归。','',''),('quantangshi-24141','和梦得','白居易','quantangshi','','卷25','纶阁沈沈无宠命，苏台籍籍有能声。
岂唯不得清文力，但恐空传冗吏名。
郎署回翔何水部，江湖留滞谢宣城。
所嗟非独君如此，自古才难共命争。','',''),('quantangshi-24142','赠草堂宗密上人','白居易','quantangshi','','卷25','吾师道与佛相应，念念无为法法能。
口藏宣传十二部，心台照耀百千灯。
尽离文字非中道，长住虚空是小乘。
少有人知菩萨行，世间只是重高僧。','',''),('quantangshi-24143','喜照密闲实四上人见过','白居易','quantangshi','','卷25','紫袍朝士白髯翁，与俗乖疎与道通。
官秩三回分洛下，交游一半在僧中。
臭[帤]世界终须出，香火因缘久愿同。
斋后将何充供养，西轩泉石北窗风。','',''),('quantangshi-24144','赠皇甫六张十五李二十三宾客','白居易','quantangshi','','卷25','昨日三川新罢守，今年四皓尽分司。
幸陪散秩闲居日，好是登山临水时。
家未苦贫常酝酒，身虽衰病尚吟诗。
龙门泉石香山月，早晚同游报一期。','',''),('quantangshi-24145','微之敦诗晦叔相次长逝岿然自伤因成二绝 一','白居易','quantangshi','','卷25','并失鵷鸾侣，空留麋鹿身。
只应嵩洛下，长作独游人。','',''),('quantangshi-24146','微之敦诗晦叔相次长逝岿然自伤因成二绝 二','白居易','quantangshi','','卷25','长夜君先去，残年我几何。
秋风满衫泪，泉下故人多。','',''),('quantangshi-24147','池上闲咏','白居易','quantangshi','','卷25','青莎台上起书楼，绿藻潭中系钓舟。
日晚爱行深竹里，月明多上小桥头。
蹔尝新酒还成醉，亦出中门便当游。
一部清商聊送老，白须萧飒管弦秋。','',''),('quantangshi-24148','凉风叹','白居易','quantangshi','','卷25','昨夜凉风又飒然，萤飘叶坠卧牀前。
逢秋莫叹须知分，已过潘安三十年。','',''),('quantangshi-24149','和高仆射罢节度让尚书授少保分司喜遂游山水之作','白居易','quantangshi','','卷25','蹔辞八座罢双旌，便作登山临水行。
能以忠贞酬重任，不将富贵碍高情。
朱门出去簪缨从，绛帐归来歌吹迎。
鞍辔闹装光满马，何人信道是书生。','',''),('quantangshi-24150','送考功崔郎中赴阙','白居易','quantangshi','','卷25','称意新官又少年，秋凉身健好朝天。
青云上了无多路，却要徐驱稳着鞭。','',''),('quantangshi-24151','重修香山寺毕题二十二韵以纪之','白居易','quantangshi','','卷25','阙塞龙门口，只园鹫岭头。
曾随减劫坏，今遇胜缘修。
再莹新金刹，重装旧石楼。
病僧皆引起，忙客亦淹留。
四望穷沙界，孤标出赡州。
地图铺洛邑，天柱倚崧丘。
两面苍苍岸，中心瑟瑟流。
波翻八滩雪，堰护一潭油。
台殿朝弥丽，房廊夜更幽。
千花高下塔，一叶往来舟。
岫合云初吐，林开雾半收。
静闻樵子语，远听棹郎讴。
官散殊无事，身闲甚自由。
吟来携笔砚，宿去抱衾裯。
霁月当窗白，凉风满簟秋。
烟香封药竈，泉冷洗茶瓯。
南祖心应学，西方社可投。
先宜知止足，次要悟浮休。
觉路随方乐，迷涂到老愁。
须除爱名障，莫作恋家囚。
便合穷年住，何言竟日游。
可怜终老地，此是我菟裘。','',''),('quantangshi-24152','送杨八给事赴常州','白居易','quantangshi','','卷25','无嗟别青琐，且喜拥朱轮。
五十得三品，百千无一人。
须勤念黎庶，莫苦忆交亲。
此外无过醉，毗陵何限春。','',''),('quantangshi-24153','闻歌者唱微之诗','白居易','quantangshi','','卷25','新诗绝笔声名歇，旧卷生尘箧笥深。
时向歌中闻一句，未容倾耳已伤心。','',''),('quantangshi-24154','醉送李二十常侍赴镇浙东','白居易','quantangshi','','卷25','靖安客舍花枝下，共脱青衫典浊醪。
今日洛桥还醉别，金杯翻污麒麟袍。
喧阗夙驾君脂辖，酩酊离筵我藉糟。
好去商山紫芝伴，珊瑚鞭动马头高。','',''),('quantangshi-24155','醉别程秀才','白居易','quantangshi','','卷25','五度龙门点额回，却缘多艺复多才。
贫泥客路黏难出，愁锁乡心掣不开。
何必更游京国去，不如且入醉乡来。
吴弦楚调潇湘弄，为我殷勤送一杯。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24156','自咏','白居易','quantangshi','','卷25','白衣居士紫芝仙，半醉行歌半坐禅。
今日维摩兼饮酒，当时绮季不请钱。
等闲池上留宾客，随事灯前有管弦。
但问此身销得否，分司气味不论年。','',''),('quantangshi-24157','把酒思闲事二首 一','白居易','quantangshi','','卷25','把酒思闲事，春愁谁最深。
乞钱羁客面，落第举人心。
月下低眉立，灯前抱膝吟。
凭君劝一醉，胜与万黄金。','',''),('quantangshi-24158','把酒思闲事二首 二','白居易','quantangshi','','卷25','把酒思闲事，春娇何处多。
试鞍新白马，弄镜小青娥。
掌上初教舞，花前欲按歌。
凭君劝一醉，劝了问如何。','',''),('quantangshi-24159','衰荷','白居易','quantangshi','','卷25','白露凋花花不残，凉风吹叶叶初干。
无人解爱萧条境，更绕衰藂一匝看。','',''),('quantangshi-24160','池上送考功崔郎中兼别房窦二妓','白居易','quantangshi','','卷25','文昌列宿征还日，洛浦行云放散时。
鵷鹭上天花逐水，无因再会白家池。','',''),('quantangshi-24161','自问','白居易','quantangshi','','卷25','依仁台废悲风晚，履信池荒宿草春。
自问老身骑马出，洛阳城里觅何人。','',''),('quantangshi-24162','送陈许高仆射赴镇','白居易','quantangshi','','卷25','敦诗说礼中军师，重士轻财大丈夫。
常与师徒同苦乐，不教亲故隔荣枯。
花钿坐绕黄金印，丝管行随白玉壶。
商皓老狂唯爱醉，时时能寄酒钱无。','',''),('quantangshi-24163','青毡帐二十韵','白居易','quantangshi','','卷25','合聚千羊毳，施张百子弮。
骨盘边柳健，色染塞蓝鲜。
北制因戎剏，南移逐虏迁。
汰风吹不动，御雨湿弥坚。
有顶中央耸，无隅四向圆。
傍通门豁尔，内密气温然。
远别关山外，初安庭户前。
影孤明月夜，价重苦寒年。
软暖围毡毯，枪摐束管弦。
最宜霜后地，偏称雪中天。
侧置低歌座，平铺小舞筵。
闲多揭帘入，醉便拥袍眠。
铁檠移灯背，银囊带火悬。
深藏晓兰焰，暗贮宿香烟。
兽炭休亲近，狐裘可弃捐。
砚温融冻墨，瓶暖变春泉。
蕙帐徒招隐，茅庵浪坐禅。
贫僧应叹羡，寒士定留连。
宾客于中接，儿孙向后传。
王家夸旧物，未及此青毡。','',''),('quantangshi-24164','答梦得秋日书怀见寄','白居易','quantangshi','','卷25','幸免非常病，甘当本分衰。
眼昏灯最觉，腰瘦带先知。
树叶霜红日，髭须雪白时。
悲愁缘欲老，老过却无悲。','',''),('quantangshi-24165','同诸客题于家公主旧宅','白居易','quantangshi','','卷25','平阳旧宅少人游，应是游人到即愁。
布谷鸟啼桃李院，络丝虫怨凤皇楼。
台倾滑石犹残砌，帘断珍珠不满钩。
闻道至今萧史在，髭须雪白向明州。','',''),('quantangshi-24166','答梦得八月十五日夜翫月见寄','白居易','quantangshi','','卷25','南国碧云客，东京白首翁。
松江初有月，伊水正无风。
远思两乡断，清光千里同。
不知娃馆上，何似石楼中。','',''),('quantangshi-24167','初冬早起寄梦得','白居易','quantangshi','','卷25','起戴乌纱帽，行披白布裘。
炉温先暖酒，手冷未梳头。
早起烟霜白，初寒鸟雀愁。
诗成遣谁和，还是寄苏州。','',''),('quantangshi-24168','秋夜听高调凉州','白居易','quantangshi','','卷25','楼上金风声渐紧，月中银字韵初调。
促张弦柱吹高管，一曲凉州入泬寥。','',''),('quantangshi-24169','香山寺二绝 一','白居易','quantangshi','','卷25','空山寂静老夫闲，伴鸟随云往复还。
家酝满瓶书满架，半移生计入香山。','',''),('quantangshi-24170','香山寺二绝 二','白居易','quantangshi','','卷25','爱风岩上攀松盖，恋月潭边坐石棱。
且共云泉结缘境，他生当作此山僧。','',''),('quantangshi-24171','送舒着作重授省郎赴阙','白居易','quantangshi','','卷25','三岁相依在洛都，游花宴月饱欢娱。
惜别笙歌多怨咽，愿留轩盖少踟蹰。
劒磨光彩依前出，鹏举风云逐后驱。
从此求闲应不得，更能重醉白家无。','',''),('quantangshi-24172','同诸客嘲雪中马上妓','白居易','quantangshi','','卷25','珊瑚鞭嚲马踟蹰，引手低蛾索一盂。
腰为逆风成弱柳，面因冲冷作凝酥。
银箆稳篸乌罗帽，花襜宜乘吒拨驹。
雪里君看何所似，王昭君妹写真图。','',''),('quantangshi-24173','喜刘苏州恩赐金紫遥[想]贺宴以诗庆之','白居易','quantangshi','','卷25','海内姑苏太守贤，恩加章绶岂徒然。
贺宾喜色欺杯酒，醉妓欢声遏管弦。
鱼佩葺鳞光照地，鹘衔瑞带势冲天。
莫嫌鬓上些些白，金紫由来称长年。','',''),('quantangshi-24174','蓝田刘明府携酌相过与皇甫郎中卯时同饮醉后赠之','白居易','quantangshi','','卷25','腊月九日暖寒客，卯时十分空腹杯。
玄晏舞狂乌帽落，蓝田醉倒玉山颓。
貌偷花色老蹔去，歌蹋柳枝春暗来。
不为刘家贤圣物，愁翁笑口大难开。','',''),('quantangshi-24175','刘苏州以华亭一鹤远寄以诗谢之','白居易','quantangshi','','卷25','老鹤风姿异，衰翁诗思深。
素毛如我鬓，丹顶似君心。
松际雪相映，鸡羣尘不侵。
殷勤远来意，一只重千金。','',''),('quantangshi-24176','早春忆苏州寄梦得','白居易','quantangshi','','卷25','吴苑四时风景好，就中偏好是春天。
霞光曙后殷于火，水色晴来嫩似烟。
士女笙歌宜月下，使君金紫称花前。
诚知欢乐堪留恋，其奈离乡已四年。','',''),('quantangshi-24177','尝新酒忆晦叔二首 一','白居易','quantangshi','','卷25','尊里看无色，杯中动有光。
自君抛我去，此物共谁尝。','',''),('quantangshi-24178','尝新酒忆晦叔二首 二','白居易','quantangshi','','卷25','世上强欺弱，人间醉胜醒。
自君抛我去，此语更谁听。','',''),('quantangshi-24179','负春','白居易','quantangshi','','卷25','病来道士教调气，老去山僧劝坐禅。
孤负春风杨柳曲，去年断酒到今年。','',''),('quantangshi-24180','池上闲吟二首 一','白居易','quantangshi','','卷25','高卧闲行自在身，池边六见柳条新。
幸逢尧舜无为日，得作羲皇向上人。
四皓再除犹且健，三州罢守未全贫。
莫愁客到无供给，家酝香浓野菜春。','',''),('quantangshi-24181','池上闲吟二首 二','白居易','quantangshi','','卷25','非庄非宅非兰若，竹树池亭十亩余。
非道非僧非俗吏，褐裘乌帽闭门居。
梦游信意宁殊蝶，心乐身闲便是鱼。
虽未定知生与死，其间胜负两何如。','',''),('quantangshi-24182','早春招张宾客','白居易','quantangshi','','卷25','久雨初晴天气新，风烟草树尽欣欣。
虽当冷落衰残日，还有阳和暖活身。
池色溶溶蓝染水，花光焰焰火烧春。
商山老伴相收拾，不用随他年少人。','',''),('quantangshi-24183','营闲事','白居易','quantangshi','','卷25','自笑营闲事，从朝到日斜。
浇畦引泉脉，扫径避兰芽。
暖变墙衣色，晴催木笔花。
桃根知酒渴，晚送一瓯茶。','',''),('quantangshi-24184','感春','白居易','quantangshi','','卷25','老思不禁春，风光照眼新。
花房红鸟觜，池浪碧鱼鳞。
倚棹谁为伴，持杯自问身。
心情多少在，六十二三人。','',''),('quantangshi-24185','春池上戏赠李郎中','白居易','quantangshi','','卷25','满池春水何人爱，唯我回看指似君。
直似挼蓝新汁色，与君南宅染罗裙。','',''),('quantangshi-24186','翫半开花赠皇甫郎中','白居易','quantangshi','','卷25','勿讶春来晚，无嫌花发迟。
人怜全盛日，我爱半开时。
紫蜡黏为蔕，红苏点作蕤。
成都新夹缬，梁汉碎胭脂。
树杪真珠颗，墙头小女儿。
浅深妆驳落，高下火参差。
蝶戏争香朵，莺啼选稳枝。
好教郎作伴，合共酒相随。
醉翫无胜此，狂嘲更让谁。
犹残少年兴，不似老人诗。
西日凭轻照，东风莫杀吹。
明朝应烂熳，后夜更离披。
林下遥相忆，尊前暗有期。
衔杯嚼蘂思，唯我与君知。','',''),('quantangshi-24187','池边','白居易','quantangshi','','卷25','柳老香丝宛，荷新钿扇圆。
残春深树里，斜日小楼前。
醉遣收杯杓，闲听理管弦。
池边更无事，看补采莲船。','',''),('quantangshi-24188','家酿新熟每尝輙醉妻侄等劝令少饮因成长句以谕之','白居易','quantangshi','','卷25','君应怪我朝朝饮，不说向君君不知。
身上幸无疼痛处，瓮头正是撇尝时。
刘妻劝谏夫休醉，王侄分疎叔不痴。
六十三翁头雪白，假如醒黠欲何为。','',''),('quantangshi-24189','送常秀才下第东归','白居易','quantangshi','','卷25','东归多旅恨，西上少知音。
寒食看花眼，春风落日心。
百忧当二月，一醉直千金。
到处公卿席，无辞酒盏深。','',''),('quantangshi-24190','且游','白居易','quantangshi','','卷25','手里一杯满，心中百事休。
春应唯仰醉，老更不禁愁。
弄水回船尾，寻花信马头。
眼看筋力减，游得且须游。','',''),('quantangshi-24191','题王家庄临水柳亭','白居易','quantangshi','','卷25','弱柳缘堤种，虚亭压水开。
条疑逐风去，波欲上阶来。
翠羽偷鱼入，红腰学舞回。
春愁正无绪，争不尽残杯。','',''),('quantangshi-24192','题令狐家木兰花','白居易','quantangshi','','卷25','腻如玉指涂朱粉，光似金刀剪紫霞。
从此时时春梦里，应添一树女郎花。','',''),('quantangshi-24193','拜表回闲游','白居易','quantangshi','','卷25','玉佩金章紫花绶，紵衫藤带白纶巾。
晨兴拜表称朝士，晚出游山作野人。
达磨传心令息念，玄元留意遣同尘。
八关净戒斋销日，一曲狂歌醉送春。
酒肆法堂方丈室，其间岂是两般身。','',''),('quantangshi-24194','西街渠中种莲叠石颇有幽致偶题小楼','白居易','quantangshi','','卷25','朱槛低墙上，清流小阁前。
雇人栽菡萏，买石造潺湲。
影落江心月，声移谷口泉。
闲看卷帘坐，醉听掩窗眠。
路笑淘官水，家愁费料钱。
是非君莫问，一对一翛然。','',''),('quantangshi-24195','晚春闲居杨工部寄诗杨常州寄茶同到因以长句答之','白居易','quantangshi','','卷25','宿酲寂寞眠初起，春意阑珊日又斜。
劝我加餐因早笋，恨人休醉是残花。
闷吟工部新来句，渴饮毗陵远到茶。
兄弟东西官职冷，门前车马向谁家。','',''),('quantangshi-24196','玉泉寺南三里涧下多深红踯躅繁艳殊常感惜题诗以示游者','白居易','quantangshi','','卷25','玉泉南涧花奇怪，不似花丛似火堆。
今日多情唯我到，每年无故为谁开。
宁辞辛苦行三里，更与留连饮两杯。
犹有一般辜负事，不将歌舞管弦来。','',''),('quantangshi-24197','早服云母散','白居易','quantangshi','','卷25','晓服云英漱井华，寥然身若在烟霞。
药销日晏三匙饭，酒渴春深一椀茶。
每夜坐禅观水月，有时行醉翫风花。
净名事理人难解，身不出家心出家。','',''),('quantangshi-24198','三月晦日晚闻鸟声','白居易','quantangshi','','卷25','晚来林鸟语殷勤，似惜风光说向人。
遣脱破袍劳报暖，催沽美酒敢辞贫。
声声劝醉应须醉，一岁唯残半日春。','',''),('quantangshi-24199','早夏游平原回','白居易','quantangshi','','卷25','夏早日初长，南风草木香。
肩舆颇平稳，涧路甚清凉。
紫蕨行看采，青梅旋摘尝。
疗饥兼解渴，一盏冷云浆。','',''),('quantangshi-24200','宿天竺寺回','白居易','quantangshi','','卷25','野寺经三宿，都城复一还。
家仍念婚嫁，身尚系官班。
萧洒秋临水，沈吟晚下山。
长闲犹未得，逐日且偷闲。','',''),('quantangshi-24201','侍中晋公欲到东洛先蒙书问期宿龙门思往感今輙献长句','白居易','quantangshi','','卷25','昔蒙兴化池头送，今许龙门潭上期。
聚散但慙长见念，荣枯安敢道相思。
功成名遂来虽久，云卧山游去未迟。
闻说风情筋力在，只如初破蔡州时。','',''),('quantangshi-24202','奉和晋公侍中蒙除留守行及洛师感悦发中斐然成咏之作','白居易','quantangshi','','卷25','鸾凤翺翔在寥廓，貂蝉萧洒出埃尘。
致成尧舜升平代，收得夔龙强健身。
抛掷功名还史册，分张欢乐与交亲。
商山老皓虽休去，终是留侯门下人。','',''),('quantangshi-24203','送刘五司马赴任硖州兼寄崔使君','白居易','quantangshi','','卷25','位下才高多怨天，刘兄道胜独恬然。
贫于扬子两三倍，老过荣公六七年。
笔砚莫抛留压案，箪瓢从陋也销钱。
郡丞自合当优礼，何况夷陵太守贤。','',''),('quantangshi-24204','菩提寺上方晚眺','白居易','quantangshi','','卷25','楼阁高低树浅深，山光水色暝沈沈。
嵩烟半卷青绡幕，伊浪平铺绿绮衾。
飞鸟灭时宜极目，远风来处好开襟。
谁知不离簪缨内，长得逍遥自在心。','',''),('quantangshi-24205','杨柳枝词八首 一','白居易','quantangshi','','卷25','六么水调家家唱，白雪梅花处处吹。
古歌旧曲君休听，听取新翻杨柳枝。','',''),('quantangshi-24206','杨柳枝词八首 二','白居易','quantangshi','','卷25','陶令门前四五树，亚夫营里百千条。
何似东都正二月，黄金枝映洛阳桥。','',''),('quantangshi-24207','杨柳枝词八首 三','白居易','quantangshi','','卷25','依依褭褭复青青，句引春风无限情。
白雪花繁空扑地，绿丝条弱不胜莺。','',''),('quantangshi-24208','杨柳枝词八首 四','白居易','quantangshi','','卷25','红板江桥青酒旗，馆娃宫暖日斜时。
可怜雨歇东风定，万树千条各自垂。','',''),('quantangshi-24209','杨柳枝词八首 五','白居易','quantangshi','','卷25','苏州杨柳任君夸，更有钱唐胜馆娃。
若解多情寻小小，绿杨深处是苏家。','',''),('quantangshi-24210','杨柳枝词八首 六','白居易','quantangshi','','卷25','苏家小女旧知名，杨柳风前别有情。
剥条盘作银环样，卷叶吹为玉笛声。','',''),('quantangshi-24211','杨柳枝词八首 七','白居易','quantangshi','','卷25','叶含浓露如啼眼，枝褭轻风似舞腰。
小树不禁攀折苦，乞君留取两三条。','',''),('quantangshi-24212','杨柳枝词八首 八','白居易','quantangshi','','卷25','人言柳叶似愁眉，更有愁肠似柳丝。
柳丝挽断肠牵断，彼此应无续得期。','',''),('quantangshi-24213','读老子','白居易','quantangshi','','卷25','言者不如知者默，此语吾闻于老君。
若道老君是知者，缘何自着五千文。','',''),('quantangshi-24214','读庄子','白居易','quantangshi','','卷25','庄生齐物同归一，我道同中有不同。
遂性逍遥虽一致，莺凰终挍胜蛇虫。','',''),('quantangshi-24215','读禅经','白居易','quantangshi','','卷25','须知诸相皆非相，若住无余却有余。
言下忘言一时了，梦中说梦两重虚。
空花岂得兼求果，阳焰如何更觅鱼。
摄动是禅禅是动，不禅不动即如如。','',''),('quantangshi-24216','感兴二首 一','白居易','quantangshi','','卷25','吉凶祸福有来由，但要深知不要忧。
只见火光烧润屋，不闻风浪覆虚舟。
名为公器无多取，利是身灾合少求。
虽异匏瓜难不食，大都食足早宜休。','',''),('quantangshi-24217','感兴二首 二','白居易','quantangshi','','卷25','鱼能深入宁忧钓，鸟解高飞岂触罗。
热处先争炙手去，悔时其奈噬脐何。
尊前诱得猩猩血，幕上偷安燕燕窠。
我有一言君记取，世间自取苦人多。','',''),('quantangshi-24218','问鹤','白居易','quantangshi','','卷25','乌鸢争食雀争窠，独立池边风雪多。
尽日蹋冰翘一足，不鸣不动意如何。','',''),('quantangshi-24219','代鹤答','白居易','quantangshi','','卷25','鹰爪攫鸡鸡肋折，鹘拳蹴雁雁头垂。
何如歛翅水边立，飞上云松栖稳枝。','',''),('quantangshi-24220','闲卧有所思二首 一','白居易','quantangshi','','卷25','向夕搴帘卧枕琴，微凉入户起开襟。
偶因明月清风夜，忽想迁臣逐客心。
何处投荒初恐惧，谁人绕泽正悲吟。
始知洛下分司坐，一日安闲直万金。','',''),('quantangshi-24221','闲卧有所思二首 二','白居易','quantangshi','','卷25','权门要路是身灾，散地闲居少祸胎。
今日怜君岭南去，当时笑我洛中来。
虫全性命缘无毒，木尽天年为不才。
大抵吉凶多自致，李斯一去二疎回。','',''),('quantangshi-24222','喜闲','白居易','quantangshi','','卷25','萧洒伊嵩下，优游黄绮间。
未曾一日闷，已得六年闲。
鱼鸟为徒侣，烟霞是往还。
伴僧禅闭目，迎客笑开颜。
兴发宵游寺，慵时昼掩关。
夜来风月好，悔不宿香山。','',''),('quantangshi-24223','诗酒琴人例多薄命予酷好三事雅当此科而所得已多为幸斯甚偶成狂咏聊写愧怀','白居易','quantangshi','','卷25','爱琴爱酒爱诗客，多贱多穷多苦辛。
中散步兵终不贵，孟郊张籍过于贫。
一之已叹关于命，三者何堪并在身。
只合飘零随草木，谁教凌厉出风尘。
荣名厚禄二千石，乐饮闲游三十春。
何得无厌时咄咄，犹言薄命不如人。','',''),('quantangshi-24224','寄明州于驸马使君三绝句 一','白居易','quantangshi','','卷25','有花有酒有笙歌，其奈难逢亲故何。
近海饶风春足雨，白须太守闷时多。','',''),('quantangshi-24225','寄明州于驸马使君三绝句 二','白居易','quantangshi','','卷25','平阳音乐随都尉，留滞三年在浙东。
吴越声邪无法用，莫教偷入管弦中。','',''),('quantangshi-24226','寄明州于驸马使君三绝句 三','白居易','quantangshi','','卷25','何郎小妓歌喉好，严老呼为一串珠。
海味腥咸损声气，听看犹得断肠无。','',''),('quantangshi-24227','闲卧','白居易','quantangshi','','卷25','薄食当斋戒，散班同隐沦。
佛容为弟子，天许作闲人。
唯置牀临水，都无物近身。
清风散发卧，兼不要纱巾。','',''),('quantangshi-24228','春早秋初因时即事兼寄浙东李侍郎','白居易','quantangshi','','卷25','春早秋初昼夜长，可怜天气好年光。
和风细动帘帷暖，清露微凝枕簟凉。
窗下晓眠初减被，池边晚坐乍移牀。
闲从蕙草侵堦绿，静任槐花满地黄。
理曲管弦闻后院，熨衣灯火映深房。
四时新景何人别，遥忆多情李侍郎。','',''),('quantangshi-24229','新秋喜凉','白居易','quantangshi','','卷25','过得炎蒸月，尤宜老病身。
衣裳朝不润，枕簟夜相亲。
楼月纤纤早，波风褭褭新。
光阴与时节，先感是诗人。','',''),('quantangshi-24230','初夏闲吟兼呈韦宾客','白居易','quantangshi','','卷25','孟夏清和月，东都闲散官。
体中无病痛，眼下未饥寒。
世事闻常闷，交游见即欢。
杯觞留客切，妓乐取人宽。
雪鬓随身老，云心着处安。
此中殊有味，试说向君看。','',''),('quantangshi-24231','哭崔二十四常侍','白居易','quantangshi','','卷25','貂冠初别九重门，马鬣新封四尺坟。
薤露歌词非白雪，旌铭官爵是浮云。
伯伦每置随身锸，元亮先为自祭文。
莫道高风无继者，一千年内有崔君。','',''),('quantangshi-24232','奉酬侍中夏中雨后游城南庄见示八韵','白居易','quantangshi','','卷25','岛树间林峦，云收雨气残。
四山岚色重，五月水声寒。
老鹤两三只，新篁千万竿。
化成天竺寺，移得子陵滩。
心觉闲弥贵，身缘健更欢。
帝将风后待，人作谢公看。
角里年虽老，高阳兴未阑。
佳辰不见召，争免趂杯盘。','',''),('quantangshi-24233','送兖州崔大夫驸马赴镇','白居易','quantangshi','','卷25','戚里夸为贤驸马，儒家认作好诗人。
鲁侯不得辜风景，沂水年年有暮春。','',''),('quantangshi-24234','少年问','白居易','quantangshi','','卷25','少年怪我问如何，何事朝朝醉复歌。
号作乐天应不错，忧愁时少乐时多。','',''),('quantangshi-24235','问少年','白居易','quantangshi','','卷25','千首诗堆青玉案，十分酒写白金盂。
回头却问诸年少，作个狂夫得了无。','',''),('quantangshi-24236','代琵琶弟子谢女师曹供奉寄新调弄谱','白居易','quantangshi','','卷25','琵琶师在九重城，忽得书来喜且惊。
一纸展看非旧谱，四弦翻出是新声。
蕤宾掩抑娇多怨，散水玲珑峭更清。
珠颗泪霑金捍拨，红妆弟子不胜情。','',''),('quantangshi-24237','代林园戏赠','白居易','quantangshi','','卷25','南院今秋游宴少，西坊近日往来频。
假如宰相池亭好，作客何如作主人。','',''),('quantangshi-24238','戏答林园','白居易','quantangshi','','卷25','岂独西坊来往频，偷闲处处作游人。
衡门虽是栖迟地，不可终朝鏁老身。','',''),('quantangshi-24239','重戏赠','白居易','quantangshi','','卷25','集贤池馆从他盛，履道林亭勿自轻。
往往归来嫌窄小，年年为主莫无情。','',''),('quantangshi-24240','重戏答','白居易','quantangshi','','卷25','小水低亭自可亲，大池高馆不关身。
林园莫妬裴家好，憎故怜新岂是人。','',''),('quantangshi-24241','早秋登天宫寺阁赠诸客','白居易','quantangshi','','卷25','天宫阁上醉萧辰，丝管闲听酒慢巡。
为向凉风清景道，今朝属我两三人。','',''),('quantangshi-24242','晓上天津桥闲望偶逢卢郎中张员外携酒同倾','白居易','quantangshi','','卷25','上阳宫里晓钟后，天津桥头残月前。
空阔境疑非下界，飘颻身似在寥天。
星河隐映初生日，楼阁葱茏半出烟。
此处相逢倾一盏，始知地上有神仙。','',''),('quantangshi-24243','八月十五日夜同诸客翫月','白居易','quantangshi','','卷25','月好共传唯此夜，境闲皆道是东都。
嵩山表里千重雪，洛水高低两颗珠。
清景难逢宜爱惜，白头相劝强欢娱。
诚知亦有来年会，保得晴明强健无。','',''),('quantangshi-24244','对晚开夜合花赠皇甫郎中','白居易','quantangshi','','卷25','移晚校一月，花迟过半年。
红开杪秋日，翠合欲昏天。
白露滴未死，凉风吹更鲜。
后时谁肯顾，唯我与君怜。','',''),('quantangshi-24245','醉游平泉','白居易','quantangshi','','卷25','狂歌箕踞酒尊前，眼不看人面向天。
洛客最闲唯有我，一年四度到平泉。','',''),('quantangshi-24246','题赠平泉韦征君拾遗','白居易','quantangshi','','卷25','箕颍千年后，唯君得古风。
位留丹陛上，身入白云中。
躁静心相背，高低迹不同。
笼鸡与梁燕，不信有冥鸿。','',''),('quantangshi-24247','酬皇甫郎中对新菊花见忆','白居易','quantangshi','','卷25','爱菊高人吟逸韵，悲秋病客感衰怀。
黄花助兴方携酒，红叶添愁正满堦。
居士荤腥今已断，仙郎杯杓为谁排。
愧君相忆东篱下，拟废重阳一日斋。','',''),('quantangshi-24248','夜宴醉后留献裴侍中','白居易','quantangshi','','卷25','九烛台前十二姝，主人留醉任欢娱。
翩翻舞袖双飞蝶，宛转歌声一索珠。
坐久欲醒还酩酊，夜深初散又踟蹰。
南山宾客东山妓，此会人间曾有无。','',''),('quantangshi-24249','和韦庶子远坊赴宴未夜先归之作兼呈裴员外','白居易','quantangshi','','卷25','促席留欢日未曛，远坊归思已纷纷。
无妨按辔行乘月，何必逃杯走似云。
银烛忍抛杨柳曲，金鞍潜送石榴裙。
到时常晚归时早，笑乐三分校一分。','',''),('quantangshi-24250','集贤池答侍中问','白居易','quantangshi','','卷25','主人晚入皇城宿，问客裴回何所须。
池月幸闲无用处，今宵能借客游无。','',''),('quantangshi-24251','杨柳枝二十韵','白居易','quantangshi','','卷25','小妓携桃叶，新声蹋柳枝。
妆成剪烛后，醉起拂衫时。
绣履娇行缓，花筵笑上迟。
身轻委回雪，罗薄透凝脂。
笙引簧频暖，筝催柱数移。
乐童翻怨调，才子与妍词。
便想人如树，先将发比丝。
风条摇两带，烟叶贴双眉。
口动樱桃破，鬟低翡翠垂。
枝柔腰袅娜，荑嫩手葳蕤。
唳鹤啨呼侣，哀猨夜呌儿。
玉敲音历历，珠贯字累累。
袖为收声点，钗因赴节遗。
重重遍头别，一一拍心知。
塞北愁攀折，江南苦别离。
黄遮金谷岸，绿映杏园池。
春惜芳华好，秋怜颜色衰。
取来歌里唱，胜向笛中吹。
曲罢那能别，情多不自持。
缠头无别物，一首断肠诗。','',''),('quantangshi-24252','答皇甫十郎中秋深酒熟见忆','白居易','quantangshi','','卷25','烟景冷苍茫，秋深夜夜霜。
为思池上酌，先觉瓮头香。
未暇倾巾漉，还应染指尝。
醍醐慙气味，琥珀让晶光。
若许陪歌席，须容散道场。
月终斋戒毕，犹及菊花黄。','',''),('quantangshi-24253','老去','白居易','quantangshi','','卷25','老去愧妻儿，冬来有劝词。
暖寒从饮酒，冲冷少吟诗。
战胜心还壮，斋勤体校羸。
由来世间法，损益合相随。','',''),('quantangshi-24254','送宗实上人游江南','白居易','quantangshi','','卷25','忽辞洛下缘何事，拟向江南住几时。
每过渡头应问法，无妨菩萨是船师。','',''),('quantangshi-24255','和同州杨侍郎夸柘枝见寄','白居易','quantangshi','','卷25','细吟冯翊使君诗，忆作余杭太守时。
君有一般输我事，柘枝看校十年迟。','',''),('quantangshi-24256','冬初酒熟二首 一','白居易','quantangshi','','卷25','霜繁脆庭柳，风利剪池荷。
月色晓弥苦，鸟声寒更多。
秋怀久寥落，冬计又如何。
一瓮新醅酒，萍浮春水波。','',''),('quantangshi-24257','冬初酒熟二首 二','白居易','quantangshi','','卷25','酒熟无客来，因成独酌谣。
人间老黄绮，地上散松乔。
忽忽醒还醉，悠悠暮复朝。
残年多少在，尽付此中销。','',''),('quantangshi-24258','送姚杭州赴任因思旧游二首 一','白居易','quantangshi','','卷25','与君细话杭州事，为我留心莫等闲。
闾里固宜勤抚恤，楼台亦要数跻攀。
笙歌缥缈虚空里，风月依稀梦想间。
且喜诗人重管领，遥飞一盏贺江山。','',''),('quantangshi-24259','送姚杭州赴任因思旧游二首 二','白居易','quantangshi','','卷25','渺渺钱唐路几千，想君到后事依然。
静逢竺寺猨偷橘，闲看苏家女采莲。
故妓数人凭问询，新诗两首倩留传。
舍人虽健无多兴，老挍当时八九年。','',''),('quantangshi-24260','寄李相公','白居易','quantangshi','','卷25','渐老只谋欢，虽贫不要官。
唯求造化力，试为驻春看。','',''),('quantangshi-24261','冬日平泉路晚归','白居易','quantangshi','','卷25','山路难行日易斜，烟村霜树欲栖鵶。
夜归不到应闲事，热饮三杯即是家。','',''),('quantangshi-24262','利仁北街作','白居易','quantangshi','','卷25','草色斑斑春雨晴，利仁坊北面西行。
踟蹰立马缘何事，认得张家歌吹声。','',''),('quantangshi-24263','洛阳堰闲行','白居易','quantangshi','','卷25','洛阳堰上新晴日，长夏门前欲暮春。
遇酒即沽逢树歇，七年此地作闲人。','',''),('quantangshi-24264','过永宁','白居易','quantangshi','','卷25','村杏野桃繁似雪，行人不醉为谁开。
赖逢山县卢明府，引我花前劝一杯。','',''),('quantangshi-24265','往年稠桑曾丧白马题诗厅壁今来尚存又复感怀更题绝句','白居易','quantangshi','','卷25','路傍埋骨蒿草合，壁上题诗尘藓生。
马死七年犹怅望，自知无乃太多情。','',''),('quantangshi-24266','罗敷水','白居易','quantangshi','','卷25','野店东头花落处，一条流水号罗敷。
芳魂艳骨知何处，春草茫茫墓亦无。','',''),('quantangshi-24267','路逢青州王大夫赴镇立马赠别','白居易','quantangshi','','卷25','大斾拥金羁，书生得者稀。
何劳问官职，岂不见光辉。
赫赫人争看，翩翩马欲飞。
不期前岁尹，驻节语依依。','',''),('quantangshi-24268','和杨同州寒食干坑会后闻杨工部欲到知予与工部有宿酲','白居易','quantangshi','','卷25','夜饮归常晚，朝眠起更迟。
举头中酒后，引手索茶时。
拂枕青长袖，欹簪白接䍦。
宿酲无兴味，先是肺神知。','',''),('quantangshi-24269','和刘汝州酬侍中见寄长句因书集贤坊胜事戏而问之','白居易','quantangshi','','卷25','洛川汝海封畿接，履道集贤来往频。
一复时程虽不远，百余步地更相亲。
朱门陪宴多投辖，青眼留欢任吐茵。
闻道郡斋还有酒，花前月下对何人。','',''),('quantangshi-24270','池上二绝 一','白居易','quantangshi','','卷25','山僧对棊坐，局上竹阴清。
映竹无人见，时闻下子声。','',''),('quantangshi-24271','池上二绝 二','白居易','quantangshi','','卷25','小娃撑小艇，偷采白莲回。
不解藏踪迹，浮萍一道开。','',''),('quantangshi-24272','白羽扇','白居易','quantangshi','','卷25','素是自然色，圆因裁制功。
飒如松起籁，飘似鹤翻空。
盛夏不销雪，终年无尽风。
引秋生手里，藏月入怀中。
麈尾斑非疋，蒲葵陋不同。
何人称相对，清瘦白须翁。','',''),('quantangshi-24273','五月斋戒罢宴彻乐闻韦宾客皇甫郎中饮会亦稀又知欲携酒馔出斋先以长句呈谢','白居易','quantangshi','','卷25','妓房匣镜满红埃，酒库封瓶生绿苔。
居士尔时缘护戒，车公何事亦停杯。
散斋香火今朝散，开素盘筵后日开。
随意往还君莫怪，坐禅僧去饮徒来。','',''),('quantangshi-24274','闲园独赏','白居易','quantangshi','','卷25','午后郊园静，晴来景物新。
雨添山气色，风借水精神。
永日若为度，独游何所亲。
仙禽狎君子，芳树倚佳人。
蚁鬬王争肉，蜗移舍逐身。
蝶双知伉俪，蜂分见君臣。
蠢蠕形虽小，逍遥性即均。
不知鹏与鷃，相去几微尘。','',''),('quantangshi-24275','种柳三咏 一','白居易','quantangshi','','卷25','白头种松桂，早晚见成林。
不及栽杨柳，明年便有阴。
春风为催促，副取老人心。','',''),('quantangshi-24276','种柳三咏 二','白居易','quantangshi','','卷25','从君种杨柳，夹水意如何。
准拟三年后，青丝拂绿波。
仍教小楼上，对唱柳枝歌。','',''),('quantangshi-24277','种柳三咏 三','白居易','quantangshi','','卷25','更想五年后，千千条麴尘。
路傍深映月，楼上暗藏春。
愁杀闲游客，闻歌不见人。','',''),('quantangshi-24278','偶吟','白居易','quantangshi','','卷25','好官病免曾三度，散地归休已七年。
老自退闲非世弃，贫蒙强健是天怜。
韦荆南去留春服，王侍中来乞酒钱。
便得一年生计足，与君美食复甘眠。','',''),('quantangshi-24279','池上即事','白居易','quantangshi','','卷25','移牀避日依松竹，解带当风挂薜萝。
钿砌池心绿苹合，粉开花面白莲多。
久阴新霁宜丝管，苦热初凉入绮罗。
家酝瓶空人客绝，今宵争奈月明何。','',''),('quantangshi-24280','南塘暝兴','白居易','quantangshi','','卷25','水色昏犹白，霞光暗渐无。
风荷摇破扇，波月动连珠。
蟋蟀啼相应，鸳鸯宿不孤。
小僮频报夜，归步尚踟蹰。','',''),('quantangshi-24281','小宅','白居易','quantangshi','','卷25','小宅里闾接，疎篱鸡犬通。
渠分南巷水，窗借北家风。
庾信园殊小，陶潜屋不丰。
何劳问宽窄，宽窄在心中。','',''),('quantangshi-24282','谕亲友','白居易','quantangshi','','卷25','适情处处皆安乐，大抵园林胜市朝。
烦闹荣华犹易过，优闲福禄更难销。
自怜老大宜疎散，却被交亲叹寂寥。
终日相逢不相见，两心相去一何遥。','',''),('quantangshi-24283','龙门送别皇甫泽州赴任韦山人南游','白居易','quantangshi','','卷25','隼旟归洛知何日，鹤驾还嵩莫过春。
惆怅香山云水冷，明朝便是独游人。','',''),('quantangshi-24284','刘苏州寄酿酒糯米李浙东寄杨柳枝舞衫偶因尝酒试衫輙成长句寄谢之','白居易','quantangshi','','卷25','柳枝谩蹋试双袖，桑落初香尝一杯。
金屑醅浓吴米酿，银泥衫稳越娃裁。
舞时已觉愁眉展，醉后仍教笑口开。
慙愧故人怜寂寞，三千里外寄欢来。','',''),('quantangshi-24285','诏授同州刺史病不赴任因咏所怀','白居易','quantangshi','','卷25','同州慵不去，此意复谁知。
诚爱俸钱厚，其如身力衰。
可怜病判案，何似醉吟诗。
劳逸悬相远，行藏决不疑。
徒烦人劝谏，只合自寻思。
白发来无限，青山去有期。
野心惟怕闹，家口莫愁饥。
卖却新昌宅，聊充送老资。','',''),('quantangshi-24286','寄杨六侍郎','白居易','quantangshi','','卷25','西户最荣君好去，左冯虽稳我慵来。
秋风一筯鲈鱼鲙，张翰摇头唤不回。','',''),('quantangshi-24287','韦七自太子宾客再除祕书监以长句贺而饯之','白居易','quantangshi','','卷25','离筵莫怆且同欢，共贺新恩拜旧官。
屈就商山伴麋鹿，好归芸阁狎鵷鸾。
落星石上苍苔古，画鹤厅前白露寒。
老监姓名应在壁，相思试为拂尘看。','',''),('quantangshi-24288','酒熟忆皇甫十','白居易','quantangshi','','卷25','新酒此时熟，故人何日来。
自从金谷别，不见玉山颓。
疎索柳花盌，寂寥荷叶杯。
今冬问毡帐，雪里为谁开。','',''),('quantangshi-24289','九年十一月二十一日感事而作','白居易','quantangshi','','卷25','祸福茫茫不可期，大都早退似先知。
当君白首同归日，是我青山独往时。
顾索素琴应不暇，忆牵黄犬定难追。
麒麟作脯龙为醢，何似泥中曳尾龟。','',''),('quantangshi-24290','即事重题','白居易','quantangshi','','卷25','重裘暖帽宽毡履，小阁低窗深地炉。
身稳心安眠未起，西京朝士得知无。','',''),('quantangshi-24291','将归渭村先寄舍弟','白居易','quantangshi','','卷25','一年年觉此身衰，一日日知前事非。
咏月嘲风先要减，登山临水亦宜稀。
子平嫁娶贫中毕，元亮田园醉里归。
为报阿连寒食下，与吾酿酒扫柴扉。','',''),('quantangshi-24292','看嵩洛有叹','白居易','quantangshi','','卷25','今日看嵩洛，回头叹世间。
荣华急如水，忧患大于山。
见苦方知乐，经忙始爱闲。
未闻笼里鸟，飞出肯飞还。','',''),('quantangshi-24293','咏怀','白居易','quantangshi','','卷25','随缘逐处便安闲，不入朝廷不住山。
心似虚舟浮水上，身同宿鸟寄林间。
尚平婚嫁了无累，冯翊符章封却还。
处分贫家残活计，匹如身后莫相关。','',''),('quantangshi-24294','咏老赠梦得','白居易','quantangshi','','卷25','与君俱老也，自问老何如。
眼涩夜先卧，头慵朝未梳。
有时扶杖出，尽日闭门居。
嬾照新磨镜，休看小字书。
情于故人重，迹共少年疎。
唯是闲谈兴，相逢尚有余。','',''),('quantangshi-24295','从同州刺史改授太子少傅分司','白居易','quantangshi','','卷25','承华东署三分务，履道西池七过春。
歌酒优游聊卒岁，园林萧洒可终身。
留侯爵秩诚虚贵，疏受生涯未苦贫。
月俸百千官二品，朝廷雇我作闲人。','',''),('quantangshi-24296','奉和裴令公新成午桥庄绿野堂即事','白居易','quantangshi','','卷25','旧径开桃李，新池凿凤皇。
只添丞相阁，不改午桥庄。
远处尘埃少，闲中日月长。
青山为外屏，绿野是前堂。
引水多随势，栽松不趂行。
年华玩风景，春事看农桑。
花妬谢家妓，兰偷荀令香。
游丝飘酒席，瀑布溅琴牀。
巢许终身稳，萧曹到老忙。
千年落公便，进退处中央。','',''),('quantangshi-24297','自题小草亭','白居易','quantangshi','','卷25','新结一茅茨，规模俭且卑。
土堦全垒块，山木半留皮。
阴合连藤架，藂香近菊篱。
壁宜藜杖倚，门称荻帘垂。
窗里风清夜，檐间月好时。
留连尝酒客，句引坐禅师。
伴宿双栖鹤，扶行一侍儿。
绿醅量盏饮，红稻约升炊。
龌龊豪家笑，酸寒富室欺。
陶庐闲自爱，颜巷陋谁知。
蝼蚁谋深穴，鹪鹩占小枝。
各随其分足，焉用有余为。','',''),('quantangshi-24298','自咏','白居易','quantangshi','','卷25','细故随缘尽，衰形具体微。
鬬闲僧尚闹，较瘦鹤犹肥。
老遣宽裁袜，寒教厚絮衣。
马从衔草展，鸡任啄笼飞。
只要天和在，无令物性违。
自余君莫问，何是复何非。','',''),('quantangshi-24299','新亭病后独坐招李侍郎公垂','白居易','quantangshi','','卷25','新亭未有客，景日独何为。
趂暖泥茶竈，防寒夹竹篱。
头风初定后，眼暗欲明时。
浅把三分酒，闲题数句诗。
应须置两榻，一榻待公垂。','',''),('quantangshi-24300','闲卧寄刘同州','白居易','quantangshi','','卷25','软褥短屏风，昏昏醉卧翁。
鼻香茶熟后，腰暖日阳中。
伴老琴长在，迎春酒不空。
可怜闲气味，唯欠与君同。','',''),('quantangshi-24301','残酌晚餐','白居易','quantangshi','','卷25','闲倾残酒后，暖拥小炉时。
舞看新翻曲，歌听自作词。
鱼香肥泼火，饭细滑流匙。
除却慵馋外，其余尽不知。','',''),('quantangshi-24302','喜见刘同州梦得','白居易','quantangshi','','卷25','紫绶白髭须，同年二老夫。
论心共牢落，见面且欢娱。
酒好携来否，诗多记得无。
应须为春草，五马少踟蹰。','',''),('quantangshi-24303','裴令公席上赠别梦得','白居易','quantangshi','','卷25','年老官高多别离，转难相见转相思。
雪销酒尽梁王起，便是邹枚分散时。','',''),('quantangshi-24304','寻春题诸家园林','白居易','quantangshi','','卷25','闻健朝朝出，乘春处处寻。
天供闲日月，人借好园林。
渐以狂为态，都无闷到心。
平生身得所，未省似而今。','',''),('quantangshi-24305','又题一绝','白居易','quantangshi','','卷25','貌随年老欲何如，兴遇春牵尚有余。
遥见人家花便入，不论贵贱与亲疎。','',''),('quantangshi-24306','家园三绝 一','白居易','quantangshi','','卷25','沧浪峡水子陵滩，路远江深欲去难。
何似家池通小院，卧房阶下插鱼竿。','',''),('quantangshi-24307','家园三绝 二','白居易','quantangshi','','卷25','篱下先生时得醉，瓮间吏部暂偷闲。
何如家酝双鱼榼，雪夜花时长在前。','',''),('quantangshi-24308','家园三绝 三','白居易','quantangshi','','卷25','鸳鸯怕捉竟难亲，鹦鹉虽笼不着人。
何似家禽双白鹤，闲行一步亦随身。','',''),('quantangshi-24309','老来生计','白居易','quantangshi','','卷25','老来生计君看取，白日游行夜醉吟。
陶令有田唯种黍，邓家无子不留金。
人间荣耀因缘浅，林下幽闲气味深。
烦虑渐消虚白长，一年心胜一年心。','',''),('quantangshi-24310','早春题少室东岩','白居易','quantangshi','','卷25','三十六峰晴，雪销岚翠生。
月留三夜宿，春引四山行。
远草初含色，寒禽未变声。
东岩最高石，唯我有题名。','',''),('quantangshi-24311','早春即事','白居易','quantangshi','','卷25','眼重朝眠足，头轻宿酒醒。
阳光满前户，雪水半中庭。
物变随天气，春生逐地形。
北檐梅晚白，东岸柳先青。
葱壠抽羊角，松巢堕鹤翎。
老来诗更拙，吟罢少人听。','',''),('quantangshi-24312','叹春风兼赠李二十侍郎二绝 一','白居易','quantangshi','','卷25','树根雪尽催花发，池岸冰消放草生。
唯有须霜依旧白，春风于我独无情。','',''),('quantangshi-24313','叹春风兼赠李二十侍郎二绝 二','白居易','quantangshi','','卷25','道场斋戒今初毕，酒伴欢娱久不同。
不把一杯来劝我，无情亦得似春风。','',''),('quantangshi-24314','春来频与李二宾客郭外同游因赠长句','白居易','quantangshi','','卷25','风光引步酒开颜，送老消春嵩洛间。
朝蹋落花相伴出，暮随飞鸟一时还。
我为病叟诚宜退，君是才臣岂合闲。
可惜济时心力在，放教临水复登山。','',''),('quantangshi-24315','二月二日','白居易','quantangshi','','卷25','二月二日新雨晴，草芽菜甲一时生。
轻衫细马春年少，十字津头一字行。','',''),('quantangshi-24316','奉和令公绿野堂种花','白居易','quantangshi','','卷25','绿野堂开占物华，路人指道令公家。
令公桃李满天下，何用堂前更种花。','',''),('quantangshi-24317','清明日登老君阁望洛城赠韩道士','白居易','quantangshi','','卷25','风光烟火清明日，歌哭悲欢城市间。
何事不随东洛水，谁家又葬北邙山。
中桥车马长无已，下渡舟航亦不闲。
冢墓累累人扰扰，辽东怅望鹤飞还。','',''),('quantangshi-24318','三月三日','白居易','quantangshi','','卷25','画堂三月初三日，絮扑窗纱燕拂檐。
莲子数杯尝冷酒，柘枝一曲试春衫。
阶临池面胜看镜，户映花藂当下帘。
指点楼南玩新月，玉钩素手两纤纤。','',''),('quantangshi-24319','雨中听琴者弹别鹤操','白居易','quantangshi','','卷25','双鹤分离一何苦，连阴雨夜不堪闻。
莫教迁客孀妻听，嗟叹悲啼䛏杀君。','',''),('quantangshi-24320','酬郑二司录与李六郎中寒食日相过同宴见赠','白居易','quantangshi','','卷25','偶因冷节会嘉宾，况是平生心所亲。
迎接须衿疏傅老，祗供莫笑阮家贫。
杯盘狼籍宜侵夜，风景阑珊欲过春。
相对喜欢还怅望，同年只有此三人。','',''),('quantangshi-24321','喜杨六侍御同宿','白居易','quantangshi','','卷25','岸帻静言明月夜，匡牀闲卧落花朝。
二三月里饶春睡，七八年来不早朝。
浊水清尘难会合，高鹏低鷃各逍遥。
眼看又上青云去，更卜同衾一两宵。','',''),('quantangshi-24322','残春咏怀赠杨慕巢侍郎','白居易','quantangshi','','卷25','位逾三品日，年过六旬时。
不道官班下，其如筋力衰。
犹怜好风景，转重旧亲知。
少壮难重得，欢娱且强为。
兴来池上酌，醉出袖中诗。
静话开襟久，闲吟放盏迟。
落花无限雪，残鬓几多丝。
莫说伤心事，春翁易酒悲。','',''),('quantangshi-24323','闲居春尽','白居易','quantangshi','','卷25','闲泊池舟静掩扉，老身慵出客来稀。
愁应暮雨留教住，春被残莺唤遣归。
揭瓮偷尝新熟酒，开箱试着旧生衣。
冬裘夏葛相催促，垂老光阴速似飞。','',''),('quantangshi-24324','春尽日天津桥醉吟偶呈李尹侍郎','白居易','quantangshi','','卷25','宿雨洗天津，无泥未有尘。
初晴迎早夏，落照送残春。
兴发诗随口，狂来酒寄身。
水边行嵬峩，桥上立逡巡。
疎傅心情老，吴公政化新。
三川徒有主，风景属闲人。','',''),('quantangshi-24325','池上逐凉二首 一','白居易','quantangshi','','卷25','青苔地上消残暑，绿树阴前逐晚凉。
轻屐单衫薄纱帽，浅池平岸庳藤牀。
簪缨怪我情何薄，泉石谙君味甚长。
徧问交亲为老计，多言宜静不宜忙。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24326','池上逐凉二首 二','白居易','quantangshi','','卷25','窗间睡足休高枕，水畔闲来上小船。
棹遣秃头奴子拨，茶教纤手侍儿煎。
门前便是红尘地，林外无非赤日天。
谁信好风清簟上，更无一事但翛然。','',''),('quantangshi-24327','香山避暑二绝 一','白居易','quantangshi','','卷25','六月滩声如猛雨，香山楼北畅师房。
夜深起凭阑干立，满耳潺湲满面凉。','',''),('quantangshi-24328','香山避暑二绝 二','白居易','quantangshi','','卷25','纱巾草履竹疎衣，晚下香山蹋翠微。
一路凉风十八里，卧乘篮轝睡中归。','',''),('quantangshi-24329','老夫','白居易','quantangshi','','卷25','七八年来游洛都，三分游伴二分无。
风前月下花园里，处处唯残个老夫。
世事劳心非富贵，人间实事是欢娱。
谁能逐我来闲坐，时共酣歌倾一壶。','',''),('quantangshi-24330','香山下卜居','白居易','quantangshi','','卷25','老须为老计，老计在抽簪。
山下初投足，人间久息心。
乱藤遮石壁，绝涧护云林。
若要深藏处，无如此处深。','',''),('quantangshi-24331','无长物','白居易','quantangshi','','卷25','莫讶家居窄，无嫌活计贫。
只缘无长物，始得作闲人。
青竹单牀簟，乌纱独幅巾。
其余皆称是，亦足奉吾身。','',''),('quantangshi-24332','宿香山寺酬广陵牛相公见寄','白居易','quantangshi','','卷25','手札八行诗一篇，无由相见但依然。
君匡圣主方行道，我事空王正坐禅。
支许徒思游白月，夔龙未放下青天。
应须且为苍生住，犹去悬车十四年。','',''),('quantangshi-24333','以诗代书寄户部杨侍郎劝买东邻王家宅','白居易','quantangshi','','卷25','劝君买取东邻宅，与我衡门相并开。
云映嵩峰当户牖，月和伊水入池台。
林园亦要闻闲置，筋力应须及健回。
莫学因循白宾客，欲年六十始归来。','',''),('quantangshi-24334','赠谈客','白居易','quantangshi','','卷25','上客清谈何亹亹，幽人闲思自寥寥。
请君休说长安事，膝上风清琴正调。','',''),('quantangshi-24335','初入香山院对月','白居易','quantangshi','','卷25','老住香山初到夜，秋逢白月正圆时。
从今便是家山月，试问清光知不知。','',''),('quantangshi-24336','题龙门堰西涧','白居易','quantangshi','','卷25','东岸菊丛西岸柳，柳阴烟合菊花开。
一条秋水琉璃色，阔狭才容小舫回。
除却悠悠白少傅，何人解入此中来。','',''),('quantangshi-24337','秋霖中奉裴令公见招早出赴会马上先寄六韵','白居易','quantangshi','','卷25','雨暗三秋日，泥深一尺时。
老人平旦出，自问欲何之。
不是寻医药，非干送别离。
素书传好语，绛帐赴佳期。
续借桃花马，催迎杨柳姬。
只愁张录事，罚我怪来迟。','',''),('quantangshi-24338','尝酒听歌招客','白居易','quantangshi','','卷25','一瓮香醪新插刍，双鬟小妓薄能讴。
管弦渐好新教得，罗绮虽贫免外求。
世上贪忙不觉苦，人间除醉即须愁。
不知此事君知否，君若知时从我游。','',''),('quantangshi-24339','八月三日夜作','白居易','quantangshi','','卷25','露白月微明，天凉景物清。
草头珠颗冷，楼角玉钩生。
气爽衣裳健，风疎砧杵鸣。
夜衾香有思，秋簟冷无情。
梦短眠频觉，宵长起暂行。
烛凝临晓影，虫怨欲寒声。
槿老花先尽，莲凋子始成。
四时无了日，何用叹衰荣。','',''),('quantangshi-24340','病中赠南邻觅酒','白居易','quantangshi','','卷25','头痛牙疼三日卧，妻看煎药婢来扶。
今朝似校抬头语，先问南邻有酒无。','',''),('quantangshi-24341','晓眠后寄杨户部','白居易','quantangshi','','卷25','輭绫腰褥薄緜被，凉冷秋天稳暖身。
一觉晓眠殊有味，无因寄与早朝人。','',''),('quantangshi-24342','秋雨夜眠','白居易','quantangshi','','卷25','凉冷三秋夜，安闲一老翁。
卧迟灯灭后，睡美雨声中。
灰宿温瓶火，香添暖被笼。
晓晴寒未起，霜叶满阶红。','',''),('quantangshi-24343','喜梦得自冯翊归洛兼呈令公','白居易','quantangshi','','卷25','上客新从左辅回，高阳兴助洛阳才。
已将四海声名去，又占三春风景来。
甲子等头怜共老，文章敌手莫相猜。
邹枚未用争诗酒，且饮梁王贺喜杯。','',''),('quantangshi-24344','斋戒满夜戏招梦得','白居易','quantangshi','','卷25','纱笼灯下道场前，白日持斋夜坐禅。
无复更思身外事，未能全尽世间缘。
明朝又拟亲杯酒，今夕先闻理管弦。
方丈若能来问疾，不妨兼有散花天。','',''),('quantangshi-24345','和令公问刘宾客归来称意无之作','白居易','quantangshi','','卷25','水南秋一半，风景未萧条。
皂盖回沙苑，蓝轝上洛桥。
闲尝黄菊酒，醉唱紫芝谣。
称意那劳问，请钱不早朝。','',''),('quantangshi-24346','酬梦得穷秋夜坐即事见寄','白居易','quantangshi','','卷25','焰细灯将尽，声遥漏正长。
老人秋向火，小女夜缝裳。
菊悴篱经雨，萍销水得霜。
今冬暖寒酒，先拟共君尝。','',''),('quantangshi-24347','偶于维扬牛相公处觅得筝筝未到先寄诗来走笔戏答','白居易','quantangshi','','卷25','楚匠饶巧思，秦筝多好音。
如能惠一面，何啻直双金。
玉柱调须品，朱弦染要深。
会教魔女弄，不动是禅心。','',''),('quantangshi-24348','答梦得秋庭独坐见赠','白居易','quantangshi','','卷25','林梢隐映夕阳残，庭际萧疎夜气寒。
霜草欲枯虫思急，风枝未定鸟栖难。
容衰见镜同惆怅，身健逢杯且喜欢。
应是天教相暖热，一时垂老与闲宫。','',''),('quantangshi-24349','长斋月满携酒先与梦得对酌醉中同赴令公之宴戏赠梦得','白居易','quantangshi','','卷25','斋宫前日满三旬，酒榼今朝一拂尘。
乘兴还同访戴客，解酲仍对姓刘人。
病心汤沃寒灰活，老面花生朽木春。
若怕平原怪先醉，知君未惯吐车茵。','',''),('quantangshi-24350','奉酬淮南牛相公思黯见寄二十四韵','白居易','quantangshi','','卷25','白老忘机客，牛公济世贤。
鸥栖心恋水，鹏举翅摩天。
累就优闲秩，连操造化权。
贫司甚萧洒，荣路自喧阗。
望苑三千日，台阶十五年。
是人皆弃忘，何物不陶甄。
篮轝游嵩岭，油幢镇海壖。
竹篙撑钓艇，金甲拥楼船。
雪夜寻僧舍，春朝列妓筵。
长斋俨香火，密宴簇花钿。
自觉闲胜闹，遥知醉笑禅。
是非分未定，会合杳无缘。
我正思杨府，君应望洛川。
西来风褭褭，南去雁连连。
日落龙门外，潮生瓜步前。
秋同一时尽，月共两乡圆。
旧眷交欢在，新文气调全。
慙无白雪曲，难答碧云篇。
金谷诗谁赏，芜城赋众传。
珠应哂鱼目，铅未伏龙泉。
远讯惊魔物，深情寄酒钱。
霜纨一百疋，玉柱十三弦。
楚醴来尊里，秦声送耳边。
何时红烛下，相对一陶然。','',''),('quantangshi-24351','吴祕监每有美酒独酌独醉但蒙诗报不以饮招輙此戏酬兼呈梦得','白居易','quantangshi','','卷25','蓬山仙客下烟霄，对酒唯吟独酌谣。
不怕道狂挥玉爵，亦曾乘兴解金貂。
君称名士夸能饮，我是愚夫肯见招。
赖有伯伦为醉伴，何愁不解傲松乔。','',''),('quantangshi-24352','酬梦得霜夜对月见怀','白居易','quantangshi','','卷25','凄清冬夜景，摇落长年情。
月带新霜色，砧和远雁声。
暖怜炉火近，寒觉被衣轻。
枕上酬佳句，诗成梦不成。','',''),('quantangshi-24353','初冬月夜得皇甫泽州手札并诗数篇因遣报书偶题长句','白居易','quantangshi','','卷25','清泠玉韵两三章，落箔银钩七八行。
心逐报书悬雁足，梦寻来路绕羊肠。
水南地空多明月，山北天寒足早霜。
最恨泼醅新熟酒，迎冬不得共君尝。','',''),('quantangshi-24354','雪中酒熟欲携访吴监先寄此诗','白居易','quantangshi','','卷25','新雪对新酒，忆同倾一杯。
自然须访戴，不必待延枚。
陈榻无辞解，袁门莫嬾开。
笙歌与谈笑，随事自将来。','',''),('quantangshi-24355','酬令公雪中见赠讶不与梦得同相访','白居易','quantangshi','','卷25','雪似鹅毛飞散乱，人披鹤氅立裴回。
邹生枚叟非无兴，唯待梁王召即来。','',''),('quantangshi-24356','题酒瓮呈梦得','白居易','quantangshi','','卷25','若无清酒两三瓮，争向白须千万茎。
麴糵销愁真得力，光阴催老苦无情。
凌烟阁上功无分，伏火炉中药未成。
更拟共君何处去，且来同作醉先生。','',''),('quantangshi-24357','迂叟','白居易','quantangshi','','卷25','一辞魏阙就商宾，散地闲居八九春。
初时被目为迂叟，近日蒙呼作隐人。
冷暖俗情谙世路，是非闲论任交亲。
应须绳墨机关外，安置疎愚钝滞身。','',''),('quantangshi-24358','洛下闲居寄山南令狐相公','白居易','quantangshi','','卷25','已收身向园林下，犹寄名于禄仕间。
不锻嵇康弥嬾静，无金疎傅更贫闲。
支分门内余生计，谢绝朝中旧往还。
唯是相君忘未得，时思汉水梦巴山。','',''),('quantangshi-24359','惜春赠李尹','白居易','quantangshi','','卷25','春色有时尽，公门终日忙。
两衙但不阙，一醉亦何妨。
芳树花团雪，衰翁鬓扑霜。
知君倚年少，未苦惜风光。','',''),('quantangshi-24360','对酒劝令公开春游宴','白居易','quantangshi','','卷25','时泰岁丰无事日，功成名遂自由身。
前头更有忘忧日，向上应无快活人。
自去年来多事故，从今日去少交亲。
宜须数数谋欢会，好作开成第二春。','',''),('quantangshi-24361','与梦得偶同到敦诗宅感而题壁','白居易','quantangshi','','卷25','山东才副苍生愿，川上俄惊逝水波。
履道凄凉新第宅，宣城零落旧笙歌。
园荒唯有薪堪采，门冷兼无雀可罗。
今日相逢偶同到，伤心不是故经过。','',''),('quantangshi-24362','杨六尚书新授东川节度使代妻戏贺兄嫂二绝 一','白居易','quantangshi','','卷25','刘纲与妇共升仙，弄玉随夫亦上天。
何似沙哥领崔嫂，碧油幢引向东川。','',''),('quantangshi-24363','杨六尚书新授东川节度使代妻戏贺兄嫂二绝 二','白居易','quantangshi','','卷25','金花银椀饶君用，罨画罗衣尽嫂裁。
觅得黔娄为妹壻，可能空寄蜀茶来。','',''),('quantangshi-24364','闲游即事','白居易','quantangshi','','卷25','郊野游行熟，村园次第过。
蓦山寻浥涧，蹋水渡伊河。
寒食青青草，春风瑟瑟波。
逢人共杯酒，随马有笙歌。
胜事经非少，芳辰过亦多。
还须自知分，不老拟如何。','',''),('quantangshi-24365','六十六','白居易','quantangshi','','卷25','七十欠四岁，此生那足论。
每因悲物故，还且喜身存。
安得头长黑，争教眼不昏。
交游成拱木，婢仆见曾孙。
瘦觉腰金重，衰怜鬓雪繁。
将何理老病，应付与空门。','',''),('quantangshi-24366','池上早春即事招梦得','白居易','quantangshi','','卷25','老更惊年改，闲先觉日长。
晴熏榆荚黑，春染柳梢黄。
云破山呈色，冰融水放光。
低平稳船舫，轻暖好衣裳。
白角三升榼，红茵六尺牀。
偶游难得伴，独醉不成狂。
我有中心乐，君无外事忙。
经过莫慵嬾，相去两三坊。','',''),('quantangshi-24367','因梦得题公垂所寄蜡烛因寄公垂','白居易','quantangshi','','卷25','照梁初日光相似，出水新莲艳不如。
却寄两条君令取，明年双引入中书。','',''),('quantangshi-24368','令公南庄花柳正盛欲偷一赏先寄二篇 一','白居易','quantangshi','','卷25','最忆楼花千万朵，偏怜堤柳两三株。
拟提社酒携村妓，擅入朱门莫怪无。','',''),('quantangshi-24369','令公南庄花柳正盛欲偷一赏先寄二篇 二','白居易','quantangshi','','卷25','可惜亭台闲度日，欲偷风景暂游春。
只愁花里莺饶舌，飞入宫城报主人。','',''),('quantangshi-24370','春夜宴席上戏赠裴淄川','白居易','quantangshi','','卷25','九十不衰真地仙，六旬犹健亦天怜。
今年相遇莺花月，此夜同欢歌酒筵。
四座齐声和丝竹，两家随分鬬金钿。
留君到晓无他意，图向君前作少年。','',''),('quantangshi-24371','赠梦得','白居易','quantangshi','','卷25','年颜老少与君同，眼未全昏耳未聋。
放醉卧为春日伴，趂欢行入少年丛。
寻花借马烦川守，弄水偷船恼令公。
闻道洛城人尽怪，呼为刘白二狂翁。','',''),('quantangshi-24372','晚春欲携酒寻沈四着作先以六韵寄之','白居易','quantangshi','','卷25','病容衰惨澹，芳景晚蹉跎。
无计留春得，争能奈老何。
篇章慵报答，杯宴喜经过。
顾我酒狂久，负君诗债多。
敢辞携绿蚁，只愿见青娥。
最忆阳关唱，真珠一串歌。','',''),('quantangshi-24373','三月三日祓禊洛滨','白居易','quantangshi','','卷25','三月草萋萋，黄莺歇又啼。
柳桥晴有絮，沙路润无泥。
禊事修初半，游人到欲齐。
金钿耀桃李，丝管骇凫鹥。
转岸回船尾，临流簇马蹄。
闹翻扬子渡，蹋破魏王堤。
妓接谢公宴，诗陪荀令题。
舟同李膺泛，醴为穆生携。
水引春心荡，花牵醉眼迷。
尘街从鼓动，烟树任鸦栖。
舞急红腰软，歌迟翠黛低。
夜归何用烛，新月凤楼西。','',''),('quantangshi-24374','同梦得暮春寄贺东西川二杨尚书','白居易','quantangshi','','卷25','龙节对持真可爱，雁行相接更堪夸。
两川风景同三月，千里江山属一家。
鲁卫定知连气色，潘杨亦觉有光华。
应怜洛下分司伴，冷宴闲游老看花。','',''),('quantangshi-24375','喜小楼西新柳抽条','白居易','quantangshi','','卷25','一行弱柳前年种，数尺柔条今日新。
渐欲拂他骑马客，未多遮得上楼人。
须教碧玉羞眉黛，莫与红桃作麴尘。
为报金堤千万树，饶伊未敢苦争春。','',''),('quantangshi-24376','晚春酒醒寻梦得','白居易','quantangshi','','卷25','料合同惆怅，花残酒亦残。
醉心忘老易，醒眼别春难。
独出虽慵嬾，相逢定喜欢。
还携小蛮去，试觅老刘看。','',''),('quantangshi-24377','感事','白居易','quantangshi','','卷25','服气崔常侍，烧丹郑舍人。
常期生羽翼，那忽化灰尘。
每遇凄凉事，还思潦倒身。
唯知趂杯酒，不解炼金银。
睡适三尸性，慵安五藏神。
无忧亦无喜，六十六年春。','',''),('quantangshi-24378','和裴令公南庄绝句','白居易','quantangshi','','卷25','陶庐僻陋那堪比，谢墅幽微不足攀。
何似嵩峰三十六，长随申甫作家山。','',''),('quantangshi-24379','宅西有流水墙下构小楼临玩之时颇有幽趣因命歌酒聊以自娱独醉独吟偶题五绝句 一','白居易','quantangshi','','卷25','伊水分来不自由，无人解爱为谁流。
家家抛向墙根底，唯我栽莲越小楼。','',''),('quantangshi-24380','宅西有流水墙下构小楼临玩之时颇有幽趣因命歌酒聊以自娱独醉独吟偶题五绝句 二','白居易','quantangshi','','卷25','水色波文何所似，麴尘罗带一条斜。
莫言罗带春无主，自置楼来属白家。','',''),('quantangshi-24381','宅西有流水墙下构小楼临玩之时颇有幽趣因命歌酒聊以自娱独醉独吟偶题五绝句 三','白居易','quantangshi','','卷25','日滟水光摇素壁，风飘树影拂朱栏。
皆言此处宜弦管，试奏霓裳一曲看。','',''),('quantangshi-24382','宅西有流水墙下构小楼临玩之时颇有幽趣因命歌酒聊以自娱独醉独吟偶题五绝句 四','白居易','quantangshi','','卷25','霓裳奏罢唱梁州，红袖斜翻翠黛愁。
应是遥闻胜近听，行人欲过尽回头。','',''),('quantangshi-24383','宅西有流水墙下构小楼临玩之时颇有幽趣因命歌酒聊以自娱独醉独吟偶题五绝句 五','白居易','quantangshi','','卷25','独醉还须得歌舞，自娱何必要亲宾。
当时一部清商乐，亦不长将乐外人。','',''),('quantangshi-24384','偶作','白居易','quantangshi','','卷25','篮舁出即忘归舍，柴户昏犹未掩关。
闻客病时慙体健，见人忙处觉心闲。
清凉秋寺行香去，和暖春城拜表还。
木雁一篇须记取，致身才与不才间。','',''),('quantangshi-24385','因梦得酬牛相公初到洛中小饮见赠','白居易','quantangshi','','卷25','淮南挥手抛红斾，洛下回头向白云。
政事堂中老丞相，制科场里旧将军。
宫城烟月饶全占，关塞风光请半分。
诗酒放狂犹得在，莫欺白叟与刘君。','',''),('quantangshi-24386','幽居早秋闲咏','白居易','quantangshi','','卷25','幽僻嚣尘外，清凉水木间。
卧风秋拂簟，步月夜开关。
且得身安泰，从他世险艰。
但休争要路，不必入深山。
轩鹤留何用，泉鱼放不还。
谁人知此味，临老十年闲。','',''),('quantangshi-24387','和令狐仆射小饮听阮咸','白居易','quantangshi','','卷25','掩抑复凄清，非琴不是筝。
还弹乐府曲，别占阮家名。
古调何人识，初闻满座惊。
落盘珠历历，摇佩玉琤琤。
似劝杯中物，如含林下情。
时移音律改，岂是昔时声。','',''),('quantangshi-24388','烧药不成命酒独醉','白居易','quantangshi','','卷25','白发逢秋王，丹砂见火空。
不能留姹女，争免作衰翁。
赖有杯中绿，能为面上红。
少年心不远，只在半酣中。','',''),('quantangshi-24389','送卢郎中赴河东裴令公幕','白居易','quantangshi','','卷25','别时暮雨洛桥岸，到日凉风汾水波。
荀令见君应问我，为言秋草闭门多。','',''),('quantangshi-24390','送李滁州','白居易','quantangshi','','卷25','君于觉路深留意，我亦禅门薄致功。
未悟病时须去病，已知空后莫依空。
白衣卧病嵩山下，皂盖行春楚水东。
谁道三年千里别，两心同在道场中。','',''),('quantangshi-24391','长斋月满寄思黯','白居易','quantangshi','','卷25','一日不见如三月，一月相思如七年。
似隔山河千里地，仍当风雨九秋天。
明朝斋满相寻去，挈榼抱衾同醉眠。','',''),('quantangshi-24392','冬夜对酒寄皇甫十','白居易','quantangshi','','卷25','霜杀中庭草，冰生后院池。
有风空动树，无叶可辞枝。
十月苦长夜，百年强半时。
新开一瓶酒，那得不相思。','',''),('quantangshi-24393','岁除夜对酒','白居易','quantangshi','','卷25','衰翁岁除夜，对酒思悠然。
草白经霜地，云黄欲雪天。
醉依香枕坐，慵傍暖炉眠。
洛下闲来久，明朝是十年。','',''),('quantangshi-24394','寄献北都留守裴令公','白居易','quantangshi','','卷25','天上中台正，人间一品高。
休明值尧舜，勋业过萧曹。
始擅文三捷，终兼武六韬。
动人名赫赫，忧国意忉忉。
荡蔡擒封豕，平齐斩巨鳌。
两河收土宇，四海定波涛。
宠重移宫龠，恩新换阃旄。
保厘东宅静，守护北门牢。
晋国封疆阔，并州士马豪。
胡兵惊赤帜，边雁避乌号。
令下流如水，仁霑泽似膏。
路喧歌五袴，军醉感单醪。
将校森貔武，宾僚俨隽髦。
客无烦夜柝，吏不犯秋毫。
神在台骀助，魂亡猃狁逃。
德星销彗孛，霖雨灭腥臊。
烽戍高临代，关河远控洮。
汾云晴漠漠，朔吹冷颾颾。
豹尾交牙戟，蚪须捧佩刀。
通天白犀带，照地紫麟袍。
羌管吹杨柳，燕姬酌蒲萄。
银含凿落盏，金屑琵琶槽。
遥想从军乐，应忘报国劳。
紫微留北阙，绿野寄东臯。
忽忆前时会，多慙下客叨。
清宵陪宴话，美景从游遨。
花月还同赏，琴诗雅自操。
朱弦拂宫征，洪笔振风骚。
近竹开方丈，依林架桔槔。
春池八九曲，画舫两三艘。
径滑苔黏屐，潭深水没篙。
绿丝萦岸柳，红粉映楼桃。
为穆先陈醴，招刘共藉糟。
舞鬟金翡翠，歌颈玉蛴螬。
盛德终难过，明时岂易遭。
公虽慕张范，帝未舍伊臯。
眷恋心方结，踟蹰首已搔。
鸾皇上寥廓，燕雀任蓬蒿。
欲献文狂简，徒烦思郁陶。
可怜四百字，轻重抵鸿毛。','',''),('quantangshi-24395','和东川杨慕巢尚书府中独坐感戚在怀见寄十四韵','白居易','quantangshi','','卷25','我是知君者，君今意若何。
穷通时不定，苦乐事相和。
东蜀欢殊渥，西江叹逝波。
只缘荣贵极，翻使感伤多。
行断风惊雁，年侵日下坡。
片心休惨戚，双鬓已蹉跎。
紫绶黄金印，青幢白玉珂。
老将荣补贴，愁用道销磨。
外府饶杯酒，中堂有绮罗。
应须引满饮，何不放狂歌？
锦水通巴峡，香山对洛河。
将军驰铁马，少傅步铜驼。
深契怜松竹，高情忆薜萝。
悬车年甚远，未敢故相过。','',''),('quantangshi-24396','分司洛中多暇数与诸客宴游醉后狂吟偶成十韵因招梦得宾客兼呈思黯奇章公','白居易','quantangshi','','卷25','性与时相远，身将世两忘。
寄名朝士籍，寓兴少年场。
老岂无谈笑，贫犹有酒浆。
随时来伴侣，逐日用风光。
数数游何爽，些些病未妨。
天教荣启乐，人恕接舆狂。
改业为逋客，移家住醉乡。
不论招梦得，兼拟诱奇章。
要路风波险，权门市井忙。
世间无可恋，不是不思量。','',''),('quantangshi-24397','小岁日喜谈氏外孙女孩满月','白居易','quantangshi','','卷25','今旦夫妻喜，他人岂得知。
自嗟生女晚，敢讶见孙迟。
物以稀为贵，情因老更慈。
新年逢吉日，满月乞名时。
桂燎熏花果，兰汤洗玉肌。
怀中有可抱，何必是男儿。','',''),('quantangshi-24398','闲吟赠皇甫郎中亲家翁','白居易','quantangshi','','卷25','谁能嗟叹光阴暮，岂复忧愁活计贫。
忽忽不知头上事，时时犹忆眼中人。
早为良友非交势，晚接嘉姻不失亲。
最喜两家婚嫁毕，一时抽得尚平身。','',''),('quantangshi-24399','梦得卧病携酒相寻先以此寄','白居易','quantangshi','','卷25','病来知少客，谁可以为娱。
日晏开门未，秋寒有酒无。
自宜相慰问，何必待招呼。
小疾无妨饮，还须挈一壶。','',''),('quantangshi-24400','酬思黯戏赠同用狂字','白居易','quantangshi','','卷25','钟乳三千两，金钗十二行。
妬他心似火，欺我鬓如霜。
慰老资歌笑，销愁仰酒浆。
眼看狂不得，狂得且须狂。','',''),('quantangshi-24401','又戏答绝句','白居易','quantangshi','','卷25','狂夫与我两相忘，故态些些亦不妨。
纵酒放歌聊自乐，接舆争解教人狂。','',''),('quantangshi-24402','令狐相公与梦得交情素深眷予分亦不浅一闻薨逝相顾泫然旋有使来得前月未殁之前数日书及诗寄赠梦得哀吟悲叹寄情于诗诗成示予感而继和','白居易','quantangshi','','卷25','缄题重叠语殷勤，存没交亲自此分。
前月使来犹理命，今朝诗到是遗文。
银钩见晚书无报，玉树埋深哭不闻。
最感一行绝笔字，尚言千万乐天君。','',''),('quantangshi-24403','洛下雪中频与刘李二宾客宴集因寄汴州李尚书','白居易','quantangshi','','卷25','水南水北雪纷纷，雪里欢游莫厌频。
日日暗来唯老病，年年少去是交亲。
碧毡帐暖梅花湿，红燎炉香竹叶春。
今日邹枚俱在洛，梁园置酒召何人。','',''),('quantangshi-24404','看梦得题答李侍郎诗诗中有文星之句因戏和之','白居易','quantangshi','','卷25','看题锦绣报琼瓌，俱是人天第一才。
好遣文星守躔次，亦须防有客星来。','',''),('quantangshi-24405','闲适','白居易','quantangshi','','卷25','禄俸优饶官不卑，就中闲适是分司。
风光暖助游行处，雨雪寒供饮宴时。
肥马轻裘还且有，麤歌薄酒亦相随。
微躬所要今皆得，只是蹉跎得校迟。','',''),('quantangshi-24406','戏答思黯','白居易','quantangshi','','卷25','何时得见十三弦，待取无云有月天。
愿得金波明似镜，镜中照出月中仙。','',''),('quantangshi-24407','酬裴令公赠马相戏','白居易','quantangshi','','卷25','安石风流无奈何，欲将赤骥换青娥。
不辞便送东山去，临老何人与唱歌。','',''),('quantangshi-24408','新岁赠梦得','白居易','quantangshi','','卷25','暮齿忽将及，同心私自怜。
渐衰宜减食，已喜更加年。
紫绶行联袂，篮轝出比肩。
与君同甲子，岁酒合谁先。','',''),('quantangshi-24409','早春持斋答皇甫十见赠','白居易','quantangshi','','卷25','正月晴和风气新，纷纷已有醉游人。
帝城花笑长斋客，三十年来负早春。','',''),('quantangshi-24410','戏赠梦得兼呈思黯','白居易','quantangshi','','卷25','霜鬓莫欺今老矣，一杯莫笑便陶然。
陈郎中处为高户，裴使君前作少年。
顾我独狂多自哂，与君同病最相怜。
月终斋满谁开素，须拟奇章置一筵。','',''),('quantangshi-24411','早春忆游思黯南庄因寄长句','白居易','quantangshi','','卷25','南庄胜处心常忆，借问轩车早晚游。
美景难忘竹廊下，好风争奈柳桥头。
冰消见水多于地，雪霁看山尽入楼。
若待春深始同赏，莺残花落却堪愁。','',''),('quantangshi-24412','酬皇甫十早春对雪见赠','白居易','quantangshi','','卷25','漠漠复雰雰，东风散玉尘。
明催竹窗晓，寒退柳园春。
绿酝香堪忆，红炉暖可亲。
忍心三两日，莫作破斋人。','',''),('quantangshi-24413','奉和思黯自题南庄见示兼呈梦得','白居易','quantangshi','','卷25','谢家别墅最新奇，山展屏风花夹篱。
晓月渐沈桥脚底，晨光初照屋梁时。
台头有酒莺呼客，水面无尘风洗池。
除却吟诗两闲客，此中情状更谁知。','',''),('quantangshi-24414','送蕲春李十九使君赴郡','白居易','quantangshi','','卷25','可怜官职好文词，五十专城未是迟。
晓日镜前无白发，春风门外有红旗。
郡中何处堪携酒，席上谁人解和诗。
唯共交亲开口笑，知君不及洛阳时。','',''),('quantangshi-24415','自题酒库','白居易','quantangshi','','卷25','野鹤一辞笼，虚舟长任风。
送愁还闹处，移老入闲中。
身更求何事，天将富此翁。
此翁何处富，酒库不曾空。','',''),('quantangshi-24416','寒食日寄杨东川','白居易','quantangshi','','卷25','不知杨六逢寒食，作底欢娱过此辰。
兜率寺高宜望月，嘉陵江近好游春。
蛮旗似火行随马，蜀妓如花坐遶身。
不使黔娄夫妇看，夸张富贵向何人。','',''),('quantangshi-24417','醉后听唱桂华曲','白居易','quantangshi','','卷25','桂华词意苦丁宁，唱到常娥醉便醒。
此是人间肠断曲，莫教不得意人听。','',''),('quantangshi-24418','酬梦得以予五月长斋延僧徒绝宾友见戏十韵','白居易','quantangshi','','卷25','宾客懒逢迎，翛然池馆清。
檐闲空燕语，林静未蝉鸣。
荤血还休食，杯觞亦罢倾。
三春多放逸，五月暂修行。
香印朝烟细，纱灯夕焰明。
交游诸长老，师事古先生。
禅后心弥寂，斋来体更轻。
不唯忘肉味，兼拟灭风情。
蒙以声闻待，难将戏论争。
虚空若有佛，灵运恐先成。','',''),('quantangshi-24419','奉和裴令公三月上巳日游太原龙泉忆去岁禊洛见示之作','白居易','quantangshi','','卷25','去岁暮春上巳，共泛洛水中流。
今岁暮春上巳，独立香山下头。
风光闲寂寂，旌斾远悠悠。
丞相府归晋国，太行山碍并州。
鹏背负天龟曳尾，云泥不可得同游。','',''),('quantangshi-24420','又和令公新开龙泉晋水二池','白居易','quantangshi','','卷25','旧有潢汚泊，今为白水塘。
笙歌闻四面，楼阁在中央。
春变烟波色，晴添树木光。
龙泉信为美，莫忘午桥庄。','',''),('quantangshi-24421','早夏晓兴赠梦得','白居易','quantangshi','','卷25','窗明帘薄透朝光，卧整巾簪起下牀。
背壁灯残经宿焰，开箱衣带隔年香。
无情亦任他春去，不醉争销得昼长。
一部清商一壶酒，与君明日暖新堂。','',''),('quantangshi-24422','春日题干元寺上方最高峰亭','白居易','quantangshi','','卷25','危亭绝顶四无邻，见尽三千世界春。
但觉虚空无障碍，不知高下几由旬。
回看官路三条线，却望都城一片尘。
宾客暂游无半日，王侯不到便终身。
始知天造空闲境，不为忙人富贵人。','',''),('quantangshi-24423','奉和思黯相公以李苏州所寄太湖石奇状绝伦因题二十韵见示兼呈梦得','白居易','quantangshi','','卷25','错落复崔嵬，苍然玉一堆。
峰骈仙掌出，罅坼劒门开。
峭顶高危矣，盘根下壮哉。
精神欺竹树，气色压亭台。
隐起磷磷状，凝成瑟瑟胚。
廉棱露锋刃，清越扣琼瑰。
岌嶪形将动，巍峩势欲摧。
奇应潜鬼怪，灵合蓄云雷。
黛润霑新雨，斑明点古苔。
未曾栖鸟雀，不肯染尘埃。
尖削琅玕笋，洼剜玛瑙罍。
海神移碣石，画障簇天台。
在世为尤物，如人负逸才。
渡江一苇载，入洛五丁推。
出处虽无意，升沈亦有媒。
拔从水府底，置向相庭隈。
对称吟诗句，看宜把酒杯。
终随金砺用，不学玉山颓。
疎傅心偏爱，园公眼屡回。
共嗟无此分，虚管太湖来。','',''),('quantangshi-24424','奉和思黯相公雨后林园四韵见示','白居易','quantangshi','','卷25','新晴夏景好，复此池边地。
烟树绿含滋，水风清有味。
便成林下隐，都忘门前事。
骑吏引归轩，始知身富贵。','',''),('quantangshi-24425','晚夏闲居绝无宾客欲寻梦得先寄此诗','白居易','quantangshi','','卷25','鱼笋朝餐饱，蕉纱暑服轻。
欲为窗下寝，先傍水边行。
晴引鹤双舞，秋生蝉一声。
无人解相访，有酒共谁倾。
老更谙时事，闲多见物情。
只应刘与白，二叟自相迎。','',''),('quantangshi-24426','寄李蕲州','白居易','quantangshi','','卷25','下车书奏龚黄课，动笔诗传鲍谢风。
江郡讴谣夸杜母，洛城欢会忆车公。
笛愁春尽梅花里，簟冷秋生薤叶中。
不道蕲州歌酒少，使君难称与谁同。','',''),('quantangshi-24427','酬思黯相公晚夏雨后感秋见赠','白居易','quantangshi','','卷25','暮去朝来无歇期，炎凉暗向雨中移。
夜长祗合愁人觉，秋冷先应瘦客知。
两幅彩笺挥逸翰，一声寒玉振清辞。
无忧无病身荣贵，何故沈吟亦感时。','',''),('quantangshi-24428','久雨闲闷对酒偶吟','白居易','quantangshi','','卷25','凄凄苦雨暗铜駞，袅袅凉风起漕河。
自夏及秋晴日少，从朝至暮闷时多。
鹭临池立窥鱼笱，隼傍林飞拂雀罗。
赖有杯中神圣物，百忧无奈十分何。','',''),('quantangshi-24429','雨后秋凉','白居易','quantangshi','','卷25','夜来秋雨后，秋气飒然新。
团扇先辞手，生衣不着身。
更添砧引思，难与簟相亲。
此境谁偏觉，贫闲老瘦人。','',''),('quantangshi-24430','酬梦得早秋夜对月见寄','白居易','quantangshi','','卷25','吾衰寡情趣，君病懒经过。
其奈西楼上，新秋明月何。
庭芜凄白露，池色澹金波。
况是初长夜，东城砧杵多。','',''),('quantangshi-24431','题谢公东山障子','白居易','quantangshi','','卷25','贤愚共在浮生内，贵贱同趋羣动间。
多见忙时已衰病，少闻健日肯休闲。
鹰饥受緤从难退，鹤老乘轩亦不还。
唯有风流谢安石，拂衣携妓入东山。','',''),('quantangshi-24432','谢杨东川寄衣服','白居易','quantangshi','','卷25','年年衰老交游少，处处萧条书信稀。
唯有巢兄不相忘，春茶未断寄秋衣。','',''),('quantangshi-24433','咏怀寄皇甫朗之','白居易','quantangshi','','卷25','老大多情足往还，招僧待客夜开关。
学调气后衰中健，不用心来闹处闲。
养病未能辞薄俸，忘名何必入深山。
与君别有相知分，同置身于木雁间。','',''),('quantangshi-24434','东城晚归','白居易','quantangshi','','卷25','一条邛杖悬龟榼，双角吴童控马衔。
晚入东城谁识我，短靴低帽白蕉衫。','',''),('quantangshi-24435','与梦得沽酒闲饮且约后期','白居易','quantangshi','','卷25','少时犹不忧生计，老后谁能惜酒钱。
共把十千沽一斗，相看七十欠三年。
闲征雅令穷经史，醉听清吟胜管弦。
更待菊黄家酝熟，共君一醉一陶然。','',''),('quantangshi-24436','与牛家妓乐雨后合宴','白居易','quantangshi','','卷25','玉管清弦声旖旎，翠钗红袖坐参差。
两家合奏洞房夜，八月连阴秋雨时。
歌脸有情凝睇久，舞腰无力转帬迟。
人间欢乐无过此，上界西方即不知。','',''),('quantangshi-24437','和杨六尚书喜两弟汉公转吴兴鲁士赐章服命宾开宴用庆恩荣赋长句见示','白居易','quantangshi','','卷25','华筵贺客日纷纷，劒外欢娱洛下闻。
朱绂宠光新照地，彤襜喜气远凌云。
荣联花萼诗难和，乐助埙箎酒易[醺]。
感羡料应知我意，今生此事不如君。','',''),('quantangshi-24438','自咏','白居易','quantangshi','','卷25','须白面微红，醺醺半醉中。
百年随手过，万事转头空。
卧疾瘦居士，行歌狂老翁。
仍闻好事者，将我画屏风。','',''),('quantangshi-24439','梦得相过援琴命酒因弹秋思偶咏所怀兼寄继之待价二相府','白居易','quantangshi','','卷25','闲居静侣偶相招，小饮初酣琴欲调。
我正风前弄秋思，君应天上听云韶。
时和始见陶钧力，物遂方知盛圣朝。
双凤栖梧鱼在藻，飞沈随分各逍遥。','',''),('quantangshi-24440','九月八日酬皇甫十见赠','白居易','quantangshi','','卷25','君方对酒缀诗章，我正持斋坐道场。
处处追游虽不去，时时吟咏亦无妨。
霜蓬旧鬓三分白，露菊新花一半黄。
惆怅东篱不同醉，陶家明日是重阳。','',''),('quantangshi-24441','慕巢尚书书云室人欲为置一歌者非所安也以诗相报因而和之','白居易','quantangshi','','卷25','东川已过二三春，南国须求一两人。
富贵大都多老大，欢娱太半为亲宾。
如愁翠黛应堪重，买笑黄金莫诉贫。
他日相逢一杯酒，尊前还要落梁尘。','',''),('quantangshi-24442','杪秋独夜','白居易','quantangshi','','卷25','无限少年非我伴，可怜清夜与谁同。
欢娱牢落中心少，亲故凋零四面空。
红叶树飘风起后，白须人立月明中。
前头更有萧条物，老菊衰兰三两丛。','',''),('quantangshi-24443','凭李睦州访徐凝山人','白居易','quantangshi','','卷25','郡守轻诗客，乡人薄钓翁。
解怜徐处士，唯有李郎中。','',''),('quantangshi-24444','苏州故吏','白居易','quantangshi','','卷25','江南故吏别来久，今日池边识我无。
不独使君头似雪，华亭鹤死白莲枯。','',''),('quantangshi-24445','得杨湖州书颇夸抚民接宾纵酒题诗因以绝句戏之','白居易','quantangshi','','卷25','岂独爱民兼爱客，不唯能饮又能文。
白苹洲上春传语，柳使君输杨使君。','',''),('quantangshi-24446','天宫阁秋晴晚望','白居易','quantangshi','','卷25','洛城秋霁后，梵阁暮登时。
此日风烟好，今秋节候迟。
霞光红泛艳，树影碧参差。
莫虑言归晚，牛家有宿期。','',''),('quantangshi-24447','酬梦得暮秋晴夜对月相忆','白居易','quantangshi','','卷25','霁月光如练，盈庭复满池。
秋深无热后，夜浅未寒时。
露叶团荒菊，风枝落病棃。
相思懒相访，应是各年衰。','',''),('quantangshi-24448','同梦得和思黯见赠来诗中先叙三人同宴之欢次有叹鬓发渐衰嫌孙子催老之意因酬妍唱兼吟鄙怀','白居易','quantangshi','','卷25','醉伴腾腾白与刘，何朝何夕不同游。
留连灯下明犹饮，断送尊前倒即休。
催老莫嫌孙稚长，加年须喜鬓毛秋。
教他伯道争存活，无子无孙亦白头。','',''),('quantangshi-24449','听歌','白居易','quantangshi','','卷25','管妙弦清歌入云，老人合眼醉醺醺。
诚知不及当年听，犹觉闻时胜不闻。','',''),('quantangshi-24450','三年冬随事铺设小堂寝处稍似稳暖因念衰病偶吟所怀','白居易','quantangshi','','卷25','小宅非全陋，中堂不甚卑。
聊堪会亲族，足以贮妻儿。
暖帐迎冬设，温炉向夜施。
裘新青兔褐，褥软白猨皮。
似鹿眠深草，如鸡宿稳枝。
逐身安枕席，随事有屏帷。
病致衰残早，贫营活计迟。
由来蚕老后，方是茧成时。','',''),('quantangshi-24451','初冬即事呈梦得','白居易','quantangshi','','卷25','青毡帐暖喜微雪，红地炉深宜早寒。
走笔小诗能和否，泼醅新酒试尝看。
僧来乞食因留宿，客到开尊便共欢。
临老交亲零落尽，希君恕我取人宽。','',''),('quantangshi-24452','自罢河南已换七尹每一入府怅然旧游因宿内厅偶题西壁兼呈韦尹常侍','白居易','quantangshi','','卷25','每入河南府，依然似到家。
杯尝七尹酒，树看十年花。
且健须欢喜，虽衰莫叹嗟。
迎门无故吏，侍坐有新娃。
暖阁谋宵宴，寒庭放晚衙。
主人留宿定，一任夕阳斜。','',''),('quantangshi-24453','天寒晚起引酌咏怀寄许州王尚书汝州李常侍','白居易','quantangshi','','卷25','叶覆冰池雪满山，日高慵起未开关。
寒来更亦无过醉，老后何由可得闲。
四海故交唯许汝，十年贫健是樊蛮。
相思莫忘樱桃会，一放狂歌一破颜。','',''),('quantangshi-24454','四年春','白居易','quantangshi','','卷25','柳梢黄嫩草芽新，又入开成第四春。
近日放慵多不出，少年嫌老可相亲。
分司吉傅频过舍，致仕崔卿拟卜邻。
时辈推迁年事到，往还多是白头人。','',''),('quantangshi-24455','白发','白居易','quantangshi','','卷25','白发生来三十年，而今须鬓尽皤然。
歌吟终日如狂叟，衰疾多时似瘦仙。
八戒夜持香火印，三光朝念蘂珠篇。
其余便被春收拾，不作闲游即醉眠。','',''),('quantangshi-24456','追欢偶作','白居易','quantangshi','','卷25','追欢逐乐少闲时，补贴平生得事迟。
何处花开曾后看，谁家酒熟不先知。
石楼月下吹芦管，金谷风前舞柳枝。
十听春啼变莺舌，三嫌老丑换蛾眉。
乐天一过难知分，犹自咨嗟两鬓丝。','',''),('quantangshi-24457','公垂尚书以白马见寄光洁稳善以诗谢之','白居易','quantangshi','','卷25','翩翩白马称金羁，领缀银花尾曳丝。
毛色鲜明人尽爱，性灵驯善主偏知。
免将妾换慙来处，试使奴牵欲上时。
不蹶不惊行步稳，最宜山简醉中骑。','',''),('quantangshi-24458','西楼独立','白居易','quantangshi','','卷25','身着白衣头似雪，时时醉立小楼中。
路人回顾应相怪，十一年来见此翁。','',''),('quantangshi-24459','书事咏怀','白居易','quantangshi','','卷25','官俸将生计，虽贫岂敢嫌。
金多输陆贾，酒足胜陶潜。
牀暖僧敷坐，楼晴妓卷帘。
日遭斋破用，春赖闰加添。
老向欢弥切，狂于饮不廉。
十年闲未足，亦恐涉无厌。','',''),('quantangshi-24460','酬梦得比萱草见赠','白居易','quantangshi','','卷25','杜康能散闷，萱草解忘忧。
借问萱逢杜，何如白见刘。
老衰胜少夭，闲乐笑忙愁。
试问同年内，何人得白头。','',''),('quantangshi-24461','问皇甫十','白居易','quantangshi','','卷25','苦乐心由我，穷通命任他。
坐倾张翰酒，行唱接舆歌。
荣盛傍看好，优闲自适多。
知君能断事，胜负两如何。','',''),('quantangshi-24462','早春独登天宫阁','白居易','quantangshi','','卷25','天宫日暖阁门开，独上迎春饮一杯。
无限游人遥怪我，缘何最老最先来。','',''),('quantangshi-24463','送苏州李使君赴郡二绝句 一','白居易','quantangshi','','卷25','忆抛印绶辞吴郡，衰病当时已有余。
今日贺君兼自喜，八回看换旧铜鱼。','',''),('quantangshi-24464','送苏州李使君赴郡二绝句 二','白居易','quantangshi','','卷25','馆娃宫深春日长，乌鹊桥高秋夜凉。
风月不知人世变，奉君直似奉吴王。','',''),('quantangshi-24465','长洲曲新词','白居易','quantangshi','','卷25','茂苑绮罗佳丽地，女湖桃李艳阳时。
心奴已死胡容老，后辈风流是阿谁。','',''),('quantangshi-24466','忆江南词三首 一','白居易','quantangshi','','卷25','江南好，风景旧曾谙。','',''),('quantangshi-24467','忆江南词三首 二','白居易','quantangshi','','卷25','江南忆，最忆是杭州。','',''),('quantangshi-24468','忆江南词三首 三','白居易','quantangshi','','卷25','江南忆，其次忆吴宫。','',''),('quantangshi-24469','病中诗十五首 初病风','白居易','quantangshi','','卷25','六十八衰翁，乘衰百疾攻。
朽株难免蠹，空穴易来风。
肘痹宜生柳，头旋剧转蓬。
恬然不动处，虚白在胷中。','',''),('quantangshi-24470','病中诗十五首 枕上作','白居易','quantangshi','','卷25','风疾侵凌临老头，血凝筋滞不调柔。
甘从此后支离卧，赖是从前烂漫游。
回思往事纷如梦，转觉余生杳若浮。
浩气自能充静室，惊飙何必荡虚舟。
腹空先进松花酒，膝冷重装桂布裘。
若问乐天忧病否，乐天知命了无忧。','',''),('quantangshi-24471','病中诗十五首 答闲上人来问因何风疾','白居易','quantangshi','','卷25','一牀方丈向阳开，劳动文殊问疾来。
欲界凡夫何足道，四禅天始免风灾。','',''),('quantangshi-24472','病中诗十五首 病中五绝句 一','白居易','quantangshi','','卷25','世间生老病相随，此事心中久自知。
今日行年将七十，犹须慙愧病来迟。','',''),('quantangshi-24473','病中诗十五首 病中五绝句 二','白居易','quantangshi','','卷25','方寸成灰鬓作丝，假如强健亦何为。
家无忧累身无事，正是安闲好病时。','',''),('quantangshi-24474','病中诗十五首 病中五绝句 三','白居易','quantangshi','','卷25','李君墓上松应拱，元相池头竹尽枯。
多幸乐天今始病，不知合要苦治无。','',''),('quantangshi-24475','病中诗十五首 病中五绝句 四','白居易','quantangshi','','卷25','目昏思寝即安眠，足软妨行便坐禅。
身作医王心是药，不劳和扁到门前。','',''),('quantangshi-24476','病中诗十五首 病中五绝句 五','白居易','quantangshi','','卷25','交亲不要苦相忧，亦拟时时强出游。
但有心情何用脚，陆乘肩轝水乘舟。','',''),('quantangshi-24477','病中诗十五首 送嵩客','白居易','quantangshi','','卷25','登山临水分无期，泉石烟霞今属谁。
君到嵩阳吟此句，与教二十六峰知。','',''),('quantangshi-24478','病中诗十五首 罢[灸]','白居易','quantangshi','','卷25','病身佛说将何喻，变灭须臾岂不闻。
莫遣净名知我笑，休将火艾[灸]浮云。','',''),('quantangshi-24479','病中诗十五首 卖骆马','白居易','quantangshi','','卷25','五年花下醉骑行，临卖回头嘶一声。
项籍顾骓犹解叹，乐天别骆岂无情。','',''),('quantangshi-24480','病中诗十五首 别柳枝','白居易','quantangshi','','卷25','两枝杨柳小楼中，袅袅多年伴醉翁。
明日放归归去后，世间应不要春风。','',''),('quantangshi-24481','病中诗十五首 就暖偶酌戏诸诗酒旧侣','白居易','quantangshi','','卷25','低屏软褥卧藤牀，舁向前轩就日阳。
一足任他为外物，三杯自要沃中肠。
头风若见诗应愈，齿折仍夸笑不妨。
细酌徐吟犹得在，旧游未必便相忘。','',''),('quantangshi-24482','病中诗十五首 岁暮呈思黯相公皇甫朗之及梦得尚书','白居易','quantangshi','','卷25','岁暮皤然一老夫，十分流辈九分无。
莫嫌身病人扶侍，犹胜无身可遣扶。','',''),('quantangshi-24483','病中诗十五首 自解','白居易','quantangshi','','卷25','房传往世为禅客王道前生应画师。
我亦定中观宿命，多生债负是歌诗。
不然何故狂吟咏，病后多于未病时。','',''),('quantangshi-24484','岁暮病怀赠梦得','白居易','quantangshi','','卷25','十年四海故交亲，零落唯残两病身。
共遣数奇从是命，同教步蹇有何因。
眼随老减嫌长夜，体待阳舒望早春。
新乐堂前旧池上，相过亦不要他人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24485','雪后过集贤裴令公旧宅有感','白居易','quantangshi','','卷25','梁王捐馆后，枚叟过门时。
有泪人还泣，无情雪不知。
台亭留尽在，宾客散何之。
唯有萧条雁，时来下故池。','',''),('quantangshi-24486','酬梦得贫居咏怀见赠','白居易','quantangshi','','卷25','岁阴生计两蹉跎，相顾悠悠醉且歌。
厨冷难留乌止屋，门闲可与雀张罗。
病添庄舃吟声苦，贫欠韩康药债多。
日望挥金贺新命，俸钱依旧又如何。','',''),('quantangshi-24487','酬梦得见喜疾瘳','白居易','quantangshi','','卷25','暖卧摩绵褥，晨倾药酒螺。
昏昏布裘底，病醉睡相和。
末疾徒云尔，余年有几何。
须知差与否，相去校无多。','',''),('quantangshi-24488','夜闻筝中弹潇湘送神曲感旧','白居易','quantangshi','','卷25','缥缈巫山女，归来七八年。
殷勤湘水曲，留在十三弦。
苦调吟还出，深情咽不传。
万重云水思，今夜月明前。','',''),('quantangshi-24489','感苏州旧舫','白居易','quantangshi','','卷25','画梁朽折红窗破，独立池边尽日看。
守得苏州船舫烂，此身争合不衰残。','',''),('quantangshi-24490','感旧石上字','白居易','quantangshi','','卷25','闲拨船行寻旧池，幽情往事复谁知。
太湖石上镌三字，十五年前陈结之。','',''),('quantangshi-24491','见敏中初到邠宁秋日登城楼诗诗中颇多乡思因以寄和','白居易','quantangshi','','卷25','想尔到边头，萧条正值秋。
二年贫御史，八月古邠州。
丝管闻虽乐，风沙见亦愁。
望乡心若苦，不用数登楼。','',''),('quantangshi-24492','斋戒','白居易','quantangshi','','卷25','每因斋戒断荤腥，渐觉尘劳染爱轻。
六贼定知无气色，三尸应恨少恩情。
酒魔降伏终须尽，诗债填还亦欲平。
从此始堪为弟子，竺干师是古先生。','',''),('quantangshi-24493','戏礼经老僧','白居易','quantangshi','','卷25','香火一炉灯一盏，白头夜礼佛名经。
何年饮着声闻酒，直到如今醉未醒。','',''),('quantangshi-24494','近见慕巢尚书诗中屡有叹老思退之意又于洛下新置郊居然宠寄方深归心大速因以长句戏而谕之','白居易','quantangshi','','卷25','近见诗中叹白发，遥知阃外忆东都。
烟霞偷眼窥来久，富贵黏身摆得无。
新置林园犹濩落，未终婚嫁且踟蹰。
应须待到悬车岁，然后东归伴老夫。','',''),('quantangshi-24495','对镜偶吟赠张道士抱元','白居易','quantangshi','','卷25','闲来对镜自思量，年貌衰残分所当。
白发万茎何所怪，丹砂一粒不曾尝。
眼昏久被书料理，肺渴多因酒损伤。
今日逢师虽已晚，枕中治老有何方。','',''),('quantangshi-24496','病入新正','白居易','quantangshi','','卷25','枕上惊新岁，花前念旧欢。
是身老所逼，非意病相干。
风月情犹在，杯觞兴渐阑。
便休心未伏，更试一春看。','',''),('quantangshi-24497','卧疾来早晚','白居易','quantangshi','','卷25','卧疾来早晚，悬悬将十旬。
婢能寻本草，犬不吠医人。
酒瓮全生醭，歌筵半委尘。
风光还欲好，争向枕前春。','',''),('quantangshi-24498','强起迎春戏寄思黯','白居易','quantangshi','','卷25','杖策人扶废病身，晴和强起一迎春。
他时蹇跛纵行得，笑杀平原楼上人。','',''),('quantangshi-24499','梦得前所酬篇有炼尽美少年之句因思往事兼咏今怀重以长句答之','白居易','quantangshi','','卷25','炼尽少年成白首，忆初相识到今朝。
昔饶春桂长先折，今伴寒松取后凋。
生事纵贫犹可过，风情虽老未全销。
声华宠命人皆得，若个如君历七朝。','',''),('quantangshi-24500','病后寒食','白居易','quantangshi','','卷25','故纱绛帐旧青毡，药酒醺醺引醉眠。
斗擞弊袍春晚后，摩挲病脚日阳前。
行无筋力寻山水，坐少精神听管弦。
抛掷风光负寒食，曾来未省似今年。','',''),('quantangshi-24501','老病相仍以诗自解','白居易','quantangshi','','卷25','荣枯忧喜与彭殇，都是人间戏一场。
虫臂鼠肝犹不怪，鸡肤鹤发复何伤。
昨因风发甘长往，今遇阳和又小康。
还似远行装束了，迟回且住亦何妨。','',''),('quantangshi-24502','皇甫郎中亲家翁赴任绛州宴送出城赠别','白居易','quantangshi','','卷25','慕贤入室交先定，结援通家好复成。
新妇不嫌贫活计，娇孙同慰老心情。
洛桥歌酒今朝散，绛路风烟几日行。
欲识离羣相恋意，为君扶病出都城。','',''),('quantangshi-24503','春暖','白居易','quantangshi','','卷25','风痹宜和暖，春来脚较轻。
莺留花下立，鹤引水边行。
发少嫌巾重，颜衰讶镜明。
不论亲与故，自亦昧平生。','',''),('quantangshi-24504','残春晚起伴客笑谈','白居易','quantangshi','','卷25','掩户下帘朝睡足，一声黄鸟报残春。
披衣岸帻日高起，两角青衣扶老身。
策杖强行过里巷，引杯闲酌伴亲宾。
莫言病后妨谈笑，犹恐多于不病人。','',''),('quantangshi-24505','送唐州崔使君侍亲赴任','白居易','quantangshi','','卷25','连持使节历专城，独贺崔侯最庆荣。
乌府一抛霜简去，朱轮四从板舆行。
发时止许沙鸥送，到日方乘竹马迎。
唯虑郡斋宾友少，数杯春酒共谁倾。','',''),('quantangshi-24506','春晚咏怀赠皇甫朗之','白居易','quantangshi','','卷25','艳阳时节又蹉跎，迟暮光阴复若何。
一岁平分春日少，百年通计老时多。
多中更被愁牵引，少处兼遭病折磨。
赖有销忧治闷药，君家浓酎我狂歌。','',''),('quantangshi-24507','春尽日宴罢感事独吟','白居易','quantangshi','','卷25','五年三月今朝尽，客散筵空独掩扉。
病共乐天相伴住，春随樊子一时归。
闲听莺语移时立，思逐杨花触处飞。
金带缒腰衫委地，年年衰瘦不胜衣。','',''),('quantangshi-24508','病中辱崔宣城长句见寄兼有觥绮之赠因以四韵总而酬之','白居易','quantangshi','','卷25','刘[桢]病发经春卧，谢朓诗来尽日吟。
三道旧夸收片玉，一章新喜获双金。
信题霞绮缄情重，酒试银觥表分深。
科第门生满霄汉，岁寒少得似君心。','',''),('quantangshi-24509','前有别杨柳枝绝句梦得继和云春尽絮飞留不得随风好去落谁家又复戏答','白居易','quantangshi','','卷25','柳老春深日又斜，任他飞向别人家。
谁能更学孩童戏，寻逐春风捉柳花。','',''),('quantangshi-24510','池上早夏','白居易','quantangshi','','卷25','水积春塘晚，阴交夏木繁。
舟船如野渡，篱落似江村。
静拂琴牀席，香开酒库门。
慵闲无一事，时弄小娇孙。','',''),('quantangshi-24511','谈氏外孙生三日喜是男偶吟成篇兼戏呈梦得','白居易','quantangshi','','卷25','玉芽珠颗小男儿，罗荐兰汤欲罢时。
芣苢春来盈女手，梧桐老去长孙枝。
庆传媒氏燕先贺，喜报谈家乌预知。
明日贫翁具鸡黍，应须酬赛引雏诗。','',''),('quantangshi-24512','开成大行皇帝挽歌词四首奉敕撰进 一','白居易','quantangshi','','卷25','御宇恢皇化，传家叶至公。
华夷臣妾内，尧舜弟兄中。
制度移民俗，文章变国风。
开成与贞观，实录事多同。','',''),('quantangshi-24513','开成大行皇帝挽歌词四首奉敕撰进 二','白居易','quantangshi','','卷25','晏驾辞双阙，灵仪出九衢。
上云归碧落，下席葬苍梧。
蓂晚余尧历，龟新启夏图。
三朝联棣萼，从古帝王无。','',''),('quantangshi-24514','开成大行皇帝挽歌词四首奉敕撰进 三','白居易','quantangshi','','卷25','严恭七月礼，哀恸万人心。
地感胜秋气，天愁结夕阴。
鼎湖龙渐远，蒙汜日初沈。
唯有云韶乐，长留治世音。','',''),('quantangshi-24515','开成大行皇帝挽歌词四首奉敕撰进 四','白居易','quantangshi','','卷25','化成同轨表清平，恩结连枝感圣明。
帝与九龄虽吉梦，山呼万岁是虚声。
月低仪仗辞兰路，风引笳箫入柏城。
老病龙髯攀不及，东周退傅最伤情。','',''),('quantangshi-24516','时热少客因咏所怀','白居易','quantangshi','','卷25','冠栉心多懒，逢迎兴渐微。
况当时热甚，幸遇客来稀。
湿洒池边地，凉开竹下扉。
露牀青篾簟，风架白蕉衣。
院静留僧宿，楼空放妓归。
衰残强欢宴，此事久知非。','',''),('quantangshi-24517','宣州崔大夫合老忽以近诗数十首见示吟讽之下窃有所喜因成长句寄题郡斋','白居易','quantangshi','','卷25','谢玄晖殁吟声寝，郡阁寥寥笔砚闲。
无复新诗题壁上，虚教远岫列窗间。
忽惊歌雪今朝至，必恐文星昨夜还。
再喜宣城章句动，飞觞遥贺敬亭山。','',''),('quantangshi-24518','足疾','白居易','quantangshi','','卷25','足疾无加亦不瘳，绵春历夏复经秋。
开颜且酌尊中酒，代步多乘池上舟。
幸有眼前衣食在，兼无身后子孙忧。
应须学取陶彭泽，但委心形任去留。','',''),('quantangshi-24519','晚池泛舟遇景成咏赠吕处士','白居易','quantangshi','','卷25','岸浅桥平池面宽，飘然轻棹泛澄澜。
风宜扇引开怀入，树爱舟行仰卧看。
别境客稀知不易，能诗人少咏应难。
唯怜吕叟时相伴，同把磻溪旧钓竿。','',''),('quantangshi-24520','梦微之','白居易','quantangshi','','卷25','夜来携手梦同游，晨起盈巾泪莫收。
漳浦老身三度病，咸阳草树八回秋。
君埋泉下泥销骨，我寄人间雪满头。
阿卫韩郎相次去，夜台茫昧得知不。','',''),('quantangshi-24521','感秋咏意','白居易','quantangshi','','卷25','炎凉迁次速如飞，又脱生衣着熟衣。
遶壁暗蛩无限思，恋巢寒燕未能归。
须知流辈年年失，莫叹衰容日日非。
旧语相传聊自慰，世间七十老人稀。','',''),('quantangshi-24522','老病幽独偶吟所怀','白居易','quantangshi','','卷25','眼渐昏昏耳渐聋，满头霜雪半身风。
已将身出浮云外，犹寄形于逆旅中。
觞咏罢来宾阁闭，笙歌散后妓房空。
世缘俗念消除尽，别是人间清净翁。','',''),('quantangshi-24523','和杨尚书罢相后夏日游永安水亭兼招本曹杨侍郎同行','白居易','quantangshi','','卷25','道行无喜退无忧，舒卷如云得自由。
良冶动时为哲匠，巨川济了作虚舟。
竹亭阴合偏宜夏，水槛风凉不待秋。
遥爱翩翩双紫凤，入同官署出同游。','',''),('quantangshi-24524','在家出家','白居易','quantangshi','','卷25','衣食支吾婚嫁毕，从今家事不相仍。
夜眠身是投林鸟，朝饭心同乞食僧。
清唳数声松下鹤，寒光一点竹间灯。
中宵入定跏趺坐，女唤妻呼多不应。','',''),('quantangshi-24525','夜凉','白居易','quantangshi','','卷25','露白风清庭户凉，老人先着夹衣裳。
舞腰歌袖抛何处，唯对无弦琴一张。','',''),('quantangshi-24526','继之尚书自余病来寄遗非一又蒙览醉吟先生传题诗以美之今以此篇用伸酬谢','白居易','quantangshi','','卷25','衰残与世日相疎，惠好唯君分有余。
茶药赠多因病久，衣裳寄早及寒初。
交情郑重金相似，诗韵清锵玉不如。
醉傅狂言人尽笑，独知我者是尚书。','',''),('quantangshi-24527','五年秋病后独宿香山寺三绝句 一','白居易','quantangshi','','卷25','经年不到龙门寺，今夜何人知我情。
还向畅师房里宿，新秋月色旧滩声。','',''),('quantangshi-24528','五年秋病后独宿香山寺三绝句 二','白居易','quantangshi','','卷25','饮徒歌伴今何在，雨散云飞尽不回。
从此香山风月夜，祗应长是一身来。','',''),('quantangshi-24529','五年秋病后独宿香山寺三绝句 三','白居易','quantangshi','','卷25','石盆泉畔石楼头，十二年来昼夜游。
更过今年年七十，假如无病亦宜休。','',''),('quantangshi-24530','题香山新经堂招僧','白居易','quantangshi','','卷25','烟满秋堂月满庭，香花漠漠磬泠泠。
谁能来此寻真谛，白老新开一藏经。','',''),('quantangshi-24531','偶题邓公','白居易','quantangshi','','卷25','偶因携酒寻村客，聊复回车访薜萝。
且值雪寒相慰问，不妨春暖更经过。
翁居山下年空老，我得人间事校多。
一种共翁头似雪，翁无衣食自如何。','',''),('quantangshi-24532','早入皇城赠王留守仆射','白居易','quantangshi','','卷25','津桥残月晓沈沈，风露凄清禁署深。
城柳宫槐谩摇落，悲愁不到贵人心。','',''),('quantangshi-24533','寄题庐山旧草堂兼呈二林寺道侣','白居易','quantangshi','','卷25','三十年前草堂主，而今虽在鬓如丝。
登山寻水应无力，不似江州司马时。
渐伏酒魔休放醉，犹残口业未抛诗。
君行过到炉峰下，为报东林长老知。','',''),('quantangshi-24534','改业','白居易','quantangshi','','卷25','先生老去饮无兴，居士病来闲有余。
犹觉醉吟多放逸，不如禅定更清虚。
柘枝紫袖教丸药，羯鼓苍头遣种蔬。
却被山僧戏相问，一时改业意何如。','',''),('quantangshi-24535','山下留别佛光和尚','白居易','quantangshi','','卷25','劳师送我下山行，此别何人识此情。
我已七旬师九十，当知后会在他生。','',''),('quantangshi-24536','山中五绝句 岭上云','白居易','quantangshi','','卷25','岭上白云朝未散，田中青麦旱将枯。
自生自灭成何事，能逐东风作雨无。','',''),('quantangshi-24537','山中五绝句 石上苔','白居易','quantangshi','','卷25','漠漠斑斑石上苔，幽芳静绿绝纤埃。
路傍凡草荣遭遇，曾得七香车辗来。','',''),('quantangshi-24538','山中五绝句 林下樗','白居易','quantangshi','','卷25','香檀文桂苦雕镌，生理何曾得自全。
知我无材老樗否，一枝不损尽天年。','',''),('quantangshi-24539','山中五绝句 涧中鱼','白居易','quantangshi','','卷25','海水桑田欲变时，风涛翻覆沸天池。
鲸吞蛟鬬波成血，深涧游鱼乐不知。','',''),('quantangshi-24540','山中五绝句 洞中蝙蝠','白居易','quantangshi','','卷25','千年鼠化白蝙蝠，黑洞深藏避网罗。
远害全身诚得计，一生幽暗又如何。','',''),('quantangshi-24541','自戏三绝句 心问身','白居易','quantangshi','','卷25','心问身云何泰然，严冬暖被日高眠。
放君快活知恩否，不早朝来十一年。','',''),('quantangshi-24542','自戏三绝句 身报心','白居易','quantangshi','','卷25','心是身王身是宫，君今居在我宫中。
是君家舍君须爱，何事论恩自说功。','',''),('quantangshi-24543','自戏三绝句 心重答身','白居易','quantangshi','','卷25','因我疎慵休罢早，遣君安乐岁时多。
世间老苦人何限，不放君闲奈我何。','',''),('quantangshi-24544','会昌元年春五绝句 病后喜过刘家','白居易','quantangshi','','卷25','忽忆前年初病后，此生甘分不衔杯。
谁能料得今春事，又向刘家饮酒来。','',''),('quantangshi-24545','会昌元年春五绝句 赠举之仆射','白居易','quantangshi','','卷25','鸡球饧粥屡开筵，谈笑讴吟间管弦。
一月三回寒食会，春光应不负今年。','',''),('quantangshi-24546','会昌元年春五绝句 卢尹贺梦得会中作','白居易','quantangshi','','卷25','病闻川守贺筵开，起伴尚书饮一杯。
任意少年长笑我，老人自觅老人来。','',''),('quantangshi-24547','会昌元年春五绝句 题朗之槐亭','白居易','quantangshi','','卷25','春风可惜无多日，家酝唯残软半瓶。
犹望君归同一醉，篮舁早晚入槐亭。','',''),('quantangshi-24548','会昌元年春五绝句 劝梦得酒','白居易','quantangshi','','卷25','谁人功画麒麟阁，何客新投魑魅乡。
两处荣枯君莫问，残春更醉两三场。','',''),('quantangshi-24549','过裴令公宅二绝句 一','白居易','quantangshi','','卷25','风吹杨柳出墙枝，忆得同欢共醉时。
每到集贤坊地过，不曾一度不低眉。','',''),('quantangshi-24550','过裴令公宅二绝句 二','白居易','quantangshi','','卷25','梁王旧馆雪蒙蒙，愁杀邹枚二老翁。
假使明朝深一尺，亦无人到兔园中。','',''),('quantangshi-24551','百日假满少傅官停自喜言怀','白居易','quantangshi','','卷25','长告今朝满十旬，从兹萧洒便终身。
老嫌手重抛牙笏，病喜头轻换角巾。
疎傅不朝悬组绶，尚平无累毕婚姻。
人言世事何时了，我是人间事了人。','',''),('quantangshi-24552','早热','白居易','quantangshi','','卷25','畏景又加旱，火云殊未收。
篱暄饥有雀，池涸渴无鸥。
岸帻头仍痛，褰裳汗亦流。
若为当此日，迁客向炎州。','',''),('quantangshi-24553','题崔少尹上林坊新居','白居易','quantangshi','','卷25','坊静居新深且幽，忽疑缩地到沧洲。
宅东篱缺嵩峰出，堂后池开洛水流。
高下三层盘野径，沿洄十里泛渔舟。
若能为客烹鸡黍，愿伴田苏日日游。','',''),('quantangshi-24554','新涧亭','白居易','quantangshi','','卷25','烟萝初合涧新开，闲上西亭日几回。
老病归山应未得，且移泉石就身来。','',''),('quantangshi-24555','对酒有怀寄李十九郎中','白居易','quantangshi','','卷25','往年江外抛桃叶，去岁楼中别柳枝。
寂寞春来一杯酒，此情唯有李君知。','',''),('quantangshi-24556','杨六尚书频寄新诗诗中多有思闲相就之志因书鄙意报而谕之','白居易','quantangshi','','卷25','君年殊未及悬车，未合将闲逐老夫。
身健正宜金印绶，位高方称白髭须。
若论尘事何由了，但问云心自在无。
进退是非俱是梦，丘中阙下亦何殊。','',''),('quantangshi-24557','偶吟自慰兼呈梦得','白居易','quantangshi','','卷25','且喜同年满七旬，莫嫌衰病莫嫌贫。
已为海内有名客，又占世间长命人。
耳里声闻新将相，眼前失尽故交亲。
尊荣富寿难兼得，闲坐思量最要身。','',''),('quantangshi-24558','寄潮州杨继之','白居易','quantangshi','','卷25','相府潮阳俱梦中，梦中何者是穷通。
他时事过方应悟，不独荣空辱亦空。','',''),('quantangshi-24559','雪暮偶与梦得同致仕裴宾客王尚书饮','白居易','quantangshi','','卷25','黄昏惨惨雪霏霏，白首相欢醉不归。
四个老人三百岁人间此会亦应稀。','',''),('quantangshi-24560','雪朝乘兴欲诣李司徒留守先以五韵戏之','白居易','quantangshi','','卷25','夜寒生酒思，晓雪引诗情。
热饮一两盏，冷吟三五声。
铺花怜地冻，销玉畏天晴。
好拂乌巾出，宜披鹤氅行。','',''),('quantangshi-24561','赠思黯','白居易','quantangshi','','卷25','为怜清浅爱潺湲，一日三回到水边。
若道归仁滩更好，主人何故别三年。','',''),('quantangshi-24562','听歌六绝句 听都子歌','白居易','quantangshi','','卷25','都子新歌有性灵，一声格转已堪听。
更听唱到嫦娥字，犹有樊家旧典刑。','',''),('quantangshi-24563','听歌六绝句 乐世','白居易','quantangshi','','卷25','管急弦繁拍渐稠，绿腰宛转曲终头。
诚知乐世声声乐，老病人听未免愁。','',''),('quantangshi-24564','听歌六绝句 水调','白居易','quantangshi','','卷25','五言一徧最殷勤，调少情多似有因。
不会当时翻曲意，此声肠断为何人。','',''),('quantangshi-24565','听歌六绝句 想夫怜','白居易','quantangshi','','卷25','玉管朱弦莫急催，容听歌送十分杯。
长爱夫怜第二句，请君重唱夕阳开。','',''),('quantangshi-24566','听歌六绝句 何满子','白居易','quantangshi','','卷25','世传满子是人名，临就刑时曲始成。
一曲四调歌八叠，从头便是断肠声。','',''),('quantangshi-24567','听歌六绝句 离别难','白居易','quantangshi','','卷25','绿杨陌上送行人，马去车回一望尘。
不觉别时红泪尽，归来无泪可霑巾。','',''),('quantangshi-24568','闲乐','白居易','quantangshi','','卷25','坐安卧稳舆平肩，倚杖披衫遶四边。
空腹三杯卯后酒，曲肱一觉醉中眠。
更无忙苦吟闲乐，恐是人间自在天。','',''),('quantangshi-24569','立秋夕凉风忽至炎暑稍消即事咏怀寄汴州节度使李二十尚书','白居易','quantangshi','','卷25','袅袅檐树动，好风西南来。
红缸霏微灭，碧幌飘颻开。
披襟有余凉，拂簟无纤埃。
但喜烦暑退，不惜光阴催。
河秋稍清浅，月午方裴回。
或行或坐卧，体适心悠哉。
美人在浚都，旌旗绕楼台。
虽非沧溟阻，难见如蓬莱。
蝉迎节又换，雁送书未回。
君位日宠重，我年日摧颓。
无因风月下，一举平生杯。','',''),('quantangshi-24570','开成二年夏闻新蝉赠梦得','白居易','quantangshi','','卷25','十载与君别，常感新蝉鸣。
今年共君听，同在洛阳城。
噪处知林静，闻时觉景清。
凉风忽袅袅，秋思先秋生。
残槿花边立，老槐阴下行。
虽无索居恨，还动长年情。
且喜未聋耳，年年闻此声。','',''),('quantangshi-24571','题牛相公归仁里宅新成小滩','白居易','quantangshi','','卷25','平生见流水，见此转留连。
况此朱门内，君家新引泉。
伊流决一带，洛石砌千拳。
与君三伏月，满耳作潺湲。
深处碧磷磷，浅处清溅溅。
崎岸束呜咽，沙汀散沦涟。
翻浪雪不尽，澄波空共鲜。
两岸滟滪口，一泊潇湘天。
曾作天南客，漂流六七年。
何山不倚杖，何水不停船。
巴峡声心里，松江色眼前。
今朝小滩上，能不思悠然。','',''),('quantangshi-24572','春日闲居三首 一','白居易','quantangshi','','卷25','陶云爱吾庐，吾亦爱吾屋。
屋中有琴书，聊以慰幽独。
是时三月半，花落庭芜绿。
舍上晨鸠鸣，窗间春睡足。
睡足起闲坐，景晏方栉沐。
今日非十斋，庖童馈鱼肉。
饥来恣餐歠，冷热随所欲。
饱竟快搔爬，筋骸无检束。
岂徒畅肢体，兼欲遗耳目。
便可傲松乔，何假杯中渌。','',''),('quantangshi-24573','春日闲居三首 二','白居易','quantangshi','','卷25','广池春水平，羣鱼恣游泳。
新林绿阴成，众鸟欣相鸣。
时我亦潇洒，适无累与病。
鱼鸟人则殊，同归于遂性。
缅思山梁雉，时哉感孔圣。
圣人不得所，慨然叹时命。
我今对鳞羽，取乐成谣咏。
得所仍得时，吾生一何幸。','',''),('quantangshi-24574','春日闲居三首 三','白居易','quantangshi','','卷25','劳者不觉歌，歌其劳苦事。
逸者不觉歌，歌其逸乐意。
问我逸如何，闲居多兴味。
问我乐如何，闲官少忧累。
又问俸厚薄，百千随月至。
又问年几何，七十行欠二。
所得皆过望，省躬良可愧。
马闲无羁绊，鹤老有禄位。
设自为化工，优饶只如是。
安得不歌咏，默默受天赐。','',''),('quantangshi-24575','小阁闲坐','白居易','quantangshi','','卷25','阁前竹萧萧，阁下水潺潺。
拂簟卷帘坐，清风生其间。
静闻新蝉鸣，远见飞鸟还。
但有巾挂壁，而无客叩关。
二疎返故里，四老归旧山。
吾亦适所愿，求闲而得闲。','',''),('quantangshi-24576','游平泉宴浥涧宿香山石楼赠座客','白居易','quantangshi','','卷25','逸少集兰亭，季伦宴金谷。
金谷太繁华，兰亭阙丝竹。
何如今日会，浥涧平泉曲。
杯酒与管弦，贫中随分足。
紫鲜林笋嫩，红润园桃熟。
采摘助盘筵，芳滋盈口腹。
闲吟暮云碧，醉藉春草绿。
舞妙艳流风，歌清叩寒玉。
古诗惜昼短，劝我令秉烛。
是夜勿言归，相携石楼宿。','',''),('quantangshi-24577','池上幽境','白居易','quantangshi','','卷25','褭褭过水桥，微微入林路。
幽境深谁知，老身闲独步。
行行何所爱，遇物自成趣。
平滑青盘石，低密绿阴树。
石上一素琴，树下双草屦。
此是荣先生，坐禅三乐处。','',''),('quantangshi-24578','夏日闲放','白居易','quantangshi','','卷25','时暑不出门，亦无宾客至。
静室深下帘，小庭新扫地。
褰裳复岸帻，闲傲得自恣。
朝景枕簟清，乘凉一觉睡。
午餐何所有，鱼肉一两味。
夏服亦无多，蕉纱三五事。
资身既给足，长物徒烦费。
若比箪瓢人，吾今太富贵。','',''),('quantangshi-24579','和思黯居守独饮偶醉见示六韵时梦得和篇先成颇为丽绝时添两韵继而美之','白居易','quantangshi','','卷25','宫漏滴渐阑，城乌啼复歇。
此时若不醉，争奈千门月。
主人中夜起，妓烛前罗列。
歌袂默收声，舞鬟低赴节。
弦吟玉柱品，酒透金杯热。
朱颜忽已酡，清奏犹未阕。
妍词黯先唱，逸韵刘继发。
铿然双雅音，金石相磨戛。','',''),('quantangshi-24580','和梦得洛中早春见赠七韵','白居易','quantangshi','','卷25','众皆赏春色，君独怜春意。
春意竟如何，老夫知此味。
烛余减夜漏，衾暖添朝睡。
恬和台上风，虚润池边地。
开迟花养艳，语懒莺含思。
似讶隔年斋，如劝迎春醉。
何日同宴游，心期二月二。','',''),('quantangshi-24581','樱桃花下有感而作','白居易','quantangshi','','卷25','蔼蔼美周宅，樱繁春日斜。
一为洛下客，十见池上花。
烂熳岂无意，为君占年华。
风光饶此树，歌舞胜诸家。
失尽白头伴，长成红粉娃。
停杯两相顾，堪喜亦堪嗟。','',''),('quantangshi-24582','洗竹','白居易','quantangshi','','卷25','布衾寒拥颈，毡履温承足。
独立冰池前，久看洗霜竹。
先除老且病，次去纤而曲。
剪弃犹可怜，琅玕十余束。
青青复籊籊，颇异凡草木。
依然若有情，回头语僮仆。
小者截鱼竿，大者编茅屋。
勿作彗与箕，而令粪土辱。','',''),('quantangshi-24583','新沐浴','白居易','quantangshi','','卷25','形适外无恙，心恬内无忧。
夜来新沐浴，肌发舒且柔。
宽裁夹乌帽，厚絮长白裘。
裘温裹我足，帽暖覆我头。
先进酒一杯，次举粥一瓯。
半酣半饱时，四体春悠悠。
是月岁阴暮，惨冽天地愁。
白日冷无光，黄河冻不流。
何处征戍行，何人羁旅游。
穷途绝粮客，寒狱无灯囚。
劳生彼何苦，遂性我何优。
抚心但自愧，孰知其所由。','',''),('quantangshi-24584','三年除夜','白居易','quantangshi','','卷25','晰晰燎火光，氲氲腊酒香。
嗤嗤童稚戏，迢迢岁夜长。
堂上书帐前，长幼合成行。
以我年最长，次第来称觞。
七十期渐近，万绿心已忘。
不唯少欢乐，兼亦无悲伤。
素屏应居士，青衣侍孟光。
夫妻老相对，各坐一绳牀。','',''),('quantangshi-24585','自题小园','白居易','quantangshi','','卷25','不鬬门馆华，不鬬林园大。
但鬬为主人，一坐十余载。
回看甲乙第，列在都城内。
素垣夹朱门，蔼蔼遥相对。
主人安在哉，富贵去不回。
池乃为鱼凿，林乃为禽栽。
何如小园主，拄杖闲即来。
亲宾有时会，琴酒连夜开。
以此聊自足，不羡大池台。','',''),('quantangshi-24586','病中宴坐','白居易','quantangshi','','卷25','有酒病不饮，有诗慵不吟。
头眩罢垂钩，手痹休援琴。
竟日悄无事，所居闲且深。
外安支离体，中养希夷心。
窗户纳秋景，竹木澄夕阴。
宴坐小池畔，清风时动襟。','',''),('quantangshi-24587','戒药','白居易','quantangshi','','卷25','促促急景中，蠢蠢微尘里。
生涯有分限，爱恋无终已。
早夭羡中年，中年羡暮齿。
暮齿又贪生，服食求不死。
朝吞太阳精，夕吸秋石髓。
徼福反成灾，药误者多矣。
以之资嗜欲，又望延甲子。
天人阴隲间，亦恐无此理。
域中有真道，所说不如此。
后身始身存，吾闻诸老氏。','',''),('quantangshi-24588','赠梦得','白居易','quantangshi','','卷25','前日君家饮，昨日王家宴。
今日过我庐，三日三会面。
当歌聊自放，对酒交相劝。
为我尽一杯，与君发三愿。
一愿世清平，二愿身强健。
三愿临老头，数与君相见。','',''),('quantangshi-24589','逸老','白居易','quantangshi','','卷25','白日下骎骎，青天高浩浩。
人生在其中，适时即为好。
劳我以少壮，息我以衰老。
顺之多吉寿，违之或凶夭。
我初五十八，息老虽非早。
一闲十三年，所得亦不少。
况加禄仕后，衣食常温饱。
又从风疾来，女嫁男婚了。
胷中一无事，浩气凝襟抱。
飘若云信风，乐于鱼在藻。
桑榆坐已暮，钟漏行将晓。
皤然七十翁，亦足称寿考。
筋骸本非实，一束芭蕉草。
眷属偶相依，一夕同栖鸟。
去何有顾恋，住亦无忧恼。
生死尚复然，其余安足道。
是故临老心，冥然合玄造。','',''),('quantangshi-24590','遇物感兴因示子弟','白居易','quantangshi','','卷25','圣择狂夫言，俗信老人语。
我有老狂词，听之吾语汝。
吾观器用中，劒锐锋多伤。
吾观形骸内，骨劲齿先亡。
寄言处世者，不可苦刚强。
龟性愚且善，鸠心钝无恶。
人贱拾支牀，鹘欺擒暖脚。
寄言立身者，不得全柔弱。
彼固罹祸难，此未免忧患。
于何保终吉，强弱刚柔间。
上遵周孔训，旁鉴老庄言。
不唯鞭其后，亦要轭其先。','',''),('quantangshi-24591','首夏南池独酌','白居易','quantangshi','','卷25','春尽杂英歇，夏初芳草深。
薰风自南至，吹我池上林。
绿苹散还合，頳鲤跳复沈。
新叶有佳色，残莺犹好音。
依然谢家物，池酌对风琴。
慙无康乐作，秉笔思沈吟。
境胜才思劣，诗成不称心。','',''),('quantangshi-24592','官俸初罢亲故见忧以诗谕之','白居易','quantangshi','','卷25','七年为少傅，品高俸不薄。
乘轩已多慙，况是一病鹤。
又及悬车岁，筋力转衰弱。
岂以贫是忧，尚为名所缚。
今春始病免，缨组初摆落。
蜩甲有何知，云心无所着。
囷中残旧谷，可备岁饥恶。
园中多新蔬，未至食藜藿。
不求安师卜，不问陈生药。
但对丘中琴，时开池上酌。
信风舟不系，掉尾鱼方乐。
亲友不我知，而忧我寂寞。','',''),('quantangshi-24593','闲居偶吟招郑庶子皇甫郎中','白居易','quantangshi','','卷25','自哂此迂叟，少迂老更迂。
家计不一问，园林聊自娱。
竹间琴一张，池上酒一壶。
更无俗物到，但与秋光俱。
古石苍错落，新泉碧萦纡。
焉用车马客，即此是吾徒。
犹有所思人，各在城一隅。
杳然爱不见，搔首方踟蹰。
玄晏风韵远，子真云貌孤。
诚知厌朝市，何必忆江湖。
能来小涧上，一听潺湲无。','',''),('quantangshi-24594','亭西墙下伊渠水中置石激流潺湲成韵颇有幽趣以诗记之','白居易','quantangshi','','卷25','嵌巉嵩石峭，皎洁伊流清。
立为远峰势，激作寒玉声。
夹岸罗密树，面滩开小亭。
忽疑严子濑，流入洛阳城。
是时羣动息，风静微月明。
高枕夜悄悄，满耳秋泠泠。
终日临大道，何人知此情。
此情苟自惬，亦不要人听。','',''),('quantangshi-24595','闲题家池寄王屋张道士','白居易','quantangshi','','卷25','有石白磷磷，有水清潺潺。
有叟头似雪，婆娑乎其间。
进不趋要路，退不入深山。
深山太濩落，要路多险艰。
不如家池上，乐逸无忧患。
有食适吾口，有酒酡吾颜。
恍惚游醉乡，希夷造玄关。
五千言下悟，十二年来闲。
富者我不顾，贵者我不攀。
唯有天坛子，时来一往还。','',''),('quantangshi-24596','李卢二中丞各创山居俱夸胜绝然去城稍远来往颇劳弊居新泉实在宇下偶题十五韵聊戏二君','白居易','quantangshi','','卷25','龙门苍石壁，浥涧碧潭水。
各在一山隅，迢遥几十里。
清镜碧屏风，惜哉信为美。
爱而不得见，亦与无相似。
闻君每来去，矻矻事行李。
脂辖复裹粮，心力颇劳止。
未如吾舍下，石与泉甚迩。
凿凿复溅溅，昼夜流不已。
洛石千万拳，衬波铺锦绮。
海珉一两片，激濑含宫征。
绿宜春濯足，净可朝漱齿。
遶砌紫鳞游，拂帘白鸟起。
何言履道叟，便是沧浪子。
君若趁归程，请君先到此。
愿以潺湲声，洗君尘土耳。','',''),('quantangshi-24597','北窗竹石','白居易','quantangshi','','卷25','一片瑟瑟石，数竿青青竹。
向我如有情，依然看不足。
况临北窗下，复近西塘曲。
筠风散余清，苔雨含微绿。
有妻亦衰老，无子方茕独。
莫掩夜窗扉，共渠相伴宿。','',''),('quantangshi-24598','饮后戏示弟子','白居易','quantangshi','','卷25','吾为尔先生，尔为吾弟子。
孔门有遗训，复坐吾告尔。
先生馔酒食，弟子服劳止。
孝敬不在他，在兹而已矣。
欲我少忧愁，欲我多欢喜。
无如酝好酒，酒须多且旨。
旨即宾可留，多即罍不耻。
吾更有一言，尔宜听入耳。
人老多忧贫，人病多忧死。
我今虽老病，所忧不在此。
忧在半酣时，尊空座客起。','',''),('quantangshi-24599','闲坐看书贻诸少年','白居易','quantangshi','','卷25','雨砌长寒芜，风庭落秋果。
窗间有闲叟，尽日看书坐。
书中见往事，历历知福祸。
多取终厚亡，疾驱必先堕。
劝君少干名，名为锢身鏁。
劝君少求利，利是焚身火。
我心知已久，吾道无不可。
所以雀罗门，不能寂寞我。','',''),('quantangshi-24600','梦上山','白居易','quantangshi','','卷25','夜梦上嵩山，独携藜杖出。
千岩与万壑，游览皆周毕。
梦中足不病，健似少年日。
既悟神返初，依然旧形质。
始知形神内，形病神无疾。
形神两是幻，梦寐俱非实。
昼行虽蹇涩，夜步颇安逸。
昼夜既平分，其间何得失。','',''),('quantangshi-24601','对酒闲吟赠同老者','白居易','quantangshi','','卷25','人生七十稀，我年幸过之。
远行将尽路，春梦欲觉时。
家事口不问，世名心不思。
老既不足叹，病亦不能治。
扶持仰婢仆，将养信妻儿。
饥饱进退食，寒暄加减衣。
声妓放郑卫，裘马脱轻肥。
百事尽除去，尚余酒与诗。
兴来吟一篇，吟罢酒一巵。
不独适情性，兼用扶衰羸。
云液洒六腑，阳和生四肢。
于中我自乐，此外吾不知。
寄问同老者，舍此将安归。
莫学蓬心叟，胷中残是非。','',''),('quantangshi-24602','晚起闲行','白居易','quantangshi','','卷25','皤然一老子，拥裘仍隐几。
坐稳夜忘眠，卧安朝不起。
起来无可作，闭目时叩齿。
静对铜炉香，暖漱银瓶水。
午斋何俭洁，饼与蔬而已。
西寺讲楞伽，闲行一随喜。','',''),('quantangshi-24603','香山居士写真诗','白居易','quantangshi','','卷25','昔作少学士，图形入集贤。
今为老居士，写貌寄香山。
鹤毳变玄发，鸡肤换朱颜。
前形与后貌，相去三十年。
勿叹韶华子，俄成皤叟仙。
请看东海水，亦变作桑田。','',''),('quantangshi-24604','二年三月五日斋毕开素当食偶吟赠妻弘农郡君','白居易','quantangshi','','卷25','睡足肢体畅，晨起开中堂。
初旭泛帘幕，微风拂衣裳。
二婢扶盥栉，双童舁簟牀。
庭东有茂树，其下多阴凉。
前月事斋戒，昨日散道塲。
以我久蔬素，加笾仍异粮。
鲂鳞白如雪，蒸炙加桂姜。
稻饭红似花，调沃新酪浆。
佐以脯醢味，间之椒薤芳。
老怜口尚美，病喜鼻闻香。
娇呆三四孙，索哺遶我傍。
山妻未举案，馋叟已先尝。
忆同牢卺初，家贫共糟糠。
今食且如此，何必烹猪羊。
况观姻族间，夫妻半存亡。
偕老不易得，白头何足伤。
食罢酒一杯，醉饱吟又狂。
缅想梁高士，乐道喜文章。
徒夸五噫作，不解赠孟光。','',''),('quantangshi-24605','不出门','白居易','quantangshi','','卷25','弥月不出门，永日无来宾。
食饱更拂牀，睡觉一嚬伸。
轻箑白鸟羽，新簟青箭筠。
方寸方丈室，空然两无尘。
披衣腰不带，散发头不巾。
袒跣北窗下，葛天之遗民。
一日亦自足，况得以终身。
不知天壤内，目我为何人。','',''),('quantangshi-24606','感旧','白居易','quantangshi','','卷25','晦叔坟荒草已陈，梦得墓湿土犹新。
微之捐馆将一纪，杓直归丘二十春。
城中虽有故第宅，庭芜园废生荆榛。
箧中亦有旧书札，纸穿字蠹成灰尘。
平生定交取人窄，屈指相知唯五人。
四人先去我在后，一枝蒲柳衰残身。
岂无晚岁新相识，相识面亲心不亲。
人生莫羡苦长命，命长感旧多悲辛。','',''),('quantangshi-24607','送毛仙翁','白居易','quantangshi','','卷25','仙翁已得道，混迹寻岩泉。
肌肤冰雪莹，衣服云霞鲜。
绀发丝竝致，龆容花共妍。
方瞳点玄漆，高步凌非烟。
几见桑海变，莫知龟鹤年。
所憩九清外，所游五岳巅。
轩昊旧为侣，松乔难比肩。
每嗟人世人，役役如狂颠。
孰能脱羁鞅，尽遭名利牵。
貌随岁律换，神逐光阴迁。
惟余负忧谴，顦顇湓江壖。
衰鬓忽霜白，愁肠如火煎。
羁旅坐多感，裴回私自怜。
晴眺五老峰，玉洞多神仙。
何当悯湮厄，授道安虚孱。
我师惠然来，论道穷重玄。
浩荡八溟阔，志泰心超然。
形骸既无束，得丧亦都捐。
岂识椿菌异，那知鹏鷃悬。
丹华既相付，促景定当延。
玄功曷可报，感极惟勤拳。
霓旌不肯驻，又归武夷川。
语罢倏然别，孤鹤升遥天。
赋诗叙明德，永续步虚篇。','',''),('quantangshi-24608','达哉乐天行','白居易','quantangshi','','卷25','达哉达哉白乐天，分司东都十三年。
七旬才满冠已挂，半禄未及车先悬。
或伴游客春行乐，或随山僧夜坐禅。
二年忘却问家事，门庭多草厨少烟。
庖童朝告盐米尽，侍婢暮诉衣裳穿。
妻孥不悦甥侄闷，而我醉卧方陶然。
起来与尔画生计，薄产处置有后先。
先卖南坊十亩园，次卖东都五顷田。
然后兼卖所居宅，仿髴获缗二三千。
半与尔充衣食费，半与吾供酒肉钱。
吾今已年七十一，眼昏须白头风眩。
但恐此钱用不尽，即先朝露归夜泉。
未归且住亦不恶，饥餐乐饮安稳眠。
死生无可无不可，达哉达哉白乐天。','',''),('quantangshi-24609','春池闲泛','白居易','quantangshi','','卷25','绿塘新水平，红槛小舟轻。
解缆随风去，开襟信意行。
浅怜清演漾，深爱绿澄泓。
白扑柳飞絮，红浮桃落英。
古文科斗出，新叶剪刀生。
树集莺朋友，云行雁弟兄。
飞沈皆适性，酣咏自怡情。
花助银杯气，松添玉轸声。
鱼跳何事乐，鸥起复谁惊。
莫唱沧浪曲，无尘可濯缨。','',''),('quantangshi-24610','池上寓兴二绝 一','白居易','quantangshi','','卷25','濠梁庄惠谩相争，未必人情知物情。
獭捕鱼来鱼跃出，此非鱼乐是鱼惊。','',''),('quantangshi-24611','池上寓兴二绝 二','白居易','quantangshi','','卷25','水浅鱼稀白鹭饥，劳心瞪目待鱼时。
外容闲暇中心苦，似是而非谁得知。','',''),('quantangshi-24612','宴后题府中水堂赠卢尹中丞','白居易','quantangshi','','卷25','水斋岁久渐荒芜，自愧甘棠无一株。
新酒客来方宴饮，旧堂主在重欢娱。
莫言杨柳枝空老，直致樱桃树已枯。
从我到君十一尹，相看自置府来无。','',''),('quantangshi-24613','和敏中洛下即事','白居易','quantangshi','','卷25','昨日池塘春草生，阿连新有好诗成。
花园到处莺呼入，骢马游时客避行。
水暖鱼多似南国，人稀尘少胜西京。
洛中佳境应无限，若欲谙知问老兄。','',''),('quantangshi-24614','送敏中新授户部员外郎西归','白居易','quantangshi','','卷25','千里归程三伏天，官新身健马翩翩。
行冲赤日加餐饭，上到青云稳着鞭。
长庆老郎唯我在，客曹故事望君传。
前鸿后雁行难续，相去迢迢二十年。','',''),('quantangshi-24615','南侍御以石相赠助成水声因以绝句谢之','白居易','quantangshi','','卷25','泉石磷磷声似琴，闲眠静听洗尘心。
莫轻两片青苔石，一夜潺湲直万金。','',''),('quantangshi-24616','闲居自题戏招宿客','白居易','quantangshi','','卷25','水畔竹林边，闲居二十年。
健常携酒出，病即掩门眠。
解绶收朝佩，褰裳出野船。
屏除身外物，摆落世间缘。
报曙窗何早，知秋簟最先。
微风深树里，斜日小楼前。
渠口添新石，篱根写乱泉。
欲招同宿客，谁解爱潺湲。','',''),('quantangshi-24617','李留守相公见过池上泛舟举酒话及翰林旧事因成四韵以献之','白居易','quantangshi','','卷25','引棹寻池岸，移尊就菊丛。
何言济川后，相访钓船中。
白首故情在，青云往事空。
同时六学士，五相一渔翁。','',''),('quantangshi-24618','闰九月九日独饮','白居易','quantangshi','','卷25','黄花丛畔绿尊前，犹有些些旧管弦。
偶遇闰秋重九日，东篱独酌一陶然。
自从九月持斋戒，不醉重阳十五年。','',''),('quantangshi-24619','览卢子蒙侍御旧诗多与微之唱和感今伤昔因赠子蒙题于卷后','白居易','quantangshi','','卷25','早闻元九咏君诗，恨与卢君相识迟。
今日逢君开旧卷，卷中多道赠微之。
相看掩泪情难说，别有伤心事岂知。
闻道咸阳坟上树，已抽三丈白杨枝。','',''),('quantangshi-24620','寒亭留客','白居易','quantangshi','','卷25','今朝闲坐石亭中，炉火销残尊又空。
冷落若为留客住，冰池霜竹雪髯翁。','',''),('quantangshi-24621','新小滩','白居易','quantangshi','','卷25','石浅沙平流水寒，水边斜插一渔竿。
江南客见生乡思，道似严陵七里滩。','',''),('quantangshi-24622','和李中丞与李给事山居雪夜同宿小酌','白居易','quantangshi','','卷25','宪府触邪峩豸角，璅闱驳正犯龙鳞。
那知近地斋居客，忽作深山同宿人。
一盏寒灯云外夜，数杯温酎雪中春。
林泉莫作多时计，谏猎登封忆旧臣。','',''),('quantangshi-24623','履道西门二首 一','白居易','quantangshi','','卷25','履道西门有弊居，池塘竹树遶君庐。
豪华肥壮虽无分，饱暖安闲即有余。
行竈朝香炊早饭，小园春暖掇新蔬。
夷齐黄绮夸芝蕨，比我盘飧恐不如。','',''),('quantangshi-24624','履道西门二首 二','白居易','quantangshi','','卷25','履道西门独掩扉，官休病退客来稀。
亦知轩冕荣堪恋，其奈田园老合归。
跛鼈难随骐骥足，伤禽莫趁凤凰飞。
世间认得身人少，今我虽愚亦庶几。','',''),('quantangshi-24625','偶吟','白居易','quantangshi','','卷25','人生变改故无穷，昔是朝官今野翁。
久寄形于朱紫内，渐抽身入蕙荷中。
无情水任方圆器，不系舟随去住风。
犹有鲈鱼莼菜兴，来春或拟往江东。','',''),('quantangshi-24626','雪夜小饮赠梦得','白居易','quantangshi','','卷25','同为懒慢园林客，共对萧条雨雪天。
小酌酒巡销永夜，大开口笑送残年。
久将时背成遗老，多被人呼作散仙。
呼作散仙应有以，曾看东海变桑田。','',''),('quantangshi-24627','岁暮夜长病中灯下闻卢尹夜宴以诗戏之且为来日张本也','白居易','quantangshi','','卷25','荣闹兴多嫌昼短，衰闲睡少觉明迟。
当君秉烛衔杯夜，是我停飱服药时。
枕上愁吟堪发病，府中欢笑胜寻医。
明朝强出须谋乐，不拟车公更拟谁。','',''),('quantangshi-24628','病中数会张道士见讥以此答之','白居易','quantangshi','','卷25','亦知数出妨将息，不可端居守寂寥。
病即药窗眠尽日，兴来酒席坐通宵。
贤人易狎须勤饮，姹女难禁莫慢烧。
张道士输白道士，一杯沆[瀣]便逍遥。','',''),('quantangshi-24629','卯饮','白居易','quantangshi','','卷25','短屏风掩卧牀头，乌帽青毡白氎裘。
卯饮一杯眠一觉，世间何事不悠悠。','',''),('quantangshi-24630','寄题余杭郡楼兼呈裴使君','白居易','quantangshi','','卷25','官历二十政，宦游三十秋。
江山与风月，最忆是杭州。
北郭沙堤尾，西湖石岸头。
绿觞春送客，红烛夜回舟。
不敢言遗爱，空知念旧游。
凭君吟此句，题向望涛楼。','',''),('quantangshi-24631','杨六尚书留太湖石在洛下借置庭中因对举杯寄赠绝句','白居易','quantangshi','','卷25','借君片石意何如，置向庭中慰索居。
每就玉山倾一酌，兴来如对醉尚书。','',''),('quantangshi-24632','喜入新年自咏','白居易','quantangshi','','卷25','白须如雪五朝臣，又值新正第七旬。
老过占他蓝尾酒，病余收得到头身。
销磨岁月成高位，比类时流是幸人。
大历年中骑竹马，几人得见会昌春。','',''),('quantangshi-24633','滩声','白居易','quantangshi','','卷25','碧玉班班沙历历，清流决决响泠泠。
自从造得滩声后，玉管朱弦可要听。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24634','题石泉','白居易','quantangshi','','卷25','殷勤傍石遶泉行，不说何人知我情。
渐恐耳聋兼眼暗，听泉看石不分明。','',''),('quantangshi-24635','送王卿使君赴任苏州因思花迎新使感旧游寄题郡中木兰西院一别','白居易','quantangshi','','卷25','一别苏州十八载，时光人事随年改。
不论竹马尽成人，亦恐桑田半为海。
莺入故宫含意思，花迎新使生光彩。
为报江山风月知，至今白使君犹在。','',''),('quantangshi-24636','出斋日喜皇甫十早访','白居易','quantangshi','','卷25','三旬斋满欲衔杯，平旦敲门门未开。
除却朗之携一榼，的应不是别人来。','',''),('quantangshi-24637','会昌二年春题池西小楼','白居易','quantangshi','','卷25','花边春水水边楼，一坐经今四十秋。
望月桥倾三遍换，采莲船破五回修。
园林一半成乔木，邻里三分作白头。
苏李冥蒙随烛灭，陈樊漂泊逐萍流。
虽贫眼下无妨乐，纵病心中不与愁。
自笑灵光岿然在，春来游得且须游。','',''),('quantangshi-24638','酬南洛阳早春见赠','白居易','quantangshi','','卷25','物华春意尚迟回，赖有东风昼夜催。
寒缒柳腰收未得，暖熏花口噤初开。
欲披云雾联襟去，先喜琼琚入袖来。
久病长斋诗老退，争禁年少洛阳才。','',''),('quantangshi-24639','对新家醖翫自种花','白居易','quantangshi','','卷25','香麴亲看造，芳丛手自栽。
迎春报酒熟，垂老看花开。
红蜡半含萼，绿油新发醅。
玲珑五六树，潋滟两三杯。
恐有狂风起，愁无好客来。
独酣还独语，待取月明回。','',''),('quantangshi-24640','携酒往朗之庄居同饮','白居易','quantangshi','','卷25','慵中又少经过处，别后都无劝酒人。
不挈一壶相就醉，若为将老度残春。','',''),('quantangshi-24641','以诗代书酬慕巢尚书见寄','白居易','quantangshi','','卷25','书意诗情不偶然，苦云梦想在林泉。
愿为愚谷烟霞侣，思结空门香火缘。
每愧尚书情眷眷，自怜居士病绵绵。
不知待得心期否，老挍于君六七年。','',''),('quantangshi-24642','春尽日','白居易','quantangshi','','卷25','芳景销残暑气生，感时思事坐含情。
无人开口共谁语，有酒回头还自倾。
醉对数丛红芍药，渴尝一盌绿昌明。
春归似遣莺留语，好住园林三两声。','',''),('quantangshi-24643','招山僧','白居易','quantangshi','','卷25','能入城中乞食否，莫辞尘土汚袈裟。
欲知住处东城下，遶竹泉声是白家。','',''),('quantangshi-24644','夏日与闲禅师林下避暑','白居易','quantangshi','','卷25','洛景城西尘土红，伴僧闲坐竹泉东。
绿萝潭上不见日，白石滩边长有风。
热恼渐知随念尽，清凉常愿与人同。
每因毒暑悲亲故，多在炎方瘴海中。','',''),('quantangshi-24645','题新涧亭兼酬寄朝中亲故见赠','白居易','quantangshi','','卷25','何处披襟风快哉，一亭临涧四门开。
金章紫绶辞腰去，白石清泉就眼来。
自得所宜还独乐，各行其志莫相咍。
禽鱼出得池笼后，纵有人呼可更回。','',''),('quantangshi-24646','病中看经赠诸道侣','白居易','quantangshi','','卷25','右眼昏花左足风，金箆石水用无功。
不如回念三乘乐，便得浮生百病空。
无子同居草庵下，有妻偕老道塲中。
何烦更请僧为侣，月上新归伴病翁。','',''),('quantangshi-24647','游丰乐招提佛光三寺','白居易','quantangshi','','卷25','竹鞋葵扇白绡巾，林野为家云是身。
山寺每游多寄宿，都城暂出即经旬。
汉容黄绮为逋客，尧放巢由作外臣。
昨日制书临郡县，不该愚谷醉乡人。','',''),('quantangshi-24648','醉中得上都亲友书以予停俸多时忧问贫乏偶乘酒兴咏而报之','白居易','quantangshi','','卷25','头白醉昏昏，狂歌秋复春。
一生躭酒客，五度弃官人。
异世陶元亮，前生刘伯伦。
卧将琴作枕，行以锸随身。
岁要衣三对，年支谷一囷。
园葵烹佐饭，林叶扫添薪。
没齿甘蔬食，摇头谢缙绅。
自能抛爵禄，终不恼交亲。
但得杯中渌，从生甑上尘。
烦君问生计，忧醒不忧贫。','',''),('quantangshi-24649','池畔逐凉','白居易','quantangshi','','卷25','风清泉冷竹修修，三伏炎天凉似秋。
黄犬引迎骑马客，青衣扶下钓鱼舟。
衰容自觉宜闲坐，蹇步谁能更远游。
料得此身终老处，只应林下与滩头。','',''),('quantangshi-24650','池鹤八绝句 鸡赠鹤','白居易','quantangshi','','卷25','一声警露君能薄，五德司晨我用多。
不会悠悠时俗士，重君轻我意如何。','',''),('quantangshi-24651','池鹤八绝句 鹤答鸡','白居易','quantangshi','','卷25','尔争伉俪泥中鬬，吾整羽仪松上栖。
不可遣他天下眼，却轻野鹤重家鸡。','',''),('quantangshi-24652','池鹤八绝句 乌赠鹤','白居易','quantangshi','','卷25','与君白黑大分明，纵不相亲莫见轻。
我每夜啼君怨别，玉徽琴里忝同声。','',''),('quantangshi-24653','池鹤八绝句 鹤答乌','白居易','quantangshi','','卷25','吾爱栖云上华表，汝多攫肉下田中。
吾音中羽汝声角，琴曲虽同调不同。','',''),('quantangshi-24654','池鹤八绝句 鸢赠鹤','白居易','quantangshi','','卷25','君夸名鹤我名鸢，君呌闻天我戾天。
更有与君相似处，饥来一种啄腥膻。','',''),('quantangshi-24655','池鹤八绝句 鹤答鸢','白居易','quantangshi','','卷25','无妨自是莫相非，清浊高低各有归。
鸾鹤羣中彩云里，几时曾见喘鸢飞。','',''),('quantangshi-24656','池鹤八绝句 鹅赠鹤','白居易','quantangshi','','卷25','君因风送入青云，我被人驱向鸭羣。
雪颈霜毛红网掌，请看何处不如君。','',''),('quantangshi-24657','池鹤八绝句 鹤答鹅','白居易','quantangshi','','卷25','右军殁后欲何依，只合随鸡逐鸭飞。
未必牺牲及吾辈，大都我瘦胜君肥。','',''),('quantangshi-24658','谈氏小外孙玉童','白居易','quantangshi','','卷25','外翁七十孙三岁，笑指琴书欲遣传。
自念老夫今耄矣，因思稚子更茫然。
中郎余庆钟羊祜，子幼能文似马迁。
才与不才争料得，东牀空后且娇怜。','',''),('quantangshi-24659','送后集往庐山东林寺兼寄云臯上人','白居易','quantangshi','','卷25','后集寄将何处去，故山迢递在匡庐。
旧僧独有云臯在，三二年来不得书。
别后道情添几许，老来筋力又何如。
来生缘会应非远，彼此年过七十余。','',''),('quantangshi-24660','客有说','白居易','quantangshi','','卷25','近有人从海上回，海山深处见楼台。
中有仙龛虚一室，多传此待乐天来。','',''),('quantangshi-24661','答客说','白居易','quantangshi','','卷25','吾学空门非学仙，恐君此说是虚传。
海山不是吾归处，归即应归兜率天。','',''),('quantangshi-24662','哭刘尚书梦得二首 一','白居易','quantangshi','','卷25','四海齐名白与刘，百年交分两绸缪。
同贫同病退闲日，一死一生临老头。
杯酒英雄君与操，文章微婉我知丘。
贤豪虽殁精灵在，应共微之地下游。','',''),('quantangshi-24663','哭刘尚书梦得二首 二','白居易','quantangshi','','卷25','今日哭君吾道孤，寝门泪满白髭须。
不知箭折弓何用，兼恐唇亡齿亦枯。
窅窅穷泉埋宝玉，骎骎落景挂桑榆。
夜台暮齿期非远，但问前头相见无。','',''),('quantangshi-24664','昨日复今辰','白居易','quantangshi','','卷25','昨日复今辰，悠悠七十春。
所经多故处，却想似前身。
散秩优游老，闲居净洁贫。
螺杯中有物，鹤氅上无尘。
解佩收朝带，抽簪换野巾。
风仪与名号，别是一生人。','',''),('quantangshi-24665','病疮','白居易','quantangshi','','卷25','门有医来往，庭无客送迎。
病销谈笑兴，老足叹嗟声。
鹤伴临池立，人扶下砌行。
脚疮春断酒，那得有心情。','',''),('quantangshi-24666','游赵村杏花','白居易','quantangshi','','卷25','赵村红杏每年开，十五年来看几回。
七十三人难再到，今春来是别花来。','',''),('quantangshi-24667','刑部尚书致仕','白居易','quantangshi','','卷25','十五年来洛下居，道缘俗累两何如。
迷路心回因向佛，宦途事了是悬车。
全家遁世曾无闷，半俸资身亦有余。
唯是名衔人不会，毗耶长者白尚书。','',''),('quantangshi-24668','初致仕后戏酬留守牛相公并呈分司诸寮友','白居易','quantangshi','','卷25','南北东西无所羁，挂冠目在胜分司。
探花尝酒多先到，拜表行香尽不知。
炮笋烹鱼饱飱后，拥袍枕臂醉眠时。
报君一语君应笑，兼亦无心羡保厘。','',''),('quantangshi-24669','问诸亲友','白居易','quantangshi','','卷25','七十人难到，过三更较稀。
占花租野寺，定酒典朝衣。
趁醉春多出，贪欢夜未归。
不知亲故口，道我是耶非。','',''),('quantangshi-24670','戏问牛司徒','白居易','quantangshi','','卷25','抖擞尘缨捋白须，半酣扶起问司徒。
不知诏下悬车后，醉舞狂歌有例无。','',''),('quantangshi-24671','不与老为期','白居易','quantangshi','','卷25','不与老为期，因何两鬓丝。
才应免夭促，便已及衰羸。
昨夜梦何在，明朝身不知。
百忧非我所，三乐是吾师。
闭目常闲坐，低头每静思。
存神机虑息，养气语言迟。
行亦携诗箧，眠多枕酒巵。
自慙无一事，少有不安时。','',''),('quantangshi-24672','开龙门八节石滩诗二首 一','白居易','quantangshi','','卷25','铁凿金锤殷若雷，八滩九石劒棱摧。
竹篙桂檝飞如箭，百筏千艘鱼贯来。
振锡导师凭众力，挥金退傅施家财。
他时相逐西方去，莫虑尘沙路不开。','',''),('quantangshi-24673','开龙门八节石滩诗二首 二','白居易','quantangshi','','卷25','七十三翁旦暮身，誓开险路作通津。
夜舟过此无倾覆，朝胫从今免苦辛。
十里叱滩变河汉，八寒阴狱化阳春。
我身虽殁心长在，暗施慈悲与后人。','',''),('quantangshi-24674','闲坐','白居易','quantangshi','','卷25','婆娑放鸡犬，嬉戏任儿童。
闲坐槐阴下，开襟向晚风。
沤麻池水里，晒枣日阳中。
人物何相称，居然田舍翁。','',''),('quantangshi-24675','酬寄牛相公同宿话旧劝酒见赠','白居易','quantangshi','','卷25','每来政事堂中宿，共忆华阳观里时。
日暮独归愁米尽，泥深同出借驴骑。
交游今日唯残我，富贵当年更有谁。
彼此相看头雪白，一杯可合重推辞。','',''),('quantangshi-24676','道场独坐','白居易','quantangshi','','卷25','整顿衣巾拂净牀，一瓶秋水一炉香。
不论烦恼先须去，直到菩提亦拟忘。
朝谒久停收劒佩，宴游渐罢废壶觞。
世间无用残年处，祗合逍遥坐道场。','',''),('quantangshi-24677','偶作寄朗之','白居易','quantangshi','','卷25','历想为官日，无如刺史时。
欢娱接宾客，饱暖及妻儿。
自到东都后，安闲更得宜。
分司胜刺史，致仕胜分司。
何况园林下，欣然得朗之。
仰名同旧识，为乐即新知。
有雪先相访，无花不作期。
鬬醲干酿酒，夸妙细吟诗。
里巷千来往，都门五别离。
岐分两回首，书到一开眉。
叶落槐亭院，冰生竹阁池。
雀罗谁问讯，鹤氅罢追随。
身与心俱病，容将力共衰。
老来多健忘，唯不忘相思。','',''),('quantangshi-24678','狂吟七言十四韵','白居易','quantangshi','','卷25','亦知世是休明世，自想身非富贵身。
但恐人间为长物，不如林下作遗民。
游依二室成三友，住近双林当四邻。
性海澄渟平少浪，心田洒扫净无尘。
香山闲宿一千夜，梓泽连游十六春。
是客相逢皆故旧，无僧每见不殷勤。
药停有喜闲销疾，金尽无忧醉忘贫。
补绽衣裳愧妻女，支持酒肉赖交亲。
俸随日计钱盈贯，禄逐年支粟满囷。
洛堰鱼鲜供取足，游村果熟馈争新。
诗章人与传千首，寿命天教过七旬。
点检一生徼幸事，东都除我更无人。','',''),('quantangshi-24679','喜裴涛使君携诗见访醉中戏赠','白居易','quantangshi','','卷25','忽闻扣户醉吟声，不觉停杯倒屣迎。
共放诗狂同酒癖，与君别是一亲情。','',''),('quantangshi-24680','得潮州杨相公继之书并诗以此寄之','白居易','quantangshi','','卷25','诗情书意两殷勤，来自天南瘴海滨。
初覩银钩还启齿，细吟琼什欲霑巾。
凤池隔绝三千里，蜗舍沈冥十五春。
唯有新昌故园月，至今分照两乡人。','',''),('quantangshi-24681','宿府池西亭','白居易','quantangshi','','卷25','池上平桥桥下亭，夜深睡觉上桥行。
白头老尹重来宿，十五年前旧月明。','',''),('quantangshi-24682','闲眠','白居易','quantangshi','','卷25','暖牀斜卧日曛腰，一觉闲眠百病销。
尽日一餐茶两碗，更无所要到明朝。','',''),('quantangshi-24683','杨柳枝词','白居易','quantangshi','','卷25','一树春风千万枝，嫩于金色软于丝。
永丰西角荒园里，尽日无人属阿谁。','',''),('quantangshi-24684','诏取永丰柳植禁苑感赋','白居易','quantangshi','','卷25','一树衰残委泥土，双枝荣耀植天庭。
定知玄象今春后，柳宿光中添两星。','',''),('quantangshi-24685','斋居春久感事遣怀','白居易','quantangshi','','卷25','斋戒坐三旬，笙歌发四邻。
月明停酒夜，眼暗看花人。
赖学空为观，深知念是尘。
犹思闲语笑，未忘旧交亲。
久作龙门主，多为兔苑宾。
水嬉歌尽日，雪宴烛通晨。
事事皆过分，时时自问身。
风光抛得也，七十四年春。','',''),('quantangshi-24686','每见吕南二郎中新文辄窃有所叹惜因成长句以咏所怀','白居易','quantangshi','','卷25','双金百炼少人知，纵我知君徒尔为。
望梅合老无妨渴，画饼尚书不救饥。
白日回头看又晚，青云举足蹑何迟。
壮年可惜虚销掷，遣把闲杯吟咏诗。','',''),('quantangshi-24687','胡吉郑刘卢张等六贤皆多年寿予亦次焉偶于弊居合成尚齿之会七老相顾既醉且欢静而思之此会稀有因成七言六韵以纪之传好事者','白居易','quantangshi','','卷25','七人五百七十岁，拖紫纡朱垂白须。
手里无金莫嗟叹，尊中有酒且欢娱。
诗吟两句神还王，酒饮三杯气尚麤。
嵬峩狂歌教婢拍，婆娑醉舞遣孙扶。
天年高过二疎傅，人数多于四皓图。
除却三山五天竺，人间此会更应无。','',''),('quantangshi-24688','欢喜二偈 一','白居易','quantangshi','','卷25','得老加年诚可喜，当春对酒亦宜欢。
心中别有欢喜事，开得龙门八节滩。','',''),('quantangshi-24689','欢喜二偈 二','白居易','quantangshi','','卷25','眼暗头旋耳重听，唯余心口尚醒醒。
今朝欢喜缘何事，礼彻佛名百部经。','',''),('quantangshi-24690','闲居贫活计','白居易','quantangshi','','卷25','冠盖闲居少，箪瓢陋巷深。
称家开户牖，量力置园林。
俭薄身都惯，营为力不任。
饥烹一斤肉，暖卧两重衾。
尊有陶潜酒，囊无陆贾金。
莫嫌贫活计，更富即劳心。','',''),('quantangshi-24691','赠诸少年','白居易','quantangshi','','卷25','少年莫笑我蹉跎，听我狂翁一曲歌。
入手荣名取虽少，关心稳事得还多。
老慙退马霑刍秣，高喜归鸿脱弋罗。
官给俸钱天与寿，些些贫病奈吾何。','',''),('quantangshi-24692','感所见','白居易','quantangshi','','卷25','巧者焦劳智者愁，愚翁何喜复何忧。
莫嫌山木无人用，大胜笼禽不自由。
网外老鸡因断尾，盘中鲜鲙为吞钩。
谁人会我心中事，冷笑时时一掉头。','',''),('quantangshi-24693','寄黔州马常侍','白居易','quantangshi','','卷25','闲看双节信为贵，乐饮一杯谁与同。
可惜风情与心力，五年抛掷在黔中。','',''),('quantangshi-24694','和李相公留守题漕上新桥六韵','白居易','quantangshi','','卷25','选石铺新路，安桥压古堤。
似从银汉下，落傍玉川西。
影定栏杆倒，标高华表齐。
烟开虹半见，月冷鹤双栖。
材映夔龙小，功嫌元凯低。
从容济世后，余力及黔黎。','',''),('quantangshi-24695','闲居','白居易','quantangshi','','卷25','风雨萧条秋少客，门庭冷静昼多关。
金羁骆马近卖却，罗袖柳枝寻放还。
书卷略寻聊取睡，酒杯浅把麤开颜。
眼昏入夜休看月，脚重经春不上山。
心静无妨喧处寂，机忘兼觉梦中闲。
是非爱恶销停尽，唯寄空身在世间。','',''),('quantangshi-24696','新秋夜雨','白居易','quantangshi','','卷25','蟋蟀暮啾啾，光阴不少留。
松檐半夜雨，风幌满牀秋。
曙早灯犹在，凉初簟未收。
新晴好天气，谁伴老人游。','',''),('quantangshi-24697','春眠','白居易','quantangshi','','卷25','枕低被暖身安稳，日照房门帐未开。
还有少年春气味，时时蹔到梦中来。','',''),('quantangshi-24698','喜老自嘲','白居易','quantangshi','','卷25','面黑头雪白，自嫌还自怜。
毛龟蓍下老，蝙蝠鼠中仙。
名籍同逋客，衣装类古贤。
裘轻被白氎，靴暖蹋乌毡。
周易休开卦，陶琴不上弦。
任从人弃掷，自与我周旋。
铁马因疲退，铅刀以钝全。
行开第八秩，可谓尽天年。','',''),('quantangshi-24699','能无愧','白居易','quantangshi','','卷25','十两新绵褐，披行暖似春。
一团香絮枕，倚坐稳于人。
婢仆遣他尝药草，儿孙与我拂衣巾。
回看左右能无愧，养活枯残废退身。','',''),('quantangshi-24700','河阳石尚书破回鹘迎贵主过上党射鹭𪆗绘画为图猥蒙见示称叹不足以诗美之','白居易','quantangshi','','卷25','塞北虏郊随手破，山东贼垒掉鞭收。
乌孙公主归秦地，白马将军入潞州。
劒拔青鳞蛇尾活，弦抨赤羽火星流。
须知鸟目犹难漏，纵有天狼岂足忧。
画角三声刁斗晓，清商一部管弦秋。
他时麟阁图勋业，更合何人居上头。','',''),('quantangshi-24701','自咏老身示诸家属','白居易','quantangshi','','卷25','寿及七十五，俸霑五十千。
夫妻偕老日，甥侄聚居年。
粥美尝新米，袍温换故绵。
家居虽濩落，眷属幸团圆。
置榻素屏下，移炉青帐前。
书听孙子读，汤看侍儿煎。
走笔还诗债，抽衣当药钱。
支分闲事了，爬背向阳眠。','',''),('quantangshi-24702','自问此心呈诸老伴','白居易','quantangshi','','卷25','朝问此心何所思，暮问此心何所为。
不入公门慵歛手，不看人面免低眉。
居士室间眠得所，少年场上饮非宜。
闲谈亹亹留诸老，美酝徐徐进一巵。
心未曾求过分事，身常少有不安时。
此心除自谋身外，更问其余尽不知。','',''),('quantangshi-24703','六年立春日人日作','白居易','quantangshi','','卷25','二日立春人七日，盘蔬饼饵逐时新。
年方吉郑犹为少，家比刘韩未是贫。
乡园节岁应堪重，亲故欢游莫厌频。
试作循潮封眼想，何由得见洛阳春。','',''),('quantangshi-24704','斋居偶作','白居易','quantangshi','','卷25','童子装炉火，行添一炷香。
老翁持麈尾，坐拂半张牀。
卷缦看天色，移斋近日阳。
甘鲜新饼果，稳暖旧衣裳。
止足安生理，悠闲乐性场。
是非一以遣，动静百无妨。
岂有物相累，兼无情可忘。
不须忧老病，心是自医王。','',''),('quantangshi-24705','咏身','白居易','quantangshi','','卷25','自中风来三历闰，从悬军后几逢春。
周南留滞称遗老，汉上羸残号半人。
薄有文章传子弟，断无书札答交亲。
余年自问将何用，恐是人间剩长身。','',''),('quantangshi-24706','予与山南王仆射起淮南李仆射绅事历五朝逾三纪海内年辈今唯三人荣路虽殊交情不替聊题长句寄举之公垂二相公','白居易','quantangshi','','卷25','故交海内只三人，二坐岩廊一卧云。
老爱诗书还似我，荣兼将相不如君。
百年胶漆初心在，万里烟霄中路分。
阿阁鸾凰野田鹤，何人信道旧同羣。','',''),('quantangshi-24707','读道德经','白居易','quantangshi','','卷25','玄元皇帝着遗文，乌角先生仰后尘。
金玉满堂非己物，子孙委蜕是他人。
世间尽不关吾事，天下无亲于我身。
只有一身宜爱护，少教冰炭逼心神。','',''),('quantangshi-24708','禽虫十二章 一','白居易','quantangshi','','卷25','燕违戊己鹊避岁，兹事因何羽族知。
疑有凤凰颁鸟历，一时一日不参差。','',''),('quantangshi-24709','禽虫十二章 二','白居易','quantangshi','','卷25','水中科斗长成蛙，林下桑虫老作蛾。
蛙跳蛾舞仰头笑，焉用鵾鹏鳞羽多。','',''),('quantangshi-24710','禽虫十二章 三','白居易','quantangshi','','卷25','江鱼羣从称妻妾，塞雁联行号弟兄。
但恐世间真眷属，亲疎亦是强为名。','',''),('quantangshi-24711','禽虫十二章 四','白居易','quantangshi','','卷25','蚕老茧成不庇身，蜂饥蜜熟属他人。
须知年老忧家者，恐是二虫虚苦辛。','',''),('quantangshi-24712','禽虫十二章 五','白居易','quantangshi','','卷25','阿阁鵷鸾田舍乌，妍蚩贵贱两悬殊。
如何闭向深笼里，一种摧颓触四隅。','',''),('quantangshi-24713','禽虫十二章 六','白居易','quantangshi','','卷25','兽中刀枪多怒吼，鸟遭罗弋尽哀鸣。
羔羊口在缘何事，暗死屠门无一声。','',''),('quantangshi-24714','禽虫十二章 七','白居易','quantangshi','','卷25','蟭螟杀敌蚊巢上，蛮触交争蜗角中。
应是诸天观下界，一微尘内鬬英雄。','',''),('quantangshi-24715','禽虫十二章 八','白居易','quantangshi','','卷25','蟏蛸网上罥蜉蝣，反覆相持死始休。
何异浮生临老日，一弹指顷报恩讐。','',''),('quantangshi-24716','禽虫十二章 九','白居易','quantangshi','','卷25','蚁王化饭为臣妾，蜾母偷虫作子孙。
彼此假名非本物，其间何怨复何恩。','',''),('quantangshi-24717','禽虫十二章 十','白居易','quantangshi','','卷25','豆苗鹿嚼解乌毒，艾叶雀衔夺燕巢。
鸟兽不曾看本草，谙知药性是谁教。','',''),('quantangshi-24718','禽虫十二章 十一','白居易','quantangshi','','卷25','一鼠得仙生羽翼，众鼠相看有羡色。
岂知飞上未半空，已作乌鸢口中食。','',''),('quantangshi-24719','禽虫十二章 十二','白居易','quantangshi','','卷25','鹅乳养雏遗在水，鱼心想子变成鳞。
细微幽隐何穷事，知者唯应是圣人。','',''),('quantangshi-24720','窗中列远岫','白居易','quantangshi','','卷25','天静秋山好，窗开晓翠通。
遥怜峰窈窕，不隔竹朦胧。
万点当虚室，千重叠远空。
列檐攒秀气，缘隙助清风。
碧爱新晴后，明宜反照中。
宣城郡斋在，望与古时同。','',''),('quantangshi-24721','玉水记方流','白居易','quantangshi','','卷25','良璞含章久，寒泉彻底幽。
矩浮光滟滟，方折浪悠悠。
凌乱波纹异，萦回水性柔。
似风摇浅濑，疑月落清流。
潜颍应傍达，藏真岂上浮。
玉人如不见，沦弃即千秋。','',''),('quantangshi-24722','大社观献捷诗','白居易','quantangshi','','卷25','淮海妖氛灭，干坤嘉气通。
班师郊社内，操袂凯歌中。
庙算无遗策，天兵不战功。
小臣同鸟兽，率舞向皇风。','',''),('quantangshi-24723','自诲','白居易','quantangshi','','卷25','乐天乐天，来与汝言。
汝宜拳拳，终身行焉。
物有万类，锢人如锁。
事有万感，爇人如火。
万类遰来，鏁汝形骸。
使汝未老，形枯如柴。
万感遰至，火汝心怀。
使汝未死，心化为灰。
乐天乐天，可不大哀。
汝胡不惩往而念来，人生百岁七十稀，设使与汝七十期。
汝今年已四十四，却后二十六年能几时。
汝不思二十五六年来事，疾速倏忽如一寐。
往日来日皆瞥然，胡为自苦于其间。
乐天乐天，可不大哀。
而今而后，汝宜饥而食，渴而饮。
昼而兴，夜而寝。
无浪喜，无妄忧。
病则卧，死则休。
此中是汝家，此中是汝乡。
汝何舍此而去，自取其遑遑。
遑遑兮欲安往哉，乐天乐天归去来。','',''),('quantangshi-24724','三谣 蟠木谣','白居易','quantangshi','','卷25','蟠木蟠木，有似我身。
不中乎器，无用于人。
下拥肿而上辚菌，桷不桷兮轮不轮。
天子建明堂兮既非梁栋，诸侯斵大辂兮材又不中。
唯我病夫，或有所用。
用尔为几，承吾臂支吾颐而已矣。
不伤尔性，不枉尔理。
尔怏怏为几之外，无所用尔。
尔既不材，吾亦不材，胡为乎人间裴回？
蟠木蟠木，吾与汝归草堂去来。','',''),('quantangshi-24725','三谣 素屏谣','白居易','quantangshi','','卷25','素屏素屏，胡为乎不文不饰，不丹不青。
当世岂无李阳冰之篆字，张旭之笔迹。
边鸾之花鸟，张璪之松石。
吾不令加一点一画于其上，欲尔保真而全白。
吾于香炉峰下置草堂，二屏倚在东西墙。
夜如明月入我室，晓如白云围我牀。
我心久养浩然气，亦欲与尔表里相辉光。
尔不见当今甲第与王宫，织成步障银屏风。
缀珠陷钿贴云母，五金七宝相玲珑。
贵豪待此方悦目，晏然寝卧乎其中。
素屏素屏，物各有所宜，用各有所施。
尔今木为骨兮纸为面，舍吾草堂欲何之。','',''),('quantangshi-24726','三谣 朱藤谣','白居易','quantangshi','','卷25','朱藤朱藤，温如红玉，直如朱绳。
自我得尔以为杖，大有裨于股肱。
前年左选，东南万里。
交游别我于国门，亲友送我于浐水。
登高山兮车倒轮摧，渡汉水兮马跙蹄开。
中途不进，部曲多回。
唯此朱藤，实随我来。
瘴疠之乡，无人之地。
扶卫衰病，驱诃魑魅。
吾独一身，赖尔为二。
或水或陆，自北徂南。
泥黏雪滑，足力不堪。
吾本两足，得尔为三。
紫霄峰头，黄石岩下。
松门石磴，不通舆马。
吾与尔披云拨水，环山绕野。
二年蹋徧匡庐间，未尝一步而相舍。
虽有佳子弟，良友朋。
扶危助蹇，不如朱藤。
嗟乎！穷既若是，通复何如？
吾不以常杖待尔，尔勿以常人望吾。
朱藤朱藤，吾虽青云之上，黄泥之下，誓不弃尔于斯须。','',''),('quantangshi-24727','无可奈何歌','白居易','quantangshi','','卷25','无可奈何兮！白日走而朱颜颓，少日往而老日催。
生者不住兮死者不回，况乎宠辱丰顇之外物。
又何常不十去而一来，去不可挽兮来不可推。
无可奈何兮！已焉哉！惟天长而地久，前无始兮后无终。
嗟吾生之几何，寄瞬息乎其中。
又如太仓之稊米，委一粒于万钟。
何不与道逍遥？
委化从容。
纵心放志，泄泄融融。
胡为乎分爱恶于生死，系忧喜于穷通。
倔强其骨髓，龃龉其心胷。
合冰炭以交战，祗自苦兮厥躬。
彼造物者，云何不为。
此与化者，云何不随。
或喣或吹，或盛或衰。
虽千变与万化，委一顺以贯之。
为彼何非，为此何是。
谁冥此心，梦蝶之子。
何祸非福，何吉非凶。
谁达此观，丧马之翁。
俾吾为秋毫之杪，吾亦自足。
不见其小，俾吾为泰山之阿。
吾亦无余，不见其多。
是以达人静则脗然与阴合迹，动则浩然与阳同波。
委顺而已，孰知其他。
时邪命邪！吾其无奈彼何？委邪顺邪！彼亦无奈吾何？夫两无奈何，然后能冥至顺而合太和。
故吾所以饮太和，扣至顺，而为无可奈何之歌。','',''),('quantangshi-24728','池上篇','白居易','quantangshi','','卷25','十亩之宅，五亩之园。
有水一池，有竹千竿。
勿谓土狭，勿谓地偏。
足以容膝，足以息肩。
有堂有庭，有桥有船。
有书有酒，有歌有弦。
有叟在中，白须飘然。
识分知足，外无求焉。
如鸟择木，姑务巢安。
如龟居坎，不知海宽。
灵鹤怪石，紫菱白莲。
皆吾所好，尽在吾前。
时饮一杯，或吟一篇。
妻孥熙熙，鸡犬闲闲。
优哉游哉，吾将终老乎其间。','',''),('quantangshi-24729','齿落辞','白居易','quantangshi','','卷25','嗟嗟乎双齿，自吾有之尔。
俾尔嚼肉咀蔬，衔杯漱水。
丰吾肤革，滋吾血髓。
从幼逮老，勤亦至矣。
幸有辅车，非无齗腭。
胡然舍我，一旦双落。
齿虽无情，吾岂无情。
老与齿别，齿随涕零。
我老日来，尔去不回。
嗟嗟乎双齿，孰谓而来哉？孰谓而去哉？齿不能言，请以意宣。
为口中之物，忽乎六十余年。
昔君之壮也，血刚齿坚。
今君之老矣，血衰齿寒。
辅车齗腭，日削月朘。
上参差而下𠨜𦤞，曾何足以少安。
嘻！君其听哉，女长辞姥，臣老辞主。
发衰辞头，叶枯辞树。
物无细大，功成者去，君何嗟嗟？
独不闻诸道经，我身非我有也，盖天地之委形。
君何嗟嗟？
又不闻诸佛说，是身如浮云，须臾变灭。
由是而言，君何有焉？
所宜委百骸而顺万化，胡为乎嗟嗟于一牙一齿之间。
吾应曰：吾过矣，尔之言然。','',''),('quantangshi-24730','不能忘情吟','白居易','quantangshi','','卷25','鬻骆马兮放杨柳枝，掩翠黛兮顿金羁。
马不能言兮长鸣而却顾，杨柳枝再拜长跪而致辞。
辞曰：主乘此骆五年，凡千有八百日。
衔橜之下，不惊不逸。
素事主十年，凡三千有六百日。
巾栉之间，无违无失。
今素貌虽陋，未至衰摧。
骆力犹壮，又无虺颓。
即骆之力，尚可以代主一步。
素之歌，亦可以送主一杯。
一旦双去，有去无回。
故素将去，其辞也苦。
骆将去，其鸣也哀。
此人之情也，马之情也，岂主君独无情哉？
予俯而叹，仰而咍，且曰：骆、骆，尔勿嘶，素、素，尔勿啼，骆反廐，素反闺。
吾疾虽作，年虽颓，幸未及项籍之将死。
何必一日之内，弃骓兮而别虞兮，乃目素兮素兮。
为我歌杨柳枝，我姑酌彼金罍，我与尔归醉乡去来。','',''),('quantangshi-24731','劝酒','白居易','quantangshi','','卷25','昨与美人对尊酒，朱颜如花腰似柳。
今与美人倾一杯，秋风飒飒头上来。
年光似水向东去，两鬓不禁白日催。
东邻起楼高百尺，璇题照日光相射。
珠翠无非二八人，盘筵何啻三千客。
邻家儒者方下帷，夜诵古书朝忍饥。
身年三十未入仕，仰望东邻安可期。
一朝逸翮乘风势，金榜高张登上第。
春闱未了冬登科，九万抟风谁与继。
不逾十稔居台衡，门前车马纷纵横。
人人仰望在何处，造化笔头云雨生。
东邻高楼色未改，主人云亡息犹在。
金玉车马一不存，朱门更有何人待。
墙垣反锁长安春，楼台渐渐属西邻。
松篁薄暮亦栖鸟，桃李无情还笑人。
忆昔东邻宅初构，云甍彩栋皆非旧。
瑇瑁筵前翡翠栖，芙蓉池上鸳鸯鬬。
日往月来凡几秋，一衰一盛何悠悠。
但教帝里笙歌在，池上年年醉五侯。','',''),('quantangshi-24732','南阳小将张彦硖口镇税人场射虎歌','白居易','quantangshi','','卷25','海内昔年狎太平，横目穰穰何峥嵘。
天生天杀岂天怒，忍使朝朝喂猛虎。
关东驿路多丘荒，行人最忌税人场。
张彦雄特制残暴，见之叱起如叱羊。
鸣弦霹雳越幽阻，往往依林犹旅拒。
草际旋看委锦茵，腰间不更抽白羽。
老饕已毙众雏恐，童穉揶揄皆自勇。
忠良效顺势亦然，一劒猜狂敢轻动。
有文有武方为国，不是英雄伏不得。
试征张彦作将军，几个将军愿策勋。','',''),('quantangshi-24733','阴雨','白居易','quantangshi','','卷25','润叶濡枝浃四方，浓云来去势何长。
旷然寰宇清风满，救旱功高暑气凉。','',''),('quantangshi-24734','喜雨','白居易','quantangshi','','卷25','西北油然云势浓，须臾霶沛雨飘空。
顿疎万物焦枯意，定看秋郊稼穑丰。','',''),('quantangshi-24735','过故洛城','白居易','quantangshi','','卷25','故城门前春日斜，故城门里无人家。
市朝欲认不知处，漠漠野田飞草花。','',''),('quantangshi-24736','江南喜逢萧九彻因话长安旧游戏赠五十韵','白居易','quantangshi','','卷25','忆昔嬉游伴，多陪欢宴场。
寓居同永乐，幽会共平康。
师子寻前曲，声儿出内坊。
花深态奴宅，竹错得怜堂。
庭晚开红药，门闲荫绿杨。
经过悉同巷，居处尽连墙。
时世高梳髻，风流澹作妆。
戴花红石竹，帔晕紫槟榔。
鬓动悬蝉翼，钗垂小凤行。
拂胷轻粉絮，暖手小香囊。
选胜移银烛，邀欢举玉觞。
炉烟凝麝气，酒色注鹅黄。
急管停还奏，繁弦慢更张。
雪飞回舞袖，尘起绕歌梁。
旧曲翻调笑，新声打义扬。
名情推阿轨，巧语许秋娘。
风暖春将暮，星回夜未央。
宴余添粉黛，坐久换衣裳。
结伴归深院，分头入洞房。
彩帷开翡翠，罗荐拂鸳鸯。
留宿争牵袖，贪眠各占牀。
绿窗笼水影，红壁背灯光。
索镜收花钿，邀人解袷裆。
暗娇妆靥笑，私语口脂香。
怕听钟声坐，羞明映缦藏。
眉残蛾翠浅，鬟解绿云长。
聚散知无定，忧欢事不常。
离筵开夕宴，别骑促晨装。
去住青门外，留连浐水傍。
车行遥寄语，马驻共相望。
云雨分何处，山川共异方。
野行初寂莫，店宿乍恓惶。
别后嫌宵永，愁来厌岁芳。
几看花结子，频见露为霜。
岁月何超忽，音容坐渺茫。
往还书断绝，来去梦游扬。
自我辞秦地，逢君客楚乡。
常嗟异岐路，忽喜共舟航。
话旧堪垂泪，思乡数断肠。
愁云接巫峡，泪竹近潇湘。
月落江湖阔，天高节候凉。
浦深烟渺渺，沙冷月苍苍。
红叶江枫老，青芜驿路荒。
野风吹蟋蟀，湖水浸菰蒋。
帝路何由见，心期不可忘。
旧游千里外，往事十年强。
春昼提壶饮，秋林摘橘尝。
强歌还自感，纵饮不成狂。
永夜长相忆，逢君各共伤。
殷勤万里意，并写赠萧郎。','',''),('quantangshi-24737','赠薛涛','白居易','quantangshi','','卷25','蛾眉山势接云霓，欲逐刘郎北路迷。
若似剡中容易到，春风犹隔武陵溪。','',''),('quantangshi-24738','酬令狐留守尚书见赠十韵','白居易','quantangshi','','卷25','长庆清风在，夔龙燮理余。
太和膏雨降，周邵保厘初。
嵩少当宫署，伊瀍入禁渠。
晓关开玉兔，夕钥纳银鱼。
旧眷怜移疾，新吟念索居。
离声双白鹂，行色一篮轝。
罢免无余俸，休闲有敝庐。
慵于嵇叔夜，渴似马相如。
酒每蒙酤我，诗尝许起予。
洛中归计定，一半为尚书。','',''),('quantangshi-24739','听芦管','白居易','quantangshi','','卷25','幽咽新芦管，凄凉古竹枝。
似临猨峡唱，疑在雁门吹。
调为高多切，声缘小乍迟。
麤豪嫌觱篥，细妙胜参差。
云水巴南客，风沙陇上儿。
屈原收泪夜，苏武断肠时。
仰秣胡驹听，惊栖越鸟知。
何言胡越异，闻此一同悲。','',''),('quantangshi-24740','送滕庶子致仕归婺州','白居易','quantangshi','','卷25','春风秋月携歌酒，八十年来翫物华。
已见曾孙骑竹马，犹听侍女唱梅花。
入乡不杖归时健，出郭乘轺到处夸。
儿着绣衣身衣锦，东阳门户胜滕家。','',''),('quantangshi-24741','送刘郎中赴任苏州','白居易','quantangshi','','卷25','仁风膏雨去随轮，胜境欢游到逐身。
水驿路穿儿店月，花船棹入女湖春。
宣城独咏窗中岫，柳恽单题汀上苹。
何似姑苏诗太守，吟诗相继有三人。','',''),('quantangshi-24742','福先寺雪中饯刘苏州','白居易','quantangshi','','卷25','送君何处展离筵，大梵王宫大雪天。
庾岭梅花落歌管，谢家柳絮扑金田。
乱从纨袖交加舞，醉入篮轝取次眠。
却笑召邹兼访戴，只持空酒驾空船。','',''),('quantangshi-24743','除夜言怀兼赠张常侍','白居易','quantangshi','','卷25','三百六旬今夜尽，六十四年明日催。
不用叹身随日老，亦须知寿逐年来。
加添雪兴凭毡帐，消杀春愁付酒杯。
唯恨诗成君去后，红笺纸卷为谁开。','',''),('quantangshi-24744','送张常侍西归','白居易','quantangshi','','卷25','二年花下为闲伴，一旦尊前弃老夫。
西午桥街行怅望，南龙兴寺立踟蹰。
洛城久住留情否，省骑重归称意无。
出镇归朝但相访，此身应不离东都。','',''),('quantangshi-24745','和河南郑尹新岁对雪','白居易','quantangshi','','卷25','白雪吟诗铃阁开，故情新兴两裴回。
昔经勤苦照书卷，今助欢娱飘酒杯。
楚客难酬郢中曲，吴公兼占洛阳才。
铜街金谷春知否，又有诗人作尹来。','',''),('quantangshi-24746','吹笙内人出家','白居易','quantangshi','','卷25','雨露难忘君念重，电泡易灭妾身轻。
金刀已剃头然发，玉管休吹肠断声。
新戒珠从衣里得，初心莲向火中生。
道场夜半香花冷，犹在灯前礼佛名。','',''),('quantangshi-24747','醉中见微之旧卷有感','白居易','quantangshi','','卷25','今朝何事一霑襟，检得君诗醉后吟。
老泪交流风病眼，春笺摇动酒杯心。
银钩尘覆年年暗，玉树泥埋日日深。
闻道墓松高一丈，更无消息到如今。','',''),('quantangshi-24748','寿安歇马重吟','白居易','quantangshi','','卷25','春衫细薄马蹄轻，一日迟迟进一程。
野枣花含新蜜气，山禽语带破匏声。
垂鞭晚就槐阴歇，低倡闲冲柳絮行。
忽忆家园须速去，樱桃欲熟笋应生。','',''),('quantangshi-24749','赠张处士山人','白居易','quantangshi','','卷25','萝襟蕙带竹皮巾，虽到尘中不染尘。
每见俗人多惨澹，惟逢美酒即殷勤。
浮云心事谁能会，老鹤风标不可亲。
世说三生如不谬，共疑巢许是前身。','',''),('quantangshi-24750','池畔闲坐兼呈侍中','白居易','quantangshi','','卷25','池畔最平处，树阴新合时。
移牀解衣带，坐任清风吹。
举棹鸟先觉，垂纶鱼未知。
前头何所有，一卷晋公诗。','',''),('quantangshi-24751','初冬即事忆皇甫十','白居易','quantangshi','','卷25','冷竹风成韵，荒街叶作堆。
欲寻联句卷，先饮暖寒杯。
帽为迎霜戴，炉因试火开。
时时还有客，终不当君来。','',''),('quantangshi-24752','小庭寒夜寄梦得','白居易','quantangshi','','卷25','庭小同蜗舍，门闲称雀罗。
火将灯共尽，风与雪相和。
老睡随年减，衰情向夕多。
不知同病者，争奈夜长何。','',''),('quantangshi-24753','西还寿安路西歇马','白居易','quantangshi','','卷25','槐阴歇鞍马，柳絮惹衣巾。
日晚独归路，春深多思人。
去家才百里，为客只三旬。
已念纱窗下，应生宝瑟尘。','',''),('quantangshi-24754','雨中访崔十八','白居易','quantangshi','','卷25','肩舁仍挈榼，莫怪就君来。
秋雨经三宿，无人劝一杯。','',''),('quantangshi-24755','梦得得新诗','白居易','quantangshi','','卷25','池上今宵风月凉，闲教少乐理霓裳。
集仙殿里新词到，便播笙歌作乐章。','',''),('quantangshi-24756','初见刘二十八郎中有感','白居易','quantangshi','','卷25','欲话毗陵君反袂，欲言夏口我霑衣。
谁知临老相逢日，悲叹声多语笑稀。','',''),('quantangshi-24757','夜题玉泉','白居易','quantangshi','','卷25','遇客多言爱山水，逢僧尽道厌嚣尘。
玉泉潭畔松间宿，要且经年无一人。','',''),('quantangshi-24758','拜表早出赠皇甫宾客','白居易','quantangshi','','卷25','一月一回同拜表，莫辞侵早过中桥。
老于君者应无数，犹趁西京十五朝。','',''),('quantangshi-24759','赠郑尹','白居易','quantangshi','','卷25','府池东北旧亭台，久别长思醉一回。
但请主人空埽地，自携杯酒管弦来。','',''),('quantangshi-24760','别杨同州后却寄','白居易','quantangshi','','卷25','潘驿桥南醉中别，下邽村北醒时归。
春风怪我君知否，榆叶杨花扑面飞。','',''),('quantangshi-24761','狐泉店前作','白居易','quantangshi','','卷25','野狐泉上柳花飞，逐水东流便不归。
花水悠悠两无意，因风吹落偶相依。','',''),('quantangshi-24762','赠卢绩','白居易','quantangshi','','卷25','余杭县里卢明府，虚白亭中白舍人。
今日相逢头似雪，一杯相劝送残春。','',''),('quantangshi-24763','与裴华州同过敷水戏赠','白居易','quantangshi','','卷25','使君五马且蜘蹰，马上能听绝句无。
每过桑间试留意，何妨后代有罗敷。','',''),('quantangshi-24764','闲游','白居易','quantangshi','','卷25','欲笑随情酒逐身，此身虽老未辜春。
春来点检闲游数，犹自多于年少人。','',''),('quantangshi-24765','招韬光禅师','白居易','quantangshi','','卷25','白屋炊香饭，荤膻不入家。
滤泉澄葛粉，洗手摘藤花。
青芥除黄叶，红姜带紫芽。
命师相伴食，斋罢一瓯茶。','',''),('quantangshi-24766','和柳公权登齐云楼','白居易','quantangshi','','卷25','楼外春晴百鸟鸣，楼中春酒美人倾。
路傍花日添衣色，云里天风散佩声。
向此高吟谁得意，偶来闲客独多情。
佳时莫起兴亡恨，游乐今逢四海清。','',''),('quantangshi-24767','毛公坛','白居易','quantangshi','','卷25','毛公坛上片云闲，得道何年去不还。
千载鹤翎归碧落，五湖空镇万重山。','',''),('quantangshi-24768','灵岩寺','白居易','quantangshi','','卷25','馆娃宫畔千年寺，水阔云多客到稀。
闻说春来更惆怅，百花深处一僧归。','',''),('quantangshi-24769','白云泉','白居易','quantangshi','','卷25','天平山上白云泉，云自无心水自闲。
何必奔冲山下去，更添波浪向人间。','',''),('quantangshi-24770','寄韬光禅师','白居易','quantangshi','','卷25','一山门作两山门，两寺原从一寺分。
东涧水流西涧水，南山云起北山云。
前台花发后台见，上界钟声下界闻。
遥想吾师行道处，天香桂子落纷纷。','',''),('quantangshi-24771','和梦得夏至忆苏州呈卢宾客','白居易','quantangshi','','卷25','忆在苏州日，常谙夏至筵。
糉香筒竹嫩，炙脆子鹅鲜。
水国多台榭，吴风尚管弦。
每家皆有酒，无处不过船。
交印君相次，褰帷我在前。
此乡俱老矣，东望共依然。
洛下麦秋月，江南梅雨天。
齐云楼上事，已上十三年。','',''),('quantangshi-24772','曲江','白居易','quantangshi','','卷25','细草岸西东，酒旗摇水风。
楼台在花杪，鸥鹭下烟中。
翠幄晴相接，芳洲夜暂空。
何人赏秋景，兴与此时同。','',''),('quantangshi-24773','岁夜咏怀兼寄思黯','白居易','quantangshi','','卷25','徧数故交亲，何人得六旬。
今年已入手，余事岂关身。
老自无多兴，春应不拣人。
陶窗与弘阁，风景一时新。','',''),('quantangshi-24774','寒食日过枣团店','白居易','quantangshi','','卷25','寒食枣团店，春低杨柳枝。
酒香留客住，莺语和人诗。
困立攀花久，慵行上马迟。
若为将此意，前字与僧期。','',''),('quantangshi-24775','宿张云举院','白居易','quantangshi','','卷25','不食胡麻饭，杯中自得仙。
隔房招好客，可室致芳筵。
美酝香醪嫩，时新异果鲜。
夜深唯畏晓，坐稳不思眠。
棊罢嫌无敌，诗成愧在前。
明朝题壁上，谁得众人传。','',''),('quantangshi-24776','惜花','白居易','quantangshi','','卷25','可怜夭艳正当时，刚被狂风一夜吹。
今日流莺来旧处，百般言语泥空枝。','',''),('quantangshi-24777','七夕','白居易','quantangshi','','卷25','烟霄微月澹长空，银汉秋期万古同。
几许欢情与离恨，年年并在此宵中。','',''),('quantangshi-24778','宿诚禅师山房题赠','白居易','quantangshi','','卷25','不出孤峰上，人间四十秋。
视身如传舍，阅世任东流。
法为因缘立，心从次第修。
中宵问真偈，有住是吾忧。','',''),('quantangshi-24779','新池','白居易','quantangshi','','卷25','数日自穿凿，引泉来近陂。
寻渠通咽处，绕岸待清时。
深好求鱼养，闲堪与鹤期。
幽声听难尽，入夜睡常迟。','',''),('quantangshi-24780','南池','白居易','quantangshi','','卷25','萧条微雨绝，荒岸抱清源。
入舫山侵塞，分泉道接邨。
秋声依树色，月影在蒲根。
淹泊方难遂，他宵关梦魂。','',''),('quantangshi-24781','宿池上','白居易','quantangshi','','卷25','泉来从绝壑，亭敞在中流。
竹密无空岸，松长可绊舟。
蟪蛄潭上夜，河汉岛前秋。
异夕期新涨，携琴却此游。','',''),('quantangshi-24782','翻经台','白居易','quantangshi','','卷25','一会灵山犹未散，重翻贝叶有来由。
是名精进才开眼，岩石无端亦点头。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24783','寄题上强山精舍寺','白居易','quantangshi','','卷25','惯游山水住南州，行尽天台及虎丘。
惟有上强精舍寺，最堪游处未曾游。','',''),('quantangshi-24784','一字至七字诗','白居易','quantangshi','','卷25','诗，绮美，瓌奇。
明月夜，落花时。
能助欢笑，亦伤别离。
调清金石怨，吟苦鬼神悲。
天下只应我爱，世间唯有君知。
自从都尉别苏句，便到司空送白辞。','',''),('quantangshi-24785','九老图诗','白居易','quantangshi','','卷25','雪作须眉云作衣，辽东华表鹤双归。
当时一鹤犹希有，何况今逢两令威。','',''),('quantangshi-24786','和裴相公傍水闲行绝句','白居易','quantangshi','','卷25','行寻春水坐看山，早出中书晚未还。
为报野僧岩客道，偷闲气味胜长闲。','',''),('quantangshi-24787','七老会诗','胡杲','quantangshi','','卷25','闲居同会在三春，大抵愚年最出羣。
霜鬓不嫌杯酒兴，白头仍爱玉炉熏。
裴回玩柳心犹健，老大看花意却勤。
凿落满斟判酩酊，香囊高挂任氤氲。
搜神得句题红叶，望景长吟对白云。
今日交情何不替？齐年同事圣明君。','',''),('quantangshi-24788','七老会诗','吉皎','quantangshi','','卷25','休官罢任已闲居，林苑园亭兴有余。
对酒最宜花藻发，邀欢不厌柳条初。
低腰醉舞垂绯袖，击筑讴歌任褐裾。
宁用管弦来合杂，自亲松竹且清虚。
飞觥酒到须先酌，赋咏成诗不住书。
借问商山贤四皓，不如此后更何如。','',''),('quantangshi-24789','七老会诗','劉真','quantangshi','','卷25','垂丝今日幸同筵，朱紫居身是大年。
赏景尚知心未退，吟诗犹觉力完全。
闲庭饮酒当三月，在席挥毫象七贤。
山茗煮时秋雾碧，玉杯斟处彩霞鲜。
临堦花笑如歌妓，傍竹松声当管弦。
虽未学穷生死诀，人间岂不是神仙。','',''),('quantangshi-24790','七老会诗','鄭據','quantangshi','','卷25','东洛幽闲日暮春，邀欢多是白头宾。
官班朱紫多相似，年纪高低次第匀。
联句每言松竹意，停杯多说古今人。
更无外事来心肺，空有清虚入思神。
醉舞两回迎劝酒，狂歌一曲会娱身。
今朝何事偏情重，同作明时列任臣。','',''),('quantangshi-24791','七老会诗','盧真','quantangshi','','卷25','三春已尽洛阳宫，天气初晴景象中。
千朵嫩桃迎晓日，万株垂柳逐和风。
非论官位皆相似，及至年高亦共同。
对酒歌声犹觉妙，玩花诗思岂能穷。
先时共作三朝贵，今日犹逢七老翁。
但愿醁醽常满酌，烟霞万里会应同。','',''),('quantangshi-24792','七老会诗','張渾','quantangshi','','卷25','幽亭春尽共为欢，印绶居身是大官。
遁迹岂劳登远岫，垂丝何必坐溪磻。
诗联七韵犹应易，酒饮三杯未觉难。
每况襟怀同宴会，共将心事比波澜。
风吹野柳垂罗带，日照庭花落绮纨。
此席不烦铺锦帐，斯筵堪作画图看。','',''),('quantangshi-24793','一字至七字诗 竹','韋式','quantangshi','','卷25','竹，临池，似玉。
裛露静，和烟绿。
抱节宁改，贞心自束。
渭曲偏种多，王家看不足。
仙杖正惊龙化，美实当随凤熟。
唯愁吹作别离声，回首驾骖舞阵速。','',''),('quantangshi-24794','奉和白太守拣橘','張彤','quantangshi','','卷25','凌霜远涉太湖深，双卷朱旗望橘林。
树树笼烟疑带火，山山照日似悬金。
行看采掇方盈手，暗觉馨香已满襟。
拣选封题皆尽力，无人不感近臣心。','',''),('quantangshi-24795','和白太守拣贡橘','周元範','quantangshi','','卷25','离离朱实绿丛中，似火烧山处处红。
影下寒林沈绿水，光摇高树照晴空。
银章自竭人臣力，玉液谁知造化功。
看取明朝船发后，余香犹尚逐仁风。','',''),('quantangshi-24796','句','周元範','quantangshi','','卷25','谁云蒿上烟，随云依碧落。
莫怪西陵风景别，镜湖花草为先春。','',''),('quantangshi-24797','书巫山神女祠','繁知一','quantangshi','','卷25','忠州刺史今才子，行到巫山必有诗。
为报高唐神女道，速排云雨候清词。','',''),('quantangshi-24798','唐昌观玉蘂花折有仙人游怅然成二绝 一','嚴休復','quantangshi','','卷25','终日斋心祷玉宸，魂销目断未逢真。
不如满树琼瑶蘂，笑对藏花洞里人。','',''),('quantangshi-24799','唐昌观玉蘂花折有仙人游怅然成二绝 二','嚴休復','quantangshi','','卷25','羽车潜下玉龟山，尘世何由覩蕣颜。
唯有多情枝上雪，好风吹缀绿云鬟。','',''),('quantangshi-24800','江亭寓目','盧拱','quantangshi','','卷25','江郭带林峦，津亭倚槛看。
水风蒲叶战，沙雨鹭鹚寒。
晚木初凋柳，秋丛欲败兰。
哀猨自相叫，乡泪好无端。','',''),('quantangshi-24801','中元日观法事','盧拱','quantangshi','','卷25','四孟逢秋序，三元得气中。
云迎碧落步，章奏玉皇宫。
坛滴槐花露，香飘栢子风。
羽衣凌缥缈，瑶毂辗虚空。
久慕餐霞客，常悲习蓼虫。
青囊如可授，从此访鸿蒙。','',''),('quantangshi-24802','句','盧拱','quantangshi','','卷25','地甃如拳石，溪横似叶舟。','',''),('quantangshi-24803','苏州元日郡斋感怀寄越州元相公杭州白舍人','李諒','quantangshi','','卷25','称庆还乡郡吏归，端忧明发俨朝衣。
首开三百六旬日，新知四十九年非。
当官补拙犹勤虑，游宦量才已息机。
举族共资随月俸，一身惟忆故山薇。
旧交邂逅封疆近，老牧萧条宴赏稀。
书札每来同笑语，篇章时到借光辉。
丝纶暂厌分符竹，舟檝初登拥羽旗。
未知今日情何似，应与幽人事有违。','',''),('quantangshi-24804','月生','劉猛','quantangshi','','卷25','月生十五前，日望光彩圆。
月满十五后，日畏光彩瘦。
不见夜花色，一尊成暗酒。
匣中苔背铜，光短不照空。
不惜补明月，惭无此良工。','',''),('quantangshi-24805','苦雨','劉猛','quantangshi','','卷25','自念数年间，两手中藏钩。
于心且无恨，他日为我羞。
古老传童歌，连淫亦兵象。
夜梦戈甲鸣，苦不愿年长。','',''),('quantangshi-24806','晓','劉猛','quantangshi','','卷25','朝梳一把白，夜泪千滴雨。
可耻垂拱时，老作在家女。','',''),('quantangshi-24807','献卢尚书','萬彤雲','quantangshi','','卷25','荷衣拭泪几回穿，欲谒朱门抵上天。
不是尚书轻下客，山家无物与王权。','',''),('quantangshi-24808','和白尚书赋永丰柳','盧貞','quantangshi','','卷25','一树依依在永丰，两枝飞去杳无踪。
玉皇曾采人间曲，应逐歌声入九重。','',''),('quantangshi-24809','和刘梦得岁夜怀友','盧貞','quantangshi','','卷25','文翰走天下，琴尊卧洛阳。
贞元朝士尽，新岁一悲凉。
名早缘才大，官迟为寿长。
时来知病已，莫叹步趋妨。','',''),('quantangshi-24810','和李校书雨中自秘省见访知早入朝便入集贤不遇诗','王起','quantangshi','','卷25','台庭才子来欵扉，典校初从天禄归。
已慙陋巷回玉趾，仍闻细雨霑彩衣。
诘朝始趋凤阙去，此日遂愁鸡黍违。
忆昨谬官在乌府，喜君对门讨鱼鲁。
直庐相望夜每阑，高阁遥临月时吐。
昔闻三入承明庐，今来重入中秘书。
校文复忝丞相属，博物更与张侯居。
新冠峩峩不变铁，旧泉脉脉犹在渠。
忽枉情人吐芳讯，临风不羡潘锦舒。
忆见青天霞未卷，吟翫瑶华不知晚。
自怜岂是风引舟，如何渐与蓬山远。','',''),('quantangshi-24811','贡举人谒先师闻雅乐','王起','quantangshi','','卷25','蔼蔼观光士，来同鹄鹭羣。
鞠躬遗像在，稽首雅歌闻。
度曲飘清汉，余音遏晓云。
两楹凄已合，九仞杳难分。
断续同清吹，洪纤入紫氛。
长言听已罢，千载仰斯文。','',''),('quantangshi-24812','浊水求珠','王起','quantangshi','','卷25','行潦沈明月，光辉也不浮。
识珍能洞鉴，精宝此来求。
几被泥沙杂，常随混浊流。
润川终自媚，照乘且何由。
的皪终难掩，晶荧愿见收。
蛇行无胫至，饮德已闻酬。','',''),('quantangshi-24813','和周侍郎见寄','王起','quantangshi','','卷25','贡院离来二十霜，谁知更忝主文场。
杨叶纵能穿旧的，桂枝何必爱新香。
九重每忆同仙禁，六义初吟得夜光。
莫道相知不相见，莲峰之下欲征黄。','',''),('quantangshi-24814','赠毛仙翁','王起','quantangshi','','卷25','冰霜肌骨称童年，羽驾何由到俗间。
丹竈化金留秘诀，仙宫嗽玉叩玄关。
壶中世界青天近，洞里烟霞白日闲。
若许随师去尘网，愿陪鸾鹤向三山。','',''),('quantangshi-24815','赋花','王起','quantangshi','','卷25','花，点缀，分葩。
露初裛，月未斜。
一枝曲水，千树山家。
戏蝶未成梦，娇莺语更夸。
既见东园成径，何殊西子同车。
渐觉风飘轻似雪，能令醉者乱如麻。','',''),('quantangshi-24816','赋得浊水求珠','王損之','quantangshi','','卷25','积水非澄彻，明珠不易求。
依稀沈极浦，想像在中流。
瞪目思清浅，褰裳恨暗投。
徒看川色媚，空爱夜光浮。
月入疑龙吐，星归似蚌游。
终希识珍者，采掇冀冥搜。','',''),('quantangshi-24817','赋得行不由径','王炎','quantangshi','','卷25','邪径趋时捷，端心恶此名。
长衢贵高步，大路自规行。
且虑萦纡僻，将求坦荡情。
讵同流俗好，方保立身贞。
远迹如违险，修仁在履平。
始知夫子道，从此得坚诚。','',''),('quantangshi-24818','赋得行不由径','封孟紳','quantangshi','','卷25','欲速意何成，康庄欲砥平。
天衢皆利往，吾道泰方行。
不复由莱径，无由见蒋生。
三条遵广达，九轨尚安贞。
紫陌悠悠去，芳尘步步清。
澹台千载后，公正有遗名。','',''),('quantangshi-24819','题马侍中燧木香亭','邵楚萇','quantangshi','','卷25','春日迟迟木香阁，窈窕佳人褰绣幕。
淋漓玉露滴紫蕤，绵蛮黄鸟窥朱萼。
横汉碧云歌处断，满地花钿舞时落。
树影参差斜入檐，风动玲珑水晶箔。','',''),('quantangshi-24820','赋得玉水记方流','鄭俞','quantangshi','','卷25','积水綦文动，因知玉产幽。
如天涵素色，侔地引方流。
潜润滋云起，荧华射浪浮。
鱼龙泉不夜，草木岸无秋。
璧沼宁堪比，瑶池讵可俦。
若非悬坐测，谁复寄冥搜。','',''),('quantangshi-24821','赋得玉水记方流','吳丹','quantangshi','','卷25','玉泉何处记，四折水纹浮。
润下宁逾矩，居方在上流。
映空虚漾漾，涵白净悠悠。
影碎疑冲斗，光清耐触舟。
圭璋分辨状，沙砾共怀柔。
愿赴朝宗日，萦回入御沟。','',''),('quantangshi-24822','赋得玉水记方流','王鑑','quantangshi','','卷25','玉润在中洲，光临崎岸幽。
氤氲冥瑞影，演漾度方流。
乍似轻涟合，还疑骇浪收。
夤缘知有异，洞彻信无俦。
比德称殊赏，含辉处至柔。
沈沦如见念，况乃属时休。','',''),('quantangshi-24823','赋得玉水记方流','陳昌言','quantangshi','','卷25','明媚如怀玉，奇姿自诧幽。
白虹深不见，绿水折空流。
方珏清沙遍，纵横气色浮。
类圭才有角，写月让成钩。
久处沈潜贵，希当特达收。
滔滔在何许，揭厉愿从游。','',''),('quantangshi-24824','白日丽江臯','陳昌言','quantangshi','','卷25','迟景临遥水，晴空似不高。
清明开晓镜，昭晰辨秋毫。
郁郁长堤土，离离浅渚毛。
烟销占一候，风静拥千艘。
独媚青春柳，宜看白鹭涛。
何年谢公赏，遗韵在江臯。','',''),('quantangshi-24825','赋得玉水记方流','杜元穎','quantangshi','','卷25','重泉生美玉，积水异常流。
始玩清堪赏，因知宝可求。
斗回虹气见，磬折紫光浮。
中矩皆明德，同方叶至柔。
月华偏共映，风暖伫将游。
遇鉴终无暗，逢时愿见收。','',''),('quantangshi-24826','太常观阅骠国新乐','胡直鈞','quantangshi','','卷25','异音来骠国，初被奉常人。
才可宫商辨，殊惊节奏新。
转规回绣面，曲折度文身。
舒散随鸾吹，喧呼杂鸟春。
襟袵怀旧识，丝竹变恒陈。
何事留中夏，长令表化淳。','',''),('quantangshi-24827','行不由径','俞簡','quantangshi','','卷25','古人心有尚，乃是孔门生。
为计安贫乐，当从大道行。
讵应流远迹，方欲料前程。
捷径虽云易，长衢岂不平。
后来无枉路，先达擅前名。
一示遵途意，微衷益自精。','',''),('quantangshi-24828','丁巳岁八月祭武侯祠堂因题临淮公旧碑','楊嗣復','quantangshi','','卷25','斋庄修祀事，旌斾出郊闉。
剃草轩墀狭，涂墙赭垩新。
谋猷期作圣，风俗奉为神。
酹酒成坳泽，持兵列偶人。
非才膺宠任，异代揖芳尘。
况是平津客，碑前泪满巾。','',''),('quantangshi-24829','仪凤','楊嗣復','quantangshi','','卷25','八方该帝泽，威凤忽来宾。
向日朱光动，迎风翠羽新。
低昂多异趣，饮啄迥无邻。
郊薮今翔集，河图意等伦。
闻韶知鼓舞，偶圣愿逡巡。
比屋初同俗，垂恩击壤人。','',''),('quantangshi-24830','赠毛仙翁','楊嗣復','quantangshi','','卷25','天上玉郎骑白鹤，肘后金壶盛妙药。
暂游下界傲五侯，重看当时旧城郭。
羽衣茸茸轻似雪，云上双童持绛节。
王母亲缝紫锦囊，令向怀中藏秘诀。
令威子晋皆俦侣，东岳同寻太真女。
搜奇缀韵和阳春，文章不是人间语。
药成自固黄金骨，天地齐兮身不没。
日月宫中便是家，下视昆仑何突兀。
童姿玉貌谁方比，玄发绿髯光弥弥。
满朝将相门弟子，随师尽愿抛尘滓。
九转琅玕必有余，愿乞刀圭救生死。','',''),('quantangshi-24831','题李处士山居','楊嗣復','quantangshi','','卷25','卧龙决起为时君，寂寞匡庐惟白云。
今日仲容修故业，草堂焉敢更移文。','',''),('quantangshi-24832','谢寄新茶','楊嗣復','quantangshi','','卷25','石上生芽二月中，蒙山顾渚莫争雄。
封题寄与杨司马，应为前衔是相公。','',''),('quantangshi-24833','卢十五竹亭送侄偁归山','楊衡','quantangshi','','卷25','落叶寒拥壁，清霜夜霑石。
正是忆山时，复送归山客。
殷勤一尊酒，晓月当窗白。','',''),('quantangshi-24834','旅次江亭','楊衡','quantangshi','','卷25','扣舷不能寐，皓露清衣襟。
弥伤孤舟夜，远结万里心。
幽兴惜瑶草，素怀寄鸣琴。
三奏月初上，寂寥寒江深。','',''),('quantangshi-24835','赋得夜雨滴空堦送魏秀才','楊衡','quantangshi','','卷25','委檐方滴滴，霑红复洒绿。
醉听乍朦胧，愁闻多断续。
始兼泉向细，稍杂更声促。
百虑自萦心，况有人如玉。','',''),('quantangshi-24836','征人','楊衡','quantangshi','','卷25','西风屡鸣雁，东郊未升日。
繁烟幕幕昏，暗骑萧萧出。
望云愁玉塞，眠月想蕙质。
借问露霑衣，何如香满室。','',''),('quantangshi-24837','游陆先生故岩居','楊衡','quantangshi','','卷25','独壑临万嶂，苍苔绝行迹。
仰窥猨挂树，俯对鹤巢石。
上有一岩屋，相传灵人宅。
深林无阳晖，幽水转鲜碧。
拾薪遇遗鼎，探穴得古籍。
结念候云兴，烧香坐终夕。','',''),('quantangshi-24838','题玄和师仙药室','楊衡','quantangshi','','卷25','山边萧寂室，石掩浮云扃。
遶室微有路，松烟深冥冥。
入松汲寒水，对鹤问仙经。
石几香未尽，水花风欲零。
何年去华表，几度穷苍冥。
却顾宦游子，眇如霜中萤。','',''),('quantangshi-24839','宿陆氏斋赋得残灯诗','楊衡','quantangshi','','卷25','殷勤照永夜，属思未成眠。
余晖含薄雾，落烬迸空筵。
谁比秦楼晓，缄愁别幌前。','',''),('quantangshi-24840','夷陵郡内叙别','楊衡','quantangshi','','卷25','礼娶嗣明德，同牢夙所钦。
况蒙生死契，岂顾蓬蒿心。
雁币任野薄，恩爱缘义深。
同声若鼓瑟，合韵似鸣琴。
将迓空未立，就赘意难任。
皎月托言誓，沧波信浮沈。
荆台理晨辙，巫渚疑宵襟。
悯悯百虑起，回回万恨深。
候更促徒侣，先晓彻夜禽。
灯彩凝寒风，蝉思噪密林。
留念同心带，赠远芙蓉簪。
抚怀极投漆，感物重黄金。
分鸾岂遐阻，别劒念相寻。
傥甘蓬户贱，愿俟故山岑。','',''),('quantangshi-24841','将之荆州南与张伯刚马惣钟陵夜别','楊衡','quantangshi','','卷25','荆台别路长，密绪分离状。
莫诉杯来促，更筹屡已倡。
烛花侵雾暗，瑟调寒风亮。
谁念晓帆开，默睇参差浪。','',''),('quantangshi-24842','经端溪峡中','楊衡','quantangshi','','卷25','阴岸东流水，上有微风生。
素羽漾翠涧，碧苔敷丹英。
重林宿雨晦，远岫孤霞明。
飞猱相攀牵，白云乱纵横。
有客溯轻檝，阅胜匪羁程。
逍遥一息间，粪土五侯荣。
搴茗庶蠲热，漱泉聊析酲。
寄言丝竹者，讵识松风声。','',''),('quantangshi-24843','南海苦雨寄赠王四侍御','楊衡','quantangshi','','卷25','炎风杂海气，暑雨每成霖。
涂泥亲杖屦，苔藓渍衣襟。
念近剧怀远，涉浅定知深。
暗沟夜滴滴，荒庭昼霪霪。
折简展离旷，理迳俟招寻。
处阴诚多惨，况乃触隅禽。','',''),('quantangshi-24844','秋夜闲居即事寄庐山郑员外蜀郡符处士','楊衡','quantangshi','','卷25','忧思繁未整，良辰会无由。
引领迟佳音，星纪屡以周。
蓬阆绝华耀，况乃处穷愁。
坠叶寒拥砌，灯火夜悠悠。
开琴弄清弦，窥月俯澄流。
冉冉鸿雁度，萧萧帷箔秋。
怅怀石门咏，缅慕碧鸡游。
仿髴蒙颜色，崇兰隐芳洲。','',''),('quantangshi-24845','寄赠田仓曹湾','楊衡','quantangshi','','卷25','芳兰媚庭除，灼灼红英舒。
身为陋巷客，门有绛辕车。
朝览夷胡传，暮习颍阳书。
盻云高羽翼，待贾蕴璠璵。
缨弁虽云阻，音尘岂复疎。
若因风雨晦，应念寂寥居。','',''),('quantangshi-24846','咏春色','楊衡','quantangshi','','卷25','霭霭复蒙蒙，非雾满晴空。
密添宫柳翠，暗泄路桃红。
萦丝光乍失，缘隟影才通。
夕迷鸳枕上，朝漫绮弦中。
促驷驰香陌，劳莺转艳丛。
可怜肠断望，并在洛城东。','',''),('quantangshi-24847','送春','楊衡','quantangshi','','卷25','三月三十日，春归日复暮。
惆怅问春风，明朝应不住。
送春曲江上，眷眷东西顾。
但见扑水花，纷纷不知数。
人生似行客，两足无停步。
日日进前程，前程几多路。
兵刃与水火，尽可违之去。
惟有老到来，人间无避处。
感时良未已，独倚池南树。
今日送春心，心如别亲故。','',''),('quantangshi-24848','游峡山寺','楊衡','quantangshi','','卷25','结构天南畔，胜绝固难俦。
幸蒙时所漏，遂得恣闲游。
路石荫松盖，槛藤维鹤舟。
雨霁花木润，风和景气柔。
宝殿敞丹扉，灵幡垂绛旒。
照曜芙蓉壶，金人居上头。
翔禽拂危刹，落日避层楼。
端溪弥漫驶，曲涧潺湲流。
高居何重沓，登览自夷犹。
烟霞无隐态，岩洞讵遗幽。
奔驷非久耀，驰波肯暂留。
会从香火缘，灭迹此山丘。','',''),('quantangshi-24849','宿陟岵寺云律师院','楊衡','quantangshi','','卷25','像宇郁参差，宝林疎复密。
中有弥天子，燃灯坐虚室。
心证红莲喻，迹羁青眼律。
玉炉扬翠烟，金经开缥帙。
肆陈坚固学，破我梦幻质。
碧水洒尘缨，凉扇当夏日。
宿禽讵相保，迸火烟欲失。
愿回戚促劳，趋隅事休逸。','',''),('quantangshi-24850','秋夜桂州宴送郑十九侍御','楊衡','quantangshi','','卷25','秋至触物愁，况当离别筵。
短歌销夜烛，繁绪遍高弦。
桂水舟始泛，兰堂榻讵悬。
一杯勾离阻，三载奉周旋。
鸦噪更漏飒，露濡风景鲜。
斯须不共此，且为更留连。','',''),('quantangshi-24851','九日陪樊尚书龙山宴集','楊衡','quantangshi','','卷25','孟嘉从宴地，千乘复登临。
缘危陟高步，凭旷写幽襟。
黄花翫初馥，翠物喜盈斟。
云杂组绣色，乐和山水音。
斾摇秋吹急，筵卷夕光沈。
都人瞻骑火，犹知隔寺深。','',''),('quantangshi-24852','江陵送客归河北','楊衡','quantangshi','','卷25','远客归故里，临路结裴回。
山长水复阔，无因重此来。
聊将歌一曲，送子手中杯。','',''),('quantangshi-24853','送郑丞之罗浮中习业','楊衡','quantangshi','','卷25','百年泛飘忽，万事系衰荣。
高鸿脱矰缴，达士去簪缨。
始从天目游，复作罗浮行。
云卧石林密，月窥花洞明。
全形在气和，习默凭境清。
夙祕绛囊诀，屡投金简名。
钟管促离觞，烟霞随去程。
何当真府内，重得欵平生。','',''),('quantangshi-24854','送王秀才往安南','楊衡','quantangshi','','卷25','君为蹈海客，客路谁谙悉。
鲸度乍疑山，鸡鸣先见日。
所嗟回棹晚，倍结离情密。
无贪合浦珠，念守江陵橘。','',''),('quantangshi-24855','送公孙器自桂林归蜀','楊衡','quantangshi','','卷25','桂林浅复碧，潺湲半露石。
将乘触物舟，暂驻飞空锡。
蜀乡异青眼，蓬户高朱戟。
风度杳难寻，云飘讵留迹。
旧户闲花草，驯鸽傍檐隟。
挥手共忘怀，日堕千山夕。','',''),('quantangshi-24856','赠罗浮易炼师','楊衡','quantangshi','','卷25','海上多仙峤，灵人信长生。
荣卫冰雪姿，咽嚼日月精。
默书绛符遍，晦步斗文成。
翠发披肩长，金盖凌风轻。
晓籁息尘响，天鸡叱幽声。
碧树来户阴，丹霞照窗明。
焚香叩虚寂，稽首回太清。
鸾鹭振羽仪，飞翻拂斾旌。
左挹玉泉液，右搴云芝英。
念得参龙驾，攀天度赤城。','',''),('quantangshi-24857','登紫霄峰赠黄仙师','楊衡','quantangshi','','卷25','紫霄不可涉，灵峯信穹崇。
下有琼树枝，上有翠发翁。
鸡鸣秋汉侧，日出红霞中。
璨璨真仙子，执旄为侍童。
焚香杳忘言，默念合太空。
世华徒熠耀，虚室自朦胧。
云飞琼瑶圃，龟息芝兰藂。
玉箓掩不开，天窗微微风。
兹焉悟佳旨，尘境亦幽通。
浩渺临广津，永用挹无穷。','',''),('quantangshi-24858','乌啼曲','楊衡','quantangshi','','卷25','可怜杨叶复杨花，雪净烟深碧玉家。
乌栖不定枝条弱，城头夜半声哑哑。
浮萍流荡门前水，任罥芙蓉莫浣纱。','',''),('quantangshi-24859','白紵歌二首 一','楊衡','quantangshi','','卷25','玉缨翠佩杂轻罗，香汗微渍朱颜酡，为君起唱白紵歌。
清声褭云繁思多，凝笳哀瑟时相和。
金壶半倾芳夜促，梁尘霏霏暗红烛。
令君安坐听终曲，坠叶飘花难再复。','',''),('quantangshi-24860','白紵歌二首 二','楊衡','quantangshi','','卷25','蹑珠履，步琼筵轻身起舞红烛前，芳姿艳态妖且妍。
回眸转袖暗催弦，凉风萧萧漏水急。
月华泛艳红莲湿，牵裙揽带翻成泣。','',''),('quantangshi-24861','长门怨','楊衡','quantangshi','','卷25','丝声繁兮管声急，珠帘不卷风吹入。
万遍凝愁枕上听，千回候命花间立。
望望昭阳信不来，回眸独掩红巾泣。','',''),('quantangshi-24862','寄彻公','楊衡','quantangshi','','卷25','北风吹霜霜月明，荷叶枯尽越水清。
别来几度龙宫宿，雪山童子应相逐。','',''),('quantangshi-24863','哭李象','楊衡','quantangshi','','卷25','白鸡黄犬不将去，寂寞空余葬时路。
草死花开年复年，后人知是何人墓。
忆君思君独不眠，夜寒月照青枫树。','',''),('quantangshi-24864','宿云溪观赋得秋灯引送客','楊衡','quantangshi','','卷25','云房寄宿秋夜客，一灯荧荧照虚壁。
虫声呼客客未眠，几人语话清景侧。
不可离别愁纷多，秋灯秋灯奈别何。','',''),('quantangshi-24865','采莲曲','楊衡','quantangshi','','卷25','凝鲜雾渚夕，阳艳绿波风。
鱼游乍散藻，露重稍欹红。
楚客伤暮节，吴娃泣败藂。
促令芳本固，宁望雪霜中。','',''),('quantangshi-24866','他乡七夕','楊衡','quantangshi','','卷25','汉渚常多别，山桥忽重游。
向云迎翠辇，当月拜珠旒。
寝幌凝宵态，妆奁闭晓愁。
不堪鸣杼日，空对白榆秋。','',''),('quantangshi-24867','春日偶题','楊衡','quantangshi','','卷25','何处春先到，桥东水北亭。
[冻]花开未得，冷酒酌难醒。
就日移轻榻，遮风展小屏。
更无人劝饮，莺语渐叮咛。','',''),('quantangshi-24868','题山寺','楊衡','quantangshi','','卷25','千峯白露后，云壁挂残灯。
曙色海边日，经声松下僧。
意闲门不闭，年去水空澄。
稽首如何问，森罗尽一乘。','',''),('quantangshi-24869','广州石门寺重送李尚赴朝时兼宗正卿','楊衡','quantangshi','','卷25','象阙趋云陛，龙宫憩石门。
清铙犹启路，黄发重攀辕。
藻变朝天服，珠怀委地言。
那令蓬蒿客，兹席未离尊。','',''),('quantangshi-24870','送孔周之南海谒王尚书','楊衡','quantangshi','','卷25','泛棹若流萍，桂寒山更青。
望云生碧落，看日下沧溟。
潮尽收珠母，沙闲拾翠翎。
自趋龙戟下，再为诵芳馨。','',''),('quantangshi-24871','冬夜举公房送崔秀才归南阳','楊衡','quantangshi','','卷25','闻君动征棹，犯夜故来寻。
强置一尊酒，重欵百年心。
灯白霜气冷，室虚松韵深。
南阳三顾地，幸偶价千金。','',''),('quantangshi-24872','送陈房谒抚州周使君','楊衡','quantangshi','','卷25','匡山一亩宫，尚有桂兰丛。
凿壁年虽异，穿杨志幸同。
貌羸缘塞苦，道蹇为囊空。
去谒临川守，因怜鹤在笼。','',''),('quantangshi-24873','山斋独宿赠晏上人','楊衡','quantangshi','','卷25','幢幢云树秋，黄叶下山头。
虫响夜难度，梦闲神不游。
窗灯寒几尽，帘雨晓堦愁。
何以禅栖客，灰心在沃州。','',''),('quantangshi-24874','桂州与陈羽念别','楊衡','quantangshi','','卷25','惨戚损志抱，因君时解颜。
重叹今夕会，复在几夕间。
碧桂水连海，苍梧云满山。
茫茫从此去，何路入秦关。','',''),('quantangshi-24875','经赵处士居','楊衡','quantangshi','','卷25','云居避世客，发白习儒经。
有地水空绿，无人山自青。
废梁悲逝水，卧木思荒庭。
向夕霏烟敛，徒看处士星。','',''),('quantangshi-24876','病中赴袁州次香馆','楊衡','quantangshi','','卷25','病舆憩上馆，缭绕向山隅。
荒葛漫欹壁，幽禽啄朽株。
力微怯升降，意欲结踟躇。
谁能挹香水，一为濯烦纡。','',''),('quantangshi-24877','送人流雷州','楊衡','quantangshi','','卷25','逐客指天涯，人间此路赊。
地图经大庾，水驿过长沙。
腊月雷州雨，秋风桂岭花。','',''),('quantangshi-24878','送彻公','楊衡','quantangshi','','卷25','白首年空度，幽居俗岂知。
败蕉依晚日，孤鹤立秋墀。
久客何由造，禅门不可窥。
会同尘外友，斋沐奉威仪。','',''),('quantangshi-24879','赠庐山道士','楊衡','quantangshi','','卷25','寂寥高室古松寒，松下仙人字委鸾。
头垂白发朝鸣磬，手把青芝夜遶坛。
物像自随尘外灭，真源长向性中看。
悠悠万古皆如此，秋比松枝春比兰。','',''),('quantangshi-24880','赋得直如朱丝弦','楊衡','quantangshi','','卷25','寂寞瑶琴上，深知直者情。
幸传朱鹭曲，那止素丝名。
瑞草人空仰，王言世久行。
大方闻正位，乐府动清声。
文武音初合，宫商调屡更。
谁能向机杼，终日泣无成。','',''),('quantangshi-24881','早春即事','楊衡','quantangshi','','卷25','眼重朝眠足，头轻宿醉醒。
阳光满前户，雪水半中庭。
候变随天气，春生逐地形。
北檐梅晚白，东岸柳先青。
葱壠抽羊角，松巢堕鹤翎。
老来诗更拙，吟罢少人听。','',''),('quantangshi-24882','题花树','楊衡','quantangshi','','卷25','都无看花意，偶到树边来。
可怜枝上色，一一为愁开。','',''),('quantangshi-24883','宿吉祥寺寄庐山隐者','楊衡','quantangshi','','卷25','风鸣云外钟，鹤宿千年松。
相思杳不见，月出山重重。','',''),('quantangshi-24884','边思','楊衡','quantangshi','','卷25','苏武节旄尽，李陵音信稀。
梅当陇上发，人向陇头归。','',''),('quantangshi-24885','夜半步次古城','楊衡','quantangshi','','卷25','茫茫死复生，惟有古时城。
夜半无鸟雀，花枝当月明。','',''),('quantangshi-24886','春梦','楊衡','quantangshi','','卷25','空庭日照花如锦，红妆美人当昼寝。
傍人不知梦中事，唯见玉钗时坠枕。','',''),('quantangshi-24887','宿青牛谷','楊衡','quantangshi','','卷25','随云步入青牛谷，青牛道士留我宿。
可怜夜久月明中，唯有坛边一枝竹。','',''),('quantangshi-24888','槿','楊衡','quantangshi','','卷25','自用金钱买槿栽，二年方始一花开。
怜红未许家人见，胡蜨争知早到来。','',''),('quantangshi-24889','九日','楊衡','quantangshi','','卷25','黄菊紫菊傍篱落，摘菊泛酒爱芳新。
不堪今日望乡意，强插茱萸随众人。','',''),('quantangshi-24890','仙女词','楊衡','quantangshi','','卷25','玉京初侍紫皇君，金缕鸳鸯满绛裙。
仙宫一闭无消息，遥结芳心向碧云。','',''),('quantangshi-24891','句','楊衡','quantangshi','','卷25','贤人处霄汉，荒泽自耕耘。
陇首降时雨，雷声出夏云。
一一鹤声飞上天。','',''),('quantangshi-24892','享太庙乐章','牛僧孺','quantangshi','','卷25','湜湜颀颀，融昭德辉。
不纽不舒，贯成九围。
武烈文经，敷施当宜。
纂尧付启，亿万熙熙。','',''),('quantangshi-24893','乐天梦得有岁夜诗聊以奉和','牛僧孺','quantangshi','','卷25','惜岁岁今尽，少年应不知。
凄凉数流辈，欢喜见孙儿。
暗减一身力，潜添满鬓丝。
莫愁花笑老，花自几多时。','',''),('quantangshi-24894','李苏州遗太湖石奇状绝伦因题二十韵奉呈梦得乐天','牛僧孺','quantangshi','','卷25','胚浑何时结，嵌空此日成。
掀蹲龙虎鬬，挟怪鬼神惊。
带雨新水静，轻敲碎玉鸣。
搀叉锋刃簇，缕络钓丝萦。
近水摇奇冷，依松助澹清。
通身鳞甲隐，透穴洞天明。
丑凸隆胡准，深凹刻兕觵。
雷风疑欲变，阴黑讶将行。
噤㾕微寒早，轮囷数片横。
地只愁垫压，鳌足困支撑。
珍重姑苏守，相怜嬾慢情。
为探湖里物，不怕浪中鲸。
利涉余千里，山河仅百程。
池塘初展见，金玉自凡轻。
侧眩魂犹悚，周观意渐平。
似逢三益友，如对十年兄。
旺兴添魔力，消烦破宿酲。
嫓人当绮皓，视秩即公卿。
念此园林宝，还须别识精。
诗仙有刘白，为汝数逢迎。','',''),('quantangshi-24895','席上赠刘梦得','牛僧孺','quantangshi','','卷25','粉署为郎四十春，今来名辈更无人。
休论世上升沉事，且鬬樽前见在身。
珠玉会应成咳唾，山川犹觉露精神。
莫嫌恃酒轻言语，曾把文章谒后尘。','',''),('quantangshi-24896','句','牛僧孺','quantangshi','','卷25','但愁封寄去，魔物或惊禅。
惟羡东都白居士，年年香积问禅师。
不是道公狂不得，恨公逢我不教狂。
地瘦草丛短，求人气色沮。
凭酒意乃伸。','',''),('quantangshi-24897','赋得月照冰池','葉季良','quantangshi','','卷25','霁夕云初歛，栖娥月未亏。
圆光生碧海，素色满瑶池。
天迥轮空见，波凝影讵窥。
浮霜玉比彩，照像镜同规。
皎洁寒偏净，裴回夜转宜。
谁怜幽境在，长与赏心随。','',''),('quantangshi-24898','赋得琢玉成器','葉季良','quantangshi','','卷25','片玉寄幽石，纷纶当代名。
荆人献始遇，良匠琢初成。
冰映寒光动，虹开晚色明。
雅容看更澈，余响扣弥清。
自与琼瑶比，方随掌握荣。
因知君有用，高价伫连城。','',''),('quantangshi-24899','省试吴宫教美人战','葉季良','quantangshi','','卷25','强吴矜霸略，讲武在深宫。
尽出娇娥妓，先观上将风。
挥戈罗袖卷，擐甲汗妆红。
掩笑分旗下，含羞入队中。
鼓停行未正，刑举令才崇。
自可威隣国，何劳逞战功。','',''),('quantangshi-24900','题历山司徒右长史祖宅','湛賁','quantangshi','','卷25','隳官长史籍，高步历山椒。
丽句传黄绢，香名播宋朝。
分能知止足，迹贵出尘嚣。
松竹心长固，池台兴自饶。
龙宫欣访旧，莺谷忝迁乔。
从事叨承乏，铜章愧在腰。','',''),('quantangshi-24901','伏览吕侍郎丘员外旧题十三代祖历山草堂诗因书记事','湛賁','quantangshi','','卷25','名遂贵知己，道胜方晦迹。
高居葺莲宫，遗文焕石壁。
桑田代已变，池草春犹碧。
识曲遇周郎，知音荷宗伯。
调逸南平兆，风清建安迹。
祖德今发扬，还同书史册。','',''),('quantangshi-24902','别慧山书堂','湛賁','quantangshi','','卷25','卷帘晓望云平槛，下榻宵吟月半窗。
病守未能依结社，更施何术去为邦。','',''),('quantangshi-24903','暮春自南台丞再除给事中','薛存誠','quantangshi','','卷25','再入青锁闱，忝官诚自非。
拂尘惊物在，开户似僧归。
积草渐无迳，残花犹洒衣。
禁垣偏日近，行坐是恩辉。','',''),('quantangshi-24904','御制段太尉碑','薛存誠','quantangshi','','卷25','葬仪从俭礼，刊石荷尧君。
露迹垂繁字，天哀洒丽文。
诏深荣嗣子，海变记孤坟。
宝思皆涵象，皇心永念勋。
雅词黄绢妙，渥泽紫泥分。
青史应同久，芳名万古闻。','',''),('quantangshi-24905','御题国子监门','薛存誠','quantangshi','','卷25','宸翰符玄造，荣题国子门。
笔锋回日月，字势动干坤。
檐下云光绝，梁间鹊影飜。
张英圣莫拟，索靖妙难言。
为着盘龙迹，能彰舞凤蹲。
更随垂露像，常以沐皇恩。','',''),('quantangshi-24906','御箭连中双兔','薛存誠','quantangshi','','卷25','宸游经上苑，羽猎向闲田。
狡兔初迷窟，纤骊讵着鞭。
三驱仍百步，一发遂双连。
影射含霜草，魂消向月弦。
驩声动寒木，喜气满晴天。
那似陈王意，空随乐府篇。','',''),('quantangshi-24907','太学创置石经','薛存誠','quantangshi','','卷25','圣唐复古制，德义功无替。
奥旨悦诗书，遗文分篆隶。
银钩互交映，石壁靡尘翳。
永与干坤期，不逐日月逝。
儒林道益广，学者心弥锐。
从此理化成，恩光遍遐裔。','',''),('quantangshi-24908','观南郊回仗','薛存誠','quantangshi','','卷25','传警千门寂，南郊彩仗回。
但惊龙再见，谁识日双开。
德泽施云雨，恩光变烬灰。
阅兵貔武振，听乐凤皇来。
候刻移宸辇，遵时集观台。
多惭远臣贱，不得礼容陪。','',''),('quantangshi-24909','闻击壤','薛存誠','quantangshi','','卷25','尧年听野老，击壤复何云。
自谓欢由己，宁知德在君。
气平闲易畅，声贺作难分。
耕凿方随日，恩威比望云。
篑桴均下调，和木等南薰。
无落于吾事，谁将帝已闻。','',''),('quantangshi-24910','膏泽多丰年','薛存誠','quantangshi','','卷25','帝德方多泽，莓莓井迳同。
八方甘雨布，四远报年丰。
厫庾千厢在，幽流万壑通。
候时勤稼穑，击壤乐农功。
畎亩人无惰，田庐岁不空。
何须忧伏腊，千载贺尧风。','',''),('quantangshi-24911','东都父老望幸','薛存誠','quantangshi','','卷25','銮舆秦地久，羽卫洛阳空。
彼土虽凭固，兹川乃得中。
龙颜觐白日，鹤发仰清风。
望幸诚逾邈，怀来意不穷。
昔因封泰岳，今伫蹑维嵩。
天地心无异，神只理亦同。
翠华翔渭北，玉检候关东。
众愿其难阻，明君早勒功。','',''),('quantangshi-24912','嵩山望幸','薛存誠','quantangshi','','卷25','峻极位何崇，方知造化功。
降灵逢圣主，望幸表维嵩。
隐映连青壁，嵯峨向碧空。
象车因叶瑞，龙驾愿升中。
万岁声长在，千岩气转雄。
东都歌盛事，西笑伫皇风。','',''),('quantangshi-24913','华清宫望幸','薛存誠','quantangshi','','卷25','骊岫接新丰，岧峣驾碧空。
凿山开秘殿，隐雾蔽仙宫。
绛阙犹栖凤，雕梁尚带虹。
温泉曾浴日，华馆旧迎风。
肃穆瞻云辇，深沉闭绮栊。
东郊望幸处，瑞气霭蒙蒙。','',''),('quantangshi-24914','谒见日将至双阙','薛存誠','quantangshi','','卷25','晓色临双阙，微臣礼位陪。
远惊龙凤覩，谁识冕旒开。
蔼蔼千年盛，颙颙万国来。
天文标日月，时令布云雷。
迥出黄金殿，全分白玉台。
雕虫竟何取，瞻恋不知回。','',''),('quantangshi-24915','南至日隔仗望含元殿炉香','裴次元','quantangshi','','卷25','冕旒初负扆，卉服尽朝天。
阳谷初移日，金炉渐起烟。
芬馨流远近，散漫入貂蝉。
霜仗凝逾白，朱栏映转鲜。
始看浮阙在，稍见逐风迁。
为沐皇家庆，来瞻羽卫前。','',''),('quantangshi-24916','律中应钟','裴次元','quantangshi','','卷25','律穷方数寸，室暗在三重。
伶管灰先动，秦正节已逢。
商声辞玉笛，羽调入金钟。
密叶翻霜彩，轻冰歛水容。
望鸿南去绝，迎气北来浓。
愿托无凋性，寒林自比松。','',''),('quantangshi-24917','赋得亚父碎玉斗','裴次元','quantangshi','','卷25','雄谋竟不决，宝玉将何爱。
倏尔霜刃挥，飒然春冰碎。
飞光动旗帜，散响惊环佩。
霜浓绣帐前，星流锦筵内。
图王业已失，为虏言空悔。
独有青史中，英风冠千载。','',''),('quantangshi-24918','句','裴次元','quantangshi','','卷25','积高依郡城，迥拔凌霄汉。','',''),('quantangshi-24919','并州路','李宣遠','quantangshi','','卷25','秋日并州路，黄榆落故关。
孤城吹角罢，数骑射雕还。
帐幕遥临水，牛羊自下山。
征人正垂泪，烽火起云间。','',''),('quantangshi-24920','近无西耗','李宣遠','quantangshi','','卷25','远戎兵压境，迁客泪横襟。
烽堠惊秦塞，囚居困越吟。
自怜牛马走，未识犬羊心。
一月无消息，西看日又沈。','',''),('quantangshi-24921','曲江亭望慈恩寺杏园花发','李君何','quantangshi','','卷25','春晴凭水轩，仙杏发南园。
开蘂风初晓，浮香景欲暄。
光华临御陌，色相对空门。
野雪遥添净，山烟近借繁。
地闲分鹿苑，景胜类桃源。
况值新晴日，芳枝度彩鸳。','',''),('quantangshi-24922','除夜书情','周弘亮','quantangshi','','卷25','何处风尘岁，云阳古驿前。
三冬不再稔，晓日又明年。
春入江南柳，寒归塞北天。
还伤知候客，花景对韦编。','',''),('quantangshi-24923','曲江亭望慈恩寺杏园花发','周弘亮','quantangshi','','卷25','江亭闲望处，远近见秦源。
古寺迟春景，新花发杏园。
萼中轻蘂密，枝上素姿繁。
拂雨云初起，含风雪欲翻。
容辉明十地，香气遍千门。
愿莫随桃李，芳菲不为言。','',''),('quantangshi-24924','故乡除夜','周弘亮','quantangshi','','卷25','三百六十日云终，故乡还与异乡同。
非唯律变情堪恨，抑亦才疎命未通。
何处夜歌销腊酒，谁家高烛候春风。
诗成始欲吟将看，早是去年牵课中。','',''),('quantangshi-24925','曲江亭望慈恩寺杏园花发','陳翥','quantangshi','','卷25','曲江晴望好，近接梵王家。
十亩开金地，千林发杏花。
映云犹误雪，煦日欲成霞。
紫陌传香远，红泉落影斜。
园中春尚早，亭上路非赊。
芳景堪游处，其如惜物华。','',''),('quantangshi-24926','曲江亭望慈恩寺杏园花发','曹著','quantangshi','','卷25','渚亭临净域，凭望一开轩。
晚日分初地，东风发杏园。
异香飘九陌，丽色映千门。
照灼瑶华散，葳蕤玉露繁。
未教游妓折，乍听早莺喧。
谁复争桃李，含芳自不言。','',''),('quantangshi-24927','鱼上冰','王公亮','quantangshi','','卷25','春生寒气减，稍动久潜鱼。
乍喜东风至，来看曲岸初。
出冰朱鬣见，望日锦鳞舒。
渐觉流澌近，还欣掉尾余。
噞喁情自乐，沿溯意宁疎。
傥得随鲲化，终能上太虚。','',''),('quantangshi-24928','赋得竹箭有筠','張仲方','quantangshi','','卷25','东南生绿竹，独美有筠箭。
枝叶讵曾凋，风霜孰云变。
偏宜林表秀，多向岁寒见。
碧色乍葱茏，清光常蒨练。
皮开凤彩出，节劲龙文现。
爱此守坚贞，含歌属时彦。','',''),('quantangshi-24929','赠毛仙翁','張仲方','quantangshi','','卷25','毛仙翁，毛仙翁，容貌常如二八童。
几岁头梳云鬓绿，无时面带桃花红。
眼前人世阅沧海，肘后药成辞月宫。
方口秀眉编贝齿，瞭然炅炅双瞳子。
芝椿禀气本坚强，龟鹤计年应不死。
四海五山长独游，矜贫傲富欺王侯。
灵通指下甎甓化，瑞气炉中金玉流。
定是烟霞列仙侣，暂来尘俗救危苦。
紫霞妖女琼华飞，秘法虔心传付与。
阴功足，阴功成，羽驾何年归上清。
待我休官了婚嫁，桃源洞里觅仙兄。','',''),('quantangshi-24930','句','張仲方','quantangshi','','卷25','入门池色静，登阁雨声来。','',''),('quantangshi-24931','和白乐天','崔玄亮','quantangshi','','卷25','病余归到洛阳头，拭目开眉见白侯。
凤诏恐君今岁去，龙门欠我旧时游。
几人樽下同歌咏，数盏灯前共献酬。
相对忆刘刘在远，寒宵耿耿梦长洲。','',''),('quantangshi-24932','临终诗','崔玄亮','quantangshi','','卷25','蹔荣蹔悴石敲火，即空即色眼生花。
许时为客今归去，大历元年是我家。','',''),('quantangshi-24933','句','崔玄亮','quantangshi','','卷25','共相呼唤醉归来。','',''),('quantangshi-24934','省试临渊羡鱼','徐牧','quantangshi','','卷25','清泚濯缨处，今来喜一临。
慙无下钓处，空有羡鱼心。
退省时频改，谋身岁屡沈。
鬣成川上媚，网就水宁深。
頳尾临波里，朱须破浪浔。
此时傥不漏，江上免行吟。','',''),('quantangshi-24935','淮南游故居感旧酬西川李尚书德裕','王播','quantangshi','','卷25','昔年献赋去江湄，今日行春到却悲。
三径仅存新竹树，四邻惟见旧孙儿。
壁间潜认偷光处，川上宁忘结网时。
更见桥边记名姓，始知题柱免人嗤。','',''),('quantangshi-24936','题木兰院二首 一','王播','quantangshi','','卷25','三十年前此院游，木兰花发院新修。
如今再到经行处，树老无花僧白头。','',''),('quantangshi-24937','题木兰院二首 二','王播','quantangshi','','卷25','上堂已了各西东，惭愧闍黎饭后钟。
三十年来尘扑面，如今始得碧纱笼。','',''),('quantangshi-24938','上巳接清明游宴','獨孤良弼','quantangshi','','卷25','上巳欢初罢，清明赏又追。
闰年侵旧历，令节并芳时。
细雨莺飞重，春风酒酝迟。
寻花迷白雪，看柳拆青丝。
淑气如相待，天和意为谁。
吁嗟名未立，空咏宴游诗。','',''),('quantangshi-24939','次潭州酬唐侍御姚员外游道林岳麓寺题示','沈傳師','quantangshi','','卷25','承明年老輙自论，乞得湘守东南奔。
为闻楚国富山水，青嶂逦迤僧家园。
含香珥笔皆眷旧，谦抑自忘台省尊。
不令执简候亭馆，直许携手游山樊。
忽惊列岫晓来逼，朔雪洗尽烟岚昏。
碧波回屿三山转，丹槛缭郭千艘屯。
华镳躞蹀绚砂步，大斾彩错辉松门。
樛枝竞骛龙蛇势，折干不灭风霆痕。
相重古殿倚嵓腹，别引新径萦云根。
目伤平楚虞帝魂，情多思远聊开樽。
危弦细管逐歌飘，画鼓绣靴随节飜。
锵金七言凌老杜，入木八法蟠高轩。
嗟余潦倒久不利，忍复感激论元元。','',''),('quantangshi-24940','和李德裕观玉蘂花见怀之作','沈傳師','quantangshi','','卷25','曾对金銮直，同依玉树阴。
雪英飞舞近，烟叶动摇深。
素萼年年密，衰容日日侵。
劳君想华发，近欲不胜簪。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-24941','赠毛仙翁','沈傳師','quantangshi','','卷25','安期何事出云烟，为把仙方与世传。
只向人间称百岁，谁知洞里过千年。
青牛到日迎方朔，丹竈开时共稚川。
更说桃源更深处，异花长占四时天。','',''),('quantangshi-24942','寄大府兄侍史','沈傳師','quantangshi','','卷25','积雪山阴马过难，残更深夜铁衣寒。
将军破了单于阵，更把兵书仔细看。','',''),('quantangshi-24943','蒙泉','沈傳師','quantangshi','','卷25','京路马骎骎，尘劳日向深。
蒙泉聊息驾，可以洗君心。','',''),('quantangshi-24944','春从何处来','白行簡','quantangshi','','卷25','欲识春生处，先从木德来。
入门潜报柳，度岭暗惊梅。
透雪寒光散，消冰水镜开。
晓迎郊骑发，夜逐斗杓回。
淑气空中变，新声雨后催。
偏宜资律吕，应是候阳台。','',''),('quantangshi-24945','贡院楼北新栽小松','白行簡','quantangshi','','卷25','华省春霜曙，楼阴植小松。
移根依厚地，委质别危峰。
北户知犹远，东堂幸见容。
心坚终待鹤，枝嫩未成龙。
夜影看仍薄，朝岚色渐浓。
山苗不可荫，孤直俟秦封。','',''),('quantangshi-24946','金在镕','白行簡','quantangshi','','卷25','巨橐方镕物，洪炉欲范金。
紫光看渐发，赤气望逾深。
焰热晴云变，烟浮昼景阴。
坚刚由我性，鼓铸任君心。
踊跃徒标异，沈潜自可钦。
何当得成器，待叩向知音。','',''),('quantangshi-24947','归马华山','白行簡','quantangshi','','卷25','牧野功成后，周王战马闲。
驱驰休伏皂，饮齕任依山。
逐日朝仍去，随风暮自还。
冰生疑陇坂，叶落似榆关。
躞蹀仙峰下，腾骧渭水湾。
幸逢时偃武，不复鼓鼙间。','',''),('quantangshi-24948','夫子鼓琴得其人','白行簡','quantangshi','','卷25','宣父穷玄奥，师襄授素琴。
稍殊流水引，全辨圣人心。
慕德声逾感，怀人意自深。
泠泠传妙手，摵摵振空林。
促调清风至，操弦白日沈。
曲终情不尽，千古仰知音。','',''),('quantangshi-24949','李都尉重阳日得苏属国书','白行簡','quantangshi','','卷25','降虏意何如，穷荒九月初。
三秋异乡节，一纸故人书。
对酒情无极，开缄思有余。
感时空寂寞，怀旧几踌躇。
雁尽平沙迥，烟销大漠虚。
登台南望处，掩泪对双鱼。','',''),('quantangshi-24950','在巴南望郡南山呈乐天','白行簡','quantangshi','','卷25','临江一嶂白云间，红绿层层锦绣班。
不作巴南天外意，何殊昭应望骊山。','',''),('quantangshi-24951','春云','裴澄','quantangshi','','卷25','漠漠复溶溶，乘春任所从。
映林初展叶，触石未成峰。
旭日消寒翠，晴烟点净容。
霏微将似灭，深浅又如重。
薄彩临溪散，轻阴带雨浓。
空余负樵者，岭上自相逢。','',''),('quantangshi-24952','赋得沽美玉','羅立言','quantangshi','','卷25','谁怜被褐士，怀玉正求沽。
成器终期达，逢时岂见诬。
宝同珠照乘，价重劒论都。
浮彩朝虹满，悬光夜月孤。
几年沦瓦砾，今日出泥涂。
采斵资良匠，无令瑕掩瑜。','',''),('quantangshi-24953','寒食遣怀','張燦','quantangshi','','卷25','繁华泣清露，悄悄落衣巾。
明日逢寒食，春风见故人。
病来羞滞楚，西去欲迷秦。
憔悴此时久，青山归四邻。','',''),('quantangshi-24954','春日山亭','牟融','quantangshi','','卷25','醉来重整华阳巾，搔首惊看白发新。
莫道愁多因病酒，只缘命薄不辞贫。
龙鱼失水难为用，龟玉蒙尘未见珍。
正是圣朝全盛日，讵知林下有闲人。','',''),('quantangshi-24955','寄周韶州','牟融','quantangshi','','卷25','十年学道困穷庐，空有长才重老儒。
功业要当垂永久，利名那得在须臾。
山中荆璞谁知玉，海底骊龙不见珠。
寄语故人休怅怏，古来贤达事多殊。','',''),('quantangshi-24956','秋夜醉归有感而赋','牟融','quantangshi','','卷25','衔杯谁道易更阑，沈醉归来不自欢。
惆怅后时孤劒冷，寂寥无寐一灯残。
竹窗凉雨鸣秋籁，江郭清砧捣夜寒。
多少客怀消不得，临风搔首浩漫漫。','',''),('quantangshi-24957','寄范使君','牟融','quantangshi','','卷25','未秋为别已终秋，咫尺娄江路阻修。
心上惟君知委曲，眼前独我逐漂流。
从来姑息难为好，到底依栖总是诹。
西望家山成浩叹，临风搔首不胜愁。','',''),('quantangshi-24958','送罗约','牟融','quantangshi','','卷25','雨晴江馆柳依依，握手那堪此别离。
独鹤孤琴随远斾，红亭绿酒惜分岐。
月明野店闻鸡早，花暗关城匹马迟。
从夜定知相忆处，东风回首不胜悲。','',''),('quantangshi-24959','题李昭训山水','牟融','quantangshi','','卷25','卜筑藏修地自偏，尊前诗酒集羣贤。
半岩松暝时藏鹤，一枕秋声夜听泉。
风月谩劳酬逸兴，渔樵随处度流年。
南州人物依然在，山水幽居胜辋川。','',''),('quantangshi-24960','处厚游杭作诗寄之','牟融','quantangshi','','卷25','江村摇落暂逢秋，况是闻君独远游。
浙水风烟思吊古，楚乡人物赋登楼。
书沈寒雁云边影，梦绕清猨月下愁。
念我故人劳碌久，不如投老卧沧洲。','',''),('quantangshi-24961','山中有怀李十二','牟融','quantangshi','','卷25','林前风景晚苍苍，林下怀人路杳茫。
白发流年淹旧业，碧山茅屋卧斜阳。
客边秋兴悲张翰，病里春情笑沈郎。
何事登楼□□□，几回搔首□思归。','',''),('quantangshi-24962','客中作','牟融','quantangshi','','卷25','异乡岁晚怅离怀，游子驱驰愧不才。
夜夜砧声催客去，年年雁影带寒来。
半林残叶迎霜落，三径黄花近节开。
几度无聊倍惆怅，临风搔首独兴哀。','',''),('quantangshi-24963','山寺律僧画兰竹图','牟融','quantangshi','','卷25','偶来绝顶兴无穷，独有山僧笔最工。
绿径日长袁户在，紫荃秋晚谢庭空。
离花影度湘江月，遗佩香生洛浦风。
欲结岁寒盟不去，忘机相对画图中。','',''),('quantangshi-24964','送客之杭','牟融','quantangshi','','卷25','西风吹[冷]透貂裘，行色匆匆不暂留。
帆带夕阳投越浦，心随明月到杭州。
风清听漏惊乡梦，灯下闻歌乱别愁。
悬想到杭州兴地，尊前应与话离忧。','',''),('quantangshi-24965','有感二首 一','牟融','quantangshi','','卷25','何事离怀入梦频，贫居寂莫四无邻。
诗因韵险难成律，酒为愁多不顾身。
眼底故人惊岁别，尊前华发逐时新。
十年飘泊如萍迹，一度登临一怅神。','',''),('quantangshi-24966','有感二首 二','牟融','quantangshi','','卷25','搔首临风独倚栏，客边惊觉岁华残。
栖迟未遇常鋾荐，邂逅宁弹贡禹冠。
有兴不愁诗韵险，无聊只怕酒杯干。
何如日日长如醉，付与诗人一笑看。','',''),('quantangshi-24967','送沈侯之京','牟融','quantangshi','','卷25','悠悠旌斾出东楼，特出仙郎上帝州。
刘旻才高能富国，萧何人杰足封侯。
关河弱柳垂金缕，水驿青帘拂画楼。
欲尽故人尊酒意，春风江上暂停舟。','',''),('quantangshi-24968','寄羽士','牟融','quantangshi','','卷25','别来有路隔仙凡，几度临风欲去难。
乐道无时忘鹤伴，谈玄何日到星坛。
山中胜景常留客，林下清风好炼丹。
使我浮生尘鞅脱，相从应得一盘桓。','',''),('quantangshi-24969','题赵支','牟融','quantangshi','','卷25','林间曲径掩衡茅，遶屋青青翡翠梢。
一枕秋声鸾舞月，半窗云影鹤归巢。
曾闻贾谊陈奇策，肯学杨雄赋解嘲。
我有清风高节在，知君不负岁寒交。','',''),('quantangshi-24970','司马迁墓','牟融','quantangshi','','卷25','落落长才负不羁，中原回首益堪悲。
英雄此日谁能荐，声价当时众所推。
一代高风留异国，百年遗迹剩残碑。
经过词客空惆怅，落日寒烟赋黍离。','',''),('quantangshi-24971','春游','牟融','quantangshi','','卷25','锦袍日暖耀冰蚕，上客陪游酒半酣。
笑拂吟鞭邀好兴，醉欹乌帽逞雄谈。
楼前弱柳摇金缕，林外遥山隔翠岚。
正是太平行乐处，春风花下且停骖。','',''),('quantangshi-24972','水西草堂','牟融','quantangshi','','卷25','萝径萧然曲业存，闲云流水四无邻。
身留白屋潜踪迹，门□□吟学隐沦。
吟对琴尊江上月，笑看花木镜中春。
遗书自有亲□处，何必驱驰扰世尘。','',''),('quantangshi-24973','送羽衣之京','牟融','quantangshi','','卷25','羽衣缥缈拂尘嚣，怅别河梁赠柳条。
阆苑云深孤鹤逈，蓬莱天近一身遥。
香浮宝辇仙风润，花落瑶坛绛雨消。
自是长生林下客，也陪鸳鹭入清朝。','',''),('quantangshi-24974','题道院壁','牟融','quantangshi','','卷25','山中旧宅四无邻，草净云和逈绝尘。
神枣胡麻能饭客，桃花流水荫通津。
星坛火伏烟霞暝，林壑春香鸟雀驯。
若使凡缘终可脱，也应从此度闲身。','',''),('quantangshi-24975','赠欧阳詹','牟融','quantangshi','','卷25','为客囊无季子金，半生踪迹任浮沈。
服勤因念劬劳重，思养徒怀感慨深。
岛外断云凝远日，天涯芳草动愁心。
家林千里遥相忆，几度停车一怅吟。','',''),('quantangshi-24976','邵公母','牟融','quantangshi','','卷25','搔首惊闻楚些歌，拂衣归去泪悬河。
劬劳常想三春恨，思养其如寸草何。
淛水梦怀千里远，苏台愁望白云多。
伤心独有黄堂客，几度临风咏蓼莪。','',''),('quantangshi-24977','客中作','牟融','quantangshi','','卷25','千里云山恋旧游，寒窗凉雨夜悠悠。
浮亭花竹频劳梦，别路风烟半是愁。
芳草傍人空对酒，流年多病倦登楼。
一杯重向樽前醉，莫遣相思累白头。','',''),('quantangshi-24978','赠杨处厚','牟融','quantangshi','','卷25','十年学道苦劳神，赢得尊前一病身。
天上故人皆自贵，山中明月独相亲。
客心淡泊偏宜静，吾道从容不厌贫。
几度临风一回首，笑看华发及时新。','',''),('quantangshi-24979','重赠张籍','牟融','quantangshi','','卷25','旧日仪容只宛然，笑谈不觉度流年。
凡缘未了嗟无子，薄命能孤不怨天。
一醉便同尘外客，百杯疑是酒中仙。
人生随处堪为乐，管甚秋香满鬓边。','',''),('quantangshi-24980','赠殷以道','牟融','quantangshi','','卷25','世路红尘懒步趋，长年结屋傍岩隅。
独留乡井诚非隐，老向山林不自愚。
肯信白圭终在璞，谁怜沧海竟遗珠。
闲来抚景穷吟处，尊酒临风不自娱。','',''),('quantangshi-24981','翁母些','牟融','quantangshi','','卷25','满头华发向人垂，长逝音容逈莫追。
先壠每怀风木夜，画堂无复彩衣时。
停车遥望孤云影，翘首惊看吊鹤悲。
独有贤人崇孝义，伤心共咏蓼莪诗。','',''),('quantangshi-24982','题山庄','牟融','quantangshi','','卷25','萝屋萧萧事事幽，临风搔首远凝眸。
东园松菊存遗业，晚景桑榆乐旧游。
吟对清尊江上月，笑谈华发镜中秋。
牀头浊酒时时漉，上客相过一任留。','',''),('quantangshi-24983','沈存尚林亭夜宴','牟融','quantangshi','','卷25','草堂寂寂景偏幽，到此令人一纵眸。
松菊寒香三径晚，桑榆烟景两淮秋。
近山红叶堆林屋，隔浦青帘拂画楼。
终日忘情能自乐，清尊应得遣闲愁。','',''),('quantangshi-24984','题孙君山亭','牟融','quantangshi','','卷25','长年乐道远尘氛，静筑藏修学隐沦。
吟对琴樽庭下月，笑看花木槛前春。
闲来欲着登山屐，醉里还披漉酒巾。
林壑能忘轩冕贵，白云黄鹤好相亲。','',''),('quantangshi-24985','题徐俞山居','牟融','quantangshi','','卷25','青山重叠巧裁攒，引水流泉夜激湍。
岚锁岩扉清昼瞑，云归松壑翠阴寒。
不因李相门前见，曾向袁生画里看。
老我不堪诗思杳，几回吟倚曲栏干。','',''),('quantangshi-24986','送范启东还京','牟融','quantangshi','','卷25','萧萧行李上征鞍，满目离情欲去难。
客里故人尊酒别，天涯游子弊裘寒。
官桥杨柳和愁折，驿路梅花带雪看。
重到京华旧游处，春风佳丽好盘桓。','',''),('quantangshi-24987','楼城叙别','牟融','quantangshi','','卷25','故人为客上神州，倾盖相逢感昔游。
屈指年华嗟远别，对牀风雨话离愁。
清樽不负花前约，白发惊看镜里秋。
此际那堪重分手，缘波芳草暂停舟。','',''),('quantangshi-24988','写意二首 一','牟融','quantangshi','','卷25','寂寥荒馆闭闲门，苔径阴阴屐少痕。
白发颠狂尘梦断，青毡泠落客心存。
高山流水琴三弄，明月清风酒一樽。
醉后曲肱林下卧，此生荣辱不须论。','',''),('quantangshi-24989','写意二首 二','牟融','quantangshi','','卷25','萧萧华发满头生，深远蓬门倦送迎。
独喜冥心无外慕，自怜知命不求荣。
闲情欲赋思陶令，卧病和人问马卿。
林下贫居甘困守，尽教城市不知名。','',''),('quantangshi-24990','赠浙西李相公','牟融','quantangshi','','卷25','长庚烈烈独遥天，盛世应知降谪仙。
月里昔曾分兔药，人间今喜得椿年。
文章政事追先达，冠盖声华羡昔贤。
尊酒与君称寿毕，春风入醉绮罗筵。','',''),('quantangshi-24991','天台','牟融','quantangshi','','卷25','碧溪流水泛桃花，树绕天台逈不赊。
洞里无尘通客境，人间有路入仙家。
鸡鸣犬吠三山近，草静云和一径斜。
此地不知何处去，暂留琼佩卧烟霞。','',''),('quantangshi-24992','送陈衡','牟融','quantangshi','','卷25','秋江烟景晚苍苍，江上离人促去航。
千里一官嗟独往，十年双髩付三霜。
云迷楼曲亲庭远，梦遶通山客路长。
不必临风悲冷落，古来白首尚为郎。','',''),('quantangshi-24993','送沈翔','牟融','quantangshi','','卷25','江上西风一棹归，故人此别会应稀。
清朝尽道无遗逸，当路谁曾访少微。
谩有才华嗟未达，闲寻鸥鸟暂忘机。
临岐不用空惆怅，未必新丰老布衣。','',''),('quantangshi-24994','过蠡湖','牟融','quantangshi','','卷25','东湖烟水浩漫漫，湘浦秋声入夜寒。
风外暗香飘落粉，月中清影无离鸾。
多情袁尹频移席，有道乔仙独倚阑。
几度篝帘相对处，无边诗思到吟坛。','',''),('quantangshi-24995','登环翠楼','牟融','quantangshi','','卷25','山中地僻好藏修，寂寂幽居架小楼。
云树四围当户瞑，烟岚一带隔帘浮。
举杯对月邀诗兴，抚景令人豁醉眸。
我亦人间肥遁客，也将踪迹寄林丘。','',''),('quantangshi-24996','游淮云寺','牟融','quantangshi','','卷25','白云深锁沃州山，冠盖登临众仰攀。
松径风清闻鹤唳，昙花香瞑见僧还。
玄机隐隐应难觉，尘事悠悠了不关。
兴尽凡缘因未晚，裴回依旧到人间。','',''),('quantangshi-24997','游报本寺 一','牟融','quantangshi','','卷25','山房寂寂荜门开，此日相期社友来。
雅兴共寻方外乐，新诗争羡郢中才。
茶烟褭褭笼禅榻，竹影萧萧扫径苔。
醉后不知明月上，狂歌直到夜深回。','',''),('quantangshi-24998','游报本寺 二','牟融','quantangshi','','卷25','了然尘事不相关，锡杖时时独看山。
白发任教双鬓改，黄金难买一生闲。
不留活计存囊底，赢得诗名满世间。
自笑微躯长碌碌，几时来此学无还。','',''),('quantangshi-24999','题陈侯竹亭','牟融','quantangshi','','卷25','曾向幽亭一榻分，清风满座绝尘氛。
丹山凤泣钩帘听，沧海龙吟对酒闻。
漠漠瞑阴笼砌月，盈盈寒翠动湘云。
岁寒高节谁能识，独有王猷爱此君。','',''),('quantangshi-25000','送报本寺分韵得通字','牟融','quantangshi','','卷25','几度乘闲谒梵宫，此郎声价重江东。
贵侯知重曾忘势，闲客频来也悟空。
满地新蔬和雨绿，半林残叶带霜红。
□□□□□□□，□□□□□□□。','',''),('quantangshi-25001','寄永平友人 一','牟融','quantangshi','','卷25','故人千里隔天涯，几度临风动远思。
贾谊上书曾伏阙，仲舒陈策欲匡时。
高风落落谁同调，往事悠悠我独悲。
何日归来话畴昔，一樽重叙旧襟期。','',''),('quantangshi-25002','寄永平友人 二','牟融','quantangshi','','卷25','朔风猎猎惨寒沙，关月寥寥咽暮笳。
放逐一心终去国，驱驰千里未还家。
青蝇点玉原非病，沧海遗珠世所嗟。
直道未容淹屈久，暂劳踪迹寄天涯。','',''),('quantangshi-25003','陈使君山庄','牟融','quantangshi','','卷25','新卜幽居地自偏，士林争羡使君贤。
数椽潇洒临溪屋，十亩膏腴附郭田。
流水断桥芳草路，淡烟疎雨落花天。
秋成准拟重来此，沈醉何妨一榻眠。','',''),('quantangshi-25004','题寺壁','牟融','quantangshi','','卷25','僧家胜景瞰平川，雾重岚深马不前。
宛转数声花外鸟，往来几叶渡头船。
青山远隔红尘路，碧殿深笼绿树烟。
闻道此中堪遁迹，肯容一榻学逃禅。','',''),('quantangshi-25005','送徐浩','牟融','quantangshi','','卷25','渡口潮平促去舟，莫辞尊酒暂相留。
弟兄聚散云边雁，踪迹浮沈水上鸥。
千里好山青入楚，几家深树碧藏楼。
知君此去情偏切，堂上椿萱雪满头。','',''),('quantangshi-25006','谢惠劒','牟融','quantangshi','','卷25','感君三尺铁，挥攉鬼神惊。
浩气中心发，雄风两腋生。
犬戎从此灭，巢穴不时平。
万里横行去，封侯赖有成。','',''),('quantangshi-25007','送僧','牟融','quantangshi','','卷25','梵王生别思，之子事遐征。
烟水浮杯渡，云山只履行。
三生尘梦醒，一锡衲衣轻。
此去家林近，飘飘物外情。','',''),('quantangshi-25008','送友人','牟融','quantangshi','','卷25','有客棹扁舟，相逢不暂留。
衣冠重文物，诗酒足风流。
官路生归兴，家林想旧游。
临岐分手后，乘月过苏州。','',''),('quantangshi-25009','题朱庆余闲居四首 一','牟融','quantangshi','','卷25','潇洒藏修处，琴书与画图。
白丁门外远，俗子眼前无。
楚楚临轩竹，青青映水蒲。
道人能爱静，诸事近清枯。','',''),('quantangshi-25010','题朱庆余闲居四首 二','牟融','quantangshi','','卷25','尽日衡门闭，苍苔一径新。
客心非厌静，悟道不忧贫。
白屋悬尘榻，清樽忆故人。
近来疎懒甚，诗债后吟身。','',''),('quantangshi-25011','题朱庆余闲居四首 三','牟融','quantangshi','','卷25','闲客幽栖处，潇然一草庐。
路通元亮宅，门对子云居。
按劒心犹壮，琴书乐有余。
黄金都散尽，收得邺侯书。','',''),('quantangshi-25012','题朱庆余闲居四首 四','牟融','quantangshi','','卷25','寂寥荒馆下，投老欲何为。
草色凝陈榻，书声出董帷。
闲云长作伴，归鹤独相随。
才薄知无用，安贫不自危。','',''),('quantangshi-25013','寄张源','牟融','quantangshi','','卷25','咫尺西江路，悲欢暂莫闻。
青年俱未达，白社独离羣。
曲径荒秋草，衡茅掩夕曛。
相思不相见，愁绝赋停云。','',''),('quantangshi-25014','题竹','牟融','quantangshi','','卷26','潇洒碧玉枝，清风追晋贤。
数点渭川雨，一缕湘江烟。
不见凤皇尾，谁识珊瑚鞭。
柯亭丁相遇，惊听奏钧天。','',''),('quantangshi-25015','有感','牟融','quantangshi','','卷26','盛世嗟沈伏，中情怏未舒。
途穷悲阮籍，病久忆相如。
无客空尘榻，闲门闭草庐。
不胜岑绝处，高卧半牀书。','',''),('quantangshi-25016','题山房壁','牟融','quantangshi','','卷26','珠林春寂寂，宝地夜沈沈。
玄奥凝神久，禅机入妙深。
参同大块理，窥测至人心。
定处波罗蜜，须从物外寻。','',''),('quantangshi-25017','访请上人','牟融','quantangshi','','卷26','曲径遶丛林，钟声杂梵音。
松风吹定衲，萝月照禅心。
抚景吟行远，谈玄入悟深。
不能尘鞅脱，聊复一登临。','',''),('quantangshi-25018','送范启东','牟融','quantangshi','','卷26','杨柳春江上，东风一棹轻。
行囊归客兴，尊酒故人情。
画史名当代，声华重两京。
临岐分手处，无奈别离生。','',''),('quantangshi-25019','客中作','牟融','quantangshi','','卷26','十年江汉客，几度帝京游。
迹比风前叶，身如水上鸥。
醉吟愁里月，羞对镜中秋。
怅望频回首，西风忆故丘。','',''),('quantangshi-25020','赠韩翃','牟融','quantangshi','','卷26','京国久知名，江河近识荆。
不辞今日醉，便有故人情。
细雨孤鸿远，西风一棹轻。
暂时分手去，应不负诗盟。','',''),('quantangshi-25021','禁烟作','牟融','quantangshi','','卷26','柳拖金缕拂朱栏，花扑香尘满绣鞍。
尊酒临风酬令节，越罗衣薄觉春寒。','',''),('quantangshi-25022','闽中回','牟融','quantangshi','','卷26','帆影随风过富阳，橹声摇月下钱塘。
千山积雪凝寒碧，梦入枫宸遶御牀。','',''),('quantangshi-25023','苦妇词','劉言史','quantangshi','','卷26','地远易骄崇，用刑匪精研。
哀哉苦妇身，夫死百殃缠。
草草催出门，衣堕发披肩。
独随军吏行，当夕余欲迁。
来时已厌生，到此自不全。
临江卧黄砂，二子死在边。
气哕不发声，背头血涓涓。
有时强为言，祗是尤青天。
藳蓐无一枝，冷气两悬悬。
穷荒夷教卑，骨肉病弃捐。
况非本族音，肌露谁为怜。
事痛感行宾，住得贪程船。
必当负严法，岂有胎孕篇。
游畋复释麛，羔兔尚免鹯。
何处摈逐深，一罪三见颠。
校尉勋望重，幕府才且贤。
兰裙间珠履，食玉处花筵。
但勿轻所暗，莫虑无人焉。','',''),('quantangshi-25024','与孟郊洛北野泉上煎茶','劉言史','quantangshi','','卷26','粉细越笋芽，野煎寒溪滨。
恐乖灵草性，触事皆手亲。
敲石取鲜火，撇泉避腥鳞。
荧荧爨风铛，拾得坠巢薪。
洁色既爽别，浮氲亦殷勤。
以兹委曲静，求得正味真。
宛如摘山时，自歠指下春。
湘瓷泛轻花，涤尽昏渴神。
此游惬醒趣，可以话高人。','',''),('quantangshi-25025','七夕歌','劉言史','quantangshi','','卷26','星寥寥兮月细轮，佳期可想兮不可亲。
云衣香薄妆态新，彩軿悠悠度天津。
玉幌相逢夜将极，妖红惨黛生愁色。
寂寞低容入旧机，歇着金梭思往夕。
人间不见因谁知，万家闺艳求此时。
碧空露重彩盘湿，花上乞得蜘蛛丝。','',''),('quantangshi-25026','立秋日','劉言史','quantangshi','','卷26','商风动叶初，萧索一贫居。
老性容茶少，羸肌与簟疎。
旧醅难重漉，新菜未胜鉏。
才薄无潘兴，便便画偃庐。','',''),('quantangshi-25027','题茅山仙台药院','劉言史','quantangshi','','卷26','扰扰浮生外，华阳一洞春。
道书金字小，仙圃玉苗新。
芝草迎飞燕，桃花笑俗人。
楼台争耸汉，鸡犬亦嫌秦。
愿得青芽散，长年驻此身。','',''),('quantangshi-25028','送婆罗门归本国','劉言史','quantangshi','','卷26','刹利王孙字迦摄，竹锥横写叱萝叶。
遥知汉地未有经，手牵白马遶天行。
龟兹碛西胡雪黑，大师冻死来不得。
地尽年深始到船，海里更行三十国。
行多耳断金环落，冉冉悠悠不停脚。
马死经留却去时，往来应尽一生期。
出漠独行人绝处，碛西天漏雨丝丝。','',''),('quantangshi-25029','潇湘游','劉言史','quantangshi','','卷26','夷女采山蕉，缉纱浸江水。
野花满髻妆色新，闲歌[唉]乃深峡里。
[唉]乃知从何处生，当时泣舜肠断声。
翠华寂寞婵娟没，野筱空余红泪情。
青烟冥冥覆杉桂，崖壁凌天风雨细。
昔人幽恨此地遗，绿芳红艳含怨姿。
清猨未尽鼯鼠切，泪水流到湘妃祠。
北人莫作潇湘游，九疑云入苍梧愁。','',''),('quantangshi-25030','放萤怨','劉言史','quantangshi','','卷26','放萤去，不须留，聚时年少今白头。
架中科斗万余卷，一字千回重照见。
青云杳渺不可亲，开囊欲放增余怨。
且逍遥，还酩酊，仲舒漫不窥园井。
那将寂寞老病身，更就微虫借光影。
欲放时，泪沾裳，冲篱落，千点光。','',''),('quantangshi-25031','观绳伎','劉言史','quantangshi','','卷26','泰陵遗乐何最珍，彩绳冉冉天仙人。
广场寒食风日好，百夫伐鼓锦臂新。
银画青绡抹云发，高处绮罗香更切。
重肩接立三四层，着屐背行仍应节。
两边丸劒渐相迎，侧身交步何轻盈。
闪然欲落却收得，万人肉上寒毛生。
危机险势无不有，倒挂纤腰学垂柳。
下来一一芙蓉姿，粉薄钿稀态转奇。
坐中还有沾巾者，曾见先皇初教时。','',''),('quantangshi-25032','买花谣','劉言史','quantangshi','','卷26','杜陵村人不田穑，入谷经溪复缘壁。
每至南山草木春，即向侯家取金碧。
幽艳凝华春景曙，林夫移得将何处。
蝶惜芳丛送下山，寻断孤香始回去。
豪少居连鳷鹊东，千金使买一株红。
院多花少栽未得，零落绿娥纤指中。
咸阳亲戚长安里，无限将金买花子。
浇红湿绿千万家，青丝玉轳声哑哑。','',''),('quantangshi-25033','王中丞宅夜观舞胡腾','劉言史','quantangshi','','卷26','石国胡儿人见少，蹲舞尊前急如鸟。
织成蕃帽虚顶尖，细氎胡衫双袖小。
手中抛下蒲萄盏，西顾忽思乡路远。
跳身转毂宝带鸣，弄脚缤纷锦靴软。
四座无言皆瞪目，横笛琵琶徧头促。
乱腾新毯雪朱毛，傍拂轻花下红烛。
酒阑舞罢丝管绝，木槿花西见残月。','',''),('quantangshi-25034','竹里梅','劉言史','quantangshi','','卷26','竹里梅花相竝枝，梅花正发竹枝垂。
风吹总向竹枝上，直似王家雪下时。','',''),('quantangshi-25035','春过赵墟','劉言史','quantangshi','','卷26','下马邯郸陌头歇，寂寥崩隧临车辙。
古柏重生枝亦干，余燎见风幽焰灭。
白蒿微发紫槿新，行人感此复悲春。','',''),('quantangshi-25036','初下东周赠孟郊','劉言史','quantangshi','','卷26','鹤老身更昂，龟死壳亦灵。
正信非外沿，终始全本情。
童子不戏尘，积书就岩扃。
身着木叶衣，养鹿兼牸耕。
偶随下山云，荏苒失故程。
渐入机险中，危思难太行。
十发九缕丝，悠然东周城。
言词野麋态，出口多累形。
因依汉元寮，未思羇细轻。
[冷]竈助新热，静砧与寒声。
断蓬在门栏，岂当桃李荣。
寄食若蠹虫，侵损利微生。
固非拙为强，懦劣外疗并。
素坚冰蘖心，洁持保坚贞。
修文返正风，刊字齐古经。
慙将衰末分，高栖喧世名。','',''),('quantangshi-25037','过春秋峡','劉言史','quantangshi','','卷26','峭壁苍苍苔色新，无风晴景自胜春。
不知何树幽崖里，腊月开花似北人。','',''),('quantangshi-25038','长门怨','劉言史','quantangshi','','卷26','独坐炉边结夜愁，暂时思去亦难留。
手持金筯垂红泪，乱拨寒灰不举头。','',''),('quantangshi-25039','春游曲 一','劉言史','quantangshi','','卷26','花颔红鬃一何偏，绿槐香陌欲朝天。
仍嫌众里娇行疾，傍𩍐深藏白玉鞭。','',''),('quantangshi-25040','春游曲 二','劉言史','quantangshi','','卷26','喷沫团香小桂条，玉鞭兼赐霍嫖姚。
弄影便从天禁出，碧蹄声碎五门桥。','',''),('quantangshi-25041','广州王园寺伏日即事寄北中亲友','劉言史','quantangshi','','卷26','南越逢初伏，东林度一朝。
曲池煎畏景，高阁绝微飇。
竹簟移先洒，蒲葵破复摇。
地偏毛瘴近，山毒火威饶。
裛汗絺如濯，亲牀枕竝烧。
堕枝伤翠羽，萎叶惜红蕉。
且困流金炽，难成独酌谣。
望霖窥润础，思吹候生条。
旅恨生乌浒，乡心系洛桥。
谁怜在炎客，一夕壮容销。','',''),('quantangshi-25042','立秋','劉言史','quantangshi','','卷26','兹晨戒流火，商飇早已惊。
云天收夏色，木叶动秋声。','',''),('quantangshi-25043','别落花','劉言史','quantangshi','','卷26','风艳霏霏去，羁人处处游。
明年纵相见，不在此枝头。','',''),('quantangshi-25044','登甘露台','劉言史','quantangshi','','卷26','偶至无尘空翠间，雨花甘露境闲闲。
身心未寂终为累，非想天中独退还。','',''),('quantangshi-25045','夜泊润州江口','劉言史','quantangshi','','卷26','秋江欲起白头波，贾客瞻风无渡河。
