年年此树花开日，出尽丹阳郭里人。','',''),('quantangshi-25047','看山木瓜花二首 二','劉言史','quantangshi','','卷26','柔枝湿艳亚朱栏，暂作庭芳便欲残。
深藏数片将归去，红缕金针绣取看。','',''),('quantangshi-25048','题十三弟竹园','劉言史','quantangshi','','卷26','绕屋扶疎耸翠茎，苔滋粉漾有幽情。
