梦中无限风流事，夫壻多情亦未知。','',''),('quantangshi-25052','岁暮题杨录事江亭','劉言史','quantangshi','','卷26','垂丝蜀客涕濡衣，岁尽长沙未得归。
肠断锦帆风日好，可怜桐鸟出花飞。','',''),('quantangshi-25053','冬日峡中旅泊','劉言史','quantangshi','','卷26','霜月明明雪复残，孤舟夜泊使君滩。
一声钟出远山里，暗想雪窗僧起寒。','',''),('quantangshi-25054','泊花石浦','劉言史','quantangshi','','卷26','旧业丛台废苑东，几年为梗复为蓬。
