空留梲杖犊鼻褌，蒙蒙烟雨归山村。','',''),('quantangshi-25098','北原情三首 一','劉言史','quantangshi','','卷26','错莫天色愁，挽歌出重闉。
谁家白网车，送客入幽尘。
