列纸泻壶浆，空向春云哭。','',''),('quantangshi-25101','林中独醒','劉言史','quantangshi','','卷26','晚来林沼静，独坐间瓢尊。
向己非前迹，齐心欲不言。
微凉生乱筱，轻馥起孤萱。
未得浑无事，瓜田草正繁。','',''),('quantangshi-25102','江陵客舍留别樊尚书','劉言史','quantangshi','','卷26','信陵门馆下，多病有归思。
坠履忘情后，寒灰更湿时。
委栏芳蕙晚，凭几雪髫垂。
明日秋关外，单车风雨随。','',''),('quantangshi-25103','拟古咏河边枯树','長孫佐輔','quantangshi','','卷26','野火烧枝水洗根，数围孤树半心存。
应是无机承雨露，却将春色寄苔痕。','',''),('quantangshi-25104','别友人','長孫佐輔','quantangshi','','卷26','愁多不忍醒时别，想极还寻静处行。
谁遣同衾又分手，不如行路本无情。','',''),('quantangshi-25105','伤故人歌妓','長孫佐輔','quantangshi','','卷26','愁脸无红衣满尘，万家门户不容身。
曾将一笑君前去，悞杀几多回顾人。','',''),('quantangshi-25106','南中客舍对雨送故人归北','長孫佐輔','quantangshi','','卷26','猨声啾啾雁声苦，卷帘相对愁不语。
几年客吴君在楚，况送君归我犹阻。
家书作得不忍封，北风吹断堦前雨。','',''),('quantangshi-25107','杭州秋日别故友','長孫佐輔','quantangshi','','卷26','相见又相别，大江秋水深。
悲欢一世事，去住两乡心。
淅沥篱下叶，凄清阶上琴。','',''),('quantangshi-25108','代别后梦别','長孫佐輔','quantangshi','','卷26','别中还梦别，悲后更生悲。
觉梦俱千里，追随难再期。
翻思梦里苦，却恨觉来迟。
纵是非真事，何妨梦会时。','',''),('quantangshi-25109','答边信','長孫佐輔','quantangshi','','卷26','征人去年戍辽水，夜得边书字盈纸。
挥刀就烛裁红绮，结作同心答千里。
君寄边书书莫绝，妾答同心心自结。
同心再解心不离，书字频看字愁灭。
结成一夜和泪封，贮书只在怀袖中。
莫如书字故难久，愿学同心长可同。','',''),('quantangshi-25110','对镜吟','長孫佐輔','quantangshi','','卷26','忆昔逢君新纳娉，青铜铸出千年镜。
意怜光彩固无瑕，义比恩情永相映。
每将鉴面兼鉴心，鉴来不辍情逾深。
君非结心空结带，结处尚新恩已背。
开帘览镜悲难语，对面相看孟门阻。
掩匣徒慙双凤飞，悬台欲效孤鸾舞。
昔日照来人共许，今朝照罢自生疑。
镜上有尘犹可淬，君恩讵肯无回时。','',''),('quantangshi-25111','山行书事','長孫佐輔','quantangshi','','卷26','日落风䬘䬘，驱车行远郊。
中心有所悲，古墓穿黄茅。
茅中狐兔窠，四面乌鸢巢。
鬼火时独出，人烟不相交。
行行近破村，一径欹还坳。
迎霜听蟋蟀，向月看蟏蛸。
翁喜客来至，客来羞厨庖。
浊醪夸泼蚁，时果仍新苞。
相劝对寒灯，呼儿爇枯梢。
性朴颇近古，其言无斗筲。
忧欢世上并，岁月途中抛。
谁知问津客，空作杨雄嘲。','',''),('quantangshi-25112','古宫怨','長孫佐輔','quantangshi','','卷26','窗前好树名玫瑰，去年花落今年开。
无情春色尚识返，君心忽断何时来。
忆昔妆成候仙仗，宫璅玲珑日新上。
拊心却笑西子嚬，掩鼻谁忧郑姬谤。
草染文章衣下履，花黏甲乙牀前帐。
三千玉貌休自夸，十二金钗独相向。
盛衰倾夺欲何如，娇爱翻悲逐佞谀。
重远岂能慙沼鹄，弃前方见泣船鱼。
看笼不记薰龙脑，咏扇空曾秃鼠须。
始喜类萝新托柏，终伤如荠却甘荼。
院深独开还独闭，鹦鹉惊飞苔覆地。
满箱旧赐前日衣，渍枕新垂夜来泪。
痕多开镜照还悲，绿髻青蛾尚未衰。
莫道新缣长绝比，犹逢故劒会相追。','',''),('quantangshi-25113','关山月','長孫佐輔','quantangshi','','卷26','凄凄还切切，戍客多离别。
何处最伤心，关山见秋月。
关月竟如何，由来远近过。
始经玄菟塞，终绕白狼河。
忽忆秦楼妇，流光应共有。
已得并蛾眉，还知揽纤手。
去岁照同行，比翼复连形。
今宵照独立，顾影自茕茕。
余晖渐西落，夜夜看如昨。
借问暎旌旗，何如鉴帷幕。
拂晓朔风悲，蓬惊雁不飞。
几时征戍罢，还向月中归。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-25114','陇西行','長孫佐輔','quantangshi','','卷26','阴云凝朔气，陇上正飞雪。
四月草不生，北风劲如切。
朝来羽书急，夜救长城窟。
道隘行不前，相呼抱鞍歇。
人寒指欲堕，马冻蹄亦裂。
射雁旋充饥，斧冰还止渴。
宁辞解围鬬，但恐乘疲没。
早晚边候空，归来养羸卒。','',''),('quantangshi-25115','寻山家','長孫佐輔','quantangshi','','卷26','独访山家歇还涉，茅屋斜连隔松叶。
主人闻语未开门，绕篱野菜飞黄蝶。','',''),('quantangshi-25116','山居','長孫佐輔','quantangshi','','卷26','看书爱幽寂，结宇青冥间。
飞泉引风听，古桂和云攀。
地深草木稠，境静鱼鸟闲。
阴气晚出谷，朝光先照山。
有时独杖藜，入夜犹启关。
星昏归鸟过，火出樵童还。
神体自和适，不是离人寰。','',''),('quantangshi-25117','楚州盐𡏖古墙望海','長孫佐輔','quantangshi','','卷26','混沌本冥冥，泄为洪川流。
雄哉大造化，万古横中州。
我从西北来，登高望蓬丘。
阴晴乍开合，天地相沈浮。
长风卷繁云，日出扶桑头。
水净露鲛室，烟销凝蜃楼。
时来会云翔，道蹇即津游。
明发促归轸，沧波非宿谋。','',''),('quantangshi-25118','闻韦驸马使君迁拜台州','長孫佐輔','quantangshi','','卷26','溟藩轸帝忧，见说初鸣驺。
德胜祸先戢，情闲思自流。
蚕殷桑柘空，廪实雀鼠稠。
谏虎昔赐骏，安人将问牛。
曾陪后乘光，共逐平津游。
旌斾拥追赏，歌钟催献酬。
音徽一寂寥，贵贱双沈浮。
北郭乏中崖，东方称上头。
跻山望百城，目尽增遐愁。
海逼日月近，天高星汉秋。
无阶异渐鸿，有志慙驯鸥。
终期促孤棹，暂访天台幽。','',''),('quantangshi-25119','山行经村径','長孫佐輔','quantangshi','','卷26','一径有人迹，到来唯数家。
依稀听机杼，寂历看桑麻。
雨湿渡头草，风吹坟上花。
却驱羸马去，数点归林鸦。','',''),('quantangshi-25120','野田行','張碧','quantangshi','','卷26','风昏昼色飞斜雨，冤骨千堆髑髅语。
八纮牢落人物悲，是个田园荒废主。
悲嗟自古争天下，几度干坤复如此。
秦皇矻矻筑长城，汉祖区区白蛇死。
野田之骨兮又成尘，楼阁风烟兮还复新。
愿得华山之下长归马，野田无复堆冤者。','',''),('quantangshi-25121','贫女','張碧','quantangshi','','卷26','岂是昧容华，岂不知机织。
自是生寒门，良媒不相识。','',''),('quantangshi-25122','幽思','張碧','quantangshi','','卷26','金炉烟霭微，锦釭残影灭。
出户独裴回，落花满明月。','',''),('quantangshi-25123','惜花三首 一','張碧','quantangshi','','卷26','千枝万枝占春开，彤霞着地红成堆。
一窖闲愁驱不去，殷勤对尔酌金杯。','',''),('quantangshi-25124','惜花三首 二','張碧','quantangshi','','卷26','老鸦拍翼盘空疾，准拟浮生如瞬息。
阿母蟠桃香未齐，汉皇骨葬秋山碧。','',''),('quantangshi-25125','惜花三首 三','張碧','quantangshi','','卷26','朝开暮落煎人老，无人为报东君道。
留取穠红伴醉吟，莫教少女来吹扫。','',''),('quantangshi-25126','游春引三首 一','張碧','quantangshi','','卷26','句芒爱弄春风权，开萌发翠无党偏。
句芒小女精神巧，机罗杼绮满平川。','',''),('quantangshi-25127','游春引三首 二','張碧','quantangshi','','卷26','五陵年少轻薄客，蛮锦花多春袖窄。
酌桂鸣金翫物华，星蹄绣毂填香陌。','',''),('quantangshi-25128','游春引三首 三','張碧','quantangshi','','卷26','千条碧绿轻拖水，金毛泣怕春江死。
万汇俱含造化恩，见我春工无私理。','',''),('quantangshi-25129','农父','張碧','quantangshi','','卷26','运锄耕斸侵星起，陇亩丰盈满家喜。
到头禾黍属他人，不知何处抛妻子。','',''),('quantangshi-25130','古意','張碧','quantangshi','','卷26','銮舆不碾香尘灭，更残三十六宫月。
手持纨扇独含情，秋风吹落横波血。','',''),('quantangshi-25131','秋日登岳阳楼晴望','張碧','quantangshi','','卷26','三秋倚练飞金盏，洞庭波定平如刬。
天高云卷绿罗低，一点君山碍人眼。
漫漫万顷铺琉璃，烟波阔远无鸟飞。
西南东北竞无际，直疑侵断青天涯。
屈原回日牵愁吟，龙宫感激致应沈。
贾生憔悴说不得，茫茫烟霭堆湖心。','',''),('quantangshi-25132','鸿沟','張碧','quantangshi','','卷26','毒龙衔日天地昏，八纮叆叇生愁云。
秦园走鹿无藏处，纷纷争处蜂成羣。
四溟波立鲸相吞，荡摇五岳崩山根。
鱼虾舞浪狂鳅鲲，龙蛇胆战登鸿门。
星旗羽镞强者尊，黑风白雨东西屯。
山河欲拆人烟分，壮士鼓勇君王存。
项庄愤气吐不得，亚父斗声天上闻。
玉光堕地惊昆仑，留侯气魄吞太华。
舌头一寸生阳春，神农女娲愁不言。
蛇枯老媪啼泪痕，星曹定秤秤王孙。
项籍骨轻迷精魂，沛公仰面争干坤。
须臾垓下贼星起，歌声缭绕凄人耳。
吴娃捧酒横秋波，霜天月照空城垒。
力拔山兮忽到此，骓嘶懒渡乌江水。
新丰瑞色生楼台，西楚寒蒿哭愁鬼。
三尺霜鸣金匣里，神光一掉八千里。
汉皇骤马意气生，西南扫地迎天子。','',''),('quantangshi-25133','美人梳头','張碧','quantangshi','','卷26','玉堂花院小枝红，绿窗一片春光晓。
玉容惊觉浓睡醒，圆蟾挂出妆台表。
金盘解下丛鬟碎，三尺巫云绾朝翠。
皓指高低寸黛愁，水精梳滑参差坠。
须臾拢掠蝉鬓生，玉钗冷透冬冰明。
芙蓉拆向新开脸，秋泉慢转眸波横。
鹦鹉偷来话心曲，屏风半倚遥山绿。','',''),('quantangshi-25134','题祖山人池上怪石','張碧','quantangshi','','卷26','寒姿数片奇突兀，曾作秋江秋水骨。
先生应是厌风云，着向江边塞龙窟。
我来池上倾酒尊，半酣书破青烟痕。
参差翠缕摆不落，笔头惊怪黏秋云。
我闻吴中项容水墨有高价，邀得将来倚松下。
铺却双缯直道难，掉首空归不成画。','',''),('quantangshi-25135','山居雨霁即事','張碧','quantangshi','','卷26','结茅苍岭下，自与喧卑隔。
况值雷雨晴，郊原转岑寂。
出门看反照，绕屋残溜滴。
古路绝人行，荒陂响蝼蝈。
篱崩瓜豆蔓，圃坏牛羊迹。
断续古祠鸦，高低远村笛。
喜闻东臯润，欲往未通屐。
杖策试危桥，攀萝瞰苔壁。
邻翁夜相访，缓酌聊跂石。
新月出污尊，浮云在巾舃。
常隳腐儒操，谬习经邦画。
有待时未知，非关慕沮溺。','',''),('quantangshi-25136','赠琴棋僧歌','張瀛','quantangshi','','卷26','我尝听师法一说，波上莲花水中月。
不垢不净是色空，无法无空亦无灭。
我尝听师禅一观，浪溢鳌头蟾魄满。
河沙世界尽空空，一寸寒灰冷灯畔。
我又听师琴一抚，长松唤住秋山雨。
弦中雅弄若铿金，指下寒泉流太古。
我又听师棋一着，山顶坐沈红日脚。
阿谁称是国手人，罗浮道士赌却鹤。
输却药，法怀斟下红霞丹，束手不敢争头角。','',''),('quantangshi-25137','妾换马','盧殷','quantangshi','','卷26','伴凤楼中妾，如龙枥上宛。
同年辞旧宠，异地受新恩。
香阁更衣处，尘蒙喷草痕。
连嘶将忍泪，俱恋主人门。','',''),('quantangshi-25138','七夕','盧殷','quantangshi','','卷26','河耿月凉时，牵牛织女期。
欢娱方在此，漏刻竟由谁。
定不嫌秋驶，唯当乞夜迟。
全胜客子媍，十载泣生离。','',''),('quantangshi-25139','月夜','盧殷','quantangshi','','卷26','露下凉生簟，无人月满庭。
难闻逆河浪，徒望白榆星。
树遶孤栖鹊，窗飞就暗萤。
移时宿兰影，思共习芳馨。','',''),('quantangshi-25140','仲夏寄江南','盧殷','quantangshi','','卷26','五月行将近，三年客未回。
梦成千里去，酒醒百忧来。
晚暮时看槿，悲酸不食梅。
空将白团扇，从寄复裴回。','',''),('quantangshi-25141','欲销云','盧殷','quantangshi','','卷26','欲隐从龙质，仍余触石文。
霏微依碧落，仿髴悞非云。
度月光无隔，倾河影不分。
如逢作霖处，当为起氤氲。','',''),('quantangshi-25142','遇边使','盧殷','quantangshi','','卷26','累年无的信，每夜梦边城。
袖掩千行泪，书封一尺情。','',''),('quantangshi-25143','移住别居','盧殷','quantangshi','','卷26','自到西川住，唯君别有情。
常逢对门远，又隔一重城。','',''),('quantangshi-25144','堋口逢友人','盧殷','quantangshi','','卷26','艰难别离久，中外往还深。
已改当时法，空余旧日心。','',''),('quantangshi-25145','雨霁登北岸寄友人','盧殷','quantangshi','','卷26','稻黄扑扑黍油油，野树连山涧自流。
忆得年时冯翊部，谢郎相引上楼头。','',''),('quantangshi-25146','长安亲故','盧殷','quantangshi','','卷26','楚兰不佩佩吴钩，带酒城头别旧游。
年事已多筋力在，试将弓箭到并州。','',''),('quantangshi-25147','悲秋','盧殷','quantangshi','','卷26','秋空雁度青天远，疎树蝉嘶白露寒。
阶下败兰犹有气，手中团扇渐无端。','',''),('quantangshi-25148','晚蝉','盧殷','quantangshi','','卷26','深藏高柳背斜晖，能轸孤愁减昔围。
犹畏旅人头不白，再三移树带声飞。','',''),('quantangshi-25149','维扬郡西亭赠友人','盧殷','quantangshi','','卷26','萍飒风池香满船，杨花漠漠暮春天。
玉人此日心中事，何似乘羊入市年。','',''),('quantangshi-25150','终南精舍月中闻磬','獨孤申叔','quantangshi','','卷26','精庐残夜景，天宇灭埃氛。
幽磬此时击，余音几处闻。
随风树杪去，支策月中分。
断绝如残漏，凄清不隔云。
羇人方罢梦，独雁忽迷羣。
响尽河汉落，千山空纠纷。','',''),('quantangshi-25151','题汉州西湖','嚴公弼','quantangshi','','卷26','西湖创置自房公，心匠纵横造化同。
见说凤池推独步，高名何事滞川中。','',''),('quantangshi-25152','题汉州西湖','嚴公貺','quantangshi','','卷26','凤沼才难尽，余思凿西湖。
珍木罗修岸，冰光映坐隅。
琴台今寂寞，竹岛尚萦纡。
犹蕴济川志，芳名终不渝。','',''),('quantangshi-25153','湘弦曲','莊南傑','quantangshi','','卷26','楚云铮铮戛秋露，巫云峡雨飞朝暮。
古磬高敲百尺楼，孤猨夜哭千丈树。
云轩碾火声珑珑，连山卷尽长江空。
莺啼寂寞花枝雨，鬼啸荒郊松柏风。
满堂怨咽悲相续，苦调中含古离曲。
繁弦响绝楚魂遥，湘江水碧湘山绿。','',''),('quantangshi-25154','黄雀行','莊南傑','quantangshi','','卷26','穿屋穿墙不知止，争树争巢入营死。
林间公子夹弹弓，一丸致毙花丛里。
小口黄雏未有知，青天不解高高飞。
虞人设网当要路，白日啾嘲祸万机。','',''),('quantangshi-25155','雁门太守行','莊南傑','quantangshi','','卷26','旌旗闪闪摇天末，长笛横吹虏尘阔。
跨下嘶风白练狞，腰间切玉青蛇活。
击革摐金燧牛尾，犬羊兵败如山死。
九泉寂寞葬秋虫，湿云荒草啼秋思。','',''),('quantangshi-25156','阳春曲','莊南傑','quantangshi','','卷26','紫锦红囊香满风，金鸾玉轼摇丁冬。
沙鸥白羽翦晴碧，野桃红艳烧春空。
芳草緜延鏁平地，壠蝶双双舞幽翠。
凤叶龙吟白日长，落花声底仙娥醉。','',''),('quantangshi-25157','伤歌行','莊南傑','quantangshi','','卷26','兔走乌飞不相见，人事依稀速如电。
王母夭桃一度开，玉楼红粉千回变。
车驰马走咸阳道，石家旧宅空荒草。
秋雨无情不惜花，芙蓉一一惊香倒。
劝君莫谩栽荆棘，秦皇虚费驱山力。
英风一去更无言，白骨沈埋暮山碧。','',''),('quantangshi-25158','无题','李溟','quantangshi','','卷26','乔木挂斗邑，水驿坏门开。
向月片帆去，背云行雁来。
晚年名利迹，宁免路岐哀。
前计不能息，若为玄鬓回。','',''),('quantangshi-25159','客舍喜友人相访','賀蘭朋吉','quantangshi','','卷26','荒居无四隣，谁肯访来频。
