苦心三百首，暂请侍郎看。','',''),('quantangshi-25161','吊灵均','王魯復','quantangshi','','卷26','万古汨罗深，骚人道不沈。
明明唐日月，应见楚臣心。','',''),('quantangshi-25162','吊韩侍郎','王魯復','quantangshi','','卷26','星落少微宫，高人入古风。
