扫坛天地肃，投简鬼神惊。
傥赐刀圭药，还成不死名。','',''),('quantangshi-25234','王仙坛','林傑','quantangshi','','卷26','羽客已登仙路去，丹炉草木尽凋残。
不知千载归何日，空使时人扫旧坛。','',''),('quantangshi-25235','乞巧','林傑','quantangshi','','卷26','七夕今宵看碧霄，牵牛织女渡河桥。
家家乞巧望秋月，穿尽红丝几万条。','',''),('quantangshi-25236','句','林傑','quantangshi','','卷26','金盘摘下挂朱颗，红壳开时饮玉浆。','',''),('quantangshi-25237','哭林杰','鄭立之','quantangshi','','卷26','才高未及贾生年，何事孤魂逐逝川。
萤聚帐中人已去，鹤离台上月空圆。','',''),('quantangshi-25238','咏和亲','蘇郁','quantangshi','','卷26','关月夜悬青冢镜，寒云秋薄汉宫罗。
君王莫信和亲策，生得胡雏虏更多。','',''),('quantangshi-25239','鹦鹉词','蘇郁','quantangshi','','卷26','莫把金笼闭鹦鹉，个个分明解人语。
忽然更向君前言，三十六宫愁几许。','',''),('quantangshi-25240','步虚词','蘇郁','quantangshi','','卷26','十二楼藏玉堞中，凤凰双宿碧芙蓉。
流霞浅酌谁同醉，今夜笙歌第几重。','',''),('quantangshi-25241','句','蘇郁','quantangshi','','卷26','吟倚雨残树，月收山下村。','',''),('quantangshi-25242','赋得琢玉成器','浩虛舟','quantangshi','','卷26','已沐识坚贞，应怜器未成。
辉山方可重，散璞乍堪惊。
玷灭随心正，瑕消夺眼明。
琢磨虹气在，拂拭水容生。
赏翫冰光冷，提携月魄轻。
伫当亲捧握，瑚琏幸齐名。','',''),('quantangshi-25243','责商山四皓','蔡京','quantangshi','','卷26','秦末家家思逐鹿，商山四皓独忘机。
如何鬓发霜相似，更出深山定是非。','',''),('quantangshi-25244','假节邕交道由吴溪','蔡京','quantangshi','','卷26','停桡横水中，举目孤烟外。
借问吴溪人，谁家有山卖。','',''),('quantangshi-25245','咏子规','蔡京','quantangshi','','卷26','千年冤魄化为禽，永逐悲风叫远林。
愁血滴花春艳死，月明飘浪冷光沈。
凝成紫塞风前泪，惊破红楼梦里心。
肠断楚词归不得，劒门迢遰蜀江深。','',''),('quantangshi-25246','献蔡京','張頂','quantangshi','','卷26','抛却长竿卷却丝，手持蓑笠献新诗。
临川太守清如镜，不是渔人下钓时。','',''),('quantangshi-25247','享惠昭太子庙乐章','李逢吉','quantangshi','','卷26','既洁酒醴，聿陈熟腥。
肃将震念，昭格储灵。
展矣礼典，薰然德馨。
愔愔管磬，亦具是听。','',''),('quantangshi-25248','望京楼上寄令狐华州','李逢吉','quantangshi','','卷26','祗役滞南服，颓思属暮年。
闲上望京台，万山蔽其前。
落日归飞翼，连翩东北天。
涪江适在下，为我久潺湲。
中叶成文教，德威清远边。
颁条信徒尔，华发生苍然。
寄怀三峰守，岐路隔云烟。','',''),('quantangshi-25249','再赴襄阳辱宣武相公贻诗今用奉酬','李逢吉','quantangshi','','卷26','解韨辞丹禁，扬旌去赤墀。
自惊非素望，何力及清时。
又据三公席，多慙四老祠。
岘山风已远，棠树事难追。
江汉饶春色，荆蛮足梦思。
唯怜吐凤句，相示凿龙期。','',''),('quantangshi-25250','奉送李相公重镇襄阳','李逢吉','quantangshi','','卷26','海内埏埴徧，汉阴旌斾还。
望留丹阙下，恩在紫霄间。
冰雪背秦岭，风烟经武关。
树皆人尚爱，辕即吏曾攀。
自惜两心合，相看双鬓斑。
终期谢戎务，同隐凿龙山。','',''),('quantangshi-25251','和严揆省中宿斋遇令狐员外当直之作','李逢吉','quantangshi','','卷26','致斋分直宿南宫，越石卢谌此夜同。
位极班行犹念旧，名题章奏亦从公。
曾驱爪士三边静，新赠髯参六义穷。
竟夕文昌知有月，可怜如在庾楼中。','',''),('quantangshi-25252','奉酬忠武李相公见寄','李逢吉','quantangshi','','卷26','直继先朝卫与英，能移孝友作忠贞。
劒门失险曾缚虎，淮水安流缘斩鲸。
黄阁碧幢惟是俭，三公二伯未为荣。
惠连忽赠池塘句，又遣羸师破胆惊。','',''),('quantangshi-25253','酬致政杨祭酒见寄','李逢吉','quantangshi','','卷26','初还相印罢戎旃，获守皇居在紫烟。
妄比酇侯功蔑尔，每怀疏傅意悠然。
应将半俸霑闾里，料入中条访洞天。
十载别离那可道，倍令惊喜见来篇。','',''),('quantangshi-25254','送令狐秀才赴举','李逢吉','quantangshi','','卷26','子有雄文藻思繁，龆年射策向金门。
前随鸾鹤登霄汉，却望风沙走塞垣。
独忆忘机陪出处，自怜何力继飞翻。
那堪两地生离绪，蓬户长扃行旅喧。','',''),('quantangshi-25255','郡斋卧疾赠昼上人','于頔','quantangshi','','卷26','夙陪翰墨徒，深论穷文格。
丽则风骚后，公然我词客。
晚依方外友，极理探精赜。
吻合南北宗，昼公我禅伯。
尤明性不染，故我行贞白。
随顺令得解，故我言芳泽。
霅水漾清浔，吴山横碧岑。
含珠复蕴玉，价重双南金。
的皪曜奇彩，凄清流雅音。
商声发楚调，调切谱瑶琴。
吴山为我高，霅水为我深。
万景徒有象，孤云本无心。
众木岂无声，椅桐有清响。
众耳岂不聆，钟期有真赏。
高洁古人操，素怀夙所仰。
觌君冰雪姿，祛我淫滞想。
常吟柳恽诗，苕浦久相思。
逮此远为郡，苹洲芳草衰。
逢师年腊长，值我病容羸。
共话无生理，聊用契心期。','',''),('quantangshi-25256','和丘员外题湛长史旧居','于頔','quantangshi','','卷26','萧条历山下，水木无氛滓。
王门结长裾，岩扃怡暮齿。
昔贤枕高躅，今彦仰知止。
依依瞩烟霞，眷眷返墟里。
湛生久已没，丘也亦同耻。
立言咸不朽，何必在青史。','',''),('quantangshi-25257','寒夜闻霜钟','盧景亮','quantangshi','','卷26','洪钟发长夜，清响出层岑。
暗入繁霜切，遥传古寺深。
何城乱远漏，几处杂疎砧。
已警离人梦，仍霑旅客襟。
待时当命侣，抱器本无心。
傥若无知者，谁能设此音。','',''),('quantangshi-25258','南溪诗','李渤','quantangshi','','卷26','玄岩丽南溪，新泉发幽色。
岩泉孕灵秀，云烟纷崖壁。
斜峰信天插，奇洞固神辟。
窈窕去未穷，环回势难极。
玉池似无水，玄井昏不测。
仙户掩复开，乳膏凝更滴。
丹砂有遗址，石径无留迹。
南眺苍梧云，北望洞庭客。
萧条风烟外，爽朗形神寂。
若值浮丘翁，从此谢尘役。','',''),('quantangshi-25259','喜弟淑再至为长歌','李渤','quantangshi','','卷26','前年别时秋九月，白露吹霜金吹烈。
离鸿一别影初分，泪袖双挥心哽咽。
别来几度得音书，南岳知□□□□。
庐山峨峨倚天碧，捧排空崖千万尺。
社牓长题高士名，食堂每记云山迹。
我本开云此山住，偶为名利相萦误。
自负心机四十年，羞闻社客山中篇。
忧时魂梦忆归路，觉来疑在林中眠。
昨日亭前乌鹊喜，果得今朝尔来此。
吾吟行路五十篇，尽说江南数千里。
自怜兄弟今五人，共萦儒素家尚贫。
虽然廪饩各不一，就中总免拘常伦。
长兄年少曾落托，拔劒沙场随卫霍。
口里虽谭周孔文，怀中不舍孙吴略。
次兄一生能苦节，夏聚流萤冬映雪。
非论疾恶志如霜，更觉临泉心似铁。
第三之兄更奇异，昂昂独负青云志。
下看金玉不如泥，肯道王侯身可贵。
却愁清逸不干时，高踪大器无人知。
倘逢感激许然诺，必能万古留清规。
念尔年来方二十，夙夜孜孜能独立。
卷中笔落星汉摇，洞里丹灵鬼神泣。
嗟余流浪心最狂，十年学劒逢时康。
心中不解事拘束，世间谈笑多相妨。
广海青山殊未足，逢着高楼还醉宿。
朝走安公枥上驹，暮伦陶令篱边菊。
近来诗思殊无况，苦被时流不相放。
云腾浪走势未衰，鹤膝蜂腰岂能障。
送尔为文殊不识，贵从一一传胷臆。
若到湖南见紫霄，会须待我同攀陟。','',''),('quantangshi-25260','留别南溪二首 一','李渤','quantangshi','','卷26','常叹春泉去不回，我今此去更难来。
欲知别后留情处，手种岩花次第开。','',''),('quantangshi-25261','留别南溪二首 二','李渤','quantangshi','','卷26','如云不厌苍梧远，似雁逢春又北归。
惟有隐山溪上月，年年相望两依依。','',''),('quantangshi-25262','桂林叹雁','李渤','quantangshi','','卷26','三朝四黜倦遐征，往复皆愁万里程。
尔解分飞却回去，我方从此向南行。','',''),('quantangshi-25263','享惠昭太子庙乐章','孟簡','quantangshi','','卷26','喧喧金石容既缺，肃肃羽驾就行列。
缑山遗响昔所闻，庙庭进旅今攸设。','',''),('quantangshi-25264','拟古','孟簡','quantangshi','','卷26','劒客不夸貌，主人知此心。
但营纤毫义，肯计千万金。
勇发看鸷击，愤来听虎吟。
平生贵酬德，刃敌无幽深。','',''),('quantangshi-25265','咏欧阳行周事','孟簡','quantangshi','','卷26','有客西北逐，驱马次太原。
太原有佳人，神艳照行云。
座上转横波，流光注夫君。
夫君意荡漾，即日相交欢。
定情非一词，结念誓青山。
生死不变易，中诚无间言。
此为太学徒，彼属北府官。
中夜欲相从，严城限军门。
白日欲同居，君畏仁人闻。
忽如陇头水，坐作东西分。
惊离肠千结，滴泪眼双昏。
本达京师回，贺期相追攀。
宿约始乖阻，彼忧已缠緜。
高髻若黄鹂，危鬓如玉蝉。
纤手自整理，剪刀断其根。
柔情托侍儿，为我遗所欢。
所欢使者来，侍儿因复前。
抆泪取遗寄，深诚祈为传。
封来赠君子，愿言慰穷泉。
使者回复命，迟迟蓄悲酸。
詹生喜言旋，倒屦走迎门。
长跪听未毕，惊伤涕涟涟。
不饮亦不食，哀心百千端。
襟情一夕空，精爽旦日残。
哀哉浩然气，溃散归化元。
短生虽别离，长夜无阻难。
双魂终会合，两劒遂蜿蜒。
丈夫早通脱，巧笑安能干。
防身本苦节，一去何由还。
后生莫沈迷，沈迷丧其真。','',''),('quantangshi-25266','惜分阴','孟簡','quantangshi','','卷26','业广因功苦，拳拳志士心。
九流难酌挹，四海易消沉。
对景嗟移晷，窥园讵改阴。
三冬劳聚学，驷景重兼金。
刺股情方励，偷光思益深。
再中如可冀，终嗣绝编音。','',''),('quantangshi-25267','嘉禾合颖','孟簡','quantangshi','','卷26','玉烛将成岁，封人亦自歌。
八方霑圣泽，异亩发嘉禾。
共秀芳何远，连茎瑞且多。
颖低甘露滴，影乱惠风过。
表稔由神化，为祥识气和。
因知兴嗣岁，王道旧无颇。','',''),('quantangshi-25268','赋得亚父碎玉斗','孟簡','quantangshi','','卷26','献谋既我违，积愤从心痗。
鸿门入已迫，赤帝时潜退。
宝位方苦竞，玉斗何情爱。
犹看虹气凝，讵惜冰姿碎。
而嗟大事返，当起千里悔。
谁为西楚王，坐见东城溃。','',''),('quantangshi-25269','酬施先辈','孟簡','quantangshi','','卷26','襄阳才子得声多，四海皆传古镜歌。
乐府正声三百首，[梨]园新入教青娥。','',''),('quantangshi-25270','寄李十员外','王仲舒','quantangshi','','卷26','百丈悬泉旧卧龙，欲将肝胆佐时雍。
惟愁又入烟霞去，知在庐峰第几重。','',''),('quantangshi-25271','访羊尊师','孫革','quantangshi','','卷26','松下问童子，言师采药去。
只在此山中，云深不知处。','',''),('quantangshi-25272','晚眺','汪萬於','quantangshi','','卷26','杖策倚柴门，泉声隔岸闻。
夕阳诸岭出，晴雪万山分。
静对豺狼窟，幽观鹿豕羣。
今宵寒月近，东北埽浮云。','',''),('quantangshi-25273','亚父碎玉斗','何儒亮','quantangshi','','卷26','嬴女昔解网，楚王有遗躅。
破关既定秦，碎首闻献玉。
贞姿应刃散，清响因风续。
匪狥切泥功，将明怀璧辱。
莫量汉祖德，空受项君勖。
事去见前心，千秋渭水绿。','',''),('quantangshi-25274','赠毛仙翁','李宗閔','quantangshi','','卷26','不知仙客占青春，肌骨才教称两旬。
俗眼暂惊相见日，疑心未测几时人。
闲推甲子经何代，笑说浮生老此身。
残药傥能沾朽质，愿将霄汉永为邻。','',''),('quantangshi-25275','池州夫子庙麟台','韋表微','quantangshi','','卷26','二仪既闭，三象乃乖。
圣道埋郁，人心不开。
上无文武，下有定哀。
吁嗟麟兮，孰为来哉。
周虽不纲，孔实嗣圣。
诗书既删，礼乐大定。
劝善惩恶，奸邪乃正。
吁嗟麟兮，克昭符命。
圣与时合，化行位尊。
苟或乖戾，身穷道存。
于昭鲁邑，栖迟孔门。
吁嗟麟兮，孰知其仁。
运极数残，德至时否。
楚国寖广，秦封益侈。
墙仞迫厄，崎岖阙里。
吁嗟麟兮，靡有攸止。
世治则麟，世乱则麕。
出非其时，麋鹿同羣。
孔不自圣，麟不自祥。
吁嗟麟兮，天何所亡。','',''),('quantangshi-25276','送马向入蜀','徐凝','quantangshi','','卷26','游子出咸京，巴山万里程。
白云连鸟道，青壁遰猨声。
雨雪经泥坂，烟花望锦城。
工文人共许，应纪蜀中行。','',''),('quantangshi-25277','送李补阙归朝','徐凝','quantangshi','','卷26','驷马归咸秦，双凫出海门。
还从清切禁，再沐圣明恩。
礼乐中朝贵，文章大雅存。
江湖多放逸，献替欲谁论。','',''),('quantangshi-25278','送日本使还','徐凝','quantangshi','','卷26','绝国将无外，扶桑更有东。
来朝逢圣日，归去及秋风。
夜泛潮回际，晨征苍莽中。
鲸波腾水府，蜃气壮仙宫。
天眷何期远，王文久已同。
相望杳不见，离恨托飞鸿。','',''),('quantangshi-25279','题开元寺牡丹','徐凝','quantangshi','','卷26','此花南地知难种，惭愧僧闲用意栽。
海燕解怜频睥睨，胡蜂未识更徘徊。
虚生芍药徒劳妒，羞杀玫瑰不敢开。
惟有数苞红蕚在，含芳只待舍人来。','',''),('quantangshi-25280','香炉峰','徐凝','quantangshi','','卷26','香炉一峰绝，顶在寺门前。
尽是玲珑石，时生旦暮烟。','',''),('quantangshi-25281','白铜鞮','徐凝','quantangshi','','卷26','騕褭锦障泥，楼头日又西。
留欢住不住，素齿白铜鞮。','',''),('quantangshi-25282','杨叛儿','徐凝','quantangshi','','卷26','哀怨杨叛儿，骀荡郎知否。
香死博山炉，烟生白门柳。','',''),('quantangshi-25283','春寒','徐凝','quantangshi','','卷26','乱雪从教舞，回风任听吹。
春寒能作底，已被柳条欺。','',''),('quantangshi-25284','庐山独夜','徐凝','quantangshi','','卷26','寒空五老雪，斜月九江云。
钟声知何处，苍苍树里闻。','',''),('quantangshi-25285','天台独夜','徐凝','quantangshi','','卷26','银地秋月色，石梁夜溪声。
谁知屐齿尽，为破烟苔行。','',''),('quantangshi-25286','送寒岩归士','徐凝','quantangshi','','卷26','不挂丝纩衣，归向寒岩栖。
寒岩风雪夜，又过岩前溪。','',''),('quantangshi-25287','送陈司马','徐凝','quantangshi','','卷26','家寄茅洞中，身游越城下。
宁知许长史，不忆陈司马。','',''),('quantangshi-25288','武夷山仙城','徐凝','quantangshi','','卷26','武夷无上路，毛径不通风。
欲共麻姑住，仙城半在空。','',''),('quantangshi-25289','避暑二首 一','徐凝','quantangshi','','卷26','一株金染密，数亩碧鲜疎。
避暑临溪坐，何妨直钓鱼。','',''),('quantangshi-25290','避暑二首 二','徐凝','quantangshi','','卷26','斑多筒簟冷，发少角冠清。
避暑长林下，寒蝉又有声。','',''),('quantangshi-25291','浙西李尚书奏毁淫昏庙','徐凝','quantangshi','','卷26','传闻废淫祀，万里静山陂。
欲慰灵均恨，先烧靳尚祠。','',''),('quantangshi-25292','酬相公再游云门寺','徐凝','quantangshi','','卷26','远羡五云路，逶迤千骑回。
遗簪唯一去，贵赏不重来。','',''),('quantangshi-25293','杭州祝涛头二首 一','徐凝','quantangshi','','卷26','不道沙堤尽，犹欺石栈顽。
寄言飞白雪，休去打青山。','',''),('quantangshi-25294','杭州祝涛头二首 二','徐凝','quantangshi','','卷26','倒打钱塘郭，长驱白浪花。
吞吴休得也，输却五千家。','',''),('quantangshi-25295','问渔叟','徐凝','quantangshi','','卷26','生事同漂梗，机心在野船。
如何临逝水，白发未忘筌。','',''),('quantangshi-25296','云封庵','徐凝','quantangshi','','卷26','登岩背山河，立石秋风里。
隐见浙江涛，一尺东沟水。','',''),('quantangshi-25297','汉宫曲','徐凝','quantangshi','','卷26','水色帘前流玉霜，赵家飞燕侍昭阳。
掌中舞罢箫声绝，三十六宫秋夜长。','',''),('quantangshi-25298','和嵩阳客月夜忆上清人','徐凝','quantangshi','','卷26','独夜嵩阳忆上仙，月明三十六峰前。
瑶池月胜嵩阳月，人在玉清眠不眠。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-25299','八月望夕雨','徐凝','quantangshi','','卷26','今年八月十五夜，寒雨萧萧不可闻。
如练如霜在何处，吴山越水万重云。','',''),('quantangshi-25300','观浙江涛','徐凝','quantangshi','','卷26','浙江悠悠海西绿，惊涛日夜两翻覆。
钱塘郭里看潮人，直至白头看不足。','',''),('quantangshi-25301','庐山瀑布','徐凝','quantangshi','','卷26','虚空落泉千仞直，雷奔入江不暂息。
今古长如白练飞，一条界破青山色。','',''),('quantangshi-25302','嘉兴寒食','徐凝','quantangshi','','卷26','嘉兴郭里逢寒食，落日家家拜扫回。
唯有县前苏小小，无人送与纸钱来。','',''),('quantangshi-25303','忆扬州','徐凝','quantangshi','','卷26','萧娘脸下难胜泪，桃叶眉头易得愁。
天下三分明月夜，二分无赖是扬州。','',''),('quantangshi-25304','八月灯夕寄游越施秀才','徐凝','quantangshi','','卷26','四天净色寒如水，八月清辉冷似霜。
想得越人今夜见，孟家珠在镜中央。','',''),('quantangshi-25305','八月十五夜','徐凝','quantangshi','','卷26','皎皎秋空八月圆，常娥端正桂枝鲜。
一年无似如今夜，十二峰前看不眠。','',''),('quantangshi-25306','题伍员庙','徐凝','quantangshi','','卷26','千载空祠云海头，夫差亡国已千秋。
浙波只有灵涛在，拜奠青山人不休。','',''),('quantangshi-25307','员峤先生','徐凝','quantangshi','','卷26','员峤先生无白发，海烟深处采青芝。
逢人借问陶唐主，欲进冰蚕五色丝。','',''),('quantangshi-25308','莫愁曲','徐凝','quantangshi','','卷26','玳瑁牀头刺战袍，碧纱窗外叶骚骚。
若为教作辽西梦，月冷如丁风似刀。','',''),('quantangshi-25309','寄白司马','徐凝','quantangshi','','卷26','三条九陌花时节，万户千车看牡丹。
争遣江州白司马，五年风景忆长安。','',''),('quantangshi-25310','相思林','徐凝','quantangshi','','卷26','游客远游新过岭，每逢芳树问芳名。
长林遍是相思树，争遣愁人独自行。','',''),('quantangshi-25311','寄海峤丈人','徐凝','quantangshi','','卷26','万丈只愁沧海浅，一身谁测岁华遥。
自言来此云边住，曾看秦王树石桥。','',''),('quantangshi-25312','寄潘先生','徐凝','quantangshi','','卷26','至人知姓不知名，闻道黄金骨节轻。
世上仙方无觅处，欲来西岳事先生。','',''),('quantangshi-25313','宫中曲二首 一','徐凝','quantangshi','','卷26','披香侍宴插山花，厌着龙绡着越纱。
恃赖倾城人不及，檀妆唯约数条霞。','',''),('quantangshi-25314','宫中曲二首 二','徐凝','quantangshi','','卷26','身轻入宠尽恩私，腰细偏能舞柘枝。
一日新妆抛旧样，六宫争画黑烟眉。','',''),('quantangshi-25315','七夕','徐凝','quantangshi','','卷26','一道鹊桥横渺渺，千声玉佩过玲玲。
别离还有经年客，怅望不如河鼓星。','',''),('quantangshi-25316','八月九月望夕雨','徐凝','quantangshi','','卷26','八月繁云连九月，两回三五晦漫漫。
一年怅望秋将尽，不得常娥正面看。','',''),('quantangshi-25317','喜雪','徐凝','quantangshi','','卷26','长爱谢家能咏雪，今朝见雪亦狂歌。
杨花道即偷人句，不那杨花似雪何。','',''),('quantangshi-25318','春饮','徐凝','quantangshi','','卷26','乌家若下蚁还浮，白玉尊前倒即休。
不是春来偏爱酒，应须得酒遣春愁。','',''),('quantangshi-25319','二月望日','徐凝','quantangshi','','卷26','长短一年相似夜，中秋未必胜中春。
不寒不暖看明月，况是从来少睡人。','',''),('quantangshi-25320','读远书','徐凝','quantangshi','','卷26','两转三回读远书，画檐愁见燕归初。
百花时节教人懒，云髻朝来不欲梳。','',''),('quantangshi-25321','古树','徐凝','quantangshi','','卷26','古树欹斜临古道，枝不生花腹生草。
行人不见树少时，树见行人几番老。','',''),('quantangshi-25322','独住僧','徐凝','quantangshi','','卷26','百补袈裟一比丘，数茎长睫覆青眸。
多应独住山林惯，唯照寒泉自剃头。','',''),('quantangshi-25323','伤画松道芬上人','徐凝','quantangshi','','卷26','百法驱驰百年寿，五劳消瘦五株松。
昨来闻道严陵死，画到青山第几重。','',''),('quantangshi-25324','观钓台画图','徐凝','quantangshi','','卷26','一水寂寥青霭合，两崖崔崒白云残。
画人心到啼猨破，欲作三声出树难。','',''),('quantangshi-25325','荆巫梦思','徐凝','quantangshi','','卷26','楚水白波风袅袅，荆门暮色雨萧萧。
相思合眼梦何处，十二峰高巴字遥。','',''),('quantangshi-25326','浙东故孟尚书种柳','徐凝','quantangshi','','卷26','孟家种柳东城去，临水逶迤思故人。
不似当时大司马，重来得见汉南春。','',''),('quantangshi-25327','长洲览古','徐凝','quantangshi','','卷26','吴王上国长洲奢，翠黛寒江一道斜。
伤见摧残旧宫树，美人曾插九枝花。','',''),('quantangshi-25328','却归旧山望月有寄','徐凝','quantangshi','','卷26','年年明月总相似，大抵人情自不同。
今夜故山依旧见，班家扇样碧峰东。','',''),('quantangshi-25329','再归松溪旧居宿西林','徐凝','quantangshi','','卷26','五粒松深溪水清，众山摇落月偏明。
西林静夜重来宿，暗记人家犬吠声。','',''),('quantangshi-25330','翫花五首 一','徐凝','quantangshi','','卷26','一树梨花春向暮，雪枝残处怨风来。
明朝渐校无多去，看到黄昏不欲回。','',''),('quantangshi-25331','翫花五首 二','徐凝','quantangshi','','卷26','麴尘溪上素红枝，影在溪流半落时。
时人自惜花肠断，春风却是等闲吹。','',''),('quantangshi-25332','翫花五首 三','徐凝','quantangshi','','卷26','朱霞焰焰山枝动，绿野声声杜宇来。
谁为蜀王身作鸟，自啼还自有花开。','',''),('quantangshi-25333','翫花五首 四','徐凝','quantangshi','','卷26','谁家踯躅青林里，半见殷花焰焰枝。
忆得倡楼人送客，深红衫子影门时。','',''),('quantangshi-25334','翫花五首 五','徐凝','quantangshi','','卷26','花到蔷薇明艳绝，燕支颗破麦风秋。
一番弄色一番退，小妇轻妆大妇愁。','',''),('quantangshi-25335','长庆春','徐凝','quantangshi','','卷26','山头水色薄笼烟，久客新愁长庆年。
身上五劳仍病酒，夭桃窗下背花眠。','',''),('quantangshi-25336','山鹧鸪词','徐凝','quantangshi','','卷26','南越岭头山鹧鸪，传是当时守贞女。
化为飞鸟怨何人，犹有啼声带蛮语。','',''),('quantangshi-25337','郑女出参丈人词','徐凝','quantangshi','','卷26','凤钗翠翘双宛转，出见丈人梳洗晚。
掣曳罗绡跪拜时，柳条无力花枝软。','',''),('quantangshi-25338','春雨','徐凝','quantangshi','','卷26','花时闷见联绵雨，云入人家水毁堤。
昨日春风源上路，可怜红锦枉抛泥。','',''),('quantangshi-25339','和白使君木兰花','徐凝','quantangshi','','卷26','枝枝转势雕弓动，片片摇光玉剑斜。
见说木兰征戍女，不知那作酒边花。','',''),('quantangshi-25340','正月十五夜呈幕中诸公','徐凝','quantangshi','','卷26','宵游二万七千人，独坐重城圈一身。
步月游山俱不得，可怜辜负白头春。','',''),('quantangshi-25341','乐府新诗','徐凝','quantangshi','','卷26','一声卢女十三弦，早嫁城西好少年。
不羡越溪歌者苦，采莲归去绿窗眠。','',''),('quantangshi-25342','春陪相公看花宴会二首 一','徐凝','quantangshi','','卷26','丞相邀欢事事同，玉箫金管咽东风。
百分春酒莫辞醉，明日的无今日红。','',''),('quantangshi-25343','春陪相公看花宴会二首 二','徐凝','quantangshi','','卷26','木兰花谢可怜条，远道音书转寂寥。
春去一年春又尽，几回空上望江桥。','',''),('quantangshi-25344','牡丹','徐凝','quantangshi','','卷26','何人不爱牡丹花，占断城中好物华。
疑是洛川神女作，千娇万态破朝霞。','',''),('quantangshi-25345','过马当','徐凝','quantangshi','','卷26','风波隐隐石苍苍，送客灵鸦拂去樯。
三月尽头云叶秀，小姑新着好衣裳。','',''),('quantangshi-25346','金谷览古','徐凝','quantangshi','','卷26','金谷园中数尺土，问人知是绿珠台。
绿珠歌舞天下绝，唯与石家生祸胎。','',''),('quantangshi-25347','上阳红叶','徐凝','quantangshi','','卷26','洛下三分红叶秋，二分翻作上阳愁。
千声万片御沟上，一片出宫何处流。','',''),('quantangshi-25348','洛城秋砧','徐凝','quantangshi','','卷26','三川水上秋砧发，五凤楼前明月新。
谁为秋砧明月夜，洛阳城里更愁人。','',''),('quantangshi-25349','和川守侍郎缑山题仙庙','徐凝','quantangshi','','卷26','王子缑山石殿明，白家诗句咏吹笙。
安知散席人间曲，不是寥天鹤上声。','',''),('quantangshi-25350','和夜题玉泉寺','徐凝','quantangshi','','卷26','岁岁云山玉泉寺，年年车马洛阳尘。
风清月冷水边宿，诗好官高能几人。','',''),('quantangshi-25351','和秋游洛阳','徐凝','quantangshi','','卷26','洛阳自古多才子，唯爱春风烂漫游。
今到白家诗句出，无人不咏洛阳秋。','',''),('quantangshi-25352','和嘲春风','徐凝','quantangshi','','卷26','源上拂桃烧水发，江边吹杏暗园开。
可怜半死龙门树，懊恼春风作底来。','',''),('quantangshi-25353','侍郎宅泛池','徐凝','quantangshi','','卷26','莲子花边回竹岸，鸡头叶上荡兰舟。
谁知洛北朱门里，便到江南绿水游。','',''),('quantangshi-25354','和侍郎邀宿不至','徐凝','quantangshi','','卷26','蟾蜍有色门应锁，街鼓无声夜自深。
料得白家诗思苦，一篇诗了一弹琴。','',''),('quantangshi-25355','自鄂渚至河南将归江外留辞侍郎','徐凝','quantangshi','','卷26','一生所遇唯元白，天下无人重布衣。
欲别朱门泪先尽，白头游子白身归。','',''),('quantangshi-25356','蛮入西川后','徐凝','quantangshi','','卷26','守隘一夫何处在，长桥万里只堪伤。
纷纷塞外乌蛮贼，驱尽江头濯锦娘。','',''),('quantangshi-25357','忆紫溪','徐凝','quantangshi','','卷26','长忆紫溪春欲尽，千岩交映水回斜。
岩空水满溪自紫，水态更笼南烛花。','',''),('quantangshi-25358','夸红槿','徐凝','quantangshi','','卷26','谁道槿花生感促，可怜相计半年红。
何如桃李无多少，并打千枝一夜风。','',''),('quantangshi-25359','题缙云山鼎池二首 一','徐凝','quantangshi','','卷26','黄帝旌旗去不回，空余片石碧崔嵬。
有时风卷鼎湖浪，散作晴天雨点来。','',''),('quantangshi-25360','题缙云山鼎池二首 二','徐凝','quantangshi','','卷26','天地茫茫成古今，仙都凡有几人寻。
到来唯见山高下，只是不知湖浅深。','',''),('quantangshi-25361','宿冽上人房','徐凝','quantangshi','','卷26','浮生不定若蓬飘，林下真僧偶见招。
觉后始知身是梦，更闻寒雨滴芭蕉。','',''),('quantangshi-25362','汴河览古','徐凝','quantangshi','','卷26','炀帝龙舟向此行，三千宫女采桡轻。
渡河不似如今唱，为是杨家怨思声。','',''),('quantangshi-25363','柬白丈人','徐凝','quantangshi','','卷26','昔时丈人鬓发白，千年松下锄茯苓。
今来见此松树死，丈人斩新鬓发青。','',''),('quantangshi-25364','览镜词','徐凝','quantangshi','','卷26','宝镜磨来寒水清，青衣把就绿窗明。
潘郎懊恼新秋发，拔却一茎生两茎。','',''),('quantangshi-25365','寄玄阳先生','徐凝','quantangshi','','卷26','不能相见见人传，{山瞿}岸山中岱岸边。
颜貌只如三二十，道年三百亦藏年。','',''),('quantangshi-25366','白人','徐凝','quantangshi','','卷26','暖风入烟花漠漠，白人梳洗寻常薄。
泥郎为插珑璁钗，争教一朵牙云落。','',''),('quantangshi-25367','奉酬元相公上元','徐凝','quantangshi','','卷26','出拥楼船千万人，入为台辅九霄身。
如何更羡看灯夜，曾见宫花拂面春。','',''),('quantangshi-25368','奉和鹦鹉','徐凝','quantangshi','','卷26','毛羽曾经翦处残，学人言语道暄寒。
任饶长被金笼阖，也免栖飞雨雪难。','',''),('quantangshi-25369','将至妙喜寺','徐凝','quantangshi','','卷26','清风袅袅越水陂，远树苍苍妙喜寺。
自有车轮与马蹄，未曾到此波心地。','',''),('quantangshi-25370','红蕉','徐凝','quantangshi','','卷26','红蕉曾到岭南看，校小芭蕉几一般。
差是斜刀翦红绢，卷来开去叶中安。','',''),('quantangshi-25371','见少室','徐凝','quantangshi','','卷26','适我一箪孤客性，问人三十六峰名。
青云无忘白云在，便可嵩阳老此生。','',''),('quantangshi-25372','语儿见新月','徐凝','quantangshi','','卷26','几处天边见新月，经过草市忆西施。
娟娟水宿初三夜，曾伴愁蛾到语儿。','',''),('quantangshi-25373','回施先辈见寄新诗二首 一','徐凝','quantangshi','','卷26','九幽仙子西山卷，读了绦绳系又开。
此卷玉清宫里少，曾寻真诰读诗来。','',''),('quantangshi-25374','回施先辈见寄新诗二首 二','徐凝','quantangshi','','卷26','紫河车里丹成也，皂荚枝头早晚飞。
料得仙宫列仙[籍]，如君进士出身稀。','',''),('quantangshi-25375','送沈亚之赴郢掾','徐凝','quantangshi','','卷26','千万乘骢沈司户，不须惆怅郢中游。
几年白雪无人唱，今日唯君上雪楼。','',''),('quantangshi-25376','答白公','徐凝','quantangshi','','卷26','高景争来草木头，一生心事酒前休。
山公自是仙人侣，携手醉登城上楼。','',''),('quantangshi-25377','句','徐凝','quantangshi','','卷26','青山旧路在，白首醉还乡。
试到第三桥，便入千顷花。
乱后见淮水，归心忽迢遥。
乍疑鲸喷浪，忽似鷁凌风。
呀呷汀洲动，喧阗里巷空。','',''),('quantangshi-25378','奉和圣制南郊礼毕诗','李德裕','quantangshi','','卷26','磬管歌大吕，冕裘旅天神。
烧萧辟阊阖，祈谷为蒸人。
羽旗洒轻雪，麦陇含阳春。
昌运岁今会，王猷从此新。
三臣皆就日，万国望如云。
仁寿信非远，羣生方在钧。','',''),('quantangshi-25379','郊坛回舆中书二相公蒙圣慈召至御马前仰感恩遇辄书是诗兼呈二相公','李德裕','quantangshi','','卷26','七萃和銮动，三条葆吹回。
相星环日道，苍马近龙媒。
咫尺天颜接，光华喜气来。
自慙衰且病，无以效涓埃。','',''),('quantangshi-25380','寒食日三殿侍宴奉进诗一首','李德裕','quantangshi','','卷26','宛转龙歌节，参差燕羽高。
风光摇禁柳，霁色暖宫桃。
春露明仙掌，晨霞照御袍。
雪凝陈组练，林植耸干旄。
广乐初跄凤，神山欲拚鳌。
鸣笳朱鹭起，叠鼓紫騂豪。
象舞严金铠，丰歌耀宝刀。
不劳孙子法，自得太公韬。
分席罗玄冕，行觞举绿醪。
彀中时落羽，幢末乍升猱。
瑞景开阴翳，薰风散郁陶。
天颜欢益醉，臣节劲尤高。
楛矢方来贡，雕弓已载櫜。
英威扬绝漠，神算尽临洮。
赤县阳和布，苍生雨露膏。
野平惟有麦，田辟久无蒿。
禄秩荣三事，功勋乏一毫。
寝谋慙汲黯，秉羽贵孙敖。
焕若游玄圃，欢如享太牢。
轻生何以报，祗自比鸿毛。','',''),('quantangshi-25381','雨中自秘书省访王三侍御知早入朝便入集贤侍御任集贤校书及升柏台又与秘阁相对同院张学士亦余特厚故以诗赠之','李德裕','quantangshi','','卷26','共怜独鹤青霞姿，瀛洲故山归已迟。
仁者焉能效鸷鹗，飞舞自合追长离。
梧桐迥齐鳷鹊观，烟雨屡拂蛟龙旗。
鸿雁冲颷去不尽，寒声晚下天泉池。
顾我蓬莱静无事，玉版宝书藏众瑞。
青编尽以汲冢来，科斗皆从鲁室至。
金门待诏何逍遥，名儒早问张子侨。
王褒轶材晚始入，宫女已能传洞箫。
应令栢台长对户，别来相望独寥寥。','',''),('quantangshi-25382','奉和太原张尚书山亭书怀','李德裕','quantangshi','','卷26','岩石在朱户，风泉当翠楼。
始知岘亭赏，难与清晖留。
余景淡将夕，凝岚轻欲收。
东山有归志，方接赤松游。','',''),('quantangshi-25383','奉和韦侍御陪相公游开义五言六韵','李德裕','quantangshi','','卷26','羊公追胜概，兹地暂逍遥。
风景同南岘，丹青见北朝。
石渠清夏气，高树激鲜飙。
念法珍禽集，闻轻醉象调。
偶分甘露味，偏觉众香饶。
为问毗城内，余薰几日销。','',''),('quantangshi-25384','赠圆明上人','李德裕','quantangshi','','卷26','远公说易长松下，龙树双轻海藏中。
今日导师闻佛慧，始知前路化成空。','',''),('quantangshi-25385','赠奉律上人','李德裕','quantangshi','','卷26','知君学地厌多闻，广渡羣生出世氛。
饭色不应殊宝器，树香皆遣入禅薰。','',''),('quantangshi-25386','戏赠慎微寺主道安上座三僧正','李德裕','quantangshi','','卷26','甘露洒空惟一味，旃檀移植自成薰。
遥知畅献分南北，应用调柔致六羣。','',''),('quantangshi-25387','长安秋夜','李德裕','quantangshi','','卷26','内宫传诏问戎机，载笔金銮夜始归。
万户千门皆寂寂，月中清露点朝衣。','',''),('quantangshi-25388','清冷池怀古','李德裕','quantangshi','','卷26','区囿三百里，常闻驷马来。
旌旗朝甬道，箫鼓燕平台。
追昔赋文雅，从容游上才。
竹园秋水净，风苑雪烟开。
牛祸衅将发，羊孙谋始回。
袁丝徒伏劒，长孺欲成灰。
兴废由所感，湮沦斯可哀。
空留故池雁，刷羽尚徘徊。','',''),('quantangshi-25389','述梦诗四十韵','李德裕','quantangshi','','卷26','赋命诚非薄，良时幸已遭。
君当尧舜日，官接凤皇曹。
目睇烟霄阔，心惊羽翼高。
椅梧连鹤禁，壀堄接龙韬。
我后怜词客，吾僚并隽髦。
着书同陆贾，待诏比王褒。
重价连悬璧，英词淬宝刀。
泉流初落涧，露滴更濡毫。
赤豹欣来献，彤弓喜暂櫜非烟含瑞气，驯雉洁霜毛。
静室便幽独，虚楼散郁陶。
花光晨艳艳，松韵晚骚骚。
画壁看飞鹤，仙图见巨鳌。
倚檐阴药树，落格蔓蒲桃。
荷静蓬池鲙，冰寒郢水醪。
荔枝来自远，卢橘赐仍叨。
麝气随兰泽，霜华入杏膏。
恩光惟觉重，携挈未为劳。
夕阅梨园骑，宵闻禁杖獒。
扇回交彩翟，雕起扬银绦。
辔待袁丝揽，书期蜀客操。
尽规常謇謇，退食尚忉忉。
龟顾垂金钮，鸾飞曳锦袍。
御沟杨柳弱，天廐驌驦豪。
屡换青春直，闲随上苑遨。
烟低行殿竹，风拆绕墙桃。
聚散俄成昔，悲愁益自熬。
每怀仙驾远，更望茂陵号。
地接三茅岭，川迎伍子涛。
花迷瓜步暗，石固蒜山牢。
兰野凝香管，梅洲动翠篙。
泉鱼惊彩妓，溪鸟避干旄。
感旧心犹绝，思归首更搔。
无聊燃[蜜]炬，谁复劝金舠。
岚气朝生栋，城阴夜入濠。
望烟归海峤，送雁渡江臯。
宛马嘶寒枥，吴钩在锦弢。
未能追狡兔，空觉长黄蒿。
水国逾千里，风帆过万艘。
阅川终古恨，惟见暮滔滔。','',''),('quantangshi-25390','招隐山观玉蘂树戏书即事奉寄江西沈大夫阁老','李德裕','quantangshi','','卷26','玉蘂天中树，金闺昔共窥。
落英闲舞雪，密叶乍低帷旧赏烟霄远，前欢岁月移。
今来想颜色，还似忆琼枝。','',''),('quantangshi-25391','寄题惠林李侍郎旧馆','李德裕','quantangshi','','卷26','栋宇非吾室，烟山是我邻。
百龄惟待尽，一世乐长贫。
半壁悬秋日，空林满夕尘。
祗应双鹤吊，松路更无人。','',''),('quantangshi-25392','寄茅山孙炼师','李德裕','quantangshi','','卷26','何地最翛然，华阳第八天。
松风清有露，萝月净无烟。
乍警瑶坛鹤，时嘶玉树蝉。
欲驰千里恋，惟有凤门泉。','',''),('quantangshi-25393','又二绝 一','李德裕','quantangshi','','卷26','石上溪荪发紫茸，碧山幽蔼水溶溶。
菖花定是无人见，春日惟应羽客逢。','',''),('quantangshi-25394','又二绝 二','李德裕','quantangshi','','卷26','独寻兰渚翫迟晖，闲倚松窗望翠微。
遥想春山明月曙，玉坛清磬步虚归。','',''),('quantangshi-25395','题奇石','李德裕','quantangshi','','卷26','蕴玉抱清辉，闲庭日潇洒。
块然天地间，自是孤生者。','',''),('quantangshi-25396','送张中丞入台从事','李德裕','quantangshi','','卷26','驿骑朝天去，江城睠阙深。
夜珠先去握，芳桂乍辞阴。
泽国三千里，羁孤万感心。
自嗟文废久，此曲为卢谌。','',''),('quantangshi-25397','怀京国','李德裕','quantangshi','','卷26','海上东风犯雪来，腊前先折镜湖梅。
遥思禁苑青春夜，坐待宫人画诏回。','',''),('quantangshi-25398','追和太师颜公同清远道士游虎丘寺','李德裕','quantangshi','','卷26','茂苑有灵峰，嗟余未游观。
藏山半平陆，坏谷为高岸。
冈绕数仞墙，岩潜千丈干。
乃知造化意，回斡资奇玩。
鏐腾昔虎踞，劒没尝龙焕。
潭黛入海底，崟岑耸霄半。
层峦未升日，哀狖宁知旦。
绿筱夏凝阴，碧林秋不换。
冥搜既窈窕，回望何萧散。
川晴岚气收，江春杂英乱。
逸人缀清藻，前哲留篇翰。
共扣哀玉音，皆舒文绣段。
难追彦回赏，徒起兴公叹。
一夕如再升，含毫星斗烂。','',''),('quantangshi-25399','东郡怀古二首 王京兆','李德裕','quantangshi','','卷26','河水昔将决，冲波溢川浔。
峥嵘金堤下，喷薄风雷音。
投马灾未弭，为鱼叹方深。
惟公执圭璧，誓与身俱沈。
诚信不虚发，神明宜尔临。
湍流自此回，咫尺焉能侵。
逮我守东郡，凄然怀所钦。
虽非识君面，自谓知君心。
意气苟相合，神明无古今。
登城见遗庙，日夕空悲吟。','',''),('quantangshi-25400','东郡怀古二首 阳给事','李德裕','quantangshi','','卷26','宋氏远家左，豺狼满中州。
阳君守滑台，终古垂英猷。
数仞城既毁，万夫心莫留。
跳身入飞镞，免胄临霜矛。
毕命在旗下，僵尸横道周。
义风激河汴，壮气沦山丘。
嗟尔抱忠烈，古来谁与俦。
就烹感汉使，握节悲阳秋。
颜子缀清藻，铿然如素璆。
徘徊望故垒，尚想精魂游。','',''),('quantangshi-25401','秋日登郡楼望赞皇山感而成咏','李德裕','quantangshi','','卷26','昔人怀井邑，为有挂冠期。
顾我飘蓬者，长随泛梗移。
越吟因病感，潘鬓入秋悲。
北指邯郸道，应无归去期。','',''),('quantangshi-25402','雨后净望河西连山怆然成咏','李德裕','quantangshi','','卷26','宿雨初收晚吹繁，秋光极目自销魂。
烟山北下归辽海，鸿雁南飞出蓟门。
只恨无功书史籍，岂悲临老事戎轩。
唯怀药饵蠲衰病，为惜余年报主恩。','',''),('quantangshi-25403','秋日美晴郡楼闲眺寄荆南张书记','李德裕','quantangshi','','卷26','高槛凉风起，清川旭景开。
秋声向野去，爽气自山来。
霄外鸿初返，檐间燕已归。
不因烟雨夕，何处梦阳台。','',''),('quantangshi-25404','故人寄茶','李德裕','quantangshi','','卷26','劒外九华英，缄题下玉京。
开时微月上，碾处乱泉声。
半夜邀僧至，孤吟对竹烹。
碧流霞脚碎，香泛乳花轻。
六腑睡神去，数朝诗思清。
其余不敢费，留伴读书行。','',''),('quantangshi-25405','奉送相公十八丈镇杨州','李德裕','quantangshi','','卷26','千骑风生大斾舒，春江重到武侯庐。
共悬龟印衔新绶，同忆鳣庭访旧居。
取履桥边啼鸟换，钓璜溪畔落花初。
今来却笑临邛客，入蜀空驰使者车。','',''),('quantangshi-25406','题劒门','李德裕','quantangshi','','卷26','奇峰百仞悬，清眺出岚烟。
迥若戈回日，高疑劒倚天。
参差霞壁耸，合沓翠屏连。
想是三刀梦，森然在目前。','',''),('quantangshi-25407','汉州月夕游房太尉西湖','李德裕','quantangshi','','卷26','丞相鸣琴地，何年闭玉徽。
偶因明月夕，重敞故楼扉。
桃柳溪空在，芙蓉客暂依。
谁怜济川楫，长与夜舟归。','',''),('quantangshi-25408','重题','李德裕','quantangshi','','卷26','晚日临寒渚，微风发棹讴。
凤池波自阔，鱼水运难留。
亭古思宏栋，川长忆夜舟。
想公高世志，祗似冶城游。','',''),('quantangshi-25409','房公旧竹亭闻琴缅慕风流神期如在因重题此作','李德裕','quantangshi','','卷26','流水音长在，青霞意不传。
独悲形解后，谁听广陵弦。','',''),('quantangshi-25410','忆金门旧游奉寄江西沈大夫','李德裕','quantangshi','','卷26','东望沧溟路几重，无因白首更相逢。
已悲泉下双琪树，又惜天边一卧龙。
人事升沉才十载，宦游漂泊过千峰。
思君远寄西山药，岁暮相期向赤松。','',''),('quantangshi-25411','早入中书行公主册礼事毕登集贤阁成咏','李德裕','quantangshi','','卷26','明星入东陌，灿灿光层宙。
皎月映高梧，轻风发凉候。
金门列葆吹，钟室传清漏。
简册自中来，貂黄忝宣授。
更登天禄阁，极眺终南岫。
遥羡商山翁，闲歌紫芝秀。
晨兴念始辱，夕惕思致寇。
倾夺非我心，凄然感田窦。','',''),('quantangshi-25412','题罗浮石','李德裕','quantangshi','','卷26','清景持芳菊，凉天倚茂松。
名山何必去，此地有羣峰。','',''),('quantangshi-25413','重过列子庙追感顷年自淮服与居守王仆射同题名于庙壁仆射已为御史余尚布衣自后俱列紫垣继游内署两为夏官之代复联左揆之荣荷宠多同感涕何极因书四韵奉寄','李德裕','quantangshi','','卷26','白首过遗庙，朱轮入故城。
已惭联左揆，犹喜抗前旌。
曳履忘年旧，弹冠久要情。
重看题壁处，岂羡弃繻生。','',''),('quantangshi-25414','遥伤茅山县孙尊师三首 一','李德裕','quantangshi','','卷26','蝉蜕遗虚白，霓飞入上清。
同人悲劒解，旧友觉衣轻。
黄鹄遥将举，斑麟俨未行。
惟应鲍靓室，中夜识琴声。','',''),('quantangshi-25415','遥伤茅山县孙尊师三首 二','李德裕','quantangshi','','卷26','金格期初至，飙轮去不停。
山摧武担石，天陨少微星。
弟子悲徐甲，门人泣蔡经。
空闻留玉舃，犹在阜乡亭。','',''),('quantangshi-25416','遥伤茅山县孙尊师三首 三','李德裕','quantangshi','','卷26','空宇留丹竈，层霞被羽衣。
旧山闻鹿化，遗舃尚凫飞。
数日奇香在，何年白鹤归。
想君旋下泪，方欵里闾扉。','',''),('quantangshi-25417','尊师是桃源黄先生传法弟子常见尊师称先师灵迹今重赋此诗兼寄题黄先生旧馆','李德裕','quantangshi','','卷26','后学方成市，吾师又上宾。
洞天应不夜，源树秪如春。
棋客留童子，山精避直神。
无因握石髓，及与养生人。','',''),('quantangshi-25418','仆射相公偶话于故集贤张学士厅写得德裕与仆射旧唱和诗其时和者五人惟仆射与德裕皆列高位凄然怀旧辄献此诗','李德裕','quantangshi','','卷26','赋感邻人篴，诗留夫子墙。
延年如有作，应不用山王。','',''),('quantangshi-25419','惠泉','李德裕','quantangshi','','卷26','兹泉由太洁，终不畜纤鳞。
到底清何益，含虚势自贫。
明玑难秘彩，美玉讵潜珍。
未及黄陂量，滔滔岂有津。','',''),('quantangshi-25420','无题','李德裕','quantangshi','','卷26','松倚苍崖老，兰临碧洞衰。
不劳邻舍篴，吹起旧时悲。','',''),('quantangshi-25421','题冠盖里','李德裕','quantangshi','','卷26','偶来冠盖里，愧是旧三公。
自喜无兵术，轻裘上閟宫。','',''),('quantangshi-25422','离平泉马上作','李德裕','quantangshi','','卷26','十年紫殿掌洪钧，出入三朝一品身。
文帝宠深陪雉尾，武皇恩厚宴龙津。
黑山永破和亲虏，乌岭全坑跋扈臣。
自是功高临尽处，祸来[名]灭不由人。','',''),('quantangshi-25423','谪岭南道中作','李德裕','quantangshi','','卷26','岭水争分路转迷，桄榔椰叶暗蛮溪。
愁冲毒雾逢虵草，畏落沙虫避燕泥。
五月畲田收火米，三更津吏报潮鸡。
不堪肠断思乡处，红槿花中越鸟啼。','',''),('quantangshi-25424','到恶溪夜泊芦岛','李德裕','quantangshi','','卷26','甘露花香不再持，远公应怪负前期。
青蝇岂独悲虞氏，黄犬应闻笑李斯。
风雨瘴昏蛮日月，烟波魂断恶溪时。
岭头无限相思泪，泣向寒梅近北枝。','',''),('quantangshi-25425','登崖州城作','李德裕','quantangshi','','卷26','独上高楼望帝京，鸟飞犹是半年程。
青山似欲留人住，百匝千遭遶郡城。','',''),('quantangshi-25426','鸳鸯篇','李德裕','quantangshi','','卷26','君不见昔时同心人，化作鸳鸯鸟。
和鸣一夕不暂离，交颈千年尚为少。
二月草菲菲，山樱花未稀。
金塘风日好，何处不相依？
既逢解佩游女，更值凌波宓妃。
精光摇翠盖，丽色映珠玑。
双影相伴，双心莫违。
淹留碧沙上，荡漾洗红衣。
春光兮宛转，嬉游兮未反。
宿莫近天泉池，飞莫近长洲苑。
尔愿欢爱不相忘，须去人间罗网远。
南有潇湘洲，且为千里游。
洞庭无苦寒，沅江多碧流。
昔为薄命妾，无日不含愁。
今为水中鸟，颉颃自相求。
洛阳女儿在青阁，二月罗衣轻更薄。
金泥文彩未足珍，画作鸳鸯始堪着。
亦有少妇破瓜年，春闺无伴独婵娟。
夜夜学织连枝锦，织作鸳鸯人共怜。
悠悠湘水滨，清浅漾初苹。
菖花发艳无人识，江柳逶迤空自春。
唯怜独鹤依琴曲，更念孤鸾隐镜尘。
愿作鸳鸯被，长覆有情人。','',''),('quantangshi-25427','南梁行','李德裕','quantangshi','','卷26','江南郁郁春草长，悠悠汉水浮清光。
杂英飞尽空和景，绿杨阴重官舍静。
此时醉客纵横书，公言可荐承明庐。
青天诏下宠光至，颁籍金闺征石渠。
重归山路烟岚隔，巫山未深晚花折。
涧底红光夺目燃，摇风有毒愁行客。
杜鹃啼咽花亦殷，声悲绝艳连空山。
斜阳瞥映浅深树，云雨翻迷崖谷间。
山鸡锦质矜毛羽，透竹穿萝命俦侣。
乔木幽谷上下同，雄雌不异飞栖处。
望秦峰迥过商颜，浪叠云堆万簇山。
行尽杳冥青嶂外，九重钟漏紫云间。
元和列侍明光殿，谏草初焚市朝变。
北阙趋臣半隟尘，南梁笑客皆飞霰。
追思感叹却昏迷，霜鬓愁吟到晓鸡。
故园岁深开断简，秋堂月晓掩遗袿。
呜呜晓角霞辉粲，抚劒当楹一长叹。
刍狗无由学圣贤，空持感激终昏旦。','',''),('quantangshi-25428','近于伊川卜山居将命者画图而至欣然有感聊赋此诗兼寄上浙东元相公大夫使求青田胎化鹤','李德裕','quantangshi','','卷26','弱岁弄词翰，遂叨明主恩。
怀章过越邸，建斾守吴门。
西圮阴难驻，东臯意尚存。
慙逾六百石，愧负五千言。
寄世知婴缴，辞荣类触藩。
欲追绵上隐，况近子平村。
邑有桐乡爱，山余黍谷暄。
既非逃相地，乃是故侯园。
野竹多微迳，岩泉岂一源。
映池方树密，傍涧古藤繁。
邛杖堪扶老，黄牛已服辕。
只应将唳鹤，幽谷共翩翻。','',''),('quantangshi-25429','忆平泉山居赠沈吏部一首','李德裕','quantangshi','','卷26','昔闻羊叔子，茅屋在东渠。
岂不念归路，徘徊畏简书。
乃知轩冕客，自与田园疎。
殁世有遗恨，精诚何所如。
嗟予寡时用，夙志在林闾。
虽抱山水癖，敢希仁智居。
清泉绕舍下，修竹荫庭除。
幽径松盖密，小池莲叶初。
从来有好鸟，近复跃鯈鱼。
少室映川陆，鸣臯对蓬庐。
张何旧寮寀，相勉在悬舆。
常恐似伯玉，瞻前慙魏舒。','',''),('quantangshi-25430','夏晚有怀平泉林居','李德裕','quantangshi','','卷26','孟夏守畏途，舍舟在徂暑。
愀然何所念，念我龙门坞。
密竹无蹊径，高松有四五。
飞泉鸣树间，飒飒如度雨。
菌桂秀层岭，芳荪媚幽渚。
稚子候我归，衡门独延伫。
谁言圣与哲，曾是不怀土。
公旦既思周，宣尼亦念鲁。
矧余窜炎裔，日夕谁晤语。
眷阙悲子牟，班荆感椒举。
凄凄视环玦，恻恻步庭庑。
岂待庄舃吟，方知倦羁旅。','',''),('quantangshi-25431','早秋龙兴寺江亭闲眺忆龙门山居寄崔张旧从事','李德裕','quantangshi','','卷26','江亭感秋至，兰径悲露泫。
秔稻秀晚川，杉松郁晴巘。
嗟予有林壑，兹夕念原衍。
绿筱连岭多，青莎近溪浅。
渊明菊犹在，仲蔚蒿莫翦。
乔木粲凌苕，阴崖积幽藓。
遥思伊川水，北渡龙门岘。
苍翠双阙间，逶迤清滩转。
故人在乡国，岁晏路悠缅。
惆怅此生涯，无由共登践。','',''),('quantangshi-25432','比闻龙门敬善寺有红桂树独秀伊川尝于江南诸山访之莫致陈侍御知予所好因访剡溪樵客偶得数株移植郊园众芳色沮乃知敬善所有是蜀道菵草徒得嘉名因赋是诗兼赠陈侍御','李德裕','quantangshi','','卷26','昔闻红桂枝，独秀龙门侧。
越叟遗数株，周人未尝识。
平生爱此树，攀翫无由得。
君子知我心，因之为羽翼。
岂烦嘉客誉，且就清阴息。
来自天姥岑，长疑翠岚色。
芬芳世所绝，偃蹇枝渐直。
琼叶润不凋，珠英粲如织。
犹疑翡翠宿，想待鵷雏食。
宁止暂淹留，终当更封植。','',''),('quantangshi-25433','怀山居邀松阳子同作','李德裕','quantangshi','','卷26','我有爱山心，如饥复如渴。
出谷一年余，常疑十年别。
春思岩花烂，夏忆寒泉冽。
秋忆泛兰巵，冬思玩松雪。
晨思小山桂，暝忆深潭月。
醉忆剖红梨，饭思食紫蕨。
坐思藤萝密，步忆莓苔滑。
昼夜百刻中，愁肠几回绝。
每念羊叔子，言之岂常辍。
人生不如意，十乃居七八。
我未及悬舆，今犹佩朝绂。
焉能逐麋鹿，便得游林樾。
范恣沧波舟，张怀赤松列。
惟应讵身恤，岂敢忘臣节。
器满自当欹，物盈终有缺。
从兹返樵径，庶可希前哲。','',''),('quantangshi-25434','思归赤松村呈松阳子','李德裕','quantangshi','','卷26','昔人思避世，惟恐不深幽。
禽庆潜名岳，鸱夷漾钓舟。
顾余知止足，所乐在归休。
不似寻山者，忘家恣远游。','',''),('quantangshi-25435','近腊对雪有怀林居','李德裕','quantangshi','','卷26','蓬门常昼掩，竹径寂无人。
鸟起飘松霰，麕行动谷榛。
应知禽鱼侣，合与薜萝亲。
遥忆平臯望，溪烟已发春。','',''),('quantangshi-25436','思山居一十首 清明后忆山中','李德裕','quantangshi','','卷26','遥思寒食后，野老林下醉。
月照一山明，风吹百花气。
飞泉与万籁，仿髴疑箫吹。
不待曙华分，已应喧鸟至。','',''),('quantangshi-25437','思山居一十首 题寄商山石','李德裕','quantangshi','','卷26','绮皓岩中石，尝经伴隐沦。
紫芝呈几曲，红藓閟千春。
聊用支琴尾，宁惟倚病身。
自知来处所，何暇问严遵。','',''),('quantangshi-25438','思山居一十首 忆钟苽时','李德裕','quantangshi','','卷26','尚平方毕娶，疎广念归期。
涧底松成盖，檐前桂长枝。
径闲芳草合，山静落花迟。
虽有苽园在，无因及种时。','',''),('quantangshi-25439','思山居一十首 春日独坐思归','李德裕','quantangshi','','卷26','壮龄心已尽，孤赏意犹存。
岂望图麟阁，惟思卧鹿门。
无谋堪适野，何力可拘原。
只有容身去，幽山自灌园。','',''),('quantangshi-25440','思山居一十首 思登家山林岭','李德裕','quantangshi','','卷26','自知无世用，只是爱山游。
旧有嵇康嬾，今慙赵武偷。
登峦未觉疾，泛水便忘忧。
最惜残筋力，扪萝遍一丘。','',''),('quantangshi-25441','思山居一十首 思乡园老人','李德裕','quantangshi','','卷26','常羡荜门翁，所思惟岁稔。
遥知松月曙，尚在山窗寝。
兰气入幽帘，禽言傍孤枕。
晨兴步岩径，更酌寒泉饮。','',''),('quantangshi-25442','思山居一十首 寄龙门僧','李德裕','quantangshi','','卷26','龙门有开士，爱我春潭碧。
清景出东山，闲来玩松石。
应怜林壑主，远作沧溟客。
为我谢此僧，终当理归策。','',''),('quantangshi-25443','思山居一十首 忆药苗','李德裕','quantangshi','','卷26','溪上药苗齐，丰茸正堪掇。
皆能扶我寿，岂止坚肌骨。
味掩商山芝，英逾首阳蕨。
岂如甘谷士，只得香泉啜。','',''),('quantangshi-25444','思山居一十首 忆村中老人春酒','李德裕','quantangshi','','卷26','二叟茅茨下，清晨饮浊醪。
雨残红芍药，风落紫樱桃。
巢燕衔泥疾，檐虫挂网高。
闲思春谷事，转觉宦途劳。','',''),('quantangshi-25445','思山居一十首 忆葛胜木禅床','李德裕','quantangshi','','卷26','忆我斋中榻，寒宵几独眠。
管宁穿亦坐，徐孺去常悬。
虫网垂应遍，苔痕染更鲜。
何人及身在，归对老僧禅。','',''),('quantangshi-25446','初夏有怀山居','李德裕','quantangshi','','卷26','山中有所忆，夏景始清幽。
野竹阴无日，岩泉冷似秋。
翠岑当累榭，皓月入轻舟。
只有思归夕，空帘且梦游。','',''),('quantangshi-25447','张公超谷中石','李德裕','quantangshi','','卷26','鼓箧依绿槐，横经起秋雾。
有时连岳客，尚办弦歌处。
自予去幽谷，谁人袭芳杜。
空留古苔石，对我岩中树。','',''),('quantangshi-25448','初归平泉过龙门南岭遥望山居即事','李德裕','quantangshi','','卷26','初归故乡陌，极望且徐轮。
近野樵蒸至，平泉烟火新。
农夫馈鸡黍，渔子荐霜鳞。
惆怅怀杨仆，惭为关外人。','',''),('quantangshi-25449','伊川晚眺','李德裕','quantangshi','','卷26','桑叶初黄梨叶红，伊川落日尽无风。
汉储何假终南客，角里先生在谷中。','',''),('quantangshi-25450','潭上喜见新月','李德裕','quantangshi','','卷26','簪组十年梦，园庐今夕情。
谁怜故乡月，复映碧潭生。
皓彩松上见，寒光波际轻。
还将孤赏意，暂寄玉琴声。','',''),('quantangshi-25451','郊外即事寄侍郎大尹','李德裕','quantangshi','','卷26','高秋慙非隐，闲林喜退居。
老农争席坐，稚子带经锄。
竹径难回骑，仙舟但跂予。
岂知陶靖节，秪自爱吾庐。','',''),('quantangshi-25452','山居遇雪喜道者相访','李德裕','quantangshi','','卷26','幽居近谷西，乔木与山齐。
野竹连池合，岩松映雪低。
喜君来白社，值我在青溪。
应笑于陵子，遗荣自灌畦。','',''),('quantangshi-25453','雪霁晨起','李德裕','quantangshi','','卷26','雪覆寒溪竹，风卷野田蓬。
四望无竹迹，谁怜孤老翁。','',''),('quantangshi-25454','洛中士君子多以平泉见呼愧获方外之名因以此诗为报奉寄刘宾客','李德裕','quantangshi','','卷26','非高柳下逸，自爱竹林闲。
才异居东里，愚因在北山。
径荒寒未扫，门设昼长关。
不及鸱夷子，悠悠烟水间。','',''),('quantangshi-25455','早春至言禅公法堂忆平泉别业','李德裕','quantangshi','','卷26','昔我伊原上，孤游竹树间。
人依红桂静，鸟傍碧潭闲。
松盖低春雪，藤轮倚暮山。
永怀桑梓邑，衰老若为还。','',''),('quantangshi-25456','峡山亭月夜独宿对樱桃花有怀伊川别墅','李德裕','quantangshi','','卷26','皎月照芳树，鲜葩含素辉。
愁人惜春夜，达曙想岩扉。
风静阴满砌，露浓香入衣。
恨无金谷妓，为我奏思归。','',''),('quantangshi-25457','春暮思平泉杂咏二十首 望伊川','李德裕','quantangshi','','卷26','远村寒食后，细雨度川来。
芳草连溪合，梨花映墅开。
槿篱悬落照，松径长新苔。
向夕亭臯望，游禽几处回。','',''),('quantangshi-25458','春暮思平泉杂咏二十首 潭上紫藤','李德裕','quantangshi','','卷26','故乡春欲尽，一岁芳难再。
岩树已青葱，吾庐日堪爱。
幽溪人未去，芳草行应碍。
遥忆紫藤垂，繁英照潭黛。','',''),('quantangshi-25459','春暮思平泉杂咏二十首 书楼晴望','李德裕','quantangshi','','卷26','幽居人世外，久厌市朝喧。
苍翠连双阙，微茫认九原。
残红映巩树，斜日照轘辕。
薄暮柴扉掩，谁知仲蔚园。','',''),('quantangshi-25460','春暮思平泉杂咏二十首 西岭望鸣臯山','李德裕','quantangshi','','卷26','高秋对凉野，四望何萧瑟。
远见鸣臯山，青峰原上出。
晨兴采薇蕨，向暮归蓬荜。
讵假数挥金，餐和养余日。','',''),('quantangshi-25461','春暮思平泉杂咏二十首 瀑泉亭','李德裕','quantangshi','','卷26','向老多悲恨，凄然念一丘。
岩泉终古在，风月几年游。
菌阁饶佳树，菱潭有钓舟。
不如羊叔子，名与岘山留。','',''),('quantangshi-25462','春暮思平泉杂咏二十首 红桂树','李德裕','quantangshi','','卷26','欲求尘外物，此树是瑶林。
后素合余绚，如丹见本心。
妍姿无点辱，芳意托幽深。
愿以鲜葩色，凌霜照碧浔。','',''),('quantangshi-25463','春暮思平泉杂咏二十首 金松','李德裕','quantangshi','','卷26','台岭生奇树，佳名世未知。
纤纤疑大菊，落落是松枝。
照日含金晰，笼烟淡翠滋。
勿言人去晚，犹有岁寒期。','',''),('quantangshi-25464','春暮思平泉杂咏二十首 月桂','李德裕','quantangshi','','卷26','何年霜夜月，桂子落寒山。
翠干生岩下，金英在世间。
幽崖空自老，清汉未知还。
惟有凉秋夜，嫦娥来暂攀。','',''),('quantangshi-25465','春暮思平泉杂咏二十首 山桂','李德裕','quantangshi','','卷26','吾爱山中树，繁英满目鲜。
临风飘碎锦，映日乱非烟。
影入春潭底，香凝月榭前。
岂知幽独客，赖此当朱弦。','',''),('quantangshi-25466','春暮思平泉杂咏二十首 栢','李德裕','quantangshi','','卷26','闻有三株树，惟应秘阆风。
珊瑚不生叶，朱草又无丛。
未若凌云栢，常能终岁红。
晨霞与落日，相照在岩中。','',''),('quantangshi-25467','春暮思平泉杂咏二十首 芳荪','李德裕','quantangshi','','卷26','楚客重兰荪，遗芳今未歇。
叶抽清浅水，花照暄妍节。
紫艳映渠鲜，轻香含露洁。
离居若有赠，暂与幽人折。','',''),('quantangshi-25468','春暮思平泉杂咏二十首 流杯亭','李德裕','quantangshi','','卷26','激水自山椒，析波分浅濑。
回环疑古篆，诘曲如萦带。
宁愬羽觞迟，惟欢亲友会。
欲知中圣处，皓月临松盖。','',''),('quantangshi-25469','春暮思平泉杂咏二十首 东溪','李德裕','quantangshi','','卷26','近蓄东溪水，悠悠起渌波。
彩鸳留不去，芳草日应多。
夹岸生奇筱，缘岩覆女萝。
兰桡思无限，为感濯缨歌。','',''),('quantangshi-25470','春暮思平泉杂咏二十首 鸂鶒','李德裕','quantangshi','','卷26','清沚双鸂鶒，前年海上雏。
今年恋洲屿，思若在江湖。
欲起摇荷盖，闲飞溅水珠。
不能常泛泛，惟作逐波凫。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-25471','春暮思平泉杂咏二十首 西园','李德裕','quantangshi','','卷26','西园最多趣，永日自忘归。
石濑流清浅，风岑澹翠微。
晓翻红药艳，晴袅碧潭辉。
独望娟娟月，宵分半掩扉。','',''),('quantangshi-25472','春暮思平泉杂咏二十首 海石楠','李德裕','quantangshi','','卷26','昔见历阳山，鸡笼已孤秀。
今看海峤树，翠盖何幽茂。
霰雪讵能侵，烟岚自相揉。
攀条独临憩，况值清阴昼。','',''),('quantangshi-25473','春暮思平泉杂咏二十首 双碧潭','李德裕','quantangshi','','卷26','清剡与严湍，潺湲皆可忆。
适来玩山水，无此秋潭色。
莫辨幽兰丛，难分翠禽翼。
迟迟洲渚步，临眺忘餐食。','',''),('quantangshi-25474','春暮思平泉杂咏二十首 竹径','李德裕','quantangshi','','卷26','野竹自成径，绕溪三里余。
檀栾被层阜，萧瑟荫清渠。
日落见林静，风行知谷虚。
田家故人少，谁肯共焚鱼。','',''),('quantangshi-25475','春暮思平泉杂咏二十首 花药栏','李德裕','quantangshi','','卷26','蕙草春已碧，兰花秋更红。
四时发英艳，三径满芳丛。
秀色濯清露，鲜辉摇惠风。
王孙未知返，幽赏竟谁同。','',''),('quantangshi-25476','春暮思平泉杂咏二十首 自叙','李德裕','quantangshi','','卷26','五岳径虽深，遍游心已荡。
苟能知止足，所遇皆清旷。
七十难可期，一丘乃微尚。
遥怀少室山，常恐非吾望。','',''),('quantangshi-25477','首夏清景想望山居','李德裕','quantangshi','','卷26','嘉树阴初合，山中赏更新。
禽言未知夏，兰径尚余春。
散满萝垂带，扶疎桂长轮。
丹青写不尽，宵梦叹非真。
累榭空留月，虚舟若待人。
何时倚兰棹，相与掇汀苹。','',''),('quantangshi-25478','思平泉树石杂咏一十首 钓台','李德裕','quantangshi','','卷26','我有严湍思，怀人访故台。
客星依钓隐，仙石逐槎回。
倒影含清沚，凝阴长碧苔。
飞泉信可挹，幽客未归来。','',''),('quantangshi-25479','思平泉树石杂咏一十首 似鹿石','李德裕','quantangshi','','卷26','林中有奇石，仿髴兽潜行。
乍似依岩桂，还疑食野苹。
茸长绿藓映，斑细紫苔生。
不是见羇者，何劳如顿缨。','',''),('quantangshi-25480','思平泉树石杂咏一十首 海上石笋','李德裕','quantangshi','','卷26','常爱仙都山，奇峰千仞悬。
迢迢一何迥，不与众山连。
忽逢海峤石，稍慰平生忆。
何以慰我心，亭亭孤且直。','',''),('quantangshi-25481','思平泉树石杂咏一十首 叠石','李德裕','quantangshi','','卷26','潺湲桂水湍，漱石多奇状。
鳞次冠烟霞，蝉联叠波浪。
今来碧梧下，迥出秋潭上。
岁晚苔藓滋，怀贤益惆怅。','',''),('quantangshi-25482','思平泉树石杂咏一十首 重台芙蓉','李德裕','quantangshi','','卷26','芙蓉含露时，秀色波中溢。
玉女袭朱裳，重重映皓质。
晨霞耀丹景，片片明秋日。
兰泽多众芳，妍姿不相匹。','',''),('quantangshi-25483','思平泉树石杂咏一十首 白鹭鹚','李德裕','quantangshi','','卷26','余心怜白鹭，潭上日相依。
拂石疑星落，凌风似雪飞。
碧沙常独立，清景自忘归。
所乐惟烟水，徘徊恋钓矶。','',''),('quantangshi-25484','思平泉树石杂咏一十首 海鱼骨','李德裕','quantangshi','','卷26','昔日任公子，期年钓此鱼。
无由见成岳，聊喜识专车。
皎皎连霜月，高高映碧渠。
陶潜虽好事，观海只披图。','',''),('quantangshi-25485','思平泉树石杂咏一十首 泛池舟','李德裕','quantangshi','','卷26','桂舟兰作枻，芬芳皆绝世。
只可弄潺湲，焉能济大川。
树悬凉夜月，风散碧潭烟。
未得同鱼子，菱歌共扣舷。','',''),('quantangshi-25486','思平泉树石杂咏一十首 舴艋舟','李德裕','quantangshi','','卷26','无轻舴艋舟，始自鸱夷子。
双阙挂朝衣，五湖极烟水。
时游杏坛下，乍入湘川里。
永日歌濯缨，超然谢尘滓。','',''),('quantangshi-25487','思平泉树石杂咏一十首 二猿','李德裕','quantangshi','','卷26','钓濑水涟漪，富春山合沓。
松上夜猿鸣，谷中清响合。
冲网忽见羁，故山从此辞。
无由碧潭饮，争接绿萝枝。','',''),('quantangshi-25488','思在山居日偶成此咏邀松阳子同作','李德裕','quantangshi','','卷26','闲思昔岁事，忽忽念伊川。
乘月步秋坂，满山闻石泉。
回塘碧潭映，高树绿萝悬。
露下呌田鹤，风来嘶晚蝉。
怀兹长在梦，归去且无缘。
幽谷人未至，兰苕应更鲜。','',''),('quantangshi-25489','重忆山居六首 平泉源','李德裕','quantangshi','','卷26','出谷才浮芥，中园已滥觞。
逶迤过竹坞，浩淼走兰塘。
夜静闻鱼跃，风微见雁翔。
从兹东向海，可泛济川航。','',''),('quantangshi-25490','重忆山居六首 泰山石','李德裕','quantangshi','','卷26','鸡鸣日观望，远与扶桑对。
沧海似镕金，众山如点黛。
遥知碧峰首，独立烟岚内。
此石依五松，苍苍几千载。','',''),('quantangshi-25491','重忆山居六首 巫山石','李德裕','quantangshi','','卷26','十二峰前月，三声猿夜愁。
此中多怪石，日夕漱寒流。
必是归星渚，先求历斗牛。
还疑烟雨霁，仿髴是嵩丘。','',''),('quantangshi-25492','重忆山居六首 罗浮山','李德裕','quantangshi','','卷26','龙伯钓鳌时，蓬莱一峰坼。
飞来碧海畔，遂与三山隔。
其下多长溪，潺湲淙乱石。
知君分如此，赠逾荆山璧。','',''),('quantangshi-25493','重忆山居六首 漏潭石','李德裕','quantangshi','','卷26','常疑六合外，未信漆园书。
及此闻溪漏，方欣验尾闾。
大哉天地气，呼吸有盈虚。
美石劳相赠，琼瑰自不如。','',''),('quantangshi-25494','重忆山居六首 钓石','李德裕','quantangshi','','卷26','严光隐富春，山色溪又碧。
所钓不在鱼，挥纶以自适。
余怀慕君子，且欲坐潭石。
持此返伊川，悠然慰衰疾。','',''),('quantangshi-25495','怀伊川郊居','李德裕','quantangshi','','卷26','衰疾常怀土，郊园欲掩扉。
虽知明目地，不及有身归。
巩树秋阴遍，伊原霁色微。
此生看白首，良愿已应违。','',''),('quantangshi-25496','晨起见雪忆山居','李德裕','quantangshi','','卷26','忽忆岩中雪，谁人拂薜萝。
竹梢低未举，松盖偃应多。
山溜随冰落，林麕带霰过。
不劳闻鹤语，方奏苦寒歌。','',''),('quantangshi-25497','忆平泉杂咏 忆初暖','李德裕','quantangshi','','卷26','今日初春暖，山中事若何。
雪开喧鸟至，澌散跃鱼多。
幽翠生松栝，轻烟起薜萝。
柴扉常昼掩，惟有野人过。','',''),('quantangshi-25498','忆平泉杂咏 忆辛夷','李德裕','quantangshi','','卷26','昔年将出谷，几日对辛夷。
倚树怜芳意，攀条惜岁滋。
清阴须暂憩，秀色正堪思。
只待挥金日，殷勤泛羽巵。','',''),('quantangshi-25499','忆平泉杂咏 忆寒梅','李德裕','quantangshi','','卷26','寒塘数树梅，常近腊前开。
雪映缘岩竹，香侵泛水苔。
遥思清景暮，还有野禽来。
谁是攀枝客，兹辰醉始回。','',''),('quantangshi-25500','忆平泉杂咏 忆药栏','李德裕','quantangshi','','卷26','野人清旦起，扫雪见兰芽。
始畎春泉入，惟愁暮景斜。
未抽萱草叶，才发欵冬花。
谁念江潭老，中宵旅梦赊。','',''),('quantangshi-25501','忆平泉杂咏 忆茗芽','李德裕','quantangshi','','卷26','谷中春日暖，渐忆掇茶英。
欲及清明火，能销醉客酲。
松花飘鼎泛，兰气入瓯轻。
饮罢闲无事，扪萝溪上行。','',''),('quantangshi-25502','忆平泉杂咏 忆野花','李德裕','quantangshi','','卷26','虽游洛阳道，未识故园花。
晓忆东溪雪，晴思冠岭霞。
谷深兰色秀，村迥柳阴斜。
怅望龙门晚，谁知小隐家。','',''),('quantangshi-25503','忆平泉杂咏 忆春雨','李德裕','quantangshi','','卷26','春鸠鸣野树，细雨入池塘。
潭上花微落，溪边草更长。
梳风白鹭起，拂水彩鸳翔。
最羡归飞燕，年年在故乡。','',''),('quantangshi-25504','忆平泉杂咏 忆晚眺','李德裕','quantangshi','','卷26','伊川新雨霁，原上见春山。
缑岭晴虹断，龙门宿鸟还。
牛羊平野外，桑柘夕烟间。
不及乡园叟，悠悠尽日闲。','',''),('quantangshi-25505','忆平泉杂咏 忆新藤','李德裕','quantangshi','','卷26','遥闻碧潭上，春晚紫藤开。
水似晨霞照，林疑彩凤来。
清香凝岛屿，繁艳映莓苔。
金谷如相并，应将锦帐回。','',''),('quantangshi-25506','忆平泉杂咏 忆春耕','李德裕','quantangshi','','卷26','郊外杏花坼，林间布谷鸣。
原田春雨后，溪水夕流平。
野老荷蓑至，和风吹草轻。
无因共沮溺，相与事岩耕。','',''),('quantangshi-25507','余所居平泉村舍近蒙韦常侍大尹特改嘉名因寄诗以谢','李德裕','quantangshi','','卷26','未谢留侯疾，常怀仲蔚园。
闲谣紫芝曲，归梦赤松村。
忽改蓬蒿色，俄吹黍谷暄。
多慙孔北海，传教及衡门。','',''),('quantangshi-25508','山信至说平泉别墅草木滋长地转幽深怅然思归复此作','李德裕','quantangshi','','卷26','忽闻樵客语，暂慰野人心。
幽径芳兰密，闲庭秀木深。
麕䴥来涧底，凫鹄遍川浔。
谁念沧溟上，归欤起叹音。','',''),('quantangshi-25509','临海太守惠予赤城石报以是诗','李德裕','quantangshi','','卷26','闻君采奇石，剪断赤城霞。
潭上倒虹影，波中摇日华。
仙岩接绛气，溪路杂桃花。
若值客星去，便应随海槎。','',''),('quantangshi-25510','上巳忆江南禊事','李德裕','quantangshi','','卷26','黄河西绕郡城流，上巳应无祓禊游。
为忆渌江春水色，更无宵梦向吴州。','',''),('quantangshi-25511','北固怀古','李德裕','quantangshi','','卷26','自有此山川，于今几太守。
近世二千石，毕公宣化厚。
丞相量纳川，平阳气冲斗。
三贤若时雨，所至跻仁寿。','',''),('quantangshi-25512','汨罗','李德裕','quantangshi','','卷26','远谪南荒一病身，停舟暂吊汨罗人。
都缘靳尚图专国，岂是怀王厌直臣。
万里碧潭秋景静，四时愁色野花新。
不劳渔父重相问，自有招魂拭泪巾。','',''),('quantangshi-25513','岭外守岁','李德裕','quantangshi','','卷26','冬逐更筹尽，春随斗柄回。
寒暄一夜隔，客鬓两年催。','',''),('quantangshi-25514','记韦楚老不遇','李德裕','quantangshi','','卷26','昔日征黄绮，余惭在凤池。
今来招隐士，恨不见琼枝。','',''),('quantangshi-25515','题柳郎中故居','李德裕','quantangshi','','卷26','下马荒堦日欲曛，潺潺石溜静中闻。
鸟啼花发人声绝，寂寞山窗掩白云。','',''),('quantangshi-25516','盘陀岭驿楼','李德裕','quantangshi','','卷26','嵩少心期杳莫攀，好山聊复一开颜。
明朝便是南荒路，更上层楼望故关。','',''),('quantangshi-25517','句','李德裕','quantangshi','','卷26','检经求绿字，凭酒借红颜。
君不见秋山寂历风飙歇，半夜青崖吐明月。
寒光乍出松筱间，万籁萧萧从此发。
忽闻歌管吟朔风，精魂想在幽岩中。
银花悬院榜，神撼引铃縧。
葳蕤轻风里，若衔若垂何可拟。
自从一梦高唐后，可是无人胜楚王。
牛羊具特俎，心悟觉身劳。
云中弃宝刀，久闲生䏶肉。
多寿长眉毫，书空跷足睡。
路险侧身行，谁家幼女敲筯歌。
何处丁妻点灯织，鱼虾集橘市。
休咎占人甲，挨持见天丁。
洛下推年少，山东许地高。
世上文章士，谁为第一人。
老生夸隐拙，时辈毁尖新。
𭲟濴寒深百尺，奇觚率尔操。
讽谏欣然纳。','',''),('quantangshi-25518','至日荷李常侍过郊居','熊孺登','quantangshi','','卷26','贱子守柴荆，谁人记姓名。
风云千骑降，草木一阳生。
礼异江河动，欢殊里巷惊。
称觞容侍坐，看竹许同行。
遇觉沧溟浅，恩疑太岳轻。
尽搜天地物，无谕此时情。','',''),('quantangshi-25519','日暮天无云','熊孺登','quantangshi','','卷26','杳杳复苍然，无云日暮天。
象分青气外，景尽赤霄前。
渐吐星河色，遥生水木烟。
从容难附丽，顾步欲澄鲜。
但见收三素，何能测上玄。
应非暂呈瑞，不许出山川。','',''),('quantangshi-25520','新成小亭月夜','熊孺登','quantangshi','','卷26','已被月知处，斩新风到来。
无人伴幽境，多取木兰栽。','',''),('quantangshi-25521','和窦中丞岁酒喜见小男两岁','熊孺登','quantangshi','','卷26','更添十岁应为相，岁酒从今把未休。
闻得一毛添五色，眼看相逐凤池头。','',''),('quantangshi-25522','寒食','熊孺登','quantangshi','','卷26','东风泼火雨新休，舁尽春泥扫雪沟。
走马犊车当御路，汉阳公主谢鸡球。','',''),('quantangshi-25523','送僧游山','熊孺登','quantangshi','','卷26','云身自在山山去，何处灵山不是归？日暮寒林投古寺，雪花飞满水田衣。','',''),('quantangshi-25524','雪中答僧书','熊孺登','quantangshi','','卷26','八行银字非常草，六出天花尽是梅。
无所与陈童子别，雪中辛苦远山来。','',''),('quantangshi-25525','题逍遥楼伤故韦大夫','熊孺登','quantangshi','','卷26','利及生人无更为，落花流水旧城池。
逍遥楼上雕龙字，便是羊公堕泪碑。','',''),('quantangshi-25526','戏赠费冠卿','熊孺登','quantangshi','','卷26','但恐红尘虚白首，宁论蹇逸分先后。
莫占莺花笑寂寥，长安春色年年有。','',''),('quantangshi-25527','与左兴宗湓城别','熊孺登','quantangshi','','卷26','江逢九派人将别，猨到三声月为秋。
不知相见更何日，此夜少年堪白头。','',''),('quantangshi-25528','八月十五夜卧疾','熊孺登','quantangshi','','卷26','一年秪有今宵月，尽上江楼独病眠。
寂寞竹窗闲不闭，夜深斜影到牀前。','',''),('quantangshi-25529','正月十五日','熊孺登','quantangshi','','卷26','汉家遗事今宵见，楚郭明灯几处张。
深夜行歌声绝后，紫姑神下月苍苍。','',''),('quantangshi-25530','曲池陪宴即事上窦中丞','熊孺登','quantangshi','','卷26','水自山阿绕坐来，珊瑚台上木绵开。
欲知举目无情罚，一片花流酒一杯。','',''),('quantangshi-25531','董监庙','熊孺登','quantangshi','','卷26','仁杰淫祠废欲无，枯枫老栎两三株。
神乌惯得商人食，飞趂征帆过蠡湖。','',''),('quantangshi-25532','赠侯山人','熊孺登','quantangshi','','卷26','一见清容惬素闻，有人传是紫阳君。
来时玉女裁春服，翦破湘山几片云。','',''),('quantangshi-25533','送马判官赴安南','熊孺登','quantangshi','','卷26','故人交趾去从军，应笑狂生挥阵云。
省得蔡州今日事，旧曾都护帐前闻。','',''),('quantangshi-25534','送准上人归石经院','熊孺登','quantangshi','','卷26','旃檀刻像今犹少，白石镌经古未曾。
归去更寻翻译寺，前山应遇雁门僧。','',''),('quantangshi-25535','寒食野望','熊孺登','quantangshi','','卷26','拜扫无过骨肉亲，一年唯此两三辰。
冢头莫种有花树，春色不关泉下人。','',''),('quantangshi-25536','祗役遇风谢湘中春色','熊孺登','quantangshi','','卷26','水生风熟布帆新，只见公程不见春。
应被百花撩乱笑，比来天地一闲人。','',''),('quantangshi-25537','湘江夜泛','熊孺登','quantangshi','','卷26','江流如箭月如弓，行尽三湘数夜中。
无那子规知向蜀，一声声似怨春风。','',''),('quantangshi-25538','蜀江水','熊孺登','quantangshi','','卷26','日夜朝宗来万里，共怜江水引蕃心。
若论巴峡愁人处，猨比滩声是好音。','',''),('quantangshi-25539','寄安南马中丞','熊孺登','quantangshi','','卷26','龙韬能致虎符分，万里霜台压瘴云。
蕃客不须愁海路，波神今伏马将军。','',''),('quantangshi-25540','甘子堂陪宴上韦大夫','熊孺登','quantangshi','','卷26','武陵楼上春长早，甘子堂前花落迟。
楚乐怪来声竞起，新歌尽是大夫词。','',''),('quantangshi-25541','青溪村居二首 一','熊孺登','quantangshi','','卷26','家占溪南千个竹，地临湖上一羣山。
渔船多在马长放，出处自由闲不闲。','',''),('quantangshi-25542','青溪村居二首 二','熊孺登','quantangshi','','卷26','深树黄[鹂]晓一声，林西江上月犹明。
野人早起无他事，贪绕沙泉看笋生。','',''),('quantangshi-25543','奉和兴元郑相公早春送杨侍郎','熊孺登','quantangshi','','卷26','征鞍欲上醉还留，南浦春生百草头。
丞相新裁别离曲，声声飞出旧梁州。','',''),('quantangshi-25544','送舍弟孺复往庐山','熊孺登','quantangshi','','卷26','能骑竹马辨西东，未省烟花暂不同。
第一早归春欲尽，庐山好看过湖风。','',''),('quantangshi-25545','野别留少微上人','熊孺登','quantangshi','','卷26','若为相见还分散，翻觉浮云亦不闲。
何处留师暂且住，家贫唯有坐中山。','',''),('quantangshi-25546','经古墓','熊孺登','quantangshi','','卷26','碑折松枯山火烧，夜台从闭不曾朝。
那将逝者比流水，流水东流逢上潮。','',''),('quantangshi-25547','赠灵彻上人','熊孺登','quantangshi','','卷26','诗句能生世界春，僧家更有姓汤人。
况闻暗忆前朝事，知是修行第几身。','',''),('quantangshi-25548','春郊醉中赠章八元','熊孺登','quantangshi','','卷26','三月踏青能几日，百回添酒莫辞频。
看君到卧杨花里，始觉春光为醉人。','',''),('quantangshi-25549','怀古','李涉','quantangshi','','卷26','尼父未适鲁，屡屡倦迷津。
徒怀教化心，纡郁不能伸。
一遇知己言，万方始喧喧。
至今百王则，孰不挹其源。','',''),('quantangshi-25550','咏古','李涉','quantangshi','','卷26','大智思济物，道行心始休。
垂纶自消息，岁月任春秋。
纣虐武既贤，风云固可求。
顺天行杀机，所向协良谋。
况以丈人师，将济安川流。
何劳问枯骨，再取阴阳筹。
霸国不务仁，兵戈恣相酬。
空令渭水迹，千古独悠悠。','',''),('quantangshi-25551','题清溪鬼谷先生旧居','李涉','quantangshi','','卷26','翠壁开天池，青崖列云树。
冰容不可状，杳若清河雾。
常闻先生教，指示秦仪路。
二子才不同，逞词过尺度。
偶因从吏役，远到冥栖处。
松月想旧山，烟霞了如故。
未遑炼金鼎，日觉容光暮。
万虑随境生，何由返真素。
寂寞天籁息，清逈鸟声曙。
回首望重重，无期挹风驭。','',''),('quantangshi-25552','感兴','李涉','quantangshi','','卷26','隋氏造宫阙，峨峨倚云烟。
搜奇竭四海，立制谋千年。
秦兵半夜来，烈火焚高台。
万人聚筋血，一旦为尘埃。
君看汴河路，尚说隋家柳。
但问哭陵人，秋草没来久。','',''),('quantangshi-25553','鹧鸪词二首 一','李涉','quantangshi','','卷26','湘江烟水深，沙岸隔枫林。
何处鹧鸪飞，日斜斑竹阴。
二女空垂泪，三闾枉自沉。
惟有鹧鸪啼，独伤行客心。','',''),('quantangshi-25554','鹧鸪词二首 二','李涉','quantangshi','','卷26','越冈连越井，越鸟更南飞。
何处鹧鸪啼，夕烟东岭归。
岭外行人少，天涯北客稀。
鹧鸪啼别处，相对泪沾衣。','',''),('quantangshi-25555','山中','李涉','quantangshi','','卷26','无奈牧童何，放牛吃我竹。
隔林呼不譍，呌笑如生鹿。
欲报田舍翁，更深不归屋。','',''),('quantangshi-25556','寄荆娘写真','李涉','quantangshi','','卷26','章华台南莎草齐，长河柳色连金堤。
青楼曈昽曙光蚤，梨花满巷莺新啼。
章台玉颜年十六，小来能唱西梁曲。
教坊大使久知名，郢上词人歌不足。
少年才子心相许，夜夜高堂梦云雨。
五铢香帔结同心，三寸红牋替传语。
缘池并戏双鸳鸯，田田翠叶红莲香。
百年恩爱两相许，一夕不见生愁肠。
上清仙女征游伴，欲从湘灵住河汉。
只愁陵谷变人寰，空叹桑田归海岸。
愿分精魄定形影，永似银壶挂金井。
召得丹青绝世工，写真与身真相同。
忽然相对两不语，疑是妆成来镜中。
岂期人愿天不违，云軿却驻从山归。
画图封裹寄箱箧，洞房艳艳生光辉。
良人翻作东飞翼，却遣江头问消息。
经年不得一封书，翠幕云屏遶空壁。
结客有少年，名总身姓江。
征帆三千里，前月发豫章。
知我别时言，识我马上郎。
恨无羽翼飞，使我徒怨沧波长。
开箧取画图，寄我形影与客将。
如今憔悴不相似，恐君重见生悲伤。
苍梧九疑在何处，斑斑竹泪连潇湘。','',''),('quantangshi-25557','与弟渤新罗劒歌','李涉','quantangshi','','卷26','我有神劒异人与，暗中往往精灵语。
识者知从东海来，来时一夜因风雨。
长河临晓北斗残，秋水露背青螭寒。
昨夜大梁城下宿，不借𨁂跌光颜看。
刃边飒飒尘沙缺，瘢痕半是蛟龙血。
雷焕张华久已无，沉冤知向何人说。
我有爱弟都九江，一条直气今无双。
青光好去莫惆怅，必斩长鲸须少壮。','',''),('quantangshi-25558','六叹 一','李涉','quantangshi','','卷26','绮罗香风翡翠车，清明独傍芙蓉渠。
上有云鬟洞仙女，垂罗掩縠烟中语。
风月频惊桃李时，沧波久别鸳鸿侣。
欲传一札孤飞翼，山长水远无消息。
却锁重门一院深，半夜空庭明月色。','',''),('quantangshi-25559','六叹 二','李涉','quantangshi','','卷26','深院梧桐夹金井，上有辘轳青丝索。
美人清昼汲寒泉，寒泉欲上银瓶落。
迢迢碧甃千余尺，竟日倚阑空叹息。
惆怅不来照明镜，却掩洞房抱寂寂。','',''),('quantangshi-25560','六叹 三','李涉','quantangshi','','卷26','汉臣一没丁零塞，牧羊西过阴沙外。
朝凭南雁信难回，夜望北辰心独在。
汉家茅土横九州，高门长戟封王侯。
但将钟鼓悦私爱，肯以犬羊为国羞。
夜宿寒云卧冰雪，严风触刃垂旌节。
丁年奉使白头归，泣尽李陵衣上血。','',''),('quantangshi-25561','春山三朅来 一','李涉','quantangshi','','卷26','钓鱼朅来春日暖，沿溪不厌舟行缓。
野竹初栽碧玉长，澄潭欲下青丝短。
昔人避世兼避讐，暮栖云外朝悠悠。
我今无事亦如此，赤鲤忽到长竿头。
泛泛随波凡几里，碧莎如烟沙似砥。
瘦壁横空怪石危，山花鬬日禽争水。
有时带月归扣舷，身闲自是渔家仙。','',''),('quantangshi-25562','春山三朅来 二','李涉','quantangshi','','卷26','山上朅来采新茗，新花乱发前山顶。
琼英动摇钟乳碧，业业高下随崖岭。
未必蓬莱有仙药，能向鼎中云漠漠。
越瓯遥见裂鼻香，欲觉身轻骑白鹤。','',''),('quantangshi-25563','春山三朅来 三','李涉','quantangshi','','卷26','采药朅来药苗盛，药生只傍行人径。
世人重耳不重目，指似药苗心不足。
野客住山三十载，妻儿共寄浮云外。
小男学语便分别，已辩君臣知匹配。
都市广长开大铺，疾来求者多相悞。
见说韩康旧姓名，识之不识先相怒。','',''),('quantangshi-25564','牧童词','李涉','quantangshi','','卷26','朝牧牛，牧牛下江曲。
夜牧牛，牧牛度村谷。
荷蓑出林春雨细，芦管卧吹莎草绿。
乱插蓬蒿箭满腰，不怕猛虎欺黄犊。','',''),('quantangshi-25565','醉中赠崔膺','李涉','quantangshi','','卷26','与君兄弟匡岭故，与君相逢扬子渡。
白浪南分吴塞云，绿杨深入隋宫路。
隋家文物今虽改，舞馆歌台基尚在。
炀帝陵边草木深，汴河流水空归海。
古今悠悠人自别，此地繁华终未歇。
大道青楼夹翠烟，琼墀绣帐开明月。
与君一言两相许，外舍形骸中尔女。
扬州歌酒不可追，洛神映箔湘妃语。
白马黄金为身置，谁能独羡他人醉。
暂到香炉一夕间，能展愁眉百世事。
君看白日光如箭，一度别来颜色变。
早谋侯印佩腰间，莫遣看花鬓如霰。','',''),('quantangshi-25566','岳阳别张[祜]','李涉','quantangshi','','卷26','十年蹭蹬为逐臣，鬓毛白尽巴江春。
鹿鸣猨啸虽寂寞，水蛟山魅多精神。
山疟困中闻有赦，死灰不望光阴借。
半夜州符唤牧童，虚教衰病生惊怕。
巫峡洞庭千里余，蛮陬水国何亲疎。
由来真宰不宰我，徒劳叹者怀吹嘘。
霸桥昔与张生别，万变桑田何处说。
龙蛇纵在没泥涂，长衢却为驽骀设。
爱君气坚风骨峭，文章真把江淹笑。
洛下诸生惧刺先，乌鸢不得齐鹰鹞。
岳阳西南湖上寺，水阁松房遍文字。
新钉张生一首诗，自余吟着皆无味。
策马前途须努力，莫学龙钟虚叹息。','',''),('quantangshi-25567','寄河阳从事杨潜','李涉','quantangshi','','卷26','忆昨天台寻石梁，赤城枕下看扶桑。
金乌欲上海如血，翠色一点蓬莱光。
安期先生不可见，蓬莱目极沧海长。
回舟偶得风水便，烟帆数夕归潇湘。
潇湘水清岩嶂曲，夜宿朝游常不足。
一自无名身事闲，五湖云月偏相属。
进者恐不荣，退者恐不深。
鱼游鸟逝两虽异，彼此各有遂生心。
身解耕耘妾能织，岁晏饥寒免相逼。
稚子才年七岁余，渔樵一半分渠力。
吾友从军在河上，腰佩吴钩佐飞将。
偶与嵩山道士期，西寻汴水来相访。
见君颜色犹憔悴，知君未展心中事。
落日驱车出孟津，高歌共叹伤心地。
洛邑秦城少年别，两都陈事空闻说。
汉家天子不东游，古木行宫闭烟月。
洛滨老翁年八十，西望残阳临水泣。
自言生长开元中，武皇恩化亲霑及。
当时天下无甲兵，虽闻赋敛毫毛轻。
红车翠盖满衢路，洛中欢笑争逢迎。
一从戎马来幽蓟，山谷虎狼无捍制。
九重宫殿闭豺狼，万国生人自相噬。
蹭蹬疮痍今不平，干戈南北常纵横。
中原膏血焦欲尽，四郊贪将犹凭陵。
秦中豪宠争出羣，巧将言智宽明君。
南山四皓不敢语，渭上钓人何足云。
君不见昔时槐柳八百里，路傍五月清阴起。
只今零落几株残，枯根半死黄河水。','',''),('quantangshi-25568','重登滕王阁','李涉','quantangshi','','卷26','滕王阁上唱伊州，二十年前向此游。
