纵使鸡鸣遇关吏，不知余也是何人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-25657','奉和九弟渤见寄绝句','李涉','quantangshi','','卷26','忽启新缄吟近诗，诗中韵出碧云词。
且喜陟冈愁已散，登舟只恨渡江迟。','',''),('quantangshi-25658','赠友人孩子','李涉','quantangshi','','卷26','骊龙颔下亦生珠，便与人间众宝殊。
他时若要追风日，须得君家万里驹。','',''),('quantangshi-25659','奉宣慰使鱼十四郎','李涉','quantangshi','','卷26','年才二十众知名，孤鹤仪容彻骨清。
口传天语来人世，却逐祥云上玉京。','',''),('quantangshi-25660','题善光寺','李涉','quantangshi','','卷26','云门天竺旧姻缘，临老移家住玉泉。
早到可中涢南寺，免得翻经住几年。','',''),('quantangshi-25661','题宣化寺道光上人居','李涉','quantangshi','','卷26','二十年前不系身，草堂曾与雪为邻。
常思和尚当时语，衣钵留将与此人。','',''),('quantangshi-25662','柳枝词','李涉','quantangshi','','卷26','锦池江上柳垂桥，风引蝉声送寂寥。
不必如丝千万缕，只禁离恨两三条。','',''),('quantangshi-25663','竹枝词','李涉','quantangshi','','卷26','十二山晴花尽开，楚宫双阙对阳台。
细腰争舞君沈醉，白日秦兵天下来。','',''),('quantangshi-25664','竹里','李涉','quantangshi','','卷26','竹里编茅倚石[根]，竹茎疎处见前村。
闲眠尽日无人到，自有春风为扫门。','',''),('quantangshi-25665','失题','李涉','quantangshi','','卷26','华表千年一鹤归，丹砂为顶雪为衣。
泠泠仙语人听尽，却向五云翻翅飞。','',''),('quantangshi-25666','云安公主下降奉诏作催妆诗','陸暢','quantangshi','','卷26','云安公主贵，出嫁五侯家。
天母亲调粉，日兄怜赐花。
催铺百子帐，待障七香车。
借问妆成未，东方欲晓霞。','',''),('quantangshi-25667','山出云','陸暢','quantangshi','','卷26','灵山蓄云彩，纷郁出清晨。
望树繁花白，看峰小雪新。
映松张盖影，依涧布鱼鳞。
高似从龙处，低如触石频。
浓光藏半岫，浅色类飘尘。
玉叶开天际，遥怜占早春。','',''),('quantangshi-25668','惊雪','陸暢','quantangshi','','卷26','怪得北风急，前庭如月辉。
天人宁许巧，翦水作花飞。','',''),('quantangshi-25669','闻早蝉','陸暢','quantangshi','','卷26','落日早蝉急，客心闻更愁。
一声来枕上，梦里故园秋。','',''),('quantangshi-25670','别刘端公','陸暢','quantangshi','','卷26','连骑出都门，秋蝉噪高柳。
落日辞故人，自醉不关酒。','',''),('quantangshi-25671','新晴爱月','陸暢','quantangshi','','卷26','野性平生惟爱月，新晴半夜覩婵娟。
起来自擘纱窗破，恰漏清光落枕前。','',''),('quantangshi-25672','云安公主出降杂咏催妆二首 一','陸暢','quantangshi','','卷26','天上琼花不避秋，今宵织女嫁牵牛。
万人惟待乘鸾出，乞巧齐登明月楼。','',''),('quantangshi-25673','云安公主出降杂咏催妆二首 二','陸暢','quantangshi','','卷26','少妆银粉饰金钿，端正天花贵自然。
闻道禁中时节异，九秋香满镜台前。','',''),('quantangshi-25674','坐障','陸暢','quantangshi','','卷26','白玉为竿丁字成，黄金绣带短长轻。
强遮天上花颜色，不隔云中语笑声。','',''),('quantangshi-25675','帘','陸暢','quantangshi','','卷26','劳将素手卷虾须，琼室流光更缀珠。
玉漏报来过半夜，可怜潘岳立踟蹰。','',''),('quantangshi-25676','阶','陸暢','quantangshi','','卷26','甃玉编金次第平，花纹隐起踏无声。
几重便上华堂里，得见天人吹凤笙。','',''),('quantangshi-25677','扇','陸暢','quantangshi','','卷26','宝扇持来入禁宫，本教花下动香风。
姮娥须逐彩云降，不可通宵在月中。','',''),('quantangshi-25678','解内人嘲','陸暢','quantangshi','','卷26','粉面仙郎选圣朝，偶逢秦女学吹箫。
须教翡翠闻王母，不奈乌鸢噪鹊桥。','',''),('quantangshi-25679','成都赠别席夔','陸暢','quantangshi','','卷26','不值分流二江水，定应犹得且同行。
三千里外情人别，更被子规啼数声。','',''),('quantangshi-25680','游城东王驸马亭','陸暢','quantangshi','','卷26','城外无尘水间松，秋天木落见山容。
共寻萧史江亭去，一望终南紫阁峰。','',''),('quantangshi-25681','望毛女峰','陸暢','quantangshi','','卷26','我种东峰千叶莲，此峰毛女始求仙。
今朝暗算当时事，已是人间七万年。','',''),('quantangshi-25682','送李山人归山','陸暢','quantangshi','','卷26','来从千山万山里，归向千山万山去。
山中白云千万重，却望人间不知处。','',''),('quantangshi-25683','长安新晴','陸暢','quantangshi','','卷26','九重深浅人不知，金殿玉楼倚朝日。
一夜城中新雨晴，御沟流得宫花出。','',''),('quantangshi-25684','出蓝田关寄董使君','陸暢','quantangshi','','卷26','万里烟萝锦帐间，云迎水送度蓝关。
七盘九折难行处，尽是龚黄界外山。','',''),('quantangshi-25685','题悟公禅室','陸暢','quantangshi','','卷26','临坛付法十三春，家本长城若下人。
芸阁少年应不识，南山钞主是前身。','',''),('quantangshi-25686','宿陕府北楼奉酬崔大夫二首 一','陸暢','quantangshi','','卷26','楼压黄河山满坐，风清水凉谁忍卧。
人定军州禁漏传，不妨秋月城头过。','',''),('quantangshi-25687','宿陕府北楼奉酬崔大夫二首 二','陸暢','quantangshi','','卷26','一别朱门三四春，再来应笑尚风尘。
昨宵唯有楼前月，识是谢公诗酒人。','',''),('quantangshi-25688','陕州逢窦巩同宿寄江陵韦协律','陸暢','quantangshi','','卷26','共出丘门岁九霜，相逢凄怆对离觞。
荆南为报韦从事，一宿同眠御史牀。','',''),('quantangshi-25689','夜到泗州酬崔使君','陸暢','quantangshi','','卷26','徐城洪尽到淮头，月里山河见泗州。
闻道泗滨清庙磬，雅声今在谢家楼。','',''),('quantangshi-25690','送崔员外使回入京金钩驿逢因赠','陸暢','quantangshi','','卷26','六星宫里一星归，行到金钩近紫微。
侍史别来经岁月，今宵应梦护香衣。','',''),('quantangshi-25691','成都送别费冠卿','陸暢','quantangshi','','卷26','红椒花落桂花开，万里同游俱未回。
莫厌客中频送客，思乡独上望乡台。','',''),('quantangshi-25692','题商山庙','陸暢','quantangshi','','卷26','商洛秦时四老翁，人传羽化此山空。
若无仙眼何由见，总在庙前花洞中。','',''),('quantangshi-25693','题独孤少府园林','陸暢','quantangshi','','卷26','四面青山是四隣，烟霞成伴草成茵。
年年洞口桃花发，不记曾经迷几人。','',''),('quantangshi-25694','送独孤秀才下第归太白山','陸暢','quantangshi','','卷26','逸翮暂时成落羽，将归太白赏灵踪。
须寻最近碧霄处，拟倩和云买一峰。','',''),('quantangshi-25695','下第后病中','陸暢','quantangshi','','卷26','献玉频年命未通，穷秋成病悟真空。
笑看朝市趋名者，不病那知在病中。','',''),('quantangshi-25696','送深上人归江南','陸暢','quantangshi','','卷26','留得莲花偈付谁，独携金策欲归时。
江南无限萧家寺，曾与白云何处期。','',''),('quantangshi-25697','题自然观','陸暢','quantangshi','','卷26','劒阁门西第一峰，道陵成道有高踪。
行人若上升仙处，须拨白云三四重。','',''),('quantangshi-25698','疾愈步庭花','陸暢','quantangshi','','卷26','桃红李白觉春归，强步闲庭力尚微。
从困不扶灵寿杖，恐惊花里早莺飞。','',''),('quantangshi-25699','筹笔店江亭','陸暢','quantangshi','','卷26','九折岩边下马行，江亭暂歇听江声。
白云绿树不关我，枉与樵人乐一生。','',''),('quantangshi-25700','赠贺若少府','陸暢','quantangshi','','卷26','十日广陵城里住，听君花下抚金徽。
新声指上怀中纸，莫怪潜偷数曲归。','',''),('quantangshi-25701','太子刘舍人邀看花','陸暢','quantangshi','','卷26','年少风流七品官，朱衣白马冶游盘。
负心不报春光主，几处偷看红牡丹。','',''),('quantangshi-25702','蔷薇花','陸暢','quantangshi','','卷26','锦窠花朵灯业醉，翠叶眉稠裛露垂。
莫引美人来架下，恐惊红片落燕支。','',''),('quantangshi-25703','句','陸暢','quantangshi','','卷26','蜀道易，易于履平地。
蝉噪入云树，风开无主花。','',''),('quantangshi-25704','应制贺边军支春衣 一','柳公權','quantangshi','','卷26','去岁虽无战，今年未得归。
皇恩何以报，春日得春衣。','',''),('quantangshi-25705','应制贺边军支春衣 二','柳公權','quantangshi','','卷26','挟纩非真纩，分衣是假衣。
从今貔武士，不惮戍金微。','',''),('quantangshi-25706','应制为宫嫔咏','柳公權','quantangshi','','卷26','不分前时忤主恩，已甘寂寞守长门。
今朝却得君王顾，重入椒房拭泪痕。','',''),('quantangshi-25707','题朱审寺壁山水画','柳公權','quantangshi','','卷26','朱审偏能视夕岚，洞边深墨写秋潭。
与君一顾西墙画，从此看山不向南。','',''),('quantangshi-25708','阊门即事','柳公權','quantangshi','','卷26','耕夫占募逐楼船，春草青青万顷田。
试上吴门看郡郭，清明几处有新烟。','',''),('quantangshi-25709','贡院楼北新栽小松','吳武陵','quantangshi','','卷26','拂槛爱贞容，移根自远峰。
已曾经草没，终不任苔封。
叶少初陵雪，鳞生欲化龙。
乘春濯雨露，得地近垣墉。
逐吹香微动，含烟色渐浓。
时回日月照，为谢小山松。','',''),('quantangshi-25710','题路左佛堂','吳武陵','quantangshi','','卷26','雀儿来逐扬风高，下视鹰鹯意气豪。
自谓能生千里翼，黄昏依旧委蓬蒿。','',''),('quantangshi-25711','盛山十二诗 隐月岫','韋處厚','quantangshi','','卷26','初映钩如线，终衔镜似钩。
远澄秋水色，高倚晓河流。','',''),('quantangshi-25712','盛山十二诗 流杯渠','韋處厚','quantangshi','','卷26','激曲萦飞箭，浮沟泛满巵。
将来山太守，早向习家池。','',''),('quantangshi-25713','盛山十二诗 竹岩','韋處厚','quantangshi','','卷26','不资冬日秀，为作暑天寒。
先植诚非凤，来翔定是鸾。','',''),('quantangshi-25714','盛山十二诗 绣衣石榻','韋處厚','quantangshi','','卷26','巉巉雪中峤，磊磊标方峭。
勿为枕苍山，还当础清庙。','',''),('quantangshi-25715','盛山十二诗 宿云亭','韋處厚','quantangshi','','卷26','雨合飞危砌，天开卷晓窗。
齐平联郭柳，带绕抱城江。','',''),('quantangshi-25716','盛山十二诗 梅溪','韋處厚','quantangshi','','卷26','夹岸凝清素，交枝漾浅沦。
味调方荐实，腊近又先春。','',''),('quantangshi-25717','盛山十二诗 桃坞','韋處厚','quantangshi','','卷26','喷日舒红景，通蹊茂绿阴。
终期王母摘，不羡武陵深。','',''),('quantangshi-25718','盛山十二诗 胡卢沼','韋處厚','quantangshi','','卷26','疏凿徒为巧，圆洼自可澄。
倒花纷错秀，鉴月静涵冰。','',''),('quantangshi-25719','盛山十二诗 茶岭','韋處厚','quantangshi','','卷26','顾渚吴商绝，蒙山蜀信稀。
千丛因此始，含霞紫英肥。','',''),('quantangshi-25720','盛山十二诗 盘石磴','韋處厚','quantangshi','','卷26','缭绕缘云上，璘玢甃玉联。
高高曾几折，极目瞰秋鸢。','',''),('quantangshi-25721','盛山十二诗 琵琶台','韋處厚','quantangshi','','卷26','褊地难层土，因厓遂削成。
浅深岚嶂色，尽向此中呈。','',''),('quantangshi-25722','盛山十二诗 上士瓶泉','韋處厚','quantangshi','','卷26','绠汲岂无井，颠崖贵非浚。
愿洒尘垢余，一雨根茎润。','',''),('quantangshi-25723','客思吟','楊敬之','quantangshi','','卷26','禾黍正离离，南园剪白芝。
细腰沈赵女，高髻唱蛮姬。
路愧前冈月，梳惭一颔丝。
乡人不可语，独念畏人知。','',''),('quantangshi-25724','赠项斯','楊敬之','quantangshi','','卷26','几度见诗诗总好，及观标格过于诗。
平生不解藏人善，到处逢人说项斯。','',''),('quantangshi-25725','句','楊敬之','quantangshi','','卷26','霜树鸟栖夜，空街雀报明。
碧山相倚暮，归雁一行斜。','',''),('quantangshi-25726','初日照凤楼','李虞仲','quantangshi','','卷26','旭日烟云殿，朝阳烛帝居。
断霞生峻宇，通阁丽晴虚。
流彩连朱槛，腾辉照绮疏。
曈昽晨景里，明灭晓光初。
户牖仙山近，轩楹凤翼舒。
还如王母过，遥度五云车。','',''),('quantangshi-25727','郡斋三月下旬作','張又新','quantangshi','','卷26','春事日已歇，池塘旷幽寻。
残红披独坠，初绿间浅深。
偃仰倦芳褥，顾步爱新阴。
谋春未及竟，夏初遽见侵。','',''),('quantangshi-25728','五月水边柳','張又新','quantangshi','','卷26','结根挺涯涘，垂影覆清浅。
睡脸寒未开，嬾腰晴更软。
摇空条已重，拂水带方展。
似醉烟景凝，如愁月露泫。
丝长鱼悞恐，枝弱禽惊践。
怅别几多情，含春任攀搴。','',''),('quantangshi-25729','三月五日陪大夫泛长沙东湖','張又新','quantangshi','','卷26','上巳余风景，芳辰集远坰。
彩舟浮泛荡，绣毂下娉婷。
栖树回葱蒨，笙歌转杳冥。
湖光迷翡翠，草色醉蜻蜓。
鸟弄桐花日，鱼飜谷雨萍。
从今留胜会，谁看画兰亭。','',''),('quantangshi-25730','赠广陵妓','張又新','quantangshi','','卷26','云雨分飞二十年，当时求梦不曾眠。
今来头白重相见，还上襄王玳瑁筵。','',''),('quantangshi-25731','牡丹','張又新','quantangshi','','卷26','牡丹一朵值千金，将谓从来色最深。
今日满栏开似雪，一生辜负看花心。','',''),('quantangshi-25732','游白鹤山','張又新','quantangshi','','卷26','白鹤山边秋复春，张文宅畔少风尘。
欲驱五马寻真隐，谁是当初□竹人。','',''),('quantangshi-25733','行田诗','張又新','quantangshi','','卷26','白石岩前湖水春，湖边旧境有清尘。
欲追谢守行田意，今古同忧是长人。','',''),('quantangshi-25734','罗浮山','張又新','quantangshi','','卷26','江北重峦积翠浓，绮霞遥映碧芙蓉。
不知末后沧溟上，灭却瀛洲第几峰。','',''),('quantangshi-25735','青障山','張又新','quantangshi','','卷26','一派远光澄碧月，万株耸翠猎金飙。
陶仙谩学长生术，暑往寒来更寂寥。','',''),('quantangshi-25736','中界山','張又新','quantangshi','','卷26','瑟瑟峰头玉水流，晋时遗迹更堪愁。
愁人到此劳长望，何处烟波是祖州。','',''),('quantangshi-25737','帆游山','張又新','quantangshi','','卷26','涨海尝从此地流，千帆飞过碧山头。
君看深谷为陵后，翻覆人间未肯休。','',''),('quantangshi-25738','谢池','張又新','quantangshi','','卷26','郡郭东南积谷山，谢公曾是此跻攀。
今来惟有灵池月，犹是婵娟一水间。','',''),('quantangshi-25739','华盖山','張又新','quantangshi','','卷26','一岫坡陀凝绿草，千重虚翠透红霞。
愁来始上消归思，见尽江城数百家。','',''),('quantangshi-25740','吹台山','張又新','quantangshi','','卷26','吹台山上彩烟凝，日落云收叠翠屏。
应谓焦桐堪采斵，不知谁是柳吴兴。','',''),('quantangshi-25741','青㠗山','張又新','quantangshi','','卷26','灵海泓澄匝翠峰，昔贤心赏已成空。
今朝亭馆无遗制，积水沧浪一望中。','',''),('quantangshi-25742','孤屿','張又新','quantangshi','','卷26','碧水逶迤浮翠巘，绿萝蒙密媚晴江。
不知谁与名孤屿，其实中川是一双。','',''),('quantangshi-25743','春草池','張又新','quantangshi','','卷26','谢公梦草一差微，谪宦当时道不机。
且谓飞霞游赏地，池塘烟柳亦依依。','',''),('quantangshi-25744','春色满皇州','封敖','quantangshi','','卷26','帝里春光正，葱茏喜气浮。
锦铺仙禁侧，镜写曲江头。
红蕚开萧阁，黄丝拂御楼。
千门歌吹动，九陌绮罗游。
日近风先满，仁深泽共流。
应非顦顇质，辛苦在神州。','',''),('quantangshi-25745','题西隐寺','封敖','quantangshi','','卷26','三年未到九华山，终日披图一室间。
秋寺喜因晴后赏，灵峰看待足时还。
猨从有性留僧坐，云霭无心伴客闲。
胜事倘能销岁月，已𢬵名利不相关。','',''),('quantangshi-25746','奉和白敏中圣道和平致兹休运岁终功就合咏盛明呈上','馬植','quantangshi','','卷26','舜德尧仁化犬戎，许提河陇欵皇风。
指挥貙武皆神算，恢拓干坤是圣功。
四帅有征无汗马，七关虽戍已弢弓。
天留此事还英主，不在他年在大中。','',''),('quantangshi-25747','夏日途中','李廓','quantangshi','','卷26','树夹炎风路，行人正午稀。
初蝉数声起，戏蝶一团飞。
日色欺清镜，槐膏点白衣。
无成归故里，自觉少光辉。','',''),('quantangshi-25748','长安少年行 一','李廓','quantangshi','','卷26','金紫少年郎，绕街鞍马光。
身从左中尉，官属右春坊。
刬戴扬州帽，重薰异国香。
垂鞭踏青草，来去杏园芳。','',''),('quantangshi-25749','长安少年行 二','李廓','quantangshi','','卷26','追逐轻薄伴，闲游不着绯。
长拢出猎马，数换打球衣。
晓日寻花去，春风带酒归。
青楼无昼夜，歌舞歇时稀。','',''),('quantangshi-25750','长安少年行 三','李廓','quantangshi','','卷26','日高春睡足，帖马赏年华。
倒插银鱼袋，行随金犊车。
还携新市酒，远醉曲江花。
几度归侵黑，金吾送到家。','',''),('quantangshi-25751','长安少年行 四','李廓','quantangshi','','卷26','好胜耽长夜，天明烛满楼。
留人看独脚，赌马换偏头。
乐奏曾无歇，杯巡不暂休。
时时遥冷笑，怪客有春愁。','',''),('quantangshi-25752','长安少年行 五','李廓','quantangshi','','卷26','遨游携艳妓，装束似男儿。
杯酒逢花住，笙歌簇马吹。
莺声催曲忽，春色送归迟。
不以闻街鼓，华筵待月移。','',''),('quantangshi-25753','长安少年行 六','李廓','quantangshi','','卷26','赏春惟逐胜，大宅可曾归。
不乐还逃席，多狂惯衩衣。
歌人踏日起，语燕卷帘飞。
妇好唯相妬，倡楼不醉稀。','',''),('quantangshi-25754','长安少年行 七','李廓','quantangshi','','卷26','戟门连日闭，苦饮惜残春。
开锁通新客，教姬屈醉人。
倩歌牵白马，自舞踏红茵。
时辈皆相许，平生不负身。','',''),('quantangshi-25755','长安少年行 八','李廓','quantangshi','','卷26','新年高殿上，始见有光辉。
玉雁排方带，金鹅立仗衣。
酒深和椀赐，马疾打珂飞。
朝下人争看，香街意气归。','',''),('quantangshi-25756','长安少年行 九','李廓','quantangshi','','卷26','游市慵骑马，随姬入坐车。
楼边听歌吹，帘外见莺花。
乐眼从人闹，归心畏日斜。
苍头来去报，饮伴到倡家。','',''),('quantangshi-25757','长安少年行 十','李廓','quantangshi','','卷26','小妇教鹦鹉，头边唤醉醒。
犬娇眠玉簟，鹰掣撼金铃。
碧地攅花障，红泥待客亭。
虽然长按曲，不饮不曾听。','',''),('quantangshi-25758','鸡鸣曲','李廓','quantangshi','','卷26','星稀月没入五更，胶胶角角鸡初鸣。
征人牵马出门立，辞妾欲向安西行。
再鸣引颈檐头下，楼中角声催上马。
才分曙色第二鸣，旌斾红尘已出城。
妇人上城乱招手，夫壻不闻遥哭声。
长恨鸡鸣别时苦，不遣鸡栖近窗户。','',''),('quantangshi-25759','镜听词','李廓','quantangshi','','卷26','匣中取镜辞竈王，罗衣掩尽明月光。
昔时长着照容色，今夜潜将听消息。
门前地黑人来稀，无人错道朝夕归。
更深弱体冷如铁，绣带菱花怀里热。
铜片铜片如有灵，愿照得见行人千里形。','',''),('quantangshi-25760','猛士行','李廓','quantangshi','','卷26','战鼓惊沙恶天色，猛士虬髯眼前黑。
单于衣锦日行兵，阵头走马生擒得。
幽并少年不敢轻，虎狼窟里空手行。','',''),('quantangshi-25761','送振武将军','李廓','quantangshi','','卷26','叶叶归边骑，风头万里干。
金装腰带重，铁缝耳衣寒。
芦酒烧蓬暖，霜鸿拈箭看。
黄河古戍道，秋雪白漫漫。','',''),('quantangshi-25762','落第','李廓','quantangshi','','卷26','牓前潜制泪，众里自嫌身。
气味如中酒，情怀似别人。
暖风张乐席，晴日看花尘。
尽是添愁处，深居乞过春。','',''),('quantangshi-25763','赠商山东于岭僧','李廓','quantangshi','','卷26','商岭东西路欲分，两间茅屋一溪云。
师言耳重知师意，人是人非不欲闻。','',''),('quantangshi-25764','上令狐舍人','李廓','quantangshi','','卷26','名利生愁地，贫居岁月移。
买书添架上，断酒过花时。
宿客嫌吟苦，乖童恨睡迟。
近来唯俭静，持此答深知。','',''),('quantangshi-25765','南梁行','李紳','quantangshi','','卷26','江城郁郁春草长，悠悠汉水浮青光。
杂英飞尽空昼景，绿杨重阴官舍静。
此时醉客纵横书，公言可荐承明庐。
青天诏下宠光至，颁籍金闺征石渠。
秭归山路烟岚隔，山木幽深晚花拆。
涧底红光夺火燃，摇风扇毒愁行客。
杜鹃啼咽花亦殷，声悲绝艳连空山。
斜阳瞥映浅深树，云雨翻迷崖谷间。
山鸡锦质矜毛羽，透竹穿萝命俦侣。
乔木幽溪上下同，雄雌不惑飞栖处。
望秦峰回过商颜，浪叠云堆万簇山。
行尽杳冥青嶂外，九重钟漏紫霄间。
元和列侍明光殿，谏草初焚市朝变。
北阙趋承半隙尘，南梁笑客皆飞霰。
追思感叹却昏迷，霜鬓愁吟到晓鸡。
故箧岁深开断简，秋堂月曙掩遗题。
呜呜晓角霞辉粲，抚劒当应一长叹。
刍狗无由学圣贤，空持感激终昏旦。','',''),('quantangshi-25766','趋翰苑遭诬构四十六韵','李紳','quantangshi','','卷26','九五当干德，三千应瑞符。
纂尧昌圣历，宗禹盛丕图。
画象垂新令，消兵易旧谟。
选贤方去智，招谏忽升愚。
大乐调元气，神功运化罏。
脱鳞超沆瀣，翻翼集蓬壶。
捧日恩光别，抽毫顾问殊。
凤形怜彩笔，龙颔借骊珠。
掷地声名寡，摩天羽翮孤。
洁身酬雨露，利口扇谗谀。
碧海同宸眷，鸿毛比贱躯。
辨疑分黑白，举直抵朋徒。
庭兽方呈角，阶蓂始効莩。
日倾乌掩魄，星落斗摧枢。
坠劒悲乔岳，号弓泣鼎湖。
乱羣逢害马，择肉纵狂貙。
胆为隳肝竭，心因沥血枯。
满帆摧骇浪，征棹折危途。
燕客书方诈，尧门信未孚。
谤兴金就铄，毁极玉生愈。
砺吻矜先搏，张罗骋疾驱。
地嫌稀魍魉，海恨止番禺。
瘴岭冲蛇入，蒸池蹑虺趋。
望天收雪涕，看镜揽霜须。
草毒人惊剪，茅荒室未诛。
火风晴处扇，山鬼雨中呼。
穷老乡关远，羇愁骨肉无。
鹊灵窥牖户，龟瑞出泥途。
烟岛深千瘴，沧波淼四隅。
海标传信使，江棹认妻孥。
到接三冬暮，来经六月徂。
暗滩朝不怒，惊濑夜无虞。
俛首安羸业，齐眉慰病夫。
涸鱼思雨润，僵燕望雷苏。
诏下因颁朔，恩移讵省辜。
诳天犹指鹿，依社尚凭狐。
度岭瞻牛斗，浮江淬辘轳。
未平人睚眦，谁惧鬼揶揄。
盆浦潮通楚，匡山地接吴。
庾楼清桂满，远寺素莲敷。
仿髴皆停马，悲欢尽隙驹。
旧交封宿草，衰鬓重生刍。
万戟分梁苑，双旌寄鲁儒。
骎骎移岁月，冉冉近桑榆。
疲马愁千里，孤鸿念五湖。
终当赋归去，那更学杨朱。','',''),('quantangshi-25767','忆春日太液池亭候对','李紳','quantangshi','','卷26','宫莺报晓瑞烟开，三岛灵禽拂水回。
桥转彩虹当绮殿，舰浮花鷁近蓬莱。
草承香辇王孙长，桃艳仙颜阿母栽。
簪笔此时方侍从，却思金马笑邹枚。','',''),('quantangshi-25768','忆夜直金銮殿承旨','李紳','quantangshi','','卷26','月当银汉玉绳低，深听箫韶碧落齐。
门压紫垣高绮树，阁连青琐近丹梯。
墨宣外渥催飞诏，草布深恩促换题。
明日独归花路远，可怜人世隔云霓。','',''),('quantangshi-25769','忆春日曲江宴后许至芙蓉园','李紳','quantangshi','','卷26','春风上苑开桃李，诏许看花入御园。
香径草中回玉勒，凤皇池畔泛金樽。
绿丝垂柳遮风暗，红药低丛拂砌繁。
归绕曲江烟景晚，未央明月锁千门。','',''),('quantangshi-25770','新昌宅书堂前有药树一株今已盈拱前长庆中于翰林院内西轩药树下移得才长一寸仆夫封一泥丸以归植今则长成名之天上树','李紳','quantangshi','','卷26','白榆星底开红甲，珠树宫中长紫霄。
丹彩结心才辨质，碧枝抽叶乍成条。
羽衣道士偷玄圃，金简真人护玉苗。
长带九天余雨露，近来葱翠欲成乔。','',''),('quantangshi-25771','过荆门','李紳','quantangshi','','卷26','荆江水阔烟波转，荆门路遶山葱蒨。
帆势侵云灭又明，山程背日昏还见。
青青麦陇啼飞鸦，寂寞野径棠梨花。
行行驱马万里远，渐入烟岚危栈赊。
林中有鸟飞出谷，月上千岩一声哭。
肠断思归不可闻，人言恨魄来巴蜀。
我听此鸟祝我魂，魂死莫学声衔冤。
纵为羽族莫栖息，直上青云呼帝阍。
此时山月如衔镜，岩树参差互辉映。
皎洁深看入涧泉，分明细见樵人径。
阴森鬼庙当邮亭，鸡豚日宰闻膻腥。
愚夫祸福自迷惑，魍魉凭何通百灵。
月低山晓问行客，已酹椒浆拜荒陌。
惆怅忠贞徒自持，谁祭山头望夫石。','',''),('quantangshi-25772','涉沅潇','李紳','quantangshi','','卷26','屈原死处潇湘阴，沧浪淼淼云沈沈。
蛟龙长怒虎长啸，山木翛翛波浪深。
烟横日落惊鸿起，山映余霞杳千里。
鸿叫离离入暮天，霞消漠漠深云水。
水灵江暗扬波涛，鼋鼍动荡风骚骚。
行人愁望待明月，星汉沈浮𩳤鬼号。
屈原尔为怀王没，水府通天化灵物。
何不驱雷击电除奸邪，可怜空作沈泉骨。
举杯沥酒招尔魂，月影滉漾开干坤。
波白水黑山隐见，汨罗之上遥昏昏。
风帆候晓看五两，戍鼓冬冬远山响。
潮满江津猨鸟啼，荆夫楚语飞蛮桨。
潇湘岛浦无人居，风惊水暗惟鲛鱼。
行来击棹独长叹，问尔精魄何所如。','',''),('quantangshi-25773','逾岭峤止荒陬抵高要','李紳','quantangshi','','卷26','天将南北分寒燠，北被羔裘南卉服。
寒气凝为戎虏骄，炎蒸结作虫虺毒。
周王止化惟荆蛮，汉武凿远通孱颜。
南标铜柱限荒徼，五岭从兹穷险艰。
衡山截断炎方北，回雁峰南瘴烟黑。
万壑奔伤溢作泷，湍飞浪激如绳直。
千崖傍耸猨啸悲，丹蛇玄虺潜蜲蛇。
泷夫拟檝劈高浪，瞥忽浮沈如电随。
岭头刺竹蒙笼密，火拆红蕉焰烧日。
岭上泉分南北流，行人照水愁肠骨。
阴森石路盘萦纡，雨寒日暖常斯须。
瘴云暂卷火山外，苍茫海气穷番禺。
鹧鸪猿鸟声相续，椎髻晓呼同戚促。
百处溪滩异雨晴，四时雷电迷昏旭。
鱼肠雁足望缄封，地远三江岭万重。
鱼跃岂通清远峡，雁飞难渡漳江东。
云蒸地热无霜霰，桃李冬华匪时变。
天际长垂饮涧虹，檐前不去衔泥燕。
幸逢雷雨荡妖昏，提挈悲欢出海门。
西日眼明看少长，北风身醒辨寒温。
贾生谪去因前席，痛哭书成竟何益。
物忌忠良表是非，朝驱绛灌为雠敌。
明皇圣德异文皇，不使无辜困鬼方。
汉日傅臣终委弃，如今衰叟重辉光。
高明白日恩深海，齿发虽残壮心在。
空愧驽骀异一毛，无令朽骨慙千载。','',''),('quantangshi-25774','移九江','李紳','quantangshi','','卷26','秋波入白水，帆去侵空小。
五两剧奔星，樯乌疾飞鸟。
盆城依落日，盆浦看云眇。
云眇更苍苍，匡山低夕阳。
楚客喜风水，秦人悲异乡。
异乡秋思苦，江臯月华吐。
漾漾隐波亭，悠悠通月浦。
津桥归候吏，竹巷开门户。
容膝有匡牀，及肩才数堵。
隙光非白驹，悬磬我无虞。
体瘦寡行立，家肥安啜哺。
天书怜谴谪，重作朱轓客。
四座眼全青，一麾头半白。
今来思往事，往事益凄然。
风月同今昔，悲欢异目前。
四时嗟阅水，一纪换流年。
独有西庭鹤，孤鸣白露天。','',''),('quantangshi-25775','泛五湖','李紳','quantangshi','','卷26','范子蜕冠履，扁舟逸霄汉。
嗟予抱险艰，怵惕惊弥漫。
穷通泛滥劳，趣适殊昏旦。
浴日荡层空，浮天淼无畔。
依滩落叶聚，立浦惊鸿散。
浪叠雪峰连，山孤翠崖断。
风帆同巨壑，云矗成高岸。
宇宙可东西，星辰沈粲烂。
霞生[澒]洞远，月吐青荧乱。
岂复问津迷，休为吕梁叹。
漂沈自讵保，覆溺心长判。
吴越郡异乡，婴童及为翫。
依稀占井邑，嘹唳同鹅鹳。
举棹未宵分，维舟方日旰。
征斯济川力，若鼓凌风翰。
易狎当悔游，临深罔知难。','',''),('quantangshi-25776','过钟陵','李紳','quantangshi','','卷26','龙沙江尾抱钟陵，水郭村桥晚景澄。
江对楚山千里月，郭连渔浦万家灯。
省抛双斾辞荣宠，遽落丹霄起爱憎。
惆怅旧游同草露，却思恩顾一霑膺。','',''),('quantangshi-25777','溯西江','李紳','quantangshi','','卷26','江风不定半晴阴，愁对花时尽日吟。
孤棹自迟从蹭蹬，乱帆争疾竞浮沈。
一身累困怀千载，百口无虞贵万金。
空阔远看波浪息，楚山安稳过云岑。','',''),('quantangshi-25778','早发','李紳','quantangshi','','卷26','沙洲月落宿禽惊，潮起风微晓雾生。
黄鹤浪明知上信，黑龙山暗避前程。
火旗似辨吴门戍，水驿遥迷楚塞城。
萧索更看江叶下，两乡俱是宦游情。','',''),('quantangshi-25779','守滁阳深秋忆登郡城望琅琊','李紳','quantangshi','','卷26','山城小阁临青嶂，红树莲宫接薜萝。
斜日半岩开古殿，野烟浮水掩轻波。
菊迎秋节西风急，雁引砧声北思多。
深夜独吟还不寐，坐看凝露满庭莎。','',''),('quantangshi-25780','滁阳春日怀果园闲宴','李紳','quantangshi','','卷26','西园到日栽桃李，红白低枝拂酒杯。
繁艳只愁风处落，醉筵多就月中开。
劝人莫折怜芳早，把烛频看畏晓催。
闻道数年深草露，几株犹得近池台。','',''),('quantangshi-25781','悲善才','李紳','quantangshi','','卷26','穆王夜幸蓬池曲，金銮殿开高秉烛。
东头弟子曹善才，琵琶请进新翻曲。
翠蛾列坐层城女，笙笛参差齐笑语。
天颜静听朱丝弹，众乐寂然无敢举。
衔花金凤当承拨，转腕拢弦促挥抹。
花翻凤啸天上来，裴回满殿飞春雪。
抽弦度曲新声发，金铃玉佩相瑳切。
流莺子母飞上林，仙鹤雌雄唳明月。
此时奉诏侍金銮，别殿承恩许召弹。
三月曲江春草绿，九霄天乐下云端。
紫髯供奉前屈膝，尽弹妙曲当春日。
寒泉注射陇水开，胡雁翻飞向天没。
日曛尘暗车马散，为惜新声有余叹。
明年冠劒闭桥山，万里孤臣投海畔。
笼禽铩翮尚还飞，白首生从五岭归。
闻道善才成朽骨，空余弟子奉音徽。
南谯寂寞三春晚，有客弹弦独凄怨。
静听深奏楚月光，忆昔初闻曲江宴。
心悲不觉泪阑干，更为调弦反覆弹。
秋吹动摇神女佩，月珠敲击水晶盘。
自怜淮海同泥滓，恨魄凝心未能死。
惆怅追怀万事空，雍门感慨徒为尔。','',''),('quantangshi-25782','闻里谣效古歌','李紳','quantangshi','','卷26','乡里儿，桑麻郁郁禾黍肥，冬有褴襦夏有絺。
兄锄弟耨妻在机，夜犬不吠开蓬扉。
乡里儿，醉还饱，浊醪初熟劝翁媪。
鸣鸠拂羽知年好，齐和杨花踏春草。
劝年少，乐耕桑。
使君为我剪荆棘，使君为我驱豺狼。
林中无虎山有鹿，水底无蛟鱼有鲂。
父渔子猎日归暮，月明处处舂黄粱。
乡里儿，东家父老为尔言，鼓腹那知生育恩。
莫令太守驰朱轓，悬鼓一鸣卢鹊喧。
恶声主吏噪尔门，唧唧力力烹鸡豚。
乡里儿，莫悲咤。
上有明王颁诏下，重选贤良恤孤寡。
春日迟迟驱五马，留犊投钱以为谢。
乡里儿，终尔词。
我无工巧唯无私，举手一挥临路岐。','',''),('quantangshi-25783','转寿春守太和庚戌岁二月祗命寿阳时替裴五墉终殁因视壁题自墉而上或除名在边坐殿殁凡七子无一存焉寿人多寇盗好诉讦时谓讦时谓之凶郡犷俗特着蒙此处之顾余衰年甘蹑前患俾三月而寇静朞岁而人和虎不暴物奸吏屏窜三载复遭邪佞所恶授宾客分司东都或举其目或寄于风亦麤继诗人之末云','李紳','quantangshi','','卷26','未登崖谷寻丹竈，且历轩窗看壁题。
那遇八公生羽翼，空悲七子委尘泥。
旧坛无复翔云鹤，废垒曾经振鼓鼙。
点检遗编尽朝菌，应难求望一刀圭。','',''),('quantangshi-25784','忆寿春废虎坑余以春二月至郡主吏举所职称霍山多虎每岁采茶为患择肉于人至春常修陷穽数十所勒猎者采其皮睛余悉除罢之是岁虎不复为害至余去郡三载','李紳','quantangshi','','卷26','匪将履尾求兢惕，那效探雏所患争。
当路绝羣尝诫暴，为猫驱狝亦先迎。
每推至化宣余力，岂用潜机害尔生。
休逐豺狼止贪戾，好为仁兽答皇明。','',''),('quantangshi-25785','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 肥河维舟阻冻袛待勅命 一','李紳','quantangshi','','卷26','罢分符竹作闲官，舟冻肥河拟棹难。
食蘖苦心甘处困，饮冰持操敢辞寒。
夜灯空应渔家火，朝食还依雁宿滩。
西奏血诚遥稽首，乞容归病老江干。','',''),('quantangshi-25786','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 肥河维舟阻冻袛待勅命 二','李紳','quantangshi','','卷26','淮阳效理空多病，疎受辞荣岂恋班。
陈力不任趋北阙，有家无处寄东山。
疲骖岂念前程税，倦鸟安能待暮还。
珍重八公山下叟，不劳重泪更追攀。','',''),('quantangshi-25787','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物','李紳','quantangshi','','卷26','垂阴敢慕甘棠叶，附干将呈瑞木符。
十步兰茶同秀彩，万年枝叶表皇图。
芟夷不及知无患，雨露曾霑自不枯。
好住孤根托桃李，莫令从此混樵苏。','',''),('quantangshi-25788','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物','李紳','quantangshi','','卷26','南山白额同驯扰，亦变仁心去杀机。
不竞牛甘令买患，免遭狐假妄凭威。
渡河岂适他邦害，据谷终无暴物非。
尔效驺虞护生草，岂徒柔伏在淮淝。','',''),('quantangshi-25789','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 发寿阳分司勅到又遇新正感怀书事','李紳','quantangshi','','卷26','休为建隼临淝守，转作垂丝入洛人。
罢阅旧林三载籍，又开新历四年春。
云遮北雁愁行客，柳起东风慰病身。
渐喜雪霜消解尽，得随风水到天津。','',''),('quantangshi-25790','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 初出淝口入淮','李紳','quantangshi','','卷26','东风百里雪初晴，淝口冰开好濯缨。
野老拥途知意重，病夫抛郡喜身轻。
人心莫厌如弦直，淮水长怜似镜清。
回首夕岚山翠远，楚郊烟树隐襄城。','',''),('quantangshi-25791','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 入淮至盱眙','李紳','quantangshi','','卷26','山凝翠黛孤峰迥，淮起银花五两高。
天外绮霞迷海鹤，日边红树艳仙桃。
岸惊目眩同奔马，浦溢心疑覩拚鳌。
寄谢云帆疾飞鸟，莫夸回雁卷轻毛。','',''),('quantangshi-25792','寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 忆东湖','李紳','quantangshi','','卷26','菱歌罢唱鷁舟回，雪鹭银鸥左右来。
霞散浦边云锦截，月升湖面镜波开。
鱼惊翠羽金鳞跃，莲脱红衣紫菂摧。
淮口值春偏怅望，数株临水是寒梅。','',''),('quantangshi-25793','七年初到洛阳寓居宣教里时已春暮而四老俱在洛中分司','李紳','quantangshi','','卷26','青莎满地无三径，白发缘头忝四人。
官职谬齐商岭客，姓名那重汉廷臣。
圣朝寡罪容衰齿，愚叟多慙未退身。
惟有门人怜钝拙，劝教沈醉洛阳春。','',''),('quantangshi-25794','初秋忽奉诏除浙东观察使检校右貂','李紳','quantangshi','','卷26','龙楼寄引簪裾客，凤阙陪趋朔望朝。
疎受杜门期脱屣，买臣归邸忽乘轺。
印封龟纽知颁爵，冠饰蝉緌更珥貂。
飞诏宠荣欢里舍，岂徒斑白与垂髫。','',''),('quantangshi-25795','忆至巩县河宿待家累追怀','李紳','quantangshi','','卷26','巩树翻红秋日斜，水分伊洛照余霞。
弓开后骑低初月，鹗驻前旌拂暮鸦。
闺信坐迟青玉案，弄儿闲望白羊车。
今来忆事凉风晚，烟浦空悲黄菊花。','',''),('quantangshi-25796','宿扬州','李紳','quantangshi','','卷26','江横渡阔烟波晚，潮过金陵落叶秋。
嘹唳塞鸿经楚泽，浅深红树见扬州。
夜桥灯火连星汉，水郭帆樯近斗牛。
今日市朝风俗变，不须开口问迷楼。','',''),('quantangshi-25797','忆被牛相留醉州中时无他宾牛公夜出真珠辈数人','李紳','quantangshi','','卷26','严城画角三声闭，清宴金樽一夕同。
银烛坐隅听子夜，宝筝筵上起春风。
酒征旧对慙衰质，曲换新词感上宫。
淮海一从云雨散，杳然俱是梦魂中。','',''),('quantangshi-25798','早渡扬子江','李紳','quantangshi','','卷26','日冲海浪翻银屋，江转秋波走雪山。
青嶂迥开蹲虎戍，碧流潜伏跃龙关。
地分吴楚星辰内，水迫沧溟宇宙间。
焚却戍船无战伐，使知风教被乌蛮。','',''),('quantangshi-25799','忆过润州','李紳','quantangshi','','卷26','昔年从宦干戈地，黄绶青春一鲁儒。
弓犯控弦招武旅，劒当抽匣问狂夫。
帛书投笔封鱼腹，玄发冲冠捋虎须。
谈笑谢金何所愧，不为偷买用兵符。','',''),('quantangshi-25800','忆登栖霞寺峰','李紳','quantangshi','','卷26','香印烟火息，法堂钟磬余。
纱灯耿晨焰，释子安禅居。
林叶脱红影，竹烟含绮疎。
星珠错落耀，月宇参差虚。
顾眺匪恣适，旷襟怀卷舒。
江海淼清荡，丘陵何所如。
滔滔可问津，耕者非长沮。
茅岭感仙客，萧园成古墟。
移步下碧峰，涉涧更踌躇。
乌噪啄秋果，翠惊衔素鱼。
回塘彩鷁来，落景标林箊。
漾漾棹翻月，萧萧风袭裾。
劳歌起旧思，戚叹竟难摅。
却数共游者，凋落非里闾。','',''),('quantangshi-25801','忆万岁楼望金山','李紳','quantangshi','','卷26','楼高雉堞千师垒，峰拔惊波万壑攒。
山绝地维消虎踞，水浮天险尚龙盘。
蜃嘘云拱飞江岛，鳌喷仙岩隔海澜。
长对碧波临古渡，几经风月与悲欢。','',''),('quantangshi-25802','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后','李紳','quantangshi','','卷26','上家山，家山依旧好。
昔去松桂长，今来容须老。
上家山，临古道。
高低入云树，芜没连天草。
草色绿萋萋，寒蛩徧草啼。
噪鸦啼树远，行雁帖云齐。
岩光翻落日，僧火开经室。
竹洞磬声长，松楼钟韵疾。
苔阶泉溜鈌，石甃青莎密。
旧径行处迷，前交坐中失。
叹息整华冠，持杯强自欢。
笑歌怜稚孺，弦竹纵吹弹。
山明溪月上，酒满心聊放。
丱发此淹留，垂丝匪闲旷。
青山不可上，昔事还惆怅。
况复白头人，追怀空望望。','',''),('quantangshi-25803','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后 忆东郭居','李紳','quantangshi','','卷26','昔余过稚齿，从师昧知奥。
徒怀利物心，不获藏身宝。
曳娄一缝掖，出处劳昏早。
醒醉迷啜哺，衣裳辨颠倒。
忠诚贯白日，直己凭苍昊。
卷舌堕谗谀，惊波息行潦。
衰禽识旧木，疲马知归道。
杨柳长庭柯，兰荃覆阶草。
旌旄光里舍，骑服欢妻嫂。
绿鬓绝新知，苍须稀旧老。
冠緌身忝贵，斋沐心常祷。
笙磬谅谐和，庭除还洒扫。
栖迟还竹巷，物役浸江岛。
倏忽变星霜，悲伤满衷抱。','',''),('quantangshi-25804','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后 忆题惠山寺书堂','李紳','quantangshi','','卷26','故山一别光阴改，秋露清风岁月多。
松下壮心年少去，池边衰影老人过。
白云生灭依岩岫，青桂荣枯托薜萝。
惟有此身长是客，又驱旌斾寄烟波。','',''),('quantangshi-25805','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后 忆西湖双鸂鶒','李紳','quantangshi','','卷26','双鸂鶒，锦毛斓斑长比翼，戏绕莲藂回锦臆。
照灼花丛两相得，渔歌惊起飞南北。
缭绕追随不迷惑，云间上下同栖息。
不作惊禽远相忆，东家少妇机中语。
剪断回文泣机杼，徒嗟孔雀衔毛羽。
一去东南别离苦，五里裴回竟何补。','',''),('quantangshi-25806','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后 早梅桥','李紳','quantangshi','','卷26','早梅花，满枝发。
东风报春春未彻，紫萼迎风玉珠裂。
杨柳未黄莺结舌，委素飘香照新月。
桥边一树伤离别，游荡行人莫攀折。
不竞江南艳阳节，任落东风伴春雪。','',''),('quantangshi-25807','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后 翡翠坞','李紳','quantangshi','','卷26','翡翠飞飞绕莲坞，一啄嘉鱼一鸣舞。
莲茎触散莲叶欹，露滴珠光似还浦。
虞人掠水轻浮弋，翡翠惊飞飞不息。
直上层空翠影高，还向云间双比翼。
弹射莫及弋不得，日暮虞人空叹息。','',''),('quantangshi-25808','过梅里七首 家于无锡四十载今敝庐数堵犹存今列题于后','李紳','quantangshi','','卷26','羽毛似雪无瑕点，顾影秋池舞白云。
闲整素仪三岛近，回飘清唳九霄闻。
好风顺举应摩日，逸翮将成莫恋羣。
凌励坐看空碧外，更怜凫鹭老江濆。','',''),('quantangshi-25809','过吴门二十四韵','李紳','quantangshi','','卷26','烟水吴都郭，阊门架碧流。
绿杨深浅巷，青翰往来舟。
朱户千家室，丹楹百处楼。
水光摇极浦，草色辨长洲。
忆作麻衣翠，曾为旅棹游。
放歌随楚老，清宴奉诸侯。
花寺听莺入，春湖看雁留。
里吟传绮唱，乡语认歈讴。
桥转攒虹饮，波通鬬鷁浮。
竹扉梅圃静，水巷橘园幽。
缝堵荒麋苑，穿岩破虎丘。
旧风犹越鼓，余俗尚吴钩。
故馆曾闲访，遗基亦徧搜。
吹台山木尽，香径佛宫秋。
帐殿菰蒲掩，云房露雾收。
苎萝妖覆灭，荆棘鬼包羞。
风月俄黄绶，经过半白头。
重来冠盖客，非复别离愁。
候火分通陌，前旌驻外邮。
水风摇彩斾，堤柳引鸣驺。
问吏儿孙隔，呼名礼敬修。
顾瞻殊宿昔，语默过悲忧。
义感心空在，容衰日易偷。
还持沧海诏，从此布皇猷。','',''),('quantangshi-25810','杭州天竺灵隐二寺顷岁亦布衣一游及赴镇会稽不敢以登临自适竟不复到寺寺多猨猱谓之孙团弥长其类因追思为诗二首 一','李紳','quantangshi','','卷26','翠岩幽谷高低寺，十里松风碧嶂连。
开尽春花芳草涧，徧通秋水月明泉。
石文照日分霞壁，竹影侵云拂暮烟。
时有猨猱扰钟磬，老僧无复得安禅。','',''),('quantangshi-25811','杭州天竺灵隐二寺顷岁亦布衣一游及赴镇会稽不敢以登临自适竟不复到寺寺多猨猱谓之孙团弥长其类因追思为诗二首 二','李紳','quantangshi','','卷26','人烟不隔江城近，水石虽清海气深。
波动只观罗刹相，静居难识梵王心。
鱼扃昼锁龙宫宝，雁塔高摩欲界金。
近日尤闻重雕饰，世人遥礼二檀林。','',''),('quantangshi-25812','渡西陵十六韵','李紳','quantangshi','','卷26','雨送奔涛远，风收骇浪平。
截流张斾影，分岸走鼙声。
兽逐衔波涌，龟艨喷棹轻。
海门凝雾暗，江渚湿云横。
雁翼看舟子，鱼鳞辨水营。
骑交遮戍合，戈簇拥沙明。
谬履千夫长，将询百吏情。
下车占黍稷，冬雨害粢盛。
望祷依前圣，垂休翼厚生。
半江犹惨澹，全野已澄清。
爱景三辰朗，祥农万庾盈。
浦程通曲屿，海色媚重城。
弓日鞬櫜动，旗风虎豹争。
及郊挥白羽，入里卷红旌。
恺悌思陈力，端庄冀表诚。
临人与安俗，非止奉师贞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-25813','新楼诗二十首 新楼','李紳','quantangshi','','卷26','戎容罢引旌旗卷，朱户褰开雉堞高。
山耸翠微连郡阁，地临沧海接灵鳌。
坐疑许宅驱鸡犬，笑类樊妻化羽毛。
惆怅桂枝零落促，莫思方朔种仙桃。','',''),('quantangshi-25814','新楼诗二十首 海榴亭','李紳','quantangshi','','卷26','海榴亭早开繁蘂，光照晴霞破碧烟。
高近紫霄疑菡萏，迥依江月半婵娟。
怀芳不作翻风艳，别萼犹含泣露妍。
摇落旧丛云水隔，不堪行坐数流年。','',''),('quantangshi-25815','新楼诗二十首 望海亭','李紳','quantangshi','','卷26','乌盈兔缺天涯迥，鹤背松梢拂槛低。
湖镜坐隅看匣满，海涛生处辨云齐。
夕岚明灭江帆小，烟树苍茫客思迷。
萧索感心俱是梦，九天应共草萋萋。','',''),('quantangshi-25816','新楼诗二十首','李紳','quantangshi','','卷26','杜鹃如火千房拆，丹槛低看晚景中。
繁艳向人啼宿露，落英飘砌怨春风。
早梅昔待佳人折，好月谁将老子同。
惟有此花随越鸟，一声啼处满山红。','',''),('quantangshi-25817','新楼诗二十首','李紳','quantangshi','','卷26','为怜湖水通宵望，不学樊杨却月楼。
惟待素规澄满镜，莫看纤魄挂如钩。
卷帘方影侵红烛，绕竹斜晖透碧流。
萧瑟晓风闻木落，此时何异洞庭秋。','',''),('quantangshi-25818','新楼诗二十首','李紳','quantangshi','','卷26','绿波春水湖光满，丹槛连楹碧嶂遥。
兰鷁对飞渔棹急，彩虹翻影海旗摇。
鬬疑斑虎归三岛，散作游龙上九霄。
鼍鼓若雷争胜负，柳堤花岸万人招。','',''),('quantangshi-25819','新楼诗二十首','李紳','quantangshi','','卷26','银地溪边遇衲师，笑将花宇指潜知。
定观玄度生前事，不道灵山别后期。
真相有无因色界，化城兴灭在莲基。
好令沧海龙宫子，长护金人旧浴池。','',''),('quantangshi-25820','新楼诗二十首 禹庙','李紳','quantangshi','','卷26','削平水土穷沧海，畚锸东南尽会稽。
山拥翠屏朝玉帛，穴通金阙架云霓。
秘文镂石藏青壁，宝检封云化紫泥。
清庙万年长血食，始知明德与天齐。','',''),('quantangshi-25821','新楼诗二十首','李紳','quantangshi','','卷26','寺深松桂无尘事，地接荒郊带夕阳。
啼鸟歇时山寂寂，野花残处月苍苍。
绛纱凝焰开金像，清梵销声闭竹房。
丘壠渐平连茂草，九原何处不心伤。','',''),('quantangshi-25822','新楼诗二十首','李紳','quantangshi','','卷26','一峰凝黛当明镜，十仞乔松倚翠屏。
秋月满时侵兔魄，素波摇处动龟形。
旧深崖谷藏仙岛，新结楼台起佛扃。
不学大蛟凭水怪，等闲雪雨害生灵。','',''),('quantangshi-25823','新楼诗二十首 重台莲','李紳','quantangshi','','卷26','绿荷舒卷凉风晓，红萼开萦紫菂重。
游女汉臯争笑脸，二妃湘浦竝愁容。
自含秋露贞姿结，不竞春妖冶态穠。
终恐玉京仙子识，却将归种碧池峰。','',''),('quantangshi-25824','新楼诗二十首 橘园','李紳','quantangshi','','卷26','江城雾歛轻霜早，园橘千株欲变金。
朱实摘时天路近，素英飘处海云深。
惧同枳棘愁迁徙，每抱馨香委照临。
怜尔结根能自保，不随寒暑换贞心。','',''),('quantangshi-25825','新楼诗二十首','李紳','quantangshi','','卷26','最深城郭在人烟，疑借壶中到梵天。
岩树桂花开月殿，石楼风铎绕金仙。
地无尘染多灵草，室鉴真空有定泉。
应是法宫传觉路，使无烦恼见青莲。','',''),('quantangshi-25826','新楼诗二十首 北楼樱桃花','李紳','quantangshi','','卷26','开花占得春光早，雪缀云装万萼轻。
凝艳拆时初照日，落英频处乍闻莺。
舞空柔弱看无力，带月葱茏似有情。
多事东风入闺闼，尽飘芳思委江城。','',''),('quantangshi-25827','新楼诗二十首 城上蔷薇','李紳','quantangshi','','卷26','蔷薇繁艳满城阴，烂熳开红次第深。
新蘂度香翻宿蝶，密房飘影戏晨禽。
窦闺织妇慙诗句，南国佳人怨锦衾。
风月寂寥思往事，暮春空赋白头吟。','',''),('quantangshi-25828','新楼诗二十首 南庭竹','李紳','quantangshi','','卷26','东南旧美凌霜操，五月凝阴入坐寒。
烟惹翠梢含玉露，粉开春箨耸琅玕。
莫令戏马童儿见，试引为龙道士看。
知尔结根香实在，凤皇终拟下云端。','',''),('quantangshi-25829','新楼诗二十首','李紳','quantangshi','','卷26','石桥峰上栖玄鹤，碧阙岩边荫羽人。
冰叶万条垂碧实，玉珠千日保青春。
月中泣露应同浥，涧底侵云尚有尘。
徒使茯苓成琥珀，不为松老化龙鳞。','',''),('quantangshi-25830','新楼诗二十首 海棠','李紳','quantangshi','','卷26','海边佳树生奇彩，知是仙山取得栽。
琼蘂籍中闻阆苑，紫芝图上见蓬莱。
浅深芳萼通宵换，委积红英报晓开。
寄语春园百花道，莫争颜色泛金杯。','',''),('quantangshi-25831','新楼诗二十首 水寺','李紳','quantangshi','','卷26','烟波野寺经过处，水国苍茫梦想中。
云散浦间江月迥，日曛洲渚海潮通。
坐看鱼鸟沈浮远，静见楼台上下同。
闻道化城方便喻，只应从此到龙宫。','',''),('quantangshi-25832','新楼诗二十首 灵汜桥','李紳','quantangshi','','卷26','灵汜桥边多感伤，分明湖派绕回塘。
岸花前后闻幽鸟，湖月高低怨绿杨。
能促岁阴惟白发，巧乘风马是春光。
何须化鹤归华表，却数凋零念越乡。','',''),('quantangshi-25833','若耶溪','李紳','quantangshi','','卷26','岚光花影绕山阴，山转花稀到碧浔。
倾国美人妖艳远，凿山良冶铸炉深。
凌波莫惜临妆面，莹锷当期出匣心。
应是蛟龙长不去，若耶秋水尚沈沈。','',''),('quantangshi-25834','登禹庙回降雪五言二十韵','李紳','quantangshi','','卷26','金奏云坛毕，同云拂雪来。
玉田千亩合，琼室万家开。
湖暗冰封镜，山明树变梅。
裂缯分井陌，连璧混楼台。
麻引诗人兴，盐牵谢女才。
细疑歌响尽，旋作舞腰回。
着水鹅毛失，铺松鹤羽摧。
半崖云掩映，当砌月裴回。
遇物纤能状，随方巧若裁。
玉花全缀萼，珠蚌尽呈胎。
志士书频照，鲛人杼正催。
妬妆凌粉匣，欺酒上琼杯。
海使迷奔辙，江涛认暗雷。
疾飘风作驭，轻集霰为媒。
劒客休矜利，农师正念摧。
瑞彰知有感，灵贶表无灾。
尧历占新庆，虞阶想旧陪。
粉凝鸾阁下，银结凤池隈。
鸡树花惊笑，龙池絮欲猜。
劳歌会稽守，遥祝永康哉。','',''),('quantangshi-25835','题法华寺五言二十韵','李紳','quantangshi','','卷26','花界无生地，慈宫有相天。
化娥腾宝像，留影閟金仙。
殿涌全身塔，池开半月泉。
十峰排碧落，双涧合清涟。
药草经行徧，香灯次第燃。
戒珠高腊护，心印祖僧传。
瓶识先罗汉，衣存旧福田。
幻身观火宅，昏眼照青莲。
住觉超真境，依游渡法船。
化城珠百亿，灵迹冠三千。
萧壁将沈影，梁薪尚缀烟。
色尘知有数，劫烬岂无年。
龙喷疑通海，鲸吞想漏川。
磬疎闻启梵，钟息见安禅。
指喻三车觉，开迷五阴缠。
教通方便入，心达是非诠。
见叶千花藏，檀林万宝篇。
坐严狮子迅，幢饰网珠悬。
极乐知无碍，分明应有缘。
还将意功德，留偈法王前。','',''),('quantangshi-25836','宿越州天王寺','李紳','quantangshi','','卷26','海隅布政慙期月，江上霑巾愧万人。
休按簿书惩黠吏，未齐风俗昧良臣。
壶冰自洁中无玷，镜水非求下见鳞。
清夜佛宫观色相，却归前老更前身。','',''),('quantangshi-25837','却渡西陵别越中父老','李紳','quantangshi','','卷26','海潮晚上江风急，津吏篙师语默齐。
倾手奉觞看故老，拥流争拜见孩提。
慙非杜母临襄岘，自鄙朱翁别会稽。
渐举云帆烟水阔，杳然凫雁各东西。','',''),('quantangshi-25838','却到浙西','李紳','quantangshi','','卷26','临平水竭蒹葭死，里社萧条旅馆秋。
尝叹晋郊无乞籴，岂忘吴俗共分忧。
野悲扬目称嗟食，林极翳桑顾所求。
苛政尚存犹惕息，老人偷拜拥前舟。','',''),('quantangshi-25839','苏州不住遥望武丘报恩两寺','李紳','quantangshi','','卷26','秋山古寺东西远，竹院松门怅望同。
幽鸟静时侵径月，野烟消处满林风。
塔分朱雁余霞外，刹对金螭落照中。
官备散寮身却累，往来慙谢二莲宫。','',''),('quantangshi-25840','回望馆娃故宫','李紳','quantangshi','','卷26','江云断续草绵连，云隔秋波树覆烟。
飘雪荻花铺涨渚，变霜枫叶卷平田。
雀愁化水喧斜日，鸿怨惊风叫暮天。
因问馆娃何所恨，破吴红脸尚开莲。','',''),('quantangshi-25841','姑苏台杂句','李紳','quantangshi','','卷26','越王巧破夫差国，来献黄金重雕刻。
西施醉舞花艳倾，妬月娇娥恣妖惑。
姑苏百尺晓铺开，楼楣尽化黄金台。
歌清管咽欢未极，越师戈甲浮江来。
伍胥抉目看吴灭，范蠡全身霸西越。
寂莫千年尽古墟，萧条两地皆明月。
灵岩香径掩禅扉，秋草荒凉徧落晖。
江浦回看鸥鸟没，碧峰斜见鹭鸶飞。
如今白发星星满，却作闲官不闲散。
野寺经过惧悔尤，公程迫蹙悲秋馆。
吴乡越国旧淹留，草树烟霞昔徧游。
云木梦回多感欢，不惟惆怅至长洲。','',''),('quantangshi-25842','开元寺','李紳','quantangshi','','卷26','十层花宇真毫相，数仞峰峦閟月扉。
攒立宝山中色界，散周香海小轮围。
坐隅咫尺窥岩壑，窗外高低辨翠微。
难保尔形终不转，莫令偷拂六铢衣。','',''),('quantangshi-25843','臯桥','李紳','quantangshi','','卷26','伯鸾憔悴甘飘寓，非向嚣尘隐姓名。
鸿鹄羽毛终有志，素丝琴瑟自谐声。
故桥秋月无家照，古井寒泉见底清。
犹有余风未磨灭，至今乡里重和鸣。','',''),('quantangshi-25844','真娘墓','李紳','quantangshi','','卷26','一株繁艳春城尽，双树慈门忍草生。
愁态自随风烛灭，爱心难逐雨花轻。
黛消波月空蟾影，歌息梁尘有梵声。
还似钱塘苏小小，祗应回首是卿卿。','',''),('quantangshi-25845','却望无锡芙蓉湖 一','李紳','quantangshi','','卷26','水宽山远烟岚迥，柳岸萦回在碧流。
清昼不风凫雁少，却疑初梦镜湖秋。','',''),('quantangshi-25846','却望无锡芙蓉湖 二','李紳','quantangshi','','卷26','丹橘村边独火微，碧流明处雁初飞。
萧条落叶垂杨岸，隔水寥寥闻捣衣。','',''),('quantangshi-25847','却望无锡芙蓉湖 三','李紳','quantangshi','','卷26','逐波云影参差远，背日岚光隐见深。
犹似望中连海树，月生湖上是山阴。','',''),('quantangshi-25848','却望无锡芙蓉湖 四','李紳','quantangshi','','卷26','旧山认得烟岚近，湖水平铺碧岫间。
喜见云泉还怅望，自慙山叟不归山。','',''),('quantangshi-25849','却望无锡芙蓉湖 五','李紳','quantangshi','','卷26','翠崖幽谷分明处，倦鸟归云在眼前。
惆怅白头为四老，远随尘土去伊川。','',''),('quantangshi-25850','重到惠山','李紳','quantangshi','','卷26','碧峰依旧松筠老，重得经过已白头。
俱是海天黄叶信，两逢霜节菊花秋。
望中白鹤怜归翼，行处青苔恨昔游。
还向窗间名姓下，数行添记别离愁。','',''),('quantangshi-25851','鉴玄影堂','李紳','quantangshi','','卷26','香灯寂莫网尘中，烦恼身须色界空。
龙钵已倾无法雨，虎牀犹在有悲风。
定心池上浮泡没，招手岩边梦幻通。
深夜月明松子落，俨然听法侍生公。','',''),('quantangshi-25852','别石泉','李紳','quantangshi','','卷26','素沙见底空无色，青石潜流暗有声。
微渡竹风涵淅沥，细浮松月透轻明。
桂凝秋露添灵液，茗折香芽泛玉英。
应是梵宫连洞府，浴池今化醒泉清。','',''),('quantangshi-25853','别双温树','李紳','quantangshi','','卷26','翠条盈尺怜孤秀，植向西窗待月轩。
轻剪绿丝秋叶暗，密扶纤干夏阴繁。
故山手种空怀想，温室心知不敢言。
看尔拂云今得地，莫随陵谷改深根。','',''),('quantangshi-25854','重别西湖','李紳','quantangshi','','卷26','浦边梅叶看凋落，波上双禽去寂寥。
吹管曲传花易失，织文机学羽难飘。
雪欺春早摧芳蕚，隼励秋深拂翠翘。
繁艳彩毛无处所，尽成愁叹别溪桥。','',''),('quantangshi-25855','毗陵东山','李紳','quantangshi','','卷26','昔人别馆淹留处，卜筑东山学谢家。
业桂半空摧枳棘，曲池平尽隔烟霞。
重开渔浦连天月，更种春园满地花。
依旧秋风还寂莫，数行衰柳宿啼鸦。','',''),('quantangshi-25856','建元寺','李紳','quantangshi','','卷26','江城物候伤心地，远寺经过禁火辰。
芳草壠边回首客，野花丛里断肠人。
紫荆繁艳空门昼，红药深开古殿春。
叹息光阴催白发，莫悲风月独霑巾。','',''),('quantangshi-25857','却到金陵登北固亭','李紳','quantangshi','','卷26','龙形江影隔云深，虎势山光入浪沈。
潮蹙海风驱万里，日浮天堑洞千寻。
众峰作限横空碧，一柱中维彻底金。
还叱檝师看五两，莫令辜负济川心。','',''),('quantangshi-25858','望鹤林寺','李紳','quantangshi','','卷26','鹤栖峰下青莲宇，花发江城世界春。
红照日高殷夺火，紫凝霞曙莹销尘。
每思载酒悲前事，欲问题诗想旧身。
自叹秋风劳物役，白头拘束一闲人。','',''),('quantangshi-25859','宿瓜州','李紳','quantangshi','','卷26','烟昏水郭津亭晚，回望金陵若动摇。
冲浦回风翻宿浪，照沙低月歛残潮。
柳经寒露看萧索，人改衰容自寂寥。
官冷旧谙唯旅馆，岁阴轻薄是凉飙。','',''),('quantangshi-25860','入扬州郭','李紳','quantangshi','','卷26','菊芳沙渚残花少，柳过秋风坠叶疎。
堤绕门津喧井市，路交村陌混樵渔。
畏冲生客呼童仆，欲指潮痕问里闾。
非为掩身羞白发，自缘多病喜肩舆。','',''),('quantangshi-25861','宿扬州水馆','李紳','quantangshi','','卷26','舟依浅岸参差合，桥映晴虹上下连。
轻檝过时摇水月，远灯繁处隔秋烟。
却思海峤还凄叹，近涉江涛更凛然。
闲凭栏干指星汉，尚疑轩盖在楼船。','',''),('quantangshi-25862','州中小饮便别牛相','李紳','quantangshi','','卷26','笙歌罢曲辞宾侣，庭竹移阴就小斋。
愁不解颜徒满酌，病非伤肺为忧怀。
耻矜学步贻身患，岂慕醒狂蹑祸阶。
从此别离长酩酊，洛阳狂狷任椎埋。','',''),('quantangshi-25863','却过淮阴吊韩信庙','李紳','quantangshi','','卷26','功高自弃汉元臣，遗庙阴森楚水滨。
英主任贤增虎翼，假王徼福犯龙鳞。
贱能忍耻卑狂少，贵乏怀忠近佞人。
徒用千金酬一饭，不知明哲重防身。','',''),('quantangshi-25864','却入泗口','李紳','quantangshi','','卷26','洪河一派清淮接，堤草芦花万里秋。
烟树寂寥分楚泽，海云明灭满扬州。
望深江汉连天远，思起乡闾满眼愁。
惆怅路岐真此处，夕阳西没水东流。','',''),('quantangshi-25865','重入洛阳东门','李紳','quantangshi','','卷26','商颜重命伊川叟，时事知非入洛人。
连野碧流通御苑，满阶秋草过天津。
每惭清秩容衰齿，犹有华簪寄病身。
驱马独归寻里巷，日斜行处旧红尘。','',''),('quantangshi-25866','拜三川守','李紳','quantangshi','','卷26','恭承宠诏临伊洛，静守朝章化比闾。
风变市儿惊偃草，雨晴郊薮谬随车。
改张琴瑟移胶柱，止息笙篁辨鲁鱼。
唯有从容期一德，使齐文教奉皇居。','',''),('quantangshi-25867','庆云见','李紳','quantangshi','','卷26','礼成中岳陈金册，祥报卿云冠玉峰。
轻未透林疑待凤，细非行雨讵从龙。
卷风变彩霏微薄，照日笼光映隐重。
还入九霄成沆瀣，夕岚生处鹤归松。','',''),('quantangshi-25868','灵蛇见少林寺','李紳','quantangshi','','卷26','琐文结绶灵蛇降，蠖屈螭盘顾视闲。
鳞蹙翠光抽璀璨，腹连金彩动弯环。
已应蜕骨风雷后，岂効衔珠草莽间。
知尔全身护昆阆，不矜挥尾在常山。','',''),('quantangshi-25869','拜宣武军节度使','李紳','quantangshi','','卷26','油幢竝入虎旗开，锦橐从天凤诏来。
星应魏师新鼓角，地嫌梁苑旧池台。
日晖红斾分如电，人拥青门动若雷。
伊洛镜清回首处，是非纷杂任尘埃。','',''),('quantangshi-25870','到宣武三十韵','李紳','quantangshi','','卷26','七月趋梁苑，三年谢尹京。
旧风除物蠹，新律奉师贞。
龙节双油重，蛇矛百练明。
跃鱼连后斾，腾虎耀前旌。
路转金神竝，川开铁马横。
拥旄差白羽，分辔引红缨。
在浚风烟接，维嵩巩洛清。
贯鱼奔骑疾，连雁卷行轻。
烟垒风调角，秋原雨洗兵。
宿云看布甲，疎柳见分营。
鼓彻通宵警，和门候晓晴。
虎符三校列，鱼胄万夫迎。
弄马猨猱健，奔车角抵呈。
驾肩傍隘道，张幕内连楹。
森戟承三令，攒戈退一声。
及郊知雨过，观俗辨风行。
望宋怜思女，游梁念客卿。
义夫留感激，公子播英名。
泽广豚鱼洽，恩宣岂弟生。
善师忘任智，中略在推诚。
式宴歌钟合，陈筵绮绣并。
戏鼙千卒跃，均酒百壶倾。
乐与师徒共，欢从井邑盈。
教通因渐染，人悦尚和平。
授钺慙分阃，登坛荷列城。
虚裘朝独坐，雄劒夜孤鸣。
白发侵霜变，丹心捧日惊。
卫青终保志，潘岳未忘情。
期月终迷化，三年讵有成。
惟看波海动，天外斩长鲸。','',''),('quantangshi-25871','江南暮春寄家','李紳','quantangshi','','卷26','雒阳城见梅迎雪，鱼口桥逢雪送梅。
劒水寺前芳草合，镜湖亭上野花开。
江鸿断续翻云去，海燕差池拂水回。
想得心知近寒食，潜听喜鹊望归来。','',''),('quantangshi-25872','奉酬乐天立秋夕有怀见寄','李紳','quantangshi','','卷26','深夜星汉静，秋风初报凉。
阶篁淅沥响，露叶参差光。
冰兔半升魄，铜壶微滴长。
薄帷乍飘卷，襟带轻摇扬。
此际昏梦清，斜月满轩房。
屣履步前楹，劒戟森在行。
重城宵正分，号鼓互相望。
独坐有所思，夫君鸾凤章。
天津落星河，一苇安可航。
龙泉白玉首，鱼服黄金装。
报国未知効，惟鹈徒在梁。
裴回顾戎旃，颢气生东方。
衰叶满栏草，斑毛盈镜霜。
羸牛未脱辕，老马强腾骧。
吟君白雪唱，慙愧巴人肠。','',''),('quantangshi-25873','山出云','李紳','quantangshi','','卷26','杳霭祥云起，飘扬翠岭新。
萦峰开石秀，吐叶间松春。
林静翻空少，山明度岭频。
回崖时掩鹤，幽涧或随人。
姑射朝凝雪，阳台晚伴神。
悠悠九霄上，应坐玉京宾。','',''),('quantangshi-25874','上党奏庆云见','李紳','quantangshi','','卷26','飞龙久驭宇，真气尚兴云。
五色传嘉瑞，千龄表圣君。
从风忽萧索，依汉更氛氲。
影彻天初霁，光鲜日未曛。
表祥近自远，垂化聚还分。
宁作无依者，空传陶令文。','',''),('quantangshi-25875','华山庆云见','李紳','quantangshi','','卷26','圣主祠名岳，高峰发庆云。
金柯初缭绕，玉叶渐氛氲。
气色含珠日，晴光吐翠雰。
依稀来鹤态，仿髴列仙羣。
万树流光影，千潭写锦文。
苍生欣有望，祥瑞在吾君。','',''),('quantangshi-25876','欲到西陵寄王行周','李紳','quantangshi','','卷26','西陵沙岸回流急，船底黏沙去岸遥。
驿吏递呼催下缆，棹郎闲立道齐桡。
犹瞻伍相青山庙，未见双童白鹤桥。
欲责舟人无次第，自知贪酒过春潮。','',''),('quantangshi-25877','华顶','李紳','quantangshi','','卷26','欲向仙峰炼九丹，独瞻华顶礼仙坛。
石标琪树凌空碧，水挂银河映月寒。
天外鹤声随绛节，洞中云气隐琅玕。
浮生未有从师地，空诵仙经想羽翰。','',''),('quantangshi-25878','莺莺歌','李紳','quantangshi','','卷26','伯劳飞迟燕飞疾，垂杨绽金花笑日。
绿窗娇女字莺莺，金雀娅鬟年十七。
黄姑上天阿母在，寂莫霜姿素莲质。
门掩重关萧寺中，芳草花时不曾出。','',''),('quantangshi-25879','赠毛仙翁','李紳','quantangshi','','卷26','忆昔我祖神仙主，玄元皇帝周柱史。
曾师轩黄友尧汤，混迹和光佐周武。
周之天子无仙气，成武康昭都瞥尔。
穆王麤识神仙事，八极轮蹄方逞志。
鹤发韬真世不知，日月星辰几回死。
金鼎作丹丹化碧，三万六千神入宅。
仙兄受术几千年，已是当时驾鸿客。
海光悠容天路长，春风玉女开宫院。
紫笔亲教书姓名，玉皇诏刻青金简。
桂窗一别三千春，秦妃镜里娥眉新。
忽控香虬天上去，海隅劫石霄花尘。
一从仙驾辞中土，顽日昏风老无主。
九州争夺无时休，八骏垂头避豺虎。
我亦玄元千世孙，眼穿望断苍烟根。
花麟白凤竟冥寞，飞春走月劳神昏。
百年命促奔马疾，愁肠盘结心摧崪。
今朝稽首拜仙兄，愿赠丹砂化秋骨。','',''),('quantangshi-25880','和晋公三首 一','李紳','quantangshi','','卷26','凤仪常欲附，蚊力自知微。
愿假罇罍末，膺门自此依。','',''),('quantangshi-25881','和晋公三首 二','李紳','quantangshi','','卷26','貂蝉公独步，鸳鹭我同羣。
插羽先飞酒，交锋便着文。','',''),('quantangshi-25882','和晋公三首 三','李紳','quantangshi','','卷26','穷阴初莽苍，离思渐氛氲。
残雪午桥岸，斜阳伊水滨。','',''),('quantangshi-25883','古风二首 一','李紳','quantangshi','','卷26','春种一粒粟，秋成万颗子。
四海无闲田，农夫犹饿死。','',''),('quantangshi-25884','古风二首 二','李紳','quantangshi','','卷26','锄禾日当午，汗滴禾下土。
谁知盘中餐，粒粒皆辛苦。','',''),('quantangshi-25885','柳二首 一','李紳','quantangshi','','卷26','陶令门前罥接篱，亚夫营里拂朱旗。
人事推移无旧物，年年春至绿垂丝。','',''),('quantangshi-25886','柳二首 二','李紳','quantangshi','','卷26','千条垂柳拂金丝，日暖牵风叶学眉。
愁见花飞狂不定，还同轻薄五陵儿。','',''),('quantangshi-25887','题白乐天文集','李紳','quantangshi','','卷26','寄玉莲花藏，缄珠贝叶扃。
院闲容客读，讲倦许僧听。
部列雕金榜，题存刻石铭。
永添鸿宝集，莫杂小乘经。','',''),('quantangshi-25888','答章孝标','李紳','quantangshi','','卷26','假金方用真金镀，若是真金不镀金。
十载长安得一第，何须空腹用高心。','',''),('quantangshi-25889','朱槿花','李紳','quantangshi','','卷26','瘴烟长暖无霜雪，槿艳繁花满树红。
每叹芳菲四时厌，不知开落有春风。','',''),('quantangshi-25890','至潭州闻猿','李紳','quantangshi','','卷26','昔陪天上三清客，今作端州万里人。
湘浦更闻猿夜啸，断肠无泪可霑巾。','',''),('quantangshi-25891','江亭','李紳','quantangshi','','卷26','瘴江昏雾连天合，欲作家书更断肠。
今日病身悲状候，岂能埋骨向炎荒。','',''),('quantangshi-25892','红蕉花','李紳','quantangshi','','卷26','红蕉花样炎方识，瘴水溪边色最深。
叶满丛深殷似火，不唯烧眼更烧心。','',''),('quantangshi-25893','忆汉月','李紳','quantangshi','','卷26','花开花落无时节，春去春来有底凭。
燕子不藏雷不蛰，烛烟昏雾暗腾腾。','',''),('quantangshi-25894','端州江亭得家书二首 一','李紳','quantangshi','','卷26','雨中鹊语喧江树，风处蛛丝扬水浔。
开拆远书何事喜，数行家信抵千金。','',''),('quantangshi-25895','端州江亭得家书二首 二','李紳','quantangshi','','卷26','长安别日春风早，岭外今来白露秋。
莫道淮南悲木叶，不闻摇落更堪愁。','',''),('quantangshi-25896','闻猨','李紳','quantangshi','','卷26','见说三声巴峡深，此时行者尽沾襟。
端州江口连云处，始信哀猨伤客心。','',''),('quantangshi-25897','赠韦金吾','李紳','quantangshi','','卷26','自报金吾主禁兵，腰间宝劒重横行。
接舆也是狂歌客，更就将军乞一声。','',''),('quantangshi-25898','长门怨','李紳','quantangshi','','卷26','宫殿沈沈晓欲分，昭阳更漏不堪闻。
珊瑚枕上千行泪，不是思君是恨君。','',''),('quantangshi-25899','龟山寺鱼池 一','李紳','quantangshi','','卷26','汲水添池活白莲，十千鬐鬣尽生天。
凡庸不识慈悲意，自葬江鱼入九泉。','',''),('quantangshi-25900','龟山寺鱼池 二','李紳','quantangshi','','卷26','剃发多缘是代耕，好闻人死恶人生。
只园说法无高下，尔辈何劳尚世情。','',''),('quantangshi-25901','赋月','李紳','quantangshi','','卷26','月，光辉，皎洁。
耀干坤，静空阔。
圆满中秋，玩争诗哲。
玉兔镝难穿，桂枝人共折。
万象照乃无私，琼台岂遮君谒。
抱琴对弹别鹤声，不得知音声不切。','',''),('quantangshi-25902','句','李紳','quantangshi','','卷26','君咏风月夕，余当童稚年。
闲窗读书罢，偷咏左司篇。','',''),('quantangshi-25903','和太原张相公山亭怀古','崔公信','quantangshi','','卷26','叠石状崖巘，翠含城上楼。
前移庐霍峰，远带沅湘流。
潇洒主人静，夤缘芳径幽。
清辉在昏旦，岂异东山游。','',''),('quantangshi-25904','过小妓英英墓','楊虞卿','quantangshi','','卷26','萧晨骑马出皇都，闻说埋冤在路隅。
别我已为泉下土，思君犹似掌中珠。
四弦品柱声初绝，三尺孤坟草已枯。
兰质蕙心何所在，焉知过者是狂夫。','',''),('quantangshi-25905','句','楊虞卿','quantangshi','','卷26','河势昆仑远，山形菡萏秋。','',''),('quantangshi-25906','和段相公登武担寺西台','楊汝士','quantangshi','','卷26','清净此道宫，层台复倚空。
偶时三伏外，列席九霄中。
平视云端路，高临树杪风。
自怜荣末座，前日别池笼。','',''),('quantangshi-25907','和段相公夏登张仪楼','楊汝士','quantangshi','','卷26','从公城上来，秋近绝纤埃。
楼古秦规在，江分蜀望开。
远山标宿雪，末席本寒灰。
陪赏今为忝，临欢敢诉杯。','',''),('quantangshi-25908','和宗人尚书嗣复祠祭武侯毕题临淮公旧碑','楊汝士','quantangshi','','卷26','古栢森然地，修严蜀相祠。
一过荣异代，三顾盛当时。
功德流何远，馨香荐未衰。
敬名探国志，饰像慰甿思。
昔谒从征盖，今闻拥信旗。
固宜光宠下，有泪刻前碑。','',''),('quantangshi-25909','宴杨仆射新昌里第','楊汝士','quantangshi','','卷26','隔坐应须赐御屏，尽将仙翰入高冥。
文章旧价留鸾掖，桃李新阴在鲤庭。
再岁生徒陈贺宴，一时良史尽传馨。
当时疏广虽云盛，讵有兹筵醉绿醽。','',''),('quantangshi-25910','建节后偶作','楊汝士','quantangshi','','卷26','抛却弓刀上砌台，上方台榭与云开。
山僧见我衣裳窄，知道新从战地来。','',''),('quantangshi-25911','题画山水','楊汝士','quantangshi','','卷26','太华峰前是故乡，路人遥指读书堂。
如今老大骑官马，羞向关西道姓杨。','',''),('quantangshi-25912','贺筵占赠营妓','楊汝士','quantangshi','','卷26','郎君得意及青春，蜀国将军又不贫。
一曲高歌红一疋，两头娘子谢夫人。','',''),('quantangshi-25913','句','楊汝士','quantangshi','','卷26','昔日兰亭无艳质，此时金谷有高人。','',''),('quantangshi-25914','赋得芙蓉出水','陳至','quantangshi','','卷26','菡萏迎秋吐，夭摇映水滨。
剑芒开宝匣，峰影写蒲津。
下覆差参荇，高辞苒弱苹。
自当巢翠甲，非止戏頳鳞。
莫以时先后，而言色故新。
芳香正堪翫，谁报涉江人。','',''),('quantangshi-25915','荐冰','陳至','quantangshi','','卷26','凌寒开涸冱，寝庙致精诚。
色静澄三酒，光寒肃两楹。
形盐非近进，玉豆为潜英。
礼自春分展，坚从北陆成。
藉茅心共结，出鉴水渐明。
幸得来观荐，灵台一小生。','',''),('quantangshi-25916','句','陳至','quantangshi','','卷26','藻井尚寒龙迹在，红楼初施日光通。','',''),('quantangshi-25917','荐冰','趙蕃','quantangshi','','卷26','仲月开凌室，斋心感圣情。
寒姿分玉坐，皓彩发丹楹。
积素因风壮，虚空向日明。
遥涵牕户冷，近映冕旒清。
在掌光逾澈，当轩质自轻。
良辰方可致，由此表精诚。','',''),('quantangshi-25918','老人星','趙蕃','quantangshi','','卷26','大史占南极，秋分见寿星。
增辉延宝历，发曜起祥经。
灼烁依狼地，昭彰近帝庭。
高悬方杳杳，孤白乍荧荧。
应见光新吐，休征德自形。
既能符圣柞，从此表遐龄。','',''),('quantangshi-25919','古意','鮑溶','quantangshi','','卷26','女萝寄青松，绿蔓花绵绵。
三五定君婚，结发早移天。
肃肃羔雁礼，泠泠琴瑟篇。
恭承采蘩祀，敢効同车贤。
皎日不留景，良辰如逝川。
愁心忽移爱，花貌无归妍。
翠袖皓珠粉，碧阶封绿钱。
新人易如玉，废瑟难为弦。
寄谢蕣华木，荣君香阁前。
岂无摇落苦，贵与根蒂连。
希君旧光景，照妾薄暮年。','',''),('quantangshi-25920','萧史图歌','鮑溶','quantangshi','','卷26','霜绡数幅八月天，彩龙引凤堂堂然。
小载萧仙穆公女，随仙上归玉京去。
仙路迢遥烟几重，女衣清净云三素。
胡髯毵珊云髻光，翠蕤皎洁琼华凉。
露痕烟迹渍红貌，疑别秦宫初断肠。
此天每在西北上，紫霄洞客晓烟望。','',''),('quantangshi-25921','会仙歌','鮑溶','quantangshi','','卷26','轻轻蒙蒙，龙言凤语何从容。
耳有响兮目无踪，杳杳默默。
花张锦织，王[母]初自昆仑来。
茅盈王方平在侧，青毛仙鸟衔锦符。
谨上阿环起居王母书，始知仙事亦多故。
一隔绛河千岁余，详玉字。
多喜气，瑶台明月来堕地。
冠劒低昂蹈舞频，礼容尽若君臣事。
愿言小仙艺，姓名许飞琼。
洞阴玉磬敲天声，乐王[母]，一送玉杯长命酒。
碧花醉，灵扬扬，笑赐二子长生方。
二子未及伸拜谢，苍苍上兮皇皇下。','',''),('quantangshi-25922','李夫人歌','鮑溶','quantangshi','','卷26','璇闺羽帐华烛陈，方士夜降夫人神。
葳蕤半露芙蓉色，窈窕将期环佩身。
丽如三五月，可望难亲近。
嚬黛含犀竟不言，春思秋怨谁能问。
欲求巧笑如生时，歌尘在空瑟衔丝。
神来未及梦相见，帝比初亡心更悲。
爱之欲其生又死，东流万代无回水。
宫漏丁丁夜向晨，烟消雾散愁方士。','',''),('quantangshi-25923','水殿采菱歌','鮑溶','quantangshi','','卷26','宫鸦叫赤光，潮声入宫宫影凉。
火华啼露卷横塘，金堤四合宛柔扬。
美人荷裙芙蓉妆，柔荑萦雾棹龙航。
采莲一声歌态长，青丝结眼捕鸳鸯。','',''),('quantangshi-25924','周先生画洞庭歌','鮑溶','quantangshi','','卷26','江南客，水为乡，舟为宅，能以笔锋知地脉。
闲分楚水入丹青，不下此堂临洞庭。
水文不浪烟不动，木末棱棱山碧重。
帝子应哀窈窕云，客人似得婵娟梦。
六月火光衣上生，斋心寂听潺湲声。
林冰摇镜水拂簟，尽日独卧秋风清。','',''),('quantangshi-25925','霓裳羽衣歌','鮑溶','quantangshi','','卷26','玉烟生窗午轻凝，晨华左耀鲜相凌。
人言天孙机上亲手迹，有时怨别无所惜。
遂令武帝厌云韶，金针天丝缀飘飘。
五声写出心中见，拊石喧金栢梁殿。
此衣春日赐何人，秦女腰肢轻若燕。
香风间旋众彩随，联联珍珠贯长丝。
眼前意是三清客，星宿离离遶身白。
鸾凤有声不见身，出宫入征随伶人。
神仙如月只可望，瑶华池头几惆怅。
乔山一闭曲未终，鼎湖秋惊白头浪。','',''),('quantangshi-25926','寓兴','鮑溶','quantangshi','','卷26','念来若望神，追往如话梦。
梦神不无迹，谁使烦心用。
鲁圣虚泣鳞，楚狂浪歌凤。
那言阮家子，更作穷途恸。','',''),('quantangshi-25927','游山','鮑溶','quantangshi','','卷26','白道行深云，云高路弥细。
时时天上客，遗路人间世。
烟花最深处，井臼得空刺。
天寒鹤巢林，石长泉脉闭。
神化万灵集，心期一朝契。
不见金板书，谁知阮家裔。
终期太古人，问取松柏岁。','',''),('quantangshi-25928','隋宫','鮑溶','quantangshi','','卷26','御街多行客，行客悲春风。
楚老几代人，种田炀帝宫。
零落池台势，高低禾黍中。','',''),('quantangshi-25929','怀仙二首 一','鮑溶','quantangshi','','卷26','昆仑九层台，台上宫城峻。
西母持地图，东来献虞舜。
虞宫礼成后，回驾仙风顺。
十二楼上人，笙歌沸天引。
裴回扶桑路，白日生离恨。
青鸟更不来，麻姑断书信。
乃知东海水，清浅谁能问。','',''),('quantangshi-25930','怀仙二首 二','鮑溶','quantangshi','','卷26','阆峰绮阁几千丈，瑶水西流十二城。
曾见周灵王太子，碧桃花下自吹笙。','',''),('quantangshi-25931','怀远人','鮑溶','quantangshi','','卷26','远道在天际，客行如浮云。
浮云不知归，似我长望君。
秋至汉水高，南音何时闻？
瑶草难远寄，西风气氤氲。
常恐山岳游，不反鸾凤羣。
无厌坐迟人，风雨惊斯文。','',''),('quantangshi-25932','怀尹真人','鮑溶','quantangshi','','卷26','万里叠嶂翠，一心浮云闲。
羽人杏花发，倚树红琼颜。
流水杳冥外，女萝阴荫间。
却思人间世，多恐不可还。
青鸟飞难远，春云晴不闲。
但恐五云车，山上复有山。','',''),('quantangshi-25933','秋晚铜山道中宿隐者','鮑溶','quantangshi','','卷26','我乡山川遥，秋晚空景促。
天明共云散，日落依鸟宿。
主人逃名子，鹤发卧空谷。
野言得真风，山貌宜古服。
喜于无声地，暂傲羲皇俗。
秋窗照疎萤，寒犬吠落木。
朝隐留此处，一点天边宿。
今忆见此时，添悲览止足。
迟迟清夜昼，幽路出深竹。
笑谢万户侯，余将耻干禄。','',''),('quantangshi-25934','感怀','鮑溶','quantangshi','','卷26','宿心不觉远，事去劳追忆。
旷古川上怀，东流几时息。
门前青山路，眼见归不得。
晓梦云月光，过秋兰蕙色。','',''),('quantangshi-25935','经秦皇墓','鮑溶','quantangshi','','卷26','左岗青虬盘，右坂白虎踞。
谁识此中陵，祖龙藏身处。
别为一天地，下入三泉路。
珠华翔青鸟，玉影耀白兔。
山河一易姓，万事随人去。
白昼盗开陵，玄冬火焚树。
哀哉送死厚，乃为弃身具。
死者不复知，回看汉文墓。','',''),('quantangshi-25936','将归旧山留别孟郊','鮑溶','quantangshi','','卷26','择木无利刃，羡鱼无巧纶。
如何不量力，自取中路贫。
前者不厌耕，一日不离亲。
今来千里外，我心不在身。
悠悠慈母心，惟愿才如人。
蚕桑能几许，衣服常着新。
一饭吐尺丝，谁见此殷勤。
别君归耕去，持火烧车轮。','',''),('quantangshi-25937','留辞杜员外式方','鮑溶','quantangshi','','卷26','东风吹旅怀，乡梦无夜无。
惭见君子堂，贫思上归途。
海岳泛念深，涓尘复何须。
婆娑不在本，屈曲无弦弧。
恻恻奉离尊，承欢独向隅。
时当凤来日，孰用鸡鸣夫。
回首九仙门，皇家在玉壶。
慙非海人别，泪下不成珠。','',''),('quantangshi-25938','长城','鮑溶','quantangshi','','卷26','蒙公虏生人，北筑秦氏冤。
祸兴萧墙内，万里防祸根。
城成六国亡，宫阙启千门。
生人半为土，何用空中原。
奈何家天下，骨肉尚无恩。
投沙拥海水，安得久不翻。
乘高惨人魂，寒日易黄昏。
枯骨贯朽铁，砂中如有言。
万古骊山下，徒悲野火燔。','',''),('quantangshi-25939','蔡平喜遇河阳马判官宽话别','鮑溶','quantangshi','','卷26','从事东军正四年，相逢且喜偃兵前。
看寻狡兔翻三窟，见射妖星落九天。
江上柳营回鼓角，河阳花府望神仙。
秋风萧飒醉中别，白马嘶霜雁叫烟。','',''),('quantangshi-25940','寄福州从事殷尧藩','鮑溶','quantangshi','','卷26','越岭寒轻物象殊，海城台阁似蓬壶。
几回入市鲛绡女，终岁啼花山鹧鸪。
雷令劒龙知去未，虎夷云鹤亦来无。
就中静事冥宵话，何惜双轮访病夫。','',''),('quantangshi-25941','壮士行','鮑溶','quantangshi','','卷26','西方太白高，壮士羞病死。
心知报恩处，对酒歌易水。
沙鸿嘷天末，横劒别妻子。
苏武执节归，班超束书起。
山河不足重，重在遇知己。','',''),('quantangshi-25942','章华宫行','鮑溶','quantangshi','','卷26','烟渚南鸿呼晓羣，章华宫娥怨行云。
十二巫峯仰天禄，金车何处邀云宿。
小腰婑堕三千人，宫衣水碧颜青春。
岂无一人似神女，忍使黛蛾常不伸。
黛蛾不伸犹自可，春朝诸处门常鏁。','',''),('quantangshi-25943','倚瑟行','鮑溶','quantangshi','','卷26','金舆传惊灞浐水，龙旗参天行殿巍。
左文皇帝右慎姬，北面侍臣张释之。
因高知处邯郸道，寿陵已见生秋草。
万世何人不此归，一言出口堪生老。
高歌倚瑟流清悲，徐乐哀生知为谁。
臣惊欢叹不可放，愿赐一言释名妄。
明珠为日红亭亭，水银为河玉为星。
泉宫一闭秦国丧，牧童弄火骊山上。
与世无情在速贫，弃尸于野由斯葬。
生死茫茫不可知，视不一姓君莫悲。
始皇有训二世哲，君独何人至于斯。
灞陵一代无发毁，俭风本是张廷尉。','',''),('quantangshi-25944','辞辇行','鮑溶','quantangshi','','卷26','汉家代久淳风薄，帝重微行极荒乐。
青娥三千奉一人，班女不以色事君。
朝停玉辇诏同载，三十六宫皆眄睐。
不惊六马缓天仪，从容鸣环前致辞。
君恩如海深难竭，妾命如丝轻易绝。
愿陪阿[母]同小星，敢使太阳齐万物。
周末幽王不可宗，妾闻上圣遗休风。
五更三老待白日，八十一女居深宫。
愿将辇内有余席，回赐忠臣妾恩泽。','',''),('quantangshi-25945','巢乌行','鮑溶','quantangshi','','卷26','乌生几子林萧条，雄乌求食雌守巢。
夜愁风雨巢倾覆，常见一乌巢下宿。
日长雏饥雄未回，雌鸟下巢去哀哀。
野田春尽少遗谷，寻食不得饥飞来。
黄雀亦引数青雀，雀飞未远乌惊落。
既分青雀噉尔雏，尔雏虽长心何如。
将飞不飞犹未忍，古瑟写哀哀不尽。','',''),('quantangshi-25946','姑苏宫行','鮑溶','quantangshi','','卷26','姑苏宫，九层金台半虚空。
雕楹璇题鬬皎洁，中有妖姬似明月。
西见洞庭秋镜开，水华百里盘宫来。
越王采女能水戏，仙舟如龙旌曳翠。
羽盖晴翻橘柚香，玉笙夜送芙蓉醉。
归帆平静君无劳，还从下下上高高。','',''),('quantangshi-25947','悲哉行','鮑溶','quantangshi','','卷26','促促晨复昏，死生同一源。
贵年不惧老，贱老伤久存。
朗朗哭前歌，绛旌引幽魂。
来为千金子，去卧百草根。
黄土塞生路，悲风送回辕。
金鞍旧良马，四顾不入门。
生结千岁念，荣华及百孙。
黄金买性命，白刃酬一言。
宁知北山下，松柏侵田园。','',''),('quantangshi-25948','元日早朝行','鮑溶','quantangshi','','卷26','干元发生春为宗，盛德在天斗建东。
东方岁星大明宫，南山喜气摇晴空。
望云五等舞万玉，献寿一声出千峯。
文章垂彩礼乐正，太白下直旌旗红。
旌旗不断春风前，直如朱绳非尔妍。','',''),('quantangshi-25949','秋怀五首 一','鮑溶','quantangshi','','卷26','促促生有涯，营营意无限。
无限意未申，有涯生已晚。
恩荣不可恃，天道归寸管。
老如影随人，时若车下坂。
行者归期尽，居人心更远。
凉风日萧条，亲戚长在眼。
多忧知无奈，圣贤莫能免。
客鸟投本枝，生生复深浅。','',''),('quantangshi-25950','秋怀五首 二','鮑溶','quantangshi','','卷26','秋晓客迢迢，月清风楚楚。
草虫夜侵我，唧唧牀下语。
流年白日驰，微愿不我与。
心如缫丝纶，展转多头绪。
凭觞散烦襟，援瑟清夜拊。
回感帝子心，空堂有烟雨。
丝减悲不减，器新声更古。
一弦有余哀，何况二十五。','',''),('quantangshi-25951','秋怀五首 三','鮑溶','quantangshi','','卷26','九月夜如年，幽房劳别梦。
不知别日远，夜夜犹相送。
玉牀暗虫响，锦席寒泪冻。
明镜失旧人，空林误归凤。
新年堪爱惜，锦字亦珍重。
一念皎皎时，幽襟非所用。','',''),('quantangshi-25952','秋怀五首 四','鮑溶','quantangshi','','卷26','金气白日来，疎黄满河关。
平居乏愉悦，况复身险艰。
一忆故乡居，一望客人还。
两心四海中，谁不伤朱颜。
双燕不巢树，浮萍不出山。
性命君由天，安得易其间。
休悲砌虫苦，此日无人闲。','',''),('quantangshi-25953','秋怀五首 五','鮑溶','quantangshi','','卷26','龙荒变露色，燕雁南为客。
游子声影中，涕零念离析。
四时如车马，转此今与昔。
往叹在空中，存事委幽迹。
翩翩日歛照，朗朗月系夕。
物生春不留，年壮老还迫。
天机杳何为，长寿与松柏。','',''),('quantangshi-25954','秋夜对月怀李正封','鮑溶','quantangshi','','卷26','援琴怅独立，高月对秋堂。
美人远于月，徒望空景光。
坐忆执手时，七弦起凄凉。
平生知音少，君子安可忘。
客意如梦寐，路岐遍四方。
日远迷所之，满天心暗伤。
主奉二鲤鱼，中含五文章。
惜无千金答，愁思盈中肠。
此夕临风叹，零露霑衣裳。','',''),('quantangshi-25955','庐山石镜','鮑溶','quantangshi','','卷26','东岩采薇人，岩际朝见月。
怪堕幽萝间，非时更澄彻。
绿萝就玉兔，再与高鸟歇。
清光照掌中，始悟石上发。
谁传阴阳火，铸此天地物。
深影藏半山，虚轮带凝雪。
早回谢公赏，今遇樵夫说。
白日乘彩霞，翩翩对容发。
我图辨鬼魅，信美留烟阙。
形神乍相逢，竟夕难取别。
如其终身照，可化黄金骨。','',''),('quantangshi-25956','与峨眉山道士期尽日不至','鮑溶','quantangshi','','卷26','倾景安再中，人生有何常。
胡为少君别，风驭峨眉阳。
结我千日期，青山故人堂。
期尽师不至，望云空烧香。
顾慙有限身，易老白日光。
怀君屡惊叹，支体安能强。
往闻清修箓，未究服食方。
瑶田有灵芝，眼见不得尝。
玉壶贮天地，岁月亦已长。
若用壶中景，东溟又堪伤。
寄言赤玉箫，夜夜吹清商。','',''),('quantangshi-25957','述德上太原严尚书绶','鮑溶','quantangshi','','卷26','帝命河岳神，降灵翼轩辕。
天王委管龠，开闭秦门北。
顶戴日月光，口宣雨露言。
甲马不及汗，天骄自亡魂。
清冢入内地，黄河穷本源。
风云寝气象，鸟兽翔旗幡。
军人歌无胡，长劒倚昆仑。
终古鞭血地，到今耕稼繁。
樵客天一畔，何由拜旌轩。
愿请执御臣，为公动朱轓。
岂令羣荒外，尚有辜帝恩。
愿陈田舍歌，暂息四坐喧。
条桑去附枝，剃草绝本根。
可惜汉公主，哀哀嫁乌孙。','',''),('quantangshi-25958','山中怀刘修','鮑溶','quantangshi','','卷26','松老秋意孤，夜凉吟风水。
山人在远道，相忆中夜起。
春光如不至，幽兰含香死。
响象离鹤情，念来一相似。
月斜掩扉卧，又在梦魂里。','',''),('quantangshi-25959','塞下','鮑溶','quantangshi','','卷26','北风号蓟门，杀气日夜兴。
咸阳三千里，驿马如饥鹰。
行子久去乡，逢山不敢登。
寒日惨大野，虏云若飞鹏。
西北防秋军，麾幢宿层层。
匈奴天未丧，战鼓长登登。
汉卒马上老，繁缨空丝绳。
诚知天所骄，欲罢又不能。','',''),('quantangshi-25960','送僧南游','鮑溶','quantangshi','','卷26','且攀隋宫柳，莫忆江南春。
师有怀乡志，未为无事人。','',''),('quantangshi-25961','行路难','鮑溶','quantangshi','','卷26','玉堂向夕如无人，丝竹俨然宫商死。
细人何言入君耳，尘生金罇酒如水。
君今不念岁蹉跎，雁天明明凉露多。
华灯清凝久照夜，彩僮窈窕虚垂萝。
入宫见妒君不察，暮入此地生风波。
此时不乐早休息，女颜易老君如何。','',''),('quantangshi-25962','子规','鮑溶','quantangshi','','卷26','中林子规啼，云是古蜀帝。
蜀帝胡为鸟，惊急如罪戾。
一啼艳阳节，春色亦可替。
再啼孟夏林，密叶堪委翳。
三啼凉秋晓，百卉无生意。
四啼玄冥冬，云物惨不霁。
芸黄壮士发，沾洒妖姬袂。
悲深寒乌雏，哀掩病鹤翅。
胡为托幽命，庇质无完毳。
戚戚含至冤，卑卑忌羣势。
吾闻凤皇长，羽族皆受制。
盍分翡翠毛，使学鹦鹉慧。
敌怨不在弦，一哀尚能继。
那令不知休，泣血经世世。
古风失中和，衰代因郑卫。
三叹尚淫哀，向渴嘻流涕。
如因异声感，乐与中肠契。
至教一昏芜，生人遂危脆。
古意叹通近，如上青天际。
荼蓼久已甘，空劳堇葵惠。
谁闻子规苦，思与正声计。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-25963','秋夜闻郑山人弹楚妃怨','鮑溶','quantangshi','','卷26','明月摇落夜，深堂清净弦。
中间楚妃奏，十指哀婵娟。
寥寥夜含风，荡荡意如泉。
寂寞物无象，依稀语空烟。
旅人多西望，客雁难南前。
由来感神事，岂为无情传。
容华能几时，不再来者年。
此夕河汉上，双星含凄然。','',''),('quantangshi-25964','忆旧游','鮑溶','quantangshi','','卷26','忆求无何乡，了在赤谷村。
仙人居其中，将往问所存。
日入蒙汜宿，石烟抱山门。
明月久不下，半峯照啼猨。
堂上白鹤翁，神清心无烦。
斋心侍席前，跪请长生恩。
云昔崆峒老，何词受轩辕。
从星使变化，任日张干坤。
若到旧乡里，宛如曾讨论。
风移嵓花气，珠贯金经言。
凉夜惜易尽，青烟谢晨喧。
自唯腥膻体，难久留其藩。
几世身在梦，百年云无根。
悠悠竟何事，愚智相忧冤。
叹息几晚寤，蒙师招其魂。
至今瑶华心，每想清水源。','',''),('quantangshi-25965','白露','鮑溶','quantangshi','','卷26','清蝉暂休响，丰露还移色。
金飙爽晨华，玉壶增夜刻。
已低疎萤焰，稍减哀蝉力。
迎社促燕心，助风劳雁翼。
一悲纨扇情，再想清浅忆。
高高拜月归，轧轧挑灯织。
盈盈玉盘泪，何处无消息。','',''),('quantangshi-25966','经隐叟','鮑溶','quantangshi','','卷26','行蹋门外泉，坐披牀上云。
谁将许由事，万古留与君。
虚洞闭金鏁，蠹简藏鸟文。
萝景深的的，蕙风闲薰薰。
余有世上心，此来未及羣。
殷勤讳姓名，莫遣樵客闻。','',''),('quantangshi-25967','秋暮山中怀李端公益','鮑溶','quantangshi','','卷26','旧事与日远，秋花仍旧香。
前年绣衣客，此节过此堂。
侍臣不自高，笑脱绣衣裳。
眠云有余态，入鸟不乱行。
我恐云岚色，损君鞍马光。
君言此何言，且共覆前觞。
古人重一笑，买日轻金装。
日尽秉烛游，千年不能忘。
君言此何言，明日皆异乡。
明日非今日，山下道路长。
一从山下来，天地再炎凉。
此中会难得，梦君马玄黄。','',''),('quantangshi-25968','苦哉远征人','鮑溶','quantangshi','','卷26','征人歌古曲，携手上河梁。
李陵死别处，窅杳玄冥乡。
忆昔从此路，连年征鬼方。
久行迷汉历，三死氊衣裳。
百战身且在，微功信难忘。
远承云台议，非势孰敢当。
落日吊李广，白首过河阳。
闲弓失月影，劳劒无龙光。
去日始束发，今来发成霜。
虚名乃闲事，生见父母乡。
掩抑大风歌，裴回少年场。
诚哉古人言，鸟尽良弓藏。','',''),('quantangshi-25969','悼豆卢策先辈','鮑溶','quantangshi','','卷26','丧车出东门，生时马无力。
何处入黄泉，嵩高山西北。
室人万里外，久望君官职。
今与牵衣儿，翻号死消息。
平生江海上，我不空相识。
远客迷畏途，孤鸿伤一翼。
行将鸡黍祭，已是乌鸢食。
劝酒执御郎，行人有哀色。
先悲三尺土，经岁哭不得。
眼前双双流，故袂安可拭。
一拜隔千里，生人意何极。
唯有阳春曲，永播清玉德。','',''),('quantangshi-25970','首夏','鮑溶','quantangshi','','卷26','昨日青春去，晚峯尚含妍。
虽留有余态，脉脉防忧煎。
幽人惜时节，对此感流年。','',''),('quantangshi-25971','寄天台准公','鮑溶','quantangshi','','卷26','赤城桥东见月夜，佛壠寺边行月僧。
闲蹋莓苔绕琪树，海光清净对心灯。','',''),('quantangshi-25972','送僧东游','鮑溶','quantangshi','','卷26','风流东晋后，外学入僧家。
独唱郢中雪，还游天际霞。
云村共香饭，水月喻秋花。
景物添新致，前程讵可涯。','',''),('quantangshi-25973','送僧之宣城','鮑溶','quantangshi','','卷26','昔从谢太守，宾客宛陵城。
有日持斋戒，高僧识姓名。
秋风送客去，安得尽忘情。','',''),('quantangshi-25974','宣城北楼昔从顺阳公会于此','鮑溶','quantangshi','','卷26','诗楼郡城北，窗牖敬亭山。
几步尘埃隔，终朝世界闲。
凭师看粉壁，名姓在其间。','',''),('quantangshi-25975','东高峯','鮑溶','quantangshi','','卷26','东亭最高峙，春树绕山腰。
画里青鸾客，云中碧玉箫。
秋风若西望，为我一长谣。','',''),('quantangshi-25976','禅定寺经院','鮑溶','quantangshi','','卷26','莲华不朽寺，雕刻满山根。
石汗知天雨，金泥落圣言。
思量施金客，千古独消魂。','',''),('quantangshi-25977','范真传侍御累有寄因奉酬十首 一','鮑溶','quantangshi','','卷26','昨日新花红满眼，今朝美酒绿留人。
更宜明月含芳露，凭仗萧郎夜赏春。','',''),('quantangshi-25978','范真传侍御累有寄因奉酬十首 二','鮑溶','quantangshi','','卷26','白雪翦花朱蜡蒂，折花传笑惜春人。
请君白日留明日，一醉春风莫厌频。','',''),('quantangshi-25979','范真传侍御累有寄因奉酬十首 三','鮑溶','quantangshi','','卷26','云髻凤文细，对君歌少年。
万金酬一顾，可惜十千钱。','',''),('quantangshi-25980','范真传侍御累有寄因奉酬十首 四','鮑溶','quantangshi','','卷26','玉管倾杯乐，春园鬬草情。
野花无限意，处处逐人行。','',''),('quantangshi-25981','范真传侍御累有寄因奉酬十首 五','鮑溶','quantangshi','','卷26','闻道中山酒，一杯千日醒。
黄莺似传语，劝酒太叮咛。','',''),('quantangshi-25982','范真传侍御累有寄因奉酬十首 六','鮑溶','quantangshi','','卷26','红袂歌声起，因君始得闻。
黄昏小垂手，与我驻浮云。','',''),('quantangshi-25983','范真传侍御累有寄因奉酬十首 七','鮑溶','quantangshi','','卷26','相劝醉年华，莫醒春日斜。
春风宛陵道，万里晋阳花。','',''),('quantangshi-25984','范真传侍御累有寄因奉酬十首 八','鮑溶','quantangshi','','卷26','碧绿草萦堤，红蓝花满溪。
愿君常践蹋，莫使暗萋萋。','',''),('quantangshi-25985','范真传侍御累有寄因奉酬十首 九','鮑溶','quantangshi','','卷26','萋萋巫峡云，楚客莫留恩。
岁久晋阳道，谁能向太原。','',''),('quantangshi-25986','范真传侍御累有寄因奉酬十首 十','鮑溶','quantangshi','','卷26','岁酒劝屠苏，楚声山鹧鸪。
春风入君意，千日不须臾。','',''),('quantangshi-25987','越女词','鮑溶','quantangshi','','卷26','越女芙蓉妆，浣纱清浅水。
忽惊春心晓，不敢思君子。
君子纵我思，宁来浣溪里。','',''),('quantangshi-25988','弄玉词二首 一','鮑溶','quantangshi','','卷26','素女结念飞天行，白玉参差凤皇声，天仙借女双翅猛。
五灯绕身生，入烟去无影。','',''),('quantangshi-25989','弄玉词二首 二','鮑溶','quantangshi','','卷26','三清弄玉秦公女，嫁得天上人。
琼箫碧月唤朱雀，携手上谒玉晨君。
夫妻同寿，万万青春。','',''),('quantangshi-25990','山行经樵翁','鮑溶','quantangshi','','卷26','我心劳我身，远道谁与论。
心如木中火，忧至常自燔。
披访结恩地，世人轻报恩。
女无良媒识，知入何人门。
寒日行深山，路由谷中村。
田翁樵采熟，男女讴吟喧。
借问身命谋，上言愧干坤。
时清公赋薄，力勤地利繁。
下念草木年，坐家见重孙。
举案馈宾客，糟浆盈陶尊。
醉闲鹿裘煗，白发舞轩轩。
仰羡太古人，余将破行辕。
遑遑问身事，师友难为言。
离歌又行去，落日低寒泉。','',''),('quantangshi-25991','途中旅思二首 一','鮑溶','quantangshi','','卷26','喔喔鸡鸣晓，萧萧马辞枥。
草草名利区，居人少于客。
生期三万日，童耄半虚掷。
修短命半中，忧欢复相敌。
朝提黄金爵，暮造青松宅。
来往日相悲，北邙田土窄。
峨峨西天岳，锦绣明翠壁。
中有不死乡，千年无人迹。
心期周太子，下马拜虚碧。
鹤驾如可从，他年执烟策。','',''),('quantangshi-25992','途中旅思二首 二','鮑溶','quantangshi','','卷26','星出方问宿，睡眼始朦胧。
天光见地色，上路车幢幢。
时物既老大，众山何枯空。
青冥见古栢，寥朗闻疎鸿。
独步天地间，无因为君忠。
白毛寻人忧，生此头发中。
跃马非壮岁，报恩无高功。
斯言化为火，日夜焚深衷。','',''),('quantangshi-25993','旧镜','鮑溶','quantangshi','','卷26','婵娟本家镜，与妾归君子。
每忆并照时，相逢明月里。
春风忽分影，白日难依倚。
珠粉不结花，玉璫宁辉耳。
心期不可见，不保长如此。
华发一欺人，青铜化为鬼。
良人有归日，肯学妖桃李。
瑶匣若浮云，冥冥藏玉水。
侍儿不遣照，恐学孤鸾死。','',''),('quantangshi-25994','宿悟空寺赠僧','鮑溶','quantangshi','','卷26','劳者谣烛蛾，致身何营营。
雪山本师在，心地如镜清。
往与本师别，人间买浮名。
朝光畏不久，内火烧人情。
迷路喜为远，宿留化人城。
前心宛如此，了了随静生。
维持薝卜花，却与前心行。','',''),('quantangshi-25995','感兴','鮑溶','quantangshi','','卷26','幽人无近迹，别易会则稀。
黄鹤亦姓丁，寥寥何处飞？
时见海上山，绕云心依依。
谅无驭风术，中路愁虚归。
童发慕道心，壮年堕尘机。
白日不饶我，如今事皆非。
羣羊化石尽，双凫与我违。
□岳黄金富，轩辕晓霞衣。
谁令日在眼，容色烟云微。','',''),('quantangshi-25996','秋思','鮑溶','quantangshi','','卷26','楚客秋更悲，皇皇无声地。
时无无事人，我命与身异。
良时如飞鸟，回掌成故事。
蹉跎秋定还，凝冽坚冰至。
人生不期老，华发谁能避。
感此惜壮年，壮年少为贵。
我生虽努力，荣途难自致。
徒为击角歌，且慙雕劒字。
吾师罕言命，感激潜伤思。','',''),('quantangshi-25997','客途逢乡人旋别','鮑溶','quantangshi','','卷26','惊鸿一断行，天远会无因。
无因忽相会，感叹若有神。
我乡路三千，百里一主人。
一宿独何恋，何况旧乡邻。
牢落岁华晏，相怜客中贫。
迎霜君衣暖，与我同一身。
谁在天日下，此生能不勤。
青萍寄流水，安得长相亲。
明发更远道，山河重苦辛。','',''),('quantangshi-25998','隋帝陵下','鮑溶','quantangshi','','卷26','白露沾衣隋主宫，云亭月馆楚淮东。
盘龙楼舰浮冤水，雕锦帆幢使乱风。
长夜应怜桀何罪，告成合笑禹无功。
伤心近似骊山路，陵树无根秋草中。','',''),('quantangshi-25999','洛阳春望','鮑溶','quantangshi','','卷26','五凤楼南望洛阳，龙门回合抱苍苍。
受朝前殿云霞煗，封岳行宫草木香。
四海为家知德盛，二京有宅卜年长。
东人犹忆时巡礼，愿觐元和日月光。','',''),('quantangshi-26000','始见二毛','鮑溶','quantangshi','','卷26','玄发迎忧光色阑，衰华因镜强相看。
百川赴海返潮易，一叶报秋归树难。
初弄藕丝牵欲断，又惊机素翦仍残。
颜生岂是光阴晚，余亦何人不自宽。','',''),('quantangshi-26001','巫山怀古','鮑溶','quantangshi','','卷26','十二峯峦鬬翠微，石烟花雾犯容辉。
青春楚女妒云老，白日神人入梦稀。
银箭暗凋歌夜烛，珠泉频点舞时衣。
谁伤宋玉千年后，留得青山辨是非。','',''),('quantangshi-26002','郊天回','鮑溶','quantangshi','','卷26','日动萧烟上泰坛，帝从黄道整和銮。
风前貔武回雕仗，云里神龙起画竿。
金鸟赦书鸣九夜，玉山寿酒舞千官。
始知报本终朝礼，旧典时巡只自难。','',''),('quantangshi-26003','温泉宫','鮑溶','quantangshi','','卷26','忆昔开元天地平，武皇十月幸华清。
山蒸阴火云三素，日落温泉鸡一鸣。
彩羽鸟仙歌不死，翠霓童妾舞长生。
仍闻老叟垂黄发，犹说龙髯缥缈情。','',''),('quantangshi-26004','寄归','鮑溶','quantangshi','','卷26','塞草黄来见雁稀，陇云白后少人归。
新丝强入未衰鬓，别泪应沾独宿衣。
几夕精诚拜初月，每秋河汉对空机。
更看出猎相思苦，不射秋田朝雉飞。','',''),('quantangshi-26005','赠远','鮑溶','quantangshi','','卷26','辛苦关西车骑官，几年旌节客河兰。
金泥舞虎精神暗，银缕交龙气色寒。
欲和古诗成窦锦，倍悲秋扇损齐纨。
莫劳雁足传书信，愿向凌烟阁上看。','',''),('quantangshi-26006','九日与友人登高','鮑溶','quantangshi','','卷26','云木疎黄秋满川，茱萸风里一尊前。
几回为客逢佳节，曾见何人再少年。
霜报征衣冷针指，雁惊幽梦泪婵娟。
古来醉乐皆难得，留取穷通付上天。','',''),('quantangshi-26007','赠杨炼师','鮑溶','quantangshi','','卷26','紫烟衣上绣春云，清隐山书小篆文。
明月在天将凤管，夜深吹向玉晨君。','',''),('quantangshi-26008','玉清坛','鮑溶','quantangshi','','卷26','上阳宫里女，玉色楚人多。
西信无因得，东游奈乐何。','',''),('quantangshi-26009','答客','鮑溶','quantangshi','','卷26','竹间深路马惊嘶，独入蓬门半似迷。
劳问圃人终岁事，桔槔声里雨春畦。','',''),('quantangshi-26010','隋宫','鮑溶','quantangshi','','卷26','柳塘烟起日西斜，竹浦风回雁弄沙。
炀帝春游古城在，坏宫芳草满人家。','',''),('quantangshi-26011','送僧文江','鮑溶','quantangshi','','卷26','吴王劒池上，禅子石房深。
久慕白云性，忽劳青玉音。
孤高知胜鹤，清雅似闻琴。
此韵书珍重，烦师出定吟。','',''),('quantangshi-26012','古意','鮑溶','quantangshi','','卷26','重锦化为泥，翦刀误人事。
夜裁远道书，翦破相思字。
妾心不自信，远道终难寄。
客心固多疑，肯信非人意。
万里不言远，归书长相次。
可即由此书，空房□忌讳。','',''),('quantangshi-26013','山中冬思二首 一','鮑溶','quantangshi','','卷26','山深先冬寒，败叶与林齐。
门巷非世路，何人念穷栖。
哀风破山起，夕雪误鸣鸡。
巢鸟侵旦出，饥猨无声啼。
晨兴动烟火，开云伐冰溪。
老木寒更瘦，阴云晴亦低。
我贫自求力，颜色常低迷。
时思灵台下，游子正凄凄。','',''),('quantangshi-26014','山中冬思二首 二','鮑溶','quantangshi','','卷26','雪壮冰亦坚，冻涧如平地。
幽人毛褐暖，笑就糟牀醉。
唤人空谷应，开火寒猨至。
拾薪煮秋栗，看鼎书古字。
忽忆南涧游，衣巾多云气。
露脚寻逸僧，谘量意中事。','',''),('quantangshi-26015','读史','鮑溶','quantangshi','','卷26','鬼书报秦亡，天地亦云闭。
赤龙吟大野，老[母]哭白帝。
苍苍无白日，项氏徒先济。
六合已姓刘，鸿门事难制。
坑降嬴政在，衣锦人望替。
宿昔见汉兵，龙蛇满旌棨。
始矜山可拔，终叹骓不逝。
区区亚父心，未究天人际。
萧张马无汗，盛业垂千世。','',''),('quantangshi-26016','冬夜答客','鮑溶','quantangshi','','卷27','冬日诚可爱，不如夜漏多。
幸君霜露里，车马犯寒过。
学耕不逢年，稂莠败黍禾。
岂唯亲宾散，鸟鼠移巢窠。
独见青松心，凌霜庇柔萝。
壮日贱若此，留恩意如何。
因忆古丈夫，一言重山河。
临风弹楚劒，为子奏燕歌。','',''),('quantangshi-26017','宿吴兴道中苕村','鮑溶','quantangshi','','卷27','浮客倦长道，秋深夜如年。
久行惜日月，常起鸡鸣前。
夕计今日程，息车在苕川。
霜中水南寺，金磬泠泠然。
畴昔此林下，归心巢顶禅。
身依寤昏寐，智月生虚圆。
羁旅违我程，去留难双全。
观身话往事，如梦游青天。
明发止宾从，寄声琴上弦。
聊书越人意，此曲名思仙。','',''),('quantangshi-26018','代楚老酬主人','鮑溶','quantangshi','','卷27','流水为我乡，扁舟为我宅。
二毛去天远，几日人间客。
曈曈衔山景，渺渺翔云迹。
从时无定心，病处不暖席。
烦君问岐路，为我生凄慽。
百年衣食身，未死皆有役。
曾伤无遗嗣，纵有复何益。
终古北邙山，樵人卖松栢。','',''),('quantangshi-26019','沛中怀古','鮑溶','quantangshi','','卷27','烟芜歌风台，此是赤帝乡。
赤帝今已矣，大风邈凄凉。
惟昔仗孤劒，十年朝八荒。
人言生处乐，万乘巡东方。
高台何巍巍，行殿起中央。
兴言万代事，四坐沾衣裳。
我为异代臣，酌水祀先王。
抚事复怀昔，临风独彷徨。','',''),('quantangshi-26020','夏日华山别韩博士愈','鮑溶','quantangshi','','卷27','别地泰华阴，孤亭潼关口。
夏日可畏时，望山易迟久。
暂因车马倦，一逐云先后。
碧霞气争寒，黄鸟相语诱。
三峰多异态，逈举仙人手。
天晴捧日轮，月夕弄星斗。
幽疑白帝近，明见黄河走。
远心不期来，真境非吾有。
鸟鸣草木下，日息天地右。
踯躅因风松，青冥谢仙叟。
不知无声泪，中感一颜厚。
青霄上何阶，别劒空朗扣。
故乡此关外，身与名相守。
迹比断根蓬，忧如长饮酒。
生离抱多恨，方寸安可受。
咫尺岐路分，苍烟蔽回首。','',''),('quantangshi-26021','春日言怀','鮑溶','quantangshi','','卷27','湛湛琴前酒，期自赏青春。
胡为缄笑语，深念不思身。
寂寂花舞多，嘤嘤鸟言频。
心悲兄弟远，愿见相似人。
江界田土卑，竞来东作勤。
岁寒虚尽力，家外无强亲。
杳窅青云望，无途同苦辛。','',''),('quantangshi-26022','题吴征君岩居','鮑溶','quantangshi','','卷27','尧泽润天下，许由心不知。
真风存绵緜，常与达者期。
有道吾不仕，有生吾不欺。
澹然灵府中，独见太古时。
地脉发醴泉，岩根生灵芝。
天文若通会，星影应离离。
亭亭傅氏岩，何独万古思。','',''),('quantangshi-26023','云溪竹园翁','鮑溶','quantangshi','','卷27','硠硠云溪里，翠竹和云生。
古泉积涧深，竦竦如刻成。
楚客卧云老，世间无姓名。
因兹千亩业，以代双牛耕。
乱林不可留，寸茎不可轻。
风暖鬬出地，仰齐故年茎。
幽室结白茅，密叶罗众清。
照水寒澹荡，对山绿峥嵘。
苍松含古貌，秋桂俨白英。
相看受天风，深夜戛击声。','',''),('quantangshi-26024','窃览都官李郎中和李舍人益酬张舍人弘静夏夜寓直思闻雅琴见寄','鮑溶','quantangshi','','卷27','朝草天子奏，夜语思忧琴。
因声含香气，其韵流水音。
仙乐朱凤意，灵芝紫鸾心。
翻然远求友，岂独双归林。
松吹暑中冷，星花池上深。
倘俾有声乐，请以丝和金。','',''),('quantangshi-26025','长安言怀','鮑溶','quantangshi','','卷27','殷殷生念厚，戚戚劳者多。
二时昼夜等，百岁讵几何。
日下文翰苑，侧身识经过。
千虑恐一失，翔阳已蹉跎。
临觞翦众忧，静寄丝桐歌。
思归绕十指，五声不相和。
暮天还巢翼，明日陨叶柯。
高谢岩谷人，鹿衣带女萝。
生不去亲爱，浮名若风波。
谁令不及此，亲爱隔山河。','',''),('quantangshi-26026','秋思三首 一','鮑溶','quantangshi','','卷27','胡风吹雁翼，远别无人乡。
君近雁来处，几回断君肠。
昔奉千日书，抚心怨星霜。
无书又千日，世路重茫茫。
燕国有佳丽，蛾眉富春光。
自然君归晚，花落君空堂。
君其若不然，岁晚双鸳鸯。','',''),('quantangshi-26027','秋思三首 二','鮑溶','quantangshi','','卷27','顾兔蚀残月，幽光不如星。
女儿晚事夫，颜色同秋萤。
秋日边马思，武夫不遑宁。
燕歌易水怨，劒舞蛟龙腥。
风折连枝树，水翻无蔕萍。
立身多门户，何必燕山铭。
生世不如鸟，双双比翼翎。','',''),('quantangshi-26028','秋思三首 三','鮑溶','quantangshi','','卷27','季秋天地闲，万物生意足。
我忧长于生，安得及草木。
试从古人愿，致酒歌秉烛。
燕赵皆世人，讵能长似玉。
俯怜老期近，仰视日车速。
萧飒御风君，魂梦愿相逐。
百年夜销半，端为垂缨束。','',''),('quantangshi-26029','归雁','鮑溶','quantangshi','','卷27','南国春早暖，渚蒲正月生。
东风吹雁心，上下和乐声。
绕水半空去，拂云偕相迎。
如防失羣怨，预有侵夜惊。
渺邈天外影，支离塞中莺。
自顾摧颓羽，偏感南北情。
乍甘烟雾劳，不顾龙沙荣。
虽乐未归意，终不能自鸣。
喜去春月满，归来秋风清。
啼余碧窗梦，望断阴山行。
不及瑶𥯅燕，寄身金宫楹。','',''),('quantangshi-26030','悲湘灵','鮑溶','quantangshi','','卷27','山上凉云收，日斜川风止。
娥皇五十弦，秋深汉江水。
初因无象外，牵感百忧里。
霜露结瑶华，烟波劳玉指。
将随落叶去，又绕疎苹起。
哀响云合来，清余桐半死。
女颜万岁后，岂复婵娟子。
不道神无悲，那能久如此。
魂魄无不之，九山徒相似。
没没竟不从，唯伤远人耳。
斑斑泪篁下，恐有学瑟鬼。','',''),('quantangshi-26031','闻蝉','鮑溶','quantangshi','','卷27','高蝉旦夕唳，景物浮凉气。
木叶渐惊年，锦字因络纬。
稍断当窗梦，更凄临水意。
清香笋蒂风，晓露莲花泪。
余引未全歇，凝悲寻迥至。
星井欲望河，月扇看藏笥。
谁念因声感，放歌写人事。','',''),('quantangshi-26032','怀幽期','鮑溶','quantangshi','','卷27','清砧击霜天外发，楚僧期到石上月。
寒峯深虚独遶尽，夜水浅急不可越。
窅机冥智难思量，无尽性月如空王。
眼界行处不着我，天花下来惟有香。','',''),('quantangshi-26033','思琴高','鮑溶','quantangshi','','卷27','琴仙人，得仙去。
万古钓龙空有处，我持曲钩思白鱼。
仙溪绿尽含空虚，天钧踪迹无遗余。
烧香寄影在岩树，东礼海日鸡鸣初。','',''),('quantangshi-26034','得储道士书','鮑溶','quantangshi','','卷27','婵娟春尽暮心秋，邻里同年半白头。
为问蓬莱近消息，海波平静好东游。','',''),('quantangshi-26035','寒夜吟','鮑溶','quantangshi','','卷27','九衢金吾夜行行，上宫玉漏遥分明。
霜飙乘阴扫地起，旅鸿迷雪遶枕声。
远人归梦既不成，留家惜夜欢心发。
罗幕画堂深皎洁，兰烟对酒客几人。
兽火扬光二三月，细腰楚姬丝竹间。
白紵长袖歌闲闲，岂识苦寒损朱颜。','',''),('quantangshi-26036','采莲曲二首 一','鮑溶','quantangshi','','卷27','弄舟朅来南塘水，荷叶映身摘莲子。
暑衣清净鸳鸯喜，作浪舞花惊不起。
殷勤护惜纤纤指，水菱初熟多新刺。','',''),('quantangshi-26037','采莲曲二首 二','鮑溶','quantangshi','','卷27','采莲朅来水无风，莲潭如鉴松如龙。
夏衫短袖交斜红，艳歌笑鬬新芙蓉。','',''),('quantangshi-26038','玉山谣奉送王隐者','鮑溶','quantangshi','','卷27','凤皇城南玉山高，石脚耸立争雄豪。
攒峯胎玉气色润，百泉透云流不尽。
万古分明对眼开，五烟窈窕呈祥近。
有客师事金身仙，用金买得山中田。
闲开玉水灌芝草，静醉天酒松间眠。
心期南溟万里外，出山几遇光阴改。
水玉丁东不可闻，冰华皎洁应如待。
秋风引吾歌去来，玉山彩翠遥相催。
殷勤千树玉山顶，碧洞寥寥寒锦苔。','',''),('quantangshi-26039','岐路','鮑溶','quantangshi','','卷27','北风送微寒，徒侣勤远征。
忧人席不暖，残月马上明。
飘飘岐路间，长见日初生。
重嶂晓色浅，疎猨寒啼清。
人间多岐路，常恐终身行。
回见四方人，车轮无留声。
空谷亦堪隐，下田非嬾耕。
古人有遗训，饱食非亲荣。
我生礼义乡，少小见太平。
圣贤犹羁旅，况复非其名。','',''),('quantangshi-26040','陇头水','鮑溶','quantangshi','','卷27','陇头水，千古不堪闻。
生归苏属国，死别李将军。
细响风凋草，清哀雁落云。','',''),('quantangshi-26041','沙上月','鮑溶','quantangshi','','卷27','黄昏潮落南沙明，月光涵沙秋雪清。
水文不上烟不荡，平平玉田冷空旷。','',''),('quantangshi-26042','赠李黯将军','鮑溶','quantangshi','','卷27','细柳连营石壍牢，平安狼火赤星高。
岩云入角雕龙爽，寒日摇旗画兽豪。
搜伏雄儿欺魍魉，射声游骑怯分毫。
圣人唯有河[湟]恨，寰海无虞在一劳。','',''),('quantangshi-26043','人日陪宣州范中丞传正与范侍御宴','鮑溶','quantangshi','','卷27','人日春风绽早梅，谢家兄弟看花来。
吴姬对客歌千曲，秦女留人酒百杯。
丝柳向空轻婉转，玉山看日渐裴回。
流光易去欢难得，莫厌频频上此台。','',''),('quantangshi-26044','古鉴','鮑溶','quantangshi','','卷27','古鉴含灵气象和，蛟龙盘鼻护金波。
隐山道士未曾识，负局先生不敢磨。
曾向春窗分绰约，误回秋水照蹉跎。
世间纵有应难比，十斛明珠酬未多。','',''),('quantangshi-26045','送王炼师','鮑溶','quantangshi','','卷27','圣母祠堂药树香，邑君承命荐椒浆。
风云大感精神地，雷雨频过父母乡。
尽日一川侵草绿，回车二麦遶山黄。
野人久会神仙事，敢奏歌钟庆万箱。','',''),('quantangshi-26046','寄张十七校书李仁行秀才','鮑溶','quantangshi','','卷27','去年八月此佳辰，池上闲闲四五人。
久行月影愁迷梦，误入华光笑认春。
一与清风上芸阁，再期秋雨过龙津。
今年此日何由见，蓬户萧条对病身。','',''),('quantangshi-26047','送王损之秀才赴举','鮑溶','quantangshi','','卷27','青门佩兰客，淮水誓风流。
名在乡书贡，心期月殿游。
平沙大河急，细雨二陵秋。
感此添离恨，年光不少留。','',''),('quantangshi-26048','旧镜','鮑溶','quantangshi','','卷27','团团铜镜似潭水，心爱玉颜私自亲。
一经离别少年改，难与清光相见新。','',''),('quantangshi-26049','忆郊天','鮑溶','quantangshi','','卷27','忆向郊坛望武皇，九军旗帐下南方。
六龙日驭天行健，神母呈图地道光。
浓暖气中生历草，是非烟里爱瑶浆。
至今满耳箫韶曲，徒羡瑶池舞凤皇。','',''),('quantangshi-26050','期尽','鮑溶','quantangshi','','卷27','鱼鏁生衣门不开，玉筐金月共尘埃。
青山石妇千年望，雷雨曾知来不来。','',''),('quantangshi-26051','晚山蝉','鮑溶','quantangshi','','卷27','山蝉秋晚妨人语，客子惊心马亦嘶。
能阅几时新碧树，不知何日寂金闺。
若逢海月明千里，莫忘何郎寄一题。','',''),('quantangshi-26052','秋暮送裴垍员外刺婺州','鮑溶','quantangshi','','卷27','婺女星边气不秋，金华山水似瀛州。
含香太守心清净，去与神仙日日游。','',''),('quantangshi-26053','寄薛膺昆季','鮑溶','quantangshi','','卷27','楚山清洛两无期，梦里春风玉树枝。
何况芙蓉楼上客，海门江月亦相思。','',''),('quantangshi-26054','杨真人箓中像','鮑溶','quantangshi','','卷27','画中留得清虚质，人世难逢白鹤身。
应见茅盈哀老弟，为持金箓救生人。','',''),('quantangshi-26055','寄卢给事汀吴员外丹','鮑溶','quantangshi','','卷27','姓丁黄鹤辽东去，客倩仙翁海上人。
闻道姓名多改变，只今偕是圣朝臣。','',''),('quantangshi-26056','怀王直秀才','鮑溶','quantangshi','','卷27','乡无竹圃为三径，贫寄邻家已二年。
惟有素风身未坠，世间开口不言钱。','',''),('quantangshi-26057','赠真公影堂','鮑溶','quantangshi','','卷27','旧房西壁画支公，昨暮今晨色不同。
远客闲心无处所，独添香火望虚空。','',''),('quantangshi-26058','赠僧戒休','鮑溶','quantangshi','','卷27','风行露宿不知贫，明月为心又是身。
欲问月中无我法，无人无我问何人。','',''),('quantangshi-26059','秋夜怀紫阁峯僧','鮑溶','quantangshi','','卷27','满山雨色应难见，隔涧经声又不闻。
紫阁夜深多入定，石台谁为扫秋云。','',''),('quantangshi-26060','酬江公见寄','鮑溶','quantangshi','','卷27','曾答雁门偈，为怜同社人。
多慙惠休句，偕得此阳春。','',''),('quantangshi-26061','送罗侍御归西台','鮑溶','quantangshi','','卷27','归台新柱史，辞府旧英髦。
劝酒莲幕贵，望尘骢马高。
诗情分绣段，劒彩拂霜毫。
此举关风化，谁云别恨劳。','',''),('quantangshi-26062','宿水亭','鮑溶','quantangshi','','卷27','雕楹彩槛压通波，鱼鳞碧幕衔曲玉。
