野人为此多东望，云雨仍从海上来。','',''),('quantangshi-26065','淮南卧病感路羣侍御访别','鮑溶','quantangshi','','卷27','西台御史重难言，落木疎篱遶病魂。
一望青云感骢马，欵行黄草出柴门。','',''),('quantangshi-26066','题禅定寺集公竹院','鮑溶','quantangshi','','卷27','公门得休静，禅寺少逢迎。
任客看花醉，随僧入竹行。
归时常犯夜，云里有经声。','',''),('quantangshi-26067','风筝','鮑溶','quantangshi','','卷27','何响与天通，瑶筝挂望中。
彩弦非触指，锦瑟忽闻风。
雁柱虚连势，鸾歌且坠空。
夜和霜击磬，晴引凤归桐。
幽咽谁生怨，清泠自匪躬。
秦姬收宝匣，搔首不成功。','',''),('quantangshi-26068','经旧游','鮑溶','quantangshi','','卷27','游鱼怀故池，倦鸟怀故窠。
故山系归念，行坐青巍峨。
羸马经旧途，此乡喜重过。
居人无故老，倍感别日多。
但见野中坟，累累如青螺。
凉风日摇落，桑下松婆娑。
叹息追古人，临风伤逝波。
古人无不死，叹息欲如何。
朅来遂远心，默默存天和。','',''),('quantangshi-26069','过薛舍人旧隐','鮑溶','quantangshi','','卷27','寝门来哭夜，此月小祥初。
风意犹忆瑟，萤光乍近书。
墙蒿藏宿鸟，池月上钩鱼。
徒引相思泪，涓涓东逝余。','',''),('quantangshi-26070','山居','鮑溶','quantangshi','','卷27','窈窕垂涧萝，蒙茸黄葛花。
鸳鸯怜碧水，照影舞金沙。','',''),('quantangshi-26071','暮秋与裴居晦宴因见采菊花之作','鮑溶','quantangshi','','卷27','菊花低色过重阳，似忆王孙白玉觞。
今日王孙好收采，高天已下两回霜。','',''),('quantangshi-26072','望麻姑山','鮑溶','quantangshi','','卷27','幽人往往怀麻姑，浮世悠悠仙景殊。
自从青鸟不堪使，更得蓬莱消息无。','',''),('quantangshi-26073','湖上望月','鮑溶','quantangshi','','卷27','湖上清凉月更好，天边旅人犹未归。
几见金波满还破，草虫声畔露沾衣。','',''),('quantangshi-26074','襄阳怀古','鮑溶','quantangshi','','卷27','襄阳太守沈碑意，身后身前几年事。
湘江千岁未为陵，水底鱼龙应识字。','',''),('quantangshi-26075','秋夜对月寄僧特','鮑溶','quantangshi','','卷27','忆见特公赏秋处，凉溪看月清光寒。
