可怜夜久月中行，惟有坛边一枝竹。','',''),('quantangshi-26078','得僧书','鮑溶','quantangshi','','卷27','身归紫霄岭，书下白云来。
翦笋发寒字，烧花芳夜雷。
想随香驭至，不假定钟催。','',''),('quantangshi-26079','见袁德师侍御说江南有仙檀花因以戏赠','鮑溶','quantangshi','','卷27','闻说天坛花耐凉，笑风含露对秋光。
欲求御史更分别，何似衣花岁岁香。','',''),('quantangshi-26080','和王璠侍御酬友人赠白角冠','鮑溶','quantangshi','','卷27','芙蓉寒艳镂冰姿，天朗灯深拔豸时。
