可怜石室烧香夜，江月对心无是非。','',''),('quantangshi-26083','上巳日寄樊瓘樊宗宪兼呈上浙东孟中丞简','鮑溶','quantangshi','','卷27','世间禊事风流处，镜里云山若画屏。
今日会稽王内史，好将宾客醉兰亭。','',''),('quantangshi-26084','暮春戏赠樊宗宪','鮑溶','quantangshi','','卷27','羌笛胡琴春调长，美人何处乐年芳。
