应和朝云垂手语，肯嫌夜色断刀光。','',''),('quantangshi-26085','酬王侍御','鮑溶','quantangshi','','卷27','慙非青玉制，故以赠仙郎。
希翼留书合，提携在笔牀。
讵能辉绣服，安得似芸香。
所报何珍重，清明胜夜光。','',''),('quantangshi-26086','寄宋申锡评事时从李少师移军回归','鮑溶','quantangshi','','卷27','君逐元侯静虏归，虎旗龙节驻春晖。
欲求岱岳燔柴礼，已锡鲁人缝掖衣。
长劒一时天外倚，五云多遶日边飞。
心期共贺太平世，去去故乡亲食薇。','',''),('quantangshi-26087','夏日怀杜悰驸马','鮑溶','quantangshi','','卷27','五月清凉萧史家，瑶池分水种菱花。
回文地簟龙鳞浪，交鏁天窗蝉翼纱。
闲遣青琴飞小雪，自看碧玉破甘瓜。
仍闻圣主知书癖，凤阁烧香对五车。','',''),('quantangshi-26088','莺雏','鮑溶','quantangshi','','卷27','双莺衔野蝶，枝上教雏飞。
避日花阴语，愁风竹里啼。
须防美人赏，为尔好毛衣。','',''),('quantangshi-26089','上阳宫月','鮑溶','quantangshi','','卷27','水北宫城夜柝严，宫西新月影纤纤。
受环花幌小开镜，移烛瑶房皆卷帘。
学织机边娥影静，拜新衣上露华沾。
合裁班扇思行幸，愿托凉风箧笥嫌。','',''),('quantangshi-26090','淮南卧病闻李相夷简移军山阳以靖东寇感激之下因抒长句','鮑溶','quantangshi','','卷27','太白星前龙虎符，元臣出将顺天诛。
教闻清净萧丞相，计立安危范大夫。
玉帐黄昏大刁斗，月营寒晓小单于。
鲁连未必蹈沧海，应见麒麟新画图。','',''),('quantangshi-26091','读淮南李相行营至楚州诗','鮑溶','quantangshi','','卷27','阃外建牙威不宾，古来戡难忆忠臣。
已分舟楫归元老，更使熊罴属丈人。
玄象合教沧海晏，青龙喜应太山春。
来年二月登封礼，去望台星扈日轮。','',''),('quantangshi-26092','读李相心中乐','鮑溶','quantangshi','','卷27','负海狂鲸纵巨鳞，四朝天子阻时巡。
谁将侯玉乖南面，几使戎军殷左轮。
久作妖星虚费日，终□天洞亦何人。
果闻丞相心中乐，上赞陶唐一万春。','',''),('quantangshi-26093','闻国家将行封禅聊抒臣情','鮑溶','quantangshi','','卷27','云雨由来随六龙，玉泥瑶检不干封。
山知槱柞新烟火，臣望箫韶旧鼓钟。
清跸间过素王庙，翠华高映大夫松。
旅中病客谙尧曲，身贱何由奏九重。','',''),('quantangshi-26094','和淮南李相公夷简喜平淄青回军之作','鮑溶','quantangshi','','卷27','横笛临吹发晓军，元戎幢节拂寒云。
搜山羽骑乘风引，下濑楼船背水分。
天际兽旗摇火焰，日前鱼甲动金文。
马毛不汗东方靖，行见萧何第一勋。','',''),('quantangshi-26095','秋暮八月十五夜与王璠侍御赏月因怆远离聊以奉寄','鮑溶','quantangshi','','卷27','前月月明夜，美人同远光。
清尘一以间，今夕坐相忘。
风落芙蓉露，凝余绣服香。','',''),('quantangshi-26096','送萧世秀才','鮑溶','quantangshi','','卷27','心交别我西京去，愁满春魂不易醒。
从此无人访穷病，马蹄车辙草青青。','',''),('quantangshi-26097','怀惠明禅师','鮑溶','quantangshi','','卷27','秋天欲霜夜无风，我意不在天地中。
雪山世界此凉夜，宝月独照琉璃宫。
解空长老莲花手，曾以佛书亲指授。
雪岭无人又问来，十年夏腊平安否。','',''),('quantangshi-26098','吴中夜别','鮑溶','quantangshi','','卷27','楚客秋思着黄叶，吴姬夜歌停碧云。
声尽灯前各流泪，水天凉冷雁离羣。','',''),('quantangshi-26099','隋家井','鮑溶','quantangshi','','卷27','玉钩栏下寒泉水，金辘轳边影照人。
此水今为九泉路，数枝花照数堆尘。','',''),('quantangshi-26100','寄王璠侍御求蜀笺','鮑溶','quantangshi','','卷27','蜀川牋纸彩云初，闻说王家最有余。
野客思将池上学，石楠红叶不堪书。','',''),('quantangshi-26101','湘妃列女操','鮑溶','quantangshi','','卷27','有虞夫人哭虞后，淑女何事又伤离，竹上泪迹生不尽。
寄哀云和五十丝，云和终奏钧天曲。
乍听宝琴遥嗣续，三湘测测流急绿。
秋夜露寒蜀帝飞，枫林月斜楚臣宿。
更疑川宫日黄昏，暗携女手殷勤言。
环佩玲珑有无间，终疑既远双悄悄。
苍梧旧云岂难召，老猨心寒不可啸。
目眄眄兮意蹉跎，魂腾腾兮惊秋波。
曲一尽兮忆再奏，众弦不声且如何。','',''),('quantangshi-26102','羽林行','鮑溶','quantangshi','','卷27','朝出羽林宫，入参云台议。
独请万里行，不奏和亲事。
君王重年少，深纳开边利。
宝马雕玉鞍，一朝从万骑。
煌煌都门外，祖帐光七贵。
歌钟乐行军，云物惨别地。
箫笳整部曲，幢盖动郊次。
临风亲戚怀，满袖儿女泪。
行行复何赠，长劒报恩字。','',''),('quantangshi-26103','鸣雁行','鮑溶','quantangshi','','卷27','七月朔方雁心苦，联影翻空落南土。
八月江南阴复晴，浮云绕天难夜行。
羽翼劳痛心虚惊，一声相呼百处鸣。
楚童夜宿烟波侧，沙上布罗连草色。
月暗风悲欲下天，不知何处容栖息？
楚童胡为伤我神，尔不曾作远行人。
江南羽族本不少，宁得网罗此客鸟。','',''),('quantangshi-26104','织妇词','鮑溶','quantangshi','','卷27','百日织彩丝，一朝停杼机。
机中有双凤，化作天边衣。
使人马如风，诚不阻音徽。
影响随羽翼，双双绕君飞。
行人岂愿行，不怨不知归。
所怨天尽处，何人见光辉。','',''),('quantangshi-26105','塞上行','鮑溶','quantangshi','','卷27','西风应时筋角坚，承露牧马水草冷。
可怜黄河九曲尽，毡馆牢落胡无影。','',''),('quantangshi-26106','采珠行','鮑溶','quantangshi','','卷27','东方暮空海面平，骊龙弄珠烧月明。
海人惊窥水底火，百宝错落随龙行。
浮心一夜生奸见，月质龙躯看几遍。
擘波下去忘此身，迢迢谓海无灵神。
海宫正当龙睡重，昨夜孤光今得弄。
河伯空忧水府贫，天吴不敢相惊动。
一团冰容掌上清，四面人入光中行。
腾华乍摇白日影，铜镜万古羞为灵。
海边老翁怨狂子，抱珠哭向无底水。
一富何须龙颔前，千金几葬鱼腹里。
鳞虫变化为阴阳，填海破山无景光。
拊心仿髴失珠意，此土为尔离农桑。
饮风衣日亦饱暖，老翁掷却荆鸡卵。','',''),('quantangshi-26107','采葛行','鮑溶','quantangshi','','卷27','春溪几回葛花黄，黄麝引子山山香。
蛮女不惜手足损，钩刀一一牵柔长。
葛丝茸茸春雪体，深涧择泉清处洗。
殷勤十指蚕吐丝，当窗袅袅声高机。
织成一尺无一两，供进天子五月衣。
水精夏殿开凉户，冰山绕座犹难御。
衣亲玉体又何如，杳然独对秋风曙。
镜湖女儿嫁鲛人，鲛绡逼肖也不分。
吴中角簟泛清水，摇曳胜被三素云。
自兹贡荐无人惜，那敢更争龙手迹。
蛮女将来海市头，卖与岭南贫估客。','',''),('quantangshi-26108','南塘二首 一','鮑溶','quantangshi','','卷27','南塘旅舍秋浅清，夜深绿苹风不生。
莲花受露重如睡，斜月起动鸳鸯声。','',''),('quantangshi-26109','南塘二首 二','鮑溶','quantangshi','','卷27','塘东白日驻红雾，早鱼翻光落碧浔。
画舟兰棹欲破浪，恐畏惊动莲花心。','',''),('quantangshi-26110','东邻女','鮑溶','quantangshi','','卷27','双飞鹧鸪春影斜，美人盘金衣上花。
身为父母几时客，一生知向何人家。','',''),('quantangshi-26111','寄李都护','鮑溶','quantangshi','','卷27','去年河上送行人，万里弓旌一武臣。
闻道玉关烽火灭，犬戎知有外家亲。','',''),('quantangshi-26112','长安旅舍怀旧山','鮑溶','quantangshi','','卷27','昨夜清凉梦本山，眠云唤鹤有慙颜。
青莲道士长堪羡，身外无名至老闲。','',''),('quantangshi-26113','汉宫词二首 一','鮑溶','quantangshi','','卷27','栢梁宸居清窈窕，东方先生夜待诏。
夜久月当承露盘，内人吹笙舞凤鸾。','',''),('quantangshi-26114','汉宫词二首 二','鮑溶','quantangshi','','卷27','月映东窗似玉轮，未央前殿绝声尘。
宫槐花落西风起，鹦鹉惊寒夜唤人。','',''),('quantangshi-26115','荐冰','鮑溶','quantangshi','','卷27','西陵宜先启，春寒寝庙清。
历官分气候，天子荐精诚。
已辨瑶池色，如和玉佩鸣。
礼余神转肃，曙后月残明。
雅合霜容洁，非同雪体轻。
空怜一掬水，珍重此时情。','',''),('quantangshi-26116','送薛补阙入朝','鮑溶','quantangshi','','卷27','平原门下十余人，独受恩多未杀身。
每叹陆家兄弟少，更怜杨氏子孙贫。
柴门已断施行马，鲁酒那能醉近臣。
赖有军中遗令在，犹将谈笑对风尘。','',''),('quantangshi-26117','句','鮑溶','quantangshi','','卷27','万里岐路多，一身天地窄。','',''),('quantangshi-26118','荐冰','盧鈞','quantangshi','','卷27','荐冰朝日后，辟庙晓光清。
不改晶荧质，能彰语露情。
且无霜共洁，岂与水均明。
在捧摇寒色，当呈表素诚。
凝姿陈俎豆，浮彩映牕楹。
皎皎盘盂侧，棱棱严气生。','',''),('quantangshi-26119','荐冰','范傳質','quantangshi','','卷27','乘春方启闭，羞献有常程。
洁朗寒光彻，辉华素彩明。
色凝霜雪净，影照冕旒清。
肃肃将崇礼，兢兢示捧盈。
方圆陈玉座，小大表精诚。
朝觌当西陆，桃弧每共行。','',''),('quantangshi-26120','赋得芙蓉出水','賈謩','quantangshi','','卷27','的皪舒芳艳，红姿映绿苹。
摇风开细浪，出沼媚清晨。
翻影初迎日，流香暗袭人。
独披千叶浅，不竞百花春。
鱼戏参差动，龟游次第新。
涉江如可采，从此免迷津。','',''),('quantangshi-26121','恩赐魏文贞公诸孙旧第以𨗳直臣','陳彥博','quantangshi','','卷27','阿衡随逝水，池馆主他人。
天意能酬德，云孙喜庇身。
生前由直道，殁后振芳尘。
雨露新恩日，芝兰旧里春。
勋庸留十代，光彩映诸邻。
共贺升平日，从兹得谏臣。','',''),('quantangshi-26122','使南海道长沙题道林岳麓寺','扶','quantangshi','','卷27','道林岳麓仲与昆，卓荦请从先后论。
松根踏云二千步，始见大屋开三门。
泉清或戏蛟龙窟，殿豁数尽高帆掀。
即今异鸟声不断，闻道看花春更繁。
从容一衲分若有，萧瑟两鬓吾能髠。
逢迎侯伯转觉贵，膜拜佛像心加尊。
稍揖皇英頮浓泪，试与屈贾招清魂。
荒唐大树悉楠桂，细碎枯草多兰荪。
沙弥去学五印字，静女来悬千尺幡。
主人念我尘眼昏，半夜号令期至暾。
迟回难得上白舫，羁泄不敢言绿尊。
两祠物色采拾尽，壁间杜甫真少恩。
晚来光彩更腾射，笔锋正健如可吞。','',''),('quantangshi-26123','和兵部郑侍郎省中四松诗','扶','quantangshi','','卷27','幽抱应无语，贞松遂自栽。
寄怀丞相业，因擢大夫材。
日射苍鳞动，尘迎翠箒回。
嫩茸含细粉，初叶泛新杯。
偶圣为舟去，逢时与鹤来。
寒声连晓竹，静气结阴苔。
赫奕鸣驺至，荧煌洞户开。
良辰一临眺，憩树几裴回。
恨发风期阻，诗从绮思裁。
还闻旧凋契，凡在此中培。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-26124','和兵部郑侍郎省中四松诗','陶雍','quantangshi','','卷27','右相历兵署，四松皆手栽。
斸时惊鹤去，移处带云来。
根倍双桐植，花分八桂开。
生成造化力，长作栋梁材。
岂羡兰依省，犹嫌柏占台。
出楼终百尺，入梦已三台。
幽韵和宫漏，余香度酒杯。
拂冠枝上雪，染履影中苔。
高位相承地，新诗寡和才。
何由比萝蔓，攀附在条枚。','',''),('quantangshi-26125','谭子池','郭周藩','quantangshi','','卷27','澄水一百步，世名谭子池。
余诘陵阳叟，此池当因谁。
父老谓余说，本郡谭叔皮。
开元末年中，生子字阿宜。
坠地便能语，九岁多须眉。
不饮亦不食，未尝言渴饥。
十五锐行走，快马不能追。
二十入山林，一去无还期。
父母忆念深，乡闾为立祠。
大历元年春，此儿忽来归。
头冠簪凤皇，身着霞裳衣。
普遍拯疲俗，丁宁告亲知。
余为神仙官，下界不可祈。
恐为妖魅假，不如早平夷。
此有黄金藏，镇在兹庙基。
发掘散生聚，可以救贫羸。
金出继灵泉，湛若清琉璃。
泓澄表符瑞，水旱无竭时。
言讫辞冲虚，杳霭上玄微。
凡情留不得，攀望众号悲。
寻禀神仙诫，彻庙斸开窥。
果获无穷宝，均融霑困危。
巨源出岭顶，喷涌世间稀。
异境流千古，终年福四维。','',''),('quantangshi-26126','金谷园花发怀古','侯冽','quantangshi','','卷27','金谷千年后，春花发满园。
红芳徒笑日，穠艳尚迎轩。
雨湿轻光软，风摇碎影翻。
犹疑施锦帐，堪叹罢朱纨。
愁态莺吟涩，啼容露缀繁。
殷勤问前事，桃李竟无言。','',''),('quantangshi-26127','花发上林','侯冽','quantangshi','','卷27','花发三阳盛，香飘五柞深。
素晖云积苑，红彩绣张林。
落水随鱼戏，摇风映鸟吟。
琼楼出高艳，玉辇驻浓阴。
乱蝶枝开影，繁蜂蘂上音。
鲜芳盈禁籞，布泽荷天心。','',''),('quantangshi-26128','金谷园花发怀古','王質','quantangshi','','卷27','寂寥金谷涧，花发旧时园。
人事空怀古，烟霞此独存。
管弦非上客，歌舞少王孙。
繁蘂风惊散，轻红鸟乍翻。
山川终不改，桃李自无言。
今日经尘路，凄凉讵可论。','',''),('quantangshi-26129','和太原张相公山亭怀古','高銖','quantangshi','','卷27','鬬石类岩巘，飞流泻潺湲。
远壑檐宇际，孤峦雉堞间。
何必到海岳，境幽机自闲。
兹焉得高趣，高步谢东山。','',''),('quantangshi-26130','八月五日中部官舍读唐历天宝已来追怆故事','舒元輿','quantangshi','','卷27','将寻国朝事，静读柳芳历。
八月日之五，开卷忽感激。
正当天宝末，抚事坐追惜。
仰思圣明帝，贻祸在肘腋。
杨李盗吏权，贪残日狼籍。
燕戎伺其便，百万奋长戟。
两河连烟尘，二京成瓦砾。
生人死欲尽，揳业犹不息。
肃宗传宝图，寇难连年击。
天地方开泰，铸鼎成继述。
万国哭龙衮，悲思动蛮[貊]。
自此千秋节，不复动金石。
悲风扬霜天，繐帷冷尘席。
零落太平老，东西乱离客。
往往为余言，呜咽泪双滴。
况当近塞地，哀吹起边笛。
抚几观陈文，使我心不怿。
花萼笑繁华，温泉树容碧。
霓裳烟云尽，梨园风雨隔。
露囊与金镜，东逝惊波溺。
昔闻欢娱事，今日成惨戚。
神仙不可求，劒玺苔文积。
万古长恨端，萧萧泰陵陌。','',''),('quantangshi-26131','坊州按狱','舒元輿','quantangshi','','卷27','中部接戎塞，顽山四周遭。
风冷木长瘦，石硗人亦劳。
牧守苟怀仁，痒之时为搔。
其爱如赤子，始得无啼号。
奈何贪狼心，润屋沈脂膏。
攫搏如猛虎，吞噬若狂獒。
山秃逾高采，水穷益深捞。
龟鱼即绝迹，鹿兔无遗毛。
氓苦税外缗，吏忧笑中刀。
大君明四目，烛之洞秋毫。
眷兹一州命，虑齐坠波涛。
临轩诏小臣，汝往穷贪饕。
分明举公法，为我缓穷骚。
小臣诚小心，奉命如煎熬。
饮冰不待夕，驱马凌晨臯。
及此督簿书，游词出狴牢。
门墙见狼狈，案牍闻腥臊。
探情与之言，变态如奸猱。
真非既巧饰，伪意乃深韬。
去恶犹农夫，稂莠须耘耨。
恢恢布疎网，罪者何由逃。
自顾孱钝姿，利器非能操。
六旬始归奏，霜落秋原蒿。
寄谢守土臣，努力清郡曹。
须知听甚卑，勿谓天之高。','',''),('quantangshi-26132','桥山怀古','舒元輿','quantangshi','','卷27','轩辕厌代千万秋，渌波浩荡东南流。
今来古往无不死，独有天地长悠悠。
我乘驿骑到中部，古闻此地为渠搜。
桥山突兀在其左，荒榛交鏁寒风愁。
神仙天下亦如此，况我戚促同蜉蝣。
谁言衣冠葬其下，不见弓劒何人收。
哀喧呌笑牧童戏，阴天月落狐狸游。
却思皇坟立人极，车轮马迹无不周。
洞庭张乐降玄鹤，涿鹿大战摧蚩尤。
知勇神天不自大，风后力牧输长筹。
襄城迷路问童子，帝乡归去无人留。
崆峒求道失遗迹，荆山铸鼎余荒丘。
君不见黄龙飞去山下路，断髯成草风飕飕。','',''),('quantangshi-26133','坊州按狱苏氏庄记室二贤自鄜州走马相访留连数日发后独坐寂寞因成诗寄之','舒元輿','quantangshi','','卷27','十年一相见，世俗信多岐。
云雨易分散，山川长间之。
我衔凤阙恩，按狱桥山陲。
君在龙骧府，掌奏羽檄词。
相去百余里，魂梦自相驰。
形容在胸臆，书札通相思。
烦君爱我深，轻车忽载脂。
塞门秋色老，霜气方凝姿。
此地少平川，冈阜相参差。
谁知路非远，行者多云疲。
君能犯劲风，信宿凌欹危。
情亲不自倦，下马开双眉。
相对坐沉吟，屈指惊岁时。
万事且莫问，一杯欣共持。
阳乌忽西倾，明蟾挂高枝。
卷帘引瑶玉，灭烛临霜墀。
中庭有疎芦，淅淅闻风吹。
长河卷云色，凝碧无瑕疵。
一言开我怀，旷然澹希夷。
悠悠夜方永，冷思偏相宜。
眉睫无他人，与君闲解题。
陶然叩寂寞，更请吟清诗。
得意且忘言，何况竹与丝。
顷刻过三夕，起坐轻四肢。
明朝告行去，惨然还别离。
出门送君去，君马扬金羁。
回来坐空堂，寂寞无人知。','',''),('quantangshi-26134','履春冰','舒元輿','quantangshi','','卷27','投迹清冰上，凝光动早春。
兢兢愁陷履，步步怯移身。
鸟照微生水，狐听或过人。
细迁形外影，轻蹑镜中轮。
咫尺忧偏远，危疑惧已频。
愿坚容足分，莫使独惊神。','',''),('quantangshi-26135','赠李翺','舒元輿','quantangshi','','卷27','湘江舞罢忽成悲，便脱蛮靴出绛帷。
谁是蔡邕琴酒客，魏公怀旧嫁文姬。','',''),('quantangshi-26136','登长安慈恩寺塔','盧宗回','quantangshi','','卷27','东方晓日上翔鸾，西转苍龙拂露盘。
渭水寒光摇藻井，玉峰晴色上朱阑。
九重宫阙参差见，百二山河表里观。
蹔辍去蓬悲不定，一凭金界望长安。','',''),('quantangshi-26137','古镜歌','周匡物','quantangshi','','卷27','轩辕铸镜谁将去，曾被良工泻金取。
明月心中桂不生，轻冰面上菱初吐。
蛟龙久无雷雨声，鸾凤空踏莓苔舞。
欲向高台对晓开，不知谁是孤光主。','',''),('quantangshi-26138','及第谣','周匡物','quantangshi','','卷27','水国寒消春日长，燕莺催促花枝忙。
风吹金榜落凡世，三十三人名字香。
遥望龙墀新得意，九天勅下多狂醉。
骅骝一百三十蹄，踏破蓬莱五云地。
物经千载出尘埃，从此便为天下瑞。','',''),('quantangshi-26139','及第后谢座主','周匡物','quantangshi','','卷27','一纵东越入西秦，十度闻莺不见春。
试向昆山投瓦砾，便容灵沼濯埃尘。
悲欢暗负风云力，感激潜生草木身。
中夜自将形影语，古来吞炭是何人。','',''),('quantangshi-26140','自题读书堂','周匡物','quantangshi','','卷27','窗外卷帘侵碧落，槛前敲竹向青冥。
黄昏不欲留人宿，云起风生龙虎醒。','',''),('quantangshi-26141','应举题钱塘公馆','周匡物','quantangshi','','卷27','万里茫茫天堑遥，秦皇底事不安桥。
钱塘江口无钱过，又阻西陵两信潮。','',''),('quantangshi-26142','题旅榇','廖有方','quantangshi','','卷27','嗟君没世委空囊，几度劳心翰墨场。','',''),('quantangshi-26143','立春日呈宫傅侍郎','皇甫曙','quantangshi','','卷27','朝旦微风吹晓霞，散为和气满家家。
不知容貌潜消落，且喜春光动物华。
出问池冰犹塞岸，归寻园柳未生芽。
摩娑酒瓮重封闭，待入新年共赏花。','',''),('quantangshi-26144','赋得玉声如乐','潘存實','quantangshi','','卷27','表质自坚贞，因人一扣鸣。
静将金并响，妙与乐同声。
杳杳疑风送，泠泠似曲成。
韵含湘瑟切，音带舜弦清。
不独藏虹气，犹能畅物情。
后夔如为听，从此振琮琤。','',''),('quantangshi-26145','送林刺史简言之漳州','陳去疾','quantangshi','','卷27','江树欲含曛，清歌一送君。
征骖辞荔浦，别袂暗松云。
路狭横柯度，山深坠叶闻。
明朝宿何处，未忍醉中分。','',''),('quantangshi-26146','忆山中','陳去疾','quantangshi','','卷27','长吟重悒然，为忆山中年。
清瑟泛遥夜，乱花随暮烟。
珠林余露气，乳窦滴香泉。
迹远尘埃外，花开绮藻前。
岩罗云貌逸，竹抱水容妍。
蕙磴飞英遶，萍潭片影悬。
林藏诸曲胜，台擅一峰偏。
会可标真寄，焚香对石筵。','',''),('quantangshi-26147','元夕京城和欧阳衮','陳去疾','quantangshi','','卷27','兰焰芳芬彻晓开，珠光新霭映人来。
歌迎甲夜催银管，影动繁星缀玉台。
别有朱门春澹荡，不妨芝火翠崔嵬。','',''),('quantangshi-26148','送韩将军之雁门','陳去疾','quantangshi','','卷27','荒塞峰烟百道驰，雁门风色暗旌旗。
破围铁骑长驱疾，饮血将军转战危。
画角吹开边月静，缦缨不信虏尘窥。
归来长揖功成后，黄石当年故有期。','',''),('quantangshi-26149','赋得骐骥长鸣','陳去疾','quantangshi','','卷27','骐骥忻知己，嘶鸣忽异常。
积悲摅怨抑，一举彻穹苍。
迹类三年鸟，心驰五达庄。
何言从蹇踬，今日逐腾骧。
牛皂休维絷，天衢恣陆梁。
向非逢伯乐，谁足见其长。','',''),('quantangshi-26150','偶题','陳去疾','quantangshi','','卷27','魂梦天南垂，宿昔万里道。
池台花气深，到处生春草。','',''),('quantangshi-26151','春宫曲','陳去疾','quantangshi','','卷27','流莺春晓唤樱桃，花外传呼殿影高。
抱里琵琶最承宠，君王勅赐玉檀槽。','',''),('quantangshi-26152','采莲曲','陳去疾','quantangshi','','卷27','粉光花色叶中开，荷气衣香水上来。
棹响清潭见斜领，双鸳何事亦相猜。','',''),('quantangshi-26153','踏歌行 一','陳去疾','quantangshi','','卷27','鸳鸯楼下万花新，翡翠宫前百戏陈。
夭矫翔龙衔火树，飞来瑞凤散芳春。','',''),('quantangshi-26154','踏歌行 二','陳去疾','quantangshi','','卷27','仙跸初传紫禁香，瑞云开处夜花芳。
繁弦促管升平调，绮缀丹莲借月光。','',''),('quantangshi-26155','塞下曲','陳去疾','quantangshi','','卷27','春至金河雪似花，萧条玉塞但胡沙。
晓来重上关城望，惟见惊尘不见家。','',''),('quantangshi-26156','送人谪幽州','陳去疾','quantangshi','','卷27','临路深怀放废惭，梦中犹自忆江南。
莫言塞北春风少，还胜炎荒入瘴岚。','',''),('quantangshi-26157','西上辞母坟','陳去疾','quantangshi','','卷27','高盖山头日影微，黄昏独立宿禽稀。
林间滴酒空垂泪，不见丁宁嘱早归。','',''),('quantangshi-26158','履春冰','張蕭遠','quantangshi','','卷27','一步一愁新，轻轻恐陷人。
薄光全透日，残影半销春。
蝉想行时翼，鱼惊蹋处鳞。
底虚难驻足，岸阔怯回身。
岂暇踟蹰久，宁辞顾盼频。
愿将兢慎意，从此赴通津。','',''),('quantangshi-26159','观灯','張蕭遠','quantangshi','','卷27','十万人家火烛光，门门开处见红妆。
歌钟喧夜更漏暗，罗绮满街尘土香。
星宿别从天畔出，莲花不向水中芳。
宝钗骤马多遗落，依旧明朝在路傍。','',''),('quantangshi-26160','送宫人入道','張蕭遠','quantangshi','','卷27','舍宠求仙畏色衰，辞天素面立堦墀。
金丹拟驻千年貌，玉指休匀八字眉。
师主与收珠翠后，君王看戴角冠时。
从来宫女皆相妬，闻向瑶台尽泪垂。','',''),('quantangshi-26161','句','張蕭遠','quantangshi','','卷27','秦云寂寂僧还定，尽日无人鹿遶牀。
日暮风吹官渡柳，白鵶飞出石头墙。
双双白燕入词堂。','',''),('quantangshi-26162','见志','李播','quantangshi','','卷27','去岁买琴不与价，今年沽酒未还钱。
门前债主雁行立，屋里醉人鱼贯眠。','',''),('quantangshi-26163','鱼上冰','王季則','quantangshi','','卷27','北陆收寒尽，东风解冻初。
冰消通浅溜，气变跃潜鱼。
应节似知化，扬鬐任所如。
浮沈非乐藻，沿溯异传书。
结网时空久，临川意有余。
为龙将可望，今日愧才虚。','',''),('quantangshi-26164','鱼上冰','紀元臯','quantangshi','','卷27','春生寒气灭，稍动伏泉鱼。
乍喜东风至，来观曲浦初。
近冰朱鬣见，望日锦鳞舒。
渐觉流澌退，还忻掉尾余。
噞喁情自乐，沿溯意宁疎。
傥得随鲲化，终能戾太虚。','',''),('quantangshi-26165','鱼上冰','吳晃','quantangshi','','卷27','春水潜鳞发，寒潭旧藻疎。
扬鬐顺气后，振鬣上冰初。
戏广怜空洁，浮清媚景虚。
戒贪还避饵，思达每怀书。
湿映流澌薄，狂游触浪余。
终希泮涣泽，为化北溟鱼。','',''),('quantangshi-26166','赠柳氏妓','鄭還古','quantangshi','','卷27','冶艳出神仙，歌声胜管弦。
词轻白紵曲，歌遏碧云天。
未拟生裴秀，如何乞郑玄。
不堪金谷水，横过坠楼前。','',''),('quantangshi-26167','吉州道中','鄭還古','quantangshi','','卷27','吉州新置掾，驰驿到条山。
薏苡殊非谤，羊肠未是艰。
自惭多白发，争敢竞朱颜。
若有前生债，今朝不懊还。','',''),('quantangshi-26168','望思台','鄭還古','quantangshi','','卷27','谗语能令骨肉离，奸情难测事堪悲。
何因掘得江充骨，捣作微尘祭望思。','',''),('quantangshi-26169','日南长至','獨孤鉉','quantangshi','','卷27','玉历颁新律，凝阴发一阳。
轮辉犹惜短，圭影此偏长。
晷度经南斗，流晶尽北堂。
乍疑周户耀，可爱逗林光。
积雪销微照，初萌动早芒。
更升台上望，云物已昭彰。','',''),('quantangshi-26170','延平天庆观','王初','quantangshi','','卷27','劒化江边绿构新，层台不染玉梯尘。
千章隐篆标龙简，一曲空歌降凤钧。
岚气湿衣云叶晚，天香飘户月枝春。
盟经早晚闻仙语，学种三芝伴羽人。','',''),('quantangshi-26171','送叶秀才','王初','quantangshi','','卷27','快骑璁珑刻玉羁，河梁返照上征衣。
层冰春近蟠龙起，九泽云闲独鹤飞。
行想北山清梦断，重游西洛故人稀。
汉庭狗监深知己，有日前驱负弩归。','',''),('quantangshi-26172','送王秀才谒池州吴都督','王初','quantangshi','','卷27','池阳去去跃雕鞍，十里长亭百草干。
衣袂障风金镂细，劒光横雪玉龙寒。
晴郊别岸乡魂断，晓树啼乌客梦残。
南馆星郎东道主，摇鞭休问路行难。','',''),('quantangshi-26173','青帝','王初','quantangshi','','卷27','青帝邀春隔岁还，月娥孀独夜漫漫。
韩凭舞羽身犹在，素女商弦调未残。
终古兰岩栖偶鹤，从来玉谷有离鸾。
几时幽恨飘然断，共待天池一水干。','',''),('quantangshi-26174','银河','王初','quantangshi','','卷27','阊阖疎云漏绛津，桥头秋夜鹊飞频。
犹残仙媛湔帬水，几见星妃度袜尘。
历历素榆飘玉叶，涓涓清月湿冰轮。
年来若有乘槎客，为吊波灵是楚臣。','',''),('quantangshi-26175','书秋','王初','quantangshi','','卷27','千里南云度塞鸿，秋容无迹淡平空。
人间玉岭清宵月，天上银河白昼风。
潘赋登山魂易断，楚歌遗佩怨何穷。
往来未若奇张翰，欲鲙霜鲸碧海东。','',''),('quantangshi-26176','自和书秋','王初','quantangshi','','卷27','陇首斜飞避弋鸿，颓云萧索见层空。
汉宫夜结双茎露，阊阖凉生六幕风。
湘女怨弦愁不禁，鄂君香被梦难穷。
江边两桨连歌渡，惊散游鱼莲叶东。','',''),('quantangshi-26177','立春后作','王初','quantangshi','','卷27','东君珂佩响珊珊，青驭多时下九关。
方信玉霄千万里，春风犹未到人间。','',''),('quantangshi-26178','梅花二首 一','王初','quantangshi','','卷27','应为阳春信未传，固将青艳属残年。
东君欲待寻佳约，剩寄衣香与粉绵。','',''),('quantangshi-26179','梅花二首 二','王初','quantangshi','','卷27','迎春雪艳飘零极，度夕蟾华掩映多。
欲托清香传远信，一枝无计奈愁何。','',''),('quantangshi-26180','春日咏梅花二首 一','王初','quantangshi','','卷27','靓妆才罢粉痕新，递晓风回散玉尘。
若遣有情应怅望，已兼残雪又兼春。','',''),('quantangshi-26181','春日咏梅花二首 二','王初','quantangshi','','卷27','青帝来时值远芳，残花残雪尚交光。
隔年拟待春消息，得见春风已断肠。','',''),('quantangshi-26182','即夕','王初','quantangshi','','卷27','榆叶飘零碧汉流，玉蟾珠露两清秋。
仙家若有单栖恨，莫向银台半夜游。','',''),('quantangshi-26183','送陈校勘入宿','王初','quantangshi','','卷27','日落风回卷碧霓，芳蓬一夜拆龙泥。
银台级级连清汉，桂子香浓月杵低。','',''),('quantangshi-26184','即夕','王初','quantangshi','','卷27','风幌凉生白袷衣，星榆才乱绛河低。
月明休近相思树，恐有韩凭一处栖。','',''),('quantangshi-26185','早春咏雪','王初','quantangshi','','卷27','句芒宫树已先开，珠蘂琼花鬬剪裁。
散作上林今夜雪，送教春色一时来。','',''),('quantangshi-26186','望雪','王初','quantangshi','','卷27','银花珠树晓来看，宿醉初醒一倍寒。
已似王恭披鹤氅，凭栏仍是玉栏干。','',''),('quantangshi-26187','雪霁','王初','quantangshi','','卷27','星榆叶叶昼离披，云粉千重凝不飞。
昆玉楼台珠树密，夜来谁向月中归。','',''),('quantangshi-26188','舟次汴堤','王初','quantangshi','','卷27','曲岸兰丛雁飞起，野客维舟碧烟里。
竿头五两转天风，白日杨花满流水。','',''),('quantangshi-26189','玉声如乐','劉軻','quantangshi','','卷27','玉叩能旋止，人言与乐并。
繁音忽已阕，雅韵诎然清。
佩想停仙步，泉疑咽夜声。
曲终无异听，响极有余情。
特达知难拟，玲珑岂易名。
昆山如可得，一片伫为荣。','',''),('quantangshi-26190','喜陈懿老示新制','朱晝','quantangshi','','卷27','一别一千日，一日十二忆。
苦心无闲时，今夕见玉色。
玉色复何异，弘明含羣德。
有文如星宿，飞入我胷臆。
忧愁方破坏，欢喜重补塞。
使我心貌全，且非黄金力。
将攀下风手，愿假仙鸾翼。','',''),('quantangshi-26191','赠友人古镜','朱晝','quantangshi','','卷27','我有古时镜，初自坏陵得。
蛟龙犹泥蟠，魑魅幸月蚀。
摩久见菱蘂，青于蓝水色。
赠君将照色，无使心受惑。','',''),('quantangshi-26192','赋得花藤药合寄頴阴故人','朱晝','quantangshi','','卷27','藤生南海滨，引蔓青且长。
剪削为花枝，何人无文章。
非才亦有心，割骨闻余芳。
繁叶落何处，孤贞在中央。
愿盛黄金膏，寄与青眼郎。
路远莫知意，水深天苍苍。','',''),('quantangshi-26193','春色满皇州','滕邁','quantangshi','','卷27','蔼蔼复悠悠，春归十二楼。
最明云里阙，先满日边州。
色媚青门外，光摇紫陌头。
上林荣旧树，太液镜新流。
暧带祥烟起，清添瑞景浮。
阳和如启蛰，从此事芳游。','',''),('quantangshi-26194','杨柳枝词','滕邁','quantangshi','','卷27','三条陌上拂金羁，万里桥边映酒旗。
此日令人肠欲断，不堪将入笛中吹。','',''),('quantangshi-26195','句','滕邁','quantangshi','','卷27','陶令门前罥接䍦，亚夫营里拂朱旗。','',''),('quantangshi-26196','留别吉州太守宗人迈','滕倪','quantangshi','','卷27','秋初江上别旌旗，故国无家泪欲垂。
千里未知投足处，前程便是听猨时。
误攻文字身空老，却返渔樵计已迟。
羽翼雕零飞不得，丹霄无路接差池。','',''),('quantangshi-26197','句','滕倪','quantangshi','','卷27','映水有深意，见人无惧心。
白发不能容相国，也同闲客满头生。','',''),('quantangshi-26198','吴宫','殷堯藩','quantangshi','','卷27','吴王爱歌舞，夜夜醉婵娟。
见日吹红烛，和尘扫翠钿。
徒令句践霸，不信子胥贤。
莫问长洲草，荒凉无限年。','',''),('quantangshi-26199','久雨','殷堯藩','quantangshi','','卷27','云影蔽遥空，无端淡复浓。
两旬绵密雨，二月似深冬。
诗酒从教数，帘帏一任重。
孰知春有地，微露小桃红。','',''),('quantangshi-26200','郊行逢社日','殷堯藩','quantangshi','','卷27','酒熟送迎便，村村庆有年。
妻孥亲稼穑，老稚効渔畋。
红树青林外，黄芦白鸟边。
稔看风景美，宁不羡归田。','',''),('quantangshi-26201','过友人幽居','殷堯藩','quantangshi','','卷27','身坐众香国，蒲团诗思新。
一贫曾累我，此兴未输人。
陋巷谁为俗，寒窗不染尘。
石斋盟四友，年下顿生春。','',''),('quantangshi-26202','过雍陶博士邸中饮','殷堯藩','quantangshi','','卷27','落叶下萧萧，幽居远市朝。
偶成投辖饮，不待致书招。
塞雁冲寒过，山云傍槛飘。
此身何所似，天地一渔樵。','',''),('quantangshi-26203','游王羽士山房','殷堯藩','quantangshi','','卷27','落日半楼明，琳宫事事清。
山横万古色，鹤带九臯声。
易作神仙侣，难忘父子情。
道人应识我，未肯说长生。','',''),('quantangshi-26204','署中答武功姚合','殷堯藩','quantangshi','','卷27','原中多阴雨，惟留一室明。
自宜居静者，谁得问先生。
深井泉香出，危沙药更荣。
全家笑无辱，曾不见戈兵。','',''),('quantangshi-26205','赠龙阳尉马戴','殷堯藩','quantangshi','','卷27','早学全身术，惟令耕近田。
自输官税后，常卧晚云边。
细草沿堦长，高萝出石悬。
向来名姓茂，空被外情牵。','',''),('quantangshi-26206','上巳日赠都上人 一','殷堯藩','quantangshi','','卷27','三月初三日，千家与万家。
蝶飞秦地草，莺入汉宫花。
鞍马皆争丽，笙歌尽鬬奢。
吾师无所愿，惟愿老烟霞。','',''),('quantangshi-26207','上巳日赠都上人 二','殷堯藩','quantangshi','','卷27','曲水公卿宴，香尘尽满街。
无心修禊事，独步到禅斋。
细草萦愁目，繁花逆旅怀。
绮罗人走马，遗落凤皇钗。','',''),('quantangshi-26208','送沈亚之尉南康','殷堯藩','quantangshi','','卷27','行迈南康路，客心离怨多。
暮烟葵叶屋，秋月竹枝歌。
孤鹤唳残梦，惊猨啸薜萝。
对江翘首望，愁泪叠如波。','',''),('quantangshi-26209','奉送刘使君王屋山隐居','殷堯藩','quantangshi','','卷27','散发风檐下，沈沈日渐曛。
鹰拳擒野雀，蛛网猎飞蚊。
羣动能归计，吾生亦谩勤。
尘缘难着眼，晚兴寄青云。','',''),('quantangshi-26210','寄许浑秀才','殷堯藩','quantangshi','','卷27','文字饥难煮，为农策最良。
兴来鉏晓月，倦后卧斜阳。
秋稼连千顷，春花醉几场。
任他名利客，车马闹康庄。','',''),('quantangshi-26211','送客游吴','殷堯藩','quantangshi','','卷27','吴国水中央，波涛白渺茫。
衣逢梅雨渍，船入稻花香。
海戍通盐竈，山村带蜜房。
欲知苏小小，君试到钱塘。','',''),('quantangshi-26212','陆丞相故宅','殷堯藩','quantangshi','','卷27','衣冠零落久，今日事堪伤。
厨起青烟薄，门开白日长。
残梅欹古道，名石卧颓墙。
山色依然好，兴衰未可量。','',''),('quantangshi-26213','中元日观诸道士步虚','殷堯藩','quantangshi','','卷27','玄都开秘箓，白石礼先生。
上界秋光净，中元夜气清。
星辰朝帝处，鸾鹤步虚声。
玉洞花长发，珠宫月最明。
扫坛天地肃，投简鬼神惊。
傥赐刀圭药，还留不死名。','',''),('quantangshi-26214','醉赠刘十二','殷堯藩','quantangshi','','卷27','春草正凄凄，知君过恶溪。
莺将吉了语，猿共猓然啼。
别路魂先断，还家梦几迷。
定寻雷令劒，应识越王笄。
树色多于北，潮声少向西。
椰花好为酒，谁伴醉如泥。','',''),('quantangshi-26215','早朝','殷堯藩','quantangshi','','卷27','曙钟催入紫宸朝，列炬流虹映绛绡。
天近鳌头花簇杖，风低豹尾乐鸣韶。
衣冠一变无夷俗，律令重颁有正条。
昨日钟山甘露降，玻璃满赐出宫瓢。','',''),('quantangshi-26216','帝京二首 一','殷堯藩','quantangshi','','卷27','列郡征才起俊髦，万机独使圣躬劳。
开藩上相颁龙节，破虏将军展豹韬。
地入黄图三辅壮，天垂华盖七星高。
迎春别赐瑶池宴，捧进金盘五色桃。','',''),('quantangshi-26217','帝京二首 二','殷堯藩','quantangshi','','卷27','龙虎山河御气通，遥瞻帝阙五云红。
英雄尽入江东籍，将相多收蓟北功。
礼乐日稽三代盛，梯航岁贡万方同。
都将俭德熙文治，淳俗应还太古风。','',''),('quantangshi-26218','宫词','殷堯藩','quantangshi','','卷27','悄悄深宫不见人，倚阑惟见石麒麟。
芙蓉帐冷愁长夜，翡翠帘垂隔小春。
天远难通青鸟信，风寒欲动锦花茵。
夜深怕有羊车过，自起笼灯看雪纹。','',''),('quantangshi-26219','郊居作','殷堯藩','quantangshi','','卷27','碧树浓阴护短垣，苍江春暖渚凫喧。
买鱼试唤鸣榔艇，寻鹤因行隔壠村。
生理何凭文是业，世情纵遣酒盈樽。
相逢谓我迂疎甚，欲辨还憎恐失言。','',''),('quantangshi-26220','闲居','殷堯藩','quantangshi','','卷27','茂苑闲居木石同，旋开小迳翦蒿蓬。
虚游心在鸿蒙外，穴处身疑培塿中。
花影一阑吟夜月，松声半榻卧秋风。
百年寄傲聊容膝，何必高车驷马通。','',''),('quantangshi-26221','暮春述怀','殷堯藩','quantangshi','','卷27','为客山南二十年，愁来怳近落花天。
阴云带雨连山脊，湿气成岚滴树巅。
隣屋有声敲石火，野禽无语避茶烟。
此时若遇孙阳顾，肯服盐车不受鞭。','',''),('quantangshi-26222','端午日','殷堯藩','quantangshi','','卷27','少年佳节倍多情，老去谁知感慨生。
不効艾符趋习俗，但祈蒲酒话升平。
鬓丝日日添头白，榴锦年年照眼明。
千载贤愚同瞬息，几人湮没几垂名。','',''),('quantangshi-26223','九日','殷堯藩','quantangshi','','卷27','万里飘零十二秋，不堪今倚夕阳楼。
壮怀空掷班超笔，久客谁怜季子裘。
瘴雨蛮烟朝暮景，平芜野草古今愁。
酣歌欲尽登高兴，强把黄花插满头。','',''),('quantangshi-26224','九日病起','殷堯藩','quantangshi','','卷27','重阳开满菊花金，病起榰牀惜赏心。
紫蟹霜肥秋纵好，绿醅蚁滑晚慵斟。
眼窥薄雾行殊倦，身怯寒风坐未禁。
沈醉又成来岁约，遣怀聊作记时吟。','',''),('quantangshi-26225','寒夜','殷堯藩','quantangshi','','卷27','云冷江空岁暮时，竹阴梅影月参差。
鸡催梦枕司晨早，更咽寒城报点迟。
人事纷华潜动息，天心静默运推移。
凭谁荡涤穷残候，入眼东风喜在期。','',''),('quantangshi-26226','喜雨','殷堯藩','quantangshi','','卷27','临岐终日自裴回，干我茅斋半亩苔。
山上乱云随手变，淛东飞雨过江来。
一元和气归中正，百怪苍渊起蛰雷。
千里稻花应秀色，酒樽风月醉亭台。','',''),('quantangshi-26227','春游','殷堯藩','quantangshi','','卷27','明日城东看杏花，叮咛童子蚤将车。
路从丹凤楼前过，酒向金鱼馆里赊。
绿水满沟生杜若，暖云将雨湿泥沙。
绝胜羊傅襄阳道，车骑西风拥鼓笳。','',''),('quantangshi-26228','夜酌溪楼','殷堯藩','quantangshi','','卷27','楼居溪上凉生早，坐对城头起暮笳。
打鼓泊船何处客，捣衣隔竹是谁家。
玉绳低转宵初迥，银烛高烧月近斜。
得意引杯须痛饮，好怀那许负年华。','',''),('quantangshi-26229','旅行','殷堯藩','quantangshi','','卷27','烟树寒林半有无，野人行李更萧疎。
堠长堠短逢官马，山北山南闻鹧鸪。
万里关河成传舍，五更风雨忆呼卢。
寂寥一点寒灯在，酒熟隣家许夜沽。','',''),('quantangshi-26230','下第东归作','殷堯藩','quantangshi','','卷27','十载驱驰倦荷锄，三年生计鬓萧疎。
辛勤几逐英雄后，乙榜犹然姓氏虚。
欲射狼星把弓箭，休将萤火读诗书。
身贱自慙贫骨相，朗啸东归学钓鱼。','',''),('quantangshi-26231','还京口','殷堯藩','quantangshi','','卷27','黄鹤山头雪未消，行人归计在今朝。
城高铁瓮江山壮，地接金陵草木雕。
北府市楼闻旧酒，南桥官柳识归桡。
吏民莫见参军面，水宿风餐鬓发焦。','',''),('quantangshi-26232','襄口阻风','殷堯藩','quantangshi','','卷27','雪浪排空接海门，孤舟三日阻龙津。
曹瞒曾堕周郎计，王导难遮庚亮尘。
鸥散白云沈远浦，花飞红雨送残春。
篙师整缆候明发，仍谒荒祠问鬼神。','',''),('quantangshi-26233','潭州独步','殷堯藩','quantangshi','','卷27','鹤发垂肩懒着巾，晚凉独步楚江滨。
一帆暝色鸥边雨，数尺筇枝物外身。
习巧未逢医拙手，闻歌先识采莲人。
笑看斥鷃飞翔去，乐处蓬莱便有春。','',''),('quantangshi-26234','金陵怀古','殷堯藩','quantangshi','','卷27','黄道天清拥佩珂，东南王气秣陵多。
江吞彭蠡来三蜀，地接昆仑带九河。
凤阙晓霞红散绮，龙池春水绿生波。
华夷混一归真主，端拱无为乐太和。','',''),('quantangshi-26235','登凤凰台二首 一','殷堯藩','quantangshi','','卷27','凤凰台上望长安，五色宫袍照水寒。
彩笔十年留翰墨，银河一夜卧阑干。
三山飞鸟江天暮，六代离宫草树残。
始信人生如一梦，壮怀莫使酒杯干。','',''),('quantangshi-26236','登凤凰台二首 二','殷堯藩','quantangshi','','卷27','梧桐叶落秋风老，人去台空凤不来。
梁武台成芳草合，吴王宫殿野花开。
石头城下春生水，燕子堂前雨长苔。
莫问人间兴废事，百年相遇且衔杯。','',''),('quantangshi-26237','韩信庙','殷堯藩','quantangshi','','卷27','长空鸟尽将军死，无复中原入马蹄。
身向九泉还属汉，功超诸将合封齐。
荒凉古庙惟松柏，咫尺长陵又鹿麋。
此日深怜萧相国，竟无一语到金闺。','',''),('quantangshi-26238','访许浑','殷堯藩','quantangshi','','卷27','去郭来寻隐者居，柳阴假步小篮舆。
每期会面初偿约，却计论心旧得书。
浅绿垣墙绵薜荔，淡红池沼映芙蕖。
为言肯共留连饮，涧有青芹罟有鱼。','',''),('quantangshi-26239','李舍人席上感遇','殷堯藩','quantangshi','','卷27','微云歛雨天气清，松声出树秋泠泠。
窗户长含碧萝色，溪流时带蛟龙腥。
一官到手不可避，万事役我徒劳形。
飘然曳杖出门去，无数好山江上横。','',''),('quantangshi-26240','和赵相公登鹳雀楼','殷堯藩','quantangshi','','卷27','危楼高架泬寥天，上相闲登立彩旃。
树色到京三百里，河流归汉几千年。
晴峰耸日当周道，秋谷垂花满舜田。
云路何人见高志，最看西面赤阑前。','',''),('quantangshi-26241','冬至酬刘使君','殷堯藩','quantangshi','','卷27','异乡冬至又今朝，回首家山入梦遥。
渐喜一阳从地复，却怜羣沴逐冰消。
梅含露蘂知迎腊，柳拂宫袍忆候朝。
多少故人承宴赏，五云堆里听箫韶。','',''),('quantangshi-26242','李节度平虏诗','殷堯藩','quantangshi','','卷27','百万王师下日边，将军雄略可图全。
元勋未论封茅异，捷势应知破竹然。
燕警无烽清朔漠，秦文有宝进蓝田。
太平从此销兵甲，记取红羊换劫年。','',''),('quantangshi-26243','金陵上李公垂侍郎','殷堯藩','quantangshi','','卷27','海国微茫散晓暾，郁葱佳气满干坤。
六朝空据长江险，一统今归圣代尊。
西北诸峰连朔漠，东南众水合昆仑。
愿从吾道禧文运，再使河清俗化淳。','',''),('quantangshi-26244','赠惟俨师','殷堯藩','quantangshi','','卷27','焕然文采照青春，一策江湖自在身。
云锁木龛聊息影，雪香纸袄不生尘。
谈禅早续灯无尽，护法重编论有神。
拟扫绿阴浮佛寺，桫椤高树结为隣。','',''),('quantangshi-26245','寄许浑秀才','殷堯藩','quantangshi','','卷27','万木惊秋叶渐稀，静探造化见玄机。
眼前谁悟先天理，去后还知今日非。
树拥秣陵千嶂合，云开萧寺一僧归。
汉廷累下征贤诏，未许严陵老钓矶。','',''),('quantangshi-26246','送白舍人渡江','殷堯藩','quantangshi','','卷27','晓发龙江第一程，诸公同济似登瀛。
海门日上千峰出，桃叶波平一棹轻。
横锁已沈王浚筏，投鞭难阻谢玄兵。
片时喜得东风便，回首钟声隔凤城。','',''),('quantangshi-26247','送刘禹锡侍御出刺连州','殷堯藩','quantangshi','','卷27','遐荒迢遰五羊城，归兴浓消客里情。
家近似忘山路险，土甘殊觉瘴烟轻。
梅花清入罗浮梦，荔子红分广海程。
此去定知偿隐趣，石田春雨读书耕。','',''),('quantangshi-26248','送韦侍御报使西蕃','殷堯藩','quantangshi','','卷27','归奏圣朝行万里，却衔天诏报蕃臣。
本是诸生守文墨，今将匹马静烟尘。
旅宿关河逢暮雨，春耕亭障识遗民。
此去多应收故地，宁辞沙塞往来频。','',''),('quantangshi-26249','寒食城南即事因访蓝田韦明府','殷堯藩','quantangshi','','卷27','闲出城南禁火天，路傍骑马独摇鞭。
青松古墓伤碑碣，红杏春园羡管弦。
徒说䴙鹈膏玉劒，漫夸蚨血点铜钱。
世间尽是悠悠事，且饮韦家冷酒眠。','',''),('quantangshi-26250','送源中丞使新罗','殷堯藩','quantangshi','','卷27','赤墀奉命使殊方，官重霜台紫绶光。
玉节在船清海怪，金函开诏抚夷王。
云晴渐觉山川异，风便宁知道路长。
谁得似君将雨露，海东万里洒扶桑。','',''),('quantangshi-26251','送景玄上人还山','殷堯藩','quantangshi','','卷27','嵩阳听罢讲经钟，远访庭闱锡度空。
蒲履谩从归后织，衲衣犹记别时缝。
地横龙朔连沙暝，山入乌桓碧树重。
梵宇传来金贝叶，花前拜捧慰亲容。','',''),('quantangshi-26252','宫人入道','殷堯藩','quantangshi','','卷27','卸却宫妆锦绣衣，黄冠素服制相宜。
锡名近奉君王旨，佩箓新参老氏师。
白昼无情趋玉陛，清宵有梦步瑶池。
绿鬟女伴含愁别，释尽当年妬宠私。','',''),('quantangshi-26253','友人山中梅花','殷堯藩','quantangshi','','卷27','南国看花动远情，沈郎诗苦瘦容生。
铁心自儗山中赋，玉笛谁将月下横。
临水一枝春占早，照人千树雪同清。
好风吹醒罗浮梦，莫听空林翠羽声。','',''),('quantangshi-26254','客中有感','殷堯藩','quantangshi','','卷27','天地一身在，头颅五十过。
流年消壮志，空使泪成河。','',''),('quantangshi-26255','忆家二首 一','殷堯藩','quantangshi','','卷27','新霁扬林初，苹花贴岸舒。
故乡今夜月，犹得照孤庐。','',''),('quantangshi-26256','忆家二首 二','殷堯藩','quantangshi','','卷27','树拥溪边阁，山浮雨后岚。
白头归未得，梦里望江南。','',''),('quantangshi-26257','江行二首 一','殷堯藩','quantangshi','','卷27','暝色沧州迥，秋声玉峡长。
只因江上月，不觉过浔阳。','',''),('quantangshi-26258','江行二首 二','殷堯藩','quantangshi','','卷27','晚泊长江口，寒沙白似霜。
年光流不尽，东去水声长。','',''),('quantangshi-26259','偶题','殷堯藩','quantangshi','','卷27','越女收龙眼，蛮儿拾象牙。
长安千万里，走马送谁家。','',''),('quantangshi-26260','关中伤乱后','殷堯藩','quantangshi','','卷27','去岁干戈险，今年蝗旱忧。
关西归战马，海内卖耕牛。','',''),('quantangshi-26261','楚江怀古','殷堯藩','quantangshi','','卷27','骚灵不可见，楚些竟谁闻。
欲采苹花去，沧州隔暮云。','',''),('quantangshi-26262','张飞庙','殷堯藩','quantangshi','','卷27','威名垂万古，勇力冠当时。
回首三分国，何人赋黍离。','',''),('quantangshi-26263','生公讲台','殷堯藩','quantangshi','','卷27','暝色护楼台，阴云昼未开。
一尘无处着，花雨遍苍苔。','',''),('quantangshi-26264','席上听琴','殷堯藩','quantangshi','','卷27','高堂流月明，万籁不到耳。
一听清心魂，飞絮春纷起。','',''),('quantangshi-26265','酬雍秀才二首 一','殷堯藩','quantangshi','','卷27','晚市人烟合，归帆带夕阳。
栖迟未归客，犹着锦衣裳。','',''),('quantangshi-26266','酬雍秀才二首 二','殷堯藩','quantangshi','','卷27','卧病茅窗下，惊闻两月过。
兴来聊赋咏，清婉逼阴何。','',''),('quantangshi-26267','竹','殷堯藩','quantangshi','','卷27','窗户尽萧森，空堦凝碧阴。
不缘冰雪里，为识岁寒心。','',''),('quantangshi-26268','春怨','殷堯藩','quantangshi','','卷27','柳花扑帘春欲尽，绿阴障林莺乱啼。
秖愁明日送春去，落日满园啼竹鸡。','',''),('quantangshi-26269','馆娃宫','殷堯藩','quantangshi','','卷27','宫女三千去不回，真珠翠羽是尘埃。
夫差旧国久破碎，红燕自归花自开。','',''),('quantangshi-26270','汉宫词三首 一','殷堯藩','quantangshi','','卷27','成帝夫人泪满怀，璧宫相趁落空堦。
可怜玉貌花前死，惟有君恩白燕钗。','',''),('quantangshi-26271','汉宫词三首 二','殷堯藩','quantangshi','','卷27','霍家有女字成君，年少教人着绣裙。
枉杀宫中许皇后，椒房恩泽是浮云。','',''),('quantangshi-26272','汉宫词三首 三','殷堯藩','quantangshi','','卷27','骏马金鞍白玉鞭，宫中来取李延年。
承恩直日鸳鸯殿，一曲清歌在九天。','',''),('quantangshi-26273','同州端午','殷堯藩','quantangshi','','卷27','鹤发垂肩尺许长，离家三十五端阳。
儿童见说深惊讶，却问何方是故乡。','',''),('quantangshi-26274','夜过洞庭','殷堯藩','quantangshi','','卷27','笙歌只解闹花天，谁是敲冰掉小船。
为觅潇湘幽隐处，夜深载月听鸣泉。','',''),('quantangshi-26275','游山南寺二首 一','殷堯藩','quantangshi','','卷27','山中尽日无人到，竹外交加百鸟鸣。
昨日小楼微雨过，樱桃花落晚风晴。','',''),('quantangshi-26276','游山南寺二首 二','殷堯藩','quantangshi','','卷27','踏碎羊山黄叶堆，天飞细雨隐轻雷。
朗陵莫讶来何晚，不忍听君话别杯。','',''),('quantangshi-26277','寄太仆田卿二首 一','殷堯藩','quantangshi','','卷27','客窗强饮太怱怱，急雨寒风意万重。
蓦上心来消未得，梦回又听五更钟。','',''),('quantangshi-26278','寄太仆田卿二首 二','殷堯藩','quantangshi','','卷27','一阳才动伏羣阴，万物于今寓太音。
若喜长生添线日，微微消息识天心。','',''),('quantangshi-26279','新昌井','殷堯藩','quantangshi','','卷27','辘轳千转劳筋力，待得甘泉渴杀人。
且共山麋同饮涧，玉沙铺底浅磷磷。','',''),('quantangshi-26280','经靖安里','殷堯藩','quantangshi','','卷27','巷底萧萧绝市尘，供愁疎雨打黄昏。
悠然一曲泉明调，浅立闲愁轻闭门。','',''),('quantangshi-26281','闻筝歌','殷堯藩','quantangshi','','卷27','凄凄切切断肠声，指滑音柔万种情。
花影深沈遮不住，度帏穿幕又残更。','',''),('quantangshi-26282','吹笙歌','殷堯藩','quantangshi','','卷27','伶儿竹声愁绕空，秦女泪湿燕支红。
玉桃花片落不住，三十六簧能唤风。','',''),('quantangshi-26283','赠歌人郭婉二首 一','殷堯藩','quantangshi','','卷27','石家金谷旧歌人，起唱花筵泪满巾。
红粉少年诸弟子，一时惆怅望梁尘。','',''),('quantangshi-26284','赠歌人郭婉二首 二','殷堯藩','quantangshi','','卷27','云满衣裳月满身，轻盈归步过流尘。
五更无限留连意，常恐风花又一春。','',''),('quantangshi-26285','潭州席上赠舞柘枝妓','殷堯藩','quantangshi','','卷27','姑苏太守青娥女，流落长沙舞柘枝。
坐满绣衣皆不识，可怜红脸泪双垂。','',''),('quantangshi-26286','句','殷堯藩','quantangshi','','卷27','瘴雨出虹蝀，蛮烟渡江急。
尝闻岛夷俗，犀象满城邑。','',''),('quantangshi-26287','虎丘山真娘墓','沈亞之','quantangshi','','卷27','金钗沦劒壑，兹地似花台。
油壁何人值，钱塘度曲哀。
翠余长染柳，香重欲薰梅。
但道行云去，应随魂梦来。','',''),('quantangshi-26288','答殷尧藩赠罢泾源记室','沈亞之','quantangshi','','卷27','劳君辍雅话，听说事疆场。
提笔从征虏，飞书始伏羌。
河流辞马岭，节卧听龙骧。
孤负平生劒，空怜射斗光。','',''),('quantangshi-26289','五月六日发石头城步望前船示舍弟兼寄侯郎','沈亞之','quantangshi','','卷27','客子去淮阳，逶迤别梦长。
水关开夜锁，雾棹起晨凉。
烟月期同赏，风波勿异行。
隐山曾撼橹，转濑指遥樯。
蒲叶吴刀绿，筠筒楚粽香。
因书报惠远，为我忆檀郎。','',''),('quantangshi-26290','别庞子肃','沈亞之','quantangshi','','卷27','自为应仙才，丹砂炼几回。
山秋梦桂树，月晓忆瑶台。
雨雪依岩避，烟云逐步开。
今朝龙杖去，早晚鹤书来。','',''),('quantangshi-26291','春色满皇州','沈亞之','quantangshi','','卷27','何处春辉好，偏宜在雍州。
花明夹城道，柳暗曲江头。
风软游丝重，光融瑞气浮。
鬬鸡怜短草，乳燕傍高楼。
绣毂盈香陌，新泉溢御沟。
回看日欲暮，还骑似川流。','',''),('quantangshi-26292','宿白马津寄寇立','沈亞之','quantangshi','','卷27','客思听蛩嗟，秋怀似乱砂。
劒头悬日影，蝇鼻落灯花。
天外归鸿断，漳南别路赊。
闻君同旅舍，几得梦还家。','',''),('quantangshi-26293','汴州船行赋岸傍所见','沈亞之','quantangshi','','卷27','古木晓苍苍，秋林拂岸香。
露珠虫网细，金缕兔丝长。
秋浪时回沫，惊鳞乍触航。
蓬烟拈绿线，棘实缀红囊。
乱穗摇鼯尾，出根挂凤肠。
聊持一濯足，谁道比沧浪。','',''),('quantangshi-26294','送文頴上人游天台','沈亞之','quantangshi','','卷27','露花浮翠瓦，鲜思起芳丛。
此际断客梦，况复别志公。
既历天台去，言过赤城东。
莫说人间事，崎岖尘土中。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-26295','宿后自华阳行次昭应寄王直方','沈亞之','quantangshi','','卷27','重归能几日，物意早如春。
暖色先骊岫，寒声别雁羣。
川光如戏劒，帆态似翔云。
为报东园蝶，南枝日已曛。','',''),('quantangshi-26296','题海榴树呈八叔大人','沈亞之','quantangshi','','卷27','曾在蓬壶伴众仙，文章枝叶五云边。
几时奉宴瑶台下，何日移荣玉砌前。
染日裁霞深雨露，凌寒送暖占风烟。
应笑强如河畔柳，逢波逐浪送张骞。','',''),('quantangshi-26297','西蕃请谒庙','沈亞之','quantangshi','','卷27','肃肃层城里，巍巍祖庙清。
圣恩覃布濩，异域献精诚。
冠盖分行列，戎夷辨姓名。
礼终齐百拜，心洁表忠贞。
瑞气千重色，箫韶九奏声。
杖移迎日转，旌动逐风轻。
休运威仪正，年推俎豆盈。
不才慙圣泽，空此望华缨。','',''),('quantangshi-26298','劝政楼下观百官献寿','沈亞之','quantangshi','','卷27','御气黄花节，临轩紫陌头。
早阳生彩杖，霁色入仙楼。
献寿皆鸳鹭，瞻天在冕旒。
菊尊开九日，凤历启千秋。
乐阕祥烟起，杯酣瑞影收。
年年歌舞夕，此地庆皇休。','',''),('quantangshi-26299','山出云','沈亞之','quantangshi','','卷27','片云朝出岫，孤色逈难亲。
盖小辞山早，根轻触石新。
飘扬经绿野，明丽照青春。
拂树疑舒叶，临江似结鳞。
从龙方有感，捧日岂无因。
看助为霖去，恩沾雨露均。','',''),('quantangshi-26300','曲江亭望慈恩杏花发','沈亞之','quantangshi','','卷27','曲台晴好望，近接梵王家。
十亩开金地，千株发杏花。
带云犹误雪，映日欲欺霞。
紫陌传香远，红泉落影斜。
园中春尚早，亭上路非赊。
芳景偏堪赏，其如积岁华。','',''),('quantangshi-26301','村居','沈亞之','quantangshi','','卷27','有树巢宿鸟，无酒共客醉。
月上蝉韵残，梧桐阴绕地。
独出村舍门，吟剧微风起。
萧萧芦荻丛，呌啸如山鬼。
应缘我憔悴，为我哭秋思。','',''),('quantangshi-26302','春词酬元微之','沈亞之','quantangshi','','卷27','黄莺啼时春日高，红芳发尽井边桃。
美人手暖裁衣易，片片轻花落翦刀。','',''),('quantangshi-26303','题侯仙亭','沈亞之','quantangshi','','卷27','新创仙亭覆石坛，雕梁峻宇入云端。
岭北啸猨高枕听，湖南山色卷帘看。','',''),('quantangshi-26304','送庞子肃','沈亞之','quantangshi','','卷27','三年游宦也迷津，马困长安九陌尘。
都作无成不归去，古来妻嫂笑苏秦。','',''),('quantangshi-26305','梦挽秦弄玉','沈亞之','quantangshi','','卷27','泣葬一枝红，生同死不同。
金钿坠芳草，香绣满春风。
旧日闻箫处，高楼当月中。
梨花寒食夜，深闭翠微宫。','',''),('quantangshi-26306','梦别秦穆公','沈亞之','quantangshi','','卷27','击髆舞，恨满烟光无处所。
泪如雨，欲拟着辞不成语。
金凤衔红旧绣衣，几度宫中同看舞。
人间春日正欢乐，日暮东风何处去。','',''),('quantangshi-26307','梦游秦宫','沈亞之','quantangshi','','卷27','君王多感放东归，从此秦宫不复期。
春景似伤秦丧主，落花如雨泪胭脂。','',''),('quantangshi-26308','湘中怨 一','沈亞之','quantangshi','','卷27','隆佳秀兮昭盛时，播薰绿兮淑华归。
顾室荑与处蕚兮，潜重房以饰姿。
见稚态之韶羞兮，蒙长霭以为帏。
醉融光兮渺渺弥弥，迷千里兮涵烟眉。
晨陶陶兮暮熙熙，舞婑那之穠条兮。
骋盈盈以披迟，酡游颜兮倡蔓卉縠，流蒨霓兮石发髓旎。','',''),('quantangshi-26309','湘中怨 二','沈亞之','quantangshi','','卷27','溯青山兮江之隅，拖湘波兮褭绿裾。
荷拳拳兮未舒，匪同归兮将焉[如]。','',''),('quantangshi-26310','文祝延二阕 一','沈亞之','quantangshi','','卷27','闽山之杭杭兮水堋堋，吞荒抱大兮香叠层。
腾气清浑兮朝昏，神生其中兮宅幽凝。
居如山兮惠如水，处端卓兮赴下而忘鄙。
集人之祈兮从人之所市，攀清明兮叩仿髴。
我民清兮期吉日，愿听诚兮陈所当。
侯临我兮恩如光，照导兮天覆。
惠流吾兮乐且康，恭闻侯兮饮食失常。
民萦忧兮心苦疮，饱我之饥兮侯由有谷。
神有泽兮宜荫沃，脱侯之恙兮归侯之多福。
羣卑勤之恭洁兮，鉴贞盟乎山竹。','',''),('quantangshi-26311','文祝延二阕 二','沈亞之','quantangshi','','卷27','兕载吹兮音咿咿，铜铙呶兮睋呼𪾤睢。
樟之盖兮麓下，云垂幄兮为帷。
合吾民兮将安，维吾侯之康兮乐欣。
肴盘列兮答神，神摆渔篁兮降拂窣窣。
右持妓兮左夫人，态修邃兮佻眇。
调丹含琼兮瑳佳笑，馨炮膻燔兮溢按豆。
爵盎无虚兮菓摭杂佑，秋云清醉兮流融光。
巫裾旋兮觋袖翔，瞪虚凝兮览回杨。
语神欢兮酒云央，望吾侯兮遵赏事。
朝马驾兮搦宝辔，千弭函弦兮森道骑。
吾何乐兮神轩，维侯之康兮居游自遂。','',''),('quantangshi-26312','及第后过杨子江','施肩吾','quantangshi','','卷27','忆昔将贡年，抱愁此江边。
鱼龙互闪烁，黑浪高于天。
今日步春草，复来经此道。
江神也世情，为我风色好。','',''),('quantangshi-26313','夜宴曲','施肩吾','quantangshi','','卷27','兰缸如昼晓不眠，玉堂夜起沈香烟。
青娥一行十二仙，欲笑不笑桃花然。
碧窗弄娇梳洗晚，户外不知银汉转。
被郎嗔罚琉璃盏，酒入四肢红玉软。','',''),('quantangshi-26314','効古兴','施肩吾','quantangshi','','卷27','金雀无旧钗，缃绮无旧裾。
唯有一寸心，长贮万里夫。
南轩夜虫织已促，北牖飞蛾遶残烛。
祗言众口铄千金，谁信独愁销片玉。
不知岁晚归不归，又将啼眼缝征衣。','',''),('quantangshi-26315','古别离二首 一','施肩吾','quantangshi','','卷27','古人谩歌西飞燕，十年不见狂夫面。
三更风作切梦刀，万转愁成系肠线。
所嗟不及牛女星，一年一度得相见。','',''),('quantangshi-26316','古别离二首 二','施肩吾','quantangshi','','卷27','老母别爱子，少妻送征郎。
血流既四面，乃一断二肠。
不愁寒无衣，不怕饥无粮。
惟恐征战不还乡，母化为鬼妻为孀。','',''),('quantangshi-26317','壮士行','施肩吾','quantangshi','','卷27','一斗之胆撑脏腑，如磥之筋碍臂骨。
有时悞入千人丛，自觉一身横突兀。
当今四海无烟尘，胸襟被压不得伸。
冻枭残虿我不取，汚我匣里青蛇鳞。','',''),('quantangshi-26318','代征妇怨','施肩吾','quantangshi','','卷27','寒窗羞见影相随，嫁得五陵轻薄儿。
长短艳歌君自解，浅深更漏妾偏知。
画裙多泪鸳鸯湿，云鬓慵梳玳瑁垂。
何事不看霜雪里，坚贞惟有古松枝。','',''),('quantangshi-26319','送人南游','施肩吾','quantangshi','','卷27','见说南行偏不易，中途莫忘寄书频。
凌空瘴气堕飞鸟，解语山魈恼病人。
闽县绿娥能引客，泉州乌药好防身。
异花奇竹分明看，待汝归来画取真。','',''),('quantangshi-26320','赠边将','施肩吾','quantangshi','','卷27','轻生奉国不为难，战苦身多旧箭瘢。
玉匣锁龙鳞甲冷，金铃衬鹘羽毛寒。
皂貂拥出花当背，白马骑来月在鞍。
犹恐犬戎临虏塞，柳营时把阵图看。','',''),('quantangshi-26321','上礼部侍郎陈情','施肩吾','quantangshi','','卷27','九重城里无亲识，八百人中独姓施。
弱羽飞时攒箭险，蹇驴行处薄冰危。
晴天欲照盆难反，贫女如花镜不知。
却向从来受恩地，再求青律变寒枝。','',''),('quantangshi-26322','早春残雪','施肩吾','quantangshi','','卷27','春景照林峦，玲珑雪影残。
井泉添碧甃，药圃洗朱栏。
